SET search_path TO dbo, public;

-- ==== proc BulkSalesFromPendingQuotations ====
CREATE OR REPLACE FUNCTION dbo.bulksalesfrompendingquotations(machinename citext, custlist citext, gcode smallint, usercode smallint, startdate timestamp, enddate timestamp, INOUT saleinvcount integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_machinename citext;
  v_custlist citext;
  v_gcode smallint;
  v_usercode smallint;
  v_startdate timestamp(3);
  v_enddate timestamp(3);
  v_saleinvcount integer;
  v_rowscount integer;
  v_counter integer;
  v_custcode integer;
  v_rt_code integer;
  v_newsaleinvcode integer;
  v_invcount integer;
BEGIN
  v_machinename := machinename;
  v_custlist := custlist;
  v_gcode := gcode;
  v_usercode := usercode;
  v_startdate := startdate;
  v_enddate := enddate;
  v_saleinvcount := saleinvcount;
  -- SET NOCOUNT ON
  DROP TABLE IF EXISTS tv_bulksalesfrompendingquotations_tab_custlist;
  CREATE TEMP TABLE tv_bulksalesfrompendingquotations_tab_custlist (
    code integer NOT NULL,
    rowid integer GENERATED BY DEFAULT AS IDENTITY
) ON COMMIT DROP;
  INSERT INTO tv_bulksalesfrompendingquotations_tab_custlist (code) SELECT code FROM dbo.udf_stringtotabl(v_custlist, ',') AS udf_stringtotabl;
  v_counter := 1;
  v_rowscount := coalesce((SELECT count(code) FROM tv_bulksalesfrompendingquotations_tab_custlist AS tab_custlist), 0);
  v_invcount := 0;
  WHILE (v_counter <= v_rowscount) LOOP
    v_newsaleinvcode := 0;
    v_custcode := (SELECT code FROM tv_bulksalesfrompendingquotations_tab_custlist AS tab_custlist WHERE (rowid = v_counter));
    SELECT r.return_value, r.newsaleinvcode INTO v_rt_code, v_newsaleinvcode FROM dbo.sp_generate_sale_from_pendingquotations(machinename => v_machinename, custcode => v_custcode, gcode => v_gcode, usercode => v_usercode, startdate => v_startdate, enddate => v_enddate, newsaleinvcode => v_newsaleinvcode) AS r;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      return_value := -1;
      saleinvcount := v_saleinvcount;
      RETURN;
    END IF;
    IF (v_newsaleinvcode > 0) THEN
      v_invcount := (v_invcount + 1);
    END IF;
    v_counter := (v_counter + 1);
  END LOOP;
  v_saleinvcount := v_invcount;
  return_value := 0;
  saleinvcount := v_saleinvcount;
  RETURN;
  return_value := 0;
  saleinvcount := v_saleinvcount;
  RETURN;
END
$body$;

