-- ==== proc PostServiceOrder_Service_Sale ====
CREATE OR REPLACE FUNCTION dbo.postserviceorder_service_sale(serviceocode integer, usercode smallint, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_serviceocode integer;
  v_usercode smallint;
  v_errcode integer;
  v_serviceinvcode integer;
  v_saleinvcode integer;
  v_raiseprofsale citext;
BEGIN
  v_serviceocode := serviceocode;
  v_usercode := usercode;
  v_raiseprofsale := dbo.fn_getpreference('RaiseProformaSaleOnServiceOrderPosting');
  IF (v_raiseprofsale IS NULL) THEN
    v_raiseprofsale := 'N';
  END IF;
  IF (v_serviceocode <> 0) THEN
    v_errcode := 0;
    SELECT r.return_value, r.serviceinvcode, r.rs1 INTO v_errcode, v_serviceinvcode, rs1 FROM dbo.sp_generate_svc_for_serviceorder(serviceocode => v_serviceocode, usercode => v_usercode, serviceinvcode => v_serviceinvcode) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Problem while Generating Service Invoice';
      return_value := -1;
      RETURN;
    END IF;
    IF (v_raiseprofsale = 'Y') THEN
      v_errcode := 0;
      SELECT r.return_value, r.saleinvcode INTO v_errcode, v_saleinvcode FROM dbo.sp_generate_proforamsales_for_serviceorder(serviceocode => v_serviceocode, usercode => v_usercode, saleinvcode => v_saleinvcode) AS r;
      IF ((0 <> 0) OR (v_errcode <> 0)) THEN
        RAISE EXCEPTION 'Problem while Generating Proforma Sale Invoice';
        return_value := -1;
        RETURN;
      END IF;
    END IF;
    UPDATE dbo.issuereqheader SET posted = 'Y', postedby = v_usercode, postdate = localtimestamp(3) WHERE (serviceocode = v_serviceocode);
    UPDATE dbo.serviceoheader SET posted = 'Y', postdate = localtimestamp(3), postedby = v_usercode, saleinvcode = v_saleinvcode, serviceinvcode = v_serviceinvcode WHERE ((serviceocode = v_serviceocode) AND (posted = 'N'));
  END IF;
  IF (0 = 0) THEN
    return_value := 0;
    RETURN;
  ELSE
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
END
$body$;

