  UPDATE dbo._tabmaxkey SET tabmaxkey = CASE (SELECT max(acccode) FROM dbo.accounts) WHEN NULL THEN 0 ELSE (SELECT max(acccode) FROM dbo.accounts) END WHERE (tabname = 'Accounts');
