-- ==== proc SP_AbsoluteOpeningBalance ====
CREATE OR REPLACE FUNCTION dbo.sp_absoluteopeningbalance(acccode integer, INOUT bal numeric, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_acccode integer;
  v_bal numeric(15,5);
BEGIN
  v_acccode := acccode;
  v_bal := bal;
  PERFORM dbo.sp_virtualgl(ac_type => 'A');
  v_bal := 0;
  v_bal := coalesce((SELECT coalesce(sum((debit - credit)), 0) FROM dbo.virtualgl WHERE (acccode IN (SELECT acccode FROM dbo.udf_getsummaryaccountlist(v_acccode) AS udf_getsummaryaccountlist))), 0);
  return_value := 0;
  bal := v_bal;
  RETURN;
END
$body$;

-- ==== proc sp_AccountOpeningBalance ====
CREATE OR REPLACE FUNCTION dbo.sp_accountopeningbalance(al_acccode integer, ad_edate timestamp, INOUT af_openbalance numeric, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_al_acccode integer;
  v_ad_edate timestamp(3);
  v_af_openbalance numeric(15,5);
BEGIN
  v_al_acccode := al_acccode;
  v_ad_edate := ad_edate;
  v_af_openbalance := af_openbalance;
  v_af_openbalance := coalesce((SELECT (sum(debit) - sum(credit)) FROM dbo.virtualgl WHERE ((acccode = v_al_acccode) AND (date < v_ad_edate))), 0);
  return_value := 0;
  af_openbalance := v_af_openbalance;
  RETURN;
END
$body$;

-- ==== proc sp_AccountsBalance ====
CREATE OR REPLACE FUNCTION dbo.sp_accountsbalance(ad_date timestamp, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ad_date timestamp(3);
  v_ln_purchaseacc numeric(5,0);
  v_ln_cashacc numeric(5,0);
  v_ln_equityacc numeric(5,0);
  v_ln_salesacc numeric(5,0);
  v_ln_salesretacc numeric(5,0);
  v_ln_purchaseretacc numeric(5,0);
  v_ln_revfromservice numeric(5,0);
  v_ln_salestaxacc numeric(5,0);
BEGIN
  v_ad_date := ad_date;
  v_ln_purchaseacc := (SELECT code FROM dbo.global WHERE (name = 'GT_PurchaseAccount'));
  v_ln_cashacc := (SELECT code FROM dbo.global WHERE (name = 'GT_CashACC'));
  v_ln_equityacc := (SELECT code FROM dbo.global WHERE (name = 'GT_EquityACC'));
  v_ln_salesacc := (SELECT code FROM dbo.global WHERE (name = 'GT_SalesACC'));
  v_ln_salesretacc := (SELECT code FROM dbo.global WHERE (name = 'GT_SalesReturnACC'));
  v_ln_purchaseretacc := (SELECT code FROM dbo.global WHERE (name = 'GT_PurchaseReturnsAccount'));
  v_ln_revfromservice := (SELECT code FROM dbo.global WHERE (name = 'GT_RevenueFromServices'));
  v_ln_salestaxacc := (SELECT code FROM dbo.global WHERE (name = 'GT_AdvanceSalesTaxACC'));
  DROP TABLE IF EXISTS tmp_lt_accounts;
  CREATE TEMP TABLE tmp_lt_accounts (
    acccode numeric(5,0) NOT NULL,
    currbalance numeric(15,2) NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_accounts SELECT acccode, 0 FROM dbo.accounts;
  DROP TABLE IF EXISTS tmp_lt_accentries;
  CREATE TEMP TABLE tmp_lt_accentries (
    acccode numeric(5,0) NOT NULL,
    saletax numeric(15,2) NOT NULL,
    gross numeric(15,2) NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_accentries SELECT CASE purledger.purcatcode WHEN 3 THEN v_ln_equityacc ELSE purledger.suppcode END, round((((sum(((((purdetail.looseqty + purdetail.packqty) + purdetail.bonusqty)) * purdetail.unitsalestax)) + sum(round((((((((purdetail.looseqty + purdetail.packqty)) * purdetail.purprice) * ((1 - ((.01 * purdetail.discperc))))) * purdetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((((purdetail.looseqty + purdetail.packqty)) * purdetail.purprice)) * ((1 - ((.01 * purdetail.discperc)))))) * ((1 - ((.01 * purledger.discperc))))) - purledger.flatdisc)) * ((purledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) AS saletax, round((((((sum(((((purdetail.looseqty + purdetail.packqty)) * purdetail.purprice) * ((1 - ((.01 * purdetail.discperc)))))) * ((1 - ((.01 * purledger.discperc))))) + purledger.misccharges) + purledger.salestax) - purledger.flatdisc))::numeric, 0) AS gross FROM dbo.purledger, dbo.purdetail WHERE (((purledger.date <= v_ad_date) AND (purledger.posted = 'Y')) AND (purledger.purinvcode = purdetail.purinvcode)) GROUP BY purledger.purinvcode, purledger.purcatcode, purledger.date, purledger.discperc, purledger.misccharges, purledger.salestax, purledger.flatdisc, purledger.invgstperc1, purledger.suppcode;
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(saletax), 0) FROM tmp_lt_accentries AS lt_accentries)) WHERE (lt_accounts.acccode = v_ln_salestaxacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(gross), 0) FROM tmp_lt_accentries AS lt_accentries)) WHERE (lt_accounts.acccode = v_ln_purchaseacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance - (SELECT sum(coalesce((lt_accentries.gross + lt_accentries.saletax), 0)) FROM tmp_lt_accentries AS lt_accentries WHERE (lt_accentries.acccode = lt_accounts.acccode))) FROM tmp_lt_accentries AS lt_accentries WHERE (lt_accounts.acccode = lt_accentries.acccode);
  DELETE FROM tmp_lt_accentries AS lt_accentries;
  INSERT INTO tmp_lt_accentries SELECT CASE prledger.prcatcode WHEN 6 THEN v_ln_equityacc ELSE prledger.suppcode END, round((((sum((((prdetail.looseqty + prdetail.bonusqty)) * prdetail.unitsalestax)) + sum(round((((((prdetail.looseqty * prdetail.prprice) * ((1 - ((.01 * prdetail.discperc))))) * prdetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((prdetail.looseqty * prdetail.prprice)) * ((1 - ((.01 * prdetail.discperc)))))) * ((1 - ((.01 * prledger.discperc))))) - prledger.flatdisc)) * ((prledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) AS saletax, round((((((sum((((prdetail.looseqty * prdetail.prprice)) * ((1 - ((.01 * prdetail.discperc)))))) * ((1 - ((.01 * prledger.discperc))))) + prledger.misccharges) + prledger.salestax) - prledger.flatdisc))::numeric, 0) AS gross FROM dbo.prledger, dbo.prdetail WHERE (((prledger.date <= v_ad_date) AND (prledger.posted = 'Y')) AND (prledger.prinvcode = prdetail.prinvcode)) GROUP BY prledger.prinvcode, prledger.suppcode, prledger.prcatcode, prledger.date, prledger.discperc, prledger.misccharges, prledger.salestax, prledger.invgstperc1, prledger.flatdisc;
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance - (SELECT coalesce(sum(saletax), 0) FROM tmp_lt_accentries AS lt_accentries)) WHERE (lt_accounts.acccode = v_ln_salestaxacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance - (SELECT coalesce(sum(gross), 0) FROM tmp_lt_accentries AS lt_accentries)) WHERE (lt_accounts.acccode = v_ln_purchaseretacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT sum(coalesce((lt_accentries.gross + lt_accentries.saletax), 0)) FROM tmp_lt_accentries AS lt_accentries WHERE (lt_accentries.acccode = lt_accounts.acccode))) FROM tmp_lt_accentries AS lt_accentries WHERE (lt_accounts.acccode = lt_accentries.acccode);
  DELETE FROM tmp_lt_accentries AS lt_accentries;
  INSERT INTO tmp_lt_accentries SELECT CASE saleledger.salecatcode WHEN 1 THEN v_ln_cashacc WHEN 3 THEN v_ln_cashacc ELSE saleledger.custcode END, round((((sum((saledetail.looseqty * saledetail.unitsalestax)) + sum(round(((((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc))))) * saledetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc)))))) * ((1 - ((.01 * saleledger.discperc))))) - saleledger.flatdisc)) * ((saleledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) AS saletax, round((((((sum((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc)))))) * ((1 - ((.01 * saleledger.discperc))))) + saleledger.misccharges) + saleledger.salestax) - saleledger.flatdisc))::numeric, 0) AS gross FROM dbo.saleledger, dbo.saledetail WHERE (((saleledger.date <= v_ad_date) AND (saleledger.posted = 'Y')) AND (saleledger.saleinvcode = saledetail.saleinvcode)) GROUP BY saleledger.saleinvcode, saleledger.custcode, saleledger.salecatcode, saleledger.date, saleledger.discperc, saleledger.misccharges, saleledger.salestax, saleledger.invgstperc1, saleledger.flatdisc;
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance - (SELECT coalesce(sum(saletax), 0) FROM tmp_lt_accentries AS lt_accentries)) WHERE (lt_accounts.acccode = v_ln_salestaxacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance - (SELECT coalesce(sum(gross), 0) FROM tmp_lt_accentries AS lt_accentries)) WHERE (lt_accounts.acccode = v_ln_salesacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT sum(coalesce((lt_accentries.gross + lt_accentries.saletax), 0)) FROM tmp_lt_accentries AS lt_accentries WHERE (lt_accentries.acccode = lt_accounts.acccode))) FROM tmp_lt_accentries AS lt_accentries WHERE (lt_accounts.acccode = lt_accentries.acccode);
  DELETE FROM tmp_lt_accentries AS lt_accentries;
  INSERT INTO tmp_lt_accentries SELECT CASE srledger.srcatcode WHEN 6 THEN v_ln_cashacc WHEN 8 THEN v_ln_cashacc ELSE srledger.custcode END, round((((sum((srdetail.looseqty * srdetail.unitsalestax)) + sum(round(((((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc))))) * srdetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc)))))) * ((1 - ((.01 * srledger.discperc))))) - srledger.flatdisc)) * ((srledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) AS saletax, round((((((sum((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc)))))) * ((1 - ((.01 * srledger.discperc))))) + srledger.misccharges) + srledger.salestax) - srledger.flatdisc))::numeric, 0) AS gross FROM dbo.srledger, dbo.srdetail WHERE (((srledger.date <= v_ad_date) AND (srledger.posted = 'Y')) AND (srledger.srinvcode = srdetail.srinvcode)) GROUP BY srledger.srinvcode, srledger.custcode, srledger.srcatcode, srledger.date, srledger.discperc, srledger.misccharges, srledger.salestax, srledger.invgstperc1, srledger.flatdisc;
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(saletax), 0) FROM tmp_lt_accentries AS lt_accentries)) WHERE (lt_accounts.acccode = v_ln_salestaxacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(gross), 0) FROM tmp_lt_accentries AS lt_accentries)) WHERE (lt_accounts.acccode = v_ln_salesretacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance - (SELECT sum(coalesce((lt_accentries.gross + lt_accentries.saletax), 0)) FROM tmp_lt_accentries AS lt_accentries WHERE (lt_accentries.acccode = lt_accounts.acccode))) FROM tmp_lt_accentries AS lt_accentries WHERE (lt_accounts.acccode = lt_accentries.acccode);
  DELETE FROM tmp_lt_accentries AS lt_accentries;
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum((gldetail.debit - gldetail.credit)), 0) FROM dbo.glheader, dbo.gldetail WHERE ((((glheader.date <= v_ad_date) AND (glheader.posted = 'Y')) AND (glheader.glvochcode = gldetail.glvochcode)) AND (gldetail.acccode = lt_accounts.acccode)))) WHERE (lt_accounts.acccode IN (SELECT DISTINCT acccode FROM dbo.gldetail));
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(CASE notecatcode WHEN 1 THEN (amount * -1) ELSE notes.amount END), 0) FROM dbo.notes WHERE (((notes.postdate <= v_ad_date) AND (notes.posted = 'Y')) AND (notes.acccode = lt_accounts.acccode)))) WHERE (lt_accounts.acccode IN (SELECT DISTINCT acccode FROM dbo.notes));
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(CASE notecatcode WHEN 1 THEN amount ELSE (notes.amount * -1) END), 0) FROM dbo.notes WHERE (((notes.postdate <= v_ad_date) AND (notes.posted = 'Y')) AND (notes.bankacccode = lt_accounts.acccode)))) WHERE (lt_accounts.acccode IN (SELECT DISTINCT bankacccode FROM dbo.notes));
  INSERT INTO tmp_lt_accentries SELECT CASE h.servicecatcode WHEN 10 THEN v_ln_cashacc WHEN 12 THEN v_ln_cashacc ELSE h.custcode END, 0.00 AS saletax, coalesce(round((sum((((((coalesce(d.price, 0) * ((1 - ((.01 * coalesce(d.discperc, 0))))))) * ((1 - ((.01 * h.discperc))))) + coalesce(h.misccharges, 0)) - coalesce(h.flatdisc, 0))))::numeric, 0), 0) AS gross FROM dbo.serviceheader AS h, dbo.servicedetail AS d WHERE (((h.date <= v_ad_date) AND (h.posted = 'Y')) AND (h.serviceinvcode = d.serviceinvcode)) GROUP BY h.serviceinvcode, h.custcode, h.servicecatcode, h.date, h.discperc, h.misccharges, h.flatdisc;
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance - (SELECT coalesce(sum(gross), 0) FROM tmp_lt_accentries AS lt_accentries)) WHERE (lt_accounts.acccode = v_ln_revfromservice);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(lt_accentries.gross), 0) FROM tmp_lt_accentries AS lt_accentries WHERE (lt_accentries.acccode = lt_accounts.acccode))) FROM tmp_lt_accentries AS lt_accentries WHERE (lt_accounts.acccode = lt_accentries.acccode);
  DELETE FROM tmp_lt_accentries AS lt_accentries;
  INSERT INTO tmp_lt_accentries SELECT CASE h.servicercatcode WHEN 13 THEN v_ln_cashacc WHEN 15 THEN v_ln_cashacc ELSE h.custcode END, 0.00 AS saletax, coalesce(round((sum((((((coalesce(d.serviceprice, 0) * ((1 - ((.01 * coalesce(d.discperc, 0))))))) * ((1 - ((.01 * h.discperc))))) + coalesce(h.misccharges, 0)) - coalesce(h.flatdisc, 0))))::numeric, 0), 0) AS gross FROM dbo.servicerheader AS h, dbo.servicerdetail AS d WHERE (((h.date <= v_ad_date) AND (h.posted = 'Y')) AND (h.servicerinvcode = d.servicerinvcode)) GROUP BY h.servicerinvcode, h.custcode, h.servicercatcode, h.date, h.discperc, h.misccharges, h.flatdisc;
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(gross), 0) FROM tmp_lt_accentries AS lt_accentries)) WHERE (lt_accounts.acccode = v_ln_revfromservice);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance - (SELECT coalesce(sum(lt_accentries.gross), 0) FROM tmp_lt_accentries AS lt_accentries WHERE (lt_accentries.acccode = lt_accounts.acccode))) FROM tmp_lt_accentries AS lt_accentries WHERE (lt_accounts.acccode = lt_accentries.acccode);
  DROP TABLE IF EXISTS tmp_lt_accentries;
  DELETE FROM dbo.reportdata;
  INSERT INTO dbo.reportdata (name1, name2, value1, code1) SELECT accounts.name, subaccounts.name, lt_accounts.currbalance, accounts.acccode FROM dbo.accounts, tmp_lt_accounts AS lt_accounts, dbo.subaccounts WHERE ((accounts.acccode = lt_accounts.acccode) AND (accounts.subcode = subaccounts.subacccode));
  DROP TABLE IF EXISTS tmp_lt_accounts;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_AccountsLedger ====
CREATE OR REPLACE FUNCTION dbo.sp_accountsledger(ad_startdate timestamp, ad_enddate timestamp, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ad_startdate timestamp(3);
  v_ad_enddate timestamp(3);
  v_ln_purchaseacc numeric(5,0);
  v_ln_cashacc numeric(5,0);
  v_ln_equityacc numeric(5,0);
  v_ln_salesacc numeric(5,0);
  v_ln_salesretacc numeric(5,0);
  v_ln_purchaseretacc numeric(5,0);
  v_ln_revfromservice numeric(5,0);
  v_ln_salestaxacc numeric(5,0);
BEGIN
  v_ad_startdate := ad_startdate;
  v_ad_enddate := ad_enddate;
  v_ln_purchaseacc := (SELECT code FROM dbo.global WHERE (name = 'GT_PurchaseAccount'));
  v_ln_cashacc := (SELECT code FROM dbo.global WHERE (name = 'GT_CashACC'));
  v_ln_equityacc := (SELECT code FROM dbo.global WHERE (name = 'GT_EquityACC'));
  v_ln_salesacc := (SELECT code FROM dbo.global WHERE (name = 'GT_SalesACC'));
  v_ln_salesretacc := (SELECT code FROM dbo.global WHERE (name = 'GT_SalesReturnACC'));
  v_ln_purchaseretacc := (SELECT code FROM dbo.global WHERE (name = 'GT_PurchaseReturnsAccount'));
  v_ln_revfromservice := (SELECT code FROM dbo.global WHERE (name = 'GT_RevenueFromServices'));
  v_ln_salestaxacc := (SELECT code FROM dbo.global WHERE (name = 'GT_AdvanceSalesTaxACC'));
  PERFORM dbo.sp_accountsbalance(ad_date => v_ad_startdate);
  DROP TABLE IF EXISTS tmp_lt_accounts;
  CREATE TEMP TABLE tmp_lt_accounts (
    acccode numeric(5,0) NOT NULL,
    accname citext NULL,
    subaccname citext NULL,
    openbalance numeric(15,2) NOT NULL
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_lt_accountsledger;
  CREATE TEMP TABLE tmp_lt_accountsledger (
    acccode numeric(5,0) NOT NULL,
    type citext NOT NULL,
    date timestamp(3) NOT NULL,
    debit numeric(12,2) NOT NULL,
    credit numeric(12,2) NOT NULL,
    remarks citext NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_accounts SELECT code1, name1, name2, value1 FROM dbo.reportdata;
  INSERT INTO tmp_lt_accountsledger SELECT gldetail.acccode AS acccode, (CASE vochcatcode WHEN 1 THEN 'CP-' WHEN 2 THEN 'CR-' WHEN 3 THEN 'BP-' WHEN 4 THEN 'BR-' WHEN 5 THEN 'JV-' ELSE 'OV-' END || ltrim(dbo.tsql_str((glheader.glvochcode)::numeric))) AS type, glheader.date AS date, gldetail.debit AS debit, gldetail.credit AS credit, glheader.remarks AS remarks FROM dbo.glheader, dbo.gldetail WHERE (((glheader.date BETWEEN v_ad_startdate AND v_ad_enddate) AND (glheader.posted = 'Y')) AND (glheader.glvochcode = gldetail.glvochcode));
  INSERT INTO tmp_lt_accountsledger SELECT notes.acccode AS acccode, (CASE notes.notecatcode WHEN 1 THEN 'NR-' ELSE 'NP-' END || ltrim(dbo.tsql_str((notes.notecode)::numeric))) AS type, notes.postdate AS date, CASE notes.notecatcode WHEN 2 THEN notes.amount ELSE 0 END AS debit, CASE notes.notecatcode WHEN 1 THEN notes.amount ELSE 0 END AS credit, notes.remarks AS remarks FROM dbo.notes WHERE ((notes.postdate BETWEEN v_ad_startdate AND v_ad_enddate) AND (notes.posted = 'Y'));
  INSERT INTO tmp_lt_accountsledger SELECT notes.bankacccode AS acccode, (CASE notes.notecatcode WHEN 1 THEN 'NR-' ELSE 'NP-' END || ltrim(dbo.tsql_str((notes.notecode)::numeric))) AS type, notes.postdate AS date, CASE notes.notecatcode WHEN 1 THEN notes.amount ELSE 0 END AS debit, CASE notes.notecatcode WHEN 2 THEN notes.amount ELSE 0 END AS credit, notes.remarks AS remarks FROM dbo.notes WHERE ((notes.postdate BETWEEN v_ad_startdate AND v_ad_enddate) AND (notes.posted = 'Y'));
  DELETE FROM dbo.reportdata;
  INSERT INTO dbo.reportdata (name1, name4, value3, name2, date1, value1, value2, name3) SELECT rtrim(lt_accounts.accname), rtrim(lt_accounts.subaccname), lt_accounts.openbalance, lt_accountsledger.type, lt_accountsledger.date, lt_accountsledger.debit, lt_accountsledger.credit, lt_accountsledger.remarks FROM tmp_lt_accounts AS lt_accounts, tmp_lt_accountsledger AS lt_accountsledger WHERE (lt_accounts.acccode = lt_accountsledger.acccode) ORDER BY accname;
  UPDATE dbo.reportdata AS reportdata SET code1 = accounts.acccode FROM dbo.accounts WHERE (reportdata.name1 = accounts.name);
  DROP TABLE IF EXISTS tmp_lt_accounts;
  DROP TABLE IF EXISTS tmp_lt_accountsledger;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_AccountsLedger1 ====
CREATE OR REPLACE FUNCTION dbo.sp_accountsledger1(ai_acccode integer, ad_sdate timestamp, ad_ldate timestamp, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_acccode integer;
  v_ad_sdate timestamp(3);
  v_ad_ldate timestamp(3);
  v_ln_purchaseacc numeric(5,0);
  v_ln_cashacc numeric(5,0);
  v_ln_equityacc numeric(5,0);
  v_ln_salesacc numeric(5,0);
  v_ln_salesretacc numeric(5,0);
  v_ln_purchaseretacc numeric(5,0);
  v_ln_revfromservice numeric(5,0);
  v_ln_salestaxacc numeric(5,0);
  v_ln_openingbalance numeric(15,2);
BEGIN
  v_ai_acccode := ai_acccode;
  v_ad_sdate := ad_sdate;
  v_ad_ldate := ad_ldate;
  v_ln_purchaseacc := (SELECT code FROM dbo.global WHERE (name = 'GT_PurchaseAccount'));
  v_ln_cashacc := (SELECT code FROM dbo.global WHERE (name = 'GT_CashACC'));
  v_ln_equityacc := (SELECT code FROM dbo.global WHERE (name = 'GT_EquityACC'));
  v_ln_salesacc := (SELECT code FROM dbo.global WHERE (name = 'GT_SalesACC'));
  v_ln_salesretacc := (SELECT code FROM dbo.global WHERE (name = 'GT_SalesReturnACC'));
  v_ln_purchaseretacc := (SELECT code FROM dbo.global WHERE (name = 'GT_PurchaseReturnsAccount'));
  v_ln_revfromservice := (SELECT code FROM dbo.global WHERE (name = 'GT_RevenueFromServices'));
  v_ln_salestaxacc := (SELECT code FROM dbo.global WHERE (name = 'GT_AdvanceSalesTaxACC'));
  DROP TABLE IF EXISTS tmp_lt_virtualgl;
  CREATE TEMP TABLE tmp_lt_virtualgl (
    documentcode integer NOT NULL,
    documenttype citext NOT NULL,
    catcode smallint NOT NULL,
    dr_acccode smallint NOT NULL,
    cr_acccode smallint NOT NULL,
    alternateacccode smallint NULL,
    date timestamp(3) NOT NULL,
    amount numeric(15,2) NOT NULL,
    remarks citext NULL,
    checkno citext NULL,
    usercode smallint NULL
) ON COMMIT DROP;
  IF (v_ai_acccode = v_ln_cashacc) THEN
    v_ln_openingbalance := (((((SELECT coalesce(sum(s.amount), 0) FROM (SELECT coalesce((round((((sum((saledetail.looseqty * saledetail.unitsalestax)) + sum(round(((((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc))))) * saledetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc)))))) * ((1 - ((.01 * saleledger.discperc))))) - saleledger.flatdisc)) * ((saleledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) + round((((((sum((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc)))))) * ((1 - ((.01 * saleledger.discperc))))) + saleledger.misccharges) + saleledger.salestax) - saleledger.flatdisc))::numeric, 0)), 0) AS amount FROM dbo.saleledger, dbo.saledetail WHERE (((saleledger.salecatcode IN (1, 3)) AND (saleledger.date < v_ad_sdate)) AND (saleledger.saleinvcode = saledetail.saleinvcode)) GROUP BY saleledger.saleinvcode, saleledger.custcode, saleledger.salecatcode, saleledger.date, saleledger.discperc, saleledger.misccharges, saleledger.salestax, saleledger.invgstperc1, saleledger.flatdisc, saleledger.salesmancode) AS s) - (SELECT coalesce(sum(sr.amount), 0) FROM (SELECT coalesce((round((((sum((srdetail.looseqty * srdetail.unitsalestax)) + sum(round(((((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc))))) * srdetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc)))))) * ((1 - ((.01 * srledger.discperc))))) - srledger.flatdisc)) * ((srledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) + round((((((sum((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc)))))) * ((1 - ((.01 * srledger.discperc))))) + srledger.misccharges) + srledger.salestax) - srledger.flatdisc))::numeric, 0)), 0) AS amount FROM dbo.srledger, dbo.srdetail WHERE ((((srledger.srcatcode IN (8, 6)) AND (srledger.date < v_ad_sdate)) AND (srledger.posted = 'Y')) AND (srledger.srinvcode = srdetail.srinvcode)) GROUP BY srledger.srinvcode, srledger.custcode, srledger.srcatcode, srledger.date, srledger.discperc, srledger.misccharges, srledger.salestax, srledger.invgstperc1, srledger.flatdisc, srledger.salesmancode) AS sr)) + (SELECT coalesce(sum(ser.amount), 0) FROM (SELECT coalesce(round((sum((((((coalesce(d.price, 0) * ((1 - ((.01 * coalesce(d.discperc, 0))))))) * ((1 - ((.01 * coalesce(h.discperc, 0)))))) + coalesce(h.misccharges, 0)) - coalesce(h.flatdisc, 0))))::numeric, 0), 0) AS amount FROM dbo.serviceheader AS h, dbo.servicedetail AS d WHERE (((h.servicecatcode IN (10, 12)) AND (h.date < v_ad_sdate)) AND (h.serviceinvcode = d.serviceinvcode)) GROUP BY h.serviceinvcode, h.custcode, h.servicecatcode, h.date, h.discperc, h.misccharges, h.flatdisc, h.salesmancode) AS ser)) - (SELECT coalesce(sum(serr.amount), 0) FROM (SELECT coalesce(round((sum((((((coalesce(d.serviceprice, 0) * ((1 - ((.01 * coalesce(d.discperc, 0))))))) * ((1 - ((.01 * h.discperc))))) + coalesce(h.misccharges, 0)) - coalesce(h.flatdisc, 0))))::numeric, 0), 0) AS amount FROM dbo.servicerheader AS h, dbo.servicerdetail AS d WHERE ((((h.servicercatcode IN (13, 15)) AND (h.date < v_ad_sdate)) AND (h.posted = 'Y')) AND (h.servicerinvcode = d.servicerinvcode)) GROUP BY h.servicerinvcode, h.custcode, h.servicercatcode, h.date, h.discperc, h.misccharges, h.flatdisc, h.salesmancode) AS serr)) + (SELECT coalesce(sum((gl.debit - gl.credit)), 0) FROM (SELECT debit, credit, gldetail.glvochcode, glheader.postdate FROM dbo.gldetail, dbo.glheader WHERE ((((glheader.postdate < v_ad_sdate) AND (glheader.posted = 'Y')) AND (glheader.glvochcode = gldetail.glvochcode)) AND (gldetail.acccode = v_ai_acccode))) AS gl));
    INSERT INTO tmp_lt_virtualgl SELECT saleledger.saleinvcode AS documentcode, 'SV' AS documenttype, saleledger.salecatcode AS catcode, trunc(CASE saleledger.salecatcode WHEN 1 THEN v_ln_cashacc WHEN 3 THEN v_ln_cashacc ELSE saleledger.custcode END)::smallint AS dr_acccode, trunc(v_ln_salesacc)::smallint AS cr_acccode, CASE saleledger.salecatcode WHEN 1 THEN saleledger.custcode WHEN 3 THEN saleledger.custcode ELSE NULL END AS alternateacccode, saleledger.date AS date, coalesce((round((((sum((saledetail.looseqty * saledetail.unitsalestax)) + sum(round(((((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc))))) * saledetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc)))))) * ((1 - ((.01 * saleledger.discperc))))) - saleledger.flatdisc)) * ((saleledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) + round((((((sum((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc)))))) * ((1 - ((.01 * saleledger.discperc))))) + saleledger.misccharges) + saleledger.salestax) - saleledger.flatdisc))::numeric, 0)), 0) AS amount, max(saleledger.remarks) AS remarks, NULL::citext AS checkno, saleledger.salesmancode AS usercode FROM dbo.saleledger, dbo.saledetail WHERE (((saleledger.salecatcode IN (1, 3)) AND (saleledger.date BETWEEN v_ad_sdate AND v_ad_ldate)) AND (saleledger.saleinvcode = saledetail.saleinvcode)) GROUP BY saleledger.saleinvcode, saleledger.custcode, saleledger.salecatcode, saleledger.date, saleledger.discperc, saleledger.misccharges, saleledger.salestax, saleledger.invgstperc1, saleledger.flatdisc, saleledger.salesmancode;
    INSERT INTO tmp_lt_virtualgl SELECT srledger.srinvcode AS documentcode, 'SRV' AS documenttype, srledger.srcatcode AS catcode, trunc(v_ln_salesretacc)::smallint AS dr_acccode, trunc(CASE srledger.srcatcode WHEN 6 THEN v_ln_cashacc WHEN 8 THEN v_ln_cashacc ELSE srledger.custcode END)::smallint AS cr_acccode, CASE srledger.srcatcode WHEN 6 THEN srledger.custcode WHEN 8 THEN srledger.custcode ELSE NULL END AS alternateacccode, srledger.date AS date, coalesce((round((((sum((srdetail.looseqty * srdetail.unitsalestax)) + sum(round(((((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc))))) * srdetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc)))))) * ((1 - ((.01 * srledger.discperc))))) - srledger.flatdisc)) * ((srledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) + round((((((sum((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc)))))) * ((1 - ((.01 * srledger.discperc))))) + srledger.misccharges) + srledger.salestax) - srledger.flatdisc))::numeric, 0)), 0) AS amount, max(srledger.remarks) AS remarks, NULL::citext AS checkno, coalesce(srledger.salesmancode, 0) AS usercode FROM dbo.srledger, dbo.srdetail WHERE ((((srledger.srcatcode IN (8, 6)) AND (srledger.date BETWEEN v_ad_sdate AND v_ad_ldate)) AND (srledger.posted = 'Y')) AND (srledger.srinvcode = srdetail.srinvcode)) GROUP BY srledger.srinvcode, srledger.custcode, srledger.srcatcode, srledger.date, srledger.discperc, srledger.misccharges, srledger.salestax, srledger.invgstperc1, srledger.flatdisc, srledger.salesmancode;
    INSERT INTO tmp_lt_virtualgl SELECT h.serviceinvcode AS documentcode, CASE h.servicecatcode WHEN 10 THEN 'SERV' WHEN 12 THEN 'SERV' ELSE 'SERV' END AS documenttype, h.servicecatcode AS catcode, trunc(CASE h.servicecatcode WHEN 10 THEN v_ln_cashacc WHEN 12 THEN v_ln_cashacc ELSE h.custcode END)::smallint AS dr_acccode, trunc(v_ln_revfromservice)::smallint AS cr_acccode, CASE h.servicecatcode WHEN 10 THEN h.custcode WHEN 12 THEN h.custcode ELSE NULL END AS alternateacccode, h.date AS date, coalesce(round((sum((((((coalesce(d.price, 0) * ((1 - ((.01 * coalesce(d.discperc, 0))))))) * ((1 - ((.01 * coalesce(h.discperc, 0)))))) + coalesce(h.misccharges, 0)) - coalesce(h.flatdisc, 0))))::numeric, 0), 0) AS amount, max(h.remarks) AS remarks, NULL::citext AS checkno, coalesce(h.salesmancode, 0) AS usercode FROM dbo.serviceheader AS h, dbo.servicedetail AS d WHERE (((h.servicecatcode IN (10, 12)) AND (h.date BETWEEN v_ad_sdate AND v_ad_ldate)) AND (h.serviceinvcode = d.serviceinvcode)) GROUP BY h.serviceinvcode, h.custcode, h.servicecatcode, h.date, h.discperc, h.misccharges, h.flatdisc, h.salesmancode;
    INSERT INTO tmp_lt_virtualgl SELECT h.servicerinvcode AS documentcode, CASE h.servicercatcode WHEN 13 THEN 'SERRV' WHEN 15 THEN 'SERRV' ELSE 'SERRV' END AS documenttype, h.servicercatcode AS catcode, trunc(v_ln_revfromservice)::smallint AS dr_acccode, trunc(CASE h.servicercatcode WHEN 13 THEN v_ln_cashacc WHEN 15 THEN v_ln_cashacc ELSE h.custcode END)::smallint AS cr_acccode, CASE h.servicercatcode WHEN 13 THEN h.custcode WHEN 15 THEN h.custcode ELSE NULL END AS alternateacccode, h.date AS date, coalesce(round((sum((((((coalesce(d.serviceprice, 0) * ((1 - ((.01 * coalesce(d.discperc, 0))))))) * ((1 - ((.01 * h.discperc))))) + coalesce(h.misccharges, 0)) - coalesce(h.flatdisc, 0))))::numeric, 0), 0) AS amount, max(h.remarks) AS remarks, NULL::citext AS checkno, h.salesmancode AS usercode FROM dbo.servicerheader AS h, dbo.servicerdetail AS d WHERE ((((h.servicercatcode IN (13, 15)) AND (h.date BETWEEN v_ad_sdate AND v_ad_ldate)) AND (h.posted = 'Y')) AND (h.servicerinvcode = d.servicerinvcode)) GROUP BY h.servicerinvcode, h.custcode, h.servicercatcode, h.date, h.discperc, h.misccharges, h.flatdisc, h.salesmancode;
    DELETE FROM dbo.reportdata;
    INSERT INTO dbo.reportdata (code1, value1, value2, date1, name2, name3) SELECT v_ai_acccode, amount, 0, date, remarks, ((documentcode)::text || documenttype) FROM tmp_lt_virtualgl AS lt_virtualgl WHERE (documenttype IN ('SV', 'SERV'));
    INSERT INTO dbo.reportdata (code1, value1, value2, date1, name2, name3) SELECT v_ai_acccode, 0, amount, date, remarks, ((documentcode)::text || documenttype) FROM tmp_lt_virtualgl AS lt_virtualgl WHERE (documenttype IN ('SERRV', 'SRV'));
