  INSERT INTO dbo.reportdata (code1, name1, value1, value2, date1, name2, name3) SELECT gldetail.acccode, 'cash', debit, credit, glheader.postdate, gldetail.remarks, CASE glheader.vochcatcode WHEN 1 THEN ((glheader.glvochcode)::text || 'CPV') WHEN 2 THEN ((glheader.glvochcode)::text || 'CRV') WHEN 3 THEN ((glheader.glvochcode)::text || 'BPV') WHEN 4 THEN ((glheader.glvochcode)::text || 'BRV') WHEN 5 THEN ((glheader.glvochcode)::text || 'JV') ELSE ((glheader.glvochcode)::text || 'OPEN') END FROM dbo.gldetail, dbo.glheader WHERE ((((glheader.postdate BETWEEN v_ad_sdate AND v_ad_ldate) AND (glheader.posted = 'Y')) AND (glheader.glvochcode = gldetail.glvochcode)) AND (gldetail.acccode = v_ai_acccode));
  UPDATE dbo.reportdata SET value3 = (SELECT v_ln_openingbalance);
  DROP TABLE IF EXISTS tmp_lt_virtualgl;
  return_value := 0;
  RETURN;
END
$body$;

