-- ==== proc sp_Admit_Patient_Emergency ====
CREATE OR REPLACE FUNCTION dbo.sp_admit_patient_emergency(patientcode integer, usercode integer, doctcode smallint, INOUT admissioncode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_patientcode integer;
  v_usercode integer;
  v_doctcode smallint;
  v_admissioncode integer;
  v_code integer;
  v_rt_code integer;
  _rc integer;
BEGIN
  v_patientcode := patientcode;
  v_usercode := usercode;
  v_doctcode := doctcode;
  v_admissioncode := admissioncode;
  SELECT r.return_value, r.key INTO v_rt_code, v_code FROM dbo.sp_gettabmaxkey(tabname => 'PatientAdmission', key => v_code) AS r;
  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
    RAISE EXCEPTION 'Error occured in generating patient admission';
    return_value := -1;
    admissioncode := v_admissioncode;
    RETURN;
  END IF;
  INSERT INTO dbo.patientadmission (admissioncode, patientcode, locationcode, date, usercode, doctorcode, discharged1, discharged, diseasecode, cashacccode, cashtendered, cashcharged, cashback, diagnosis) VALUES (v_code, v_patientcode, 1, localtimestamp(3), v_usercode, v_doctcode, 'N', 'N', 1, 2, 0.00, 0.00, 0.00, 'SYSTEM GENERATED ADMISSION');
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((0 <> 0) OR (_rc = 0)) THEN
    RAISE EXCEPTION 'Error occured in inserting record into Patient Admission';
    return_value := -1;
    admissioncode := v_admissioncode;
    RETURN;
  END IF;
  v_admissioncode := v_code;
  _rc := 1;
  return_value := 0;
  admissioncode := v_admissioncode;
  RETURN;
  return_value := 0;
  admissioncode := v_admissioncode;
  RETURN;
END
$body$;

-- ==== proc SP_Admit_Student ====
CREATE OR REPLACE FUNCTION dbo.sp_admit_student(classcode integer, studentcode integer, INOUT rollno citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_classcode integer;
  v_studentcode integer;
  v_rollno citext;
  v_newrollno citext;
  _rc integer;
BEGIN
  v_classcode := classcode;
  v_studentcode := studentcode;
  v_rollno := rollno;
  DELETE FROM dbo.studentclass WHERE ((studentcode = v_studentcode) AND (classcode = v_classcode));
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_newrollno := coalesce((SELECT (coalesce(max((trunc((rollno)::numeric))::integer), 0) + 1) FROM dbo.studentclass WHERE (classcode = v_classcode)), 1);
  _rc := 1;
  IF (v_newrollno IS NULL) THEN
    v_newrollno := '';
    _rc := 1;
  END IF;
  INSERT INTO dbo.studentclass (classcode, studentcode, rollno, admissiondate) VALUES (v_classcode, v_studentcode, v_newrollno, localtimestamp(3));
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((_rc = 0) AND (0 <> 0)) THEN
    RAISE EXCEPTION 'Can Not Admit student in the specified class';
    return_value := -1;
    rollno := v_rollno;
    RETURN;
  END IF;
  v_rollno := v_newrollno;
  _rc := 1;
  UPDATE dbo.student SET currentclass = v_classcode, status = 'A' WHERE (studentcode = v_studentcode);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((_rc = 0) AND (0 <> 0)) THEN
    RAISE EXCEPTION 'Can Not Update Current Student Class in student regisration';
    return_value := -1;
    rollno := v_rollno;
    RETURN;
  END IF;
  return_value := 0;
  rollno := v_rollno;
  RETURN;
  return_value := 0;
  rollno := v_rollno;
  RETURN;
END
$body$;

-- ==== proc sp_Aging ====
CREATE OR REPLACE FUNCTION dbo.sp_aging(type citext, l_date timestamp, "interval" integer, "limit" integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_type citext;
  v_l_date timestamp(3);
  v_interval integer;
  v_limit integer;
  v_oldacccode integer;
  v_acccode integer;
  v_tdate timestamp(3);
  v_amt numeric(15,5);
  v_paid numeric(15,5);
  v_rowid integer;
  v_pmt numeric(15,5);
  v_daysold integer;
  v_startlimit integer;
  v_endlimit integer;
  cur_c1 refcursor;
  _fs integer := -1;
BEGIN
  v_type := type;
  v_l_date := l_date;
  v_interval := "interval";
  v_limit := "limit";
  DELETE FROM dbo.reportdata;
  DROP TABLE IF EXISTS tmp_lt_amt;
  CREATE TEMP TABLE tmp_lt_amt (
    acccode integer NOT NULL,
    date timestamp(3) NOT NULL,
    amount numeric(15,5) NOT NULL DEFAULT 0,
    paid numeric(15,5) NOT NULL DEFAULT 0,
    rowid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    daysold integer NOT NULL DEFAULT 0
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_lt_pmt;
  CREATE TEMP TABLE tmp_lt_pmt (
    acccode integer NOT NULL,
    amount numeric(15,5) NOT NULL DEFAULT 0
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_lt_interval;
  CREATE TEMP TABLE tmp_lt_interval (
    intervalid integer GENERATED BY DEFAULT AS IDENTITY (START WITH 0 INCREMENT BY 1 MINVALUE 0) NOT NULL,
    lowerlimit integer NOT NULL DEFAULT 0,
    upperlimit integer NOT NULL DEFAULT 0
) ON COMMIT DROP;
  v_startlimit := 0;
  WHILE (v_startlimit <= v_limit) LOOP
    v_endlimit := (v_startlimit + CASE v_startlimit WHEN 0 THEN 0 ELSE (v_interval - 1) END);
    v_endlimit := CASE WHEN (v_endlimit > v_limit) THEN v_limit ELSE v_endlimit END;
    INSERT INTO tmp_lt_interval (lowerlimit, upperlimit) VALUES (v_startlimit, v_endlimit);
    v_startlimit := (v_endlimit + 1);
  END LOOP;
  INSERT INTO tmp_lt_interval (lowerlimit, upperlimit) VALUES (v_startlimit, 99999999);
  IF (v_type = 'C') THEN
    INSERT INTO tmp_lt_amt (acccode, date, amount, paid, daysold) SELECT acccode, date, debit AS amount, 0 AS paid, ((v_l_date)::date - (date)::date) AS daysold FROM dbo.virtualgl WHERE (((date <= v_l_date) AND (debit > 0)) AND (acccode IN (SELECT custcode FROM dbo.customer))) ORDER BY acccode, date, debit;
    INSERT INTO tmp_lt_pmt SELECT acccode, sum(credit) AS amount FROM dbo.virtualgl WHERE (((date <= v_l_date) AND (credit > 0)) AND (acccode IN (SELECT custcode FROM dbo.customer))) GROUP BY acccode ORDER BY acccode;
  END IF;
  IF (v_type = 'S') THEN
    INSERT INTO tmp_lt_amt (acccode, date, amount, paid, daysold) SELECT acccode, date, credit AS amount, 0 AS paid, ((v_l_date)::date - (date)::date) AS daysold FROM dbo.virtualgl WHERE (((date <= v_l_date) AND (credit > 0)) AND (acccode IN (SELECT suppcode FROM dbo.supplier))) ORDER BY acccode, date, credit;
    INSERT INTO tmp_lt_pmt SELECT acccode, sum(debit) AS amount FROM dbo.virtualgl WHERE (((date <= v_l_date) AND (debit > 0)) AND (acccode IN (SELECT suppcode FROM dbo.supplier))) GROUP BY acccode ORDER BY acccode;
  END IF;
  OPEN cur_c1 FOR SELECT * FROM tmp_lt_amt AS lt_amt ORDER BY 1, 2, 3;
  FETCH NEXT FROM cur_c1 INTO v_acccode, v_tdate, v_amt, v_paid, v_rowid, v_daysold;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    v_pmt := coalesce((SELECT coalesce(amount, 0) FROM tmp_lt_pmt AS lt_pmt WHERE (acccode = v_acccode)), 0);
    IF (v_pmt <> 0) THEN
      UPDATE tmp_lt_amt AS lt_amt SET paid = (paid + CASE WHEN (v_amt >= v_pmt) THEN v_pmt ELSE v_amt END) WHERE (rowid = v_rowid);
      v_pmt := (v_pmt - (SELECT CASE WHEN (v_amt >= v_pmt) THEN v_pmt ELSE v_amt END));
      UPDATE tmp_lt_pmt AS lt_pmt SET amount = v_pmt WHERE (acccode = v_acccode);
    END IF;
    FETCH NEXT FROM cur_c1 INTO v_acccode, v_tdate, v_amt, v_paid, v_rowid, v_daysold;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_c1;
  -- DEALLOCATE C1
  DELETE FROM tmp_lt_amt AS lt_amt WHERE ((amount - paid) = 0);
  IF (v_type = 'C') THEN
    INSERT INTO dbo.reportdata (code1, name1, name2, name3, name4, name5, value1, code2) SELECT ar.areacode AS code1, ar.name AS name1, ac.aliasname AS name2, ac.name AS name3, left(((ltrim(rtrim(c.address1)) || ' ') || ltrim(rtrim(c.address2))), 60) AS name4, c.phone AS name5, sum((amount - paid)) AS value1, (SELECT max(lowerlimit) FROM tmp_lt_interval AS lt_interval WHERE ((l.daysold >= lowerlimit) AND (l.daysold <= upperlimit))) AS code2 FROM tmp_lt_amt AS l, dbo.accounts AS ac, dbo.area AS ar, dbo.customer AS c WHERE (((l.acccode = ac.acccode) AND (ac.acccode = c.custcode)) AND (c.areacode = ar.areacode)) GROUP BY ar.areacode, ar.name, ac.acccode, ac.name, ac.aliasname, c.address1, c.address2, c.phone, l.daysold;
  END IF;
  IF (v_type = 'S') THEN
    INSERT INTO dbo.reportdata (code1, name1, name2, name3, name4, name5, value1, code2) SELECT 0 AS code1, 'All Supplier(s)' AS name1, ac.aliasname AS name2, ac.name AS name3, left(((ltrim(rtrim(s.address1)) || ' ') || ltrim(rtrim(s.address2))), 60) AS name4, s.phone AS name5, sum((amount - paid)) AS value1, (SELECT max(lowerlimit) FROM tmp_lt_interval AS lt_interval WHERE ((l.daysold >= lowerlimit) AND (l.daysold <= upperlimit))) AS code2 FROM tmp_lt_amt AS l, dbo.accounts AS ac, dbo.supplier AS s WHERE ((l.acccode = ac.acccode) AND (ac.acccode = s.suppcode)) GROUP BY ac.acccode, ac.name, ac.aliasname, s.address1, s.address2, s.phone, l.daysold;
  END IF;
  DROP TABLE IF EXISTS tmp_lt_amt;
  DROP TABLE IF EXISTS tmp_lt_pmt;
  DROP TABLE IF EXISTS tmp_lt_interval;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_Aging_Account ====
CREATE OR REPLACE FUNCTION dbo.sp_aging_account(type citext, acccode integer, l_date timestamp, "interval" integer, "limit" integer, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_type citext;
  v_acccode integer;
  v_l_date timestamp(3);
  v_interval integer;
  v_limit integer;
  v_oldacccode integer;
  v_tdate timestamp(3);
  v_documentcode citext;
  v_amt numeric(15,5);
  v_paid numeric(15,5);
  v_rowid integer;
  v_pmt numeric(15,5);
  v_daysold integer;
  v_startlimit integer;
  v_endlimit integer;
  cur_c1 refcursor;
  _fs integer := -1;
BEGIN
  v_type := type;
  v_acccode := acccode;
  v_l_date := l_date;
  v_interval := "interval";
  v_limit := "limit";
  PERFORM dbo.sp_virtualgl(ac_type => 'A');
  DELETE FROM dbo.reportdata;
  DROP TABLE IF EXISTS tmp_lt_amt;
  CREATE TEMP TABLE tmp_lt_amt (
    acccode integer NOT NULL,
    documentcode citext,
    date timestamp(3) NOT NULL,
    amount numeric(15,5) NOT NULL DEFAULT 0,
    paid numeric(15,5) NOT NULL DEFAULT 0,
    rowid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    daysold integer NOT NULL DEFAULT 0
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_lt_pmt;
  CREATE TEMP TABLE tmp_lt_pmt (
    acccode integer NOT NULL,
    amount numeric(15,5) NOT NULL DEFAULT 0
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_lt_interval;
  CREATE TEMP TABLE tmp_lt_interval (
    intervalid integer GENERATED BY DEFAULT AS IDENTITY (START WITH 0 INCREMENT BY 1 MINVALUE 0) NOT NULL,
    lowerlimit integer NOT NULL DEFAULT 0,
    upperlimit integer NOT NULL DEFAULT 0
) ON COMMIT DROP;
  v_startlimit := 0;
  WHILE (v_startlimit <= v_limit) LOOP
    v_endlimit := (v_startlimit + CASE v_startlimit WHEN 0 THEN 0 ELSE (v_interval - 1) END);
    v_endlimit := CASE WHEN (v_endlimit > v_limit) THEN v_limit ELSE v_endlimit END;
    INSERT INTO tmp_lt_interval (lowerlimit, upperlimit) VALUES (v_startlimit, v_endlimit);
    v_startlimit := (v_endlimit + 1);
  END LOOP;
  INSERT INTO tmp_lt_interval (lowerlimit, upperlimit) VALUES (v_startlimit, 99999999);
  IF (v_type = 'C') THEN
    INSERT INTO tmp_lt_amt (acccode, documentcode, date, amount, paid, daysold) SELECT acccode, ((documenttype || '-') || ltrim(rtrim(dbo.tsql_str((documentcode)::numeric, 10)))) AS documentcode, date, debit AS amount, 0 AS paid, ((v_l_date)::date - (date)::date) AS daysold FROM dbo.virtualgl WHERE (((date <= v_l_date) AND (debit > 0)) AND (acccode = v_acccode)) ORDER BY acccode, date, debit;
    INSERT INTO tmp_lt_pmt SELECT acccode, sum(credit) AS amount FROM dbo.virtualgl WHERE (((date <= v_l_date) AND (credit > 0)) AND (acccode = v_acccode)) GROUP BY acccode ORDER BY acccode;
  END IF;
  IF (v_type = 'S') THEN
    INSERT INTO tmp_lt_amt (acccode, documentcode, date, amount, paid, daysold) SELECT acccode, ((documenttype || '-') || ltrim(rtrim(dbo.tsql_str((documentcode)::numeric, 10)))) AS documentcode, date, credit AS amount, 0 AS paid, ((v_l_date)::date - (date)::date) AS daysold FROM dbo.virtualgl WHERE (((date <= v_l_date) AND (credit > 0)) AND (acccode = v_acccode)) ORDER BY acccode, date, credit;
    INSERT INTO tmp_lt_pmt SELECT acccode, sum(debit) AS amount FROM dbo.virtualgl WHERE (((date <= v_l_date) AND (debit > 0)) AND (acccode = v_acccode)) GROUP BY acccode ORDER BY acccode;
  END IF;
  OPEN cur_c1 FOR SELECT * FROM tmp_lt_amt AS lt_amt ORDER BY 1, 3, 4;
  FETCH NEXT FROM cur_c1 INTO v_acccode, v_documentcode, v_tdate, v_amt, v_paid, v_rowid, v_daysold;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    v_pmt := coalesce((SELECT coalesce(amount, 0) FROM tmp_lt_pmt AS lt_pmt WHERE (acccode = v_acccode)), 0);
    IF (v_pmt <> 0) THEN
      UPDATE tmp_lt_amt AS lt_amt SET paid = (paid + CASE WHEN (v_amt >= v_pmt) THEN v_pmt ELSE v_amt END) WHERE (rowid = v_rowid);
      v_pmt := (v_pmt - (SELECT CASE WHEN (v_amt >= v_pmt) THEN v_pmt ELSE v_amt END));
      UPDATE tmp_lt_pmt AS lt_pmt SET amount = v_pmt WHERE (acccode = v_acccode);
    END IF;
    FETCH NEXT FROM cur_c1 INTO v_acccode, v_documentcode, v_tdate, v_amt, v_paid, v_rowid, v_daysold;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_c1;
  -- DEALLOCATE C1
  DELETE FROM tmp_lt_amt AS lt_amt WHERE ((amount - paid) = 0);
  IF (v_type = 'C') THEN
    INSERT INTO dbo.reportdata (code1, name1, name2, name3, name4, name5, name6, date1, value1, code2, code3) SELECT ar.areacode AS code1, ar.name AS name1, ac.aliasname AS name2, ac.name AS name3, left(((ltrim(rtrim(c.address1)) || ' ') || ltrim(rtrim(c.address2))), 60) AS name4, c.phone AS name5, l.documentcode AS name6, l.date AS date1, sum((amount - paid)) AS value1, (SELECT max(lowerlimit) FROM tmp_lt_interval AS lt_interval WHERE ((l.daysold >= lowerlimit) AND (l.daysold <= upperlimit))) AS code2, l.daysold AS code3 FROM tmp_lt_amt AS l, dbo.accounts AS ac, dbo.area AS ar, dbo.customer AS c WHERE (((l.acccode = ac.acccode) AND (ac.acccode = c.custcode)) AND (c.areacode = ar.areacode)) GROUP BY ar.areacode, ar.name, ac.acccode, ac.name, ac.aliasname, c.address1, c.address2, c.phone, l.date, l.documentcode, l.daysold;
  END IF;
  IF (v_type = 'S') THEN
    INSERT INTO dbo.reportdata (code1, name1, name2, name3, name4, name5, name6, date1, value1, code2, code3) SELECT 0 AS code1, 'All Supplier(s)' AS name1, ac.aliasname AS name2, ac.name AS name3, left(((ltrim(rtrim(s.address1)) || ' ') || ltrim(rtrim(s.address2))), 60) AS name4, s.phone AS name5, l.documentcode AS name6, l.date AS date1, sum((amount - paid)) AS value1, (SELECT max(lowerlimit) FROM tmp_lt_interval AS lt_interval WHERE ((l.daysold >= lowerlimit) AND (l.daysold <= upperlimit))) AS code2, l.daysold AS code3 FROM tmp_lt_amt AS l, dbo.accounts AS ac, dbo.supplier AS s WHERE ((l.acccode = ac.acccode) AND (ac.acccode = s.suppcode)) GROUP BY ac.acccode, ac.name, ac.aliasname, s.address1, s.address2, s.phone, l.date, l.documentcode, l.daysold;
  END IF;
  DROP TABLE IF EXISTS tmp_lt_amt;
  DROP TABLE IF EXISTS tmp_lt_pmt;
  DROP TABLE IF EXISTS tmp_lt_interval;
  OPEN rs1 FOR SELECT reportdata.code1, reportdata.value1, reportdata.name1, reportdata.name2, reportdata.name3, reportdata.name4, reportdata.name5, reportdata.name6, reportdata.date1, reportdata.code2, reportdata.code3 FROM dbo.reportdata ORDER BY name1, code1, name3, name2, date1, code2, value1;
  return_value := 0;
  RETURN;
END
$body$;

