  WHILE (v_startlimit <= v_limit) LOOP
    v_endlimit := (v_startlimit + CASE v_startlimit WHEN 0 THEN 0 ELSE (v_interval - 1) END);
    v_endlimit := CASE WHEN (v_endlimit > v_limit) THEN v_limit ELSE v_endlimit END;
    INSERT INTO tmp_lt_interval (lowerlimit, upperlimit) VALUES (v_startlimit, v_endlimit);
    v_startlimit := (v_endlimit + 1);
  END LOOP;
  INSERT INTO tmp_lt_interval (lowerlimit, upperlimit) VALUES (v_startlimit, 99999999);
  IF (v_type = 'C') THEN
    INSERT INTO tmp_lt_amt (acccode, date, amount, paid, daysold) SELECT acccode, date, debit AS amount, 0 AS paid, ((v_l_date)::date - (date)::date) AS daysold FROM dbo.virtualgl WHERE (((date <= v_l_date) AND (debit > 0)) AND (acccode IN (SELECT custcode FROM dbo.customer))) ORDER BY acccode, date, debit;
    INSERT INTO tmp_lt_pmt SELECT acccode, sum(credit) AS amount FROM dbo.virtualgl WHERE (((date <= v_l_date) AND (credit > 0)) AND (acccode IN (SELECT custcode FROM dbo.customer))) GROUP BY acccode ORDER BY acccode;
  END IF;
  IF (v_type = 'S') THEN
    INSERT INTO tmp_lt_amt (acccode, date, amount, paid, daysold) SELECT acccode, date, credit AS amount, 0 AS paid, ((v_l_date)::date - (date)::date) AS daysold FROM dbo.virtualgl WHERE (((date <= v_l_date) AND (credit > 0)) AND (acccode IN (SELECT suppcode FROM dbo.supplier))) ORDER BY acccode, date, credit;
    INSERT INTO tmp_lt_pmt SELECT acccode, sum(debit) AS amount FROM dbo.virtualgl WHERE (((date <= v_l_date) AND (debit > 0)) AND (acccode IN (SELECT suppcode FROM dbo.supplier))) GROUP BY acccode ORDER BY acccode;
  END IF;
  OPEN cur_c1 FOR SELECT * FROM tmp_lt_amt AS lt_amt ORDER BY 1, 2, 3;
  FETCH NEXT FROM cur_c1 INTO v_acccode, v_tdate, v_amt, v_paid, v_rowid, v_daysold;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    v_pmt := coalesce((SELECT coalesce(amount, 0) FROM tmp_lt_pmt AS lt_pmt WHERE (acccode = v_acccode)), 0);
    IF (v_pmt <> 0) THEN
      UPDATE tmp_lt_amt AS lt_amt SET paid = (paid + CASE WHEN (v_amt >= v_pmt) THEN v_pmt ELSE v_amt END) WHERE (rowid = v_rowid);
      v_pmt := (v_pmt - (SELECT CASE WHEN (v_amt >= v_pmt) THEN v_pmt ELSE v_amt END));
      UPDATE tmp_lt_pmt AS lt_pmt SET amount = v_pmt WHERE (acccode = v_acccode);
    END IF;
    FETCH NEXT FROM cur_c1 INTO v_acccode, v_tdate, v_amt, v_paid, v_rowid, v_daysold;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_c1;
  -- DEALLOCATE C1
  DELETE FROM tmp_lt_amt AS lt_amt WHERE ((amount - paid) = 0);
  IF (v_type = 'C') THEN
    INSERT INTO dbo.reportdata (code1, name1, name2, name3, name4, name5, value1, code2) SELECT code1, name1, name2, name3, name4, name5, sum(value1) AS value1, code2 FROM (SELECT ar.areacode AS code1, ar.name AS name1, ac.aliasname AS name2, ac.name AS name3, left(((ltrim(rtrim(c.address1)) || ' ') || ltrim(rtrim(c.address2))), 60) AS name4, c.phone AS name5, 0.00 AS value1, t.lowerlimit AS code2 FROM dbo.accounts AS ac, dbo.area AS ar, dbo.customer AS c, tmp_lt_interval AS t WHERE ((ac.acccode = c.custcode) AND (c.areacode = ar.areacode)) UNION ALL SELECT ar.areacode AS code1, ar.name AS name1, ac.aliasname AS name2, ac.name AS name3, left(((ltrim(rtrim(c.address1)) || ' ') || ltrim(rtrim(c.address2))), 60) AS name4, c.phone AS name5, sum((amount - paid)) AS value1, (SELECT max(lowerlimit) FROM tmp_lt_interval AS lt_interval WHERE ((l.daysold >= lowerlimit) AND (l.daysold <= upperlimit))) AS code2 FROM tmp_lt_amt AS l, dbo.accounts AS ac, dbo.area AS ar, dbo.customer AS c WHERE (((l.acccode = ac.acccode) AND (ac.acccode = c.custcode)) AND (c.areacode = ar.areacode)) GROUP BY ar.areacode, ar.name, ac.acccode, ac.name, ac.aliasname, c.address1, c.address2, c.phone, l.daysold) AS t GROUP BY code1, name1, name2, name3, name4, name5, code2;
  END IF;
  IF (v_type = 'S') THEN
    INSERT INTO dbo.reportdata (code1, name1, name2, name3, name4, name5, value1, code2) SELECT code1, name1, name2, name3, name4, name5, sum(value1) AS value1, code2 FROM (SELECT 0 AS code1, 'All Supplier(s)' AS name1, ac.aliasname AS name2, ac.name AS name3, left(((ltrim(rtrim(s.address1)) || ' ') || ltrim(rtrim(s.address2))), 60) AS name4, s.phone AS name5, 0.00 AS value1, t.lowerlimit AS code2 FROM dbo.accounts AS ac, dbo.supplier AS s, tmp_lt_interval AS t WHERE (ac.acccode = s.suppcode) UNION ALL SELECT 0 AS code1, 'All Supplier(s)' AS name1, ac.aliasname AS name2, ac.name AS name3, left(((ltrim(rtrim(s.address1)) || ' ') || ltrim(rtrim(s.address2))), 60) AS name4, s.phone AS name5, sum((amount - paid)) AS value1, (SELECT max(lowerlimit) FROM tmp_lt_interval AS lt_interval WHERE ((l.daysold >= lowerlimit) AND (l.daysold <= upperlimit))) AS code2 FROM tmp_lt_amt AS l, dbo.accounts AS ac, dbo.supplier AS s WHERE ((l.acccode = ac.acccode) AND (ac.acccode = s.suppcode)) GROUP BY ac.acccode, ac.name, ac.aliasname, s.address1, s.address2, s.phone, l.daysold) AS t GROUP BY code1, name1, name2, name3, name4, name5, code2;
  END IF;
  UPDATE dbo.reportdata AS r SET value1 = coalesce((SELECT sum(coalesce(t.value1, 0)) FROM dbo.reportdata AS t WHERE ((((t.code2 >= r.code2) AND (t.code1 = r.code1)) AND (t.name2 = r.name2)) AND (t.name3 = r.name3))), 0);
  DELETE FROM dbo.reportdata WHERE (value1 = 0);
  DROP TABLE IF EXISTS tmp_lt_amt;
  DROP TABLE IF EXISTS tmp_lt_pmt;
  DROP TABLE IF EXISTS tmp_lt_interval;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_Aging_CustomerWise ====
CREATE OR REPLACE FUNCTION dbo.sp_aging_customerwise(type citext, l_date timestamp, "interval" integer, "limit" integer, accountlist citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_type citext;
  v_l_date timestamp(3);
  v_interval integer;
  v_limit integer;
  v_accountlist citext;
  v_oldacccode integer;
  v_acccode integer;
  v_tdate timestamp(3);
  v_amt numeric(15,5);
  v_paid numeric(15,5);
  v_rowid integer;
  v_pmt numeric(15,5);
  v_daysold integer;
  v_startlimit integer;
  v_endlimit integer;
  cur_c1 refcursor;
  _fs integer := -1;
BEGIN
  v_type := type;
  v_l_date := l_date;
  v_interval := "interval";
  v_limit := "limit";
  v_accountlist := accountlist;
  DROP TABLE IF EXISTS tv_sp_aging_customerwise_tab_acclist;
  CREATE TEMP TABLE tv_sp_aging_customerwise_tab_acclist (
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tv_sp_aging_customerwise_tab_acclist SELECT code FROM dbo.udf_stringtotabl(v_accountlist, ',') AS udf_stringtotabl;
  DELETE FROM dbo.reportdata;
  DROP TABLE IF EXISTS tmp_lt_amt;
  CREATE TEMP TABLE tmp_lt_amt (
    acccode integer NOT NULL,
    date timestamp(3) NOT NULL,
    amount numeric(15,5) NOT NULL DEFAULT 0,
    paid numeric(15,5) NOT NULL DEFAULT 0,
    rowid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    daysold integer NOT NULL DEFAULT 0
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_lt_pmt;
  CREATE TEMP TABLE tmp_lt_pmt (
    acccode integer NOT NULL,
    amount numeric(15,5) NOT NULL DEFAULT 0
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_lt_interval;
  CREATE TEMP TABLE tmp_lt_interval (
    intervalid integer GENERATED BY DEFAULT AS IDENTITY (START WITH 0 INCREMENT BY 1 MINVALUE 0) NOT NULL,
    lowerlimit integer NOT NULL DEFAULT 0,
    upperlimit integer NOT NULL DEFAULT 0
) ON COMMIT DROP;
  v_startlimit := 0;
  WHILE (v_startlimit <= v_limit) LOOP
    v_endlimit := (v_startlimit + CASE v_startlimit WHEN 0 THEN 0 ELSE (v_interval - 1) END);
    v_endlimit := CASE WHEN (v_endlimit > v_limit) THEN v_limit ELSE v_endlimit END;
    INSERT INTO tmp_lt_interval (lowerlimit, upperlimit) VALUES (v_startlimit, v_endlimit);
    v_startlimit := (v_endlimit + 1);
  END LOOP;
  INSERT INTO tmp_lt_interval (lowerlimit, upperlimit) VALUES (v_startlimit, 99999999);
  IF (v_type = 'C') THEN
    INSERT INTO tmp_lt_amt (acccode, date, amount, paid, daysold) SELECT acccode, date, debit AS amount, 0 AS paid, ((v_l_date)::date - (date)::date) AS daysold FROM dbo.virtualgl WHERE (((date <= v_l_date) AND (debit > 0)) AND (acccode IN (SELECT code FROM tv_sp_aging_customerwise_tab_acclist AS tab_acclist))) ORDER BY acccode, date, debit;
    INSERT INTO tmp_lt_pmt SELECT acccode, sum(credit) AS amount FROM dbo.virtualgl WHERE (((date <= v_l_date) AND (credit > 0)) AND (acccode IN (SELECT code FROM tv_sp_aging_customerwise_tab_acclist AS tab_acclist))) GROUP BY acccode ORDER BY acccode;
  END IF;
  IF (v_type = 'S') THEN
    INSERT INTO tmp_lt_amt (acccode, date, amount, paid, daysold) SELECT acccode, date, credit AS amount, 0 AS paid, ((v_l_date)::date - (date)::date) AS daysold FROM dbo.virtualgl WHERE (((date <= v_l_date) AND (credit > 0)) AND (acccode IN (SELECT code FROM tv_sp_aging_customerwise_tab_acclist AS tab_acclist))) ORDER BY acccode, date, credit;
    INSERT INTO tmp_lt_pmt SELECT acccode, sum(debit) AS amount FROM dbo.virtualgl WHERE (((date <= v_l_date) AND (debit > 0)) AND (acccode IN (SELECT code FROM tv_sp_aging_customerwise_tab_acclist AS tab_acclist))) GROUP BY acccode ORDER BY acccode;
  END IF;
  OPEN cur_c1 FOR SELECT * FROM tmp_lt_amt AS lt_amt ORDER BY 1, 2, 3;
  FETCH NEXT FROM cur_c1 INTO v_acccode, v_tdate, v_amt, v_paid, v_rowid, v_daysold;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    v_pmt := coalesce((SELECT coalesce(amount, 0) FROM tmp_lt_pmt AS lt_pmt WHERE (acccode = v_acccode)), 0);
    IF (v_pmt <> 0) THEN
      UPDATE tmp_lt_amt AS lt_amt SET paid = (paid + CASE WHEN (v_amt >= v_pmt) THEN v_pmt ELSE v_amt END) WHERE (rowid = v_rowid);
      v_pmt := (v_pmt - (SELECT CASE WHEN (v_amt >= v_pmt) THEN v_pmt ELSE v_amt END));
      UPDATE tmp_lt_pmt AS lt_pmt SET amount = v_pmt WHERE (acccode = v_acccode);
    END IF;
    FETCH NEXT FROM cur_c1 INTO v_acccode, v_tdate, v_amt, v_paid, v_rowid, v_daysold;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_c1;
  -- DEALLOCATE C1
  DELETE FROM tmp_lt_amt AS lt_amt WHERE ((amount - paid) = 0);
  IF (v_type = 'C') THEN
    INSERT INTO dbo.reportdata (code1, name1, name2, name3, name4, name5, value1, code2, code3) SELECT ar.areacode AS code1, ar.name AS name1, ac.aliasname AS name2, ac.name AS name3, left(((ltrim(rtrim(c.address1)) || ' ') || ltrim(rtrim(c.address2))), 60) AS name4, c.phone AS name5, sum((amount - paid)) AS value1, (SELECT max(lowerlimit) FROM tmp_lt_interval AS lt_interval WHERE ((l.daysold >= lowerlimit) AND (l.daysold <= upperlimit))) AS code2, ac.acccode AS code3 FROM tmp_lt_amt AS l, dbo.accounts AS ac, dbo.area AS ar, dbo.customer AS c WHERE (((l.acccode = ac.acccode) AND (ac.acccode = c.custcode)) AND (c.areacode = ar.areacode)) GROUP BY ar.areacode, ar.name, ac.acccode, ac.name, ac.aliasname, c.address1, c.address2, c.phone, l.daysold;
  END IF;
  IF (v_type = 'S') THEN
    INSERT INTO dbo.reportdata (code1, name1, name2, name3, name4, name5, value1, code2, code3) SELECT 0 AS code1, 'All Supplier(s)' AS name1, ac.aliasname AS name2, ac.name AS name3, left(((ltrim(rtrim(s.address1)) || ' ') || ltrim(rtrim(s.address2))), 60) AS name4, s.phone AS name5, sum((amount - paid)) AS value1, (SELECT max(lowerlimit) FROM tmp_lt_interval AS lt_interval WHERE ((l.daysold >= lowerlimit) AND (l.daysold <= upperlimit))) AS code2, ac.acccode AS code3 FROM tmp_lt_amt AS l, dbo.accounts AS ac, dbo.supplier AS s WHERE ((l.acccode = ac.acccode) AND (ac.acccode = s.suppcode)) GROUP BY ac.acccode, ac.name, ac.aliasname, s.address1, s.address2, s.phone, l.daysold;
  END IF;
  DROP TABLE IF EXISTS tmp_lt_amt;
  DROP TABLE IF EXISTS tmp_lt_pmt;
  DROP TABLE IF EXISTS tmp_lt_interval;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_Aging_Per_Invoice ====
CREATE OR REPLACE FUNCTION dbo.sp_aging_per_invoice(saleinvcode integer, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_saleinvcode integer;
  v_documentcode citext;
  v_type citext;
  v_acccode integer;
  v_l_date timestamp(3);
  v_interval integer;
  v_limit integer;
  v_oldacccode integer;
  v_tdate timestamp(3);
  v_amt numeric(15,5);
  v_paid numeric(15,5);
  v_rowid integer;
  v_pmt numeric(15,5);
  v_daysold integer;
  v_startlimit integer;
  v_endlimit integer;
  cur_c1 refcursor;
  _fs integer := -1;
BEGIN
  v_saleinvcode := saleinvcode;
  v_type := 'C';
  v_l_date := (SELECT max(date) FROM dbo.saleledger WHERE (saleinvcode = v_saleinvcode));
  v_interval := 30;
  v_limit := 180;
  v_acccode := (SELECT max(custcode) FROM dbo.saleledger WHERE (saleinvcode = v_saleinvcode));
  PERFORM dbo.sp_virtualgl(ac_type => 'A');
  DELETE FROM dbo.reportdata;
  DROP TABLE IF EXISTS tmp_lt_amt;
  CREATE TEMP TABLE tmp_lt_amt (
    acccode integer NOT NULL,
    documentcode citext,
    date timestamp(3) NOT NULL,
    amount numeric(15,5) NOT NULL DEFAULT 0,
    paid numeric(15,5) NOT NULL DEFAULT 0,
    rowid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    daysold integer NOT NULL DEFAULT 0
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_lt_pmt;
  CREATE TEMP TABLE tmp_lt_pmt (
    acccode integer NOT NULL,
    amount numeric(15,5) NOT NULL DEFAULT 0
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_lt_interval;
  CREATE TEMP TABLE tmp_lt_interval (
    intervalid integer GENERATED BY DEFAULT AS IDENTITY (START WITH 0 INCREMENT BY 1 MINVALUE 0) NOT NULL,
    lowerlimit integer NOT NULL DEFAULT 0,
    upperlimit integer NOT NULL DEFAULT 0
) ON COMMIT DROP;
  v_startlimit := 0;
  WHILE (v_startlimit <= v_limit) LOOP
    v_endlimit := (v_startlimit + CASE v_startlimit WHEN 0 THEN 0 ELSE (v_interval - 1) END);
    v_endlimit := CASE WHEN (v_endlimit > v_limit) THEN v_limit ELSE v_endlimit END;
    INSERT INTO tmp_lt_interval (lowerlimit, upperlimit) VALUES (v_startlimit, v_endlimit);
    v_startlimit := (v_endlimit + 1);
  END LOOP;
  INSERT INTO tmp_lt_interval (lowerlimit, upperlimit) VALUES (v_startlimit, 99999999);
  IF (v_type = 'C') THEN
    INSERT INTO tmp_lt_amt (acccode, documentcode, date, amount, paid, daysold) SELECT acccode, ((documenttype || '-') || ltrim(rtrim(dbo.tsql_str((documentcode)::numeric, 10)))) AS documentcode, date, debit AS amount, 0 AS paid, ((v_l_date)::date - (date)::date) AS daysold FROM dbo.virtualgl WHERE (((date <= v_l_date) AND (debit > 0)) AND (acccode = v_acccode)) ORDER BY acccode, date, debit;
    INSERT INTO tmp_lt_pmt SELECT acccode, sum(credit) AS amount FROM dbo.virtualgl WHERE (((date <= v_l_date) AND (credit > 0)) AND (acccode = v_acccode)) GROUP BY acccode ORDER BY acccode;
  END IF;
  IF (v_type = 'S') THEN
    INSERT INTO tmp_lt_amt (acccode, documentcode, date, amount, paid, daysold) SELECT acccode, ((documenttype || '-') || ltrim(rtrim(dbo.tsql_str((documentcode)::numeric, 10)))) AS documentcode, date, credit AS amount, 0 AS paid, ((v_l_date)::date - (date)::date) AS daysold FROM dbo.virtualgl WHERE (((date <= v_l_date) AND (credit > 0)) AND (acccode = v_acccode)) ORDER BY acccode, date, credit;
    INSERT INTO tmp_lt_pmt SELECT acccode, sum(debit) AS amount FROM dbo.virtualgl WHERE (((date <= v_l_date) AND (debit > 0)) AND (acccode = v_acccode)) GROUP BY acccode ORDER BY acccode;
  END IF;
  OPEN cur_c1 FOR SELECT * FROM tmp_lt_amt AS lt_amt ORDER BY 1, 3, 4;
  FETCH NEXT FROM cur_c1 INTO v_acccode, v_documentcode, v_tdate, v_amt, v_paid, v_rowid, v_daysold;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    v_pmt := coalesce((SELECT coalesce(amount, 0) FROM tmp_lt_pmt AS lt_pmt WHERE (acccode = v_acccode)), 0);
    IF (v_pmt <> 0) THEN
      UPDATE tmp_lt_amt AS lt_amt SET paid = (paid + CASE WHEN (v_amt >= v_pmt) THEN v_pmt ELSE v_amt END) WHERE (rowid = v_rowid);
      v_pmt := (v_pmt - (SELECT CASE WHEN (v_amt >= v_pmt) THEN v_pmt ELSE v_amt END));
      UPDATE tmp_lt_pmt AS lt_pmt SET amount = v_pmt WHERE (acccode = v_acccode);
    END IF;
    FETCH NEXT FROM cur_c1 INTO v_acccode, v_documentcode, v_tdate, v_amt, v_paid, v_rowid, v_daysold;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_c1;
  -- DEALLOCATE C1
  DELETE FROM tmp_lt_amt AS lt_amt WHERE ((amount - paid) = 0);
  IF (v_type = 'C') THEN
    INSERT INTO dbo.reportdata (code1, name1, name2, name3, name4, name5, name6, date1, value1, value2, value3, code2, code3) SELECT ar.areacode AS code1, ar.name AS name1, ac.aliasname AS name2, ac.name AS name3, left(((ltrim(rtrim(c.address1)) || ' ') || ltrim(rtrim(c.address2))), 60) AS name4, c.phone AS name5, l.documentcode AS name6, l.date AS date1, sum((amount - paid)) AS value1, sum(amount) AS value2, sum(paid) AS value3, (SELECT max(lowerlimit) FROM tmp_lt_interval AS lt_interval WHERE ((l.daysold >= lowerlimit) AND (l.daysold <= upperlimit))) AS code2, l.daysold AS code3 FROM tmp_lt_amt AS l, dbo.accounts AS ac, dbo.area AS ar, dbo.customer AS c WHERE (((l.acccode = ac.acccode) AND (ac.acccode = c.custcode)) AND (c.areacode = ar.areacode)) GROUP BY ar.areacode, ar.name, ac.acccode, ac.name, ac.aliasname, c.address1, c.address2, c.phone, l.date, l.documentcode, l.daysold;
  END IF;
  IF (v_type = 'S') THEN
    INSERT INTO dbo.reportdata (code1, name1, name2, name3, name4, name5, name6, date1, value1, value2, value3, code2, code3) SELECT 0 AS code1, 'All Supplier(s)' AS name1, ac.aliasname AS name2, ac.name AS name3, left(((ltrim(rtrim(s.address1)) || ' ') || ltrim(rtrim(s.address2))), 60) AS name4, s.phone AS name5, l.documentcode AS name6, l.date AS date1, sum((amount - paid)) AS value1, sum(amount) AS value2, sum(paid) AS value3, (SELECT max(lowerlimit) FROM tmp_lt_interval AS lt_interval WHERE ((l.daysold >= lowerlimit) AND (l.daysold <= upperlimit))) AS code2, l.daysold AS code3 FROM tmp_lt_amt AS l, dbo.accounts AS ac, dbo.supplier AS s WHERE ((l.acccode = ac.acccode) AND (ac.acccode = s.suppcode)) GROUP BY ac.acccode, ac.name, ac.aliasname, s.address1, s.address2, s.phone, l.date, l.documentcode, l.daysold;
  END IF;
  DROP TABLE IF EXISTS tmp_lt_amt;
  DROP TABLE IF EXISTS tmp_lt_pmt;
  DROP TABLE IF EXISTS tmp_lt_interval;
  OPEN rs1 FOR SELECT reportdata.code1, reportdata.value1, reportdata.value2, reportdata.value3, reportdata.name1, reportdata.name2, reportdata.name3, reportdata.name4, reportdata.name5, reportdata.name6, reportdata.date1, reportdata.code2, reportdata.code3 FROM dbo.reportdata ORDER BY name1, code1, name3, name2, code2, date1, value1;
  return_value := 0;
  RETURN;
END
$body$;

