    v_pmt := coalesce((SELECT coalesce(amount, 0) FROM tmp_lt_pmt AS lt_pmt WHERE (acccode = v_acccode)), 0);
    IF (v_pmt <> 0) THEN
      UPDATE tmp_lt_amt AS lt_amt SET paid = (paid + CASE WHEN (v_amt >= v_pmt) THEN v_pmt ELSE v_amt END) WHERE (rowid = v_rowid);
      v_pmt := (v_pmt - (SELECT CASE WHEN (v_amt >= v_pmt) THEN v_pmt ELSE v_amt END));
      UPDATE tmp_lt_pmt AS lt_pmt SET amount = v_pmt WHERE (acccode = v_acccode);
    END IF;
    FETCH NEXT FROM cur_c1 INTO v_acccode, v_tdate, v_amt, v_paid, v_rowid, v_daysold;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_c1;
  -- DEALLOCATE C1
  DELETE FROM tmp_lt_amt AS lt_amt WHERE ((amount - paid) = 0);
  INSERT INTO dbo.reportdata (code1, name1, name2, name3, name4, name5, value1, code2) SELECT c.salesmancode AS code1, (SELECT sm.name FROM dbo.salesman AS sm WHERE (sm.salesmancode = c.salesmancode)) AS name1, ac.aliasname AS name2, ac.name AS name3, left(((ltrim(rtrim(c.address1)) || ' ') || ltrim(rtrim(c.address2))), 60) AS name4, c.phone AS name5, sum((amount - paid)) AS value1, (SELECT max(lowerlimit) FROM tmp_lt_interval AS lt_interval WHERE ((l.daysold >= lowerlimit) AND (l.daysold <= upperlimit))) AS code2 FROM tmp_lt_amt AS l, dbo.accounts AS ac, dbo.customer AS c WHERE ((l.acccode = ac.acccode) AND (ac.acccode = c.custcode)) GROUP BY c.salesmancode, ac.acccode, ac.name, ac.aliasname, c.address1, c.address2, c.phone, l.daysold;
  DROP TABLE IF EXISTS tmp_lt_amt;
  DROP TABLE IF EXISTS tmp_lt_pmt;
  DROP TABLE IF EXISTS tmp_lt_interval;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_Aging_SubAreaWise ====
CREATE OR REPLACE FUNCTION dbo.sp_aging_subareawise(l_date timestamp, "interval" integer, "limit" integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
