  DELETE FROM tmp_lt_amt AS lt_amt WHERE ((amount - paid) = 0);
  INSERT INTO dbo.reportdata (code1, name1, name2, name3, name4, name5, value1, code2) SELECT c.subareacode AS code1, (SELECT sa.name FROM dbo.subarea AS sa WHERE (sa.subareacode = c.subareacode)) AS name1, ac.aliasname AS name2, ac.name AS name3, left(((ltrim(rtrim(c.address1)) || ' ') || ltrim(rtrim(c.address2))), 60) AS name4, c.phone AS name5, sum((amount - paid)) AS value1, (SELECT max(lowerlimit) FROM tmp_lt_interval AS lt_interval WHERE ((l.daysold >= lowerlimit) AND (l.daysold <= upperlimit))) AS code2 FROM tmp_lt_amt AS l, dbo.accounts AS ac, dbo.customer AS c WHERE ((l.acccode = ac.acccode) AND (ac.acccode = c.custcode)) GROUP BY c.subareacode, ac.acccode, ac.name, ac.aliasname, c.address1, c.address2, c.phone, l.daysold;
  DROP TABLE IF EXISTS tmp_lt_amt;
  DROP TABLE IF EXISTS tmp_lt_pmt;
  DROP TABLE IF EXISTS tmp_lt_interval;
