$body$;

-- ==== proc sp_AgingBasedEPI ====
CREATE OR REPLACE FUNCTION dbo.sp_agingbasedepi(areacode integer, agedate timestamp, agelimit integer, collectionsdate timestamp, collectionedate timestamp, vochcatlist citext, epiperc numeric, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_areacode integer;
  v_agedate timestamp(3);
  v_agelimit integer;
  v_collectionsdate timestamp(3);
  v_collectionedate timestamp(3);
  v_vochcatlist citext;
  v_epiperc numeric(10,2);
  v_oldacccode integer;
  v_acccode integer;
  v_tdate timestamp(3);
  v_amt numeric(15,5);
  v_paid numeric(15,5);
  v_rowid integer;
  v_pmt numeric(15,5);
  v_daysold integer;
  v_startlimit integer;
  v_endlimit integer;
  cur_c1 refcursor;
  _fs integer := -1;
BEGIN
  v_areacode := areacode;
  v_agedate := agedate;
  v_agelimit := agelimit;
  v_collectionsdate := collectionsdate;
  v_collectionedate := collectionedate;
  v_vochcatlist := vochcatlist;
  v_epiperc := epiperc;
  DROP TABLE IF EXISTS tv_sp_agingbasedepi_tab_vouchcatlist;
  CREATE TEMP TABLE tv_sp_agingbasedepi_tab_vouchcatlist (
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tv_sp_agingbasedepi_tab_vouchcatlist SELECT code FROM dbo.udf_stringtotabl(v_vochcatlist, ',') AS udf_stringtotabl;
  DELETE FROM dbo.reportdata;
  DROP TABLE IF EXISTS tmp_lt_amt;
  CREATE TEMP TABLE tmp_lt_amt (
    acccode integer NOT NULL,
    date timestamp(3) NOT NULL,
    amount numeric(15,5) NOT NULL DEFAULT 0,
    paid numeric(15,5) NOT NULL DEFAULT 0,
    rowid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    daysold integer NOT NULL DEFAULT 0
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_lt_pmt;
  CREATE TEMP TABLE tmp_lt_pmt (
    acccode integer NOT NULL,
    amount numeric(15,5) NOT NULL DEFAULT 0
) ON COMMIT DROP;
  INSERT INTO tmp_lt_amt (acccode, date, amount, paid, daysold) SELECT acccode, date, debit AS amount, 0 AS paid, ((v_agedate)::date - (date)::date) AS daysold FROM dbo.virtualgl WHERE (((date <= v_agedate) AND (debit > 0)) AND (acccode IN (SELECT custcode FROM dbo.customer WHERE (areacode = v_areacode)))) ORDER BY acccode, date, debit;
  INSERT INTO tmp_lt_pmt SELECT acccode, sum(credit) AS amount FROM dbo.virtualgl WHERE (((date <= v_agedate) AND (credit > 0)) AND (acccode IN (SELECT custcode FROM dbo.customer WHERE (areacode = v_areacode)))) GROUP BY acccode ORDER BY acccode;
  OPEN cur_c1 FOR SELECT * FROM tmp_lt_amt AS lt_amt;
  FETCH NEXT FROM cur_c1 INTO v_acccode, v_tdate, v_amt, v_paid, v_rowid, v_daysold;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    v_pmt := coalesce((SELECT coalesce(amount, 0) FROM tmp_lt_pmt AS lt_pmt WHERE (acccode = v_acccode)), 0);
    IF (v_pmt <> 0) THEN
      UPDATE tmp_lt_amt AS lt_amt SET paid = (paid + CASE WHEN (v_amt >= v_pmt) THEN v_pmt ELSE v_amt END) WHERE (rowid = v_rowid);
      v_pmt := (v_pmt - (SELECT CASE WHEN (v_amt >= v_pmt) THEN v_pmt ELSE v_amt END));
      UPDATE tmp_lt_pmt AS lt_pmt SET amount = v_pmt WHERE (acccode = v_acccode);
    END IF;
    FETCH NEXT FROM cur_c1 INTO v_acccode, v_tdate, v_amt, v_paid, v_rowid, v_daysold;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_c1;
  -- DEALLOCATE C1
  DELETE FROM tmp_lt_amt AS lt_amt WHERE ((amount - paid) = 0);
  INSERT INTO dbo.reportdata (code1, name1, name2, name3, name4, name5, value1, value2, value3, value4) SELECT ar.areacode AS code1, ar.name AS name1, ac.aliasname AS name2, ac.name AS name3, left(((ltrim(rtrim(c.address1)) || ' ') || ltrim(rtrim(c.address2))), 60) AS name4, c.phone AS name5, agb.balance AS value1, agb.totbalance AS value2, agb.collection AS value3, round((((agb.collection * v_epiperc) * 0.01))::numeric, 2) AS value4 FROM dbo.accounts AS ac, dbo.area AS ar, dbo.customer AS c, (SELECT t.acccode, coalesce(sum(CASE WHEN (t.daysold <= v_agelimit) THEN (t.amount - t.paid) ELSE 0 END), 0) AS balance, coalesce(sum((t.amount - t.paid)), 0) AS totbalance, coalesce((SELECT coalesce(sum(gd.credit), 0) AS collection FROM dbo.gldetail AS gd, dbo.glheader AS gh WHERE ((((gh.date BETWEEN v_collectionsdate AND v_collectionedate) AND (gh.vochcatcode IN (SELECT code FROM tv_sp_agingbasedepi_tab_vouchcatlist AS tab_vouchcatlist))) AND (gh.glvochcode = gd.glvochcode)) AND (gd.acccode = t.acccode))), 0) AS collection FROM tmp_lt_amt AS t GROUP BY t.acccode) AS agb WHERE ((((((((ac.acccode = c.custcode) AND (c.areacode = ar.areacode)) AND (ar.areacode = v_areacode)) AND (ac.acccode = agb.acccode)) AND (agb.balance = agb.totbalance)) AND (agb.balance <> 0)) AND (agb.totbalance <> 0)) AND (agb.collection <> 0));
  DROP TABLE IF EXISTS tmp_lt_amt;
  DROP TABLE IF EXISTS tmp_lt_pmt;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_AgingDetail ====
CREATE OR REPLACE FUNCTION dbo.sp_agingdetail(type citext, l_date timestamp, "interval" integer, "limit" integer, code integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_type citext;
  v_l_date timestamp(3);
  v_interval integer;
  v_limit integer;
  v_code integer;
  v_doccode citext;
  v_remarks citext;
  v_oldacccode integer;
  v_acccode integer;
  v_rowid integer;
  v_daysold integer;
  v_startlimit integer;
  v_endlimit integer;
  v_collectionid integer;
  v_tdate timestamp(3);
  v_lastpaymentdate timestamp(3);
  v_amt numeric(15,5);
  v_paid numeric(15,5);
  v_pmt numeric(15,5);
  cur_c_pay refcursor;
  cur_c_topay refcursor;
  _fs integer := -1;
BEGIN
  v_type := type;
  v_l_date := l_date;
  v_interval := "interval";
  v_limit := "limit";
  v_code := code;
  DELETE FROM dbo.reportdata;
  DROP TABLE IF EXISTS tmp_lt_amt;
  CREATE TEMP TABLE tmp_lt_amt (
    doccode citext NOT NULL,
    acccode integer NOT NULL,
    date timestamp(3) NOT NULL,
    amount numeric(15,5) NOT NULL DEFAULT 0,
    paid numeric(15,5) NOT NULL DEFAULT 0,
    rowid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    daysold integer NOT NULL DEFAULT 0,
    remarks citext NULL,
    lastpaymentdate timestamp(3) NULL
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_lt_pmt;
  CREATE TEMP TABLE tmp_lt_pmt (
    acccode integer NOT NULL,
    date timestamp(3) NOT NULL,
    collectionid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    amount numeric(15,5) NOT NULL DEFAULT 0
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_lt_interval;
  CREATE TEMP TABLE tmp_lt_interval (
    intervalid integer GENERATED BY DEFAULT AS IDENTITY (START WITH 0 INCREMENT BY 1 MINVALUE 0) NOT NULL,
    lowerlimit integer NOT NULL DEFAULT 0,
    upperlimit integer NOT NULL DEFAULT 0
) ON COMMIT DROP;
  v_startlimit := 0;
  WHILE (v_startlimit <= v_limit) LOOP
    v_endlimit := (v_startlimit + CASE v_startlimit WHEN 0 THEN 0 ELSE (v_interval - 1) END);
    v_endlimit := CASE WHEN (v_endlimit > v_limit) THEN v_limit ELSE v_endlimit END;
    INSERT INTO tmp_lt_interval (lowerlimit, upperlimit) VALUES (v_startlimit, v_endlimit);
    v_startlimit := (v_endlimit + 1);
  END LOOP;
  INSERT INTO tmp_lt_interval (lowerlimit, upperlimit) VALUES (v_startlimit, 99999999);
  IF (v_type = 'C') THEN
    INSERT INTO tmp_lt_amt (doccode, acccode, date, amount, paid, daysold, remarks, lastpaymentdate) SELECT ((rtrim(ltrim(documenttype)) || '-') || rtrim(ltrim((documentcode)::text))) AS doccode, acccode, date, debit AS amount, 0 AS paid, ((v_l_date)::date - (date)::date) AS daysold, remarks, NULL::timestamp(3) AS lastpaymentdate FROM dbo.virtualgl WHERE (((date <= v_l_date) AND (debit > 0)) AND (acccode = v_code)) ORDER BY acccode, date, daysold DESC, debit;
    INSERT INTO tmp_lt_pmt (acccode, date, amount) SELECT acccode, date, credit AS amount FROM dbo.virtualgl WHERE (((date <= v_l_date) AND (credit > 0)) AND (acccode = v_code)) ORDER BY acccode, date;
  END IF;
  IF (v_type = 'S') THEN
    INSERT INTO tmp_lt_amt (doccode, acccode, date, amount, paid, daysold, remarks, lastpaymentdate) SELECT ((rtrim(ltrim(documenttype)) || '-') || rtrim(ltrim((documentcode)::text))) AS doccode, acccode, date, credit AS amount, 0 AS paid, ((v_l_date)::date - (date)::date) AS daysold, remarks, NULL::timestamp(3) AS lastpaymentdate FROM dbo.virtualgl WHERE (((date <= v_l_date) AND (credit > 0)) AND (acccode = v_code)) ORDER BY acccode, date, daysold DESC, credit;
    INSERT INTO tmp_lt_pmt (acccode, date, amount) SELECT acccode, date, debit AS amount FROM dbo.virtualgl WHERE (((date <= v_l_date) AND (debit > 0)) AND (acccode = v_code)) ORDER BY acccode, date;
  END IF;
  OPEN cur_c_pay FOR SELECT collectionid, amount FROM tmp_lt_pmt AS lt_pmt;
  FETCH NEXT FROM cur_c_pay INTO v_collectionid, v_pmt;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    OPEN cur_c_topay FOR SELECT * FROM tmp_lt_amt AS lt_amt WHERE ((amount - paid) <> 0);
    FETCH NEXT FROM cur_c_topay INTO v_doccode, v_acccode, v_tdate, v_amt, v_paid, v_rowid, v_daysold, v_remarks, v_lastpaymentdate;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    WHILE (_fs = 0) LOOP
      v_pmt := coalesce((SELECT coalesce(amount, 0) FROM tmp_lt_pmt AS lt_pmt WHERE (collectionid = v_collectionid)), 0);
      v_lastpaymentdate := (SELECT date FROM tmp_lt_pmt AS lt_pmt WHERE (collectionid = v_collectionid));
      IF (v_pmt <> 0) THEN
        UPDATE tmp_lt_amt AS lt_amt SET paid = (paid + CASE WHEN (((v_amt - v_paid)) >= v_pmt) THEN v_pmt ELSE (v_amt - v_paid) END) WHERE (rowid = v_rowid);
        v_pmt := (v_pmt - (SELECT CASE WHEN (((v_amt - v_paid)) >= v_pmt) THEN v_pmt ELSE (v_amt - v_paid) END));
        UPDATE tmp_lt_pmt AS lt_pmt SET amount = v_pmt WHERE ((acccode = v_acccode) AND (collectionid = v_collectionid));
        UPDATE tmp_lt_amt AS lt_amt SET lastpaymentdate = v_lastpaymentdate WHERE ((rowid = v_rowid) AND (paid > 0));
        UPDATE tmp_lt_amt AS lt_amt SET daysold = ((v_lastpaymentdate)::date - (date)::date) WHERE ((rowid = v_rowid) AND ((amount - paid) = 0));
        IF (v_pmt = 0) THEN
          EXIT;
        END IF;
      ELSE
        EXIT;
      END IF;
      FETCH NEXT FROM cur_c_topay INTO v_doccode, v_acccode, v_tdate, v_amt, v_paid, v_rowid, v_daysold, v_remarks, v_lastpaymentdate;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    END LOOP;
    CLOSE cur_c_topay;
    -- DEALLOCATE c_topay
    FETCH NEXT FROM cur_c_pay INTO v_collectionid, v_pmt;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_c_pay;
  -- DEALLOCATE c_pay
  IF (v_type = 'C') THEN
    INSERT INTO dbo.reportdata (name1, name2, name3, date1, value1, value2, value3, code2, code3, name4, name5, name6, date2) SELECT ac.aliasname AS name1, ac.name AS name2, l.doccode AS name3, l.date AS date1, amount AS value1, paid AS value2, (amount - paid) AS value3, l.daysold AS code2, (SELECT max(lowerlimit) FROM tmp_lt_interval AS lt_interval WHERE ((l.daysold >= lowerlimit) AND (l.daysold <= upperlimit))) AS code3, l.remarks AS name4, left(((ltrim(rtrim(c.address1)) || ' ') || ltrim(rtrim(c.address2))), 60) AS name5, c.phone AS name6, l.lastpaymentdate AS date2 FROM tmp_lt_amt AS l, dbo.accounts AS ac, dbo.area AS ar, dbo.customer AS c WHERE (((l.acccode = ac.acccode) AND (ac.acccode = c.custcode)) AND (c.areacode = ar.areacode));
  END IF;
  IF (v_type = 'S') THEN
    INSERT INTO dbo.reportdata (name1, name2, name3, date1, value1, value2, value3, code2, code3, name4, name5, name6, date2) SELECT '' AS name1, ac.name AS name2, l.doccode AS name3, l.date AS date, amount AS value1, paid AS value2, (amount - paid) AS value3, l.daysold AS code2, (SELECT max(lowerlimit) FROM tmp_lt_interval AS lt_interval WHERE ((l.daysold >= lowerlimit) AND (l.daysold <= upperlimit))) AS code3, l.remarks AS name4, left(((ltrim(rtrim(s.address1)) || ' ') || ltrim(rtrim(s.address2))), 60) AS name5, s.phone AS name6, l.lastpaymentdate AS date2 FROM tmp_lt_amt AS l, dbo.accounts AS ac, dbo.supplier AS s WHERE ((l.acccode = ac.acccode) AND (ac.acccode = s.suppcode));
  END IF;
  DROP TABLE IF EXISTS tmp_lt_amt;
  DROP TABLE IF EXISTS tmp_lt_pmt;
  DROP TABLE IF EXISTS tmp_lt_interval;
  return_value := 0;
  RETURN;
END
$body$;

