  FETCH NEXT FROM cur_c_pay INTO v_acccode, v_collectionid, v_pmt;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    OPEN cur_c_topay FOR SELECT * FROM tmp_lt_amt AS lt_amt WHERE ((acccode = v_acccode) AND ((amount - paid) <> 0));
    FETCH NEXT FROM cur_c_topay INTO v_doccode, v_acccode2, v_tdate, v_amt, v_paid, v_rowid, v_daysold, v_remarks, v_lastpaymentdate;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    WHILE (_fs = 0) LOOP
      v_pmt := coalesce((SELECT coalesce(amount, 0) FROM tmp_lt_pmt AS lt_pmt WHERE ((acccode = v_acccode) AND (collectionid = v_collectionid))), 0);
      v_lastpaymentdate := (SELECT date FROM tmp_lt_pmt AS lt_pmt WHERE ((acccode = v_acccode) AND (collectionid = v_collectionid)));
      IF (v_pmt <> 0) THEN
        UPDATE tmp_lt_amt AS lt_amt SET paid = (paid + CASE WHEN (((v_amt - v_paid)) >= v_pmt) THEN v_pmt ELSE (v_amt - v_paid) END) WHERE (rowid = v_rowid);
        v_pmt := (v_pmt - (SELECT CASE WHEN (((v_amt - v_paid)) >= v_pmt) THEN v_pmt ELSE (v_amt - v_paid) END));
        UPDATE tmp_lt_pmt AS lt_pmt SET amount = v_pmt WHERE ((acccode = v_acccode) AND (collectionid = v_collectionid));
        UPDATE tmp_lt_amt AS lt_amt SET lastpaymentdate = v_lastpaymentdate WHERE ((rowid = v_rowid) AND (paid > 0));
        UPDATE tmp_lt_amt AS lt_amt SET daysold = ((v_lastpaymentdate)::date - (date)::date) WHERE ((rowid = v_rowid) AND ((amount - paid) = 0));
        IF (v_pmt = 0) THEN
          EXIT;
        END IF;
      ELSE
        EXIT;
      END IF;
      FETCH NEXT FROM cur_c_topay INTO v_doccode, v_acccode2, v_tdate, v_amt, v_paid, v_rowid, v_daysold, v_remarks, v_lastpaymentdate;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    END LOOP;
    CLOSE cur_c_topay;
    -- DEALLOCATE c_topay
    FETCH NEXT FROM cur_c_pay INTO v_acccode, v_collectionid, v_pmt;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_c_pay;
  -- DEALLOCATE c_pay
  INSERT INTO dbo.reportdata (name1, name2, name3, date1, value1, value2, value3, code2, code3, name4, name5, name6, date2, name7) SELECT ac.aliasname AS name1, ac.name AS name2, l.doccode AS name3, l.date AS date1, amount AS value1, paid AS value2, (amount - paid) AS value3, l.daysold AS code2, (SELECT max(lowerlimit) FROM tmp_lt_interval AS lt_interval WHERE ((l.daysold >= lowerlimit) AND (l.daysold <= upperlimit))) AS code3, l.remarks AS name4, left(((ltrim(rtrim(c.address1)) || ' ') || ltrim(rtrim(c.address2))), 60) AS name5, c.phone AS name6, l.lastpaymentdate AS date2, (SELECT sm.name FROM dbo.salesman AS sm WHERE (sm.salesmancode = c.salesmancode)) AS name7 FROM tmp_lt_amt AS l, dbo.accounts AS ac, dbo.area AS ar, dbo.customer AS c WHERE (((l.acccode = ac.acccode) AND (ac.acccode = c.custcode)) AND (c.areacode = ar.areacode));
  DROP TABLE IF EXISTS tmp_lt_amt;
  DROP TABLE IF EXISTS tmp_lt_pmt;
  DROP TABLE IF EXISTS tmp_lt_interval;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_AllocateSaleReturn ====
CREATE OR REPLACE FUNCTION dbo.sp_allocatesalereturn(srinvcode integer, saleinvcode integer, usercode smallint, INOUT srallocationcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srinvcode integer;
  v_saleinvcode integer;
  v_usercode smallint;
  v_srallocationcode integer;
  v_retcode integer;
  v_code integer;
  v_unpostedtrans integer;
  v_null integer;
  v_err integer;
  v_sale_balance numeric(15,2);
  v_sr_balance numeric(15,2);
  v_amt numeric(15,2);
  v_new_sale_balance numeric(15,2);
  v_new_sr_balance numeric(15,2);
  v_posted citext;
  v_msg citext;
  v_title citext;
  v_date timestamp(3);
BEGIN
  v_srinvcode := srinvcode;
  v_saleinvcode := saleinvcode;
  v_usercode := usercode;
  v_srallocationcode := srallocationcode;
  v_null := NULL;
  v_retcode := 0;
  v_date := localtimestamp(3);
  v_retcode := -1;
  v_posted := 'Y';
  SELECT r.return_value INTO v_retcode FROM dbo.sp_checkunpostedsaleinvintransactions(invcode => v_saleinvcode, code => v_srinvcode, callermodule => 'SR', rowscount => v_unpostedtrans, msg => v_msg) AS r;
  IF ((0 <> 0) OR (v_retcode <> 0)) THEN
    RAISE EXCEPTION 'Error occured while checking unposted transaction for sale invoice : %', v_saleinvcode;
    return_value := -1;
    srallocationcode := v_srallocationcode;
    RETURN;
  END IF;
  IF (v_unpostedtrans <= 0) THEN
    RAISE EXCEPTION '%', v_msg;
    return_value := -1;
    srallocationcode := v_srallocationcode;
    RETURN;
  END IF;
  SELECT r.return_value, r.an_balance INTO v_retcode, v_sr_balance FROM dbo.sp_getsrinvbalance(ai_srinvcode => v_srinvcode, an_balance => v_sr_balance) AS r;
  IF ((0 <> 0) OR (v_retcode <> 0)) THEN
    RAISE EXCEPTION 'Error occured while fetching balance for sale return invoice : %', v_srinvcode;
    return_value := -1;
    srallocationcode := v_srallocationcode;
    RETURN;
  END IF;
  v_sr_balance := coalesce(v_sr_balance, 0);
  IF (v_sr_balance < 0) THEN
    RAISE EXCEPTION 'There exists no balance for sale return invoice : %', v_srinvcode;
    return_value := -1;
    srallocationcode := v_srallocationcode;
    RETURN;
  END IF;
  IF (v_sr_balance = 0) THEN
    return_value := 0;
    srallocationcode := v_srallocationcode;
    RETURN;
  END IF;
  SELECT r.return_value, r.an_balance INTO v_retcode, v_sale_balance FROM dbo.sp_getsaleinvbalance(ai_saleinvcode => v_saleinvcode, an_balance => v_sale_balance) AS r;
  IF ((0 <> 0) OR (v_retcode <> 0)) THEN
    RAISE EXCEPTION 'Error occured while fetching balance for sale invoice : %', v_saleinvcode;
    return_value := -1;
    srallocationcode := v_srallocationcode;
    RETURN;
  END IF;
  v_sale_balance := coalesce(v_sale_balance, 0);
  IF (v_sale_balance < 0) THEN
    RAISE EXCEPTION 'There exists no balance for sale invoice : %', v_saleinvcode;
    return_value := -1;
    srallocationcode := v_srallocationcode;
    RETURN;
  END IF;
  IF (v_sale_balance = 0) THEN
    return_value := 0;
    srallocationcode := v_srallocationcode;
    RETURN;
  END IF;
  IF (v_sale_balance <= v_sr_balance) THEN
    v_amt := coalesce(v_sale_balance, 0);
  ELSE
    v_amt := coalesce(v_sr_balance, 0);
  END IF;
  v_amt := coalesce(v_amt, 0);
  v_new_sale_balance := (coalesce(v_sale_balance, 0) - coalesce(v_amt, 0));
  v_new_sr_balance := (coalesce(v_sr_balance, 0) - coalesce(v_amt, 0));
  SELECT r.return_value, r.an_amt INTO v_retcode, v_new_sr_balance FROM dbo.sp_updatesrinvbalance(ai_srinvcode => v_srinvcode, an_amt => v_new_sr_balance) AS r;
  IF ((0 <> 0) OR (v_retcode <> 0)) THEN
    RAISE EXCEPTION 'Error occured while updating balance for sale return invoice : %', v_srinvcode;
    return_value := -1;
    srallocationcode := v_srallocationcode;
    RETURN;
  END IF;
  SELECT r.return_value, r.an_amt INTO v_retcode, v_new_sale_balance FROM dbo.sp_updatesaleinvbalance(ai_saleinvcode => v_saleinvcode, an_amt => v_new_sale_balance) AS r;
  IF ((0 <> 0) OR (v_retcode <> 0)) THEN
    RAISE EXCEPTION 'Error occured while updating balance for sale invoice : %', v_saleinvcode;
    return_value := -1;
    srallocationcode := v_srallocationcode;
    RETURN;
  END IF;
  SELECT r.return_value, r.ai_srallocationcode INTO v_retcode, v_code FROM dbo.sp_createsrallocation(ai_srinvcode => v_srinvcode, ai_saleinvcode => v_saleinvcode, ad_date => v_date, ai_usercode => (v_usercode)::integer, ac_posted => v_posted, ad_postdate => v_date, an_outstandingamt => v_sale_balance, an_amt => v_amt, ai_srallocationcode => v_code) AS r;
  IF ((0 <> 0) OR (v_retcode <> 0)) THEN
    RAISE EXCEPTION 'Error occured while Creating Sale Return Allocation for sale invoice : %', v_saleinvcode;
    return_value := -1;
    srallocationcode := v_srallocationcode;
    RETURN;
  END IF;
  IF (v_code > 0) THEN
    v_srallocationcode := v_code;
  END IF;
  return_value := 0;
  srallocationcode := v_srallocationcode;
  RETURN;
  return_value := 0;
  srallocationcode := v_srallocationcode;
  RETURN;
END
$body$;

