  SELECT r.return_value, r.an_balance INTO v_retcode, v_service_balance FROM dbo.sp_getserviceinvbalance(ai_invcode => v_serviceinvcode, an_balance => v_service_balance) AS r;
  IF ((0 <> 0) OR (v_retcode <> 0)) THEN
