  END IF;
  v_service_balance := coalesce(v_service_balance, 0);
  IF (v_service_balance < 0) THEN
    RAISE EXCEPTION 'There exists no balance for service invoice : %', v_serviceinvcode;
    return_value := -1;
    srallocationcode := v_srallocationcode;
    RETURN;
  END IF;
  IF (v_service_balance = 0) THEN
    return_value := 0;
    srallocationcode := v_srallocationcode;
    RETURN;
  END IF;
  IF (v_service_balance <= v_sr_balance) THEN
    v_amt := coalesce(v_service_balance, 0);
  ELSE
    v_amt := coalesce(v_sr_balance, 0);
  END IF;
  v_amt := coalesce(v_amt, 0);
  v_new_service_balance := (coalesce(v_service_balance, 0) - coalesce(v_amt, 0));
  v_new_sr_balance := (coalesce(v_sr_balance, 0) - coalesce(v_amt, 0));
  SELECT r.return_value, r.an_amt INTO v_retcode, v_new_sr_balance FROM dbo.sp_updateservicesrinvbalance(ai_invcode => v_servicerinvcode, an_amt => v_new_sr_balance) AS r;
  IF ((0 <> 0) OR (v_retcode <> 0)) THEN
    RAISE EXCEPTION 'Error occured while updating balance for service return invoice : %', v_servicerinvcode;
