  END IF;
  SELECT r.return_value, r.an_amt INTO v_retcode, v_new_service_balance FROM dbo.sp_updateserviceinvbalance(ai_invcode => v_serviceinvcode, an_amt => v_new_service_balance) AS r;
  IF ((0 <> 0) OR (v_retcode <> 0)) THEN
    RAISE EXCEPTION 'Error occured while updating balance for service invoice : %', v_serviceinvcode;
