$body$;

-- ==== proc SP_AlterDB ====
CREATE OR REPLACE FUNCTION dbo.sp_alterdb(db citext, option integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_db citext;
  v_option integer;
  v_alterdb citext;
  _dq1 text;
BEGIN
  v_db := db;
  v_option := option;
  -- SET NOCOUNT ON
  IF (v_db IS NULL) THEN
    return_value := 0;
    RETURN;
  END IF;
  IF (v_option IS NULL) THEN
    return_value := 0;
    RETURN;
  END IF;
  IF (v_option = 1) THEN
    v_alterdb := (('ALTER DATABASE ' || v_db) || ' SET Single_User');
  ELSE
    v_alterdb := (('ALTER DATABASE ' || v_db) || ' SET Multi_User');
  END IF;
  _dq1 := v_alterdb;
  IF _dq1 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq1);
  END IF;
  IF (0 <> 0) THEN
    return_value := 0;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_Apply_SaleAmt_Based_DiscountPolicy ====
CREATE OR REPLACE FUNCTION dbo.sp_apply_saleamt_based_discountpolicy(invamount numeric, INOUT discperc numeric, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_invamount numeric(15,2);
  v_discperc numeric(5,2);
BEGIN
  v_invamount := invamount;
  v_discperc := discperc;
  v_discperc := 0.00;
  IF (v_invamount IS NULL) THEN
    v_invamount := 0.00;
  END IF;
  IF ((dbo.fn_getpreference('ApplySaleInvoiceDiscountPolicyOnSaving'))::citext = 'N') THEN
    return_value := 0;
    discperc := v_discperc;
    RETURN;
  END IF;
  v_discperc := (SELECT d.discperc FROM dbo.salesdiscountpolicy AS d, (SELECT min(salelimit) AS salelimit FROM dbo.salesdiscountpolicy WHERE (salelimit >= v_invamount) UNION SELECT max(salelimit) AS salelimit FROM dbo.salesdiscountpolicy WHERE (salelimit <= v_invamount)) AS t WHERE ((d.salelimit = t.salelimit) AND (t.salelimit <= v_invamount)));
  IF ((v_discperc IS NULL) OR (v_discperc < 0)) THEN
    v_discperc := 0;
  END IF;
  return_value := 0;
  discperc := v_discperc;
  RETURN;
  return_value := 0;
  discperc := v_discperc;
  RETURN;
END
$body$;

-- ==== proc SP_Apply_StudentFine_On_UnpaidInvoices ====
CREATE OR REPLACE FUNCTION dbo.sp_apply_studentfine_on_unpaidinvoices(fineamt numeric, startdate timestamp, enddate timestamp, serviceinvtypecode smallint, excludepartialpaid citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_fineamt numeric(10,2);
  v_startdate timestamp(3);
  v_enddate timestamp(3);
  v_serviceinvtypecode smallint;
  v_excludepartialpaid citext;
BEGIN
  v_fineamt := fineamt;
  v_startdate := startdate;
  v_enddate := enddate;
  v_serviceinvtypecode := serviceinvtypecode;
  v_excludepartialpaid := excludepartialpaid;
  IF (v_excludepartialpaid = 'Y') THEN
    DELETE FROM dbo.virtualgl WHERE ((documenttype = 'RS') AND (documentcode IN (SELECT serviceinvcode FROM dbo.serviceheader WHERE (((outstandingamt = invtotal) AND (date BETWEEN v_startdate AND v_enddate)) AND (serviceinvtypecode = v_serviceinvtypecode)))));
    UPDATE dbo.serviceheader SET misccharges = v_fineamt WHERE (((outstandingamt = invtotal) AND (date BETWEEN v_startdate AND v_enddate)) AND (serviceinvtypecode = v_serviceinvtypecode));
    UPDATE dbo.serviceheader SET invtotal = coalesce(dbo.fn_getserviceinvtotal((serviceinvcode)::integer), 0), outstandingamt = (coalesce(dbo.fn_getserviceinvtotal((serviceinvcode)::integer), 0) - ((invtotal - outstandingamt))) WHERE (((outstandingamt = invtotal) AND (date BETWEEN v_startdate AND v_enddate)) AND (serviceinvtypecode = v_serviceinvtypecode));
  ELSE
    DELETE FROM dbo.virtualgl WHERE ((documenttype = 'RS') AND (documentcode IN (SELECT serviceinvcode FROM dbo.serviceheader WHERE (((outstandingamt > 0) AND (date BETWEEN v_startdate AND v_enddate)) AND (serviceinvtypecode = v_serviceinvtypecode)))));
    UPDATE dbo.serviceheader SET misccharges = v_fineamt WHERE (((outstandingamt > 0) AND (date BETWEEN v_startdate AND v_enddate)) AND (serviceinvtypecode = v_serviceinvtypecode));
    UPDATE dbo.serviceheader SET invtotal = coalesce(dbo.fn_getserviceinvtotal((serviceinvcode)::integer), 0), outstandingamt = (coalesce(dbo.fn_getserviceinvtotal((serviceinvcode)::integer), 0) - ((invtotal - outstandingamt))) WHERE (((outstandingamt > 0) AND (date BETWEEN v_startdate AND v_enddate)) AND (serviceinvtypecode = v_serviceinvtypecode));
  END IF;
  PERFORM dbo.sp_virtualgl(ac_type => 'A');
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_ApplySalePromotions ====
CREATE OR REPLACE FUNCTION dbo.sp_applysalepromotions(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
BEGIN
  UPDATE dbo.customer SET defaultitemdiscperc = 1 WHERE (custcode IN (SELECT DISTINCT d.custcode FROM dbo.salepromotion AS sp, dbo.customergroupdetail AS d, dbo.customer AS c WHERE (((sp.customergroupcode IS NOT NULL) AND (sp.customergroupcode = d.customergroupcode)) AND (d.custcode = c.custcode))));
  UPDATE dbo.customer AS c SET defaultitemdiscperc = sp.defaultitemdiscperc FROM dbo.salepromotion AS sp, dbo.customergroupdetail AS d WHERE ((((((sp.active = 'Y') AND (localtimestamp(3) BETWEEN sp.startdate AND sp.enddate)) AND (sp.customergroupcode IS NOT NULL)) AND (((sp.weekdaycode = 0) OR (sp.weekdaycode = (extract(dow from localtimestamp(3))::integer + 1))))) AND (sp.customergroupcode = d.customergroupcode)) AND (d.custcode = c.custcode));
  UPDATE dbo.customer AS c SET defaultitemdiscperc = 1 FROM dbo.salepromotion AS sp, dbo.customergroupdetail AS d WHERE (((((sp.active = 'Y') AND (NOT ((localtimestamp(3) BETWEEN sp.startdate AND sp.enddate)))) AND (sp.customergroupcode IS NOT NULL)) AND (sp.customergroupcode = d.customergroupcode)) AND (d.custcode = c.custcode));
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_ApproveInstallment ====
CREATE OR REPLACE FUNCTION dbo.sp_approveinstallment(startcode integer, endcode integer, usercode smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_startcode integer;
  v_endcode integer;
  v_usercode smallint;
  v_totalrows integer;
  _rc integer;
BEGIN
  v_startcode := startcode;
  v_endcode := endcode;
  v_usercode := usercode;
  UPDATE dbo.installmentheader SET approved = 'Y', approvedby = v_usercode, approvedon = localtimestamp(3) WHERE ((((installmentcode BETWEEN v_startcode AND v_endcode) AND (posted = 'N')) AND (approved = 'N')) AND (rejected = 'N'));
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_totalrows := _rc;
  _rc := 1;
  IF (v_totalrows = 0) THEN
    RAISE EXCEPTION 'No Installment Estimate available for Approval';
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_ApproveWorkOrder ====
CREATE OR REPLACE FUNCTION dbo.sp_approveworkorder(workordercode integer, usercode smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_workordercode integer;
  v_usercode smallint;
  v_errcode integer;
BEGIN
  v_workordercode := workordercode;
  v_usercode := usercode;
  UPDATE dbo.workorder SET approved = 'Y', approvedon = localtimestamp(3), approvedby = v_usercode WHERE (((workordercode = v_workordercode) AND (approved = 'N')) AND (posted = 'N'));
  IF (0 = 0) THEN
    return_value := 0;
    RETURN;
  ELSE
    RAISE EXCEPTION 'Error occured in Approving Work Order. Work Order Code: %', v_workordercode;
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_AquirePostedTransactions ====
CREATE OR REPLACE FUNCTION dbo.sp_aquirepostedtransactions(srv citext, db citext, owner citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_err integer;
  v_rowid integer;
  v_tablename citext;
  v_archaccdata citext;
  v_synchronize citext;
  v_del_qry citext;
  v_qry citext;
  v_sql citext;
  v_list citext;
  v_from citext;
  cur_c1 refcursor;
  _dq1 text;
  _dq2 text;
  _dq3 text;
  _dq4 text;
  _fs integer := -1;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  v_archaccdata := dbo.fn_getpreference('archiveaccountingdata');
  v_archaccdata := coalesce(v_archaccdata, 'N');
  v_from := ((((((' FROM ' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.');
  DROP TABLE IF EXISTS tmp_ins_temp;
  CREATE TEMP TABLE tmp_ins_temp (
    rowid integer,
    tablename citext,
    synchronize citext
) ON COMMIT DROP;
  INSERT INTO tmp_ins_temp SELECT 10, 'ActivityMonitor', 'Y' UNION ALL SELECT 15, 'CashierJob', 'Y' UNION ALL SELECT 20, 'CashierActivity', 'Y' UNION ALL SELECT 40, 'StockLedger', 'Y' UNION ALL SELECT 41, 'PurQuotationHeader', 'Y' UNION ALL SELECT 42, 'PurQuotationDetail', 'Y' UNION ALL SELECT 43, 'SaleOrderHeader', 'Y' UNION ALL SELECT 44, 'SaleOrderDetail', 'Y' UNION ALL SELECT 45, 'QuotationHeader', 'Y' UNION ALL SELECT 46, 'QuotationDetail', 'Y' UNION ALL SELECT 47, 'PurOrderHeader', 'Y' UNION ALL SELECT 48, 'PurOrderDetail', 'Y' UNION ALL SELECT 50, 'PurRegister', 'Y' UNION ALL SELECT 60, 'ImpPurHeader', 'Y' UNION ALL SELECT 70, 'PurLedger', 'Y' UNION ALL SELECT 80, 'AdvPurHeader', 'Y' UNION ALL SELECT 90, 'PurExp', 'Y' UNION ALL SELECT 100, 'PurDetail', 'Y' UNION ALL SELECT 105, 'PurPayment', 'Y' UNION ALL SELECT 110, 'ProformaPurDetail', 'Y' UNION ALL SELECT 120, 'AdvPurDetail', 'Y' UNION ALL SELECT 130, 'ImpPurDetail', 'Y' UNION ALL SELECT 140, 'PurRegisterDetail', 'Y' UNION ALL SELECT 150, 'PRLedger', 'Y' UNION ALL SELECT 160, 'PRAllocationHeader', 'Y' UNION ALL SELECT 170, 'PRDetail', 'Y' UNION ALL SELECT 180, 'PRAllocationDetail', 'Y' UNION ALL SELECT 190, 'DueAdjHeader', 'Y' UNION ALL SELECT 200, 'SaleLedger', 'Y' UNION ALL SELECT 201, 'SaleInvGroup', 'Y' UNION ALL SELECT 202, 'SaleInvGroupDetail', 'Y' UNION ALL SELECT 203, 'DispatchHeader', 'Y' UNION ALL SELECT 204, 'DispatchDetail', 'Y' UNION ALL SELECT 205, 'SaleSetsHeader', 'Y' UNION ALL SELECT 206, 'SaleSetsOrigDetail', 'Y' UNION ALL SELECT 207, 'SaleSetsDetail', 'Y' UNION ALL SELECT 210, 'DueSatisfyHeader', 'Y' UNION ALL SELECT 230, 'SRBufferLedger', 'Y' UNION ALL SELECT 240, 'SRLedger', 'Y' UNION ALL SELECT 250, 'SaleInvDetail', 'Y' UNION ALL SELECT 260, 'SaleDetail', 'Y' UNION ALL SELECT 280, 'SRDetail', 'Y' UNION ALL SELECT 290, 'SRBufferDetail', 'Y' UNION ALL SELECT 300, 'SRAllocationHeader', 'Y' UNION ALL SELECT 310, 'SRAllocationDetail', 'Y' UNION ALL SELECT 320, 'RefusedSaleHeader', 'Y' UNION ALL SELECT 330, 'RefusedSaleDetail', 'Y' UNION ALL SELECT 340, 'CashierWindow', 'Y' UNION ALL SELECT 350, 'DueAdjDetail', 'Y' UNION ALL SELECT 360, 'DueDeleteDetail', 'Y' UNION ALL SELECT 370, 'DueSatisfyDetail', 'Y' UNION ALL SELECT 380, 'AdjHeader', 'Y' UNION ALL SELECT 390, 'AdjBufferHeader', 'Y' UNION ALL SELECT 400, 'AdjDetail', 'Y' UNION ALL SELECT 410, 'ItemConversionHeader', 'Y' UNION ALL SELECT 420, 'ItemConversionDetail', 'Y' UNION ALL SELECT 430, 'AdjBufferDetail', 'Y' UNION ALL SELECT 440, 'TransferRequisitionHeader', 'Y' UNION ALL SELECT 450, 'TransferRequisitionDetail', 'Y' UNION ALL SELECT 460, 'Theader', 'Y' UNION ALL SELECT 470, 'TDetail', 'Y' UNION ALL SELECT 480, 'IssueReqHeader', 'Y' UNION ALL SELECT 490, 'IssueReqDetail', 'Y' UNION ALL SELECT 500, 'IssueHeader', 'Y' UNION ALL SELECT 510, 'ReceiptHeader', 'Y' UNION ALL SELECT 520, 'IssueDetail', 'Y' UNION ALL SELECT 530, 'ReceiptDetail', 'Y' UNION ALL SELECT 540, 'ProdHeader', 'Y' UNION ALL SELECT 550, 'ProdDetail', 'Y' UNION ALL SELECT 560, 'ProdBuffer', 'Y' UNION ALL SELECT 700, 'ServiceHeader', 'Y' UNION ALL SELECT 710, 'ServiceDetail', 'Y' UNION ALL SELECT 720, 'ServiceRHeader', 'Y' UNION ALL SELECT 730, 'ServiceRDetail', 'Y' UNION ALL SELECT 740, 'ServiceSrAllocationHeader', 'Y' UNION ALL SELECT 750, 'ServiceSrAllocationDetail', 'Y' UNION ALL SELECT 760, 'ServicePurHeader', 'Y' UNION ALL SELECT 770, 'ServicePurDetail', 'Y' UNION ALL SELECT 780, 'ServicePrHeader', 'Y' UNION ALL SELECT 790, 'ServicePrDetail', 'Y' UNION ALL SELECT 800, 'ServicePrAllocationHeader', 'Y' UNION ALL SELECT 810, 'ServicePrAllocationDetail', 'Y' UNION ALL SELECT 1010, 'GLHeader', v_archaccdata UNION ALL SELECT 1020, 'GLDetail', v_archaccdata UNION ALL SELECT 1030, 'Notes', v_archaccdata UNION ALL SELECT 1040, 'NotesDetail', v_archaccdata UNION ALL SELECT 1050, 'TransactionHeader', v_archaccdata UNION ALL SELECT 1060, 'TransactionDetail', v_archaccdata UNION ALL SELECT 1065, 'AvgPriceAdjHeader', v_archaccdata UNION ALL SELECT 1070, 'AvgPriceAdjDetail', v_archaccdata;
  OPEN cur_c1 FOR SELECT rowid, tablename, synchronize FROM tmp_ins_temp AS ins_temp ORDER BY rowid;
  FETCH NEXT FROM cur_c1 INTO v_rowid, v_tablename, v_synchronize;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    v_sql := ' SELECT ';
    v_list := '';
    SELECT r.return_value, r.list INTO v_err, v_list FROM dbo.sp_columnlist(owner => v_owner, "table" => v_tablename, list => v_list) AS r;
    v_err := 0;
    IF ((0 <> 0) OR (v_err <> 0)) THEN
      CLOSE cur_c1;
      -- DEALLOCATE C1
      return_value := -1;
      RETURN;
    END IF;
    IF (((((((((v_tablename = 'PurQuotationHeader') OR (v_tablename = 'SaleOrderHeader')) OR (v_tablename = 'QuotationHeader')) OR (v_tablename = 'PurOrderHeader')) OR (v_tablename = 'StockLedger')) OR (v_tablename = 'ActivityMonitor')) OR (v_tablename = 'CashierJob')) OR (v_tablename = 'SaleLedger')) OR (v_tablename = 'SaleLedgerLog')) THEN
      IF (v_tablename = 'PurQuotationHeader') THEN
        TRUNCATE TABLE dbo.purquotationdetail RESTART IDENTITY;
        v_qry := ((((((((('INSERT INTO DBO.' || v_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_list) || v_from) || v_tablename) || ' WHERE PurQuotationCode NOT IN (SELECT T.PurQuotationCode FROM DBO.PurQuotationHeader T)');
      END IF;
      IF (v_tablename = 'SaleOrderHeader') THEN
        TRUNCATE TABLE dbo.saleorderdetail RESTART IDENTITY;
        v_qry := ((((((((('INSERT INTO DBO.' || v_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_list) || v_from) || v_tablename) || ' WHERE SaleOrderCode NOT IN (SELECT T.SaleOrderCode FROM DBO.SaleOrderHeader T)');
      END IF;
      IF (v_tablename = 'QuotationHeader') THEN
        TRUNCATE TABLE dbo.quotationdetail RESTART IDENTITY;
        v_qry := ((((((((('INSERT INTO DBO.' || v_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_list) || v_from) || v_tablename) || ' WHERE QuotationCode NOT IN (SELECT T.QuotationCode FROM DBO.QuotationHeader T)');
      END IF;
      IF (v_tablename = 'PurOrderHeader') THEN
        TRUNCATE TABLE dbo.purorderdetail RESTART IDENTITY;
        v_qry := ((((((((('INSERT INTO DBO.' || v_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_list) || v_from) || v_tablename) || ' WHERE POCode NOT IN (SELECT T.POCode FROM DBO.PurOrderHeader T)');
      END IF;
      IF (v_tablename = 'StockLedger') THEN
        v_qry := ((((((((('INSERT INTO DBO.' || v_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_list) || v_from) || v_tablename) || ' WHERE UTN NOT IN (SELECT T.UTN FROM DBO.StockLedger T)');
      END IF;
      IF (v_tablename = 'ActivityMonitor') THEN
        TRUNCATE TABLE dbo.activitymonitor RESTART IDENTITY;
        v_qry := (((((((('INSERT INTO DBO.' || v_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_list) || v_from) || v_tablename);
      END IF;
      IF (v_tablename = 'CashierJob') THEN
        TRUNCATE TABLE dbo.cashieractivity RESTART IDENTITY;
        v_qry := ((((((((('INSERT INTO DBO.' || v_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_list) || v_from) || v_tablename) || ' WHERE CashierJobCode NOT IN (SELECT T.CashierJobCode FROM DBO.CashierJob T)');
      END IF;
      IF ((v_tablename = 'SaleLedger') OR (v_tablename = 'SaleLedgerLog')) THEN
        v_qry := ((((((((('INSERT INTO DBO.' || v_tablename) || ' (') || v_list) || ' )  ') || v_sql) || replace((v_list)::citext, ('SRBufferInvCode')::citext, ('SRBufferInvCode=NULL')::citext)) || v_from) || v_tablename) || ' WHERE SaleInvCode NOT IN (SELECT T.SaleInvCode FROM DBO.SaleLedger T)');
      END IF;
    ELSE
      IF (v_synchronize = 'Y') THEN
        IF (v_tablename = 'PurLedger') THEN
          v_qry := ((((((((('INSERT INTO DBO.' || v_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_list) || v_from) || v_tablename) || ' WHERE Posted=''Y''');
        END IF;
        IF (v_tablename = 'PurDetail') THEN
          v_qry := (((((((((((('INSERT INTO DBO.' || v_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_list) || v_from) || v_tablename) || ' WHERE PurInvCode NOT IN (SELECT PurInvCode ') || v_from) || 'PurLedger WHERE Posted=''N''') || ')');
        END IF;
        IF (v_tablename = 'PurExp') THEN
          v_qry := (((((((((((('INSERT INTO DBO.' || v_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_list) || v_from) || v_tablename) || ' WHERE PurInvCode NOT IN (SELECT PurInvCode ') || v_from) || 'PurLedger WHERE Posted=''N''') || ')');
        END IF;
        IF (((v_tablename <> 'PurLedger') AND (v_tablename <> 'PurDetail')) AND (v_tablename <> 'PurExp')) THEN
          v_qry := (((((((('INSERT INTO DBO.' || v_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_list) || v_from) || v_tablename);
        END IF;
        IF (v_tablename = 'PurPayment') THEN
          v_qry := ((((((((('INSERT INTO DBO.' || v_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_list) || v_from) || v_tablename) || ' WHERE Posted=''Y''');
        END IF;
      END IF;
    END IF;
    _dq1 := v_qry;
    IF _dq1 IS NOT NULL THEN
      EXECUTE dbo.tsql_dyn(_dq1);
    END IF;
    v_err := 0;
    IF ((0 <> 0) OR (v_err <> 0)) THEN
      RAISE EXCEPTION 'Data Insertion: Error Transfering % Data', v_tablename;
      CLOSE cur_c1;
      -- DEALLOCATE C1
      return_value := -1;
      RETURN;
    END IF;
    FETCH NEXT FROM cur_c1 INTO v_rowid, v_tablename, v_synchronize;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_c1;
  -- DEALLOCATE C1
  v_tablename := 'VirtualGl';
  v_qry := 'TRUNCATE TABLE DBO.VirtualGl';
  _dq2 := v_qry;
  IF _dq2 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq2);
  END IF;
  v_err := 0;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Data Truncation: Error Truncating % ', v_tablename;
    return_value := -1;
    RETURN;
  END IF;
  v_tablename := 'GodownDetail';
  v_qry := 'TRUNCATE TABLE DBO.GodownDetail';
  _dq3 := v_qry;
  IF _dq3 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq3);
  END IF;
  v_err := 0;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Data Truncation: Error Truncating % ', v_tablename;
    return_value := -1;
    RETURN;
  END IF;
  v_qry := (('INSERT INTO DBO.GodownDetail SELECT * ' || v_from) || v_tablename);
  _dq4 := v_qry;
  IF _dq4 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq4);
  END IF;
  v_err := 0;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Data Insertion: Error Transfering % Data', v_tablename;
    return_value := -1;
    RETURN;
  END IF;
  INSERT INTO dbo.dataimportlog (logdate, importedby, importtype, remarks) VALUES (localtimestamp(3), 1, 'Trans. Acquired', 'Data Import');
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_AreaWise_ComparativeMonthSales ====
CREATE OR REPLACE FUNCTION dbo.sp_areawise_comparativemonthsales(startmonth integer, startyear integer, reportgrouping citext, grouplist citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_startmonth integer;
  v_startyear integer;
  v_reportgrouping citext;
  v_grouplist citext;
  v_tempdate timestamp(3);
  v_olddate timestamp(3);
  v_newdate timestamp(3);
  v_startdate timestamp(3);
  v_enddate timestamp(3);
  v_mindate timestamp(3);
  v_maxdate timestamp(3);
  v_firstnewdate timestamp(3);
  v_counter integer;
  v_endmonth integer;
  v_endyear integer;
BEGIN
  v_startmonth := startmonth;
  v_startyear := startyear;
  v_reportgrouping := reportgrouping;
  v_grouplist := grouplist;
  DELETE FROM dbo.reportdata;
  DROP TABLE IF EXISTS tv_sp_areawise_comparativemonthsales_tab_grouplist;
  CREATE TEMP TABLE tv_sp_areawise_comparativemonthsales_tab_grouplist (
    code integer NOT NULL
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tv_sp_areawise_comparativemonthsales_tab_itemlist;
  CREATE TEMP TABLE tv_sp_areawise_comparativemonthsales_tab_itemlist (
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tv_sp_areawise_comparativemonthsales_tab_grouplist SELECT code FROM dbo.udf_stringtotabl(v_grouplist, ',') AS udf_stringtotabl;
  INSERT INTO tv_sp_areawise_comparativemonthsales_tab_itemlist SELECT code FROM dbo.udf_selectitems(v_reportgrouping, v_grouplist) AS udf_selectitems;
  DROP TABLE IF EXISTS tv_sp_areawise_comparativemonthsales_tab_dateslab;
  CREATE TEMP TABLE tv_sp_areawise_comparativemonthsales_tab_dateslab (
    dateid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    m integer,
    date timestamp(3),
    cdate citext
) ON COMMIT DROP;
  v_startdate := (SELECT (min(date) + (10) * interval '1 day') FROM dbo.udf_daysofmonthlist((v_startmonth)::smallint, v_startyear) AS udf_daysofmonthlist);
  v_endmonth := extract(month from (v_startdate + (360) * interval '1 day'))::integer;
  v_endyear := extract(year from (v_startdate + (360) * interval '1 day'))::integer;
  v_enddate := (SELECT max(date) FROM dbo.udf_daysofmonthlist((v_endmonth)::smallint, v_endyear) AS udf_daysofmonthlist);
  v_counter := 0;
  v_firstnewdate := (((ltrim(rtrim(dbo.tsql_str((v_startmonth)::numeric))) || '-01-') || ltrim(rtrim(dbo.tsql_str((v_startyear)::numeric)))))::timestamp(3);
  WHILE (v_counter <= 11) LOOP
    v_newdate := (((ltrim(rtrim(dbo.tsql_str((extract(month from (v_startdate + (((30 * v_counter))) * interval '1 day'))::integer)::numeric))) || '-01-') || ltrim(rtrim(dbo.tsql_str((extract(year from (v_startdate + (((30 * v_counter))) * interval '1 day'))::integer)::numeric)))))::timestamp(3);
    v_olddate := (((ltrim(rtrim(dbo.tsql_str((extract(month from (v_newdate - (360) * interval '1 day'))::integer)::numeric))) || '-01-') || ltrim(rtrim(dbo.tsql_str((extract(year from (v_newdate - (360) * interval '1 day'))::integer)::numeric)))))::timestamp(3);
    INSERT INTO tv_sp_areawise_comparativemonthsales_tab_dateslab (m, date, cdate) SELECT extract(month from v_olddate)::integer, v_olddate, ((trim(to_char(v_olddate, 'Month')) || ' - ') || ltrim(rtrim(dbo.tsql_str((to_char(v_olddate, 'YYYY'))::numeric))));
    INSERT INTO tv_sp_areawise_comparativemonthsales_tab_dateslab (m, date, cdate) SELECT extract(month from v_newdate)::integer, v_newdate, ((trim(to_char(v_newdate, 'Month')) || ' - ') || ltrim(rtrim(dbo.tsql_str((to_char(v_newdate, 'YYYY'))::numeric))));
    v_counter := (v_counter + 1);
  END LOOP;
  v_mindate := (SELECT min(date) FROM tv_sp_areawise_comparativemonthsales_tab_dateslab AS tab_dateslab);
  v_maxdate := (SELECT max(date) FROM tv_sp_areawise_comparativemonthsales_tab_dateslab AS tab_dateslab);
  INSERT INTO dbo.reportdata (name1, name2, name3, name4, name5, code1, name6, name7, value1) SELECT ar.name AS area, a.name AS customer, c.address1 AS address, c.city AS city, CASE WHEN ((s.salecatcode = 3) OR (s.salecatcode = 1)) THEN 'CASH' ELSE 'CREDIT' END AS salecategory, extract(month from s.date)::integer AS month, ((trim(to_char(s.date, 'Month')) || ' - ') || ltrim(rtrim(dbo.tsql_str((to_char(s.date, 'YYYY'))::numeric)))) AS date, (SELECT cc.name FROM dbo.customercategory AS cc WHERE (cc.custcatcode = c.custcatcode)) AS category, coalesce(sum((((d.looseqty * ((d.saleprice - d.itemflatdisc))) * ((1 - (d.discperc * 0.01)))) * ((1 - (s.discperc * 0.01))))), 0) AS salevalue FROM dbo.saleledger AS s, dbo.saledetail AS d, dbo.item AS i, tv_sp_areawise_comparativemonthsales_tab_itemlist AS t, dbo.customer AS c, dbo.accounts AS a, dbo.area AS ar WHERE (((((((s.date BETWEEN v_mindate AND v_maxdate) AND (s.saleinvcode = d.saleinvcode)) AND (d.icode = i.icode)) AND (i.icode = t.code)) AND (s.custcode = c.custcode)) AND (c.custcode = a.acccode)) AND (c.areacode = ar.areacode)) GROUP BY s.date, s.salecatcode, a.name, c.address1, c.city, c.custcatcode, ar.name UNION ALL SELECT (SELECT min(ar.name) FROM dbo.area AS ar) AS area, (SELECT min(a.name) FROM dbo.accounts AS a) AS customer, '' AS address, '' AS city, 'CASH' AS salecategory, extract(month from date)::integer AS m, cdate AS date, '' AS category, 0 AS salevalue FROM tv_sp_areawise_comparativemonthsales_tab_dateslab AS tab_dateslab;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_AREAWISESALES ====
CREATE OR REPLACE FUNCTION dbo.sp_areawisesales(startdate timestamp, enddate timestamp, regioncode smallint, reportgrouping citext, grouplist citext, zerorows smallint, pricetype smallint, includebonus integer, includereturns integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_startdate timestamp(3);
  v_enddate timestamp(3);
  v_regioncode smallint;
  v_reportgrouping citext;
  v_grouplist citext;
  v_zerorows smallint;
  v_pricetype smallint;
  v_includebonus integer;
  v_includereturns integer;
BEGIN
  v_startdate := startdate;
  v_enddate := enddate;
  v_regioncode := regioncode;
  v_reportgrouping := reportgrouping;
  v_grouplist := grouplist;
  v_zerorows := zerorows;
  v_pricetype := pricetype;
  v_includebonus := includebonus;
  v_includereturns := includereturns;
  DELETE FROM dbo.reportdata;
  DROP TABLE IF EXISTS tv_sp_areawisesales_tab_grouplist;
  CREATE TEMP TABLE tv_sp_areawisesales_tab_grouplist (
    code integer NOT NULL
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tv_sp_areawisesales_tab_itemlist;
  CREATE TEMP TABLE tv_sp_areawisesales_tab_itemlist (
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tv_sp_areawisesales_tab_grouplist SELECT code FROM dbo.udf_stringtotabl(v_grouplist, ',') AS udf_stringtotabl;
  INSERT INTO tv_sp_areawisesales_tab_itemlist SELECT code FROM dbo.udf_selectitems(v_reportgrouping, v_grouplist) AS udf_selectitems;
  INSERT INTO dbo.reportdata (code1, code2, code3, code4, name1, name2, name3, name4, name5, value1, value2) SELECT s.icode AS code1, s.areacode AS code2, s.regioncode AS code3, CASE v_reportgrouping WHEN 'M' THEN i.manfcode WHEN 'C' THEN i.icatcode WHEN 'L' THEN i.iccode ELSE i.packcode END AS code4, i.name AS name1, (SELECT shortname FROM dbo.area WHERE (areacode = s.areacode)) AS name2, (SELECT name FROM dbo.region WHERE (regioncode = s.regioncode)) AS name3, CASE v_reportgrouping WHEN 'M' THEN (SELECT m.name FROM dbo.manufacturer AS m WHERE (m.manfcode = i.manfcode)) WHEN 'C' THEN (SELECT c.name FROM dbo.itemcategory AS c WHERE (c.icatcode = i.icatcode)) WHEN 'L' THEN (SELECT c.name FROM dbo.itemclass AS c WHERE (c.iccode = i.iccode)) ELSE (SELECT p.name FROM dbo.itempacking AS p WHERE (p.packcode = i.packcode)) END AS name4, i.customicode AS name5, sum(s.qty) AS value1, coalesce(sum(CASE v_pricetype WHEN 1 THEN s.netamt WHEN 2 THEN (s.qty * round(((i.saleprice / CASE i.packunits WHEN 0 THEN 1 ELSE i.packunits END))::numeric, 2)) WHEN 3 THEN (s.qty * round(((i.purprice / CASE i.packunits WHEN 0 THEN 1 ELSE i.packunits END))::numeric, 2)) ELSE (s.qty * round((i.avgprice)::numeric, 2)) END), 0) AS value2 FROM (SELECT 0 AS invno, i.icode, 0 AS qty, 0 AS netamt, a.areacode, a.regioncode FROM dbo.area AS a, (SELECT min(code) AS icode FROM tv_sp_areawisesales_tab_itemlist AS tab_itemlist) AS i WHERE ((a.regioncode = v_regioncode) AND (CASE v_zerorows WHEN 0 THEN 0 ELSE 1 END = 1)) UNION ALL SELECT 0 AS invno, i.code, 0 AS qty, 0 AS netamt, a.areacode, v_regioncode FROM (SELECT min(areacode) AS areacode FROM dbo.area WHERE (regioncode = v_regioncode)) AS a, (SELECT code FROM tv_sp_areawisesales_tab_itemlist AS tab_itemlist) AS i WHERE (CASE v_zerorows WHEN 0 THEN 0 ELSE 1 END = 1) UNION ALL SELECT sl.saleinvcode AS invno, sd.icode, sum((sd.looseqty + CASE v_includebonus WHEN 0 THEN 0 ELSE sd.bonusqty END)) AS qty, round(((sum((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc)))) * ((1 - ((.01 * sd.discperc)))))) * ((1 - ((.01 * sl.discperc))))))::numeric, 2) AS netamt, c.areacode, a.regioncode FROM dbo.saleledger AS sl, dbo.saledetail AS sd, dbo.customer AS c, dbo.area AS a WHERE ((((((((a.regioncode = v_regioncode) AND (a.areacode = c.areacode)) AND (c.custcode = sl.custcode)) AND (sl.posted = 'Y')) AND (sl.saleinvcode = sd.saleinvcode)) AND (sl.date >= v_startdate)) AND (sl.date <= v_enddate)) AND (sd.icode IN (SELECT code FROM tv_sp_areawisesales_tab_itemlist AS tab_itemlist))) GROUP BY sl.saleinvcode, sd.icode, sl.custcode, a.regioncode, c.areacode, sl.discperc UNION ALL SELECT sl.saleinvcode AS invno, sd.icode, sum((sd.looseqty + CASE v_includebonus WHEN 0 THEN 0 ELSE sd.bonusqty END)) AS qty, round(((sum((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc)))) * ((1 - ((.01 * sd.discperc)))))) * ((1 - ((.01 * sl.discperc))))))::numeric, 2) AS netamt, c.areacode, a.regioncode FROM dbo.saleledger AS sl, dbo.saleinvdetail AS sd, dbo.customer AS c, dbo.area AS a WHERE (((((((((sl.impactinventory = 'N') AND (a.regioncode = v_regioncode)) AND (a.areacode = c.areacode)) AND (c.custcode = sl.custcode)) AND (sl.posted = 'Y')) AND (sl.saleinvcode = sd.saleinvcode)) AND (sl.date >= v_startdate)) AND (sl.date <= v_enddate)) AND (sd.icode IN (SELECT code FROM tv_sp_areawisesales_tab_itemlist AS tab_itemlist))) GROUP BY sl.saleinvcode, sd.icode, sl.custcode, a.regioncode, c.areacode, sl.discperc UNION ALL SELECT sl.srinvcode AS invno, sd.icode, (-sum((sd.looseqty + CASE v_includebonus WHEN 0 THEN 0 ELSE sd.bonusqty END))) AS qty, (-round(((sum((((sd.looseqty * sd.srprice)) * ((1 - ((.01 * sd.discperc)))))) * ((1 - ((.01 * sl.discperc))))))::numeric, 2)) AS netamt, c.areacode, a.regioncode FROM dbo.srledger AS sl, dbo.srdetail AS sd, dbo.customer AS c, dbo.area AS a WHERE (((((((((v_includereturns = 1) AND (a.regioncode = v_regioncode)) AND (a.areacode = c.areacode)) AND (c.custcode = sl.custcode)) AND (sl.posted = 'Y')) AND (sl.srinvcode = sd.srinvcode)) AND (sl.date >= v_startdate)) AND (sl.date <= v_enddate)) AND (sd.icode IN (SELECT code FROM tv_sp_areawisesales_tab_itemlist AS tab_itemlist))) GROUP BY sl.srinvcode, sd.icode, sl.custcode, sl.discperc, a.regioncode, c.areacode) AS s, dbo.item AS i WHERE (s.icode = i.icode) GROUP BY s.regioncode, s.areacode, s.icode, i.name, i.customicode, i.icatcode, i.manfcode, i.iccode, i.packcode;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_AutoCreateCustomerGodown ====
CREATE OR REPLACE FUNCTION dbo.sp_autocreatecustomergodown(acccode smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_acccode smallint;
  v_name citext;
  v_code integer;
  v_err integer;
  v_rt_code integer;
  v_godownexists integer;
  v_gcode smallint;
BEGIN
  v_acccode := acccode;
  v_name := (SELECT name FROM dbo.accounts WHERE (acccode = v_acccode));
  v_godownexists := coalesce((SELECT count(*) FROM dbo.godown WHERE (name = v_name)), 0);
  IF (v_godownexists > 0) THEN
    v_gcode := (SELECT gcode FROM dbo.godown WHERE (name = v_name));
  ELSE
    SELECT r.return_value, r.key INTO v_rt_code, v_code FROM dbo.sp_gettabmaxkey(tabname => 'Godown', key => v_code) AS r;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      RAISE EXCEPTION 'Error occured in inserting record into Godown Name : %', v_code;
      return_value := -1;
      RETURN;
    END IF;
    v_gcode := v_code;
  END IF;
  INSERT INTO dbo.godown (gcode, name, location, godowngroupcode) VALUES (v_gcode, v_name, v_name, 1);
  IF (0 <> 0) THEN
    RAISE EXCEPTION 'Error inserting record into Godown Name : %', v_name;
    return_value := -1;
    RETURN;
  END IF;
  INSERT INTO dbo.accountgodown (acccode, gcode) VALUES (v_acccode, v_gcode);
  IF (0 <> 0) THEN
    RAISE EXCEPTION 'Error inserting record into Account Godown. Name : %', v_name;
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_AutoCreatePricePolicy ====
CREATE OR REPLACE FUNCTION dbo.sp_autocreatepricepolicy(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_lastpricepolicycode integer;
BEGIN
  v_lastpricepolicycode := coalesce((SELECT max(pricepolicycode) FROM dbo.pricepolicy), 0);
  DROP TABLE IF EXISTS tmp_lt_pricepolicy;
  CREATE TEMP TABLE tmp_lt_pricepolicy (
    code integer GENERATED BY DEFAULT AS IDENTITY,
    pricepolicycode integer,
    name citext,
    icode integer
) ON COMMIT DROP;
  INSERT INTO tmp_lt_pricepolicy (name, icode) SELECT i.name, i.icode FROM dbo.item AS i WHERE (icode NOT IN (SELECT icode FROM dbo.pricepolicy));
  UPDATE tmp_lt_pricepolicy AS lt_pricepolicy SET pricepolicycode = (code + v_lastpricepolicycode);
  INSERT INTO dbo.pricepolicy (pricepolicycode, name, icode) SELECT pricepolicycode, (ltrim(rtrim(dbo.tsql_str((icode)::numeric, 10))) || '.') AS name, icode FROM tmp_lt_pricepolicy AS lt_pricepolicy;
  INSERT INTO dbo.pricepolicydetail (pricepolicycode, qtylimit, price, expirydate) SELECT p.pricepolicycode, 0 AS qtylimit, i.saleprice, ('2012-12-12')::timestamp(3) FROM tmp_lt_pricepolicy AS p, dbo.item AS i WHERE (p.icode = i.icode);
  v_lastpricepolicycode := coalesce((SELECT max(pricepolicycode) FROM dbo.pricepolicy), 0);
  UPDATE dbo._tabmaxkey SET tabmaxkey = v_lastpricepolicycode WHERE (tabname = 'PricePolicy');
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_AutoDataMigration ====
CREATE OR REPLACE FUNCTION dbo.sp_autodatamigration(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_rt_code integer;
  v_errorno integer;
  v_rowsaffected integer;
  v_inv_posted_age integer;
  v_prevsalehistory citext;
  v_saledump citext;
  v_purdump citext;
  v_startdate timestamp(3);
  v_enddate timestamp(3);
  v_dbname citext;
  v_svr citext;
  v_pktfile citext;
  v_dm_db citext;
  v_dbcount integer;
  cur_db_cursor refcursor;
  _r1 record;
  _r2 record;
  _fs integer := -1;
BEGIN
  v_svr := current_setting('cluster_name', true);
  v_dm_db := 'DataMigrationTempDB';
  -- Select @dbcount = count(*)
  -- From master..Sysdatabases
  -- Where lower(name) like '%databasev%'
  RAISE EXCEPTION 'untranslated T-SQL (cross-database table master..Sysdatabases)' USING ERRCODE = '0A000';
  IF (v_dbcount > 0) THEN
    -- OPEN db_cursor
    RAISE EXCEPTION 'untranslated T-SQL (cross-database table master..Sysdatabases)' USING ERRCODE = '0A000';
    FETCH LAST FROM cur_db_cursor INTO v_dbname;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    IF (_fs <> 0) THEN
      -- Select @dbname = name FROM master..Sysdatabases Where lower(name) like '%database%'
      RAISE EXCEPTION 'untranslated T-SQL (cross-database table master..Sysdatabases)' USING ERRCODE = '0A000';
    END IF;
    CLOSE cur_db_cursor;
    -- DEALLOCATE db_cursor
  ELSE
    -- Select @dbname = name FROM master..Sysdatabases Where lower(name) like '%database%'
    RAISE EXCEPTION 'untranslated T-SQL (cross-database table master..Sysdatabases)' USING ERRCODE = '0A000';
  END IF;
  v_prevsalehistory := dbo.fn_getpreference('SaveSaleHistoryBeforeMigration');
  v_purdump := dbo.fn_getpreference('PreparePurDumpBeforeMigration');
  v_saledump := dbo.fn_getpreference('PrepareSaleDumpBeforeMigration');
  v_startdate := (localtimestamp(3) - (90) * interval '1 day');
  v_enddate := localtimestamp(3);
  -- BEGIN TRANSACTION (the caller owns the transaction)
  SELECT r.return_value INTO v_rt_code FROM dbo.sp_copysbuffertosales() AS r;
  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
    RAISE EXCEPTION 'Error Moving Sale From Buffer to Sale Ledger';
    RAISE EXCEPTION 'T-SQL ROLLBACK in SP_AutoDataMigration' USING ERRCODE = 'TS001';
    return_value := -1;
    RETURN;
  ELSE
    -- COMMIT (the caller owns the transaction)
  END IF;
  -- BEGIN TRANSACTION (the caller owns the transaction)
  SELECT r.return_value INTO v_rt_code FROM dbo.sp_posttransactionsbeforeautomigration() AS r;
  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
    RAISE EXCEPTION 'T-SQL ROLLBACK in SP_AutoDataMigration' USING ERRCODE = 'TS001';
    return_value := -1;
    RETURN;
  ELSE
    -- COMMIT (the caller owns the transaction)
  END IF;
  IF (v_purdump = 'Y') THEN
    -- BEGIN TRANSACTION (the caller owns the transaction)
    SELECT r.return_value, r.rowsaffected INTO v_rt_code, v_rowsaffected FROM dbo.sp_copyinvoicestopurledgermod(rowsaffected => v_rowsaffected) AS r;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_AutoDataMigration' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    ELSE
      -- COMMIT (the caller owns the transaction)
    END IF;
  END IF;
  IF (v_saledump = 'Y') THEN
    -- BEGIN TRANSACTION (the caller owns the transaction)
    SELECT r.return_value, r.rowsaffected INTO v_rt_code, v_rowsaffected FROM dbo.sp_copyinvoicestosaledump(rowsaffected => v_rowsaffected) AS r;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_AutoDataMigration' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    ELSE
      -- COMMIT (the caller owns the transaction)
    END IF;
  END IF;
  IF (v_prevsalehistory = 'Y') THEN
    -- BEGIN TRANSACTION (the caller owns the transaction)
    SELECT r.return_value INTO v_rt_code FROM dbo.sp_get_previoussalehistory_onarchival(startdate => v_startdate, enddate => v_enddate) AS r;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_AutoDataMigration' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    ELSE
      -- COMMIT (the caller owns the transaction)
    END IF;
  END IF;
  SELECT r.return_value, r.packetfile INTO v_rt_code, v_pktfile FROM dbo.sp_preparedatamigrationpacket(svr => v_svr, db => v_dbname, packetfile => v_pktfile) AS r;
  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
    RAISE EXCEPTION 'Error Preparing Data Migration Packet';
    return_value := -1;
    RETURN;
  END IF;
  SELECT r.return_value INTO v_rt_code FROM dbo.sp_verifydatamigrationpacket(packetfile => v_pktfile, tempdbname => v_dm_db, svr => v_svr) AS r;
  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
    RAISE EXCEPTION 'Error Verifying Data Migration Packet';
    return_value := -1;
    RETURN;
  END IF;
  -- BEGIN TRANSACTION (the caller owns the transaction)
  SELECT r.return_value INTO v_rt_code FROM dbo.sp_deletepostedtransactions() AS r;
  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
    RAISE EXCEPTION 'Error Verifying Data Migration Packet';
    RAISE EXCEPTION 'T-SQL ROLLBACK in SP_AutoDataMigration' USING ERRCODE = 'TS001';
    return_value := -1;
    RETURN;
  ELSE
    -- COMMIT (the caller owns the transaction)
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_AutoDoctorTokenReset ====
CREATE OR REPLACE FUNCTION dbo.sp_autodoctortokenreset(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
BEGIN
  UPDATE dbo.doctors SET lasttokenno = coalesce(t.tokenno, 0) FROM (SELECT sh.doctcode, (coalesce(max(sh.tokenno), 0) + 1) AS tokenno FROM dbo.serviceheader AS sh, dbo.doctors AS d WHERE (sh.date BETWEEN (date_trunc('day', localtimestamp(3)))::timestamp(3) AND ((left(to_char(localtimestamp(3), 'MM/DD/YYYY'), 100) || ' 23:59:59'))::timestamp(3)) GROUP BY sh.doctcode UNION SELECT va.doctcode, (coalesce(max(va.tokenno), 0) + 1) AS tokenno FROM dbo.visitappointment AS va, dbo.doctors AS d WHERE (va.duedate BETWEEN (date_trunc('day', localtimestamp(3)))::timestamp(3) AND ((left(to_char(localtimestamp(3), 'MM/DD/YYYY'), 100) || ' 23:59:59'))::timestamp(3)) GROUP BY va.doctcode UNION SELECT d.doctcode, 0 AS tokenno FROM dbo.doctors AS d WHERE (d.doctcode NOT IN (SELECT va.doctcode FROM dbo.visitappointment AS va WHERE (va.duedate BETWEEN (date_trunc('day', localtimestamp(3)))::timestamp(3) AND ((left(to_char(localtimestamp(3), 'MM/DD/YYYY'), 100) || ' 23:59:59'))::timestamp(3)) GROUP BY va.doctcode UNION SELECT sh.doctcode FROM dbo.serviceheader AS sh WHERE (sh.date BETWEEN (date_trunc('day', localtimestamp(3)))::timestamp(3) AND ((left(to_char(localtimestamp(3), 'MM/DD/YYYY'), 100) || ' 23:59:59'))::timestamp(3)) GROUP BY sh.doctcode))) AS t WHERE (doctors.doctcode = t.doctcode);
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_AutoGenerateIssueReqForConsumableItem ====
CREATE OR REPLACE FUNCTION dbo.sp_autogenerateissuereqforconsumableitem(serviceinvcode integer, usercode smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_serviceinvcode integer;
  v_usercode smallint;
  v_posted citext;
  v_price numeric(12,2);
  v_tot_services integer;
  v_resultcode integer;
  v_servicecode integer;
  v_serviceissuerequestcode integer;
  v_lastserviceissuerequestcode integer;
  v_errcode integer;
  v_rowid integer;
  v_in_rowid integer;
  v_in_qty integer;
  v_tmpcode integer;
  v_issueinvcode integer;
  _rc integer;
BEGIN
  v_serviceinvcode := serviceinvcode;
  v_usercode := usercode;
  -- SET NOCOUNT ON
  IF (v_serviceinvcode IS NULL) THEN
    return_value := 0;
    RETURN;
  END IF;
  IF ((SELECT dbo.fn_getpreference('generate_issuereq_for_consumableitem_onservicepost')) = 'N') THEN
    return_value := 0;
    RETURN;
  END IF;
  IF (v_serviceinvcode IS NULL) THEN
    return_value := 0;
    RETURN;
  END IF;
  v_posted := coalesce((SELECT posted FROM dbo.serviceheader WHERE (serviceinvcode = v_serviceinvcode)), 'N');
  _rc := 1;
  IF ((v_posted = 'N') OR (v_posted IS NULL)) THEN
    return_value := 0;
    RETURN;
  END IF;
  v_errcode := 0;
  _rc := 1;
  SELECT r.return_value, r.key INTO v_errcode, v_serviceissuerequestcode FROM dbo.sp_locktabmaxkey(tabname => 'ServiceIssueRequest', key => v_serviceissuerequestcode) AS r;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem while Fetching Service Issue Request Value';
    return_value := -1;
    RETURN;
  END IF;
  IF (v_usercode IS NULL) THEN
    v_usercode := 1;
    _rc := 1;
  END IF;
  v_tmpcode := (SELECT count(sci.icode) FROM dbo.serviceheader AS h, dbo.servicedetail AS d, dbo.serviceconsumableitem AS sci WHERE ((((h.serviceinvcode = v_serviceinvcode) AND (h.posted = 'Y')) AND (h.serviceinvcode = d.serviceinvcode)) AND (d.servicecode = sci.servicecode)));
  _rc := 1;
  IF ((v_tmpcode <= 0) OR (v_tmpcode IS NULL)) THEN
    return_value := 0;
    RETURN;
  END IF;
  INSERT INTO dbo.serviceissuerequest (serviceissuerequestcode, deptcode, date, originaldate, salesmancode, modifiedby, posted, postedby, remarks, postdate, smancode, areacode, acccode, serviceinvcode) SELECT v_serviceissuerequestcode, 1 AS deptcode, localtimestamp(3) AS date, localtimestamp(3) AS originaldate, v_usercode AS salesmancode, NULL::smallint AS modifiedby, 'N' AS posted, NULL::smallint AS postedby, NULL::citext AS remarks, NULL::timestamp(3) AS postdate, NULL::smallint AS smancode, 1 AS areacode, NULL::smallint AS acccode, v_serviceinvcode AS serviceinvcode;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((0 <> 0) OR (_rc <= 0)) THEN
    RAISE EXCEPTION 'Problem while Inserting Service Issue Request Header Value';
    return_value := -1;
    RETURN;
  END IF;
  INSERT INTO dbo.serviceissuerequestdetail (serviceissuerequestcode, servicerowid, icode, qty, processcharge) SELECT v_serviceissuerequestcode, d.srvrowid, sci.icode, trunc(sci.qty)::integer, sci.processcharge FROM dbo.serviceheader AS h, dbo.servicedetail AS d, dbo.serviceconsumableitem AS sci WHERE ((((h.serviceinvcode = v_serviceinvcode) AND (h.posted = 'Y')) AND (h.serviceinvcode = d.serviceinvcode)) AND (d.servicecode = sci.servicecode)) ORDER BY d.srvrowid, sci.rowid;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((0 <> 0) OR (_rc <= 0)) THEN
    RAISE EXCEPTION 'Problem while Inserting Service Issue Request Detail Rows';
    return_value := -1;
    RETURN;
  END IF;
  v_lastserviceissuerequestcode := (v_serviceissuerequestcode + 1);
  _rc := 1;
  SELECT r.return_value INTO v_errcode FROM dbo.sp_updatetabmaxkey(tabname => 'ServiceIssueRequest', key => v_lastserviceissuerequestcode) AS r;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem while Updating Service Issue Request Max Key Value';
    return_value := -1;
    RETURN;
  END IF;
  IF ((SELECT dbo.fn_getpreference('AutoPost_issuereq_for_consumableitem_onservicepost')) = 'N') THEN
    return_value := 0;
    RETURN;
  ELSE
    UPDATE dbo.serviceissuerequest SET posted = 'Y', postdate = localtimestamp(3), postedby = v_usercode WHERE (((serviceissuerequestcode = v_serviceissuerequestcode) AND (serviceinvcode = v_serviceinvcode)) AND (posted = 'N'));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc <= 0)) THEN
      RAISE EXCEPTION 'Problem while Updating Posting Status of Service Issue Request';
      return_value := -1;
      RETURN;
    END IF;
    SELECT r.return_value, r.issueinvcode INTO v_errcode, v_issueinvcode FROM dbo.sp_autoissueconsumableitem(serviceissuerequestcode => v_serviceissuerequestcode, usercode => (v_usercode)::integer, issueinvcode => v_issueinvcode) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Problem while Auto Generation of Issue against Service Consumable Items.';
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_AutoGeneratePatientRegNo ====
CREATE OR REPLACE FUNCTION dbo.sp_autogeneratepatientregno(patientcatcode smallint, INOUT regno citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_patientcatcode smallint;
  v_regno citext;
  v_err integer;
  v_rowcount integer;
  v_counter integer;
  v_shortname citext;
  _r1 record;
  _rc integer;
BEGIN
  v_patientcatcode := patientcatcode;
  v_regno := regno;
  -- SET NOCOUNT ON
  _rc := 0;
  FOR _r1 IN SELECT counter AS c1, shortname AS c2 FROM dbo.patientcategory WHERE (patientcatcode = v_patientcatcode) FOR UPDATE OF patientcategory LOOP
    _rc := _rc + 1;
    v_counter := _r1.c1;
    v_shortname := _r1.c2;
  END LOOP;
  v_err := 0;
  v_rowcount := _rc;
  _rc := 1;
  IF ((v_err = 0) AND (v_rowcount > 0)) THEN
    UPDATE dbo.patientcategory SET counter = (counter + 1) WHERE (patientcatcode = v_patientcatcode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_err := 0;
    v_rowcount := _rc;
    _rc := 1;
    IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
      -- SET NOCOUNT OFF
      RAISE EXCEPTION 'Exception occured in updating counter for patient category %', v_patientcatcode;
      return_value := -1;
      regno := v_regno;
      RETURN;
    ELSE
      v_regno := coalesce((ltrim(rtrim(v_shortname)) || ltrim(rtrim(dbo.tsql_str(((v_counter + 1))::numeric)))), '');
      _rc := 1;
    END IF;
  ELSE
    -- SET NOCOUNT OFF
    RAISE EXCEPTION 'Exception occured in fetching counter for patient category %', v_patientcatcode;
    return_value := -1;
    regno := v_regno;
    RETURN;
  END IF;
  -- SET NOCOUNT OFF
  return_value := 0;
  regno := v_regno;
  RETURN;
  return_value := 0;
  regno := v_regno;
  RETURN;
END
$body$;

-- ==== proc SP_AutoGeneratePurchaseOfService ====
CREATE OR REPLACE FUNCTION dbo.sp_autogeneratepurchaseofservice(serviceinvcode integer, usercode smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_serviceinvcode integer;
  v_usercode smallint;
  v_posted citext;
  v_price numeric(12,2);
  v_tot_services integer;
  v_resultcode integer;
  v_servicecode integer;
  v_start_no integer;
  v_end_no integer;
  v_errcode integer;
  v_rowid integer;
  v_in_rowid integer;
  v_in_qty integer;
  v_tmpcode integer;
  _rc integer;
BEGIN
  v_serviceinvcode := serviceinvcode;
  v_usercode := usercode;
  -- SET NOCOUNT ON
  IF (v_serviceinvcode IS NULL) THEN
    return_value := 0;
    RETURN;
  END IF;
  v_posted := (SELECT posted FROM dbo.serviceinvpurtempheader WHERE (serviceinvcode = v_serviceinvcode));
  _rc := 1;
  IF ((v_posted = 'Y') OR (v_posted IS NULL)) THEN
    return_value := 0;
    RETURN;
  END IF;
  v_errcode := 0;
  _rc := 1;
  SELECT r.return_value, r.key INTO v_errcode, v_start_no FROM dbo.sp_locktabmaxkey(tabname => 'ServicePurHeader', key => v_start_no) AS r;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem while Fetching Service Purchase Header Value';
    return_value := -1;
    RETURN;
  END IF;
  DROP TABLE IF EXISTS tv_sp_autogeneratepurchaseofservice_servicepurheader;
  CREATE TEMP TABLE tv_sp_autogeneratepurchaseofservice_servicepurheader (
    servicepurinvcode integer,
    suppcode smallint,
