) ON COMMIT DROP;
  IF (v_usercode IS NULL) THEN
    v_usercode := 1;
    _rc := 1;
  END IF;
  INSERT INTO tv_sp_autogeneratepurchaseofservice_servicepurheader (suppcode) SELECT DISTINCT suppcode FROM dbo.serviceinvpurtempdetail WHERE (serviceinvcode = v_serviceinvcode);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF (_rc = 0) THEN
    return_value := 0;
    RETURN;
  END IF;
  v_tot_services := coalesce((SELECT count(*) FROM tv_sp_autogeneratepurchaseofservice_servicepurheader AS servicepurheader), 0);
  _rc := 1;
  IF (v_tot_services <= 0) THEN
    return_value := 0;
    RETURN;
  END IF;
  UPDATE tv_sp_autogeneratepurchaseofservice_servicepurheader AS servicepurheader SET servicepurinvcode = (v_start_no + rowid);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  INSERT INTO dbo.servicepurheader (servicepurinvcode, date, suppcode, usercode, remarks, originaldate, modifiedby, postedby, posted, postdate, headerno, discperc, flatdisc, misccharges, cashacccode, cashtendered, cashcharged, cashback, invtotal, outstandingamt, marked, ref1, ref2, ref3, ref4, serviceinvcode) SELECT t.servicepurinvcode, localtimestamp(3), t.suppcode, v_usercode, ('Service Purchase Against Service Sale Inv. ' || ltrim(rtrim((v_serviceinvcode)::text))) AS remarks, localtimestamp(3), NULL::smallint, NULL::smallint, 'N' AS posted, NULL::timestamp(3) AS postdate, 1 AS headerno, 0 AS discperc, 0 AS flatdisc, 0 AS misccharges, 2 AS cashacccode, 0 AS cashtendered, 0 AS cashcharged, 0 AS cashback, 0 AS invtotal, 0 AS outstandingamt, 'N' AS marked, v_serviceinvcode AS ref1, NULL::citext AS ref2, NULL::citext AS ref3, NULL::citext AS ref4, v_serviceinvcode FROM tv_sp_autogeneratepurchaseofservice_servicepurheader AS t;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((0 <> 0) OR (_rc <= 0)) THEN
    RAISE EXCEPTION 'Problem while Inserting Service Purchase Invoice Header Value';
    return_value := -1;
    RETURN;
  END IF;
  INSERT INTO dbo.servicepurdetail (servicepurinvcode, servicecode, qty, price, serviceflatdisc, discperc, remarks, srvrowid) SELECT t.servicepurinvcode, std.servicecode, std.qty, std.purprice, std.serviceflatdisc, std.discperc, NULL::citext AS remarks, std.srvrowid FROM dbo.serviceinvpurtempdetail AS std, tv_sp_autogeneratepurchaseofservice_servicepurheader AS t WHERE ((std.serviceinvcode = v_serviceinvcode) AND (std.suppcode = t.suppcode)) ORDER BY std.srvrowid, std.rowid;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((0 <> 0) OR (_rc <= 0)) THEN
    RAISE EXCEPTION 'Problem while Inserting Service Purchase Detail Rows';
    return_value := -1;
    RETURN;
  END IF;
  v_end_no := coalesce((SELECT max(servicepurinvcode) FROM tv_sp_autogeneratepurchaseofservice_servicepurheader AS servicepurheader), 0);
  _rc := 1;
  SELECT r.return_value INTO v_errcode FROM dbo.sp_updatetabmaxkey(tabname => 'ServicePurHeader', key => v_end_no) AS r;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem while Updating Service Purchase Key Value';
    return_value := -1;
    RETURN;
  END IF;
  UPDATE dbo.servicepurheader SET invtotal = coalesce((SELECT round((sum(((d.qty * ((d.price - d.serviceflatdisc))) * ((1 - (d.discperc * 0.01))))))::numeric, 0) AS invtotal FROM dbo.servicepurdetail AS d WHERE (d.servicepurinvcode = servicepurheader.servicepurinvcode)), 0) WHERE (servicepurinvcode IN (SELECT t.servicepurinvcode FROM tv_sp_autogeneratepurchaseofservice_servicepurheader AS t));
  GET DIAGNOSTICS _rc = ROW_COUNT;
  UPDATE dbo.servicepurheader SET outstandingamt = invtotal WHERE (servicepurinvcode IN (SELECT t.servicepurinvcode FROM tv_sp_autogeneratepurchaseofservice_servicepurheader AS t));
  GET DIAGNOSTICS _rc = ROW_COUNT;
  UPDATE dbo.serviceinvpurtempheader SET posted = 'Y', postedby = v_usercode, postdate = localtimestamp(3) WHERE (serviceinvcode = v_serviceinvcode);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((SELECT dbo.fn_getpreference('AutoPostPurOfServiceOnServicePurTemplatePosting')) = 'N') THEN
    return_value := 0;
    RETURN;
  ELSE
    UPDATE dbo.servicepurheader SET posted = 'Y', postdate = localtimestamp(3), postedby = v_usercode WHERE ((serviceinvcode = v_serviceinvcode) AND (servicepurheader.posted = 'N'));
    GET DIAGNOSTICS _rc = ROW_COUNT;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_AutoGeneratePurchaseOfService_DoctorShareBased ====
