  END IF;
  DROP TABLE IF EXISTS tv_sp_autogeneratepurchaseofservice_doctorsharebased_s_c1171cc7;
  CREATE TEMP TABLE tv_sp_autogeneratepurchaseofservice_doctorsharebased_s_c1171cc7 (
