  END IF;
  INSERT INTO tv_sp_autogeneratepurchaseofservice_doctorsharebased_s_c1171cc7 (suppcode, headerno, ref) SELECT DISTINCT dc.acccode, h.headerno, CASE WHEN (h.admissioncode > 0) THEN (SELECT p.name FROM dbo.patientadmission AS pa, dbo.patient AS p WHERE ((h.admissioncode = pa.admissioncode) AND (pa.patientcode = p.patientcode))) ELSE CASE WHEN (h.patientcode > 0) THEN (SELECT p.name FROM dbo.patient AS p WHERE (p.patientcode = h.patientcode)) ELSE '' END END AS ref FROM dbo.serviceheader AS h, dbo.servicedetail AS d, dbo.doctors AS dc WHERE (((((h.serviceinvcode = v_serviceinvcode) AND (h.serviceinvcode = d.serviceinvcode)) AND (((d.commission > 0) OR (d.shareperc > 0)))) AND (h.doctcode = dc.doctcode)) AND (dc.acccode > 0));
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF (_rc = 0) THEN
    return_value := 0;
    RETURN;
  END IF;
  v_tot_services := coalesce((SELECT count(*) FROM tv_sp_autogeneratepurchaseofservice_doctorsharebased_s_c1171cc7 AS servicepurheader), 0);
  _rc := 1;
  IF (v_tot_services <= 0) THEN
    return_value := 0;
    RETURN;
  END IF;
  UPDATE tv_sp_autogeneratepurchaseofservice_doctorsharebased_s_c1171cc7 AS servicepurheader SET servicepurinvcode = (v_start_no + rowid);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  INSERT INTO dbo.servicepurheader (servicepurinvcode, date, suppcode, usercode, remarks, originaldate, modifiedby, postedby, posted, postdate, headerno, discperc, flatdisc, misccharges, cashacccode, cashtendered, cashcharged, cashback, invtotal, outstandingamt, marked, ref1, ref2, ref3, ref4, serviceinvcode) SELECT t.servicepurinvcode, localtimestamp(3), t.suppcode, v_usercode, ('Service Purchase Against Service Sale Inv. ' || ltrim(rtrim((v_serviceinvcode)::text))) AS remarks, localtimestamp(3), NULL::smallint, NULL::smallint, 'N' AS posted, NULL::timestamp(3) AS postdate, t.headerno, 0 AS discperc, 0 AS flatdisc, 0 AS misccharges, 2 AS cashacccode, 0 AS cashtendered, 0 AS cashcharged, 0 AS cashback, 0 AS invtotal, 0 AS outstandingamt, 'N' AS marked, v_serviceinvcode AS ref1, t.ref AS ref2, NULL::citext AS ref3, NULL::citext AS ref4, v_serviceinvcode FROM tv_sp_autogeneratepurchaseofservice_doctorsharebased_s_c1171cc7 AS t;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((0 <> 0) OR (_rc <= 0)) THEN
    RAISE EXCEPTION 'Problem while Inserting Service Purchase Invoice Header Value';
