  INSERT INTO dbo.servicepurdetail (servicepurinvcode, servicecode, qty, price, serviceflatdisc, discperc, remarks, srvrowid) SELECT t.servicepurinvcode, d.servicecode, d.qty, (d.commission + round((((((d.price - d.serviceflatdisc)) * ((1 - (d.discperc * 0.01)))) * ((d.shareperc * 0.01))))::numeric, 2)) AS purprice, 0 AS serviceflatdisc, 0 AS discperc, NULL::citext AS remarks, d.srvrowid FROM dbo.serviceheader AS h, dbo.servicedetail AS d, dbo.doctors AS dc, tv_sp_autogeneratepurchaseofservice_doctorsharebased_s_c1171cc7 AS t WHERE (((((h.serviceinvcode = v_serviceinvcode) AND (h.serviceinvcode = d.serviceinvcode)) AND (((d.commission > 0) OR (d.shareperc > 0)))) AND (h.doctcode = dc.doctcode)) AND (dc.acccode = t.suppcode)) ORDER BY d.srvrowid;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((0 <> 0) OR (_rc <= 0)) THEN
    RAISE EXCEPTION 'Problem while Inserting Service Purchase Detail Rows';
    return_value := -1;
    RETURN;
  END IF;
  v_end_no := coalesce((SELECT max(servicepurinvcode) FROM tv_sp_autogeneratepurchaseofservice_doctorsharebased_s_c1171cc7 AS servicepurheader), 0);
  _rc := 1;
  SELECT r.return_value INTO v_errcode FROM dbo.sp_updatetabmaxkey(tabname => 'ServicePurHeader', key => v_end_no) AS r;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem while Updating Service Purchase Key Value';
