    RETURN;
  END IF;
  UPDATE dbo.servicepurheader SET invtotal = coalesce((SELECT round((sum(((d.qty * ((d.price - d.serviceflatdisc))) * ((1 - (d.discperc * 0.01))))))::numeric, 0) AS invtotal FROM dbo.servicepurdetail AS d WHERE (d.servicepurinvcode = servicepurheader.servicepurinvcode)), 0) WHERE (servicepurinvcode IN (SELECT t.servicepurinvcode FROM tv_sp_autogeneratepurchaseofservice_doctorsharebased_s_c1171cc7 AS t));
  GET DIAGNOSTICS _rc = ROW_COUNT;
  UPDATE dbo.servicepurheader SET outstandingamt = invtotal WHERE (servicepurinvcode IN (SELECT t.servicepurinvcode FROM tv_sp_autogeneratepurchaseofservice_doctorsharebased_s_c1171cc7 AS t));
  GET DIAGNOSTICS _rc = ROW_COUNT;
  UPDATE dbo.servicepurheader SET posted = 'Y', postdate = localtimestamp(3), postedby = v_usercode WHERE ((serviceinvcode = v_serviceinvcode) AND (servicepurheader.posted = 'N'));
  GET DIAGNOSTICS _rc = ROW_COUNT;
  return_value := 0;
  RETURN;
  return_value := 0;
