END
$body$;

-- ==== proc SP_AutoGenerateServiceInvPurTemplate ====
CREATE OR REPLACE FUNCTION dbo.sp_autogenerateserviceinvpurtemplate(serviceinvcode integer, usercode smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_serviceinvcode integer;
  v_usercode smallint;
  v_posted citext;
  v_price numeric(12,2);
  v_tot_services integer;
  v_resultcode integer;
  v_servicecode integer;
  v_start_no integer;
  v_end_no integer;
  v_errcode integer;
  v_rowid integer;
  v_in_rowid integer;
  v_in_qty integer;
  v_tmpcode integer;
  _rc integer;
BEGIN
  v_serviceinvcode := serviceinvcode;
  v_usercode := usercode;
  -- SET NOCOUNT ON
  IF ((SELECT dbo.fn_getpreference('AutoGenSrvPurTempOnServicePosting')) = 'N') THEN
    return_value := 0;
    RETURN;
  END IF;
  IF (v_serviceinvcode IS NULL) THEN
    return_value := 0;
    RETURN;
  END IF;
  v_posted := coalesce((SELECT posted FROM dbo.serviceheader WHERE (serviceinvcode = v_serviceinvcode)), 'N');
  _rc := 1;
  IF ((v_posted = 'N') OR (v_posted IS NULL)) THEN
    return_value := 0;
    RETURN;
  END IF;
  IF (v_usercode IS NULL) THEN
    v_usercode := 1;
    _rc := 1;
  END IF;
  v_tmpcode := (SELECT count(ptd.servicecode) FROM dbo.serviceheader AS h, dbo.servicedetail AS d, dbo.servicepurtempheader AS pt, dbo.servicepurtempdetail AS ptd WHERE (((((h.serviceinvcode = v_serviceinvcode) AND (h.posted = 'Y')) AND (h.serviceinvcode = d.serviceinvcode)) AND (d.servicecode = pt.servicecode)) AND (pt.servicepurtempcode = ptd.servicepurtempcode)));
  _rc := 1;
  IF ((v_tmpcode <= 0) OR (v_tmpcode IS NULL)) THEN
    return_value := 0;
    RETURN;
  END IF;
  v_tmpcode := (SELECT count(ptd.servicecode) FROM dbo.servicedetail AS d, dbo.serviceinvpurtempdetail AS ptd WHERE ((d.serviceinvcode = v_serviceinvcode) AND (d.srvrowid = ptd.srvrowid)));
  _rc := 1;
  IF (v_tmpcode > 0) THEN
    return_value := 0;
    RETURN;
  END IF;
  INSERT INTO dbo.serviceinvpurtempheader (serviceinvcode, date, usercode, posted, postedby, postdate, remarks) SELECT v_serviceinvcode, localtimestamp(3), v_usercode, 'N' AS posted, NULL::smallint AS postedby, NULL::timestamp(3) AS postdate, 'Auto Generated Service Purchase Template' AS remarks;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((0 <> 0) OR (_rc <= 0)) THEN
    RAISE EXCEPTION 'Problem while Inserting Service Invoice Purchase Template Header Value';
    return_value := -1;
    RETURN;
  END IF;
  INSERT INTO dbo.serviceinvpurtempdetail (serviceinvcode, srvrowid, servicecode, suppcode, qty, pricerule, saleprice, salepriceperc, purprice, serviceflatdisc, discperc) SELECT v_serviceinvcode AS serviceinvcode, d.srvrowid AS srvrowid, ptd.servicecode AS servicecode, ptd.suppcode AS suppcode, (ptd.qty * d.qty) AS qty, ptd.pricerule AS pricerule, s.price AS saleprice, ptd.salepriceperc AS salepriceperc, CASE WHEN (ptd.pricerule = 1) THEN (((((d.price - d.serviceflatdisc)) * ((1 - (d.discperc * 0.01)))) * ptd.salepriceperc) * 0.01) ELSE ptd.purprice END AS purprice, ptd.serviceflatdisc AS serviceflatdisc, ptd.discperc AS discperc FROM dbo.serviceheader AS h, dbo.servicedetail AS d, dbo.service AS s, dbo.servicepurtempheader AS pt, dbo.servicepurtempdetail AS ptd WHERE ((((((h.serviceinvcode = v_serviceinvcode) AND (h.posted = 'Y')) AND (h.serviceinvcode = d.serviceinvcode)) AND (d.servicecode = pt.servicecode)) AND (pt.servicepurtempcode = ptd.servicepurtempcode)) AND (ptd.servicecode = s.servicecode)) ORDER BY h.serviceinvcode, d.srvrowid, ptd.rowid;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((0 <> 0) OR (_rc <= 0)) THEN
    RAISE EXCEPTION 'Problem while Inserting Service Result Detail Rows';
    return_value := -1;
    RETURN;
  END IF;
  IF ((SELECT dbo.fn_getpreference('AutoPostSrvPurTempOnServicePosting')) = 'N') THEN
    return_value := 0;
    RETURN;
  ELSE
    SELECT r.return_value INTO v_errcode FROM dbo.sp_autogeneratepurchaseofservice(serviceinvcode => v_serviceinvcode, usercode => v_usercode) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Problem while Generating Purchase of Service Invoices against Service Inv. # = %', v_serviceinvcode;
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_AutoGenerateServiceResult ====
CREATE OR REPLACE FUNCTION dbo.sp_autogenerateserviceresult(serviceinvcode integer, usercode smallint, INOUT serviceresultcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_serviceinvcode integer;
  v_usercode smallint;
  v_serviceresultcode integer;
  v_tot_services integer;
  v_resultcode integer;
  v_servicecode integer;
  v_patientcode integer;
  v_gestationcode smallint;
  v_posted citext;
  v_expiry timestamp(3);
  v_price numeric(12,2);
  v_start_ticket integer;
  v_end_ticket integer;
  v_errcode integer;
  v_rowid integer;
  v_in_rowid integer;
  v_in_qty integer;
  v_ticketcode integer;
  _r1 record;
  _rc integer;
BEGIN
  v_serviceinvcode := serviceinvcode;
  v_usercode := usercode;
  v_serviceresultcode := serviceresultcode;
  IF ((SELECT dbo.fn_getpreference('AutoGenResultOnServicePosting')) = 'N') THEN
    return_value := 0;
    serviceresultcode := v_serviceresultcode;
    RETURN;
  END IF;
  -- SET NOCOUNT ON
  DROP TABLE IF EXISTS tv_sp_autogenerateserviceresult_service_table;
  CREATE TEMP TABLE tv_sp_autogenerateserviceresult_service_table (
    servicecode integer,
    qty integer,
    expiry timestamp(3),
    price numeric(12,2),
    rowid integer GENERATED BY DEFAULT AS IDENTITY
) ON COMMIT DROP;
  IF (v_serviceinvcode IS NULL) THEN
    return_value := 0;
    serviceresultcode := v_serviceresultcode;
    RETURN;
  END IF;
  IF (v_usercode IS NULL) THEN
    v_usercode := 1;
    _rc := 1;
  END IF;
  v_posted := coalesce((SELECT posted FROM dbo.serviceheader WHERE (serviceinvcode = v_serviceinvcode)), 'N');
  _rc := 1;
  IF ((v_posted = 'N') OR (v_posted IS NULL)) THEN
    return_value := 0;
    serviceresultcode := v_serviceresultcode;
    RETURN;
  END IF;
  v_resultcode := (SELECT (SELECT max(srh.serviceresultcode) FROM dbo.serviceresultheader AS srh WHERE (serviceinvcode = v_serviceinvcode)) AS resultcode FROM dbo.serviceheader WHERE (((serviceinvcode = v_serviceinvcode) AND (posted = 'Y')) AND (serviceinvcode IN (SELECT srh.serviceinvcode FROM dbo.serviceresultheader AS srh WHERE (srh.serviceinvcode = v_serviceinvcode)))));
  _rc := 1;
  IF (v_resultcode >= 0) THEN
    return_value := 0;
    serviceresultcode := v_serviceresultcode;
    RETURN;
  END IF;
  v_tot_services := (SELECT (SELECT count(sd.servicecode) FROM dbo.servicedetail AS sd, dbo.service AS sv WHERE (((sd.serviceinvcode = v_serviceinvcode) AND (sd.servicecode = sv.servicecode)) AND (sv.resultrequired = 'Y'))) AS servicecount FROM dbo.serviceheader WHERE (((serviceinvcode = v_serviceinvcode) AND (posted = 'Y')) AND (serviceinvcode NOT IN (SELECT srh.serviceinvcode FROM dbo.serviceresultheader AS srh WHERE (srh.serviceinvcode = v_serviceinvcode)))));
  _rc := 1;
  IF ((v_tot_services <= 0) OR (v_tot_services IS NULL)) THEN
    return_value := 0;
    serviceresultcode := v_serviceresultcode;
    RETURN;
  END IF;
  _rc := 0;
  FOR _r1 IN SELECT p.patientcode AS c1, p.gestationcode AS c2 FROM dbo.patient AS p WHERE (p.patientcode IN (SELECT sh.patientcode AS patientcode FROM dbo.serviceheader AS sh WHERE (sh.serviceinvcode = v_serviceinvcode) UNION ALL SELECT pa.patientcode FROM dbo.patientadmission AS pa, dbo.serviceheader AS sh WHERE ((sh.serviceinvcode = v_serviceinvcode) AND (sh.admissioncode = pa.admissioncode)))) LOOP
    _rc := _rc + 1;
    v_patientcode := _r1.c1;
    v_gestationcode := _r1.c2;
  END LOOP;
  v_errcode := 0;
  _rc := 1;
  SELECT r.return_value, r.key INTO v_errcode, v_serviceresultcode FROM dbo.sp_locktabmaxkey(tabname => 'ServiceResultHeader', key => v_serviceresultcode) AS r;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem while Fetching Service Result Key Value';
    return_value := -1;
    serviceresultcode := v_serviceresultcode;
    RETURN;
  END IF;
  v_serviceresultcode := (v_serviceresultcode + 1);
  _rc := 1;
  INSERT INTO dbo.serviceresultheader (serviceresultcode, date, serviceinvcode, usercode, posted, postdate, postedby, remarks, serviceresultstampcode) SELECT v_serviceresultcode, localtimestamp(3), v_serviceinvcode, v_usercode, 'N' AS posted, NULL::timestamp(3) AS postdate, NULL::smallint AS postedby, NULL::citext AS remarks, 1 AS serviceresultstampcode;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((0 <> 0) OR (_rc <= 0)) THEN
    RAISE EXCEPTION 'Problem while Inserting Service Result Header Value';
    return_value := -1;
    serviceresultcode := v_serviceresultcode;
    RETURN;
  END IF;
  INSERT INTO dbo.serviceresultdetail (serviceresultcode, servicerowid, rowid, servicehead, servicecomponentcode, servicecomponentunitcode, testmachinecode, costprice, saleprice, componentvalue, lowerreferencevalue, upperreferencevalue, comments, remarks, componentvalue2, deliverydate, printonreport) SELECT v_serviceresultcode AS serviceresultcode, d.srvrowid AS srvrowid, sb.rowid AS rowid, sb.servicehead AS servicehead, sb.servicecomponentcode AS servicecomponentcode, (SELECT s.servicecomponentunitcode FROM dbo.servicecomponent AS s WHERE (s.servicecomponentcode = sb.servicecomponentcode)) AS servicecomponentunitcode, 1 AS testmachinecode, sb.costprice AS costprice, sb.saleprice AS saleprice, CASE WHEN (s.serviceresulttemplate IS NULL) THEN NULL ELSE (SELECT max(srd.componentvalue) FROM dbo.serviceresultdetail AS srd WHERE ((srd.serviceresultcode = s.serviceresulttemplate) AND (srd.servicecomponentcode = sb.servicecomponentcode))) END AS componentvalue, CASE WHEN (s.serviceresulttemplate IS NULL) THEN NULL ELSE (SELECT max(srd.lowerreferencevalue) FROM dbo.serviceresultdetail AS srd WHERE ((srd.serviceresultcode = s.serviceresulttemplate) AND (srd.servicecomponentcode = sb.servicecomponentcode))) END AS lowerreferencevalue, CASE WHEN (s.serviceresulttemplate IS NULL) THEN NULL ELSE (SELECT max(srd.upperreferencevalue) FROM dbo.serviceresultdetail AS srd WHERE ((srd.serviceresultcode = s.serviceresulttemplate) AND (srd.servicecomponentcode = sb.servicecomponentcode))) END AS upperreferencevalue, CASE WHEN (s.serviceresulttemplate IS NULL) THEN NULL ELSE (SELECT max(srd.comments) FROM dbo.serviceresultdetail AS srd WHERE ((srd.serviceresultcode = s.serviceresulttemplate) AND (srd.servicecomponentcode = sb.servicecomponentcode))) END AS comments, CASE WHEN (s.serviceresulttemplate IS NULL) THEN NULL ELSE (SELECT max(srd.remarks) FROM dbo.serviceresultdetail AS srd WHERE ((srd.serviceresultcode = s.serviceresulttemplate) AND (srd.servicecomponentcode = sb.servicecomponentcode))) END AS remarks, CASE WHEN (s.serviceresulttemplate IS NULL) THEN NULL ELSE (SELECT max(srd.componentvalue2) FROM dbo.serviceresultdetail AS srd WHERE ((srd.serviceresultcode = s.serviceresulttemplate) AND (srd.servicecomponentcode = sb.servicecomponentcode))) END AS componentvalue2, d.deliverydate AS deliverydate, sb.printonreport AS printonreport FROM dbo.serviceheader AS h, dbo.servicedetail AS d, dbo.service AS s, dbo.servicebreakup AS sb WHERE (((((h.serviceinvcode = v_serviceinvcode) AND (h.serviceinvcode = d.serviceinvcode)) AND (d.servicecode = s.servicecode)) AND (s.resultrequired = 'Y')) AND (s.servicecode = sb.servicecode)) ORDER BY d.srvrowid, sb.servicehead, rowid;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((0 <> 0) OR (_rc <= 0)) THEN
    RAISE EXCEPTION 'Problem while Inserting Service Result Detail Rows';
    return_value := -1;
    serviceresultcode := v_serviceresultcode;
    RETURN;
  END IF;
  v_errcode := 0;
  _rc := 1;
  SELECT r.return_value INTO v_errcode FROM dbo.sp_updatetabmaxkey(tabname => 'ServiceResultHeader', key => v_serviceresultcode) AS r;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem while Updating Service Result Key Value';
    return_value := -1;
    serviceresultcode := v_serviceresultcode;
    RETURN;
  END IF;
  return_value := 0;
  serviceresultcode := v_serviceresultcode;
  RETURN;
END
$body$;

-- ==== proc sp_AutoIssueConsumableItem ====
CREATE OR REPLACE FUNCTION dbo.sp_autoissueconsumableitem(serviceissuerequestcode integer, usercode integer, INOUT issueinvcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_serviceissuerequestcode integer;
  v_usercode integer;
  v_issueinvcode integer;
  v_code integer;
  v_deptcode integer;
  v_module smallint;
  v_utn integer;
  v_headerinvno integer;
  v_headerno integer;
  v_servicerowid integer;
  v_serviceinvcode integer;
  v_category smallint;
  v_issuecode integer;
  v_dracccode smallint;
  v_accountfor citext;
  v_issuetype smallint;
  v_pricetype smallint;
  v_groupcode smallint;
  v_icode integer;
  v_gcode integer;
  v_packunits integer;
  v_areacode integer;
  v_totgodown integer;
  v_rowid integer;
  v_consumableqty numeric(15,4);
  v_totalqty numeric(15,4);
  v_currqty numeric(15,4);
  v_delqty numeric(15,4);
  v_batchqty numeric(15,4);
  v_reqqty numeric(15,4);
  v_newqty numeric(15,4);
  v_availableqty numeric(15,4);
  v_price numeric(8,2);
  v_purprice numeric(8,2);
  v_saleprice numeric(8,2);
  v_hold_avgprice numeric(11,5);
  v_recentpurprice numeric(8,2);
  v_batch citext;
  v_itemname citext;
  v_invposted citext;
  v_total_availablestock numeric(15,4);
  v_items_rows integer;
  v_counter integer;
  v_rowcount integer;
  v_totalrows integer;
  v_continue integer;
  v_err integer;
  v_rt_code integer;
  v_consumableitemcount integer;
  v_serverdate timestamp(3);
  v_expiry timestamp(3);
  cur_cursor_consumableitems refcursor;
  cur_itembatch_cursor refcursor;
  _rc integer;
  _fs integer := -1;
BEGIN
  v_serviceissuerequestcode := serviceissuerequestcode;
  v_usercode := usercode;
  v_issueinvcode := issueinvcode;
  DROP TABLE IF EXISTS tv_sp_autoissueconsumableitem_godownlist;
  CREATE TEMP TABLE tv_sp_autoissueconsumableitem_godownlist (
    code smallint,
    growid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL
) ON COMMIT DROP;
  v_continue := 0;
  _rc := 1;
  v_deptcode := 1;
  _rc := 1;
  v_areacode := 1;
  _rc := 1;
  v_serverdate := (SELECT localtimestamp(3));
  _rc := 1;
  v_serviceinvcode := coalesce((SELECT max(serviceinvcode) FROM dbo.serviceissuerequest WHERE (serviceissuerequestcode = v_serviceissuerequestcode)), 0);
  _rc := 1;
  v_consumableitemcount := coalesce((SELECT count(d.icode) FROM dbo.serviceissuerequestdetail AS d, dbo.serviceissuerequest AS h WHERE ((h.serviceissuerequestcode = v_serviceissuerequestcode) AND (h.serviceissuerequestcode = d.serviceissuerequestcode))), 0);
  _rc := 1;
  IF (v_consumableitemcount <= 0) THEN
    return_value := 0;
    issueinvcode := v_issueinvcode;
    RETURN;
  END IF;
  v_module := (SELECT module FROM dbo.module WHERE ((lower(name))::citext = 'issue'));
  _rc := 1;
  IF ((v_module <= 0) OR (v_module IS NULL)) THEN
    RAISE EXCEPTION 'Error occured While Fetching Issue Module Information';
    return_value := -1;
    issueinvcode := v_issueinvcode;
    RETURN;
  END IF;
  v_pricetype := dbo.fn_get_int_preference('IssuePriceTypeCode');
  _rc := 1;
  IF ((v_pricetype <= 0) OR (v_pricetype IS NULL)) THEN
    RAISE EXCEPTION 'Error occured While Fetching Issue Module Price Ttype Information';
    return_value := -1;
    issueinvcode := v_issueinvcode;
    RETURN;
  END IF;
  v_groupcode := dbo.fn_getgroupcode((v_usercode)::smallint);
  _rc := 1;
  IF ((v_groupcode <= 0) OR (v_groupcode IS NULL)) THEN
    RAISE EXCEPTION 'Error occured While Fetching Group Information for the user triggered this event';
    return_value := -1;
    issueinvcode := v_issueinvcode;
    RETURN;
  END IF;
  v_gcode := dbo.fn_getgodown(v_groupcode, v_module);
  _rc := 1;
  IF ((v_gcode <= 0) OR (v_gcode IS NULL)) THEN
    RAISE EXCEPTION 'You have No Allowed Godown for Issue Module';
    return_value := -1;
    issueinvcode := v_issueinvcode;
    RETURN;
  END IF;
  v_headerno := dbo.fn_getheader(v_groupcode, v_module);
  _rc := 1;
  IF ((v_headerno <= 0) OR (v_headerno IS NULL)) THEN
    RAISE EXCEPTION 'You have No Allowed Header for Issue Module';
    return_value := -1;
    issueinvcode := v_issueinvcode;
    RETURN;
  END IF;
  INSERT INTO tv_sp_autoissueconsumableitem_godownlist (code) SELECT code FROM dbo.fn_getavailablegodown(v_groupcode, v_module) AS fn_getavailablegodown ORDER BY rowid;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_totgodown := coalesce((SELECT count(code) FROM tv_sp_autoissueconsumableitem_godownlist AS godownlist), 0);
  _rc := 1;
  IF ((v_totgodown = 0) OR (v_totgodown IS NULL)) THEN
    RAISE EXCEPTION 'You have No Allowed Godown for Issue Module';
    return_value := -1;
    issueinvcode := v_issueinvcode;
    RETURN;
  END IF;
  v_category := 2;
  _rc := 1;
  v_accountfor := coalesce((SELECT accountfor FROM dbo.issuecategory WHERE (issuecategorycode = v_category)), 'N');
  _rc := 1;
  IF (v_accountfor = 'Y') THEN
    v_dracccode := trunc(coalesce((SELECT code FROM dbo.global WHERE (name = 'GT_WIPAcc')), 33))::smallint;
    _rc := 1;
  ELSE
    v_dracccode := NULL;
    _rc := 1;
  END IF;
  OPEN cur_cursor_consumableitems FOR SELECT d.servicerowid AS servicerowid, d.icode AS icode, d.rowid AS rowid, coalesce(sum(d.qty), 0) AS consumeableqty, coalesce((SELECT sum(gd.currqty) FROM dbo.godowndetail AS gd WHERE ((gd.icode = d.icode) AND (gd.gcode IN (SELECT code FROM tv_sp_autoissueconsumableitem_godownlist AS godownlist)))), 0) AS availableqty, i.packunits AS packunits, round(((i.purprice / i.packunits))::numeric, 2) AS purprice, round(((i.saleprice / i.packunits))::numeric, 2) AS saleprice, round(((i.recentpurprice / i.packunits))::numeric, 2) AS recentpurprice, (CASE v_pricetype WHEN 1 THEN round(((i.saleprice / i.packunits))::numeric, 2) WHEN 2 THEN round(((i.saleprice2 / i.packunits))::numeric, 2) WHEN 3 THEN round(((i.saleprice3 / i.packunits))::numeric, 2) WHEN 4 THEN round(((i.purprice / i.packunits))::numeric, 2) WHEN 5 THEN round(((i.recentpurprice / i.packunits))::numeric, 2) WHEN 6 THEN round((i.avgprice)::numeric, 2) WHEN 7 THEN round(((i.saleprice4 / i.packunits))::numeric, 2) WHEN 8 THEN round(((i.saleprice5 / i.packunits))::numeric, 2) END + d.processcharge) AS price FROM dbo.serviceissuerequestdetail AS d, dbo.serviceissuerequest AS h, dbo.item AS i WHERE (((h.serviceissuerequestcode = v_serviceissuerequestcode) AND (h.serviceissuerequestcode = d.serviceissuerequestcode)) AND (d.icode = i.icode)) GROUP BY d.servicerowid, d.icode, d.rowid, i.packunits, i.purprice, i.saleprice, i.saleprice2, i.saleprice3, i.saleprice4, i.saleprice5, i.recentpurprice, i.avgprice, d.processcharge ORDER BY d.rowid;
  v_items_rows := (-1);
  _rc := 1;
  IF (v_items_rows > 0) THEN
    SELECT r.return_value, r.key INTO v_rt_code, v_code FROM dbo.sp_gettabmaxkey(tabname => 'IssueHeader', key => v_code) AS r;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      v_continue := -1;
      _rc := 1;
    ELSE
      v_issueinvcode := v_code;
      _rc := 1;
      SELECT r.return_value, r.key INTO v_rt_code, v_headerinvno FROM dbo.sp_getheadertabmaxkey(headercode => (v_headerno)::smallint, modulecode => v_module, key => v_headerinvno) AS r;
      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
        v_continue := -1;
        _rc := 1;
      ELSE
        v_issuecode := NULL;
        _rc := 1;
        SELECT r.return_value, r.counter INTO v_rt_code, v_issuecode FROM dbo.sp_getissuecategorycounter(category => v_category, counter => v_issuecode) AS r;
        IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
          v_continue := -1;
          _rc := 1;
        ELSE
          INSERT INTO dbo.issueheader (issueinvcode, deptcode, date, originaldate, salesmancode, posted, postdate, postedby, areacode, headerno, headerinvno, pricetypecode, remarks, serviceissuerequestcode, serviceinvcode, issuecategorycode, accountfor, dracccode, issuecode) VALUES (v_code, v_deptcode, v_serverdate, v_serverdate, v_usercode, 'Y', v_serverdate, v_usercode, v_areacode, v_headerno, v_headerinvno, v_pricetype, ('SYS. GEN. ISSUE FOR ITEMS CONSUMED AGAINST SVC. INV. #: ' || ltrim(rtrim(dbo.tsql_str((v_serviceinvcode)::numeric, 10)))), v_serviceissuerequestcode, v_serviceinvcode, v_category, v_accountfor, v_dracccode, v_issuecode);
          GET DIAGNOSTICS _rc = ROW_COUNT;
          v_err := 0;
          v_rowcount := _rc;
          _rc := 1;
          IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
            RAISE EXCEPTION 'Error occured in inserting record into Issue Header : %', v_code;
            v_continue := -1;
            _rc := 1;
          ELSE
            FETCH NEXT FROM cur_cursor_consumableitems INTO v_servicerowid, v_icode, v_rowid, v_consumableqty, v_availableqty, v_packunits, v_purprice, v_saleprice, v_recentpurprice, v_price;
            IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
            WHILE ((_fs = 0) AND (v_continue >= 0)) LOOP
              SELECT r.return_value, r.avgprice INTO v_rt_code, v_hold_avgprice FROM dbo.sp_getitemavgprice(icode => v_icode, avgprice => v_hold_avgprice) AS r;
              IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                v_continue := -1;
                _rc := 1;
              ELSE
                v_total_availablestock := (SELECT coalesce(sum(currqty), 0) FROM dbo.godowndetail WHERE (godowndetail.icode = v_icode));
                _rc := 1;
                IF ((v_total_availablestock < 0) OR (v_total_availablestock IS NULL)) THEN
                  v_total_availablestock := 0;
                  _rc := 1;
                END IF;
                v_packunits := CASE WHEN (v_packunits IS NULL) THEN 1 WHEN (v_packunits = 0) THEN 1 ELSE v_packunits END;
                _rc := 1;
                v_totalqty := (SELECT coalesce(sum(currqty), 0) FROM dbo.godowndetail WHERE ((godowndetail.gcode IN (SELECT code FROM tv_sp_autoissueconsumableitem_godownlist AS godownlist)) AND (godowndetail.icode = v_icode)));
                _rc := 1;
                IF (v_totalqty >= v_consumableqty) THEN
                  v_reqqty := v_consumableqty;
                  _rc := 1;
                  OPEN cur_itembatch_cursor FOR SELECT gd.gcode, gd.batch, gd.expiry, gd.currqty FROM dbo.godowndetail AS gd, (SELECT code AS gcode, growid FROM tv_sp_autoissueconsumableitem_godownlist AS godownlist) AS g WHERE ((gd.gcode = g.gcode) AND (gd.icode = v_icode)) ORDER BY g.growid, gd.gcode, gd.priority, gd.expiry, gd.currqty;
                  v_totalrows := (-1);
                  _rc := 1;
                  FETCH NEXT FROM cur_itembatch_cursor INTO v_gcode, v_batch, v_expiry, v_currqty;
                  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
                  v_counter := 1;
                  _rc := 1;
                  WHILE (((_fs = 0) AND (v_counter <= v_totalrows)) AND (v_reqqty > 0)) LOOP
                    v_batchqty := v_currqty;
                    _rc := 1;
                    IF (v_batchqty >= v_reqqty) THEN
                      v_delqty := v_reqqty;
                      _rc := 1;
                    ELSE
                      v_delqty := v_batchqty;
                      _rc := 1;
                    END IF;
                    v_reqqty := (v_reqqty - v_delqty);
                    _rc := 1;
                    SELECT r.return_value, r.lbi_maxutn INTO v_rt_code, v_utn FROM dbo.sp_maxutn(lbi_rows => (1)::bigint, lbi_maxutn => (v_utn)::bigint) AS r;
                    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                      v_continue := -1;
                      _rc := 1;
                    END IF;
                    v_total_availablestock := (v_total_availablestock - v_delqty);
                    _rc := 1;
                    INSERT INTO dbo.issuedetail (issueinvcode, gcode, icode, batch, expiry, qty, saleprice, purchaseprice, avgprice, packunits, mrpp, issueutn, price, serviceissuereqrowid, servicerowid, balancestock) VALUES (v_code, v_gcode, v_icode, v_batch, v_expiry, v_delqty, v_saleprice, v_purprice, v_hold_avgprice, v_packunits, v_recentpurprice, v_utn, v_price, v_rowid, v_servicerowid, v_total_availablestock);
                    GET DIAGNOSTICS _rc = ROW_COUNT;
                    v_err := 0;
                    v_rowcount := _rc;
                    _rc := 1;
                    IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
                      RAISE EXCEPTION 'Error occured in inserting record into Issue Detail for Service Issue Request Code : %', v_code;
                      v_continue := -1;
                      _rc := 1;
                    ELSE
                      v_newqty := (v_currqty - v_delqty);
                      _rc := 1;
                      IF (v_newqty > 0) THEN
                        SELECT r.return_value INTO v_rt_code FROM dbo.sp_saleupdateitemstockbatch(gcode => v_gcode, icode => v_icode, batch => v_batch, expiry => v_expiry, newqty => v_newqty, oldqty => v_currqty) AS r;
                      ELSE
                        SELECT r.return_value INTO v_rt_code FROM dbo.sp_deleteitemstockbatch(gcode => v_gcode, icode => v_icode, batch => v_batch, expiry => v_expiry, oldqty => v_delqty) AS r;
                      END IF;
                      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                        v_continue := -1;
                        _rc := 1;
                      END IF;
                    END IF;
                    v_counter := (v_counter + 1);
                    _rc := 1;
                    FETCH NEXT FROM cur_itembatch_cursor INTO v_gcode, v_batch, v_expiry, v_currqty;
                    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
                  END LOOP;
                  CLOSE cur_itembatch_cursor;
                  -- DEALLOCATE ItemBatch_Cursor
                ELSE
                  v_itemname := (SELECT name FROM dbo.item WHERE (icode = v_icode));
                  _rc := 1;
                  RAISE EXCEPTION 'Not enough stock for item (%) to decrease for Issue No. : %', v_itemname, v_code;
                  v_continue := -1;
                  _rc := 1;
                END IF;
              END IF;
              FETCH NEXT FROM cur_cursor_consumableitems INTO v_servicerowid, v_icode, v_rowid, v_consumableqty, v_availableqty, v_packunits, v_purprice, v_saleprice, v_recentpurprice, v_price;
              IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
            END LOOP;
          END IF;
        END IF;
      END IF;
    END IF;
  ELSE
    RAISE EXCEPTION 'Not enough stock exists for some of the consumable items for Issue No. : %', v_code;
    v_continue := -1;
    _rc := 1;
  END IF;
  CLOSE cur_cursor_consumableitems;
  -- DEALLOCATE Cursor_ConsumableItems
  IF (v_continue <> 0) THEN
    return_value := -1;
    issueinvcode := v_issueinvcode;
    RETURN;
  ELSE
    return_value := 0;
    issueinvcode := v_issueinvcode;
    RETURN;
  END IF;
  return_value := 0;
  issueinvcode := v_issueinvcode;
  RETURN;
END
$body$;

-- ==== proc SP_AutoLoyaltyRedemption ====
CREATE OR REPLACE FUNCTION dbo.sp_autoloyaltyredemption(acccode integer, pointsredeemed integer, redemptionvalue numeric, documentcode integer, documnttype citext, usercode smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_acccode integer;
  v_pointsredeemed integer;
  v_redemptionvalue numeric(12,2);
  v_documentcode integer;
  v_documnttype citext;
  v_usercode smallint;
  v_loyaltyredemptioncode integer;
  v_errcode integer;
  v_rowid integer;
  v_in_rowid integer;
  v_in_qty integer;
  v_tmpcode integer;
  v_remarks citext;
  v_balancedate timestamp(3);
  v_layaltypointsbalance integer;
  v_layaltypointsvalue numeric(12,2);
  v_loyaltycardcode integer;
  _rc integer;
BEGIN
  v_acccode := acccode;
  v_pointsredeemed := pointsredeemed;
  v_redemptionvalue := redemptionvalue;
  v_documentcode := documentcode;
  v_documnttype := documnttype;
  v_usercode := usercode;
  -- SET NOCOUNT ON
  v_errcode := 0;
  _rc := 1;
  SELECT r.return_value, r.key INTO v_errcode, v_loyaltyredemptioncode FROM dbo.sp_locktabmaxkey(tabname => 'LoyaltyRedemption', key => v_loyaltyredemptioncode) AS r;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem while Fetching Loyalty Redemption Code';
    return_value := -1;
    RETURN;
  END IF;
  v_loyaltyredemptioncode := (v_loyaltyredemptioncode + 1);
  _rc := 1;
  v_remarks := 'Auto Points Redeemed';
  _rc := 1;
  IF (v_documnttype = 'SV') THEN
    v_remarks := ((v_remarks || ' via Sale Inv. Code ') || ltrim(rtrim(dbo.tsql_str((v_documentcode)::numeric))));
    _rc := 1;
  END IF;
  IF (v_usercode IS NULL) THEN
    v_usercode := 1;
    _rc := 1;
  END IF;
  v_loyaltycardcode := (SELECT min(lc.loyaltycardcode) FROM dbo.loyaltycard AS lc WHERE (lc.acccode = v_acccode));
  _rc := 1;
  v_balancedate := localtimestamp(3);
  _rc := 1;
  v_errcode := 0;
  _rc := 1;
  SELECT r.return_value, r.layaltypointsbalance, r.layaltypointsvalue INTO v_errcode, v_layaltypointsbalance, v_layaltypointsvalue FROM dbo.sp_getaccountloyaltybalance(acccode => v_acccode, balancedate => v_balancedate, layaltypointsbalance => v_layaltypointsbalance, layaltypointsvalue => v_layaltypointsvalue) AS r;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem while Fetching Account Loyalty Balance Info.';
    return_value := -1;
    RETURN;
  END IF;
  INSERT INTO dbo.loyaltyredemption (loyaltyredemptioncode, loyaltycardcode, date, usercode, pointsbalance, pointsredeemed, pointsvalue, remarks) SELECT v_loyaltyredemptioncode, v_loyaltycardcode, localtimestamp(3) AS date, v_usercode, v_layaltypointsbalance, v_pointsredeemed, v_redemptionvalue, v_remarks;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF (_rc = 0) THEN
    return_value := 0;
    RETURN;
  END IF;
  SELECT r.return_value INTO v_errcode FROM dbo.sp_updatetabmaxkey(tabname => 'LoyaltyRedemption', key => v_loyaltyredemptioncode) AS r;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem while Updating Loyalty Redemption Key Value';
    return_value := -1;
    RETURN;
  END IF;
  SELECT r.return_value INTO v_errcode FROM dbo.sp_manageloyaltypoints(invtype => 'RD', invoicecode => v_loyaltyredemptioncode) AS r;
  return_value := v_errcode;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_autopost_visit ====
CREATE OR REPLACE FUNCTION dbo.sp_autopost_visit(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_age integer;
BEGIN
  v_age := dbo.fn_get_int_preference('VisitAutoPostTime');
  UPDATE dbo.visit SET posted = 'Y' WHERE ((dbo.tsql_datediff('minute', date, localtimestamp(3)) >= v_age) AND (posted = 'N'));
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_autopost_visitappointment ====
CREATE OR REPLACE FUNCTION dbo.sp_autopost_visitappointment(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_age integer;
  v_appointmentcode integer;
BEGIN
  v_age := dbo.fn_get_int_preference('VisitAppointmentAutoPostTime');
  UPDATE dbo.visitappointment SET posted = 'Y' WHERE ((dbo.tsql_datediff('minute', date, localtimestamp(3)) >= v_age) AND (posted = 'N'));
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_autosaleposting ====
CREATE OR REPLACE FUNCTION dbo.sp_autosaleposting(salecategory integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_salecategory integer;
  v_invoiceage integer;
  v_custcode integer;
  v_saleinvcode integer;
  v_balance numeric(15,5);
  v_dt timestamp(3);
  v_savebal citext;
  cur_saleposting_cursor refcursor;
  _fs integer := -1;
BEGIN
  v_salecategory := salecategory;
  IF (v_salecategory = 3) THEN
    v_invoiceage := dbo.fn_get_int_preference('cashsaleautopostingtime');
  ELSE
    v_invoiceage := dbo.fn_get_int_preference('creditsaleautopostingtime');
  END IF;
  v_savebal := dbo.fn_getpreference('SaveBalanceOnSalePosting');
  -- BEGIN TRANSACTION (the caller owns the transaction)
  OPEN cur_saleposting_cursor FOR SELECT saleinvcode FROM dbo.saleledger JOIN dbo.customer AS c ON (saleledger.custcode = c.custcode) WHERE ((((dbo.tsql_datediff('minute', originaldate, localtimestamp(3)) >= v_invoiceage) AND (posted = 'N')) AND (salecatcode = v_salecategory)) AND (c.schedforposting = 'Y')) FOR UPDATE OF saleledger;
  FETCH NEXT FROM cur_saleposting_cursor INTO v_saleinvcode;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    v_custcode := 0;
    v_balance := 0;
    IF ((v_savebal = 'Y') AND (v_salecategory <> 3)) THEN
      v_custcode := (SELECT custcode FROM dbo.saleledger WHERE (saleinvcode = v_saleinvcode));
      v_dt := localtimestamp(3);
      SELECT r.bal INTO v_balance FROM dbo.sp_openingbalance(acccode => v_custcode, datetime => v_dt, bal => v_balance) AS r;
    END IF;
    UPDATE dbo.saleledger SET posted = 'Y', postdate = localtimestamp(3), postedby = 1, balance = v_balance WHERE (saleinvcode = v_saleinvcode);
    FETCH NEXT FROM cur_saleposting_cursor INTO v_saleinvcode;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  IF (0 = 0) THEN
    -- COMMIT (the caller owns the transaction)
  ELSE
    RAISE EXCEPTION 'T-SQL ROLLBACK in sp_AutoSalePosting' USING ERRCODE = 'TS001';
  END IF;
  CLOSE cur_saleposting_cursor;
  -- DEALLOCATE saleposting_cursor
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_AutoSatisfyDue ====
CREATE OR REPLACE FUNCTION dbo.sp_autosatisfydue(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_dueadjcode integer;
  v_totalrows integer;
  v_continue integer;
  v_counter integer;
  v_icode integer;
  v_oldicode integer;
  v_gcode smallint;
  v_totstock numeric(15,4);
  v_satisfiableqty numeric(15,4);
  v_rt_code integer;
  v_err_string citext;
  v_itemname citext;
  v_err integer;
  v_rowcount integer;
  v_serverdate timestamp(3);
  v_usercode integer;
  _rc integer;
BEGIN
  v_usercode := 1;
  _rc := 1;
  v_serverdate := localtimestamp(3);
  _rc := 1;
  v_continue := 0;
  _rc := 1;
  DROP TABLE IF EXISTS tv_sp_autosatisfydue_temp_table;
  CREATE TEMP TABLE tv_sp_autosatisfydue_temp_table (
    saleinvcode integer,
    itemname citext,
    icode integer,
    gcode smallint,
    salerowid integer,
    dueqty numeric(15,4),
    satisfiedqty numeric(15,4),
    stock numeric(15,4),
    satisfiableqty numeric(15,4),
    selected citext,
    rowid integer GENERATED BY DEFAULT AS IDENTITY
) ON COMMIT DROP;
  INSERT INTO tv_sp_autosatisfydue_temp_table (saleinvcode, itemname, icode, gcode, salerowid, dueqty, satisfiedqty, stock, satisfiableqty, selected) SELECT saleinvcode, itemname, icode, gcode, salerowid, dueqty, satisfiedqty, stock, coalesce((dueqty - satisfiedqty), 0) AS satisfiableqty, 'N' AS selected FROM (SELECT sl.saleinvcode AS saleinvcode, i.name AS itemname, sd.icode AS icode, sd.gcode AS gcode, sd.rowid AS salerowid, sd.looseqty AS dueqty, coalesce((SELECT sum(dsd.duesatisfyqty) FROM dbo.duesatisfyheader AS dsh, dbo.duesatisfydetail AS dsd WHERE ((((dsh.saleinvcode = sl.saleinvcode) AND (dsh.duesatisfycode = dsd.duesatisfycode)) AND (dsd.icode = sd.icode)) AND (dsd.salerowid = sd.rowid))), 0) AS satisfiedqty, coalesce((SELECT sum(gd.currqty) FROM dbo.godowndetail AS gd WHERE ((gd.icode = sd.icode) AND (sd.gcode = gd.gcode))), 0) AS stock FROM dbo.saleledger AS sl, dbo.saledetail AS sd, dbo.item AS i, (SELECT DISTINCT icode, gcode FROM dbo.godowndetail WHERE (gcode IN (SELECT g.gcode FROM dbo.godown AS g WHERE (g.autosatisfydue = 'Y')))) AS p WHERE ((((((sl.saleinvcode = sd.saleinvcode) AND (sl.posted = 'Y')) AND (sd.icode = i.icode)) AND (sd.due = 'D')) AND (sd.icode = p.icode)) AND (sd.gcode = p.gcode))) AS t WHERE ((((t.dueqty - t.satisfiedqty)) > 0) AND (t.stock > 0)) ORDER BY t.itemname, t.saleinvcode;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_totalrows := coalesce((SELECT count(*) FROM tv_sp_autosatisfydue_temp_table AS temp_table), 0);
  _rc := 1;
  v_counter := 1;
  _rc := 1;
  v_oldicode := -1;
  _rc := 1;
  WHILE ((v_totalrows > 0) AND (v_counter <= v_totalrows)) LOOP
    v_icode := (SELECT icode FROM tv_sp_autosatisfydue_temp_table AS temp_table WHERE (rowid = v_counter));
    _rc := 1;
    IF (v_icode <> v_oldicode) THEN
      v_oldicode := v_icode;
      _rc := 1;
      v_totstock := coalesce((SELECT stock FROM tv_sp_autosatisfydue_temp_table AS temp_table WHERE (rowid = v_counter)), 0);
      _rc := 1;
    END IF;
    IF (v_totstock > 0) THEN
      v_satisfiableqty := (SELECT satisfiableqty FROM tv_sp_autosatisfydue_temp_table AS temp_table WHERE (rowid = v_counter));
      _rc := 1;
      UPDATE tv_sp_autosatisfydue_temp_table AS temp_table SET stock = v_totstock WHERE (rowid = v_counter);
      GET DIAGNOSTICS _rc = ROW_COUNT;
      IF (v_satisfiableqty <= v_totstock) THEN
        v_totstock := (v_totstock - v_satisfiableqty);
        _rc := 1;
      ELSE
        UPDATE tv_sp_autosatisfydue_temp_table AS temp_table SET satisfiableqty = v_totstock WHERE (rowid = v_counter);
        GET DIAGNOSTICS _rc = ROW_COUNT;
        v_totstock := 0;
        _rc := 1;
      END IF;
      UPDATE tv_sp_autosatisfydue_temp_table AS temp_table SET selected = 'Y' WHERE (rowid = v_counter);
      GET DIAGNOSTICS _rc = ROW_COUNT;
    END IF;
    v_counter := (v_counter + 1);
    _rc := 1;
  END LOOP;
  DELETE FROM tv_sp_autosatisfydue_temp_table AS temp_table WHERE (selected = 'N');
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_totalrows := coalesce((SELECT count(*) FROM tv_sp_autosatisfydue_temp_table AS temp_table), 0);
  _rc := 1;
  IF (v_totalrows > 0) THEN
    SELECT r.return_value, r.key INTO v_rt_code, v_dueadjcode FROM dbo.sp_gettabmaxkey(tabname => 'DueAdjHeader', key => v_dueadjcode) AS r;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      v_continue := -1;
      _rc := 1;
      RAISE EXCEPTION 'Unable to Generate New Due Adjustment code';
    ELSE
      INSERT INTO dbo.dueadjheader (dueadjcode, date, startdate, enddate, remarks, usercode) VALUES (v_dueadjcode, v_serverdate, ('01-01-1990 00:00:00')::timestamp(3), localtimestamp(3), 'Due Satisfied Via Auto Due Satisfy Job', v_usercode);
      GET DIAGNOSTICS _rc = ROW_COUNT;
      INSERT INTO dbo.dueadjdetail (dueadjcode, saleinvcode, icode, gcode, salerowid, dueqty, satisfiedqty, satisfiableqty, duedelete) SELECT v_dueadjcode, saleinvcode, icode, gcode, salerowid, dueqty, satisfiedqty, satisfiableqty, 'N' AS duedelete FROM tv_sp_autosatisfydue_temp_table AS temp_table;
      GET DIAGNOSTICS _rc = ROW_COUNT;
      v_err := 0;
      v_rowcount := _rc;
      _rc := 1;
      IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
        RAISE EXCEPTION 'Error occured in inserting record into Due Adjustment Detail';
        v_continue := -1;
        _rc := 1;
      END IF;
      IF (v_continue >= 0) THEN
        SELECT r.return_value INTO v_rt_code FROM dbo.sp_satisfydueinbulk(dueadjcode => v_dueadjcode, usercode => v_usercode, serverdate => v_serverdate) AS r;
        IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
          v_continue := -1;
          _rc := 1;
          RAISE EXCEPTION 'Unable to Generate New Due Adjustment code';
        END IF;
      END IF;
    END IF;
  END IF;
  return_value := v_continue;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_AutoStockVerification ====
CREATE OR REPLACE FUNCTION dbo.sp_autostockverification(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
BEGIN
  INSERT INTO dbo.items_corrupted SELECT localtimestamp(3), tot.icode, item.name, sum(CASE WHEN (tot.type = 'ST') THEN tot.netqty ELSE 0 END) AS stock, sum(CASE WHEN (tot.type <> 'ST') THEN tot.netqty ELSE 0 END) AS netqty FROM (SELECT icode, sum(((packqty * packunits) + (bonusqty * packunits))) AS netqty, 'PU' AS type FROM dbo.purdetail, dbo.purledger WHERE (((purledger.purcatcode IN (1, 2)) AND (purledger.purinvcode = purdetail.purinvcode)) AND (posted = (upper('Y'))::citext)) GROUP BY icode UNION ALL SELECT icode, sum((looseqty + bonusqty)) AS netqty, 'PU' AS type FROM dbo.purdetail, dbo.purledger WHERE (((purledger.purcatcode IN (3, 7, 8)) AND (purledger.purinvcode = purdetail.purinvcode)) AND (posted = (upper('Y'))::citext)) GROUP BY icode UNION ALL SELECT icode, (-sum((looseqty + bonusqty))) AS netqty, 'PR' AS type FROM dbo.prdetail GROUP BY icode UNION ALL SELECT icode, (-sum((looseqty + bonusqty))) AS netqty, 'SL' AS type FROM dbo.saledetail WHERE (due IS NULL) GROUP BY icode UNION ALL SELECT icode, sum((looseqty + bonusqty)) AS netqty, 'SR' AS type FROM dbo.srdetail GROUP BY icode UNION ALL SELECT icode, (-sum(qty)) AS netqty, 'IS' AS type FROM dbo.issuedetail, dbo.issueheader WHERE (issueheader.issueinvcode = issuedetail.issueinvcode) GROUP BY icode UNION ALL SELECT icode, (-sum(duesatisfyqty)) AS netqty, 'DS' AS type FROM dbo.duesatisfydetail GROUP BY icode UNION ALL SELECT icode, sum(qty) AS netqty, 'DS' AS type FROM dbo.receiptheader, dbo.receiptdetail WHERE ((receiptheader.posted = 'Y') AND (receiptheader.receiptinvcode = receiptdetail.receiptinvcode)) GROUP BY icode UNION ALL SELECT icode, sum(looseqty) AS netqty, 'AI' AS type FROM dbo.adjheader, dbo.adjdetail WHERE (((adjheader.posted = 'Y') AND (adjheader.adjcatcode = 1)) AND (adjheader.adjcode = adjdetail.adjcode)) GROUP BY icode UNION ALL SELECT icode, (-sum(looseqty)) AS netqty, 'AD' AS type FROM dbo.adjheader, dbo.adjdetail WHERE (((adjheader.posted = 'Y') AND (adjheader.adjcatcode = 2)) AND (adjheader.adjcode = adjdetail.adjcode)) GROUP BY icode UNION ALL SELECT icode, sum(currqty) AS netqty, 'ST' AS type FROM dbo.godowndetail GROUP BY icode) AS tot, dbo.item WHERE (tot.icode = item.icode) GROUP BY tot.icode, item.name HAVING (sum(CASE WHEN (tot.type = 'ST') THEN tot.netqty ELSE 0 END) <> sum(CASE WHEN (tot.type <> 'ST') THEN tot.netqty ELSE 0 END)) ORDER BY item.name;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_AutoTimeOut_Attendance ====
CREATE OR REPLACE FUNCTION dbo.sp_autotimeout_attendance(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_applydepttimeslabs citext;
  v_automarkabsents citext;
BEGIN
  v_applydepttimeslabs := dbo.fn_getpreference('ApplyDeptTimeSlabsInOnlineAtten');
  IF (v_applydepttimeslabs IS NULL) THEN
    v_applydepttimeslabs := 'N';
  END IF;
  v_automarkabsents := dbo.fn_getpreference('MarkAbsentsOnAutoTimeout');
  IF (v_automarkabsents IS NULL) THEN
    v_automarkabsents := 'N';
  END IF;
  IF (v_automarkabsents = 'Y') THEN
    INSERT INTO dbo.emp_attendance (empcode, fingercode, timein, timeout, fingercodeout, attendancestatuscode, payed, comments) SELECT empcode, 1 AS fingercode, localtimestamp(3) AS timein, localtimestamp(3) AS timeout, NULL::smallint AS fingercodeout, 2 AS attendancestatuscode, 'N' AS payed, 'Absent Marked By System' AS comments FROM dbo.emp_employee WHERE ((active = 'Y') AND (empcode NOT IN (SELECT ea.empcode FROM dbo.emp_attendance AS ea WHERE ((left(to_char(ea.timein, 'MM/DD/YYYY'), 100))::citext = (left(to_char(localtimestamp(3), 'MM/DD/YYYY'), 100))::citext))));
  END IF;
  IF (v_applydepttimeslabs = 'Y') THEN
    UPDATE dbo.emp_attendance SET timeout = eto.idealtimeout, comments = 'System Timed-Out' FROM dbo.emp_attendance AS a, dbo.emp_employee AS e, (SELECT ea.attendancecode, (((left(to_char(ea.timein, 'MM/DD/YYYY'), 100) || ' ') || CASE WHEN ((ltrim(rtrim(left(to_char(ed.shtimeout, 'HH24:MI:SS:MS'), 100))))::citext > (ltrim(rtrim(left(to_char(ed.fhtimeout, 'HH24:MI:SS:MS'), 100))))::citext) THEN ltrim(rtrim(left(to_char(ed.shtimeout, 'HH24:MI:SS:MS'), 100))) WHEN ((ltrim(rtrim(left(to_char(ed.fhtimeout, 'HH24:MI:SS:MS'), 100))))::citext > (ltrim(rtrim(left(to_char(ed.shtimeout, 'HH24:MI:SS:MS'), 100))))::citext) THEN ltrim(rtrim(left(to_char(ed.fhtimeout, 'HH24:MI:SS:MS'), 100))) WHEN ((ltrim(rtrim(left(to_char(ea.timein, 'HH24:MI:SS:MS'), 100))))::citext > (ltrim(rtrim(left(to_char(ed.fhtimeout, 'HH24:MI:SS:MS'), 100))))::citext) THEN ltrim(rtrim(left(to_char(ed.shtimeout, 'HH24:MI:SS:MS'), 100))) ELSE ltrim(rtrim(left(to_char(ed.fhtimeout, 'HH24:MI:SS:MS'), 100))) END))::timestamp(3) AS idealtimeout FROM dbo.emp_departmenttiming AS ed, dbo.emp_attendance AS ea, dbo.emp_employee AS ee WHERE ((((ea.timeout IS NULL) AND (ea.empcode = ee.empcode)) AND ((extract(dow from ea.timein)::integer + 1) = ed.weekdaycode)) AND (ed.deptcode = ee.deptcode))) AS eto WHERE ((((a.timeout IS NULL) AND (a.empcode = e.empcode)) AND (a.attendancecode = eto.attendancecode)) AND (localtimestamp(3) >= eto.idealtimeout));
  ELSE
    UPDATE dbo.emp_attendance AS a SET timeout = (a.timein + (trunc(CASE WHEN ((SELECT max(ep.workinghours) FROM dbo.emp_pay AS ep WHERE (ep.empcode = e.empcode)) IS NULL) THEN e.maxtimeinlimitinhrs ELSE (SELECT max(ep.workinghours) FROM dbo.emp_pay AS ep WHERE (ep.empcode = e.empcode)) END)) * interval '1 hour'), comments = 'System Timed-Out' FROM dbo.emp_employee AS e WHERE (((a.timeout IS NULL) AND (a.empcode = e.empcode)) AND (localtimestamp(3) >= (a.timein + (trunc(CASE WHEN ((SELECT max(ep.workinghours) FROM dbo.emp_pay AS ep WHERE (ep.empcode = e.empcode)) IS NULL) THEN e.maxtimeinlimitinhrs ELSE (SELECT max(ep.workinghours) FROM dbo.emp_pay AS ep WHERE (ep.empcode = e.empcode)) END)) * interval '1 hour')));
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

