-- ==== proc SP_BatchWiseSaleReturn_IssueBased ====
CREATE OR REPLACE FUNCTION dbo.sp_batchwisesalereturn_issuebased(icode integer, batch citext, expiry timestamp, INOUT retableqty numeric, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_icode integer;
  v_batch citext;
  v_expiry timestamp(3);
  v_retableqty numeric(15,4);
BEGIN
  v_icode := icode;
  v_batch := batch;
  v_expiry := expiry;
  v_retableqty := retableqty;
  v_retableqty := (SELECT sum(coalesce(qty, 0)) AS qty FROM (SELECT sum(qty) AS qty FROM dbo.issuedetail WHERE (((icode = v_icode) AND (batch = v_batch)) AND (expiry = v_expiry)) UNION ALL SELECT (-sum(looseqty)) AS qty FROM dbo.srdetail WHERE (((icode = v_icode) AND (batch = v_batch)) AND (expiry = v_expiry))) AS a);
  return_value := 0;
  retableqty := v_retableqty;
  RETURN;
END
$body$;

-- ==== proc SP_CancelServiceOHeader ====
CREATE OR REPLACE FUNCTION dbo.sp_cancelserviceoheader(serviceocode integer, usercode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_serviceocode integer;
  v_usercode integer;
BEGIN
  v_serviceocode := serviceocode;
  v_usercode := usercode;
  UPDATE dbo.serviceoheader SET cancelled = 'Y', cancelledon = localtimestamp(3), cancelledby = v_usercode WHERE ((serviceocode = v_serviceocode) AND (posted = 'N'));
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_CashFlowTotals ====
CREATE OR REPLACE FUNCTION dbo.sp_cashflowtotals(ad_startdate timestamp, ad_enddate timestamp, INOUT af_retailsale double precision, INOUT af_wholesale double precision, INOUT af_clinicsale double precision, INOUT af_retailsaleret double precision, INOUT af_wholesaleret double precision, INOUT af_purchase double precision, INOUT af_purchaseloose double precision, INOUT af_clinicsaleret double precision, INOUT af_purchaseret double precision, INOUT af_retailservice double precision, INOUT af_retailserviceret double precision, OUT return_value integer, OUT rs1 refcursor, OUT rs2 refcursor, OUT rs3 refcursor, OUT rs4 refcursor, OUT rs5 refcursor, OUT rs6 refcursor, OUT rs7 refcursor, OUT rs8 refcursor, OUT rs9 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ad_startdate timestamp(3);
  v_ad_enddate timestamp(3);
  v_af_retailsale double precision;
  v_af_wholesale double precision;
  v_af_clinicsale double precision;
  v_af_retailsaleret double precision;
  v_af_wholesaleret double precision;
  v_af_purchase double precision;
  v_af_purchaseloose double precision;
  v_af_clinicsaleret double precision;
  v_af_purchaseret double precision;
  v_af_retailservice double precision;
  v_af_retailserviceret double precision;
  v_ln_retailsale numeric(12,2);
  v_ln_wholesale numeric(12,2);
  v_ln_clinicsale numeric(12,2);
  v_ln_clinicsaleret numeric(12,2);
  v_ln_retailsaleret numeric(12,2);
  v_ln_wholesaleret numeric(12,2);
  v_ln_purchase numeric(12,2);
  v_ln_purchaseloose numeric(12,2);
  v_ln_purchaseret numeric(12,2);
  v_ln_retailservice numeric(12,2);
  v_ln_retailserviceret numeric(12,2);
BEGIN
  v_ad_startdate := ad_startdate;
  v_ad_enddate := ad_enddate;
  v_af_retailsale := af_retailsale;
  v_af_wholesale := af_wholesale;
  v_af_clinicsale := af_clinicsale;
  v_af_retailsaleret := af_retailsaleret;
  v_af_wholesaleret := af_wholesaleret;
  v_af_purchase := af_purchase;
  v_af_purchaseloose := af_purchaseloose;
  v_af_clinicsaleret := af_clinicsaleret;
  v_af_purchaseret := af_purchaseret;
  v_af_retailservice := af_retailservice;
  v_af_retailserviceret := af_retailserviceret;
  DROP TABLE IF EXISTS tmp_lt_cashamts;
  CREATE TEMP TABLE tmp_lt_cashamts (
    received numeric(11,2) NOT NULL,
    payed numeric(11,2) NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_cashamts SELECT coalesce((round((((sum((saledetail.looseqty * saledetail.unitsalestax)) + sum(round(((((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc))))) * saledetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc)))))) * ((1 - ((.01 * saleledger.discperc))))) - saleledger.flatdisc)) * ((saleledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) + round((((((sum((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc)))))) * ((1 - ((.01 * saleledger.discperc))))) + saleledger.misccharges) + saleledger.salestax) - saleledger.flatdisc))::numeric, 0)), 0) AS received, 0.0 AS payed FROM dbo.saleledger, dbo.saledetail WHERE (((((saleledger.saleinvcode = saledetail.saleinvcode) AND ((saleledger.salecatcode = 3))) AND (saleledger.posted = 'Y')) AND (saleledger.date >= v_ad_startdate)) AND (saleledger.date <= v_ad_enddate)) GROUP BY saleledger.saleinvcode, saleledger.salecatcode, saleledger.date, saleledger.discperc, saleledger.misccharges, saleledger.salestax, saleledger.invgstperc1, saleledger.flatdisc;
  v_ln_retailsale := (SELECT CASE WHEN ((sum(received) - sum(payed)) IS NULL) THEN 0.0 ELSE (sum(received) - sum(payed)) END FROM tmp_lt_cashamts AS lt_cashamts);
  DELETE FROM tmp_lt_cashamts AS lt_cashamts;
  INSERT INTO tmp_lt_cashamts SELECT coalesce((round((((sum((saledetail.looseqty * saledetail.unitsalestax)) + sum(round(((((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc))))) * saledetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc)))))) * ((1 - ((.01 * saleledger.discperc))))) - saleledger.flatdisc)) * ((saleledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) + round((((((sum((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc)))))) * ((1 - ((.01 * saleledger.discperc))))) + saleledger.misccharges) + saleledger.salestax) - saleledger.flatdisc))::numeric, 0)), 0) AS received, 0.0 AS payed FROM dbo.saleledger, dbo.saledetail WHERE (((((saleledger.saleinvcode = saledetail.saleinvcode) AND ((saleledger.salecatcode = 1))) AND (saleledger.posted = 'Y')) AND (saleledger.date >= v_ad_startdate)) AND (saleledger.date <= v_ad_enddate)) GROUP BY saleledger.saleinvcode, saleledger.salecatcode, saleledger.date, saleledger.discperc, saleledger.misccharges, saleledger.salestax, saleledger.invgstperc1, saleledger.flatdisc;
  v_ln_wholesale := (SELECT CASE WHEN ((sum(received) - sum(payed)) IS NULL) THEN 0.0 ELSE (sum(received) - sum(payed)) END FROM tmp_lt_cashamts AS lt_cashamts);
  DELETE FROM tmp_lt_cashamts AS lt_cashamts;
  INSERT INTO tmp_lt_cashamts SELECT 0 AS received, coalesce((round((((sum((srdetail.looseqty * srdetail.unitsalestax)) + sum(round(((((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc))))) * srdetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc)))))) * ((1 - ((.01 * srledger.discperc))))) - srledger.flatdisc)) * ((srledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) + round((((((sum((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc)))))) * ((1 - ((.01 * srledger.discperc))))) + srledger.misccharges) + srledger.salestax) - srledger.flatdisc))::numeric, 0)), 0) AS payed FROM dbo.srledger, dbo.srdetail WHERE (((((srledger.srinvcode = srdetail.srinvcode) AND (srledger.srcatcode = 8)) AND (srledger.posted = 'Y')) AND (srledger.date >= v_ad_startdate)) AND (srledger.date <= v_ad_enddate)) GROUP BY srledger.srinvcode, srledger.srcatcode, srledger.date, srledger.discperc, srledger.misccharges, srledger.salestax, srledger.invgstperc1, srledger.flatdisc;
  v_ln_retailsaleret := (SELECT CASE WHEN ((sum(received) - sum(payed)) IS NULL) THEN 0.0 ELSE (sum(received) - sum(payed)) END FROM tmp_lt_cashamts AS lt_cashamts);
  DELETE FROM tmp_lt_cashamts AS lt_cashamts;
