-- ==== proc SP_Change_SaleReturn ====
CREATE OR REPLACE FUNCTION dbo.sp_change_salereturn(srbufferinvcode integer, custcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srbufferinvcode integer;
  v_custcode integer;
BEGIN
  v_srbufferinvcode := srbufferinvcode;
  v_custcode := custcode;
  UPDATE dbo.srbufferledger SET custcode = v_custcode, srcatcode = 7 WHERE (srbufferinvcode = v_srbufferinvcode);
  UPDATE dbo.srledger SET custcode = v_custcode, srcatcode = 7 WHERE (srinvcode = v_srbufferinvcode);
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_changeitemdisc ====
CREATE OR REPLACE FUNCTION dbo.sp_changeitemdisc(changeoption integer, code integer, discpercno integer, discperc numeric, usercode integer, serverdatetime timestamp, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_changeoption integer;
  v_code integer;
  v_discpercno integer;
  v_discperc numeric(5,2);
  v_usercode integer;
  v_serverdatetime timestamp(3);
  v_query citext;
  v_str_wherecondition citext;
  v_str_discquery citext;
  v_str_usercode citext;
  v_str_serverdatetime citext;
  v_str_discperc citext;
  v_str_code citext;
  _dq1 text;
BEGIN
  v_changeoption := changeoption;
  v_code := code;
  v_discpercno := discpercno;
  v_discperc := discperc;
  v_usercode := usercode;
  v_serverdatetime := serverdatetime;
  v_str_usercode := (v_usercode)::text;
  v_str_discperc := (v_discperc)::text;
  v_str_serverdatetime := left(to_char(v_serverdatetime, 'Mon DD YYYY HH12:MIAM'), 20);
  v_str_code := (v_code)::text;
  IF ((((v_discpercno < 1)) OR ((v_discpercno > 5)))) THEN
    return_value := -1;
    RETURN;
  END IF;
  IF ((((v_changeoption < 1)) OR ((v_changeoption > 4)))) THEN
    return_value := -1;
    RETURN;
  END IF;
  IF (v_discpercno = 1) THEN
    v_str_discquery := (' SaleDiscPerc = ' || v_str_discperc);
  END IF;
  IF (v_discpercno = 2) THEN
    v_str_discquery := (' SaleDiscPerc2 = ' || v_str_discperc);
  END IF;
  IF (v_discpercno = 3) THEN
    v_str_discquery := (' SaleDiscPerc3 = ' || v_str_discperc);
  END IF;
  IF (v_discpercno = 4) THEN
    v_str_discquery := (' SaleDiscPerc4 = ' || v_str_discperc);
  END IF;
  IF (v_discpercno = 5) THEN
    v_str_discquery := (' SaleDiscPerc5 = ' || v_str_discperc);
  END IF;
  IF (v_changeoption = 1) THEN
    v_str_wherecondition := ('  Where item.manfcode = ' || v_str_code);
  END IF;
  IF (v_changeoption = 2) THEN
    v_str_wherecondition := ('  Where item.icatcode = ' || v_str_code);
  END IF;
  IF (v_changeoption = 3) THEN
    v_str_wherecondition := ('  Where item.iccode = ' || v_str_code);
  END IF;
  IF (v_changeoption = 4) THEN
    v_str_wherecondition := ('  Where item.packcode = ' || v_str_code);
  END IF;
  v_str_wherecondition := (v_str_wherecondition || '  AND Item.Active=1');
  v_query := ((((((' Update  Item Set ChangeReason=''Change Discounts Cat Wise'', Module=''Change Discounts'', UserCode  = ' || v_str_usercode) || ' , LastUpdate = ''') || v_str_serverdatetime) || ''' , ') || v_str_discquery) || v_str_wherecondition);
  _dq1 := v_query;
  IF _dq1 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq1);
  END IF;
  IF (0 <> 0) THEN
    RAISE EXCEPTION 'Unable to update item Salediscperc';
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

