-- ==== proc SP_ChangePrintStatus_ActivityMonitor ====
CREATE OR REPLACE FUNCTION dbo.sp_changeprintstatus_activitymonitor(docrowid integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_docrowid integer;
  v_rowsaffected integer;
  v_err integer;
  _rc integer;
BEGIN
  v_docrowid := docrowid;
  IF (v_docrowid IS NULL) THEN
    RAISE EXCEPTION 'Error Changing Print Status of Activity Monitor';
    return_value := -1;
    RETURN;
  END IF;
  UPDATE dbo.activitymonitor SET printed = 'Y' WHERE (docrowid = v_docrowid);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_rowsaffected := _rc;
  v_err := 0;
  _rc := 1;
  IF ((v_rowsaffected = 0) AND (v_err = 0)) THEN
    RAISE EXCEPTION 'Unable to Update Activity Monitor for Document Row ID = (%)', v_docrowid;
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

