  UPDATE dbo.cashieractivity SET printed = 'Y' WHERE ((rowid = v_docrowid) AND (printed = 'N'));
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_rowsaffected := _rc;
  v_err := 0;
  _rc := 1;
  IF ((v_rowsaffected = 0) AND (v_err = 0)) THEN
    RAISE EXCEPTION 'Unable to Update Print Status for Cashier Activity, Document Row ID = (%)', v_docrowid;
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_ChangeRecurringStatus ====
CREATE OR REPLACE FUNCTION dbo.sp_changerecurringstatus(saleinvcode integer, status citext, thisinvcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_saleinvcode integer;
  v_status citext;
  v_thisinvcode integer;
  v_rowsaffected integer;
  v_err integer;
  _rc integer;
BEGIN
  v_saleinvcode := saleinvcode;
  v_status := status;
  v_thisinvcode := thisinvcode;
  UPDATE dbo.saleledger SET recurringinvoice = v_status, lastrecurringinvcode = v_thisinvcode WHERE ((saleinvcode = v_saleinvcode) AND (recurringinvoice <> v_status));
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_rowsaffected := _rc;
  v_err := 0;
  _rc := 1;
  IF ((v_rowsaffected = 0) AND (v_err = 0)) THEN
    RAISE EXCEPTION 'Unable to change the recurring status of Sale Invoice No. = (%)', v_saleinvcode;
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_Check_UserAttendance ====
CREATE OR REPLACE FUNCTION dbo.sp_check_userattendance(usercode smallint, INOUT rowid integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_usercode smallint;
  v_rowid integer;
BEGIN
  v_usercode := usercode;
  v_rowid := rowid;
  v_rowid := coalesce((SELECT max(rowid) AS rowid FROM dbo.userattendance WHERE (((usercode = v_usercode) AND (timeout IS NULL)) AND (timein IS NOT NULL))), -1);
  return_value := 0;
  rowid := v_rowid;
  RETURN;
  return_value := 0;
  rowid := v_rowid;
  RETURN;
END
$body$;

-- ==== proc SP_CheckCustomerWiseItemCategory_ForAnItem ====
CREATE OR REPLACE FUNCTION dbo.sp_checkcustomerwiseitemcategory_foranitem(custcode smallint, icode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_custcode smallint;
  v_icode integer;
  v_icatcode smallint;
BEGIN
  v_custcode := custcode;
