  v_icatcode := (SELECT icatcode FROM dbo.item WHERE ((item.icode = v_icode) AND (icatcode IN (SELECT ci.icatcode FROM dbo.custwiseitemcategory AS ci WHERE (ci.custcode = v_custcode)))));
