  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_CheckDBIntegrity ====
CREATE OR REPLACE FUNCTION dbo.sp_checkdbintegrity(db citext DEFAULT NULL, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_db citext;
  v_rc integer;
  v_versioninfo citext;
  v_dbversion citext;
  cur_database_cursor refcursor;
  _fs integer := -1;
BEGIN
  v_db := db;
  TRUNCATE TABLE dbo.dbcc_history RESTART IDENTITY;
  SELECT r.return_value, r.versioninfo INTO v_rc, v_versioninfo FROM dbo.sp_dbms_version(versioninfo => v_versioninfo) AS r;
  OPEN rs1 FOR SELECT v_versioninfo;
  IF (dbo.tsql_charindex(('Microsoft SQL Server 2012')::citext, (v_versioninfo)::citext, 1) > 0) THEN
    v_dbversion := '2012';
  ELSE
    v_dbversion := '2000';
  END IF;
  IF (v_db IS NULL) THEN
    -- OPEN database_cursor
    RAISE EXCEPTION 'untranslated T-SQL (cross-database table master.dbo.sysdatabases)' USING ERRCODE = '0A000';
    FETCH NEXT FROM cur_database_cursor INTO v_db;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    WHILE (_fs = 0) LOOP
      IF (v_dbversion = '2012') THEN
        EXECUTE coalesce('INSERT INTO dbo.dbcc_history (errorid, levelid, stateid, messagetext, repairlevel, statusid, dbid, dbfragid, objectid, indid, partitionid, allocunitid, riddbid, ridpruid, fileid, pageid, slotid, refdbid, refpruid, reffileid, refpageid, refslotid, allocationid) ' || (('dbcc checkdb(''' || v_db) || ''') with tableresults, ALL_ERRORMSGS'), 'SELECT 1');
      ELSE
        EXECUTE coalesce('INSERT INTO dbo.dbcc_history (errorid, levelid, stateid, messagetext, repairlevel, statusid, dbid, objectid, indid, fileid, pageid, slotid, reffileid, refpageid, refslotid, allocationid) ' || (('dbcc checkdb(''' || v_db) || ''') with tableresults, ALL_ERRORMSGS'), 'SELECT 1');
      END IF;
      IF (0 <> 0) THEN
        CLOSE cur_database_cursor;
        -- DEALLOCATE database_cursor
        return_value := 0;
        RETURN;
      END IF;
      FETCH NEXT FROM cur_database_cursor INTO v_db;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    END LOOP;
    CLOSE cur_database_cursor;
    -- DEALLOCATE database_cursor
  ELSE
    IF (v_dbversion = '2012') THEN
      EXECUTE coalesce('INSERT INTO dbo.dbcc_history (errorid, levelid, stateid, messagetext, repairlevel, statusid, dbid, dbfragid, objectid, indid, partitionid, allocunitid, riddbid, ridpruid, fileid, pageid, slotid, refdbid, refpruid, reffileid, refpageid, refslotid, allocationid) ' || (('dbcc checkdb(''' || v_db) || ''') with tableresults, ALL_ERRORMSGS'), 'SELECT 1');
    ELSE
      EXECUTE coalesce('INSERT INTO dbo.dbcc_history (errorid, levelid, stateid, messagetext, repairlevel, statusid, dbid, objectid, indid, fileid, pageid, slotid, reffileid, refpageid, refslotid, allocationid) ' || (('dbcc checkdb(''' || v_db) || ''') with tableresults, ALL_ERRORMSGS'), 'SELECT 1');
    END IF;
    IF (0 <> 0) THEN
      CLOSE cur_database_cursor;
      -- DEALLOCATE database_cursor
      return_value := 0;
      RETURN;
    END IF;
  END IF;
  -- UPDATE DBCC_History
  -- SET DB = (SELECT db.name FROM master.dbo.sysdatabases db WHERE db.dbid = DBCC_History.dbid),
  -- 	Object = (SELECT o.name FROM sysobjects o WHERE o.id = DBCC_History.objectid)
  -- WHERE DB IS NULL OR Object IS NULL
  RAISE EXCEPTION 'untranslated T-SQL (cross-database table master.dbo.sysdatabases)' USING ERRCODE = '0A000';
  IF (0 <> 0) THEN
    CLOSE cur_database_cursor;
    -- DEALLOCATE database_cursor
    return_value := 0;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_CheckForNewItemInDataCarry ====
CREATE OR REPLACE FUNCTION dbo.sp_checkfornewitemindatacarry(srv citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_qry citext;
  v_count integer;
  _dq1 text;
BEGIN
  v_srv := srv;
  DELETE FROM dbo.reportdata;
  v_qry := (('INSERT INTO ReportData (Code1) Select COALESCE(COUNT(ICode),0) AS Items From ' || v_srv) || '...Item Where ICode NOT IN (SELECT ICode FROM Item)');
  _dq1 := v_qry;
  IF _dq1 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq1);
  END IF;
  IF (0 <> 0) THEN
    RAISE EXCEPTION 'Some Problem occur in checking new items in data carry db';
    return_value := -1;
    RETURN;
  END IF;
  v_count := trunc(coalesce((SELECT max(coalesce(code1, 0)) FROM dbo.reportdata), 0))::integer;
  return_value := v_count;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_CheckItemWiseUpperSaleQty_ForAnItem ====
CREATE OR REPLACE FUNCTION dbo.sp_checkitemwiseuppersaleqty_foranitem(icode integer, INOUT checklimit citext, INOUT upperlimit integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
