  upperlimit := v_upperlimit;
  RETURN;
END
$body$;

-- ==== proc SP_CheckPacketCounters ====
CREATE OR REPLACE FUNCTION dbo.sp_checkpacketcounters(srv citext, db citext, owner citext, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_qry citext;
  v_from citext;
  v_archiveaccountsdata citext;
  v_rtcode integer;
  v_err integer;
  v_salediff integer;
  v_purdiff integer;
  _dq1 text;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  DELETE FROM dbo.reportdata;
  v_from := ((((((' FROM ' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.');
  v_qry := ((((((((((((((((((((((('INSERT INTO ReportData (Name1, Code1) ' || 'SELECT ''Sales'', COALESCE((SELECT MIN(SaleInvCode) AS Diff ') || v_from) || 'SaleLedger), COALESCE((SELECT MAX(SaleInvCode) FROM SaleLedger), 0)) - COALESCE((SELECT MAX(SaleInvCode) FROM SaleLedger), 0) ') || ' UNION ALL ') || 'SELECT ''Service Sale'', COALESCE((SELECT MIN(ServiceInvCode) AS Diff ') || v_from) || 'ServiceHeader), COALESCE((SELECT MAX(ServiceInvCode) FROM ServiceHeader), 0)) - COALESCE((SELECT MAX(ServiceInvCode) FROM ServiceHeader), 0)') || ' UNION ALL ') || 'SELECT ''Service Purchase'', COALESCE((SELECT MIN(ServicePurInvCode) AS Diff ') || v_from) || 'ServicePurHeader), COALESCE((SELECT MAX(ServicePurInvCode) FROM ServicePurHeader), 0)) - COALESCE((SELECT MAX(ServicePurInvCode) FROM ServicePurHeader), 0)') || ' UNION ALL ') || 'SELECT ''A/c Voucher'', COALESCE((SELECT MIN(GLVochCode) AS Diff ') || v_from) || 'GLHeader), COALESCE((SELECT MAX(GLVochCode) FROM GLHeader), 0)) - COALESCE((SELECT MAX(GLVochCode) FROM GLHeader), 0)') || ' UNION ALL ') || 'SELECT ''Notes Receiveable/Payable'', COALESCE((SELECT MIN(NoteCode) AS Diff ') || v_from) || 'Notes), COALESCE((SELECT MAX(NoteCode) FROM Notes), 0)) - COALESCE((SELECT MAX(NoteCode) FROM Notes), 0)') || ' UNION ALL ') || 'SELECT ''Transaction Data'', COALESCE((SELECT MIN(DocumentCode) AS Diff ') || v_from) || 'TransactionHeader ), COALESCE((SELECT MAX(DocumentCode) FROM TransactionHeader), 0)) - COALESCE((SELECT MAX(DocumentCode) FROM TransactionHeader), 0)');
  _dq1 := v_qry;
  IF _dq1 IS NOT NULL THEN
    IF _dq1 ~* '^[[:space:]]*select' THEN OPEN rs1 FOR EXECUTE dbo.tsql_dyn(_dq1); ELSE EXECUTE dbo.tsql_dyn(_dq1); END IF;
  END IF;
  v_err := 0;
  IF ((v_err <> 0) OR (v_rtcode <> 0)) THEN
    RAISE EXCEPTION 'Failure to check version difference of Data Migration Packet and Current Database, Error Code = %', v_err;
    return_value := -1;
    RETURN;
  END IF;
  v_salediff := trunc(coalesce((SELECT code1 FROM dbo.reportdata WHERE (name1 = 'Sales')), 0))::integer;
  IF ((v_salediff < 0) OR (v_salediff > 1)) THEN
    RAISE EXCEPTION 'The Data Migration Packet is not the correct version to aquire into current database (sales), Error Code = %', v_salediff;
    return_value := -1;
    RETURN;
  END IF;
  v_salediff := trunc(coalesce((SELECT code1 FROM dbo.reportdata WHERE (name1 = 'Service Sale')), 0))::integer;
  IF ((v_salediff < 0) OR (v_salediff > 1)) THEN
    RAISE EXCEPTION 'The Data Migration Packet is not the correct version to aquire into current database (service sales), Error Code = %', v_salediff;
    return_value := -1;
    RETURN;
  END IF;
  v_purdiff := trunc(coalesce((SELECT code1 FROM dbo.reportdata WHERE (name1 = 'Service Purchase')), 0))::integer;
  IF ((v_purdiff < 0) OR (v_purdiff > 1)) THEN
    RAISE EXCEPTION 'The Data Migration Packet is not the correct version to aquire into current database (Service Purchase), Error Code = %', v_purdiff;
    return_value := -1;
    RETURN;
  END IF;
  v_archiveaccountsdata := dbo.fn_getpreference('archiveaccountingdata');
  v_archiveaccountsdata := coalesce(v_archiveaccountsdata, 'N');
  IF (v_archiveaccountsdata = 'Y') THEN
    v_purdiff := trunc(coalesce((SELECT code1 FROM dbo.reportdata WHERE (name1 = 'A/c Voucher')), 0))::integer;
    IF ((v_purdiff < 0) OR (v_purdiff > 1)) THEN
      RAISE EXCEPTION 'The Data Migration Packet is not the correct version to aquire into current database (A/c Voucher), Error Code = %', v_purdiff;
      return_value := -1;
      RETURN;
    END IF;
    v_purdiff := trunc(coalesce((SELECT code1 FROM dbo.reportdata WHERE (name1 = 'Notes Receiveable/Payable')), 0))::integer;
    IF ((v_purdiff < 0) OR (v_purdiff > 1)) THEN
      RAISE EXCEPTION 'The Data Migration Packet is not the correct version to aquire into current database (Notes Receiveable/Payable), Error Code = %', v_purdiff;
      return_value := -1;
      RETURN;
    END IF;
    v_purdiff := trunc(coalesce((SELECT code1 FROM dbo.reportdata WHERE (name1 = 'Transaction Data')), 0))::integer;
    IF ((v_purdiff < 0) OR (v_purdiff > 1)) THEN
      RAISE EXCEPTION 'The Data Migration Packet is not the correct version to aquire into current database (Transaction Data), Error Code = %', v_purdiff;
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_CheckTable ====
CREATE OR REPLACE FUNCTION dbo.sp_checktable(db citext, object citext, option integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_db citext;
  v_object citext;
  v_option integer;
  v_qry citext;
  _dq1 text;
BEGIN
  v_db := db;
  v_object := object;
  v_option := option;
  -- SET NOCOUNT ON
  IF (v_db IS NULL) THEN
    return_value := 0;
    RETURN;
  END IF;
  IF (v_object IS NULL) THEN
    return_value := 0;
    RETURN;
  END IF;
  IF (v_option IS NULL) THEN
    return_value := 0;
    RETURN;
  END IF;
  v_qry := (('dbcc CheckTable(''' || v_object) || '''');
  IF (v_option = 0) THEN
    v_qry := (v_qry || '');
  END IF;
  IF (v_option = 1) THEN
    v_qry := (v_qry || ', REPAIR_FAST');
  END IF;
  IF (v_option = 2) THEN
    v_qry := (v_qry || ', REPAIR_REBUILD');
  END IF;
  IF (v_option = 3) THEN
    v_qry := (v_qry || ', REPAIR_ALLOW_DATA_LOSS');
  END IF;
  v_qry := (v_qry || ') with tableresults, ALL_ERRORMSGS');
  _dq1 := v_qry;
  IF _dq1 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq1);
  END IF;
  IF (0 <> 0) THEN
    return_value := 0;
    RETURN;
  END IF;
  INSERT INTO dbo.dbrepairlog (date, repairlevel, objectname) SELECT localtimestamp(3) AS date, CASE v_option WHEN 1 THEN 'REPAIR_FAST' WHEN 2 THEN 'REPAIR_REBUILD' WHEN 3 THEN 'REPAIR_ALLOW_DATA_LOSS' ELSE '' END AS repairlevel, v_object AS objectname;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_CheckUniqueAliasName ====
CREATE OR REPLACE FUNCTION dbo.sp_checkuniquealiasname(icode integer, customicode citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_icode integer;
  v_customicode citext;
  v_rowscount integer;
BEGIN
  v_icode := icode;
  v_customicode := customicode;
  IF (v_icode > 0) THEN
    v_rowscount := (SELECT sum(coalesce(c, 0)) AS c FROM (SELECT 0 AS c UNION ALL SELECT count(customicode) AS c FROM dbo.item WHERE ((icode <> v_icode) AND (customicode = v_customicode)) UNION ALL SELECT count(customicode) AS c FROM dbo.alternateitemalias WHERE ((icode <> v_icode) AND (customicode = v_customicode))) AS s);
  ELSE
    v_rowscount := (SELECT sum(coalesce(c, 0)) AS c FROM (SELECT 0 AS c UNION ALL SELECT count(customicode) AS c FROM dbo.item WHERE (customicode = v_customicode) UNION ALL SELECT count(customicode) AS c FROM dbo.alternateitemalias WHERE (customicode = v_customicode)) AS s);
  END IF;
  IF (v_rowscount = 0) THEN
    return_value := 0;
    RETURN;
  ELSE
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_CheckUnpostedPRInvInTransactions ====
CREATE OR REPLACE FUNCTION dbo.sp_checkunpostedprinvintransactions(invcode integer, code integer, callermodule citext, INOUT rowscount integer, INOUT msg citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_invcode integer;
  v_code integer;
  v_callermodule citext;
  v_rowscount integer;
  v_msg citext;
BEGIN
  v_invcode := invcode;
  v_code := code;
  v_callermodule := callermodule;
  v_rowscount := rowscount;
  v_msg := msg;
  SELECT coalesce(count(prallocationheader.prinvcode), 0) INTO v_rowscount FROM dbo.prallocationheader WHERE (((prallocationheader.posted = 'N') AND (prallocationheader.prinvcode = v_invcode)) AND (prallocationheader.prallocationcode <> CASE v_callermodule WHEN 'PRA' THEN CASE WHEN (v_code IS NULL) THEN -1 ELSE v_code END ELSE -1 END));
  IF (v_rowscount = 0) THEN
    v_msg := '';
  ELSE
    SELECT max(m) INTO v_msg FROM (SELECT (((('Module: Purchase Return Allocation' || chr(13)) || chr(10)) || 'Code: ') || rtrim(ltrim(dbo.tsql_str((prallocationheader.prallocationcode)::numeric, 10)))) AS m FROM dbo.prallocationheader WHERE (((prallocationheader.posted = 'N') AND (prallocationheader.prinvcode = v_invcode)) AND (prallocationheader.prallocationcode <> CASE v_callermodule WHEN 'PRA' THEN CASE WHEN (v_code IS NULL) THEN -1 ELSE v_code END ELSE -1 END))) AS p;
  END IF;
  return_value := 0;
  rowscount := v_rowscount;
  msg := v_msg;
  RETURN;
END
$body$;

-- ==== proc SP_CheckUnpostedPurInvInTransactions ====
CREATE OR REPLACE FUNCTION dbo.sp_checkunpostedpurinvintransactions(invcode integer, code integer, callermodule citext, INOUT rowscount integer, INOUT msg citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_invcode integer;
  v_code integer;
  v_callermodule citext;
  v_rowscount integer;
  v_msg citext;
BEGIN
  v_invcode := invcode;
  v_code := code;
  v_callermodule := callermodule;
  v_rowscount := rowscount;
  v_msg := msg;
  SELECT sum(coalesce(c, 0)) INTO v_rowscount FROM (SELECT 0 AS c UNION ALL SELECT count(notesdetail.invoicecode) AS c FROM dbo.notesdetail, dbo.notes WHERE ((((((notes.posted = 'N') AND (notes.finalized = 'N')) AND (notes.notecatcode = 2)) AND (notes.notecode = notesdetail.notecode)) AND (notesdetail.invoicecode = v_invcode)) AND (notesdetail.notecode <> CASE v_callermodule WHEN 'NP' THEN CASE WHEN (v_code IS NULL) THEN -1 ELSE v_code END ELSE -1 END)) UNION ALL SELECT count(purpayment.purinvcode) AS c FROM dbo.purpayment WHERE (((purpayment.posted = 'N') AND (purpayment.purinvcode = v_invcode)) AND (purpayment.purpaymentcode <> CASE v_callermodule WHEN 'PP' THEN CASE WHEN (v_code IS NULL) THEN -1 ELSE v_code END ELSE -1 END)) UNION ALL SELECT count(gldetail.invoicecode) AS c FROM dbo.gldetail, dbo.glheader, dbo.vochercategory WHERE ((((((glheader.posted = 'N') AND (glheader.glvochcode = gldetail.glvochcode)) AND (gldetail.invoicecode = v_invcode)) AND (vochercategory.invoicetype = 2)) AND (vochercategory.vochcatcode = glheader.vochcatcode)) AND (gldetail.glvochcode <> CASE v_callermodule WHEN 'V' THEN CASE WHEN (v_code IS NULL) THEN -1 ELSE v_code END ELSE -1 END)) UNION ALL SELECT count(prallocationdetail.purinvcode) AS c FROM dbo.prallocationdetail, dbo.prallocationheader WHERE ((((prallocationheader.posted = 'N') AND (prallocationheader.prallocationcode = prallocationdetail.prallocationcode)) AND (prallocationdetail.purinvcode = v_invcode)) AND (prallocationdetail.prallocationcode <> CASE v_callermodule WHEN 'PRA' THEN CASE WHEN (v_code IS NULL) THEN -1 ELSE v_code END ELSE -1 END))) AS p;
  IF (v_rowscount = 0) THEN
    v_msg := '';
  ELSE
    SELECT max(m) INTO v_msg FROM (SELECT (((('Module: Post-Dated Cheque Payable' || chr(13)) || chr(10)) || 'Code: ') || rtrim(ltrim(dbo.tsql_str((notes.notecode)::numeric, 10)))) AS m FROM dbo.notesdetail, dbo.notes WHERE ((((((notes.posted = 'N') AND (notes.finalized = 'N')) AND (notes.notecatcode = 2)) AND (notes.notecode = notesdetail.notecode)) AND (notesdetail.invoicecode = v_invcode)) AND (notesdetail.notecode <> CASE v_callermodule WHEN 'NP' THEN CASE WHEN (v_code IS NULL) THEN -1 ELSE v_code END ELSE -1 END)) UNION ALL SELECT (((('Module: Purchase Payment' || chr(13)) || chr(10)) || 'Code: ') || rtrim(ltrim(dbo.tsql_str((pp.purpaymentcode)::numeric, 10)))) AS m FROM dbo.purpayment AS pp WHERE (((pp.posted = 'N') AND (pp.purinvcode = v_invcode)) AND (pp.purpaymentcode <> CASE v_callermodule WHEN 'PP' THEN CASE WHEN (v_code IS NULL) THEN -1 ELSE v_code END ELSE -1 END)) UNION ALL SELECT ((((('Module: ' || rtrim(ltrim(vochercategory.name))) || chr(13)) || chr(10)) || 'Code: ') || rtrim(ltrim(dbo.tsql_str((glheader.glvochcode)::numeric, 10)))) AS m FROM dbo.gldetail, dbo.glheader, dbo.vochercategory WHERE ((((((glheader.posted = 'N') AND (glheader.glvochcode = gldetail.glvochcode)) AND (gldetail.invoicecode = v_invcode)) AND (vochercategory.invoicetype = 2)) AND (vochercategory.vochcatcode = glheader.vochcatcode)) AND (gldetail.glvochcode <> CASE v_callermodule WHEN 'V' THEN CASE WHEN (v_code IS NULL) THEN -1 ELSE v_code END ELSE -1 END)) UNION ALL SELECT (((('Module: Purchase Return Allocation' || chr(13)) || chr(10)) || 'Code: ') || rtrim(ltrim(dbo.tsql_str((prallocationheader.prallocationcode)::numeric, 10)))) AS m FROM dbo.prallocationdetail, dbo.prallocationheader WHERE ((((prallocationheader.posted = 'N') AND (prallocationheader.prallocationcode = prallocationdetail.prallocationcode)) AND (prallocationdetail.purinvcode = v_invcode)) AND (prallocationdetail.prallocationcode <> CASE v_callermodule WHEN 'PRA' THEN CASE WHEN (v_code IS NULL) THEN -1 ELSE v_code END ELSE -1 END))) AS p;
  END IF;
  return_value := 0;
  rowscount := v_rowscount;
  msg := v_msg;
  RETURN;
END
$body$;

-- ==== proc SP_CheckUnpostedSaleInvInTransactions ====
CREATE OR REPLACE FUNCTION dbo.sp_checkunpostedsaleinvintransactions(invcode integer, code integer, callermodule citext, INOUT rowscount integer, INOUT msg citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_invcode integer;
  v_code integer;
  v_callermodule citext;
  v_rowscount integer;
  v_msg citext;
BEGIN
  v_invcode := invcode;
  v_code := code;
  v_callermodule := callermodule;
  v_rowscount := rowscount;
  v_msg := msg;
  SELECT sum(coalesce(c, 0)) INTO v_rowscount FROM (SELECT 0 AS c UNION ALL SELECT count(notesdetail.invoicecode) AS c FROM dbo.notesdetail, dbo.notes WHERE ((((((notes.posted = 'N') AND (notes.finalized = 'N')) AND (notes.notecatcode = 1)) AND (notes.notecode = notesdetail.notecode)) AND (notesdetail.invoicecode = v_invcode)) AND (notesdetail.notecode <> CASE v_callermodule WHEN 'NR' THEN CASE WHEN (v_code IS NULL) THEN -1 ELSE v_code END ELSE -1 END)) UNION ALL SELECT count(gldetail.invoicecode) AS c FROM dbo.gldetail, dbo.glheader, dbo.vochercategory WHERE ((((((glheader.posted = 'N') AND (glheader.glvochcode = gldetail.glvochcode)) AND (gldetail.invoicecode = v_invcode)) AND (vochercategory.invoicetype = 1)) AND (vochercategory.vochcatcode = glheader.vochcatcode)) AND (gldetail.glvochcode <> CASE v_callermodule WHEN 'V' THEN CASE WHEN (v_code IS NULL) THEN -1 ELSE v_code END ELSE -1 END)) UNION ALL SELECT count(bd.saleinvcode) AS c FROM dbo.billsummarydetail AS bd, dbo.billsummary AS b WHERE ((((b.posted = 'N') AND (b.billsummarycode = bd.billsummarycode)) AND (bd.saleinvcode = v_invcode)) AND (bd.billsummarycode <> CASE v_callermodule WHEN 'BS' THEN CASE WHEN (v_code IS NULL) THEN -1 ELSE v_code END ELSE -1 END)) UNION ALL SELECT count(srallocationdetail.saleinvcode) AS c FROM dbo.srallocationdetail, dbo.srallocationheader WHERE ((((srallocationheader.posted = 'N') AND (srallocationheader.srallocationcode = srallocationdetail.srallocationcode)) AND (srallocationdetail.saleinvcode = v_invcode)) AND (srallocationdetail.srallocationcode <> CASE v_callermodule WHEN 'SRA' THEN CASE WHEN (v_code IS NULL) THEN -1 ELSE v_code END ELSE -1 END))) AS s;
  IF (v_rowscount = 0) THEN
    v_msg := '';
  ELSE
    SELECT max(m) INTO v_msg FROM (SELECT (((('Module: Post-Dated Cheque Receivable' || chr(13)) || chr(10)) || 'Code: ') || rtrim(ltrim(dbo.tsql_str((notes.notecode)::numeric, 10)))) AS m FROM dbo.notesdetail, dbo.notes WHERE ((((((notes.posted = 'N') AND (notes.finalized = 'N')) AND (notes.notecatcode = 1)) AND (notes.notecode = notesdetail.notecode)) AND (notesdetail.invoicecode = v_invcode)) AND (notesdetail.notecode <> CASE v_callermodule WHEN 'NR' THEN CASE WHEN (v_code IS NULL) THEN -1 ELSE v_code END ELSE -1 END)) UNION ALL SELECT ((((('Module: ' || rtrim(ltrim(vochercategory.name))) || chr(13)) || chr(10)) || 'Code: ') || rtrim(ltrim(dbo.tsql_str((glheader.glvochcode)::numeric, 10)))) AS m FROM dbo.gldetail, dbo.glheader, dbo.vochercategory WHERE ((((((glheader.posted = 'N') AND (glheader.glvochcode = gldetail.glvochcode)) AND (gldetail.invoicecode = v_invcode)) AND (vochercategory.invoicetype = 1)) AND (vochercategory.vochcatcode = glheader.vochcatcode)) AND (gldetail.glvochcode <> CASE v_callermodule WHEN 'V' THEN CASE WHEN (v_code IS NULL) THEN -1 ELSE v_code END ELSE -1 END)) UNION ALL SELECT (((('Module: Bill Summary ' || chr(13)) || chr(10)) || 'Code: ') || rtrim(ltrim(dbo.tsql_str((b.billsummarycode)::numeric, 10)))) AS m FROM dbo.billsummarydetail AS bd, dbo.billsummary AS b WHERE ((((b.posted = 'N') AND (b.billsummarycode = bd.billsummarycode)) AND (bd.saleinvcode = v_invcode)) AND (bd.billsummarycode <> CASE v_callermodule WHEN 'BS' THEN CASE WHEN (v_code IS NULL) THEN -1 ELSE v_code END ELSE -1 END)) UNION ALL SELECT (((('Module: Sale Return Allocation' || chr(13)) || chr(10)) || 'Code: ') || rtrim(ltrim(dbo.tsql_str((srallocationheader.srallocationcode)::numeric, 10)))) AS m FROM dbo.srallocationdetail, dbo.srallocationheader WHERE ((((srallocationheader.posted = 'N') AND (srallocationheader.srallocationcode = srallocationdetail.srallocationcode)) AND (srallocationdetail.saleinvcode = v_invcode)) AND (srallocationdetail.srallocationcode <> CASE v_callermodule WHEN 'SRA' THEN CASE WHEN (v_code IS NULL) THEN -1 ELSE v_code END ELSE -1 END))) AS s;
  END IF;
  return_value := 0;
  rowscount := v_rowscount;
  msg := v_msg;
  RETURN;
END
$body$;

