-- ==== proc SP_CheckUnpostedTransactionOfAnItem ====
CREATE OR REPLACE FUNCTION dbo.sp_checkunpostedtransactionofanitem(icode integer, INOUT rowscount integer, INOUT msg citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_icode integer;
  v_rowscount integer;
  v_msg citext;
BEGIN
  v_icode := icode;
  v_rowscount := rowscount;
  v_msg := msg;
  v_rowscount := coalesce((SELECT sum(coalesce(c, 0)) AS c FROM (SELECT 0 AS c UNION ALL SELECT count(d.icode) AS c FROM dbo.purdetail AS d, dbo.purledger AS h WHERE (((h.posted = 'N') AND (h.purinvcode = d.purinvcode)) AND (d.icode = v_icode)) UNION ALL SELECT count(d.icode) AS c FROM dbo.prdetail AS d, dbo.prledger AS h WHERE (((h.posted = 'N') AND (h.prinvcode = d.prinvcode)) AND (d.icode = v_icode)) UNION ALL SELECT count(d.icode) AS c FROM dbo.saledetail AS d, dbo.saleledger AS h WHERE (((h.posted = 'N') AND (h.saleinvcode = d.saleinvcode)) AND (d.icode = v_icode)) UNION ALL SELECT count(d.icode) AS c FROM dbo.srdetail AS d, dbo.srledger AS h WHERE (((h.posted = 'N') AND (h.srinvcode = d.srinvcode)) AND (d.icode = v_icode)) UNION ALL SELECT count(d.icode) AS c FROM dbo.srbufferdetail AS d, dbo.srbufferledger AS h WHERE (((h.posted = 'N') AND (h.srbufferinvcode = d.srbufferinvcode)) AND (d.icode = v_icode)) UNION ALL SELECT count(d.icode) AS c FROM dbo.adjdetail AS d, dbo.adjheader AS h WHERE (((h.posted = 'N') AND (h.adjcode = d.adjcode)) AND (d.icode = v_icode)) UNION ALL SELECT count(d.icode) AS c FROM dbo.issuedetail AS d, dbo.issueheader AS h WHERE (((h.posted = 'N') AND (h.issueinvcode = d.issueinvcode)) AND (d.icode = v_icode)) UNION ALL SELECT count(d.icode) AS c FROM dbo.receiptdetail AS d, dbo.receiptheader AS h WHERE (((h.posted = 'N') AND (h.receiptinvcode = d.receiptinvcode)) AND (d.icode = v_icode)) UNION ALL SELECT count(d.icode) AS c FROM dbo.tdetail AS d, dbo.theader AS h WHERE (((h.posted = 'N') AND (h.transcode = d.transcode)) AND (d.icode = v_icode))) AS s), 0);
  IF (v_rowscount = 0) THEN
    v_msg := '';
  ELSE
    v_msg := 'Some Unposted Transactions Exist for This Item.';
  END IF;
  return_value := 0;
  rowscount := v_rowscount;
  msg := v_msg;
  RETURN;
  return_value := 0;
  rowscount := v_rowscount;
  msg := v_msg;
  RETURN;
END
$body$;

-- ==== proc SP_CheckUnpostedTransactions ====
CREATE OR REPLACE FUNCTION dbo.sp_checkunpostedtransactions(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_transcount integer;
BEGIN
  v_transcount := coalesce((SELECT count(*) FROM dbo.saleledger WHERE (posted = 'N')), 0);
  IF (v_transcount > 0) THEN
    RAISE EXCEPTION 'Some Sale Invoices are not posted. Kindly post them first';
    return_value := -1;
    RETURN;
  END IF;
  v_transcount := coalesce((SELECT count(*) FROM dbo.advsaleledger WHERE (posted = 'N')), 0);
  IF (v_transcount > 0) THEN
    RAISE EXCEPTION 'Some Advanced Sale Invoices are not posted. Kindly post them first';
    return_value := -1;
    RETURN;
  END IF;
  v_transcount := coalesce((SELECT count(*) FROM dbo.srledger WHERE (posted = 'N')), 0);
  IF (v_transcount > 0) THEN
    RAISE EXCEPTION 'Some Sale Returns are not posted. Kindly post them first';
    return_value := -1;
    RETURN;
  END IF;
  v_transcount := coalesce((SELECT count(*) FROM dbo.srbufferledger WHERE (posted = 'N')), 0);
  IF (v_transcount > 0) THEN
    RAISE EXCEPTION 'Some Sale Return Buffer Invoices are not posted. Kindly post them first';
    return_value := -1;
    RETURN;
  END IF;
  v_transcount := coalesce((SELECT count(*) FROM dbo.advpurheader WHERE (posted = 'N')), 0);
  IF (v_transcount > 0) THEN
    RAISE EXCEPTION 'Some Advanced Purchase Invoices are not posted. Kindly post them first';
    return_value := -1;
    RETURN;
  END IF;
  v_transcount := coalesce((SELECT count(*) FROM dbo.imppurheader WHERE (posted = 'N')), 0);
  IF (v_transcount > 0) THEN
    RAISE EXCEPTION 'Some Imported Purchase Invoices are not posted. Kindly post them first';
    return_value := -1;
    RETURN;
  END IF;
  v_transcount := coalesce((SELECT count(*) FROM dbo.purregister WHERE (posted = 'N')), 0);
  IF (v_transcount > 0) THEN
    RAISE EXCEPTION 'Some Purchase Register Invoices are not posted. Kindly post them first';
    return_value := -1;
    RETURN;
  END IF;
  v_transcount := coalesce((SELECT count(*) FROM dbo.prledger WHERE (posted = 'N')), 0);
  IF (v_transcount > 0) THEN
    RAISE EXCEPTION 'Some Purchase Returns are not posted. Kindly post them first';
    return_value := -1;
    RETURN;
  END IF;
  v_transcount := coalesce((SELECT count(*) FROM dbo.issueheader WHERE (posted = 'N')), 0);
  IF (v_transcount > 0) THEN
    RAISE EXCEPTION 'Some Issue Documents are not posted. Kindly post them first';
    return_value := -1;
    RETURN;
  END IF;
  v_transcount := coalesce((SELECT count(*) FROM dbo.receiptheader WHERE (posted = 'N')), 0);
  IF (v_transcount > 0) THEN
    RAISE EXCEPTION 'Some Receipt Documents are not posted. Kindly post them first';
    return_value := -1;
    RETURN;
  END IF;
  v_transcount := coalesce((SELECT count(*) FROM dbo.theader WHERE (posted = 'N')), 0);
  IF (v_transcount > 0) THEN
    RAISE EXCEPTION 'Some Godown Transfers are not posted. Kindly post them first';
    return_value := -1;
    RETURN;
  END IF;
  v_transcount := coalesce((SELECT count(*) FROM dbo.adjheader WHERE (posted = 'N')), 0);
  IF (v_transcount > 0) THEN
    RAISE EXCEPTION 'Some Stock Adjustments are not posted. Kindly post them first';
    return_value := -1;
    RETURN;
  END IF;
  v_transcount := coalesce((SELECT count(*) FROM dbo.adjbufferheader WHERE (posted = 'N')), 0);
  IF (v_transcount > 0) THEN
    RAISE EXCEPTION 'Some Stock Adjustment Buffer Documents are not posted. Kindly post them first';
    return_value := -1;
    RETURN;
  END IF;
  v_transcount := coalesce((SELECT count(*) FROM dbo.prodheader WHERE (posted = 'N')), 0);
  IF (v_transcount > 0) THEN
    RAISE EXCEPTION 'Some Production Documents are not posted. Kindly post them first';
    return_value := -1;
    RETURN;
  END IF;
  v_transcount := coalesce((SELECT count(*) FROM dbo.prodnote WHERE (posted = 'N')), 0);
  IF (v_transcount > 0) THEN
    RAISE EXCEPTION 'Some Production Note Documents are not posted. Kindly post them first';
    return_value := -1;
    RETURN;
  END IF;
  v_transcount := coalesce((SELECT count(*) FROM dbo.serviceheader WHERE (posted = 'N')), 0);
  IF (v_transcount > 0) THEN
    RAISE EXCEPTION 'Some Service Invoices are not posted. Kindly post them first';
    return_value := -1;
    RETURN;
  END IF;
  v_transcount := coalesce((SELECT count(*) FROM dbo.servicerheader WHERE (posted = 'N')), 0);
  IF (v_transcount > 0) THEN
    RAISE EXCEPTION 'Some Service Returns are not posted. Kindly post them first';
    return_value := -1;
    RETURN;
  END IF;
  v_transcount := coalesce((SELECT count(*) FROM dbo.servicepurheader WHERE (posted = 'N')), 0);
  IF (v_transcount > 0) THEN
    RAISE EXCEPTION 'Some Service Purchase Invoices are not posted. Kindly post them first';
    return_value := -1;
    RETURN;
  END IF;
  v_transcount := coalesce((SELECT count(*) FROM dbo.serviceprheader WHERE (posted = 'N')), 0);
  IF (v_transcount > 0) THEN
    RAISE EXCEPTION 'Some Service Purchase Returns are not posted. Kindly post them first';
    return_value := -1;
    RETURN;
  END IF;
  v_transcount := coalesce((SELECT count(*) FROM dbo.glheader WHERE (posted = 'N')), 0);
  IF (v_transcount > 0) THEN
    RAISE EXCEPTION 'Some Accounting Vouchers are not posted. Kindly post them first';
    return_value := -1;
    RETURN;
  END IF;
  v_transcount := coalesce((SELECT count(*) FROM dbo.notes WHERE (posted = 'N')), 0);
  IF (v_transcount > 0) THEN
    RAISE EXCEPTION 'Some Notes Payable/Reveivable are not posted. Kindly post them first';
    return_value := -1;
    RETURN;
  END IF;
  v_transcount := coalesce((SELECT count(*) FROM dbo.transactionheader WHERE (posted = 'N')), 0);
  IF (v_transcount > 0) THEN
    RAISE EXCEPTION 'Some Transaction are not posted. Kindly post them first';
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_ChildServer_AllSales_Translation ====
CREATE OR REPLACE FUNCTION dbo.sp_childserver_allsales_translation(childserver citext, usercode integer, OUT return_value integer, OUT rs1 refcursor, OUT rs2 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_childserver citext;
  v_usercode integer;
  v_refund numeric(10,2);
  v_refundamt numeric(10,2);
  v_invtotal numeric(15,2);
  v_sale_invtotal numeric(15,2);
  v_ret_invtotal numeric(15,2);
  v_invtotal_diff numeric(15,2);
  v_saleinvcode integer;
  v_srinvcode integer;
  v_sale_rowcount integer;
  v_continue integer;
  v_rt_code integer;
  v_err integer;
  v_invcounter integer;
  v_invcode integer;
  v_sale numeric(15,4);
  v_salereturn numeric(15,4);
  v_thischildserver citext;
  v_flag integer;
  v_invtype integer;
  v_dt timestamp(3);
  _r1 record;
  _rc integer;
BEGIN
  v_childserver := childserver;
  v_usercode := usercode;
  -- SET NOCOUNT ON
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  v_invtype := 1;
  _rc := 1;
  WHILE (v_invtype <= 3) LOOP
    DROP TABLE IF EXISTS tmp_saletemp;
    CREATE TEMP TABLE tmp_saletemp (
    id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    childserver citext NOT NULL,
    invcode integer,
    sale numeric(15,4),
    salereturn numeric(15,4),
    refundamt numeric(10,2),
    invtotal numeric(15,2)
) ON COMMIT DROP;
    INSERT INTO tmp_saletemp (childserver, invcode, sale, salereturn, refundamt, invtotal) SELECT h.childserver, h.saleinvcode AS invcode, coalesce((SELECT sum(d.looseqty) FROM dbo.imp_saledetail AS d WHERE ((h.saleinvcode = d.saleinvcode) AND (d.looseqty > 0))), 0) AS sale, 0 AS salereturn, 0 AS refundamt, h.invtotal FROM dbo.imp_saleledger AS h WHERE ((((v_invtype = 1) AND (h.childserver = (CASE WHEN (length(rtrim(v_childserver)) > 0) THEN v_childserver ELSE h.childserver END)::citext)) AND (h.transmit = 'Y')) AND (h.transmited = 'N')) UNION ALL SELECT h.childserver, h.srinvcode AS invcode, 0.00 AS sale, coalesce((SELECT sum(d.looseqty) FROM dbo.imp_srdetail AS d WHERE ((h.srinvcode = d.srinvcode) AND (d.looseqty > 0))), 0) AS salereturn, 0 AS refundamt, h.invtotal FROM dbo.imp_srledger AS h WHERE ((((v_invtype = 3) AND (h.childserver = (CASE WHEN (length(rtrim(v_childserver)) > 0) THEN v_childserver ELSE h.childserver END)::citext)) AND (h.transmit = 'Y')) AND (h.transmited = 'N')) UNION ALL SELECT h.childserver, h.advsaleinvcode AS invcode, coalesce((SELECT sum(d.looseqty) FROM dbo.imp_advsaledetail AS d WHERE ((h.advsaleinvcode = d.advsaleinvcode) AND (d.looseqty > 0))), 0) AS sale, coalesce((SELECT sum(abs(d.looseqty)) FROM dbo.imp_advsaledetail AS d WHERE ((h.advsaleinvcode = d.advsaleinvcode) AND (d.looseqty < 0))), 0) AS salereturn, h.refundamt AS refundamt, h.invtotal FROM dbo.imp_advsaleledger AS h WHERE ((((v_invtype = 2) AND (h.childserver = (CASE WHEN (length(rtrim(v_childserver)) > 0) THEN v_childserver ELSE h.childserver END)::citext)) AND (h.transmit = 'Y')) AND (h.transmited = 'N')) ORDER BY 1, 2;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc < 0)) THEN
      IF (v_invtype = 1) THEN
        RAISE EXCEPTION 'Unable to Fetch Information of Sale Inv. No. % ', v_invcode;
      END IF;
      IF (v_invtype = 3) THEN
        RAISE EXCEPTION 'Unable to Fetch Information of S/R Inv. No. % ', v_invcode;
      ELSE
        RAISE EXCEPTION 'Unable to Fetch Information of Advance Sale Inv. No. % ', v_invcode;
      END IF;
      v_continue := -1;
      _rc := 1;
    ELSE
      v_sale_rowcount := coalesce((SELECT count(*) FROM tmp_saletemp AS saletemp), 0);
      _rc := 1;
      v_continue := 0;
      _rc := 1;
      v_invcounter := 1;
      _rc := 1;
    END IF;
    WHILE ((((v_sale_rowcount > 0)) AND ((v_continue >= 0))) AND ((v_invcounter <= v_sale_rowcount))) LOOP
      _rc := 0;
      FOR _r1 IN SELECT invcode AS c1, coalesce(sale, 0) AS c2, coalesce(salereturn, 0) AS c3, coalesce(refundamt, 0) AS c4, childserver AS c5, invtotal AS c6, NULL AS c7, NULL AS c8 FROM tmp_saletemp AS saletemp WHERE (id = v_invcounter) LOOP
        _rc := _rc + 1;
        v_invcode := _r1.c1;
        v_sale := _r1.c2;
        v_salereturn := _r1.c3;
        v_refundamt := _r1.c4;
        v_thischildserver := _r1.c5;
        v_invtotal := _r1.c6;
        v_saleinvcode := _r1.c7;
        v_srinvcode := _r1.c8;
      END LOOP;
      IF ((0 <> 0) OR (_rc <= 0)) THEN
        IF (v_invtype = 1) THEN
          RAISE EXCEPTION 'Unable to Fetch Information of Sale Inv. No. % ', v_invcode;
        END IF;
        IF (v_invtype = 3) THEN
          RAISE EXCEPTION 'Unable to Fetch Information of S/R Inv. No. % ', v_invcode;
        ELSE
          RAISE EXCEPTION 'Unable to Fetch Information of Advance Sale Inv. No. % ', v_invcode;
        END IF;
        v_continue := -1;
        _rc := 1;
      END IF;
      IF ((v_sale > 0) AND (v_continue = 0)) THEN
        IF ((v_refundamt > 0) AND (v_salereturn = 0)) THEN
          v_refund := v_refundamt;
          _rc := 1;
        ELSE
          v_refund := 0;
          _rc := 1;
        END IF;
        v_continue := 0;
        _rc := 1;
        SELECT r.return_value INTO v_rt_code FROM dbo.sp_translate_childeserver_sale(childserver => v_thischildserver, invtype => v_invtype, invcode => v_invcode, usercode => v_usercode, refund => v_refund, saleinvcode => v_saleinvcode) AS r;
        IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
          IF (v_invtype = 1) THEN
            RAISE EXCEPTION 'Unable to Generate Sale Invoice No. % FROM Sale Inv. No. % ', v_saleinvcode, v_invcode;
          ELSE
            RAISE EXCEPTION 'Unable to Generate Sale Invoice No. % FROM Advance Sale Inv. No. % ', v_saleinvcode, v_invcode;
          END IF;
          v_continue := -1;
          _rc := 1;
        END IF;
        IF (v_saleinvcode > 0) THEN
          v_sale_invtotal := dbo.fn_getsaleinvtotal(v_saleinvcode);
          _rc := 1;
        ELSE
          v_sale_invtotal := 0;
          _rc := 1;
        END IF;
        v_flag := 1;
        _rc := 1;
      END IF;
      IF ((v_salereturn > 0) AND (v_continue = 0)) THEN
        IF (v_invtype = 2) THEN
          IF (v_refundamt > 0) THEN
            v_refund := v_refundamt;
            _rc := 1;
          ELSE
            v_refund := 0;
            _rc := 1;
          END IF;
          v_continue := 0;
          _rc := 1;
          SELECT r.return_value, r.rs1 INTO v_rt_code, rs1 FROM dbo.sp_translate_childeserver_salereturn(childserver => v_thischildserver, advsaleinvcode => v_invcode, usercode => v_usercode, refund => v_refund, srinvcode => v_srinvcode) AS r;
          IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
            RAISE EXCEPTION 'Unable to Generate Sale Return No. % FROM Advance Sale Inv. No. % ', v_srinvcode, v_invcode;
            v_continue := -1;
            _rc := 1;
          END IF;
        END IF;
        IF (v_invtype = 3) THEN
          v_refund := 0;
          _rc := 1;
          v_continue := 0;
          _rc := 1;
          SELECT r.return_value, r.srinvcode, r.rs1 INTO v_rt_code, v_srinvcode, rs2 FROM dbo.sp_translate_childeserver_sreturn(childserver => v_thischildserver, oldsrinvcode => v_invcode, usercode => v_usercode, srinvcode => v_srinvcode) AS r;
          IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
            RAISE EXCEPTION 'Unable to Generate Sale Return No. % FROM Old S/R No. % ', v_srinvcode, v_invcode;
            v_continue := -1;
            _rc := 1;
          END IF;
        END IF;
        IF (v_srinvcode > 0) THEN
          v_ret_invtotal := dbo.fn_getsrinvtotal(v_srinvcode);
          _rc := 1;
        ELSE
          v_ret_invtotal := 0;
          _rc := 1;
        END IF;
        v_flag := 1;
        _rc := 1;
      END IF;
      IF (v_invtype = 2) THEN
        v_invtotal_diff := ((coalesce(v_invtotal, 0) - coalesce(v_sale_invtotal, 0)) - coalesce(v_ret_invtotal, 0));
        _rc := 1;
      END IF;
      IF (v_saleinvcode > 0) THEN
        IF (v_invtotal_diff > 0) THEN
          UPDATE dbo.saleledger SET misccharges = (coalesce(misccharges, 0) + v_invtotal_diff) WHERE (saleinvcode = v_saleinvcode);
          GET DIAGNOSTICS _rc = ROW_COUNT;
        END IF;
        IF (v_invtotal_diff < 0) THEN
          IF (v_sale_invtotal > abs(v_invtotal_diff)) THEN
            UPDATE dbo.saleledger SET flatdisc = (coalesce(flatdisc, 0) + abs(v_invtotal_diff)) WHERE (saleinvcode = v_saleinvcode);
            GET DIAGNOSTICS _rc = ROW_COUNT;
          ELSE
            UPDATE dbo.saleledger SET flatdisc = (coalesce(flatdisc, 0) + coalesce(v_sale_invtotal, 0)) WHERE (saleinvcode = v_saleinvcode);
            GET DIAGNOSTICS _rc = ROW_COUNT;
          END IF;
          UPDATE dbo.saleledger SET invtotal = coalesce(dbo.fn_getsaleinvtotal(v_saleinvcode), 0) WHERE (saleinvcode = v_saleinvcode);
          GET DIAGNOSTICS _rc = ROW_COUNT;
        END IF;
        v_sale_invtotal := dbo.fn_getsaleinvtotal(v_saleinvcode);
        _rc := 1;
      ELSE
        v_sale_invtotal := 0;
        _rc := 1;
      END IF;
      v_invtotal_diff := ((coalesce(v_invtotal, 0) - coalesce(v_sale_invtotal, 0)) - coalesce(v_ret_invtotal, 0));
      _rc := 1;
      IF (v_srinvcode > 0) THEN
        IF ((v_sale <= 0) AND (v_invtype <> 3)) THEN
          UPDATE dbo.srledger SET flatdisc = coalesce(misccharges, 0), misccharges = coalesce(flatdisc, 0) WHERE (srinvcode = v_srinvcode);
          GET DIAGNOSTICS _rc = ROW_COUNT;
        END IF;
        IF (((v_invtotal_diff > 0) AND (v_saleinvcode <= 0)) AND (v_invtype <> 3)) THEN
          IF (v_ret_invtotal > abs(v_invtotal_diff)) THEN
            UPDATE dbo.srledger SET flatdisc = (coalesce(flatdisc, 0) + abs(v_invtotal_diff)) WHERE (srinvcode = v_srinvcode);
            GET DIAGNOSTICS _rc = ROW_COUNT;
          ELSE
            UPDATE dbo.srledger SET flatdisc = (coalesce(flatdisc, 0) + abs(v_ret_invtotal)) WHERE (srinvcode = v_srinvcode);
            GET DIAGNOSTICS _rc = ROW_COUNT;
          END IF;
        END IF;
        IF ((v_invtotal_diff < 0) AND (v_invtype <> 3)) THEN
          UPDATE dbo.srledger SET misccharges = (coalesce(misccharges, 0) + abs(v_invtotal_diff)) WHERE (srinvcode = v_srinvcode);
          GET DIAGNOSTICS _rc = ROW_COUNT;
        END IF;
        UPDATE dbo.srledger SET invtotal = coalesce(dbo.fn_getsrinvtotal(v_srinvcode), 0) WHERE (srinvcode = v_srinvcode);
        GET DIAGNOSTICS _rc = ROW_COUNT;
      END IF;
      v_invcounter := (v_invcounter + 1);
      _rc := 1;
    END LOOP;
    IF (v_continue = 0) THEN
      IF (v_invtype = 1) THEN
        UPDATE dbo.imp_saleledger SET transmited = 'Y' WHERE (((childserver = (CASE WHEN (length(rtrim(v_childserver)) > 0) THEN v_childserver ELSE childserver END)::citext) AND (transmit = 'Y')) AND (transmited = 'N'));
        GET DIAGNOSTICS _rc = ROW_COUNT;
      END IF;
      IF (v_invtype = 3) THEN
        UPDATE dbo.imp_srledger SET transmited = 'Y' WHERE (((childserver = (CASE WHEN (length(rtrim(v_childserver)) > 0) THEN v_childserver ELSE childserver END)::citext) AND (transmit = 'Y')) AND (transmited = 'N'));
        GET DIAGNOSTICS _rc = ROW_COUNT;
      ELSE
        UPDATE dbo.imp_advsaleledger SET transmited = 'Y' WHERE (((childserver = (CASE WHEN (length(rtrim(v_childserver)) > 0) THEN v_childserver ELSE childserver END)::citext) AND (transmit = 'Y')) AND (transmited = 'N'));
        GET DIAGNOSTICS _rc = ROW_COUNT;
      END IF;
    END IF;
    IF ((v_continue = 0) AND (v_flag = 1)) THEN
      v_dt := localtimestamp(3);
      _rc := 1;
      v_continue := 0;
      _rc := 1;
      SELECT r.return_value INTO v_rt_code FROM dbo.sp_set_datetime_preference(prefname => 'LastSaleSynchronized', prefvalue => v_dt) AS r;
      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
        RAISE EXCEPTION 'Unable to Record Last Sale Synchronization Information in Software Preferences';
        v_continue := -1;
        _rc := 1;
      END IF;
    END IF;
    DROP TABLE IF EXISTS tmp_saletemp;
    v_invtype := (v_invtype + 1);
    _rc := 1;
  END LOOP;
  return_value := v_continue;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_ChildServer_Sale_Translation ====
CREATE OR REPLACE FUNCTION dbo.sp_childserver_sale_translation(childserver citext, invtype integer, custcode integer, startdate timestamp, enddate timestamp, usercode integer, OUT return_value integer, OUT rs1 refcursor, OUT rs2 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_childserver citext;
