BEGIN
  v_childserver := childserver;
  v_invtype := invtype;
  v_custcode := custcode;
  v_startdate := startdate;
  v_enddate := enddate;
  v_usercode := usercode;
  -- SET NOCOUNT ON
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  DROP TABLE IF EXISTS tmp_saletemp;
  CREATE TEMP TABLE tmp_saletemp (
    id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
