-- ==== proc SP_ClearActivityMonitorHistory ====
CREATE OR REPLACE FUNCTION dbo.sp_clearactivitymonitorhistory(startdate timestamp, enddate timestamp, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_startdate timestamp(3);
  v_enddate timestamp(3);
  v_rowsaffected integer;
  v_err integer;
  _rc integer;
BEGIN
  v_startdate := startdate;
  v_enddate := enddate;
  DELETE FROM dbo.activitymonitor WHERE (date BETWEEN v_startdate AND v_enddate);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_rowsaffected := _rc;
  v_err := 0;
  _rc := 1;
  IF ((v_rowsaffected = 0) AND (v_err = 0)) THEN
    RAISE EXCEPTION 'Unable to Clear Activity Monitor History';
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_CLOpeningBalance ====
CREATE OR REPLACE FUNCTION dbo.sp_clopeningbalance(al_acccode numeric, ad_date timestamp, INOUT af_openbalance double precision, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_al_acccode numeric(5,0);
  v_ad_date timestamp(3);
  v_af_openbalance double precision;
  v_ln_openbalance numeric(12,2);
BEGIN
  v_al_acccode := al_acccode;
  v_ad_date := ad_date;
  v_af_openbalance := af_openbalance;
  DROP TABLE IF EXISTS tmp_lt_pvamts;
  CREATE TEMP TABLE tmp_lt_pvamts (
    debit numeric(15,2) NOT NULL,
    credit numeric(15,2) NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_pvamts SELECT coalesce((round((((sum((saledetail.looseqty * saledetail.unitsalestax)) + sum(round(((((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc))))) * saledetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc)))))) * ((1 - ((.01 * saleledger.discperc))))) - saleledger.flatdisc)) * ((saleledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) + round((((((sum((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc)))))) * ((1 - ((.01 * saleledger.discperc))))) + saleledger.misccharges) + saleledger.salestax) - saleledger.flatdisc))::numeric, 0)), 0) AS debit, 0 AS credit FROM dbo.saleledger, dbo.saledetail WHERE (((((saleledger.saleinvcode = saledetail.saleinvcode) AND (saleledger.salecatcode = 2)) AND (saleledger.date <= v_ad_date)) AND (saleledger.posted = 'Y')) AND (saleledger.custcode = v_al_acccode)) GROUP BY saleledger.saleinvcode, salecatcode, saleledger.date, saleledger.discperc, saleledger.misccharges, saleledger.salestax, saleledger.flatdisc, saleledger.invgstperc1;
  INSERT INTO tmp_lt_pvamts SELECT 0 AS debit, coalesce((round((((sum((srdetail.looseqty * srdetail.unitsalestax)) + sum(round(((((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc))))) * srdetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc)))))) * ((1 - ((.01 * srledger.discperc))))) - srledger.flatdisc)) * ((srledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) + round((((((sum((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc)))))) * ((1 - ((.01 * srledger.discperc))))) + srledger.misccharges) + srledger.salestax) - srledger.flatdisc))::numeric, 0)), 0) AS credit FROM dbo.srledger, dbo.srdetail WHERE (((((srledger.srinvcode = srdetail.srinvcode) AND (srledger.srcatcode = 7)) AND (srledger.date <= v_ad_date)) AND (srledger.posted = 'Y')) AND (srledger.custcode = v_al_acccode)) GROUP BY srledger.srinvcode, srledger.srcatcode, srledger.date, srledger.discperc, srledger.misccharges, srledger.salestax, srledger.flatdisc, srledger.invgstperc1;
  INSERT INTO tmp_lt_pvamts SELECT coalesce((((sum((coalesce(servicedetail.price, 0) * ((1 - ((.01 * servicedetail.discperc)))))) * ((1 - ((.01 * serviceheader.discperc))))) + serviceheader.misccharges) - serviceheader.flatdisc), 0) AS debit, 0.0 AS credit FROM dbo.serviceheader, dbo.servicedetail WHERE (((((serviceheader.serviceinvcode = servicedetail.serviceinvcode) AND (serviceheader.servicecatcode = 11)) AND (serviceheader.date <= v_ad_date)) AND (serviceheader.posted = 'Y')) AND (serviceheader.custcode = v_al_acccode)) GROUP BY serviceheader.serviceinvcode, serviceheader.servicecatcode, serviceheader.date, serviceheader.discperc, serviceheader.misccharges, serviceheader.flatdisc;
  INSERT INTO tmp_lt_pvamts SELECT 0.0 AS debit, coalesce((((sum((coalesce(servicerdetail.serviceprice, 0) * ((1 - ((.01 * servicerdetail.discperc)))))) * ((1 - ((.01 * servicerheader.discperc))))) + servicerheader.misccharges) - servicerheader.flatdisc), 0) AS credit FROM dbo.servicerheader, dbo.servicerdetail WHERE (((((servicerheader.servicerinvcode = servicerdetail.servicerinvcode) AND (servicerheader.servicercatcode = 14)) AND (servicerheader.date <= v_ad_date)) AND (servicerheader.posted = 'Y')) AND (servicerheader.custcode = v_al_acccode)) GROUP BY servicerheader.servicerinvcode, servicerheader.servicercatcode, servicerheader.date, servicerheader.discperc, servicerheader.misccharges, servicerheader.flatdisc;
  INSERT INTO tmp_lt_pvamts SELECT coalesce(sum(gldetail.debit), 0), coalesce(sum(gldetail.credit), 0) FROM dbo.glheader, dbo.gldetail WHERE ((((glheader.glvochcode = gldetail.glvochcode) AND (glheader.date <= v_ad_date)) AND (glheader.posted = 'Y')) AND (gldetail.acccode = v_al_acccode));
  INSERT INTO tmp_lt_pvamts SELECT 0, coalesce(sum(notes.amount), 0) FROM dbo.notes WHERE ((((notes.notecatcode = 1) AND (notes.posted = 'Y')) AND (notes.postdate <= v_ad_date)) AND (notes.acccode = v_al_acccode));
  v_ln_openbalance := (SELECT coalesce((sum(debit) - sum(credit)), 0) FROM tmp_lt_pvamts AS lt_pvamts);
  v_af_openbalance := (SELECT (v_ln_openbalance)::double precision);
  OPEN rs1 FOR SELECT v_af_openbalance;
  DROP TABLE IF EXISTS tmp_lt_pvamts;
  return_value := 0;
  af_openbalance := v_af_openbalance;
  RETURN;
END
$body$;

-- ==== proc SP_COLUMNLIST ====
CREATE OR REPLACE FUNCTION dbo.sp_columnlist(owner citext, "table" citext, INOUT list citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_owner citext;
  v_table citext;
  v_list citext;
  v_table_id integer;
  v_err integer;
  v_rc integer;
  v_full_table_name citext;
  v_colname citext;
  v_typename citext;
  v_position smallint;
  v_versioninfo citext;
  v_dbversion citext;
  cur_curs_collist refcursor;
  _fs integer := -1;
BEGIN
  v_owner := owner;
  v_table := "table";
  v_list := list;
  SELECT r.return_value, r.versioninfo INTO v_rc, v_versioninfo FROM dbo.sp_dbms_version(versioninfo => v_versioninfo) AS r;
  IF (dbo.tsql_charindex(('Microsoft SQL Server 2012')::citext, (v_versioninfo)::citext, 1) > 0) THEN
    v_dbversion := '2012';
  ELSE
    v_dbversion := '2000';
  END IF;
  v_full_table_name := ((ltrim(rtrim(v_owner)) || '.') || ltrim(rtrim(v_table)));
  -- SET @table_id = OBJECT_ID(@full_table_name)
  RAISE EXCEPTION 'untranslated T-SQL (OBJECT_ID of non-literal)' USING ERRCODE = '0A000';
  v_err := 0;
  IF ((v_err <> 0) OR (v_table_id IS NULL)) THEN
    RAISE EXCEPTION 'Can Not Produce Column List, Invalid Object Refered: Name = %', v_full_table_name;
    return_value := -1;
    list := v_list;
    RETURN;
  END IF;
  IF (v_dbversion = '2012') THEN
  ELSE
  END IF;
  -- OPEN curs_collist
  RAISE EXCEPTION 'untranslated T-SQL (system table sysobjects)' USING ERRCODE = '0A000';
  FETCH NEXT FROM cur_curs_collist INTO v_colname, v_typename, v_position;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    IF (((lower(right(rtrim(ltrim(v_typename)), 8)))::citext <> 'identity') AND ((lower(right(rtrim(ltrim(v_typename)), 5)))::citext <> 'image')) THEN
      IF (v_list <> '') THEN
        v_list := (v_list || ',');
      END IF;
      v_list := (v_list || ltrim(rtrim(v_colname)));
    END IF;
    FETCH NEXT FROM cur_curs_collist INTO v_colname, v_typename, v_position;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_curs_collist;
  -- DEALLOCATE curs_collist
  IF (v_list = '') THEN
    return_value := -1;
    list := v_list;
    RETURN;
  ELSE
    return_value := 0;
    list := v_list;
    RETURN;
  END IF;
  return_value := 0;
  list := v_list;
  RETURN;
END
$body$;

-- ==== proc SP_Compare_Remote_VersionInfo ====
CREATE OR REPLACE FUNCTION dbo.sp_compare_remote_versioninfo(prefix citext, INOUT versionsyn integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_prefix citext;
  v_versionsyn integer;
  v_sequenceid integer;
  v_appversion integer;
  v_dbstatus integer;
  v_qry citext;
  v_localsequenceid integer;
  v_localappversion integer;
  v_localdbstatus integer;
  _dq1 text;
BEGIN
  v_prefix := prefix;
  v_versionsyn := versionsyn;
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  DELETE FROM dbo.reportdata;
  v_qry := (('INSERT INTO REPORTDATA (code1, code2, code3) SELECT * FROM ' || v_prefix) || 'Sequence');
  _dq1 := v_qry;
  IF _dq1 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq1);
  END IF;
  v_sequenceid := trunc((SELECT max(code1) FROM dbo.reportdata))::integer;
  v_appversion := trunc((SELECT max(code2) FROM dbo.reportdata))::integer;
  v_dbstatus := trunc((SELECT max(code3) FROM dbo.reportdata))::integer;
  v_localsequenceid := trunc(coalesce((SELECT sequenceid FROM dbo.sequence), 0))::integer;
  v_localappversion := trunc(coalesce((SELECT appversion FROM dbo.sequence), 0))::integer;
  v_localdbstatus := coalesce((SELECT dbstatus FROM dbo.sequence), 0);
  IF (((v_sequenceid = v_localsequenceid) AND (v_appversion = v_localappversion)) AND (v_dbstatus = v_localdbstatus)) THEN
    v_versionsyn := 1;
  END IF;
  IF (v_versionsyn = 0) THEN
    RAISE EXCEPTION 'Unable to Continue due to Local and Remote version Conflicts.';
    return_value := -1;
    versionsyn := v_versionsyn;
    RETURN;
  END IF;
  return_value := 0;
  versionsyn := v_versionsyn;
  RETURN;
  return_value := 0;
  versionsyn := v_versionsyn;
  RETURN;
END
$body$;

-- ==== proc sp_ConsolidatedExpiryIntimation ====
CREATE OR REPLACE FUNCTION dbo.sp_consolidatedexpiryintimation(usercode smallint, list citext, acccode smallint, custcode smallint, type smallint, INOUT intimationcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_usercode smallint;
  v_list citext;
  v_acccode smallint;
  v_custcode smallint;
  v_type smallint;
  v_intimationcode integer;
  v_continue integer;
  v_rt_code integer;
  v_err integer;
  v_totalrows integer;
  v_rowcount integer;
  v_counter integer;
  v_serialno integer;
  _rc integer;
BEGIN
  v_usercode := usercode;
  v_list := list;
  v_acccode := acccode;
  v_custcode := custcode;
  v_type := type;
  v_intimationcode := intimationcode;
  -- SET NOCOUNT ON
  DROP TABLE IF EXISTS tv_sp_consolidatedexpiryintimation_intimation;
  CREATE TEMP TABLE tv_sp_consolidatedexpiryintimation_intimation (
    code integer
) ON COMMIT DROP;
  INSERT INTO tv_sp_consolidatedexpiryintimation_intimation (code) SELECT intimationcode FROM dbo.expiryintimation WHERE ((intimationtypecode = v_type) AND (intimationcode IN (SELECT code FROM dbo.udf_stringtotabl(v_list, ',') AS udf_stringtotabl)));
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_rowcount := coalesce((SELECT count(*) FROM tv_sp_consolidatedexpiryintimation_intimation AS intimation), 0);
  _rc := 1;
  IF (v_rowcount <= 0) THEN
    RAISE EXCEPTION 'No Expiry Intimation Selected';
    return_value := -1;
    intimationcode := v_intimationcode;
    RETURN;
  END IF;
  SELECT r.return_value, r.key INTO v_rt_code, v_intimationcode FROM dbo.sp_gettabmaxkey(tabname => 'ExpiryIntimation', key => v_intimationcode) AS r;
  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
    RAISE EXCEPTION 'New Expiry Intimation Code Generation Problem';
    return_value := -1;
    intimationcode := v_intimationcode;
    RETURN;
  END IF;
  v_serialno := coalesce((SELECT counter FROM dbo.intimationtype WHERE (intimationtypecode = v_type) FOR UPDATE OF intimationtype), 0);
  _rc := 1;
  IF (v_serialno > 0) THEN
    v_serialno := (v_serialno + 1);
    _rc := 1;
    UPDATE dbo.intimationtype SET counter = v_serialno WHERE (intimationtypecode = v_type);
    GET DIAGNOSTICS _rc = ROW_COUNT;
  END IF;
  INSERT INTO dbo.expiryintimation (intimationcode, intimationtypecode, intimationserialno, acccode, date, refno, remarks1, remarks2, usercode, posted, postedby, postdate, custcode) VALUES (v_intimationcode, v_type, v_serialno, v_acccode, localtimestamp(3), '', 'Consolidated Expiry Intimation', ('Included Intimations are:- ' || v_list), v_usercode, 'N', v_usercode, localtimestamp(3), v_custcode);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((0 <> 0) OR (_rc = 0)) THEN
    RAISE EXCEPTION 'Expiry Intimation Header Row Insertion Problem for Expiry Intimation Code %', v_intimationcode;
    return_value := -1;
    intimationcode := v_intimationcode;
    RETURN;
  END IF;
  INSERT INTO dbo.expiryintimationdetail (intimationcode, icode, batch, expiry, qty, packunits, packprice, price, invoicecode, invoicedate, refno, refdate, lastacccode, manfcode) SELECT t.intimationcode, t.icode, t.batch, t.expiry, t.qty, t.packunits, t.packprice, t.price, t.invoicecode, t.invoicedate, t.refno, t.refdate, t.lastacccode, t.manfcode FROM (SELECT v_intimationcode AS intimationcode, d.icode, d.batch, d.expiry, sum(d.qty) AS qty, max(d.packunits) AS packunits, max(d.packprice) AS packprice, max(d.price) AS price, max(d.invoicecode) AS invoicecode, max(d.invoicedate) AS invoicedate, max(d.refno) AS refno, max(d.refdate) AS refdate, max(d.lastacccode) AS lastacccode, max(d.manfcode) AS manfcode FROM dbo.expiryintimationdetail AS d, dbo.expiryintimation AS h WHERE ((h.intimationcode IN (SELECT code FROM tv_sp_consolidatedexpiryintimation_intimation AS intimation)) AND (h.intimationcode = d.intimationcode)) GROUP BY d.icode, d.batch, d.expiry) AS t, dbo.item AS i WHERE (t.icode = i.icode) ORDER BY i.name;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((0 <> 0) OR (_rc = 0)) THEN
    RAISE EXCEPTION 'Expiry Intimation Detail Row Insertion Problem for Expiry Intimation Code =%', v_intimationcode;
    return_value := -1;
    intimationcode := v_intimationcode;
    RETURN;
  END IF;
  return_value := 0;
  intimationcode := v_intimationcode;
  RETURN;
  return_value := 0;
  intimationcode := v_intimationcode;
  RETURN;
END
$body$;

-- ==== proc sp_ConsolidateQuotation_as_SaleOrder ====
CREATE OR REPLACE FUNCTION dbo.sp_consolidatequotation_as_saleorder(usercode smallint, list citext, INOUT saleordercode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_usercode smallint;
  v_list citext;
  v_saleordercode integer;
  v_continue integer;
  v_rt_code integer;
  v_err integer;
  v_totalrows integer;
  v_rowcount integer;
  v_counter integer;
  v_module integer;
  v_headerinvno integer;
  v_headerno integer;
  _rc integer;
BEGIN
  v_usercode := usercode;
  v_list := list;
  v_saleordercode := saleordercode;
  -- SET NOCOUNT ON
  DROP TABLE IF EXISTS tv_sp_consolidatequotation_as_saleorder_quot;
  CREATE TEMP TABLE tv_sp_consolidatequotation_as_saleorder_quot (
    code integer
) ON COMMIT DROP;
  INSERT INTO tv_sp_consolidatequotation_as_saleorder_quot (code) SELECT code FROM dbo.udf_stringtotabl(v_list, ',') AS udf_stringtotabl;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_rowcount := coalesce((SELECT count(*) FROM tv_sp_consolidatequotation_as_saleorder_quot AS quot), 0);
  _rc := 1;
  IF (v_rowcount <= 0) THEN
    RAISE EXCEPTION 'No Quotations Selected';
    return_value := -1;
    saleordercode := v_saleordercode;
    RETURN;
  END IF;
  SELECT r.return_value, r.key INTO v_rt_code, v_saleordercode FROM dbo.sp_gettabmaxkey(tabname => 'SaleOrderHeader', key => v_saleordercode) AS r;
  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
    RAISE EXCEPTION 'New Order Code Generation Problem';
    return_value := -1;
    saleordercode := v_saleordercode;
    RETURN;
  END IF;
  v_module := 12;
  _rc := 1;
  v_headerno := 1;
  _rc := 1;
  SELECT r.return_value, r.key INTO v_rt_code, v_headerinvno FROM dbo.sp_getheadertabmaxkey(headercode => (v_headerno)::smallint, modulecode => (v_module)::smallint, key => v_headerinvno) AS r;
  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
    RAISE EXCEPTION 'New Header Inv Code Generation Problem';
    return_value := -1;
    saleordercode := v_saleordercode;
    RETURN;
  END IF;
