  INSERT INTO dbo.saleinvdetail (saleinvcode, icode, gcode, batch, expiry, looseqty, packunits, saleprice, avgprice, rate, discperc, itemflatdisc, saleitemdescription, packprice, unitsalestax, gstperc, saleutn, bonusqty, claimable, rowgroup, claimablediscperc, packqtyforsale, bonuspackqtyforsale, descicode, sourcesaleinvcode, salerowid, issuerowid, alternatepurprice) SELECT saleinvcode, icode, gcode, batch, expiry, looseqty, packunits, saleprice, avgprice, rate, discperc, itemflatdisc, saleitemdescription, packprice, unitsalestax, gstperc, saleutn, bonusqty, claimable, rowgroup, claimablediscperc, packqtyforsale, bonuspackqtyforsale, descicode, sourcesaleinvcode, salerowid, issuerowid, alternatepurprice FROM dbo.sbufferdetail WHERE (saleinvcode IN (SELECT saleinvcode FROM dbo.saleledger WHERE (impactinventory = 'N'))) ORDER BY rowid;
