-- ==== proc SP_CreateAutoTriggerSMS ====
CREATE OR REPLACE FUNCTION dbo.sp_createautotriggersms(ai_list citext, ai_moduleid smallint, ai_event citext, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_list citext;
  v_ai_moduleid smallint;
  v_ai_event citext;
  v_err integer;
  v_rowcount integer;
  v_rowid integer;
  v_smstemplatecode integer;
  v_smsgenerated integer;
  v_totalsmsgen integer;
BEGIN
  v_ai_list := ai_list;
  v_ai_moduleid := ai_moduleid;
  v_ai_event := ai_event;
  -- SET NOCOUNT ON
  DROP TABLE IF EXISTS tmp_templatetosend;
  CREATE TEMP TABLE tmp_templatetosend (
    rowid integer GENERATED BY DEFAULT AS IDENTITY,
    templatecode integer
) ON COMMIT DROP;
  INSERT INTO tmp_templatetosend (templatecode) SELECT smstemplatecode FROM dbo.sms_template WHERE (((((moduleid = v_ai_moduleid) AND (scheduled = 'N')) AND (event = v_ai_event)) AND (enabled = 'Y')) AND (active = 'Y'));
  v_rowcount := coalesce((SELECT count(*) FROM tmp_templatetosend AS templatetosend), 0);
  IF (v_rowcount > 0) THEN
    v_totalsmsgen := 0;
    v_rowid := 1;
    WHILE (v_rowid <= v_rowcount) LOOP
      v_smsgenerated := 0;
      v_smstemplatecode := (SELECT templatecode FROM tmp_templatetosend AS templatetosend WHERE (rowid = v_rowid));
      SELECT r.return_value, r.ai_totsms, r.rs1 INTO v_err, v_smsgenerated, rs1 FROM dbo.sp_createdatasms(as_list => v_ai_list, ai_smstemplatecode => v_smstemplatecode, ai_totsms => v_smsgenerated) AS r;
      IF ((v_err <> 0) OR (0 <> 0)) THEN
        RAISE EXCEPTION 'Auto Triggered SMS Generation Problem, SMS Template Code : %', v_smstemplatecode;
        return_value := -1;
        RETURN;
      ELSE
        v_totalsmsgen := (v_totalsmsgen + v_smsgenerated);
      END IF;
      v_rowid := (v_rowid + 1);
    END LOOP;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_CreateDataSMS ====
CREATE OR REPLACE FUNCTION dbo.sp_createdatasms(as_list citext, ai_smstemplatecode integer, INOUT ai_totsms integer, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_as_list citext;
  v_ai_smstemplatecode integer;
  v_ai_totsms integer;
  v_smstemplate citext;
  v_tokenvalue citext;
  v_tokenname citext;
  v_filteron citext;
  v_viewname citext;
  v_qry citext;
  v_smsto citext;
  v_smstype smallint;
  v_smsdata integer;
  v_err integer;
  v_rowcount integer;
  v_strlen integer;
  v_currpos integer;
  v_startpos integer;
  v_endpos integer;
  v_totalrows integer;
  v_sno integer;
  v_tottokens integer;
  v_phonenoexists integer;
  v_mincontactcard integer;
  v_expiry integer;
  _r1 record;
  _dq2 text;
  _dq3 text;
  _dq4 text;
  _dq5 text;
  _rc integer;
BEGIN
  v_as_list := as_list;
  v_ai_smstemplatecode := ai_smstemplatecode;
  v_ai_totsms := ai_totsms;
  -- SET NOCOUNT ON
  IF ((ltrim(rtrim(v_as_list)))::citext = '') THEN
    v_as_list := '1';
    _rc := 1;
  END IF;
  v_expiry := dbo.fn_get_int_preference('defaultsmsexpiry');
  _rc := 1;
  IF (v_expiry IS NULL) THEN
    v_expiry := 24;
    _rc := 1;
  END IF;
  _rc := 0;
  FOR _r1 IN SELECT smstypecode AS c1, smsdatacode AS c2, smstemplate AS c3, (SELECT d.viewname FROM dbo.sms_datadefinition AS d WHERE (d.smsdatacode = sms_template.smsdatacode)) AS c4, (SELECT d.filteron FROM dbo.sms_datadefinition AS d WHERE (d.smsdatacode = sms_template.smsdatacode)) AS c5 FROM dbo.sms_template WHERE (((smstemplatecode = v_ai_smstemplatecode) AND (enabled = 'Y')) AND (active = 'Y')) LOOP
    _rc := _rc + 1;
    v_smstype := _r1.c1;
    v_smsdata := _r1.c2;
    v_smstemplate := _r1.c3;
    v_viewname := _r1.c4;
    v_filteron := _r1.c5;
  END LOOP;
  IF ((length(rtrim(v_viewname)) > 0) AND (_rc > 0)) THEN
    DROP TABLE IF EXISTS tmp_inputrows;
    CREATE TEMP TABLE tmp_inputrows (
    cardcode integer,
    code citext,
    tokenvalue citext,
    smstext citext,
    smsto citext,
    rowid integer GENERATED BY DEFAULT AS IDENTITY
) ON COMMIT DROP;
    DROP TABLE IF EXISTS tmp_token;
    CREATE TEMP TABLE tmp_token (
    sno integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    startpos integer NOT NULL,
    endpos integer NOT NULL,
    tokenname citext NOT NULL,
    tokenvalue citext
) ON COMMIT DROP;
    DROP TABLE IF EXISTS tmp_eachsmsto;
    CREATE TEMP TABLE tmp_eachsmsto (
    smsto citext
) ON COMMIT DROP;
    v_qry := ((((('INSERT INTO tmp_inputrows (CardCode, Code, TokenValue, SMSText, SMSTO) SELECT DISTINCT T.ContactCardCode, P.Code, NULL, NULL, T.Mobile FROM ' || v_viewname) || ' AS T, (SELECT CODE FROM udf_StringToTabl_String(''') || v_as_list) || ''', '','')) P WHERE P.Code = T.') || v_filteron);
    _rc := 1;
    _dq2 := v_qry;
    IF _dq2 IS NOT NULL THEN
      EXECUTE dbo.tsql_dyn(_dq2);
    END IF;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_qry := (((('INSERT INTO #InputRows (CardCode, Code, TokenValue, SMSText, SMSTO) SELECT DISTINCT T.ContactCardCode, P.Code, NULL, NULL, T.Mobile FROM GetAssociatedRecipientForSMS AS T, (SELECT CODE FROM udf_StringToTabl_String(''' || v_as_list) || ''', '','')) P WHERE T.SMSTemplateCode = ') || ltrim(rtrim(dbo.tsql_str((v_ai_smstemplatecode)::numeric, 10)))) || ' AND T.ContactCardCode NOT IN (SELECT M.CardCode FROM tmp_inputrows M)');
    _rc := 1;
    _dq3 := v_qry;
    IF _dq3 IS NOT NULL THEN
      EXECUTE dbo.tsql_dyn(_dq3);
    END IF;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    UPDATE tmp_inputrows AS inputrows SET smstext = v_smstemplate;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_strlen := length(rtrim(v_smstemplate));
    _rc := 1;
    v_currpos := 1;
    _rc := 1;
    WHILE (v_currpos <= v_strlen) LOOP
      v_startpos := dbo.tsql_charindex(('«')::citext, (v_smstemplate)::citext, v_currpos);
      _rc := 1;
      IF (v_startpos > 0) THEN
        v_endpos := dbo.tsql_charindex(('»')::citext, (v_smstemplate)::citext, v_startpos);
        _rc := 1;
        v_tokenname := substring(v_smstemplate, (v_startpos + 1), ((v_endpos - v_startpos) - 1));
        _rc := 1;
        INSERT INTO tmp_token (startpos, endpos, tokenname, tokenvalue) VALUES (v_startpos, v_endpos, v_tokenname, '');
        GET DIAGNOSTICS _rc = ROW_COUNT;
        v_currpos := v_endpos;
        _rc := 1;
      ELSE
        v_currpos := (v_strlen + 1);
        _rc := 1;
      END IF;
    END LOOP;
    v_totalrows := coalesce((SELECT count(code) FROM tmp_inputrows AS inputrows), 0);
    _rc := 1;
    v_tottokens := coalesce((SELECT count(*) FROM tmp_token AS token), 0);
    _rc := 1;
    IF ((v_totalrows > 0) AND (v_tottokens > 0)) THEN
      v_mincontactcard := coalesce((SELECT min(cardcode) FROM tmp_inputrows AS inputrows), 0);
      _rc := 1;
      v_sno := 1;
      _rc := 1;
      WHILE (v_sno <= v_tottokens) LOOP
        v_tokenname := (SELECT tokenname FROM tmp_token AS token WHERE (sno = v_sno));
        _rc := 1;
        IF (v_mincontactcard > 0) THEN
          _dq4 := (((((('UPDATE tmp_inputrows SET TokenValue = (SELECT MAX(' || v_tokenname) || ') FROM ') || v_viewname) || ' WHERE ') || v_filteron) || ' = tmp_inputrows.Code  AND ContactCardCode = tmp_inputrows.CardCode)');
          IF _dq4 IS NOT NULL THEN
            EXECUTE dbo.tsql_dyn(_dq4);
          END IF;
          GET DIAGNOSTICS _rc = ROW_COUNT;
        ELSE
          _dq5 := (((((('UPDATE tmp_inputrows SET TokenValue = (SELECT MAX(' || v_tokenname) || ') FROM ') || v_viewname) || ' WHERE ') || v_filteron) || ' = tmp_inputrows.Code )');
          IF _dq5 IS NOT NULL THEN
            EXECUTE dbo.tsql_dyn(_dq5);
          END IF;
          GET DIAGNOSTICS _rc = ROW_COUNT;
        END IF;
        UPDATE tmp_inputrows AS inputrows SET smstext = replace((smstext)::citext, ((('«' || v_tokenname) || '»'))::citext, (tokenvalue)::citext) WHERE (dbo.tsql_charindex(((('«' || v_tokenname) || '»'))::citext, (smstext)::citext, 1) > 0);
        GET DIAGNOSTICS _rc = ROW_COUNT;
        v_sno := (v_sno + 1);
        _rc := 1;
      END LOOP;
      v_sno := 1;
      _rc := 1;
      WHILE (v_sno <= v_totalrows) LOOP
        v_smsto := (SELECT smsto FROM tmp_inputrows AS inputrows WHERE (rowid = v_sno));
        _rc := 1;
        DELETE FROM tmp_eachsmsto AS eachsmsto;
        GET DIAGNOSTICS _rc = ROW_COUNT;
        INSERT INTO tmp_eachsmsto SELECT DISTINCT code FROM dbo.udf_stringtotabl_string(v_smsto, ',') AS udf_stringtotabl_string;
        GET DIAGNOSTICS _rc = ROW_COUNT;
        DELETE FROM tmp_eachsmsto AS eachsmsto WHERE ((smsto IS NULL) OR (smsto = ''));
        GET DIAGNOSTICS _rc = ROW_COUNT;
        v_phonenoexists := coalesce((SELECT count(*) FROM tmp_eachsmsto AS eachsmsto), 0);
        _rc := 1;
        rs1 := NULL;
        OPEN rs1 FOR SELECT DISTINCT localtimestamp(3) AS date, s.smsto, t.smstext, v_smstype AS smstypecode, 1 AS smsstatuscode, v_ai_smstemplatecode AS smstemplatecode FROM tmp_inputrows AS t, tmp_eachsmsto AS s WHERE ((t.rowid = v_sno) AND (t.smstext IS NOT NULL));
        INSERT INTO dbo.sms_center (date, smsto, smstext, smstypecode, smsstatuscode, smstemplatecode, expiry) SELECT DISTINCT localtimestamp(3) AS date, s.smsto, t.smstext, v_smstype AS smstypecode, 1 AS smsstatuscode, v_ai_smstemplatecode AS smstemplatecode, (localtimestamp(3) + (v_expiry) * interval '1 hour') AS expiry FROM tmp_inputrows AS t, tmp_eachsmsto AS s WHERE ((t.rowid = v_sno) AND (t.smstext IS NOT NULL));
        GET DIAGNOSTICS _rc = ROW_COUNT;
        v_ai_totsms := (v_ai_totsms + coalesce(_rc, 0));
        _rc := 1;
        v_sno := (v_sno + 1);
        _rc := 1;
      END LOOP;
    END IF;
  END IF;
  return_value := 0;
  ai_totsms := v_ai_totsms;
  RETURN;
  return_value := 0;
  ai_totsms := v_ai_totsms;
  RETURN;
END
$body$;

-- ==== proc SP_CreatePurchase_From_AdvPurchase ====
CREATE OR REPLACE FUNCTION dbo.sp_createpurchase_from_advpurchase(ai_advpurinvcode integer, INOUT ai_purinvcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_advpurinvcode integer;
  v_ai_purinvcode integer;
  v_errcode integer;
  v_newnetamt double precision;
  v_netdiff double precision;
BEGIN
  v_ai_advpurinvcode := ai_advpurinvcode;
  v_ai_purinvcode := ai_purinvcode;
  UPDATE dbo.advpurdetail SET discountedsaleprice = (SELECT item.discountedsaleprice FROM dbo.item WHERE (item.icode = advpurdetail.icode)), recentpurprice = (SELECT item.recentpurprice FROM dbo.item WHERE (item.icode = advpurdetail.icode)) WHERE (advpurinvcode = v_ai_advpurinvcode);
  SELECT r.return_value, r.key INTO v_errcode, v_ai_purinvcode FROM dbo.sp_gettabmaxkey(tabname => 'purledger', key => v_ai_purinvcode) AS r;
  v_errcode := 0;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem in generating new purchase invoice code';
    return_value := -1;
    ai_purinvcode := v_ai_purinvcode;
    RETURN;
  END IF;
  v_errcode := 0;
  INSERT INTO dbo.purledger (purinvcode, purcatcode, suppcode, suppinvcode, salesmancode, date, pocode, discperc, flatdisc, misccharges, salestax, posted, postdate, remarks, originaldate, modifiedby, postedby, suppinvdate, grn, porb, invgstperc1, purtypecode, headerno, headerinvno, invtotal, accountfor, paymentmode, paymentacccode, amt, amtby, amtdate, amtreference, outstandingamt, marked, transferable, transfered, transferedon, transferedby, imported, importedby, printbalance, purinvpagesize, currencycode, conversionfactor) SELECT v_ai_purinvcode, purcatcode, suppcode, suppinvcode, usercode, date, pocode, 0 AS discperc, 0 AS flatdisc, 0 AS misccharges, 0 AS salestax, 'N' AS posted, postdate, remarks, originaldate, modifiedby, postedby, suppinvdate, grn, porb, 0 AS invgstperc1, purtypecode, headerno, NULL::integer, invtotal, accountfor, paymentmode, paymentacccode, amt, amtby, amtdate, amtreference, outstandingamt, 'N' AS marked, 'N' AS transferable, 'N' AS transfered, NULL::timestamp(3) AS transferedon, NULL::smallint AS transferedby, 'N' AS imported, NULL::smallint AS importedby, printbalance, purinvpagesize, currencycode, conversionfactor FROM dbo.advpurheader WHERE (advpurinvcode = v_ai_advpurinvcode);
  v_errcode := 0;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem in Creation Of Purchase Invoice Header From Advanced Purchase';
    return_value := -1;
    ai_purinvcode := v_ai_purinvcode;
    RETURN;
  END IF;
  v_errcode := 0;
  INSERT INTO dbo.purdetail (purinvcode, icode, gcode, batch, expiry, packqty, looseqty, packunits, purprice, discperc, avgprice, bonusqty, newavgprice, currstock, gstperc, unitsalestax, purutn, saleprice, itemdescription, rate, salepriceforitem, foreignprice, purpriceinadvpur, netrate, recentpurprice, alternatecustomicode, retailprice) SELECT v_ai_purinvcode, d.icode, d.gcode, d.batch, d.expiry, CASE WHEN (h.purcatcode IN (1, 2)) THEN ((d.packqty + d.bonusqty)) ELSE 0 END AS packqty, CASE WHEN (h.purcatcode IN (1, 2)) THEN 0 ELSE ((d.looseqty + d.bonusqty)) END AS looseqty, d.packunits, round((d.netrate)::numeric, 2) AS purprice, 0 AS discperc, d.avgprice, 0 AS bonusqty, d.newavgprice, d.currstock, 0 AS gstperc, 0 AS unitsalestax, d.purutn, d.saleprice, d.itemdescription, d.rate, d.salepriceforitem, d.foreignprice, CASE (SELECT dbo.fn_getpreference('UpdatePurPrice') AS a) WHEN 'D' THEN CASE WHEN (round(((((((((((d.purprice + d.purprice2) + d.purprice3) + d.purprice4) - itemflatdisc)) * ((1 - (d.discperc * 0.01))))) - d.itemflatdiscafterdiscperc)))::numeric, 2) >= 0) THEN round(((((((((((d.purprice + d.purprice2) + d.purprice3) + d.purprice4) - itemflatdisc)) * ((1 - (d.discperc * 0.01))))) - d.itemflatdiscafterdiscperc)))::numeric, 2) ELSE round(((((d.purprice + d.purprice2) + d.purprice3) + d.purprice4))::numeric, 2) END WHEN 'R' THEN d.netrate ELSE round(((((d.purprice + d.purprice2) + d.purprice3) + d.purprice4))::numeric, 2) END AS purprice, d.netrate, coalesce((SELECT i.recentpurprice FROM dbo.item AS i WHERE (i.icode = d.icode)), 0) AS recentpurprice, d.alternatecustomicode, d.retailprice FROM dbo.advpurdetail AS d, dbo.advpurheader AS h WHERE ((h.advpurinvcode = v_ai_advpurinvcode) AND (h.advpurinvcode = d.advpurinvcode)) ORDER BY purrowid;
  v_errcode := 0;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem in Creation Of Purchase Invoice Detail From Advanced Purchase';
    return_value := -1;
    ai_purinvcode := v_ai_purinvcode;
    RETURN;
  END IF;
  v_errcode := 0;
  v_newnetamt := (SELECT coalesce(((max(h.invtotal) - sum((round((d.purprice)::numeric, 2) * (((d.packqty + d.looseqty) + d.bonusqty)))))), 0) FROM dbo.purdetail AS d, dbo.purledger AS h WHERE ((h.purinvcode = v_ai_purinvcode) AND (h.purinvcode = d.purinvcode)));
  IF (v_newnetamt <> 0) THEN
    IF (v_newnetamt > 0) THEN
      UPDATE dbo.purledger SET misccharges = abs(v_newnetamt) WHERE (purinvcode = v_ai_purinvcode);
    ELSE
      UPDATE dbo.purledger SET flatdisc = abs(v_newnetamt) WHERE (purinvcode = v_ai_purinvcode);
    END IF;
  END IF;
  v_errcode := 0;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem in Updation Of Purchase Invoice Amount From Advanced Purchase';
    return_value := -1;
    ai_purinvcode := v_ai_purinvcode;
    RETURN;
  END IF;
  return_value := 0;
  ai_purinvcode := v_ai_purinvcode;
  RETURN;
  return_value := 0;
  ai_purinvcode := v_ai_purinvcode;
  RETURN;
END
$body$;

-- ==== proc SP_CreatePurchase_From_ImpPur ====
CREATE OR REPLACE FUNCTION dbo.sp_createpurchase_from_imppur(ai_imppurinvcode integer, ai_salesmancode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_imppurinvcode integer;
  v_ai_salesmancode integer;
  v_errcode integer;
  v_ai_purinvcode integer;
  v_suppcode integer;
  v_newnetamt double precision;
  v_netdiff double precision;
  cur_c1 refcursor;
  _fs integer := -1;
BEGIN
  v_ai_imppurinvcode := ai_imppurinvcode;
  v_ai_salesmancode := ai_salesmancode;
  OPEN cur_c1 FOR SELECT DISTINCT suppcode FROM dbo.imppurdetail WHERE (imppurinvcode = v_ai_imppurinvcode) ORDER BY suppcode;
  FETCH NEXT FROM cur_c1 INTO v_suppcode;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    v_ai_purinvcode := NULL;
    SELECT r.return_value, r.key INTO v_errcode, v_ai_purinvcode FROM dbo.sp_gettabmaxkey(tabname => 'purledger', key => v_ai_purinvcode) AS r;
    v_errcode := 0;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Problem in generating new purchase invoice code';
      CLOSE cur_c1;
      -- DEALLOCATE C1
      return_value := -1;
      RETURN;
    END IF;
    v_errcode := 0;
    INSERT INTO dbo.purledger (purinvcode, purcatcode, suppcode, suppinvcode, salesmancode, date, pocode, discperc, flatdisc, misccharges, salestax, posted, postdate, remarks, originaldate, modifiedby, postedby, suppinvdate, grn, porb, invgstperc1, purtypecode, headerno, headerinvno, invtotal, accountfor, paymentmode, paymentacccode, amt, amtby, amtdate, amtreference, outstandingamt, marked, transferable, transfered, transferedon, transferedby, imported, importedby, printbalance, purinvpagesize, currencycode, conversionfactor, imppurinvcode, impactinventory) SELECT v_ai_purinvcode, 2 AS purcatcode, v_suppcode, '' AS suppinvcode, usercode, date, NULL::integer AS pocode, 0 AS discperc, 0 AS flatdisc, 0 AS misccharges, 0 AS salestax, 'N' AS posted, localtimestamp(3) AS posteddate, remarks, date AS originaldate, NULL::smallint AS modifiedby, v_ai_salesmancode AS postedby, NULL::timestamp(3) AS suppinvdate, NULL::citext AS grn, NULL::citext AS porb, 0 AS invgstperc1, NULL::smallint AS purtypecode, headerno, NULL::integer, invtotal, 'N' AS accountfor, 'C' AS paymentmode, NULL::smallint AS paymentacccode, 0.00 AS amt, NULL::smallint AS amtby, NULL::timestamp(3) AS amtdate, NULL::citext AS amtreference, invtotal AS outstandingamt, 'N' AS marked, 'N' AS transferable, 'N' AS transfered, NULL::timestamp(3) AS transferedon, NULL::smallint AS transferedby, 'N' AS imported, NULL::smallint AS importedby, 'N' AS printbalance, 'F' AS purinvpagesize, currencycode, conversionfactor, imppurinvcode, 'Y' AS impactinventory FROM dbo.imppurheader WHERE (imppurinvcode = v_ai_imppurinvcode);
    v_errcode := 0;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Problem in Creation Of Purchase Invoice Header From Imported Purchase';
      CLOSE cur_c1;
      -- DEALLOCATE C1
      return_value := -1;
      RETURN;
    END IF;
    v_errcode := 0;
    INSERT INTO dbo.purdetail (purinvcode, icode, gcode, batch, expiry, packqty, looseqty, packunits, purprice, discperc, avgprice, bonusqty, newavgprice, currstock, gstperc, unitsalestax, purutn, saleprice, itemdescription, rate, salepriceforitem, foreignprice, purpriceinadvpur, netrate, recentpurprice) SELECT v_ai_purinvcode, d.icode, d.gcode, d.batch, d.expiry, ((d.packqty + d.bonusqty)) AS packqty, 0 AS looseqty, d.packunits, round((d.netrate)::numeric, 2) AS purprice, 0 AS discperc, d.avgprice, 0 AS bonusqty, d.newavgprice, d.currstock, 0 AS gstperc, 0 AS unitsalestax, d.purutn, d.saleprice, d.itemdescription, d.rate, d.salepriceforitem, d.foreignprice, CASE (SELECT dbo.fn_getpreference('UpdatePurPrice') AS a) WHEN 'D' THEN CASE WHEN (round(((((((((((d.purprice + d.purprice2) + d.purprice3) + d.purprice4) - itemflatdisc)) * ((1 - (d.discperc * 0.01))))) - d.itemflatdiscafterdiscperc)))::numeric, 2) >= 0) THEN round(((((((((((d.purprice + d.purprice2) + d.purprice3) + d.purprice4) - itemflatdisc)) * ((1 - (d.discperc * 0.01))))) - d.itemflatdiscafterdiscperc)))::numeric, 2) ELSE round(((((d.purprice + d.purprice2) + d.purprice3) + d.purprice4))::numeric, 2) END WHEN 'R' THEN d.netrate ELSE round(((((d.purprice + d.purprice2) + d.purprice3) + d.purprice4))::numeric, 2) END AS purprice, d.netrate, coalesce((SELECT i.recentpurprice FROM dbo.item AS i WHERE (i.icode = d.icode)), 0) AS recentpurprice FROM dbo.imppurdetail AS d, dbo.imppurheader AS h WHERE (((h.imppurinvcode = v_ai_imppurinvcode) AND (d.suppcode = v_suppcode)) AND (h.imppurinvcode = d.imppurinvcode)) ORDER BY purrowid;
    v_errcode := 0;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Problem in Creation Of Purchase Invoice Detail From Imported Purchase';
      CLOSE cur_c1;
      -- DEALLOCATE C1
      return_value := -1;
      RETURN;
    END IF;
    v_errcode := 0;
    v_newnetamt := (SELECT coalesce(round((sum((d.purprice * (((d.packqty + d.looseqty) + d.bonusqty)))))::numeric, 0), 0) FROM dbo.purdetail AS d, dbo.purledger AS h WHERE ((h.purinvcode = v_ai_purinvcode) AND (h.purinvcode = d.purinvcode)));
    IF (v_newnetamt <> 0) THEN
      UPDATE dbo.purledger SET invtotal = v_newnetamt, outstandingamt = v_newnetamt WHERE (purinvcode = v_ai_purinvcode);
    END IF;
    v_errcode := 0;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Problem in Updation Of Purchase Invoice Amount From Imported Purchase';
      CLOSE cur_c1;
      -- DEALLOCATE C1
      return_value := -1;
      RETURN;
    END IF;
    FETCH NEXT FROM cur_c1 INTO v_suppcode;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_c1;
  -- DEALLOCATE C1
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_CreatePurchase_From_PurRegister ====
CREATE OR REPLACE FUNCTION dbo.sp_createpurchase_from_purregister(ai_purregistercode integer, INOUT ai_purinvcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_purregistercode integer;
  v_ai_purinvcode integer;
  v_errcode integer;
  v_newnetamt double precision;
  v_netdiff double precision;
BEGIN
  v_ai_purregistercode := ai_purregistercode;
  v_ai_purinvcode := ai_purinvcode;
  SELECT r.return_value, r.key INTO v_errcode, v_ai_purinvcode FROM dbo.sp_gettabmaxkey(tabname => 'purledger', key => v_ai_purinvcode) AS r;
  v_errcode := 0;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem in generating new purchase invoice code';
    return_value := -1;
    ai_purinvcode := v_ai_purinvcode;
    RETURN;
  END IF;
  v_errcode := 0;
  INSERT INTO dbo.purledger (purinvcode, purcatcode, suppcode, suppinvcode, salesmancode, date, pocode, discperc, flatdisc, misccharges, salestax, posted, postdate, remarks, originaldate, modifiedby, postedby, suppinvdate, grn, porb, invgstperc1, purtypecode, headerno, headerinvno, invtotal, accountfor, paymentmode, paymentacccode, amt, amtby, amtdate, amtreference, outstandingamt, marked, transferable, transfered, transferedon, transferedby, imported, importedby, printbalance, purinvpagesize, currencycode, conversionfactor) SELECT v_ai_purinvcode, 1 AS purcatcode, suppcode, referenceno AS suppinvcode, usercode, date, NULL::integer AS pocode, 0 AS discperc, 0 AS flatdisc, 0 AS misccharges, 0 AS salestax, 'N' AS posted, postdate, remarks, date AS originaldate, NULL::smallint AS modifiedby, postedby, date AS suppinvdate, lotno AS grn, 'N' AS porb, 0 AS invgstperc1, NULL::smallint AS purtypecode, 1 AS headerno, NULL::integer, totalamount AS invtotal, 'Y' AS accountfor, 'C' AS paymentmode, NULL::smallint AS paymentacccode, 0 AS amt, NULL::smallint AS amtby, NULL::timestamp(3) AS amtdate, NULL::citext AS amtreference, totalamount AS outstandingamt, 'N' AS marked, 'N' AS transferable, 'N' AS transfered, NULL::timestamp(3) AS transferedon, NULL::smallint AS transferedby, 'N' AS imported, NULL::smallint AS importedby, 'N' AS printbalance, 'F' AS purinvpagesize, 1 AS currencycode, 1 AS conversionfactor FROM dbo.purregister WHERE (purregistercode = v_ai_purregistercode);
  v_errcode := 0;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem in Creation Of Purchase Invoice Header From Purchase Register Code = %', v_ai_purregistercode;
    return_value := -1;
    ai_purinvcode := v_ai_purinvcode;
    RETURN;
  END IF;
  v_errcode := 0;
  INSERT INTO dbo.purdetail (purinvcode, icode, gcode, batch, expiry, packqty, looseqty, packunits, purprice, discperc, avgprice, bonusqty, newavgprice, currstock, gstperc, unitsalestax, purutn, saleprice, itemdescription, rate, salepriceforitem, foreignprice, purpriceinadvpur, netrate, recentpurprice, totalpieces, piecesinhand) SELECT v_ai_purinvcode, d.icode, 1 AS gcode, (SELECT dbo.fn_getpreference('DefaultBatch') AS a) AS batch, (SELECT dbo.fn_get_datetime_preference('DefaultExpiry') AS a) AS expiry, d.qty AS packqty, 0 AS looseqty, d.packunits, round((d.purprice)::numeric, 2) AS purprice, 0 AS discperc, i.avgprice AS avgprice, 0 AS bonusqty, i.avgprice AS newavgprice, coalesce((SELECT sum(gd.currqty) FROM dbo.godowndetail AS gd WHERE (gd.icode = d.icode)), 0) AS currstock, 0 AS gstperc, 0 AS unitsalestax, 1 AS purutn, i.saleprice, NULL::citext AS itemdescription, i.purprice AS rate, i.saleprice, 0 AS foreignprice, d.purprice AS purprice, d.purprice AS netrate, coalesce((SELECT i.recentpurprice FROM dbo.item AS i WHERE (i.icode = d.icode)), 0) AS recentpurprice, d.totalpieces, i.totalpieces AS piecesinhand FROM dbo.purregisterdetail AS d, dbo.purregister AS h, dbo.item AS i WHERE (((h.purregistercode = v_ai_purregistercode) AND (h.purregistercode = d.purregistercode)) AND (d.icode = i.icode)) ORDER BY rowid;
  v_errcode := 0;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem in Creation Of Purchase Invoice Detail From Purchase Register Code = %', v_ai_purregistercode;
    return_value := -1;
    ai_purinvcode := v_ai_purinvcode;
    RETURN;
  END IF;
  v_errcode := 0;
  v_newnetamt := (SELECT coalesce(((max(h.invtotal) - sum((round((d.purprice)::numeric, 2) * (((d.packqty + d.looseqty) + d.bonusqty)))))), 0) FROM dbo.purdetail AS d, dbo.purledger AS h WHERE ((h.purinvcode = v_ai_purinvcode) AND (h.purinvcode = d.purinvcode)));
  IF (v_newnetamt <> 0) THEN
    IF (v_newnetamt > 0) THEN
      UPDATE dbo.purledger SET misccharges = abs(v_newnetamt) WHERE (purinvcode = v_ai_purinvcode);
    ELSE
      UPDATE dbo.purledger SET flatdisc = abs(v_newnetamt) WHERE (purinvcode = v_ai_purinvcode);
    END IF;
  END IF;
  v_errcode := 0;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem in Updation Of Purchase Invoice Amount From Advanced Purchase';
    return_value := -1;
    ai_purinvcode := v_ai_purinvcode;
    RETURN;
  END IF;
  return_value := 0;
  ai_purinvcode := v_ai_purinvcode;
  RETURN;
  return_value := 0;
  ai_purinvcode := v_ai_purinvcode;
  RETURN;
END
$body$;

-- ==== proc SP_CreateScheduledSMS ====
CREATE OR REPLACE FUNCTION dbo.sp_createscheduledsms(OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_runparm citext;
  v_qry citext;
  v_err integer;
  v_rowcount integer;
  v_rowid integer;
  v_smstemplatecode integer;
  v_smsgenerated integer;
  v_totalsmsgen integer;
BEGIN
  -- SET NOCOUNT ON
  DROP TABLE IF EXISTS tmp_templatetosend;
  CREATE TEMP TABLE tmp_templatetosend (
    rowid integer GENERATED BY DEFAULT AS IDENTITY,
    templatecode integer,
    runparam citext
) ON COMMIT DROP;
  INSERT INTO tmp_templatetosend (templatecode, runparam) SELECT smstemplatecode, runparameters FROM dbo.sms_template WHERE (((((enabled = 'Y') AND (active = 'Y')) AND (scheduled = 'Y')) AND (executed = 'N')) AND (localtimestamp(3) >= coalesce(nextrunon, '1900-01-01 00:00:00')));
  v_rowcount := coalesce((SELECT count(*) FROM tmp_templatetosend AS templatetosend), 0);
  IF (v_rowcount > 0) THEN
    v_totalsmsgen := 0;
    v_rowid := 1;
    WHILE (v_rowid <= v_rowcount) LOOP
      v_smsgenerated := 0;
      v_runparm := coalesce((SELECT runparam FROM tmp_templatetosend AS templatetosend WHERE (rowid = v_rowid)), '1');
      IF ((ltrim(rtrim(v_runparm)))::citext = '') THEN
        v_runparm := '1';
      END IF;
      v_smstemplatecode := (SELECT templatecode FROM tmp_templatetosend AS templatetosend WHERE (rowid = v_rowid));
      SELECT r.return_value, r.ai_totsms, r.rs1 INTO v_err, v_smsgenerated, rs1 FROM dbo.sp_createdatasms(as_list => v_runparm, ai_smstemplatecode => v_smstemplatecode, ai_totsms => v_smsgenerated) AS r;
      IF ((v_err <> 0) OR (0 <> 0)) THEN
        RAISE EXCEPTION 'Scheduled SMS Generation Problem, SMS Template Code : %', v_smstemplatecode;
        return_value := -1;
        RETURN;
      ELSE
        v_totalsmsgen := (v_totalsmsgen + v_smsgenerated);
        UPDATE dbo.sms_template SET executedon = localtimestamp(3), nextrunon = CASE scheduletype WHEN 1 THEN (((left(to_char(localtimestamp(3), 'MM/DD/YYYY'), 100) || ' ') || left(to_char(runonce, 'HH24:MI:SS:MS'), 100)))::timestamp ELSE (localtimestamp(3) + (CASE runeveryfreq WHEN 1 THEN ((((runevery * 60) * 60) * 1000)) ELSE (((runevery * 60) * 1000)) END) * interval '1 millisecond') END WHERE (smstemplatecode = v_smstemplatecode);
      END IF;
      v_rowid := (v_rowid + 1);
    END LOOP;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_CreateServiceSRAllocation ====
CREATE OR REPLACE FUNCTION dbo.sp_createservicesrallocation(ai_servicerinvcode integer, ai_serviceinvcode integer, ad_date timestamp, ai_usercode integer, ac_posted citext, ad_postdate timestamp, an_outstandingamt numeric, an_amt numeric, INOUT ai_srallocationcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_servicerinvcode integer;
  v_ai_serviceinvcode integer;
  v_ad_date timestamp(3);
  v_ai_usercode integer;
  v_ac_posted citext;
  v_ad_postdate timestamp(3);
  v_an_outstandingamt numeric(15,2);
  v_an_amt numeric(15,2);
  v_ai_srallocationcode integer;
  v_err integer;
  v_rowcount integer;
  v_tabmaxkey integer;
  v_maxutn bigint;
  _rc integer;
BEGIN
  v_ai_servicerinvcode := ai_servicerinvcode;
  v_ai_serviceinvcode := ai_serviceinvcode;
  v_ad_date := ad_date;
  v_ai_usercode := ai_usercode;
  v_ac_posted := ac_posted;
  v_ad_postdate := ad_postdate;
  v_an_outstandingamt := an_outstandingamt;
  v_an_amt := an_amt;
  v_ai_srallocationcode := ai_srallocationcode;
  SELECT r.return_value, r.key INTO v_err, v_tabmaxkey FROM dbo.sp_gettabmaxkey(tabname => 'ServiceSRAllocationHeader', key => v_tabmaxkey) AS r;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Service Return Allocation Code generation problem';
    return_value := -1;
    ai_srallocationcode := v_ai_srallocationcode;
    RETURN;
  END IF;
  INSERT INTO dbo.servicesrallocationheader (servicesrallocationcode, date, servicerinvcode, usercode, originaldate, modified, modifiedby, postedby, posted, postdate, remarks) VALUES (v_tabmaxkey, v_ad_date, v_ai_servicerinvcode, v_ai_usercode, v_ad_date, 'N', NULL::smallint, v_ai_usercode, v_ac_posted, v_ad_date, 'Auto Created Service Return Allocaiton');
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_err := 0;
  v_rowcount := _rc;
  _rc := 1;
  IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
    RAISE EXCEPTION 'Problem in Creating Service Return Allocation (Header)';
    return_value := -1;
    ai_srallocationcode := v_ai_srallocationcode;
    RETURN;
  END IF;
  SELECT r.return_value, r.lbi_maxutn INTO v_err, v_maxutn FROM dbo.sp_maxutn(lbi_rows => (2)::bigint, lbi_maxutn => v_maxutn) AS r;
  IF ((v_err <> 0) AND (0 <> 0)) THEN
    RAISE EXCEPTION 'Problem Fetching UTN in Service Return Allocation Process';
    return_value := -1;
    ai_srallocationcode := v_ai_srallocationcode;
    RETURN;
  END IF;
  INSERT INTO dbo.servicesrallocationdetail (servicesrallocationcode, serviceinvcode, outstandingamt, amt, utn) VALUES (v_tabmaxkey, v_ai_serviceinvcode, v_an_outstandingamt, v_an_amt, v_maxutn);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_err := 0;
  v_rowcount := _rc;
  _rc := 1;
  IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
    RAISE EXCEPTION 'Problem in Creating Service Return Allocation (Detail)';
    return_value := -1;
    ai_srallocationcode := v_ai_srallocationcode;
    RETURN;
  END IF;
  v_ai_srallocationcode := v_tabmaxkey;
  _rc := 1;
  return_value := 0;
  ai_srallocationcode := v_ai_srallocationcode;
  RETURN;
  return_value := 0;
  ai_srallocationcode := v_ai_srallocationcode;
  RETURN;
END
