-- ==== proc SP_CreateSMS ====
CREATE OR REPLACE FUNCTION dbo.sp_createsms(as_contactlist citext, ai_smstypecode smallint, as_smstext citext, ai_smstemplatecode integer, INOUT ai_totsms integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_as_contactlist citext;
  v_ai_smstypecode smallint;
  v_as_smstext citext;
  v_ai_smstemplatecode integer;
  v_ai_totsms integer;
  v_err integer;
  v_rowcount integer;
  v_expiry integer;
  _rc integer;
BEGIN
  v_as_contactlist := as_contactlist;
  v_ai_smstypecode := ai_smstypecode;
  v_as_smstext := as_smstext;
  v_ai_smstemplatecode := ai_smstemplatecode;
  v_ai_totsms := ai_totsms;
  DROP TABLE IF EXISTS tv_sp_createsms_lt_sms;
  CREATE TEMP TABLE tv_sp_createsms_lt_sms (
    smsto citext,
    smstext citext,
    smstypecode smallint
) ON COMMIT DROP;
  v_expiry := dbo.fn_get_int_preference('defaultsmsexpiry');
  _rc := 1;
  IF (v_expiry IS NULL) THEN
    v_expiry := 24;
    _rc := 1;
  END IF;
  INSERT INTO tv_sp_createsms_lt_sms SELECT code, v_as_smstext AS smstext, v_ai_smstypecode AS smstype FROM dbo.udf_stringtotabl_string(v_as_contactlist, ',') AS udf_stringtotabl_string;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF (0 <> 0) THEN
    RAISE EXCEPTION 'Problem Inserting SMS in temporary table';
    return_value := -1;
    ai_totsms := v_ai_totsms;
    RETURN;
  END IF;
  INSERT INTO dbo.sms_center (date, smsto, smstext, smstypecode, smsstatuscode, smstemplatecode, expiry) SELECT localtimestamp(3) AS date, t.smsto, t.smstext, t.smstypecode, 1 AS smsstatuscode, v_ai_smstemplatecode AS smstemplatecode, (localtimestamp(3) + (v_expiry) * interval '1 hour') AS expiry FROM tv_sp_createsms_lt_sms AS t;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_ai_totsms := _rc;
  _rc := 1;
  v_err := 0;
  _rc := 1;
  IF (((0 <> 0) OR (v_err <> 0)) OR (v_ai_totsms = 0)) THEN
    RAISE EXCEPTION 'Problem Inserting SMS in SMS Center';
    return_value := -1;
    ai_totsms := v_ai_totsms;
    RETURN;
  END IF;
  return_value := 0;
  ai_totsms := v_ai_totsms;
  RETURN;
  return_value := 0;
  ai_totsms := v_ai_totsms;
  RETURN;
END
$body$;

-- ==== proc SP_CreateSRAllocation ====
CREATE OR REPLACE FUNCTION dbo.sp_createsrallocation(ai_srinvcode integer, ai_saleinvcode integer, ad_date timestamp, ai_usercode integer, ac_posted citext, ad_postdate timestamp, an_outstandingamt numeric, an_amt numeric, INOUT ai_srallocationcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_srinvcode integer;
  v_ai_saleinvcode integer;
  v_ad_date timestamp(3);
  v_ai_usercode integer;
  v_ac_posted citext;
  v_ad_postdate timestamp(3);
  v_an_outstandingamt numeric(15,2);
  v_an_amt numeric(15,2);
  v_ai_srallocationcode integer;
  v_err integer;
  v_rowcount integer;
  v_tabmaxkey integer;
  v_maxutn bigint;
  _rc integer;
BEGIN
  v_ai_srinvcode := ai_srinvcode;
  v_ai_saleinvcode := ai_saleinvcode;
  v_ad_date := ad_date;
  v_ai_usercode := ai_usercode;
  v_ac_posted := ac_posted;
  v_ad_postdate := ad_postdate;
  v_an_outstandingamt := an_outstandingamt;
  v_an_amt := an_amt;
  v_ai_srallocationcode := ai_srallocationcode;
  SELECT r.return_value, r.key INTO v_err, v_tabmaxkey FROM dbo.sp_gettabmaxkey(tabname => 'SRAllocationHeader', key => v_tabmaxkey) AS r;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Sale Return Allocation Code generation problem';
    return_value := -1;
    ai_srallocationcode := v_ai_srallocationcode;
    RETURN;
  END IF;
  INSERT INTO dbo.srallocationheader (srallocationcode, date, srinvcode, usercode, modified, modifiedby, posted, postedby, postdate) VALUES (v_tabmaxkey, v_ad_date, v_ai_srinvcode, v_ai_usercode, 'N', NULL::smallint, v_ac_posted, v_ai_usercode, v_ad_date);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_err := 0;
  v_rowcount := _rc;
  _rc := 1;
  IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
    RAISE EXCEPTION 'Problem in Creating Sale Return Allocation (Header)';
    return_value := -1;
    ai_srallocationcode := v_ai_srallocationcode;
    RETURN;
  END IF;
  SELECT r.return_value, r.lbi_maxutn INTO v_err, v_maxutn FROM dbo.sp_maxutn(lbi_rows => (2)::bigint, lbi_maxutn => v_maxutn) AS r;
  IF ((v_err <> 0) AND (0 <> 0)) THEN
    RAISE EXCEPTION 'Problem Fetching UTN in Sale Return Allocation Process';
    return_value := -1;
    ai_srallocationcode := v_ai_srallocationcode;
    RETURN;
  END IF;
  INSERT INTO dbo.srallocationdetail (srallocationcode, saleinvcode, outstandingamt, amt, srallocationutn) VALUES (v_tabmaxkey, v_ai_saleinvcode, v_an_outstandingamt, v_an_amt, v_maxutn);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_err := 0;
  v_rowcount := _rc;
  _rc := 1;
  IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
    RAISE EXCEPTION 'Problem in Creating Sale Return Allocation (Detail)';
    return_value := -1;
    ai_srallocationcode := v_ai_srallocationcode;
    RETURN;
  END IF;
  v_ai_srallocationcode := v_tabmaxkey;
  _rc := 1;
  return_value := 0;
  ai_srallocationcode := v_ai_srallocationcode;
  RETURN;
  return_value := 0;
  ai_srallocationcode := v_ai_srallocationcode;
  RETURN;
END
$body$;

-- ==== proc SP_CreateVoucher ====
CREATE OR REPLACE FUNCTION dbo.sp_createvoucher(ai_vochcatcode integer, ai_acccode integer, ad_date timestamp, ai_salesmancode integer, as_posted citext, ad_postdate timestamp, as_remarks citext, ad_originaldate timestamp, ai_modifiedby integer, ai_postedby integer, as_chkno citext, ai_dr_acccode integer, ai_cr_acccode integer, an_amount numeric, as_chkno_detail citext, as_remarks_detail citext, ai_patientcode integer, ai_guestcode integer, ai_studentcode integer, ai_invoicecode integer, an_outstandingamt numeric, an_balance numeric, INOUT glvochcode integer, INOUT vochcode integer, smancode smallint DEFAULT NULL, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_vochcatcode integer;
  v_ai_acccode integer;
  v_ad_date timestamp(3);
  v_ai_salesmancode integer;
  v_as_posted citext;
  v_ad_postdate timestamp(3);
  v_as_remarks citext;
  v_ad_originaldate timestamp(3);
  v_ai_modifiedby integer;
  v_ai_postedby integer;
  v_as_chkno citext;
  v_ai_dr_acccode integer;
  v_ai_cr_acccode integer;
  v_an_amount numeric(15,2);
  v_as_chkno_detail citext;
  v_as_remarks_detail citext;
  v_ai_patientcode integer;
  v_ai_guestcode integer;
  v_ai_studentcode integer;
  v_ai_invoicecode integer;
  v_an_outstandingamt numeric(15,2);
  v_an_balance numeric(15,2);
  v_glvochcode integer;
  v_vochcode integer;
  v_smancode smallint;
  v_err integer;
  v_rowcount integer;
  v_tabmaxkey integer;
  v_ai_vouchercode integer;
BEGIN
  v_ai_vochcatcode := ai_vochcatcode;
  v_ai_acccode := ai_acccode;
  v_ad_date := ad_date;
  v_ai_salesmancode := ai_salesmancode;
  v_as_posted := as_posted;
  v_ad_postdate := ad_postdate;
  v_as_remarks := as_remarks;
  v_ad_originaldate := ad_originaldate;
  v_ai_modifiedby := ai_modifiedby;
  v_ai_postedby := ai_postedby;
  v_as_chkno := as_chkno;
  v_ai_dr_acccode := ai_dr_acccode;
  v_ai_cr_acccode := ai_cr_acccode;
  v_an_amount := an_amount;
  v_as_chkno_detail := as_chkno_detail;
  v_as_remarks_detail := as_remarks_detail;
  v_ai_patientcode := ai_patientcode;
  v_ai_guestcode := ai_guestcode;
  v_ai_studentcode := ai_studentcode;
  v_ai_invoicecode := ai_invoicecode;
  v_an_outstandingamt := an_outstandingamt;
  v_an_balance := an_balance;
  v_glvochcode := glvochcode;
  v_vochcode := vochcode;
  v_smancode := smancode;
  SELECT r.return_value, r.key INTO v_err, v_tabmaxkey FROM dbo.sp_gettabmaxkey(tabname => 'GLHeader', key => v_tabmaxkey) AS r;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'GL Voucher Code generation problem';
    return_value := -1;
    glvochcode := v_glvochcode;
    vochcode := v_vochcode;
    RETURN;
  END IF;
  SELECT r.return_value, r.ai_vouchercode INTO v_err, v_ai_vouchercode FROM dbo.sp_getvouchercode(ai_vochcatcode => v_ai_vochcatcode, ai_vouchercode => v_ai_vouchercode) AS r;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Voucher Code Generation Problem';
    return_value := -1;
    glvochcode := v_glvochcode;
    vochcode := v_vochcode;
    RETURN;
  END IF;
  SELECT r.return_value INTO v_err FROM dbo.sp_setglheader(ai_glvochcode => v_tabmaxkey, ai_vochcatcode => v_ai_vochcatcode, ai_acccode => v_ai_acccode, ad_date => v_ad_date, ai_salesmancode => v_ai_salesmancode, as_posted => v_as_posted, ad_postdate => v_ad_postdate, as_remarks => v_as_remarks, ad_originaldate => v_ad_originaldate, ai_modifiedby => v_ai_modifiedby, ai_postedby => v_ai_postedby, as_chkno => v_as_chkno, ai_vouchercode => v_ai_vouchercode) AS r;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Problem Inserting Voucher (Table:GLHeader)';
    return_value := -1;
    glvochcode := v_glvochcode;
    vochcode := v_vochcode;
    RETURN;
  END IF;
  SELECT r.return_value INTO v_err FROM dbo.sp_setgldetail(ai_glvochcode => v_tabmaxkey, ai_dr_acccode => v_ai_dr_acccode, ai_cr_acccode => v_ai_cr_acccode, an_amount => v_an_amount, as_chkno => v_as_chkno_detail, as_remarks => v_as_remarks_detail, ai_patientcode => v_ai_patientcode, ai_guestcode => v_ai_guestcode, ai_studentcode => v_ai_studentcode, ai_invoicecode => v_ai_invoicecode, an_outstandingamt => v_an_outstandingamt, an_balance => v_an_balance) AS r;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Problem Inserting Voucher (Table:GLDetail)';
    return_value := -1;
    glvochcode := v_glvochcode;
    vochcode := v_vochcode;
    RETURN;
  END IF;
  v_glvochcode := v_tabmaxkey;
  v_vochcode := v_ai_vouchercode;
  return_value := 0;
  glvochcode := v_glvochcode;
  vochcode := v_vochcode;
  RETURN;
  return_value := 0;
  glvochcode := v_glvochcode;
  vochcode := v_vochcode;
  RETURN;
END
$body$;

-- ==== proc SP_CreateVoucher_From_ImpPur ====
CREATE OR REPLACE FUNCTION dbo.sp_createvoucher_from_imppur(ai_imppurinvcode integer, ai_salesmancode integer, INOUT ai_glvochcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_imppurinvcode integer;
  v_ai_salesmancode integer;
  v_ai_glvochcode integer;
  v_ai_vochcatcode integer;
  v_ai_acccode integer;
  v_ai_modifiedby integer;
  v_ai_postedby integer;
  v_ai_dr_acccode integer;
  v_ai_cr_acccode integer;
  v_ai_patientcode integer;
  v_ai_invoicecode integer;
  v_glvochcode integer;
  v_vochcode integer;
  v_ad_date timestamp(3);
  v_ad_postdate timestamp(3);
  v_ad_originaldate timestamp(3);
  v_as_remarks citext;
  v_as_chkno citext;
  v_as_chkno_detail citext;
  v_an_amount numeric(15,2);
  v_as_remarks_detail citext;
  v_an_outstandingamt numeric(15,2);
  v_an_balance numeric(15,2);
  v_as_posted citext;
  v_err integer;
  v_rowcount integer;
  v_tabmaxkey integer;
  v_ai_vouchercode integer;
  _rc integer;
BEGIN
  v_ai_imppurinvcode := ai_imppurinvcode;
  v_ai_salesmancode := ai_salesmancode;
  v_ai_glvochcode := ai_glvochcode;
  SELECT r.return_value, r.key INTO v_err, v_tabmaxkey FROM dbo.sp_gettabmaxkey(tabname => 'GLHeader', key => v_tabmaxkey) AS r;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'GL Voucher Code generation problem';
    return_value := -1;
    ai_glvochcode := v_ai_glvochcode;
    RETURN;
  END IF;
  v_ai_vochcatcode := 5;
  _rc := 1;
  SELECT r.return_value, r.ai_vouchercode INTO v_err, v_ai_vouchercode FROM dbo.sp_getvouchercode(ai_vochcatcode => v_ai_vochcatcode, ai_vouchercode => v_ai_vouchercode) AS r;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Voucher Code Generation Problem';
    return_value := -1;
    ai_glvochcode := v_ai_glvochcode;
    RETURN;
  END IF;
  v_ai_acccode := 2;
  _rc := 1;
  v_ad_date := localtimestamp(3);
  _rc := 1;
  v_as_posted := 'Y';
  _rc := 1;
  v_ad_postdate := localtimestamp(3);
  _rc := 1;
  v_as_remarks := (SELECT remarks FROM dbo.imppurheader WHERE (imppurinvcode = v_ai_imppurinvcode));
  _rc := 1;
  v_ad_originaldate := localtimestamp(3);
  _rc := 1;
  v_ai_modifiedby := NULL;
  _rc := 1;
  v_ai_postedby := v_ai_salesmancode;
  _rc := 1;
  v_as_chkno := (SELECT container FROM dbo.imppurheader WHERE (imppurinvcode = v_ai_imppurinvcode));
  _rc := 1;
  SELECT r.return_value INTO v_err FROM dbo.sp_setglheader(ai_glvochcode => v_tabmaxkey, ai_vochcatcode => v_ai_vochcatcode, ai_acccode => v_ai_acccode, ad_date => v_ad_date, ai_salesmancode => v_ai_salesmancode, as_posted => v_as_posted, ad_postdate => v_ad_postdate, as_remarks => v_as_remarks, ad_originaldate => v_ad_originaldate, ai_modifiedby => v_ai_modifiedby, ai_postedby => v_ai_postedby, as_chkno => v_as_chkno, ai_vouchercode => v_ai_vouchercode) AS r;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Problem Inserting Voucher (Table:GLHeader)';
    return_value := -1;
    ai_glvochcode := v_ai_glvochcode;
    RETURN;
  END IF;
  INSERT INTO dbo.gldetail (glvochcode, acccode, debit, credit, chkno, remarks, glutn, patientcode, invoicecode, outstandingamt, balance, guestcode, studentcode) SELECT v_tabmaxkey, suppcode AS acccode, 0 AS debit, sum((packqty * netdiscountedrate)) AS credit, v_as_chkno, v_as_remarks, NULL::bigint AS glutn, NULL::integer AS patientcode, NULL::integer AS invoicecode, 0 AS outstandingamt, 0 AS balance, NULL::integer AS guestcode, NULL::integer AS studentcode FROM dbo.imppurdetail WHERE (imppurinvcode = v_ai_imppurinvcode) GROUP BY suppcode HAVING (sum((packqty * netdiscountedrate)) <> 0) UNION ALL SELECT v_tabmaxkey, acccode AS acccode, 0 AS debit, sum(localamt) AS credit, v_as_chkno, v_as_remarks, NULL::bigint AS glutn, NULL::integer AS patientcode, NULL::integer AS invoicecode, 0 AS outstandingamt, 0 AS balance, NULL::integer AS guestcode, NULL::integer AS studentcode FROM dbo.imppurexp WHERE ((imppurinvcode = v_ai_imppurinvcode) AND (localamt <> 0)) GROUP BY expensetype, acccode UNION ALL SELECT v_tabmaxkey, 1 AS acccode, invtotal AS debit, 0.00 AS credit, v_as_chkno, v_as_remarks, NULL::bigint AS glutn, NULL::integer AS patientcode, NULL::integer AS invoicecode, 0 AS outstandingamt, 0 AS balance, NULL::integer AS guestcode, NULL::integer AS studentcode FROM dbo.imppurheader WHERE ((imppurinvcode = v_ai_imppurinvcode) AND (invtotal <> 0)) ORDER BY 3 DESC, 4, 2;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF (((0 <> 0) OR (v_err <> 0)) OR (_rc = 0)) THEN
    RAISE EXCEPTION 'Problem Inserting Voucher (Table:GLDetail)';
    return_value := -1;
    ai_glvochcode := v_ai_glvochcode;
    RETURN;
  END IF;
  v_glvochcode := v_tabmaxkey;
  _rc := 1;
  v_vochcode := v_ai_vouchercode;
  _rc := 1;
  v_ai_glvochcode := v_tabmaxkey;
  _rc := 1;
  UPDATE dbo.imppurheader SET glvochcode = v_glvochcode WHERE (imppurinvcode = v_ai_imppurinvcode);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF (((0 <> 0) OR (v_err <> 0)) OR (_rc = 0)) THEN
    RAISE EXCEPTION 'Problem Updating GL Voucher Code in (Table: ImpPurDetail)';
    return_value := -1;
    ai_glvochcode := v_ai_glvochcode;
    RETURN;
  END IF;
  return_value := 0;
  ai_glvochcode := v_ai_glvochcode;
  RETURN;
  return_value := 0;
  ai_glvochcode := v_ai_glvochcode;
  RETURN;
END
$body$;

-- ==== proc SP_CreateVoucher_From_PurPayment ====
CREATE OR REPLACE FUNCTION dbo.sp_createvoucher_from_purpayment(ai_purpaymentcode integer, ai_usercode integer, INOUT ai_glvochcode integer, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_purpaymentcode integer;
  v_ai_usercode integer;
  v_ai_glvochcode integer;
  v_ai_vochcatcode integer;
  v_ai_acccode integer;
  v_ai_modifiedby integer;
  v_ai_postedby integer;
  v_ai_dr_acccode integer;
  v_ai_cr_acccode integer;
  v_ai_patientcode integer;
  v_ai_invoicecode integer;
  v_glvochcode integer;
  v_vochcode integer;
  v_ad_date timestamp(3);
  v_ad_postdate timestamp(3);
  v_ad_originaldate timestamp(3);
  v_as_remarks citext;
  v_as_chkno citext;
  v_as_chkno_detail citext;
  v_an_amount numeric(15,2);
  v_as_remarks_detail citext;
  v_an_outstandingamt numeric(15,2);
  v_an_balance numeric(15,2);
  v_as_posted citext;
  v_err integer;
  v_rowcount integer;
  v_tabmaxkey integer;
  v_ai_vouchercode integer;
  _rc integer;
BEGIN
  v_ai_purpaymentcode := ai_purpaymentcode;
  v_ai_usercode := ai_usercode;
  v_ai_glvochcode := ai_glvochcode;
  SELECT r.return_value, r.key INTO v_err, v_tabmaxkey FROM dbo.sp_gettabmaxkey(tabname => 'GLHeader', key => v_tabmaxkey) AS r;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'GL Voucher Code generation problem';
    return_value := -1;
    ai_glvochcode := v_ai_glvochcode;
    RETURN;
  END IF;
  v_ai_vochcatcode := 17;
  _rc := 1;
  SELECT r.return_value, r.ai_vouchercode INTO v_err, v_ai_vouchercode FROM dbo.sp_getvouchercode(ai_vochcatcode => v_ai_vochcatcode, ai_vouchercode => v_ai_vouchercode) AS r;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Voucher Code Generation Problem';
    return_value := -1;
    ai_glvochcode := v_ai_glvochcode;
    RETURN;
  END IF;
  OPEN rs1 FOR SELECT * FROM dbo.purpayment;
  v_ai_acccode := 2;
  _rc := 1;
  v_ad_date := (SELECT max(date) FROM dbo.purpayment WHERE (purpaymentcode = v_ai_purpaymentcode));
  _rc := 1;
  v_as_posted := 'Y';
  _rc := 1;
  v_ad_postdate := localtimestamp(3);
  _rc := 1;
  v_as_remarks := (SELECT paymentremarks FROM dbo.purpayment WHERE (purpaymentcode = v_ai_purpaymentcode));
  _rc := 1;
  v_ad_originaldate := (SELECT max(date) FROM dbo.purpayment WHERE (purpaymentcode = v_ai_purpaymentcode));
  _rc := 1;
  v_ai_modifiedby := NULL;
  _rc := 1;
  v_ai_postedby := v_ai_usercode;
  _rc := 1;
  v_as_chkno := (SELECT paymentcheckno FROM dbo.purpayment WHERE (purpaymentcode = v_ai_purpaymentcode));
  _rc := 1;
  SELECT r.return_value INTO v_err FROM dbo.sp_setglheader(ai_glvochcode => v_tabmaxkey, ai_vochcatcode => v_ai_vochcatcode, ai_acccode => v_ai_acccode, ad_date => v_ad_date, ai_salesmancode => v_ai_usercode, as_posted => v_as_posted, ad_postdate => v_ad_postdate, as_remarks => v_as_remarks, ad_originaldate => v_ad_originaldate, ai_modifiedby => v_ai_modifiedby, ai_postedby => v_ai_postedby, as_chkno => v_as_chkno, ai_vouchercode => v_ai_vouchercode) AS r;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Problem Inserting Voucher (Table:GLHeader)';
    return_value := -1;
    ai_glvochcode := v_ai_glvochcode;
    RETURN;
  END IF;
  INSERT INTO dbo.gldetail (glvochcode, acccode, debit, credit, chkno, remarks, glutn, patientcode, invoicecode, outstandingamt, balance, guestcode, studentcode) SELECT v_tabmaxkey, acccode, (coalesce(paymentamt, 0) + coalesce(whtaxamt, 0)) AS debit, 0.00 AS credit, v_as_chkno, v_as_remarks, NULL::bigint AS glutn, NULL::integer AS patientcode, purinvcode AS invoicecode, outstandingamt AS outstandingamt, 0 AS balance, NULL::integer AS guestcode, NULL::integer AS studentcode FROM dbo.purpayment WHERE (purpaymentcode = v_ai_purpaymentcode) UNION ALL SELECT v_tabmaxkey, paymentacccode, 0.00 AS debit, coalesce(paymentamt, 0) AS credit, paymentcheckno, paymentremarks, NULL::bigint AS glutn, NULL::integer AS patientcode, NULL::integer AS invoicecode, outstandingamt AS outstandingamt, 0 AS balance, NULL::integer AS guestcode, NULL::integer AS studentcode FROM dbo.purpayment WHERE ((purpaymentcode = v_ai_purpaymentcode) AND (coalesce(paymentamt, 0) <> 0)) UNION ALL SELECT v_tabmaxkey, whtaxacccode, 0.00 AS debit, coalesce(whtaxamt, 0) AS credit, whtaxcheckno, whtaxremarks, NULL::bigint AS glutn, NULL::integer AS patientcode, NULL::integer AS invoicecode, outstandingamt AS outstandingamt, 0 AS balance, NULL::integer AS guestcode, NULL::integer AS studentcode FROM dbo.purpayment WHERE ((purpaymentcode = v_ai_purpaymentcode) AND (coalesce(whtaxamt, 0) <> 0));
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF (((0 <> 0) OR (v_err <> 0)) OR (_rc = 0)) THEN
    RAISE EXCEPTION 'Problem Inserting Voucher (Table:GLDetail)';
    return_value := -1;
    ai_glvochcode := v_ai_glvochcode;
    RETURN;
  END IF;
  v_glvochcode := v_tabmaxkey;
  _rc := 1;
  v_vochcode := v_ai_vouchercode;
  _rc := 1;
  v_ai_glvochcode := v_tabmaxkey;
  _rc := 1;
  UPDATE dbo.purpayment SET glvochcode = v_glvochcode, posted = 'Y', postedby = v_ai_usercode, postdate = localtimestamp(3) WHERE (purpaymentcode = v_ai_purpaymentcode);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF (((0 <> 0) OR (v_err <> 0)) OR (_rc = 0)) THEN
    RAISE EXCEPTION 'Problem Updating GL Voucher Code in (Table: PurPayment)';
    return_value := -1;
    ai_glvochcode := v_ai_glvochcode;
    RETURN;
  END IF;
  return_value := 0;
  ai_glvochcode := v_ai_glvochcode;
  RETURN;
  return_value := 0;
  ai_glvochcode := v_ai_glvochcode;
  RETURN;
END
$body$;

-- ==== proc SP_CreateVoucher_From_SOReceipt ====
CREATE OR REPLACE FUNCTION dbo.sp_createvoucher_from_soreceipt(ai_soreceiptcode integer, ai_usercode integer, INOUT ai_glvochcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_soreceiptcode integer;
  v_ai_usercode integer;
  v_ai_glvochcode integer;
  v_ai_vochcatcode integer;
  v_ai_acccode integer;
  v_ai_modifiedby integer;
  v_ai_postedby integer;
  v_ai_dr_acccode integer;
  v_ai_cr_acccode integer;
  v_ai_patientcode integer;
  v_ai_invoicecode integer;
  v_glvochcode integer;
  v_vochcode integer;
  v_ad_date timestamp(3);
  v_ad_postdate timestamp(3);
  v_ad_originaldate timestamp(3);
  v_as_remarks citext;
  v_as_chkno citext;
  v_as_chkno_detail citext;
  v_an_amount numeric(15,2);
  v_as_remarks_detail citext;
  v_an_outstandingamt numeric(15,2);
  v_an_balance numeric(15,2);
  v_as_posted citext;
  v_err integer;
  v_rowcount integer;
  v_tabmaxkey integer;
  v_ai_vouchercode integer;
  _rc integer;
BEGIN
  v_ai_soreceiptcode := ai_soreceiptcode;
  v_ai_usercode := ai_usercode;
  v_ai_glvochcode := ai_glvochcode;
  SELECT r.return_value, r.key INTO v_err, v_tabmaxkey FROM dbo.sp_gettabmaxkey(tabname => 'GLHeader', key => v_tabmaxkey) AS r;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'GL Voucher Code generation problem';
    return_value := -1;
    ai_glvochcode := v_ai_glvochcode;
    RETURN;
  END IF;
  v_ai_vochcatcode := 5;
  _rc := 1;
  SELECT r.return_value, r.ai_vouchercode INTO v_err, v_ai_vouchercode FROM dbo.sp_getvouchercode(ai_vochcatcode => v_ai_vochcatcode, ai_vouchercode => v_ai_vouchercode) AS r;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Voucher Code Generation Problem';
    return_value := -1;
    ai_glvochcode := v_ai_glvochcode;
    RETURN;
  END IF;
  v_ai_acccode := 2;
  _rc := 1;
  v_ad_date := localtimestamp(3);
  _rc := 1;
  v_as_posted := 'Y';
  _rc := 1;
  v_ad_postdate := localtimestamp(3);
  _rc := 1;
  v_as_remarks := (SELECT receiptremarks FROM dbo.soreceipt WHERE (soreceiptcode = v_ai_soreceiptcode));
  _rc := 1;
  v_ad_originaldate := localtimestamp(3);
  _rc := 1;
  v_ai_modifiedby := NULL;
  _rc := 1;
  v_ai_postedby := v_ai_usercode;
  _rc := 1;
  v_as_chkno := (SELECT receiptrefno FROM dbo.soreceipt WHERE (soreceiptcode = v_ai_soreceiptcode));
  _rc := 1;
  SELECT r.return_value INTO v_err FROM dbo.sp_setglheader(ai_glvochcode => v_tabmaxkey, ai_vochcatcode => v_ai_vochcatcode, ai_acccode => v_ai_acccode, ad_date => v_ad_date, ai_salesmancode => v_ai_usercode, as_posted => v_as_posted, ad_postdate => v_ad_postdate, as_remarks => v_as_remarks, ad_originaldate => v_ad_originaldate, ai_modifiedby => v_ai_modifiedby, ai_postedby => v_ai_postedby, as_chkno => v_as_chkno, ai_vouchercode => v_ai_vouchercode) AS r;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Problem Inserting Voucher (Table:GLHeader)';
    return_value := -1;
    ai_glvochcode := v_ai_glvochcode;
    RETURN;
  END IF;
  INSERT INTO dbo.gldetail (glvochcode, acccode, debit, credit, chkno, remarks, glutn, patientcode, invoicecode, outstandingamt, balance, guestcode, studentcode) SELECT v_tabmaxkey, acccode, 0.00 AS debit, coalesce(receiptamt, 0) AS credit, v_as_chkno, v_as_remarks, NULL::bigint AS glutn, patientcode, NULL::integer AS invoicecode, 0.00 AS outstandingamt, 0 AS balance, NULL::integer AS guestcode, NULL::integer AS studentcode FROM dbo.soreceipt WHERE ((soreceiptcode = v_ai_soreceiptcode) AND (coalesce(receiptamt, 0) <> 0)) UNION ALL SELECT v_tabmaxkey, acccode, 0.00 AS debit, coalesce(whtaxamt, 0) AS credit, v_as_chkno, v_as_remarks, NULL::bigint AS glutn, patientcode, NULL::integer AS invoicecode, 0.00 AS outstandingamt, 0 AS balance, NULL::integer AS guestcode, NULL::integer AS studentcode FROM dbo.soreceipt WHERE ((soreceiptcode = v_ai_soreceiptcode) AND (coalesce(whtaxamt, 0) <> 0)) UNION ALL SELECT v_tabmaxkey, receiptacccode, coalesce(receiptamt, 0) AS debit, 0.00 AS credit, receiptrefno, receiptremarks, NULL::bigint AS glutn, patientcode, NULL::integer AS invoicecode, 0.00 AS outstandingamt, 0 AS balance, NULL::integer AS guestcode, NULL::integer AS studentcode FROM dbo.soreceipt WHERE ((soreceiptcode = v_ai_soreceiptcode) AND (coalesce(receiptamt, 0) <> 0)) UNION ALL SELECT v_tabmaxkey, whtaxacccode, coalesce(whtaxamt, 0) AS debit, 0.00 AS credit, whtaxrefno, whtaxremarks, NULL::bigint AS glutn, patientcode, NULL::integer AS invoicecode, 0.00 AS outstandingamt, 0 AS balance, NULL::integer AS guestcode, NULL::integer AS studentcode FROM dbo.soreceipt WHERE ((soreceiptcode = v_ai_soreceiptcode) AND (coalesce(whtaxamt, 0) <> 0)) UNION ALL SELECT v_tabmaxkey, deduction1_acccode, coalesce(deduction1, 0) AS debit, 0.00 AS credit, deduction1_ref, deduction1_remarks, NULL::bigint AS glutn, patientcode, NULL::integer AS invoicecode, 0.00 AS outstandingamt, 0 AS balance, NULL::integer AS guestcode, NULL::integer AS studentcode FROM dbo.soreceipt WHERE (((soreceiptcode = v_ai_soreceiptcode) AND (coalesce(deduction1, 0) <> 0)) AND (deduction1_acccode IS NOT NULL)) UNION ALL SELECT v_tabmaxkey, acccode, 0.00 AS debit, coalesce(deduction1, 0) AS credit, deduction1_ref, deduction1_remarks, NULL::bigint AS glutn, patientcode, NULL::integer AS invoicecode, 0.00 AS outstandingamt, 0 AS balance, NULL::integer AS guestcode, NULL::integer AS studentcode FROM dbo.soreceipt WHERE (((soreceiptcode = v_ai_soreceiptcode) AND (coalesce(deduction1, 0) <> 0)) AND (deduction1_acccode IS NOT NULL)) UNION ALL SELECT v_tabmaxkey, deduction2_acccode, coalesce(deduction2, 0) AS debit, 0.00 AS credit, deduction2_ref, deduction2_remarks, NULL::bigint AS glutn, patientcode, NULL::integer AS invoicecode, 0.00 AS outstandingamt, 0 AS balance, NULL::integer AS guestcode, NULL::integer AS studentcode FROM dbo.soreceipt WHERE (((soreceiptcode = v_ai_soreceiptcode) AND (coalesce(deduction2, 0) <> 0)) AND (deduction2_acccode IS NOT NULL)) UNION ALL SELECT v_tabmaxkey, acccode, 0.00 AS debit, coalesce(deduction2, 0) AS credit, deduction2_ref, deduction2_remarks, NULL::bigint AS glutn, patientcode, NULL::integer AS invoicecode, 0.00 AS outstandingamt, 0 AS balance, NULL::integer AS guestcode, NULL::integer AS studentcode FROM dbo.soreceipt WHERE (((soreceiptcode = v_ai_soreceiptcode) AND (coalesce(deduction2, 0) <> 0)) AND (deduction2_acccode IS NOT NULL)) UNION ALL SELECT v_tabmaxkey, deduction3_acccode, coalesce(deduction3, 0) AS debit, 0.00 AS credit, deduction3_ref, deduction3_remarks, NULL::bigint AS glutn, patientcode, NULL::integer AS invoicecode, 0.00 AS outstandingamt, 0 AS balance, NULL::integer AS guestcode, NULL::integer AS studentcode FROM dbo.soreceipt WHERE (((soreceiptcode = v_ai_soreceiptcode) AND (coalesce(deduction3, 0) <> 0)) AND (deduction3_acccode IS NOT NULL)) UNION ALL SELECT v_tabmaxkey, acccode, 0.00 AS debit, coalesce(deduction3, 0) AS credit, deduction3_ref, deduction3_remarks, NULL::bigint AS glutn, patientcode, NULL::integer AS invoicecode, 0.00 AS outstandingamt, 0 AS balance, NULL::integer AS guestcode, NULL::integer AS studentcode FROM dbo.soreceipt WHERE (((soreceiptcode = v_ai_soreceiptcode) AND (coalesce(deduction3, 0) <> 0)) AND (deduction3_acccode IS NOT NULL)) UNION ALL SELECT v_tabmaxkey, deduction4_acccode, coalesce(deduction4, 0) AS debit, 0.00 AS credit, deduction4_ref, deduction4_remarks, NULL::bigint AS glutn, patientcode, NULL::integer AS invoicecode, 0.00 AS outstandingamt, 0 AS balance, NULL::integer AS guestcode, NULL::integer AS studentcode FROM dbo.soreceipt WHERE (((soreceiptcode = v_ai_soreceiptcode) AND (coalesce(deduction4, 0) <> 0)) AND (deduction4_acccode IS NOT NULL)) UNION ALL SELECT v_tabmaxkey, acccode, 0.00 AS debit, coalesce(deduction4, 0) AS credit, deduction4_ref, deduction4_remarks, NULL::bigint AS glutn, patientcode, NULL::integer AS invoicecode, 0.00 AS outstandingamt, 0 AS balance, NULL::integer AS guestcode, NULL::integer AS studentcode FROM dbo.soreceipt WHERE (((soreceiptcode = v_ai_soreceiptcode) AND (coalesce(deduction4, 0) <> 0)) AND (deduction4_acccode IS NOT NULL)) UNION ALL SELECT v_tabmaxkey, deduction5_acccode, coalesce(deduction5, 0) AS debit, 0.00 AS credit, deduction5_ref, deduction5_remarks, NULL::bigint AS glutn, patientcode, NULL::integer AS invoicecode, 0.00 AS outstandingamt, 0 AS balance, NULL::integer AS guestcode, NULL::integer AS studentcode FROM dbo.soreceipt WHERE (((soreceiptcode = v_ai_soreceiptcode) AND (coalesce(deduction5, 0) <> 0)) AND (deduction5_acccode IS NOT NULL)) UNION ALL SELECT v_tabmaxkey, acccode, 0.00 AS debit, coalesce(deduction5, 0) AS credit, deduction5_ref, deduction5_remarks, NULL::bigint AS glutn, patientcode, NULL::integer AS invoicecode, 0.00 AS outstandingamt, 0 AS balance, NULL::integer AS guestcode, NULL::integer AS studentcode FROM dbo.soreceipt WHERE (((soreceiptcode = v_ai_soreceiptcode) AND (coalesce(deduction5, 0) <> 0)) AND (deduction5_acccode IS NOT NULL));
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF (((0 <> 0) OR (v_err <> 0)) OR (_rc = 0)) THEN
    RAISE EXCEPTION 'Problem Inserting Voucher (Table:GLDetail)';
    return_value := -1;
    ai_glvochcode := v_ai_glvochcode;
    RETURN;
  END IF;
  v_glvochcode := v_tabmaxkey;
  _rc := 1;
  v_vochcode := v_ai_vouchercode;
  _rc := 1;
  v_ai_glvochcode := v_tabmaxkey;
  _rc := 1;
  UPDATE dbo.soreceipt SET glvochcode = v_glvochcode, posted = 'Y', postedby = v_ai_usercode, postdate = localtimestamp(3) WHERE (soreceiptcode = v_ai_soreceiptcode);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF (((0 <> 0) OR (v_err <> 0)) OR (_rc = 0)) THEN
    RAISE EXCEPTION 'Problem Updating GL Voucher Code in (Table: SOReceipt)';
    return_value := -1;
    ai_glvochcode := v_ai_glvochcode;
    RETURN;
  END IF;
  return_value := 0;
  ai_glvochcode := v_ai_glvochcode;
  RETURN;
  return_value := 0;
  ai_glvochcode := v_ai_glvochcode;
  RETURN;
END
$body$;

-- ==== proc sp_CRS_AutoSendStockAndSales ====
CREATE OR REPLACE FUNCTION dbo.sp_crs_autosendstockandsales(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_rc integer;
  v_rc2 integer;
  v_rc3 integer;
BEGIN
  -- BEGIN TRANSACTION (the caller owns the transaction)
  SELECT r.return_value INTO v_rc FROM dbo.sp_crs_transmitstockinhand() AS r;
  IF (v_rc = 0) THEN
    -- COMMIT (the caller owns the transaction)
  ELSE
    RAISE EXCEPTION 'T-SQL ROLLBACK in sp_CRS_AutoSendStockAndSales' USING ERRCODE = 'TS001';
  END IF;
  -- BEGIN TRANSACTION (the caller owns the transaction)
  SELECT r.return_value INTO v_rc2 FROM dbo.sp_crs_transmitclientsale() AS r;
  IF (v_rc2 = 0) THEN
    -- COMMIT (the caller owns the transaction)
  ELSE
    RAISE EXCEPTION 'T-SQL ROLLBACK in sp_CRS_AutoSendStockAndSales' USING ERRCODE = 'TS001';
  END IF;
  -- BEGIN TRANSACTION (the caller owns the transaction)
  SELECT r.return_value INTO v_rc3 FROM dbo.sp_crs_transmitclientsalereturn() AS r;
  IF (v_rc3 = 0) THEN
    -- COMMIT (the caller owns the transaction)
  ELSE
    RAISE EXCEPTION 'T-SQL ROLLBACK in sp_CRS_AutoSendStockAndSales' USING ERRCODE = 'TS001';
  END IF;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_CRS_ClientDataTransfer ====
CREATE OR REPLACE FUNCTION dbo.sp_crs_clientdatatransfer(srv citext, db citext, owner citext, usercode smallint DEFAULT NULL, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_usercode smallint;
  v_err integer;
  v_versionsyn smallint;
  v_clientid smallint;
  v_instanceid smallint;
  v_logid integer;
  v_instancename citext;
  v_remarks citext;
  v_tablename citext;
  v_lasttablename citext;
  v_localupd citext;
  v_query citext;
  v_tableprefix citext;
  v_transfertype citext;
  v_clientid_str citext;
  v_instanceid_str citext;
  v_logid_str citext;
  _dq1 text;
  _dq2 text;
  cur_tmpcrs1 refcursor;
  _dq3 text;
  _dq4 text;
  _dq5 text;
  _dq6 text;
  _rc integer;
  _fs integer := -1;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  v_usercode := usercode;
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  -- SET NOCOUNT ON
  -- SET XACT_ABORT ON
  v_tableprefix := '';
  _rc := 1;
  IF (((length(rtrim(ltrim(rtrim(v_srv)))) = 0) OR (v_srv IS NULL))) THEN
    v_tableprefix := '';
    _rc := 1;
  ELSE
    v_tableprefix := (v_srv || '.');
    _rc := 1;
  END IF;
  IF (((length(rtrim(ltrim(rtrim(v_db)))) = 0) OR (v_db IS NULL))) THEN
    v_tableprefix := v_tableprefix;
    _rc := 1;
  ELSE
    v_tableprefix := ((v_tableprefix || v_db) || '.');
    _rc := 1;
  END IF;
  IF (((length(rtrim(ltrim(rtrim(v_owner)))) = 0) OR (v_owner IS NULL))) THEN
    v_tableprefix := ((v_tableprefix || 'DBO') || '.');
    _rc := 1;
  ELSE
    v_tableprefix := ((v_tableprefix || v_owner) || '.');
    _rc := 1;
  END IF;
  v_versionsyn := 0;
  _rc := 1;
  SELECT r.return_value, r.versionsyn INTO v_err, v_versionsyn FROM dbo.sp_compare_remote_versioninfo(prefix => v_tableprefix, versionsyn => (v_versionsyn)::integer) AS r;
  v_err := 0;
  _rc := 1;
  IF (((0 <> 0) OR (v_err <> 0)) OR (v_versionsyn = 0)) THEN
    RAISE EXCEPTION 'Unable to Continue due to Local and Remote version Conflicts.';
    return_value := -1;
    RETURN;
  END IF;
  v_instancename := coalesce((SELECT name FROM dbo.clientinstance), '');
  _rc := 1;
  SELECT r.return_value, r.clientid, r.instanceid INTO v_err, v_clientid, v_instanceid FROM dbo.sp_crs_getclientinstanceinfo(srv => v_srv, db => v_db, owner => v_owner, instancename => v_instancename, clientid => v_clientid, instanceid => v_instanceid) AS r;
  v_err := 0;
  _rc := 1;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'CRS Instance Verification: Unable to make CRS Instance Verification From CRS Server.';
    return_value := -1;
    RETURN;
  END IF;
  IF ((((v_clientid IS NULL) OR (v_clientid = 0)) OR (v_instanceid IS NULL)) OR (v_instanceid = 0)) THEN
    RAISE EXCEPTION 'CRS Instance Validation: Unable to Validate CRS Instance From CRS Server.';
    return_value := -1;
    RETURN;
  END IF;
  UPDATE dbo.clientinstance SET clientid = v_clientid, clientinstanceid = v_instanceid;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_clientid_str := ltrim(rtrim((v_clientid)::text));
  _rc := 1;
  v_instanceid_str := ltrim(rtrim((v_instanceid)::text));
  _rc := 1;
  v_query := (((((('INSERT INTO ' || v_tableprefix) || 'CRS_DataTransferLog (ClientInstanceID, UserCode, StartDate, EndDate) VALUES (') || v_instanceid_str) || ', ') || coalesce(dbo.tsql_str((v_usercode)::numeric), 'NULL')) || ', localtimestamp(3), localtimestamp(3))');
  _rc := 1;
  _dq1 := v_query;
  IF _dq1 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq1);
  END IF;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_err := 0;
  _rc := 1;
  IF (((0 <> 0) OR (v_err <> 0)) OR (_rc = 0)) THEN
    RAISE EXCEPTION 'CRS Data Transfer Error: Problem in generating data transfer log header row';
    return_value := -1;
    RETURN;
  END IF;
  v_query := ((('INSERT INTO REPORTDATA (Code1, Name1) SELECT LOGID=MAX(LogID), Name1 = ''CRS_DataTransferLog'' FROM ' || v_tableprefix) || 'CRS_DataTransferLog WHERE ClientInstanceID = ') || v_instanceid_str);
  _rc := 1;
  _dq2 := v_query;
  IF _dq2 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq2);
  END IF;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_err := 0;
  _rc := 1;
  IF (((0 <> 0) OR (v_err <> 0)) OR (_rc = 0)) THEN
    RAISE EXCEPTION 'CRS Data Transfer Error: Problem in generating data transfer log header row';
    return_value := -1;
    RETURN;
  END IF;
  v_logid := trunc(coalesce((SELECT max(code1) FROM dbo.reportdata WHERE (name1 = 'CRS_DataTransferLog')), 0))::integer;
  _rc := 1;
  v_logid_str := ltrim(rtrim((v_logid)::text));
  _rc := 1;
  IF ((v_logid <= 0) OR (v_logid IS NULL)) THEN
    RAISE EXCEPTION 'CRS Data Transfer Error: Problem in generating data transfer log header row';
    return_value := -1;
    RETURN;
  END IF;
  OPEN cur_tmpcrs1 FOR SELECT sourcetablename, remarks, transfertype, priority FROM dbo.crs_transferabledata WHERE (enable = 'Y') ORDER BY transfertype, priority;
  FETCH NEXT FROM cur_tmpcrs1 INTO v_tablename, v_remarks, v_transfertype;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    v_query := (((((('INSERT INTO ' || v_tableprefix) || 'CRS_DataTransferLogDetail (LogID, SourceTableName, StartDate, EndDate) VALUES (') || v_logid_str) || ', ''') || v_tablename) || ''', GETDATE(), GETDATE())');
    _rc := 1;
    _dq3 := v_query;
    IF _dq3 IS NOT NULL THEN
      EXECUTE dbo.tsql_dyn(_dq3);
    END IF;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_err := 0;
    _rc := 1;
    IF ((0 <> 0) OR (v_err <> 0)) THEN
      RAISE EXCEPTION 'CRS Data Transfer Error: Problem in generating data transfer log detail row';
      return_value := -1;
      RETURN;
    END IF;
    SELECT r.return_value INTO v_err FROM dbo.sp_crs_transferclienttable(srv => v_srv, db => v_db, owner => v_owner, clientid => v_clientid, instanceid => v_instanceid, sourcetablename => v_tablename) AS r;
    v_err := 0;
    _rc := 1;
    IF ((0 <> 0) OR (v_err <> 0)) THEN
      RAISE EXCEPTION 'CRS Data Transfer Error: Unable to Transfer Object, Name = %.', v_tablename;
      CLOSE cur_tmpcrs1;
      -- DEALLOCATE TmpCrs1
      return_value := -1;
      RETURN;
    END IF;
    IF (((v_transfertype = 'T') AND ((right(upper(v_tablename), 6))::citext = 'DETAIL')) AND ((upper(v_tablename))::citext <> 'GODOWNDETAIL')) THEN
      IF ((upper(v_lasttablename))::citext = 'DUESATISFYHEADER') THEN
        v_localupd := (('UPDATE ' || v_lasttablename) || ' SET CRS_Transfered = ''Y'', CRS_TransferedON = localtimestamp(3) WHERE CRS_Transfered = ''N''');
        _rc := 1;
      ELSE
        v_localupd := (('UPDATE ' || v_lasttablename) || ' SET CRS_Transfered = ''Y'', CRS_TransferedON = localtimestamp(3) WHERE CRS_Transfered = ''N'' AND Posted=''Y'' ');
        _rc := 1;
      END IF;
      _dq4 := v_localupd;
      IF _dq4 IS NOT NULL THEN
        EXECUTE dbo.tsql_dyn(_dq4);
      END IF;
      GET DIAGNOSTICS _rc = ROW_COUNT;
      v_err := 0;
      _rc := 1;
      IF ((0 <> 0) OR (v_err <> 0)) THEN
        RAISE EXCEPTION 'CRS Data Transfer Error: Unable to Update Status of Object, Name = %.', v_lasttablename;
        CLOSE cur_tmpcrs1;
        -- DEALLOCATE TmpCrs1
        return_value := -1;
        RETURN;
      END IF;
    END IF;
    v_query := (((((('UPDATE ' || v_tableprefix) || 'CRS_DataTransferLogDetail SET EndDate = localtimestamp(3) WHERE LogID = ') || v_logid_str) || ' AND SourceTableName = ''') || v_tablename) || '''');
    _rc := 1;
    _dq5 := v_query;
    IF _dq5 IS NOT NULL THEN
      EXECUTE dbo.tsql_dyn(_dq5);
    END IF;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_err := 0;
    _rc := 1;
    IF ((0 <> 0) OR (v_err <> 0)) THEN
      RAISE EXCEPTION 'CRS Data Transfer Error: Problem in marking end date for data transfer log detail row';
      return_value := -1;
      RETURN;
    END IF;
    v_lasttablename := v_tablename;
    _rc := 1;
    FETCH NEXT FROM cur_tmpcrs1 INTO v_tablename, v_remarks, v_transfertype;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_tmpcrs1;
  -- DEALLOCATE TmpCrs1
  v_query := ((('UPDATE ' || v_tableprefix) || 'CRS_DataTransferLog SET EndDate = localtimestamp(3) WHERE LogID = ') || v_logid_str);
  _rc := 1;
  _dq6 := v_query;
  IF _dq6 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq6);
  END IF;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_err := 0;
  _rc := 1;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'CRS Data Transfer Error: Problem in marking end date for data transfer log';
    return_value := -1;
    RETURN;
  END IF;
  SELECT r.return_value, r.rs1 INTO v_err, rs1 FROM dbo.sp_crs_fetchfinalizedsaleorders(srv => v_srv, db => v_db, owner => v_owner, clientinstanceid => v_instanceid, usercode => v_usercode) AS r;
  v_err := 0;
  _rc := 1;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Unable To Fetch Sale Orders From CRS Server.';
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_CRS_CRSClient_MONTHLYSALES ====
CREATE OR REPLACE FUNCTION dbo.sp_crs_crsclient_monthlysales(ar_startdate timestamp, ar_enddate timestamp, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ar_startdate timestamp(3);
  v_ar_enddate timestamp(3);
BEGIN
  v_ar_startdate := ar_startdate;
  v_ar_enddate := ar_enddate;
  DELETE FROM dbo.reportdata;
  INSERT INTO dbo.reportdata (name1, date1, value1) SELECT t.clientname, (t.date)::timestamp(3), sum(t.value) AS netsales FROM (SELECT ((ltrim(rtrim((extract(month from sl.date)::integer)::text)) || '-01-') || rtrim(ltrim(to_char(sl.date, 'YYYY')))) AS date, cl.name AS clientname, sum(coalesce(sl.invtotal, 0)) AS value FROM dbo.crs_clientinstance AS ci, dbo.crs_clientlist AS cl, dbo.crs_saleledger AS sl WHERE ((((cl.clientid = ci.clientid) AND (ci.clientinstanceid = sl.clientinstanceid)) AND (sl.posted = 'Y')) AND (sl.date BETWEEN v_ar_startdate AND v_ar_enddate)) GROUP BY sl.date, cl.name UNION ALL SELECT ((ltrim(rtrim((extract(month from date)::integer)::text)) || '-01-') || rtrim(ltrim(to_char(date, 'YYYY')))) AS date, cl.name AS clientname, (-sum(coalesce(sl.invtotal, 0))) AS value FROM dbo.crs_clientinstance AS ci, dbo.crs_clientlist AS cl, dbo.crs_srledger AS sl WHERE ((((cl.clientid = ci.clientid) AND (ci.clientinstanceid = sl.clientinstanceid)) AND (sl.posted = 'Y')) AND (sl.date BETWEEN v_ar_startdate AND v_ar_enddate)) GROUP BY sl.date, cl.name UNION ALL SELECT ((ltrim(rtrim((extract(month from v_ar_startdate)::integer)::text)) || '-01-') || rtrim(ltrim(to_char(v_ar_startdate, 'YYYY')))) AS date, cl.name AS clientname, 0.00 AS value FROM dbo.crs_clientlist AS cl) AS t GROUP BY t.clientname, t.date;
  return_value := 0;
  RETURN;
END
$body$;

