-- ==== proc SP_CRS_Fetch_ItemStockPosition ====
CREATE OR REPLACE FUNCTION dbo.sp_crs_fetch_itemstockposition(srv citext, db citext, owner citext, icode integer, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_icode integer;
  v_tp citext;
  v_itemname citext;
  v_qry citext;
  _dq1 text;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  v_icode := icode;
  v_tp := '';
  IF (((length(rtrim(ltrim(rtrim(v_srv)))) = 0) OR (v_srv IS NULL))) THEN
    v_tp := '';
  ELSE
    v_tp := (v_srv || '.');
  END IF;
  IF (((length(rtrim(ltrim(rtrim(v_db)))) = 0) OR (v_db IS NULL))) THEN
    v_tp := v_tp;
  ELSE
    v_tp := ((v_tp || v_db) || '.');
