-- ==== proc SP_CRS_FetchFinalizedSaleOrders ====
CREATE OR REPLACE FUNCTION dbo.sp_crs_fetchfinalizedsaleorders(srv citext, db citext, owner citext, clientinstanceid smallint, usercode smallint DEFAULT NULL, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_clientinstanceid smallint;
  v_usercode smallint;
  v_err integer;
  v_lastsocode integer;
  v_rowid integer;
  v_socount integer;
  v_header_qry citext;
  v_detail_qry citext;
  v_instanceid_str citext;
  v_logid_str citext;
  v_tp citext;
  _dq1 text;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  v_clientinstanceid := clientinstanceid;
  v_usercode := usercode;
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  -- SET NOCOUNT ON
  -- SET XACT_ABORT ON
  v_tp := '';
  IF (((length(rtrim(ltrim(rtrim(v_srv)))) = 0) OR (v_srv IS NULL))) THEN
    v_tp := '';
  ELSE
    v_tp := (v_srv || '.');
  END IF;
  IF (((length(rtrim(ltrim(rtrim(v_db)))) = 0) OR (v_db IS NULL))) THEN
    v_tp := v_tp;
  ELSE
    v_tp := ((v_tp || v_db) || '.');
  END IF;
  IF (((length(rtrim(ltrim(rtrim(v_owner)))) = 0) OR (v_owner IS NULL))) THEN
    v_tp := ((v_tp || 'DBO') || '.');
  ELSE
    v_tp := ((v_tp || v_owner) || '.');
  END IF;
  IF (v_usercode IS NULL) THEN
    v_usercode := 1;
  END IF;
  v_instanceid_str := ltrim(rtrim((v_clientinstanceid)::text));
  SELECT r.return_value, r.key INTO v_err, v_lastsocode FROM dbo.sp_locktabmaxkey(tabname => 'SaleOrderHeader', key => v_lastsocode) AS r;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'CRS Data Transfer Error: unable to fetch new sale order code';
    return_value := -1;
    RETURN;
  END IF;
  DROP TABLE IF EXISTS tmp_soheader;
  CREATE TEMP TABLE tmp_soheader (
    saleordercode integer,
    custcode smallint,
    date timestamp(3),
    originaldate timestamp(3),
    billingdate timestamp(3),
    discperc numeric(6,2),
    flatdisc numeric(12,2),
    misccharges numeric(12,2),
    invgstperc1 numeric(6,2),
    invtotal numeric(12,2),
    sprice smallint,
    remarks citext,
    custrefno citext,
    custrefno2 citext,
    custrefno3 citext,
    custrefno4 citext,
    deliverydeadline timestamp(3),
    newsocode integer NOT NULL DEFAULT (0),
    myrowid integer GENERATED BY DEFAULT AS IDENTITY
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_sodetail;
  CREATE TEMP TABLE tmp_sodetail (
    saleordercode integer,
    icode integer,
    gcode smallint,
    looseqty numeric(15,4),
    packunits smallint,
    saleprice numeric(12,2),
    discperc numeric(6,2),
    itemflatdisc numeric(12,2),
    saleitemdescription citext,
    unitsalestax numeric(12,2),
    gstperc numeric(6,2),
    bonusqty numeric(15,4),
    remarks citext,
    batch citext,
    expiry timestamp(3)
) ON COMMIT DROP;
  v_header_qry := ((('SELECT SaleOrderCode, CustCode, Date, OriginalDate, BillingDate, DiscPerc, FlatDisc, MiscCharges, InvGSTPerc1, InvTotal, SPrice, Remarks, CustRefNo, CustRefNo2, CustRefNo3, CustRefNo4, DeliveryDeadLine FROM ' || v_tp) || 'SaleOrderHeader WHERE Finalized=''Y'' AND Posted=''N'' AND CRS_Sent=''N'' AND ClientInstanceID=') || v_instanceid_str);
  EXECUTE coalesce('INSERT INTO tmp_soheader (saleordercode, custcode, date, originaldate, billingdate, discperc, flatdisc, misccharges, invgstperc1, invtotal, sprice, remarks, custrefno, custrefno2, custrefno3, custrefno4, deliverydeadline) ' || v_header_qry, 'SELECT 1');
  v_err := 0;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'CRS Data Transfer Error: Fetching Sale Order Header Data From source';
    return_value := -1;
    RETURN;
  END IF;
  v_socount := coalesce((SELECT count(*) FROM tmp_soheader AS soheader), 0);
  IF (v_socount <= 0) THEN
    return_value := 0;
    RETURN;
  END IF;
  v_detail_qry := (((((('SELECT SaleOrderCode, ICode, GCode=1, LooseQty, PackUnits, SalePrice, DiscPerc, ItemFlatDisc, SaleItemDescription, UnitSalesTax, GSTPerc, BonusQty, Remarks, Batch, Expiry FROM ' || v_tp) || 'SaleOrderDetail WHERE SaleOrderCode IN (SELECT SaleOrderCode FROM ') || v_tp) || 'SaleOrderHeader WHERE Finalized=''Y'' AND Posted=''N'' AND CRS_Sent=''N'' AND ClientInstanceID=') || v_instanceid_str) || ')');
  EXECUTE coalesce('INSERT INTO tmp_sodetail (saleordercode, icode, gcode, looseqty, packunits, saleprice, discperc, itemflatdisc, saleitemdescription, unitsalestax, gstperc, bonusqty, remarks, batch, expiry) ' || v_detail_qry, 'SELECT 1');
  v_err := 0;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'CRS Data Transfer Error: Fetching Sale Order Detail Data From source';
    return_value := -1;
    RETURN;
  END IF;
  UPDATE tmp_soheader AS soheader SET newsocode = (v_lastsocode + myrowid);
  v_err := 0;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'CRS Data Transfer Error: Updating Identity Column in Temporary Sale Order Data';
    return_value := -1;
    RETURN;
  END IF;
  UPDATE tmp_sodetail AS d SET saleordercode = h.newsocode FROM tmp_soheader AS h WHERE (h.saleordercode = d.saleordercode);
  INSERT INTO dbo.saleorderheader (saleordercode, custcode, usercode, date, originaldate, billingdate, discperc, flatdisc, misccharges, invgstperc1, invtotal, sprice, remarks, custrefno, custrefno2, custrefno3, custrefno4, deliverydeadline, grn) SELECT newsocode, custcode, v_usercode, date, originaldate, billingdate, discperc, flatdisc, misccharges, invgstperc1, invtotal, sprice, remarks, custrefno, custrefno2, custrefno3, custrefno4, deliverydeadline, saleordercode AS grn FROM tmp_soheader AS soheader;
  v_err := 0;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'CRS Data Transfer Error: Error Inseting Sale Order Data';
    return_value := -1;
    RETURN;
  END IF;
  INSERT INTO dbo.saleorderdetail (saleordercode, icode, gcode, looseqty, packunits, saleprice, discperc, itemflatdisc, saleitemdescription, unitsalestax, gstperc, bonusqty, remarks, batch, expiry) SELECT saleordercode, icode, gcode, looseqty, packunits, saleprice, discperc, itemflatdisc, saleitemdescription, unitsalestax, gstperc, bonusqty, remarks, batch, expiry FROM tmp_sodetail AS sodetail;
  v_err := 0;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'CRS Data Transfer Error: Error Inseting Sale Order Detail Data';
    return_value := -1;
    RETURN;
  END IF;
  v_lastsocode := coalesce((SELECT max(newsocode) FROM tmp_soheader AS soheader), 0);
  SELECT r.return_value INTO v_err FROM dbo.sp_updatetabmaxkey(tabname => 'SaleOrderHeader', key => v_lastsocode) AS r;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'CRS Data Transfer Error: unable to update new sale order code';
    return_value := -1;
    RETURN;
  END IF;
  v_header_qry := ((((('Update ' || v_tp) || 'SaleOrderHeader SET CRS_Sent = ''Y'', CRS_SentOn = localtimestamp(3), Posted=''Y'', PostDate=localtimestamp(3), PostedBy=') || ltrim(rtrim(dbo.tsql_str((v_usercode)::numeric)))) || ' WHERE Finalized=''Y'' AND Posted=''N'' AND CRS_Sent=''N'' AND ClientInstanceID=') || v_instanceid_str);
  _dq1 := v_header_qry;
  IF _dq1 IS NOT NULL THEN
    IF _dq1 ~* '^[[:space:]]*select' THEN OPEN rs1 FOR EXECUTE dbo.tsql_dyn(_dq1); ELSE EXECUTE dbo.tsql_dyn(_dq1); END IF;
  END IF;
  v_err := 0;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'CRS Data Transfer Error: Error Marking Sale Order On source as Sent';
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_CRS_GetClientInstanceInfo ====
CREATE OR REPLACE FUNCTION dbo.sp_crs_getclientinstanceinfo(srv citext, db citext, owner citext, instancename citext, INOUT clientid smallint, INOUT instanceid smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_instancename citext;
  v_clientid smallint;
  v_instanceid smallint;
  v_tp citext;
  v_qry citext;
  _dq1 text;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  v_instancename := instancename;
  v_clientid := clientid;
  v_instanceid := instanceid;
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  v_tp := '';
  IF (((length(rtrim(ltrim(rtrim(v_srv)))) = 0) OR (v_srv IS NULL))) THEN
    v_tp := '';
  ELSE
    v_tp := (v_srv || '.');
  END IF;
  IF (((length(rtrim(ltrim(rtrim(v_db)))) = 0) OR (v_db IS NULL))) THEN
    v_tp := v_tp;
  ELSE
    v_tp := ((v_tp || v_db) || '.');
  END IF;
  IF (((length(rtrim(ltrim(rtrim(v_owner)))) = 0) OR (v_owner IS NULL))) THEN
    v_tp := ((v_tp || 'DBO') || '.');
  ELSE
    v_tp := ((v_tp || v_owner) || '.');
  END IF;
  DELETE FROM dbo.reportdata;
  v_qry := (((('INSERT INTO REPORTDATA (code1, code2, name1, name2) SELECT ClientInstanceID, ClientID, Name, Description FROM ' || v_tp) || 'CRS_ClientInstance WHERE Name = ''') || v_instancename) || '''');
  _dq1 := v_qry;
  IF _dq1 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq1);
  END IF;
  v_instanceid := trunc((SELECT code1 FROM dbo.reportdata))::smallint;
  v_clientid := trunc((SELECT code2 FROM dbo.reportdata))::smallint;
  return_value := 0;
  clientid := v_clientid;
  instanceid := v_instanceid;
  RETURN;
  return_value := 0;
  clientid := v_clientid;
  instanceid := v_instanceid;
  RETURN;
END
$body$;

-- ==== proc SP_CRS_GetLastCRSDataSendInfo ====
CREATE OR REPLACE FUNCTION dbo.sp_crs_getlastcrsdatasendinfo(srv citext, db citext, owner citext, INOUT clientinstanceid smallint, INOUT startdate timestamp, INOUT enddate timestamp, INOUT usercode smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_clientinstanceid smallint;
  v_startdate timestamp(3);
  v_enddate timestamp(3);
  v_usercode smallint;
  v_instancename citext;
  v_qry citext;
  v_clientid smallint;
  v_instanceid smallint;
  v_err integer;
  _dq1 text;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  v_clientinstanceid := clientinstanceid;
  v_startdate := startdate;
  v_enddate := enddate;
  v_usercode := usercode;
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  v_instancename := coalesce((SELECT name FROM dbo.clientinstance), '');
  SELECT r.return_value, r.clientid, r.instanceid INTO v_err, v_clientid, v_instanceid FROM dbo.sp_crs_getclientinstanceinfo(srv => v_srv, db => v_db, owner => v_owner, instancename => v_instancename, clientid => v_clientid, instanceid => v_instanceid) AS r;
  v_err := 0;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'CRS Instance Verification: Unable to make CRS Instance Verification From CRS Server.';
    return_value := -1;
    clientinstanceid := v_clientinstanceid;
    startdate := v_startdate;
    enddate := v_enddate;
    usercode := v_usercode;
    RETURN;
  END IF;
  DELETE FROM dbo.reportdata;
  v_qry := (((((((((((((((('INSERT INTO REPORTDATA (code1, date1, date2, code2) SELECT ClientInstanceID, StartDate, EndDate, UserCode  FROM ' || v_srv) || '.') || v_db) || '.') || v_owner) || '.CRS_DataTransferLog WHERE ClientInstanceID = ') || ltrim(rtrim(dbo.tsql_str((v_instanceid)::numeric)))) || ' AND LogID IN (SELECT LogID=MAX(LogID) FROM ') || v_srv) || '.') || v_db) || '.') || v_owner) || '.CRS_DataTransferLog WHERE ClientInstanceID = ') || ltrim(rtrim(dbo.tsql_str((v_instanceid)::numeric)))) || ')');
  _dq1 := v_qry;
  IF _dq1 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq1);
  END IF;
  v_clientinstanceid := trunc((SELECT max(code1) FROM dbo.reportdata))::smallint;
  v_startdate := (SELECT max(date1) FROM dbo.reportdata);
  v_enddate := (SELECT max(date2) FROM dbo.reportdata);
  v_usercode := trunc((SELECT max(code2) FROM dbo.reportdata))::smallint;
  return_value := 0;
  clientinstanceid := v_clientinstanceid;
  startdate := v_startdate;
  enddate := v_enddate;
  usercode := v_usercode;
  RETURN;
END
$body$;

-- ==== proc SP_CRS_GetTableKey ====
CREATE OR REPLACE FUNCTION dbo.sp_crs_gettablekey(table_id integer, tablename citext, fulltablename citext, INOUT pkcond citext, INOUT upd_pkcond citext, INOUT maxcol citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_table_id integer;
  v_tablename citext;
  v_fulltablename citext;
  v_pkcond citext;
  v_upd_pkcond citext;
  v_maxcol citext;
  v_colname citext;
  v_keyseq smallint;
  v_con citext;
  cur_tmpcrs refcursor;
  _fs integer := -1;
BEGIN
  v_table_id := table_id;
  v_tablename := tablename;
  v_fulltablename := fulltablename;
  v_pkcond := pkcond;
  v_upd_pkcond := upd_pkcond;
  v_maxcol := maxcol;
  v_con := 'CONVERT(VarChar(10),';
  -- OPEN TmpCrs
  RAISE EXCEPTION 'untranslated T-SQL (system table sysindexes)' USING ERRCODE = '0A000';
  FETCH NEXT FROM cur_tmpcrs INTO v_colname, v_keyseq;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    IF (v_keyseq <> 1) THEN
      v_pkcond := (v_pkcond || ' + ');
      IF (v_keyseq = 2) THEN
        v_upd_pkcond := v_upd_pkcond;
      ELSE
        v_upd_pkcond := (v_upd_pkcond || ' AND ');
      END IF;
    END IF;
    v_pkcond := ((((v_pkcond || ' ') || v_con) || ltrim(rtrim(v_colname))) || ')');
    IF (v_keyseq <> 1) THEN
      v_upd_pkcond := (((((v_upd_pkcond || ' S.') || ltrim(rtrim(v_colname))) || ' = ') || 'C.') || ltrim(rtrim(v_colname)));
    END IF;
    v_maxcol := (('MAX(' || rtrim(ltrim(v_colname))) || ')');
