      INSERT INTO dbo.reportdata (code4, name3, code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5) SELECT a.clientinstanceid, (SELECT c.name FROM dbo.crs_clientinstance AS ci, dbo.crs_clientlist AS c WHERE ((c.clientid = ci.clientid) AND (ci.clientinstanceid = a.clientinstanceid))) AS client, 8 AS code1, (SELECT (max(code2) + 1) FROM dbo.reportdata) AS code2, acccode AS code3, name AS name1, (SELECT max(name1) FROM dbo.reportdata WHERE ((code4 = a.clientinstanceid) AND (code2 = 8))) AS name2, coalesce(balance, 0) AS value1, 0 AS value2, 0 AS value3, 1 AS value4, v_ad_sdate AS date1, v_ad_edate AS date2, (v_ac_level)::numeric(15,2) AS value5 FROM (SELECT v.clientinstanceid, a.acccode, a.name, sum((coalesce(v.debit, 0) - coalesce(v.credit, 0))) AS balance FROM dbo.crs_virtualgl AS v, dbo.accounts AS a WHERE ((((v.acccode IN (SELECT acccode FROM dbo.accounts WHERE (subcode IN (SELECT subacccode FROM dbo.subaccounts WHERE (catacccode IN (SELECT catacccode FROM dbo.categoryaccounts WHERE (catacccode = v_ln_otherrevenuescat))))))) AND (v.acccode = a.acccode)) AND (v.date >= v_ad_sdate)) AND (v.date <= v_ad_edate)) GROUP BY v.clientinstanceid, a.acccode, a.name) AS a;
      GET DIAGNOSTICS _rc = ROW_COUNT;
    END IF;
    INSERT INTO dbo.reportdata (code4, name3, code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5) SELECT a.clientinstanceid, (SELECT c.name FROM dbo.crs_clientinstance AS ci, dbo.crs_clientlist AS c WHERE ((c.clientid = ci.clientid) AND (ci.clientinstanceid = a.clientinstanceid))) AS client, (10 + catacccode) AS code1, catacccode AS code2, acccode AS code3, name AS name1, catname AS name2, coalesce(balance, 0) AS value1, 0 AS value2, 0 AS value3, 1 AS value4, v_ad_sdate AS date1, v_ad_edate AS date2, (v_ac_level)::numeric(15,2) AS value5 FROM (SELECT v.clientinstanceid, a.acccode, a.name, c.catacccode, c.name AS catname, sum((coalesce(v.debit, 0) - coalesce(v.credit, 0))) AS balance FROM dbo.crs_virtualgl AS v, dbo.accounts AS a, dbo.subaccounts AS s, dbo.categoryaccounts AS c WHERE ((((((v.acccode IN (SELECT acccode FROM dbo.accounts WHERE (subcode IN (SELECT subacccode FROM dbo.subaccounts WHERE (catacccode IN (SELECT catacccode FROM dbo.categoryaccounts WHERE ((mainacccode IN (4, 5)) AND (catacccode NOT IN (v_ln_revenuefromsalescat, v_ln_directexpensescat, v_ln_operatingexpensescat, v_ln_otherexpensescat, v_ln_otherrevenuescat))))))))) AND (v.acccode = a.acccode)) AND (v.date >= v_ad_sdate)) AND (v.date <= v_ad_edate)) AND (a.subcode = s.subacccode)) AND (s.catacccode = c.catacccode)) GROUP BY v.clientinstanceid, a.acccode, a.name, c.name, c.catacccode) AS a;
    GET DIAGNOSTICS _rc = ROW_COUNT;
  END IF;
  UPDATE dbo.reportdata SET value1 = 0 WHERE (value1 IS NULL);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((v_ac_level = '2') OR (v_ac_level = '3')) THEN
    INSERT INTO dbo.reportdata (code4, name3, code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5) SELECT s.clientinstanceid, (SELECT c.name FROM dbo.crs_clientinstance AS ci, dbo.crs_clientlist AS c WHERE ((c.clientid = ci.clientid) AND (ci.clientinstanceid = s.clientinstanceid))) AS client, (SELECT (max(code1) + 1) FROM dbo.reportdata) AS code1, catcode AS code2, acccode AS code3, (SELECT name FROM dbo.salecategory WHERE (salecatcode = s.catcode)) AS name1, (SELECT max(name1) FROM dbo.reportdata WHERE ((code4 = s.clientinstanceid) AND (code3 = v_ln_salesacc))) AS name2, coalesce(balance, 0) AS value1, 0 AS value2, 0 AS value3, 2 AS value4, v_ad_sdate AS date1, v_ad_edate AS date2, (v_ac_level)::numeric(15,2) AS value5 FROM (SELECT v.clientinstanceid, acccode, catcode, sum((debit - credit)) AS balance FROM dbo.crs_virtualgl AS v WHERE ((acccode IN (v_ln_salesacc)) AND (date BETWEEN v_ad_sdate AND v_ad_edate)) GROUP BY v.clientinstanceid, v.acccode, v.catcode) AS s;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    INSERT INTO dbo.reportdata (code4, name3, code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5) SELECT sr.clientinstanceid, (SELECT c.name FROM dbo.crs_clientinstance AS ci, dbo.crs_clientlist AS c WHERE ((c.clientid = ci.clientid) AND (ci.clientinstanceid = sr.clientinstanceid))) AS client, (SELECT (max(code1) + 1) FROM dbo.reportdata) AS code1, catcode AS code2, acccode AS code3, (SELECT name FROM dbo.salecategory WHERE (salecatcode = sr.catcode)) AS name1, (SELECT max(name1) FROM dbo.reportdata WHERE ((code4 = sr.clientinstanceid) AND (code3 = v_ln_salesretacc))) AS name2, coalesce(balance, 0) AS value1, 0 AS value2, 0 AS value3, 2 AS value4, v_ad_sdate AS date1, v_ad_edate AS date2, (v_ac_level)::numeric(15,2) AS value5 FROM (SELECT v.clientinstanceid, acccode, catcode, sum((debit - credit)) AS balance FROM dbo.crs_virtualgl AS v WHERE (((acccode IN (v_ln_salesretacc)) AND (date >= v_ad_sdate)) AND (date <= v_ad_edate)) GROUP BY v.clientinstanceid, v.acccode, v.catcode) AS sr;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    INSERT INTO dbo.reportdata (code4, name3, code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5) SELECT p.clientinstanceid, (SELECT c.name FROM dbo.crs_clientinstance AS ci, dbo.crs_clientlist AS c WHERE ((c.clientid = ci.clientid) AND (ci.clientinstanceid = p.clientinstanceid))) AS client, (SELECT (max(code1) + 1) FROM dbo.reportdata) AS code1, catcode AS code2, acccode AS code3, (SELECT name FROM dbo.purcategory WHERE (purcatcode = p.catcode)) AS name1, (SELECT max(name1) FROM dbo.reportdata WHERE ((code4 = p.clientinstanceid) AND (code3 = v_ln_purchaseacc))) AS name2, coalesce(balance, 0) AS value1, 0 AS value2, 0 AS value3, 2 AS value4, v_ad_sdate AS date1, v_ad_edate AS date2, (v_ac_level)::numeric(15,2) AS value5 FROM (SELECT clientinstanceid, acccode, catcode, sum((debit - credit)) AS balance FROM dbo.crs_virtualgl AS v WHERE (((acccode IN (v_ln_purchaseacc)) AND (date >= v_ad_sdate)) AND (date <= v_ad_edate)) GROUP BY v.clientinstanceid, v.acccode, v.catcode) AS p;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    INSERT INTO dbo.reportdata (code4, name3, code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5) SELECT p.clientinstanceid, (SELECT c.name FROM dbo.crs_clientinstance AS ci, dbo.crs_clientlist AS c WHERE ((c.clientid = ci.clientid) AND (ci.clientinstanceid = p.clientinstanceid))) AS client, (SELECT (max(code1) + 1) FROM dbo.reportdata) AS code1, catcode AS code2, acccode AS code3, (SELECT name FROM dbo.purcategory WHERE (purcatcode = p.catcode)) AS name1, (SELECT max(name1) FROM dbo.reportdata WHERE ((code4 = p.clientinstanceid) AND (code3 = v_ln_purchaseretacc))) AS name2, coalesce(balance, 0) AS value1, 0 AS value2, 0 AS value3, 2 AS value4, v_ad_sdate AS date1, v_ad_edate AS date2, (v_ac_level)::numeric(15,2) AS value5 FROM (SELECT clientinstanceid, acccode, catcode, sum((debit - credit)) AS balance FROM dbo.crs_virtualgl AS v WHERE (((acccode IN (v_ln_purchaseretacc)) AND (date >= v_ad_sdate)) AND (date <= v_ad_edate)) GROUP BY v.clientinstanceid, v.acccode, v.catcode) AS p;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    INSERT INTO dbo.reportdata (code4, name3, code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5) SELECT s.clientinstanceid, (SELECT c.name FROM dbo.crs_clientinstance AS ci, dbo.crs_clientlist AS c WHERE ((c.clientid = ci.clientid) AND (ci.clientinstanceid = s.clientinstanceid))) AS client, (SELECT (max(code1) + 1) FROM dbo.reportdata) AS code1, catcode AS code2, a.acccode AS code3, (SELECT name FROM dbo.salecategory WHERE (salecatcode = s.catcode)) AS name1, (SELECT max(name1) FROM dbo.reportdata WHERE ((code4 = s.clientinstanceid) AND (code3 = v_ln_revfromservice))) AS name2, coalesce(balance, 0) AS value1, 0 AS value2, 0 AS value3, 2 AS value4, v_ad_sdate AS date1, v_ad_edate AS date2, (v_ac_level)::numeric(15,2) AS value5 FROM (SELECT clientinstanceid, acccode, catcode, sum((debit - credit)) AS balance FROM dbo.crs_virtualgl AS v WHERE (((acccode IN (v_ln_revfromservice)) AND (date >= v_ad_sdate)) AND (date <= v_ad_edate)) GROUP BY v.clientinstanceid, v.acccode, v.catcode) AS s, dbo.accounts AS a WHERE (s.acccode = a.acccode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
  END IF;
  UPDATE dbo.reportdata SET value1 = 0 WHERE (value1 IS NULL);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  UPDATE dbo.reportdata SET value2 = 0 WHERE (value2 IS NULL);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  -- COMMIT (the caller owns the transaction)
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_CRS_MONTHLYSALES ====
CREATE OR REPLACE FUNCTION dbo.sp_crs_monthlysales(ar_startdate timestamp, ar_enddate timestamp, ai_pricetype integer, ai_returns integer, ai_bonus integer, ai_allcust integer, ai_custcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ar_startdate timestamp(3);
  v_ar_enddate timestamp(3);
  v_ai_pricetype integer;
  v_ai_returns integer;
  v_ai_bonus integer;
  v_ai_allcust integer;
  v_ai_custcode integer;
BEGIN
  v_ar_startdate := ar_startdate;
  v_ar_enddate := ar_enddate;
  v_ai_pricetype := ai_pricetype;
  v_ai_returns := ai_returns;
  v_ai_bonus := ai_bonus;
  v_ai_allcust := ai_allcust;
  v_ai_custcode := ai_custcode;
  DELETE FROM dbo.reportdata;
  INSERT INTO dbo.reportdata (date1, name1, code1, name2, name3, name4, code2, value1, value2, value3, name5, name6) SELECT (st.date)::timestamp(3), ic.name AS name, i.icatcode AS code, i.name AS item, i.customicode AS aliasname, i.packingdesc AS packingdesc, st.icode, round(((i.saleprice / CASE WHEN (i.packunits > 0) THEN i.packunits ELSE 1 END))::numeric, 2) AS rate, sum(qty) AS saleqty, sum(CASE v_ai_pricetype WHEN 1 THEN value ELSE (round(((i.saleprice / CASE WHEN (i.packunits > 0) THEN i.packunits ELSE 1 END))::numeric, 2) * qty) END) AS salevalue, (SELECT m.name FROM dbo.manufacturer AS m WHERE (m.manfcode = i.manfcode)) AS manfname, CASE WHEN (v_ai_allcust = 0) THEN (SELECT a.name FROM dbo.accounts AS a WHERE (a.acccode = v_ai_custcode)) ELSE 'ALL CUSTOMERS' END AS customer FROM (SELECT sd.icode, ((ltrim(rtrim((extract(month from sl.date)::integer)::text)) || '-01-') || rtrim(ltrim(to_char(sl.date, 'YYYY')))) AS date, sum(((sd.looseqty + CASE v_ai_bonus WHEN 0 THEN 0 ELSE sd.bonusqty END) + (sd.packqty * sd.packunits))) AS qty, sum((((((sd.looseqty + (sd.packqty * sd.packunits))) * ((sd.saleprice - sd.itemflatdisc))) * ((1 - (sd.discperc * 0.01)))) * ((1 - (sl.discperc * 0.01))))) AS value FROM dbo.crs_clientinstance AS ci, dbo.crs_clientlist AS cl, dbo.crs_saleledger AS sl, dbo.crs_saledetail AS sd, (SELECT c.custcode FROM dbo.customer AS c WHERE ((v_ai_allcust = 0) AND (c.custcode = v_ai_custcode)) UNION SELECT c.custcode FROM dbo.customer AS c WHERE (v_ai_allcust = 1)) AS cs WHERE ((((((((cl.clientid = ci.clientid) AND (ci.clientinstanceid = sl.clientinstanceid)) AND (ci.clientinstanceid = sd.clientinstanceid)) AND (sl.clientinstanceid = sd.clientinstanceid)) AND (sl.saleinvcode = sd.saleinvcode)) AND (sl.posted = 'Y')) AND (sl.custcode = cs.custcode)) AND (sl.date BETWEEN v_ar_startdate AND v_ar_enddate)) GROUP BY sd.icode, sl.date UNION ALL SELECT sd.icode, ((ltrim(rtrim((extract(month from date)::integer)::text)) || '-01-') || rtrim(ltrim(to_char(date, 'YYYY')))) AS date, (-sum(((sd.looseqty + CASE v_ai_bonus WHEN 0 THEN 0 ELSE sd.bonusqty END) + (sd.packqty * sd.packunits)))) AS qty, (-sum((((((sd.looseqty + (sd.packqty * sd.packunits))) * sd.srprice) * ((1 - (sd.discperc * 0.01)))) * ((1 - (sl.discperc * 0.01)))))) AS value FROM dbo.crs_clientinstance AS ci, dbo.crs_clientlist AS cl, dbo.crs_srledger AS sl, dbo.crs_srdetail AS sd, (SELECT c.custcode FROM dbo.customer AS c WHERE ((v_ai_allcust = 0) AND (c.custcode = v_ai_custcode)) UNION SELECT c.custcode FROM dbo.customer AS c WHERE (v_ai_allcust = 1)) AS cs WHERE (((((((((cl.clientid = ci.clientid) AND (ci.clientinstanceid = sl.clientinstanceid)) AND (ci.clientinstanceid = sd.clientinstanceid)) AND (sl.clientinstanceid = sd.clientinstanceid)) AND (sl.srinvcode = sd.srinvcode)) AND (sl.posted = 'Y')) AND (sl.custcode = cs.custcode)) AND (sl.date BETWEEN v_ar_startdate AND v_ar_enddate)) AND (v_ai_returns = 1)) GROUP BY sd.icode, sl.date) AS st, dbo.item AS i, dbo.itemcategory AS ic WHERE ((st.icode = i.icode) AND (i.icatcode = ic.icatcode)) GROUP BY st.icode, i.name, i.customicode, st.date, i.icatcode, ic.name, i.manfcode, i.saleprice, i.packunits, i.packingdesc ORDER BY st.date, ic.name, i.icatcode, i.name, i.customicode, st.icode;
  return_value := 0;
  RETURN;
END
$body$;

