-- ==== proc SP_CRS_Push_CRSData ====
CREATE OR REPLACE FUNCTION dbo.sp_crs_push_crsdata(srv citext, db citext, owner citext, usercode smallint DEFAULT NULL, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_usercode smallint;
  v_err integer;
  v_versionsyn smallint;
  v_clientid smallint;
  v_instanceid smallint;
  v_logid integer;
  v_instancename citext;
  v_remarks citext;
  v_tablename citext;
  v_query citext;
  v_tp citext;
  v_transfertype citext;
  v_transactionname citext;
  v_cid citext;
  v_id citext;
  v_logid_str citext;
  _dq1 text;
  _dq2 text;
  cur_tmpcrs1 refcursor;
  _dq3 text;
  _dq4 text;
  _rc integer;
  _fs integer := -1;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  v_usercode := usercode;
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  -- SET NOCOUNT ON
  -- SET XACT_ABORT ON
  v_tp := '';
  _rc := 1;
  IF (((length(rtrim(ltrim(rtrim(v_srv)))) = 0) OR (v_srv IS NULL))) THEN
    v_tp := '';
    _rc := 1;
  ELSE
    v_tp := (v_srv || '.');
    _rc := 1;
  END IF;
  IF (((length(rtrim(ltrim(rtrim(v_db)))) = 0) OR (v_db IS NULL))) THEN
    v_tp := v_tp;
    _rc := 1;
  ELSE
    v_tp := ((v_tp || v_db) || '.');
    _rc := 1;
  END IF;
  IF (((length(rtrim(ltrim(rtrim(v_owner)))) = 0) OR (v_owner IS NULL))) THEN
    v_tp := ((v_tp || 'DBO') || '.');
    _rc := 1;
  ELSE
    v_tp := ((v_tp || v_owner) || '.');
    _rc := 1;
  END IF;
  v_versionsyn := 0;
  _rc := 1;
  SELECT r.return_value, r.versionsyn INTO v_err, v_versionsyn FROM dbo.sp_compare_remote_versioninfo(prefix => v_tp, versionsyn => (v_versionsyn)::integer) AS r;
  v_err := 0;
  _rc := 1;
  IF (((0 <> 0) OR (v_err <> 0)) OR (v_versionsyn = 0)) THEN
    RAISE EXCEPTION 'Unable to Continue due to Local and Remote version Conflicts.';
    return_value := -1;
    RETURN;
  END IF;
  v_instancename := coalesce((SELECT name FROM dbo.clientinstance), '');
  _rc := 1;
  SELECT r.return_value, r.clientid, r.instanceid INTO v_err, v_clientid, v_instanceid FROM dbo.sp_crs_getclientinstanceinfo(srv => v_srv, db => v_db, owner => v_owner, instancename => v_instancename, clientid => v_clientid, instanceid => v_instanceid) AS r;
  v_err := 0;
  _rc := 1;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'CRS Instance Verification: Unable to make CRS Instance Verification From CRS Server.';
    return_value := -1;
    RETURN;
  END IF;
  IF ((((v_clientid IS NULL) OR (v_clientid = 0)) OR (v_instanceid IS NULL)) OR (v_instanceid = 0)) THEN
    RAISE EXCEPTION 'CRS Instance Validation: Unable to Validate CRS Instance From CRS Server.';
    return_value := -1;
    RETURN;
  END IF;
  UPDATE dbo.clientinstance SET clientid = v_clientid, clientinstanceid = v_instanceid;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_cid := ltrim(rtrim((v_clientid)::text));
  _rc := 1;
  v_id := ltrim(rtrim((v_instanceid)::text));
  _rc := 1;
  v_query := (((((('INSERT INTO ' || v_tp) || 'CRS_DataTransferLog (ClientInstanceID, UserCode, StartDate, EndDate) VALUES (') || v_id) || ', ') || coalesce(dbo.tsql_str((v_usercode)::numeric), 'NULL')) || ', localtimestamp(3), localtimestamp(3))');
  _rc := 1;
  _dq1 := v_query;
  IF _dq1 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq1);
  END IF;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_err := 0;
  _rc := 1;
  IF (((0 <> 0) OR (v_err <> 0)) OR (_rc = 0)) THEN
    RAISE EXCEPTION 'CRS Data Transfer Error: Problem in generating data transfer log header row';
    return_value := -1;
    RETURN;
  END IF;
  v_query := ((('INSERT INTO REPORTDATA (Code1, Name1) SELECT LOGID=MAX(LogID), Name1 = ''CRS_DataTransferLog'' FROM ' || v_tp) || 'CRS_DataTransferLog WHERE ClientInstanceID = ') || v_id);
  _rc := 1;
  _dq2 := v_query;
  IF _dq2 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq2);
  END IF;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_err := 0;
  _rc := 1;
  IF (((0 <> 0) OR (v_err <> 0)) OR (_rc = 0)) THEN
    RAISE EXCEPTION 'CRS Data Transfer Error: Problem in generating data transfer log header row';
    return_value := -1;
    RETURN;
  END IF;
  v_logid := trunc(coalesce((SELECT max(code1) FROM dbo.reportdata WHERE (name1 = 'CRS_DataTransferLog')), 0))::integer;
  _rc := 1;
  v_logid_str := ltrim(rtrim((v_logid)::text));
  _rc := 1;
  IF ((v_logid <= 0) OR (v_logid IS NULL)) THEN
    RAISE EXCEPTION 'CRS Data Transfer Error: Problem in generating data transfer log header row';
    return_value := -1;
    RETURN;
  END IF;
  OPEN cur_tmpcrs1 FOR SELECT transactionname FROM dbo.crs_transactions WHERE (enable = 'Y') ORDER BY transactionname;
  FETCH NEXT FROM cur_tmpcrs1 INTO v_transactionname;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    v_query := (((((('INSERT INTO ' || v_tp) || 'CRS_DataTransferLogDetail (LogID, SourceTableName, StartDate, EndDate) VALUES (') || v_logid_str) || ', ''') || v_tablename) || ''', GETDATE(), GETDATE())');
    _rc := 1;
    _dq3 := v_query;
    IF _dq3 IS NOT NULL THEN
      EXECUTE dbo.tsql_dyn(_dq3);
    END IF;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_err := 0;
    _rc := 1;
    IF ((0 <> 0) OR (v_err <> 0)) THEN
      RAISE EXCEPTION 'CRS Data Transfer Error: Problem in generating data transfer log detail row';
      return_value := -1;
      RETURN;
    END IF;
    IF (v_transactionname = 'Stock') THEN
      SELECT r.return_value INTO v_err FROM dbo.sp_crs_push_stock(tp => v_tp, cid => v_cid, id => v_id, usercode => v_usercode) AS r;
      v_err := 0;
      _rc := 1;
      IF ((0 <> 0) OR (v_err <> 0)) THEN
        RAISE EXCEPTION 'Error While Pushing Stock To CRS Server.';
        return_value := -1;
        RETURN;
      END IF;
    END IF;
    IF (v_transactionname = 'Purchase') THEN
      SELECT r.return_value INTO v_err FROM dbo.sp_crs_push_purchase(tp => v_tp, cid => v_cid, id => v_id, usercode => v_usercode) AS r;
      v_err := 0;
      _rc := 1;
      IF ((0 <> 0) OR (v_err <> 0)) THEN
        RAISE EXCEPTION 'Error While Pushing Purchases To CRS Server.';
        return_value := -1;
        RETURN;
      END IF;
    END IF;
    IF (v_transactionname = 'P/R') THEN
      SELECT r.return_value INTO v_err FROM dbo.sp_crs_push_pr(tp => v_tp, cid => v_cid, id => v_id, usercode => v_usercode) AS r;
      v_err := 0;
      _rc := 1;
      IF ((0 <> 0) OR (v_err <> 0)) THEN
        RAISE EXCEPTION 'Error While Pushing Purchase Return To CRS Server.';
        return_value := -1;
        RETURN;
      END IF;
    END IF;
    IF (v_transactionname = 'Sales') THEN
      SELECT r.return_value INTO v_err FROM dbo.sp_crs_push_sales(tp => v_tp, cid => v_cid, id => v_id, usercode => v_usercode) AS r;
      v_err := 0;
      _rc := 1;
      IF ((0 <> 0) OR (v_err <> 0)) THEN
        RAISE EXCEPTION 'Error While Pushing Purchase Return To CRS Server.';
        return_value := -1;
        RETURN;
      END IF;
    END IF;
    IF (v_transactionname = 'S/R') THEN
      SELECT r.return_value INTO v_err FROM dbo.sp_crs_push_sr(tp => v_tp, cid => v_cid, id => v_id, usercode => v_usercode) AS r;
      v_err := 0;
      _rc := 1;
      IF ((0 <> 0) OR (v_err <> 0)) THEN
        RAISE EXCEPTION 'Error While Pushing Sales Return To CRS Server.';
        return_value := -1;
        RETURN;
      END IF;
    END IF;
    IF (v_transactionname = 'Receipt') THEN
      SELECT r.return_value INTO v_err FROM dbo.sp_crs_push_receipt(tp => v_tp, cid => v_cid, id => v_id, usercode => v_usercode) AS r;
      v_err := 0;
      _rc := 1;
      IF ((0 <> 0) OR (v_err <> 0)) THEN
        RAISE EXCEPTION 'Error While Pushing Receipt To CRS Server.';
        return_value := -1;
        RETURN;
      END IF;
    END IF;
    IF (v_transactionname = 'Issue') THEN
      SELECT r.return_value INTO v_err FROM dbo.sp_crs_push_issue(tp => v_tp, cid => v_cid, id => v_id, usercode => v_usercode) AS r;
      v_err := 0;
      _rc := 1;
      IF ((0 <> 0) OR (v_err <> 0)) THEN
        RAISE EXCEPTION 'Error While Pushing Issue To CRS Server.';
        return_value := -1;
        RETURN;
      END IF;
    END IF;
    IF (v_transactionname = 'Adjustment') THEN
      SELECT r.return_value INTO v_err FROM dbo.sp_crs_push_adjustment(tp => v_tp, cid => v_cid, id => v_id, usercode => v_usercode) AS r;
      v_err := 0;
      _rc := 1;
      IF ((0 <> 0) OR (v_err <> 0)) THEN
        RAISE EXCEPTION 'Error While Pushing Adjustments To CRS Server.';
        return_value := -1;
        RETURN;
      END IF;
    END IF;
    IF (v_transactionname = 'Due Satisfy') THEN
      SELECT r.return_value INTO v_err FROM dbo.sp_crs_push_duesatisfy(tp => v_tp, cid => v_cid, id => v_id, usercode => v_usercode) AS r;
      v_err := 0;
      _rc := 1;
      IF ((0 <> 0) OR (v_err <> 0)) THEN
        RAISE EXCEPTION 'Error While Pushing Due Satisfy To CRS Server.';
        return_value := -1;
        RETURN;
      END IF;
    END IF;
    IF (v_transactionname = 'Inter Godown Transfer') THEN
      SELECT r.return_value INTO v_err FROM dbo.sp_crs_push_transfers(tp => v_tp, cid => v_cid, id => v_id, usercode => v_usercode) AS r;
      v_err := 0;
      _rc := 1;
      IF ((0 <> 0) OR (v_err <> 0)) THEN
        RAISE EXCEPTION 'Error While Pushing Inter Godown Transfer To CRS Server.';
        return_value := -1;
        RETURN;
      END IF;
    END IF;
    IF (v_transactionname = 'A/c Transactions') THEN
      SELECT r.return_value INTO v_err FROM dbo.sp_crs_push_accvouchers(tp => v_tp, cid => v_cid, id => v_id, usercode => v_usercode) AS r;
      v_err := 0;
      _rc := 1;
      IF ((0 <> 0) OR (v_err <> 0)) THEN
        RAISE EXCEPTION 'Error While Pushing A/c Vouchers To CRS Server.';
        return_value := -1;
        RETURN;
      END IF;
    END IF;
    FETCH NEXT FROM cur_tmpcrs1 INTO v_transactionname;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_tmpcrs1;
  -- DEALLOCATE TmpCrs1
  v_query := ((('UPDATE ' || v_tp) || 'CRS_DataTransferLog SET EndDate = localtimestamp(3) WHERE LogID = ') || v_logid_str);
  _rc := 1;
  _dq4 := v_query;
  IF _dq4 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq4);
  END IF;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_err := 0;
  _rc := 1;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'CRS Data Transfer Error: Problem in marking end date for data transfer log';
    return_value := -1;
    RETURN;
  END IF;
  SELECT r.return_value, r.rs1 INTO v_err, rs1 FROM dbo.sp_crs_fetchfinalizedsaleorders(srv => v_srv, db => v_db, owner => v_owner, clientinstanceid => v_instanceid, usercode => v_usercode) AS r;
  v_err := 0;
  _rc := 1;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Unable To Fetch Sale Orders From CRS Server.';
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_CRS_Push_DueSatisfy ====
CREATE OR REPLACE FUNCTION dbo.sp_crs_push_duesatisfy(tp citext, cid citext, id citext, usercode smallint DEFAULT NULL, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_tp citext;
  v_cid citext;
  v_id citext;
  v_usercode smallint;
  v_err integer;
  v_query citext;
  _dq1 text;
  _dq2 text;
BEGIN
  v_tp := tp;
  v_cid := cid;
  v_id := id;
  v_usercode := usercode;
  DROP TABLE IF EXISTS tmp_lsl;
  CREATE TEMP TABLE tmp_lsl (
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lsl SELECT duesatisfycode FROM dbo.duesatisfyheader WHERE (crs_transfered = 'N') ORDER BY duesatisfycode DESC LIMIT 500;
  v_query := (((('INSERT INTO ' || v_tp) || 'CRS_DueSatisfyHeader (ClientInstanceID,DueSatisfyCode,SaleInvCode,DueSatisfyDate,UserCode,DueAdjCode) SELECT ') || v_id) || ',DueSatisfyCode,SaleInvCode,DueSatisfyDate,UserCode,DueAdjCode FROM DBO.DueSatisfyHeader WHERE DueSatisfyCode IN (SELECT Code FROM tmp_lsl)');
  _dq1 := v_query;
  IF _dq1 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq1);
  END IF;
  v_err := 0;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Due Satisfy Data Transfer Error: Problem in Sending Due Satisfy Data TO CRS Server';
    return_value := -1;
    RETURN;
  END IF;
  v_query := (((('INSERT INTO ' || v_tp) || 'CRS_DueSatisfyDetail (ClientInstanceID,DueSatisfyCode,ICode,GCode,Batch,Expiry,DueSatisfyQty,AvgPrice,DueSatisfyUtn,PackSalePrice,PackUnits,SaleRowId) SELECT ') || v_id) || ',DueSatisfyCode,ICode,GCode,Batch,Expiry,DueSatisfyQty,AvgPrice,DueSatisfyUtn,PackSalePrice,PackUnits,SaleRowId FROM DBO.DueSatisfyDetail WHERE DueSatisfyCode IN (SELECT Code FROM tmp_lsl)');
  _dq2 := v_query;
  IF _dq2 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq2);
  END IF;
  v_err := 0;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Adjustment Detail Data Transfer Error: Problem in Sending Adjustment Data TO CRS Server';
    return_value := -1;
    RETURN;
  END IF;
  UPDATE dbo.duesatisfyheader SET crs_transfered = 'Y', crs_transferedon = localtimestamp(3) WHERE (duesatisfycode IN (SELECT code FROM tmp_lsl AS lsl));
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_CRS_Push_Issue ====
CREATE OR REPLACE FUNCTION dbo.sp_crs_push_issue(tp citext, cid citext, id citext, usercode smallint DEFAULT NULL, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_tp citext;
  v_cid citext;
  v_id citext;
  v_usercode smallint;
  v_err integer;
  v_query citext;
  _dq1 text;
  _dq2 text;
  _dq3 text;
  _dq4 text;
BEGIN
  v_tp := tp;
  v_cid := cid;
  v_id := id;
  v_usercode := usercode;
  DROP TABLE IF EXISTS tmp_lsl;
  CREATE TEMP TABLE tmp_lsl (
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lsl SELECT issueinvcode FROM dbo.issueheader WHERE ((posted = 'Y') AND (crs_transfered = 'N')) ORDER BY issueinvcode DESC LIMIT 500;
  v_query := ((('DELETE ' || v_tp) || 'CRS_IssueCategory WHERE ClientInstanceID = ') || v_id);
  _dq1 := v_query;
  IF _dq1 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq1);
  END IF;
  v_err := 0;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Godown Data Deletion Error: Problem in Deleting Godown Data From CRS Server';
    return_value := -1;
    RETURN;
  END IF;
  v_query := (((('INSERT INTO ' || v_tp) || 'CRS_IssueCategory (ClientInstanceID, IssueCategoryCode,Name,ShortName,Description,AccountFor,Posted,Counter,Enabled) SELECT ') || v_id) || ', IssueCategoryCode,Name,ShortName,Description,AccountFor,Posted,Counter,Enabled FROM DBO.IssueCategory');
  _dq2 := v_query;
  IF _dq2 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq2);
  END IF;
  v_err := 0;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Issue Category Data Transfer Error: Problem in Sending Issue Category Data TO CRS Server';
    return_value := -1;
