-- ==== proc SP_CRS_SUBAREASALES_CROSSTAB ====
CREATE OR REPLACE FUNCTION dbo.sp_crs_subareasales_crosstab(startdate timestamp, enddate timestamp, reportgrouping citext, grouplist citext, pricetype smallint, totcol double precision, subarealist citext, onlysalearea citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_startdate timestamp(3);
  v_enddate timestamp(3);
  v_reportgrouping citext;
  v_grouplist citext;
  v_pricetype smallint;
  v_totcol double precision;
  v_subarealist citext;
  v_onlysalearea citext;
  v_upd citext;
  v_col citext;
  v_rowid integer;
  v_colname citext;
  v_colcode citext;
  v_str_col citext;
  v_totareas double precision;
  v_curriter integer;
  v_iterations integer;
  v_i integer;
  v_tot integer;
  v_icode integer;
  v_subareacode integer;
  v_qty integer;
  v_val numeric(15,5);
  v_err integer;
  _dq1 text;
  cur_c1 refcursor;
  _dq2 text;
  _fs integer := -1;
BEGIN
  v_startdate := startdate;
  v_enddate := enddate;
  v_reportgrouping := reportgrouping;
  v_grouplist := grouplist;
  v_pricetype := pricetype;
  v_totcol := totcol;
  v_subarealist := subarealist;
  v_onlysalearea := onlysalearea;
  DELETE FROM dbo.crosstab_reportdata;
  -- SET NOCOUNT ON
  DROP TABLE IF EXISTS tv_sp_crs_subareasales_crosstab_coltable;
  CREATE TEMP TABLE tv_sp_crs_subareasales_crosstab_coltable (
    code integer,
    shortname citext,
    rowid integer GENERATED BY DEFAULT AS IDENTITY
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tv_sp_crs_subareasales_crosstab_saleareastable;
  CREATE TEMP TABLE tv_sp_crs_subareasales_crosstab_saleareastable (
    code integer
) ON COMMIT DROP;
  INSERT INTO tv_sp_crs_subareasales_crosstab_saleareastable SELECT code FROM dbo.udf_stringtotabl(v_subarealist, ',') AS udf_stringtotabl;
  DROP TABLE IF EXISTS tv_sp_crs_subareasales_crosstab_tab_grouplist;
  CREATE TEMP TABLE tv_sp_crs_subareasales_crosstab_tab_grouplist (
    code integer NOT NULL
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tv_sp_crs_subareasales_crosstab_tab_itemlist;
  CREATE TEMP TABLE tv_sp_crs_subareasales_crosstab_tab_itemlist (
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tv_sp_crs_subareasales_crosstab_tab_grouplist SELECT code FROM dbo.udf_stringtotabl(v_grouplist, ',') AS udf_stringtotabl;
  INSERT INTO tv_sp_crs_subareasales_crosstab_tab_itemlist SELECT code FROM dbo.udf_selectitems(v_reportgrouping, v_grouplist) AS udf_selectitems;
  IF (v_onlysalearea = 'Y') THEN
    DELETE FROM tv_sp_crs_subareasales_crosstab_saleareastable AS saleareastable WHERE (code NOT IN (SELECT DISTINCT (customer.subareacode) FROM dbo.crs_saleledger, dbo.customer, dbo.item, dbo.crs_saledetail WHERE (((((((crs_saledetail.clientinstanceid = crs_saleledger.clientinstanceid) AND (crs_saleledger.saleinvcode = crs_saledetail.saleinvcode)) AND (crs_saleledger.posted = 'Y')) AND (crs_saleledger.date BETWEEN v_startdate AND v_enddate)) AND (crs_saleledger.custcode = customer.custcode)) AND (crs_saledetail.icode = item.icode)) AND (CASE v_reportgrouping WHEN 'M' THEN item.manfcode WHEN 'C' THEN item.icatcode WHEN 'L' THEN item.iccode ELSE item.packcode END IN (SELECT code FROM tv_sp_crs_subareasales_crosstab_tab_grouplist AS tab_grouplist))) UNION SELECT DISTINCT (customer.subareacode) FROM dbo.crs_srledger, dbo.customer, dbo.crs_srdetail, dbo.item WHERE (((((((crs_srdetail.clientinstanceid = crs_srledger.clientinstanceid) AND (crs_srledger.srinvcode = crs_srdetail.srinvcode)) AND (crs_srledger.posted = 'Y')) AND (crs_srledger.date BETWEEN v_startdate AND v_enddate)) AND (crs_srledger.custcode = customer.custcode)) AND (crs_srdetail.icode = item.icode)) AND (CASE v_reportgrouping WHEN 'M' THEN item.manfcode WHEN 'C' THEN item.icatcode WHEN 'L' THEN item.iccode ELSE item.packcode END IN (SELECT code FROM tv_sp_crs_subareasales_crosstab_tab_grouplist AS tab_grouplist)))));
  END IF;
  v_totareas := coalesce((SELECT count(code) FROM tv_sp_crs_subareasales_crosstab_saleareastable AS saleareastable), 0);
  IF ((v_totareas > 0) AND (v_totcol > 0)) THEN
    v_tot := trunc((SELECT min(a) FROM (SELECT v_totcol AS a UNION SELECT v_totareas AS a) AS t))::integer;
    INSERT INTO tv_sp_crs_subareasales_crosstab_coltable (code, shortname) SELECT s.subareacode, s.name FROM tv_sp_crs_subareasales_crosstab_saleareastable AS a, dbo.subarea AS s WHERE (a.code = s.subareacode) ORDER BY s.name;
    v_iterations := trunc(ceiling((v_totareas / v_totcol)))::integer;
    v_curriter := 1;
    v_rowid := 0;
    WHILE (v_curriter <= v_iterations) LOOP
      INSERT INTO dbo.crosstab_reportdata (code1, code2, code3) SELECT code, v_curriter, NULL::integer FROM tv_sp_crs_subareasales_crosstab_tab_itemlist AS tab_itemlist;
      v_i := 1;
      WHILE (v_i <= v_tot) LOOP
        v_rowid := (v_rowid + 1);
        v_colname := rtrim(ltrim(coalesce((SELECT shortname FROM tv_sp_crs_subareasales_crosstab_coltable AS coltable WHERE (rowid = v_rowid)), '')));
        v_colcode := rtrim(ltrim(dbo.tsql_str(((SELECT code FROM tv_sp_crs_subareasales_crosstab_coltable AS coltable WHERE (rowid = v_rowid)))::numeric, 7)));
        IF (v_colcode IS NULL) THEN
          EXIT;
        ELSE
          v_str_col := ltrim(rtrim(dbo.tsql_str((v_i)::numeric, 7)));
          v_upd := ((((((((('UPDATE CrossTab_ReportData SET C_Name' || v_str_col) || ' = ''') || v_colname) || ''', C_Code') || v_str_col) || ' = ') || v_colcode) || ' WHERE CODE2 = ') || ltrim(rtrim(dbo.tsql_str((v_curriter)::numeric, 7))));
          _dq1 := v_upd;
          IF _dq1 IS NOT NULL THEN
            EXECUTE dbo.tsql_dyn(_dq1);
          END IF;
          v_err := 0;
          IF (v_err <> 0) THEN
            v_upd := ('UPDATION ERROR, DETAILS: ' || v_upd);
            RAISE EXCEPTION '%', v_upd;
            return_value := -1;
            RETURN;
          END IF;
          v_i := (v_i + 1);
        END IF;
      END LOOP;
      v_curriter := (v_curriter + 1);
    END LOOP;
    OPEN cur_c1 FOR SELECT s.icode, coalesce(sum(s.qty), 0) AS qty, round((sum(CASE v_pricetype WHEN 1 THEN s.netamt WHEN 2 THEN (s.qty * round(((i.saleprice / CASE i.packunits WHEN 0 THEN 1 ELSE i.packunits END))::numeric, 2)) WHEN 3 THEN (s.qty * round(((i.purprice / CASE i.packunits WHEN 0 THEN 1 ELSE i.packunits END))::numeric, 2)) ELSE (s.qty * round((i.avgprice)::numeric, 2)) END))::numeric, 0) AS val, s.subareacode FROM (SELECT sd.icode, c.subareacode, sl.custcode AS custcode, coalesce(sum((sd.looseqty + sd.bonusqty)), 0) AS qty, round((coalesce(sum(((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc)))) * ((1 - ((.01 * sd.discperc))))) * ((1 - ((.01 * sl.discperc)))))), 0))::numeric, 2) AS netamt FROM dbo.crs_saleledger AS sl, dbo.crs_saledetail AS sd, dbo.customer AS c WHERE ((((((sl.saleinvcode = sd.saleinvcode) AND (sd.clientinstanceid = sl.clientinstanceid)) AND (sl.posted = 'Y')) AND (c.subareacode IN (SELECT code FROM tv_sp_crs_subareasales_crosstab_saleareastable AS saleareastable))) AND (c.custcode = sl.custcode)) AND (sl.date BETWEEN v_startdate AND v_enddate)) GROUP BY sd.icode, sl.custcode, c.subareacode UNION ALL SELECT sd.icode, c.subareacode, sl.custcode AS custcode, (-coalesce(sum((sd.looseqty + sd.bonusqty)), 0)) AS qty, (-round((coalesce(sum(((((sd.looseqty * sd.srprice)) * ((1 - ((.01 * sd.discperc))))) * ((1 - ((.01 * sl.discperc)))))), 0))::numeric, 2)) AS netamt FROM dbo.crs_srledger AS sl, dbo.crs_srdetail AS sd, dbo.customer AS c WHERE ((((((sd.clientinstanceid = sl.clientinstanceid) AND (sl.srinvcode = sd.srinvcode)) AND (c.subareacode IN (SELECT code FROM tv_sp_crs_subareasales_crosstab_saleareastable AS saleareastable))) AND (c.custcode = sl.custcode)) AND (sl.posted = 'Y')) AND (sl.date BETWEEN v_startdate AND v_enddate)) GROUP BY sd.icode, sl.custcode, c.subareacode) AS s, dbo.item AS i WHERE ((i.icode = s.icode) AND (i.icode IN (SELECT code FROM tv_sp_crs_subareasales_crosstab_tab_itemlist AS tab_itemlist))) GROUP BY s.subareacode, s.icode ORDER BY s.subareacode, s.icode;
    FETCH NEXT FROM cur_c1 INTO v_icode, v_qty, v_val, v_subareacode;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    WHILE (_fs = 0) LOOP
      v_i := 1;
      WHILE (v_i <= v_tot) LOOP
        v_colcode := ltrim(rtrim(dbo.tsql_str((v_icode)::numeric, 7)));
        v_colname := ltrim(rtrim(dbo.tsql_str((v_subareacode)::numeric, 7)));
        v_str_col := ltrim(rtrim(dbo.tsql_str((v_i)::numeric, 7)));
        v_upd := ((((((((((((((((((('UPDATE CrossTab_ReportData SET ' || 'QTY') || v_str_col) || ' = ') || ltrim(rtrim(dbo.tsql_str((v_qty)::numeric, 7)))) || ', VAL') || v_str_col) || ' = ') || ltrim(rtrim(dbo.tsql_str((v_val)::numeric, 15, 5)))) || ', C_Code') || v_str_col) || ' = ') || v_colname) || ' WHERE CODE1 = ') || v_colcode) || ' AND ') || ' C_Code') || v_str_col) || ' = ') || v_colname);
        _dq2 := v_upd;
        IF _dq2 IS NOT NULL THEN
          EXECUTE dbo.tsql_dyn(_dq2);
        END IF;
        v_err := 0;
        IF (v_err <> 0) THEN
          v_upd := ('CROSSTAB PLOTING ERROR, DETAILS: ' || v_upd);
          RAISE EXCEPTION '%', v_upd;
          CLOSE cur_c1;
          -- DEALLOCATE C1
          return_value := -1;
          RETURN;
        END IF;
        v_i := (v_i + 1);
      END LOOP;
      FETCH NEXT FROM cur_c1 INTO v_icode, v_qty, v_val, v_subareacode;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    END LOOP;
    CLOSE cur_c1;
    -- DEALLOCATE C1
    UPDATE dbo.crosstab_reportdata AS c SET name1 = i.name, name2 = i.customicode, name3 = i.packingdesc, name4 = NULL::citext, code5 = CASE v_reportgrouping WHEN 'M' THEN i.manfcode WHEN 'C' THEN i.icatcode WHEN 'L' THEN i.iccode ELSE i.packcode END, name5 = CASE v_reportgrouping WHEN 'M' THEN (SELECT m.name FROM dbo.manufacturer AS m WHERE (m.manfcode = i.manfcode)) WHEN 'C' THEN (SELECT c.name FROM dbo.itemcategory AS c WHERE (c.icatcode = i.icatcode)) WHEN 'L' THEN (SELECT c.name FROM dbo.itemclass AS c WHERE (c.iccode = i.iccode)) ELSE (SELECT p.name FROM dbo.itempacking AS p WHERE (p.packcode = i.packcode)) END, value1 = CASE v_pricetype WHEN 1 THEN round(((i.saleprice / CASE i.packunits WHEN 0 THEN 1 ELSE i.packunits END))::numeric, 2) WHEN 2 THEN round(((i.saleprice / CASE i.packunits WHEN 0 THEN 1 ELSE i.packunits END))::numeric, 2) WHEN 3 THEN round(((i.purprice / CASE i.packunits WHEN 0 THEN 1 ELSE i.packunits END))::numeric, 2) ELSE round((i.avgprice)::numeric, 2) END FROM dbo.item AS i WHERE (i.icode = c.code1);
    PERFORM dbo.sp_update_total_crosstab_reportdata();
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_CRS_TransferClientTable ====
CREATE OR REPLACE FUNCTION dbo.sp_crs_transferclienttable(srv citext, db citext, owner citext, clientid smallint, instanceid smallint, sourcetablename citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_clientid smallint;
  v_instanceid smallint;
  v_sourcetablename citext;
  v_transfertype citext;
  v_crs_tablename citext;
  v_full_crs_table_name citext;
  v_whr citext;
  v_full_table_name citext;
  v_from citext;
  v_pkcond citext;
  v_notin citext;
  v_endd citext;
  v_maxcol citext;
  v_str_clientid citext;
  v_str_instanceid citext;
  v_tabmaxsql citext;
  v_sql citext;
  v_list citext;
  v_srclist citext;
  v_autoinsert citext;
  v_autoupdate citext;
  v_autodelete citext;
  v_table_id integer;
  v_source_table_id integer;
  v_err integer;
  v_flag smallint;
  v_priority integer;
  v_position smallint;
  v_colname citext;
  v_tblprfix citext;
  v_del citext;
  v_del_qry citext;
  v_ins citext;
  v_ins_qry citext;
  v_pkcond_src citext;
  v_upd citext;
  v_setpart citext;
  v_upd_pkcond citext;
  v_upd_qry citext;
  _r1 record;
  _dq2 text;
  cur_tmpcrs3 refcursor;
  _dq3 text;
  _dq4 text;
  _rc integer;
  _fs integer := -1;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  v_clientid := clientid;
  v_instanceid := instanceid;
  v_sourcetablename := sourcetablename;
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  -- SET NOCOUNT ON
  v_tblprfix := '';
  _rc := 1;
  IF (((length(rtrim(ltrim(rtrim(v_srv)))) = 0) OR (v_srv IS NULL))) THEN
    v_tblprfix := '';
    _rc := 1;
  ELSE
    v_tblprfix := (v_srv || '.');
    _rc := 1;
  END IF;
  IF (((length(rtrim(ltrim(rtrim(v_db)))) = 0) OR (v_db IS NULL))) THEN
    v_tblprfix := v_tblprfix;
    _rc := 1;
  ELSE
    v_tblprfix := ((v_tblprfix || v_db) || '.');
    _rc := 1;
  END IF;
  IF (((length(rtrim(ltrim(rtrim(v_owner)))) = 0) OR (v_owner IS NULL))) THEN
    v_tblprfix := ((v_tblprfix || 'DBO') || '.');
    _rc := 1;
  ELSE
    v_tblprfix := ((v_tblprfix || v_owner) || '.');
    _rc := 1;
  END IF;
  v_from := (' FROM ' || v_tblprfix);
  _rc := 1;
  v_notin := ' NOT IN (SELECT ';
  _rc := 1;
  v_sql := 'SELECT ';
  _rc := 1;
  v_whr := ' WHERE ';
  _rc := 1;
  v_endd := ' AS C WHERE ';
  _rc := 1;
  v_del := 'DELETE ';
  _rc := 1;
  v_upd := 'UPDATE S ';
  _rc := 1;
  v_setpart := ' SET ';
  _rc := 1;
  v_ins := 'INSERT INTO ';
  _rc := 1;
  _rc := 0;
  FOR _r1 IN SELECT transfertype AS c1, ltrim(rtrim(crs_tablename)) AS c2, priority AS c3, autoinsert AS c4, autoupdate AS c5, autodelete AS c6 FROM dbo.crs_transferabledata WHERE ((enable = 'Y') AND (sourcetablename = v_sourcetablename)) LOOP
    _rc := _rc + 1;
    v_transfertype := _r1.c1;
    v_crs_tablename := _r1.c2;
    v_priority := _r1.c3;
    v_autoinsert := _r1.c4;
    v_autoupdate := _r1.c5;
    v_autodelete := _r1.c6;
  END LOOP;
  IF ((_rc = 0) AND (v_crs_tablename IS NULL)) THEN
    RAISE EXCEPTION 'CRS Data Transfer: Unable to find data tranfer specification for an Object: Name = %', v_sourcetablename;
    return_value := -1;
    RETURN;
  ELSE
    v_full_table_name := ('DBO.' || v_sourcetablename);
    _rc := 1;
    v_full_crs_table_name := ((ltrim(rtrim(v_owner)) || '.') || v_crs_tablename);
    _rc := 1;
    -- SET @table_id = OBJECT_ID(@full_crs_table_name)
    RAISE EXCEPTION 'untranslated T-SQL (OBJECT_ID of non-literal)' USING ERRCODE = '0A000';
    -- SET @source_table_id = OBJECT_ID(@full_table_name)
    RAISE EXCEPTION 'untranslated T-SQL (OBJECT_ID of non-literal)' USING ERRCODE = '0A000';
    v_err := 0;
    _rc := 1;
    IF ((((0 <> 0) OR (v_err <> 0)) OR (v_table_id IS NULL)) OR (v_source_table_id IS NULL)) THEN
      RAISE EXCEPTION 'CRS Data Transfer: Invalid Object Refered: Name = %', v_full_table_name;
      return_value := -1;
      RETURN;
    END IF;
    v_pkcond := '';
    _rc := 1;
    v_maxcol := '';
    _rc := 1;
    v_upd_pkcond := '';
    _rc := 1;
    SELECT r.return_value, r.pkcond, r.upd_pkcond, r.maxcol INTO v_err, v_pkcond, v_upd_pkcond, v_maxcol FROM dbo.sp_crs_gettablekey(table_id => v_table_id, tablename => v_crs_tablename, fulltablename => v_full_crs_table_name, pkcond => v_pkcond, upd_pkcond => v_upd_pkcond, maxcol => v_maxcol) AS r;
    v_err := 0;
    _rc := 1;
    IF (v_err <> 0) THEN
      RAISE EXCEPTION 'CRS Data Transfer: Error Transfering % Data', v_full_table_name;
      return_value := -1;
      RETURN;
    END IF;
    v_str_clientid := ltrim(rtrim((v_clientid)::text));
    _rc := 1;
    v_str_instanceid := ltrim(rtrim((v_instanceid)::text));
    _rc := 1;
    IF (v_autodelete = 'Y') THEN
      IF (v_transfertype = 'B') THEN
        v_del_qry := (((((((v_del || v_tblprfix) || v_crs_tablename) || ' ') || v_whr) || ' ') || 'ClientID = ') || v_str_clientid);
        _rc := 1;
      ELSE
        v_del_qry := (((((((v_del || v_tblprfix) || v_crs_tablename) || ' ') || v_whr) || ' ') || 'ClientInstanceID = ') || v_str_instanceid);
        _rc := 1;
      END IF;
      _dq2 := v_del_qry;
      IF _dq2 IS NOT NULL THEN
        EXECUTE dbo.tsql_dyn(_dq2);
      END IF;
      GET DIAGNOSTICS _rc = ROW_COUNT;
      v_err := 0;
      _rc := 1;
      IF (v_err <> 0) THEN
        RAISE EXCEPTION 'CRS Data Deletion: Error Transfering % Data', v_full_table_name;
        return_value := -1;
        RETURN;
      END IF;
    END IF;
    IF (v_autoupdate = 'Y') THEN
      v_flag := 0;
      _rc := 1;
      v_setpart := ' SET ';
      _rc := 1;
      -- OPEN TmpCrs3
      RAISE EXCEPTION 'untranslated T-SQL (system table sysobjects)' USING ERRCODE = '0A000';
      FETCH NEXT FROM cur_tmpcrs3 INTO v_colname, v_position;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
      WHILE (_fs = 0) LOOP
        -- IF ColumnProperty (@table_id, @ColName, 'IsIdentity') <> 1
        -- 			BEGIN
        -- --				IF @ColName = (SELECT columnname FROM TransferableData_RestrictedColumns WHERE columnname = @ColName and tablename = @CRS_TableName)
        -- --				BEGIN
        -- --					SET @ColName = @ColName
        -- --				END
        -- --				ELSE
        -- --				BEGIN
        -- 					IF @SETPART <> ' SET ' AND RIGHT(@SETPART, 1) <> ','
        -- 					BEGIN
        -- 						SET @SETPART = @SETPART + ','
        -- 					END
        -- 
        -- 					IF @TransferType = 'B' AND @Position = 1
        -- 					BEGIN
        -- 						SET @SETPART = @SETPART + 'S.ClientID = ' + @Str_ClientID + ','
        -- 						SET @flag = 1
        -- 					END
        -- 					ELSE
        -- 					BEGIN
        -- 						IF @TransferType = 'T' AND @Position = 1
        -- 						BEGIN
        -- 							SET @SETPART = @SETPART + 'S.ClientInstanceID=' + @Str_InstanceID + ','
        -- 							SET @flag = 1
        -- 						END
        -- 						ELSE
        -- 							SET @flag = 0
        -- 					END
        -- 
        -- 					IF @flag = 0
        -- 						SET @SETPART = @SETPART + ' S.' + LTRIM(RTRIM(@ColName)) + '=' + 'C.' +  LTRIM(RTRIM(@ColName))
        -- --				END
        -- 			END
        RAISE EXCEPTION 'untranslated T-SQL (function ColumnProperty)' USING ERRCODE = '0A000';
        FETCH NEXT FROM cur_tmpcrs3 INTO v_colname, v_position;
        IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
      END LOOP;
      CLOSE cur_tmpcrs3;
      -- DEALLOCATE TmpCrs3
      IF (v_setpart <> ' SET ') THEN
        IF (v_transfertype = 'B') THEN
          v_upd_qry := (((((((((((v_upd || v_setpart) || ' ') || v_from) || v_crs_tablename) || ' AS S, ') || v_sourcetablename) || v_endd) || ' S.ClientID=') || v_str_clientid) || ' AND ') || v_upd_pkcond);
          _rc := 1;
        ELSE
          IF ((upper(v_crs_tablename))::citext <> 'CRS_GodownDetail') THEN
            v_upd_qry := ((((((((((((v_upd || v_setpart) || ' ') || v_from) || v_crs_tablename) || ' AS S, ') || v_sourcetablename) || v_endd) || ' S.ClientInstanceID=') || v_str_instanceid) || ' AND ') || v_upd_pkcond) || ' AND C.Posted = ''Y'' AND C.CRS_Transfered = ''N''');
            _rc := 1;
          END IF;
        END IF;
        _dq3 := v_upd_qry;
        IF _dq3 IS NOT NULL THEN
          EXECUTE dbo.tsql_dyn(_dq3);
        END IF;
        GET DIAGNOSTICS _rc = ROW_COUNT;
        v_err := 0;
        _rc := 1;
        IF ((0 <> 0) OR (v_err <> 0)) THEN
          RAISE EXCEPTION 'CRS Data Updation: Error Transfering % Data', v_full_table_name;
          return_value := -1;
          RETURN;
        END IF;
      END IF;
    END IF;
    IF (v_autoinsert = 'Y') THEN
      v_sql := ' SELECT ';
      _rc := 1;
      v_list := '';
      _rc := 1;
      SELECT r.return_value, r.list INTO v_err, v_list FROM dbo.sp_columnlist(owner => v_owner, "table" => v_crs_tablename, list => v_list) AS r;
      v_err := 0;
      _rc := 1;
      IF ((0 <> 0) OR (v_err <> 0)) THEN
        return_value := -1;
        RETURN;
      END IF;
      v_pkcond_src := substring(v_pkcond, (coalesce(dbo.tsql_charindex(('+')::citext, (v_pkcond)::citext, 1), 0) + 1), length(rtrim(v_pkcond)));
      _rc := 1;
      IF (v_transfertype = 'B') THEN
        v_srclist := substring(v_list, 10, length(rtrim(v_list)));
        _rc := 1;
        v_ins_qry := (((((((((((((((((((((v_ins || v_tblprfix) || v_crs_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_str_clientid) || ' AS CID, ') || v_srclist) || ' FROM ') || v_sourcetablename) || v_endd) || v_pkcond_src) || v_notin) || v_pkcond_src) || ' FROM ') || v_tblprfix) || v_crs_tablename) || ' WHERE ClientID = ') || v_str_clientid) || ')');
        _rc := 1;
      ELSE
        v_srclist := substring(v_list, 18, length(rtrim(v_list)));
        _rc := 1;
        IF ((upper(v_crs_tablename))::citext = 'CRS_PURDETAIL') THEN
          v_ins_qry := (((((((((((((((((((v_ins || v_tblprfix) || v_crs_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_str_instanceid) || ' AS CID, ') || v_srclist) || ' FROM ') || v_sourcetablename) || v_endd) || ' C.PurInvCode IN (SELECT M.PurInvCode FROM Purledger M WHERE M.Posted=''Y'' AND M.CRS_Transfered=''N'' AND M.PurInvCode NOT IN (SELECT PurInvCode FROM ') || v_tblprfix) || v_crs_tablename) || v_whr) || ' ClientInstanceID = ') || v_str_instanceid) || '))');
          _rc := 1;
        ELSE
          IF ((upper(v_crs_tablename))::citext = 'CRS_PRDETAIL') THEN
            v_ins_qry := (((((((((((((((((((v_ins || v_tblprfix) || v_crs_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_str_instanceid) || ' AS CID, ') || v_srclist) || ' FROM ') || v_sourcetablename) || v_endd) || ' C.PrInvCode IN (SELECT M.PrInvCode FROM Prledger M WHERE M.Posted=''Y'' AND M.CRS_Transfered=''N'' AND M.PrInvCode NOT IN (SELECT PrInvCode FROM ') || v_tblprfix) || v_crs_tablename) || v_whr) || ' ClientInstanceID = ') || v_str_instanceid) || '))');
            _rc := 1;
          ELSE
            IF ((upper(v_crs_tablename))::citext = 'CRS_SALEDETAIL') THEN
              v_ins_qry := (((((((((((((((((((v_ins || v_tblprfix) || v_crs_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_str_instanceid) || ' AS CID, ') || v_srclist) || ' FROM ') || v_sourcetablename) || v_endd) || ' C.SaleInvCode IN (SELECT M.SaleInvCode FROM Saleledger M WHERE M.Posted=''Y'' AND M.CRS_Transfered=''N'' AND M.SaleInvCode NOT IN (SELECT SaleInvCode FROM ') || v_tblprfix) || v_crs_tablename) || v_whr) || ' ClientInstanceID = ') || v_str_instanceid) || '))');
              _rc := 1;
            ELSE
              IF ((upper(v_crs_tablename))::citext = 'CRS_SRDETAIL') THEN
                v_ins_qry := (((((((((((((((((((v_ins || v_tblprfix) || v_crs_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_str_instanceid) || ' AS CID, ') || v_srclist) || ' FROM ') || v_sourcetablename) || v_endd) || ' C.SRInvCode IN (SELECT M.SRInvCode FROM SRledger M WHERE M.Posted=''Y'' AND M.CRS_Transfered=''N'' AND M.SRInvCode NOT IN (SELECT SRInvCode FROM ') || v_tblprfix) || v_crs_tablename) || v_whr) || ' ClientInstanceID = ') || v_str_instanceid) || '))');
                _rc := 1;
              ELSE
                IF ((upper(v_crs_tablename))::citext = 'CRS_RECEIPTDETAIL') THEN
                  v_ins_qry := (((((((((((((((((((v_ins || v_tblprfix) || v_crs_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_str_instanceid) || ' AS CID, ') || v_srclist) || ' FROM ') || v_sourcetablename) || v_endd) || ' C.ReceiptInvCode IN (SELECT M.ReceiptInvCode FROM ReceiptHeader M WHERE M.Posted=''Y'' AND M.CRS_Transfered=''N'' AND M.ReceiptInvCode NOT IN (SELECT ReceiptInvCode FROM ') || v_tblprfix) || v_crs_tablename) || v_whr) || ' ClientInstanceID = ') || v_str_instanceid) || '))');
                  _rc := 1;
                ELSE
                  IF ((upper(v_crs_tablename))::citext = 'CRS_ISSUEDETAIL') THEN
                    v_ins_qry := (((((((((((((((((((v_ins || v_tblprfix) || v_crs_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_str_instanceid) || ' AS CID, ') || v_srclist) || ' FROM ') || v_sourcetablename) || v_endd) || ' C.IssueInvCode IN (SELECT M.IssueInvCode FROM IssueHeader M WHERE M.Posted=''Y'' AND M.CRS_Transfered=''N'' AND M.IssueInvCode NOT IN (SELECT IssueInvCode FROM ') || v_tblprfix) || v_crs_tablename) || v_whr) || ' ClientInstanceID = ') || v_str_instanceid) || '))');
                    _rc := 1;
                  ELSE
                    IF ((upper(v_crs_tablename))::citext = 'CRS_ADJDETAIL') THEN
                      v_ins_qry := (((((((((((((((((((v_ins || v_tblprfix) || v_crs_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_str_instanceid) || ' AS CID, ') || v_srclist) || ' FROM ') || v_sourcetablename) || v_endd) || ' C.AdjCode IN (SELECT M.AdjCode FROM AdjHeader M WHERE M.Posted=''Y'' AND M.CRS_Transfered=''N'' AND M.AdjCode NOT IN (SELECT AdjCode FROM ') || v_tblprfix) || v_crs_tablename) || v_whr) || ' ClientInstanceID = ') || v_str_instanceid) || '))');
                      _rc := 1;
                    ELSE
                      IF ((upper(v_crs_tablename))::citext = 'CRS_TDETAIL') THEN
                        v_ins_qry := (((((((((((((((((((v_ins || v_tblprfix) || v_crs_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_str_instanceid) || ' AS CID, ') || v_srclist) || ' FROM ') || v_sourcetablename) || v_endd) || ' C.TransCode IN (SELECT M.TransCode FROM THeader M WHERE M.Posted=''Y'' AND M.CRS_Transfered=''N'' AND M.TransCode NOT IN (SELECT TransCode FROM ') || v_tblprfix) || v_crs_tablename) || v_whr) || ' ClientInstanceID = ') || v_str_instanceid) || '))');
                        _rc := 1;
                      ELSE
                        IF ((upper(v_crs_tablename))::citext = 'CRS_DUESATISFYDETAIL') THEN
                          v_ins_qry := (((((((((((((((((((v_ins || v_tblprfix) || v_crs_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_str_instanceid) || ' AS CID, ') || v_srclist) || ' FROM ') || v_sourcetablename) || v_endd) || ' C.DueSatisfyCode IN (SELECT M.DueSatisfyCode FROM DueSatisfyHeader M WHERE M.CRS_Transfered=''N'' AND M.DueSatisfyCode NOT IN (SELECT DueSatisfyCode FROM ') || v_tblprfix) || v_crs_tablename) || v_whr) || ' ClientInstanceID = ') || v_str_instanceid) || '))');
                          _rc := 1;
                        ELSE
                          IF ((upper(v_crs_tablename))::citext = 'CRS_DUESATISFYHEADER') THEN
                            v_ins_qry := (((((((((((((v_ins || v_tblprfix) || v_crs_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_str_instanceid) || ' AS CID, ') || v_srclist) || ' FROM ') || v_sourcetablename) || v_endd) || ' C.CRS_Transfered=''N''');
                            _rc := 1;
                          ELSE
                            IF ((upper(v_crs_tablename))::citext = 'CRS_GODOWNDETAIL') THEN
                              v_ins_qry := ((((((((((((v_ins || v_tblprfix) || v_crs_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_str_instanceid) || ' AS CID, ') || v_srclist) || ' FROM ') || v_sourcetablename) || ' AS C ');
                              _rc := 1;
                            ELSE
                              v_ins_qry := (((((((((((((((((((((((v_ins || v_tblprfix) || v_crs_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_str_instanceid) || ' AS CID, ') || v_srclist) || ' FROM ') || v_sourcetablename) || v_endd) || ' C.Posted=''Y'' AND C.CRS_Transfered = ''N'' AND ') || v_pkcond_src) || ' NOT IN (SELECT ') || v_pkcond_src) || ' FROM ') || v_tblprfix) || v_crs_tablename) || v_whr) || ' ClientInstanceID = ') || v_str_instanceid) || ')');
                              _rc := 1;
                            END IF;
                          END IF;
                        END IF;
                      END IF;
                    END IF;
                  END IF;
                END IF;
              END IF;
            END IF;
          END IF;
        END IF;
      END IF;
      _dq4 := v_ins_qry;
      IF _dq4 IS NOT NULL THEN
        EXECUTE dbo.tsql_dyn(_dq4);
      END IF;
      GET DIAGNOSTICS _rc = ROW_COUNT;
      v_err := 0;
      _rc := 1;
      IF ((0 <> 0) OR (v_err <> 0)) THEN
        RAISE EXCEPTION 'Data Insertion: Error Transfering % Data', v_full_crs_table_name;
        return_value := -1;
        RETURN;
      END IF;
    END IF;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

