-- ==== proc SP_CRS_VirtualGL_PurchaseReturn ====
CREATE OR REPLACE FUNCTION dbo.sp_crs_virtualgl_purchasereturn(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ln_purchaseacc numeric(5,0);
  v_ln_cashacc numeric(5,0);
  v_ln_equityacc numeric(5,0);
  v_ln_invacc numeric(5,0);
  v_ln_salesacc numeric(5,0);
  v_ln_salesretacc numeric(5,0);
  v_ln_purchaseretacc numeric(5,0);
  v_ln_revfromservice numeric(5,0);
  v_ln_salestaxacc numeric(5,0);
  v_prremks citext;
  v_invsys citext;
  v_roundupto smallint;
BEGIN
  -- SET NOCOUNT ON
  v_roundupto := (SELECT dbo.fn_get_int_preference('roundpurinvon') AS a);
  v_invsys := coalesce((SELECT dbo.fn_getpreference('InventorySystemUsed') AS a), 'P');
  v_ln_invacc := (SELECT code FROM dbo.global WHERE (name = 'GT_InventoryAcc'));
  v_ln_purchaseacc := (SELECT code FROM dbo.global WHERE (name = 'GT_PurchaseAccount'));
  v_ln_cashacc := (SELECT code FROM dbo.global WHERE (name = 'GT_CashACC'));
  v_ln_equityacc := (SELECT code FROM dbo.global WHERE (name = 'GT_EquityACC'));
  v_ln_purchaseretacc := (SELECT code FROM dbo.global WHERE (name = 'GT_PurchaseReturnsAccount'));
  v_ln_salestaxacc := (SELECT code FROM dbo.global WHERE (name = 'GT_AdvanceSalesTaxACC'));
  v_prremks := (SELECT dbo.fn_getpreference('ShowPRetRemarksInLedger') AS a);
  DROP TABLE IF EXISTS tmp_lt_pret;
  CREATE TEMP TABLE tmp_lt_pret (
    clientinstanceid smallint NOT NULL,
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_pret SELECT p.clientinstanceid, p.prinvcode FROM dbo.crs_prledger AS p WHERE (((p.posted = 'Y') AND (p.accountfor = 'Y')) AND (NOT EXISTS (SELECT DISTINCT v.clientinstanceid, v.documentcode FROM dbo.crs_virtualgl AS v WHERE ((v.documenttype IN ('PR')) AND (v.documentcode = p.prinvcode)))));
  INSERT INTO dbo.crs_virtualgltemp SELECT p.clientinstanceid, p.prinvcode AS documentcode, 'PR' AS documenttype, p.prcatcode AS catcode, trunc(CASE p.prcatcode WHEN 6 THEN v_ln_equityacc ELSE CASE WHEN (p.custcode > 0) THEN p.custcode ELSE p.suppcode END END)::smallint AS dr_acccode, trunc(CASE WHEN (v_invsys = 'P') THEN v_ln_purchaseretacc ELSE v_ln_invacc END)::smallint AS cr_acccode, NULL::smallint AS alternateacccode, p.date AS date, CASE p.updateavgpricewithnetrate WHEN 'N' THEN round((((sum((((d.looseqty + d.bonusqty)) * d.unitsalestax)) + sum(round((((((d.looseqty * d.prprice) * ((1 - ((.01 * d.discperc))))) * d.gstperc) * .01))::numeric, 2))) + round((((((sum((((d.looseqty * d.prprice)) * ((1 - ((.01 * d.discperc)))))) * ((1 - ((.01 * p.discperc))))) - p.flatdisc)) * ((p.invgstperc1 * .01))))::numeric, 2)))::numeric, v_roundupto) ELSE 0.00 END AS saletax, CASE p.updateavgpricewithnetrate WHEN 'N' THEN round((((((sum((((d.looseqty * d.prprice)) * ((1 - ((.01 * d.discperc)))))) * ((1 - ((.01 * p.discperc))))) + p.misccharges) + p.salestax) - p.flatdisc))::numeric, v_roundupto) ELSE (round((((((sum((((d.looseqty * d.prprice)) * ((1 - ((.01 * d.discperc)))))) * ((1 - ((.01 * p.discperc))))) + p.misccharges) + p.salestax) - p.flatdisc))::numeric, v_roundupto) + round((((sum((((d.looseqty + d.bonusqty)) * d.unitsalestax)) + sum(round((((((d.looseqty * d.prprice) * ((1 - ((.01 * d.discperc))))) * d.gstperc) * .01))::numeric, 2))) + round((((((sum((((d.looseqty * d.prprice)) * ((1 - ((.01 * d.discperc)))))) * ((1 - ((.01 * p.discperc))))) - p.flatdisc)) * ((p.invgstperc1 * .01))))::numeric, 2)))::numeric, v_roundupto)) END AS gross, CASE v_prremks WHEN 'Y' THEN p.remarks ELSE ((CASE p.prcatcode WHEN 6 THEN 'Open' ELSE 'Receivable on ' END || ' pur. return #: ') || rtrim(ltrim((p.prinvcode)::text))) END AS dr_remarks, ((('Stock returned on ' || CASE p.prcatcode WHEN 6 THEN 'open' ELSE '' END) || ' pur. return #: ') || rtrim(ltrim((p.prinvcode)::text))) AS cr_remarks, ((('S.Tax receivable on ' || CASE p.prcatcode WHEN 6 THEN 'open' ELSE ':' END) || ' pur. return #: ') || rtrim(ltrim((p.prinvcode)::text))) AS saletax_remarks, NULL::citext AS checkno, p.salesmancode AS usercode, p.prinvcode AS vouchercode, p.prinvcode AS invoicecode, 4 AS invoicetype, p.amt AS amt, p.paymentacccode AS dramtacccode, p.suppcode AS cramtacccode, p.amtby AS amtby, p.amtdate AS amtdate, p.amtreference AS amtref, p.outstandingamt AS outstandingamt, 0 AS balance, NULL::integer AS patientcode, NULL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto, NULL::integer AS guestcode, NULL::integer AS studentcode, 0 AS cgs, NULL::smallint AS currencycode, NULL::numeric(11,5) AS conversionrate, 0.00 AS advincometax, 0.0 AS fbrposfee FROM dbo.crs_prledger AS p, dbo.crs_prdetail AS d WHERE (((((dbo.tsql_str((p.clientinstanceid)::numeric, 10) || dbo.tsql_str((p.purinvcode)::numeric, 10)))::citext IN (SELECT (dbo.tsql_str((lt_pret.clientinstanceid)::numeric, 10) || dbo.tsql_str((lt_pret.code)::numeric, 10)) FROM tmp_lt_pret AS lt_pret)) AND (p.clientinstanceid = d.clientinstanceid)) AND (p.prinvcode = d.prinvcode)) GROUP BY p.clientinstanceid, p.prinvcode, p.suppcode, p.custcode, p.prcatcode, p.date, p.discperc, p.misccharges, p.salestax, p.flatdisc, p.invgstperc1, p.salesmancode, p.amt, p.paymentacccode, p.amtby, p.amtdate, p.amtreference, p.outstandingamt, p.remarks, p.updateavgpricewithnetrate;
  TRUNCATE TABLE tmp_lt_pret RESTART IDENTITY;
  return_value := 0;
  RETURN;
END
$body$;

