  v_ln_purchaseretacc numeric(5,0);
  v_ln_revfromservice numeric(5,0);
  v_ln_salestaxacc numeric(5,0);
  v_ln_advincometaxsale numeric(5,0);
  v_ln_fbrposfeeacc numeric(5,0);
  v_sremks citext;
  v_invsys citext;
  v_roundupyo smallint;
  v_advincometax citext;
BEGIN
  -- SET NOCOUNT ON
  v_advincometax := coalesce((SELECT dbo.fn_getpreference('ApplyAdvanceIncomeTaxInSale') AS a), 'N');
  v_roundupyo := (SELECT dbo.fn_get_int_preference('roundsaleinvon') AS a);
  v_invsys := coalesce((SELECT dbo.fn_getpreference('InventorySystemUsed') AS a), 'P');
  v_ln_invacc := (SELECT code FROM dbo.global WHERE (name = 'GT_InventoryAcc'));
  v_ln_cgs := (SELECT code FROM dbo.global WHERE (name = 'GT_CostOfGoodsSoldAcc'));
  v_ln_cashacc := (SELECT code FROM dbo.global WHERE (name = 'GT_CashACC'));
  v_ln_salesacc := (SELECT code FROM dbo.global WHERE (name = 'GT_SalesACC'));
  v_ln_salesretacc := (SELECT code FROM dbo.global WHERE (name = 'GT_SalesReturnACC'));
  v_ln_salestaxacc := (SELECT code FROM dbo.global WHERE (name = 'GT_AdvanceSalesTaxACC'));
  v_ln_advincometaxsale := (SELECT code FROM dbo.global WHERE (name = 'GT_AdvIncomeTaxSale'));
  v_ln_fbrposfeeacc := (SELECT code FROM dbo.global WHERE (name = 'GT_FBRPOSFeeAcc'));
  v_sremks := (SELECT dbo.fn_getpreference('ShowSaleRemarksInLedger') AS a);
  DROP TABLE IF EXISTS tmp_lsl;
  CREATE TEMP TABLE tmp_lsl (
    clientinstanceid smallint NOT NULL,
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lsl SELECT s.clientinstanceid, s.saleinvcode FROM dbo.crs_saleledger AS s WHERE (((s.posted = 'Y') AND (s.accountfor = 'Y')) AND (NOT EXISTS (SELECT DISTINCT v.clientinstanceid, v.documentcode FROM dbo.crs_virtualgl AS v WHERE (((v.documenttype IN ('SV')) AND (v.clientinstanceid = s.clientinstanceid)) AND (v.documentcode = s.saleinvcode)))));
  INSERT INTO dbo.crs_virtualgltemp SELECT s.clientinstanceid, s.saleinvcode AS documentcode, 'SV' AS documenttype, s.salecatcode AS catcode, CASE s.salecatcode WHEN 1 THEN s.cashacccode WHEN 3 THEN s.cashacccode ELSE s.custcode END AS dr_acccode, trunc(v_ln_salesacc)::smallint AS cr_acccode, CASE s.salecatcode WHEN 1 THEN s.custcode WHEN 3 THEN s.custcode ELSE NULL END AS alternateacccode, s.date AS date, round((((sum((((d.looseqty + d.bonusqty)) * d.unitsalestax)) + sum(round(((((((d.looseqty * ((d.saleprice - d.itemflatdisc)))) * ((1 - ((.01 * d.discperc))))) * d.gstperc) * .01))::numeric, 2))) + round((((((sum((((d.looseqty * ((d.saleprice - d.itemflatdisc)))) * ((1 - ((.01 * d.discperc)))))) * ((1 - ((.01 * s.discperc))))) - s.flatdisc)) * ((s.invgstperc1 * .01))))::numeric, 2)))::numeric, v_roundupyo) AS saletax, round((((((sum((((d.looseqty * ((d.saleprice - d.itemflatdisc)))) * ((1 - ((.01 * d.discperc)))))) * ((1 - ((.01 * s.discperc))))) + s.misccharges) + s.salestax) - s.flatdisc))::numeric, v_roundupyo) AS gross, CASE v_sremks WHEN 'Y' THEN s.remarks ELSE (CASE s.salecatcode WHEN 3 THEN 'Cash receipt on sale #: ' WHEN 1 THEN 'Cash receipt on sale #: ' ELSE 'Receivable on cr. sale #: ' END || rtrim(ltrim((s.saleinvcode)::text))) END AS dr_remarks, ((('Revenue from ' || CASE s.salecatcode WHEN 3 THEN 'cash' WHEN 1 THEN 'cash' ELSE 'cr.' END) || ' sale #: ') || rtrim(ltrim((s.saleinvcode)::text))) AS cr_remarks, ((((('S.Tax ' || CASE s.salecatcode WHEN 3 THEN 'received' WHEN 1 THEN 'received' ELSE 'receivable' END) || ' on ') || CASE s.salecatcode WHEN 3 THEN 'cash' WHEN 1 THEN 'cash' ELSE 'cr.' END) || ' sale #: ') || rtrim(ltrim((s.saleinvcode)::text))) AS saletax_remarks, NULL::citext AS checkno, s.salesmancode AS usercode, s.saleinvcode AS vouchercode, s.saleinvcode AS invoicecode, 1 AS invoicetype, CASE s.salecatcode WHEN 2 THEN s.amt ELSE 0 END AS amt, s.paymentacccode AS dramtacccode, s.custcode AS cramtacccode, s.amtby AS amtby, s.amtdate AS amtdate, s.amtreference AS amtref, s.outstandingamt AS outstandingamt, 0 AS balance, CASE WHEN (s.patientcode IS NULL) THEN CASE WHEN (s.admissioncode IS NULL) THEN NULL ELSE (SELECT a.patientcode FROM dbo.patientadmission AS a WHERE (s.admissioncode = a.admissioncode)) END ELSE s.patientcode END AS patientcode, s.grn AS grn, s.gccode AS gccode, s.vehicle AS vehicle, s.shipto AS shipto, s.guestcode, s.studentcode, coalesce(sum((((d.looseqty + d.bonusqty)) * d.avgprice)), 0) AS cgs, s.currencycode, s.conversionrate, CASE WHEN (v_advincometax = 'Y') THEN coalesce(s.advancetaxamt, 0) ELSE 0 END AS advincometax, s.fbrposfee FROM dbo.crs_saleledger AS s, dbo.crs_saledetail AS d WHERE (((((dbo.tsql_str((s.clientinstanceid)::numeric, 10) || dbo.tsql_str((s.saleinvcode)::numeric, 10)))::citext IN (SELECT (dbo.tsql_str((lsl.clientinstanceid)::numeric, 10) || dbo.tsql_str((lsl.code)::numeric, 10)) FROM tmp_lsl AS lsl)) AND (s.clientinstanceid = d.clientinstanceid)) AND (s.saleinvcode = d.saleinvcode)) GROUP BY s.clientinstanceid, s.saleinvcode, s.custcode, s.salecatcode, s.date, s.discperc, s.misccharges, s.salestax, s.flatdisc, s.invgstperc1, s.salesmancode, s.amt, s.paymentacccode, s.amtby, s.amtdate, s.amtreference, s.outstandingamt, s.patientcode, s.admissioncode, s.remarks, s.grn, s.gccode, s.vehicle, s.shipto, s.cashacccode, s.guestcode, s.studentcode, s.currencycode, s.conversionrate, s.advancetaxamt, s.fbrposfee;
  INSERT INTO dbo.crs_virtualgltemp SELECT s.clientinstanceid, s.saleinvcode AS documentcode, 'SV' AS documenttype, s.salecatcode AS catcode, CASE s.salecatcode WHEN 1 THEN s.cashacccode WHEN 3 THEN s.cashacccode ELSE s.custcode END AS dr_acccode, trunc(v_ln_salesacc)::smallint AS cr_acccode, CASE s.salecatcode WHEN 1 THEN s.custcode WHEN 3 THEN s.custcode ELSE NULL END AS alternateacccode, s.date AS date, round((((sum((((d.looseqty + d.bonusqty)) * d.unitsalestax)) + sum(round(((((((d.looseqty * ((d.saleprice - d.itemflatdisc)))) * ((1 - ((.01 * d.discperc))))) * d.gstperc) * .01))::numeric, 2))) + round((((((sum((((d.looseqty * ((d.saleprice - d.itemflatdisc)))) * ((1 - ((.01 * d.discperc)))))) * ((1 - ((.01 * s.discperc))))) - s.flatdisc)) * ((s.invgstperc1 * .01))))::numeric, 2)))::numeric, v_roundupyo) AS saletax, round((((((sum((((d.looseqty * ((d.saleprice - d.itemflatdisc)))) * ((1 - ((.01 * d.discperc)))))) * ((1 - ((.01 * s.discperc))))) + s.misccharges) + s.salestax) - s.flatdisc))::numeric, v_roundupyo) AS gross, CASE v_sremks WHEN 'Y' THEN s.remarks ELSE (CASE s.salecatcode WHEN 3 THEN 'Cash receipt on sale #: ' WHEN 1 THEN 'Cash receipt on sale #: ' ELSE 'Receivable on cr. sale #: ' END || rtrim(ltrim((s.saleinvcode)::text))) END AS dr_remarks, ((('Revenue from ' || CASE s.salecatcode WHEN 3 THEN 'cash' WHEN 1 THEN 'cash' ELSE 'cr.' END) || ' sale #: ') || rtrim(ltrim((s.saleinvcode)::text))) AS cr_remarks, ((((('S.Tax ' || CASE s.salecatcode WHEN 3 THEN 'received' WHEN 1 THEN 'received' ELSE 'receivable' END) || ' on ') || CASE s.salecatcode WHEN 3 THEN 'cash' WHEN 1 THEN 'cash' ELSE 'cr.' END) || ' sale #: ') || rtrim(ltrim((s.saleinvcode)::text))) AS saletax_remarks, NULL::citext AS checkno, s.salesmancode AS usercode, s.saleinvcode AS vouchercode, s.saleinvcode AS invoicecode, 1 AS invoicetype, CASE s.salecatcode WHEN 2 THEN s.amt ELSE 0 END AS amt, s.paymentacccode AS dramtacccode, s.custcode AS cramtacccode, s.amtby AS amtby, s.amtdate AS amtdate, s.amtreference AS amtref, s.outstandingamt AS outstandingamt, 0 AS balance, CASE WHEN (s.patientcode IS NULL) THEN CASE WHEN (s.admissioncode IS NULL) THEN NULL ELSE (SELECT a.patientcode FROM dbo.patientadmission AS a WHERE (s.admissioncode = a.admissioncode)) END ELSE s.patientcode END AS patientcode, s.grn AS grn, s.gccode AS gccode, s.vehicle AS vehicle, s.shipto AS shipto, s.guestcode, s.studentcode, 0 AS cgs, s.currencycode, s.conversionrate, CASE WHEN (v_advincometax = 'Y') THEN coalesce(s.advancetaxamt, 0) ELSE 0 END AS advincometax, s.fbrposfee FROM dbo.crs_saleledger AS s, dbo.crs_saleinvdetail AS d WHERE (((((dbo.tsql_str((s.clientinstanceid)::numeric, 10) || dbo.tsql_str((s.saleinvcode)::numeric, 10)))::citext IN (SELECT (dbo.tsql_str((lsl.clientinstanceid)::numeric, 10) || dbo.tsql_str((lsl.code)::numeric, 10)) FROM tmp_lsl AS lsl)) AND (s.clientinstanceid = d.clientinstanceid)) AND (s.saleinvcode = d.saleinvcode)) GROUP BY s.clientinstanceid, s.saleinvcode, s.custcode, s.salecatcode, s.date, s.discperc, s.misccharges, s.salestax, s.flatdisc, s.invgstperc1, s.salesmancode, s.amt, s.paymentacccode, s.amtby, s.amtdate, s.amtreference, s.outstandingamt, s.patientcode, s.admissioncode, s.remarks, s.grn, s.gccode, s.vehicle, s.shipto, s.cashacccode, s.guestcode, s.studentcode, s.currencycode, s.conversionrate, s.advancetaxamt, s.fbrposfee;
  INSERT INTO dbo.crs_virtualgltemp SELECT s.clientinstanceid, s.saleinvcode AS documentcode, 'SV' AS documenttype, s.salecatcode AS catcode, s.cashacccode AS dr_acccode, s.custcode AS cr_acccode, NULL::smallint AS alternateacccode, s.date AS date, 0 AS saletax, s.cashcharged AS gross, ('Cash Received on Sale Inv. No.' || ltrim(rtrim(dbo.tsql_str((s.saleinvcode)::numeric, 10)))) AS dr_remarks, ('Cash Received on Sale Inv. No.' || ltrim(rtrim(dbo.tsql_str((s.saleinvcode)::numeric, 10)))) AS cr_remarks, '' AS saletax_remarks, NULL::citext AS checkno, s.salesmancode AS usercode, s.saleinvcode AS vouchercode, s.saleinvcode AS invoicecode, 1 AS invoicetype, 0 AS amt, NULL::integer AS dramtacccode, NULL::integer AS cramtacccode, NULL::smallint AS amtby, NULL::timestamp(3) AS amtdate, NULL::citext AS amtref, s.outstandingamt AS outstandingamt, 0 AS balance, CASE WHEN (s.patientcode IS NULL) THEN CASE WHEN (s.admissioncode IS NULL) THEN NULL ELSE (SELECT a.patientcode FROM dbo.patientadmission AS a WHERE (s.admissioncode = a.admissioncode)) END ELSE s.patientcode END AS patientcode, s.grn AS grn, s.gccode AS gccode, s.vehicle AS vehicle, s.shipto AS shipto, s.guestcode, s.studentcode, 0 AS cgs, s.currencycode, s.conversionrate, 0.00 AS advincometax, 0.00 AS fbrposfee FROM dbo.crs_saleledger AS s WHERE (((s.salecatcode NOT IN (1, 3)) AND (s.cashcharged > 0)) AND (((dbo.tsql_str((s.clientinstanceid)::numeric, 10) || dbo.tsql_str((s.saleinvcode)::numeric, 10)))::citext IN (SELECT (dbo.tsql_str((lsl.clientinstanceid)::numeric, 10) || dbo.tsql_str((lsl.code)::numeric, 10)) FROM tmp_lsl AS lsl))) UNION ALL SELECT s.clientinstanceid, s.saleinvcode AS documentcode, 'SV' AS documenttype, s.salecatcode AS catcode, d.acccode AS dr_acccode, s.custcode AS cr_acccode, NULL::smallint AS alternateacccode, s.date AS date, 0 AS saletax, amount AS gross, d.remarks AS dr_remarks, d.remarks AS cr_remarks, '' AS saletax_remarks, NULL::citext AS checkno, s.salesmancode AS usercode, s.saleinvcode AS vouchercode, s.saleinvcode AS invoicecode, 1 AS invoicetype, 0 AS amt, NULL::integer AS dramtacccode, NULL::integer AS cramtacccode, NULL::smallint AS amtby, NULL::timestamp(3) AS amtdate, NULL::citext AS amtref, s.outstandingamt AS outstandingamt, 0 AS balance, CASE WHEN (s.patientcode IS NULL) THEN CASE WHEN (s.admissioncode IS NULL) THEN NULL ELSE (SELECT a.patientcode FROM dbo.patientadmission AS a WHERE (s.admissioncode = a.admissioncode)) END ELSE s.patientcode END AS patientcode, s.grn AS grn, s.gccode AS gccode, s.vehicle AS vehicle, s.shipto AS shipto, s.guestcode, s.studentcode, 0 AS cgs, s.currencycode, s.conversionrate, 0.00 AS advincometax, 0.00 AS fbrposfee FROM dbo.crs_saleledger AS s, dbo.crs_cashierwindow AS d WHERE ((((dbo.tsql_str((s.clientinstanceid)::numeric, 10) || dbo.tsql_str((s.saleinvcode)::numeric, 10)))::citext IN (SELECT (dbo.tsql_str((lsl.clientinstanceid)::numeric, 10) || dbo.tsql_str((lsl.code)::numeric, 10)) FROM tmp_lsl AS lsl)) AND (s.saleinvcode = d.saleinvcode));
  TRUNCATE TABLE tmp_lsl RESTART IDENTITY;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_CRS_VirtualGL_SalesReturn ====
CREATE OR REPLACE FUNCTION dbo.sp_crs_virtualgl_salesreturn(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ln_purchaseacc numeric(5,0);
  v_ln_cashacc numeric(5,0);
  v_ln_equityacc numeric(5,0);
  v_ln_invacc numeric(5,0);
  v_ln_cgs numeric(5,0);
  v_ln_salesacc numeric(5,0);
  v_ln_salesretacc numeric(5,0);
  v_ln_purchaseretacc numeric(5,0);
  v_ln_revfromservice numeric(5,0);
  v_ln_salestaxacc numeric(5,0);
  v_srremks citext;
  v_invsys citext;
  v_roundupyo smallint;
BEGIN
  -- SET NOCOUNT ON
  v_roundupyo := (SELECT dbo.fn_get_int_preference('roundsalereturninvon') AS a);
  v_invsys := coalesce((SELECT dbo.fn_getpreference('InventorySystemUsed') AS a), 'P');
  v_ln_invacc := (SELECT code FROM dbo.global WHERE (name = 'GT_InventoryAcc'));
  v_ln_cgs := (SELECT code FROM dbo.global WHERE (name = 'GT_CostOfGoodsSoldAcc'));
  v_ln_cashacc := (SELECT code FROM dbo.global WHERE (name = 'GT_CashACC'));
  v_ln_salesacc := (SELECT code FROM dbo.global WHERE (name = 'GT_SalesACC'));
  v_ln_salesretacc := (SELECT code FROM dbo.global WHERE (name = 'GT_SalesReturnACC'));
  v_ln_salestaxacc := (SELECT code FROM dbo.global WHERE (name = 'GT_AdvanceSalesTaxACC'));
  v_srremks := (SELECT dbo.fn_getpreference('ShowSRetRemarksInLedger') AS a);
  DROP TABLE IF EXISTS tmp_lt_sret;
  CREATE TEMP TABLE tmp_lt_sret (
    clientinstanceid smallint NOT NULL,
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_sret SELECT s.clientinstanceid, s.srinvcode FROM dbo.crs_srledger AS s WHERE (((s.posted = 'Y') AND (s.accountfor = 'Y')) AND (NOT EXISTS (SELECT DISTINCT v.clientinstanceid, v.documentcode FROM dbo.crs_virtualgl AS v WHERE (((v.documenttype IN ('SR')) AND (v.clientinstanceid = s.clientinstanceid)) AND (v.documentcode = s.srinvcode)))));
  INSERT INTO dbo.crs_virtualgltemp SELECT s.clientinstanceid, s.srinvcode AS documentcode, 'SR' AS documenttype, s.srcatcode AS catcode, trunc(v_ln_salesretacc)::smallint AS dr_acccode, CASE s.srcatcode WHEN 6 THEN s.cashacccode WHEN 8 THEN s.cashacccode ELSE s.custcode END AS cr_acccode, CASE s.srcatcode WHEN 6 THEN s.custcode WHEN 8 THEN s.custcode ELSE NULL END AS alternateacccode, s.date AS date, round((((sum((((d.looseqty + d.bonusqty)) * d.unitsalestax)) + sum(round(((((((d.looseqty * d.srprice)) * ((1 - ((.01 * d.discperc))))) * d.gstperc) * .01))::numeric, 2))) + round((((((sum((((d.looseqty * d.srprice)) * ((1 - ((.01 * d.discperc)))))) * ((1 - ((.01 * s.discperc))))) - s.flatdisc)) * ((s.invgstperc1 * .01))))::numeric, 2)))::numeric, v_roundupyo) AS saletax, round((((((sum((((d.looseqty * d.srprice)) * ((1 - ((.01 * d.discperc)))))) * ((1 - ((.01 * s.discperc))))) + s.misccharges) + s.salestax) - s.flatdisc))::numeric, v_roundupyo) AS gross, (((('Revenue (reversal) on ' || CASE s.srcatcode WHEN 6 THEN 'cash' WHEN 8 THEN 'cash' ELSE 'cr.' END) || ' sale ret. #: ') || rtrim(ltrim((s.srinvcode)::text))) || CASE WHEN (s.saleinvcode IS NULL) THEN '' ELSE (', Sale #:' || rtrim(ltrim((s.saleinvcode)::text))) END) AS dr_remarks, CASE v_srremks WHEN 'Y' THEN s.remarks ELSE ((CASE s.srcatcode WHEN 6 THEN 'Cash paid on sale ret.#: ' WHEN 8 THEN 'Cash paid on sale ret.#: ' ELSE 'Payable on cr. sale ret.#: ' END || rtrim(ltrim((s.srinvcode)::text))) || CASE WHEN (s.saleinvcode IS NULL) THEN '' ELSE (', Sale #:' || rtrim(ltrim((s.saleinvcode)::text))) END) END AS cr_remarks, (((('S.Tax ' || CASE s.srcatcode WHEN 6 THEN 'Paid' WHEN 8 THEN 'Paid' ELSE 'Payable' END) || ' on sale ret. #: ') || rtrim(ltrim((s.srinvcode)::text))) || CASE WHEN (s.saleinvcode IS NULL) THEN '' ELSE (', sale #:' || rtrim(ltrim((s.saleinvcode)::text))) END) AS saletax_remarks, NULL::citext AS checkno, coalesce(s.salesmancode, 0) AS usercode, s.srinvcode AS vouchercode, s.srinvcode AS invoicecode, 3 AS invoicetype, CASE s.srcatcode WHEN 8 THEN 0 ELSE s.amt END AS amt, s.custcode AS dramtacccode, s.paymentacccode AS cramtacccode, s.amtby AS amtby, s.amtdate AS amtdate, s.amtreference AS amtref, s.outstandingamt AS outstandingamt, 0 AS balance, CASE WHEN (s.patientcode IS NULL) THEN CASE WHEN (s.admissioncode IS NULL) THEN NULL ELSE (SELECT a.patientcode FROM dbo.patientadmission AS a WHERE (s.admissioncode = a.admissioncode)) END ELSE s.patientcode END AS patientcode, NULL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto, s.guestcode, s.studentcode, coalesce(sum((((d.looseqty + d.bonusqty)) * CASE WHEN (s.saleinvcode > 0) THEN d.avgprice ELSE (((d.srprice * ((1 - (d.discperc * 0.01)))) * ((1 - (s.discperc * 0.01))))) END)), 0) AS cgs, s.currencycode, s.conversionrate, coalesce(s.advancetaxamt, 0) AS advincometax, coalesce(s.fbrposfee, 0) AS fbrposfee FROM dbo.crs_srledger AS s, dbo.crs_srdetail AS d WHERE (((((dbo.tsql_str((s.clientinstanceid)::numeric, 10) || dbo.tsql_str((s.srinvcode)::numeric, 10)))::citext IN (SELECT (dbo.tsql_str((lt_sret.clientinstanceid)::numeric, 10) || dbo.tsql_str((lt_sret.code)::numeric, 10)) FROM tmp_lt_sret AS lt_sret)) AND (s.clientinstanceid = d.clientinstanceid)) AND (s.srinvcode = d.srinvcode)) GROUP BY s.clientinstanceid, s.srinvcode, s.custcode, s.srcatcode, s.cashacccode, s.date, s.discperc, s.misccharges, s.salestax, s.flatdisc, s.invgstperc1, s.salesmancode, s.saleinvcode, s.amt, s.paymentacccode, s.amtby, s.amtdate, s.amtreference, s.outstandingamt, s.patientcode, s.admissioncode, s.cashacccode, s.remarks, s.guestcode, s.studentcode, s.currencycode, s.conversionrate, s.advancetaxamt, s.fbrposfee;
  INSERT INTO dbo.crs_virtualgltemp SELECT s.clientinstanceid, s.srinvcode AS documentcode, 'SR' AS documenttype, s.srcatcode AS catcode, s.custcode AS dr_acccode, s.cashacccode AS cr_acccode, NULL::smallint AS alternateacccode, s.date AS date, 0 AS saletax, s.cashcharged AS gross, ('Cash Paid on S/R No.' || ltrim(rtrim(dbo.tsql_str((s.srinvcode)::numeric, 10)))) AS dr_remarks, ('Cash Paid on S/R No.' || ltrim(rtrim(dbo.tsql_str((s.srinvcode)::numeric, 10)))) AS cr_remarks, '' AS saletax_remarks, NULL::citext AS checkno, s.salesmancode AS usercode, s.srinvcode AS vouchercode, s.srinvcode AS invoicecode, 3 AS invoicetype, 0 AS amt, NULL::integer AS dramtacccode, NULL::integer AS cramtacccode, NULL::smallint AS amtby, NULL::timestamp(3) AS amtdate, NULL::citext AS amtref, s.outstandingamt AS outstandingamt, 0 AS balance, CASE WHEN (s.patientcode IS NULL) THEN CASE WHEN (s.admissioncode IS NULL) THEN NULL ELSE (SELECT a.patientcode FROM dbo.patientadmission AS a WHERE (s.admissioncode = a.admissioncode)) END ELSE s.patientcode END AS patientcode, NULL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto, s.guestcode, s.studentcode, 0 AS cgs, s.currencycode, s.conversionrate, 0.00 AS advincometax, 0.00 AS fbrposfee FROM dbo.crs_srledger AS s WHERE (((s.srcatcode NOT IN (6, 8)) AND (s.cashcharged > 0)) AND (((dbo.tsql_str((s.clientinstanceid)::numeric, 10) || dbo.tsql_str((s.srinvcode)::numeric, 10)))::citext IN (SELECT (dbo.tsql_str((lt_sret.clientinstanceid)::numeric, 10) || dbo.tsql_str((lt_sret.code)::numeric, 10)) FROM tmp_lt_sret AS lt_sret))) UNION ALL SELECT s.clientinstanceid, s.srinvcode AS documentcode, 'SR' AS documenttype, s.srcatcode AS catcode, s.custcode AS dr_acccode, d.acccode AS cr_acccode, NULL::smallint AS alternateacccode, s.date AS date, 0 AS saletax, amount AS gross, d.remarks AS dr_remarks, d.remarks AS cr_remarks, '' AS saletax_remarks, NULL::citext AS checkno, s.salesmancode AS usercode, s.srinvcode AS vouchercode, s.srinvcode AS invoicecode, 3 AS invoicetype, 0 AS amt, NULL::integer AS dramtacccode, NULL::integer AS cramtacccode, NULL::smallint AS amtby, NULL::timestamp(3) AS amtdate, NULL::citext AS amtref, s.outstandingamt AS outstandingamt, 0 AS balance, CASE WHEN (s.patientcode IS NULL) THEN CASE WHEN (s.admissioncode IS NULL) THEN NULL ELSE (SELECT a.patientcode FROM dbo.patientadmission AS a WHERE (s.admissioncode = a.admissioncode)) END ELSE s.patientcode END AS patientcode, NULL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto, s.guestcode, s.studentcode, 0 AS cgs, s.currencycode, s.conversionrate, 0.00 AS advincometax, 0.00 AS fbrposfee FROM dbo.crs_srledger AS s, dbo.crs_mastercashwin AS d WHERE ((((((dbo.tsql_str((s.clientinstanceid)::numeric, 10) || dbo.tsql_str((s.srinvcode)::numeric, 10)))::citext IN (SELECT (dbo.tsql_str((lt_sret.clientinstanceid)::numeric, 10) || dbo.tsql_str((lt_sret.code)::numeric, 10)) FROM tmp_lt_sret AS lt_sret)) AND (s.clientinstanceid = d.clientinstanceid)) AND (s.srinvcode = d.documentcode)) AND (d.documenttype = 'SR'));
  TRUNCATE TABLE tmp_lt_sret RESTART IDENTITY;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_CRS_VirtualGL_TransactionWindow ====
CREATE OR REPLACE FUNCTION dbo.sp_crs_virtualgl_transactionwindow(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
BEGIN
  -- SET NOCOUNT ON
  DROP TABLE IF EXISTS tmp_lt_transaction;
  CREATE TEMP TABLE tmp_lt_transaction (
    clientinstanceid smallint NOT NULL,
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_transaction SELECT t.clientinstanceid, t.documentcode FROM dbo.crs_transactionheader AS t WHERE (NOT EXISTS (SELECT DISTINCT v.clientinstanceid, v.documentcode FROM dbo.crs_virtualgl AS v WHERE (((v.documenttype IN (SELECT shortname FROM dbo.transactiontype)) AND (v.clientinstanceid = t.clientinstanceid)) AND (v.documentcode = t.documentcode))));
  INSERT INTO dbo.crs_virtualgltemp SELECT th.clientinstanceid, th.documentcode AS documentcode, tt.shortname AS documenttype, th.transactiontypecode AS catcode, th.cashacccode AS dr_acccode, th.acccode AS cr_acccode, NULL::smallint AS alternateacccode, th.date AS date, 0 AS saletax, th.cashcharged AS gross, ('Cash Recvd. Against Transaction Doc. Code: ' || ltrim(rtrim(dbo.tsql_str((th.documentcode)::numeric, 10)))) AS dr_remarks, ('Cash Recvd. Against Transaction Doc. Code: ' || ltrim(rtrim(dbo.tsql_str((th.documentcode)::numeric, 10)))) AS cr_remarks, '' AS saletax_remarks, NULL::citext AS checkno, th.usercode AS usercode, th.transactioncode AS vouchercode, th.transactioncode AS invoicecode, NULL::smallint AS invoicetype, 0 AS amt, NULL::integer AS dramtacccode, NULL::integer AS cramtacccode, NULL::smallint AS amtby, NULL::timestamp(3) AS amtdate, NULL::citext AS amtref, 0 AS outstandingamt, 0 AS balance, th.patientcode AS patientcode, NULL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto, NULL::integer AS guestcode, NULL::integer AS studentcode, 0 AS cgs, NULL::smallint AS currencycode, NULL::numeric(11,5) AS conversionrate, 0.00 AS advincometax, 0.00 AS fbrposfee FROM dbo.crs_transactionheader AS th, dbo.transactiontype AS tt WHERE (((((th.cashcharged > 0) AND (th.posted = 'Y')) AND (((dbo.tsql_str((th.clientinstanceid)::numeric, 10) || dbo.tsql_str((th.documentcode)::numeric, 10)))::citext IN (SELECT (dbo.tsql_str((lt_transaction.clientinstanceid)::numeric, 10) || dbo.tsql_str((lt_transaction.code)::numeric, 10)) FROM tmp_lt_transaction AS lt_transaction))) AND (th.transactiontypecode = tt.transactiontypecode)) AND (tt.transactioncatcode = 1)) UNION ALL SELECT th.clientinstanceid, th.documentcode AS documentcode, tt.shortname AS documenttype, th.transactiontypecode AS catcode, td.acccode AS dr_acccode, th.acccode AS cr_acccode, NULL::smallint AS alternateacccode, th.date AS date, 0 AS saletax, td.amount AS gross, ('Amount Recvd. Against Transaction Doc. Code: ' || ltrim(rtrim(dbo.tsql_str((th.documentcode)::numeric, 10)))) AS dr_remarks, ('Amount Recvd. Against Transaction Doc. Code: ' || ltrim(rtrim(dbo.tsql_str((th.documentcode)::numeric, 10)))) AS cr_remarks, '' AS saletax_remarks, NULL::citext AS checkno, th.usercode AS usercode, th.transactioncode AS vouchercode, th.transactioncode AS invoicecode, NULL::smallint AS invoicetype, 0 AS amt, NULL::integer AS dramtacccode, NULL::integer AS cramtacccode, NULL::smallint AS amtby, NULL::timestamp(3) AS amtdate, NULL::citext AS amtref, 0 AS outstandingamt, 0 AS balance, th.patientcode AS patientcode, NULL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto, NULL::integer AS guestcode, NULL::integer AS studentcode, 0 AS cgs, NULL::smallint AS currencycode, NULL::numeric(11,5) AS conversionrate, 0.00 AS advincometax, 0.00 AS fbrposfee FROM dbo.crs_transactionheader AS th, dbo.crs_transactiondetail AS td, dbo.transactiontype AS tt WHERE ((((((th.posted = 'Y') AND (th.transactiontypecode = tt.transactiontypecode)) AND (tt.transactioncatcode = 1)) AND (th.documentcode = td.documentcode)) AND (td.amount > 0)) AND (((dbo.tsql_str((th.clientinstanceid)::numeric, 10) || dbo.tsql_str((th.documentcode)::numeric, 10)))::citext IN (SELECT (dbo.tsql_str((lt_transaction.clientinstanceid)::numeric, 10) || dbo.tsql_str((lt_transaction.code)::numeric, 10)) FROM tmp_lt_transaction AS lt_transaction))) UNION ALL SELECT th.clientinstanceid, th.documentcode AS documentcode, tt.shortname AS documenttype, th.transactiontypecode AS catcode, th.acccode AS dr_acccode, th.cashacccode AS cr_acccode, NULL::smallint AS alternateacccode, th.date AS date, 0 AS saletax, th.cashcharged AS gross, ('Cash Paid Against Transaction Doc. Code: ' || ltrim(rtrim(dbo.tsql_str((th.documentcode)::numeric, 10)))) AS dr_remarks, ('Cash Paid Against Transaction Doc. Code: ' || ltrim(rtrim(dbo.tsql_str((th.documentcode)::numeric, 10)))) AS cr_remarks, '' AS saletax_remarks, NULL::citext AS checkno, th.usercode AS usercode, th.transactioncode AS vouchercode, th.transactioncode AS invoicecode, NULL::smallint AS invoicetype, 0 AS amt, NULL::integer AS dramtacccode, NULL::integer AS cramtacccode, NULL::smallint AS amtby, NULL::timestamp(3) AS amtdate, NULL::citext AS amtref, 0 AS outstandingamt, 0 AS balance, th.patientcode AS patientcode, NULL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto, NULL::integer AS guestcode, NULL::integer AS studentcode, 0 AS cgs, NULL::smallint AS currencycode, NULL::numeric(11,5) AS conversionrate, 0.00 AS advincometax, 0.00 AS fbrposfee FROM dbo.crs_transactionheader AS th, dbo.transactiontype AS tt WHERE (((((th.cashcharged > 0) AND (th.posted = 'Y')) AND (th.transactiontypecode = tt.transactiontypecode)) AND (tt.transactioncatcode = 2)) AND (((dbo.tsql_str((th.clientinstanceid)::numeric, 10) || dbo.tsql_str((th.documentcode)::numeric, 10)))::citext IN (SELECT (dbo.tsql_str((lt_transaction.clientinstanceid)::numeric, 10) || dbo.tsql_str((lt_transaction.code)::numeric, 10)) FROM tmp_lt_transaction AS lt_transaction))) UNION ALL SELECT th.clientinstanceid, th.documentcode AS documentcode, tt.shortname AS documenttype, th.transactiontypecode AS catcode, th.acccode AS dr_acccode, td.acccode AS cr_acccode, NULL::smallint AS alternateacccode, th.date AS date, 0 AS saletax, td.amount AS gross, ('Amount Paid Against Transaction Doc. Code: ' || ltrim(rtrim(dbo.tsql_str((th.documentcode)::numeric, 10)))) AS dr_remarks, ('Amount Paid Against Transaction Doc. Code: ' || ltrim(rtrim(dbo.tsql_str((th.documentcode)::numeric, 10)))) AS cr_remarks, '' AS saletax_remarks, NULL::citext AS checkno, th.usercode AS usercode, th.transactioncode AS vouchercode, th.transactioncode AS invoicecode, NULL::smallint AS invoicetype, 0 AS amt, NULL::integer AS dramtacccode, NULL::integer AS cramtacccode, NULL::smallint AS amtby, NULL::timestamp(3) AS amtdate, NULL::citext AS amtref, 0 AS outstandingamt, 0 AS balance, th.patientcode AS patientcode, NULL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto, NULL::integer AS guestcode, NULL::integer AS studentcode, 0 AS cgs, NULL::smallint AS currencycode, NULL::numeric(11,5) AS conversionrate, 0.00 AS advincometax, 0.00 AS fbrposfee FROM dbo.crs_transactionheader AS th, dbo.crs_transactiondetail AS td, dbo.transactiontype AS tt WHERE ((((((th.posted = 'Y') AND (th.transactiontypecode = tt.transactiontypecode)) AND (tt.transactioncatcode = 2)) AND (th.documentcode = td.documentcode)) AND (td.amount > 0)) AND (((dbo.tsql_str((th.clientinstanceid)::numeric, 10) || dbo.tsql_str((th.documentcode)::numeric, 10)))::citext IN (SELECT (dbo.tsql_str((lt_transaction.clientinstanceid)::numeric, 10) || dbo.tsql_str((lt_transaction.code)::numeric, 10)) FROM tmp_lt_transaction AS lt_transaction)));
  TRUNCATE TABLE tmp_lt_transaction RESTART IDENTITY;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_CRS_VirtualGL_Vouchers ====
CREATE OR REPLACE FUNCTION dbo.sp_crs_virtualgl_vouchers(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ln_purchaseacc numeric(5,0);
  v_ln_cashacc numeric(5,0);
  v_ln_equityacc numeric(5,0);
  v_ln_salesacc numeric(5,0);
  v_ln_salesretacc numeric(5,0);
  v_ln_purchaseretacc numeric(5,0);
  v_ln_revfromservice numeric(5,0);
  v_ln_salestaxacc numeric(5,0);
BEGIN
  -- SET NOCOUNT ON
  v_ln_purchaseacc := (SELECT code FROM dbo.global WHERE (name = 'GT_PurchaseAccount'));
  v_ln_cashacc := (SELECT code FROM dbo.global WHERE (name = 'GT_CashACC'));
  v_ln_equityacc := (SELECT code FROM dbo.global WHERE (name = 'GT_EquityACC'));
  v_ln_purchaseretacc := (SELECT code FROM dbo.global WHERE (name = 'GT_PurchaseReturnsAccount'));
  v_ln_salestaxacc := (SELECT code FROM dbo.global WHERE (name = 'GT_AdvanceSalesTaxACC'));
  DROP TABLE IF EXISTS tmp_lt_voucher;
  CREATE TEMP TABLE tmp_lt_voucher (
    clientinstanceid smallint,
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_voucher SELECT h.clientinstanceid, h.glvochcode FROM dbo.crs_glheader AS h WHERE ((NOT EXISTS (SELECT DISTINCT v.clientinstanceid, v.documentcode FROM dbo.crs_virtualgl AS v, dbo.crs_vochercategory AS vc WHERE ((((v.clientinstanceid = vc.clientinstanceid) AND (v.documenttype = vc.shortname)) AND (h.clientinstanceid = v.clientinstanceid)) AND (v.documentcode = h.glvochcode)))) AND (h.posted = 'Y'));
  INSERT INTO dbo.crs_virtualgl (clientinstanceid, documentcode, documenttype, catcode, acccode, alternateacccode, date, debit, credit, remarks, checkno, usercode, vouchercode, invoicecode, invoicetype, outstandingamt, balance, vrow, patientcode, grn, gccode, vehicle, shipto, guestcode, studentcode, currencycode, conversionrate) SELECT h.clientinstanceid, h.glvochcode AS documentcode, vc.shortname AS documenttype, h.vochcatcode AS catcode, d.acccode AS acccode, NULL::smallint AS alternateacccode, h.date AS date, d.debit AS debit, d.credit AS credit, CASE WHEN (h.acccode = d.acccode) THEN h.remarks ELSE d.remarks END AS remarks, CASE WHEN (h.acccode = d.acccode) THEN h.chkno ELSE d.chkno END AS checkno, h.salesmancode AS usercode, h.vouchercode, d.invoicecode, vc.invoicetype, d.outstandingamt AS outstandingamt, d.balance AS balance, CASE d.debit WHEN 0 THEN 1 ELSE 0 END AS vrow, d.patientcode, NULL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto, d.guestcode AS guestcode, d.studentcode AS studentcode, h.currencycode, h.conversionrate FROM dbo.crs_glheader AS h, dbo.crs_gldetail AS d, dbo.crs_vochercategory AS vc WHERE (((((((dbo.tsql_str((h.clientinstanceid)::numeric, 10) || dbo.tsql_str((h.glvochcode)::numeric, 10)))::citext IN (SELECT (dbo.tsql_str((lt_voucher.clientinstanceid)::numeric, 10) || dbo.tsql_str((lt_voucher.code)::numeric, 10)) AS code FROM tmp_lt_voucher AS lt_voucher)) AND (h.clientinstanceid = d.clientinstanceid)) AND (h.clientinstanceid = vc.clientinstanceid)) AND (h.glvochcode = d.glvochcode)) AND (h.vochcatcode = vc.vochcatcode));
  TRUNCATE TABLE tmp_lt_voucher RESTART IDENTITY;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_CRS_ZONALAREASALES_CROSSTAB ====
CREATE OR REPLACE FUNCTION dbo.sp_crs_zonalareasales_crosstab(zonecode integer, startdate timestamp, enddate timestamp, reportgrouping citext, grouplist citext, pricetype smallint, totcol double precision, colcaption smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_zonecode integer;
  v_startdate timestamp(3);
  v_enddate timestamp(3);
  v_reportgrouping citext;
  v_grouplist citext;
  v_pricetype smallint;
  v_totcol double precision;
  v_colcaption smallint;
  v_upd citext;
  v_col citext;
  v_rowid integer;
  v_colname citext;
  v_colcode citext;
  v_str_col citext;
  v_totareas double precision;
  v_curriter integer;
  v_iterations integer;
  v_i integer;
  v_tot integer;
  v_icode integer;
  v_areacode integer;
  v_qty integer;
  v_val numeric(15,5);
  v_err integer;
  _dq1 text;
  cur_c1 refcursor;
  _dq2 text;
  _fs integer := -1;
BEGIN
  v_zonecode := zonecode;
  v_startdate := startdate;
  v_enddate := enddate;
  v_reportgrouping := reportgrouping;
  v_grouplist := grouplist;
  v_pricetype := pricetype;
  v_totcol := totcol;
  v_colcaption := colcaption;
  DELETE FROM dbo.crosstab_reportdata;
  -- SET NOCOUNT ON
  DROP TABLE IF EXISTS tv_sp_crs_zonalareasales_crosstab_coltable;
  CREATE TEMP TABLE tv_sp_crs_zonalareasales_crosstab_coltable (
    code integer,
    shortname citext,
    rowid integer GENERATED BY DEFAULT AS IDENTITY
) ON COMMIT DROP;
  v_totareas := coalesce((SELECT count(area.areacode) FROM dbo.zoneareas AS z, dbo.area WHERE ((z.zonecode = v_zonecode) AND (z.areacode = area.areacode))), 0);
  DROP TABLE IF EXISTS tv_sp_crs_zonalareasales_crosstab_tab_grouplist;
  CREATE TEMP TABLE tv_sp_crs_zonalareasales_crosstab_tab_grouplist (
    code integer NOT NULL
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tv_sp_crs_zonalareasales_crosstab_tab_itemlist;
  CREATE TEMP TABLE tv_sp_crs_zonalareasales_crosstab_tab_itemlist (
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tv_sp_crs_zonalareasales_crosstab_tab_grouplist SELECT code FROM dbo.udf_stringtotabl(v_grouplist, ',') AS udf_stringtotabl;
  INSERT INTO tv_sp_crs_zonalareasales_crosstab_tab_itemlist SELECT code FROM dbo.udf_selectitems(v_reportgrouping, v_grouplist) AS udf_selectitems;
  IF ((v_totareas > 0) AND (v_totcol > 0)) THEN
    v_tot := trunc((SELECT min(a) FROM (SELECT v_totcol AS a UNION SELECT v_totareas AS a) AS t))::integer;
    INSERT INTO tv_sp_crs_zonalareasales_crosstab_coltable (code, shortname) SELECT area.areacode, CASE WHEN (v_colcaption = 1) THEN area.shortname ELSE area.name END AS name FROM dbo.zoneareas AS z, dbo.area WHERE ((z.zonecode = v_zonecode) AND (z.areacode = area.areacode)) ORDER BY area.shortname;
    v_iterations := trunc(ceiling((v_totareas / v_totcol)))::integer;
    v_curriter := 1;
    v_rowid := 0;
    WHILE (v_curriter <= v_iterations) LOOP
      INSERT INTO dbo.crosstab_reportdata (code1, code2, code3) SELECT code, v_curriter, v_zonecode FROM tv_sp_crs_zonalareasales_crosstab_tab_itemlist AS tab_itemlist;
      v_i := 1;
      WHILE (v_i <= v_tot) LOOP
        v_rowid := (v_rowid + 1);
        v_colname := rtrim(ltrim(coalesce((SELECT shortname FROM tv_sp_crs_zonalareasales_crosstab_coltable AS coltable WHERE (rowid = v_rowid)), '')));
        v_colcode := rtrim(ltrim(dbo.tsql_str(((SELECT code FROM tv_sp_crs_zonalareasales_crosstab_coltable AS coltable WHERE (rowid = v_rowid)))::numeric, 7)));
        IF (v_colcode IS NULL) THEN
          EXIT;
        ELSE
          v_str_col := ltrim(rtrim(dbo.tsql_str((v_i)::numeric, 7)));
          v_upd := ((((((((('UPDATE CrossTab_ReportData SET C_Name' || v_str_col) || ' = ''') || v_colname) || ''', C_Code') || v_str_col) || ' = ') || v_colcode) || ' WHERE CODE2 = ') || ltrim(rtrim(dbo.tsql_str((v_curriter)::numeric, 7))));
          _dq1 := v_upd;
          IF _dq1 IS NOT NULL THEN
            EXECUTE dbo.tsql_dyn(_dq1);
          END IF;
          v_err := 0;
          IF (v_err <> 0) THEN
            v_upd := ('UPDATION ERROR, DETAILS: ' || v_upd);
            RAISE EXCEPTION '%', v_upd;
            return_value := -1;
            RETURN;
          END IF;
          v_i := (v_i + 1);
        END IF;
      END LOOP;
      v_curriter := (v_curriter + 1);
    END LOOP;
    OPEN cur_c1 FOR SELECT s.icode, coalesce(sum(s.qty), 0) AS qty, round((sum(CASE v_pricetype WHEN 1 THEN s.netamt WHEN 2 THEN (s.qty * round(((i.saleprice / CASE i.packunits WHEN 0 THEN 1 ELSE i.packunits END))::numeric, 2)) WHEN 3 THEN (s.qty * round(((i.purprice / CASE i.packunits WHEN 0 THEN 1 ELSE i.packunits END))::numeric, 2)) ELSE (s.qty * round((i.avgprice)::numeric, 2)) END))::numeric, 0) AS val, s.areacode FROM (SELECT sd.icode, c.areacode, sl.custcode AS custcode, coalesce(sum((sd.looseqty + sd.bonusqty)), 0) AS qty, round((coalesce(sum(((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc)))) * ((1 - ((.01 * sd.discperc))))) * ((1 - ((.01 * sl.discperc)))))), 0))::numeric, 2) AS netamt FROM dbo.crs_saleledger AS sl, dbo.crs_saledetail AS sd, dbo.customer AS c, (SELECT areacode, zonecode FROM dbo.zoneareas WHERE (zonecode = v_zonecode)) AS a WHERE ((((((sd.clientinstanceid = sl.clientinstanceid) AND (sl.saleinvcode = sd.saleinvcode)) AND (sl.posted = 'Y')) AND (a.areacode = c.areacode)) AND (c.custcode = sl.custcode)) AND (sl.date BETWEEN v_startdate AND v_enddate)) GROUP BY sd.icode, sl.custcode, c.areacode UNION ALL SELECT sd.icode, c.areacode, sl.custcode AS custcode, (-coalesce(sum((sd.looseqty + sd.bonusqty)), 0)) AS qty, (-round((coalesce(sum(((((sd.looseqty * sd.srprice)) * ((1 - ((.01 * sd.discperc))))) * ((1 - ((.01 * sl.discperc)))))), 0))::numeric, 2)) AS netamt FROM dbo.crs_srledger AS sl, dbo.crs_srdetail AS sd, dbo.customer AS c, (SELECT areacode, zonecode FROM dbo.zoneareas WHERE (zonecode = v_zonecode)) AS a WHERE ((((((sd.clientinstanceid = sl.clientinstanceid) AND (sl.srinvcode = sd.srinvcode)) AND (sl.posted = 'Y')) AND (a.areacode = c.areacode)) AND (c.custcode = sl.custcode)) AND (sl.date BETWEEN v_startdate AND v_enddate)) GROUP BY sd.icode, sl.custcode, c.areacode) AS s, dbo.item AS i WHERE ((i.icode = s.icode) AND (i.icode IN (SELECT code FROM tv_sp_crs_zonalareasales_crosstab_tab_itemlist AS tab_itemlist))) GROUP BY s.areacode, s.icode ORDER BY s.areacode, s.icode;
    FETCH NEXT FROM cur_c1 INTO v_icode, v_qty, v_val, v_areacode;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    WHILE (_fs = 0) LOOP
      v_i := 1;
      WHILE (v_i <= v_tot) LOOP
        v_colcode := ltrim(rtrim(dbo.tsql_str((v_icode)::numeric, 7)));
        v_colname := ltrim(rtrim(dbo.tsql_str((v_areacode)::numeric, 7)));
        v_str_col := ltrim(rtrim(dbo.tsql_str((v_i)::numeric, 7)));
        v_upd := ((((((((((((((((((('UPDATE CrossTab_ReportData SET ' || 'QTY') || v_str_col) || ' = ') || ltrim(rtrim(dbo.tsql_str((v_qty)::numeric, 7)))) || ', VAL') || v_str_col) || ' = ') || ltrim(rtrim(dbo.tsql_str((v_val)::numeric, 15, 5)))) || ', C_Code') || v_str_col) || ' = ') || v_colname) || ' WHERE CODE1 = ') || v_colcode) || ' AND ') || ' C_Code') || v_str_col) || ' = ') || v_colname);
        _dq2 := v_upd;
        IF _dq2 IS NOT NULL THEN
          EXECUTE dbo.tsql_dyn(_dq2);
        END IF;
        v_err := 0;
        IF (v_err <> 0) THEN
          v_upd := ('CROSSTAB PLOTING ERROR, DETAILS: ' || v_upd);
          RAISE EXCEPTION '%', v_upd;
          CLOSE cur_c1;
          -- DEALLOCATE C1
          return_value := -1;
          RETURN;
        END IF;
        v_i := (v_i + 1);
      END LOOP;
      FETCH NEXT FROM cur_c1 INTO v_icode, v_qty, v_val, v_areacode;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    END LOOP;
    CLOSE cur_c1;
    -- DEALLOCATE C1
    UPDATE dbo.crosstab_reportdata AS c SET name1 = i.name, name2 = i.customicode, name3 = i.packingdesc, name4 = (SELECT name FROM dbo.zone WHERE (zonecode = v_zonecode)), code5 = CASE v_reportgrouping WHEN 'M' THEN i.manfcode WHEN 'C' THEN i.icatcode WHEN 'L' THEN i.iccode ELSE i.packcode END, name5 = CASE v_reportgrouping WHEN 'M' THEN (SELECT m.name FROM dbo.manufacturer AS m WHERE (m.manfcode = i.manfcode)) WHEN 'C' THEN (SELECT c.name FROM dbo.itemcategory AS c WHERE (c.icatcode = i.icatcode)) WHEN 'L' THEN (SELECT c.name FROM dbo.itemclass AS c WHERE (c.iccode = i.iccode)) ELSE (SELECT p.name FROM dbo.itempacking AS p WHERE (p.packcode = i.packcode)) END, value1 = CASE v_pricetype WHEN 1 THEN round(((i.saleprice / CASE i.packunits WHEN 0 THEN 1 ELSE i.packunits END))::numeric, 2) WHEN 2 THEN round(((i.saleprice / CASE i.packunits WHEN 0 THEN 1 ELSE i.packunits END))::numeric, 2) WHEN 3 THEN round(((i.purprice / CASE i.packunits WHEN 0 THEN 1 ELSE i.packunits END))::numeric, 2) ELSE round((i.avgprice)::numeric, 2) END FROM dbo.item AS i WHERE (i.icode = c.code1);
    PERFORM dbo.sp_update_total_crosstab_reportdata();
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_CUSTCATWISESALES ====
CREATE OR REPLACE FUNCTION dbo.sp_custcatwisesales(ar_startdate timestamp, ar_enddate timestamp, reportgrouping citext, grouplist citext, custcatlist citext, arealist citext, zerorows smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ar_startdate timestamp(3);
  v_ar_enddate timestamp(3);
  v_reportgrouping citext;
  v_grouplist citext;
  v_custcatlist citext;
  v_arealist citext;
  v_zerorows smallint;
BEGIN
  v_ar_startdate := ar_startdate;
  v_ar_enddate := ar_enddate;
  v_reportgrouping := reportgrouping;
  v_grouplist := grouplist;
  v_custcatlist := custcatlist;
  v_arealist := arealist;
  v_zerorows := zerorows;
  DELETE FROM dbo.reportdata;
  DROP TABLE IF EXISTS tv_sp_custcatwisesales_tab_grouplist;
  CREATE TEMP TABLE tv_sp_custcatwisesales_tab_grouplist (
    code integer NOT NULL
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tv_sp_custcatwisesales_tab_custcatlist;
  CREATE TEMP TABLE tv_sp_custcatwisesales_tab_custcatlist (
    code integer NOT NULL
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tv_sp_custcatwisesales_tab_arealist;
  CREATE TEMP TABLE tv_sp_custcatwisesales_tab_arealist (
    code integer NOT NULL
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tv_sp_custcatwisesales_tab_itemlist;
  CREATE TEMP TABLE tv_sp_custcatwisesales_tab_itemlist (
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tv_sp_custcatwisesales_tab_grouplist SELECT code FROM dbo.udf_stringtotabl(v_grouplist, ',') AS udf_stringtotabl;
  INSERT INTO tv_sp_custcatwisesales_tab_custcatlist SELECT code FROM dbo.udf_stringtotabl(v_custcatlist, ',') AS udf_stringtotabl;
  INSERT INTO tv_sp_custcatwisesales_tab_arealist SELECT code FROM dbo.udf_stringtotabl(v_arealist, ',') AS udf_stringtotabl;
  INSERT INTO tv_sp_custcatwisesales_tab_itemlist SELECT code FROM dbo.udf_selectitems(v_reportgrouping, v_grouplist) AS udf_selectitems;
  INSERT INTO dbo.reportdata (code1, code2, code3, name1, name2, name3, name4, name5, value1, value2) SELECT s.icode AS code1, s.custcatcode AS code2, CASE v_reportgrouping WHEN 'M' THEN i.manfcode WHEN 'C' THEN i.icatcode WHEN 'L' THEN i.iccode ELSE i.packcode END AS code3, i.name AS name1, (SELECT name FROM dbo.customercategory WHERE (custcatcode = s.custcatcode)) AS name2, CASE v_reportgrouping WHEN 'M' THEN (SELECT m.name FROM dbo.manufacturer AS m WHERE (m.manfcode = i.manfcode)) WHEN 'C' THEN (SELECT c.name FROM dbo.itemcategory AS c WHERE (c.icatcode = i.icatcode)) WHEN 'L' THEN (SELECT c.name FROM dbo.itemclass AS c WHERE (c.iccode = i.iccode)) ELSE (SELECT p.name FROM dbo.itempacking AS p WHERE (p.packcode = i.packcode)) END AS name3, i.customicode AS name4, i.packingdesc AS name5, coalesce(sum(qty), 0) AS value1, round((sum(netamt))::numeric, 0) AS value2 FROM (SELECT -1 AS invno, i.icode AS icode, c.custcatcode, 0 AS qty, 0 AS netamt FROM (SELECT c.custcatcode FROM dbo.customer AS c WHERE ((c.areacode IN (SELECT code FROM tv_sp_custcatwisesales_tab_arealist AS tab_arealist)) AND (c.custcatcode IN (SELECT code FROM tv_sp_custcatwisesales_tab_custcatlist AS tab_custcatlist)))) AS c, (SELECT min(code) AS icode FROM tv_sp_custcatwisesales_tab_itemlist AS tab_itemlist) AS i WHERE (CASE v_zerorows WHEN 0 THEN 0 ELSE 1 END = 1) UNION ALL SELECT -1 AS invno, i.icode AS icode, c.custcatcode, 0 AS qty, 0 AS netamt FROM (SELECT min(c.custcatcode) AS custcatcode FROM dbo.customer AS c WHERE ((c.areacode IN (SELECT code FROM tv_sp_custcatwisesales_tab_arealist AS tab_arealist)) AND (c.custcatcode IN (SELECT code FROM tv_sp_custcatwisesales_tab_custcatlist AS tab_custcatlist)))) AS c, (SELECT code AS icode FROM tv_sp_custcatwisesales_tab_itemlist AS tab_itemlist) AS i WHERE (CASE v_zerorows WHEN 0 THEN 0 ELSE 1 END = 1) UNION ALL SELECT sl.saleinvcode AS invno, sd.icode, c.custcatcode, coalesce(sum((sd.looseqty + sd.bonusqty)), 0) AS qty, round((coalesce(sum(((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc)))) * ((1 - ((.01 * sd.discperc))))) * ((1 - ((.01 * sl.discperc)))))), 0))::numeric, 2) AS netamt FROM dbo.saleledger AS sl, dbo.saledetail AS sd, (SELECT c.custcode, c.areacode, c.custcatcode FROM dbo.customer AS c WHERE ((c.areacode IN (SELECT code FROM tv_sp_custcatwisesales_tab_arealist AS tab_arealist)) AND (c.custcatcode IN (SELECT code FROM tv_sp_custcatwisesales_tab_custcatlist AS tab_custcatlist)))) AS c, (SELECT code AS icode FROM tv_sp_custcatwisesales_tab_itemlist AS tab_itemlist) AS i WHERE ((((((c.custcode = sl.custcode) AND (sl.posted = 'Y')) AND (sl.saleinvcode = sd.saleinvcode)) AND (sd.icode = i.icode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) GROUP BY sl.saleinvcode, sd.icode, c.custcatcode UNION ALL SELECT sl.saleinvcode AS invno, sd.icode, c.custcatcode, coalesce(sum((sd.looseqty + sd.bonusqty)), 0) AS qty, round((coalesce(sum(((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc)))) * ((1 - ((.01 * sd.discperc))))) * ((1 - ((.01 * sl.discperc)))))), 0))::numeric, 2) AS netamt FROM dbo.saleledger AS sl, dbo.saleinvdetail AS sd, (SELECT c.custcode, c.areacode, c.custcatcode FROM dbo.customer AS c WHERE ((c.areacode IN (SELECT code FROM tv_sp_custcatwisesales_tab_arealist AS tab_arealist)) AND (c.custcatcode IN (SELECT code FROM tv_sp_custcatwisesales_tab_custcatlist AS tab_custcatlist)))) AS c, (SELECT code AS icode FROM tv_sp_custcatwisesales_tab_itemlist AS tab_itemlist) AS i WHERE (((((((sl.impactinventory = 'N') AND (c.custcode = sl.custcode)) AND (sl.posted = 'Y')) AND (sl.saleinvcode = sd.saleinvcode)) AND (sd.icode = i.icode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) GROUP BY sl.saleinvcode, sd.icode, c.custcatcode UNION ALL SELECT sl.srinvcode AS invno, sd.icode, c.custcatcode, (-coalesce(sum((sd.looseqty + sd.bonusqty)), 0)) AS qty, (-round((coalesce(sum((((sd.looseqty * sd.srprice) * ((1 - ((.01 * sd.discperc))))) * ((1 - ((.01 * sl.discperc)))))), 0))::numeric, 2)) AS netamt FROM dbo.srledger AS sl, dbo.srdetail AS sd, (SELECT c.custcode, c.areacode, c.custcatcode FROM dbo.customer AS c WHERE ((c.areacode IN (SELECT code FROM tv_sp_custcatwisesales_tab_arealist AS tab_arealist)) AND (c.custcatcode IN (SELECT code FROM tv_sp_custcatwisesales_tab_custcatlist AS tab_custcatlist)))) AS c, (SELECT code AS icode FROM tv_sp_custcatwisesales_tab_itemlist AS tab_itemlist) AS i WHERE ((((((c.custcode = sl.custcode) AND (sl.posted = 'Y')) AND (sl.srinvcode = sd.srinvcode)) AND (sd.icode = i.icode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) GROUP BY sl.srinvcode, sd.icode, c.custcatcode) AS s, (SELECT * FROM dbo.item WHERE (icode IN (SELECT code FROM tv_sp_custcatwisesales_tab_itemlist AS tab_itemlist))) AS i WHERE (s.icode = i.icode) GROUP BY s.custcatcode, s.icode, i.name, i.customicode, i.packingdesc, i.icatcode, i.iccode, i.manfcode, i.packcode;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_CUSTCATWISESALESDETAIL ====
CREATE OR REPLACE FUNCTION dbo.sp_custcatwisesalesdetail(ar_startdate timestamp, ar_enddate timestamp, reportgrouping citext, grouplist citext, custcatlist citext, arealist citext, zerorows smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ar_startdate timestamp(3);
  v_ar_enddate timestamp(3);
  v_reportgrouping citext;
  v_grouplist citext;
  v_custcatlist citext;
  v_arealist citext;
  v_zerorows smallint;
  v_min_custcode integer;
  v_min_icode integer;
BEGIN
  v_ar_startdate := ar_startdate;
  v_ar_enddate := ar_enddate;
  v_reportgrouping := reportgrouping;
  v_grouplist := grouplist;
  v_custcatlist := custcatlist;
  v_arealist := arealist;
  v_zerorows := zerorows;
  DELETE FROM dbo.reportdata;
  DROP TABLE IF EXISTS tv_sp_custcatwisesalesdetail_tab_grouplist;
  CREATE TEMP TABLE tv_sp_custcatwisesalesdetail_tab_grouplist (
    code integer NOT NULL
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tv_sp_custcatwisesalesdetail_tab_custcatlist;
  CREATE TEMP TABLE tv_sp_custcatwisesalesdetail_tab_custcatlist (
    code integer NOT NULL
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tv_sp_custcatwisesalesdetail_tab_arealist;
  CREATE TEMP TABLE tv_sp_custcatwisesalesdetail_tab_arealist (
    code integer NOT NULL
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tv_sp_custcatwisesalesdetail_tab_itemlist;
  CREATE TEMP TABLE tv_sp_custcatwisesalesdetail_tab_itemlist (
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tv_sp_custcatwisesalesdetail_tab_grouplist SELECT code FROM dbo.udf_stringtotabl(v_grouplist, ',') AS udf_stringtotabl;
  INSERT INTO tv_sp_custcatwisesalesdetail_tab_custcatlist SELECT code FROM dbo.udf_stringtotabl(v_custcatlist, ',') AS udf_stringtotabl;
  INSERT INTO tv_sp_custcatwisesalesdetail_tab_arealist SELECT code FROM dbo.udf_stringtotabl(v_arealist, ',') AS udf_stringtotabl;
  INSERT INTO tv_sp_custcatwisesalesdetail_tab_itemlist SELECT code FROM dbo.udf_selectitems(v_reportgrouping, v_grouplist) AS udf_selectitems;
  v_min_custcode := coalesce((SELECT min(c.custcode) FROM dbo.customer AS c WHERE ((c.areacode IN (SELECT code FROM tv_sp_custcatwisesalesdetail_tab_arealist AS tab_arealist)) AND (c.custcatcode IN (SELECT code FROM tv_sp_custcatwisesalesdetail_tab_custcatlist AS tab_custcatlist)))), 0);
  INSERT INTO dbo.reportdata (code1, code2, code3, name1, name2, name3, name4, name5, value1, value2, value3, value4, value5, value6, value7, value8, value9, value10, value11, value12, value13) SELECT i.icode AS code1, coalesce(s.custcode, v_min_custcode) AS code2, CASE v_reportgrouping WHEN 'M' THEN i.manfcode WHEN 'C' THEN i.icatcode WHEN 'L' THEN i.iccode ELSE i.packcode END AS code3, i.name AS name1, (SELECT name FROM dbo.accounts WHERE (acccode = coalesce(s.custcode, v_min_custcode))) AS name2, CASE v_reportgrouping WHEN 'M' THEN (SELECT m.name FROM dbo.manufacturer AS m WHERE (m.manfcode = i.manfcode)) WHEN 'C' THEN (SELECT c.name FROM dbo.itemcategory AS c WHERE (c.icatcode = i.icatcode)) WHEN 'L' THEN (SELECT c.name FROM dbo.itemclass AS c WHERE (c.iccode = i.iccode)) ELSE (SELECT p.name FROM dbo.itempacking AS p WHERE (p.packcode = i.packcode)) END AS name3, i.customicode AS name4, i.packingdesc AS name5, round(((i.saleprice / CASE i.packunits WHEN 0 THEN 1 ELSE i.packunits END))::numeric, 2) AS value1, coalesce(o.qty, 0) AS value2, coalesce(o.val, 0) AS value3, coalesce(p.qty, 0) AS value4, coalesce(p.val, 0) AS value5, coalesce(pr.qty, 0) AS value6, coalesce(pr.val, 0) AS value7, coalesce(s.qty, 0) AS value8, coalesce(s.val, 0) AS value9, coalesce(sr.qty, 0) AS value10, coalesce(sr.val, 0) AS value11, coalesce(ot.qty, 0) AS value12, coalesce(ot.val, 0) AS value13 FROM (SELECT * FROM dbo.item WHERE (item.icode IN (SELECT code FROM tv_sp_custcatwisesalesdetail_tab_itemlist AS tab_itemlist))) AS i LEFT JOIN (SELECT code AS icode, coalesce(qty, 0) AS qty, coalesce(value, 0) AS val FROM dbo.udf_openingstock(v_ar_startdate, v_reportgrouping, v_grouplist, (1)::smallint) AS udf_openingstock) AS o ON ((i.icode = o.icode)) LEFT JOIN (SELECT pd.icode, coalesce(sum(((((pd.looseqty + pd.packqty) + pd.bonusqty)) * CASE pl.purcatcode WHEN 1 THEN pd.packunits WHEN 2 THEN pd.packunits ELSE 1 END)), 0) AS qty, round((coalesce(sum((((((pd.looseqty + pd.packqty)) * pd.purprice) * ((1 - ((.01 * pd.discperc))))) * ((1 - ((.01 * pl.discperc)))))), 0))::numeric, 2) AS val FROM dbo.purledger AS pl, dbo.purdetail AS pd, (SELECT code AS icode FROM tv_sp_custcatwisesalesdetail_tab_itemlist AS tab_itemlist) AS i WHERE (((((pl.posted = 'Y') AND (pl.purinvcode = pd.purinvcode)) AND (pd.icode = i.icode)) AND (pl.date >= v_ar_startdate)) AND (pl.date <= v_ar_enddate)) GROUP BY pd.icode) AS p ON ((i.icode = p.icode)) LEFT JOIN (SELECT pd.icode, coalesce(sum((pd.looseqty + pd.bonusqty)), 0) AS qty, round((coalesce(sum((((pd.looseqty * pd.prprice) * ((1 - ((.01 * pd.discperc))))) * ((1 - ((.01 * pl.discperc)))))), 0))::numeric, 2) AS val FROM dbo.prledger AS pl, dbo.prdetail AS pd, (SELECT code AS icode FROM tv_sp_custcatwisesalesdetail_tab_itemlist AS tab_itemlist) AS i WHERE (((((pl.posted = 'Y') AND (pl.prinvcode = pd.prinvcode)) AND (pd.icode = i.icode)) AND (pl.date >= v_ar_startdate)) AND (pl.date <= v_ar_enddate)) GROUP BY pd.icode) AS pr ON ((i.icode = pr.icode)) LEFT JOIN (SELECT sd.icode, coalesce(sum((sd.looseqty + sd.bonusqty)), 0) AS qty, round((coalesce(sum(((((sd.looseqty * sd.srprice)) * ((1 - ((.01 * sd.discperc))))) * ((1 - ((.01 * sl.discperc)))))), 0))::numeric, 2) AS val FROM dbo.srledger AS sl, dbo.srdetail AS sd, (SELECT code AS icode FROM tv_sp_custcatwisesalesdetail_tab_itemlist AS tab_itemlist) AS i WHERE (((((sl.posted = 'Y') AND (sl.srinvcode = sd.srinvcode)) AND (sd.icode = i.icode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) GROUP BY sd.icode) AS sr ON ((i.icode = sr.icode)) LEFT JOIN (SELECT t.icode, sum(t.qty) AS qty, sum(t.val) AS val FROM (SELECT sd.icode, (-coalesce(sum(sd.qty), 0)) AS qty, (-round((coalesce(sum((sd.qty * ((sd.saleprice / CASE sd.packunits WHEN 0 THEN 1 ELSE sd.packunits END)))), 0))::numeric, 2)) AS val FROM dbo.issueheader AS sl, dbo.issuedetail AS sd, (SELECT code AS icode FROM tv_sp_custcatwisesalesdetail_tab_itemlist AS tab_itemlist) AS i WHERE (((((sl.posted = 'Y') AND (sl.issueinvcode = sd.issueinvcode)) AND (sd.icode = i.icode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) GROUP BY sd.icode UNION ALL SELECT sd.icode, coalesce(sum(sd.qty), 0) AS qty, round((coalesce(sum((sd.qty * ((sd.saleprice / CASE sd.packunits WHEN 0 THEN 1 ELSE sd.packunits END)))), 0))::numeric, 2) AS val FROM dbo.receiptheader AS sl, dbo.receiptdetail AS sd, (SELECT code AS icode FROM tv_sp_custcatwisesalesdetail_tab_itemlist AS tab_itemlist) AS i WHERE (((((sl.posted = 'Y') AND (sl.receiptinvcode = sd.receiptinvcode)) AND (sd.icode = i.icode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) GROUP BY sd.icode UNION ALL SELECT sd.icode, coalesce(sum((sd.looseqty * CASE sl.adjcatcode WHEN 1 THEN 1 ELSE -1 END)), 0) AS qty, round((coalesce(sum(((sd.looseqty * ((sd.saleprice / CASE sd.packunits WHEN 0 THEN 1 ELSE sd.packunits END))) * CASE sl.adjcatcode WHEN 1 THEN 1 ELSE -1 END)), 0))::numeric, 2) AS val FROM dbo.adjheader AS sl, dbo.adjdetail AS sd, (SELECT code AS icode FROM tv_sp_custcatwisesalesdetail_tab_itemlist AS tab_itemlist) AS i WHERE (((((sl.posted = 'Y') AND (sl.adjcode = sd.adjcode)) AND (sd.icode = i.icode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) GROUP BY sd.icode) AS t GROUP BY t.icode) AS ot ON ((i.icode = ot.icode)) LEFT JOIN (SELECT sd.icode, c.custcode, coalesce(sum((sd.looseqty + sd.bonusqty)), 0) AS qty, round((coalesce(sum(((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc)))) * ((1 - ((.01 * sd.discperc))))) * ((1 - ((.01 * sl.discperc)))))), 0))::numeric, 2) AS val FROM dbo.saleledger AS sl, dbo.saledetail AS sd, (SELECT c.custcode FROM dbo.customer AS c WHERE ((c.areacode IN (SELECT code FROM tv_sp_custcatwisesalesdetail_tab_arealist AS tab_arealist)) AND (c.custcatcode IN (SELECT code FROM tv_sp_custcatwisesalesdetail_tab_custcatlist AS tab_custcatlist)))) AS c, (SELECT code AS icode FROM tv_sp_custcatwisesalesdetail_tab_itemlist AS tab_itemlist) AS i WHERE ((((((c.custcode = sl.custcode) AND (sl.posted = 'Y')) AND (sl.saleinvcode = sd.saleinvcode)) AND (sd.icode = i.icode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) GROUP BY c.custcode, sd.icode UNION ALL SELECT sd.icode, c.custcode, coalesce(sum((sd.looseqty + sd.bonusqty)), 0) AS qty, round((coalesce(sum(((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc)))) * ((1 - ((.01 * sd.discperc))))) * ((1 - ((.01 * sl.discperc)))))), 0))::numeric, 2) AS val FROM dbo.saleledger AS sl, dbo.saleinvdetail AS sd, (SELECT c.custcode FROM dbo.customer AS c WHERE ((c.areacode IN (SELECT code FROM tv_sp_custcatwisesalesdetail_tab_arealist AS tab_arealist)) AND (c.custcatcode IN (SELECT code FROM tv_sp_custcatwisesalesdetail_tab_custcatlist AS tab_custcatlist)))) AS c, (SELECT code AS icode FROM tv_sp_custcatwisesalesdetail_tab_itemlist AS tab_itemlist) AS i WHERE (((((((sl.impactinventory = 'N') AND (c.custcode = sl.custcode)) AND (sl.posted = 'Y')) AND (sl.saleinvcode = sd.saleinvcode)) AND (sd.icode = i.icode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) GROUP BY c.custcode, sd.icode) AS s ON ((i.icode = s.icode));
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_CUSTCATWISESALESDETAIL_CROSSTAB ====
CREATE OR REPLACE FUNCTION dbo.sp_custcatwisesalesdetail_crosstab(ar_startdate timestamp, ar_enddate timestamp, reportgrouping citext, grouplist citext, custcatcode integer, arealist citext, totcol double precision, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ar_startdate timestamp(3);
  v_ar_enddate timestamp(3);
  v_reportgrouping citext;
  v_grouplist citext;
  v_custcatcode integer;
  v_arealist citext;
  v_totcol double precision;
  v_upd citext;
  v_col citext;
  v_rowid integer;
  v_colname citext;
  v_colcode citext;
  v_str_col citext;
  v_totcols double precision;
  v_curriter integer;
  v_iterations integer;
  v_i integer;
  v_tot integer;
  v_err integer;
  v_icode integer;
  v_areacode integer;
  v_acccode integer;
  v_qty integer;
  v_val numeric(15,5);
  _dq1 text;
  cur_c1 refcursor;
  _dq2 text;
  _fs integer := -1;
BEGIN
  v_ar_startdate := ar_startdate;
  v_ar_enddate := ar_enddate;
  v_reportgrouping := reportgrouping;
  v_grouplist := grouplist;
  v_custcatcode := custcatcode;
  v_arealist := arealist;
  v_totcol := totcol;
  DELETE FROM dbo.crosstab_reportdata;
  -- SET NOCOUNT ON
  DROP TABLE IF EXISTS tv_sp_custcatwisesalesdetail_crosstab_tab_grouplist;
  CREATE TEMP TABLE tv_sp_custcatwisesalesdetail_crosstab_tab_grouplist (
    code integer NOT NULL
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tv_sp_custcatwisesalesdetail_crosstab_tab_arealist;
  CREATE TEMP TABLE tv_sp_custcatwisesalesdetail_crosstab_tab_arealist (
    code integer NOT NULL
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tv_sp_custcatwisesalesdetail_crosstab_tab_itemlist;
  CREATE TEMP TABLE tv_sp_custcatwisesalesdetail_crosstab_tab_itemlist (
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tv_sp_custcatwisesalesdetail_crosstab_tab_grouplist SELECT code FROM dbo.udf_stringtotabl(v_grouplist, ',') AS udf_stringtotabl;
  INSERT INTO tv_sp_custcatwisesalesdetail_crosstab_tab_arealist SELECT code FROM dbo.udf_stringtotabl(v_arealist, ',') AS udf_stringtotabl;
  INSERT INTO tv_sp_custcatwisesalesdetail_crosstab_tab_itemlist SELECT code FROM dbo.udf_selectitems(v_reportgrouping, v_grouplist) AS udf_selectitems;
  DROP TABLE IF EXISTS tv_sp_custcatwisesalesdetail_crosstab_coltable;
  CREATE TEMP TABLE tv_sp_custcatwisesalesdetail_crosstab_coltable (
    code integer,
    name citext,
    rowid integer GENERATED BY DEFAULT AS IDENTITY
) ON COMMIT DROP;
  v_totcols := coalesce((SELECT count(a.acccode) FROM dbo.accounts AS a, dbo.customer AS c, tv_sp_custcatwisesalesdetail_crosstab_tab_arealist AS ar WHERE (((((a.subcode = 3) AND (a.acccode = c.custcode)) AND (a.active = 'Y')) AND (c.custcatcode = v_custcatcode)) AND (ar.code = c.areacode))), 0);
  IF ((v_totcols > 0) AND (v_totcol > 0)) THEN
    v_tot := trunc((SELECT min(a) FROM (SELECT v_totcol AS a UNION SELECT v_totcols AS a) AS t))::integer;
    INSERT INTO tv_sp_custcatwisesalesdetail_crosstab_coltable (code, name) SELECT a.acccode, a.name AS name FROM dbo.accounts AS a, dbo.customer AS c, tv_sp_custcatwisesalesdetail_crosstab_tab_arealist AS ar WHERE (((((a.subcode = 3) AND (a.acccode = c.custcode)) AND (a.active = 'Y')) AND (c.custcatcode = v_custcatcode)) AND (ar.code = c.areacode)) ORDER BY a.name;
    v_iterations := trunc(ceiling((v_totcols / v_totcol)))::integer;
    v_curriter := 1;
    v_rowid := 0;
    INSERT INTO dbo.crosstab_reportdata (code1, code2) SELECT code, 0 FROM tv_sp_custcatwisesalesdetail_crosstab_tab_itemlist AS tab_itemlist;
    WHILE (v_curriter <= v_iterations) LOOP
      INSERT INTO dbo.crosstab_reportdata (code1, code2) SELECT code, v_curriter FROM tv_sp_custcatwisesalesdetail_crosstab_tab_itemlist AS tab_itemlist;
      v_i := 1;
      WHILE (v_i <= v_tot) LOOP
        v_rowid := (v_rowid + 1);
        v_colname := rtrim(ltrim(coalesce((SELECT name FROM tv_sp_custcatwisesalesdetail_crosstab_coltable AS coltable WHERE (rowid = v_rowid)), '')));
        v_colcode := rtrim(ltrim(dbo.tsql_str(((SELECT code FROM tv_sp_custcatwisesalesdetail_crosstab_coltable AS coltable WHERE (rowid = v_rowid)))::numeric, 10)));
        IF (v_colcode IS NULL) THEN
          EXIT;
        ELSE
          v_str_col := ltrim(rtrim(dbo.tsql_str((v_i)::numeric, 7)));
          v_upd := ((((((((('UPDATE CrossTab_ReportData SET C_Name' || v_str_col) || ' = ''') || v_colname) || ''', C_Code') || v_str_col) || ' = ') || v_colcode) || ' WHERE CODE2 = ') || ltrim(rtrim(dbo.tsql_str((v_curriter)::numeric, 7))));
          _dq1 := v_upd;
          IF _dq1 IS NOT NULL THEN
            EXECUTE dbo.tsql_dyn(_dq1);
          END IF;
          v_err := 0;
          IF (v_err <> 0) THEN
            v_upd := ('CROSSTAB GENERATE ERROR, DETAILS: ' || v_upd);
            RAISE EXCEPTION '%', v_upd;
            return_value := -1;
            RETURN;
          END IF;
          v_i := (v_i + 1);
        END IF;
      END LOOP;
      v_curriter := (v_curriter + 1);
    END LOOP;
    UPDATE dbo.crosstab_reportdata AS c SET value2 = k.oqty, value3 = k.oval, value4 = k.pqty, value5 = k.pval, value6 = k.prqty, value7 = k.prval, value8 = k.sqty, value9 = k.sval, value10 = k.srqty, value11 = k.srval, value12 = k.otqty, value13 = k.otval FROM (SELECT i.icode AS icode, coalesce(o.qty, 0) AS oqty, coalesce(o.val, 0) AS oval, coalesce(p.qty, 0) AS pqty, coalesce(p.val, 0) AS pval, coalesce(pr.qty, 0) AS prqty, coalesce(pr.val, 0) AS prval, coalesce(s.qty, 0) AS sqty, coalesce(s.val, 0) AS sval, coalesce(sr.qty, 0) AS srqty, coalesce(sr.val, 0) AS srval, coalesce(ot.qty, 0) AS otqty, coalesce(ot.val, 0) AS otval FROM (SELECT * FROM dbo.item WHERE (item.icode IN (SELECT code FROM tv_sp_custcatwisesalesdetail_crosstab_tab_itemlist AS tab_itemlist))) AS i LEFT JOIN (SELECT code AS icode, coalesce(qty, 0) AS qty, coalesce(value, 0) AS val FROM dbo.udf_openingstock(v_ar_startdate, v_reportgrouping, v_grouplist, (1)::smallint) AS udf_openingstock) AS o ON ((i.icode = o.icode)) LEFT JOIN (SELECT pd.icode, coalesce(sum(((((pd.looseqty + pd.packqty) + pd.bonusqty)) * CASE pl.purcatcode WHEN 1 THEN pd.packunits WHEN 2 THEN pd.packunits ELSE 1 END)), 0) AS qty, round((coalesce(sum((((((pd.looseqty + pd.packqty)) * pd.purprice) * ((1 - ((.01 * pd.discperc))))) * ((1 - ((.01 * pl.discperc)))))), 0))::numeric, 2) AS val FROM dbo.purledger AS pl, dbo.purdetail AS pd, (SELECT code AS icode FROM tv_sp_custcatwisesalesdetail_crosstab_tab_itemlist AS tab_itemlist) AS i WHERE (((((pl.posted = 'Y') AND (pl.purinvcode = pd.purinvcode)) AND (pd.icode = i.icode)) AND (pl.date >= v_ar_startdate)) AND (pl.date <= v_ar_enddate)) GROUP BY pd.icode) AS p ON ((i.icode = p.icode)) LEFT JOIN (SELECT pd.icode, coalesce(sum((pd.looseqty + pd.bonusqty)), 0) AS qty, round((coalesce(sum((((pd.looseqty * pd.prprice) * ((1 - ((.01 * pd.discperc))))) * ((1 - ((.01 * pl.discperc)))))), 0))::numeric, 2) AS val FROM dbo.prledger AS pl, dbo.prdetail AS pd, (SELECT code AS icode FROM tv_sp_custcatwisesalesdetail_crosstab_tab_itemlist AS tab_itemlist) AS i WHERE (((((pl.posted = 'Y') AND (pl.prinvcode = pd.prinvcode)) AND (pd.icode = i.icode)) AND (pl.date >= v_ar_startdate)) AND (pl.date <= v_ar_enddate)) GROUP BY pd.icode) AS pr ON ((i.icode = pr.icode)) LEFT JOIN (SELECT t.icode, sum(t.qty) AS qty, sum(t.val) AS val FROM (SELECT sd.icode, (-coalesce(sum(sd.qty), 0)) AS qty, (-round((coalesce(sum((sd.qty * ((sd.saleprice / CASE sd.packunits WHEN 0 THEN 1 ELSE sd.packunits END)))), 0))::numeric, 2)) AS val FROM dbo.issueheader AS sl, dbo.issuedetail AS sd, (SELECT code AS icode FROM tv_sp_custcatwisesalesdetail_crosstab_tab_itemlist AS tab_itemlist) AS i WHERE (((((sl.posted = 'Y') AND (sl.issueinvcode = sd.issueinvcode)) AND (sd.icode = i.icode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) GROUP BY sd.icode UNION ALL SELECT sd.icode, coalesce(sum(sd.qty), 0) AS qty, round((coalesce(sum((sd.qty * ((sd.saleprice / CASE sd.packunits WHEN 0 THEN 1 ELSE sd.packunits END)))), 0))::numeric, 2) AS val FROM dbo.receiptheader AS sl, dbo.receiptdetail AS sd, (SELECT code AS icode FROM tv_sp_custcatwisesalesdetail_crosstab_tab_itemlist AS tab_itemlist) AS i WHERE (((((sl.posted = 'Y') AND (sl.receiptinvcode = sd.receiptinvcode)) AND (sd.icode = i.icode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) GROUP BY sd.icode UNION ALL SELECT sd.icode, coalesce(sum((sd.looseqty * CASE sl.adjcatcode WHEN 1 THEN 1 ELSE -1 END)), 0) AS qty, round((coalesce(sum(((sd.looseqty * ((sd.saleprice / CASE sd.packunits WHEN 0 THEN 1 ELSE sd.packunits END))) * CASE sl.adjcatcode WHEN 1 THEN 1 ELSE -1 END)), 0))::numeric, 2) AS val FROM dbo.adjheader AS sl, dbo.adjdetail AS sd, (SELECT code AS icode FROM tv_sp_custcatwisesalesdetail_crosstab_tab_itemlist AS tab_itemlist) AS i WHERE (((((sl.posted = 'Y') AND (sl.adjcode = sd.adjcode)) AND (sd.icode = i.icode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) GROUP BY sd.icode) AS t GROUP BY t.icode) AS ot ON ((i.icode = ot.icode)) LEFT JOIN (SELECT sd.icode AS icode, coalesce(sum((sd.looseqty + sd.bonusqty)), 0) AS qty, round((coalesce(sum(((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc)))) * ((1 - ((.01 * sd.discperc))))) * ((1 - ((.01 * sl.discperc)))))), 0))::numeric, 2) AS val FROM dbo.saleledger AS sl, dbo.saledetail AS sd, (SELECT c.custcode FROM dbo.customer AS c WHERE ((c.areacode IN (SELECT code FROM tv_sp_custcatwisesalesdetail_crosstab_tab_arealist AS tab_arealist)) AND (c.custcatcode = v_custcatcode))) AS c, (SELECT code AS icode FROM tv_sp_custcatwisesalesdetail_crosstab_tab_itemlist AS tab_itemlist) AS i WHERE ((((((c.custcode = sl.custcode) AND (sl.posted = 'Y')) AND (sl.saleinvcode = sd.saleinvcode)) AND (sd.icode = i.icode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) GROUP BY sd.icode) AS s ON ((i.icode = s.icode)) LEFT JOIN (SELECT sd.icode AS icode, coalesce(sum((sd.looseqty + sd.bonusqty)), 0) AS qty, round((coalesce(sum(((((sd.looseqty * sd.srprice)) * ((1 - ((.01 * sd.discperc))))) * ((1 - ((.01 * sl.discperc)))))), 0))::numeric, 2) AS val FROM dbo.srledger AS sl, dbo.srdetail AS sd, (SELECT c.custcode FROM dbo.customer AS c WHERE ((c.areacode IN (SELECT code FROM tv_sp_custcatwisesalesdetail_crosstab_tab_arealist AS tab_arealist)) AND (c.custcatcode = v_custcatcode))) AS c, (SELECT code AS icode FROM tv_sp_custcatwisesalesdetail_crosstab_tab_itemlist AS tab_itemlist) AS i WHERE ((((((c.custcode = sl.custcode) AND (sl.posted = 'Y')) AND (sl.srinvcode = sd.srinvcode)) AND (sd.icode = i.icode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) GROUP BY sd.icode) AS sr ON ((i.icode = sr.icode))) AS k WHERE (c.code1 = k.icode);
    OPEN cur_c1 FOR SELECT sd.icode AS icode, c.custcode AS acccode, coalesce(sum((sd.looseqty + sd.bonusqty)), 0) AS qty, round((coalesce(sum(((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc)))) * ((1 - ((.01 * sd.discperc))))) * ((1 - ((.01 * sl.discperc)))))), 0))::numeric, 2) AS val FROM dbo.saleledger AS sl, dbo.saledetail AS sd, (SELECT c.custcode FROM dbo.customer AS c WHERE ((c.areacode IN (SELECT code FROM tv_sp_custcatwisesalesdetail_crosstab_tab_arealist AS tab_arealist)) AND (c.custcatcode = v_custcatcode))) AS c, (SELECT code AS icode FROM tv_sp_custcatwisesalesdetail_crosstab_tab_itemlist AS tab_itemlist) AS i WHERE ((((((c.custcode = sl.custcode) AND (sl.posted = 'Y')) AND (sl.saleinvcode = sd.saleinvcode)) AND (sd.icode = i.icode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) GROUP BY c.custcode, sd.icode;
    FETCH NEXT FROM cur_c1 INTO v_icode, v_acccode, v_qty, v_val;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    WHILE (_fs = 0) LOOP
      v_i := 1;
      WHILE (v_i <= v_tot) LOOP
        v_colcode := ltrim(rtrim(dbo.tsql_str((v_icode)::numeric, 7)));
        v_colname := ltrim(rtrim(dbo.tsql_str((v_acccode)::numeric, 7)));
        v_str_col := ltrim(rtrim(dbo.tsql_str((v_i)::numeric, 7)));
        v_upd := ((((((((((((((((((('UPDATE CrossTab_ReportData SET ' || 'QTY') || v_str_col) || ' = ') || ltrim(rtrim(dbo.tsql_str((v_qty)::numeric, 10)))) || ', VAL') || v_str_col) || ' = ') || ltrim(rtrim(dbo.tsql_str((v_val)::numeric, 15, 5)))) || ', C_Code') || v_str_col) || ' = ') || v_colname) || ' WHERE CODE2 > 0 AND CODE1 = ') || v_colcode) || ' AND ') || ' C_Code') || v_str_col) || ' = ') || v_colname);
        _dq2 := v_upd;
        IF _dq2 IS NOT NULL THEN
          EXECUTE dbo.tsql_dyn(_dq2);
        END IF;
        v_err := 0;
        IF (v_err <> 0) THEN
          v_upd := ('CROSSTAB PLOTING ERROR, DETAILS: ' || v_upd);
          RAISE EXCEPTION '%', v_upd;
          CLOSE cur_c1;
          -- DEALLOCATE C1
          return_value := -1;
          RETURN;
        END IF;
        v_i := (v_i + 1);
      END LOOP;
      FETCH NEXT FROM cur_c1 INTO v_icode, v_acccode, v_qty, v_val;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    END LOOP;
    CLOSE cur_c1;
    -- DEALLOCATE C1
    UPDATE dbo.crosstab_reportdata AS c SET name1 = i.name, name2 = i.customicode, name3 = i.packingdesc, name4 = (SELECT name FROM dbo.customercategory WHERE (custcatcode = v_custcatcode)), code5 = CASE v_reportgrouping WHEN 'M' THEN i.manfcode WHEN 'C' THEN i.icatcode WHEN 'L' THEN i.iccode ELSE i.packcode END, name5 = CASE v_reportgrouping WHEN 'M' THEN (SELECT m.name FROM dbo.manufacturer AS m WHERE (m.manfcode = i.manfcode)) WHEN 'C' THEN (SELECT c.name FROM dbo.itemcategory AS c WHERE (c.icatcode = i.icatcode)) WHEN 'L' THEN (SELECT c.name FROM dbo.itemclass AS c WHERE (c.iccode = i.iccode)) ELSE (SELECT p.name FROM dbo.itempacking AS p WHERE (p.packcode = i.packcode)) END, value1 = round(((i.saleprice / CASE i.packunits WHEN 0 THEN 1 ELSE i.packunits END))::numeric, 2) FROM dbo.item AS i WHERE (i.icode = c.code1);
    PERFORM dbo.sp_update_total_crosstab_reportdata();
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_CustGroup_ItemGroup_NetSale_CrossTab ====
CREATE OR REPLACE FUNCTION dbo.sp_custgroup_itemgroup_netsale_crosstab(custgroupcode integer, itemgroupcode integer, startdate timestamp, enddate timestamp, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_custgroupcode integer;
  v_itemgroupcode integer;
  v_startdate timestamp(3);
  v_enddate timestamp(3);
  v_upd citext;
  v_col citext;
  v_rowid integer;
  v_colname citext;
  v_colcode citext;
  v_str_col citext;
  v_totitems double precision;
  v_curriter integer;
  v_iterations integer;
  v_i integer;
  v_tot integer;
  v_icode integer;
  v_custcode integer;
  v_qty integer;
  v_val numeric(15,5);
  v_err integer;
  v_totcol smallint;
  _dq1 text;
  cur_c1 refcursor;
  _dq2 text;
  _fs integer := -1;
BEGIN
  v_custgroupcode := custgroupcode;
  v_itemgroupcode := itemgroupcode;
  v_startdate := startdate;
  v_enddate := enddate;
  DELETE FROM dbo.crosstab_reportdata;
  -- SET NOCOUNT ON
  DROP TABLE IF EXISTS tv_sp_custgroup_itemgroup_netsale_crosstab_coltable;
  CREATE TEMP TABLE tv_sp_custgroup_itemgroup_netsale_crosstab_coltable (
    code integer,
    shortname citext,
    rowid integer GENERATED BY DEFAULT AS IDENTITY
) ON COMMIT DROP;
  v_totitems := coalesce((SELECT count(icode) FROM dbo.itemgroupdetail WHERE (itemgroupcode = v_custgroupcode)), 0);
  v_totcol := 12;
  IF (v_totitems > 0) THEN
    v_tot := trunc((SELECT min(a) FROM (SELECT v_totcol AS a UNION SELECT v_totitems AS a) AS t))::integer;
    INSERT INTO tv_sp_custgroup_itemgroup_netsale_crosstab_coltable (code, shortname) SELECT icode, shortname AS name FROM dbo.item WHERE (icode IN (SELECT icode FROM dbo.itemgroupdetail WHERE (itemgroupcode = v_itemgroupcode))) ORDER BY shortname;
    v_iterations := trunc(ceiling((v_totitems / v_totcol)))::integer;
    v_curriter := 1;
    v_rowid := 0;
    WHILE (v_curriter <= v_iterations) LOOP
      INSERT INTO dbo.crosstab_reportdata (code1, code2, code3, code5) SELECT custcode, v_curriter, v_custgroupcode, v_itemgroupcode FROM dbo.customergroupdetail WHERE (customergroupcode = v_custgroupcode);
      v_i := 1;
      WHILE (v_i <= v_tot) LOOP
        v_rowid := (v_rowid + 1);
        v_colname := rtrim(ltrim(coalesce((SELECT shortname FROM tv_sp_custgroup_itemgroup_netsale_crosstab_coltable AS coltable WHERE (rowid = v_rowid)), '')));
        v_colcode := rtrim(ltrim(dbo.tsql_str(((SELECT code FROM tv_sp_custgroup_itemgroup_netsale_crosstab_coltable AS coltable WHERE (rowid = v_rowid)))::numeric, 7)));
        IF (v_colcode IS NULL) THEN
          EXIT;
        ELSE
          v_str_col := ltrim(rtrim(dbo.tsql_str((v_i)::numeric, 7)));
          v_upd := ((((((((('UPDATE CrossTab_ReportData SET C_Name' || v_str_col) || ' = ''') || v_colname) || ''', C_Code') || v_str_col) || ' = ') || v_colcode) || ' WHERE CODE2 = ') || ltrim(rtrim(dbo.tsql_str((v_curriter)::numeric, 7))));
          _dq1 := v_upd;
          IF _dq1 IS NOT NULL THEN
            EXECUTE dbo.tsql_dyn(_dq1);
          END IF;
          v_err := 0;
          IF (v_err <> 0) THEN
            v_upd := ('UPDATION ERROR, DETAILS: ' || v_upd);
            RAISE EXCEPTION '%', v_upd;
            return_value := -1;
            RETURN;
          END IF;
          v_i := (v_i + 1);
        END IF;
      END LOOP;
      v_curriter := (v_curriter + 1);
    END LOOP;
    OPEN cur_c1 FOR SELECT s.icode, s.custcode, coalesce(sum(s.qty), 0) AS qty, coalesce(sum(s.netamt), 0) AS val FROM (SELECT sl.saleinvcode AS invno, sd.icode, sl.custcode AS custcode, coalesce(sum((sd.looseqty + sd.bonusqty)), 0) AS qty, round((coalesce((sum((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc)))) * ((1 - ((.01 * sd.discperc)))))) * ((1 - ((.01 * sl.discperc))))), 0))::numeric, 2) AS netamt FROM dbo.saleledger AS sl, dbo.saledetail AS sd, dbo.customer AS c WHERE ((((((c.custcode IN (SELECT custcode FROM dbo.customergroupdetail WHERE (customergroupcode = v_custgroupcode))) AND (c.custcode = sl.custcode)) AND (sl.posted = 'Y')) AND (sl.saleinvcode = sd.saleinvcode)) AND (sl.date BETWEEN v_startdate AND v_enddate)) AND (sd.icode IN (SELECT icode FROM dbo.itemgroupdetail WHERE (itemgroupcode = v_itemgroupcode)))) GROUP BY sl.saleinvcode, sd.icode, sl.custcode, sl.discperc UNION ALL SELECT sl.srinvcode AS invno, sd.icode, sl.custcode AS custcode, (-coalesce(sum((sd.looseqty + sd.bonusqty)), 0)) AS qty, (-round((coalesce((sum((((sd.looseqty * sd.srprice)) * ((1 - ((.01 * sd.discperc)))))) * ((1 - ((.01 * sl.discperc))))), 0))::numeric, 2)) AS netamt FROM dbo.srledger AS sl, dbo.srdetail AS sd, dbo.customer AS c WHERE ((((((c.custcode IN (SELECT custcode FROM dbo.customergroupdetail WHERE (customergroupcode = v_custgroupcode))) AND (c.custcode = sl.custcode)) AND (sl.posted = 'Y')) AND (sl.srinvcode = sd.srinvcode)) AND (sl.date BETWEEN v_startdate AND v_enddate)) AND (sd.icode IN (SELECT icode FROM dbo.itemgroupdetail WHERE (itemgroupcode = v_itemgroupcode)))) GROUP BY sl.srinvcode, sd.icode, sl.custcode, sl.discperc) AS s, dbo.accounts AS a WHERE (s.custcode = a.acccode) GROUP BY s.custcode, s.icode ORDER BY s.custcode, s.icode;
    FETCH NEXT FROM cur_c1 INTO v_icode, v_custcode, v_qty, v_val;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    WHILE (_fs = 0) LOOP
      v_i := 1;
      WHILE (v_i <= v_tot) LOOP
        v_colcode := ltrim(rtrim(dbo.tsql_str((v_custcode)::numeric, 7)));
        v_colname := ltrim(rtrim(dbo.tsql_str((v_icode)::numeric, 7)));
        v_str_col := ltrim(rtrim(dbo.tsql_str((v_i)::numeric, 7)));
        v_upd := ((((((((((((((((((('UPDATE CrossTab_ReportData SET ' || 'QTY') || v_str_col) || ' = ') || ltrim(rtrim(dbo.tsql_str((v_qty)::numeric, 7)))) || ', VAL') || v_str_col) || ' = ') || ltrim(rtrim(dbo.tsql_str((v_val)::numeric, 15, 5)))) || ', C_Code') || v_str_col) || ' = ') || v_colname) || ' WHERE CODE1 = ') || v_colcode) || ' AND ') || ' C_Code') || v_str_col) || ' = ') || v_colname);
        _dq2 := v_upd;
        IF _dq2 IS NOT NULL THEN
          EXECUTE dbo.tsql_dyn(_dq2);
        END IF;
        v_err := 0;
        IF (v_err <> 0) THEN
          v_upd := ('CROSSTAB PLOTING ERROR, DETAILS: ' || v_upd);
          RAISE EXCEPTION '%', v_upd;
          CLOSE cur_c1;
          -- DEALLOCATE C1
          return_value := -1;
          RETURN;
        END IF;
        v_i := (v_i + 1);
      END LOOP;
      FETCH NEXT FROM cur_c1 INTO v_icode, v_custcode, v_qty, v_val;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    END LOOP;
    CLOSE cur_c1;
    -- DEALLOCATE C1
    UPDATE dbo.crosstab_reportdata AS c SET name1 = a.name, name2 = a.aliasname, name3 = NULL::citext, name4 = (SELECT name FROM dbo.customergroup WHERE (customergroupcode = v_custgroupcode)), name5 = (SELECT name FROM dbo.itemgroup WHERE (itemgroupcode = v_itemgroupcode)) FROM dbo.accounts AS a WHERE (a.acccode = c.code1);
    PERFORM dbo.sp_update_total_crosstab_reportdata();
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_Customer_Sale_Accounts ====
CREATE OR REPLACE FUNCTION dbo.sp_customer_sale_accounts(ad_date timestamp, ad_ldate timestamp, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ad_date timestamp(3);
  v_ad_ldate timestamp(3);
BEGIN
  v_ad_date := ad_date;
  v_ad_ldate := ad_ldate;
  DROP TABLE IF EXISTS tmp_lt_pvamts;
  CREATE TEMP TABLE tmp_lt_pvamts (
    debit numeric(15,2) NOT NULL,
    credit numeric(15,2) NOT NULL,
    code numeric(5,0) NOT NULL,
    name citext NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_pvamts SELECT coalesce((round((((sum((saledetail.looseqty * saledetail.unitsalestax)) + sum(round(((((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc))))) * saledetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc)))))) * ((1 - ((.01 * saleledger.discperc))))) - saleledger.flatdisc)) * ((saleledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) + round((((((sum((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc)))))) * ((1 - ((.01 * saleledger.discperc))))) + saleledger.misccharges) + saleledger.salestax) - saleledger.flatdisc))::numeric, 0)), 0) AS debit, 0.0 AS credit, saleledger.custcode AS custcode, (SELECT accounts.name FROM dbo.accounts WHERE (acccode = saleledger.custcode)) AS name FROM dbo.saleledger, dbo.saledetail WHERE ((((saleledger.saleinvcode = saledetail.saleinvcode) AND (saleledger.salecatcode = 2)) AND (saleledger.date < v_ad_date)) AND (saleledger.posted = 'Y')) GROUP BY saleledger.saleinvcode, salecatcode, saleledger.custcode, saleledger.date, saleledger.discperc, saleledger.misccharges, saleledger.salestax, saleledger.invgstperc1, saleledger.flatdisc;
  INSERT INTO tmp_lt_pvamts SELECT 0.0 AS debit, coalesce((round((((sum((srdetail.looseqty * srdetail.unitsalestax)) + sum(round(((((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc))))) * srdetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc)))))) * ((1 - ((.01 * srledger.discperc))))) - srledger.flatdisc)) * ((srledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) + round((((((sum((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc)))))) * ((1 - ((.01 * srledger.discperc))))) + srledger.misccharges) + srledger.salestax) - srledger.flatdisc))::numeric, 0)), 0) AS credit, srledger.custcode AS custcode, (SELECT accounts.name FROM dbo.accounts WHERE (acccode = srledger.custcode)) AS name FROM dbo.srledger, dbo.srdetail WHERE ((((srledger.srinvcode = srdetail.srinvcode) AND (srledger.srcatcode = 7)) AND (srledger.date < v_ad_date)) AND (srledger.posted = 'Y')) GROUP BY srledger.srinvcode, srledger.srcatcode, srledger.custcode, srledger.date, srledger.discperc, srledger.misccharges, srledger.salestax, srledger.invgstperc1, srledger.flatdisc;
  INSERT INTO tmp_lt_pvamts SELECT coalesce((((sum((coalesce(servicedetail.price, 0) * ((1 - ((.01 * servicedetail.discperc)))))) * ((1 - ((.01 * serviceheader.discperc))))) + serviceheader.misccharges) - serviceheader.flatdisc), 0) AS debit, 0.0 AS credit, serviceheader.custcode AS custcode, (SELECT accounts.name FROM dbo.accounts WHERE (acccode = serviceheader.custcode)) AS name FROM dbo.serviceheader, dbo.servicedetail WHERE ((((serviceheader.serviceinvcode = servicedetail.serviceinvcode) AND (serviceheader.servicecatcode = 11)) AND (serviceheader.date < v_ad_date)) AND (serviceheader.posted = 'Y')) GROUP BY serviceheader.serviceinvcode, serviceheader.servicecatcode, serviceheader.custcode, serviceheader.date, serviceheader.discperc, serviceheader.misccharges, serviceheader.flatdisc;
  INSERT INTO tmp_lt_pvamts SELECT 0.0 AS debit, coalesce((((sum((coalesce(servicerdetail.serviceprice, 0) * ((1 - ((.01 * servicerdetail.discperc)))))) * ((1 - ((.01 * servicerheader.discperc))))) + servicerheader.misccharges) - servicerheader.flatdisc), 0) AS credit, servicerheader.custcode AS custcode, (SELECT accounts.name FROM dbo.accounts WHERE (acccode = servicerheader.custcode)) AS name FROM dbo.servicerheader, dbo.servicerdetail WHERE ((((servicerheader.servicerinvcode = servicerdetail.servicerinvcode) AND (servicerheader.servicercatcode = 14)) AND (servicerheader.date < v_ad_date)) AND (servicerheader.posted = 'Y')) GROUP BY servicerheader.servicerinvcode, servicerheader.servicercatcode, servicerheader.custcode, servicerheader.date, servicerheader.discperc, servicerheader.misccharges, servicerheader.flatdisc;
  INSERT INTO tmp_lt_pvamts SELECT coalesce(sum(gldetail.debit), 0), coalesce(sum(gldetail.credit), 0), gldetail.acccode AS custcode, (SELECT accounts.name FROM dbo.accounts WHERE (accounts.acccode = gldetail.acccode)) AS name FROM dbo.glheader, dbo.gldetail WHERE ((((glheader.glvochcode = gldetail.glvochcode) AND (glheader.date < v_ad_date)) AND (glheader.posted = 'Y')) AND (gldetail.acccode IN (SELECT custcode FROM dbo.customer))) GROUP BY gldetail.acccode;
  INSERT INTO tmp_lt_pvamts SELECT 0, coalesce(sum(notes.amount), 0), notes.acccode AS custcode, (SELECT accounts.name FROM dbo.accounts WHERE (accounts.acccode = notes.acccode)) AS name FROM dbo.notes WHERE ((((notes.notecatcode = 1) AND (notes.posted = 'Y')) AND (notes.postdate < v_ad_date)) AND (notes.acccode IN (SELECT custcode FROM dbo.customer))) GROUP BY notes.acccode;
  DELETE FROM dbo.reportdata;
  INSERT INTO dbo.reportdata (code1, name1, value1, value2, value3, value4, value5, value6, value7, value8) SELECT code, name, coalesce((sum(debit) - sum(credit)), 0), 0, 0, 0, 0, 0, 0, 0 FROM tmp_lt_pvamts AS lt_pvamts GROUP BY name, code;
  INSERT INTO dbo.reportdata (code1, value1, value2, value3, value4, value5, value6, value7, value8) SELECT customer.custcode, 0, 0, 0, 0, 0, 0, 0, 0 FROM dbo.customer WHERE (customer.custcode NOT IN (SELECT code1 FROM dbo.reportdata));
  UPDATE dbo.reportdata AS reportdata SET name1 = accounts.name FROM dbo.accounts WHERE ((reportdata.name1 = NULL) AND (reportdata.code1 = accounts.acccode));
  UPDATE dbo.reportdata SET code2 = customer.areacode FROM dbo.customer WHERE (reportdata.code1 = customer.custcode);
  UPDATE dbo.reportdata AS reportdata SET value7 = saleh.amount FROM (SELECT sum(sale.amount) AS amount, sale.custcode AS customercode FROM (SELECT customer.custcode AS custcode, coalesce((round((((sum((saledetail.looseqty * saledetail.unitsalestax)) + sum(round(((((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc))))) * saledetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc)))))) * ((1 - ((.01 * saleledger.discperc))))) - saleledger.flatdisc)) * ((saleledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) + round((((((sum((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc)))))) * ((1 - ((.01 * saleledger.discperc))))) + saleledger.misccharges) + saleledger.salestax) - saleledger.flatdisc))::numeric, 0)), 0) AS amount FROM dbo.saleledger, dbo.saledetail, dbo.customer WHERE ((((((saleledger.saleinvcode = saledetail.saleinvcode) AND (saleledger.salecatcode = 2)) AND (saleledger.posted = 'Y')) AND (saleledger.date >= v_ad_date)) AND (saleledger.date <= v_ad_ldate)) AND (saleledger.custcode = customer.custcode)) GROUP BY saleledger.saleinvcode, salecatcode, saleledger.date, saleledger.discperc, saleledger.misccharges, saleledger.salestax, saleledger.flatdisc, saleledger.invgstperc1, customer.custcode) AS sale GROUP BY sale.custcode) AS saleh WHERE (reportdata.code1 = saleh.customercode);
  UPDATE dbo.reportdata AS reportdata SET value2 = salereturnh.amount FROM (SELECT sum(salereturn.amount) AS amount, salereturn.custcode AS customercode FROM (SELECT customer.custcode AS custcode, coalesce((round((((sum((srdetail.looseqty * srdetail.unitsalestax)) + sum(round(((((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc))))) * srdetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc)))))) * ((1 - ((.01 * srledger.discperc))))) - srledger.flatdisc)) * ((srledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) + round((((((sum((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc)))))) * ((1 - ((.01 * srledger.discperc))))) + srledger.misccharges) + srledger.salestax) - srledger.flatdisc))::numeric, 0)), 0) AS amount FROM dbo.srledger, dbo.srdetail, dbo.customer WHERE ((((((srledger.srinvcode = srdetail.srinvcode) AND (srledger.srcatcode = 7)) AND (srledger.posted = 'Y')) AND (srledger.date >= v_ad_date)) AND (srledger.date <= v_ad_ldate)) AND (srledger.custcode = customer.custcode)) GROUP BY srledger.srinvcode, srledger.srcatcode, srledger.date, srledger.discperc, srledger.misccharges, srledger.salestax, srledger.invgstperc1, srledger.flatdisc, customer.custcode) AS salereturn GROUP BY salereturn.custcode) AS salereturnh WHERE (reportdata.code1 = salereturnh.customercode);
  UPDATE dbo.reportdata AS reportdata SET value3 = recieved.amount FROM (SELECT customer.custcode AS customercode, CASE sum(round((gldetail.credit)::numeric, 0)) WHEN NULL THEN 0.0 ELSE sum(round((gldetail.credit)::numeric, 0)) END AS amount FROM dbo.glheader, dbo.gldetail, dbo.customer WHERE ((((((glheader.posted = 'Y') AND (glheader.vochcatcode IN (2, 4))) AND (glheader.date >= v_ad_date)) AND (glheader.date <= v_ad_ldate)) AND (glheader.glvochcode = gldetail.glvochcode)) AND (gldetail.acccode = customer.custcode)) GROUP BY customer.custcode) AS recieved WHERE (reportdata.code1 = recieved.customercode);
  UPDATE dbo.reportdata AS reportdata SET value4 = adjustment.amount FROM (SELECT customer.custcode AS customercode, coalesce(sum(round((gldetail.debit)::numeric, 0)), 0) AS amount FROM dbo.glheader, dbo.gldetail, dbo.customer WHERE ((((((glheader.posted = 'Y') AND (glheader.vochcatcode IN (5, 8, 10, 1, 3))) AND (glheader.date >= v_ad_date)) AND (glheader.date <= v_ad_ldate)) AND (glheader.glvochcode = gldetail.glvochcode)) AND (gldetail.acccode = customer.custcode)) GROUP BY customer.custcode) AS adjustment WHERE (reportdata.code1 = adjustment.customercode);
  UPDATE dbo.reportdata AS reportdata SET value8 = adjustment.amount FROM (SELECT customer.custcode AS customercode, coalesce(sum(round((gldetail.credit)::numeric, 0)), 0) AS amount FROM dbo.glheader, dbo.gldetail, dbo.customer WHERE ((((((glheader.posted = 'Y') AND (glheader.vochcatcode IN (5, 8, 10))) AND (glheader.date >= v_ad_date)) AND (glheader.date <= v_ad_ldate)) AND (glheader.glvochcode = gldetail.glvochcode)) AND (gldetail.acccode = customer.custcode)) GROUP BY customer.custcode) AS adjustment WHERE (reportdata.code1 = adjustment.customercode);
  UPDATE dbo.reportdata AS reportdata SET value5 = serviceh.amount FROM (SELECT sum(service.amount) AS amount, service.custcode AS customercode FROM (SELECT serviceheader.custcode AS custcode, coalesce((((sum((coalesce(servicedetail.price, 0) * ((1 - ((.01 * servicedetail.discperc)))))) * ((1 - ((.01 * serviceheader.discperc))))) + serviceheader.misccharges) - serviceheader.flatdisc), 0) AS amount FROM dbo.serviceheader, dbo.servicedetail, dbo.customer WHERE ((((((serviceheader.serviceinvcode = servicedetail.serviceinvcode) AND (serviceheader.servicecatcode = 11)) AND (serviceheader.posted = 'Y')) AND (serviceheader.date >= v_ad_date)) AND (serviceheader.date <= v_ad_ldate)) AND (serviceheader.custcode = customer.custcode)) GROUP BY serviceheader.serviceinvcode, serviceheader.servicecatcode, serviceheader.date, serviceheader.discperc, serviceheader.misccharges, serviceheader.flatdisc, serviceheader.custcode) AS service GROUP BY service.custcode) AS serviceh WHERE (reportdata.code1 = serviceh.customercode);
  UPDATE dbo.reportdata AS reportdata SET value6 = servicereturnh.amount FROM (SELECT sum(servicereturn.amount) AS amount, servicereturn.custcode AS customercode FROM (SELECT servicerheader.custcode AS custcode, coalesce((((sum((coalesce(servicerdetail.serviceprice, 0) * ((1 - ((.01 * servicerdetail.discperc)))))) * ((1 - ((.01 * servicerheader.discperc))))) + servicerheader.misccharges) - servicerheader.flatdisc), 0) AS amount FROM dbo.servicerheader, dbo.servicerdetail, dbo.customer WHERE ((((((servicerheader.servicerinvcode = servicerdetail.servicerinvcode) AND (servicerheader.servicercatcode = 14)) AND (servicerheader.posted = 'Y')) AND (servicerheader.date >= v_ad_date)) AND (servicerheader.date <= v_ad_ldate)) AND (servicerheader.custcode = customer.custcode)) GROUP BY servicerheader.servicerinvcode, servicerheader.servicercatcode, servicerheader.date, servicerheader.discperc, servicerheader.misccharges, servicerheader.flatdisc, servicerheader.custcode) AS servicereturn GROUP BY servicereturn.custcode) AS servicereturnh WHERE (reportdata.code1 = servicereturnh.customercode);
  DROP TABLE IF EXISTS tmp_lt_pvamts;
  OPEN rs1 FOR SELECT * FROM dbo.reportdata;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_CustomerNetSaleMonthSummary ====
CREATE OR REPLACE FUNCTION dbo.sp_customernetsalemonthsummary(ar_startdate timestamp, ar_enddate timestamp, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ar_startdate timestamp(3);
  v_ar_enddate timestamp(3);
BEGIN
  v_ar_startdate := ar_startdate;
  v_ar_enddate := ar_enddate;
  DELETE FROM dbo.reportdata;
  INSERT INTO dbo.reportdata (name1, name2, name3, name4, date1, value1, value2) SELECT cc.name, a.aliasname, a.name, coalesce((SELECT st.name FROM dbo.saletype AS st, dbo.saleledger AS sl WHERE ((sl.saleinvcode = s.documentcode) AND (sl.saletypecode = st.saletypecode))), '.') AS saletype, (s.date)::timestamp(3) AS date, sum(s.netsale) AS netsale, (SELECT sum(vg.credit) AS discount FROM dbo.virtualgl AS vg WHERE ((((vg.acccode = a.acccode) AND (vg.date BETWEEN v_ar_startdate AND v_ar_enddate)) AND (vg.documenttype IN ('JV'))) AND (vg.credit > 0))) AS discount FROM dbo.customercategory AS cc, dbo.customer AS c, dbo.accounts AS a, (SELECT ((ltrim(rtrim(dbo.tsql_str((extract(month from vg.date)::integer)::numeric))) || '/01/') || ltrim(rtrim(dbo.tsql_str((extract(year from vg.date)::integer)::numeric)))) AS date, vg.acccode, vg.documentcode, sum(CASE vg.documenttype WHEN 'SV' THEN vg.debit WHEN 'SR' THEN (-(vg.credit)) ELSE 0 END) AS netsale FROM dbo.virtualgl AS vg WHERE ((((vg.acccode IN (SELECT acccode FROM dbo.accounts WHERE (subcode = 3))) AND (vg.date BETWEEN v_ar_startdate AND v_ar_enddate)) AND (vg.documenttype IN ('SV', 'SR'))) AND (vg.catcode IN (2, 7))) GROUP BY vg.documentcode, vg.date, vg.acccode) AS s WHERE (((cc.custcatcode = c.custcatcode) AND (c.custcode = a.acccode)) AND (a.acccode = s.acccode)) GROUP BY cc.name, a.aliasname, a.name, a.acccode, s.documentcode, (s.date)::timestamp(3) ORDER BY cc.name, a.name, a.aliasname, date;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_CustomersBalance ====
CREATE OR REPLACE FUNCTION dbo.sp_customersbalance(OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
BEGIN
  DROP TABLE IF EXISTS tmp_lt_pvamts;
  CREATE TEMP TABLE tmp_lt_pvamts (
    custcode numeric(5,0) NOT NULL,
    debit numeric(15,2) NOT NULL,
    credit numeric(15,2) NOT NULL
) ON COMMIT DROP;
  DELETE FROM dbo.reportdata;
  INSERT INTO tmp_lt_pvamts SELECT customer.custcode, coalesce((round((((sum((saledetail.looseqty * saledetail.unitsalestax)) + sum(round(((((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc))))) * saledetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc)))))) * ((1 - ((.01 * saleledger.discperc))))) - saleledger.flatdisc)) * ((saleledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) + round((((((sum((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc)))))) * ((1 - ((.01 * saleledger.discperc))))) + saleledger.misccharges) + saleledger.salestax) - saleledger.flatdisc))::numeric, 0)), 0) AS debit, 0 AS credit FROM dbo.saleledger, dbo.saledetail, dbo.customer WHERE ((((saleledger.saleinvcode = saledetail.saleinvcode) AND (saleledger.salecatcode = 2)) AND (saleledger.posted = 'Y')) AND (saleledger.custcode = customer.custcode)) GROUP BY saleledger.saleinvcode, salecatcode, saleledger.date, saleledger.discperc, saleledger.misccharges, saleledger.salestax, saleledger.flatdisc, saleledger.invgstperc1, customer.custcode;
  INSERT INTO tmp_lt_pvamts SELECT customer.custcode, 0 AS debit, coalesce((round((((sum((srdetail.looseqty * srdetail.unitsalestax)) + sum(round(((((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc))))) * srdetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc)))))) * ((1 - ((.01 * srledger.discperc))))) - srledger.flatdisc)) * ((srledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) + round((((((sum((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc)))))) * ((1 - ((.01 * srledger.discperc))))) + srledger.misccharges) + srledger.salestax) - srledger.flatdisc))::numeric, 0)), 0) AS credit FROM dbo.srledger, dbo.srdetail, dbo.customer WHERE ((((srledger.srinvcode = srdetail.srinvcode) AND (srledger.srcatcode = 7)) AND (srledger.posted = 'Y')) AND (srledger.custcode = customer.custcode)) GROUP BY srledger.srinvcode, srcatcode, srledger.date, srledger.discperc, srledger.misccharges, srledger.salestax, srledger.flatdisc, srledger.invgstperc1, customer.custcode;
  INSERT INTO tmp_lt_pvamts SELECT serviceheader.custcode, coalesce((((sum((coalesce(servicedetail.price, 0) * ((1 - ((.01 * servicedetail.discperc)))))) * ((1 - ((.01 * serviceheader.discperc))))) + serviceheader.misccharges) - serviceheader.flatdisc), 0) AS debit, 0.0 AS credit FROM dbo.serviceheader, dbo.servicedetail, dbo.customer WHERE ((((serviceheader.serviceinvcode = servicedetail.serviceinvcode) AND (serviceheader.servicecatcode = 11)) AND (serviceheader.posted = 'Y')) AND (serviceheader.custcode = customer.custcode)) GROUP BY serviceheader.serviceinvcode, serviceheader.servicecatcode, serviceheader.date, serviceheader.discperc, serviceheader.misccharges, serviceheader.flatdisc, serviceheader.custcode;
  INSERT INTO tmp_lt_pvamts SELECT servicerheader.custcode, 0.0 AS debit, coalesce((((sum((coalesce(servicerdetail.serviceprice, 0) * ((1 - ((.01 * servicerdetail.discperc)))))) * ((1 - ((.01 * servicerheader.discperc))))) + servicerheader.misccharges) - servicerheader.flatdisc), 0) AS credit FROM dbo.servicerheader, dbo.servicerdetail, dbo.customer WHERE ((((servicerheader.servicerinvcode = servicerdetail.servicerinvcode) AND (servicerheader.servicercatcode = 14)) AND (servicerheader.posted = 'Y')) AND (servicerheader.custcode = customer.custcode)) GROUP BY servicerheader.servicerinvcode, servicerheader.servicercatcode, servicerheader.date, servicerheader.discperc, servicerheader.misccharges, servicerheader.flatdisc, servicerheader.custcode;
  INSERT INTO tmp_lt_pvamts SELECT customer.custcode, CASE sum(round((gldetail.debit)::numeric, 0)) WHEN NULL THEN 0.0 ELSE sum(round((gldetail.debit)::numeric, 0)) END, CASE sum(round((gldetail.credit)::numeric, 0)) WHEN NULL THEN 0.0 ELSE sum(round((gldetail.credit)::numeric, 0)) END FROM dbo.glheader, dbo.gldetail, dbo.customer WHERE (((glheader.posted = 'Y') AND (gldetail.acccode = customer.custcode)) AND (glheader.glvochcode = gldetail.glvochcode)) GROUP BY customer.custcode;
  INSERT INTO tmp_lt_pvamts SELECT customer.custcode, 0, coalesce(sum(notes.amount), 0) FROM dbo.notes, dbo.customer WHERE (((notes.posted = 'Y') AND (notes.notecatcode = 1)) AND (notes.acccode = customer.custcode)) GROUP BY customer.custcode;
  INSERT INTO dbo.reportdata (code1, name1, value1) SELECT accounts.acccode, accounts.name, (sum(lt_pvamts.debit) - sum(lt_pvamts.credit)) FROM tmp_lt_pvamts AS lt_pvamts, dbo.accounts WHERE (lt_pvamts.custcode = accounts.acccode) GROUP BY accounts.acccode, accounts.name ORDER BY accounts.name;
  DROP TABLE IF EXISTS tmp_lt_pvamts;
  OPEN rs1 FOR SELECT * FROM dbo.reportdata;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_CustomerTransactionStatus ====
CREATE OR REPLACE FUNCTION dbo.sp_customertransactionstatus(ad_date timestamp, ad_ldate timestamp, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ad_date timestamp(3);
  v_ad_ldate timestamp(3);
BEGIN
  v_ad_date := ad_date;
  v_ad_ldate := ad_ldate;
  DROP TABLE IF EXISTS tmp_lt_pvamts;
  CREATE TEMP TABLE tmp_lt_pvamts (
    debit numeric(15,2) NOT NULL,
    credit numeric(15,2) NOT NULL,
    code numeric(5,0) NOT NULL,
    name citext NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_pvamts SELECT coalesce((round((((sum((saledetail.looseqty * saledetail.unitsalestax)) + sum(round(((((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc))))) * saledetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc)))))) * ((1 - ((.01 * saleledger.discperc))))) - saleledger.flatdisc)) * ((saleledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) + round((((((sum((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc)))))) * ((1 - ((.01 * saleledger.discperc))))) + saleledger.misccharges) + saleledger.salestax) - saleledger.flatdisc))::numeric, 0)), 0) AS debit, 0.0 AS credit, saleledger.custcode AS custcode, (SELECT accounts.name FROM dbo.accounts WHERE (acccode = saleledger.custcode)) AS name FROM dbo.saleledger, dbo.saledetail WHERE ((((saleledger.saleinvcode = saledetail.saleinvcode) AND (saleledger.salecatcode = 2)) AND (saleledger.date < v_ad_date)) AND (saleledger.posted = 'Y')) GROUP BY saleledger.saleinvcode, salecatcode, saleledger.custcode, saleledger.date, saleledger.discperc, saleledger.misccharges, saleledger.salestax, saleledger.invgstperc1, saleledger.flatdisc;
  INSERT INTO tmp_lt_pvamts SELECT 0.0 AS debit, coalesce((round((((sum((srdetail.looseqty * srdetail.unitsalestax)) + sum(round(((((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc))))) * srdetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc)))))) * ((1 - ((.01 * srledger.discperc))))) - srledger.flatdisc)) * ((srledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) + round((((((sum((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc)))))) * ((1 - ((.01 * srledger.discperc))))) + srledger.misccharges) + srledger.salestax) - srledger.flatdisc))::numeric, 0)), 0) AS credit, srledger.custcode AS custcode, (SELECT accounts.name FROM dbo.accounts WHERE (acccode = srledger.custcode)) AS name FROM dbo.srledger, dbo.srdetail WHERE ((((srledger.srinvcode = srdetail.srinvcode) AND (srledger.srcatcode = 7)) AND (srledger.date < v_ad_date)) AND (srledger.posted = 'Y')) GROUP BY srledger.srinvcode, srledger.srcatcode, srledger.custcode, srledger.date, srledger.discperc, srledger.misccharges, srledger.salestax, srledger.invgstperc1, srledger.flatdisc;
  INSERT INTO tmp_lt_pvamts SELECT coalesce((((sum((coalesce(servicedetail.price, 0) * ((1 - ((.01 * servicedetail.discperc)))))) * ((1 - ((.01 * serviceheader.discperc))))) + serviceheader.misccharges) - serviceheader.flatdisc), 0) AS debit, 0.0 AS credit, serviceheader.custcode AS custcode, (SELECT accounts.name FROM dbo.accounts WHERE (acccode = serviceheader.custcode)) AS name FROM dbo.serviceheader, dbo.servicedetail WHERE ((((serviceheader.serviceinvcode = servicedetail.serviceinvcode) AND (serviceheader.servicecatcode = 11)) AND (serviceheader.date < v_ad_date)) AND (serviceheader.posted = 'Y')) GROUP BY serviceheader.serviceinvcode, serviceheader.servicecatcode, serviceheader.custcode, serviceheader.date, serviceheader.discperc, serviceheader.misccharges, serviceheader.flatdisc;
  INSERT INTO tmp_lt_pvamts SELECT 0.0 AS debit, coalesce((((sum((coalesce(servicerdetail.serviceprice, 0) * ((1 - ((.01 * servicerdetail.discperc)))))) * ((1 - ((.01 * servicerheader.discperc))))) + servicerheader.misccharges) - servicerheader.flatdisc), 0) AS credit, servicerheader.custcode AS custcode, (SELECT accounts.name FROM dbo.accounts WHERE (acccode = servicerheader.custcode)) AS name FROM dbo.servicerheader, dbo.servicerdetail WHERE ((((servicerheader.servicerinvcode = servicerdetail.servicerinvcode) AND (servicerheader.servicercatcode = 14)) AND (servicerheader.date < v_ad_date)) AND (servicerheader.posted = 'Y')) GROUP BY servicerheader.servicerinvcode, servicerheader.servicercatcode, servicerheader.custcode, servicerheader.date, servicerheader.discperc, servicerheader.misccharges, servicerheader.flatdisc;
  INSERT INTO tmp_lt_pvamts SELECT coalesce(sum(gldetail.debit), 0), coalesce(sum(gldetail.credit), 0), gldetail.acccode AS custcode, (SELECT accounts.name FROM dbo.accounts WHERE (accounts.acccode = gldetail.acccode)) AS name FROM dbo.glheader, dbo.gldetail WHERE ((((glheader.glvochcode = gldetail.glvochcode) AND (glheader.date < v_ad_date)) AND (glheader.posted = 'Y')) AND (gldetail.acccode IN (SELECT custcode FROM dbo.customer))) GROUP BY gldetail.acccode;
  INSERT INTO tmp_lt_pvamts SELECT 0, coalesce(sum(notes.amount), 0), notes.acccode AS custcode, (SELECT accounts.name FROM dbo.accounts WHERE (accounts.acccode = notes.acccode)) AS name FROM dbo.notes WHERE ((((notes.notecatcode = 1) AND (notes.posted = 'Y')) AND (notes.postdate < v_ad_date)) AND (notes.acccode IN (SELECT custcode FROM dbo.customer))) GROUP BY notes.acccode;
  DELETE FROM dbo.reportdata;
  INSERT INTO dbo.reportdata (code1, name1, value1, value2, value3) SELECT code, name, coalesce((sum(debit) - sum(credit)), 0), 0, 0 FROM tmp_lt_pvamts AS lt_pvamts GROUP BY name, code;
  INSERT INTO dbo.reportdata (code1, value1, value2, value3) SELECT customer.custcode, 0, 0, 0 FROM dbo.customer WHERE (customer.custcode NOT IN (SELECT code1 FROM dbo.reportdata));
  UPDATE dbo.reportdata AS reportdata SET name1 = accounts.name FROM dbo.accounts WHERE ((reportdata.name1 = NULL) AND (reportdata.code1 = accounts.acccode));
  DELETE FROM tmp_lt_pvamts AS lt_pvamts;
  INSERT INTO tmp_lt_pvamts SELECT coalesce((round((((sum((saledetail.looseqty * saledetail.unitsalestax)) + sum(round(((((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc))))) * saledetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc)))))) * ((1 - ((.01 * saleledger.discperc))))) - saleledger.flatdisc)) * ((saleledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) + round((((((sum((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc)))))) * ((1 - ((.01 * saleledger.discperc))))) + saleledger.misccharges) + saleledger.salestax) - saleledger.flatdisc))::numeric, 0)), 0) AS debit, 0.0 AS credit, saleledger.custcode AS custcode, (SELECT accounts.name FROM dbo.accounts WHERE (acccode = saleledger.custcode)) AS name FROM dbo.saleledger, dbo.saledetail WHERE (((((saleledger.saleinvcode = saledetail.saleinvcode) AND (saleledger.salecatcode = 2)) AND (saleledger.date >= v_ad_date)) AND (saleledger.date <= v_ad_ldate)) AND (saleledger.posted = 'Y')) GROUP BY saleledger.saleinvcode, salecatcode, saleledger.custcode, saleledger.date, saleledger.discperc, saleledger.misccharges, saleledger.salestax, saleledger.invgstperc1, saleledger.flatdisc;
  INSERT INTO tmp_lt_pvamts SELECT 0.0 AS debit, coalesce((round((((sum((srdetail.looseqty * srdetail.unitsalestax)) + sum(round(((((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc))))) * srdetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc)))))) * ((1 - ((.01 * srledger.discperc))))) - srledger.flatdisc)) * ((srledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) + round((((((sum((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc)))))) * ((1 - ((.01 * srledger.discperc))))) + srledger.misccharges) + srledger.salestax) - srledger.flatdisc))::numeric, 0)), 0) AS credit, srledger.custcode AS custcode, (SELECT accounts.name FROM dbo.accounts WHERE (acccode = srledger.custcode)) AS name FROM dbo.srledger, dbo.srdetail WHERE (((((srledger.srinvcode = srdetail.srinvcode) AND (srledger.srcatcode = 7)) AND (srledger.date >= v_ad_date)) AND (srledger.date <= v_ad_ldate)) AND (srledger.posted = 'Y')) GROUP BY srledger.srinvcode, srledger.srcatcode, srledger.custcode, srledger.date, srledger.discperc, srledger.misccharges, srledger.salestax, srledger.invgstperc1, srledger.flatdisc;
  INSERT INTO tmp_lt_pvamts SELECT coalesce((((sum((coalesce(servicedetail.price, 0) * ((1 - ((.01 * servicedetail.discperc)))))) * ((1 - ((.01 * serviceheader.discperc))))) + serviceheader.misccharges) - serviceheader.flatdisc), 0) AS debit, 0.0 AS credit, serviceheader.custcode AS custcode, (SELECT accounts.name FROM dbo.accounts WHERE (acccode = serviceheader.custcode)) AS name FROM dbo.serviceheader, dbo.servicedetail WHERE (((((serviceheader.serviceinvcode = servicedetail.serviceinvcode) AND (serviceheader.servicecatcode = 11)) AND (serviceheader.date >= v_ad_date)) AND (serviceheader.date <= v_ad_ldate)) AND (serviceheader.posted = 'Y')) GROUP BY serviceheader.serviceinvcode, serviceheader.servicecatcode, serviceheader.custcode, serviceheader.date, serviceheader.discperc, serviceheader.misccharges, serviceheader.flatdisc;
  INSERT INTO tmp_lt_pvamts SELECT 0.0 AS debit, coalesce((((sum((coalesce(servicerdetail.serviceprice, 0) * ((1 - ((.01 * servicerdetail.discperc)))))) * ((1 - ((.01 * servicerheader.discperc))))) + servicerheader.misccharges) - servicerheader.flatdisc), 0) AS credit, servicerheader.custcode AS custcode, (SELECT accounts.name FROM dbo.accounts WHERE (acccode = servicerheader.custcode)) AS name FROM dbo.servicerheader, dbo.servicerdetail WHERE (((((servicerheader.servicerinvcode = servicerdetail.servicerinvcode) AND (servicerheader.servicercatcode = 14)) AND (servicerheader.date >= v_ad_date)) AND (servicerheader.date <= v_ad_ldate)) AND (servicerheader.posted = 'Y')) GROUP BY servicerheader.servicerinvcode, servicerheader.servicercatcode, servicerheader.custcode, servicerheader.date, servicerheader.discperc, servicerheader.misccharges, servicerheader.flatdisc;
  INSERT INTO tmp_lt_pvamts SELECT coalesce(sum(gldetail.debit), 0), coalesce(sum(gldetail.credit), 0), gldetail.acccode AS custcode, (SELECT accounts.name FROM dbo.accounts WHERE (accounts.acccode = gldetail.acccode)) AS name FROM dbo.glheader, dbo.gldetail WHERE (((((glheader.glvochcode = gldetail.glvochcode) AND (glheader.date >= v_ad_date)) AND (glheader.date <= v_ad_ldate)) AND (glheader.posted = 'Y')) AND (gldetail.acccode IN (SELECT custcode FROM dbo.customer))) GROUP BY gldetail.acccode;
  INSERT INTO tmp_lt_pvamts SELECT 0, coalesce(sum(notes.amount), 0), notes.acccode AS custcode, (SELECT accounts.name FROM dbo.accounts WHERE (accounts.acccode = notes.acccode)) AS name FROM dbo.notes WHERE (((((notes.notecatcode = 1) AND (notes.posted = 'Y')) AND (notes.postdate >= v_ad_date)) AND (notes.postdate <= v_ad_ldate)) AND (notes.acccode IN (SELECT custcode FROM dbo.customer))) GROUP BY notes.acccode;
  UPDATE dbo.reportdata SET value2 = a.ddebit, value3 = a.dcredit FROM (SELECT code, name, coalesce(sum(debit), 0) AS ddebit, coalesce(sum(credit), 0) AS dcredit FROM tmp_lt_pvamts AS lt_pvamts GROUP BY name, code) AS a WHERE (reportdata.code1 = a.code);
  DROP TABLE IF EXISTS tmp_lt_pvamts;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_DailyIncomeStatement_With_GP_Summary ====
CREATE OR REPLACE FUNCTION dbo.sp_dailyincomestatement_with_gp_summary(startdate timestamp, enddate timestamp, reporttype citext, accounts citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_startdate timestamp(3);
  v_enddate timestamp(3);
  v_reporttype citext;
  v_accounts citext;
BEGIN
  v_startdate := startdate;
  v_enddate := enddate;
  v_reporttype := reporttype;
  v_accounts := accounts;
  TRUNCATE TABLE dbo.reportdata;
  DROP TABLE IF EXISTS tmp_lt_cataccounts;
  CREATE TEMP TABLE tmp_lt_cataccounts (
    code integer
) ON COMMIT DROP;
  INSERT INTO tmp_lt_cataccounts SELECT code FROM dbo.udf_stringtotabl(v_accounts, ',') AS udf_stringtotabl;
  IF ((v_reporttype = 'S') OR (v_reporttype = 'A')) THEN
    INSERT INTO dbo.reportdata (date1, name1, name2, name3, name4, value1, code1, code2, code3, code4) SELECT (date_trunc('day', (r.date)::timestamp))::timestamp(3) AS date, 'S' AS functionalarea, 'MED. G/P' AS category, '' AS details, ' Revenue' AS type, round((sum(((r.sales + r.ret) + r.cgs)))::numeric, 0) AS amt, -2 AS acccode, -2 AS catacccode, -1 AS orderby, NULL::numeric(15,4) AS code FROM (SELECT left(to_char(s.date, 'MM/DD/YYYY'), 10) AS date, round((sum(CASE s.type WHEN 'S' THEN (s.itemvalue - ((s.flatdisc * ((s.itemvalue / CASE s.grossamt WHEN 0 THEN 1 ELSE s.grossamt END))))) ELSE 0 END))::numeric, 0) AS sales, 0 AS ret, (-sum(s.cost)) AS cgs FROM (SELECT sl.saleinvcode, sl.date, sd.icode, sum((((sd.looseqty + sd.bonusqty)) * sd.avgprice)) AS cost, sum((sd.looseqty * sd.saleprice)) AS grossvalue, sum(((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc)))) * ((.01 * sd.discperc))) + sd.itemflatdisc)) AS itemdiscvalue, sum(((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc)))) * ((1 - ((.01 * sd.discperc))))) * ((.01 * sl.discperc)))) AS invitemdiscvalue, (sum((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc)))) * ((1 - ((.01 * sd.discperc)))))) * ((1 - ((.01 * sl.discperc))))) AS itemvalue, (SELECT sum(((((sdd.looseqty * ((sdd.saleprice - sdd.itemflatdisc)))) * ((1 - ((.01 * sdd.discperc))))) * ((1 - ((.01 * sll.discperc)))))) FROM dbo.saledetail AS sdd, dbo.saleledger AS sll WHERE ((sll.saleinvcode = sl.saleinvcode) AND (sll.saleinvcode = sdd.saleinvcode)) GROUP BY sll.saleinvcode) AS grossamt, sl.flatdisc, sl.salecatcode AS catcode, 'S' AS type FROM dbo.saleledger AS sl, dbo.saledetail AS sd WHERE (((sl.saleinvcode = sd.saleinvcode) AND (sl.date >= v_startdate)) AND (sl.date <= v_enddate)) GROUP BY sl.saleinvcode, sl.date, sl.salesmancode, sd.icode, sl.salecatcode, sl.discperc, sl.flatdisc, sl.invgstperc1, sl.salecatcode) AS s GROUP BY left(to_char(s.date, 'MM/DD/YYYY'), 10) UNION ALL SELECT left(to_char(s.date, 'MM/DD/YYYY'), 10) AS date, 0 AS sales, (-round((sum(CASE s.type WHEN 'R' THEN (s.itemvalue - ((s.flatdisc * ((s.itemvalue / CASE s.grossamt WHEN 0 THEN 1 ELSE s.grossamt END))))) ELSE 0 END))::numeric, 0)) AS ret, sum(s.cost) AS cgs FROM (SELECT sl.srinvcode, sl.date, sd.icode, sum((((sd.looseqty + sd.bonusqty)) * sd.avgprice)) AS cost, sum((sd.looseqty * sd.srprice)) AS grossvalue, sum((((sd.looseqty * sd.srprice)) * ((.01 * sd.discperc)))) AS itemdiscvalue, sum((((((sd.looseqty * sd.srprice)) * ((1 - ((.01 * sd.discperc)))))) * ((.01 * sl.discperc)))) AS invitemdiscvalue, sum(((((sd.looseqty * sd.srprice) * ((1 - ((.01 * sd.discperc)))))) * ((1 - ((.01 * sl.discperc)))))) AS itemvalue, (SELECT sum(((((sdd.looseqty * sdd.srprice) * ((1 - ((.01 * sdd.discperc)))))) * ((1 - ((.01 * sll.discperc)))))) FROM dbo.srdetail AS sdd, dbo.srledger AS sll WHERE ((sll.srinvcode = sl.srinvcode) AND (sll.srinvcode = sdd.srinvcode)) GROUP BY sll.srinvcode) AS grossamt, sl.flatdisc, sl.srcatcode AS catcode, 'R' AS type FROM dbo.srledger AS sl, dbo.srdetail AS sd WHERE (((sl.srinvcode = sd.srinvcode) AND (sl.date >= v_startdate)) AND (sl.date <= v_enddate)) GROUP BY sl.srinvcode, sl.date, sl.salesmancode, sd.icode, sl.srcatcode, sl.discperc, sl.flatdisc, sl.invgstperc1, sl.srcatcode) AS s GROUP BY left(to_char(s.date, 'MM/DD/YYYY'), 10)) AS r GROUP BY r.date;
  END IF;
  IF ((v_reporttype = 'H') OR (v_reporttype = 'A')) THEN
    INSERT INTO dbo.reportdata (date1, name1, name2, name3, name4, value1, code1, code2, code3, code4) SELECT (date_trunc('day', (r.date)::timestamp))::timestamp(3) AS date, 'H' AS functionalarea, (SELECT sc.name FROM dbo.servicecategory AS sc WHERE (sc.servicecatcode = r.servicecatcode)) AS category, '' AS details, ' Revenue' AS type, round((sum((r.sales + r.ret)))::numeric, 0) AS amt, -1 AS acccode, -1 AS catacccode, 0 AS orderby, NULL::numeric(15,4) AS code FROM (SELECT left(to_char(s.date, 'MM/DD/YYYY'), 10) AS date, sv.servicecatcode, round((sum(CASE s.type WHEN 'S' THEN (s.itemvalue - ((s.flatdisc * ((s.itemvalue / CASE s.grossamt WHEN 0 THEN 1 ELSE s.grossamt END))))) ELSE 0 END))::numeric, 0) AS sales, 0 AS ret FROM (SELECT sl.serviceinvcode, sl.date, sd.servicecode, sum((sd.qty * sd.price)) AS grossvalue, sum((((sd.qty * sd.price)) * ((.01 * sd.discperc)))) AS itemdiscvalue, sum(((((sd.qty * sd.price)) * ((1 - ((.01 * sd.discperc))))) * ((.01 * sl.discperc)))) AS invitemdiscvalue, (sum((((sd.qty * sd.price)) * ((1 - ((.01 * sd.discperc)))))) * ((1 - ((.01 * sl.discperc))))) AS itemvalue, (SELECT sum(((((sdd.qty * sdd.price)) * ((1 - ((.01 * sdd.discperc))))) * ((1 - ((.01 * sll.discperc)))))) FROM dbo.servicedetail AS sdd, dbo.serviceheader AS sll WHERE ((sll.serviceinvcode = sl.serviceinvcode) AND (sll.serviceinvcode = sdd.serviceinvcode)) GROUP BY sll.serviceinvcode) AS grossamt, sl.flatdisc, 'S' AS type FROM dbo.serviceheader AS sl, dbo.servicedetail AS sd WHERE (((sl.serviceinvcode = sd.serviceinvcode) AND (sl.date >= v_startdate)) AND (sl.date <= v_enddate)) GROUP BY sl.serviceinvcode, sl.date, sl.salesmancode, sd.servicecode, sl.servicecatcode, sl.discperc, sl.flatdisc) AS s, dbo.service AS sv WHERE (s.servicecode = sv.servicecode) GROUP BY left(to_char(s.date, 'MM/DD/YYYY'), 10), sv.servicecatcode UNION ALL SELECT left(to_char(s.date, 'MM/DD/YYYY'), 10) AS date, sv.servicecatcode, 0 AS sales, (-round((sum(CASE s.type WHEN 'R' THEN (s.itemvalue - ((s.flatdisc * ((s.itemvalue / CASE s.grossamt WHEN 0 THEN 1 ELSE s.grossamt END))))) ELSE 0 END))::numeric, 0)) AS ret FROM (SELECT sl.servicerinvcode, sl.date, sd.servicecode, sum((sd.qty * sd.serviceprice)) AS grossvalue, sum((((sd.qty * sd.serviceprice)) * ((.01 * sd.discperc)))) AS itemdiscvalue, sum((((((sd.qty * sd.serviceprice)) * ((1 - ((.01 * sd.discperc)))))) * ((.01 * sl.discperc)))) AS invitemdiscvalue, sum(((((sd.qty * sd.serviceprice) * ((1 - ((.01 * sd.discperc)))))) * ((1 - ((.01 * sl.discperc)))))) AS itemvalue, (SELECT sum(((((sdd.qty * sdd.serviceprice) * ((1 - ((.01 * sdd.discperc)))))) * ((1 - ((.01 * sll.discperc)))))) FROM dbo.servicerdetail AS sdd, dbo.servicerheader AS sll WHERE ((sll.servicerinvcode = sl.servicerinvcode) AND (sll.servicerinvcode = sdd.servicerinvcode)) GROUP BY sll.servicerinvcode) AS grossamt, sl.flatdisc, 'R' AS type FROM dbo.servicerheader AS sl, dbo.servicerdetail AS sd WHERE (((sl.servicerinvcode = sd.servicerinvcode) AND (sl.date >= v_startdate)) AND (sl.date <= v_enddate)) GROUP BY sl.servicerinvcode, sl.date, sl.salesmancode, sd.servicecode, sl.servicercatcode, sl.discperc, sl.flatdisc) AS s, dbo.service AS sv WHERE (s.servicecode = sv.servicecode) GROUP BY left(to_char(s.date, 'MM/DD/YYYY'), 10), sv.servicecatcode) AS r GROUP BY r.date, r.servicecatcode;
  END IF;
  INSERT INTO dbo.reportdata (date1, name1, name2, name3, name4, value1, code1, code2, code3, code4) SELECT (date_trunc('day', v_enddate))::timestamp(3) AS date, 'A' AS functionalarea, 'z Expenses' AS category, 'Expense' AS details, 'Expenses' AS type, sum((credit - debit)) AS amt, -1 AS acccode, -2 AS catacccode, 1 AS orderby, NULL::numeric(15,4) AS code FROM dbo.accounts AS a, dbo.glheader AS h, dbo.gldetail AS gd, dbo.subaccounts AS s, dbo.categoryaccounts AS c WHERE (((((((((h.date >= v_startdate) AND (h.date <= v_enddate)) AND (h.posted = 'Y')) AND (h.glvochcode = gd.glvochcode)) AND (gd.acccode = a.acccode)) AND (a.subcode = s.subacccode)) AND (s.catacccode IN (SELECT code FROM tmp_lt_cataccounts AS lt_cataccounts))) AND (s.catacccode = c.catacccode)) AND (c.mainacccode IN (5)));
  INSERT INTO dbo.reportdata (date1, name1, name2, name3, name4, value1, code1, code2, code3, code4) SELECT (date_trunc('day', h.date))::timestamp(3) AS date, gd.remarks AS functionalarea, c.name AS category, a.name AS details, s.name AS groupaccount, (credit - debit) AS amt, a.acccode AS acccode, c.catacccode AS catacccode, 2 AS orderby, h.glvochcode AS code FROM dbo.accounts AS a, dbo.glheader AS h, dbo.gldetail AS gd, dbo.subaccounts AS s, dbo.categoryaccounts AS c WHERE (((((((((h.date >= v_startdate) AND (h.date <= v_enddate)) AND (h.posted = 'Y')) AND (h.glvochcode = gd.glvochcode)) AND (gd.acccode = a.acccode)) AND (a.subcode = s.subacccode)) AND (s.catacccode IN (SELECT code FROM tmp_lt_cataccounts AS lt_cataccounts))) AND (s.catacccode = c.catacccode)) AND (c.mainacccode IN (5)));
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_DailyIncomeStatement_With_GP_Summary2 ====
CREATE OR REPLACE FUNCTION dbo.sp_dailyincomestatement_with_gp_summary2(startdate timestamp, enddate timestamp, accounts citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_startdate timestamp(3);
  v_enddate timestamp(3);
  v_accounts citext;
BEGIN
  v_startdate := startdate;
  v_enddate := enddate;
  v_accounts := accounts;
  TRUNCATE TABLE dbo.reportdata;
  DROP TABLE IF EXISTS tmp_lt_cataccounts;
  CREATE TEMP TABLE tmp_lt_cataccounts (
    code integer
) ON COMMIT DROP;
  INSERT INTO tmp_lt_cataccounts SELECT code FROM dbo.udf_stringtotabl(v_accounts, ',') AS udf_stringtotabl;
  INSERT INTO dbo.reportdata (name1, name2, name3, value1, value2, code1) SELECT (SELECT (((ltrim(rtrim(p.name)) || ' (') || ltrim(rtrim(p.regno))) || ')') FROM dbo.patient AS p WHERE (p.patientcode = r.patientcode)) AS patientname, (SELECT sc.name FROM dbo.servicecategory AS sc WHERE (sc.servicecatcode = r.servicecatcode)) AS category, ' Revenue' AS type, round((sum((r.grosssales - r.grossret)))::numeric, 0) AS amt, round((sum((r.salediscount - r.retdiscount)))::numeric, 0) AS discount, 0 AS orderby FROM (SELECT s.patientcode, sv.servicecatcode, coalesce(sum(s.grossvalue), 0) AS grosssales, coalesce(sum(s.discount), 0) AS salediscount, 0.00 AS grossret, 0.00 AS retdiscount FROM (SELECT sl.patientcode, sd.servicecode, sum((sd.qty * sd.price)) AS grossvalue, (((coalesce(sum((sd.qty * sd.serviceflatdisc)), 0) + coalesce(sum((((sd.qty * ((sd.price - sd.serviceflatdisc)))) * ((.01 * sd.discperc)))), 0)) + coalesce(sum(((((sd.qty * ((sd.price - sd.serviceflatdisc)))) * ((1 - ((.01 * sd.discperc))))) * ((.01 * sl.discperc)))), 0)) + coalesce(sl.flatdisc, 0)) AS discount, 'S' AS type FROM dbo.serviceheader AS sl, dbo.servicedetail AS sd WHERE (((sl.serviceinvcode = sd.serviceinvcode) AND (sl.date >= v_startdate)) AND (sl.date <= v_enddate)) GROUP BY sl.serviceinvcode, sl.date, sl.salesmancode, sd.servicecode, sl.servicecatcode, sl.patientcode, sl.discperc, sl.flatdisc) AS s, dbo.service AS sv WHERE (s.servicecode = sv.servicecode) GROUP BY s.patientcode, sv.servicecatcode UNION ALL SELECT s.patientcode, sv.servicecatcode, 0.00 AS grosssales, 0.00 AS salediscount, coalesce(sum(s.grossvalue), 0) AS grossret, coalesce(sum(s.discount), 0) AS retdiscount FROM (SELECT sl.patientcode, sd.servicecode, sum((sd.qty * sd.serviceprice)) AS grossvalue, (((coalesce(sum((sd.qty * sd.serviceflatdisc)), 0) + coalesce(sum((((sd.qty * ((sd.serviceprice - sd.serviceflatdisc)))) * ((.01 * sd.discperc)))), 0)) + coalesce(sum(((((sd.qty * ((sd.serviceprice - sd.serviceflatdisc)))) * ((1 - ((.01 * sd.discperc))))) * ((.01 * sl.discperc)))), 0)) + coalesce(sl.flatdisc, 0)) AS discount, 'R' AS type FROM dbo.servicerheader AS sl, dbo.servicerdetail AS sd WHERE (((sl.servicerinvcode = sd.servicerinvcode) AND (sl.date >= v_startdate)) AND (sl.date <= v_enddate)) GROUP BY sl.servicerinvcode, sl.date, sl.salesmancode, sd.servicecode, sl.servicercatcode, sl.patientcode, sl.discperc, sl.flatdisc) AS s, dbo.service AS sv WHERE (s.servicecode = sv.servicecode) GROUP BY s.patientcode, sv.servicecatcode) AS r GROUP BY r.patientcode, r.servicecatcode UNION ALL SELECT a.name AS patientname, '«Expenses»' AS category, 'Expenses' AS type, sum((credit - debit)) AS amt, 0 AS discount, 1 AS orderby FROM dbo.accounts AS a, dbo.glheader AS h, dbo.gldetail AS gd, dbo.subaccounts AS s, dbo.categoryaccounts AS c WHERE (((((((((h.date >= v_startdate) AND (h.date <= v_enddate)) AND (h.posted = 'Y')) AND (h.glvochcode = gd.glvochcode)) AND (gd.acccode = a.acccode)) AND (a.subcode = s.subacccode)) AND (s.catacccode IN (SELECT code FROM tmp_lt_cataccounts AS lt_cataccounts))) AND (s.catacccode = c.catacccode)) AND (c.mainacccode IN (5))) GROUP BY a.name;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_DailyLedger_LPLedger ====
CREATE OR REPLACE FUNCTION dbo.sp_dailyledger_lpledger(custcode integer, datetype citext, start_date timestamp, end_date timestamp, caption citext, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_custcode integer;
  v_datetype citext;
  v_start_date timestamp(3);
  v_end_date timestamp(3);
  v_caption citext;
BEGIN
  v_custcode := custcode;
  v_datetype := datetype;
  v_start_date := start_date;
  v_end_date := end_date;
  v_caption := caption;
  DELETE FROM dbo.reportdata;
  DROP TABLE IF EXISTS tmp_sale;
  CREATE TEMP TABLE tmp_sale (
    custaliasname citext,
    customer citext,
    icode integer,
    itemaliasname citext,
    itemname citext,
    packingdesc citext,
    packing citext,
    saleqty numeric(15,4),
    formnoandqty citext
) ON COMMIT DROP;
  INSERT INTO tmp_sale SELECT a.aliasname AS customeraliasname, a.name AS customer, sd.icode AS icode, i.customicode AS itemaliasname, i.name AS itemname, i.packingdesc AS packingdesc, (SELECT ip.name FROM dbo.itempacking AS ip WHERE (ip.packcode = i.packcode)) AS packing, sum(sd.looseqty) AS saleqty, '' AS formnoandqty FROM dbo.item AS i, dbo.saleledger AS sl, dbo.saleinvdetail AS sd, dbo.accounts AS a WHERE ((((((CASE WHEN ((lower(v_datetype))::citext = 'originaldate') THEN sl.originaldate WHEN ((lower(v_datetype))::citext = 'lastsavingdate') THEN sl.date WHEN ((lower(v_datetype))::citext = 'billingdate') THEN sl.billingdate ELSE sl.date END BETWEEN v_start_date AND v_end_date) AND (sl.custcode = v_custcode)) AND (sl.custcode = a.acccode)) AND (sl.posted = 'Y')) AND (sl.saleinvcode = sd.saleinvcode)) AND (sd.icode = i.icode)) GROUP BY a.aliasname, a.name, sd.icode, i.customicode, i.name, i.packingdesc, i.packcode;
  UPDATE tmp_sale AS sale SET formnoandqty = dbo.fn_getformnoandqty_dailyledger(v_custcode, (icode)::integer, v_datetype, v_start_date, v_end_date);
  OPEN rs1 FOR SELECT custaliasname, customer, icode, itemaliasname, itemname, packingdesc, packing, saleqty, formnoandqty FROM tmp_sale AS sale ORDER BY itemname;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_DateWiseSaleBreakup ====
CREATE OR REPLACE FUNCTION dbo.sp_datewisesalebreakup(ai_custcode integer, ad_startdate timestamp, ad_enddate timestamp, ai_days integer, ad_discperc numeric, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_custcode integer;
  v_ad_startdate timestamp(3);
  v_ad_enddate timestamp(3);
  v_ai_days integer;
  v_ad_discperc numeric(6,2);
  v_tmpdate timestamp(3);
  v_tmpdate2 timestamp(3);
  v_counter integer;
  v_date_str citext;
BEGIN
  v_ai_custcode := ai_custcode;
  v_ad_startdate := ad_startdate;
  v_ad_enddate := ad_enddate;
  v_ai_days := ai_days;
  v_ad_discperc := ad_discperc;
  DELETE FROM dbo.reportdata;
  v_tmpdate := v_ad_startdate;
  v_counter := 1;
  WHILE ((v_tmpdate + (v_ai_days) * interval '1 day') <= v_ad_enddate) LOOP
    v_date_str := (left(to_char(((v_tmpdate + (v_ai_days) * interval '1 day') - (1) * interval '1 day'), 'MM/DD/YYYY'), 100) || ' 23:59:59');
    INSERT INTO dbo.reportdata (date1, date2, code1, code2) SELECT v_tmpdate, (v_date_str)::timestamp(3), v_ai_custcode, v_counter;
    v_tmpdate := (v_tmpdate + (v_ai_days) * interval '1 day');
    v_counter := (v_counter + 1);
  END LOOP;
  INSERT INTO dbo.reportdata (date1, date2, code1, code2) SELECT v_tmpdate, v_ad_enddate, v_ai_custcode, v_counter;
  UPDATE dbo.reportdata SET name1 = (SELECT a.aliasname FROM dbo.accounts AS a WHERE (a.acccode = v_ai_custcode)), name2 = (SELECT a.name FROM dbo.accounts AS a WHERE (a.acccode = v_ai_custcode)), code3 = (SELECT min(s.saleinvcode) FROM dbo.saleledger AS s WHERE ((s.custcode = v_ai_custcode) AND (s.date BETWEEN reportdata.date1 AND reportdata.date2))), code4 = (SELECT max(s.saleinvcode) FROM dbo.saleledger AS s WHERE ((s.custcode = v_ai_custcode) AND (s.date BETWEEN reportdata.date1 AND reportdata.date2))), code5 = v_ad_discperc, value1 = (SELECT sum(s.netamount) FROM (SELECT (round((((((sum((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc)))))) * ((1 - ((.01 * saleledger.discperc))))) + saleledger.misccharges) + saleledger.salestax) - saleledger.flatdisc))::numeric, 0) + round((((sum((((saledetail.looseqty + saledetail.bonusqty)) * saledetail.unitsalestax)) + sum(round(((((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc))))) * saledetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc)))))) * ((1 - ((.01 * saleledger.discperc))))) - saleledger.flatdisc)) * ((saleledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0)) AS netamount FROM dbo.saleledger, dbo.saledetail WHERE (((saleledger.custcode = v_ai_custcode) AND (saleledger.date BETWEEN reportdata.date1 AND reportdata.date2)) AND (saleledger.saleinvcode = saledetail.saleinvcode)) GROUP BY saleledger.saleinvcode, saleledger.date, saleledger.salecatcode, saleledger.patientcode, saleledger.custrefno, saleledger.remarks, saleledger.relationcode, saleledger.discperc, saleledger.misccharges, saleledger.salestax, saleledger.flatdisc, saleledger.discperc, saleledger.flatdisc, saleledger.invgstperc1 UNION ALL SELECT (round((((((sum((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc)))))) * ((1 - ((.01 * saleledger.discperc))))) + saleledger.misccharges) + saleledger.salestax) - saleledger.flatdisc))::numeric, 0) + round((((sum((((saledetail.looseqty + saledetail.bonusqty)) * saledetail.unitsalestax)) + sum(round(((((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc))))) * saledetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc)))))) * ((1 - ((.01 * saleledger.discperc))))) - saleledger.flatdisc)) * ((saleledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0)) AS netamount FROM dbo.saleledger, dbo.saleinvdetail AS saledetail WHERE ((((saleledger.custcode = v_ai_custcode) AND (saleledger.impactinventory = 'N')) AND (saleledger.date BETWEEN reportdata.date1 AND reportdata.date2)) AND (saleledger.saleinvcode = saledetail.saleinvcode)) GROUP BY saleledger.saleinvcode, saleledger.date, saleledger.salecatcode, saleledger.patientcode, saleledger.custrefno, saleledger.remarks, saleledger.relationcode, saleledger.discperc, saleledger.misccharges, saleledger.salestax, saleledger.flatdisc, saleledger.discperc, saleledger.flatdisc, saleledger.invgstperc1) AS s);
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_DB_Fetch_DropBoxInfo ====
CREATE OR REPLACE FUNCTION dbo.sp_db_fetch_dropboxinfo(srv citext, db citext, owner citext, startdate timestamp, enddate timestamp, usercode smallint, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_startdate timestamp(3);
  v_enddate timestamp(3);
  v_usercode smallint;
  v_mysitecode integer;
  v_groupcode integer;
  v_err integer;
  v_doctype citext;
  v_qry citext;
  v_prefix citext;
  v_rightcode integer;
  _dq1 text;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  v_startdate := startdate;
  v_enddate := enddate;
  v_usercode := usercode;
  v_mysitecode := (SELECT max(sitecode) FROM dbo.site WHERE (instanceid IN (SELECT name FROM dbo.clientinstance)));
  IF (v_mysitecode > 0) THEN
    v_groupcode := (SELECT dbo.fn_getgroupcode(v_usercode));
    v_prefix := '';
    IF (((length(rtrim(ltrim(rtrim(v_srv)))) = 0) OR (v_srv IS NULL))) THEN
      v_prefix := '';
    ELSE
      v_prefix := (v_srv || '.');
    END IF;
    IF (((length(rtrim(ltrim(rtrim(v_db)))) = 0) OR (v_db IS NULL))) THEN
      v_prefix := v_prefix;
    ELSE
      v_prefix := ((v_prefix || v_db) || '.');
    END IF;
    IF (((length(rtrim(ltrim(rtrim(v_owner)))) = 0) OR (v_owner IS NULL))) THEN
      v_prefix := ((v_prefix || 'DBO') || '.');
    ELSE
      v_prefix := ((v_prefix || v_owner) || '.');
    END IF;
    v_doctype := '';
    v_rightcode := (SELECT max(rightcode) FROM dbo.grouprights WHERE ((groupcode = v_groupcode) AND (rightcode = 5294)));
    IF (v_rightcode = 5294) THEN
      v_doctype := (v_doctype || '''S'',');
    END IF;
    v_rightcode := (SELECT max(rightcode) FROM dbo.grouprights WHERE ((groupcode = v_groupcode) AND (rightcode = 5295)));
    IF (v_rightcode = 5295) THEN
      v_doctype := (v_doctype || '''SR'',');
    END IF;
    v_rightcode := (SELECT max(rightcode) FROM dbo.grouprights WHERE ((groupcode = v_groupcode) AND (rightcode = 5296)));
    IF (v_rightcode = 5296) THEN
      v_doctype := (v_doctype || '''P'',');
    END IF;
    v_rightcode := (SELECT max(rightcode) FROM dbo.grouprights WHERE ((groupcode = v_groupcode) AND (rightcode = 5297)));
    IF (v_rightcode = 5297) THEN
      v_doctype := (v_doctype || '''PR'',');
    END IF;
    v_rightcode := (SELECT max(rightcode) FROM dbo.grouprights WHERE ((groupcode = v_groupcode) AND (rightcode = 5298)));
    IF (v_rightcode = 5298) THEN
      v_doctype := (v_doctype || '''PO'',');
    END IF;
    v_rightcode := (SELECT max(rightcode) FROM dbo.grouprights WHERE ((groupcode = v_groupcode) AND (rightcode = 5299)));
    IF (v_rightcode = 5299) THEN
      v_doctype := (v_doctype || '''IS'',');
    END IF;
    v_rightcode := (SELECT max(rightcode) FROM dbo.grouprights WHERE ((groupcode = v_groupcode) AND (rightcode = 5300)));
    IF (v_rightcode = 5300) THEN
      v_doctype := (v_doctype || '''EI''');
    END IF;
    IF ((right(v_doctype, 1))::citext = ',') THEN
      v_doctype := left(v_doctype, (length(rtrim(v_doctype)) - 1));
    END IF;
    IF (v_startdate IS NULL) THEN
      v_startdate := (localtimestamp(3) - (30) * interval '1 day');
    END IF;
    IF (v_enddate IS NULL) THEN
      v_enddate := localtimestamp(3);
    END IF;
    IF (length(rtrim(v_doctype)) > 0) THEN
      v_qry := (((((((((((((((((('SELECT MySiteCode= ' || ltrim(rtrim(dbo.tsql_str((v_mysitecode)::numeric, 10)))) || ', SiteCode, TargetSiteCode, SourceSite, TargetSite, DocumentType, DocumentCode, AliasName, Account, Category, Amount, Date, PushedOn, Pulled, PulledOn, PulledBy, RespondWith, Remarks, RefNo, RefNo2, RefNo3, RefNo4, RefNo5 FROM ') || v_prefix) || 'View_DB_DropBox WHERE DATE BETWEEN ') || '''') || left(to_char(v_startdate, 'YYYY-MM-DD HH24:MI:SS.MS'), 100)) || '''') || ' AND ') || '''') || left(to_char(v_enddate, 'YYYY-MM-DD HH24:MI:SS.MS'), 100)) || '''') || ' AND DocumentType IN (') || v_doctype) || ') AND (SiteCode = ') || ltrim(rtrim(dbo.tsql_str((v_mysitecode)::numeric, 10)))) || ' OR TargetSiteCode = ') || ltrim(rtrim(dbo.tsql_str((v_mysitecode)::numeric, 10)))) || ')');
    ELSE
      v_qry := (((('SELECT MySiteCode= ' || ltrim(rtrim(dbo.tsql_str((v_mysitecode)::numeric, 10)))) || ', SiteCode, TargetSiteCode, SourceSite, TargetSite, DocumentType, DocumentCode, AliasName, Account, Category, Amount, Date, PushedOn, Pulled, PulledOn, PulledBy, RespondWith, Remarks, RefNo, RefNo2, RefNo3, RefNo4, RefNo5 FROM ') || v_prefix) || 'View_DB_DropBox WHERE 1=2');
    END IF;
  ELSE
    v_qry := 'SELECT MySiteCode=NULL, SiteCode, TargetSiteCode, SourceSite, TargetSite, DocumentType, DocumentCode, AliasName, Account, Category, Amount, Date, PushedOn, Pulled, PulledOn, PulledBy, RespondWith, Remarks, RefNo, RefNo2, RefNo3, RefNo4, RefNo5 FROM View_DB_DropBox WHERE 1=2';
  END IF;
  _dq1 := v_qry;
  IF _dq1 IS NOT NULL THEN
    IF _dq1 ~* '^[[:space:]]*select' THEN OPEN rs1 FOR EXECUTE dbo.tsql_dyn(_dq1); ELSE EXECUTE dbo.tsql_dyn(_dq1); END IF;
  END IF;
  return_value := 0;
  RETURN;
END
$body$;

