-- ==== proc SP_DB_PushExpiryIntimationToDropBox ====
CREATE OR REPLACE FUNCTION dbo.sp_db_pushexpiryintimationtodropbox(sinvcode integer, linvcode integer, intimationtype smallint, usercode smallint, srv citext, db citext, owner citext, INOUT count integer, OUT return_value integer, OUT rs1 refcursor, OUT rs2 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_sinvcode integer;
  v_linvcode integer;
  v_intimationtype smallint;
  v_usercode smallint;
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_count integer;
  v_ins_header citext;
  v_ins_detail citext;
  v_prefix citext;
  v_err integer;
  _dq1 text;
  _dq2 text;
BEGIN
  v_sinvcode := sinvcode;
  v_linvcode := linvcode;
  v_intimationtype := intimationtype;
  v_usercode := usercode;
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  v_count := count;
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  -- SET NOCOUNT ON
  -- SET XACT_ABORT ON
  v_prefix := '';
  IF (((length(rtrim(ltrim(rtrim(v_srv)))) = 0) OR (v_srv IS NULL))) THEN
    v_prefix := '';
  ELSE
    v_prefix := (v_srv || '.');
  END IF;
  IF (((length(rtrim(ltrim(rtrim(v_db)))) = 0) OR (v_db IS NULL))) THEN
    v_prefix := v_prefix;
  ELSE
    v_prefix := ((v_prefix || v_db) || '.');
  END IF;
  IF (((length(rtrim(ltrim(rtrim(v_owner)))) = 0) OR (v_owner IS NULL))) THEN
    v_prefix := ((v_prefix || 'DBO') || '.');
  ELSE
    v_prefix := ((v_prefix || v_owner) || '.');
  END IF;
  SELECT count(*) INTO v_count FROM dbo.expiryintimation WHERE ((((((expiryintimation.sitecode IS NOT NULL) AND (expiryintimation.targetsitecode IS NOT NULL)) AND (expiryintimation.intimationcode BETWEEN v_sinvcode AND v_linvcode)) AND (expiryintimation.intimationtypecode = v_intimationtype)) AND (expiryintimation.posted = 'Y')) AND (pushed = 'N'));
  v_ins_header := (((((((((('INSERT INTO ' || v_prefix) || 'DB_ExpiryIntimation (SiteCode,TargetSiteCode,IntimationCode,IntimationTypeCode,IntimationSerialNo,AccCode,Date,RefNo,Remarks1,Remarks2,UserCode,CustCode,PushedOn,PushedBy,Pulled,PulledOn,PulledBy) ') || ' SELECT SiteCode,TargetSiteCode,IntimationCode,IntimationTypeCode,IntimationSerialNo,AccCode,Date,RefNo,Remarks1,Remarks2,UserCode,CustCode,localtimestamp(3) AS PushedOn,PushedBy=') || ltrim(rtrim(dbo.tsql_str((v_usercode)::numeric)))) || ',Pulled=''N'',PulledOn=NULL,PulledBy=NULL FROM ExpiryIntimation WHERE SiteCode IS NOT NULL AND TargetSiteCode IS NOT NULL AND Posted=''Y'' AND Pushed=''N'' AND IntimationCode BETWEEN ') || ltrim(rtrim(dbo.tsql_str((v_sinvcode)::numeric)))) || ' AND ') || ltrim(rtrim(dbo.tsql_str((v_linvcode)::numeric)))) || ' AND IntimationTypeCode = ') || ltrim(rtrim(dbo.tsql_str((v_intimationtype)::numeric))));
  v_ins_detail := (((((((('INSERT INTO ' || v_prefix) || 'DB_ExpiryIntimationDetail (SiteCode,IntimationCode,ICode,Batch,Expiry,Qty,Packunits,PackPrice,Price,InvoiceCode,InvoiceDate,RefNo,RefDate,RowID,ManfCode,LastAccCode) ') || ' SELECT P.SiteCode,P.IntimationCode,D.ICode,D.Batch,D.Expiry,D.Qty,D.Packunits,D.PackPrice,D.Price,D.InvoiceCode,D.InvoiceDate,D.RefNo,D.RefDate,D.RowID,D.ManfCode,D.LastAccCode FROM ExpiryIntimationDetail D, ExpiryIntimation P WHERE P.IntimationCode = D.IntimationCode AND P.SiteCode IS NOT NULL AND P.TargetSiteCode IS NOT NULL AND P.Posted=''Y'' AND P.Pushed=''N'' AND P.IntimationCode BETWEEN ') || ltrim(rtrim(dbo.tsql_str((v_sinvcode)::numeric)))) || ' AND ') || ltrim(rtrim(dbo.tsql_str((v_linvcode)::numeric)))) || ' AND P.IntimationTypeCode = ') || ltrim(rtrim(dbo.tsql_str((v_intimationtype)::numeric))));
  _dq1 := v_ins_header;
  IF _dq1 IS NOT NULL THEN
    IF _dq1 ~* '^[[:space:]]*select' THEN OPEN rs1 FOR EXECUTE dbo.tsql_dyn(_dq1); ELSE EXECUTE dbo.tsql_dyn(_dq1); END IF;
  END IF;
  v_err := 0;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Data Insertion: Error Pushing Expiry Intimation Header into Drop Box';
    return_value := -1;
    count := v_count;
    RETURN;
  END IF;
  _dq2 := v_ins_detail;
  IF _dq2 IS NOT NULL THEN
    IF _dq2 ~* '^[[:space:]]*select' THEN OPEN rs2 FOR EXECUTE dbo.tsql_dyn(_dq2); ELSE EXECUTE dbo.tsql_dyn(_dq2); END IF;
  END IF;
  v_err := 0;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Data Insertion: Error Pushing Expiry Intimation Details into Drop Box';
    return_value := -1;
    count := v_count;
    RETURN;
  END IF;
  UPDATE dbo.expiryintimation SET pushed = 'Y', pushedon = localtimestamp(3), pushedby = v_usercode WHERE ((((((sitecode IS NOT NULL) AND (targetsitecode IS NOT NULL)) AND (posted = 'Y')) AND (pushed = 'N')) AND (intimationcode BETWEEN v_sinvcode AND v_linvcode)) AND (expiryintimation.intimationtypecode = v_intimationtype));
  IF (0 <> 0) THEN
    RAISE EXCEPTION 'Data Updation: Error Updating Expiry Intimation Header Info';
    return_value := -1;
    count := v_count;
    RETURN;
  END IF;
  return_value := 0;
  count := v_count;
  RETURN;
  return_value := 0;
  count := v_count;
  RETURN;
END
$body$;

