    v_err := 0;
    IF ((0 <> 0) OR (v_err <> 0)) THEN
      RAISE EXCEPTION 'Problem while Executing Quotation Generation On Remote Server';
      return_value := -1;
      count := v_count;
      RETURN;
    END IF;
  END IF;
  return_value := 0;
  count := v_count;
  RETURN;
  return_value := 0;
  count := v_count;
  RETURN;
END
$body$;

