    v_ins_detail := (((((('INSERT INTO ' || v_prefix) || 'DB_SaleDetail (SiteCode, SaleInvcode, ICode, GCode, Batch, Expiry, LooseQty, PackUnits, SalePrice, AvgPrice, Rate, DiscPerc, SalesTax, RowID, Due, itemflatdisc, SaleItemDescription, UnitSalesTax, GSTPerc, SaleUtn, bonusqty, claimable, balancestock, RowGroup, ClaimableDiscPerc, ManfDate) ') || 'SELECT S.SiteCode, S.SaleInvcode, D.ICode, D.GCode, D.Batch, D.Expiry, D.LooseQty, D.PackUnits, D.SalePrice, D.AvgPrice, D.Rate, D.DiscPerc, D.SalesTax, D.RowID, D.Due, D.itemflatdisc, D.SaleItemDescription, D.UnitSalesTax, D.GSTPerc, D.SaleUtn, D.bonusqty, D.claimable, D.balancestock, D.RowGroup, D.ClaimableDiscPerc, D.ManfDate FROM SaleDetail D, SaleLedger S WHERE S.SaleInvcode = D.SaleInvCode AND S.SiteCode IS NOT NULL AND S.TargetSiteCode IS NOT NULL AND S.Posted=''Y'' AND S.Pushed=''N'' AND S.SaleInvCode BETWEEN ') || ltrim(rtrim(dbo.tsql_str((v_sinvcode)::numeric)))) || ' AND ') || ltrim(rtrim(dbo.tsql_str((v_linvcode)::numeric))));
