-- ==== proc SP_DB_PushSRToDropBox ====
CREATE OR REPLACE FUNCTION dbo.sp_db_pushsrtodropbox(sinvcode integer, linvcode integer, custcode integer, usercode smallint, srv citext, db citext, owner citext, INOUT count integer, OUT return_value integer, OUT rs1 refcursor, OUT rs2 refcursor)
