  END IF;
  IF (v_custcode > 0) THEN
    SELECT count(*) INTO v_count FROM dbo.srledger WHERE ((((((srledger.sitecode IS NOT NULL) AND (srledger.targetsitecode IS NOT NULL)) AND (srledger.srinvcode BETWEEN v_sinvcode AND v_linvcode)) AND (srledger.posted = 'Y')) AND (pushed = 'N')) AND (custcode = v_custcode));
    v_ins_header := (((((((((('INSERT INTO ' || v_prefix) || 'DB_SRLedger (SiteCode,TargetSiteCode,SRInvCode,SaleInvCode,Date,SRCatCode,CustCode,SalesmanCode,DiscPerc,FlatDisc,MiscCharges,Remarks,InvGSTPerc1,Smancode,CustRefno,CustRefno2,CustRefno3,CustRefno4,invtotal,AdvanceTax,AdvanceTaxAmt,FBRPOSFee,PushedOn,PushedBy,Pulled,PulledOn,PulledBy) ') || 'SELECT SiteCode,TargetSiteCode,SRInvCode,SaleInvCode,Date,SRCatCode,CustCode,SalesmanCode,DiscPerc,FlatDisc,MiscCharges,Remarks,InvGSTPerc1,Smancode,CustRefno,CustRefno2,CustRefno3,CustRefno4,invtotal,AdvanceTax,AdvanceTaxAmt,FBRPOSFee,localtimestamp(3) AS PushedOn,PushedBy=') || ltrim(rtrim(dbo.tsql_str((v_usercode)::numeric)))) || ',Pulled=''N'',PulledOn=NULL,PulledBy=NULL FROM DBO.srledger WHERE SiteCode IS NOT NULL AND TargetSiteCode IS NOT NULL AND Posted=''Y'' AND Pushed=''N'' AND SRInvCode BETWEEN ') || ltrim(rtrim(dbo.tsql_str((v_sinvcode)::numeric)))) || ' AND ') || ltrim(rtrim(dbo.tsql_str((v_linvcode)::numeric)))) || ' AND CustCode = ') || ltrim(rtrim(dbo.tsql_str((v_custcode)::numeric))));
    v_ins_detail := (((((((('INSERT INTO ' || v_prefix) || 'DB_SRDetail (SiteCode,SRInvcode,Icode,Gcode,Batch,Expiry,PackQty,LooseQty,PackUnits,SRPrice,DiscPerc,SalesTax,AvgPrice,UnitSalesTax,GSTPerc,SRUtn,BonusQty,SalePrice,SaleRowId,RowId,ReturnItemDescription,TotalPieces,PiecesInHand,AlternatePurPrice,CommissionPerUnit,CommissionPerc,AlternateCustomICode,NewAvgPrice,Claimable,ClaimableDiscPerc,ItemAdvanceTaxPerc,CurrStock) ') || 'SELECT S.SiteCode,S.SRInvcode,D.Icode,D.Gcode,D.Batch,D.Expiry,D.PackQty,D.LooseQty,D.PackUnits,D.SRPrice,D.DiscPerc,D.SalesTax,D.AvgPrice,D.UnitSalesTax,D.GSTPerc,D.SRUtn,D.BonusQty,D.SalePrice,D.SaleRowId,D.RowId,D.ReturnItemDescription,D.TotalPieces,D.PiecesInHand,D.AlternatePurPrice,D.CommissionPerUnit,D.CommissionPerc,D.AlternateCustomICode,D.NewAvgPrice,D.Claimable,D.ClaimableDiscPerc,D.ItemAdvanceTaxPerc,D.CurrStock FROM SRDetail D, srledger S WHERE S.SRInvcode = D.SRInvCode AND S.SiteCode IS NOT NULL AND S.TargetSiteCode IS NOT NULL AND S.Posted=''Y'' AND S.Pushed=''N'' AND S.SRInvCode BETWEEN ') || ltrim(rtrim(dbo.tsql_str((v_sinvcode)::numeric)))) || ' AND ') || ltrim(rtrim(dbo.tsql_str((v_linvcode)::numeric)))) || ' AND S.CustCode = ') || ltrim(rtrim(dbo.tsql_str((v_custcode)::numeric))));
  ELSE
    SELECT count(*) INTO v_count FROM dbo.srledger WHERE (((((srledger.sitecode IS NOT NULL) AND (srledger.targetsitecode IS NOT NULL)) AND (srledger.srinvcode BETWEEN v_sinvcode AND v_linvcode)) AND (srledger.posted = 'Y')) AND (pushed = 'N'));
    v_ins_header := (((((((('INSERT INTO ' || v_prefix) || 'DB_SRLedger (SiteCode,TargetSiteCode,SRInvCode,SaleInvCode,Date,SRCatCode,CustCode,SalesmanCode,DiscPerc,FlatDisc,MiscCharges,Remarks,InvGSTPerc1,Smancode,CustRefno,CustRefno2,CustRefno3,CustRefno4,invtotal,AdvanceTax,AdvanceTaxAmt,FBRPOSFee,PushedOn,PushedBy,Pulled,PulledOn,PulledBy) ') || 'SELECT SiteCode,TargetSiteCode,SRInvCode,SaleInvCode,Date,SRCatCode,CustCode,SalesmanCode,DiscPerc,FlatDisc,MiscCharges,Remarks,InvGSTPerc1,Smancode,CustRefno,CustRefno2,CustRefno3,CustRefno4,invtotal,AdvanceTax,AdvanceTaxAmt,FBRPOSFee,localtimestamp(3) AS PushedOn,PushedBy=') || ltrim(rtrim(dbo.tsql_str((v_usercode)::numeric)))) || ',Pulled=''N'',PulledOn=NULL,PulledBy=NULL FROM DBO.srledger WHERE SiteCode IS NOT NULL AND TargetSiteCode IS NOT NULL AND Posted=''Y'' AND Pushed=''N'' AND SRInvCode BETWEEN ') || ltrim(rtrim(dbo.tsql_str((v_sinvcode)::numeric)))) || ' AND ') || ltrim(rtrim(dbo.tsql_str((v_linvcode)::numeric))));
    v_ins_detail := (((((('INSERT INTO ' || v_prefix) || 'DB_SRDetail (SiteCode,SRInvcode,Icode,Gcode,Batch,Expiry,PackQty,LooseQty,PackUnits,SRPrice,DiscPerc,SalesTax,AvgPrice,UnitSalesTax,GSTPerc,SRUtn,BonusQty,SalePrice,SaleRowId,RowId,ReturnItemDescription,TotalPieces,PiecesInHand,AlternatePurPrice,CommissionPerUnit,CommissionPerc,AlternateCustomICode,NewAvgPrice,Claimable,ClaimableDiscPerc,ItemAdvanceTaxPerc,CurrStock) ') || 'SELECT S.SiteCode,S.SRInvcode,D.Icode,D.Gcode,D.Batch,D.Expiry,D.PackQty,D.LooseQty,D.PackUnits,D.SRPrice,D.DiscPerc,D.SalesTax,D.AvgPrice,D.UnitSalesTax,D.GSTPerc,D.SRUtn,D.BonusQty,D.SalePrice,D.SaleRowId,D.RowId,D.ReturnItemDescription,D.TotalPieces,D.PiecesInHand,D.AlternatePurPrice,D.CommissionPerUnit,D.CommissionPerc,D.AlternateCustomICode,D.NewAvgPrice,D.Claimable,D.ClaimableDiscPerc,D.ItemAdvanceTaxPerc,D.CurrStock FROM SRDetail D, srledger S WHERE S.SRInvcode = D.SRInvCode AND S.SiteCode IS NOT NULL AND S.TargetSiteCode IS NOT NULL AND S.Posted=''Y'' AND S.Pushed=''N'' AND S.SRInvCode BETWEEN ') || ltrim(rtrim(dbo.tsql_str((v_sinvcode)::numeric)))) || ' AND ') || ltrim(rtrim(dbo.tsql_str((v_linvcode)::numeric))));
  END IF;
  _dq1 := v_ins_header;
  IF _dq1 IS NOT NULL THEN
    IF _dq1 ~* '^[[:space:]]*select' THEN OPEN rs1 FOR EXECUTE dbo.tsql_dyn(_dq1); ELSE EXECUTE dbo.tsql_dyn(_dq1); END IF;
  END IF;
  v_err := 0;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Data Insertion: Error Pushing S/R Header into Drop Box';
    return_value := -1;
    count := v_count;
    RETURN;
  END IF;
  _dq2 := v_ins_detail;
  IF _dq2 IS NOT NULL THEN
    IF _dq2 ~* '^[[:space:]]*select' THEN OPEN rs2 FOR EXECUTE dbo.tsql_dyn(_dq2); ELSE EXECUTE dbo.tsql_dyn(_dq2); END IF;
  END IF;
  v_err := 0;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Data Insertion: Error Pushing S/R Details into Drop Box';
    return_value := -1;
    count := v_count;
    RETURN;
  END IF;
  IF (v_custcode > 0) THEN
    UPDATE dbo.srledger SET pushed = 'Y', pushedon = localtimestamp(3), pushedby = v_usercode WHERE ((((((sitecode IS NOT NULL) AND (targetsitecode IS NOT NULL)) AND (posted = 'Y')) AND (pushed = 'N')) AND (srinvcode BETWEEN v_sinvcode AND v_linvcode)) AND (custcode = v_custcode));
  ELSE
    UPDATE dbo.srledger SET pushed = 'Y', pushedon = localtimestamp(3), pushedby = v_usercode WHERE (((((sitecode IS NOT NULL) AND (targetsitecode IS NOT NULL)) AND (posted = 'Y')) AND (pushed = 'N')) AND (srinvcode BETWEEN v_sinvcode AND v_linvcode));
  END IF;
  IF (0 <> 0) THEN
    RAISE EXCEPTION 'Data Updation: Error Updating S/R Header Info';
    return_value := -1;
    count := v_count;
    RETURN;
  END IF;
  return_value := 0;
  count := v_count;
  RETURN;
  return_value := 0;
  count := v_count;
  RETURN;
