-- ==== proc SP_DBReindex ====
CREATE OR REPLACE FUNCTION dbo.sp_dbreindex(object citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_object citext;
  v_qry citext;
  _dq1 text;
BEGIN
  v_object := object;
  -- SET NOCOUNT ON
  v_qry := (((((('dbcc dbreindex(' || '') || v_object) || '') || ', ') || '''''') || ',0) with tableresults, ALL_ERRORMSGS');
  IF (v_object IS NULL) THEN
    return_value := 0;
    RETURN;
  ELSE
    _dq1 := v_qry;
    IF _dq1 IS NOT NULL THEN
      EXECUTE dbo.tsql_dyn(_dq1);
    END IF;
  END IF;
  IF (0 <> 0) THEN
    return_value := 0;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_DeleteAdvSaleLedger ====
CREATE OR REPLACE FUNCTION dbo.sp_deleteadvsaleledger(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
BEGIN
  DELETE FROM dbo.assocadvsaleinvlist;
  IF (0 <> 0) THEN
    RAISE EXCEPTION 'Unable to Delete Associated Sales Invoices link For Advanced Sale Module';
    return_value := -1;
    RETURN;
  END IF;
  DELETE FROM dbo.advsaledetail;
  IF (0 <> 0) THEN
    RAISE EXCEPTION 'Unable to Delete Sales Invoices Detail For Advanced Sale Module';
    return_value := -1;
    RETURN;
  END IF;
  DELETE FROM dbo.advsaleledger;
  IF (0 <> 0) THEN
    RAISE EXCEPTION 'Unable to Delete Sales Invoices For Advanced Sale Module';
    return_value := -1;
    RETURN;
  END IF;
  UPDATE dbo._tabmaxkey SET tabmaxkey = CASE WHEN ((SELECT max(advsaleinvcode) FROM dbo.advsaleledger) IS NULL) THEN 0 ELSE (SELECT max(advsaleinvcode) FROM dbo.advsaleledger) END WHERE (tabname = 'AdvSaleLedger');
  IF (0 <> 0) THEN
    RAISE EXCEPTION 'Unable to Reset Sale Invoice Counter For Advanced Sale Module';
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_DeleteBasicData ====
CREATE OR REPLACE FUNCTION dbo.sp_deletebasicdata(srv citext, db citext, owner citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_del citext;
  v_sql citext;
  v_qry citext;
  v_con citext;
  v_notin citext;
  v_tablename citext;
  v_whr citext;
  v_full_table_name citext;
  v_colname citext;
  v_pkcond citext;
  v_priority smallint;
  v_keyseq smallint;
  v_table_id integer;
  v_err integer;
  v_rowcount integer;
  cur_del1 refcursor;
  _dq1 text;
  cur_del2 refcursor;
  _dq2 text;
  _fs integer := -1;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  v_del := 'DELETE ';
  v_whr := 'WHERE ';
  v_sql := ((((((' FROM ' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.');
  v_con := 'CONVERT(VarChar(10),';
  v_notin := ' NOT IN (SELECT ';
  OPEN cur_del1 FOR SELECT ltrim(rtrim(tablename)) AS tablename, priority FROM dbo.transferabledata WHERE ((enable = 'Y') AND (autodelete = 'Y')) ORDER BY priority;
  FETCH NEXT FROM cur_del1 INTO v_tablename, v_priority;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    v_pkcond := '';
    v_full_table_name := ((ltrim(rtrim(v_owner)) || '.') || v_tablename);
    -- SET @table_id = OBJECT_ID(@full_table_name)
    RAISE EXCEPTION 'untranslated T-SQL (OBJECT_ID of non-literal)' USING ERRCODE = '0A000';
    v_err := 0;
    IF ((v_err <> 0) OR (v_table_id IS NULL)) THEN
      RAISE EXCEPTION 'Data Deletion: Invalid Object Refered: Name = %', v_full_table_name;
      CLOSE cur_del1;
      -- DEALLOCATE Del1
      return_value := -1;
      RETURN;
    END IF;
    DELETE FROM dbo.reportdata;
    _dq1 := (('INSERT INTO REPORTDATA (Code1) SELECT COUNT(*) ' || v_sql) || v_tablename);
    IF _dq1 IS NOT NULL THEN
      EXECUTE dbo.tsql_dyn(_dq1);
    END IF;
    v_rowcount := trunc(coalesce((SELECT sum(code1) FROM dbo.reportdata), 0))::integer;
    IF (v_rowcount > 0) THEN
      -- OPEN Del2
      RAISE EXCEPTION 'untranslated T-SQL (system table sysindexes)' USING ERRCODE = '0A000';
      FETCH NEXT FROM cur_del2 INTO v_colname, v_keyseq;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
      WHILE (_fs = 0) LOOP
        IF (v_keyseq <> 1) THEN
          v_pkcond := (v_pkcond || ' + ');
        END IF;
        v_pkcond := ((((v_pkcond || ' ') || v_con) || ltrim(rtrim(v_colname))) || ')');
        FETCH NEXT FROM cur_del2 INTO v_colname, v_keyseq;
        IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
      END LOOP;
      CLOSE cur_del2;
      -- DEALLOCATE Del2
      v_qry := (((((((((v_del || v_tablename) || ' ') || v_whr) || v_pkcond) || v_notin) || v_pkcond) || v_sql) || v_tablename) || ')');
      _dq2 := v_qry;
      IF _dq2 IS NOT NULL THEN
        EXECUTE dbo.tsql_dyn(_dq2);
      END IF;
      v_err := 0;
      IF (v_err <> 0) THEN
        RAISE EXCEPTION 'Data Deletion: Error Transfering % Data', v_full_table_name;
        CLOSE cur_del1;
        -- DEALLOCATE Del1
        return_value := -1;
        RETURN;
      END IF;
    END IF;
    FETCH NEXT FROM cur_del1 INTO v_tablename, v_priority;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_del1;
  -- DEALLOCATE Del1
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_DeleteInvoicesFromPurDump ====
