-- ==== proc sp_DeleteItemStockBatch ====
CREATE OR REPLACE FUNCTION dbo.sp_deleteitemstockbatch(gcode integer, icode integer, batch citext, expiry timestamp, oldqty numeric, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_gcode integer;
  v_icode integer;
  v_batch citext;
  v_expiry timestamp(3);
  v_oldqty numeric(15,4);
  v_itemname citext;
  v_string_expiry citext;
  _r1 record;
  _rc integer;
BEGIN
  v_gcode := gcode;
  v_icode := icode;
  v_batch := batch;
  v_expiry := expiry;
  v_oldqty := oldqty;
  DELETE FROM dbo.godowndetail WHERE (((((godowndetail.gcode = v_gcode) AND (godowndetail.icode = v_icode)) AND (godowndetail.batch = v_batch)) AND (godowndetail.expiry = v_expiry)) AND (godowndetail.currqty = v_oldqty));
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((_rc = 0) OR (0 <> 0)) THEN
    _rc := 0;
    FOR _r1 IN SELECT name AS c1 FROM dbo.item WHERE (icode = v_icode) LOOP
      _rc := _rc + 1;
      v_itemname := _r1.c1;
    END LOOP;
    v_string_expiry := left(to_char(v_expiry, 'DD/MM/YYYY'), 25);
    _rc := 1;
    RAISE EXCEPTION 'Not enough stock available for the item (%) in batch no. (%) with expiry (%)', v_itemname, v_batch, v_string_expiry;
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_DeletePostedTransactions ====
CREATE OR REPLACE FUNCTION dbo.sp_deletepostedtransactions(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_err integer;
  v_rowid integer;
  v_script citext;
  v_stmt citext;
  v_tablename citext;
  v_maxlogid integer;
  v_keepbal citext;
  cur_c1 refcursor;
  _dq1 text;
  _fs integer := -1;
BEGIN
  v_keepbal := dbo.fn_getpreference('keep_accbal_on_archive');
  v_keepbal := coalesce(v_keepbal, 'Y');
  IF (v_keepbal = 'Y') THEN
    SELECT r.return_value INTO v_err FROM dbo.sp_virtualgl(ac_type => 'A') AS r;
    v_err := 0;
    IF ((0 <> 0) OR (v_err <> 0)) THEN
      RAISE EXCEPTION 'Problem in Executing Accounting Repository.';
      return_value := -1;
      RETURN;
    END IF;
    v_maxlogid := (coalesce((SELECT max(logid) FROM dbo.accountbalancelog), 0) + 1);
    IF (v_maxlogid <= 0) THEN
      RAISE EXCEPTION 'Problem in fetching maximum log id.';
      return_value := -1;
      RETURN;
    END IF;
    INSERT INTO dbo.accountbalancelog (logid, date, acccode, balance) SELECT v_maxlogid AS logid, localtimestamp(3) AS date, a.acccode, sum((coalesce(v.debit, 0) - coalesce(v.credit, 0))) AS balance FROM dbo.virtualgl AS v, dbo.accounts AS a WHERE (v.acccode = a.acccode) GROUP BY a.acccode HAVING (sum((coalesce(v.debit, 0) - coalesce(v.credit, 0))) <> 0);
    v_err := 0;
    IF ((0 <> 0) OR (v_err <> 0)) THEN
      RAISE EXCEPTION 'Problem in Insert Account balance log.';
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  DROP TABLE IF EXISTS tmp_del_temp;
  CREATE TEMP TABLE tmp_del_temp (
    rowid integer,
    stmt citext,
    tablename citext
) ON COMMIT DROP;
  INSERT INTO tmp_del_temp SELECT 40, 'TRUNCATE TABLE ', 'AvgPriceAdjDetail' UNION ALL SELECT 45, 'DELETE ', 'AvgPriceAdjHeader' UNION ALL SELECT 50, 'TRUNCATE TABLE ', 'PurExp' UNION ALL SELECT 60, 'DELETE ', 'PurDetail WHERE PurInvCode NOT IN (SELECT PurInvCode FROM PurLedger WHERE Posted=''N'')' UNION ALL SELECT 70, 'TRUNCATE TABLE ', 'ProformaPurDetail' UNION ALL SELECT 80, 'TRUNCATE TABLE ', 'AdvPurDetail' UNION ALL SELECT 85, 'TRUNCATE TABLE ', 'ImpPurExp' UNION ALL SELECT 90, 'TRUNCATE TABLE ', 'ImpPurDetail' UNION ALL SELECT 100, 'TRUNCATE TABLE ', 'PurRegisterDetail' UNION ALL SELECT 110, 'TRUNCATE TABLE ', 'PrDetail' UNION ALL SELECT 120, 'TRUNCATE TABLE ', 'PrAllocationDetail' UNION ALL SELECT 130, 'DELETE ', 'PrAllocationHeader' UNION ALL SELECT 140, 'DELETE ', 'PrLedger' UNION ALL SELECT 150, 'DELETE ', 'PurRegister' UNION ALL SELECT 160, 'DELETE ', 'ImpPurHeader' UNION ALL SELECT 170, 'DELETE ', 'AdvPurHeader' UNION ALL SELECT 175, 'DELETE ', 'PurPayment WHERE Posted=''Y''' UNION ALL SELECT 180, 'DELETE ', 'PurLedger WHERE Posted=''Y''' UNION ALL SELECT 190, 'TRUNCATE TABLE ', 'SaleInvDetail' UNION ALL SELECT 200, 'TRUNCATE TABLE ', 'SaleDetail' UNION ALL SELECT 210, 'TRUNCATE TABLE ', 'SaleDetailLog' UNION ALL SELECT 220, 'TRUNCATE TABLE ', 'SRDetail' UNION ALL SELECT 230, 'TRUNCATE TABLE ', 'SRBufferDetail' UNION ALL SELECT 240, 'TRUNCATE TABLE ', 'SRAllocationDetail' UNION ALL SELECT 250, 'DELETE ', 'SRAllocationHeader' UNION ALL SELECT 260, 'TRUNCATE TABLE ', 'RefusedSaleDetail' UNION ALL SELECT 270, 'DELETE ', 'RefusedSaleHeader' UNION ALL SELECT 280, 'TRUNCATE TABLE ', 'CashierWindow' UNION ALL SELECT 290, 'TRUNCATE TABLE ', 'DueAdjDetail' UNION ALL SELECT 300, 'TRUNCATE TABLE ', 'DueDeleteDetail' UNION ALL SELECT 310, 'TRUNCATE TABLE ', 'DueSatisfyDetail' UNION ALL SELECT 320, 'DELETE ', 'DueSatisfyHeader' UNION ALL SELECT 330, 'DELETE ', 'DueAdjHeader' UNION ALL SELECT 340, 'DELETE ', 'SaleLedgerLog' UNION ALL SELECT 350, 'DELETE ', 'SRBufferLedger' UNION ALL SELECT 360, 'DELETE ', 'SRLedger' UNION ALL SELECT 362, 'DELETE ', 'SaleInvGroupDetail' UNION ALL SELECT 363, 'DELETE ', 'SaleInvGroup' UNION ALL SELECT 364, 'DELETE ', 'DispatchDetail' UNION ALL SELECT 365, 'DELETE ', 'DispatchHeader' UNION ALL SELECT 366, 'DELETE ', 'SaleSetsDetail' UNION ALL SELECT 367, 'DELETE ', 'SaleSetsOrigDetail' UNION ALL SELECT 368, 'DELETE ', 'SaleSetsHeader' UNION ALL SELECT 400, 'TRUNCATE TABLE ', 'ServicePrAllocationDetail' UNION ALL SELECT 401, 'DELETE ', 'ServicePrAllocationHeader' UNION ALL SELECT 402, 'TRUNCATE TABLE ', 'ServicePrDetail' UNION ALL SELECT 403, 'DELETE ', 'ServicePrHeader' UNION ALL SELECT 404, 'TRUNCATE TABLE ', 'ServicePurDetail' UNION ALL SELECT 405, 'DELETE ', 'ServicePurHeader' UNION ALL SELECT 406, 'TRUNCATE TABLE ', 'ServiceSrAllocationDetail' UNION ALL SELECT 407, 'DELETE ', 'ServiceSrAllocationHeader' UNION ALL SELECT 408, 'DELETE ', 'ServiceRDetail' UNION ALL SELECT 409, 'DELETE ', 'ServiceRHeader' UNION ALL SELECT 410, 'DELETE ', 'ServiceDetail' UNION ALL SELECT 411, 'DELETE ', 'ServiceHeader' UNION ALL SELECT 430, 'DELETE ', 'SaleLedger' UNION ALL SELECT 440, 'TRUNCATE TABLE ', 'ItemConversionDetail' UNION ALL SELECT 441, 'DELETE ', 'ItemConversionHeader' UNION ALL SELECT 442, 'TRUNCATE TABLE ', 'AdjBufferDetail' UNION ALL SELECT 443, 'DELETE ', 'AdjBufferHeader' UNION ALL SELECT 444, 'TRUNCATE TABLE ', 'AdjDetail' UNION ALL SELECT 445, 'DELETE ', 'AdjHeader' UNION ALL SELECT 446, 'TRUNCATE TABLE ', 'TDetail' UNION ALL SELECT 450, 'DELETE ', 'Theader' UNION ALL SELECT 460, 'TRUNCATE TABLE ', 'TransferRequisitionDetail' UNION ALL SELECT 470, 'DELETE ', 'TransferRequisitionHeader' UNION ALL SELECT 480, 'TRUNCATE TABLE ', 'ProdDetail' UNION ALL SELECT 490, 'TRUNCATE TABLE ', 'ProdBuffer' UNION ALL SELECT 500, 'DELETE ', 'ProdHeader' UNION ALL SELECT 510, 'TRUNCATE TABLE ', 'IssueDetail' UNION ALL SELECT 520, 'DELETE ', 'IssueHeader' UNION ALL SELECT 530, 'TRUNCATE TABLE ', 'IssueReqDetail' UNION ALL SELECT 540, 'DELETE ', 'IssueReqHeader' UNION ALL SELECT 550, 'TRUNCATE TABLE ', 'ReceiptDetail' UNION ALL SELECT 560, 'DELETE ', 'ReceiptHeader' UNION ALL SELECT 705, 'TRUNCATE TABLE ', 'TransactionDetail' UNION ALL SELECT 710, 'DELETE ', 'TransactionHeader' UNION ALL SELECT 720, 'TRUNCATE TABLE ', 'GLDetail' UNION ALL SELECT 730, 'DELETE ', 'GLHeader' UNION ALL SELECT 740, 'TRUNCATE TABLE ', 'NotesDetail' UNION ALL SELECT 750, 'DELETE ', 'Notes';
  OPEN cur_c1 FOR SELECT rowid, stmt, tablename FROM tmp_del_temp AS del_temp ORDER BY rowid;
  FETCH NEXT FROM cur_c1 INTO v_rowid, v_stmt, v_tablename;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    IF (v_tablename = 'SRBufferLedger') THEN
      UPDATE dbo.saleledger SET srbufferinvcode = NULL::integer WHERE (srbufferinvcode > 0);
    END IF;
    IF (v_tablename = 'SaleLedger') THEN
      UPDATE dbo.billsummarydetail SET saleinvcode = NULL::integer WHERE (saleinvcode > 0);
      UPDATE dbo.billsummarydetail SET saleinvcode = NULL::integer WHERE (saleinvcode > 0);
      UPDATE dbo.serviceheader SET saleinvcode = NULL::integer WHERE (saleinvcode > 0);
    END IF;
    v_script := (v_stmt || v_tablename);
    _dq1 := v_script;
    IF _dq1 IS NOT NULL THEN
      EXECUTE dbo.tsql_dyn(_dq1);
    END IF;
    v_err := 0;
    IF (v_err <> 0) THEN
      RAISE EXCEPTION 'Problem in Data Deletion. Problem in deleting %', v_tablename;
      CLOSE cur_c1;
      -- DEALLOCATE C1
      return_value := -1;
      RETURN;
    END IF;
    FETCH NEXT FROM cur_c1 INTO v_rowid, v_stmt, v_tablename;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_c1;
  -- DEALLOCATE C1
  TRUNCATE TABLE dbo.virtualgl;
  IF (v_keepbal = 'Y') THEN
    INSERT INTO dbo.virtualgl (documentcode, documenttype, acccode, catcode, alternateacccode, debit, credit, date, checkno, remarks, usercode, patientcode, vouchercode, invoicecode, outstandingamt, balance, invoicetype, vrow, grn, gccode, vehicle, shipto, guestcode, studentcode) SELECT 1 AS documentcode, 'TV' AS documenttype, l.acccode, 1 AS catcode, NULL::smallint AS alternateacccode, sum(CASE WHEN (balance > 0) THEN abs(balance) ELSE 0 END) AS debit, sum(CASE WHEN (balance < 0) THEN abs(balance) ELSE 0 END) AS credit, l.date, NULL::citext AS checkno, 'Balance B/F:' AS remarks, 1 AS usercode, NULL::integer AS patientcode, 1 AS vouchercode, NULL::integer AS invoicecode, 0 AS outstandingamt, 0 AS balance, NULL::smallint AS invoicetype, 0 AS vrow, NULL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto, NULL::integer AS guestcode, NULL::integer AS studentcode FROM dbo.accountbalancelog AS l, dbo.accounts AS a WHERE ((l.logid = v_maxlogid) AND (l.acccode = a.acccode)) GROUP BY l.acccode, a.name, l.date ORDER BY a.name;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_DeleteSaleInvoice_Bulk ====
CREATE OR REPLACE FUNCTION dbo.sp_deletesaleinvoice_bulk(sinvcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_sinvcode integer;
  v_postedcount integer;
  v_linvcode integer;
  v_err integer;
  v_icode integer;
  v_cursorrows integer;
  v_rt_code integer;
  v_gcode smallint;
  v_batch citext;
  v_expiry timestamp(3);
  v_qty numeric(15,4);
  v_currqty numeric(15,4);
  v_newqty numeric(15,4);
  cur_c1 refcursor;
  _fs integer := -1;
BEGIN
  v_sinvcode := sinvcode;
  v_postedcount := coalesce((SELECT count(saleinvcode) FROM dbo.saleledger WHERE ((saleinvcode >= v_sinvcode) AND (posted = 'Y'))), 0);
  v_linvcode := coalesce((SELECT max(saleinvcode) FROM dbo.saleledger), 0);
  IF (v_postedcount > 0) THEN
    RAISE EXCEPTION '% Posted Sale Invoice(s) exist within the range: [% to %]~r~nTherefore can not delete sale invoices', v_postedcount, v_sinvcode, v_linvcode;
    return_value := -1;
    RETURN;
  END IF;
  DELETE FROM dbo.saledetaillog WHERE (saleinvcode >= v_sinvcode);
  v_err := 0;
  IF (v_err <> 0) THEN
    RAISE EXCEPTION 'Problem in truncating Sale Invoice log Details';
    return_value := -1;
    RETURN;
  END IF;
  DELETE FROM dbo.saleledgerlog WHERE (saleinvcode >= v_sinvcode);
  v_err := 0;
  IF (v_err <> 0) THEN
    RAISE EXCEPTION 'Problem in truncating Sale Invoice log';
    return_value := -1;
    RETURN;
  END IF;
  OPEN cur_c1 FOR SELECT d.gcode, d.icode, d.batch, d.expiry, sum((d.looseqty + d.bonusqty)) AS qty FROM dbo.saleledger AS s, dbo.saledetail AS d WHERE ((((s.posted = 'N') AND (s.saleinvcode >= v_sinvcode)) AND (s.saleinvcode = d.saleinvcode)) AND (d.due IS NULL)) GROUP BY d.icode, d.gcode, d.batch, d.expiry ORDER BY d.icode, d.gcode, d.batch, d.expiry;
  v_cursorrows := (-1);
  IF (v_cursorrows <= 0) THEN
    RAISE EXCEPTION 'Problem in deletion of sale invoices.~r~nReason:- No Items found in these sale invoices ';
    CLOSE cur_c1;
    -- DEALLOCATE C1
    return_value := -1;
    RETURN;
  END IF;
  FETCH NEXT FROM cur_c1 INTO v_gcode, v_icode, v_batch, v_expiry, v_qty;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    SELECT r.return_value, r.qty INTO v_rt_code, v_currqty FROM dbo.sp_getitemstockbatch(gcode => (v_gcode)::integer, icode => v_icode, batch => v_batch, expiry => v_expiry, qty => v_currqty) AS r;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      RAISE EXCEPTION 'Problem in fetching stock for items';
      CLOSE cur_c1;
      -- DEALLOCATE C1
      return_value := -1;
      RETURN;
    END IF;
    v_newqty := (v_currqty + v_qty);
    SELECT r.return_value INTO v_rt_code FROM dbo.sp_updateitemstockbatch(gcode => (v_gcode)::integer, icode => v_icode, batch => v_batch, expiry => v_expiry, newqty => v_newqty) AS r;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      RAISE EXCEPTION 'Problem in updation of stock for items';
      CLOSE cur_c1;
      -- DEALLOCATE C1
      return_value := -1;
      RETURN;
    END IF;
    FETCH NEXT FROM cur_c1 INTO v_gcode, v_icode, v_batch, v_expiry, v_qty;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_c1;
  -- DEALLOCATE C1
  DELETE FROM dbo.saledetail WHERE (saleinvcode >= v_sinvcode);
  v_err := 0;
  IF (v_err <> 0) THEN
    RAISE EXCEPTION 'Problem in truncating Sale Invoice Details';
    return_value := -1;
    RETURN;
  END IF;
  DELETE FROM dbo.saleledger WHERE (saleinvcode >= v_sinvcode);
  v_err := 0;
  IF (v_err <> 0) THEN
    RAISE EXCEPTION 'Problem in truncating Sale Invoice Details';
    return_value := -1;
    RETURN;
  END IF;
  UPDATE dbo._tabmaxkey SET tabmaxkey = coalesce((SELECT max(saleinvcode) FROM dbo.saleledger), 0) WHERE (tabname = 'SaleLedger');
  v_err := 0;
  IF (v_err <> 0) THEN
    RAISE EXCEPTION 'Problem in Updating Sale Invoice Counter';
    return_value := -1;
    RETURN;
  END IF;
  UPDATE dbo._headertabmaxkey SET tabmaxkey = coalesce((SELECT max(sl.headerinvno) FROM dbo.saleledger AS sl WHERE (sl.headerno = _headertabmaxkey.headercode)), 0) WHERE (module = 1);
  v_err := 0;
  IF (v_err <> 0) THEN
    RAISE EXCEPTION 'Problem in Updating Header Wise Sale Invoice Counter';
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_DeleteSyncedTransactions ====
CREATE OR REPLACE FUNCTION dbo.sp_deletesyncedtransactions(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_err integer;
  v_syncablerows integer;
  v_rowid integer;
  v_tablename citext;
  v_archaccdata citext;
  v_synchronize citext;
  v_parenttable citext;
  v_parentpk citext;
  v_updateparent citext;
  v_posted citext;
  v_qry citext;
  v_maxlogid integer;
  v_keepbal citext;
  v_deletesyncedtran citext;
  cur_c1 refcursor;
  _dq1 text;
  _fs integer := -1;
BEGIN
  v_deletesyncedtran := dbo.fn_getpreference('deletesyncedtransactions');
  v_deletesyncedtran := coalesce(v_deletesyncedtran, 'N');
  IF (v_deletesyncedtran = 'N') THEN
    return_value := 0;
    RETURN;
  END IF;
  v_keepbal := dbo.fn_getpreference('keep_accbal_on_archive');
  v_keepbal := coalesce(v_keepbal, 'Y');
  v_archaccdata := dbo.fn_getpreference('archiveaccountingdata');
  IF (v_keepbal = 'Y') THEN
    SELECT r.return_value INTO v_err FROM dbo.sp_virtualgl(ac_type => 'A') AS r;
    v_err := 0;
    IF ((0 <> 0) OR (v_err <> 0)) THEN
      RAISE EXCEPTION 'Problem in Executing Accounting Repository.';
      return_value := -1;
      RETURN;
    END IF;
    v_maxlogid := (coalesce((SELECT max(logid) FROM dbo.accountbalancelog), 0) + 1);
    IF (v_maxlogid <= 0) THEN
      RAISE EXCEPTION 'Problem in fetching maximum log id.';
      return_value := -1;
      RETURN;
    END IF;
    INSERT INTO dbo.accountbalancelog (logid, date, acccode, balance) SELECT v_maxlogid AS logid, localtimestamp(3) AS date, a.acccode, sum((coalesce(v.debit, 0) - coalesce(v.credit, 0))) AS balance FROM dbo.virtualgl AS v, dbo.accounts AS a WHERE (v.acccode = a.acccode) GROUP BY a.acccode HAVING (sum((coalesce(v.debit, 0) - coalesce(v.credit, 0))) <> 0);
    v_err := 0;
    IF ((0 <> 0) OR (v_err <> 0)) THEN
      RAISE EXCEPTION 'Problem in Insert Account balance log.';
      return_value := -1;
      RETURN;
    END IF;
    TRUNCATE TABLE dbo.virtualgl;
    INSERT INTO dbo.virtualgl (documentcode, documenttype, acccode, catcode, alternateacccode, debit, credit, date, checkno, remarks, usercode, patientcode, vouchercode, invoicecode, outstandingamt, balance, invoicetype, vrow, grn, gccode, vehicle, shipto, guestcode, studentcode) SELECT 1 AS documentcode, 'TV' AS documenttype, l.acccode, 1 AS catcode, NULL::smallint AS alternateacccode, sum(CASE WHEN (balance > 0) THEN abs(balance) ELSE 0 END) AS debit, sum(CASE WHEN (balance < 0) THEN abs(balance) ELSE 0 END) AS credit, l.date, NULL::citext AS checkno, 'Balance B/F:' AS remarks, 1 AS usercode, NULL::integer AS patientcode, 1 AS vouchercode, NULL::integer AS invoicecode, 0 AS outstandingamt, 0 AS balance, NULL::smallint AS invoicetype, 0 AS vrow, NULL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto, NULL::integer AS guestcode, NULL::integer AS studentcode FROM dbo.accountbalancelog AS l, dbo.accounts AS a WHERE ((l.logid = v_maxlogid) AND (l.acccode = a.acccode)) GROUP BY l.acccode, a.name, l.date ORDER BY a.name;
  END IF;
  DROP TABLE IF EXISTS tmp_ins_temp;
  CREATE TEMP TABLE tmp_ins_temp (
    rowid integer,
    tablename citext,
    synchronize citext,
    parenttable citext,
    parentpk citext,
    updateparent citext,
    posted citext
) ON COMMIT DROP;
