, 'ServiceRDetail', 'Y', 'ServiceRHeader', 'ServiceRInvCode', 'Y', 'Y' UNION ALL SELECT 740, 'ServiceSrAllocationHeader', 'Y', NULL::citext, 'ServiceSrAllocationCode', 'N', 'Y' UNION ALL SELECT 750, 'ServiceSrAllocationDetail', 'Y', 'ServiceSrAllocationHeader', 'ServiceSrAllocationCode', 'Y', 'Y' UNION ALL SELECT 760, 'ServicePurHeader', 'Y', NULL::citext, 'ServicePurInvCode', 'N', 'Y' UNION ALL SELECT 770, 'ServicePurDetail', 'Y', 'ServicePurHeader', 'ServicePurInvCode', 'Y', 'Y' UNION ALL SELECT 780, 'ServicePrHeader', 'Y', NULL::citext, 'ServicePrInvCode', 'N', 'Y' UNION ALL SELECT 790, 'ServicePrDetail', 'Y', 'ServicePrHeader', 'ServicePrInvCode', 'Y', 'Y' UNION ALL SELECT 800, 'ServicePrAllocationHeader', 'Y', NULL::citext, 'ServicePrAllocationCode', 'N', 'Y' UNION ALL SELECT 810, 'ServicePrAllocationDetail', 'Y', 'ServicePrAllocationHeader', 'ServicePrAllocationCode', 'Y', 'Y' UNION ALL SELECT 1010, 'GLHeader', v_archaccdata, NULL::citext, 'GLVochCode', 'N', 'Y' UNION ALL SELECT 1020, 'GLDetail', v_archaccdata, 'GLHeader', 'GLVochCode', 'Y', 'Y' UNION ALL SELECT 1030, 'Notes', v_archaccdata, NULL::citext, 'NoteCode', 'Y', 'Y' UNION ALL SELECT 1040, 'NotesDetail', v_archaccdata, 'Notes', 'NoteCode', 'Y', 'Y' UNION ALL SELECT 1050, 'TransactionHeader', v_archaccdata, NULL::citext, 'DocumentCode', 'N', 'Y' UNION ALL SELECT 1060, 'TransactionDetail', v_archaccdata, 'TransactionHeader', 'DocumentCode', 'Y', 'Y' UNION ALL SELECT 1065, 'AvgPriceAdjHeader', v_archaccdata, NULL::citext, 'DocumentCode', 'N', 'Y' UNION ALL SELECT 1070, 'AvgPriceAdjDetail', v_archaccdata, 'AvgPriceAdjHeader', 'DocumentCode', 'Y', 'Y';
  OPEN cur_c1 FOR SELECT rowid, tablename, synchronize, parenttable, parentpk, updateparent, posted FROM tmp_ins_temp AS ins_temp ORDER BY rowid DESC;
  FETCH NEXT FROM cur_c1 INTO v_rowid, v_tablename, v_synchronize, v_parenttable, v_parentpk, v_updateparent, v_posted;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    v_qry := '';
    IF (v_synchronize = 'Y') THEN
      IF (v_parenttable IS NULL) THEN
        IF (v_tablename = 'SRBufferLedger') THEN
          UPDATE dbo.saleledger SET srbufferinvcode = NULL::integer WHERE (srbufferinvcode > 0);
        END IF;
        IF (v_tablename = 'SaleLedger') THEN
          UPDATE dbo.billsummarydetail SET saleinvcode = NULL::integer WHERE (saleinvcode > 0);
          UPDATE dbo.billsummarydetail SET saleinvcode = NULL::integer WHERE (saleinvcode > 0);
          UPDATE dbo.serviceheader SET saleinvcode = NULL::integer WHERE (saleinvcode > 0);
        END IF;
        v_qry := (('DELETE ' || v_tablename) || ' WHERE Synced = ''Y''');
      ELSE
        v_qry := (((((((('DELETE ' || v_tablename) || ' WHERE ') || v_parentpk) || ' IN (SELECT ') || v_parentpk) || ' FROM ') || v_parenttable) || ' WHERE Synced = ''Y'')');
      END IF;
      IF (length(rtrim(ltrim(rtrim(v_qry)))) > 0) THEN
        RAISE NOTICE '%', v_qry;
        _dq1 := v_qry;
        IF _dq1 IS NOT NULL THEN
          EXECUTE dbo.tsql_dyn(_dq1);
        END IF;
        v_err := 0;
        IF ((0 <> 0) OR (v_err <> 0)) THEN
          RAISE EXCEPTION 'Data Deletion: Error Transfering % Data', v_tablename;
          CLOSE cur_c1;
          -- DEALLOCATE C1
          return_value := -1;
          RETURN;
        END IF;
      END IF;
    END IF;
    FETCH NEXT FROM cur_c1 INTO v_rowid, v_tablename, v_synchronize, v_parenttable, v_parentpk, v_updateparent, v_posted;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_c1;
  -- DEALLOCATE C1
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_Drop_Constraint ====
CREATE OR REPLACE FUNCTION dbo.sp_drop_constraint(tablename citext, constrainttype citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_tablename citext;
  v_constrainttype citext;
  v_stmt citext;
  v_constraint citext;
  _dq1 text;
BEGIN
  v_tablename := tablename;
  v_constrainttype := constrainttype;
  v_stmt := 'ALTER TABLE ';
  -- SET @Constraint = (SELECT so2.Name FROM SysObjects so, SysConstraints sc, sysobjects so2 WHERE so.Name=@TableName AND so.id = sc.id AND sc.ConstID = so2.id AND so2.xtype=@ConstraintType)
  RAISE EXCEPTION 'untranslated T-SQL (system table SysObjects)' USING ERRCODE = '0A000';
  IF (length(rtrim(ltrim(rtrim(v_constraint)))) <= 0) THEN
    return_value := 0;
    RETURN;
  END IF;
  v_stmt := ((('ALTER TABLE DBO.' || ltrim(rtrim(v_tablename))) || ' DROP CONSTRAINT ') || v_constraint);
  _dq1 := v_stmt;
  IF _dq1 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq1);
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

