DECLARE
  v_constcount integer;
  v_loopcount integer;
  v_priority numeric(6,2);
  v_table citext;
  v_col citext;
  v_const citext;
  v_stmt citext;
  v_oldtable citext;
  cur_c1 refcursor;
  _dq1 text;
  _fs integer := -1;
BEGIN
  -- OPEN C1
  RAISE EXCEPTION 'untranslated T-SQL (system table sysobjects)' USING ERRCODE = '0A000';
  FETCH NEXT FROM cur_c1 INTO v_table, v_col, v_priority, v_const;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    v_stmt := ((('ALTER TABLE DBO.' || ltrim(rtrim(v_table))) || ' DROP CONSTRAINT ') || ltrim(rtrim(v_const)));
    _dq1 := v_stmt;
    IF _dq1 IS NOT NULL THEN
      EXECUTE dbo.tsql_dyn(_dq1);
    END IF;
    FETCH NEXT FROM cur_c1 INTO v_table, v_col, v_priority, v_const;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_c1;
  -- DEALLOCATE C1
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

