-- ==== proc sp_Empty_DataCarryDB ====
CREATE OR REPLACE FUNCTION dbo.sp_empty_datacarrydb(srv citext, db citext, owner citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_tablename citext;
  v_query citext;
  v_rows integer;
  v_row integer;
  v_inrow integer;
  _dq1 text;
  _dq2 text;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  -- SET NOCOUNT ON
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  DROP TABLE IF EXISTS tv_sp_empty_datacarrydb_transtable;
  CREATE TEMP TABLE tv_sp_empty_datacarrydb_transtable (
    tablename citext NOT NULL,
    id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL
) ON COMMIT DROP;
  INSERT INTO tv_sp_empty_datacarrydb_transtable (tablename) SELECT 'GodownDetail' UNION SELECT 'SaleDetail' UNION SELECT 'SaleLedger' UNION SELECT 'PrDetail' UNION SELECT 'PrLedger' UNION SELECT 'PrDetail' UNION SELECT 'PurOrderHeader' UNION SELECT 'PurOrderDetail ' UNION SELECT 'SaleOrderHeader ' UNION SELECT 'SaleOrderDetail ' UNION SELECT 'ServiceDetail ' UNION SELECT 'ServiceHeader ' UNION SELECT 'QuotationDetail ' UNION SELECT 'QuotationHeader ' UNION SELECT 'PurDetail ' UNION SELECT 'PurLedger ' UNION SELECT 'ExpiryIntimation ' UNION SELECT 'ExpiryIntimationDetail ' UNION SELECT tablename FROM dbo.transferabledata WHERE (((((enable = 'Y') AND (autoupdate = 'Y')) OR (autoinsert = 'Y')) OR (autodelete = 'Y')) OR (updatetabmaxkey = 'Y'));
  v_rows := coalesce((SELECT count(tablename) FROM tv_sp_empty_datacarrydb_transtable AS transtable), 0);
  v_row := 1;
  WHILE ((v_rows > 0) AND (v_row <= v_rows)) LOOP
    v_tablename := (SELECT tablename FROM tv_sp_empty_datacarrydb_transtable AS transtable WHERE (id = v_row));
    v_query := ((((((('Delete From ' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.') || v_tablename);
    IF ((lower(v_tablename))::citext = 'item') THEN
      v_inrow := 1;
      WHILE (v_inrow <= 40) LOOP
        v_query := ((((((('Delete From ' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.item WHERE ICode < ') || ltrim(rtrim(dbo.tsql_str(((50000 * v_inrow))::numeric))));
        _dq1 := v_query;
        IF _dq1 IS NOT NULL THEN
          EXECUTE dbo.tsql_dyn(_dq1);
        END IF;
        IF (0 <> 0) THEN
          RAISE EXCEPTION 'Some Problem occur in emptying DataCarryDB, Table Name = %', v_tablename;
          return_value := -1;
          RETURN;
        END IF;
        v_inrow := (v_inrow + 1);
      END LOOP;
    ELSE
      _dq2 := v_query;
      IF _dq2 IS NOT NULL THEN
        EXECUTE dbo.tsql_dyn(_dq2);
      END IF;
      IF (0 <> 0) THEN
        RAISE EXCEPTION 'Some Problem occur in emptying DataCarryDB, Table Name = %', v_tablename;
        return_value := -1;
        RETURN;
      END IF;
    END IF;
    v_row := (v_row + 1);
  END LOOP;
  return_value := 1;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_executelocal ====
CREATE OR REPLACE FUNCTION dbo.sp_executelocal(query citext, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_query citext;
BEGIN
  v_query := query;
  TRUNCATE TABLE dbo.reportdata;
  EXECUTE coalesce('INSERT INTO dbo.reportdata (name10, name11, name1, name2, value17, value18) ' || v_query, 'SELECT 1');
  OPEN rs1 FOR SELECT name10, name11, name1 FROM dbo.reportdata;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_ExpiryIntimation_From_DataCarryDB ====
CREATE OR REPLACE FUNCTION dbo.sp_expiryintimation_from_datacarrydb(srv citext, db citext, owner citext, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_query citext;
  _dq1 text;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  v_query := ((((((('Select IntimationCode, IntimationTypeCode, Date, RefNo, Remarks1, Remarks2 From 	' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.') || 'ExpiryIntimation');
  _dq1 := v_query;
  IF _dq1 IS NOT NULL THEN
    IF _dq1 ~* '^[[:space:]]*select' THEN OPEN rs1 FOR EXECUTE dbo.tsql_dyn(_dq1); ELSE EXECUTE dbo.tsql_dyn(_dq1); END IF;
  END IF;
  return_value := 1;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_ExpiryIntimationList_From_DropBox ====
CREATE OR REPLACE FUNCTION dbo.sp_expiryintimationlist_from_dropbox(srv citext, db citext, owner citext, sitecode integer, intimationtypecode smallint, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_sitecode integer;
  v_intimationtypecode smallint;
  v_query citext;
  v_prefix citext;
  _dq1 text;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  v_sitecode := sitecode;
  v_intimationtypecode := intimationtypecode;
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  v_prefix := '';
  IF (((length(rtrim(ltrim(rtrim(v_srv)))) = 0) OR (v_srv IS NULL))) THEN
    v_prefix := '';
  ELSE
    v_prefix := (v_srv || '.');
  END IF;
  IF (((length(rtrim(ltrim(rtrim(v_db)))) = 0) OR (v_db IS NULL))) THEN
    v_prefix := v_prefix;
  ELSE
    v_prefix := ((v_prefix || v_db) || '.');
  END IF;
  IF (((length(rtrim(ltrim(rtrim(v_owner)))) = 0) OR (v_owner IS NULL))) THEN
    v_prefix := ((v_prefix || 'DBO') || '.');
  ELSE
    v_prefix := ((v_prefix || v_owner) || '.');
  END IF;
  v_query := ((((('Select SiteCode, Site=(SELECT Site.Name + SPACE(1) + CHAR(45) + SPACE(1) + InstanceID FROM Site WHERE Site.Sitecode = T.SiteCode), T.IntimationCode, T.IntimationTypeCode, T.Date, T.RefNo, T.Remarks1, T.Remarks2 From ' || v_prefix) || 'DB_ExpiryIntimation AS T WHERE T.TargetSiteCode = ') || ltrim(rtrim(dbo.tsql_str((v_sitecode)::numeric)))) || ' AND T.Pulled = ''N'' AND T.IntimationTypeCode = ') || ltrim(rtrim(dbo.tsql_str((v_intimationtypecode)::numeric))));
  _dq1 := v_query;
  IF _dq1 IS NOT NULL THEN
    IF _dq1 ~* '^[[:space:]]*select' THEN OPEN rs1 FOR EXECUTE dbo.tsql_dyn(_dq1); ELSE EXECUTE dbo.tsql_dyn(_dq1); END IF;
  END IF;
  return_value := 1;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_Export_Stock_To_DataCarryDB ====
CREATE OR REPLACE FUNCTION dbo.sp_export_stock_to_datacarrydb(srv citext, db citext, owner citext, exportstock citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_exportstock citext;
  v_tablename citext;
  v_query citext;
  _dq1 text;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  v_exportstock := exportstock;
  -- SET NOCOUNT ON
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  v_tablename := '';
  v_query := ((((((('INSERT INTO ' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.') || 'GodownDetail (GCode, ICode, CurrQty, Batch, Expiry, Priority, ManfDate) SELECT GCode, ICode, CurrQty, Batch, Expiry, Priority, ManfDate FROM GodownDetail ');
  _dq1 := v_query;
  IF _dq1 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq1);
  END IF;
  IF (0 <> 0) THEN
    RAISE EXCEPTION 'Some Problem occur in exporting stock in hand to DataCarryDB';
    return_value := -1;
    RETURN;
  END IF;
  return_value := 1;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_ExtractExpiryIntimation ====
CREATE OR REPLACE FUNCTION dbo.sp_extractexpiryintimation(usercode smallint, consolidatedintimation integer, grouptype citext, grouplist citext, acccode smallint, custcode smallint, type smallint, INOUT intimationcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_usercode smallint;
  v_consolidatedintimation integer;
  v_grouptype citext;
  v_grouplist citext;
  v_acccode smallint;
  v_custcode smallint;
  v_type smallint;
  v_intimationcode integer;
  v_continue integer;
  v_rt_code integer;
  v_err integer;
  v_totalrows integer;
  v_rowcount integer;
  v_counter integer;
  v_serialno integer;
  _rc integer;
BEGIN
  v_usercode := usercode;
  v_consolidatedintimation := consolidatedintimation;
  v_grouptype := grouptype;
  v_grouplist := grouplist;
  v_acccode := acccode;
  v_custcode := custcode;
  v_type := type;
  v_intimationcode := intimationcode;
  -- SET NOCOUNT ON
  IF (v_consolidatedintimation <= 0) THEN
    RAISE EXCEPTION 'No Expiry Intimation Selected';
    return_value := -1;
    intimationcode := v_intimationcode;
    RETURN;
  END IF;
  DROP TABLE IF EXISTS tv_sp_extractexpiryintimation_tab_itemlist;
  CREATE TEMP TABLE tv_sp_extractexpiryintimation_tab_itemlist (
    code integer NOT NULL
) ON COMMIT DROP;
  IF ((v_grouptype = 'S') AND (v_grouplist = 'S')) THEN
    INSERT INTO tv_sp_extractexpiryintimation_tab_itemlist SELECT DISTINCT icode FROM dbo.itemsuppliers WHERE (suppcode = v_acccode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
  ELSE
    INSERT INTO tv_sp_extractexpiryintimation_tab_itemlist SELECT code FROM dbo.udf_selectitems(v_grouptype, v_grouplist) AS udf_selectitems;
    GET DIAGNOSTICS _rc = ROW_COUNT;
  END IF;
  v_totalrows := coalesce((SELECT count(d.icode) FROM (SELECT code FROM tv_sp_extractexpiryintimation_tab_itemlist AS tab_itemlist) AS i, dbo.expiryintimationdetail AS d WHERE ((d.intimationcode = v_consolidatedintimation) AND (d.icode = i.code))), 0);
  _rc := 1;
  IF ((v_totalrows IS NULL) OR (v_totalrows <= 0)) THEN
    return_value := 0;
    intimationcode := v_intimationcode;
    RETURN;
  END IF;
  SELECT r.return_value, r.key INTO v_rt_code, v_intimationcode FROM dbo.sp_gettabmaxkey(tabname => 'ExpiryIntimation', key => v_intimationcode) AS r;
  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
    RAISE EXCEPTION 'New Expiry Intimation Code Generation Problem';
    return_value := -1;
    intimationcode := v_intimationcode;
    RETURN;
  END IF;
  v_serialno := coalesce((SELECT counter FROM dbo.intimationtype WHERE (intimationtypecode = v_type) FOR UPDATE OF intimationtype), 0);
  _rc := 1;
  IF (v_serialno > 0) THEN
    v_serialno := (v_serialno + 1);
    _rc := 1;
    UPDATE dbo.intimationtype SET counter = v_serialno WHERE (intimationtypecode = v_type);
    GET DIAGNOSTICS _rc = ROW_COUNT;
  END IF;
  INSERT INTO dbo.expiryintimation (intimationcode, intimationtypecode, intimationserialno, acccode, date, refno, remarks1, remarks2, usercode, posted, postedby, postdate, custcode) VALUES (v_intimationcode, v_type, v_serialno, v_acccode, localtimestamp(3), '', 'Extracted Expiry Intimation', ('Consolidated Intimation Code = ' || ltrim(rtrim(dbo.tsql_str((v_consolidatedintimation)::numeric)))), v_usercode, 'N', v_usercode, localtimestamp(3), v_custcode);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((0 <> 0) OR (_rc = 0)) THEN
    RAISE EXCEPTION 'Expiry Intimation Header Row Insertion Problem for Expiry Intimation Code %', v_intimationcode;
    return_value := -1;
    intimationcode := v_intimationcode;
    RETURN;
  END IF;
  INSERT INTO dbo.expiryintimationdetail (intimationcode, icode, batch, expiry, qty, packunits, packprice, price, invoicecode, invoicedate, refno, refdate, lastacccode, manfcode) SELECT t.intimationcode, t.icode, t.batch, t.expiry, t.qty, t.packunits, t.packprice, t.price, t.invoicecode, t.invoicedate, t.refno, t.refdate, t.lastacccode, t.manfcode FROM (SELECT v_intimationcode AS intimationcode, d.icode, d.batch, d.expiry, d.qty, d.packunits, d.packprice, d.price, d.invoicecode, d.invoicedate, d.refno, d.refdate, d.rowid, d.lastacccode, d.manfcode FROM dbo.expiryintimationdetail AS d, dbo.expiryintimation AS h, (SELECT code FROM tv_sp_extractexpiryintimation_tab_itemlist AS tab_itemlist) AS i WHERE (((h.intimationcode = v_consolidatedintimation) AND (h.intimationcode = d.intimationcode)) AND (d.icode = i.code))) AS t, dbo.item AS i WHERE (t.icode = i.icode) ORDER BY t.rowid;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((0 <> 0) OR (_rc = 0)) THEN
    RAISE EXCEPTION 'Expiry Intimation Detail Row Insertion Problem for Expiry Intimation Code =%', v_intimationcode;
    return_value := -1;
    intimationcode := v_intimationcode;
    RETURN;
  END IF;
  return_value := 0;
  intimationcode := v_intimationcode;
  RETURN;
  return_value := 0;
  intimationcode := v_intimationcode;
  RETURN;
END
$body$;

-- ==== proc SP_Fetch_AccountBalance_OnRemote ====
CREATE OR REPLACE FUNCTION dbo.sp_fetch_accountbalance_onremote(acccode integer, date timestamp, INOUT balance numeric, OUT return_value integer)
