-- ==== proc SP_Fetch_ChildServerSales ====
CREATE OR REPLACE FUNCTION dbo.sp_fetch_childserversales(srv citext, db citext, owner citext, usercode smallint, OUT return_value integer, OUT rs1 refcursor, OUT rs2 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_usercode smallint;
  v_ins citext;
  v_sql citext;
  v_whr citext;
  v_whr_cln citext;
  v_query citext;
  v_stdate citext;
  v_edate citext;
  v_err integer;
  v_rt_code integer;
  v_saletype integer;
  v_dt timestamp(3);
  v_prefix citext;
  v_inqry citext;
  _dq1 text;
  _dq2 text;
  _dq3 text;
  _dq4 text;
  _dq5 text;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  v_usercode := usercode;
  -- SET XACT_ABORT ON
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  v_prefix := ((((ltrim(rtrim(v_srv)) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner)));
  v_saletype := 1;
  v_whr := (((((((' WHERE Posted=''Y'' AND Transmit = ' || chr(39)) || 'Y') || chr(39)) || ' AND Transmited = ') || chr(39)) || 'N') || chr(39));
  WHILE (v_saletype <= 3) LOOP
    DELETE FROM dbo.reportdata;
    IF (v_saletype = 1) THEN
      v_ins := 'INSERT INTO IMP_SaleLedger ';
      v_sql := (((((' SELECT ServerName=' || '''') || v_srv) || ''', TransDate=GETDATE(), InvType = 1, SaleInvCode, SaleCatCode , CustCode , SalesmanCode, date, DiscPerc, FlatDisc, MiscCharges, SalesTax, Posted, PostDate, Remarks, CustRefNo, headerno, headerinvno, OriginalDate, ModifiedBy, PostedBy, SPrice, QuotationNo, DoctCode, PatientCode, RePrintingCounter, CashReceived, InvGSTPerc1, PrintWaranty, PrintBatch, MessageCode, SManCode, InvoiceSize, CustRefno2, CustRefno3, CustRefno4, GSTNO, InvTotal, MachineName, ModifyCounter, itemdiscpercno, RelationCode, DiseaseCode, WardCode, AdmissionCode, ReturnCounter, Paid, BillingDate, UnReceivedBalance, TotalOfSaleReturns, ListOfSrInvoices, printbalance, AccountFor, PaymentMode, PaymentAccCode, Amt, AmtBY, AmtDate, AmtReference, OutstandingAmt, Marked, Transferable, Transfered, TransferedOn, TransferedBy, Imported, ImportedBy, deliveredby, SaleTypeCode, Balance, PptCustCode, DELETED, PresCode, ImpactInventory, SaleOrderCode, SaleComments1, SaleComments2, AlterSaleInvCode, RecurringInvoice, RecurringPeriod, LastRecurringInvCode, RecurringAgainst, ConsiderInPO, VisitCode, DueDate, SRBufferInvCode, CustRefNo5, GCCode, GRN, SuppInvCode, Vehicle, ShipTo, GuaranteePersonCode, CashTendered, CashCharged, CashBack, CashAccCode, CustLicNo, CustLicExpiry, ModuleId, DocCode=SaleInvCode, SaleTypeInvNo, CRS_Transfered, CRS_TransferedOn, GuestCode, GuestCheckInCode, StudentCode, CustSiteCode, Transmit, Transmited, Fiscalized, FiscalizedOn, FiscalInvoiceNo, AdvanceTax, ISNULL(AdvanceTaxAmt, 0), FBRPOSFee FROM ') || v_prefix) || '.SaleLedger ');
      v_inqry := (('INSERT INTO ReportData (Code1) SELECT SaleInvCode FROM ' || v_prefix) || '.SaleLedger ');
      v_whr := ' WHERE SaleInvCode IN (SELECT Code1 FROM ReportData)';
    END IF;
    IF (v_saletype = 2) THEN
      v_ins := 'INSERT INTO IMP_AdvSaleLedger ';
      v_sql := (((((' SELECT ServerName=' || '''') || v_srv) || ''', TransDate=GETDATE(), InvType = 2, * FROM ') || v_prefix) || '.AdvSaleLedger ');
      v_inqry := (('INSERT INTO ReportData (Code1) SELECT AdvSaleInvCode FROM ' || v_prefix) || '.AdvSaleLedger ');
      v_whr := ' WHERE AdvSaleInvCode IN (SELECT Code1 FROM ReportData)';
    END IF;
    IF (v_saletype = 3) THEN
      v_ins := 'INSERT INTO IMP_SRLedger ';
      v_sql := (((((' SELECT ServerName=' || '''') || v_srv) || ''', TransDate=GETDATE(), InvType = 3, SRInvCode,SaleInvCode,Date,SRCatCode,CustCode,SalesmanCode,DiscPerc,FlatDisc,MiscCharges,Posted,PostDate,Remarks,SalesTax,OriginalDate,ModifiedBy,PostedBy,HeaderNo,InvGSTPerc1,Smancode,CustRefno,CustRefno2,CustRefno3,CustRefno4,PatientCode,MachineName,HeaderInvNo,AdmissionCode,invtotal,AccountFor,PaymentMode,PaymentAccCode,Amt,AmtBY,AmtDate,AmtReference,OutstandingAmt,Marked,PageSize,ReprintingCounter,DoctCode,ConsiderInPO,CashAccCode,CashTendered,CashCharged,CashBack,RetViaBillSummary,CRS_Transfered,CRS_TransferedOn,GuestCode,GuestCheckInCode,StudentCode,Synced,SyncedOn,SyncedBy,CurrencyCode,ConversionRate,Fiscalized,FiscalizedOn,FiscalInvoiceNo,Transmit,Transmited,AdvanceTax,AdvanceTaxAmt,FBRPOSFee FROM ') || v_prefix) || '.SRLedger ');
      v_inqry := (('INSERT INTO ReportData (Code1) SELECT SRInvCode FROM ' || v_prefix) || '.SRLedger ');
      v_whr := ' WHERE SRInvCode IN (SELECT Code1 FROM ReportData)';
    END IF;
    v_whr_cln := v_whr;
    v_inqry := ((((((((v_inqry || ' WHERE Posted=''Y'' AND Transmit = ') || chr(39)) || 'Y') || chr(39)) || ' AND Transmited = ') || chr(39)) || 'N') || chr(39));
    _dq1 := v_inqry;
    IF _dq1 IS NOT NULL THEN
      EXECUTE dbo.tsql_dyn(_dq1);
    END IF;
    v_err := 0;
    IF ((0 <> 0) OR (v_err <> 0)) THEN
      RAISE EXCEPTION 'Fetch Sales Data Problem: Error Inserting Sales Data into ReportData From Server (%) ', v_srv;
      return_value := -1;
      RETURN;
    END IF;
    v_query := ((v_ins || v_sql) || v_whr);
    _dq2 := v_query;
    IF _dq2 IS NOT NULL THEN
      EXECUTE dbo.tsql_dyn(_dq2);
    END IF;
    v_err := 0;
    IF ((0 <> 0) OR (v_err <> 0)) THEN
      RAISE EXCEPTION 'Fetch Sales Data Problem: Error Transfering Sales Data From Server (%) ', v_srv;
      return_value := -1;
      RETURN;
    ELSE
      IF (v_saletype = 1) THEN
        v_ins := 'INSERT INTO IMP_SaleDetail ';
        v_sql := ((((('SELECT ServerName=' || '''') || v_srv) || ''', SaleInvcode, ICode, GCode, Batch, Expiry, PackQty, LooseQty, PackUnits, SalePrice, AvgPrice, Rate, DiscPerc, SalesTax, RowID, Due, SatisfiedDate, itemflatdisc, SaleItemDescription, PackPrice, UnitSalesTax, GSTPerc, SaleUtn, bonusqty, claimable, balancestock, RowGroup, ClaimableDiscPerc, ManfDate, PackQtyForSale, BonusPackQtyForSale, SaleOrderRowID, DescICode, SourceSaleInvCode=SaleInvCode, SaleRowID=NULL, IssueRowID=NULL, PurUnitRate, RPPUnitRate, TotalPieces, PiecesInHand, PackSalePrice, RefusalSaleRowID=NULL, AlternatePurPrice, CommissionPerUnit, CommissionPerc, AlternateCustomICode, BatchCost, ISNULL(ItemAdvanceTaxPerc,0) FROM ') || v_prefix) || '.SaleDetail ');
      END IF;
      IF (v_saletype = 2) THEN
        v_ins := 'INSERT INTO IMP_AdvSaleDetail ';
        v_sql := ((((('SELECT ServerName=' || '''') || v_srv) || ''', * FROM ') || v_prefix) || '.AdvSaleDetail ');
      END IF;
      IF (v_saletype = 3) THEN
        v_ins := 'INSERT INTO IMP_SRDetail (ChildServer,SRInvcode,Icode,Gcode,Batch,Expiry,PackQty,LooseQty,PackUnits,SRPrice,DiscPerc,SalesTax,AvgPrice,UnitSalesTax,GSTPerc,SRUtn,BonusQty,SalePrice,SaleRowId,ReturnItemDescription,TotalPieces,PiecesInHand,AlternatePurPrice,CommissionPerUnit,CommissionPerc,AlternateCustomICode,NewAvgPrice,Claimable,ClaimableDiscPerc,ItemAdvanceTaxPerc) ';
        v_sql := ((((('SELECT ServerName=' || '''') || v_srv) || ''',SRInvcode,Icode,Gcode,Batch,Expiry,PackQty,LooseQty,PackUnits,SRPrice,DiscPerc,SalesTax,AvgPrice,UnitSalesTax,GSTPerc,SRUtn,BonusQty,SalePrice,SaleRowId,ReturnItemDescription=LTRIM(RTRIM(STR(SRUTN))),TotalPieces,PiecesInHand,AlternatePurPrice,CommissionPerUnit,CommissionPerc,AlternateCustomICode,NewAvgPrice,Claimable,ClaimableDiscPerc,ISNULL(ItemAdvanceTaxPerc,0) FROM ') || v_prefix) || '.SRDetail ');
      END IF;
      v_query := ((v_ins || v_sql) || v_whr);
      _dq3 := v_query;
      IF _dq3 IS NOT NULL THEN
        EXECUTE dbo.tsql_dyn(_dq3);
      END IF;
      v_err := 0;
      IF ((0 <> 0) OR (v_err <> 0)) THEN
        RAISE EXCEPTION 'Fetch Sales/Returns Data Detail Problem: Error Fetching Sales Data Detail From Server (%) ', v_srv;
        return_value := -1;
        RETURN;
      ELSE
        IF (v_saletype <> 2) THEN
          IF (v_saletype = 1) THEN
            v_ins := (((((('INSERT INTO IMP_CashierWindow SELECT ChildServer=' || chr(39)) || v_srv) || chr(39)) || ', CW.* FROM ') || v_prefix) || '.CashierWindow CW WHERE CW.SaleInvCode IN (SELECT Code1 FROM ReportData) ');
          END IF;
          IF (v_saletype = 3) THEN
            v_ins := (((((((((('INSERT INTO IMP_MasterCashWin SELECT ChildServer=' || chr(39)) || v_srv) || chr(39)) || ', CW.* FROM ') || v_prefix) || '.MasterCashWin CW WHERE CW.DocumentType = ') || chr(39)) || 'SR') || chr(39)) || ' AND DocumentCode IN (SELECT Code1 FROM ReportData)');
          END IF;
          v_query := v_ins;
          _dq4 := v_query;
          IF _dq4 IS NOT NULL THEN
            EXECUTE dbo.tsql_dyn(_dq4);
          END IF;
          v_err := 0;
          IF ((0 <> 0) OR (v_err <> 0)) THEN
            RAISE EXCEPTION 'Fetching Sales Data Problem: Error Updating Master Cashier Window Related Data (%)', v_saletype;
            return_value := -1;
            RETURN;
          END IF;
        END IF;
        IF (v_saletype = 1) THEN
          v_query := (((((('UPDATE ' || v_prefix) || '.SaleLedger SET Transmited = ') || chr(39)) || 'Y') || chr(39)) || v_whr);
        END IF;
        IF (v_saletype = 2) THEN
          v_query := (((((('UPDATE ' || v_prefix) || '.AdvSaleLedger SET Transmited = ') || chr(39)) || 'Y') || chr(39)) || v_whr);
        END IF;
        IF (v_saletype = 3) THEN
          v_query := (((((('UPDATE ' || v_prefix) || '.SRLedger SET Transmited = ') || chr(39)) || 'Y') || chr(39)) || v_whr);
        END IF;
        _dq5 := v_query;
        IF _dq5 IS NOT NULL THEN
          EXECUTE dbo.tsql_dyn(_dq5);
        END IF;
        v_err := 0;
        IF ((0 <> 0) OR (v_err <> 0)) THEN
          RAISE EXCEPTION 'Fetch Sales Data Problem: Error Fetching Sales';
          return_value := -1;
          RETURN;
        END IF;
      END IF;
    END IF;
    v_saletype := (v_saletype + 1);
  END LOOP;
  v_dt := localtimestamp(3);
  SELECT r.return_value INTO v_rt_code FROM dbo.sp_set_datetime_preference(prefname => 'LastSaleTransmited', prefvalue => v_dt) AS r;
  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
    RAISE EXCEPTION 'Unable to Record Last Sale Fetch Information in Software Preferences';
    return_value := -1;
    RETURN;
  END IF;
  SELECT r.return_value, r.rs1, r.rs2 INTO v_rt_code, rs1, rs2 FROM dbo.sp_childserver_allsales_translation(childserver => v_srv, usercode => (v_usercode)::integer) AS r;
  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
    RAISE EXCEPTION 'Unable to Translate Child Server Sales for Server (%)', v_srv;
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_FetchCustomerLatestDiscounts ====
CREATE OR REPLACE FUNCTION dbo.sp_fetchcustomerlatestdiscounts(custcode integer, icode integer, INOUT itemflatdisc numeric, INOUT discperc numeric, INOUT rows smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_custcode integer;
  v_icode integer;
  v_itemflatdisc numeric(5,2);
  v_discperc numeric(5,2);
  v_rows smallint;
  _r1 record;
BEGIN
  v_custcode := custcode;
  v_icode := icode;
  v_itemflatdisc := itemflatdisc;
  v_discperc := discperc;
  v_rows := rows;
  FOR _r1 IN SELECT count(*) AS c1, max(saledetail.itemflatdisc) AS c2, max(saledetail.discperc) AS c3 FROM dbo.saleledger, dbo.saledetail, (SELECT max(sl.date) AS date FROM dbo.saleledger AS sl, dbo.saledetail AS sd WHERE (((sl.custcode = v_custcode) AND (sl.saleinvcode = sd.saleinvcode)) AND (sd.icode = v_icode))) AS a WHERE ((((saleledger.custcode = v_custcode) AND (saleledger.date = a.date)) AND (saleledger.saleinvcode = saledetail.saleinvcode)) AND (saledetail.icode = v_icode)) GROUP BY saledetail.icode, saledetail.itemflatdisc, saledetail.discperc LOOP
    v_rows := _r1.c1;
    v_itemflatdisc := _r1.c2;
    v_discperc := _r1.c3;
  END LOOP;
  return_value := 0;
  itemflatdisc := v_itemflatdisc;
  discperc := v_discperc;
  rows := v_rows;
  RETURN;
END
$body$;

-- ==== proc sp_FetchCustomerLatestNetRate ====
CREATE OR REPLACE FUNCTION dbo.sp_fetchcustomerlatestnetrate(custcode integer, icode integer, INOUT netrate numeric, INOUT rows smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_custcode integer;
  v_icode integer;
  v_netrate numeric(8,2);
  v_rows smallint;
  _r1 record;
BEGIN
  v_custcode := custcode;
  v_icode := icode;
  v_netrate := netrate;
  v_rows := rows;
  FOR _r1 IN SELECT count(*) AS c1, max(round((((((saledetail.saleprice - saledetail.itemflatdisc)) * ((1 - (saledetail.discperc * 0.01)))) * ((1 - (saleledger.discperc * 0.01)))))::numeric, 2)) AS c2 FROM dbo.saleledger, dbo.saledetail, (SELECT max(sl.date) AS date FROM dbo.saleledger AS sl, dbo.saledetail AS sd WHERE (((sl.custcode = v_custcode) AND (sl.saleinvcode = sd.saleinvcode)) AND (sd.icode = v_icode))) AS a WHERE ((((saleledger.custcode = v_custcode) AND (saleledger.date = a.date)) AND (saleledger.saleinvcode = saledetail.saleinvcode)) AND (saledetail.icode = v_icode)) GROUP BY saledetail.icode LOOP
    v_rows := _r1.c1;
    v_netrate := _r1.c2;
  END LOOP;
  return_value := 0;
  netrate := v_netrate;
  rows := v_rows;
  RETURN;
END
$body$;

-- ==== proc sp_FetchCustomerLatestSalePrice ====
CREATE OR REPLACE FUNCTION dbo.sp_fetchcustomerlatestsaleprice(custcode integer, icode integer, INOUT saleprice numeric, INOUT rows smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_custcode integer;
  v_icode integer;
  v_saleprice numeric(8,2);
  v_rows smallint;
  _r1 record;
BEGIN
  v_custcode := custcode;
  v_icode := icode;
  v_saleprice := saleprice;
  v_rows := rows;
  FOR _r1 IN SELECT count(*) AS c1, max(saledetail.saleprice) AS c2 FROM dbo.saleledger, dbo.saledetail, (SELECT max(sl.date) AS date FROM dbo.saleledger AS sl, dbo.saledetail AS sd WHERE (((sl.custcode = v_custcode) AND (sl.saleinvcode = sd.saleinvcode)) AND (sd.icode = v_icode))) AS a WHERE ((((saleledger.custcode = v_custcode) AND (saleledger.date = a.date)) AND (saleledger.saleinvcode = saledetail.saleinvcode)) AND (saledetail.icode = v_icode)) GROUP BY saledetail.icode, saledetail.saleprice LOOP
    v_rows := _r1.c1;
    v_saleprice := _r1.c2;
  END LOOP;
  return_value := 0;
  saleprice := v_saleprice;
  rows := v_rows;
  RETURN;
END
$body$;

-- ==== proc sp_Finalize_Production ====
CREATE OR REPLACE FUNCTION dbo.sp_finalize_production(ai_sinvcode integer, ai_linvcode integer, ai_usercode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_sinvcode integer;
  v_ai_linvcode integer;
  v_ai_usercode integer;
  v_issueprice citext;
  _rc integer;
BEGIN
  v_ai_sinvcode := ai_sinvcode;
  v_ai_linvcode := ai_linvcode;
  v_ai_usercode := ai_usercode;
  v_issueprice := dbo.fn_getpreference('DetermineIssuePriceInProductionFrom');
  _rc := 1;
  INSERT INTO dbo.prodbuffer (prodcode, prodrowid, icode, qty, remarks, packunits, packprice, price, itemflatdisc, discperc, processcharge, processchargeperc) SELECT DISTINCT h.prodcode AS prodcode, d.rowid AS prodrowid, rd.icode, round((((rd.qty * ((d.qty / CASE WHEN (r.qty <= 0) THEN 1 ELSE r.qty END)))))::numeric, (SELECT dbo.fn_getcolumnprecision('Qty'))) AS qty, rd.remarks, rd.packunits, CASE v_issueprice WHEN '1' THEN rd.packprice WHEN '2' THEN coalesce((SELECT i.saleprice FROM dbo.item AS i WHERE (i.icode = rd.icode)), 0) WHEN '3' THEN coalesce((SELECT i.purprice FROM dbo.item AS i WHERE (i.icode = rd.icode)), 0) WHEN '4' THEN coalesce((SELECT i.recentpurprice FROM dbo.item AS i WHERE (i.icode = rd.icode)), 0) ELSE coalesce((SELECT round((i.avgprice)::numeric, 2) FROM dbo.item AS i WHERE (i.icode = rd.icode)), 0) END AS packprice, CASE v_issueprice WHEN '1' THEN rd.price WHEN '2' THEN coalesce((SELECT round(((i.saleprice / CASE WHEN (i.packunits > 0) THEN i.packunits ELSE 1 END))::numeric, 2) FROM dbo.item AS i WHERE (i.icode = rd.icode)), 0) WHEN '3' THEN coalesce((SELECT round(((i.purprice / CASE WHEN (i.packunits > 0) THEN i.packunits ELSE 1 END))::numeric, 2) FROM dbo.item AS i WHERE (i.icode = rd.icode)), 0) WHEN '4' THEN coalesce((SELECT round(((i.recentpurprice / CASE WHEN (i.packunits > 0) THEN i.packunits ELSE 1 END))::numeric, 2) FROM dbo.item AS i WHERE (i.icode = rd.icode)), 0) ELSE coalesce((SELECT round((i.avgprice)::numeric, 2) FROM dbo.item AS i WHERE (i.icode = rd.icode)), 0) END AS price, rd.itemflatdisc, rd.discperc, rd.processcharge, rd.processchargeperc FROM dbo.prodheader AS h, dbo.proddetail AS d, dbo.recipedetail AS rd, (SELECT r1.* FROM dbo.recipe AS r1 WHERE (((dbo.tsql_str((r1.resulteditem)::numeric, 7) || dbo.tsql_str((r1.priority)::numeric, 7)))::citext IN (SELECT DISTINCT (dbo.tsql_str((rr.resulteditem)::numeric, 7) || dbo.tsql_str((min(rr.priority))::numeric, 7)) FROM dbo.recipe AS rr WHERE (rr.resulteditem IN (SELECT DISTINCT pd.icode FROM dbo.prodheader AS p, dbo.proddetail AS pd WHERE ((((p.prodcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (p.posted = 'N')) AND (p.finalized = 'N')) AND (p.prodcode = pd.prodcode)))) GROUP BY rr.resulteditem))) AS r WHERE ((((((h.prodcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (h.posted = 'N')) AND (h.finalized = 'N')) AND (h.prodcode = d.prodcode)) AND (d.icode = r.resulteditem)) AND (r.recipecode = rd.recipecode)) ORDER BY prodrowid;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF (_rc > 0) THEN
    UPDATE dbo.prodheader SET finalized = 'Y', finalizedon = localtimestamp(3), finalizedby = v_ai_usercode WHERE (((prodcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (posted = 'N')) AND (finalized = 'N'));
    GET DIAGNOSTICS _rc = ROW_COUNT;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

