-- ==== proc sp_FinalizeSaleOrder ====
CREATE OR REPLACE FUNCTION dbo.sp_finalizesaleorder(ai_socatcode integer, ai_sinvcode integer, ai_linvcode integer, ai_usercode integer, ai_custcode integer, ai_oneorall integer, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_socatcode integer;
  v_ai_sinvcode integer;
  v_ai_linvcode integer;
  v_ai_usercode integer;
  v_ai_custcode integer;
  v_ai_oneorall integer;
  v_ordercode integer;
  v_rowid integer;
  v_totrows integer;
  v_rt_code integer;
  v_ai_list citext;
BEGIN
  v_ai_socatcode := ai_socatcode;
  v_ai_sinvcode := ai_sinvcode;
  v_ai_linvcode := ai_linvcode;
  v_ai_usercode := ai_usercode;
  v_ai_custcode := ai_custcode;
  v_ai_oneorall := ai_oneorall;
  DROP TABLE IF EXISTS tmp_lt_invoicelist;
  CREATE TEMP TABLE tmp_lt_invoicelist (
    code integer NOT NULL,
    rowid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL
) ON COMMIT DROP;
  IF (v_ai_oneorall = 0) THEN
    INSERT INTO tmp_lt_invoicelist (code) SELECT saleordercode FROM dbo.saleorderheader WHERE ((((((saleorderheader.socatcode = v_ai_socatcode) AND (saleorderheader.saleordercode BETWEEN v_ai_sinvcode AND v_ai_linvcode)) AND (saleorderheader.custcode = v_ai_custcode)) AND (saleorderheader.posted = 'N')) AND (saleorderheader.finalized = 'N')) AND (saleorderheader.deleted = 'N'));
    UPDATE dbo.saleorderheader SET finalized = 'Y' WHERE ((((((saleorderheader.socatcode = v_ai_socatcode) AND (saleorderheader.saleordercode BETWEEN v_ai_sinvcode AND v_ai_linvcode)) AND (saleorderheader.custcode = v_ai_custcode)) AND (saleorderheader.posted = 'N')) AND (saleorderheader.finalized = 'N')) AND (saleorderheader.deleted = 'N'));
  ELSE
    INSERT INTO tmp_lt_invoicelist (code) SELECT saleordercode FROM dbo.saleorderheader WHERE (((((saleorderheader.socatcode = v_ai_socatcode) AND (saleorderheader.saleordercode BETWEEN v_ai_sinvcode AND v_ai_linvcode)) AND (saleorderheader.posted = 'N')) AND (saleorderheader.finalized = 'N')) AND (saleorderheader.deleted = 'N'));
    UPDATE dbo.saleorderheader SET finalized = 'Y' WHERE (((((saleorderheader.socatcode = v_ai_socatcode) AND (saleorderheader.saleordercode BETWEEN v_ai_sinvcode AND v_ai_linvcode)) AND (saleorderheader.posted = 'N')) AND (saleorderheader.finalized = 'N')) AND (saleorderheader.deleted = 'N'));
  END IF;
  v_rowid := 1;
  v_totrows := coalesce((SELECT count(*) FROM tmp_lt_invoicelist AS lt_invoicelist), 0);
  WHILE (v_rowid <= v_totrows) LOOP
    v_ordercode := (SELECT code FROM tmp_lt_invoicelist AS lt_invoicelist WHERE (rowid = v_rowid));
    v_ai_list := ((v_ai_list || ltrim(rtrim(dbo.tsql_str((v_ordercode)::numeric, 10)))) || ',');
    v_rowid := (v_rowid + 1);
  END LOOP;
  IF ((right(v_ai_list, 1))::citext = ',') THEN
    v_ai_list := left(v_ai_list, (length(rtrim(v_ai_list)) - 1));
  END IF;
  SELECT r.return_value, r.rs1 INTO v_rt_code, rs1 FROM dbo.sp_createautotriggersms(ai_list => v_ai_list, ai_moduleid => (12)::smallint, ai_event => 'Finalized') AS r;
  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
    RAISE EXCEPTION 'Unable to Create Auto Trigger SMS on Sale Posting';
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_FindAndReplaceItemInProformaSales ====
CREATE OR REPLACE FUNCTION dbo.sp_findandreplaceiteminproformasales(saleinvgroupcode integer, finditem integer, findsaleprice numeric, replaceitem integer, replacesaleprice numeric, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_saleinvgroupcode integer;
  v_finditem integer;
  v_findsaleprice numeric(12,2);
  v_replaceitem integer;
  v_replacesaleprice numeric(12,2);
  v_invcount integer;
  v_rowid integer;
  v_saleinvcode integer;
BEGIN
  v_saleinvgroupcode := saleinvgroupcode;
  v_finditem := finditem;
  v_findsaleprice := findsaleprice;
  v_replaceitem := replaceitem;
  v_replacesaleprice := replacesaleprice;
  DROP TABLE IF EXISTS tmp_saletemp;
  CREATE TEMP TABLE tmp_saletemp (
    saleinvcode integer NOT NULL,
    rowid integer GENERATED BY DEFAULT AS IDENTITY
) ON COMMIT DROP;
  IF (v_finditem = v_replaceitem) THEN
    INSERT INTO tmp_saletemp (saleinvcode) SELECT DISTINCT gd.saleinvcode FROM dbo.saleinvgroupdetail AS gd, dbo.saleledger AS s, dbo.saledetail AS d WHERE (((((gd.saleinvgroupcode = v_saleinvgroupcode) AND (gd.saleinvcode = s.saleinvcode)) AND (s.posted = 'N')) AND (s.saleinvcode = d.saleinvcode)) AND (d.icode = v_finditem));
  END IF;
  INSERT INTO tmp_saletemp (saleinvcode) SELECT DISTINCT gd.saleinvcode FROM dbo.saleinvgroupdetail AS gd, dbo.saleledger AS s, dbo.saleinvdetail AS d WHERE (((((gd.saleinvgroupcode = v_saleinvgroupcode) AND (gd.saleinvcode = s.saleinvcode)) AND (s.posted = 'N')) AND (s.saleinvcode = d.saleinvcode)) AND (d.icode = v_finditem));
  v_invcount := coalesce((SELECT count(saleinvcode) FROM tmp_saletemp AS saletemp), 0);
  IF (v_invcount > 0) THEN
    IF (v_finditem = v_replaceitem) THEN
      UPDATE dbo.saledetail AS d SET icode = v_replaceitem, saleprice = coalesce(v_replacesaleprice, 0) FROM dbo.saleinvgroupdetail AS gd, dbo.saleledger AS s WHERE (((((gd.saleinvgroupcode = v_saleinvgroupcode) AND (gd.saleinvcode = s.saleinvcode)) AND (s.posted = 'N')) AND (s.saleinvcode = d.saleinvcode)) AND (d.icode = v_finditem));
    END IF;
    UPDATE dbo.saleinvdetail AS d SET icode = v_replaceitem, saleprice = coalesce(v_replacesaleprice, 0) FROM dbo.saleinvgroupdetail AS gd, dbo.saleledger AS s WHERE (((((gd.saleinvgroupcode = v_saleinvgroupcode) AND (gd.saleinvcode = s.saleinvcode)) AND (s.posted = 'N')) AND (s.saleinvcode = d.saleinvcode)) AND (d.icode = v_finditem));
    UPDATE dbo.saleledger SET invtotal = dbo.fn_getsaleinvtotal((saleledger.saleinvcode)::integer) WHERE (saleinvcode IN (SELECT saleinvcode FROM tmp_saletemp AS saletemp));
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_FiscalizeSaleInvoice ====
CREATE OR REPLACE FUNCTION dbo.sp_fiscalizesaleinvoice(saleinvcode integer, usercode smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_saleinvcode integer;
  v_usercode smallint;
  v_url citext;
  v_httpmethod citext;
  v_paramsvalues citext;
  v_soapaction citext;
  v_response citext;
  v_rt_code integer;
  v_usetestsvc citext;
  v_fiscalinvcode citext;
  _xc1 refcursor;
  _xr1 record;
BEGIN
  v_saleinvcode := saleinvcode;
  v_usercode := usercode;
  -- SET NOCOUNT ON
  IF ((coalesce((SELECT max(fiscalized) FROM dbo.saleledger WHERE (saleinvcode = v_saleinvcode)), 'N'))::citext = 'Y') THEN
    return_value := 0;
    RETURN;
  END IF;
  DROP TABLE IF EXISTS tmp_resonsetab;
  CREATE TEMP TABLE tmp_resonsetab (
    status citext,
    statustext citext,
    response citext
) ON COMMIT DROP;
  v_usetestsvc := coalesce(dbo.fn_getpreference('UseFBRTestService'), 'Y');
  IF (v_usetestsvc = 'Y') THEN
    v_url := coalesce(dbo.fn_getpreference('FBRTestServiceURL'), 'http://localhost:8524/api/IMSFiscal/Get');
    v_httpmethod := 'GET';
  ELSE
    v_url := coalesce(dbo.fn_getpreference('FBRInvoiceServiceURL'), 'http://localhost:8524/api/IMSFiscal/GetInvoiceNumberByModel');
    v_httpmethod := 'POST';
  END IF;
  v_soapaction := NULL;
  v_paramsvalues := '';
  SELECT r.return_value, r."json" INTO v_rt_code, v_paramsvalues FROM dbo.sp_getsaleinvoice_json(saleinvcode => v_saleinvcode, "json" => v_paramsvalues) AS r;
  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
    RAISE EXCEPTION 'Unable to Generate JSON String for Fiscalization of Sale Invoice %', v_saleinvcode;
    return_value := -1;
    RETURN;
  END IF;
  IF (((length(rtrim(v_url)) > 0) AND (length(rtrim(v_paramsvalues)) > 0)) AND (length(rtrim(v_httpmethod)) > 0)) THEN
    SELECT r.rs1 INTO _xc1 FROM dbo.sp_requesthttpwebservice(url => v_url, httpmethod => v_httpmethod, paramsvalues => v_paramsvalues, soapaction => v_soapaction) AS r;
    LOOP
      FETCH _xc1 INTO _xr1;
      EXIT WHEN NOT FOUND;
      INSERT INTO tmp_resonsetab (status, statustext, response)
        SELECT (a.v)[1]::citext, (a.v)[2]::citext, (a.v)[3]::citext FROM (SELECT array_agg(value ORDER BY ord) AS v FROM json_each_text(row_to_json(_xr1)) WITH ORDINALITY AS j(key, value, ord)) a;
    END LOOP;
    CLOSE _xc1;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      RAISE EXCEPTION 'Unable to send web service request sucessfully for Fiscalization of Sale Invoice %', v_saleinvcode;
      return_value := -1;
      RETURN;
    END IF;
    v_response := (SELECT max(response) FROM tmp_resonsetab AS resonsetab);
    RAISE NOTICE '%', v_response;
    IF (dbo.tsql_charindex(('"Code":"100"')::citext, (v_response)::citext, 1) > 0) THEN
      IF (dbo.tsql_charindex(('{"InvoiceNumber":"')::citext, (v_response)::citext, 1) > 0) THEN
        v_fiscalinvcode := coalesce(substring(v_response, 19, (dbo.tsql_charindex(('","Code":"100"')::citext, (v_response)::citext, 1) - 19)), '');
        RAISE NOTICE '%', v_fiscalinvcode;
        UPDATE dbo.saleledger SET fiscalized = 'Y', fiscalizedon = localtimestamp(3), fiscalinvoiceno = coalesce(v_fiscalinvcode, '') WHERE (saleinvcode = v_saleinvcode);
      END IF;
    ELSE
      RAISE EXCEPTION 'Unable to Get Fiscal Invoice Code sucessfully for Sale Invoice %', v_saleinvcode;
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

