    END IF;
    v_response := (SELECT max(response) FROM tmp_resonsetab AS resonsetab);
    IF (dbo.tsql_charindex(('"Code":"100"')::citext, (v_response)::citext, 1) > 0) THEN
      IF (dbo.tsql_charindex(('{"InvoiceNumber":"')::citext, (v_response)::citext, 1) > 0) THEN
        v_fiscalinvcode := substring(v_response, 19, (dbo.tsql_charindex(('","Code":"100"')::citext, (v_response)::citext, 1) - 19));
        UPDATE dbo.srledger SET fiscalized = 'Y', fiscalizedon = localtimestamp(3), fiscalinvoiceno = v_fiscalinvcode WHERE (srinvcode = v_srinvcode);
      END IF;
