-- ==== proc sp_fixutnbug ====
CREATE OR REPLACE FUNCTION dbo.sp_fixutnbug(OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_utn bigint;
  v_nextutn bigint;
  v_transtype citext;
  v_transcode integer;
  v_date timestamp(3);
  v_gcode smallint;
  v_icode integer;
  v_batch citext;
  v_expiry timestamp(3);
  _r1 record;
  cur_abc refcursor;
  _fs integer := -1;
BEGIN
  FOR _r1 IN SELECT utn AS c1 FROM dbo._utn LOOP
    v_utn := _r1.c1;
  END LOOP;
  SELECT max(a) INTO v_nextutn FROM (SELECT max(purutn) AS a FROM dbo.purdetail UNION ALL SELECT max(prutn) AS a FROM dbo.prdetail UNION ALL SELECT max(saleutn) AS a FROM dbo.saledetail UNION ALL SELECT max(srutn) AS a FROM dbo.srdetail UNION ALL SELECT max(issueutn) AS a FROM dbo.issuedetail UNION ALL SELECT max(receiptutn) AS a FROM dbo.receiptdetail UNION ALL SELECT max(adjutn) AS a FROM dbo.adjdetail UNION ALL SELECT max(glutn) AS a FROM dbo.gldetail UNION ALL SELECT max(transferutn) AS a FROM dbo.tdetail UNION ALL SELECT max(duesatisfyutn) AS a FROM dbo.duesatisfydetail) AS a;
  v_nextutn := (coalesce(v_nextutn, 0) + 1);
  OPEN rs1 FOR SELECT v_nextutn;
  IF (v_utn IS NULL) THEN
    OPEN cur_abc FOR SELECT 'purdetail' AS transtype, pl.purinvcode AS transcode, pl.postdate AS date, pd.gcode, pd.icode, pd.batch, pd.expiry AS expiry FROM dbo.purledger AS pl, dbo.purdetail AS pd WHERE (((pl.posted = 'Y') AND (pl.purinvcode = pd.purinvcode)) AND (pd.purutn IS NULL)) UNION ALL SELECT 'prdetail' AS transtype, pl.prinvcode AS transcode, pl.date AS date, pd.gcode, pd.icode, pd.batch, pd.expiry AS expiry FROM dbo.prledger AS pl, dbo.prdetail AS pd WHERE ((pl.prinvcode = pd.prinvcode) AND (pd.prutn IS NULL)) UNION ALL SELECT 'saledetail' AS transtype, sl.saleinvcode AS transcode, sl.date AS date, sd.gcode, sd.icode, sd.batch, sd.expiry AS expiry FROM dbo.saleledger AS sl, dbo.saledetail AS sd WHERE ((sl.saleinvcode = sd.saleinvcode) AND (sd.saleutn IS NULL)) UNION ALL SELECT 'srdetail' AS transtype, sl.srinvcode AS transcode, sl.date AS date, sd.gcode, sd.icode, sd.batch, sd.expiry AS expiry FROM dbo.srledger AS sl, dbo.srdetail AS sd WHERE ((sl.srinvcode = sd.srinvcode) AND (sd.srutn IS NULL)) UNION ALL SELECT 'duesatisfydetail' AS transtype, ds.duesatisfycode AS transcode, ds.duesatisfydate AS date, dd.gcode, dd.icode, dd.batch, dd.expiry AS expiry FROM dbo.duesatisfyheader AS ds, dbo.duesatisfydetail AS dd WHERE ((ds.duesatisfycode = dd.duesatisfycode) AND (dd.duesatisfyutn IS NULL)) UNION ALL SELECT 'issuedetail' AS transtype, ih.issueinvcode AS transcode, ih.date AS date, id.gcode, id.icode, id.batch, id.expiry AS expiry FROM dbo.issueheader AS ih, dbo.issuedetail AS id WHERE ((ih.issueinvcode = id.issueinvcode) AND (id.issueutn IS NULL)) UNION ALL SELECT 'receiptdetail' AS transtype, rh.receiptinvcode AS transcode, postdate AS date, rd.gcode, rd.icode, rd.batch, rd.expiry AS expiry FROM dbo.receiptheader AS rh, dbo.receiptdetail AS rd WHERE (((rh.posted = 'Y') AND (rh.receiptinvcode = rd.receiptinvcode)) AND (rd.receiptutn IS NULL)) UNION ALL SELECT 'adjdetail' AS transtype, ah.adjcode AS transcode, ah.date AS date, ad.gcode, ad.icode, ad.batch, ad.expiry AS expiry FROM dbo.adjheader AS ah, dbo.adjdetail AS ad WHERE ((ah.adjcode = ad.adjcode) AND (ad.adjutn IS NULL)) UNION ALL SELECT 'tdetail' AS transtype, ah.transcode AS transcode, ah.postdate AS date, ah.dgcode, ad.icode, ad.batch, ad.expiry AS expiry FROM dbo.theader AS ah, dbo.tdetail AS ad WHERE (((ah.transcode = ad.transcode) AND (ad.transferutn IS NOT NULL)) AND (posted = 'Y')) UNION ALL SELECT 'gldetail' AS transtype, gh.glvochcode AS transcode, gh.date AS date, gd.glrowid AS gcode, gd.acccode AS icode, '', NULL::timestamp FROM dbo.glheader AS gh, dbo.gldetail AS gd WHERE ((gh.glvochcode = gd.glvochcode) AND (gd.glutn IS NULL)) ORDER BY 3, 2;
    FETCH NEXT FROM cur_abc INTO v_transtype, v_transcode, v_date, v_gcode, v_icode, v_batch, v_expiry;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    WHILE (_fs = 0) LOOP
      IF (v_transtype = 'purdetail') THEN
        UPDATE dbo.purdetail SET purutn = v_nextutn WHERE (((((purinvcode = v_transcode) AND (gcode = v_gcode)) AND (icode = v_icode)) AND (batch = v_batch)) AND (expiry = v_expiry));
      END IF;
      IF (v_transtype = 'prdetail') THEN
        UPDATE dbo.prdetail SET prutn = v_nextutn WHERE (((((prinvcode = v_transcode) AND (gcode = v_gcode)) AND (icode = v_icode)) AND (batch = v_batch)) AND (expiry = v_expiry));
      END IF;
      IF (v_transtype = 'saledetail') THEN
        UPDATE dbo.saledetail SET saleutn = v_nextutn WHERE (((((saleinvcode = v_transcode) AND (gcode = v_gcode)) AND (icode = v_icode)) AND (batch = v_batch)) AND (expiry = v_expiry));
      END IF;
      IF (v_transtype = 'srdetail') THEN
        UPDATE dbo.srdetail SET srutn = v_nextutn WHERE (((((srinvcode = v_transcode) AND (gcode = v_gcode)) AND (icode = v_icode)) AND (batch = v_batch)) AND (expiry = v_expiry));
      END IF;
      IF (v_transtype = 'receiptdetail') THEN
        UPDATE dbo.receiptdetail SET receiptutn = v_nextutn WHERE (((((receiptinvcode = v_transcode) AND (gcode = v_gcode)) AND (icode = v_icode)) AND (batch = v_batch)) AND (expiry = v_expiry));
      END IF;
      IF (v_transtype = 'issuedetail') THEN
        UPDATE dbo.issuedetail SET issueutn = v_nextutn WHERE (((((issueinvcode = v_transcode) AND (gcode = v_gcode)) AND (icode = v_icode)) AND (batch = v_batch)) AND (expiry = v_expiry));
      END IF;
      IF (v_transtype = 'adjdetail') THEN
        UPDATE dbo.adjdetail SET adjutn = v_nextutn WHERE (((((adjcode = v_transcode) AND (gcode = v_gcode)) AND (icode = v_icode)) AND (batch = v_batch)) AND (expiry = v_expiry));
      END IF;
      IF (v_transtype = 'duesatisfydetail') THEN
        UPDATE dbo.duesatisfydetail SET duesatisfyutn = v_nextutn WHERE (((((duesatisfycode = v_transcode) AND (gcode = v_gcode)) AND (icode = v_icode)) AND (batch = v_batch)) AND (expiry = v_expiry));
      END IF;
      IF (v_transtype = 'tdetail') THEN
        UPDATE dbo.tdetail SET transferutn = v_nextutn WHERE ((((transcode = v_transcode) AND (icode = v_icode)) AND (batch = v_batch)) AND (expiry = v_expiry));
      END IF;
      IF (v_transtype = 'gldetail') THEN
        UPDATE dbo.gldetail SET glutn = v_nextutn WHERE (((glvochcode = v_transcode) AND (glrowid = v_gcode)) AND (acccode = v_icode));
      END IF;
      FETCH NEXT FROM cur_abc INTO v_transtype, v_transcode, v_date, v_gcode, v_icode, v_batch, v_expiry;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
      v_nextutn := (v_nextutn + 1);
    END LOOP;
    CLOSE cur_abc;
    -- DEALLOCATE abc
    UPDATE dbo._utn SET utn = (v_nextutn + 1);
  END IF;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_Generate_BatchWiseSale_From_SaleOrder ====
CREATE OR REPLACE FUNCTION dbo.sp_generate_batchwisesale_from_saleorder(saleordercode integer, INOUT newsaleinvcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_saleordercode integer;
  v_newsaleinvcode integer;
  v_module integer;
  v_headerinvno integer;
  v_continue integer;
  v_rt_code integer;
  v_err integer;
  v_totalrows integer;
  v_rowcount integer;
  v_counter integer;
  v_saleinvcode integer;
  v_headerinvcode integer;
  v_saleprice numeric(12,2);
  v_rate numeric(12,2);
  v_discperc numeric(5,2);
  v_itemflatdisc numeric(15,2);
  v_unitsalestax numeric(12,2);
  v_gstperc1 numeric(6,2);
  v_gstperc2 numeric(6,2);
  v_hold_avgprice numeric(15,5);
  v_icode integer;
  v_gcode integer;
  v_packunits integer;
  v_totalstock numeric(15,4);
  v_totalqty numeric(15,4);
  v_looseqty numeric(15,4);
  v_bonusqty numeric(15,4);
  v_totalbatchqty numeric(15,4);
  v_delqty numeric(15,4);
  v_currqty numeric(15,4);
  v_newqty numeric(15,4);
  v_total_availablestock numeric(15,4);
  v_batch citext;
  v_itemname citext;
  v_expiry timestamp(3);
  v_serverdate timestamp(3);
  v_saleutn bigint;
  v_headerno integer;
  v_rowgroup integer;
  v_innercounter integer;
  _r1 record;
  _r2 record;
  _rc integer;
BEGIN
  v_saleordercode := saleordercode;
  v_newsaleinvcode := newsaleinvcode;
  v_headerno := 1;
  _rc := 1;
  v_module := (SELECT module FROM dbo.module WHERE (name = 'Sales'));
  _rc := 1;
  v_serverdate := localtimestamp(3);
  _rc := 1;
  DROP TABLE IF EXISTS tmp_saletemp;
  CREATE TEMP TABLE tmp_saletemp (
    id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    icode integer,
    gcode smallint,
    batch citext,
    expiry timestamp(3),
    looseqty integer,
    bonusqty integer,
    saleprice numeric(12,2),
    discperc numeric(8,2),
    itemflatdisc numeric(12,2),
    unitsalestax numeric(12,2),
    gstperc numeric(6,2)
) ON COMMIT DROP;
  INSERT INTO tmp_saletemp (icode, gcode, batch, expiry, looseqty, bonusqty, saleprice, discperc, itemflatdisc, unitsalestax, gstperc) SELECT icode, gcode, batch, expiry, trunc(looseqty)::integer, 0, saleprice, discperc, itemflatdisc, unitsalestax, gstperc FROM dbo.saleorderdetail WHERE ((saleordercode = v_saleordercode) AND (((looseqty + bonusqty)) > 0)) ORDER BY rowid;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_totalrows := coalesce((SELECT count(*) FROM tmp_saletemp AS saletemp), 0);
  _rc := 1;
  v_continue := 0;
  _rc := 1;
  v_rowgroup := 0;
  _rc := 1;
  IF ((v_totalrows > 0) AND (v_continue >= 0)) THEN
    SELECT r.return_value, r.key INTO v_rt_code, v_saleinvcode FROM dbo.sp_gettabmaxkey(tabname => 'Saleledger', key => v_saleinvcode) AS r;
    v_rowgroup := 0;
    _rc := 1;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      v_continue := -1;
      _rc := 1;
    END IF;
    v_newsaleinvcode := v_saleinvcode;
    _rc := 1;
    IF (v_continue >= 0) THEN
      SELECT r.return_value, r.key INTO v_rt_code, v_headerinvno FROM dbo.sp_getheadertabmaxkey(headercode => (v_headerno)::smallint, modulecode => (v_module)::smallint, key => v_headerinvno) AS r;
      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
        v_continue := -1;
        _rc := 1;
      END IF;
    END IF;
    IF (v_continue >= 0) THEN
      v_err := 0;
      _rc := 1;
      v_rowcount := 1;
      _rc := 1;
      INSERT INTO dbo.saleledger (saleinvcode, salecatcode, custcode, salesmancode, date, discperc, flatdisc, misccharges, salestax, posted, postdate, remarks, custrefno, headerno, headerinvno, originaldate, modifiedby, postedby, sprice, quotationno, doctcode, patientcode, reprintingcounter, cashreceived, invgstperc1, printwaranty, printbatch, messagecode, smancode, invoicesize, custrefno2, custrefno3, custrefno4, gstno, invtotal, machinename, modifycounter, itemdiscpercno, relationcode, diseasecode, wardcode, admissioncode, returncounter, paid, billingdate, unreceivedbalance, totalofsalereturns, listofsrinvoices, printbalance, accountfor, paymentmode, paymentacccode, amt, amtby, amtdate, amtreference, outstandingamt, marked, transferable, transfered, transferedon, transferedby, imported, importedby, deliveredby, saletypecode, balance, pptcustcode, deleted, prescode, impactinventory, saleordercode, salecomments1, salecomments2, altersaleinvcode, recurringinvoice, recurringperiod, lastrecurringinvcode, recurringagainst, considerinpo, visitcode, duedate, srbufferinvcode, custrefno5, suppinvcode, grn, gccode, vehicle, shipto) SELECT v_saleinvcode, 2 AS salecatcode, custcode, usercode, localtimestamp(3) AS date, discperc, flatdisc, misccharges, 0 AS salestax, 'Y' AS posted, localtimestamp(3) AS postdate, remarks, custrefno, v_headerno, v_headerinvcode, localtimestamp(3) AS date, modifiedby, postedby, 1 AS sprice, quotationcode, doctcode, patientcode, reprintingcounter, 0 AS cashreceived, invgstperc1, 'N' AS printwaranty, 'N' AS printbatch, messagecode, smancode, invoicesize, custrefno2, custrefno3, custrefno4, gstno, invtotal, machinename, modifycounter, itemdiscpercno, relationcode, diseasecode, wardcode, NULL::integer AS admissioncode, 0 AS returncounter, 'N' AS paid, billingdate, invtotal AS unreceivedbalance, 0 AS totalofsalereturns, '', 'Y', 'Y', 'C' AS paymentmode, 2 AS paymentacccode, 0 AS amt, NULL::smallint AS amtby, localtimestamp(3) AS amtdate, NULL::citext AS amtreference, invtotal AS outstandingamt, 'N' AS marked, 'N' AS transferable, 'N' AS transfered, NULL::timestamp(3) AS transferedon, NULL::smallint AS transferedby, 'N' AS imported, NULL::smallint AS importedby, NULL::smallint AS deliveredby, 1 AS saletypeode, 0 AS balance, pptcustcode, 'N' AS deleted, prescode, 'Y' AS impactinventory, saleordercode, (SELECT dbo.fn_getpreference('SaleComments1') AS a) AS salecomments1, (SELECT dbo.fn_getpreference('SaleComments2') AS a) AS salecomments2, NULL::integer AS altersaleinvcode, 'N' AS recurringinvoice, 0 AS recurringperiod, NULL::integer AS lastrecurringinvcode, NULL::integer AS recurringagainst, 'Y' AS considerinpo, NULL::integer AS visitcode, localtimestamp(3) AS duedate, NULL::integer AS srbufferinvcode, NULL::citext AS custrefno5, suppinvcode, grn, gccode, vehicle, shipto FROM dbo.saleorderheader WHERE (saleordercode = v_saleordercode);
      GET DIAGNOSTICS _rc = ROW_COUNT;
      v_err := 0;
      v_rowcount := _rc;
      _rc := 1;
      IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
        RAISE EXCEPTION 'Error occured in inserting record into Sale Ledger : %', v_saleinvcode;
        v_continue := -1;
        _rc := 1;
      ELSE
        v_innercounter := 1;
        _rc := 1;
        WHILE (((v_innercounter <= v_totalrows)) AND ((v_continue >= 0))) LOOP
          _rc := 0;
          FOR _r1 IN SELECT icode AS c1, gcode AS c2, batch AS c3, expiry AS c4, looseqty AS c5, bonusqty AS c6, saleprice AS c7, discperc AS c8, itemflatdisc AS c9, unitsalestax AS c10, gstperc AS c11 FROM tmp_saletemp AS saletemp WHERE (id = v_innercounter) LOOP
            _rc := _rc + 1;
            v_icode := _r1.c1;
            v_gcode := _r1.c2;
            v_batch := _r1.c3;
            v_expiry := _r1.c4;
            v_looseqty := _r1.c5;
            v_bonusqty := _r1.c6;
            v_saleprice := _r1.c7;
            v_discperc := _r1.c8;
            v_itemflatdisc := _r1.c9;
            v_unitsalestax := _r1.c10;
            v_gstperc1 := _r1.c11;
          END LOOP;
          v_err := 0;
          v_rowcount := _rc;
          _rc := 1;
          v_totalqty := (v_looseqty + v_bonusqty);
          _rc := 1;
          IF (((v_totalqty > 0) AND (v_rowcount > 0)) AND (v_err = 0)) THEN
            SELECT r.return_value, r.avgprice INTO v_rt_code, v_hold_avgprice FROM dbo.sp_getitemavgprice(icode => v_icode, avgprice => v_hold_avgprice) AS r;
            IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
              v_continue := -1;
              _rc := 1;
            ELSE
              v_total_availablestock := (SELECT coalesce(sum(currqty), 0) FROM dbo.godowndetail WHERE (godowndetail.icode = v_icode));
              _rc := 1;
              IF ((v_total_availablestock < 0) OR (v_total_availablestock IS NULL)) THEN
                v_total_availablestock := 0;
                _rc := 1;
              END IF;
              v_totalstock := (SELECT coalesce(sum(currqty), 0) FROM dbo.godowndetail WHERE ((godowndetail.gcode = v_gcode) AND (godowndetail.icode = v_icode)));
              _rc := 1;
              v_totalbatchqty := (SELECT coalesce(sum(currqty), 0) FROM dbo.godowndetail WHERE ((((godowndetail.gcode = v_gcode) AND (godowndetail.icode = v_icode)) AND (godowndetail.batch = v_batch)) AND (godowndetail.expiry = v_expiry)));
              _rc := 1;
              IF (v_totalbatchqty >= v_totalqty) THEN
                v_newqty := (v_totalbatchqty - v_totalqty);
                _rc := 1;
                IF (v_newqty > 0) THEN
                  SELECT r.return_value INTO v_rt_code FROM dbo.sp_saleupdateitemstockbatch(gcode => v_gcode, icode => v_icode, batch => v_batch, expiry => v_expiry, newqty => v_newqty, oldqty => v_totalbatchqty) AS r;
                ELSE
                  SELECT r.return_value INTO v_rt_code FROM dbo.sp_deleteitemstockbatch(gcode => v_gcode, icode => v_icode, batch => v_batch, expiry => v_expiry, oldqty => v_totalqty) AS r;
                END IF;
                IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                  v_continue := -1;
                  _rc := 1;
                ELSE
                  v_rowgroup := (v_rowgroup + 1);
                  _rc := 1;
                  _rc := 0;
                  FOR _r2 IN SELECT saleprice AS c1, packunits AS c2 FROM dbo.item WHERE (icode = v_icode) LOOP
                    _rc := _rc + 1;
                    v_rate := _r2.c1;
                    v_packunits := _r2.c2;
                  END LOOP;
                  IF ((v_packunits = 0) OR (v_packunits IS NULL)) THEN
                    v_packunits := 1;
                    _rc := 1;
                  END IF;
                  SELECT r.return_value, r.lbi_maxutn INTO v_rt_code, v_saleutn FROM dbo.sp_maxutn(lbi_rows => (1)::bigint, lbi_maxutn => v_saleutn) AS r;
                  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                    v_continue := -1;
                    _rc := 1;
                  ELSE
                    v_total_availablestock := ((v_total_availablestock - v_looseqty) - v_bonusqty);
                    _rc := 1;
                    INSERT INTO dbo.saledetail (saleinvcode, icode, gcode, batch, expiry, packqty, looseqty, bonusqty, packunits, saleprice, avgprice, rate, discperc, salestax, itemflatdisc, packprice, unitsalestax, gstperc, saleutn, balancestock, rowgroup) VALUES (v_saleinvcode, v_icode, v_gcode, v_batch, v_expiry, 0, v_looseqty, v_bonusqty, v_packunits, v_saleprice, v_hold_avgprice, (v_rate / v_packunits), v_discperc, 0, v_itemflatdisc, v_rate, v_unitsalestax, v_gstperc1, v_saleutn, v_total_availablestock, v_rowgroup);
                    GET DIAGNOSTICS _rc = ROW_COUNT;
                    v_err := 0;
                    v_rowcount := _rc;
                    _rc := 1;
                    IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
                      RAISE EXCEPTION 'Error occured in inserting record into Sale Detail for Sale Inv. No. : %', v_saleinvcode;
                      v_continue := -1;
                      _rc := 1;
                    END IF;
                  END IF;
                END IF;
              ELSE
                v_itemname := (SELECT name FROM dbo.item WHERE (icode = v_icode));
                _rc := 1;
                RAISE EXCEPTION 'Not enough stock for item (%) to decrease for Sale Inv. No : %', v_itemname, v_saleinvcode;
                v_continue := -1;
                _rc := 1;
              END IF;
            END IF;
          END IF;
          v_innercounter := (v_innercounter + 1);
          _rc := 1;
        END LOOP;
        IF (((v_continue >= 0)) AND (v_innercounter > v_totalrows)) THEN
          UPDATE dbo.saleledger SET invtotal = coalesce(dbo.fn_getsaleinvtotal((saleledger.saleinvcode)::integer), 0) WHERE (saleinvcode = v_saleinvcode);
          GET DIAGNOSTICS _rc = ROW_COUNT;
          v_err := 0;
          v_rowcount := _rc;
          _rc := 1;
          IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
            RAISE EXCEPTION 'Unable to update Sale Inv. total for Sale Invoice %', 1;
            v_continue := -1;
            _rc := 1;
          END IF;
          IF ((v_continue >= 0)) THEN
            UPDATE dbo.saleorderheader SET posted = 'Y', postdate = localtimestamp(3), finalized = 'Y' WHERE (saleordercode = v_saleordercode);
            GET DIAGNOSTICS _rc = ROW_COUNT;
            v_err := 0;
            v_rowcount := _rc;
            _rc := 1;
            IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
              RAISE EXCEPTION 'Unable to update Sale Order Status (Inv. No. %)', 1;
              v_continue := -1;
              _rc := 1;
            END IF;
          END IF;
        END IF;
      END IF;
    END IF;
  END IF;
  DROP TABLE IF EXISTS tmp_saletemp;
  return_value := v_continue;
  newsaleinvcode := v_newsaleinvcode;
  RETURN;
  return_value := 0;
  newsaleinvcode := v_newsaleinvcode;
  RETURN;
END
$body$;

-- ==== proc sp_Generate_BillSummary_Vouchers ====
CREATE OR REPLACE FUNCTION dbo.sp_generate_billsummary_vouchers(billsummcode1 integer, billsummcode2 integer, usercode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_billsummcode1 integer;
  v_billsummcode2 integer;
  v_usercode integer;
  v_acccode smallint;
  v_type smallint;
  v_vochcatcode smallint;
  v_totvoch integer;
  v_billsummarycode integer;
  v_saleinvcode integer;
  v_rowid integer;
  v_glvochcode integer;
  v_vouchercode integer;
  v_maxutn bigint;
  v_billsummarytypecode smallint;
  v_utn bigint;
  v_counter integer;
  v_rowcount integer;
  v_totalrows integer;
  v_continue integer;
  v_err integer;
  v_rt_code integer;
  v_amt numeric(15,2);
  v_saleinvbalance numeric(15,2);
  v_newbalance numeric(15,2);
  cur_curs_voch refcursor;
  _rc integer;
  _fs integer := -1;
BEGIN
  v_billsummcode1 := billsummcode1;
  v_billsummcode2 := billsummcode2;
  v_usercode := usercode;
  v_continue := 0;
  _rc := 1;
  OPEN cur_curs_voch FOR SELECT DISTINCT b.billsummarycode, b.billsummarytypecode, d.cashacccode AS acccode, 1 AS type, CASE b.billsummarytypecode WHEN 1 THEN 2 ELSE 12 END AS vochcatcode FROM dbo.billsummary AS b, dbo.billsummarydetail AS d WHERE ((((((b.billsummarycode BETWEEN v_billsummcode1 AND v_billsummcode2) AND (b.posted = 'N')) AND (b.finalized = 'Y')) AND (b.billsummarycode = d.billsummarycode)) AND (d.cashamt <> 0)) AND (d.cashacccode IS NOT NULL)) UNION ALL SELECT DISTINCT b.billsummarycode, b.billsummarytypecode, d.bankacccode AS acccode, 2 AS type, CASE b.billsummarytypecode WHEN 1 THEN 4 ELSE 13 END AS vochcatcode FROM dbo.billsummary AS b, dbo.billsummarydetail AS d WHERE ((((((b.billsummarycode BETWEEN v_billsummcode1 AND v_billsummcode2) AND (b.posted = 'N')) AND (b.finalized = 'Y')) AND (b.billsummarycode = d.billsummarycode)) AND (d.chequeamt <> 0)) AND (d.bankacccode IS NOT NULL)) UNION ALL SELECT DISTINCT b.billsummarycode, b.billsummarytypecode, d.debitnoteacccode AS acccode, 3 AS type, CASE b.billsummarytypecode WHEN 1 THEN 19 ELSE 21 END AS vochcatcode FROM dbo.billsummary AS b, dbo.billsummarydetail AS d WHERE ((((((b.billsummarycode BETWEEN v_billsummcode1 AND v_billsummcode2) AND (b.posted = 'N')) AND (b.finalized = 'Y')) AND (b.billsummarycode = d.billsummarycode)) AND (d.debitnoteamt <> 0)) AND (d.debitnoteacccode IS NOT NULL)) UNION ALL SELECT DISTINCT b.billsummarycode, b.billsummarytypecode, d.creditnoteacccode AS acccode, 4 AS type, CASE b.billsummarytypecode WHEN 1 THEN 20 ELSE 22 END AS vochcatcode FROM dbo.billsummary AS b, dbo.billsummarydetail AS d WHERE ((((((b.billsummarycode BETWEEN v_billsummcode1 AND v_billsummcode2) AND (b.posted = 'N')) AND (b.finalized = 'Y')) AND (b.billsummarycode = d.billsummarycode)) AND (d.creditnoteamt <> 0)) AND (d.creditnoteacccode IS NOT NULL)) ORDER BY 1, 4, 3;
  v_totvoch := (-1);
  _rc := 1;
  IF (v_totvoch <= 0) THEN
    CLOSE cur_curs_voch;
    -- DEALLOCATE Curs_Voch
    return_value := 0;
    RETURN;
  END IF;
  DROP TABLE IF EXISTS tmp_voucherdetail;
  CREATE TEMP TABLE tmp_voucherdetail (
    billsummarycode integer,
    billsummarytypecode smallint,
    headeracccode smallint,
    type smallint,
    custcode smallint,
    accbalance numeric(15,2),
    invoicecode integer,
    outstandingamt numeric(15,2),
    amount numeric(15,2),
    billsummorder integer,
    utn bigint,
    rowid integer GENERATED BY DEFAULT AS IDENTITY
) ON COMMIT DROP;
  INSERT INTO tmp_voucherdetail (billsummarycode, billsummarytypecode, headeracccode, type, custcode, accbalance, invoicecode, outstandingamt, amount, billsummorder) SELECT b.billsummarycode, b.billsummarytypecode, d.cashacccode, 1, d.custcode, d.accbalance, d.saleinvcode, d.outstandingamt, d.cashamt AS amount, d.rowid FROM dbo.billsummary AS b, dbo.billsummarydetail AS d WHERE ((((((b.billsummarycode BETWEEN v_billsummcode1 AND v_billsummcode2) AND (b.posted = 'N')) AND (b.finalized = 'Y')) AND (b.billsummarycode = d.billsummarycode)) AND (d.cashamt <> 0)) AND (d.cashacccode IS NOT NULL)) UNION ALL SELECT b.billsummarycode, b.billsummarytypecode, d.bankacccode, 2, d.custcode, d.accbalance, d.saleinvcode, d.outstandingamt, d.chequeamt AS amount, d.rowid FROM dbo.billsummary AS b, dbo.billsummarydetail AS d WHERE ((((((b.billsummarycode BETWEEN v_billsummcode1 AND v_billsummcode2) AND (b.posted = 'N')) AND (b.finalized = 'Y')) AND (b.billsummarycode = d.billsummarycode)) AND (d.chequeamt <> 0)) AND (d.bankacccode IS NOT NULL)) UNION ALL SELECT b.billsummarycode, b.billsummarytypecode, d.debitnoteacccode, 3, d.custcode, d.accbalance, d.saleinvcode, d.outstandingamt, d.debitnoteamt AS amount, d.rowid FROM dbo.billsummary AS b, dbo.billsummarydetail AS d WHERE ((((((b.billsummarycode BETWEEN v_billsummcode1 AND v_billsummcode2) AND (b.posted = 'N')) AND (b.finalized = 'Y')) AND (b.billsummarycode = d.billsummarycode)) AND (d.debitnoteamt <> 0)) AND (d.debitnoteacccode IS NOT NULL)) UNION ALL SELECT b.billsummarycode, b.billsummarytypecode, d.creditnoteacccode, 4, d.custcode, d.accbalance, d.saleinvcode, d.outstandingamt, d.creditnoteamt AS amount, d.rowid FROM dbo.billsummary AS b, dbo.billsummarydetail AS d WHERE ((((((b.billsummarycode BETWEEN v_billsummcode1 AND v_billsummcode2) AND (b.posted = 'N')) AND (b.finalized = 'Y')) AND (b.billsummarycode = d.billsummarycode)) AND (d.creditnoteamt <> 0)) AND (d.creditnoteacccode IS NOT NULL)) ORDER BY 10;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_err := 0;
  v_rowcount := _rc;
  _rc := 1;
  IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
    RAISE EXCEPTION 'Error occured in making voucher details for BillSummary : %', v_billsummarycode;
    CLOSE cur_curs_voch;
    -- DEALLOCATE Curs_Voch
    DROP TABLE IF EXISTS tmp_voucherdetail;
    return_value := -1;
    RETURN;
  END IF;
  SELECT r.return_value, r.lbi_maxutn INTO v_err, v_maxutn FROM dbo.sp_maxutn(lbi_rows => (v_rowcount)::bigint, lbi_maxutn => v_maxutn) AS r;
  IF ((v_err <> 0) AND (0 <> 0)) THEN
    RAISE EXCEPTION 'Error occured in generating utn for A/c Vouchers of BillSummary : %', v_billsummarycode;
    CLOSE cur_curs_voch;
    -- DEALLOCATE Curs_Voch
    DROP TABLE IF EXISTS tmp_voucherdetail;
    return_value := -1;
    RETURN;
  END IF;
  UPDATE tmp_voucherdetail AS voucherdetail SET utn = ((v_maxutn - v_rowcount) + rowid);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  FETCH NEXT FROM cur_curs_voch INTO v_billsummarycode, v_billsummarytypecode, v_acccode, v_type, v_vochcatcode;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    SELECT r.return_value, r.key INTO v_err, v_glvochcode FROM dbo.sp_gettabmaxkey(tabname => 'GLHeader', key => v_glvochcode) AS r;
    IF ((0 <> 0) OR (v_err <> 0)) THEN
      RAISE EXCEPTION 'GL Voucher Code generation problem';
      CLOSE cur_curs_voch;
      -- DEALLOCATE Curs_Voch
      DROP TABLE IF EXISTS tmp_voucherdetail;
      return_value := -1;
      RETURN;
    END IF;
    SELECT r.return_value, r.ai_vouchercode INTO v_err, v_vouchercode FROM dbo.sp_getvouchercode(ai_vochcatcode => (v_vochcatcode)::integer, ai_vouchercode => v_vouchercode) AS r;
    IF ((0 <> 0) OR (v_err <> 0)) THEN
      RAISE EXCEPTION 'Voucher Code Generation Problem';
      CLOSE cur_curs_voch;
      -- DEALLOCATE Curs_Voch
      DROP TABLE IF EXISTS tmp_voucherdetail;
      return_value := -1;
      RETURN;
    END IF;
    INSERT INTO dbo.glheader (glvochcode, vochcatcode, acccode, date, salesmancode, posted, postdate, remarks, originaldate, modifiedby, postedby, chkno, vouchercode, smancode, transferable, transfered, transferedon, transferedby, imported, importedby, billsummarycode) SELECT v_glvochcode, v_vochcatcode, v_acccode, date AS date, usercode, 'Y' AS posted, localtimestamp(3) AS postdate, ('System Generated Voucher - Bill Summary: ' || ltrim(rtrim(dbo.tsql_str((v_billsummarycode)::numeric)))) AS remarks, date AS originaldate, NULL::smallint AS modifiedby, v_usercode AS postedby, '' AS chkno, v_vouchercode, NULL::smallint AS smancode, 'N' AS transferable, 'N' AS transferred, NULL::timestamp(3) AS transferedon, NULL::smallint AS transferedby, 'N' AS imported, NULL::smallint AS importedby, v_billsummarycode FROM dbo.billsummary WHERE (billsummarycode = v_billsummarycode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_err := 0;
    v_rowcount := _rc;
    _rc := 1;
    IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
      RAISE EXCEPTION 'Error occured in inserting record into GLHeader for BillSummary : %', v_billsummarycode;
      CLOSE cur_curs_voch;
      -- DEALLOCATE Curs_Voch
      DROP TABLE IF EXISTS tmp_voucherdetail;
      return_value := -1;
      RETURN;
    END IF;
    INSERT INTO dbo.gldetail (glvochcode, acccode, debit, credit, chkno, remarks, glutn, patientcode, invoicecode, outstandingamt, balance) SELECT v_glvochcode, custcode, CASE v_type WHEN 3 THEN amount ELSE 0.00 END AS debit, CASE v_type WHEN 3 THEN 0.00 ELSE amount END AS credit, ltrim(rtrim(dbo.tsql_str((invoicecode)::numeric, 10))) AS chkno, ((CASE v_type WHEN 1 THEN 'Cash Receipt' WHEN 2 THEN 'Bank Receipt' WHEN 3 THEN 'Debit Note Issued' ELSE 'Credit Note Issued' END || ' - Bill Summary: ') || ltrim(rtrim(dbo.tsql_str((v_billsummarycode)::numeric)))) AS remarks, utn, NULL::integer AS patientcode, invoicecode AS invoicecode, outstandingamt AS outstandingamt, accbalance AS balance FROM tmp_voucherdetail AS voucherdetail WHERE (((billsummarycode = v_billsummarycode) AND (headeracccode = v_acccode)) AND (type = v_type));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_err := 0;
    v_rowcount := _rc;
    _rc := 1;
    IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
      RAISE EXCEPTION 'Error occured in inserting record into GLDetail for BillSummary : %', v_billsummarycode;
      DROP TABLE IF EXISTS tmp_voucherdetail;
      return_value := -1;
      RETURN;
    END IF;
    INSERT INTO dbo.gldetail (glvochcode, acccode, debit, credit, chkno, remarks, glutn, patientcode, invoicecode, outstandingamt, balance) SELECT v_glvochcode, v_acccode, sum(CASE v_type WHEN 3 THEN 0.00 ELSE amount END) AS debit, sum(CASE v_type WHEN 3 THEN amount ELSE 0.00 END) AS credit, NULL::citext AS chkno, ((CASE v_type WHEN 1 THEN 'Cash Receipt' WHEN 2 THEN 'Bank Receipt' WHEN 3 THEN 'Debit Note Issued' ELSE 'Credit Note Issued' END || ' - Bill Summary : ') || ltrim(rtrim(dbo.tsql_str((v_billsummarycode)::numeric)))) AS remarks, (max(utn) + 1), NULL::integer AS patientcode, NULL::integer AS invoicecode, 0.00 AS outstandingamt, dbo.fn_accountbalance((localtimestamp(3))::timestamp, (v_acccode)::integer) AS balance FROM tmp_voucherdetail AS voucherdetail WHERE (((billsummarycode = v_billsummarycode) AND (headeracccode = v_acccode)) AND (type = v_type)) GROUP BY billsummarycode, headeracccode, type;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_err := 0;
    v_rowcount := _rc;
    _rc := 1;
    IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
      RAISE EXCEPTION 'Error occured in inserting record into GLDetail for BillSummary : %', v_billsummarycode;
      CLOSE cur_curs_voch;
      -- DEALLOCATE Curs_Voch
      DROP TABLE IF EXISTS tmp_voucherdetail;
      return_value := -1;
      RETURN;
    END IF;
    FETCH NEXT FROM cur_curs_voch INTO v_billsummarycode, v_billsummarytypecode, v_acccode, v_type, v_vochcatcode;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_curs_voch;
  -- DEALLOCATE Curs_Voch
  v_rowcount := (SELECT count(*) FROM tmp_voucherdetail AS voucherdetail);
  _rc := 1;
  IF (v_rowcount <= 0) THEN
    return_value := 0;
    RETURN;
  END IF;
  v_rowid := 1;
  _rc := 1;
  WHILE (v_rowid <= v_rowcount) LOOP
    v_saleinvcode := (SELECT invoicecode FROM tmp_voucherdetail AS voucherdetail WHERE (rowid = v_rowid));
    _rc := 1;
    IF (v_saleinvcode > 0) THEN
      v_utn := coalesce((SELECT utn FROM tmp_voucherdetail AS voucherdetail WHERE (rowid = v_rowid)), 0);
      _rc := 1;
      v_amt := coalesce((SELECT amount FROM tmp_voucherdetail AS voucherdetail WHERE (rowid = v_rowid)), 0);
      _rc := 1;
      v_type := coalesce((SELECT type FROM tmp_voucherdetail AS voucherdetail WHERE (rowid = v_rowid)), 0);
      _rc := 1;
      v_billsummarytypecode := coalesce((SELECT billsummarytypecode FROM tmp_voucherdetail AS voucherdetail WHERE (rowid = v_rowid)), 0);
      _rc := 1;
      SELECT r.return_value, r.an_balance INTO v_err, v_saleinvbalance FROM dbo.sp_getsaleinvbalance(ai_saleinvcode => v_saleinvcode, an_balance => v_saleinvbalance) AS r;
      IF ((v_err <> 0) AND (0 <> 0)) THEN
        RAISE EXCEPTION 'Error occured in Fetching Balance of Sale Invoice: % while posting of BillSummary : %', v_saleinvcode, v_billsummarycode;
        DROP TABLE IF EXISTS tmp_voucherdetail;
        return_value := -1;
        RETURN;
      END IF;
      v_saleinvbalance := coalesce(v_saleinvbalance, 0);
      _rc := 1;
      UPDATE dbo.gldetail SET outstandingamt = v_saleinvbalance WHERE (glutn = v_utn);
      GET DIAGNOSTICS _rc = ROW_COUNT;
      IF (v_billsummarytypecode = 2) THEN
        IF (v_type = 3) THEN
          v_newbalance := (coalesce(v_saleinvbalance, 0) + coalesce(v_amt, 0));
          _rc := 1;
        ELSE
          v_newbalance := (coalesce(v_saleinvbalance, 0) - coalesce(v_amt, 0));
          _rc := 1;
        END IF;
        IF (v_newbalance < 0) THEN
          RAISE EXCEPTION 'Error Occured while updation of Balance of Sale Invoice: % while posting of BillSummary : %', v_saleinvcode, v_billsummarycode;
          DROP TABLE IF EXISTS tmp_voucherdetail;
          return_value := -1;
          RETURN;
        END IF;
        SELECT r.return_value INTO v_err FROM dbo.sp_updatesaleinvbalance(ai_saleinvcode => v_saleinvcode, an_amt => v_newbalance) AS r;
        IF ((v_err <> 0) AND (0 <> 0)) THEN
          RAISE EXCEPTION 'Error occured in Fetching Balance of Sale Invoice: % while posting of BillSummary : %', v_saleinvcode, v_billsummarycode;
          DROP TABLE IF EXISTS tmp_voucherdetail;
          return_value := -1;
          RETURN;
        END IF;
      END IF;
    END IF;
    v_rowid := (v_rowid + 1);
    _rc := 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_voucherdetail;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_Generate_Proforamsales_For_ServiceOrder ====
CREATE OR REPLACE FUNCTION dbo.sp_generate_proforamsales_for_serviceorder(serviceocode integer, usercode smallint, INOUT saleinvcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_serviceocode integer;
  v_usercode smallint;
  v_saleinvcode integer;
  v_errcode integer;
  v_item_count integer;
  _rc integer;
BEGIN
  v_serviceocode := serviceocode;
  v_usercode := usercode;
  v_saleinvcode := saleinvcode;
  v_item_count := coalesce((SELECT count(*) FROM dbo.issuedetail AS d, dbo.issueheader AS h WHERE ((h.serviceocode = v_serviceocode) AND (h.issueinvcode = d.issueinvcode))), 0);
  _rc := 1;
  IF ((v_serviceocode <> 0) AND (v_item_count > 0)) THEN
    v_errcode := 0;
    _rc := 1;
    SELECT r.return_value, r.key INTO v_errcode, v_saleinvcode FROM dbo.sp_locktabmaxkey(tabname => 'SaleLedger', key => v_saleinvcode) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Problem while Fetching SaleLedger Key Value';
      return_value := -1;
      saleinvcode := v_saleinvcode;
      RETURN;
    END IF;
    v_saleinvcode := (v_saleinvcode + 1);
    _rc := 1;
    INSERT INTO dbo.saleledger (saleinvcode, salecatcode, custcode, salesmancode, date, discperc, flatdisc, misccharges, salestax, posted, postdate, remarks, custrefno, headerno, originaldate, modifiedby, patientcode, postedby, sprice, cashacccode, cashtendered, cashcharged, cashback, impactinventory) SELECT v_saleinvcode, 2 AS salecatcode, custcode, v_usercode AS salesmancode, localtimestamp(3) AS date, 0 AS discperc, 0 AS flatdisc, 0 AS misccharges, 0 AS salestax, 'Y' AS posted, localtimestamp(3) AS postdate, remarks AS remarks, reference1 AS custrefno, headerno, localtimestamp(3) AS originaldate, NULL::smallint AS modifiedby, patientcode, v_usercode AS postedby, 1 AS sprice, 2 AS cashacccode, 0 AS cashtendered, 0 AS cashcharged, 0 AS cashback, 'N' AS impactinventory FROM dbo.serviceoheader WHERE ((serviceocode = v_serviceocode) AND (serviceoheader.posted = 'N'));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem while Inserting Record in Sale Ledger';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Proforamsales_For_ServiceOrder' USING ERRCODE = 'TS001';
      return_value := -1;
      saleinvcode := v_saleinvcode;
      RETURN;
    END IF;
    INSERT INTO dbo.saleinvdetail (saleinvcode, icode, gcode, batch, expiry, looseqty, packunits, saleprice, avgprice, rate, discperc, itemflatdisc, saleitemdescription, packprice, unitsalestax, gstperc, saleutn, bonusqty, rowgroup, issuerowid, claimable, claimablediscperc) SELECT v_saleinvcode, d.icode, d.gcode, d.batch, d.expiry, d.qty, i.packunits, d.saleprice, d.avgprice, d.saleprice, 0 AS discperc, 0 AS itemflatdisc, d.itemdescription, i.saleprice, round(((i.packsalestax / CASE WHEN (i.packunits > 0) THEN i.packunits ELSE 1 END))::numeric, 2) AS unitsalestax, i.gstperc1, NULL::bigint AS saleutn, 0 AS bonusqty, 1 AS rowgroup, d.issrowid, d.claimable, d.claimablediscperc FROM dbo.issuedetail AS d, dbo.issueheader AS h, dbo.item AS i WHERE (((h.serviceocode = v_serviceocode) AND (h.issueinvcode = d.issueinvcode)) AND (d.icode = i.icode)) ORDER BY d.issueinvcode, d.issrowid;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem while Inserting Record in Sale Inv Detail';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Proforamsales_For_ServiceOrder' USING ERRCODE = 'TS001';
      return_value := -1;
      saleinvcode := v_saleinvcode;
      RETURN;
    END IF;
    v_errcode := 0;
    _rc := 1;
    SELECT r.return_value INTO v_errcode FROM dbo.sp_updatetabmaxkey(tabname => 'SaleLedger', key => v_saleinvcode) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Problem while Updating SaleLedger Key Value';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Proforamsales_For_ServiceOrder' USING ERRCODE = 'TS001';
      return_value := -1;
      saleinvcode := v_saleinvcode;
      RETURN;
    END IF;
    UPDATE dbo.saleledger AS saleledger SET invtotal = coalesce(t.invtotal, 0) FROM (SELECT sl.saleinvcode, coalesce((CASE WHEN (round((sum(((((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc)))) * ((1 - (sd.discperc / 100)))) * ((1 - (sl.discperc / 100)))) - flatdisc) + misccharges)))::numeric, 2) IS NULL) THEN 0 ELSE round((((sum(((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc)))) * ((1 - (sd.discperc / 100)))) * ((1 - (sl.discperc / 100))))) - sl.flatdisc) + sl.misccharges))::numeric, 0) END + round(((sum(round((((((sd.looseqty + sd.bonusqty)) * sd.unitsalestax) + round((((round((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc))) * ((1 - (sd.discperc * 0.01)))))::numeric, 2) * sd.gstperc) * 0.01))::numeric, 2)))::numeric, 2)) + (CASE WHEN ((((round((sum((((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc)))) * ((1 - (sd.discperc / 100)))) * ((1 - (sl.discperc / 100)))) - flatdisc)))::numeric, 2)) * sl.invgstperc1) * 0.01) IS NULL) THEN 0 ELSE (((round(((sum(((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc)))) * ((1 - (sd.discperc / 100)))) * ((1 - (sl.discperc / 100))))) - flatdisc))::numeric, 2)) * sl.invgstperc1) * 0.01) END)))::numeric, 0)), 0) AS invtotal FROM dbo.saleledger AS sl, dbo.saleinvdetail AS sd WHERE ((sl.saleinvcode = v_saleinvcode) AND (sl.saleinvcode = sd.saleinvcode)) GROUP BY sl.saleinvcode, sl.flatdisc, sl.misccharges, sl.discperc, sl.invgstperc1) AS t WHERE (t.saleinvcode = saleledger.saleinvcode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    UPDATE dbo.saleledger SET outstandingamt = coalesce(invtotal, 0) WHERE (saleinvcode = v_saleinvcode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
  END IF;
  IF (0 = 0) THEN
    return_value := 0;
    saleinvcode := v_saleinvcode;
    RETURN;
  ELSE
    return_value := -1;
    saleinvcode := v_saleinvcode;
    RETURN;
  END IF;
  return_value := 0;
  saleinvcode := v_saleinvcode;
  RETURN;
END
$body$;

-- ==== proc sp_Generate_Sale_From_PendingQuotations ====
CREATE OR REPLACE FUNCTION dbo.sp_generate_sale_from_pendingquotations(machinename citext, custcode integer, gcode smallint, usercode smallint, startdate timestamp, enddate timestamp, INOUT newsaleinvcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_machinename citext;
  v_custcode integer;
  v_gcode smallint;
  v_usercode smallint;
  v_startdate timestamp(3);
  v_enddate timestamp(3);
  v_newsaleinvcode integer;
  v_headerno integer;
  v_module integer;
  v_saletypecode smallint;
  v_salecatcode integer;
  v_headerinvno integer;
  v_continue integer;
  v_rt_code integer;
  v_err integer;
  v_totalrows integer;
  v_rowcount integer;
  v_counter integer;
  v_saleinvcode integer;
  v_satisfiableqty integer;
  v_satisfiedqty integer;
  v_saleprice numeric(12,2);
  v_rate numeric(12,2);
  v_discperc numeric(5,2);
  v_claimablediscperc numeric(5,2);
  v_itemflatdisc numeric(12,2);
  v_unitsalestax numeric(12,2);
  v_gstperc1 numeric(6,2);
  v_gstperc2 numeric(6,2);
  v_hold_avgprice numeric(15,5);
  v_icode integer;
  v_packunits integer;
  v_totalqty numeric(15,4);
  v_givenqty numeric(15,4);
  v_reqqty numeric(15,4);
  v_batchqty numeric(15,4);
  v_delqty numeric(15,4);
  v_currqty numeric(15,4);
  v_newqty numeric(15,4);
  v_total_availablestock numeric(15,4);
  v_batch citext;
  v_itemname citext;
  v_expiry timestamp(3);
  v_serverdate timestamp(3);
  v_invoicesize citext;
  v_saleutn bigint;
  v_salerows integer;
  v_rowgroup integer;
  v_lineitems_rowcount integer;
  v_innercounter integer;
  v_quotationcode integer;
  v_quotpopulatesetting integer;
  _r1 record;
  _r2 record;
  cur_itembatch_cursor refcursor;
  _r3 record;
  _rc integer;
  _fs integer := -1;
BEGIN
  v_machinename := machinename;
  v_custcode := custcode;
  v_gcode := gcode;
  v_usercode := usercode;
  v_startdate := startdate;
  v_enddate := enddate;
  v_newsaleinvcode := newsaleinvcode;
  -- SET NOCOUNT On
  v_machinename := current_setting('cluster_name', true);
  _rc := 1;
  v_salecatcode := 2;
  _rc := 1;
  v_saletypecode := 2;
  _rc := 1;
  v_headerno := 1;
  _rc := 1;
  v_module := (SELECT module FROM dbo.module WHERE (name = 'Sales'));
  _rc := 1;
  v_serverdate := localtimestamp(3);
  _rc := 1;
  v_quotpopulatesetting := coalesce((SELECT dbo.fn_get_int_preference('quotationpopulationsetting')), 1);
  _rc := 1;
  v_invoicesize := coalesce((SELECT dbo.fn_getpreference('creditsalepagesize')), 'F');
  _rc := 1;
  DROP TABLE IF EXISTS tmp_saletemp;
  CREATE TEMP TABLE tmp_saletemp (
    tid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    quotationcode integer,
    icode integer,
    rowid integer,
    itemdescription citext,
    packunits smallint,
    saleprice numeric(12,2),
    unitsalestax numeric(12,2),
    gstperc numeric(6,2),
    satisfiableqty integer,
    satisfiedqty integer,
    satisfiablebonus integer,
    satisfiedbonus integer,
    itemflatdisc numeric(12,2),
    discperc numeric(6,2),
    claimablediscperc numeric(6,2),
    stock numeric(15,4)
) ON COMMIT DROP;
  INSERT INTO tmp_saletemp (quotationcode, icode, rowid, itemdescription, packunits, saleprice, unitsalestax, gstperc, satisfiableqty, satisfiedqty, satisfiablebonus, satisfiedbonus, itemflatdisc, discperc, claimablediscperc, stock) SELECT t.quotationcode, t.icode, t.rowid, t.itemdescription, CASE WHEN (v_quotpopulatesetting = 1) THEN t.packunits ELSE i.packunits END AS packunits, round((CASE WHEN (t.loosepack = 1) THEN CASE WHEN (v_quotpopulatesetting = 1) THEN t.saleprice ELSE (i.saleprice / CASE WHEN (i.packunits > 0) THEN i.packunits ELSE 1 END) END ELSE CASE WHEN (v_quotpopulatesetting = 1) THEN (t.saleprice / CASE WHEN (t.packunits > 0) THEN t.packunits ELSE 1 END) ELSE (i.saleprice / CASE WHEN (i.packunits > 0) THEN i.packunits ELSE 1 END) END END)::numeric, 2) AS saleprice, CASE WHEN (v_quotpopulatesetting = 1) THEN t.unitsalestax ELSE round(((i.packsalestax / CASE WHEN (i.packunits > 0) THEN i.packunits ELSE 1 END))::numeric, 2) END AS unitsalestax, CASE WHEN (v_quotpopulatesetting = 1) THEN t.gstperc ELSE i.gstperc1 END AS gstperc, trunc(((CASE WHEN (t.loosepack = 1) THEN t.qty ELSE (t.qty * t.packunits) END) - t.soldqty))::integer AS satisfiableqty, 0 AS satisfiedqty, trunc(((CASE WHEN (t.loosepack = 1) THEN t.bonusqty ELSE (t.bonusqty * t.packunits) END) - t.soldbonus))::integer AS satisfiablebonus, 0 AS satisfiedbonus, CASE WHEN (v_quotpopulatesetting = 1) THEN t.itemflatdisc ELSE i.flatdisc END AS itemflatdisc, CASE WHEN (v_quotpopulatesetting = 1) THEN t.discperc ELSE i.salediscperc END AS discperc, CASE WHEN (v_quotpopulatesetting = 1) THEN t.claimablediscperc ELSE i.claimablediscperc END AS claimablediscperc, coalesce((SELECT sum(gd.currqty) FROM dbo.godowndetail AS gd WHERE ((gcode = v_gcode) AND (gd.icode = t.icode))), 0) AS stock FROM (SELECT DISTINCT icode FROM dbo.godowndetail WHERE (gcode = v_gcode)) AS gd, dbo.item AS i, (SELECT qd.quotationcode, qh.loosepack, qh.custcode, qd.icode, qd.itemflatdisc AS itemflatdisc, qd.rowid AS rowid, qd.itemdescription, qd.packunits AS packunits, qd.saleprice AS saleprice, qd.salestax, qd.bonusqty, qd.unitsalestax AS unitsalestax, qd.gstperc AS gstperc, qd.qty AS qty, qd.discperc AS discperc, qd.claimablediscperc AS claimablediscperc, coalesce((SELECT sum(sd.looseqty) AS looseqty FROM dbo.saledetail AS sd JOIN dbo.saleledger AS sl ON (sl.saleinvcode = sd.saleinvcode) WHERE ((sd.quotationcode = qh.quotationcode) AND (sd.icode = qd.icode)) GROUP BY sd.icode), 0) AS soldqty, coalesce((SELECT sum(sd.bonusqty) AS bonusqty FROM dbo.saledetail AS sd JOIN dbo.saleledger AS sl ON (sl.saleinvcode = sd.saleinvcode) WHERE ((sd.quotationcode = qh.quotationcode) AND (sd.icode = qd.icode)) GROUP BY sd.icode), 0) AS soldbonus FROM dbo.quotationheader AS qh, dbo.quotationdetail AS qd WHERE (((((qh.custcode = v_custcode) AND (qh.originaldate BETWEEN v_startdate AND v_enddate)) AND (qh.active = 'Y')) AND (qh.posted = 'Y')) AND (qh.quotationcode = qd.quotationcode))) AS t WHERE (((((t.qty > t.soldqty) OR (t.bonusqty > t.soldbonus))) AND (t.icode = gd.icode)) AND (t.icode = i.icode)) ORDER BY rowid;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  DELETE FROM tmp_saletemp AS saletemp WHERE ((stock <= 0) AND (((satisfiableqty <= 0) OR (satisfiablebonus <= 0))));
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_salerows := (SELECT count(*) FROM tmp_saletemp AS saletemp);
  _rc := 1;
  v_continue := 0;
  _rc := 1;
  v_rowgroup := 0;
  _rc := 1;
  IF ((v_salerows > 0) AND (v_continue >= 0)) THEN
    SELECT r.return_value, r.key INTO v_rt_code, v_saleinvcode FROM dbo.sp_gettabmaxkey(tabname => 'Saleledger', key => v_saleinvcode) AS r;
    v_rowgroup := 0;
    _rc := 1;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      v_continue := -1;
      _rc := 1;
    ELSE
      SELECT r.return_value, r.key INTO v_rt_code, v_headerinvno FROM dbo.sp_getheadertabmaxkey(headercode => (v_headerno)::smallint, modulecode => (v_module)::smallint, key => v_headerinvno) AS r;
      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
        v_continue := -1;
        _rc := 1;
      ELSE
        v_err := 0;
        _rc := 1;
        v_rowcount := 1;
        _rc := 1;
        INSERT INTO dbo.saleledger (saleinvcode, salecatcode, custcode, sprice, salesmancode, date, discperc, flatdisc, misccharges, salestax, posted, postdate, headerno, headerinvno, originaldate, invtotal, machinename, modifycounter, billingdate, saletypecode, invoicesize) VALUES (v_saleinvcode, v_salecatcode, v_custcode, 1, v_usercode, v_serverdate, 0, 0, 0, 0, 'N', v_serverdate, v_headerno, v_headerinvno, v_serverdate, 0, v_machinename, 0, v_serverdate, v_saletypecode, v_invoicesize);
        GET DIAGNOSTICS _rc = ROW_COUNT;
        v_err := 0;
        v_rowcount := _rc;
        _rc := 1;
        IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
          RAISE EXCEPTION 'Error occured in inserting record into Sale Ledger : %', v_saleinvcode;
          v_continue := -1;
          _rc := 1;
        ELSE
          v_innercounter := 1;
          _rc := 1;
          WHILE ((v_innercounter <= v_salerows) AND (v_continue >= 0)) LOOP
            _rc := 0;
            FOR _r1 IN SELECT icode AS c1, satisfiableqty AS c2, satisfiedqty AS c3, saleprice AS c4, discperc AS c5, itemflatdisc AS c6, unitsalestax AS c7, gstperc AS c8, quotationcode AS c9, claimablediscperc AS c10 FROM tmp_saletemp AS saletemp WHERE (tid = v_innercounter) LOOP
              _rc := _rc + 1;
              v_icode := _r1.c1;
              v_satisfiableqty := _r1.c2;
              v_satisfiedqty := _r1.c3;
              v_saleprice := _r1.c4;
              v_discperc := _r1.c5;
              v_itemflatdisc := _r1.c6;
              v_unitsalestax := _r1.c7;
              v_gstperc1 := _r1.c8;
              v_quotationcode := _r1.c9;
              v_claimablediscperc := _r1.c10;
            END LOOP;
            v_rowcount := _rc;
            _rc := 1;
            IF (((v_rowcount = 1)) AND ((((v_satisfiableqty - v_satisfiedqty)) > 0))) THEN
              v_givenqty := (v_satisfiableqty - v_satisfiedqty);
              _rc := 1;
              v_total_availablestock := (SELECT coalesce(sum(currqty), 0) FROM dbo.godowndetail WHERE (godowndetail.icode = v_icode));
              _rc := 1;
              IF ((v_total_availablestock < 0) OR (v_total_availablestock IS NULL)) THEN
                v_total_availablestock := 0;
                _rc := 1;
              END IF;
              v_totalqty := (SELECT coalesce(sum(currqty), 0) FROM dbo.godowndetail WHERE ((godowndetail.gcode = v_gcode) AND (godowndetail.icode = v_icode)));
              _rc := 1;
              IF (((v_totalqty > 0) AND (v_total_availablestock > 0)) AND (v_givenqty > 0)) THEN
                IF (v_givenqty > 0) THEN
                  UPDATE tmp_saletemp AS saletemp SET satisfiedqty = trunc((v_satisfiedqty + v_givenqty))::integer WHERE ((icode = v_icode) AND (tid = v_innercounter));
                  GET DIAGNOSTICS _rc = ROW_COUNT;
                END IF;
                SELECT r.return_value, r.avgprice INTO v_rt_code, v_hold_avgprice FROM dbo.sp_getitemavgprice(icode => v_icode, avgprice => v_hold_avgprice) AS r;
                IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                  v_continue := -1;
                  _rc := 1;
                ELSE
                  IF (v_totalqty >= v_givenqty) THEN
                    v_rowgroup := (v_rowgroup + 1);
                    _rc := 1;
                    _rc := 0;
                    FOR _r2 IN SELECT saleprice AS c1, packunits AS c2 FROM dbo.item WHERE (icode = v_icode) LOOP
                      _rc := _rc + 1;
                      v_rate := _r2.c1;
                      v_packunits := _r2.c2;
                    END LOOP;
                    IF ((v_packunits = 0) OR (v_packunits IS NULL)) THEN
                      v_packunits := 1;
                      _rc := 1;
                    END IF;
                    v_reqqty := v_givenqty;
                    _rc := 1;
                    OPEN cur_itembatch_cursor FOR SELECT batch, expiry, currqty FROM dbo.godowndetail WHERE ((godowndetail.gcode = v_gcode) AND (godowndetail.icode = v_icode)) ORDER BY priority, expiry, currqty;
                    v_totalrows := (-1);
                    _rc := 1;
                    FETCH NEXT FROM cur_itembatch_cursor INTO v_batch, v_expiry, v_currqty;
                    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
                    v_counter := 1;
                    _rc := 1;
                    WHILE (((_fs = 0) AND (v_counter <= v_totalrows)) AND (v_reqqty > 0)) LOOP
                      v_batchqty := v_currqty;
                      _rc := 1;
                      IF (v_batchqty >= v_reqqty) THEN
                        v_delqty := v_reqqty;
                        _rc := 1;
                      ELSE
                        v_delqty := v_batchqty;
                        _rc := 1;
                      END IF;
                      v_reqqty := (v_reqqty - v_delqty);
                      _rc := 1;
                      SELECT r.return_value, r.lbi_maxutn INTO v_rt_code, v_saleutn FROM dbo.sp_maxutn(lbi_rows => (1)::bigint, lbi_maxutn => v_saleutn) AS r;
                      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                        v_continue := -1;
                        _rc := 1;
                      END IF;
                      v_total_availablestock := (v_total_availablestock - v_delqty);
                      _rc := 1;
                      INSERT INTO dbo.saledetail (saleinvcode, icode, gcode, batch, expiry, packqty, looseqty, packunits, saleprice, avgprice, rate, discperc, salestax, itemflatdisc, packprice, unitsalestax, gstperc, saleutn, balancestock, rowgroup, quotationcode, claimablediscperc) VALUES (v_saleinvcode, v_icode, v_gcode, v_batch, v_expiry, 0, v_delqty, v_packunits, v_saleprice, v_hold_avgprice, (v_rate / v_packunits), v_discperc, 0, v_itemflatdisc, v_rate, v_unitsalestax, v_gstperc1, v_saleutn, v_total_availablestock, v_rowgroup, v_quotationcode, v_claimablediscperc);
                      GET DIAGNOSTICS _rc = ROW_COUNT;
                      v_err := 0;
                      v_rowcount := _rc;
                      _rc := 1;
                      IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
                        RAISE EXCEPTION 'Error occured in inserting record into Sale Detail for Sale Inv. No. : %', v_saleinvcode;
                        v_continue := -1;
                        _rc := 1;
                      ELSE
                        v_newqty := (v_currqty - v_delqty);
                        _rc := 1;
                        IF (v_newqty > 0) THEN
                          SELECT r.return_value INTO v_rt_code FROM dbo.sp_saleupdateitemstockbatch(gcode => (v_gcode)::integer, icode => v_icode, batch => v_batch, expiry => v_expiry, newqty => v_newqty, oldqty => v_currqty) AS r;
                        ELSE
                          SELECT r.return_value INTO v_rt_code FROM dbo.sp_deleteitemstockbatch(gcode => (v_gcode)::integer, icode => v_icode, batch => v_batch, expiry => v_expiry, oldqty => v_delqty) AS r;
                        END IF;
                        IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                          v_continue := -1;
                          _rc := 1;
                        END IF;
                      END IF;
                      v_counter := (v_counter + 1);
                      _rc := 1;
                      FETCH NEXT FROM cur_itembatch_cursor INTO v_batch, v_expiry, v_currqty;
                      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
                    END LOOP;
                    CLOSE cur_itembatch_cursor;
                    -- DEALLOCATE ItemBatch_Cursor
                  ELSE
                    IF ((v_totalqty > 0) AND (v_totalqty < v_givenqty)) THEN
                      v_rowgroup := (v_rowgroup + 1);
                      _rc := 1;
                      _rc := 0;
                      FOR _r3 IN SELECT saleprice AS c1, packunits AS c2 FROM dbo.item WHERE (icode = v_icode) LOOP
                        _rc := _rc + 1;
                        v_rate := _r3.c1;
                        v_packunits := _r3.c2;
                      END LOOP;
                      IF ((v_packunits = 0) OR (v_packunits IS NULL)) THEN
                        v_packunits := 1;
                        _rc := 1;
                      END IF;
                      v_reqqty := v_totalqty;
                      _rc := 1;
                      OPEN cur_itembatch_cursor FOR SELECT batch, expiry, currqty FROM dbo.godowndetail WHERE ((godowndetail.gcode = v_gcode) AND (godowndetail.icode = v_icode)) ORDER BY priority, expiry, currqty;
                      v_totalrows := (-1);
                      _rc := 1;
                      FETCH NEXT FROM cur_itembatch_cursor INTO v_batch, v_expiry, v_currqty;
                      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
                      v_counter := 1;
                      _rc := 1;
                      WHILE (((_fs = 0) AND (v_counter <= v_totalrows)) AND (v_reqqty > 0)) LOOP
                        v_batchqty := v_currqty;
                        _rc := 1;
                        IF (v_batchqty >= v_reqqty) THEN
                          v_delqty := v_reqqty;
                          _rc := 1;
                        ELSE
                          v_delqty := v_batchqty;
                          _rc := 1;
                        END IF;
                        v_reqqty := (v_reqqty - v_delqty);
                        _rc := 1;
                        SELECT r.return_value, r.lbi_maxutn INTO v_rt_code, v_saleutn FROM dbo.sp_maxutn(lbi_rows => (1)::bigint, lbi_maxutn => v_saleutn) AS r;
                        IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                          v_continue := -1;
                          _rc := 1;
                        END IF;
                        v_total_availablestock := (v_total_availablestock - v_delqty);
                        _rc := 1;
                        INSERT INTO dbo.saledetail (saleinvcode, icode, gcode, batch, expiry, packqty, looseqty, packunits, saleprice, avgprice, rate, discperc, salestax, itemflatdisc, packprice, unitsalestax, gstperc, saleutn, balancestock, rowgroup, quotationcode, claimablediscperc) VALUES (v_saleinvcode, v_icode, v_gcode, v_batch, v_expiry, 0, v_delqty, v_packunits, v_saleprice, v_hold_avgprice, (v_rate / v_packunits), v_discperc, 0, v_itemflatdisc, v_rate, v_unitsalestax, v_gstperc1, v_saleutn, v_total_availablestock, v_rowgroup, v_quotationcode, v_claimablediscperc);
                        GET DIAGNOSTICS _rc = ROW_COUNT;
                        v_err := 0;
                        v_rowcount := _rc;
                        _rc := 1;
                        IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
                          RAISE EXCEPTION 'Error occured in inserting record into Sale Detail for Sale Inv. No. : %', v_saleinvcode;
                          v_continue := -1;
                          _rc := 1;
                        ELSE
                          v_newqty := (v_currqty - v_delqty);
                          _rc := 1;
                          IF (v_newqty > 0) THEN
                            SELECT r.return_value INTO v_rt_code FROM dbo.sp_saleupdateitemstockbatch(gcode => (v_gcode)::integer, icode => v_icode, batch => v_batch, expiry => v_expiry, newqty => v_newqty, oldqty => v_currqty) AS r;
                          ELSE
                            SELECT r.return_value INTO v_rt_code FROM dbo.sp_deleteitemstockbatch(gcode => (v_gcode)::integer, icode => v_icode, batch => v_batch, expiry => v_expiry, oldqty => v_delqty) AS r;
                          END IF;
                          IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                            v_continue := -1;
                            _rc := 1;
                          END IF;
                        END IF;
                        v_counter := (v_counter + 1);
                        _rc := 1;
                        FETCH NEXT FROM cur_itembatch_cursor INTO v_batch, v_expiry, v_currqty;
                        IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
                      END LOOP;
                      CLOSE cur_itembatch_cursor;
                      -- DEALLOCATE ItemBatch_Cursor
                    ELSE
                      v_itemname := (SELECT name FROM dbo.item WHERE (icode = v_icode));
                      _rc := 1;
                      RAISE EXCEPTION 'Not enough stock for item (%) to decrease for Sale Inv. No : %', v_itemname, v_saleinvcode;
                      v_continue := -1;
                      _rc := 1;
                    END IF;
                  END IF;
                END IF;
              END IF;
            END IF;
            v_innercounter := (v_innercounter + 1);
            _rc := 1;
          END LOOP;
        END IF;
      END IF;
    END IF;
  END IF;
  DROP TABLE IF EXISTS tmp_saletemp;
  IF (((v_continue >= 0)) AND (v_saleinvcode > 0)) THEN
    UPDATE dbo.saleledger SET invtotal = dbo.fn_getsaleinvtotal((saleledger.saleinvcode)::integer), outstandingamt = dbo.fn_getsaleinvtotal((saleledger.saleinvcode)::integer) WHERE (saleinvcode = v_saleinvcode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_err := 0;
    v_rowcount := _rc;
    _rc := 1;
    IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
      RAISE EXCEPTION 'Unable to update SaleInvoices for Sale Inv. total';
      v_continue := -1;
      _rc := 1;
    END IF;
    v_newsaleinvcode := v_saleinvcode;
    _rc := 1;
  END IF;
  return_value := v_continue;
  newsaleinvcode := v_newsaleinvcode;
  RETURN;
  return_value := 0;
  newsaleinvcode := v_newsaleinvcode;
  RETURN;
END
$body$;

-- ==== proc SP_Generate_Svc_For_CustomerServiceTemplate ====
CREATE OR REPLACE FUNCTION dbo.sp_generate_svc_for_customerservicetemplate(code integer, usercode smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_code integer;
  v_usercode smallint;
  v_errcode integer;
  v_servicecode integer;
  v_serviceinvcode integer;
  v_end_invcode integer;
  v_rows integer;
  v_detailrows integer;
  v_newrowid integer;
  v_sinvcode integer;
  v_einvcode integer;
  _rc integer;
BEGIN
  v_code := code;
  v_usercode := usercode;
  v_rows := coalesce((SELECT count(customerservicetemplatecode) FROM dbo.customerservicetemplate WHERE (((customerservicetemplatecode = v_code) AND (posted = 'Y')) AND (svcinvgenerated = 'N'))), 0);
  _rc := 1;
  IF ((v_rows = 0) OR (v_rows IS NULL)) THEN
    RAISE EXCEPTION 'Template Already Posted OR used, Please select another one.';
    return_value := -1;
    RETURN;
  END IF;
  v_detailrows := coalesce((SELECT count(*) FROM dbo.customerservicetemplatedetail WHERE (customerservicetemplatecode = v_code)), 0);
  _rc := 1;
  IF ((v_detailrows = 0) OR (v_detailrows IS NULL)) THEN
    RAISE EXCEPTION 'Template Has no rows for Customers, Please select another one.';
    return_value := -1;
    RETURN;
  END IF;
  v_servicecode := (SELECT servicecode FROM dbo.customerservicetemplate WHERE (((customerservicetemplatecode = v_code) AND (posted = 'Y')) AND (svcinvgenerated = 'N')));
  _rc := 1;
  IF ((v_servicecode = 0) OR (v_servicecode IS NULL)) THEN
    RAISE EXCEPTION 'Template Has no Service selected, Please select another one.';
    return_value := -1;
    RETURN;
  END IF;
  DROP TABLE IF EXISTS tmp_studtemp;
  CREATE TEMP TABLE tmp_studtemp (
    custcode smallint NOT NULL,
    servicecode integer NOT NULL,
    qty numeric(10,2) NOT NULL,
    charges numeric(12,2) NOT NULL,
    discperc numeric(5,2) NOT NULL,
    serviceflatdisc numeric(12,2) NOT NULL,
    newrowid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    rowid integer NOT NULL,
    remarks citext NULL,
    serviceinvcode integer NULL
) ON COMMIT DROP;
  INSERT INTO tmp_studtemp (custcode, servicecode, qty, charges, discperc, serviceflatdisc, remarks, serviceinvcode, rowid) SELECT custcode, v_servicecode, qty, charges, discperc, serviceflatdisc, remarks, NULL::integer AS serviceinvcode, rowid FROM dbo.customerservicetemplatedetail WHERE (customerservicetemplatecode = v_code) ORDER BY rowid;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_detailrows := coalesce((SELECT count(*) FROM tmp_studtemp AS studtemp), 0);
  _rc := 1;
  IF ((v_servicecode <> 0) AND (v_detailrows > 0)) THEN
    v_errcode := 0;
    _rc := 1;
    SELECT r.return_value, r.key INTO v_errcode, v_serviceinvcode FROM dbo.sp_locktabmaxkey(tabname => 'ServiceHeader', key => v_serviceinvcode) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Problem while Fetching ServiceHeader Key Value';
      return_value := -1;
      RETURN;
    END IF;
    UPDATE tmp_studtemp AS studtemp SET serviceinvcode = (v_serviceinvcode + newrowid);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    INSERT INTO dbo.serviceheader (serviceinvcode, custcode, salesmancode, servicecatcode, remarks, originaldate, modifiedby, date, postedby, postdate, headerno, discperc, flatdisc, misccharges, saleinvcode, posted, reprintingcounter, serviceocode, cashreceived, cashtendered, cashcharged, cashback) SELECT d.serviceinvcode, c.custcode AS custcode, v_usercode AS salesmancode, 11 AS serivcecatcode, d.remarks AS remarks, localtimestamp(3) AS originaldate, NULL::smallint AS modifiedby, localtimestamp(3) AS date, v_usercode AS postedby, localtimestamp(3) AS postdate, 1 AS headerno, 0 AS discperc, 0 AS flatdisc, 0 AS misccharges, NULL::integer AS saleinvcode, 'Y' AS posted, 0 AS reprintingcounter, NULL::integer AS serviceocode, 0 AS cashreceived, 0 AS cashtendered, 0 AS cashcharged, 0 AS cashback FROM tmp_studtemp AS d, dbo.customer AS c WHERE (c.custcode = d.custcode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem while Inserting Record in ServiceHeader';
      return_value := -1;
      RETURN;
    END IF;
    INSERT INTO dbo.servicedetail (serviceinvcode, servicecode, smancode, qty, price, serviceflatdisc, discperc, remarks) SELECT serviceinvcode, v_servicecode, 1 AS smancode, qty, charges AS saleprice, serviceflatdisc, discperc, remarks FROM tmp_studtemp AS studtemp;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem while Inserting Record in ServiceDetail';
      return_value := -1;
      RETURN;
    END IF;
    UPDATE dbo.customerservicetemplatedetail AS d SET serviceinvcode = t.serviceinvcode FROM tmp_studtemp AS t WHERE (t.rowid = d.rowid);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem in Updating Customer Service Template Record';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_For_CustomerServiceTemplate' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
    v_sinvcode := coalesce((SELECT min(serviceinvcode) FROM tmp_studtemp AS studtemp), 0);
    _rc := 1;
    v_einvcode := coalesce((SELECT max(serviceinvcode) FROM tmp_studtemp AS studtemp), 0);
    _rc := 1;
    v_errcode := 0;
    _rc := 1;
    SELECT r.return_value INTO v_errcode FROM dbo.sp_updatetabmaxkey(tabname => 'ServiceHeader', key => v_einvcode) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Problem while Updating ServiceHeader Key Value';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_For_CustomerServiceTemplate' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
    UPDATE dbo.serviceheader SET invtotal = coalesce(dbo.fn_getserviceinvtotal((serviceinvcode)::integer), 0) WHERE (serviceinvcode BETWEEN v_sinvcode AND v_einvcode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    UPDATE dbo.serviceheader SET outstandingamt = invtotal WHERE (serviceinvcode BETWEEN v_sinvcode AND v_einvcode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    UPDATE dbo.customerservicetemplate SET svcinvgenerated = 'Y' WHERE (customerservicetemplatecode = v_code);
    GET DIAGNOSTICS _rc = ROW_COUNT;
  END IF;
  IF (0 = 0) THEN
    return_value := 0;
    RETURN;
  ELSE
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_Generate_Svc_For_CustomerStudentServiceTemplate ====
CREATE OR REPLACE FUNCTION dbo.sp_generate_svc_for_customerstudentservicetemplate(code integer, usercode smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_code integer;
  v_usercode smallint;
  v_errcode integer;
  v_servicecode integer;
  v_serviceinvcode integer;
  v_end_invcode integer;
  v_rows integer;
  v_detailrows integer;
  v_newrowid integer;
  v_sinvcode integer;
  v_einvcode integer;
  v_custcode integer;
  _rc integer;
BEGIN
  v_code := code;
  v_usercode := usercode;
  v_rows := coalesce((SELECT count(customerstudentservicetemplatecode) FROM dbo.customerstudentservicetemplate WHERE (((customerstudentservicetemplatecode = v_code) AND (posted = 'Y')) AND (svcinvgenerated = 'N'))), 0);
  _rc := 1;
  IF ((v_rows = 0) OR (v_rows IS NULL)) THEN
    RAISE EXCEPTION 'Template Already Posted OR used, Please select another one.';
    return_value := -1;
    RETURN;
  END IF;
  v_detailrows := coalesce((SELECT count(*) FROM dbo.customerstudentservicetemplatedetail WHERE (customerstudentservicetemplatecode = v_code)), 0);
  _rc := 1;
  IF ((v_detailrows = 0) OR (v_detailrows IS NULL)) THEN
    RAISE EXCEPTION 'Template Has no rows for students, Please select another one.';
    return_value := -1;
    RETURN;
  END IF;
  v_servicecode := (SELECT servicecode FROM dbo.customerstudentservicetemplate WHERE (((customerstudentservicetemplatecode = v_code) AND (posted = 'Y')) AND (svcinvgenerated = 'N')));
  _rc := 1;
  IF ((v_servicecode = 0) OR (v_servicecode IS NULL)) THEN
    RAISE EXCEPTION 'Template Has no Service selected, Please select another one.';
    return_value := -1;
    RETURN;
  END IF;
  v_custcode := (SELECT custcode FROM dbo.customerstudentservicetemplate WHERE (((customerstudentservicetemplatecode = v_code) AND (posted = 'Y')) AND (svcinvgenerated = 'N')));
  _rc := 1;
  IF ((v_custcode = 0) OR (v_custcode IS NULL)) THEN
    RAISE EXCEPTION 'Template Has no Customer selected, Please select another one.';
    return_value := -1;
    RETURN;
  END IF;
  DROP TABLE IF EXISTS tmp_studtemp;
  CREATE TEMP TABLE tmp_studtemp (
    studentcode integer NOT NULL,
    servicecode integer NOT NULL,
    qty numeric(10,2) NOT NULL,
    charges numeric(12,2) NOT NULL,
    discperc numeric(5,2) NOT NULL,
    serviceflatdisc numeric(12,2) NOT NULL,
    rowid integer NOT NULL,
    remarks citext NULL
) ON COMMIT DROP;
  INSERT INTO tmp_studtemp (studentcode, servicecode, qty, charges, discperc, serviceflatdisc, rowid, remarks) SELECT d.studentcode, v_servicecode, d.qty, d.charges, d.discperc, d.serviceflatdisc, d.rowid, coalesce((SELECT (((s.name || ' (') || s.regno) || ')') FROM dbo.student AS s WHERE (s.studentcode = d.studentcode)), d.remarks) AS remarks FROM dbo.customerstudentservicetemplatedetail AS d WHERE (d.customerstudentservicetemplatecode = v_code) ORDER BY d.rowid;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_detailrows := coalesce((SELECT count(*) FROM tmp_studtemp AS studtemp), 0);
  _rc := 1;
  IF ((v_servicecode <= 0) AND (v_detailrows <= 0)) THEN
    RAISE EXCEPTION 'Please Try Again';
    return_value := -1;
    RETURN;
  END IF;
  v_errcode := 0;
  _rc := 1;
  SELECT r.return_value, r.key INTO v_errcode, v_serviceinvcode FROM dbo.sp_locktabmaxkey(tabname => 'ServiceHeader', key => v_serviceinvcode) AS r;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem while Fetching ServiceHeader Key Value';
    return_value := -1;
    RETURN;
  END IF;
  v_serviceinvcode := (v_serviceinvcode + 1);
  _rc := 1;
  INSERT INTO dbo.serviceheader (serviceinvcode, custcode, salesmancode, servicecatcode, remarks, originaldate, modifiedby, date, postedby, postdate, headerno, discperc, flatdisc, misccharges, saleinvcode, posted, reprintingcounter, serviceocode, cashreceived, cashtendered, cashcharged, cashback, studentcode) SELECT v_serviceinvcode, v_custcode AS custcode, v_usercode AS salesmancode, 11 AS serivcecatcode, 'Student Fee Contribution' AS remarks, localtimestamp(3) AS originaldate, NULL::smallint AS modifiedby, localtimestamp(3) AS date, v_usercode AS postedby, localtimestamp(3) AS postdate, 1 AS headerno, 0 AS discperc, 0 AS flatdisc, 0 AS misccharges, NULL::integer AS saleinvcode, 'Y' AS posted, 0 AS reprintingcounter, NULL::integer AS serviceocode, 0 AS cashreceived, 0 AS cashtendered, 0 AS cashcharged, 0 AS cashback, NULL::integer AS studentcode;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((0 <> 0) OR (_rc = 0)) THEN
    RAISE EXCEPTION 'Problem Inserting Row into ServiceHeader Table';
    return_value := -1;
    RETURN;
  END IF;
  INSERT INTO dbo.servicedetail (serviceinvcode, servicecode, smancode, qty, price, serviceflatdisc, discperc, remarks) SELECT v_serviceinvcode, v_servicecode, 1 AS smancode, qty, charges AS saleprice, serviceflatdisc, discperc, remarks FROM tmp_studtemp AS studtemp ORDER BY rowid;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((0 <> 0) OR (_rc = 0)) THEN
    RAISE EXCEPTION 'Problem while Inserting Record in ServiceDetail';
    return_value := -1;
    RETURN;
  END IF;
  UPDATE dbo.customerstudentservicetemplatedetail SET serviceinvcode = v_serviceinvcode;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((0 <> 0) OR (_rc = 0)) THEN
    RAISE EXCEPTION 'Problem in Updating Student Service Template Record';
    RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_For_CustomerStudentServiceTemplate' USING ERRCODE = 'TS001';
    return_value := -1;
    RETURN;
  END IF;
  v_errcode := 0;
  _rc := 1;
  SELECT r.return_value INTO v_errcode FROM dbo.sp_updatetabmaxkey(tabname => 'ServiceHeader', key => v_serviceinvcode) AS r;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem while Updating ServiceHeader Key Value';
    RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_For_CustomerStudentServiceTemplate' USING ERRCODE = 'TS001';
    return_value := -1;
    RETURN;
  END IF;
  UPDATE dbo.serviceheader SET invtotal = coalesce(dbo.fn_getserviceinvtotal((serviceinvcode)::integer), 0) WHERE (serviceinvcode = v_serviceinvcode);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  UPDATE dbo.serviceheader SET outstandingamt = invtotal WHERE (serviceinvcode = v_serviceinvcode);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  UPDATE dbo.customerstudentservicetemplate SET svcinvgenerated = 'Y' WHERE (customerstudentservicetemplatecode = v_code);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF (0 = 0) THEN
    return_value := 0;
    RETURN;
  ELSE
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_Generate_Svc_For_ServiceOrder ====
CREATE OR REPLACE FUNCTION dbo.sp_generate_svc_for_serviceorder(serviceocode integer, usercode smallint, INOUT serviceinvcode integer, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_serviceocode integer;
  v_usercode smallint;
  v_serviceinvcode integer;
  v_errcode integer;
  v_end_invcode integer;
  v_svc_count integer;
  _rc integer;
BEGIN
  v_serviceocode := serviceocode;
  v_usercode := usercode;
  v_serviceinvcode := serviceinvcode;
  v_svc_count := coalesce((SELECT count(*) FROM dbo.serviceodetail WHERE (serviceocode = v_serviceocode)), 0);
  _rc := 1;
  IF ((v_serviceocode <> 0) AND (v_svc_count > 0)) THEN
    v_errcode := 0;
    _rc := 1;
    SELECT r.return_value, r.key INTO v_errcode, v_serviceinvcode FROM dbo.sp_locktabmaxkey(tabname => 'ServiceHeader', key => v_serviceinvcode) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Problem while Fetching ServiceHeader Key Value';
      return_value := -1;
      serviceinvcode := v_serviceinvcode;
      RETURN;
    END IF;
    v_serviceinvcode := (v_serviceinvcode + 1);
    _rc := 1;
    INSERT INTO dbo.serviceheader (serviceinvcode, custcode, salesmancode, servicecatcode, remarks, originaldate, modifiedby, date, postedby, postdate, headerno, discperc, ref1, ref2, flatdisc, misccharges, saleinvcode, posted, reprintingcounter, serviceocode, cashreceived, cashtendered, cashcharged, cashback, patientcode, studentcode, fullpatientname, patientage, patientsex, patientrefby, serviceinvtypecode, messagecode, serviceinvgstperc) SELECT v_serviceinvcode, custcode AS custcode, v_usercode AS salesmancode, 11 AS serivcecatcode, remarks AS remarks, localtimestamp(3) AS originaldate, NULL::smallint AS modifiedby, localtimestamp(3) AS date, v_usercode AS postedby, localtimestamp(3) AS postdate, 1 AS headerno, discperc, left(reference1, 60), left(reference2, 60), flatdisc, misccharges, saleinvcode AS saleinvcode, 'N' AS posted, 0 AS reprintingcounter, v_serviceocode AS serviceocode, 0 AS cashreceived, 0 AS cashtendered, 0 AS cashcharged, 0 AS cashback, patientcode, NULL::integer AS studentcode, fullpatientname, patientage, patientsex, patientrefby, serviceinvtypecode, messagecode, serviceinvgstperc FROM dbo.serviceoheader WHERE ((serviceocode = v_serviceocode) AND (serviceoheader.posted = 'N'));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem while Inserting Record in ServiceHeader';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_For_ServiceOrder' USING ERRCODE = 'TS001';
      return_value := -1;
      serviceinvcode := v_serviceinvcode;
      RETURN;
    END IF;
    INSERT INTO dbo.servicedetail (serviceinvcode, servicecode, smancode, qty, price, serviceflatdisc, discperc, remarks, serviceflattax, servicegstperc) SELECT v_serviceinvcode, servicecode, smancode, qty, price, serviceflatdisc, discperc, NULL::citext AS remarks, serviceflattax, servicegstperc FROM dbo.serviceodetail WHERE (serviceocode = v_serviceocode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem while Inserting Record in ServiceDetail';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_For_ServiceOrder' USING ERRCODE = 'TS001';
      return_value := -1;
      serviceinvcode := v_serviceinvcode;
      RETURN;
    END IF;
    v_errcode := 0;
    _rc := 1;
    SELECT r.return_value INTO v_errcode FROM dbo.sp_updatetabmaxkey(tabname => 'ServiceHeader', key => v_serviceinvcode) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Problem while Updating ServiceHeader Key Value';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_For_ServiceOrder' USING ERRCODE = 'TS001';
      return_value := -1;
      serviceinvcode := v_serviceinvcode;
      RETURN;
    END IF;
    UPDATE dbo.serviceheader SET invtotal = coalesce(dbo.fn_getserviceinvtotal((serviceinvcode)::integer), 0) WHERE (serviceinvcode = v_serviceinvcode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    UPDATE dbo.serviceheader SET outstandingamt = coalesce(dbo.fn_getserviceinvtotal((serviceinvcode)::integer), 0) WHERE (serviceinvcode = v_serviceinvcode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_errcode := 0;
    _rc := 1;
    SELECT r.return_value, r.rs1 INTO v_errcode, rs1 FROM dbo.sp_postservice_custwise(ai_sinvcode => v_serviceinvcode, ai_linvcode => v_serviceinvcode, ai_servicecatcode => 11, ai_salesmancode => (v_usercode)::integer, ai_custcode => NULL, ai_oneorall => 1) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Problem while Posting Service Invoice %', v_serviceinvcode;
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_For_ServiceOrder' USING ERRCODE = 'TS001';
      return_value := -1;
      serviceinvcode := v_serviceinvcode;
      RETURN;
    END IF;
  END IF;
  IF (0 = 0) THEN
    return_value := 0;
    serviceinvcode := v_serviceinvcode;
    RETURN;
  ELSE
    return_value := -1;
    serviceinvcode := v_serviceinvcode;
    RETURN;
  END IF;
  return_value := 0;
  serviceinvcode := v_serviceinvcode;
  RETURN;
END
$body$;

-- ==== proc SP_Generate_Svc_For_StudentFee ====
CREATE OR REPLACE FUNCTION dbo.sp_generate_svc_for_studentfee(classcode integer, studentcode integer, remarks citext, servicecode integer, fee numeric, flatdisc numeric, discperc numeric, usercode smallint, INOUT serviceinvcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_classcode integer;
  v_studentcode integer;
  v_remarks citext;
  v_servicecode integer;
  v_fee numeric(15,2);
  v_flatdisc numeric(15,2);
  v_discperc numeric(5,2);
  v_usercode smallint;
  v_serviceinvcode integer;
  v_errcode integer;
  v_end_invcode integer;
  v_feeday integer;
  v_today integer;
  v_duedate timestamp(3);
  _rc integer;
BEGIN
  v_classcode := classcode;
  v_studentcode := studentcode;
  v_remarks := remarks;
  v_servicecode := servicecode;
  v_fee := fee;
  v_flatdisc := flatdisc;
  v_discperc := discperc;
  v_usercode := usercode;
  v_serviceinvcode := serviceinvcode;
  v_feeday := coalesce((SELECT class.feedueon FROM dbo.class WHERE (class.classcode = v_classcode)), 1);
  _rc := 1;
  v_today := (SELECT extract(day from localtimestamp(3))::integer);
  _rc := 1;
  IF (v_today >= v_feeday) THEN
    IF (extract(month from localtimestamp(3))::integer < 12) THEN
      v_duedate := (((((ltrim(rtrim(dbo.tsql_str((extract(year from localtimestamp(3))::integer)::numeric, 7))) || '-') || ltrim(rtrim(dbo.tsql_str(((extract(month from localtimestamp(3))::integer + 1))::numeric, 7)))) || '-') || ltrim(rtrim(dbo.tsql_str((v_feeday)::numeric, 7)))))::timestamp(3);
      _rc := 1;
    ELSE
      v_duedate := (((((ltrim(rtrim(dbo.tsql_str(((extract(year from localtimestamp(3))::integer + 1))::numeric, 7))) || '-') || '01') || '-') || ltrim(rtrim(dbo.tsql_str((v_feeday)::numeric, 7)))))::timestamp(3);
      _rc := 1;
    END IF;
  ELSE
    v_duedate := (((((ltrim(rtrim(dbo.tsql_str((extract(year from localtimestamp(3))::integer)::numeric, 7))) || '-') || ltrim(rtrim(dbo.tsql_str((extract(month from localtimestamp(3))::integer)::numeric, 7)))) || '-') || ltrim(rtrim(dbo.tsql_str((v_feeday)::numeric, 7)))))::timestamp(3);
    _rc := 1;
  END IF;
  v_duedate := coalesce(v_duedate, localtimestamp(3));
  _rc := 1;
  IF ((v_servicecode <> 0) AND (v_studentcode <> 0)) THEN
    v_errcode := 0;
    _rc := 1;
    SELECT r.return_value, r.key INTO v_errcode, v_serviceinvcode FROM dbo.sp_locktabmaxkey(tabname => 'ServiceHeader', key => v_serviceinvcode) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Problem while Fetching ServiceHeader Key Value';
      return_value := -1;
      serviceinvcode := v_serviceinvcode;
      RETURN;
    END IF;
    v_serviceinvcode := (v_serviceinvcode + 1);
    _rc := 1;
    INSERT INTO dbo.serviceheader (serviceinvcode, custcode, salesmancode, servicecatcode, remarks, originaldate, modifiedby, date, postedby, postdate, headerno, discperc, flatdisc, misccharges, saleinvcode, posted, reprintingcounter, serviceocode, cashreceived, cashtendered, cashcharged, cashback, studentcode, duedate) SELECT v_serviceinvcode, s.custcode AS custcode, v_usercode AS salesmancode, 11 AS serivcecatcode, v_remarks AS remarks, localtimestamp(3) AS originaldate, NULL::smallint AS modifiedby, localtimestamp(3) AS date, v_usercode AS postedby, localtimestamp(3) AS postdate, 1 AS headerno, 0 AS discperc, 0 AS flatdisc, 0 AS misccharges, NULL::integer AS saleinvcode, 'Y' AS posted, 0 AS reprintingcounter, NULL::integer AS serviceocode, 0 AS cashreceived, 0 AS cashtendered, 0 AS cashcharged, 0 AS cashback, s.studentcode AS studentcode, v_duedate AS duedate FROM dbo.student AS s WHERE (s.studentcode = v_studentcode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem while Inserting Record in ServiceHeader';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_For_StudentFee' USING ERRCODE = 'TS001';
      return_value := -1;
      serviceinvcode := v_serviceinvcode;
      RETURN;
    END IF;
    INSERT INTO dbo.servicedetail (serviceinvcode, servicecode, smancode, qty, price, serviceflatdisc, discperc, remarks) SELECT v_serviceinvcode, v_servicecode, 1 AS smancode, 1 AS qty, v_fee AS saleprice, CASE WHEN (round(((((v_fee - v_flatdisc)) * ((1 - (v_discperc * 0.01)))))::numeric, 2) > 0) THEN v_flatdisc ELSE v_fee END AS serviceflatdisc, v_discperc AS discperc, v_remarks;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem while Inserting Record in ServiceDetail';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_For_StudentFee' USING ERRCODE = 'TS001';
      return_value := -1;
      serviceinvcode := v_serviceinvcode;
      RETURN;
    END IF;
    UPDATE dbo.studentclass AS studentclass SET lastserviceinvdate = localtimestamp(3), serviceinvcode = v_serviceinvcode WHERE ((classcode = v_classcode) AND (studentcode = v_studentcode));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem in Updating Student Fee Record';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_For_StudentFee' USING ERRCODE = 'TS001';
      return_value := -1;
      serviceinvcode := v_serviceinvcode;
      RETURN;
    END IF;
    v_errcode := 0;
    _rc := 1;
    SELECT r.return_value INTO v_errcode FROM dbo.sp_updatetabmaxkey(tabname => 'ServiceHeader', key => v_serviceinvcode) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Problem while Updating ServiceHeader Key Value';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_For_StudentFee' USING ERRCODE = 'TS001';
      return_value := -1;
      serviceinvcode := v_serviceinvcode;
      RETURN;
    END IF;
    UPDATE dbo.serviceheader SET invtotal = coalesce(dbo.fn_getserviceinvtotal((serviceinvcode)::integer), 0) WHERE (serviceinvcode = v_serviceinvcode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    UPDATE dbo.serviceheader SET outstandingamt = coalesce(dbo.fn_getserviceinvtotal((serviceinvcode)::integer), 0) WHERE (serviceinvcode = v_serviceinvcode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
  END IF;
  IF (0 = 0) THEN
    return_value := 0;
    serviceinvcode := v_serviceinvcode;
    RETURN;
  ELSE
    return_value := -1;
    serviceinvcode := v_serviceinvcode;
    RETURN;
  END IF;
  return_value := 0;
  serviceinvcode := v_serviceinvcode;
  RETURN;
END
$body$;

