      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_For_StudentFee_Template' USING ERRCODE = 'TS001';
      return_value := -1;
      serviceinvcode := v_serviceinvcode;
      RETURN;
    END IF;
    INSERT INTO dbo.servicedetail (serviceinvcode, servicecode, smancode, qty, price, serviceflatdisc, discperc, remarks) SELECT v_serviceinvcode, v_servicecode, 1 AS smancode, 1 AS qty, v_fee AS saleprice, CASE WHEN (round(((((v_fee - v_flatdisc)) * ((1 - (v_discperc * 0.01)))))::numeric, 2) > 0) THEN v_flatdisc ELSE v_fee END AS serviceflatdisc, v_discperc AS discperc, v_remarks UNION ALL SELECT v_serviceinvcode, servicecode, smancode, qty AS qty, saleprice, serviceflatdisc, discperc, NULL::citext AS remarks FROM dbo.servicetemplatedetail WHERE ((v_servicetemplate > 0) AND (servicetemplatecode = v_servicetemplate));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem while Inserting Record in ServiceDetail';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_For_StudentFee_Template' USING ERRCODE = 'TS001';
      return_value := -1;
      serviceinvcode := v_serviceinvcode;
      RETURN;
    END IF;
    UPDATE dbo.studentclass AS studentclass SET lastserviceinvdate = localtimestamp(3), serviceinvcode = v_serviceinvcode WHERE ((classcode = v_classcode) AND (studentcode = v_studentcode));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem in Updating Student Fee Record';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_For_StudentFee_Template' USING ERRCODE = 'TS001';
      return_value := -1;
      serviceinvcode := v_serviceinvcode;
      RETURN;
    END IF;
    v_errcode := 0;
    _rc := 1;
    SELECT r.return_value INTO v_errcode FROM dbo.sp_updatetabmaxkey(tabname => 'ServiceHeader', key => v_serviceinvcode) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Problem while Updating ServiceHeader Key Value';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_For_StudentFee_Template' USING ERRCODE = 'TS001';
      return_value := -1;
      serviceinvcode := v_serviceinvcode;
      RETURN;
    END IF;
    UPDATE dbo.serviceheader SET invtotal = coalesce(dbo.fn_getserviceinvtotal((serviceinvcode)::integer), 0) WHERE (serviceinvcode = v_serviceinvcode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    UPDATE dbo.serviceheader SET outstandingamt = coalesce(dbo.fn_getserviceinvtotal((serviceinvcode)::integer), 0) WHERE (serviceinvcode = v_serviceinvcode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
  END IF;
  IF (0 = 0) THEN
    return_value := 0;
    serviceinvcode := v_serviceinvcode;
    RETURN;
  ELSE
    return_value := -1;
    serviceinvcode := v_serviceinvcode;
    RETURN;
  END IF;
  return_value := 0;
  serviceinvcode := v_serviceinvcode;
  RETURN;
END
$body$;

-- ==== proc SP_Generate_Svc_For_StudentFee_Template2 ====
CREATE OR REPLACE FUNCTION dbo.sp_generate_svc_for_studentfee_template2(classcode integer, studentcode integer, remarks citext, servicecode integer, fee numeric, flatdisc numeric, discperc numeric, usercode smallint, servicetemplate integer, newduedate timestamp, INOUT serviceinvcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_classcode integer;
  v_studentcode integer;
  v_remarks citext;
  v_servicecode integer;
  v_fee numeric(15,2);
  v_flatdisc numeric(15,2);
  v_discperc numeric(5,2);
  v_usercode smallint;
  v_servicetemplate integer;
  v_newduedate timestamp(3);
  v_serviceinvcode integer;
  v_errcode integer;
  v_end_invcode integer;
  v_feeday integer;
  v_today integer;
  v_duedate timestamp(3);
  _rc integer;
BEGIN
  v_classcode := classcode;
  v_studentcode := studentcode;
  v_remarks := remarks;
  v_servicecode := servicecode;
  v_fee := fee;
  v_flatdisc := flatdisc;
  v_discperc := discperc;
  v_usercode := usercode;
  v_servicetemplate := servicetemplate;
  v_newduedate := newduedate;
  v_serviceinvcode := serviceinvcode;
  IF (v_newduedate IS NULL) THEN
    v_feeday := coalesce((SELECT class.feedueon FROM dbo.class WHERE (class.classcode = v_classcode)), 1);
    _rc := 1;
    v_today := (SELECT extract(day from localtimestamp(3))::integer);
    _rc := 1;
    IF (v_today >= v_feeday) THEN
      IF (extract(month from localtimestamp(3))::integer < 12) THEN
        v_duedate := (((((ltrim(rtrim(dbo.tsql_str((extract(year from localtimestamp(3))::integer)::numeric, 7))) || '-') || ltrim(rtrim(dbo.tsql_str(((extract(month from localtimestamp(3))::integer + 1))::numeric, 7)))) || '-') || ltrim(rtrim(dbo.tsql_str((v_feeday)::numeric, 7)))))::timestamp(3);
        _rc := 1;
      ELSE
        v_duedate := (((((ltrim(rtrim(dbo.tsql_str(((extract(year from localtimestamp(3))::integer + 1))::numeric, 7))) || '-') || '01') || '-') || ltrim(rtrim(dbo.tsql_str((v_feeday)::numeric, 7)))))::timestamp(3);
        _rc := 1;
      END IF;
    ELSE
      v_duedate := (((((ltrim(rtrim(dbo.tsql_str((extract(year from localtimestamp(3))::integer)::numeric, 7))) || '-') || ltrim(rtrim(dbo.tsql_str((extract(month from localtimestamp(3))::integer)::numeric, 7)))) || '-') || ltrim(rtrim(dbo.tsql_str((v_feeday)::numeric, 7)))))::timestamp(3);
      _rc := 1;
    END IF;
  ELSE
    v_duedate := v_newduedate;
    _rc := 1;
  END IF;
  v_duedate := coalesce(v_duedate, localtimestamp(3));
  _rc := 1;
  IF ((v_servicecode <> 0) AND (v_studentcode <> 0)) THEN
    v_errcode := 0;
    _rc := 1;
    SELECT r.return_value, r.key INTO v_errcode, v_serviceinvcode FROM dbo.sp_locktabmaxkey(tabname => 'ServiceHeader', key => v_serviceinvcode) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Problem while Fetching ServiceHeader Key Value';
      return_value := -1;
      serviceinvcode := v_serviceinvcode;
      RETURN;
    END IF;
    v_serviceinvcode := (v_serviceinvcode + 1);
    _rc := 1;
    INSERT INTO dbo.serviceheader (serviceinvcode, custcode, salesmancode, servicecatcode, remarks, originaldate, modifiedby, date, postedby, postdate, headerno, discperc, flatdisc, misccharges, saleinvcode, posted, reprintingcounter, serviceocode, cashreceived, cashtendered, cashcharged, cashback, studentcode, duedate) SELECT v_serviceinvcode, s.custcode AS custcode, v_usercode AS salesmancode, 11 AS serivcecatcode, v_remarks AS remarks, localtimestamp(3) AS originaldate, NULL::smallint AS modifiedby, localtimestamp(3) AS date, v_usercode AS postedby, localtimestamp(3) AS postdate, 1 AS headerno, 0 AS discperc, 0 AS flatdisc, 0 AS misccharges, NULL::integer AS saleinvcode, 'Y' AS posted, 0 AS reprintingcounter, NULL::integer AS serviceocode, 0 AS cashreceived, 0 AS cashtendered, 0 AS cashcharged, 0 AS cashback, s.studentcode AS studentcode, v_duedate AS duedate FROM dbo.student AS s WHERE (s.studentcode = v_studentcode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem while Inserting Record in ServiceHeader';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_For_StudentFee_Template2' USING ERRCODE = 'TS001';
      return_value := -1;
      serviceinvcode := v_serviceinvcode;
      RETURN;
    END IF;
    INSERT INTO dbo.servicedetail (serviceinvcode, servicecode, smancode, qty, price, serviceflatdisc, discperc, remarks) SELECT v_serviceinvcode, v_servicecode, 1 AS smancode, 1 AS qty, v_fee AS saleprice, CASE WHEN (round(((((v_fee - v_flatdisc)) * ((1 - (v_discperc * 0.01)))))::numeric, 2) > 0) THEN v_flatdisc ELSE v_fee END AS serviceflatdisc, v_discperc AS discperc, v_remarks UNION ALL SELECT v_serviceinvcode, servicecode, smancode, qty AS qty, saleprice, serviceflatdisc, discperc, NULL::citext AS remarks FROM dbo.servicetemplatedetail WHERE ((v_servicetemplate > 0) AND (servicetemplatecode = v_servicetemplate));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem while Inserting Record in ServiceDetail';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_For_StudentFee_Template2' USING ERRCODE = 'TS001';
      return_value := -1;
      serviceinvcode := v_serviceinvcode;
      RETURN;
    END IF;
    UPDATE dbo.studentclass AS studentclass SET lastserviceinvdate = localtimestamp(3), serviceinvcode = v_serviceinvcode WHERE ((classcode = v_classcode) AND (studentcode = v_studentcode));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem in Updating Student Fee Record';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_For_StudentFee_Template2' USING ERRCODE = 'TS001';
      return_value := -1;
      serviceinvcode := v_serviceinvcode;
      RETURN;
    END IF;
    v_errcode := 0;
    _rc := 1;
    SELECT r.return_value INTO v_errcode FROM dbo.sp_updatetabmaxkey(tabname => 'ServiceHeader', key => v_serviceinvcode) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Problem while Updating ServiceHeader Key Value';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_For_StudentFee_Template2' USING ERRCODE = 'TS001';
      return_value := -1;
      serviceinvcode := v_serviceinvcode;
      RETURN;
    END IF;
    UPDATE dbo.serviceheader SET invtotal = coalesce(dbo.fn_getserviceinvtotal((serviceinvcode)::integer), 0) WHERE (serviceinvcode = v_serviceinvcode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    UPDATE dbo.serviceheader SET outstandingamt = coalesce(dbo.fn_getserviceinvtotal((serviceinvcode)::integer), 0) WHERE (serviceinvcode = v_serviceinvcode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
  END IF;
  IF (0 = 0) THEN
    return_value := 0;
    serviceinvcode := v_serviceinvcode;
    RETURN;
  ELSE
    return_value := -1;
    serviceinvcode := v_serviceinvcode;
    RETURN;
  END IF;
  return_value := 0;
  serviceinvcode := v_serviceinvcode;
  RETURN;
END
$body$;

-- ==== proc SP_Generate_Svc_For_StudentServiceTemplate ====
CREATE OR REPLACE FUNCTION dbo.sp_generate_svc_for_studentservicetemplate(code integer, usercode smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_code integer;
  v_usercode smallint;
  v_errcode integer;
  v_servicecode integer;
  v_serviceinvcode integer;
  v_end_invcode integer;
  v_rows integer;
  v_detailrows integer;
  v_newrowid integer;
  v_sinvcode integer;
  v_einvcode integer;
  _rc integer;
BEGIN
  v_code := code;
  v_usercode := usercode;
  v_rows := coalesce((SELECT count(studentservicetemplatecode) FROM dbo.studentservicetemplate WHERE (((studentservicetemplatecode = v_code) AND (posted = 'Y')) AND (svcinvgenerated = 'N'))), 0);
  _rc := 1;
  IF ((v_rows = 0) OR (v_rows IS NULL)) THEN
    RAISE EXCEPTION 'Template Already Posted OR used, Please select another one.';
    return_value := -1;
    RETURN;
  END IF;
  v_detailrows := coalesce((SELECT count(*) FROM dbo.studentservicetemplatedetail WHERE (studentservicetemplatecode = v_code)), 0);
  _rc := 1;
  IF ((v_detailrows = 0) OR (v_detailrows IS NULL)) THEN
    RAISE EXCEPTION 'Template Has no rows for students, Please select another one.';
    return_value := -1;
    RETURN;
  END IF;
  v_servicecode := (SELECT servicecode FROM dbo.studentservicetemplate WHERE (((studentservicetemplatecode = v_code) AND (posted = 'Y')) AND (svcinvgenerated = 'N')));
  _rc := 1;
  IF ((v_servicecode = 0) OR (v_servicecode IS NULL)) THEN
    RAISE EXCEPTION 'Template Has no Service selected, Please select another one.';
    return_value := -1;
    RETURN;
  END IF;
  DROP TABLE IF EXISTS tmp_studtemp;
  CREATE TEMP TABLE tmp_studtemp (
    studentcode integer NOT NULL,
    servicecode integer NOT NULL,
    qty numeric(10,2) NOT NULL,
    transportroutecode integer NULL,
    vehiclecode integer NULL,
    charges numeric(12,2) NOT NULL,
    discperc numeric(5,2) NOT NULL,
    serviceflatdisc numeric(12,2) NOT NULL,
    newrowid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    rowid integer NOT NULL,
    remarks citext NULL,
    serviceinvcode integer NULL
) ON COMMIT DROP;
  INSERT INTO tmp_studtemp (studentcode, servicecode, qty, transportroutecode, vehiclecode, charges, discperc, serviceflatdisc, remarks, serviceinvcode, rowid) SELECT studentcode, v_servicecode, qty, transportroutecode, vehiclecode, charges, discperc, serviceflatdisc, remarks, NULL::integer AS serviceinvcode, rowid FROM dbo.studentservicetemplatedetail WHERE (studentservicetemplatecode = v_code) ORDER BY rowid;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_detailrows := coalesce((SELECT count(*) FROM tmp_studtemp AS studtemp), 0);
  _rc := 1;
  IF ((v_servicecode <> 0) AND (v_detailrows > 0)) THEN
    v_errcode := 0;
    _rc := 1;
    SELECT r.return_value, r.key INTO v_errcode, v_serviceinvcode FROM dbo.sp_locktabmaxkey(tabname => 'ServiceHeader', key => v_serviceinvcode) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Problem while Fetching ServiceHeader Key Value';
      return_value := -1;
      RETURN;
    END IF;
    UPDATE tmp_studtemp AS studtemp SET serviceinvcode = (v_serviceinvcode + newrowid);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    INSERT INTO dbo.serviceheader (serviceinvcode, custcode, salesmancode, servicecatcode, remarks, originaldate, modifiedby, date, postedby, postdate, headerno, discperc, flatdisc, misccharges, saleinvcode, posted, reprintingcounter, serviceocode, cashreceived, cashtendered, cashcharged, cashback, studentcode) SELECT d.serviceinvcode, s.custcode AS custcode, v_usercode AS salesmancode, 11 AS serivcecatcode, d.remarks AS remarks, localtimestamp(3) AS originaldate, NULL::smallint AS modifiedby, localtimestamp(3) AS date, v_usercode AS postedby, localtimestamp(3) AS postdate, 1 AS headerno, 0 AS discperc, 0 AS flatdisc, 0 AS misccharges, NULL::integer AS saleinvcode, 'Y' AS posted, 0 AS reprintingcounter, NULL::integer AS serviceocode, 0 AS cashreceived, 0 AS cashtendered, 0 AS cashcharged, 0 AS cashback, s.studentcode AS studentcode FROM tmp_studtemp AS d, dbo.student AS s WHERE (s.studentcode = d.studentcode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem while Inserting Record in ServiceHeader';
      return_value := -1;
      RETURN;
    END IF;
    INSERT INTO dbo.servicedetail (serviceinvcode, servicecode, smancode, qty, price, serviceflatdisc, discperc, remarks, transportroutecode, vehiclecode) SELECT serviceinvcode, v_servicecode, 1 AS smancode, qty, charges AS saleprice, serviceflatdisc, discperc, remarks, transportroutecode, vehiclecode FROM tmp_studtemp AS studtemp;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem while Inserting Record in ServiceDetail';
      return_value := -1;
      RETURN;
    END IF;
    UPDATE dbo.studentservicetemplatedetail AS d SET serviceinvcode = t.serviceinvcode FROM tmp_studtemp AS t WHERE (t.rowid = d.rowid);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem in Updating Student Service Template Record';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_For_StudentServiceTemplate' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
    v_sinvcode := coalesce((SELECT min(serviceinvcode) FROM tmp_studtemp AS studtemp), 0);
    _rc := 1;
    v_einvcode := coalesce((SELECT max(serviceinvcode) FROM tmp_studtemp AS studtemp), 0);
    _rc := 1;
    v_errcode := 0;
    _rc := 1;
    SELECT r.return_value INTO v_errcode FROM dbo.sp_updatetabmaxkey(tabname => 'ServiceHeader', key => v_einvcode) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Problem while Updating ServiceHeader Key Value';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_For_StudentServiceTemplate' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
    UPDATE dbo.serviceheader SET invtotal = coalesce(dbo.fn_getserviceinvtotal((serviceinvcode)::integer), 0) WHERE (serviceinvcode BETWEEN v_sinvcode AND v_einvcode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    UPDATE dbo.serviceheader SET outstandingamt = invtotal WHERE (serviceinvcode BETWEEN v_sinvcode AND v_einvcode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    UPDATE dbo.studentservicetemplate SET svcinvgenerated = 'Y' WHERE (studentservicetemplatecode = v_code);
    GET DIAGNOSTICS _rc = ROW_COUNT;
  END IF;
  IF (0 = 0) THEN
    return_value := 0;
    RETURN;
  ELSE
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_Generate_Svc_From_AdmPatientRecSvc ====
CREATE OR REPLACE FUNCTION dbo.sp_generate_svc_from_admpatientrecsvc(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_tot_admitted_patients integer;
  v_start_invcode integer;
  v_end_invcode integer;
  v_errcode integer;
  _rc integer;
BEGIN
  DROP TABLE IF EXISTS tv_sp_generate_svc_from_admpatientrecsvc_service_table;
  CREATE TEMP TABLE tv_sp_generate_svc_from_admpatientrecsvc_service_table (
    admissioncode integer NOT NULL,
    serviceinvcode integer NULL,
    rowid integer GENERATED BY DEFAULT AS IDENTITY
) ON COMMIT DROP;
  -- BEGIN TRANSACTION (the caller owns the transaction)
  v_tot_admitted_patients := coalesce((SELECT count(pa.admissioncode) FROM dbo.patientadmission AS pa, dbo.admittedpatientrecurringservices AS apr WHERE (((((pa.discharged1 = 'N') AND (pa.discharged = 'N')) AND (pa.admissioncode = apr.admissioncode)) AND (localtimestamp(3) >= coalesce(apr.startdate, '12-12-9999 00:00:00'))) AND (localtimestamp(3) >= coalesce(apr.nextrunon, '12-12-1900 00:00:00')))), 0);
  _rc := 1;
  IF (v_tot_admitted_patients <> 0) THEN
    INSERT INTO tv_sp_generate_svc_from_admpatientrecsvc_service_table (admissioncode, serviceinvcode) SELECT pa.admissioncode, NULL::integer FROM dbo.patientadmission AS pa WHERE (((pa.discharged1 = 'N') AND (pa.discharged = 'N')) AND (pa.admissioncode IN (SELECT DISTINCT admittedpatientrecurringservices.admissioncode FROM dbo.admittedpatientrecurringservices WHERE ((localtimestamp(3) >= coalesce(admittedpatientrecurringservices.startdate, '12-12-9999 00:00:00')) AND (localtimestamp(3) >= coalesce(admittedpatientrecurringservices.nextrunon, '12-12-1900 00:00:00')))))) ORDER BY pa.admissioncode;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem while Fetching Admitted Patient Recurring Services';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_From_AdmPatientRecSvc' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
    v_errcode := 0;
    _rc := 1;
    SELECT r.return_value, r.key INTO v_errcode, v_start_invcode FROM dbo.sp_locktabmaxkey(tabname => 'ServiceHeader', key => v_start_invcode) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Problem while Fetching ServiceHeader Key Value';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_From_AdmPatientRecSvc' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
    UPDATE tv_sp_generate_svc_from_admpatientrecsvc_service_table AS service_table SET serviceinvcode = (v_start_invcode + rowid);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem while Inserting Record in Temporary Table';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_From_AdmPatientRecSvc' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
    INSERT INTO dbo.serviceheader (serviceinvcode, custcode, salesmancode, servicecatcode, remarks, originaldate, modifiedby, date, postedby, postdate, headerno, discperc, flatdisc, misccharges, saleinvcode, posted, doctcode, reprintingcounter, serviceocode, cashreceived, patientcode, admissioncode) SELECT t.serviceinvcode, p.custcode AS custcode, 1 AS salesmancode, 11 AS serivcecatcode, 'Recurring Services' AS remarks, localtimestamp(3) AS originaldate, NULL::smallint AS modifiedby, localtimestamp(3) AS date, 1 AS postedby, localtimestamp(3) AS postdate, 1 AS headerno, 0 AS discperc, 0 AS flatdisc, 0 AS misccharges, NULL::integer AS saleinvcode, 'Y' AS posted, pa.doctorcode AS doctcode, 0 AS reprintingcounter, NULL::integer AS serviceocode, 0 AS cashreceived, NULL::integer AS patientcode, pa.admissioncode FROM dbo.patientadmission AS pa, dbo.patient AS p, (SELECT serviceinvcode, admissioncode FROM tv_sp_generate_svc_from_admpatientrecsvc_service_table AS service_table) AS t WHERE ((pa.admissioncode = t.admissioncode) AND (pa.patientcode = p.patientcode)) ORDER BY t.admissioncode;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem while Inserting Record in ServiceHeader';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_From_AdmPatientRecSvc' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
    INSERT INTO dbo.servicedetail (serviceinvcode, servicecode, smancode, qty, price, discperc) SELECT t.serviceinvcode, apr.servicecode, apr.smancode, apr.qty, apr.saleprice, apr.discperc FROM (SELECT serviceinvcode, admissioncode FROM tv_sp_generate_svc_from_admpatientrecsvc_service_table AS service_table) AS t, dbo.admittedpatientrecurringservices AS apr WHERE (((t.admissioncode = apr.admissioncode) AND (localtimestamp(3) >= coalesce(apr.startdate, '12-12-9999 00:00:00'))) AND (localtimestamp(3) >= coalesce(apr.nextrunon, '12-12-1900 00:00:00'))) ORDER BY apr.admissioncode, apr.rowid;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem while Inserting Record in ServiceDetail';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_From_AdmPatientRecSvc' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
    UPDATE dbo.patientadmission AS patientadmission SET recurringserviceschargedon = localtimestamp(3), serviceinvcode = t.serviceinvcode FROM (SELECT serviceinvcode, admissioncode FROM tv_sp_generate_svc_from_admpatientrecsvc_service_table AS service_table) AS t WHERE (patientadmission.admissioncode = t.admissioncode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem in Updating Patient Admission Record';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_From_AdmPatientRecSvc' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
    UPDATE dbo.admittedpatientrecurringservices AS admittedpatientrecurringservices SET nextrunon = (coalesce(admittedpatientrecurringservices.nextrunon, localtimestamp(3)) + (admittedpatientrecurringservices.frequencyhrs) * interval '1 hour') FROM dbo.patientadmission AS pa WHERE (((((pa.discharged1 = 'N') AND (pa.discharged = 'N')) AND (pa.admissioncode = admittedpatientrecurringservices.admissioncode)) AND (localtimestamp(3) >= coalesce(admittedpatientrecurringservices.startdate, '12-12-9999 00:00:00'))) AND (localtimestamp(3) >= coalesce(admittedpatientrecurringservices.nextrunon, '12-12-1900 00:00:00')));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_end_invcode := coalesce((SELECT max(serviceinvcode) FROM tv_sp_generate_svc_from_admpatientrecsvc_service_table AS service_table), 0);
    _rc := 1;
    IF (0 <> 0) THEN
      RAISE EXCEPTION 'Problem in Updating Service Header Key Value';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_From_AdmPatientRecSvc' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
    UPDATE dbo.serviceheader SET invtotal = coalesce(dbo.fn_getserviceinvtotal((serviceheader.serviceinvcode)::integer), 0) WHERE (serviceheader.serviceinvcode IN (SELECT DISTINCT serviceinvcode FROM tv_sp_generate_svc_from_admpatientrecsvc_service_table AS service_table));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_errcode := 0;
    _rc := 1;
    SELECT r.return_value INTO v_errcode FROM dbo.sp_updatetabmaxkey(tabname => 'ServiceHeader', key => v_end_invcode) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Problem while Updating ServiceHeader Key Value';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_From_AdmPatientRecSvc' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  IF (0 = 0) THEN
    -- COMMIT (the caller owns the transaction)
    return_value := 0;
    RETURN;
  ELSE
    RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_From_AdmPatientRecSvc' USING ERRCODE = 'TS001';
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_Generate_Svc_From_CheckedInGuest ====
CREATE OR REPLACE FUNCTION dbo.sp_generate_svc_from_checkedinguest(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_tot_checkedin integer;
  v_start_invcode integer;
  v_end_invcode integer;
  v_errcode integer;
  _rc integer;
BEGIN
  DROP TABLE IF EXISTS tv_sp_generate_svc_from_checkedinguest_service_table;
  CREATE TEMP TABLE tv_sp_generate_svc_from_checkedinguest_service_table (
    guestcheckincode integer NOT NULL,
    serviceinvcode integer NULL,
    rowid integer GENERATED BY DEFAULT AS IDENTITY
) ON COMMIT DROP;
  -- BEGIN TRANSACTION (the caller owns the transaction)
  v_tot_checkedin := coalesce((SELECT count(gc.guestcheckincode) FROM dbo.guestcheckin AS gc, dbo.guestcheckinservice AS gcs WHERE (((gc.checkout = 'N') AND (gc.guestcheckincode = gcs.guestcheckincode)) AND (((localtimestamp(3))::date - (coalesce(gc.recurringservicechargedon, (timestamp '1900-01-01' + (0) * interval '1 day')))::date) >= 1))), 0);
  _rc := 1;
  IF (v_tot_checkedin <> 0) THEN
    INSERT INTO tv_sp_generate_svc_from_checkedinguest_service_table (guestcheckincode, serviceinvcode) SELECT gc.guestcheckincode, NULL::integer FROM dbo.guestcheckin AS gc WHERE (((gc.checkout = 'N') AND (((localtimestamp(3))::date - (coalesce(gc.recurringservicechargedon, (timestamp '1900-01-01' + (0) * interval '1 day')))::date) >= 1)) AND (gc.guestcheckincode IN (SELECT DISTINCT guestcheckincode FROM dbo.guestcheckinservice))) ORDER BY gc.guestcheckincode;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem while Fetching Checked-In Guest Recurring Services';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_From_CheckedInGuest' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
    v_errcode := 0;
    _rc := 1;
    SELECT r.return_value, r.key INTO v_errcode, v_start_invcode FROM dbo.sp_locktabmaxkey(tabname => 'ServiceHeader', key => v_start_invcode) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Problem while Fetching ServiceHeader Key Value';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_From_CheckedInGuest' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
    UPDATE tv_sp_generate_svc_from_checkedinguest_service_table AS service_table SET serviceinvcode = (v_start_invcode + rowid);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem while Inserting Record in Temporary Table';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_From_CheckedInGuest' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
    INSERT INTO dbo.serviceheader (serviceinvcode, custcode, salesmancode, servicecatcode, remarks, originaldate, modifiedby, date, postedby, postdate, headerno, discperc, flatdisc, misccharges, saleinvcode, posted, doctcode, reprintingcounter, serviceocode, cashreceived, guestcode, guestcheckincode) SELECT t.serviceinvcode, g.custcode AS custcode, 1 AS salesmancode, 11 AS serivcecatcode, 'Recurring Services' AS remarks, localtimestamp(3) AS originaldate, NULL::smallint AS modifiedby, localtimestamp(3) AS date, 1 AS postedby, localtimestamp(3) AS postdate, 1 AS headerno, 0 AS discperc, 0 AS flatdisc, 0 AS misccharges, NULL::integer AS saleinvcode, 'Y' AS posted, NULL::smallint AS doctcode, 0 AS reprintingcounter, NULL::integer AS serviceocode, 0 AS cashreceived, gc.guestcode AS guestcode, gc.guestcheckincode FROM dbo.guestcheckin AS gc, dbo.guest AS g, (SELECT serviceinvcode, guestcheckincode FROM tv_sp_generate_svc_from_checkedinguest_service_table AS service_table) AS t WHERE ((gc.guestcheckincode = t.guestcheckincode) AND (gc.guestcode = g.guestcode)) ORDER BY t.guestcheckincode;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem while Inserting Record in ServiceHeader';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_From_CheckedInGuest' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
    INSERT INTO dbo.servicedetail (serviceinvcode, servicecode, smancode, qty, price, discperc) SELECT t.serviceinvcode, gcs.servicecode, gcs.smancode, gcs.qty, gcs.saleprice, gcs.discperc FROM (SELECT serviceinvcode, guestcheckincode FROM tv_sp_generate_svc_from_checkedinguest_service_table AS service_table) AS t, dbo.guestcheckinservice AS gcs WHERE (t.guestcheckincode = gcs.guestcheckincode) ORDER BY gcs.guestcheckincode, gcs.rowid;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem while Inserting Record in ServiceDetail';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_From_CheckedInGuest' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
    UPDATE dbo.guestcheckin AS guestcheckin SET recurringservicechargedon = localtimestamp(3), serviceinvcode = t.serviceinvcode FROM (SELECT serviceinvcode, guestcheckincode FROM tv_sp_generate_svc_from_checkedinguest_service_table AS service_table) AS t WHERE (guestcheckin.guestcheckincode = t.guestcheckincode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem in Updating Guest Checked-In Record';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_From_CheckedInGuest' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
    v_end_invcode := coalesce((SELECT max(serviceinvcode) FROM tv_sp_generate_svc_from_checkedinguest_service_table AS service_table), 0);
    _rc := 1;
    IF (0 <> 0) THEN
      RAISE EXCEPTION 'Problem in Updating Service Header Key Value';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_From_CheckedInGuest' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
    UPDATE dbo.serviceheader AS serviceheader SET invtotal = dbo.fn_getserviceinvtotal((t.serviceinvcode)::integer) FROM (SELECT serviceinvcode FROM tv_sp_generate_svc_from_checkedinguest_service_table AS service_table) AS t WHERE (serviceheader.serviceinvcode = t.serviceinvcode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF (0 <> 0) THEN
      RAISE EXCEPTION 'Problem in Updating Service Invoice Totals';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_From_CheckedInGuest' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
    v_errcode := 0;
    _rc := 1;
    SELECT r.return_value INTO v_errcode FROM dbo.sp_updatetabmaxkey(tabname => 'ServiceHeader', key => v_end_invcode) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Problem while Updating ServiceHeader Key Value';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_From_CheckedInGuest' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  IF (0 = 0) THEN
    -- COMMIT (the caller owns the transaction)
    return_value := 0;
    RETURN;
  ELSE
    RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_From_CheckedInGuest' USING ERRCODE = 'TS001';
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_Generate_Svc_From_PatientRecSvc ====
CREATE OR REPLACE FUNCTION dbo.sp_generate_svc_from_patientrecsvc(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_tot_patients integer;
  v_start_invcode integer;
  v_end_invcode integer;
  v_errcode integer;
  _rc integer;
BEGIN
  DROP TABLE IF EXISTS tv_sp_generate_svc_from_patientrecsvc_service_table;
  CREATE TEMP TABLE tv_sp_generate_svc_from_patientrecsvc_service_table (
    patientcode integer NOT NULL,
    serviceinvcode integer NULL,
    rowid integer GENERATED BY DEFAULT AS IDENTITY
) ON COMMIT DROP;
  -- BEGIN TRANSACTION (the caller owns the transaction)
  v_tot_patients := coalesce((SELECT count(p.patientcode) FROM dbo.patient AS p, dbo.patientrecservices AS pr WHERE ((p.autogenrecurringserviceinv = 'Y') AND (p.patientcode = pr.patientcode))), 0);
  _rc := 1;
  IF (v_tot_patients <> 0) THEN
    INSERT INTO tv_sp_generate_svc_from_patientrecsvc_service_table (patientcode, serviceinvcode) SELECT pa.patientcode, NULL::integer FROM dbo.patient AS pa, dbo.patientrecservices AS pr WHERE ((pa.autogenrecurringserviceinv = 'Y') AND (pa.patientcode = pr.patientcode)) ORDER BY pa.patientcode;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem while Fetching Patient Recurring Services';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_From_PatientRecSvc' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
    v_errcode := 0;
    _rc := 1;
    SELECT r.return_value, r.key INTO v_errcode, v_start_invcode FROM dbo.sp_locktabmaxkey(tabname => 'ServiceHeader', key => v_start_invcode) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Problem while Fetching ServiceHeader Key Value';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_From_PatientRecSvc' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
    UPDATE tv_sp_generate_svc_from_patientrecsvc_service_table AS service_table SET serviceinvcode = (v_start_invcode + rowid);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem while Inserting Record in Temporary Table';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_From_PatientRecSvc' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
    INSERT INTO dbo.serviceheader (serviceinvcode, custcode, salesmancode, servicecatcode, remarks, originaldate, modifiedby, date, postedby, postdate, headerno, discperc, flatdisc, misccharges, saleinvcode, posted, doctcode, reprintingcounter, serviceocode, cashreceived, patientcode, admissioncode) SELECT t.serviceinvcode, p.custcode AS custcode, 1 AS salesmancode, 11 AS serivcecatcode, 'Recurring Services' AS remarks, localtimestamp(3) AS originaldate, NULL::smallint AS modifiedby, localtimestamp(3) AS date, 1 AS postedby, localtimestamp(3) AS postdate, 1 AS headerno, 0 AS discperc, 0 AS flatdisc, 0 AS misccharges, NULL::integer AS saleinvcode, 'Y' AS posted, p.doctcode AS doctcode, 0 AS reprintingcounter, NULL::integer AS serviceocode, 0 AS cashreceived, p.patientcode AS patientcode, NULL::integer FROM dbo.patient AS p, (SELECT serviceinvcode, patientcode FROM tv_sp_generate_svc_from_patientrecsvc_service_table AS service_table) AS t WHERE (p.patientcode = t.patientcode) ORDER BY p.patientcode;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem while Inserting Record in ServiceHeader';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_From_PatientRecSvc' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
    INSERT INTO dbo.servicedetail (serviceinvcode, servicecode, smancode, qty, price, discperc) SELECT t.serviceinvcode, apr.servicecode, apr.smancode, apr.qty, apr.saleprice, apr.discperc FROM (SELECT serviceinvcode, patientcode FROM tv_sp_generate_svc_from_patientrecsvc_service_table AS service_table) AS t, dbo.patientrecservices AS apr WHERE (t.patientcode = apr.patientcode) ORDER BY apr.patientcode, apr.rowid;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem while Inserting Record in ServiceDetail';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_From_PatientRecSvc' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
    UPDATE dbo.patient AS patient SET recurringserviceschargedon = localtimestamp(3), serviceinvcode = t.serviceinvcode FROM (SELECT serviceinvcode, patientcode FROM tv_sp_generate_svc_from_patientrecsvc_service_table AS service_table) AS t WHERE (patient.patientcode = t.patientcode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem in Updating Patient Record';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_From_PatientRecSvc' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
    v_end_invcode := coalesce((SELECT max(serviceinvcode) FROM tv_sp_generate_svc_from_patientrecsvc_service_table AS service_table), 0);
    _rc := 1;
    IF (0 <> 0) THEN
      RAISE EXCEPTION 'Problem in Updating Service Header Key Value';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_From_PatientRecSvc' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
    v_errcode := 0;
    _rc := 1;
    SELECT r.return_value INTO v_errcode FROM dbo.sp_updatetabmaxkey(tabname => 'ServiceHeader', key => v_end_invcode) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Problem while Updating ServiceHeader Key Value';
      RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_From_PatientRecSvc' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  IF (0 = 0) THEN
    -- COMMIT (the caller owns the transaction)
    return_value := 0;
    RETURN;
  ELSE
    RAISE EXCEPTION 'T-SQL ROLLBACK in SP_Generate_Svc_From_PatientRecSvc' USING ERRCODE = 'TS001';
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_GenerateAutoSale ====
CREATE OR REPLACE FUNCTION dbo.sp_generateautosale(machinename citext, saletemplatecode integer, usercode integer, gcode integer, headerno integer, startdate timestamp, enddate timestamp, max_lineitems integer, max_lineitems_coushin integer, max_itemqty integer, INOUT sinvno integer, INOUT einvno integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_machinename citext;
  v_saletemplatecode integer;
  v_usercode integer;
  v_gcode integer;
  v_headerno integer;
  v_startdate timestamp(3);
  v_enddate timestamp(3);
  v_max_lineitems integer;
  v_max_lineitems_coushin integer;
  v_max_itemqty integer;
  v_sinvno integer;
  v_einvno integer;
  v_module integer;
  v_custcode integer;
  v_saletypecode smallint;
  v_salecatcode integer;
  v_headerinvno integer;
  v_continue integer;
  v_rt_code integer;
  v_err integer;
  v_totalrows integer;
  v_rowcount integer;
  v_invcounter integer;
  v_counter integer;
  v_saleinvcode integer;
  v_rand_itemqty integer;
  v_rand_lineitems integer;
  v_rand_item integer;
  v_satisfiableqty integer;
  v_satisfiedqty integer;
  v_item_in_inv_exist integer;
  v_saleprice numeric(12,2);
  v_rate numeric(12,2);
  v_discperc numeric(5,2);
  v_itemflatdisc numeric(12,2);
  v_unitsalestax numeric(12,2);
  v_gstperc1 numeric(6,2);
  v_gstperc2 numeric(6,2);
  v_hold_avgprice numeric(15,5);
  v_icode integer;
  v_anyitem_exist integer;
  v_packunits integer;
  v_totalqty numeric(15,4);
  v_givenqty numeric(15,4);
  v_reqqty numeric(15,4);
  v_batchqty numeric(15,4);
  v_delqty numeric(15,4);
  v_currqty numeric(15,4);
  v_newqty numeric(15,4);
  v_total_availablestock numeric(15,4);
  v_batch citext;
  v_itemname citext;
  v_expiry timestamp(3);
  v_serverdate timestamp(3);
  v_saleutn bigint;
  v_firsttime smallint;
  v_saletemplate_rowcount integer;
  v_invdetail_exist integer;
  v_rowgroup integer;
  v_lineitems_rowcount integer;
  v_innercounter integer;
  _xc1 refcursor;
  _xr1 record;
  _r2 record;
  _r3 record;
  cur_itembatch_cursor refcursor;
  _rc integer;
  _fs integer := -1;
BEGIN
  v_machinename := machinename;
  v_saletemplatecode := saletemplatecode;
  v_usercode := usercode;
  v_gcode := gcode;
  v_headerno := headerno;
  v_startdate := startdate;
  v_enddate := enddate;
  v_max_lineitems := max_lineitems;
  v_max_lineitems_coushin := max_lineitems_coushin;
  v_max_itemqty := max_itemqty;
  v_sinvno := sinvno;
  v_einvno := einvno;
  v_firsttime := 0;
  _rc := 1;
  v_custcode := 19;
  _rc := 1;
  v_salecatcode := 3;
  _rc := 1;
  v_saletypecode := 2;
  _rc := 1;
  v_module := (SELECT module FROM dbo.module WHERE (name = 'Sales'));
  _rc := 1;
  v_serverdate := v_enddate;
  _rc := 1;
  DROP TABLE IF EXISTS tmp_randomitemlist;
  CREATE TEMP TABLE tmp_randomitemlist (
    lineid integer NOT NULL,
    randomvalue integer NOT NULL
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_saletemp;
  CREATE TEMP TABLE tmp_saletemp (
    id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    icode integer,
    satisfiableqty integer,
    satisfiedqty integer,
    saleprice numeric(12,2),
    discperc numeric(8,2),
    itemflatdisc numeric(12,2),
    unitsalestax numeric(12,2),
    gstperc numeric(6,2)
) ON COMMIT DROP;
  INSERT INTO tmp_saletemp (icode, satisfiableqty, satisfiedqty, saleprice, discperc, itemflatdisc, unitsalestax, gstperc) SELECT icode, trunc(looseqty)::integer, 0, saleprice, discperc, itemflatdisc, unitsalestax, gstperc FROM dbo.saletemplatedetail WHERE (saletemplatecode = v_saletemplatecode) ORDER BY rowid;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_saletemplate_rowcount := ((SELECT count(*) FROM dbo.saletemplatedetail WHERE (saletemplatecode = v_saletemplatecode)) + 1);
  _rc := 1;
  v_anyitem_exist := (SELECT sum((satisfiableqty - satisfiedqty)) FROM tmp_saletemp AS saletemp);
  _rc := 1;
  v_continue := 0;
  _rc := 1;
  v_invcounter := 1;
  _rc := 1;
  v_invdetail_exist := 1;
  _rc := 1;
  v_rowgroup := 0;
  _rc := 1;
  WHILE ((v_anyitem_exist > 0) AND (v_continue >= 0)) LOOP
    IF (v_invdetail_exist > 0) THEN
      SELECT r.return_value, r.key INTO v_rt_code, v_saleinvcode FROM dbo.sp_gettabmaxkey(tabname => 'Saleledger', key => v_saleinvcode) AS r;
    END IF;
    IF ((v_firsttime = 0)) THEN
      v_sinvno := v_saleinvcode;
      _rc := 1;
      v_firsttime := 1;
      _rc := 1;
    END IF;
    v_rowgroup := 0;
    _rc := 1;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      v_continue := -1;
      _rc := 1;
    ELSE
      IF (v_invdetail_exist > 0) THEN
        SELECT r.return_value, r.key INTO v_rt_code, v_headerinvno FROM dbo.sp_getheadertabmaxkey(headercode => (v_headerno)::smallint, modulecode => (v_module)::smallint, key => v_headerinvno) AS r;
      END IF;
      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
        v_continue := -1;
        _rc := 1;
      ELSE
        v_err := 0;
        _rc := 1;
        v_rowcount := 1;
        _rc := 1;
        IF (v_invdetail_exist > 0) THEN
          INSERT INTO dbo.saleledger (saleinvcode, salecatcode, custcode, sprice, salesmancode, date, discperc, flatdisc, misccharges, salestax, posted, postdate, headerno, headerinvno, originaldate, invtotal, machinename, modifycounter, billingdate, saletypecode) VALUES (v_saleinvcode, v_salecatcode, v_custcode, 1, v_usercode, v_serverdate, 0, 0, 0, 0, 'N', v_serverdate, v_headerno, v_headerinvno, v_serverdate, 0, v_machinename, 0, v_serverdate, v_saletypecode);
          GET DIAGNOSTICS _rc = ROW_COUNT;
          v_err := 0;
          v_rowcount := _rc;
          _rc := 1;
        END IF;
        IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
          RAISE EXCEPTION 'Error occured in inserting record into Sale Ledger : %', v_saleinvcode;
          v_continue := -1;
          _rc := 1;
        ELSE
          v_rand_lineitems := trunc((random() * v_max_lineitems))::integer;
          _rc := 1;
          IF (v_rand_lineitems = 0) THEN
            v_rand_lineitems := 1;
            _rc := 1;
          END IF;
          v_anyitem_exist := (SELECT sum((satisfiableqty - satisfiedqty)) FROM tmp_saletemp AS saletemp);
          _rc := 1;
          v_lineitems_rowcount := v_max_lineitems;
          _rc := 1;
          TRUNCATE TABLE tmp_randomitemlist RESTART IDENTITY;
          SELECT r.rs1 INTO _xc1 FROM dbo.sp_getrandomvaluetable(rows => v_lineitems_rowcount, max_randomvalue => v_saletemplate_rowcount) AS r;
          LOOP
            FETCH _xc1 INTO _xr1;
            EXIT WHEN NOT FOUND;
            INSERT INTO tmp_randomitemlist (lineid, randomvalue)
              SELECT (a.v)[1]::integer, (a.v)[2]::integer FROM (SELECT array_agg(value ORDER BY ord) AS v FROM json_each_text(row_to_json(_xr1)) WITH ORDINALITY AS j(key, value, ord)) a;
          END LOOP;
          CLOSE _xc1;
          GET DIAGNOSTICS _rc = ROW_COUNT;
          v_innercounter := 1;
          _rc := 1;
          WHILE (((((v_rand_lineitems > 0)) AND ((v_anyitem_exist > 0))) AND ((v_innercounter <= v_lineitems_rowcount))) AND ((v_continue >= 0))) LOOP
            v_rand_item := (SELECT randomvalue FROM tmp_randomitemlist AS randomitemlist WHERE (lineid = v_innercounter));
            _rc := 1;
            _rc := 0;
            FOR _r2 IN SELECT icode AS c1, satisfiableqty AS c2, satisfiedqty AS c3, saleprice AS c4, discperc AS c5, itemflatdisc AS c6, unitsalestax AS c7, gstperc AS c8 FROM tmp_saletemp AS saletemp WHERE (id = v_rand_item) LOOP
              _rc := _rc + 1;
              v_icode := _r2.c1;
              v_satisfiableqty := _r2.c2;
              v_satisfiedqty := _r2.c3;
              v_saleprice := _r2.c4;
              v_discperc := _r2.c5;
              v_itemflatdisc := _r2.c6;
              v_unitsalestax := _r2.c7;
              v_gstperc1 := _r2.c8;
            END LOOP;
            v_rowcount := _rc;
            _rc := 1;
            v_item_in_inv_exist := (SELECT count(*) FROM dbo.saledetail WHERE ((saleinvcode = v_saleinvcode) AND (icode = v_icode)));
            _rc := 1;
            IF ((((v_item_in_inv_exist = 0)) AND ((v_rowcount = 1))) AND ((((v_satisfiableqty - v_satisfiedqty)) > 0))) THEN
              v_rand_itemqty := trunc((random() * v_max_itemqty))::integer;
              _rc := 1;
              IF (v_rand_itemqty = 0) THEN
                v_rand_itemqty := 1;
                _rc := 1;
              END IF;
              IF (((v_rand_itemqty + v_satisfiedqty)) <= v_satisfiableqty) THEN
                v_givenqty := v_rand_itemqty;
                _rc := 1;
              ELSE
                v_givenqty := (v_satisfiableqty - v_satisfiedqty);
                _rc := 1;
              END IF;
              IF (v_givenqty <= 0) THEN
                v_givenqty := 1;
                _rc := 1;
              ELSE
                UPDATE tmp_saletemp AS saletemp SET satisfiedqty = trunc((v_satisfiedqty + v_givenqty))::integer WHERE (icode = v_icode);
                GET DIAGNOSTICS _rc = ROW_COUNT;
              END IF;
              SELECT r.return_value, r.avgprice INTO v_rt_code, v_hold_avgprice FROM dbo.sp_getitemavgprice(icode => v_icode, avgprice => v_hold_avgprice) AS r;
              IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                v_continue := -1;
                _rc := 1;
              ELSE
                v_total_availablestock := (SELECT coalesce(sum(currqty), 0) FROM dbo.godowndetail WHERE (godowndetail.icode = v_icode));
                _rc := 1;
                IF ((v_total_availablestock < 0) OR (v_total_availablestock IS NULL)) THEN
                  v_total_availablestock := 0;
                  _rc := 1;
                END IF;
                v_totalqty := (SELECT coalesce(sum(currqty), 0) FROM dbo.godowndetail WHERE ((godowndetail.gcode = v_gcode) AND (godowndetail.icode = v_icode)));
                _rc := 1;
                IF (v_totalqty >= v_givenqty) THEN
                  v_rowgroup := (v_rowgroup + 1);
                  _rc := 1;
                  _rc := 0;
                  FOR _r3 IN SELECT saleprice AS c1, packunits AS c2 FROM dbo.item WHERE (icode = v_icode) LOOP
                    _rc := _rc + 1;
                    v_rate := _r3.c1;
                    v_packunits := _r3.c2;
                  END LOOP;
                  IF ((v_packunits = 0) OR (v_packunits IS NULL)) THEN
                    v_packunits := 1;
                    _rc := 1;
                  END IF;
                  v_reqqty := v_givenqty;
                  _rc := 1;
                  OPEN cur_itembatch_cursor FOR SELECT batch, expiry, currqty FROM dbo.godowndetail WHERE ((godowndetail.gcode = v_gcode) AND (godowndetail.icode = v_icode)) ORDER BY priority, expiry, currqty;
                  v_totalrows := (-1);
                  _rc := 1;
                  FETCH NEXT FROM cur_itembatch_cursor INTO v_batch, v_expiry, v_currqty;
                  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
                  v_counter := 1;
                  _rc := 1;
                  WHILE (((_fs = 0) AND (v_counter <= v_totalrows)) AND (v_reqqty > 0)) LOOP
                    v_batchqty := v_currqty;
                    _rc := 1;
                    IF (v_batchqty >= v_reqqty) THEN
                      v_delqty := v_reqqty;
                      _rc := 1;
                    ELSE
                      v_delqty := v_batchqty;
                      _rc := 1;
                    END IF;
                    v_reqqty := (v_reqqty - v_delqty);
                    _rc := 1;
                    SELECT r.return_value, r.lbi_maxutn INTO v_rt_code, v_saleutn FROM dbo.sp_maxutn(lbi_rows => (1)::bigint, lbi_maxutn => v_saleutn) AS r;
                    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                      v_continue := -1;
                      _rc := 1;
                    END IF;
                    v_total_availablestock := (v_total_availablestock - v_delqty);
                    _rc := 1;
                    INSERT INTO dbo.saledetail (saleinvcode, icode, gcode, batch, expiry, packqty, looseqty, packunits, saleprice, avgprice, rate, discperc, salestax, itemflatdisc, packprice, unitsalestax, gstperc, saleutn, balancestock, rowgroup) VALUES (v_saleinvcode, v_icode, v_gcode, v_batch, v_expiry, 0, v_delqty, v_packunits, v_saleprice, v_hold_avgprice, (v_rate / v_packunits), v_discperc, 0, v_itemflatdisc, v_rate, v_unitsalestax, v_gstperc1, v_saleutn, v_total_availablestock, v_rowgroup);
                    GET DIAGNOSTICS _rc = ROW_COUNT;
                    v_err := 0;
                    v_rowcount := _rc;
                    _rc := 1;
                    IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
                      RAISE EXCEPTION 'Error occured in inserting record into Sale Detail for Sale Inv. No. : %', v_saleinvcode;
                      v_continue := -1;
                      _rc := 1;
                    ELSE
                      v_newqty := (v_currqty - v_delqty);
                      _rc := 1;
                      IF (v_newqty > 0) THEN
                        SELECT r.return_value INTO v_rt_code FROM dbo.sp_saleupdateitemstockbatch(gcode => v_gcode, icode => v_icode, batch => v_batch, expiry => v_expiry, newqty => v_newqty, oldqty => v_currqty) AS r;
                      ELSE
                        SELECT r.return_value INTO v_rt_code FROM dbo.sp_deleteitemstockbatch(gcode => v_gcode, icode => v_icode, batch => v_batch, expiry => v_expiry, oldqty => v_delqty) AS r;
                      END IF;
                      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                        v_continue := -1;
                        _rc := 1;
                      END IF;
                    END IF;
                    v_counter := (v_counter + 1);
                    _rc := 1;
                    FETCH NEXT FROM cur_itembatch_cursor INTO v_batch, v_expiry, v_currqty;
                    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
                  END LOOP;
                  CLOSE cur_itembatch_cursor;
                  -- DEALLOCATE ItemBatch_Cursor
                ELSE
                  v_itemname := (SELECT name FROM dbo.item WHERE (icode = v_icode));
                  _rc := 1;
                  RAISE EXCEPTION 'Not enough stock for item (%) to decrease for Sale Inv. No : %', v_itemname, v_saleinvcode;
                  v_continue := -1;
                  _rc := 1;
                END IF;
              END IF;
            END IF;
            v_innercounter := (v_innercounter + 1);
            _rc := 1;
            v_anyitem_exist := (SELECT sum((satisfiableqty - satisfiedqty)) FROM tmp_saletemp AS saletemp);
            _rc := 1;
            v_rand_lineitems := (v_rand_lineitems - 1);
            _rc := 1;
          END LOOP;
          v_invdetail_exist := (SELECT count(*) FROM dbo.saledetail WHERE (saleinvcode = v_saleinvcode));
          _rc := 1;
        END IF;
      END IF;
    END IF;
    v_anyitem_exist := (SELECT sum((satisfiableqty - satisfiedqty)) FROM tmp_saletemp AS saletemp);
    _rc := 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_saletemp;
  DROP TABLE IF EXISTS tmp_randomitemlist;
  IF ((v_continue >= 0)) THEN
    v_einvno := v_saleinvcode;
    _rc := 1;
    UPDATE dbo.saleledger SET invtotal = dbo.fn_getsaleinvtotal((saleledger.saleinvcode)::integer) WHERE (saleinvcode BETWEEN v_sinvno AND v_einvno);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_err := 0;
    v_rowcount := _rc;
    _rc := 1;
    IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
      RAISE EXCEPTION 'Unable to update SaleInvoices for Sale Inv. total';
      v_continue := -1;
      _rc := 1;
    ELSE
      SELECT r.return_value INTO v_rt_code FROM dbo.sp_setdateforautosalegen(startdate => v_startdate, enddate => v_enddate, sinvno => v_sinvno, einvno => v_einvno) AS r;
      v_err := 0;
      _rc := 1;
      IF ((v_err <> 0) OR (v_rt_code <> 0)) THEN
        RAISE EXCEPTION 'Unable to update SaleInvoices for Date adjustment';
        v_continue := -1;
        _rc := 1;
      ELSE
        INSERT INTO dbo.autosalelog (saletemplatecode, ssaleinvcode, esaleinvcode, sdate, edate) VALUES (v_saletemplatecode, v_sinvno, v_einvno, v_startdate, v_enddate);
        GET DIAGNOSTICS _rc = ROW_COUNT;
        v_err := 0;
        v_rowcount := _rc;
        _rc := 1;
        IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
          RAISE EXCEPTION 'Database error in inserting record in AutoSaleLog';
          v_continue := -1;
          _rc := 1;
        END IF;
      END IF;
    END IF;
  END IF;
  return_value := v_continue;
  sinvno := v_sinvno;
  einvno := v_einvno;
  RETURN;
  return_value := 0;
  sinvno := v_sinvno;
  einvno := v_einvno;
  RETURN;
END
$body$;

-- ==== proc sp_GenerateIssue ====
CREATE OR REPLACE FUNCTION dbo.sp_generateissue(prodcode integer, usercode integer, headerno integer, serverdate timestamp, INOUT issueinvcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_prodcode integer;
  v_usercode integer;
  v_headerno integer;
  v_serverdate timestamp(3);
  v_issueinvcode integer;
  v_code integer;
  v_deptcode integer;
  v_module smallint;
  v_utn integer;
  v_headerinvno integer;
  v_category smallint;
  v_issuecode integer;
  v_issuetype smallint;
  v_pricetype smallint;
  v_issuegodownstrategy smallint;
  v_dracccode smallint;
  v_icode integer;
  v_gcode integer;
  v_packunits integer;
  v_areacode integer;
  v_prodrowid integer;
  v_rowid integer;
  v_groupcode integer;
  v_givenqty numeric(15,4);
  v_totalqty numeric(15,4);
  v_currqty numeric(15,4);
  v_delqty numeric(15,4);
  v_batchqty numeric(15,4);
  v_reqqty numeric(15,4);
  v_newqty numeric(15,4);
  v_price numeric(12,2);
  v_purprice numeric(12,2);
  v_saleprice numeric(12,2);
  v_hold_avgprice numeric(15,5);
  v_recentpurprice numeric(12,2);
  v_total_availablestock numeric(15,4);
  v_itemflatdisc numeric(10,2);
  v_discperc numeric(5,2);
  v_processcharge numeric(10,2);
  v_processchargeperc numeric(5,2);
  v_batch citext;
  v_itemname citext;
  v_autopost citext;
  v_accountfor citext;
  v_items_rows integer;
  v_counter integer;
  v_rowcount integer;
  v_totalrows integer;
  v_continue integer;
  v_err integer;
  v_rt_code integer;
  v_expiry timestamp(3);
  cur_cursor_items refcursor;
  cur_itembatch_cursor refcursor;
  _rc integer;
  _fs integer := -1;
BEGIN
  v_prodcode := prodcode;
  v_usercode := usercode;
  v_headerno := headerno;
  v_serverdate := serverdate;
  v_issueinvcode := issueinvcode;
  v_continue := 0;
  _rc := 1;
  v_deptcode := coalesce((SELECT issuedeptcode FROM dbo.prodheader WHERE (prodcode = v_prodcode)), 1);
  _rc := 1;
  v_areacode := 1;
  _rc := 1;
  v_module := (SELECT module FROM dbo.module WHERE ((lower(name))::citext = 'issue'));
  _rc := 1;
  v_pricetype := dbo.fn_get_int_preference('IssuePriceTypeCode');
  _rc := 1;
  v_groupcode := coalesce((SELECT min(groupcode) FROM dbo.usergroups WHERE (usercode = v_usercode)), 1);
  _rc := 1;
  v_category := 2;
  _rc := 1;
  v_accountfor := coalesce((SELECT accountfor FROM dbo.issuecategory WHERE (issuecategorycode = v_category)), 'N');
  _rc := 1;
  IF (v_accountfor = 'Y') THEN
    v_dracccode := trunc(coalesce((SELECT code FROM dbo.global WHERE (name = 'GT_WIPAcc')), 33))::smallint;
    _rc := 1;
  ELSE
    v_dracccode := NULL;
    _rc := 1;
  END IF;
  v_autopost := dbo.fn_getpreference('AutoPostIssueOnProdPost');
  _rc := 1;
  IF (v_autopost IS NULL) THEN
    v_autopost := 'Y';
    _rc := 1;
  END IF;
  IF (v_groupcode > 0) THEN
    v_issuegodownstrategy := coalesce((SELECT issuegodownstrategy FROM dbo.groups WHERE (groupcode = v_groupcode)), 1);
    _rc := 1;
  ELSE
    v_issuegodownstrategy := 1;
    _rc := 1;
  END IF;
  IF (v_issuegodownstrategy = 1) THEN
    v_gcode := (SELECT issuegcode FROM dbo.prodheader WHERE (prodcode = v_prodcode));
    _rc := 1;
  END IF;
  OPEN cur_cursor_items FOR SELECT rd.icode, sum(rd.qty) AS qty, max(i.packunits) AS packunits, round(((max(i.purprice) / max(i.packunits)))::numeric, 2) AS purprice, round(((max(i.saleprice) / max(i.packunits)))::numeric, 2) AS saleprice, round(((max(i.recentpurprice) / max(i.packunits)))::numeric, 2) AS recentpurprice, rd.price AS price, rd.itemflatdisc, rd.discperc, rd.processcharge, rd.processchargeperc, rd.prodrowid, rd.rowid FROM (SELECT icode, qty, rowid FROM dbo.proddetail WHERE (proddetail.prodcode = v_prodcode)) AS pd, (SELECT r1.* FROM dbo.recipe AS r1 WHERE (((dbo.tsql_str((r1.resulteditem)::numeric, 7) || dbo.tsql_str((r1.priority)::numeric, 7)))::citext IN (SELECT DISTINCT (dbo.tsql_str((rr.resulteditem)::numeric, 7) || dbo.tsql_str((min(rr.priority))::numeric, 7)) FROM dbo.recipe AS rr WHERE (rr.resulteditem IN (SELECT DISTINCT d.icode FROM dbo.prodheader AS p, dbo.proddetail AS d WHERE ((p.prodcode = v_prodcode) AND (p.prodcode = d.prodcode)))) GROUP BY rr.resulteditem))) AS r, dbo.prodbuffer AS rd, dbo.item AS i WHERE ((((pd.icode = r.resulteditem) AND (rd.prodcode = v_prodcode)) AND (pd.rowid = rd.prodrowid)) AND (rd.icode = i.icode)) GROUP BY rd.prodrowid, rd.icode, rd.price, rd.rowid, rd.itemflatdisc, rd.discperc, rd.processcharge, rd.processchargeperc ORDER BY rd.rowid;
  v_items_rows := (-1);
  _rc := 1;
  IF (v_items_rows > 0) THEN
    SELECT r.return_value, r.key INTO v_rt_code, v_code FROM dbo.sp_gettabmaxkey(tabname => 'IssueHeader', key => v_code) AS r;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      v_continue := -1;
      _rc := 1;
    ELSE
      v_issueinvcode := v_code;
      _rc := 1;
      SELECT r.return_value, r.key INTO v_rt_code, v_headerinvno FROM dbo.sp_getheadertabmaxkey(headercode => (v_headerno)::smallint, modulecode => v_module, key => v_headerinvno) AS r;
      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
        v_continue := -1;
        _rc := 1;
      ELSE
        v_issuecode := NULL;
        _rc := 1;
        SELECT r.return_value, r.counter INTO v_rt_code, v_issuecode FROM dbo.sp_getissuecategorycounter(category => v_category, counter => v_issuecode) AS r;
        IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
          v_continue := -1;
          _rc := 1;
        ELSE
          INSERT INTO dbo.issueheader (issueinvcode, deptcode, date, originaldate, salesmancode, posted, postdate, postedby, areacode, headerno, headerinvno, pricetypecode, remarks, issuecategorycode, accountfor, dracccode, issuecode) VALUES (v_code, v_deptcode, v_serverdate, v_serverdate, v_usercode, v_autopost, v_serverdate, v_usercode, v_areacode, v_headerno, v_headerinvno, v_pricetype, 'SYSTEM GENERATED ISSUE', v_category, v_accountfor, v_dracccode, v_issuecode);
          GET DIAGNOSTICS _rc = ROW_COUNT;
          v_err := 0;
          v_rowcount := _rc;
          _rc := 1;
          IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
            RAISE EXCEPTION 'Error occured in inserting record into Issue Header : %', v_code;
            v_continue := -1;
            _rc := 1;
          ELSE
            FETCH NEXT FROM cur_cursor_items INTO v_icode, v_givenqty, v_packunits, v_purprice, v_saleprice, v_recentpurprice, v_price, v_itemflatdisc, v_discperc, v_processcharge, v_processchargeperc, v_prodrowid, v_rowid;
            IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
            WHILE ((_fs = 0) AND (v_continue >= 0)) LOOP
              IF (v_issuegodownstrategy = 2) THEN
                v_gcode := coalesce((SELECT gcode FROM dbo.item WHERE (icode = v_icode)), 1);
                _rc := 1;
              END IF;
              v_price := ((((((v_price - v_itemflatdisc)) * ((1 - (v_discperc * 0.01))))) + v_processcharge) + ((((((v_price - v_itemflatdisc)) * ((1 - (v_discperc * 0.01)))) * v_processchargeperc) * 0.01)));
              _rc := 1;
              SELECT r.return_value, r.avgprice INTO v_rt_code, v_hold_avgprice FROM dbo.sp_getitemavgprice(icode => v_icode, avgprice => v_hold_avgprice) AS r;
              IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                v_continue := -1;
                _rc := 1;
              ELSE
                v_packunits := CASE WHEN (v_packunits IS NULL) THEN 1 WHEN (v_packunits = 0) THEN 1 ELSE v_packunits END;
                _rc := 1;
                v_totalqty := (SELECT coalesce(sum(currqty), 0) FROM dbo.godowndetail WHERE ((godowndetail.gcode = v_gcode) AND (godowndetail.icode = v_icode)));
                _rc := 1;
                IF (v_totalqty >= v_givenqty) THEN
                  v_total_availablestock := (SELECT coalesce(sum(currqty), 0) FROM dbo.godowndetail WHERE (godowndetail.icode = v_icode));
                  _rc := 1;
                  IF ((v_total_availablestock < 0) OR (v_total_availablestock IS NULL)) THEN
                    v_total_availablestock := 0;
                    _rc := 1;
                  END IF;
                  v_reqqty := v_givenqty;
                  _rc := 1;
                  OPEN cur_itembatch_cursor FOR SELECT batch, expiry, currqty FROM dbo.godowndetail WHERE ((godowndetail.gcode = v_gcode) AND (godowndetail.icode = v_icode)) ORDER BY priority, expiry, currqty;
                  v_totalrows := (-1);
                  _rc := 1;
                  FETCH NEXT FROM cur_itembatch_cursor INTO v_batch, v_expiry, v_currqty;
                  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
                  v_counter := 1;
                  _rc := 1;
                  WHILE (((_fs = 0) AND (v_counter <= v_totalrows)) AND (v_reqqty > 0)) LOOP
                    v_batchqty := v_currqty;
                    _rc := 1;
                    IF (v_batchqty >= v_reqqty) THEN
                      v_delqty := v_reqqty;
                      _rc := 1;
                    ELSE
                      v_delqty := v_batchqty;
                      _rc := 1;
                    END IF;
                    v_reqqty := (v_reqqty - v_delqty);
                    _rc := 1;
                    SELECT r.return_value, r.lbi_maxutn INTO v_rt_code, v_utn FROM dbo.sp_maxutn(lbi_rows => (1)::bigint, lbi_maxutn => (v_utn)::bigint) AS r;
                    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                      v_continue := -1;
                      _rc := 1;
                    END IF;
                    v_total_availablestock := (v_total_availablestock - v_delqty);
                    _rc := 1;
                    INSERT INTO dbo.issuedetail (issueinvcode, gcode, icode, batch, expiry, qty, saleprice, purchaseprice, avgprice, packunits, mrpp, issueutn, price, balancestock) VALUES (v_code, v_gcode, v_icode, v_batch, v_expiry, v_delqty, v_saleprice, v_purprice, v_hold_avgprice, v_packunits, v_recentpurprice, v_utn, v_price, v_total_availablestock);
                    GET DIAGNOSTICS _rc = ROW_COUNT;
                    v_err := 0;
                    v_rowcount := _rc;
                    _rc := 1;
                    IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
                      RAISE EXCEPTION 'Error occured in inserting record into Issue Detail for Production : %', v_code;
                      v_continue := -1;
                      _rc := 1;
                    ELSE
                      v_newqty := (v_currqty - v_delqty);
                      _rc := 1;
                      IF (v_newqty > 0) THEN
                        SELECT r.return_value INTO v_rt_code FROM dbo.sp_saleupdateitemstockbatch(gcode => v_gcode, icode => v_icode, batch => v_batch, expiry => v_expiry, newqty => v_newqty, oldqty => v_currqty) AS r;
                      ELSE
                        SELECT r.return_value INTO v_rt_code FROM dbo.sp_deleteitemstockbatch(gcode => v_gcode, icode => v_icode, batch => v_batch, expiry => v_expiry, oldqty => v_delqty) AS r;
                      END IF;
                      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                        v_continue := -1;
                        _rc := 1;
                      END IF;
                    END IF;
                    v_counter := (v_counter + 1);
                    _rc := 1;
                    FETCH NEXT FROM cur_itembatch_cursor INTO v_batch, v_expiry, v_currqty;
                    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
                  END LOOP;
                  CLOSE cur_itembatch_cursor;
                  -- DEALLOCATE ItemBatch_Cursor
                ELSE
                  v_itemname := (SELECT name FROM dbo.item WHERE (icode = v_icode));
                  _rc := 1;
                  RAISE EXCEPTION 'Not enough stock for item (%) to decrease for Issue No. : %', v_itemname, v_code;
                  v_continue := -1;
                  _rc := 1;
                END IF;
              END IF;
              FETCH NEXT FROM cur_cursor_items INTO v_icode, v_givenqty, v_packunits, v_purprice, v_saleprice, v_recentpurprice, v_price, v_itemflatdisc, v_discperc, v_processcharge, v_processchargeperc, v_prodrowid, v_rowid;
              IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
            END LOOP;
          END IF;
        END IF;
      END IF;
    END IF;
  END IF;
  CLOSE cur_cursor_items;
  -- DEALLOCATE Cursor_Items
  IF (v_continue <> 0) THEN
    return_value := -1;
    issueinvcode := v_issueinvcode;
    RETURN;
  ELSE
    return_value := 0;
    issueinvcode := v_issueinvcode;
    RETURN;
  END IF;
  return_value := 0;
  issueinvcode := v_issueinvcode;
  RETURN;
END
$body$;

-- ==== proc sp_GenerateIssue_On_ProdunctionNote ====
CREATE OR REPLACE FUNCTION dbo.sp_generateissue_on_produnctionnote(prodnotecode integer, usercode integer, INOUT issueinvcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_prodnotecode integer;
  v_usercode integer;
  v_issueinvcode integer;
  v_code integer;
  v_deptcode integer;
  v_module smallint;
  v_utn integer;
  v_headerinvno integer;
  v_category smallint;
  v_issuecode integer;
  v_dracccode smallint;
  v_accountfor citext;
  v_issuetype smallint;
  v_pricetype smallint;
  v_headerno smallint;
  v_icode integer;
  v_gcode integer;
  v_packunits integer;
  v_areacode integer;
  v_prodrowid integer;
  v_rowid integer;
  v_totalpieces integer;
  v_piecesinhand integer;
  v_givenqty numeric(15,4);
  v_totalqty numeric(15,4);
  v_currqty numeric(15,4);
  v_delqty numeric(15,4);
  v_batchqty numeric(15,4);
  v_reqqty numeric(15,4);
  v_newqty numeric(15,4);
  v_total_availablestock numeric(15,4);
  v_price numeric(12,2);
  v_purprice numeric(12,2);
  v_saleprice numeric(12,2);
  v_hold_avgprice numeric(15,5);
  v_recentpurprice numeric(12,2);
  v_itemflatdisc numeric(10,2);
  v_discperc numeric(5,2);
  v_processcharge numeric(10,2);
  v_processchargeperc numeric(5,2);
  v_batch citext;
  v_itemname citext;
  v_errtext citext;
  v_items_rows integer;
  v_counter integer;
  v_rowcount integer;
  v_totalrows integer;
  v_continue integer;
  v_err integer;
  v_rt_code integer;
  v_expiry timestamp(3);
  v_serverdate timestamp(3);
  cur_cursor_items refcursor;
  cur_itembatch_cursor refcursor;
  _rc integer;
  _fs integer := -1;
BEGIN
  v_prodnotecode := prodnotecode;
  v_usercode := usercode;
  v_issueinvcode := issueinvcode;
  v_continue := 0;
  _rc := 1;
  v_deptcode := coalesce((SELECT issuedeptcode FROM dbo.prodnote WHERE (prodnotecode = v_prodnotecode)), 1);
  _rc := 1;
  v_headerno := 1;
  _rc := 1;
  v_areacode := 1;
  _rc := 1;
  v_module := (SELECT module FROM dbo.module WHERE ((lower(name))::citext = 'issue'));
  _rc := 1;
  v_pricetype := dbo.fn_get_int_preference('IssuePriceTypeCode');
  _rc := 1;
  v_serverdate := localtimestamp(3);
  _rc := 1;
  v_category := 2;
  _rc := 1;
  v_accountfor := coalesce((SELECT accountfor FROM dbo.issuecategory WHERE (issuecategorycode = v_category)), 'N');
  _rc := 1;
  IF (v_accountfor = 'Y') THEN
    v_dracccode := trunc(coalesce((SELECT code FROM dbo.global WHERE (name = 'GT_WIPAcc')), 33))::smallint;
    _rc := 1;
  ELSE
    v_dracccode := NULL;
    _rc := 1;
  END IF;
  OPEN cur_cursor_items FOR SELECT pni.icode, pni.gcode, sum(pni.qty) AS qty, sum(pni.totalpieces) AS totalpieces, pni.packunits, round(((max(i.purprice) / max(i.packunits)))::numeric, 2) AS purprice, round(((max(i.saleprice) / max(i.packunits)))::numeric, 2) AS saleprice, round(((max(i.recentpurprice) / max(i.packunits)))::numeric, 2) AS recentpurprice, CASE v_pricetype WHEN 1 THEN round(((max(i.saleprice) / max(i.packunits)))::numeric, 2) WHEN 2 THEN round(((max(i.saleprice2) / max(i.packunits)))::numeric, 2) WHEN 3 THEN round(((max(i.saleprice3) / max(i.packunits)))::numeric, 2) WHEN 4 THEN round(((max(i.purprice) / max(i.packunits)))::numeric, 2) WHEN 5 THEN round(((max(i.recentpurprice) / max(i.packunits)))::numeric, 2) WHEN 6 THEN round((max(i.avgprice))::numeric, 2) WHEN 7 THEN round(((max(i.saleprice4) / max(i.packunits)))::numeric, 2) WHEN 8 THEN round(((max(i.saleprice5) / max(i.packunits)))::numeric, 2) END AS price, pni.rowid FROM dbo.prodnoteissue AS pni, dbo.item AS i WHERE ((pni.prodnotecode = v_prodnotecode) AND (pni.icode = i.icode)) GROUP BY pni.rowid, pni.icode, pni.gcode, pni.packunits ORDER BY pni.rowid;
  v_items_rows := (-1);
  _rc := 1;
  IF (v_items_rows > 0) THEN
    SELECT r.return_value, r.key INTO v_rt_code, v_code FROM dbo.sp_gettabmaxkey(tabname => 'IssueHeader', key => v_code) AS r;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      v_continue := -1;
      _rc := 1;
    ELSE
      v_issueinvcode := v_code;
      _rc := 1;
      SELECT r.return_value, r.key INTO v_rt_code, v_headerinvno FROM dbo.sp_getheadertabmaxkey(headercode => v_headerno, modulecode => v_module, key => v_headerinvno) AS r;
      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
        v_continue := -1;
        _rc := 1;
      ELSE
        v_issuecode := NULL;
        _rc := 1;
        SELECT r.return_value, r.counter INTO v_rt_code, v_issuecode FROM dbo.sp_getissuecategorycounter(category => v_category, counter => v_issuecode) AS r;
        IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
          v_continue := -1;
          _rc := 1;
        ELSE
          INSERT INTO dbo.issueheader (issueinvcode, deptcode, date, originaldate, salesmancode, posted, postdate, postedby, areacode, headerno, headerinvno, pricetypecode, remarks, recipientcode, issuecategorycode, accountfor, dracccode, issuecode) VALUES (v_code, v_deptcode, v_serverdate, v_serverdate, v_usercode, 'Y', v_serverdate, v_usercode, v_areacode, v_headerno, v_headerinvno, v_pricetype, 'PRODUCTION NOTE BASED ISSUE', 1, v_category, v_accountfor, v_dracccode, v_issuecode);
          GET DIAGNOSTICS _rc = ROW_COUNT;
          v_err := 0;
          v_rowcount := _rc;
          _rc := 1;
          IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
            RAISE EXCEPTION 'Error occured in inserting record into Issue Header : %', v_code;
            v_continue := -1;
            _rc := 1;
          ELSE
            FETCH NEXT FROM cur_cursor_items INTO v_icode, v_gcode, v_givenqty, v_totalpieces, v_packunits, v_purprice, v_saleprice, v_recentpurprice, v_price, v_rowid;
            IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
            WHILE ((_fs = 0) AND (v_continue >= 0)) LOOP
              v_itemname := (SELECT name FROM dbo.item WHERE (icode = v_icode));
              _rc := 1;
              SELECT r.return_value, r.avgprice INTO v_rt_code, v_hold_avgprice FROM dbo.sp_getitemavgprice(icode => v_icode, avgprice => v_hold_avgprice) AS r;
              IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                v_errtext := ('Unable to aquire item lock for item = ' || v_itemname);
                _rc := 1;
                v_continue := -1;
                _rc := 1;
              ELSE
                SELECT r.return_value, r.qty INTO v_rt_code, v_piecesinhand FROM dbo.sp_getitemtotalpiecesinhand(icode => v_icode, qty => v_piecesinhand) AS r;
                IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                  v_errtext := ('Unable to fetch total pieces in hand for item = ' || v_itemname);
                  _rc := 1;
                  v_continue := -1;
                  _rc := 1;
                ELSE
                  IF (v_totalpieces > v_piecesinhand) THEN
                    v_errtext := ('Total Pieces asked to issue are more than total pieces in hand for item = ' || v_itemname);
                    _rc := 1;
                    v_continue := -1;
                    _rc := 1;
                  ELSE
                    SELECT r.return_value INTO v_rt_code FROM dbo.sp_updateitemtotalpiecesinhand(icode => v_icode, incdec => -1, totalpieces => v_totalpieces) AS r;
                    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                      v_errtext := ('Error Updating pieces in hand for item = ' || v_itemname);
                      _rc := 1;
                      v_continue := -1;
                      _rc := 1;
                    END IF;
                  END IF;
                END IF;
              END IF;
              IF (v_continue >= 0) THEN
                v_total_availablestock := (SELECT coalesce(sum(currqty), 0) FROM dbo.godowndetail WHERE (godowndetail.icode = v_icode));
                _rc := 1;
                IF ((v_total_availablestock < 0) OR (v_total_availablestock IS NULL)) THEN
                  v_total_availablestock := 0;
                  _rc := 1;
                END IF;
                v_packunits := CASE WHEN (v_packunits IS NULL) THEN 1 WHEN (v_packunits = 0) THEN 1 ELSE v_packunits END;
                _rc := 1;
                v_totalqty := (SELECT coalesce(sum(currqty), 0) FROM dbo.godowndetail WHERE ((godowndetail.gcode = v_gcode) AND (godowndetail.icode = v_icode)));
                _rc := 1;
                IF (v_totalqty >= v_givenqty) THEN
                  v_reqqty := v_givenqty;
                  _rc := 1;
                  OPEN cur_itembatch_cursor FOR SELECT batch, expiry, currqty FROM dbo.godowndetail WHERE ((godowndetail.gcode = v_gcode) AND (godowndetail.icode = v_icode)) ORDER BY priority, expiry, currqty;
                  v_totalrows := (-1);
                  _rc := 1;
                  FETCH NEXT FROM cur_itembatch_cursor INTO v_batch, v_expiry, v_currqty;
                  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
                  v_counter := 1;
                  _rc := 1;
                  WHILE (((_fs = 0) AND (v_counter <= v_totalrows)) AND (v_reqqty > 0)) LOOP
                    v_batchqty := v_currqty;
                    _rc := 1;
                    IF (v_batchqty >= v_reqqty) THEN
                      v_delqty := v_reqqty;
                      _rc := 1;
                    ELSE
                      v_delqty := v_batchqty;
                      _rc := 1;
                    END IF;
                    v_reqqty := (v_reqqty - v_delqty);
                    _rc := 1;
                    SELECT r.return_value, r.lbi_maxutn INTO v_rt_code, v_utn FROM dbo.sp_maxutn(lbi_rows => (1)::bigint, lbi_maxutn => (v_utn)::bigint) AS r;
                    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                      v_continue := -1;
                      _rc := 1;
                    END IF;
                    v_total_availablestock := (v_total_availablestock - v_delqty);
                    _rc := 1;
                    INSERT INTO dbo.issuedetail (issueinvcode, gcode, icode, batch, expiry, qty, saleprice, purchaseprice, avgprice, packunits, mrpp, issueutn, price, totalpieces, piecesinhand, balancestock) VALUES (v_code, v_gcode, v_icode, v_batch, v_expiry, v_delqty, v_saleprice, v_purprice, v_hold_avgprice, v_packunits, v_recentpurprice, v_utn, v_price, v_totalpieces, v_piecesinhand, v_total_availablestock);
                    GET DIAGNOSTICS _rc = ROW_COUNT;
                    v_err := 0;
                    v_rowcount := _rc;
                    _rc := 1;
                    IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
                      RAISE EXCEPTION 'Error occured in inserting record into Issue Detail for Production : %', v_code;
                      v_continue := -1;
                      _rc := 1;
                    ELSE
                      v_newqty := (v_currqty - v_delqty);
                      _rc := 1;
                      IF (v_newqty > 0) THEN
                        SELECT r.return_value INTO v_rt_code FROM dbo.sp_saleupdateitemstockbatch(gcode => v_gcode, icode => v_icode, batch => v_batch, expiry => v_expiry, newqty => v_newqty, oldqty => v_currqty) AS r;
                      ELSE
                        SELECT r.return_value INTO v_rt_code FROM dbo.sp_deleteitemstockbatch(gcode => v_gcode, icode => v_icode, batch => v_batch, expiry => v_expiry, oldqty => v_delqty) AS r;
                      END IF;
                      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                        v_continue := -1;
                        _rc := 1;
                      END IF;
                    END IF;
                    v_counter := (v_counter + 1);
                    _rc := 1;
                    FETCH NEXT FROM cur_itembatch_cursor INTO v_batch, v_expiry, v_currqty;
                    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
                  END LOOP;
                  CLOSE cur_itembatch_cursor;
                  -- DEALLOCATE ItemBatch_Cursor
                ELSE
                  v_itemname := (SELECT name FROM dbo.item WHERE (icode = v_icode));
                  _rc := 1;
                  RAISE EXCEPTION 'Not enough stock for item (%) to decrease for Issue No. : %', v_itemname, v_code;
                  v_continue := -1;
                  _rc := 1;
                END IF;
              ELSE
                RAISE EXCEPTION '%', v_errtext;
                v_continue := -1;
                _rc := 1;
              END IF;
              FETCH NEXT FROM cur_cursor_items INTO v_icode, v_gcode, v_givenqty, v_totalpieces, v_packunits, v_purprice, v_saleprice, v_recentpurprice, v_price, v_rowid;
              IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
            END LOOP;
          END IF;
        END IF;
      END IF;
    END IF;
  END IF;
  CLOSE cur_cursor_items;
  -- DEALLOCATE Cursor_Items
  IF (v_continue <> 0) THEN
    return_value := -1;
    issueinvcode := v_issueinvcode;
    RETURN;
  ELSE
    return_value := 0;
    issueinvcode := v_issueinvcode;
    RETURN;
  END IF;
  return_value := 0;
  issueinvcode := v_issueinvcode;
  RETURN;
END
$body$;

-- ==== proc sp_GenerateItemLog_DataCarryDB ====
CREATE OR REPLACE FUNCTION dbo.sp_generateitemlog_datacarrydb(srv citext, db citext, owner citext, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_query citext;
  _dq1 text;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  -- SET NOCOUNT ON
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  v_query := ((((((('SELECT * INTO tmp_titem from ' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.') || 'item                     ');
  v_query := (v_query || 'Insert Into ItemLog ');
  v_query := (v_query || ' Select 	localtimestamp(3) AS TodayDate, i.saleprice, (SELECT COALESCE(sum(g.currqty),0) FROM godowndetail g WHERE g.icode=item.icode), item.* ');
  v_query := (v_query || ' from   	item , tmp_titem i ');
  v_query := ((((v_query || ' where  	item.icode = i.icode AND item.saleprice <> i.saleprice and not exists (select columnname from transferabledata_restrictedcolumns where tablename=') || '''item''') || ' and columnname=') || '''saleprice'')');
  _dq1 := v_query;
  IF _dq1 IS NOT NULL THEN
    IF _dq1 ~* '^[[:space:]]*select' THEN OPEN rs1 FOR EXECUTE dbo.tsql_dyn(_dq1); ELSE EXECUTE dbo.tsql_dyn(_dq1); END IF;
  END IF;
  IF (0 <> 0) THEN
    RAISE EXCEPTION 'Some Problem occur in generating ItemLog';
    return_value := -1;
    RETURN;
  END IF;
  return_value := 1;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_GenerateMarkedSaleFromTemplate ====
CREATE OR REPLACE FUNCTION dbo.sp_generatemarkedsalefromtemplate(saletemplatecode integer, usercode integer, machinename citext, INOUT sinvno integer, INOUT einvno integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_saletemplatecode integer;
  v_usercode integer;
  v_machinename citext;
  v_sinvno integer;
  v_einvno integer;
  v_module integer;
  v_custcode integer;
  v_saletypecode smallint;
  v_headerno smallint;
  v_headerinvno integer;
  v_continue integer;
  v_rt_code integer;
  v_err integer;
  v_totalrows integer;
  v_rowcount integer;
  v_invcounter integer;
  v_counter integer;
  v_outofstock integer;
  v_rowid integer;
  v_gcode smallint;
  v_salecatcode smallint;
  v_invcode integer;
  v_saleinvcode integer;
  v_oldinvcode integer;
  v_satisfiableqty integer;
  v_satisfiedqty integer;
  v_item_in_inv_exist integer;
  v_saleprice numeric(12,2);
  v_rate numeric(12,2);
  v_discperc numeric(5,2);
  v_itemflatdisc numeric(12,2);
  v_unitsalestax numeric(12,2);
  v_gstperc1 numeric(6,2);
  v_gstperc2 numeric(6,2);
  v_hold_avgprice numeric(15,5);
  v_icode integer;
  v_anyitem_exist integer;
  v_packunits integer;
  v_quantity numeric(15,4);
  v_bonusqty numeric(15,4);
  v_totalqty numeric(15,4);
  v_givenqty numeric(15,4);
  v_reqqty numeric(15,4);
  v_batchqty numeric(15,4);
  v_delqty numeric(15,4);
  v_currqty numeric(15,4);
  v_newqty numeric(15,4);
  v_total_availablestock numeric(15,4);
  v_batch citext;
  v_itemname citext;
  v_expiry timestamp(3);
  v_serverdate timestamp(3);
  v_remarks citext;
  v_saleutn bigint;
  v_firsttime smallint;
  v_saletemplate_rowcount integer;
  v_invdetail_exist integer;
  v_rowgroup integer;
  v_lineitems_rowcount integer;
  v_innercounter integer;
  _r1 record;
  _r2 record;
  cur_itembatch_cursor refcursor;
  _rc integer;
  _fs integer := -1;
BEGIN
  v_saletemplatecode := saletemplatecode;
  v_usercode := usercode;
  v_machinename := machinename;
  v_sinvno := sinvno;
  v_einvno := einvno;
  -- SET NOCOUNT ON
  v_outofstock := coalesce((SELECT count(t.icode) FROM (SELECT icode, sum((coalesce(looseqty, 0) + coalesce(bonusqty, 0))) AS qty, coalesce((SELECT sum(gd.currqty) FROM dbo.godowndetail AS gd WHERE (gd.icode = saletemplatedetail.icode)), 0) AS stock FROM dbo.saletemplatedetail WHERE (((saletemplatecode = v_saletemplatecode) AND (marked = 'Y')) AND (((looseqty + bonusqty)) > 0)) GROUP BY icode) AS t WHERE (t.qty > t.stock)), 0);
  _rc := 1;
  IF (v_outofstock > 0) THEN
    RAISE EXCEPTION 'Not Enough Stock exists for some items of sale template no. %', v_saletemplatecode;
    return_value := -1;
    sinvno := v_sinvno;
    einvno := v_einvno;
    RETURN;
  END IF;
  DROP TABLE IF EXISTS tmp_saletemp;
  CREATE TEMP TABLE tmp_saletemp (
    saleinvcode integer,
    salecatcode smallint,
    oldinvcode integer,
    saledate timestamp(3),
    custcode smallint,
    icode integer,
    looseqty numeric(15,4),
    bonusqty numeric(15,4),
    saleprice numeric(15,2),
    discperc numeric(5,2),
    itemflatdisc numeric(10,2),
    unitsalestax numeric(15,2),
    gstperc numeric(5,2),
    packunits integer,
    remarks citext,
    satisfiableqty numeric(15,4),
    satisfiedqty numeric(15,4),
    rowid integer GENERATED BY DEFAULT AS IDENTITY
) ON COMMIT DROP;
  INSERT INTO tmp_saletemp (saleinvcode, salecatcode, oldinvcode, saledate, custcode, icode, looseqty, bonusqty, saleprice, discperc, itemflatdisc, unitsalestax, gstperc, packunits, remarks, satisfiableqty, satisfiedqty) SELECT -1 AS saleinvcode, coalesce(salecatcode, 3), saleinvcode AS oldinvcode, saledate, custcode, icode, looseqty, bonusqty, saleprice, discperc, itemflatdisc, unitsalestax, gstperc, packunits, remarks, (looseqty + bonusqty) AS satisfiableqty, 0 AS satisfiedqty FROM dbo.saletemplatedetail WHERE (((saletemplatecode = v_saletemplatecode) AND (marked = 'Y')) AND (((looseqty + bonusqty)) > 0)) ORDER BY saleinvcode, rowid;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_saletypecode := 1;
  _rc := 1;
  v_module := (SELECT module FROM dbo.module WHERE (name = 'Sales'));
  _rc := 1;
  v_headerno := 1;
  _rc := 1;
  v_saletemplate_rowcount := coalesce((SELECT count(*) FROM tmp_saletemp AS saletemp), 0);
  _rc := 1;
  v_anyitem_exist := trunc(coalesce((SELECT sum((satisfiableqty - satisfiedqty)) FROM tmp_saletemp AS saletemp), 0))::integer;
  _rc := 1;
  v_continue := 0;
  _rc := 1;
  v_invcounter := 1;
  _rc := 1;
  v_rowgroup := 0;
  _rc := 1;
  v_rowid := 1;
  _rc := 1;
  WHILE ((v_anyitem_exist > 0) AND (v_continue >= 0)) LOOP
    v_custcode := coalesce((SELECT custcode FROM tmp_saletemp AS saletemp WHERE (rowid = v_rowid)), 19);
    _rc := 1;
    v_serverdate := coalesce((SELECT saledate FROM tmp_saletemp AS saletemp WHERE (rowid = v_rowid)), localtimestamp(3));
    _rc := 1;
    v_oldinvcode := (SELECT oldinvcode FROM tmp_saletemp AS saletemp WHERE (rowid = v_rowid));
    _rc := 1;
    v_invcode := (SELECT saleinvcode FROM tmp_saletemp AS saletemp WHERE (rowid = v_rowid));
    _rc := 1;
    v_saleinvcode := coalesce((SELECT max(saleinvcode) FROM tmp_saletemp AS saletemp WHERE (oldinvcode = v_oldinvcode)), -1);
    _rc := 1;
    v_salecatcode := coalesce((SELECT salecatcode FROM tmp_saletemp AS saletemp WHERE (rowid = v_rowid)), 3);
    _rc := 1;
    v_remarks := coalesce((SELECT remarks FROM tmp_saletemp AS saletemp WHERE (rowid = v_rowid)), '');
    _rc := 1;
    v_rowgroup := 0;
    _rc := 1;
    IF ((v_invcode = -1) AND (v_saleinvcode = -1)) THEN
      SELECT r.return_value, r.key INTO v_rt_code, v_saleinvcode FROM dbo.sp_gettabmaxkey(tabname => 'Saleledger', key => v_saleinvcode) AS r;
      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
        v_continue := -1;
        _rc := 1;
      END IF;
      IF (v_continue >= 0) THEN
        SELECT r.return_value, r.key INTO v_rt_code, v_headerinvno FROM dbo.sp_getheadertabmaxkey(headercode => v_headerno, modulecode => (v_module)::smallint, key => v_headerinvno) AS r;
        IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
          v_continue := -1;
          _rc := 1;
        END IF;
      END IF;
      IF (v_continue >= 0) THEN
        INSERT INTO dbo.saleledger (saleinvcode, salecatcode, custcode, sprice, salesmancode, date, discperc, flatdisc, misccharges, salestax, posted, postdate, headerno, headerinvno, originaldate, invtotal, machinename, modifycounter, billingdate, saletypecode, remarks, custrefno) VALUES (v_saleinvcode, v_salecatcode, v_custcode, 1, v_usercode, v_serverdate, 0, 0, 0, 0, 'N', v_serverdate, v_headerno, v_headerinvno, v_serverdate, 0, v_machinename, 0, v_serverdate, v_saletypecode, v_remarks, v_oldinvcode);
        GET DIAGNOSTICS _rc = ROW_COUNT;
        v_err := 0;
        v_rowcount := _rc;
        _rc := 1;
        IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
          RAISE EXCEPTION 'Error occured in inserting record into Sale Ledger : %', v_saleinvcode;
          v_continue := -1;
          _rc := 1;
        END IF;
      END IF;
    END IF;
    IF (v_continue >= 0) THEN
      v_anyitem_exist := trunc(coalesce((SELECT sum((satisfiableqty - satisfiedqty)) FROM tmp_saletemp AS saletemp), 0))::integer;
      _rc := 1;
      IF (v_oldinvcode > 0) THEN
        v_lineitems_rowcount := coalesce((SELECT count(*) FROM tmp_saletemp AS saletemp WHERE ((oldinvcode = v_oldinvcode) AND ((satisfiableqty - satisfiedqty) > 0))), 1);
        _rc := 1;
      ELSE
        v_lineitems_rowcount := coalesce((SELECT count(*) FROM tmp_saletemp AS saletemp WHERE ((oldinvcode IS NULL) AND ((satisfiableqty - satisfiedqty) > 0))), 1);
        _rc := 1;
      END IF;
      v_innercounter := 1;
      _rc := 1;
      WHILE ((((v_anyitem_exist > 0)) AND ((v_innercounter <= v_lineitems_rowcount))) AND ((v_continue >= 0))) LOOP
        _rc := 0;
        FOR _r1 IN SELECT icode AS c1, looseqty AS c2, bonusqty AS c3, satisfiableqty AS c4, satisfiedqty AS c5, saleprice AS c6, discperc AS c7, itemflatdisc AS c8, unitsalestax AS c9, gstperc AS c10 FROM tmp_saletemp AS saletemp WHERE (rowid = v_rowid) LOOP
          _rc := _rc + 1;
          v_icode := _r1.c1;
          v_quantity := _r1.c2;
          v_bonusqty := _r1.c3;
          v_satisfiableqty := _r1.c4;
          v_satisfiedqty := _r1.c5;
          v_saleprice := _r1.c6;
          v_discperc := _r1.c7;
          v_itemflatdisc := _r1.c8;
          v_unitsalestax := _r1.c9;
          v_gstperc1 := _r1.c10;
        END LOOP;
        v_rowcount := _rc;
        _rc := 1;
        IF (((v_rowcount > 0)) AND ((((v_satisfiableqty - v_satisfiedqty)) > 0))) THEN
          IF ((((v_quantity + v_bonusqty) + v_satisfiedqty)) <= v_satisfiableqty) THEN
            v_givenqty := (v_quantity + v_bonusqty);
            _rc := 1;
          ELSE
            v_givenqty := (v_satisfiableqty - v_satisfiedqty);
            _rc := 1;
          END IF;
          IF (v_givenqty <= 0) THEN
            v_givenqty := 1;
            _rc := 1;
          ELSE
            UPDATE tmp_saletemp AS saletemp SET satisfiedqty = (v_satisfiedqty + v_givenqty) WHERE ((icode = v_icode) AND (rowid = v_rowid));
            GET DIAGNOSTICS _rc = ROW_COUNT;
          END IF;
          SELECT r.return_value, r.avgprice INTO v_rt_code, v_hold_avgprice FROM dbo.sp_getitemavgprice(icode => v_icode, avgprice => v_hold_avgprice) AS r;
          IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
            v_continue := -1;
            _rc := 1;
          ELSE
            v_total_availablestock := (SELECT coalesce(sum(currqty), 0) FROM dbo.godowndetail WHERE (godowndetail.icode = v_icode));
            _rc := 1;
            IF ((v_total_availablestock < 0) OR (v_total_availablestock IS NULL)) THEN
              v_total_availablestock := 0;
              _rc := 1;
            END IF;
            v_totalqty := (SELECT coalesce(sum(currqty), 0) FROM dbo.godowndetail WHERE (godowndetail.icode = v_icode));
            _rc := 1;
            IF (v_totalqty >= v_givenqty) THEN
              v_rowgroup := (v_rowgroup + 1);
              _rc := 1;
              _rc := 0;
              FOR _r2 IN SELECT saleprice AS c1, packunits AS c2 FROM dbo.item WHERE (icode = v_icode) LOOP
                _rc := _rc + 1;
                v_rate := _r2.c1;
                v_packunits := _r2.c2;
              END LOOP;
              IF ((v_packunits = 0) OR (v_packunits IS NULL)) THEN
                v_packunits := 1;
                _rc := 1;
              END IF;
              v_reqqty := v_givenqty;
              _rc := 1;
              OPEN cur_itembatch_cursor FOR SELECT gcode, batch, expiry, currqty FROM dbo.godowndetail WHERE (godowndetail.icode = v_icode) ORDER BY gcode, priority, expiry, currqty;
              v_totalrows := (-1);
              _rc := 1;
              FETCH NEXT FROM cur_itembatch_cursor INTO v_gcode, v_batch, v_expiry, v_currqty;
              IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
              v_counter := 1;
              _rc := 1;
              WHILE (((_fs = 0) AND (v_counter <= v_totalrows)) AND (v_reqqty > 0)) LOOP
                v_batchqty := v_currqty;
                _rc := 1;
                IF (v_batchqty >= v_reqqty) THEN
                  v_delqty := v_reqqty;
                  _rc := 1;
                ELSE
                  v_delqty := v_batchqty;
                  _rc := 1;
                END IF;
                v_reqqty := (v_reqqty - v_delqty);
                _rc := 1;
                IF (v_delqty >= v_quantity) THEN
                  v_quantity := v_quantity;
                  _rc := 1;
                  v_bonusqty := (v_delqty - v_quantity);
                  _rc := 1;
                  IF (v_bonusqty < 0) THEN
                    v_bonusqty := 0;
                    _rc := 1;
                  END IF;
                ELSE
                  v_quantity := (v_quantity - v_delqty);
                  _rc := 1;
                  IF (v_quantity < 0) THEN
                    v_quantity := 0;
                    _rc := 1;
                  END IF;
                  v_bonusqty := 0;
                  _rc := 1;
                END IF;
                SELECT r.return_value, r.lbi_maxutn INTO v_rt_code, v_saleutn FROM dbo.sp_maxutn(lbi_rows => (1)::bigint, lbi_maxutn => v_saleutn) AS r;
                IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                  v_continue := -1;
                  _rc := 1;
                END IF;
                v_total_availablestock := ((v_total_availablestock - v_quantity) - v_bonusqty);
                _rc := 1;
                INSERT INTO dbo.saledetail (saleinvcode, icode, gcode, batch, expiry, packqty, looseqty, bonusqty, packunits, saleprice, avgprice, rate, discperc, salestax, itemflatdisc, packprice, unitsalestax, gstperc, saleutn, balancestock, rowgroup) VALUES (v_saleinvcode, v_icode, v_gcode, v_batch, v_expiry, 0, v_quantity, v_bonusqty, v_packunits, v_saleprice, v_hold_avgprice, (v_rate / v_packunits), v_discperc, 0, v_itemflatdisc, v_rate, v_unitsalestax, v_gstperc1, v_saleutn, v_total_availablestock, v_rowgroup);
                GET DIAGNOSTICS _rc = ROW_COUNT;
                v_err := 0;
                v_rowcount := _rc;
                _rc := 1;
                IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
                  RAISE EXCEPTION 'Error occured in inserting record into Sale Detail for Sale Inv. No. : %', v_saleinvcode;
                  v_continue := -1;
                  _rc := 1;
                ELSE
                  v_newqty := (v_currqty - v_delqty);
                  _rc := 1;
                  IF (v_newqty > 0) THEN
                    SELECT r.return_value INTO v_rt_code FROM dbo.sp_saleupdateitemstockbatch(gcode => (v_gcode)::integer, icode => v_icode, batch => v_batch, expiry => v_expiry, newqty => v_newqty, oldqty => v_currqty) AS r;
                  ELSE
                    SELECT r.return_value INTO v_rt_code FROM dbo.sp_deleteitemstockbatch(gcode => (v_gcode)::integer, icode => v_icode, batch => v_batch, expiry => v_expiry, oldqty => v_delqty) AS r;
                  END IF;
                  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                    v_continue := -1;
                    _rc := 1;
                  END IF;
                END IF;
                v_counter := (v_counter + 1);
                _rc := 1;
                FETCH NEXT FROM cur_itembatch_cursor INTO v_gcode, v_batch, v_expiry, v_currqty;
                IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
              END LOOP;
              CLOSE cur_itembatch_cursor;
              -- DEALLOCATE ItemBatch_Cursor
            ELSE
              v_itemname := (SELECT name FROM dbo.item WHERE (icode = v_icode));
              _rc := 1;
              RAISE EXCEPTION 'Not enough stock for item (%) to decrease for Sale Inv. No : %', v_itemname, v_saleinvcode;
              v_continue := -1;
              _rc := 1;
            END IF;
          END IF;
        END IF;
        v_innercounter := (v_innercounter + 1);
        _rc := 1;
        v_anyitem_exist := trunc(coalesce((SELECT sum((satisfiableqty - satisfiedqty)) FROM tmp_saletemp AS saletemp), 0))::integer;
        _rc := 1;
      END LOOP;
    END IF;
    IF (v_oldinvcode > 0) THEN
      UPDATE tmp_saletemp AS saletemp SET saleinvcode = v_saleinvcode WHERE ((oldinvcode = v_oldinvcode) AND (rowid = v_rowid));
      GET DIAGNOSTICS _rc = ROW_COUNT;
    ELSE
      UPDATE tmp_saletemp AS saletemp SET saleinvcode = v_saleinvcode WHERE (rowid = v_rowid);
      GET DIAGNOSTICS _rc = ROW_COUNT;
    END IF;
    v_rowid := (v_rowid + 1);
    _rc := 1;
    v_anyitem_exist := trunc(coalesce((SELECT sum((satisfiableqty - satisfiedqty)) FROM tmp_saletemp AS saletemp), 0))::integer;
    _rc := 1;
  END LOOP;
  IF ((v_continue >= 0)) THEN
    v_sinvno := (SELECT min(saleinvcode) FROM tmp_saletemp AS saletemp);
    _rc := 1;
    v_einvno := (SELECT max(saleinvcode) FROM tmp_saletemp AS saletemp);
    _rc := 1;
    UPDATE dbo.saleledger SET invtotal = dbo.fn_getsaleinvtotal((saleledger.saleinvcode)::integer) WHERE (saleinvcode BETWEEN v_sinvno AND v_einvno);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_err := 0;
    v_rowcount := _rc;
    _rc := 1;
    IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
      RAISE EXCEPTION 'Unable to update SaleInvoices for Sale Inv. total';
      v_continue := -1;
      _rc := 1;
    END IF;
  END IF;
  return_value := v_continue;
  sinvno := v_sinvno;
  einvno := v_einvno;
  RETURN;
  return_value := 0;
  sinvno := v_sinvno;
  einvno := v_einvno;
  RETURN;
END
$body$;

-- ==== proc sp_GeneratePayroll ====
CREATE OR REPLACE FUNCTION dbo.sp_generatepayroll(type integer, empcategory citext, empdept citext, startdate timestamp, enddate timestamp, usercode integer, INOUT payslipsgenerated integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_type integer;
  v_empcategory citext;
  v_empdept citext;
  v_startdate timestamp(3);
  v_enddate timestamp(3);
  v_usercode integer;
  v_payslipsgenerated integer;
  v_startcode integer;
  v_endcode integer;
  v_rowid integer;
  v_paysliprows integer;
  v_rowcount integer;
  v_totalrows integer;
  v_continue integer;
  v_err integer;
  v_rt_code integer;
BEGIN
  v_type := type;
  v_empcategory := empcategory;
  v_empdept := empdept;
  v_startdate := startdate;
  v_enddate := enddate;
  v_usercode := usercode;
  v_payslipsgenerated := payslipsgenerated;
  DROP TABLE IF EXISTS tv_sp_generatepayroll_tab_empcategory;
  CREATE TEMP TABLE tv_sp_generatepayroll_tab_empcategory (
    code integer NOT NULL
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tv_sp_generatepayroll_tab_empdept;
  CREATE TEMP TABLE tv_sp_generatepayroll_tab_empdept (
    code integer NOT NULL
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_temppay;
  CREATE TEMP TABLE tmp_temppay (
    payrollcode integer,
    empcode integer,
    workdays numeric(6,2),
    presents numeric(6,2),
    absents numeric(6,2),
    leaves numeric(6,2),
    perhourrate numeric(12,2),
    basicpay numeric(12,2),
    overtimehours numeric(12,2),
    overtimerate numeric(12,2),
    overtime numeric(12,2),
    bonuspay numeric(12,2),
    specialpay numeric(12,2),
    additionalpay numeric(12,2),
    otherpay numeric(12,2),
    fine numeric(12,2),
    penalty numeric(12,2),
    othercharge numeric(12,2),
    advance numeric(12,2),
    netpayable numeric(12,2),
    sundays numeric(6,2),
    holidays numeric(6,2),
    advacccode integer,
    paytype integer,
    hoursworked numeric(10,4),
    allowances numeric(12,2),
    deductions numeric(12,2)
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_temppay2;
  CREATE TEMP TABLE tmp_temppay2 (
    payrollcode integer,
    empcode integer,
    workdays numeric(6,2),
    presents numeric(6,2),
    absents numeric(6,2),
    leaves numeric(6,2),
    perhourrate numeric(12,2),
    basicpay numeric(12,2),
    overtimehours numeric(12,2),
    overtimerate numeric(12,2),
    overtime numeric(12,2),
    bonuspay numeric(12,2),
    specialpay numeric(12,2),
    additionalpay numeric(12,2),
    otherpay numeric(12,2),
    fine numeric(12,2),
    penalty numeric(12,2),
    othercharge numeric(12,2),
    advance numeric(12,2),
    netpayable numeric(12,2),
    sundays numeric(6,2),
    holidays numeric(6,2),
    advacccode integer,
    paytype integer,
    hoursworked numeric(10,4),
    allowances numeric(12,2),
    deductions numeric(12,2),
    rowid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL
) ON COMMIT DROP;
  INSERT INTO tv_sp_generatepayroll_tab_empcategory SELECT code FROM dbo.udf_stringtotabl(v_empcategory, ',') AS udf_stringtotabl;
  INSERT INTO tv_sp_generatepayroll_tab_empdept SELECT code FROM dbo.udf_stringtotabl(v_empdept, ',') AS udf_stringtotabl;
  v_startcode := 0;
  SELECT r.return_value, r.key INTO v_rt_code, v_startcode FROM dbo.sp_locktabmaxkey(tabname => 'EMP_Payroll', key => v_startcode) AS r;
  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
    RAISE EXCEPTION 'Error occured in aquiring latest payslip code';
    return_value := -1;
    payslipsgenerated := v_payslipsgenerated;
    RETURN;
  END IF;
  IF (v_type = 1) THEN
    INSERT INTO tmp_temppay (payrollcode, empcode, workdays, presents, absents, leaves, perhourrate, basicpay, overtimehours, overtimerate, overtime, bonuspay, specialpay, additionalpay, otherpay, fine, penalty, othercharge, advance, netpayable, sundays, holidays, advacccode, paytype, hoursworked) SELECT v_startcode AS payrollcode, e.empcode, 0 AS workdays, coalesce(t.presents, 0) AS presents, coalesce(t.absents, 0) AS absents, coalesce(t.leaves, 0) AS leaves, p.perhourrate AS perhourrate, coalesce((CASE WHEN (p.overtime = 'Y') THEN CASE WHEN (t.hoursworked > ((p.workinghours * p.payfrequencyfactor))) THEN ((p.workinghours * p.payfrequencyfactor)) ELSE t.hoursworked END ELSE t.hoursworked END * p.perhourrate), 0) AS basicpay, coalesce(t.overtimehrs, 0) AS overtimehours, p.overtimerate AS overtimerate, coalesce(CASE WHEN (p.overtime = 'Y') THEN (t.overtimehrs * p.overtimerate) ELSE 0 END, 0) AS overtime, 0 AS bonuspay, 0 AS specialpay, 0 AS additionalpay, 0 AS otherpay, 0 AS fine, 0 AS penalty, 0 AS othercharge, coalesce((SELECT CASE WHEN (t.adv_acc_balance <> t.balance) THEN CASE WHEN (t.adv_acc_balance >= t.installment) THEN t.installment ELSE t.adv_acc_balance END ELSE CASE WHEN (t.balance >= t.installment) THEN t.installment ELSE t.adv_acc_balance END END AS advance FROM (SELECT ea.empadvacccode, sum(ea.amount) AS amount, sum(ea.returnedamt) AS returnedamt, (sum(ea.amount) - sum(ea.returnedamt)) AS balance, sum(ea.installment) AS installment, coalesce((SELECT sum((v.debit - v.credit)) AS balance FROM dbo.virtualgl AS v WHERE (acccode = ea.empadvacccode)), 0) AS adv_acc_balance FROM dbo.emp_advance AS ea WHERE ((ea.amount - ea.returnedamt) > 0) GROUP BY ea.empadvacccode) AS t WHERE (t.empadvacccode = e.advacccode)), 0) AS advance, 0 AS netpayable, coalesce(t.sundays, 0) AS sundays, coalesce(t.holidays, 0) AS holidays, e.advacccode, p.paytype, coalesce(t.totaltime, 0) AS hoursworked FROM dbo.emp_employee AS e, dbo.emp_pay AS p, dbo.emp_category AS c, dbo.emp_department AS d, (SELECT ea.empcode, sum(CASE WHEN (ea.attendancestatuscode = 1) THEN 1 WHEN ((((ea.attendancestatuscode = 4) OR (ea.attendancestatuscode = 5)) OR (ea.attendancestatuscode = 6)) OR (ea.attendancestatuscode = 10)) THEN 0.5 ELSE 0 END) AS presents, sum(CASE WHEN ((ea.attendancestatuscode = 2) OR (ea.attendancestatuscode = 12)) THEN 1 ELSE 0 END) AS absents, sum(CASE WHEN ((ea.attendancestatuscode = 11) OR (ea.attendancestatuscode = 3)) THEN 1 WHEN ((((ea.attendancestatuscode = 5) OR (ea.attendancestatuscode = 6)) OR (ea.attendancestatuscode = 7)) OR (ea.attendancestatuscode = 8)) THEN 0.5 ELSE 0 END) AS leaves, CASE WHEN (e.sundayspaid = 'Y') THEN coalesce(dbo.udf_count_dayofweek(v_startdate, v_enddate, 'Sunday'), 0) ELSE 0 END AS sundays, CASE WHEN (e.holidayspaid = 'Y') THEN coalesce((SELECT count(eh.date) FROM dbo.emp_holiday AS eh WHERE (eh.date BETWEEN v_startdate AND v_enddate)), 0) ELSE 0 END AS holidays, CASE WHEN (e.overtime = 'N') THEN 0 ELSE CASE WHEN (((sum(dbo.tsql_datediff('minute', ea.timein, coalesce(ea.timeout, localtimestamp(3)))) / 60.0000)) > ((e.workinghours * e.payfrequencyfactor))) THEN (((sum(dbo.tsql_datediff('minute', ea.timein, coalesce(ea.timeout, localtimestamp(3)))) / 60.0000)) - ((e.workinghours * e.payfrequencyfactor))) ELSE 0 END END AS overtimehrs, ((sum(dbo.tsql_datediff('minute', ea.timein, coalesce(ea.timeout, localtimestamp(3)))) / 60.0000))::numeric(12,4) AS hoursworked, ((((sum(dbo.tsql_datediff('minute', ea.timein, coalesce(ea.timeout, localtimestamp(3)))) / 60)) % 60))::integer AS minworked, (((sum(dbo.tsql_datediff('minute', ea.timein, coalesce(ea.timeout, localtimestamp(3)))) / 60.0000))::numeric(12,4) + ((((((sum(dbo.tsql_datediff('minute', ea.timein, coalesce(ea.timeout, localtimestamp(3)))) / 60)) % 60))::integer / 60.0000))) AS totaltime FROM dbo.emp_attendance AS ea, (SELECT ee.empcode, ee.deptcode, ee.empcatcode, ep.overtime, ep.workinghours, ep.workingweekdays, ep.perhourrate, ep.sundayspaid, ep.holidayspaid, ep.payfrequencyfactor FROM dbo.emp_employee AS ee LEFT JOIN dbo.emp_pay AS ep ON ((ee.empcode = ep.empcode))) AS e WHERE (((((e.empcode = ea.empcode) AND (ea.timein IS NOT NULL)) AND (ea.timeout IS NOT NULL)) AND (ea.timein >= v_startdate)) AND (ea.timein <= v_enddate)) GROUP BY ea.empcode, e.overtime, e.workinghours, e.workingweekdays, e.sundayspaid, e.holidayspaid, e.payfrequencyfactor) AS t WHERE ((((((((c.empcatcode IN (SELECT code FROM tv_sp_generatepayroll_tab_empcategory AS tab_empcategory)) AND (d.deptcode IN (SELECT code FROM tv_sp_generatepayroll_tab_empdept AS tab_empdept))) AND (e.active = 'Y')) AND (e.empcatcode = c.empcatcode)) AND (e.deptcode = d.deptcode)) AND (e.empcode = p.empcode)) AND (e.empcode = t.empcode)) AND (e.acccode IN (SELECT a.acccode FROM dbo.accounts AS a WHERE (a.active = 'Y')))) UNION SELECT v_startcode AS payrollcode, e.empcode, 0 AS workdays, 0 AS presents, 0 AS absents, 0 AS leaves, p.perhourrate AS perhourrate, coalesce(p.basicpay, 0) AS basicpay, 0 AS overtimehours, p.overtimerate AS overtimerate, 0 AS overtime, 0 AS bonuspay, 0 AS specialpay, 0 AS additionalpay, 0 AS otherpay, 0 AS fine, 0 AS penalty, 0 AS othercharge, coalesce((SELECT CASE WHEN (t.adv_acc_balance <> t.balance) THEN CASE WHEN (t.adv_acc_balance >= t.installment) THEN t.installment ELSE t.adv_acc_balance END ELSE CASE WHEN (t.balance >= t.installment) THEN t.installment ELSE t.adv_acc_balance END END AS advance FROM (SELECT ea.empadvacccode, sum(ea.amount) AS amount, sum(ea.returnedamt) AS returnedamt, (sum(ea.amount) - sum(ea.returnedamt)) AS balance, sum(ea.installment) AS installment, coalesce((SELECT sum((v.debit - v.credit)) AS balance FROM dbo.virtualgl AS v WHERE (acccode = ea.empadvacccode)), 0) AS adv_acc_balance FROM dbo.emp_advance AS ea WHERE ((ea.amount - ea.returnedamt) > 0) GROUP BY ea.empadvacccode) AS t WHERE (t.empadvacccode = e.advacccode)), 0) AS advance, 0 AS netpayable, 0 AS sundays, 0 AS holidays, e.advacccode, p.paytype, 0 AS hoursworked FROM dbo.emp_employee AS e, dbo.emp_pay AS p, dbo.emp_category AS c, dbo.emp_department AS d WHERE ((((((((c.empcatcode IN (SELECT code FROM tv_sp_generatepayroll_tab_empcategory AS tab_empcategory)) AND (d.deptcode IN (SELECT code FROM tv_sp_generatepayroll_tab_empdept AS tab_empdept))) AND (e.active = 'Y')) AND (e.empcatcode = c.empcatcode)) AND (e.deptcode = d.deptcode)) AND (e.empcode = p.empcode)) AND (e.empcode NOT IN (SELECT ea.empcode FROM dbo.emp_attendance AS ea WHERE ((((ea.timein IS NOT NULL) AND (ea.timeout IS NOT NULL)) AND (ea.timein >= v_startdate)) AND (ea.timein <= v_enddate))))) AND (e.acccode IN (SELECT a.acccode FROM dbo.accounts AS a WHERE (a.active = 'Y'))));
  ELSE
    INSERT INTO tmp_temppay (payrollcode, empcode, workdays, presents, absents, leaves, perhourrate, basicpay, overtimehours, overtimerate, overtime, bonuspay, specialpay, additionalpay, otherpay, fine, penalty, othercharge, advance, netpayable, sundays, holidays, advacccode, paytype, hoursworked) SELECT v_startcode AS payrollcode, e.empcode, 0 AS workdays, 0 AS presents, 0 AS absents, 0 AS leaves, p.perhourrate AS perhourrate, coalesce(p.basicpay, 0) AS basicpay, 0 AS overtimehours, p.overtimerate AS overtimerate, 0 AS overtime, 0 AS bonuspay, 0 AS specialpay, 0 AS additionalpay, 0 AS otherpay, 0 AS fine, 0 AS penalty, 0 AS othercharge, coalesce((SELECT CASE WHEN (t.adv_acc_balance <> t.balance) THEN CASE WHEN (t.adv_acc_balance >= t.installment) THEN t.installment ELSE t.adv_acc_balance END ELSE CASE WHEN (t.balance >= t.installment) THEN t.installment ELSE t.adv_acc_balance END END AS advance FROM (SELECT ea.empadvacccode, sum(ea.amount) AS amount, sum(ea.returnedamt) AS returnedamt, (sum(ea.amount) - sum(ea.returnedamt)) AS balance, sum(ea.installment) AS installment, coalesce((SELECT sum((v.debit - v.credit)) AS balance FROM dbo.virtualgl AS v WHERE (acccode = ea.empadvacccode)), 0) AS adv_acc_balance FROM dbo.emp_advance AS ea WHERE ((ea.amount - ea.returnedamt) > 0) GROUP BY ea.empadvacccode) AS t WHERE (t.empadvacccode = e.advacccode)), 0) AS advance, 0 AS netpayable, 0 AS sundays, 0 AS holidays, e.advacccode, p.paytype, 0 AS hoursworked FROM dbo.emp_employee AS e, dbo.emp_pay AS p, dbo.emp_category AS c, dbo.emp_department AS d WHERE (((((((c.empcatcode IN (SELECT code FROM tv_sp_generatepayroll_tab_empcategory AS tab_empcategory)) AND (d.deptcode IN (SELECT code FROM tv_sp_generatepayroll_tab_empdept AS tab_empdept))) AND (e.active = 'Y')) AND (e.empcatcode = c.empcatcode)) AND (e.deptcode = d.deptcode)) AND (e.empcode = p.empcode)) AND (e.acccode IN (SELECT a.acccode FROM dbo.accounts AS a WHERE (a.active = 'Y'))));
  END IF;
  UPDATE tmp_temppay AS temppay SET allowances = coalesce((SELECT coalesce(sum((t.flatamount + round(((((t.basicpay * t.percentage) * 0.01)))::numeric, 2))), 0) AS allowances FROM (SELECT pa.*, e.basicpay FROM dbo.emp_payallowance AS pa, tmp_temppay AS e WHERE (e.empcode = pa.empcode)) AS t WHERE (temppay.empcode = t.empcode)), 0);
  UPDATE tmp_temppay AS temppay SET deductions = coalesce((SELECT coalesce(sum((t.flatamount + round(((((t.basicpay * t.percentage) * 0.01)))::numeric, 2))), 0) AS deductions FROM (SELECT pd.*, e.basicpay FROM dbo.emp_paydeduction AS pd, tmp_temppay AS e WHERE (e.empcode = pd.empcode)) AS t WHERE (temppay.empcode = t.empcode)), 0);
  UPDATE tmp_temppay AS temppay SET netpayable = round((((((((((((coalesce(basicpay, 0) + coalesce(overtime, 0)) + coalesce(bonuspay, 0)) + coalesce(additionalpay, 0)) + coalesce(otherpay, 0)) - coalesce(fine, 0)) - coalesce(penalty, 0)) - coalesce(othercharge, 0)) - coalesce(advance, 0)) + coalesce(allowances, 0)) - coalesce(deductions, 0)))::numeric, 0);
  DELETE FROM tmp_temppay AS temppay WHERE (netpayable IS NULL);
  DELETE FROM tmp_temppay AS temppay WHERE (netpayable < 0);
  INSERT INTO tmp_temppay2 (payrollcode, empcode, workdays, presents, absents, leaves, perhourrate, basicpay, overtimehours, overtimerate, overtime, bonuspay, specialpay, additionalpay, otherpay, fine, penalty, othercharge, advance, netpayable, sundays, holidays, advacccode, paytype, hoursworked) SELECT payrollcode, empcode, workdays, presents, absents, leaves, perhourrate, basicpay, overtimehours, overtimerate, overtime, bonuspay, specialpay, additionalpay, otherpay, fine, penalty, othercharge, advance, netpayable, sundays, holidays, advacccode, paytype, hoursworked FROM tmp_temppay AS temppay;
  UPDATE tmp_temppay2 AS temppay2 SET payrollcode = (payrollcode + rowid);
  v_paysliprows := coalesce((SELECT count(*) FROM tmp_temppay2 AS temppay2), 0);
  IF (v_paysliprows = 0) THEN
    return_value := 0;
    payslipsgenerated := v_payslipsgenerated;
    RETURN;
  END IF;
  v_endcode := coalesce((SELECT max(payrollcode) FROM tmp_temppay2 AS temppay2), v_startcode);
  INSERT INTO dbo.emp_payroll (payrollcode, date, usercode, posted, postdate, postedby, lastsaved, fromdate, todate, empcode, workdays, presents, absents, leaves, perhourrate, basicpay, overtimehours, overtimerate, overtime, bonuspay, specialpay, additionalpay, otherpay, fine, penalty, othercharge, advance, netpayable, remarks, paid, paidvia, paymentdate, paymentrefno, paymentremarks, paidby, sundays, holidays, hoursworked) SELECT payrollcode, localtimestamp(3) AS date, v_usercode AS usercode, 'N' AS posted, NULL::timestamp(3) AS postdate, NULL::smallint AS postedby, localtimestamp(3) AS lastsaved, v_startdate AS fromdate, v_enddate AS todate, empcode, workdays, presents, absents, leaves, perhourrate, basicpay, overtimehours, overtimerate, overtime, bonuspay, specialpay, additionalpay, otherpay, fine, penalty, othercharge, advance, netpayable, 'Auto Generated' AS remarks, 'N' AS paid, 2 AS paidvia, localtimestamp(3) AS paymentdate, 'CASH' AS paymentrefno, '' AS paymentremarks, v_usercode AS paidby, sundays, holidays, hoursworked FROM tmp_temppay2 AS temppay2;
  INSERT INTO dbo.emp_payrollallowances SELECT (SELECT t.payrollcode FROM tmp_temppay2 AS t WHERE (t.empcode = pa.empcode)) AS payrollcode, pa.allowancecode, pa.attendancewise, pa.percentage, pa.flatamount FROM dbo.emp_employee AS e, dbo.emp_category AS c, dbo.emp_department AS d, dbo.emp_payallowance AS pa WHERE (((((((c.empcatcode IN (SELECT code FROM tv_sp_generatepayroll_tab_empcategory AS tab_empcategory)) AND (d.deptcode IN (SELECT code FROM tv_sp_generatepayroll_tab_empdept AS tab_empdept))) AND (e.active = 'Y')) AND (e.empcatcode = c.empcatcode)) AND (e.deptcode = d.deptcode)) AND (e.empcode = pa.empcode)) AND (e.empcode IN (SELECT tm.empcode FROM tmp_temppay2 AS tm)));
  INSERT INTO dbo.emp_payrolldeductions SELECT (SELECT t.payrollcode FROM tmp_temppay2 AS t WHERE (t.empcode = pd.empcode)) AS payrollcode, pd.deductioncode, pd.percentage, pd.flatamount FROM dbo.emp_employee AS e, dbo.emp_category AS c, dbo.emp_department AS d, dbo.emp_paydeduction AS pd WHERE (((((((c.empcatcode IN (SELECT code FROM tv_sp_generatepayroll_tab_empcategory AS tab_empcategory)) AND (d.deptcode IN (SELECT code FROM tv_sp_generatepayroll_tab_empdept AS tab_empdept))) AND (e.active = 'Y')) AND (e.empcatcode = c.empcatcode)) AND (e.deptcode = d.deptcode)) AND (e.empcode = pd.empcode)) AND (e.empcode IN (SELECT tm.empcode FROM tmp_temppay2 AS tm)));
  v_payslipsgenerated := coalesce((SELECT count(*) FROM tmp_temppay2 AS temppay2), 0);
  UPDATE dbo.emp_payroll SET netpayable = round((((((((((((coalesce(basicpay, 0) + coalesce(overtime, 0)) + coalesce(bonuspay, 0)) + coalesce(additionalpay, 0)) + coalesce(otherpay, 0)) - coalesce(fine, 0)) - coalesce(penalty, 0)) - coalesce(othercharge, 0)) - coalesce(advance, 0)) + coalesce((SELECT sum((ea.flatamount + round(((((e.basicpay * ea.percentage) * 0.01)))::numeric, 2))) AS allowances FROM dbo.emp_payrollallowances AS ea, dbo.emp_payroll AS e WHERE ((ea.payrollcode = e.payrollcode) AND (e.payrollcode = emp_payroll.payrollcode)) GROUP BY e.payrollcode, e.basicpay), 0)) - coalesce((SELECT sum((ed.flatamount + round(((((e.basicpay * ed.percentage) * 0.01)))::numeric, 2))) AS deductions FROM dbo.emp_payrolldeductions AS ed, dbo.emp_payroll AS e WHERE ((ed.payrollcode = e.payrollcode) AND (e.payrollcode = emp_payroll.payrollcode)) GROUP BY e.payrollcode, e.basicpay), 0)))::numeric, 0) WHERE (payrollcode BETWEEN v_startcode AND v_endcode);
  SELECT r.return_value INTO v_rt_code FROM dbo.sp_updatetabmaxkey(tabname => 'EMP_Payroll', key => v_endcode) AS r;
  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
    RAISE EXCEPTION 'Problem while Updating EMP_Payroll Key Value';
    return_value := -1;
    payslipsgenerated := v_payslipsgenerated;
    RETURN;
  END IF;
  return_value := 0;
  payslipsgenerated := v_payslipsgenerated;
  RETURN;
  return_value := 0;
  payslipsgenerated := v_payslipsgenerated;
  RETURN;
END
$body$;

-- ==== proc SP_GenerateQuotations_From_DropBox ====
CREATE OR REPLACE FUNCTION dbo.sp_generatequotations_from_dropbox(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_unpulledorders integer;
  v_usercode smallint;
  v_mysitecode integer;
  v_start_no integer;
  v_end_no integer;
  v_errcode integer;
  _rc integer;
BEGIN
  -- SET NOCOUNT ON
  v_mysitecode := (SELECT min(sitecode) FROM dbo.site WHERE (instanceid IN (SELECT name FROM dbo.clientinstance)));
  _rc := 1;
  IF ((v_mysitecode < 0) OR (v_mysitecode IS NULL)) THEN
    return_value := 0;
    RETURN;
  END IF;
  v_unpulledorders := coalesce((SELECT count(*) FROM dbo.db_purorderheader WHERE ((pulled = 'N') AND (targetsitecode = v_mysitecode))), 0);
  _rc := 1;
  IF ((v_unpulledorders <= 0) OR (v_unpulledorders IS NULL)) THEN
    return_value := 0;
    RETURN;
  END IF;
  v_errcode := 0;
  _rc := 1;
  SELECT r.return_value, r.key INTO v_errcode, v_start_no FROM dbo.sp_locktabmaxkey(tabname => 'Quotation', key => v_start_no) AS r;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem while Fetching Quotation Header Value';
    return_value := -1;
    RETURN;
  END IF;
  DROP TABLE IF EXISTS tv_sp_generatequotations_from_dropbox_header;
  CREATE TEMP TABLE tv_sp_generatequotations_from_dropbox_header (
    code integer,
    sitecode integer,
    custcode integer,
    pocode integer,
    rowid integer GENERATED BY DEFAULT AS IDENTITY
) ON COMMIT DROP;
  v_usercode := 1;
  _rc := 1;
  INSERT INTO tv_sp_generatequotations_from_dropbox_header (code, sitecode, custcode, pocode) SELECT v_start_no AS code, p.sitecode, (SELECT max(c.custcode) FROM dbo.customer AS c WHERE (c.sitecode = p.sitecode)) AS custcode, p.pocode FROM dbo.db_purorderheader AS p WHERE ((p.pulled = 'N') AND (p.targetsitecode = v_mysitecode));
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF (_rc = 0) THEN
    return_value := 0;
    RETURN;
  END IF;
  UPDATE tv_sp_generatequotations_from_dropbox_header AS header SET code = (v_start_no + rowid);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF (_rc = 0) THEN
    return_value := 0;
    RETURN;
  END IF;
  INSERT INTO dbo.quotationheader (quotationcode, custcode, salesmancode, date, discperc, flatdisc, misccharges, salestax, sprice, validateupto, postdate, remarks, custrefno, headerno, originaldate, modifiedby, postedby, posted, invgstperc1, remarks2, remarks3, remarks4, remarks5, remarks6, remarks7, remarks8, remarks9, pagesize, messagecode, smancode, loosepack, consolidatedsaleorder, active, locked, autoinsertnewitems, synced, syncedon, syncedby, deliverydays, validitydays, paymentto) SELECT t.code, t.custcode, v_usercode AS salesmancode, localtimestamp(3) AS date, p.discperc, p.flatdisc, p.misccharges, 0 AS salestax, CASE WHEN (c.priceonsale IS NULL) THEN 1 ELSE c.priceonsale END AS sprice, localtimestamp(3) AS validateupto, localtimestamp(3) AS postdate, p.remarks, ltrim(rtrim(dbo.tsql_str((p.pocode)::numeric))) AS custrefno, 1 AS headerno, localtimestamp(3) AS originaldate, NULL::smallint AS modifiedby, NULL::smallint AS postedby, 'N' AS posted, p.invgstperc1, p.purorderterms1 AS remarks2, p.purorderterms2 AS remarks3, p.purorderterms3 AS remarks4, p.purorderterms4 AS remarks5, p.purorderterms5 AS remarks6, p.purorderterms6 AS remarks7, p.purorderterms7 AS remarks8, p.purorderterms8 AS remarks9, dbo.fn_getpreference('pagesize') AS pagesize, c.messagecode AS messagecode, c.salesmancode AS smancode, 2 AS loosepack, NULL::integer AS consolidatedsaleorder, 'Y' AS active, 'N' AS locked, 'Y' AS autoinsertnewitems, 'N' AS synced, NULL::timestamp(3) AS syncedon, NULL::smallint AS syncedby, 0 AS deliverydays, 0 AS validitydays, c.paymentapi FROM tv_sp_generatequotations_from_dropbox_header AS t, dbo.db_purorderheader AS p, dbo.customer AS c WHERE (((((p.pulled = 'N') AND (p.targetsitecode = v_mysitecode)) AND (t.sitecode = p.sitecode)) AND (t.pocode = p.pocode)) AND (t.custcode = c.custcode));
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((0 <> 0) OR (_rc <= 0)) THEN
    RAISE EXCEPTION 'Problem while Inserting Quotation Header Value';
    return_value := -1;
    RETURN;
  END IF;
  INSERT INTO dbo.quotationdetail (quotationcode, icode, qty, packunits, saleprice, discperc, salestax, itemflatdisc, bonusqty, gstperc, unitsalestax, itemdescription, gcode, remotenetsaleqty, remotestock, porate, podiscperc, specialrate, refno, claimablediscperc, color, remote_reorderqty, remote_optimumqty, remote_minqty, remote_poqty) SELECT t.code AS quotationcode, d.icode, d.qty, i.packunits, i.saleprice, d.discperc, 0 AS salestax, d.itemflatdisc, d.bonusqty, d.gstperc, d.packsalestax, i.name AS itemdescription, 1 AS gcode, coalesce((d.soldqty - d.returnqty), 0) AS remotenetsaleqty, coalesce(d.stock, 0) AS remotestock, d.rate AS porate, d.discperc AS podiscperc, d.rate AS specialrate, NULL::citext AS refno, 0 AS claimablediscperc, NULL::citext AS color, d.reorderqty, d.optimumqty, d.minqty, coalesce(poqty, 0) FROM dbo.db_purorderdetail AS d, tv_sp_generatequotations_from_dropbox_header AS t, dbo.item AS i WHERE ((((((d.qty + d.bonusqty)) > 0) AND (d.sitecode = t.sitecode)) AND (d.pocode = t.pocode)) AND (d.icode = i.icode)) ORDER BY d.pocode, d.porowid;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((0 <> 0) OR (_rc <= 0)) THEN
    RAISE EXCEPTION 'Problem while Inserting Quotation Detail Rows';
    return_value := -1;
    RETURN;
  END IF;
  v_end_no := coalesce((SELECT max(code) FROM tv_sp_generatequotations_from_dropbox_header AS header), 0);
  _rc := 1;
  SELECT r.return_value INTO v_errcode FROM dbo.sp_updatetabmaxkey(tabname => 'Quotation', key => v_end_no) AS r;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem while Updating Quotation Header Key Value';
    return_value := -1;
    RETURN;
  END IF;
  UPDATE dbo.quotationheader SET invtotal = dbo.fn_getquotationtotal(v_end_no) WHERE (quotationcode BETWEEN v_start_no AND v_end_no);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  UPDATE dbo.db_purorderheader SET pulled = 'Y', pulledon = localtimestamp(3), pulledby = v_usercode WHERE (((pulled = 'N') AND (targetsitecode = v_mysitecode)) AND (((dbo.tsql_str((pocode)::numeric, 10) || dbo.tsql_str((sitecode)::numeric, 10)))::citext IN (SELECT (dbo.tsql_str((t.pocode)::numeric, 10) || dbo.tsql_str((t.sitecode)::numeric, 10)) FROM tv_sp_generatequotations_from_dropbox_header AS t)));
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((0 <> 0) OR (_rc <= 0)) THEN
    RAISE EXCEPTION 'Problem while Updating P/O Status in Drop Box';
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_GenerateReceipt ====
CREATE OR REPLACE FUNCTION dbo.sp_generatereceipt(prodcode integer, usercode integer, headerno integer, serverdate timestamp, issueinvcode integer, INOUT receiptinvcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_prodcode integer;
  v_usercode integer;
  v_headerno integer;
  v_serverdate timestamp(3);
  v_issueinvcode integer;
  v_receiptinvcode integer;
  v_code integer;
  v_deptcode integer;
  v_category smallint;
  v_module smallint;
  v_utn integer;
  v_headerinvno integer;
  v_receiptcode integer;
  v_issuetype smallint;
  v_pricetype smallint;
  v_priority smallint;
  v_godownstrategy smallint;
  v_groupcode integer;
  v_cracccode smallint;
  v_icode integer;
  v_gcode integer;
  v_packunits integer;
  v_areacode integer;
  v_givenqty numeric(15,4);
  v_totalqty numeric(15,4);
  v_currqty numeric(15,4);
  v_delqty numeric(15,4);
  v_batchqty numeric(15,4);
  v_reqqty numeric(15,4);
  v_newqty numeric(15,4);
  v_totstock numeric(15,4);
  v_price numeric(12,2);
  v_purprice numeric(12,2);
  v_saleprice numeric(12,2);
  v_hold_avgprice numeric(15,5);
  v_recentpurprice numeric(12,2);
  v_newavgprice numeric(15,5);
  v_batch citext;
  v_itemname citext;
  v_updateavgprice citext;
  v_items_rows integer;
  v_counter integer;
  v_rowcount integer;
  v_totalrows integer;
  v_continue integer;
  v_err integer;
  v_rt_code integer;
  v_expiry timestamp(3);
  v_recomputecost citext;
  v_autopost citext;
  v_accountfor citext;
  cur_cursor_items refcursor;
  _rc integer;
  _fs integer := -1;
BEGIN
  v_prodcode := prodcode;
  v_usercode := usercode;
  v_headerno := headerno;
  v_serverdate := serverdate;
  v_issueinvcode := issueinvcode;
  v_receiptinvcode := receiptinvcode;
  v_continue := 0;
  _rc := 1;
  v_deptcode := coalesce((SELECT receiptdeptcode FROM dbo.prodheader WHERE (prodcode = v_prodcode)), 1);
  _rc := 1;
  v_areacode := 1;
  _rc := 1;
  v_module := (SELECT module FROM dbo.module WHERE ((lower(name))::citext = 'receipt'));
  _rc := 1;
  v_pricetype := dbo.fn_get_int_preference('ReceiptPriceTypeCode');
  _rc := 1;
  v_groupcode := coalesce((SELECT min(groupcode) FROM dbo.usergroups WHERE (usercode = v_usercode)), 1);
  _rc := 1;
  v_category := 2;
  _rc := 1;
  v_accountfor := coalesce((SELECT accountfor FROM dbo.receiptcategory WHERE (receiptcategorycode = v_category)), 'N');
  _rc := 1;
  IF (v_accountfor = 'Y') THEN
    v_cracccode := trunc(coalesce((SELECT code FROM dbo.global WHERE (name = 'GT_WIPAcc')), 33))::smallint;
    _rc := 1;
  ELSE
    v_cracccode := NULL;
    _rc := 1;
  END IF;
  IF (v_groupcode > 0) THEN
    v_godownstrategy := coalesce((SELECT receiptgodownstrategy FROM dbo.groups WHERE (groupcode = v_groupcode)), 1);
    _rc := 1;
  ELSE
    v_godownstrategy := 1;
    _rc := 1;
  END IF;
  IF (v_godownstrategy = 1) THEN
    v_gcode := (SELECT receiptgcode FROM dbo.prodheader WHERE (prodcode = v_prodcode));
    _rc := 1;
  END IF;
  v_batch := dbo.fn_getpreference('defaultbatch');
  _rc := 1;
  v_expiry := dbo.fn_get_datetime_preference('defaultexpiry');
  _rc := 1;
  v_updateavgprice := dbo.fn_getpreference('UpdAvgPriceInReceipt');
  _rc := 1;
  v_priority := 10;
  _rc := 1;
  v_recomputecost := dbo.fn_getpreference('ReComputeCostInProduction');
  _rc := 1;
  v_autopost := dbo.fn_getpreference('AutoPostReceiptOnProdPost');
  _rc := 1;
  IF (v_autopost IS NULL) THEN
    v_autopost := 'Y';
    _rc := 1;
  END IF;
  OPEN cur_cursor_items FOR SELECT pd.icode AS icode, pd.batch, pd.expiry, sum(pd.qty) AS qty, max(i.packunits) AS packunits, round(((max(i.purprice) / max(i.packunits)))::numeric, 2) AS purprice, round(((max(i.saleprice) / max(i.packunits)))::numeric, 2) AS saleprice, round(((max(i.recentpurprice) / max(i.packunits)))::numeric, 2) AS recentpurprice, CASE WHEN (v_issueinvcode > 0) THEN CASE v_recomputecost WHEN 'Y' THEN round((((SELECT sum((isd.qty * isd.price)) FROM dbo.issuedetail AS isd, dbo.recipedetail AS rd WHERE (((isd.issueinvcode = v_issueinvcode) AND (r.recipecode = rd.recipecode)) AND (rd.icode = isd.icode))) / CASE WHEN (sum(pd.qty) = 0) THEN 1 ELSE sum(pd.qty) END))::numeric, 2) ELSE CASE v_pricetype WHEN 1 THEN round(((max(i.saleprice) / max(i.packunits)))::numeric, 2) WHEN 2 THEN round(((max(i.saleprice2) / max(i.packunits)))::numeric, 2) WHEN 3 THEN round(((max(i.saleprice3) / max(i.packunits)))::numeric, 2) WHEN 4 THEN round(((max(i.purprice) / max(i.packunits)))::numeric, 2) WHEN 5 THEN round(((max(i.recentpurprice) / max(i.packunits)))::numeric, 2) WHEN 6 THEN round((max(i.avgprice))::numeric, 2) WHEN 7 THEN round(((max(i.saleprice4) / max(i.packunits)))::numeric, 2) WHEN 8 THEN round(((max(i.saleprice5) / max(i.packunits)))::numeric, 2) END END ELSE CASE v_pricetype WHEN 1 THEN round(((max(i.saleprice) / max(i.packunits)))::numeric, 2) WHEN 2 THEN round(((max(i.saleprice2) / max(i.packunits)))::numeric, 2) WHEN 3 THEN round(((max(i.saleprice3) / max(i.packunits)))::numeric, 2) WHEN 4 THEN round(((max(i.purprice) / max(i.packunits)))::numeric, 2) WHEN 5 THEN round(((max(i.recentpurprice) / max(i.packunits)))::numeric, 2) WHEN 6 THEN round((max(i.avgprice))::numeric, 2) WHEN 7 THEN round(((max(i.saleprice4) / max(i.packunits)))::numeric, 2) WHEN 8 THEN round(((max(i.saleprice5) / max(i.packunits)))::numeric, 2) END END AS price FROM dbo.recipe AS r, (SELECT icode, qty, batch, expiry FROM dbo.proddetail WHERE (proddetail.prodcode = v_prodcode)) AS pd, dbo.item AS i WHERE (((r.resulteditem = pd.icode) AND (pd.icode = i.icode)) AND (r.priority = (SELECT min(priority) FROM dbo.recipe WHERE (resulteditem = pd.icode)))) GROUP BY pd.icode, pd.batch, pd.expiry, r.recipecode;
  v_items_rows := (-1);
  _rc := 1;
  IF (v_items_rows > 0) THEN
    SELECT r.return_value, r.key INTO v_rt_code, v_code FROM dbo.sp_gettabmaxkey(tabname => 'ReceiptHeader', key => v_code) AS r;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      v_continue := -1;
      _rc := 1;
    ELSE
      v_receiptinvcode := v_code;
      _rc := 1;
      SELECT r.return_value, r.key INTO v_rt_code, v_headerinvno FROM dbo.sp_getheadertabmaxkey(headercode => (v_headerno)::smallint, modulecode => v_module, key => v_headerinvno) AS r;
      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
        v_continue := -1;
        _rc := 1;
      ELSE
        v_receiptcode := NULL;
        _rc := 1;
        SELECT r.return_value, r.counter INTO v_rt_code, v_receiptcode FROM dbo.sp_getreceiptcategorycounter(category => v_category, counter => v_receiptcode) AS r;
        IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
          v_continue := -1;
          _rc := 1;
        ELSE
          INSERT INTO dbo.receiptheader (receiptinvcode, deptcode, date, originaldate, salesmancode, posted, postdate, postedby, areacode, headerno, headerinvno, pricetypecode, remarks, receiptcategorycode, accountfor, cracccode, receiptcode) VALUES (v_code, v_deptcode, v_serverdate, v_serverdate, v_usercode, v_autopost, v_serverdate, v_usercode, v_areacode, v_headerno, v_headerinvno, v_pricetype, 'SYSTEM GENERATED RECEIPT', v_category, v_accountfor, v_cracccode, v_receiptcode);
          GET DIAGNOSTICS _rc = ROW_COUNT;
          v_err := 0;
          v_rowcount := _rc;
          _rc := 1;
          IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
            RAISE EXCEPTION 'Error occured in inserting record into Receipt Header : %', v_code;
            v_continue := -1;
            _rc := 1;
          ELSE
            FETCH NEXT FROM cur_cursor_items INTO v_icode, v_batch, v_expiry, v_givenqty, v_packunits, v_purprice, v_saleprice, v_recentpurprice, v_price;
            IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
            WHILE ((_fs = 0) AND (v_continue >= 0)) LOOP
              IF (v_godownstrategy = 2) THEN
                v_gcode := coalesce((SELECT gcode FROM dbo.item WHERE (icode = v_icode)), 1);
                _rc := 1;
              END IF;
              SELECT r.return_value, r.avgprice INTO v_rt_code, v_hold_avgprice FROM dbo.sp_getitemavgprice(icode => v_icode, avgprice => v_hold_avgprice) AS r;
              IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                v_continue := -1;
                _rc := 1;
              ELSE
                SELECT r.return_value, r.lbi_maxutn INTO v_rt_code, v_utn FROM dbo.sp_maxutn(lbi_rows => (1)::bigint, lbi_maxutn => (v_utn)::bigint) AS r;
                IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                  v_continue := -1;
                  _rc := 1;
                END IF;
                v_packunits := CASE WHEN (v_packunits IS NULL) THEN 1 WHEN (v_packunits = 0) THEN 1 ELSE v_packunits END;
                _rc := 1;
                SELECT r.return_value, r.qty INTO v_rt_code, v_totstock FROM dbo.sp_getitemstockall(icode => v_icode, qty => v_totstock) AS r;
                IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                  v_continue := -1;
                  _rc := 1;
                END IF;
                IF (v_updateavgprice = 'Y') THEN
                  v_newavgprice := coalesce((SELECT round(((((((v_totstock * v_hold_avgprice)) + ((v_givenqty * v_price)))) / ((v_givenqty + v_totstock))))::numeric, 5)), 0);
                  _rc := 1;
                  IF (v_autopost = 'Y') THEN
                    SELECT r.return_value INTO v_rt_code FROM dbo.sp_updateitemavgprice(icode => v_icode, avgprice => v_newavgprice) AS r;
                    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                      v_continue := -1;
                      _rc := 1;
                    END IF;
                  END IF;
                ELSE
                  v_newavgprice := v_hold_avgprice;
                  _rc := 1;
                END IF;
                IF (v_continue <> -1) THEN
                  INSERT INTO dbo.receiptdetail (receiptinvcode, gcode, icode, batch, expiry, qty, priority, saleprice, purchaseprice, avgprice, packunits, mrpp, receiptutn, price, updateavgprice, newavgprice, currstock) VALUES (v_code, v_gcode, v_icode, v_batch, v_expiry, v_givenqty, v_priority, v_saleprice, v_purprice, v_hold_avgprice, v_packunits, v_recentpurprice, v_utn, v_price, v_updateavgprice, v_newavgprice, v_totstock);
                  GET DIAGNOSTICS _rc = ROW_COUNT;
                  v_err := 0;
                  v_rowcount := _rc;
                  _rc := 1;
                  IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
                    RAISE EXCEPTION 'Error occured in inserting record into Receipt Detail for Production : %', v_prodcode;
                    v_continue := -1;
                    _rc := 1;
                  ELSE
                    IF (v_autopost = 'Y') THEN
                      SELECT r.return_value, r.qty INTO v_rt_code, v_currqty FROM dbo.sp_getitemstockbatch(gcode => v_gcode, icode => v_icode, batch => v_batch, expiry => v_expiry, qty => v_currqty) AS r;
                      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                        v_continue := -1;
                        _rc := 1;
                      ELSE
                        v_newqty := (v_currqty + v_givenqty);
                        _rc := 1;
                        SELECT r.return_value INTO v_rt_code FROM dbo.sp_updateitemstockbatch(gcode => v_gcode, icode => v_icode, batch => v_batch, expiry => v_expiry, newqty => v_newqty) AS r;
                        IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                          v_continue := -1;
                          _rc := 1;
                        END IF;
                      END IF;
                    END IF;
                  END IF;
                END IF;
              END IF;
              FETCH NEXT FROM cur_cursor_items INTO v_icode, v_batch, v_expiry, v_givenqty, v_packunits, v_purprice, v_saleprice, v_recentpurprice, v_price;
              IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
            END LOOP;
          END IF;
        END IF;
      END IF;
    END IF;
  END IF;
  CLOSE cur_cursor_items;
  -- DEALLOCATE Cursor_Items
  IF (v_continue <> 0) THEN
    return_value := -1;
    receiptinvcode := v_receiptinvcode;
    RETURN;
  ELSE
    return_value := 0;
    receiptinvcode := v_receiptinvcode;
    RETURN;
  END IF;
  return_value := 0;
  receiptinvcode := v_receiptinvcode;
  RETURN;
END
$body$;

-- ==== proc sp_GenerateReceipt_On_ProdunctionNote ====
CREATE OR REPLACE FUNCTION dbo.sp_generatereceipt_on_produnctionnote(prodnotecode integer, usercode integer, INOUT receiptinvcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_prodnotecode integer;
  v_usercode integer;
  v_receiptinvcode integer;
  v_code integer;
  v_rowid integer;
  v_deptcode integer;
  v_module smallint;
  v_category smallint;
  v_utn integer;
  v_headerinvno integer;
  v_issuetype smallint;
  v_pricetype smallint;
  v_priority smallint;
  v_headerno integer;
  v_receiptcode integer;
  v_cracccode smallint;
  v_icode integer;
  v_gcode integer;
  v_packunits integer;
  v_areacode integer;
  v_totalpieces integer;
  v_piecesinhand integer;
  v_givenqty numeric(15,4);
  v_totalqty numeric(15,4);
  v_currqty numeric(15,4);
  v_delqty numeric(15,4);
  v_batchqty numeric(15,4);
  v_reqqty numeric(15,4);
  v_newqty numeric(15,4);
  v_totstock numeric(15,4);
  v_price numeric(12,2);
  v_purprice numeric(12,2);
  v_saleprice numeric(12,2);
  v_hold_avgprice numeric(15,5);
  v_recentpurprice numeric(12,2);
  v_newavgprice numeric(15,5);
  v_netrate numeric(15,5);
  v_batch citext;
  v_itemname citext;
  v_updateavgprice citext;
  v_errtext citext;
  v_items_rows integer;
  v_counter integer;
  v_rowcount integer;
  v_totalrows integer;
  v_continue integer;
  v_err integer;
  v_rt_code integer;
  v_expiry timestamp(3);
  v_serverdate timestamp(3);
  v_recomputecost citext;
  v_accountfor citext;
  cur_cursor_items refcursor;
  _rc integer;
  _fs integer := -1;
BEGIN
  v_prodnotecode := prodnotecode;
  v_usercode := usercode;
  v_receiptinvcode := receiptinvcode;
  v_continue := 0;
  _rc := 1;
  v_deptcode := coalesce((SELECT receiptdeptcode FROM dbo.prodnote WHERE (prodnotecode = v_prodnotecode)), 1);
  _rc := 1;
  v_headerno := 1;
  _rc := 1;
  v_areacode := 1;
  _rc := 1;
  v_module := (SELECT module FROM dbo.module WHERE ((lower(name))::citext = 'receipt'));
  _rc := 1;
  v_pricetype := dbo.fn_get_int_preference('ReceiptPriceTypeCode');
  _rc := 1;
  v_batch := dbo.fn_getpreference('defaultbatch');
  _rc := 1;
  v_expiry := dbo.fn_get_datetime_preference('defaultexpiry');
  _rc := 1;
  v_updateavgprice := dbo.fn_getpreference('UpdAvgPriceInReceipt');
  _rc := 1;
  v_priority := 10;
  _rc := 1;
  v_recomputecost := dbo.fn_getpreference('ReComputeCostInProduction');
  _rc := 1;
  v_serverdate := localtimestamp(3);
  _rc := 1;
  v_category := 2;
  _rc := 1;
  v_accountfor := coalesce((SELECT accountfor FROM dbo.receiptcategory WHERE (receiptcategorycode = v_category)), 'N');
  _rc := 1;
  IF (v_accountfor = 'Y') THEN
    v_cracccode := trunc(coalesce((SELECT code FROM dbo.global WHERE (name = 'GT_WIPAcc')), 33))::smallint;
    _rc := 1;
  ELSE
    v_cracccode := NULL;
    _rc := 1;
  END IF;
  OPEN cur_cursor_items FOR SELECT pnr.icode, pnr.gcode, pnr.batch, pnr.expiry, sum(pnr.totalpieces) AS totalpieces, sum(pnr.qty) AS qty, pnr.packunits, round(((max(i.purprice) / max(i.packunits)))::numeric, 2) AS purprice, round(((max(i.saleprice) / max(i.packunits)))::numeric, 2) AS saleprice, round(((max(i.recentpurprice) / max(i.packunits)))::numeric, 2) AS recentpurprice, CASE v_pricetype WHEN 1 THEN round(((max(i.saleprice) / max(i.packunits)))::numeric, 2) WHEN 2 THEN round(((max(i.saleprice2) / max(i.packunits)))::numeric, 2) WHEN 3 THEN round(((max(i.saleprice3) / max(i.packunits)))::numeric, 2) WHEN 4 THEN round(((max(i.purprice) / max(i.packunits)))::numeric, 2) WHEN 5 THEN round(((max(i.recentpurprice) / max(i.packunits)))::numeric, 2) WHEN 6 THEN round((max(i.avgprice))::numeric, 2) WHEN 7 THEN round(((max(i.saleprice4) / max(i.packunits)))::numeric, 2) WHEN 8 THEN round(((max(i.saleprice5) / max(i.packunits)))::numeric, 2) END AS price, pnr.rowid FROM dbo.prodnotereceipt AS pnr, dbo.item AS i WHERE ((pnr.prodnotecode = v_prodnotecode) AND (pnr.icode = i.icode)) GROUP BY pnr.icode, pnr.gcode, pnr.batch, pnr.expiry, pnr.packunits, pnr.rowid;
  v_items_rows := (-1);
  _rc := 1;
  IF (v_items_rows > 0) THEN
    SELECT r.return_value, r.key INTO v_rt_code, v_code FROM dbo.sp_gettabmaxkey(tabname => 'ReceiptHeader', key => v_code) AS r;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      v_continue := -1;
      _rc := 1;
    ELSE
      v_receiptinvcode := v_code;
      _rc := 1;
      SELECT r.return_value, r.key INTO v_rt_code, v_headerinvno FROM dbo.sp_getheadertabmaxkey(headercode => (v_headerno)::smallint, modulecode => v_module, key => v_headerinvno) AS r;
      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
        v_continue := -1;
        _rc := 1;
      ELSE
        v_receiptcode := NULL;
        _rc := 1;
        SELECT r.return_value, r.counter INTO v_rt_code, v_receiptcode FROM dbo.sp_getreceiptcategorycounter(category => v_category, counter => v_receiptcode) AS r;
        IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
          v_continue := -1;
          _rc := 1;
        ELSE
          INSERT INTO dbo.receiptheader (receiptinvcode, deptcode, date, originaldate, salesmancode, posted, postdate, postedby, areacode, headerno, headerinvno, pricetypecode, remarks, recipientcode, receiptcategorycode, accountfor, cracccode, receiptcode, qe1_acccode, qe2_acccode, qe3_acccode, qe4_acccode, qe5_acccode, we1_acccode, we2_acccode, we3_acccode, we4_acccode, we5_acccode, qexp1_cracccode, qexp2_cracccode, qexp3_cracccode, qexp4_cracccode, qexp5_cracccode, wexp1_cracccode, wexp2_cracccode, wexp3_cracccode, wexp4_cracccode, wexp5_cracccode) SELECT v_code, v_deptcode, v_serverdate, v_serverdate, v_usercode, 'Y', v_serverdate, v_usercode, v_areacode, v_headerno, v_headerinvno, v_pricetype, 'PRODUCTION NOTE BASED RECEIPT', 1, v_category, v_accountfor, v_cracccode, v_receiptcode, qe1_acccode, qe2_acccode, qe3_acccode, qe4_acccode, qe5_acccode, we1_acccode, we2_acccode, we3_acccode, we4_acccode, we5_acccode, qexp1_cracccode, qexp2_cracccode, qexp3_cracccode, qexp4_cracccode, qexp5_cracccode, wexp1_cracccode, wexp2_cracccode, wexp3_cracccode, wexp4_cracccode, wexp5_cracccode FROM dbo.prodnote WHERE (prodnotecode = v_prodnotecode);
          GET DIAGNOSTICS _rc = ROW_COUNT;
          v_err := 0;
          v_rowcount := _rc;
          _rc := 1;
          IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
            RAISE EXCEPTION 'Error occured in inserting record into Receipt Header : %', v_code;
            v_continue := -1;
            _rc := 1;
          ELSE
            FETCH NEXT FROM cur_cursor_items INTO v_icode, v_gcode, v_batch, v_expiry, v_totalpieces, v_givenqty, v_packunits, v_purprice, v_saleprice, v_recentpurprice, v_price, v_rowid;
            IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
            WHILE ((_fs = 0) AND (v_continue >= 0)) LOOP
              v_itemname := (SELECT name FROM dbo.item WHERE (icode = v_icode));
              _rc := 1;
              SELECT r.return_value, r.avgprice INTO v_rt_code, v_hold_avgprice FROM dbo.sp_getitemavgprice(icode => v_icode, avgprice => v_hold_avgprice) AS r;
              IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                v_errtext := ('Unable to aquire item lock for item = ' || v_itemname);
                _rc := 1;
                v_continue := -1;
                _rc := 1;
              ELSE
                SELECT r.return_value, r.qty INTO v_rt_code, v_piecesinhand FROM dbo.sp_getitemtotalpiecesinhand(icode => v_icode, qty => v_piecesinhand) AS r;
                IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                  v_errtext := ('Unable to fetch total pieces in hand for item = ' || v_itemname);
                  _rc := 1;
                  v_continue := -1;
                  _rc := 1;
                ELSE
                  SELECT r.return_value INTO v_rt_code FROM dbo.sp_updateitemtotalpiecesinhand(icode => v_icode, incdec => 1, totalpieces => v_totalpieces) AS r;
                  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                    v_errtext := ('Error Updating pieces in hand for item = ' || v_itemname);
                    _rc := 1;
                    v_continue := -1;
                    _rc := 1;
                  END IF;
                END IF;
              END IF;
              IF (v_continue >= 0) THEN
                SELECT r.return_value, r.lbi_maxutn INTO v_rt_code, v_utn FROM dbo.sp_maxutn(lbi_rows => (1)::bigint, lbi_maxutn => (v_utn)::bigint) AS r;
                IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                  v_continue := -1;
                  _rc := 1;
                END IF;
                v_packunits := CASE WHEN (v_packunits IS NULL) THEN 1 WHEN (v_packunits = 0) THEN 1 ELSE v_packunits END;
                _rc := 1;
                SELECT r.return_value, r.qty INTO v_rt_code, v_totstock FROM dbo.sp_getitemstockall(icode => v_icode, qty => v_totstock) AS r;
                IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                  v_continue := -1;
                  _rc := 1;
                END IF;
                IF (v_updateavgprice = 'Y') THEN
                  v_netrate := coalesce((SELECT round(((((((((qty * price)) + ((qty * (((((qe1 + qe2) + qe3) + qe4) + qe5))))) + (((qty * unitweight) * (((((we1 + we2) + we3) + we4) + we5)))))) / CASE WHEN (qty = 0) THEN 1 ELSE qty END)))::numeric, 5) FROM dbo.prodnotereceipt WHERE ((prodnotecode = v_prodnotecode) AND (rowid = v_rowid))), 0);
                  _rc := 1;
                  v_newavgprice := coalesce((SELECT round(((((((v_totstock * v_hold_avgprice)) + ((v_givenqty * v_netrate)))) / ((v_givenqty + v_totstock))))::numeric, 5)), 0);
                  _rc := 1;
                  SELECT r.return_value INTO v_rt_code FROM dbo.sp_updateitemavgprice(icode => v_icode, avgprice => v_newavgprice) AS r;
                  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                    v_continue := -1;
                    _rc := 1;
                  END IF;
                ELSE
                  v_newavgprice := v_hold_avgprice;
                  _rc := 1;
                END IF;
                IF (v_continue <> -1) THEN
                  INSERT INTO dbo.receiptdetail (receiptinvcode, gcode, icode, batch, expiry, qty, priority, saleprice, purchaseprice, avgprice, packunits, mrpp, receiptutn, price, updateavgprice, newavgprice, currstock, totalpieces, piecesinhand, unitweight, qe1, qe2, qe3, qe4, qe5, we1, we2, we3, we4, we5) SELECT v_code, v_gcode, v_icode, v_batch, v_expiry, v_givenqty, v_priority, v_saleprice, v_purprice, v_hold_avgprice, v_packunits, v_recentpurprice, v_utn, v_price, v_updateavgprice, v_newavgprice, v_totstock, v_totalpieces, v_piecesinhand, unitweight, qe1, qe2, qe3, qe4, qe5, we1, we2, we3, we4, we5 FROM dbo.prodnotereceipt WHERE ((prodnotecode = v_prodnotecode) AND (rowid = v_rowid));
                  GET DIAGNOSTICS _rc = ROW_COUNT;
                  v_err := 0;
                  v_rowcount := _rc;
                  _rc := 1;
                  IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
                    RAISE EXCEPTION 'Error occured in inserting record into Receipt Detail for Production : %', v_prodnotecode;
                    v_continue := -1;
                    _rc := 1;
                  ELSE
                    SELECT r.return_value, r.qty INTO v_rt_code, v_currqty FROM dbo.sp_getitemstockbatch(gcode => v_gcode, icode => v_icode, batch => v_batch, expiry => v_expiry, qty => v_currqty) AS r;
                    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                      v_continue := -1;
                      _rc := 1;
                    ELSE
                      v_newqty := (v_currqty + v_givenqty);
                      _rc := 1;
                      SELECT r.return_value INTO v_rt_code FROM dbo.sp_updateitemstockbatch(gcode => v_gcode, icode => v_icode, batch => v_batch, expiry => v_expiry, newqty => v_newqty) AS r;
                      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                        v_continue := -1;
                        _rc := 1;
                      END IF;
                    END IF;
                  END IF;
                END IF;
              ELSE
                RAISE EXCEPTION '%', v_errtext;
                v_continue := -1;
                _rc := 1;
              END IF;
              FETCH NEXT FROM cur_cursor_items INTO v_icode, v_gcode, v_batch, v_expiry, v_totalpieces, v_givenqty, v_packunits, v_purprice, v_saleprice, v_recentpurprice, v_price, v_rowid;
              IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
            END LOOP;
          END IF;
        END IF;
      END IF;
    END IF;
  END IF;
  CLOSE cur_cursor_items;
  -- DEALLOCATE Cursor_Items
  IF (v_continue <> 0) THEN
    return_value := -1;
    receiptinvcode := v_receiptinvcode;
    RETURN;
  ELSE
    return_value := 0;
    receiptinvcode := v_receiptinvcode;
    RETURN;
  END IF;
  return_value := 0;
  receiptinvcode := v_receiptinvcode;
  RETURN;
END
$body$;

-- ==== proc sp_GenerateSale_From_PreSales ====
CREATE OR REPLACE FUNCTION dbo.sp_generatesale_from_presales(presaleinvcode integer, usercode smallint, INOUT newsaleinvcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_presaleinvcode integer;
  v_usercode smallint;
  v_newsaleinvcode integer;
  v_module integer;
  v_headerinvno integer;
  v_continue integer;
  v_rt_code integer;
  v_err integer;
  v_totalrows integer;
  v_rowcount integer;
  v_counter integer;
  v_saleinvcode integer;
  v_headerinvcode integer;
  v_saleprice numeric(12,2);
  v_rate numeric(12,2);
  v_discperc numeric(5,2);
  v_itemflatdisc numeric(15,2);
  v_unitsalestax numeric(12,2);
  v_gstperc1 numeric(6,2);
  v_gstperc2 numeric(6,2);
  v_hold_avgprice numeric(15,5);
  v_icode integer;
  v_gcode integer;
  v_packunits integer;
  v_totalstock numeric(15,4);
  v_totalqty numeric(15,4);
  v_looseqty numeric(15,4);
  v_bonusqty numeric(15,4);
  v_totalbatchqty numeric(15,4);
  v_delqty numeric(15,4);
  v_currqty numeric(15,4);
  v_newqty numeric(15,4);
  v_balancestock numeric(15,4);
  v_batch citext;
  v_itemname citext;
  v_expiry timestamp(3);
  v_serverdate timestamp(3);
  v_saleutn bigint;
  v_custcode smallint;
  v_itemdescription citext;
  v_headerno integer;
  v_machinename citext;
  v_rowgroup integer;
  v_innercounter integer;
  _r1 record;
  _r2 record;
  _rc integer;
BEGIN
  v_presaleinvcode := presaleinvcode;
  v_usercode := usercode;
  v_newsaleinvcode := newsaleinvcode;
  v_custcode := coalesce((SELECT custcode FROM dbo.presaleheader WHERE (presaleinvcode = v_presaleinvcode)), 19);
  _rc := 1;
  v_headerno := 1;
  _rc := 1;
  v_module := (SELECT module FROM dbo.module WHERE (name = 'Sales'));
  _rc := 1;
  v_serverdate := localtimestamp(3);
  _rc := 1;
  v_machinename := left(current_setting('cluster_name', true), 15);
  _rc := 1;
  DROP TABLE IF EXISTS tmp_saletemp;
  CREATE TEMP TABLE tmp_saletemp (
    id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    icode integer,
    gcode smallint,
    batch citext,
    expiry timestamp(3),
    looseqty integer,
    bonusqty integer,
    saleprice numeric(12,2),
    discperc numeric(8,2),
    itemflatdisc numeric(12,2),
    unitsalestax numeric(12,2),
    gstperc numeric(6,2),
    itemdescription citext
) ON COMMIT DROP;
  INSERT INTO tmp_saletemp (icode, gcode, batch, expiry, looseqty, bonusqty, saleprice, discperc, itemflatdisc, unitsalestax, gstperc, itemdescription) SELECT icode, gcode, batch, expiry, trunc(qty)::integer, 0, saleprice, discperc, 0 AS itemflatdisc, 0 AS unitsalestax, 0 AS gstperc, itemdescription FROM dbo.presaledetail WHERE ((presaleinvcode = v_presaleinvcode) AND (((qty + bonusqty)) > 0)) ORDER BY rowid;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_totalrows := coalesce((SELECT count(*) FROM tmp_saletemp AS saletemp), 0);
  _rc := 1;
  v_continue := 0;
  _rc := 1;
  v_rowgroup := 0;
  _rc := 1;
  IF ((v_totalrows > 0) AND (v_continue >= 0)) THEN
    SELECT r.return_value, r.key INTO v_rt_code, v_saleinvcode FROM dbo.sp_gettabmaxkey(tabname => 'Saleledger', key => v_saleinvcode) AS r;
    v_rowgroup := 0;
    _rc := 1;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      v_continue := -1;
      _rc := 1;
    END IF;
    v_newsaleinvcode := v_saleinvcode;
    _rc := 1;
    IF (v_continue >= 0) THEN
      SELECT r.return_value, r.key INTO v_rt_code, v_headerinvno FROM dbo.sp_getheadertabmaxkey(headercode => (v_headerno)::smallint, modulecode => (v_module)::smallint, key => v_headerinvno) AS r;
      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
        v_continue := -1;
        _rc := 1;
      END IF;
    END IF;
    IF (v_continue >= 0) THEN
      v_err := 0;
      _rc := 1;
      v_rowcount := 1;
      _rc := 1;
      INSERT INTO dbo.saleledger (saleinvcode, salecatcode, custcode, salesmancode, date, discperc, flatdisc, misccharges, salestax, posted, postdate, remarks, custrefno, headerno, headerinvno, originaldate, modifiedby, postedby, sprice, quotationno, doctcode, patientcode, reprintingcounter, cashreceived, invgstperc1, printwaranty, printbatch, messagecode, smancode, invoicesize, custrefno2, custrefno3, custrefno4, gstno, invtotal, machinename, modifycounter, itemdiscpercno, relationcode, diseasecode, wardcode, admissioncode, returncounter, paid, billingdate, unreceivedbalance, totalofsalereturns, listofsrinvoices, printbalance, accountfor, paymentmode, paymentacccode, amt, amtby, amtdate, amtreference, outstandingamt, marked, transferable, transfered, transferedon, transferedby, imported, importedby, deliveredby, saletypecode, balance, pptcustcode, deleted, prescode, impactinventory, saleordercode, salecomments1, salecomments2, altersaleinvcode, recurringinvoice, recurringperiod, lastrecurringinvcode, recurringagainst, considerinpo, visitcode, duedate, srbufferinvcode, custrefno5, suppinvcode, grn, gccode, vehicle, shipto) SELECT v_saleinvcode, 2 AS salecatcode, v_custcode, v_usercode, localtimestamp(3) AS date, 0 AS discperc, 0 AS flatdisc, 0 AS misccharges, 0 AS salestax, 'Y' AS posted, localtimestamp(3) AS postdate, remarks, custrefno, v_headerno, v_headerinvcode, localtimestamp(3) AS date, NULL::smallint AS modifiedby, v_usercode AS postedby, 1 AS sprice, NULL::integer AS quotationcode, NULL::smallint AS doctcode, NULL::integer AS patientcode, 0 AS reprintingcounter, 0 AS cashreceived, 0 AS invgstperc1, 'N' AS printwaranty, 'N' AS printbatch, 1 AS messagecode, NULL::smallint AS smancode, 'F' AS invoicesize, custrefno2, custrefno3, custrefno4, 1 AS gstno, 0 AS invtotal, v_machinename, NULL::smallint AS modifycounter, 1 AS itemdiscpercno, NULL::smallint AS relationcode, NULL::smallint AS diseasecode, NULL::smallint AS wardcode, NULL::integer AS admissioncode, 0 AS returncounter, 'N' AS paid, orderdate AS billingdate, 0 AS unreceivedbalance, 0 AS totalofsalereturns, '', 'Y', 'Y', 'C' AS paymentmode, 2 AS paymentacccode, 0 AS amt, NULL::smallint AS amtby, localtimestamp(3) AS amtdate, NULL::citext AS amtreference, 0 AS outstandingamt, 'N' AS marked, 'N' AS transferable, 'N' AS transfered, NULL::timestamp(3) AS transferedon, NULL::smallint AS transferedby, 'N' AS imported, NULL::smallint AS importedby, NULL::smallint AS deliveredby, 1 AS saletypeode, 0 AS balance, NULL::smallint AS pptcustcode, 'N' AS deleted, NULL::integer AS prescode, 'Y' AS impactinventory, NULL::integer AS saleordercode, (SELECT dbo.fn_getpreference('SaleComments1') AS a) AS salecomments1, (SELECT dbo.fn_getpreference('SaleComments2') AS a) AS salecomments2, NULL::integer AS altersaleinvcode, 'N' AS recurringinvoice, 0 AS recurringperiod, NULL::integer AS lastrecurringinvcode, NULL::integer AS recurringagainst, 'Y' AS considerinpo, NULL::integer AS visitcode, localtimestamp(3) AS duedate, NULL::integer AS srbufferinvcode, NULL::citext AS custrefno5, NULL::citext AS suppinvcode, NULL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto FROM dbo.presaleheader WHERE (presaleinvcode = v_presaleinvcode);
      GET DIAGNOSTICS _rc = ROW_COUNT;
      v_err := 0;
      v_rowcount := _rc;
      _rc := 1;
      IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
        RAISE EXCEPTION 'Error occured in inserting record into Sale Ledger : %', v_saleinvcode;
        v_continue := -1;
        _rc := 1;
      ELSE
        v_innercounter := 1;
        _rc := 1;
        WHILE (((v_innercounter <= v_totalrows)) AND ((v_continue >= 0))) LOOP
          _rc := 0;
          FOR _r1 IN SELECT icode AS c1, gcode AS c2, batch AS c3, expiry AS c4, looseqty AS c5, bonusqty AS c6, saleprice AS c7, discperc AS c8, itemflatdisc AS c9, unitsalestax AS c10, gstperc AS c11, itemdescription AS c12 FROM tmp_saletemp AS saletemp WHERE (id = v_innercounter) LOOP
            _rc := _rc + 1;
            v_icode := _r1.c1;
            v_gcode := _r1.c2;
            v_batch := _r1.c3;
            v_expiry := _r1.c4;
            v_looseqty := _r1.c5;
            v_bonusqty := _r1.c6;
            v_saleprice := _r1.c7;
            v_discperc := _r1.c8;
            v_itemflatdisc := _r1.c9;
            v_unitsalestax := _r1.c10;
            v_gstperc1 := _r1.c11;
            v_itemdescription := _r1.c12;
          END LOOP;
          v_err := 0;
          v_rowcount := _rc;
          _rc := 1;
          v_totalqty := (v_looseqty + v_bonusqty);
          _rc := 1;
          IF (((v_totalqty > 0) AND (v_rowcount > 0)) AND (v_err = 0)) THEN
            SELECT r.return_value, r.avgprice INTO v_rt_code, v_hold_avgprice FROM dbo.sp_getitemavgprice(icode => v_icode, avgprice => v_hold_avgprice) AS r;
            IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
              v_continue := -1;
              _rc := 1;
            ELSE
              v_totalstock := (SELECT coalesce(sum(currqty), 0) FROM dbo.godowndetail WHERE ((godowndetail.gcode = v_gcode) AND (godowndetail.icode = v_icode)));
              _rc := 1;
              v_totalbatchqty := (SELECT coalesce(sum(currqty), 0) FROM dbo.godowndetail WHERE ((((godowndetail.gcode = v_gcode) AND (godowndetail.icode = v_icode)) AND (godowndetail.batch = v_batch)) AND (godowndetail.expiry = v_expiry)));
              _rc := 1;
              IF (v_totalbatchqty >= v_totalqty) THEN
                v_newqty := (v_totalbatchqty - v_totalqty);
                _rc := 1;
                IF (v_newqty > 0) THEN
                  SELECT r.return_value INTO v_rt_code FROM dbo.sp_saleupdateitemstockbatch(gcode => v_gcode, icode => v_icode, batch => v_batch, expiry => v_expiry, newqty => v_newqty, oldqty => v_totalbatchqty) AS r;
                ELSE
                  SELECT r.return_value INTO v_rt_code FROM dbo.sp_deleteitemstockbatch(gcode => v_gcode, icode => v_icode, batch => v_batch, expiry => v_expiry, oldqty => v_totalqty) AS r;
                END IF;
                IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                  v_continue := -1;
                  _rc := 1;
                ELSE
                  v_rowgroup := (v_rowgroup + 1);
                  _rc := 1;
                  _rc := 0;
                  FOR _r2 IN SELECT saleprice AS c1, packunits AS c2 FROM dbo.item WHERE (icode = v_icode) LOOP
                    _rc := _rc + 1;
                    v_rate := _r2.c1;
                    v_packunits := _r2.c2;
                  END LOOP;
                  IF ((v_packunits = 0) OR (v_packunits IS NULL)) THEN
                    v_packunits := 1;
                    _rc := 1;
                  END IF;
                  SELECT r.return_value, r.lbi_maxutn INTO v_rt_code, v_saleutn FROM dbo.sp_maxutn(lbi_rows => (1)::bigint, lbi_maxutn => v_saleutn) AS r;
                  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                    v_continue := -1;
                    _rc := 1;
                  ELSE
                    INSERT INTO dbo.saledetail (saleinvcode, icode, gcode, batch, expiry, packqty, looseqty, bonusqty, packunits, saleprice, avgprice, rate, discperc, salestax, itemflatdisc, packprice, unitsalestax, gstperc, saleutn, balancestock, rowgroup, saleitemdescription) VALUES (v_saleinvcode, v_icode, v_gcode, v_batch, v_expiry, 0, v_looseqty, v_bonusqty, v_packunits, v_saleprice, v_hold_avgprice, (v_rate / v_packunits), v_discperc, 0, v_itemflatdisc, v_rate, v_unitsalestax, v_gstperc1, v_saleutn, 0, v_rowgroup, v_itemdescription);
                    GET DIAGNOSTICS _rc = ROW_COUNT;
                    v_err := 0;
                    v_rowcount := _rc;
                    _rc := 1;
                    IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
                      RAISE EXCEPTION 'Error occured in inserting record into Sale Detail for Sale Inv. No. : %', v_saleinvcode;
                      v_continue := -1;
                      _rc := 1;
                    END IF;
                  END IF;
                END IF;
              ELSE
                v_itemname := (SELECT name FROM dbo.item WHERE (icode = v_icode));
                _rc := 1;
                RAISE EXCEPTION 'Not enough stock for item (%) to decrease for Sale Inv. No : %', v_itemname, v_saleinvcode;
                v_continue := -1;
                _rc := 1;
              END IF;
            END IF;
          END IF;
          v_innercounter := (v_innercounter + 1);
          _rc := 1;
        END LOOP;
        IF (((v_continue >= 0)) AND (v_innercounter > v_totalrows)) THEN
          UPDATE dbo.saleledger SET invtotal = coalesce(dbo.fn_getsaleinvtotal((saleledger.saleinvcode)::integer), 0), outstandingamt = coalesce(dbo.fn_getsaleinvtotal((saleledger.saleinvcode)::integer), 0) WHERE (saleinvcode = v_saleinvcode);
          GET DIAGNOSTICS _rc = ROW_COUNT;
          v_err := 0;
          v_rowcount := _rc;
          _rc := 1;
          IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
            RAISE EXCEPTION 'Unable to update Sale Inv. total for Sale Invoice %', 1;
            v_continue := -1;
            _rc := 1;
          END IF;
          IF ((v_continue >= 0)) THEN
            UPDATE dbo.presaleheader SET posted = 'Y', postdate = localtimestamp(3), postedby = v_usercode, saleinvcode = v_saleinvcode WHERE (presaleinvcode = v_presaleinvcode);
            GET DIAGNOSTICS _rc = ROW_COUNT;
            v_err := 0;
            v_rowcount := _rc;
            _rc := 1;
            IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
              RAISE EXCEPTION 'Unable to update Sale Order Status (Inv. No. %)', 1;
              v_continue := -1;
              _rc := 1;
            END IF;
          END IF;
        END IF;
      END IF;
    END IF;
  END IF;
  DROP TABLE IF EXISTS tmp_saletemp;
  return_value := v_continue;
  newsaleinvcode := v_newsaleinvcode;
  RETURN;
  return_value := 0;
  newsaleinvcode := v_newsaleinvcode;
  RETURN;
END
$body$;

-- ==== proc sp_GenerateSale_From_SaleOrder ====
CREATE OR REPLACE FUNCTION dbo.sp_generatesale_from_saleorder(saleordercode integer, usercode smallint, INOUT newsaleinvcode integer, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_saleordercode integer;
  v_usercode smallint;
  v_newsaleinvcode integer;
  v_module integer;
  v_custcode integer;
  v_saletypecode smallint;
  v_salecatcode integer;
  v_headerinvno integer;
  v_continue integer;
  v_rt_code integer;
  v_err integer;
  v_totalrows integer;
  v_rowcount integer;
  v_invcounter integer;
  v_counter integer;
  v_saleinvcode integer;
  v_looseqty numeric(15,4);
  v_satisfiableqty numeric(15,4);
  v_satisfiedqty numeric(15,4);
  v_itemadvancetaxperc numeric(5,2);
  v_saleprice numeric(12,2);
  v_rate numeric(12,2);
  v_discperc numeric(5,2);
  v_claimable citext;
  v_claimablediscperc numeric(6,2);
  v_itemflatdisc numeric(12,2);
  v_unitsalestax numeric(12,2);
  v_gstperc1 numeric(6,2);
  v_gstperc2 numeric(6,2);
  v_hold_avgprice numeric(15,5);
  v_icode integer;
  v_anyitem_exist integer;
  v_packunits integer;
  v_finalized citext;
  v_posted citext;
  v_totalqty numeric(15,4);
  v_givenqty numeric(15,4);
  v_reqqty numeric(15,4);
  v_batchqty numeric(15,4);
  v_delqty numeric(15,4);
  v_currqty numeric(15,4);
  v_newqty numeric(15,4);
  v_total_availablestock numeric(15,4);
  v_batch citext;
  v_itemname citext;
  v_expiry timestamp(3);
  v_serverdate timestamp(3);
  v_machinename citext;
  v_saleutn bigint;
  v_firsttime smallint;
  v_headerno smallint;
  v_gcode smallint;
  v_socatcode smallint;
  v_saleorder_rowcount integer;
  v_invdetail_exist integer;
  v_rowgroup integer;
  v_lineitems_rowcount integer;
  v_innercounter integer;
  v_saleitemdescription citext;
  _r1 record;
  _r2 record;
  cur_itembatch_cursor refcursor;
  _rc integer;
  _fs integer := -1;
BEGIN
  v_saleordercode := saleordercode;
  v_usercode := usercode;
  v_newsaleinvcode := newsaleinvcode;
  v_posted := coalesce((SELECT posted FROM dbo.saleorderheader WHERE (saleordercode = v_saleordercode)), 'N');
  _rc := 1;
  IF (v_posted = 'Y') THEN
    RAISE EXCEPTION 'Sale Order is Already Posted, Can not post again.';
    return_value := -1;
    newsaleinvcode := v_newsaleinvcode;
    RETURN;
  END IF;
  v_firsttime := 0;
  _rc := 1;
  v_custcode := 19;
  _rc := 1;
  v_salecatcode := 3;
  _rc := 1;
  v_saletypecode := 2;
  _rc := 1;
  v_module := (SELECT module FROM dbo.module WHERE (name = 'Sales'));
  _rc := 1;
  v_serverdate := localtimestamp(3);
  _rc := 1;
  v_socatcode := coalesce((SELECT socatcode FROM dbo.saleorderheader WHERE (saleordercode = v_saleordercode)), 1);
  _rc := 1;
  DROP TABLE IF EXISTS tmp_saletemp;
  CREATE TEMP TABLE tmp_saletemp (
    id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    icode integer,
    gcode smallint,
    looseqty numeric(15,4),
    satisfiableqty numeric(15,4),
    satisfiedqty numeric(15,4),
    saleprice numeric(12,2),
    discperc numeric(8,2),
    claimable citext,
    claimablediscperc numeric(8,2),
    itemflatdisc numeric(12,2),
    unitsalestax numeric(12,2),
    gstperc numeric(6,2),
    saleitemdescription citext,
    itemadvancetaxperc numeric(5,2),
    rowid integer
) ON COMMIT DROP;
  INSERT INTO tmp_saletemp (icode, gcode, looseqty, satisfiableqty, satisfiedqty, saleprice, discperc, claimable, claimablediscperc, itemflatdisc, unitsalestax, gstperc, saleitemdescription, itemadvancetaxperc, rowid) SELECT icode, gcode, sum(looseqty), sum(looseqty), 0, max(saleprice), max(discperc), max(claimable), max(claimablediscperc), max(itemflatdisc), max(unitsalestax), max(gstperc), saleitemdescription, max(itemadvancetaxperc), max(rowid) AS rowid FROM dbo.saleorderdetail WHERE (saleordercode = v_saleordercode) GROUP BY icode, gcode, saleitemdescription ORDER BY rowid;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_saleorder_rowcount := ((SELECT count(icode) FROM dbo.saleorderdetail WHERE (saleordercode = v_saleordercode)) + 1);
  _rc := 1;
  v_anyitem_exist := trunc((SELECT sum((satisfiableqty - satisfiedqty)) FROM tmp_saletemp AS saletemp))::integer;
  _rc := 1;
  v_continue := 0;
  _rc := 1;
  v_invcounter := 1;
  _rc := 1;
  v_invdetail_exist := 1;
  _rc := 1;
  v_rowgroup := 0;
  _rc := 1;
  v_headerno := (SELECT headerno FROM dbo.saleorderheader WHERE (saleordercode = v_saleordercode));
  _rc := 1;
  WHILE ((v_anyitem_exist > 0) AND (v_continue >= 0)) LOOP
    IF (v_invdetail_exist > 0) THEN
      SELECT r.return_value, r.key INTO v_rt_code, v_saleinvcode FROM dbo.sp_gettabmaxkey(tabname => 'Saleledger', key => v_saleinvcode) AS r;
    END IF;
    IF ((v_firsttime = 0)) THEN
      v_firsttime := 1;
      _rc := 1;
    END IF;
    v_rowgroup := 0;
    _rc := 1;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      v_continue := -1;
      _rc := 1;
    ELSE
      IF (v_invdetail_exist > 0) THEN
        SELECT r.return_value, r.key INTO v_rt_code, v_headerinvno FROM dbo.sp_getheadertabmaxkey(headercode => v_headerno, modulecode => (v_module)::smallint, key => v_headerinvno) AS r;
      END IF;
      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
        v_continue := -1;
        _rc := 1;
      ELSE
        v_err := 0;
        _rc := 1;
        v_rowcount := 1;
        _rc := 1;
        IF (v_invdetail_exist > 0) THEN
          INSERT INTO dbo.saleledger (saleinvcode, salecatcode, custcode, salesmancode, date, discperc, flatdisc, misccharges, salestax, posted, postdate, remarks, custrefno, headerno, headerinvno, originaldate, modifiedby, postedby, sprice, quotationno, doctcode, patientcode, reprintingcounter, cashreceived, invgstperc1, printwaranty, printbatch, messagecode, smancode, invoicesize, custrefno2, custrefno3, custrefno4, gstno, invtotal, machinename, modifycounter, itemdiscpercno, relationcode, diseasecode, wardcode, admissioncode, returncounter, paid, billingdate, unreceivedbalance, totalofsalereturns, listofsrinvoices, printbalance, accountfor, paymentmode, paymentacccode, amt, amtby, amtdate, amtreference, outstandingamt, marked, transferable, transfered, transferedon, transferedby, imported, importedby, deliveredby, saletypecode, balance, pptcustcode, deleted, prescode, impactinventory, saleordercode, salecomments1, salecomments2, altersaleinvcode, recurringinvoice, recurringperiod, lastrecurringinvcode, recurringagainst, considerinpo, visitcode, duedate, srbufferinvcode, custrefno5, suppinvcode, grn, gccode, vehicle, shipto, advancetax, advancetaxamt, misccharges1, misccharges2, misccharges3, misccharges4, misccharges5, fbrposfee) SELECT v_saleinvcode, 2 AS salecatcode, custcode, usercode, localtimestamp(3) AS date, discperc, flatdisc, misccharges, 0 AS salestax, 'N' AS posted, localtimestamp(3) AS postdate, remarks, custrefno, v_headerno, v_headerinvno, localtimestamp(3) AS date, modifiedby, postedby, 1 AS sprice, quotationcode, doctcode, patientcode, reprintingcounter, 0 AS cashreceived, invgstperc1, 'N' AS printwaranty, 'N' AS printbatch, messagecode, smancode, invoicesize, custrefno2, custrefno3, custrefno4, gstno, invtotal, machinename, modifycounter, itemdiscpercno, relationcode, diseasecode, wardcode, NULL::integer AS admissioncode, 0 AS returncounter, 'N' AS paid, billingdate, invtotal AS unreceivedbalance, 0 AS totalofsalereturns, '', 'Y', 'Y', 'C' AS paymentmode, 2 AS paymentacccode, 0 AS amt, NULL::smallint AS amtby, localtimestamp(3) AS amtdate, NULL::citext AS amtreference, invtotal AS outstandingamt, 'N' AS marked, 'N' AS transferable, 'N' AS transfered, NULL::timestamp(3) AS transferedon, NULL::smallint AS transferedby, 'N' AS imported, NULL::smallint AS importedby, NULL::smallint AS deliveredby, 1 AS saletypeode, 0 AS balance, pptcustcode, 'N' AS deleted, prescode, 'Y' AS impactinventory, saleordercode, (SELECT dbo.fn_getpreference('SaleComments1') AS a) AS salecomments1, (SELECT dbo.fn_getpreference('SaleComments2') AS a) AS salecomments2, NULL::integer AS altersaleinvcode, 'N' AS recurringinvoice, 0 AS recurringperiod, NULL::integer AS lastrecurringinvcode, NULL::integer AS recurringagainst, 'Y' AS considerinpo, NULL::integer AS visitcode, localtimestamp(3) AS duedate, NULL::integer AS srbufferinvcode, NULL::citext AS custrefno5, suppinvcode, grn, gccode, vehicle, shipto, advancetax, advancetaxamt, misccharges1, misccharges2, misccharges3, misccharges4, misccharges5, fbrposfee FROM dbo.saleorderheader WHERE (saleordercode = v_saleordercode);
          GET DIAGNOSTICS _rc = ROW_COUNT;
          v_err := 0;
          v_rowcount := _rc;
          _rc := 1;
        END IF;
        IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
          RAISE EXCEPTION 'Error occured in inserting record into Sale Ledger : %', v_saleinvcode;
          v_continue := -1;
          _rc := 1;
        ELSE
          v_anyitem_exist := trunc((SELECT sum((satisfiableqty - satisfiedqty)) FROM tmp_saletemp AS saletemp))::integer;
          _rc := 1;
          v_lineitems_rowcount := (SELECT count(*) FROM tmp_saletemp AS saletemp);
          _rc := 1;
          v_innercounter := 1;
          _rc := 1;
          WHILE ((((v_anyitem_exist > 0)) AND ((v_innercounter <= v_lineitems_rowcount))) AND ((v_continue >= 0))) LOOP
            _rc := 0;
            FOR _r1 IN SELECT icode AS c1, gcode AS c2, looseqty AS c3, satisfiableqty AS c4, satisfiedqty AS c5, saleprice AS c6, discperc AS c7, itemflatdisc AS c8, unitsalestax AS c9, gstperc AS c10, saleitemdescription AS c11, claimable AS c12, claimablediscperc AS c13, itemadvancetaxperc AS c14 FROM tmp_saletemp AS saletemp WHERE (id = v_innercounter) LOOP
              _rc := _rc + 1;
              v_icode := _r1.c1;
              v_gcode := _r1.c2;
              v_looseqty := _r1.c3;
              v_satisfiableqty := _r1.c4;
              v_satisfiedqty := _r1.c5;
              v_saleprice := _r1.c6;
              v_discperc := _r1.c7;
              v_itemflatdisc := _r1.c8;
              v_unitsalestax := _r1.c9;
              v_gstperc1 := _r1.c10;
              v_saleitemdescription := _r1.c11;
              v_claimable := _r1.c12;
              v_claimablediscperc := _r1.c13;
              v_itemadvancetaxperc := _r1.c14;
            END LOOP;
            v_rowcount := _rc;
            _rc := 1;
            IF (((v_rowcount = 1)) AND ((((v_satisfiableqty - v_satisfiedqty)) > 0))) THEN
              IF (((v_looseqty + v_satisfiedqty)) <= v_satisfiableqty) THEN
                v_givenqty := v_looseqty;
                _rc := 1;
              ELSE
                v_givenqty := (v_satisfiableqty - v_satisfiedqty);
                _rc := 1;
              END IF;
              IF (v_givenqty <= 0) THEN
                v_givenqty := 1;
                _rc := 1;
              ELSE
                UPDATE tmp_saletemp AS saletemp SET satisfiedqty = (v_satisfiedqty + v_givenqty) WHERE (icode = v_icode);
                GET DIAGNOSTICS _rc = ROW_COUNT;
              END IF;
              SELECT r.return_value, r.avgprice INTO v_rt_code, v_hold_avgprice FROM dbo.sp_getitemavgprice(icode => v_icode, avgprice => v_hold_avgprice) AS r;
              IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                v_continue := -1;
                _rc := 1;
              ELSE
                SELECT r.return_value, r.qty INTO v_rt_code, v_total_availablestock FROM dbo.sp_getitemstockall(icode => v_icode, qty => v_total_availablestock) AS r;
                v_totalqty := (SELECT coalesce(sum(currqty), 0) FROM dbo.godowndetail WHERE ((godowndetail.gcode = v_gcode) AND (godowndetail.icode = v_icode)));
                _rc := 1;
                IF (v_totalqty >= v_givenqty) THEN
                  v_rowgroup := (v_rowgroup + 1);
                  _rc := 1;
                  _rc := 0;
                  FOR _r2 IN SELECT saleprice AS c1, packunits AS c2 FROM dbo.item WHERE (icode = v_icode) LOOP
                    _rc := _rc + 1;
                    v_rate := _r2.c1;
                    v_packunits := _r2.c2;
                  END LOOP;
                  IF ((v_packunits = 0) OR (v_packunits IS NULL)) THEN
                    v_packunits := 1;
                    _rc := 1;
                  END IF;
                  v_reqqty := v_givenqty;
                  _rc := 1;
                  OPEN cur_itembatch_cursor FOR SELECT batch, expiry, currqty FROM dbo.godowndetail WHERE ((godowndetail.gcode = v_gcode) AND (godowndetail.icode = v_icode)) ORDER BY priority, expiry, currqty;
                  v_totalrows := (-1);
                  _rc := 1;
                  FETCH NEXT FROM cur_itembatch_cursor INTO v_batch, v_expiry, v_currqty;
                  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
                  v_counter := 1;
                  _rc := 1;
                  WHILE (((_fs = 0) AND (v_counter <= v_totalrows)) AND (v_reqqty > 0)) LOOP
                    v_batchqty := v_currqty;
                    _rc := 1;
                    IF (v_batchqty >= v_reqqty) THEN
                      v_delqty := v_reqqty;
                      _rc := 1;
                    ELSE
                      v_delqty := v_batchqty;
                      _rc := 1;
                    END IF;
                    v_reqqty := (v_reqqty - v_delqty);
                    _rc := 1;
                    SELECT r.return_value, r.lbi_maxutn INTO v_rt_code, v_saleutn FROM dbo.sp_maxutn(lbi_rows => (1)::bigint, lbi_maxutn => v_saleutn) AS r;
                    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                      v_continue := -1;
                      _rc := 1;
                    END IF;
                    v_total_availablestock := (v_total_availablestock - v_delqty);
                    _rc := 1;
                    INSERT INTO dbo.saledetail (saleinvcode, icode, gcode, batch, expiry, packqty, looseqty, packunits, saleprice, avgprice, rate, discperc, salestax, itemflatdisc, packprice, unitsalestax, gstperc, saleutn, balancestock, rowgroup, saleitemdescription, claimable, claimablediscperc, itemadvancetaxperc) VALUES (v_saleinvcode, v_icode, v_gcode, v_batch, v_expiry, 0, v_delqty, v_packunits, v_saleprice, v_hold_avgprice, (v_rate / v_packunits), v_discperc, 0, v_itemflatdisc, v_rate, v_unitsalestax, v_gstperc1, v_saleutn, v_total_availablestock, v_rowgroup, v_saleitemdescription, v_claimable, v_claimablediscperc, v_itemadvancetaxperc);
                    GET DIAGNOSTICS _rc = ROW_COUNT;
                    v_err := 0;
                    v_rowcount := _rc;
                    _rc := 1;
                    IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
                      RAISE EXCEPTION 'Error occured in inserting record into Sale Detail for Sale Inv. No. : %', v_saleinvcode;
                      v_continue := -1;
                      _rc := 1;
                    ELSE
                      v_newqty := (v_currqty - v_delqty);
                      _rc := 1;
                      IF (v_newqty > 0) THEN
                        SELECT r.return_value INTO v_rt_code FROM dbo.sp_saleupdateitemstockbatch(gcode => (v_gcode)::integer, icode => v_icode, batch => v_batch, expiry => v_expiry, newqty => v_newqty, oldqty => v_currqty) AS r;
                      ELSE
                        SELECT r.return_value INTO v_rt_code FROM dbo.sp_deleteitemstockbatch(gcode => (v_gcode)::integer, icode => v_icode, batch => v_batch, expiry => v_expiry, oldqty => v_delqty) AS r;
                      END IF;
                      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                        v_continue := -1;
                        _rc := 1;
                      END IF;
                    END IF;
                    v_counter := (v_counter + 1);
                    _rc := 1;
                    FETCH NEXT FROM cur_itembatch_cursor INTO v_batch, v_expiry, v_currqty;
                    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
                  END LOOP;
                  CLOSE cur_itembatch_cursor;
                  -- DEALLOCATE ItemBatch_Cursor
                ELSE
                  v_itemname := (SELECT name FROM dbo.item WHERE (icode = v_icode));
                  _rc := 1;
                  RAISE EXCEPTION 'Not enough stock for item (%) to decrease for Sale Inv. No : %', v_itemname, v_saleinvcode;
                  v_continue := -1;
                  _rc := 1;
                END IF;
              END IF;
            END IF;
            v_innercounter := (v_innercounter + 1);
            _rc := 1;
            v_anyitem_exist := trunc((SELECT sum((satisfiableqty - satisfiedqty)) FROM tmp_saletemp AS saletemp))::integer;
            _rc := 1;
          END LOOP;
          v_invdetail_exist := (SELECT count(*) FROM dbo.saledetail WHERE (saleinvcode = v_saleinvcode));
          _rc := 1;
        END IF;
      END IF;
    END IF;
    v_anyitem_exist := trunc((SELECT sum((satisfiableqty - satisfiedqty)) FROM tmp_saletemp AS saletemp))::integer;
    _rc := 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_saletemp;
  IF ((v_continue >= 0)) THEN
    UPDATE dbo.saleledger SET invtotal = dbo.fn_getsaleinvtotal((saleledger.saleinvcode)::integer) WHERE (saleinvcode = v_saleinvcode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_err := 0;
    v_rowcount := _rc;
    _rc := 1;
    IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
      RAISE EXCEPTION 'Unable to update Sale Invoice for Sale Inv. %', v_saleinvcode;
      v_continue := -1;
      _rc := 1;
    END IF;
    IF ((v_continue >= 0)) THEN
      UPDATE dbo.saleorderheader SET finalized = 'Y', status = 'COMPLETED' WHERE (saleordercode = v_saleordercode);
      GET DIAGNOSTICS _rc = ROW_COUNT;
      SELECT r.return_value, r.rs1 INTO v_rt_code, rs1 FROM dbo.sp_postsaleorder(ai_socatcode => (v_socatcode)::integer, ai_sinvcode => v_saleordercode, ai_linvcode => v_saleordercode, ai_usercode => (v_usercode)::integer, ai_custcode => NULL, ai_oneorall => 1) AS r;
      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
        RAISE EXCEPTION 'Unable to update Sale Order Posting Status (Sale Order No. %)', 1;
        v_continue := -1;
        _rc := 1;
      END IF;
    END IF;
  END IF;
  IF ((v_continue >= 0)) THEN
    v_newsaleinvcode := v_saleinvcode;
    _rc := 1;
  END IF;
  return_value := v_continue;
  newsaleinvcode := v_newsaleinvcode;
  RETURN;
  return_value := 0;
  newsaleinvcode := v_newsaleinvcode;
  RETURN;
END
$body$;

-- ==== proc SP_GenerateServiceTicket ====
CREATE OR REPLACE FUNCTION dbo.sp_generateserviceticket(serviceinvcode integer, usercode smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_serviceinvcode integer;
  v_usercode smallint;
  v_tot_services integer;
  v_tot_tickets integer;
  v_start_ticket integer;
  v_end_ticket integer;
  v_errcode integer;
  v_rowid integer;
  v_in_rowid integer;
  v_in_qty integer;
  v_ticketcode integer;
  v_servicecode integer;
  v_interval integer;
  v_expirydays integer;
  v_posted citext;
  v_date timestamp(3);
  v_expiry timestamp(3);
  v_price numeric(12,2);
  v_discperc numeric(5,2);
  v_method citext;
  _rc integer;
BEGIN
  v_serviceinvcode := serviceinvcode;
  v_usercode := usercode;
  IF ((SELECT dbo.fn_getpreference('genserviceticketonposting')) = 'N') THEN
    return_value := 0;
    RETURN;
  END IF;
  DROP TABLE IF EXISTS tv_sp_generateserviceticket_service_table;
  CREATE TEMP TABLE tv_sp_generateserviceticket_service_table (
    servicecode integer,
    date timestamp(3),
    qty integer,
    expiry timestamp(3),
    price numeric(12,2),
    discperc numeric(5,2),
    rowid integer GENERATED BY DEFAULT AS IDENTITY,
    interval integer,
    expirydays integer
) ON COMMIT DROP;
  IF (v_serviceinvcode IS NULL) THEN
    return_value := 0;
    RETURN;
  END IF;
  IF (v_usercode IS NULL) THEN
    v_usercode := 1;
    _rc := 1;
  END IF;
  v_posted := coalesce((SELECT posted FROM dbo.serviceheader WHERE (serviceinvcode = v_serviceinvcode)), 'N');
  _rc := 1;
  IF ((v_posted = 'N') OR (v_posted IS NULL)) THEN
    return_value := 0;
    RETURN;
  END IF;
  v_method := coalesce((SELECT dbo.fn_getpreference('serviceticketgenerationmethod')), 'Q');
  _rc := 1;
  IF (v_method IS NULL) THEN
    v_method := 'Q';
    _rc := 1;
  END IF;
  v_tot_tickets := trunc(coalesce((SELECT sum(CASE WHEN (v_method = 'S') THEN s.ticketstogenerate ELSE d.qty END) FROM dbo.servicedetail AS d, dbo.service AS s WHERE (((d.serviceinvcode = v_serviceinvcode) AND (d.servicecode = s.servicecode)) AND (s.ticketrequired = 'Y'))), 0))::integer;
  _rc := 1;
  IF (v_tot_tickets = 0) THEN
    return_value := 0;
    RETURN;
  END IF;
  INSERT INTO tv_sp_generateserviceticket_service_table (servicecode, date, qty, expiry, price, discperc, interval, expirydays) SELECT d.servicecode, localtimestamp(3) AS date, CASE WHEN (v_method = 'S') THEN s.ticketstogenerate ELSE trunc(d.qty)::integer END AS qty, d.deliverydate, d.price, d.discperc, CASE WHEN (v_method = 'S') THEN s.ticketintervalindays ELSE 0 END, CASE WHEN (v_method = 'S') THEN ticketexpiryindays ELSE 0 END FROM dbo.servicedetail AS d, dbo.service AS s WHERE (((d.serviceinvcode = v_serviceinvcode) AND (d.servicecode = s.servicecode)) AND (s.ticketrequired = 'Y')) ORDER BY d.srvrowid;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((0 <> 0) OR (_rc = 0)) THEN
    RAISE EXCEPTION 'Problem while Fetching Ticketing Services';
    return_value := -1;
    RETURN;
  END IF;
  v_tot_services := coalesce((SELECT count(*) FROM tv_sp_generateserviceticket_service_table AS service_table), 0);
  _rc := 1;
  IF (v_tot_services = 0) THEN
    return_value := 0;
    RETURN;
  END IF;
  v_errcode := 0;
  _rc := 1;
  SELECT r.return_value, r.key INTO v_errcode, v_start_ticket FROM dbo.sp_locktabmaxkey(tabname => 'ServiceTicket', key => v_start_ticket) AS r;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem while Fetching Service Ticket Key Value';
    return_value := -1;
    RETURN;
  END IF;
  v_rowid := 1;
  _rc := 1;
  WHILE (v_rowid <= v_tot_services) LOOP
    v_in_rowid := 1;
    _rc := 1;
    v_in_qty := (SELECT qty FROM tv_sp_generateserviceticket_service_table AS service_table WHERE (rowid = v_rowid));
    _rc := 1;
    v_servicecode := (SELECT servicecode FROM tv_sp_generateserviceticket_service_table AS service_table WHERE (rowid = v_rowid));
    _rc := 1;
    v_interval := (SELECT interval FROM tv_sp_generateserviceticket_service_table AS service_table WHERE (rowid = v_rowid));
    _rc := 1;
    v_expirydays := (SELECT expirydays FROM tv_sp_generateserviceticket_service_table AS service_table WHERE (rowid = v_rowid));
    _rc := 1;
    v_date := (SELECT date FROM tv_sp_generateserviceticket_service_table AS service_table WHERE (rowid = v_rowid));
    _rc := 1;
    v_expiry := (SELECT CASE WHEN (v_method = 'S') THEN (v_date + (v_expirydays) * interval '1 day') ELSE expiry END FROM tv_sp_generateserviceticket_service_table AS service_table WHERE (rowid = v_rowid));
    _rc := 1;
    v_price := coalesce((SELECT price FROM tv_sp_generateserviceticket_service_table AS service_table WHERE (rowid = v_rowid)), 0);
    _rc := 1;
    v_discperc := coalesce((SELECT discperc FROM tv_sp_generateserviceticket_service_table AS service_table WHERE (rowid = v_rowid)), 0);
    _rc := 1;
    WHILE (v_in_rowid <= v_in_qty) LOOP
      v_ticketcode := (v_start_ticket + v_in_rowid);
      _rc := 1;
      IF (v_in_rowid > 1) THEN
        v_date := (v_date + (v_interval) * interval '1 day');
        _rc := 1;
        v_expiry := (SELECT CASE WHEN (v_method = 'S') THEN (v_date + (v_expirydays) * interval '1 day') ELSE expiry END FROM tv_sp_generateserviceticket_service_table AS service_table WHERE (rowid = v_rowid));
        _rc := 1;
      END IF;
      INSERT INTO dbo.serviceticket (serviceticketcode, date, serviceinvcode, servicecode, price, discperc, expireson, ticketused, ticketusedon, usercode) VALUES (v_ticketcode, v_date, v_serviceinvcode, v_servicecode, v_price, v_discperc, v_expiry, 'N', localtimestamp(3), v_usercode);
      GET DIAGNOSTICS _rc = ROW_COUNT;
      IF ((0 <> 0) OR (_rc = 0)) THEN
        RAISE EXCEPTION 'Problem while Inserting Record in ServiceHeader';
        return_value := -1;
        RETURN;
      END IF;
      v_in_rowid := (v_in_rowid + 1);
      _rc := 1;
    END LOOP;
    v_start_ticket := v_ticketcode;
    _rc := 1;
    v_rowid := (v_rowid + 1);
    _rc := 1;
  END LOOP;
  v_end_ticket := v_ticketcode;
  _rc := 1;
  v_errcode := 0;
  _rc := 1;
  SELECT r.return_value INTO v_errcode FROM dbo.sp_updatetabmaxkey(tabname => 'ServiceTicket', key => v_end_ticket) AS r;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem while Updating Service Ticket Key Value';
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_Get_ItemBatch_CostPrice ====
CREATE OR REPLACE FUNCTION dbo.sp_get_itembatch_costprice(icode integer, batch citext, expiry timestamp, INOUT costprice numeric, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_icode integer;
  v_batch citext;
  v_expiry timestamp(3);
  v_costprice numeric(15,5);
BEGIN
  v_icode := icode;
  v_batch := batch;
