-- ==== proc SP_Get_PreviousSaleHistory ====
CREATE OR REPLACE FUNCTION dbo.sp_get_previoussalehistory(sourcedb citext, targetdb citext, startdate timestamp, enddate timestamp, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_sourcedb citext;
  v_targetdb citext;
  v_startdate timestamp(3);
  v_enddate timestamp(3);
  v_ins_sql citext;
  v_del citext;
  v_err integer;
  _dq1 text;
  _dq2 text;
BEGIN
  v_sourcedb := sourcedb;
  v_targetdb := targetdb;
  v_startdate := startdate;
  v_enddate := enddate;
  v_del := (('TRUNCATE TABLE ' || v_targetdb) || '.DBO.PreviousSaleHistory');
  _dq1 := v_del;
  IF _dq1 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq1);
  END IF;
  v_err := 0;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Deletion Problem While Clearing Previous Sale History';
    return_value := -1;
    RETURN;
  END IF;
  v_ins_sql := (((((((((((((((((((((((((((((((((('INSERT INTO ' || v_targetdb) || '.DBO.PreviousSaleHistory ') || 'SELECT S.Date, S.ICode, SaleQty = SUM(S.SaleQty), ReturnQty = SUM(S.ReturnQty), SaleValue = SUM(S.SaleValue), ReturnValue = SUM(S.ReturnValue) FROM ') || '(SELECT DATE=CONVERT(DATETIME, CONVERT(VARCHAR(100), SL.Date, 110)), ') || 'SD.ICode, SaleQty = SUM(SD.LooseQty + SD.BonusQty), ReturnQty = 0, SaleValue = SUM(SD.LooseQty * (SD.SalePrice - SD.ItemFlatDisc) * (1 - SD.DiscPerc * 0.01) * (1 - SL.DiscPerc * 0.01)), ReturnValue = 0 ') || 'FROM ') || v_sourcedb) || '.DBO.SaleLedger SL, ') || v_sourcedb) || '.DBO.SaleDetail SD WHERE SL.Date BETWEEN ''') || left(to_char(v_startdate, 'MM-DD-YYYY'), 100)) || ' ') || left(to_char(v_startdate, 'HH24:MI:SS:MS'), 100)) || ''' AND ''') || left(to_char(v_enddate, 'MM-DD-YYYY'), 100)) || ' ') || left(to_char(v_enddate, 'HH24:MI:SS:MS'), 100)) || ''' AND ') || ' SL.SaleInvCode = SD.SaleInvCode GROUP BY SL.Date, SD.ICode UNION ALL ') || 'SELECT DATE=CONVERT(DATETIME, CONVERT(VARCHAR(100), SL.Date, 110)), SD.ICode, SaleQty = 0, ReturnQty = SUM(SD.LooseQty + SD.BonusQty), SaleValue=0, ReturnValue = SUM(SD.LooseQty * SD.SRPrice * (1 - SD.DiscPerc * 0.01) * (1 - SL.DiscPerc * 0.01)) FROM ') || v_sourcedb) || '.DBO.SRLedger SL, ') || v_sourcedb) || '.DBO.SRDetail SD WHERE SL.Date BETWEEN ''') || left(to_char(v_startdate, 'MM-DD-YYYY'), 100)) || ' ') || left(to_char(v_startdate, 'HH24:MI:SS:MS'), 100)) || ''' AND ''') || left(to_char(v_enddate, 'MM-DD-YYYY'), 100)) || ' ') || left(to_char(v_enddate, 'HH24:MI:SS:MS'), 100)) || ''' AND ') || ' SL.SRInvCode = SD.SRInvCode ') || 'GROUP BY SL.Date, SD.ICode) S GROUP BY S.Date, S.ICode');
  _dq2 := v_ins_sql;
  IF _dq2 IS NOT NULL THEN
    IF _dq2 ~* '^[[:space:]]*select' THEN OPEN rs1 FOR EXECUTE dbo.tsql_dyn(_dq2); ELSE EXECUTE dbo.tsql_dyn(_dq2); END IF;
  END IF;
  v_err := 0;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Insertion Problem While Storing Previous Sale History';
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_Get_PreviousSaleHistory_OnArchival ====
CREATE OR REPLACE FUNCTION dbo.sp_get_previoussalehistory_onarchival(startdate timestamp, enddate timestamp, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_startdate timestamp(3);
  v_enddate timestamp(3);
  v_err integer;
BEGIN
  v_startdate := startdate;
  v_enddate := enddate;
  INSERT INTO dbo.previoussalehistory SELECT s.date, s.icode, sum(s.saleqty) AS saleqty, sum(s.returnqty) AS returnqty, sum(s.salevalue) AS salevalue, sum(s.returnvalue) AS returnvalue FROM (SELECT (date_trunc('day', sl.date))::timestamp(3) AS date, sd.icode, sum((sd.looseqty + sd.bonusqty)) AS saleqty, 0 AS returnqty, sum((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc))) * ((1 - (sd.discperc * 0.01)))) * ((1 - (sl.discperc * 0.01))))) AS salevalue, 0 AS returnvalue FROM dbo.saleledger AS sl, dbo.saledetail AS sd WHERE ((sl.date BETWEEN v_startdate AND v_enddate) AND (sl.saleinvcode = sd.saleinvcode)) GROUP BY sl.date, sd.icode UNION ALL SELECT (date_trunc('day', sl.date))::timestamp(3) AS date, sd.icode, 0 AS saleqty, sum((sd.looseqty + sd.bonusqty)) AS returnqty, 0 AS salevalue, sum((((sd.looseqty * sd.srprice) * ((1 - (sd.discperc * 0.01)))) * ((1 - (sl.discperc * 0.01))))) AS returnvalue FROM dbo.srledger AS sl, dbo.srdetail AS sd WHERE ((sl.date BETWEEN v_startdate AND v_enddate) AND (sl.srinvcode = sd.srinvcode)) GROUP BY sl.date, sd.icode) AS s GROUP BY s.date, s.icode;
  v_err := 0;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Insertion Problem While Storing Previous Sale History';
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

