-- ==== proc SP_GetAccountLoyaltyBalance ====
CREATE OR REPLACE FUNCTION dbo.sp_getaccountloyaltybalance(acccode integer, balancedate timestamp, INOUT layaltypointsbalance integer, INOUT layaltypointsvalue numeric, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_acccode integer;
  v_balancedate timestamp(3);
  v_layaltypointsbalance integer;
  v_layaltypointsvalue numeric(12,2);
  v_loyaltycardcode integer;
  v_loyaltypolicycode integer;
  v_points integer;
  v_pointsvalue numeric(12,2);
  v_layaltypointsslab integer;
  v_err integer;
  v_rowid integer;
  v_rowcount integer;
  _r1 record;
BEGIN
  v_acccode := acccode;
  v_balancedate := balancedate;
  v_layaltypointsbalance := layaltypointsbalance;
  v_layaltypointsvalue := layaltypointsvalue;
  -- SET NOCOUNT ON
  DROP TABLE IF EXISTS tmp_pointstemp;
  CREATE TEMP TABLE tmp_pointstemp (
    loyaltycardcode integer,
    loyaltypolicycode integer,
    points integer,
    pointsvalue numeric(12,2),
    rowid integer GENERATED BY DEFAULT AS IDENTITY
) ON COMMIT DROP;
  INSERT INTO tmp_pointstemp (loyaltycardcode, loyaltypolicycode, points, pointsvalue) SELECT loyaltycardcode, loyaltypolicycode, 0 AS points, 0 AS pointsvalue FROM dbo.loyaltycard WHERE (acccode = v_acccode);
  v_err := 0;
  IF ((v_err <> 0) OR (0 <> 0)) THEN
    RAISE EXCEPTION 'Problem occured while fetching loyalty card points balance Information, Error Code = %', v_err;
    return_value := -1;
    layaltypointsbalance := v_layaltypointsbalance;
    layaltypointsvalue := v_layaltypointsvalue;
    RETURN;
  END IF;
  v_rowcount := coalesce((SELECT count(*) FROM tmp_pointstemp AS pointstemp), 0);
  IF ((v_rowcount = 0) OR (v_rowcount IS NULL)) THEN
    v_layaltypointsbalance := 0;
    v_layaltypointsvalue := 0;
    return_value := 0;
    layaltypointsbalance := v_layaltypointsbalance;
    layaltypointsvalue := v_layaltypointsvalue;
    RETURN;
  END IF;
  v_rowid := 1;
  WHILE (v_rowid <= v_rowcount) LOOP
    FOR _r1 IN SELECT loyaltycardcode AS c1, loyaltypolicycode AS c2, points AS c3, pointsvalue AS c4 FROM tmp_pointstemp AS pointstemp WHERE (rowid = v_rowid) LOOP
      v_loyaltycardcode := _r1.c1;
      v_loyaltypolicycode := _r1.c2;
      v_points := _r1.c3;
      v_pointsvalue := _r1.c4;
    END LOOP;
    SELECT r.return_value, r.layaltypointsbalance, r.layaltypointsvalue INTO v_err, v_points, v_pointsvalue FROM dbo.sp_getloyaltycardbalance(loyaltycardcode => v_loyaltycardcode, balancedate => v_balancedate, layaltypointsbalance => v_points, layaltypointsvalue => v_pointsvalue) AS r;
    IF ((v_err <> 0) OR (0 <> 0)) THEN
      RAISE EXCEPTION 'Problem occured while fetching loyalty card balance, Loyalty Card Code = %', v_loyaltycardcode;
      return_value := -1;
      layaltypointsbalance := v_layaltypointsbalance;
      layaltypointsvalue := v_layaltypointsvalue;
      RETURN;
    END IF;
    UPDATE tmp_pointstemp AS pointstemp SET points = v_points, pointsvalue = v_pointsvalue WHERE (rowid = v_rowid);
    v_rowid := (v_rowid + 1);
  END LOOP;
  v_layaltypointsbalance := coalesce((SELECT coalesce(sum(points), 0) AS pointsbalance FROM tmp_pointstemp AS pointstemp), 0);
  v_layaltypointsvalue := coalesce((SELECT coalesce(sum(pointsvalue), 0) AS pointsbalance FROM tmp_pointstemp AS pointstemp), 0);
  return_value := 0;
  layaltypointsbalance := v_layaltypointsbalance;
  layaltypointsvalue := v_layaltypointsvalue;
  RETURN;
  return_value := 0;
  layaltypointsbalance := v_layaltypointsbalance;
  layaltypointsvalue := v_layaltypointsvalue;
  RETURN;
END
$body$;

-- ==== proc SP_GetAliasName ====
CREATE OR REPLACE FUNCTION dbo.sp_getaliasname(usercode integer, aliasname citext, INOUT icode integer, INOUT itemname citext, INOUT rettype integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_usercode integer;
  v_aliasname citext;
  v_icode integer;
  v_itemname citext;
  v_rettype integer;
  v_groupcode integer;
  v_tempicode integer;
  v_retcode integer;
  v_err integer;
  v_rowcount integer;
  _r1 record;
  _r2 record;
  _r3 record;
  _r4 record;
  _r5 record;
  _r6 record;
  _rc integer;
BEGIN
  v_usercode := usercode;
  v_aliasname := aliasname;
  v_icode := icode;
  v_itemname := itemname;
  v_rettype := rettype;
  v_groupcode := (SELECT min(groupcode) FROM dbo.usergroups WHERE (usercode = v_usercode));
  _rc := 1;
  v_err := 0;
  v_rowcount := _rc;
  _rc := 1;
  IF ((v_err = 0) AND (v_rowcount = 1)) THEN
    IF ((dbo.fn_getpreference('GroupCategoryRights'))::citext = 'Y') THEN
      _rc := 0;
      FOR _r1 IN SELECT item.icode AS c1, item.name AS c2 FROM dbo.item WHERE ((((item.customicode = v_aliasname) AND (((item.restricted = 'N') OR (((item.restricted = 'Y') AND EXISTS (SELECT * FROM dbo.grouprights WHERE ((rightcode = 515) AND (groupcode = v_groupcode)))))))) AND (item.active = 1)) AND (item.icatcode IN (SELECT icatcode FROM dbo.itemcategory WHERE (icatcode IN (SELECT itemscategorycode FROM dbo.itemsgroupcategory WHERE (groupcode IN (SELECT groupcode FROM dbo.usergroups WHERE (usercode = v_usercode)))))))) LOOP
        _rc := _rc + 1;
        v_icode := _r1.c1;
        v_itemname := _r1.c2;
      END LOOP;
      v_err := 0;
      v_rowcount := _rc;
