            purprice := v_purprice;
            saleprice := v_saleprice;
            RETURN;
          ELSE
            v_retcode := 0;
            _rc := 1;
            v_rettype := 1;
            _rc := 1;
          END IF;
        ELSE
          RAISE EXCEPTION 'Unable to fetch Item Alias Name = %', v_aliasname;
          v_retcode := -1;
          _rc := 1;
          v_rettype := 0;
          _rc := 1;
          return_value := v_retcode;
          icode := v_icode;
          itemname := v_itemname;
          rettype := v_rettype;
          qty := v_qty;
          purprice := v_purprice;
          saleprice := v_saleprice;
          RETURN;
        END IF;
      ELSE
        v_retcode := -1;
        _rc := 1;
        v_rettype := 0;
        _rc := 1;
      END IF;
    ELSE
      v_retcode := 0;
      _rc := 1;
      v_rettype := 0;
      _rc := 1;
    END IF;
    IF (v_icode IS NULL) THEN
      SELECT max(ws.weighingscalecode) INTO v_weighingscalecode FROM dbo.weighingscale AS ws WHERE ((((length(rtrim(v_aliasname)) = ws.barcodelen) AND ((substring(v_aliasname, ws.scaleidpos, length(rtrim(ws.scaleid))))::citext = ws.scaleid)) AND (length(rtrim(substring(v_aliasname, ws.itemstartpos, (((ws.itemendpos - ws.itemstartpos) + 1))))) <= (((ws.itemendpos - ws.itemstartpos) + 1)))) AND (length(rtrim(substring(v_aliasname, ws.weightstartpos, (((ws.weightendpos - ws.weightstartpos) + 1))))) <= (((ws.weightendpos - ws.weightstartpos) + 1))));
      GET DIAGNOSTICS _rc = ROW_COUNT;
      IF ((0 <> 0) OR (_rc = 0)) THEN
        RAISE EXCEPTION 'Unable to fetch Item Alias Name = %', v_aliasname;
        v_retcode := -1;
        _rc := 1;
        v_rettype := 0;
        _rc := 1;
        return_value := v_retcode;
        icode := v_icode;
        itemname := v_itemname;
        rettype := v_rettype;
        qty := v_qty;
        purprice := v_purprice;
        saleprice := v_saleprice;
        RETURN;
      END IF;
      IF (v_weighingscalecode > 0) THEN
        _rc := 0;
        FOR _r7 IN SELECT substring(v_aliasname, ws.itemstartpos, (((ws.itemendpos - ws.itemstartpos) + 1))) AS c1, substring(v_aliasname, ws.weightstartpos, (((ws.weightendpos - ws.weightstartpos) + 1))) AS c2 FROM dbo.weighingscale AS ws WHERE (ws.weighingscalecode = v_weighingscalecode) LOOP
          _rc := _rc + 1;
          v_newaliasname := _r7.c1;
          v_weightstr := _r7.c2;
        END LOOP;
        IF ((0 <> 0) OR (_rc = 0)) THEN
          RAISE EXCEPTION 'Unable to fetch Item Alias Name = %', v_aliasname;
          v_retcode := -1;
          _rc := 1;
          v_rettype := 0;
          _rc := 1;
          return_value := v_retcode;
          icode := v_icode;
          itemname := v_itemname;
          rettype := v_rettype;
          qty := v_qty;
          purprice := v_purprice;
          saleprice := v_saleprice;
          RETURN;
        END IF;
        SELECT r.return_value, r.icode, r.itemname, r.rettype, r.qty, r.purprice, r.saleprice INTO v_retcode, v_icode, v_itemname, v_rettype, v_qty, v_purprice, v_saleprice FROM dbo.sp_getaliasname_withqtyprice(usercode => v_usercode, aliasname => v_newaliasname, icode => v_icode, itemname => v_itemname, rettype => v_rettype, qty => v_qty, purprice => v_purprice, saleprice => v_saleprice) AS r;
        IF ((0 <> 0) OR (v_retcode < 0)) THEN
          v_tempicode := coalesce((SELECT (trunc((v_newaliasname)::numeric))::integer), 0);
          _rc := 1;
          v_err := 0;
          v_rowcount := _rc;
          _rc := 1;
          IF (v_err <> 0) THEN
            RAISE EXCEPTION 'Unable to fetch Item Alias Name = %', v_aliasname;
            v_retcode := -1;
            _rc := 1;
            v_rettype := 0;
            _rc := 1;
            return_value := v_retcode;
            icode := v_icode;
            itemname := v_itemname;
            rettype := v_rettype;
            qty := v_qty;
            purprice := v_purprice;
            saleprice := v_saleprice;
            RETURN;
          ELSE
            v_newaliasname := ltrim(rtrim(dbo.tsql_str((v_tempicode)::numeric)));
            _rc := 1;
            SELECT r.return_value, r.icode, r.itemname, r.rettype, r.qty, r.purprice, r.saleprice INTO v_retcode, v_icode, v_itemname, v_rettype, v_qty, v_purprice, v_saleprice FROM dbo.sp_getaliasname_withqtyprice(usercode => v_usercode, aliasname => v_newaliasname, icode => v_icode, itemname => v_itemname, rettype => v_rettype, qty => v_qty, purprice => v_purprice, saleprice => v_saleprice) AS r;
            IF ((0 <> 0) OR (v_retcode < 0)) THEN
              RAISE EXCEPTION 'Unable to fetch Item Alias Name = %', v_aliasname;
              v_retcode := -1;
              _rc := 1;
              v_rettype := 0;
              _rc := 1;
              return_value := v_retcode;
              icode := v_icode;
              itemname := v_itemname;
              rettype := v_rettype;
              qty := v_qty;
              purprice := v_purprice;
              saleprice := v_saleprice;
              RETURN;
            END IF;
          END IF;
        END IF;
        IF ((v_icode > 0) AND (v_retcode = 0)) THEN
          v_allowsaleindecimalqty := coalesce((SELECT allowsaleindecimalqty FROM dbo.item WHERE (icode = v_icode)), 'Y');
          _rc := 1;
          IF (v_allowsaleindecimalqty = 'Y') THEN
            v_qty := ((v_weightstr)::numeric(15,4) / 1000);
            _rc := 1;
            IF (v_qty < 0.01) THEN
              v_qty := (v_qty * 1000);
              _rc := 1;
            END IF;
          ELSE
            v_qty := (trunc((v_weightstr)::numeric))::integer;
            _rc := 1;
          END IF;
          v_retcode := 0;
          _rc := 1;
          v_rettype := 0;
          _rc := 1;
        END IF;
      END IF;
    END IF;
  ELSE
    RAISE EXCEPTION 'Unable to fetch group code for user code = %', v_usercode;
    return_value := -1;
    icode := v_icode;
    itemname := v_itemname;
    rettype := v_rettype;
    qty := v_qty;
    purprice := v_purprice;
    saleprice := v_saleprice;
    RETURN;
  END IF;
  IF ((v_alternate = 1) AND (v_rettype = 0)) THEN
    v_rettype := 2;
    _rc := 1;
  END IF;
  return_value := v_retcode;
  icode := v_icode;
  itemname := v_itemname;
  rettype := v_rettype;
  qty := v_qty;
  purprice := v_purprice;
  saleprice := v_saleprice;
  RETURN;
  return_value := 0;
  icode := v_icode;
  itemname := v_itemname;
  rettype := v_rettype;
  qty := v_qty;
  purprice := v_purprice;
  saleprice := v_saleprice;
  RETURN;
END
$body$;

-- ==== proc sp_GetAllowedGroupCustomerCategory ====
CREATE OR REPLACE FUNCTION dbo.sp_getallowedgroupcustomercategory(groupcode integer, INOUT custcatstring citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_groupcode integer;
  v_custcatstring citext;
  v_custcategory integer;
  v_holdcustcatstring citext;
  cur_cursor_custcat refcursor;
  _fs integer := -1;
BEGIN
  v_groupcode := groupcode;
  v_custcatstring := custcatstring;
  OPEN cur_cursor_custcat FOR SELECT customercategorycode FROM dbo.customergroupcategory WHERE (groupcode = v_groupcode);
  FETCH NEXT FROM cur_cursor_custcat INTO v_custcategory;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  v_holdcustcatstring := '';
  WHILE (_fs = 0) LOOP
    IF (v_holdcustcatstring = '') THEN
      v_holdcustcatstring := (v_custcategory)::text;
    ELSE
      v_holdcustcatstring := ((v_holdcustcatstring || ' , ') || (v_custcategory)::text);
    END IF;
    FETCH NEXT FROM cur_cursor_custcat INTO v_custcategory;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_cursor_custcat;
  -- DEALLOCATE Cursor_custcat
  v_custcatstring := v_holdcustcatstring;
  return_value := 0;
  custcatstring := v_custcatstring;
  RETURN;
END
$body$;

