-- ==== proc SP_GetBonusPolicyBased_ItemBonusQty ====
CREATE OR REPLACE FUNCTION dbo.sp_getbonuspolicybased_itembonusqty(icode integer, qtysold numeric, INOUT bonusqty integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_icode integer;
  v_qtysold numeric(15,4);
  v_bonusqty integer;
  v_bonuspolicycode smallint;
BEGIN
  v_icode := icode;
  v_qtysold := qtysold;
  v_bonusqty := bonusqty;
  IF ((v_icode IS NULL) OR (v_icode < 0)) THEN
    v_bonusqty := NULL;
    RAISE EXCEPTION 'Problem occured while fetching bonus qty. Item is null';
    return_value := -1;
    bonusqty := v_bonusqty;
    RETURN;
  END IF;
  v_bonuspolicycode := (SELECT bonuspolicycode FROM dbo.item WHERE (icode = v_icode));
  IF (v_bonuspolicycode IS NULL) THEN
    v_bonusqty := NULL;
    return_value := 0;
    bonusqty := v_bonusqty;
    RETURN;
  ELSE
    v_bonusqty := (SELECT (trunc(((v_qtysold / CASE WHEN (saleqty <> 0) THEN saleqty ELSE 1 END)))::integer * bonusqty) AS bonusqty FROM dbo.bonuspolicydetail AS d, (SELECT min(qtylimit) AS qtylimit FROM dbo.bonuspolicydetail WHERE (((bonuspolicycode = v_bonuspolicycode) AND (qtylimit >= v_qtysold)) AND (expirydate >= (date_trunc('day', localtimestamp(3)))::timestamp(3))) UNION SELECT max(qtylimit) AS qtylimit FROM dbo.bonuspolicydetail WHERE (((expirydate >= (date_trunc('day', localtimestamp(3)))::timestamp(3)) AND (bonuspolicycode = v_bonuspolicycode)) AND (qtylimit <= v_qtysold))) AS t WHERE ((((d.bonuspolicycode = v_bonuspolicycode) AND (d.expirydate >= (date_trunc('day', localtimestamp(3)))::timestamp(3))) AND (d.qtylimit = t.qtylimit)) AND (t.qtylimit <= v_qtysold)));
  END IF;
  return_value := 0;
  bonusqty := v_bonusqty;
  RETURN;
  return_value := 0;
  bonusqty := v_bonusqty;
  RETURN;
END
$body$;

