-- ==== proc sp_GetCustWiseLatestItemSale ====
CREATE OR REPLACE FUNCTION dbo.sp_getcustwiselatestitemsale(custcode integer, icode integer, INOUT saleprice numeric, INOUT looseqty numeric, INOUT bonusqty numeric, INOUT discperc numeric, INOUT itemflatdisc numeric, INOUT rows smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_custcode integer;
  v_icode integer;
  v_saleprice numeric(8,2);
  v_looseqty numeric(15,4);
  v_bonusqty numeric(15,4);
  v_discperc numeric(5,2);
  v_itemflatdisc numeric(12,2);
  v_rows smallint;
  _r1 record;
BEGIN
  v_custcode := custcode;
  v_icode := icode;
  v_saleprice := saleprice;
  v_looseqty := looseqty;
  v_bonusqty := bonusqty;
  v_discperc := discperc;
  v_itemflatdisc := itemflatdisc;
  v_rows := rows;
  FOR _r1 IN SELECT count(*) AS c1, max(saledetail.saleprice) AS c2, sum(saledetail.looseqty) AS c3, sum(saledetail.bonusqty) AS c4, max(saledetail.discperc) AS c5, max(saledetail.itemflatdisc) AS c6 FROM dbo.saleledger, dbo.saledetail, (SELECT max(sl.date) AS date FROM dbo.saleledger AS sl, dbo.saledetail AS sd WHERE (((sl.custcode = v_custcode) AND (sl.saleinvcode = sd.saleinvcode)) AND (sd.icode = v_icode))) AS a WHERE ((((saleledger.custcode = v_custcode) AND (saleledger.date = a.date)) AND (saleledger.saleinvcode = saledetail.saleinvcode)) AND (saledetail.icode = v_icode)) GROUP BY saledetail.icode, saledetail.saleprice, saledetail.discperc, saledetail.itemflatdisc LOOP
    v_rows := _r1.c1;
    v_saleprice := _r1.c2;
    v_looseqty := _r1.c3;
    v_bonusqty := _r1.c4;
    v_discperc := _r1.c5;
    v_itemflatdisc := _r1.c6;
  END LOOP;
  return_value := 0;
  saleprice := v_saleprice;
  looseqty := v_looseqty;
  bonusqty := v_bonusqty;
  discperc := v_discperc;
  itemflatdisc := v_itemflatdisc;
  rows := v_rows;
  RETURN;
END
$body$;

-- ==== proc SP_GetDiscountPolicyBased_ItemDiscount ====
CREATE OR REPLACE FUNCTION dbo.sp_getdiscountpolicybased_itemdiscount(icode integer, qtysold numeric, INOUT discperc numeric, INOUT itemflatdisc numeric, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_icode integer;
  v_qtysold numeric(15,4);
  v_discperc numeric(5,2);
  v_itemflatdisc numeric(12,2);
  v_discountpolicycode smallint;
BEGIN
  v_icode := icode;
  v_qtysold := qtysold;
  v_discperc := discperc;
  v_itemflatdisc := itemflatdisc;
  IF ((v_icode IS NULL) OR (v_icode < 0)) THEN
    v_discperc := NULL;
    v_itemflatdisc := NULL;
    RAISE EXCEPTION 'Problem occured while fetching Discount (%%), Item is null';
    return_value := -1;
    discperc := v_discperc;
    itemflatdisc := v_itemflatdisc;
    RETURN;
  END IF;
  v_discountpolicycode := (SELECT discountpolicycode FROM dbo.item WHERE (icode = v_icode));
  IF (v_discountpolicycode IS NULL) THEN
    v_discperc := NULL;
    v_itemflatdisc := NULL;
    return_value := 0;
    discperc := v_discperc;
    itemflatdisc := v_itemflatdisc;
    RETURN;
  ELSE
    v_discperc := (SELECT d.discperc FROM dbo.discountpolicydetail AS d, (SELECT min(qtylimit) AS qtylimit FROM dbo.discountpolicydetail WHERE (((expirydate >= (date_trunc('day', localtimestamp(3)))::timestamp(3)) AND (discountpolicycode = v_discountpolicycode)) AND (qtylimit >= v_qtysold)) UNION SELECT max(qtylimit) AS qtylimit FROM dbo.discountpolicydetail WHERE (((expirydate >= (date_trunc('day', localtimestamp(3)))::timestamp(3)) AND (discountpolicycode = v_discountpolicycode)) AND (qtylimit <= v_qtysold))) AS t WHERE ((((expirydate >= (date_trunc('day', localtimestamp(3)))::timestamp(3)) AND (discountpolicycode = v_discountpolicycode)) AND (d.qtylimit = t.qtylimit)) AND (t.qtylimit <= v_qtysold)));
    v_itemflatdisc := (SELECT d.itemflatdisc FROM dbo.discountpolicydetail AS d, (SELECT min(qtylimit) AS qtylimit FROM dbo.discountpolicydetail WHERE (((expirydate >= (date_trunc('day', localtimestamp(3)))::timestamp(3)) AND (discountpolicycode = v_discountpolicycode)) AND (qtylimit >= v_qtysold)) UNION SELECT max(qtylimit) AS qtylimit FROM dbo.discountpolicydetail WHERE (((expirydate >= (date_trunc('day', localtimestamp(3)))::timestamp(3)) AND (discountpolicycode = v_discountpolicycode)) AND (qtylimit <= v_qtysold))) AS t WHERE ((((expirydate >= (date_trunc('day', localtimestamp(3)))::timestamp(3)) AND (discountpolicycode = v_discountpolicycode)) AND (d.qtylimit = t.qtylimit)) AND (t.qtylimit <= v_qtysold)));
  END IF;
  return_value := 0;
  discperc := v_discperc;
  itemflatdisc := v_itemflatdisc;
  RETURN;
  return_value := 0;
  discperc := v_discperc;
  itemflatdisc := v_itemflatdisc;
  RETURN;
END
$body$;

-- ==== proc SP_GetFirstItemImageDetail ====
CREATE OR REPLACE FUNCTION dbo.sp_getfirstitemimagedetail(icode integer, INOUT rowid integer, INOUT imgtype citext, INOUT imgdesc citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
