  v_imgtype citext;
  v_imgdesc citext;
BEGIN
  v_icode := icode;
  v_rowid := rowid;
  v_imgtype := imgtype;
  v_imgdesc := imgdesc;
  IF (v_icode > 0) THEN
    v_rowid := coalesce((SELECT min(rowid) FROM dbo.itemimage WHERE (icode = v_icode)), 0);
    IF (v_rowid > 0) THEN
      v_imgtype := coalesce((SELECT imagetype FROM dbo.itemimage WHERE ((icode = v_icode) AND (rowid = v_rowid))), 'bmp');
      v_imgdesc := coalesce((SELECT imagedescription FROM dbo.itemimage WHERE ((icode = v_icode) AND (rowid = v_rowid))), '');
    END IF;
  END IF;
  return_value := 0;
  rowid := v_rowid;
  imgtype := v_imgtype;
  imgdesc := v_imgdesc;
  RETURN;
  return_value := 0;
  rowid := v_rowid;
  imgtype := v_imgtype;
  imgdesc := v_imgdesc;
  RETURN;
END
$body$;

