-- ==== proc SP_GetGodownConsumption ====
CREATE OR REPLACE FUNCTION dbo.sp_getgodownconsumption(gcode smallint, type smallint, startdate timestamp, enddate timestamp, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_gcode smallint;
  v_type smallint;
  v_startdate timestamp(3);
  v_enddate timestamp(3);
BEGIN
  v_gcode := gcode;
  v_type := type;
  v_startdate := startdate;
  v_enddate := enddate;
  DELETE FROM dbo.reportdata;
  INSERT INTO dbo.reportdata (code1, value1) SELECT t.icode AS icode, sum(t.qty) AS qty FROM (SELECT d.icode, sum(d.looseqty) AS qty FROM dbo.saleledger AS h, dbo.saledetail AS d WHERE ((((((v_type = 1) OR (v_type = 4))) AND (h.date BETWEEN v_startdate AND v_enddate)) AND (h.saleinvcode = d.saleinvcode)) AND (d.gcode = v_gcode)) GROUP BY d.icode UNION ALL SELECT d.icode, (-sum(d.looseqty)) AS qty FROM dbo.srledger AS h, dbo.srdetail AS d WHERE ((((((v_type = 1) OR (v_type = 4))) AND (h.date BETWEEN v_startdate AND v_enddate)) AND (h.srinvcode = d.srinvcode)) AND (d.gcode = v_gcode)) GROUP BY d.icode UNION ALL SELECT d.icode, sum(d.qty) AS qty FROM dbo.issueheader AS h, dbo.issuedetail AS d WHERE ((((((v_type = 2) OR (v_type = 4))) AND (h.date BETWEEN v_startdate AND v_enddate)) AND (h.issueinvcode = d.issueinvcode)) AND (d.gcode = v_gcode)) GROUP BY d.icode UNION ALL SELECT d.icode, (-sum(d.qty)) AS qty FROM dbo.receiptheader AS h, dbo.receiptdetail AS d WHERE ((((((v_type = 2) OR (v_type = 4))) AND (h.date BETWEEN v_startdate AND v_enddate)) AND (h.receiptinvcode = d.receiptinvcode)) AND (d.gcode = v_gcode)) GROUP BY d.icode UNION ALL SELECT d.icode, sum(d.qty) AS qty FROM dbo.theader AS h, dbo.tdetail AS d WHERE ((((((v_type = 3) OR (v_type = 4))) AND (h.date BETWEEN v_startdate AND v_enddate)) AND (h.sgcode = v_gcode)) AND (h.transcode = d.transcode)) GROUP BY d.icode UNION ALL SELECT d.icode, (-sum(d.qty)) AS qty FROM dbo.theader AS h, dbo.tdetail AS d WHERE ((((((v_type = 3) OR (v_type = 4))) AND (h.date BETWEEN v_startdate AND v_enddate)) AND (h.dgcode = v_gcode)) AND (h.transcode = d.transcode)) GROUP BY d.icode UNION ALL SELECT d.icode, sum((CASE WHEN (h.adjcatcode = 1) THEN -1 ELSE 1 END * d.looseqty)) AS qty FROM dbo.adjheader AS h, dbo.adjdetail AS d WHERE ((((v_type = 4) AND (h.date BETWEEN v_startdate AND v_enddate)) AND (h.adjcode = d.adjcode)) AND (d.gcode = v_gcode)) GROUP BY d.icode UNION ALL SELECT d.icode, (-sum(CASE WHEN (h.purcatcode > 2) THEN ((d.looseqty + d.bonusqty)) ELSE (((d.looseqty + d.bonusqty)) * d.packunits) END)) AS qty FROM dbo.purledger AS h, dbo.purdetail AS d WHERE ((((v_type = 4) AND (h.date BETWEEN v_startdate AND v_enddate)) AND (h.purinvcode = d.purinvcode)) AND (d.gcode = v_gcode)) GROUP BY d.icode UNION ALL SELECT d.icode, sum(d.looseqty) AS qty FROM dbo.prledger AS h, dbo.prdetail AS d WHERE ((((v_type = 4) AND (h.date BETWEEN v_startdate AND v_enddate)) AND (h.prinvcode = d.prinvcode)) AND (d.gcode = v_gcode)) GROUP BY d.icode) AS t GROUP BY icode HAVING (sum(t.qty) > 0);
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_GetHeaderTabMaxKey ====
CREATE OR REPLACE FUNCTION dbo.sp_getheadertabmaxkey(headercode smallint, modulecode smallint, INOUT key integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_headercode smallint;
  v_modulecode smallint;
  v_key integer;
  v_modulename citext;
  v_err integer;
  v_rowcount integer;
  _r1 record;
  _r2 record;
  _r3 record;
  _rc integer;
BEGIN
  v_headercode := headercode;
  v_modulecode := modulecode;
  v_key := key;
  -- SET NOCOUNT On
  _rc := 0;
  FOR _r1 IN SELECT tabmaxkey AS c1 FROM dbo._headertabmaxkey WHERE ((_headertabmaxkey.headercode = v_headercode) AND (_headertabmaxkey.module = v_modulecode)) FOR UPDATE OF _headertabmaxkey LOOP
    _rc := _rc + 1;
    v_key := _r1.c1;
  END LOOP;
  v_err := 0;
  v_rowcount := _rc;
  _rc := 1;
  IF ((v_err = 0) AND (v_rowcount > 0)) THEN
    v_key := (v_key + 1);
    _rc := 1;
    UPDATE dbo._headertabmaxkey SET tabmaxkey = v_key WHERE ((_headertabmaxkey.headercode = v_headercode) AND (_headertabmaxkey.module = v_modulecode));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_err := 0;
    v_rowcount := _rc;
    _rc := 1;
    IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
      _rc := 0;
      FOR _r2 IN SELECT name AS c1 FROM dbo.module WHERE (module = v_modulecode) LOOP
        _rc := _rc + 1;
        v_modulename := _r2.c1;
      END LOOP;
      -- SET NOCOUNT OFF
      RAISE EXCEPTION 'Exception occured in updating max key for module %', v_modulename;
      return_value := -1;
      key := v_key;
      RETURN;
    END IF;
  ELSE
    _rc := 0;
    FOR _r3 IN SELECT name AS c1 FROM dbo.module WHERE (module = v_modulecode) LOOP
      _rc := _rc + 1;
      v_modulename := _r3.c1;
    END LOOP;
    -- SET NOCOUNT OFF
    RAISE EXCEPTION 'Exception occured in getting max key for module %', v_modulename;
    return_value := -1;
    key := v_key;
    RETURN;
  END IF;
  -- SET NOCOUNT OFF
  return_value := 0;
  key := v_key;
  RETURN;
  return_value := 0;
  key := v_key;
  RETURN;
END
$body$;

-- ==== proc sp_GetIssueCategoryCounter ====
CREATE OR REPLACE FUNCTION dbo.sp_getissuecategorycounter(category smallint, INOUT counter integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_category smallint;
  v_counter integer;
  v_err integer;
  v_rowcount integer;
  _r1 record;
  _rc integer;
BEGIN
  v_category := category;
  v_counter := counter;
  -- SET NOCOUNT On
  _rc := 0;
  FOR _r1 IN SELECT counter AS c1 FROM dbo.issuecategory WHERE (issuecategorycode = v_category) FOR UPDATE OF issuecategory LOOP
    _rc := _rc + 1;
    v_counter := _r1.c1;
  END LOOP;
  v_err := 0;
  v_rowcount := _rc;
  _rc := 1;
  IF ((v_err = 0) AND (v_rowcount > 0)) THEN
    v_counter := (v_counter + 1);
    _rc := 1;
    UPDATE dbo.issuecategory SET counter = v_counter WHERE (issuecategorycode = v_category);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_err := 0;
    v_rowcount := _rc;
    _rc := 1;
    IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
      -- SET NOCOUNT OFF
      RAISE EXCEPTION 'Exception occured in updating Issue category counter';
      return_value := -1;
      counter := v_counter;
      RETURN;
    END IF;
  ELSE
    -- SET NOCOUNT OFF
    RAISE EXCEPTION 'Exception occured in fetching Issue category counter';
    return_value := -1;
    counter := v_counter;
    RETURN;
  END IF;
  -- SET NOCOUNT OFF
  return_value := 0;
  counter := v_counter;
  RETURN;
  return_value := 0;
  counter := v_counter;
  RETURN;
END
$body$;

-- ==== proc SP_GetItemAliasName ====
CREATE OR REPLACE FUNCTION dbo.sp_getitemaliasname(aliasname citext, INOUT icode integer, INOUT itemname citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_aliasname citext;
  v_icode integer;
  v_itemname citext;
  v_tempicode integer;
  v_retcode integer;
  v_err integer;
  v_rowcount integer;
  _r1 record;
  _r2 record;
  _r3 record;
  _rc integer;
BEGIN
  v_aliasname := aliasname;
  v_icode := icode;
  v_itemname := itemname;
  -- SET NOCOUNT ON
  _rc := 0;
  FOR _r1 IN SELECT item.icode AS c1, item.name AS c2 FROM dbo.item WHERE (((item.customicode = v_aliasname) AND (item.active = 1)) AND (item.restricted = 'N')) LOOP
    _rc := _rc + 1;
    v_icode := _r1.c1;
    v_itemname := _r1.c2;
  END LOOP;
  v_err := 0;
  v_rowcount := _rc;
  _rc := 1;
  IF (v_err <> 0) THEN
    RAISE EXCEPTION 'Unable to fetch Item Alias Name = %', v_aliasname;
    v_retcode := -1;
    _rc := 1;
    return_value := v_retcode;
    icode := v_icode;
    itemname := v_itemname;
    RETURN;
  END IF;
  IF (v_rowcount = 0) THEN
    _rc := 0;
    FOR _r2 IN SELECT item.icode AS c1, item.name AS c2 FROM dbo.item WHERE (((item.active = 1) AND (item.restricted = 'N')) AND (item.icode IN (SELECT max(ai.icode) FROM dbo.alternateitemalias AS ai WHERE (ai.customicode = v_aliasname)))) LOOP
      _rc := _rc + 1;
      v_icode := _r2.c1;
      v_itemname := _r2.c2;
    END LOOP;
    v_err := 0;
    v_rowcount := _rc;
    _rc := 1;
    IF (v_err <> 0) THEN
      RAISE EXCEPTION 'Unable to fetch Item Alias Name = %', v_aliasname;
      v_retcode := -1;
      _rc := 1;
      return_value := v_retcode;
      icode := v_icode;
      itemname := v_itemname;
      RETURN;
    END IF;
    IF (v_rowcount = 0) THEN
      v_icode := NULL;
      _rc := 1;
      v_itemname := NULL;
      _rc := 1;
    END IF;
  END IF;
  IF (v_icode IS NULL) THEN
    IF ((dbo.fn_getpreference('SearchItemCodeIfAliasNameNotFound'))::citext = 'Y') THEN
      v_tempicode := coalesce((SELECT (trunc((v_aliasname)::numeric))::integer), 0);
      _rc := 1;
      v_err := 0;
      v_rowcount := _rc;
      _rc := 1;
      IF (v_err <> 0) THEN
        RAISE EXCEPTION 'Unable to fetch Item Alias Name = %', v_aliasname;
        v_retcode := -1;
        _rc := 1;
        return_value := v_retcode;
        icode := v_icode;
        itemname := v_itemname;
        RETURN;
      END IF;
      IF (v_tempicode > 0) THEN
        _rc := 0;
        FOR _r3 IN SELECT item.icode AS c1, item.name AS c2 FROM dbo.item WHERE (((item.icode = v_tempicode) AND (item.active = 1)) AND (item.restricted = 'N')) LOOP
          _rc := _rc + 1;
          v_icode := _r3.c1;
          v_itemname := _r3.c2;
        END LOOP;
        v_err := 0;
        v_rowcount := _rc;
        _rc := 1;
        IF (v_err <> 0) THEN
          RAISE EXCEPTION 'Unable to fetch Item Alias Name = %', v_aliasname;
          v_retcode := -1;
          _rc := 1;
          return_value := v_retcode;
          icode := v_icode;
          itemname := v_itemname;
          RETURN;
        END IF;
        IF (v_rowcount = 0) THEN
          v_icode := NULL;
          _rc := 1;
          v_itemname := NULL;
          _rc := 1;
        END IF;
        IF (v_icode IS NULL) THEN
          RAISE EXCEPTION 'Unable to fetch Item Alias Name = %', v_aliasname;
          v_retcode := -1;
          _rc := 1;
          return_value := v_retcode;
          icode := v_icode;
          itemname := v_itemname;
          RETURN;
        ELSE
          v_retcode := 0;
          _rc := 1;
        END IF;
      ELSE
        RAISE EXCEPTION 'Unable to fetch Item Alias Name = %', v_aliasname;
        v_retcode := -1;
        _rc := 1;
        return_value := v_retcode;
        icode := v_icode;
        itemname := v_itemname;
        RETURN;
      END IF;
    ELSE
      RAISE EXCEPTION 'Unable to fetch Item Alias Name = %', v_aliasname;
      v_retcode := -1;
      _rc := 1;
      return_value := v_retcode;
      icode := v_icode;
      itemname := v_itemname;
      RETURN;
    END IF;
  END IF;
  return_value := v_retcode;
  icode := v_icode;
  itemname := v_itemname;
  RETURN;
  return_value := 0;
  icode := v_icode;
  itemname := v_itemname;
  RETURN;
END
$body$;

-- ==== proc sp_GetItemAvgPrice ====
CREATE OR REPLACE FUNCTION dbo.sp_getitemavgprice(icode integer, INOUT avgprice numeric, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
