  _rc := 1;
  v_err := 0;
  v_rowcount := _rc;
  _rc := 1;
  IF ((v_err = 0) AND (v_rowcount = 1)) THEN
    IF (v_price IS NULL) THEN
      v_avgprice := 0;
      _rc := 1;
    ELSE
      v_avgprice := (v_price)::numeric(15,5);
