    RAISE EXCEPTION 'Unable to fetch AvgPrice for Item = %', v_itemname;
    return_value := -1;
    avgprice := v_avgprice;
    RETURN;
  END IF;
  return_value := 0;
  avgprice := v_avgprice;
  RETURN;
  return_value := 0;
  avgprice := v_avgprice;
  RETURN;
END
$body$;

