-- ==== proc SP_GetItemReqQtyForTransfer ====
CREATE OR REPLACE FUNCTION dbo.sp_getitemreqqtyfortransfer(startdate timestamp, enddate timestamp, icode integer, gcode integer, INOUT reqqty numeric, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_startdate timestamp(3);
  v_enddate timestamp(3);
  v_icode integer;
  v_gcode integer;
  v_reqqty numeric(15,4);
  _r1 record;
BEGIN
  v_startdate := startdate;
  v_enddate := enddate;
  v_icode := icode;
  v_gcode := gcode;
  v_reqqty := reqqty;
  -- SET NOCOUNT On
  FOR _r1 IN SELECT ((saleqty - coalesce(saleretqty, 0))) AS c1 FROM (SELECT saledetail.icode, coalesce(sum((saledetail.looseqty + saledetail.bonusqty)), 0) AS saleqty FROM dbo.saleledger, dbo.saledetail WHERE ((((saleledger.saleinvcode = saledetail.saleinvcode) AND (saleledger.date BETWEEN v_startdate AND v_enddate)) AND (saledetail.gcode = v_gcode)) AND (saledetail.icode = v_icode)) GROUP BY saledetail.icode) AS s LEFT JOIN (SELECT srdetail.icode, coalesce(sum((srdetail.looseqty + srdetail.bonusqty)), 0) AS saleretqty FROM dbo.srledger, dbo.srdetail WHERE ((((srledger.srinvcode = srdetail.srinvcode) AND (srledger.date BETWEEN v_startdate AND v_enddate)) AND (srdetail.gcode = v_gcode)) AND (srdetail.icode = v_icode)) GROUP BY srdetail.icode) AS sr ON (s.icode = sr.icode) WHERE (((saleqty - coalesce(saleretqty, 0))) > 0) LOOP
    v_reqqty := _r1.c1;
  END LOOP;
  -- SET NOCOUNT OFF
  return_value := 0;
  reqqty := v_reqqty;
  RETURN;
END
$body$;

-- ==== proc SP_GetItemStock_Exc_PendingDue ====
CREATE OR REPLACE FUNCTION dbo.sp_getitemstock_exc_pendingdue(gcode integer, icode integer, INOUT qty numeric, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_gcode integer;
  v_icode integer;
  v_qty numeric(15,4);
BEGIN
  v_gcode := gcode;
  v_icode := icode;
  v_qty := qty;
  v_qty := 0;
  v_qty := ((SELECT coalesce(sum(godowndetail.currqty), 0) FROM dbo.godowndetail WHERE ((godowndetail.gcode = v_gcode) AND (godowndetail.icode = v_icode))) - ((((SELECT coalesce(sum((sd.looseqty + sd.bonusqty)), 0) FROM dbo.saledetail AS sd WHERE (((sd.due IN ('X', 'D', 'S')) AND (sd.icode = v_icode)) AND (gcode = v_gcode))) - (SELECT coalesce(sum(dd.deletedqty), 0) FROM dbo.duedeletedetail AS dd WHERE (dd.icode = v_icode))) - (SELECT coalesce(sum(ds.duesatisfyqty), 0) FROM dbo.duesatisfydetail AS ds WHERE ((ds.icode = v_icode) AND (gcode = v_gcode))))));
  IF (v_qty IS NULL) THEN
    v_qty := 0;
  END IF;
  return_value := 0;
  qty := v_qty;
  RETURN;
END
$body$;

