-- ==== proc sp_GetItemStockBatch ====
CREATE OR REPLACE FUNCTION dbo.sp_getitemstockbatch(gcode integer, icode integer, batch citext, expiry timestamp, INOUT qty numeric, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_gcode integer;
  v_icode integer;
  v_batch citext;
  v_expiry timestamp(3);
  v_qty numeric(15,4);
  v_itemname citext;
  v_str_expiry citext;
  _r1 record;
BEGIN
  v_gcode := gcode;
  v_icode := icode;
  v_batch := batch;
  v_expiry := expiry;
  v_qty := qty;
  v_qty := 0;
  FOR _r1 IN SELECT coalesce(godowndetail.currqty, 0) AS c1 FROM dbo.godowndetail WHERE ((((godowndetail.gcode = v_gcode) AND (godowndetail.icode = v_icode)) AND (godowndetail.batch = v_batch)) AND (godowndetail.expiry = v_expiry)) LOOP
    v_qty := _r1.c1;
  END LOOP;
  IF (0 <> 0) THEN
    v_itemname := (SELECT name FROM dbo.item WHERE (icode = v_icode));
    v_str_expiry := left(to_char(v_expiry, 'DD/MM/YYYY'), 10);
    RAISE EXCEPTION 'Unable to fetch item batch wise stock for Item = (%) , with batch = (%) and expiry = (%)', v_itemname, v_batch, v_str_expiry;
    v_qty := 0;
    return_value := -1;
    qty := v_qty;
    RETURN;
  END IF;
  IF (v_qty IS NULL) THEN
    v_qty := 0;
  END IF;
  return_value := 0;
  qty := v_qty;
  RETURN;
  return_value := 0;
  qty := v_qty;
  RETURN;
END
$body$;

-- ==== proc sp_GetItemStockInAllowedGodown ====
CREATE OR REPLACE FUNCTION dbo.sp_getitemstockinallowedgodown(icode integer, groupcode integer, strategy integer, module integer, INOUT qty numeric, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_icode integer;
  v_groupcode integer;
  v_strategy integer;
  v_module integer;
  v_qty numeric(15,4);
BEGIN
  v_icode := icode;
  v_groupcode := groupcode;
  v_strategy := strategy;
  v_module := module;
  v_qty := qty;
  v_qty := 0;
  v_qty := (SELECT coalesce(sum(gd.currqty), 0) FROM dbo.godowndetail AS gd WHERE ((gd.icode = v_icode) AND (gd.gcode IN (CASE v_strategy WHEN 2 THEN (SELECT DISTINCT g.gcode FROM dbo.godown AS g WHERE (g.gcode = gd.gcode)) ELSE (SELECT DISTINCT gag.gcode FROM dbo.groupallowedgodown AS gag WHERE (((gag.groupcode = v_groupcode) AND (gag.module = v_module)) AND (gag.gcode = gd.gcode))) END))));
  IF (v_qty IS NULL) THEN
    v_qty := 0;
  END IF;
  return_value := 0;
  qty := v_qty;
  RETURN;
END
$body$;

