-- ==== proc SP_GetLoyaltyCardBalance ====
CREATE OR REPLACE FUNCTION dbo.sp_getloyaltycardbalance(loyaltycardcode integer, balancedate timestamp, INOUT layaltypointsbalance integer, INOUT layaltypointsvalue numeric, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_loyaltycardcode integer;
  v_balancedate timestamp(3);
  v_layaltypointsbalance integer;
  v_layaltypointsvalue numeric(12,2);
  v_loyaltypolicycode integer;
  v_pointsvalue numeric(12,2);
  v_layaltypointsslab integer;
BEGIN
  v_loyaltycardcode := loyaltycardcode;
  v_balancedate := balancedate;
  v_layaltypointsbalance := layaltypointsbalance;
  v_layaltypointsvalue := layaltypointsvalue;
  -- SET NOCOUNT ON
  IF ((v_loyaltycardcode IS NULL) OR (v_loyaltycardcode < 0)) THEN
    RAISE EXCEPTION 'Problem occured while fetching loyalty card balance Information';
    return_value := -1;
    layaltypointsbalance := v_layaltypointsbalance;
    layaltypointsvalue := v_layaltypointsvalue;
    RETURN;
  END IF;
  v_layaltypointsbalance := coalesce((SELECT coalesce(sum((pointsdebit - pointscredit)), 0) AS pointsbalance FROM dbo.loyaltycardledger WHERE ((loyaltycardcode = v_loyaltycardcode) AND (date < v_balancedate))), 0);
  v_layaltypointsvalue := coalesce((SELECT coalesce(sum((debit - credit)), 0) AS balance FROM dbo.loyaltycardledger WHERE ((loyaltycardcode = v_loyaltycardcode) AND (date < v_balancedate))), 0);
  return_value := 0;
  layaltypointsbalance := v_layaltypointsbalance;
  layaltypointsvalue := v_layaltypointsvalue;
  RETURN;
  return_value := 0;
  layaltypointsbalance := v_layaltypointsbalance;
  layaltypointsvalue := v_layaltypointsvalue;
  RETURN;
END
$body$;

-- ==== proc SP_GetMaxLimitForPackCase ====
CREATE OR REPLACE FUNCTION dbo.sp_getmaxlimitforpackcase(icode integer, INOUT icatcode smallint, INOUT packcode smallint, INOUT oclimit integer, INOUT mclimit integer, INOUT sclimit integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_icode integer;
  v_icatcode smallint;
  v_packcode smallint;
  v_oclimit integer;
  v_mclimit integer;
  v_sclimit integer;
  _r1 record;
BEGIN
  v_icode := icode;
  v_icatcode := icatcode;
  v_packcode := packcode;
  v_oclimit := oclimit;
  v_mclimit := mclimit;
  v_sclimit := sclimit;
  -- SET NOCOUNT ON
  FOR _r1 IN SELECT coalesce(pcc.icatcode, 0) AS c1, coalesce(pcc.packcode, 0) AS c2, coalesce(pcc.ocqty, 0) AS c3, coalesce(pcc.mcqty, 0) AS c4, coalesce(pcc.scqty, 0) AS c5 FROM dbo.packingcasecapacity AS pcc, dbo.item AS i WHERE (((i.icode = v_icode) AND (i.icatcode = pcc.icatcode)) AND (i.packcode = pcc.packcode)) LOOP
    v_icatcode := _r1.c1;
    v_packcode := _r1.c2;
    v_oclimit := _r1.c3;
    v_mclimit := _r1.c4;
    v_sclimit := _r1.c5;
  END LOOP;
  return_value := 0;
  icatcode := v_icatcode;
  packcode := v_packcode;
  oclimit := v_oclimit;
  mclimit := v_mclimit;
  sclimit := v_sclimit;
  RETURN;
END
$body$;

-- ==== proc sp_GetMostRecentTransDate ====
CREATE OR REPLACE FUNCTION dbo.sp_getmostrecenttransdate(INOUT ad_recentdate timestamp, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ad_recentdate timestamp(3);
BEGIN
  v_ad_recentdate := ad_recentdate;
  -- BEGIN TRANSACTION (the caller owns the transaction)
  DROP TABLE IF EXISTS tmp_lt_maxdate;
  CREATE TEMP TABLE tmp_lt_maxdate (
    recentdate timestamp(3) NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_maxdate SELECT max(date) FROM dbo.saleledger;
  INSERT INTO tmp_lt_maxdate SELECT max(date) FROM dbo.srledger;
  INSERT INTO tmp_lt_maxdate SELECT max(date) FROM dbo.purledger;
  INSERT INTO tmp_lt_maxdate SELECT max(date) FROM dbo.prledger;
  INSERT INTO tmp_lt_maxdate SELECT max(date) FROM dbo.glheader;
  v_ad_recentdate := (SELECT max(recentdate) FROM tmp_lt_maxdate AS lt_maxdate);
  RAISE EXCEPTION 'T-SQL ROLLBACK in sp_GetMostRecentTransDate' USING ERRCODE = 'TS001';
  return_value := 0;
  ad_recentdate := v_ad_recentdate;
  RETURN;
END
$body$;

