-- ==== proc SP_GetPatientAge ====
CREATE OR REPLACE FUNCTION dbo.sp_getpatientage(patientcode integer, INOUT ageyears integer, INOUT agemonth integer, INOUT agedays integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_patientcode integer;
  v_ageyears integer;
  v_agemonth integer;
  v_agedays integer;
  _r1 record;
BEGIN
  v_patientcode := patientcode;
  v_ageyears := ageyears;
  v_agemonth := agemonth;
  v_agedays := agedays;
  -- SET NOCOUNT ON
  FOR _r1 IN SELECT dbo.tsql_datediff('year', p.dob, localtimestamp(3)) AS c1, (((((localtimestamp(3))::date - (p.dob)::date) % 360) / 30))::integer AS c2, (((((localtimestamp(3))::date - (p.dob)::date) % 360) % 30))::integer AS c3 FROM dbo.patient AS p WHERE (p.patientcode = v_patientcode) LOOP
    v_ageyears := _r1.c1;
    v_agemonth := _r1.c2;
    v_agedays := _r1.c3;
  END LOOP;
  v_ageyears := coalesce(v_ageyears, 0);
  v_agemonth := coalesce(v_agemonth, 0);
  v_agedays := coalesce(v_agedays, 0);
  -- SET NOCOUNT OFF
  return_value := 0;
  ageyears := v_ageyears;
  agemonth := v_agemonth;
  agedays := v_agedays;
  RETURN;
  return_value := 0;
  ageyears := v_ageyears;
  agemonth := v_agemonth;
  agedays := v_agedays;
  RETURN;
END
$body$;

-- ==== proc sp_GetPatientDischargeability ====
CREATE OR REPLACE FUNCTION dbo.sp_getpatientdischargeability(l_admissioncode integer, INOUT l_status integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_l_admissioncode integer;
  v_l_status integer;
BEGIN
  v_l_admissioncode := l_admissioncode;
  v_l_status := l_status;
  SELECT coalesce(count(admissioncode), 0) INTO v_l_status FROM dbo.saleledger WHERE ((admissioncode = v_l_admissioncode) AND (posted = 'N'));
  IF ((v_l_status = 0) OR (v_l_status = NULL)) THEN
    SELECT coalesce(count(admissioncode), 0) INTO v_l_status FROM dbo.srledger WHERE ((admissioncode = v_l_admissioncode) AND (posted = 'N'));
  END IF;
  return_value := 0;
  l_status := v_l_status;
  RETURN;
END
$body$;

-- ==== proc SP_GetPatientInfo ====
CREATE OR REPLACE FUNCTION dbo.sp_getpatientinfo(patientcode integer, INOUT regno citext, INOUT patientname citext, INOUT fname citext, INOUT dob timestamp, INOUT gender citext, INOUT custcode integer, INOUT address1 citext, INOUT address2 citext, INOUT phone citext, INOUT ageyears integer, INOUT agemonths integer, INOUT agedays integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_patientcode integer;
  v_regno citext;
  v_patientname citext;
  v_fname citext;
  v_dob timestamp(3);
  v_gender citext;
  v_custcode integer;
  v_address1 citext;
  v_address2 citext;
  v_phone citext;
  v_ageyears integer;
  v_agemonths integer;
  v_agedays integer;
  _r1 record;
BEGIN
  v_patientcode := patientcode;
  v_regno := regno;
  v_patientname := patientname;
  v_fname := fname;
  v_dob := dob;
  v_gender := gender;
  v_custcode := custcode;
  v_address1 := address1;
  v_address2 := address2;
  v_phone := phone;
  v_ageyears := ageyears;
  v_agemonths := agemonths;
  v_agedays := agedays;
  FOR _r1 IN SELECT p.regno AS c1, p.name AS c2, p.fname AS c3, p.dob AS c4, p.gender AS c5, p.custcode AS c6, p.address1 AS c7, p.address2 AS c8, p.phone AS c9 FROM dbo.patient AS p WHERE (p.patientcode = v_patientcode) LOOP
    v_regno := _r1.c1;
    v_patientname := _r1.c2;
    v_fname := _r1.c3;
    v_dob := _r1.c4;
    v_gender := _r1.c5;
    v_custcode := _r1.c6;
    v_address1 := _r1.c7;
    v_address2 := _r1.c8;
    v_phone := _r1.c9;
  END LOOP;
  IF (v_patientname IS NOT NULL) THEN
    SELECT r.ageyears, r.agemonth, r.agedays INTO v_ageyears, v_agemonths, v_agedays FROM dbo.sp_getpatientage(patientcode => v_patientcode, ageyears => v_ageyears, agemonth => v_agemonths, agedays => v_agedays) AS r;
  END IF;
  return_value := 0;
  regno := v_regno;
  patientname := v_patientname;
  fname := v_fname;
  dob := v_dob;
  gender := v_gender;
  custcode := v_custcode;
  address1 := v_address1;
  address2 := v_address2;
  phone := v_phone;
  ageyears := v_ageyears;
  agemonths := v_agemonths;
  agedays := v_agedays;
  RETURN;
  return_value := 0;
  regno := v_regno;
  patientname := v_patientname;
  fname := v_fname;
  dob := v_dob;
  gender := v_gender;
  custcode := v_custcode;
  address1 := v_address1;
  address2 := v_address2;
  phone := v_phone;
  ageyears := v_ageyears;
  agemonths := v_agemonths;
  agedays := v_agedays;
  RETURN;
END
$body$;

-- ==== proc SP_GetPriceFromServicePricePolicy ====
CREATE OR REPLACE FUNCTION dbo.sp_getpricefromservicepricepolicy(servicecode integer, INOUT price numeric, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_servicecode integer;
  v_price numeric(12,2);
  v_pricepolicycode smallint;
BEGIN
  v_servicecode := servicecode;
  v_price := price;
  IF ((v_servicecode IS NULL) OR (v_servicecode < 0)) THEN
    v_price := NULL;
    RAISE EXCEPTION 'Problem occured while fetching Service Price, Service is null';
    return_value := -1;
    price := v_price;
    RETURN;
  END IF;
  v_pricepolicycode := (SELECT max(servicepricepolicycode) FROM dbo.servicepricepolicy WHERE ((localtimestamp(3) BETWEEN startdate AND enddate) AND (servicecode = v_servicecode)));
  IF (v_pricepolicycode IS NULL) THEN
    v_price := NULL;
    return_value := 0;
    price := v_price;
    RETURN;
  ELSE
    v_price := coalesce((SELECT coalesce(d.price, 0) FROM dbo.servicepricepolicydetail AS d WHERE ((d.servicepricepolicycode = v_pricepolicycode) AND (d.weekdaycode = (extract(dow from localtimestamp(3))::integer + 1)))), 0);
  END IF;
  return_value := 0;
  price := v_price;
  RETURN;
  return_value := 0;
  price := v_price;
  RETURN;
END
$body$;

-- ==== proc SP_GetPricePolicyBased_ItemPrice ====
CREATE OR REPLACE FUNCTION dbo.sp_getpricepolicybased_itemprice(usercode integer, icode integer, qtysold numeric, INOUT price numeric, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_usercode integer;
  v_icode integer;
  v_qtysold numeric(15,4);
  v_price numeric(15,4);
  v_getprice integer;
  v_getitemflatdisc integer;
  v_getitemdiscperc integer;
  v_pricepolicycode integer;
  v_packunits integer;
BEGIN
  v_usercode := usercode;
  v_icode := icode;
  v_qtysold := qtysold;
  v_price := price;
  v_getprice := coalesce((SELECT rightcode FROM dbo.grouprights WHERE ((groupcode IN (SELECT min(groupcode) FROM dbo.usergroups WHERE (usercode = v_usercode))) AND (rightcode = 5070))), 0);
  v_getitemflatdisc := coalesce((SELECT rightcode FROM dbo.grouprights WHERE ((groupcode IN (SELECT min(groupcode) FROM dbo.usergroups WHERE (usercode = v_usercode))) AND (rightcode = 5071))), 0);
  v_getitemdiscperc := coalesce((SELECT rightcode FROM dbo.grouprights WHERE ((groupcode IN (SELECT min(groupcode) FROM dbo.usergroups WHERE (usercode = v_usercode))) AND (rightcode = 5072))), 0);
  IF ((v_usercode IS NULL) OR (v_usercode < 0)) THEN
    v_price := NULL;
    RAISE EXCEPTION 'Problem occured while fetching Item Price, User is Not Valid / null';
    return_value := -1;
    price := v_price;
    RETURN;
  END IF;
  IF ((v_icode IS NULL) OR (v_icode < 0)) THEN
    v_price := NULL;
    RAISE EXCEPTION 'Problem occured while fetching Item Price, Item is not valid / null';
    return_value := -1;
    price := v_price;
    RETURN;
  END IF;
  v_pricepolicycode := (SELECT pricepolicycode FROM dbo.pricepolicy WHERE (icode = v_icode));
  v_packunits := (SELECT item.packunits FROM dbo.item WHERE (item.icode = v_icode));
  IF (v_packunits = 0) THEN
    v_packunits := 1;
  END IF;
  IF (v_pricepolicycode IS NULL) THEN
    v_price := NULL;
    return_value := 0;
    price := v_price;
    RETURN;
  ELSE
    v_price := (SELECT round((((((CASE WHEN (v_getprice > 0) THEN (d.price / v_packunits) ELSE coalesce((SELECT (i.saleprice / v_packunits) FROM dbo.item AS i WHERE (i.icode = v_icode)), v_price) END - CASE WHEN (v_getitemflatdisc > 0) THEN d.itemflatdisc ELSE 0 END)) * ((1 - (CASE WHEN (v_getitemdiscperc > 0) THEN d.discperc ELSE 0 END * 0.01))))))::numeric, 2) FROM dbo.pricepolicydetail AS d, (SELECT min(qtylimit) AS qtylimit FROM dbo.pricepolicydetail WHERE (((expirydate >= (date_trunc('day', localtimestamp(3)))::timestamp(3)) AND (pricepolicycode = v_pricepolicycode)) AND (qtylimit >= v_qtysold)) UNION SELECT max(qtylimit) AS qtylimit FROM dbo.pricepolicydetail WHERE (((expirydate >= (date_trunc('day', localtimestamp(3)))::timestamp(3)) AND (pricepolicycode = v_pricepolicycode)) AND (qtylimit <= v_qtysold))) AS t WHERE ((((expirydate >= (date_trunc('day', localtimestamp(3)))::timestamp(3)) AND (pricepolicycode = v_pricepolicycode)) AND (d.qtylimit = t.qtylimit)) AND (t.qtylimit <= v_qtysold)));
  END IF;
  return_value := 0;
  price := v_price;
  RETURN;
  return_value := 0;
  price := v_price;
  RETURN;
END
$body$;

