-- ==== proc sp_getRandomValueTable ====
CREATE OR REPLACE FUNCTION dbo.sp_getrandomvaluetable(rows integer, max_randomvalue integer, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_rows integer;
  v_max_randomvalue integer;
  v_counter integer;
  v_randomvalue integer;
BEGIN
  v_rows := rows;
  v_max_randomvalue := max_randomvalue;
  DROP TABLE IF EXISTS tv_sp_getrandomvaluetable_randomtable;
  CREATE TEMP TABLE tv_sp_getrandomvaluetable_randomtable (
    lineid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    randomvalue integer NOT NULL
) ON COMMIT DROP;
  v_counter := 1;
  IF ((v_rows <= 0)) THEN
    v_rows := 1;
  END IF;
  WHILE ((v_counter <= v_rows)) LOOP
    -- WaitFor Delay '00:00:00.003'
    RAISE EXCEPTION 'untranslated T-SQL (WAITFOR)' USING ERRCODE = '0A000';
    v_randomvalue := trunc((random() * v_max_randomvalue))::integer;
    IF ((v_randomvalue = 0)) THEN
      v_randomvalue := 1;
    END IF;
    INSERT INTO tv_sp_getrandomvaluetable_randomtable (randomvalue) VALUES (v_randomvalue);
    v_counter := (v_counter + 1);
  END LOOP;
  OPEN rs1 FOR SELECT lineid, randomvalue FROM tv_sp_getrandomvaluetable_randomtable AS randomtable;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_GetReceiptCategoryCounter ====
CREATE OR REPLACE FUNCTION dbo.sp_getreceiptcategorycounter(category smallint, INOUT counter integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_category smallint;
  v_counter integer;
  v_err integer;
  v_rowcount integer;
  _r1 record;
  _rc integer;
BEGIN
  v_category := category;
  v_counter := counter;
  -- SET NOCOUNT On
  _rc := 0;
  FOR _r1 IN SELECT counter AS c1 FROM dbo.receiptcategory WHERE (receiptcategorycode = v_category) FOR UPDATE OF receiptcategory LOOP
    _rc := _rc + 1;
    v_counter := _r1.c1;
  END LOOP;
  v_err := 0;
  v_rowcount := _rc;
  _rc := 1;
  IF ((v_err = 0) AND (v_rowcount > 0)) THEN
    v_counter := (v_counter + 1);
    _rc := 1;
    UPDATE dbo.receiptcategory SET counter = v_counter WHERE (receiptcategorycode = v_category);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_err := 0;
    v_rowcount := _rc;
    _rc := 1;
    IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
      -- SET NOCOUNT OFF
      RAISE EXCEPTION 'Exception occured in updating receipt category counter';
      return_value := -1;
      counter := v_counter;
      RETURN;
    END IF;
  ELSE
    -- SET NOCOUNT OFF
    RAISE EXCEPTION 'Exception occured in fetching receipt category counter';
    return_value := -1;
    counter := v_counter;
    RETURN;
  END IF;
  -- SET NOCOUNT OFF
  return_value := 0;
  counter := v_counter;
  RETURN;
  return_value := 0;
  counter := v_counter;
  RETURN;
END
$body$;

