-- ==== proc SP_GetSaleInvBalance ====
CREATE OR REPLACE FUNCTION dbo.sp_getsaleinvbalance(ai_saleinvcode integer, INOUT an_balance numeric, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_saleinvcode integer;
  v_an_balance numeric(15,2);
  _r1 record;
BEGIN
  v_ai_saleinvcode := ai_saleinvcode;
  v_an_balance := an_balance;
  FOR _r1 IN SELECT saleledger.outstandingamt AS c1 FROM dbo.saleledger WHERE ((((saleledger.saleinvcode = v_ai_saleinvcode) AND (saleledger.marked = 'N')) AND (saleledger.posted = 'Y')) AND (saleledger.accountfor = 'Y')) LOOP
    v_an_balance := _r1.c1;
  END LOOP;
  return_value := 0;
  an_balance := v_an_balance;
  RETURN;
END
$body$;

-- ==== proc SP_GetSaleInvoice_JSON ====
CREATE OR REPLACE FUNCTION dbo.sp_getsaleinvoice_json(saleinvcode integer, INOUT "json" citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_saleinvcode integer;
  v_json citext;
  v_qry citext;
  v_q citext;
  v_posid citext;
  cur_c1 refcursor;
  _fs integer := -1;
BEGIN
  v_saleinvcode := saleinvcode;
  v_json := "json";
  -- SET NOCOUNT ON
  v_posid := coalesce(dbo.fn_getpreference('FBRPOSID'), '');
  v_qry := '';
  OPEN cur_c1 FOR SELECT a FROM (SELECT (((((((((((((((((((((((('{"InvoiceNumber":"","POSID":"' || v_posid) || '","USIN":"') || ltrim(rtrim(dbo.tsql_str((s.saleinvcode)::numeric)))) || '","DateTime":"') || left(to_char(s.date, 'YYYY-MM-DD HH24:MI:SS.MS'), 100)) || '","BuyerNTN":"') || coalesce(c.ntnno, '')) || '","BuyerCNIC":"') || coalesce(c.nic, '')) || '","BuyerName":"') || coalesce(a.name, '')) || '","BuyerPhoneNumber":"') || coalesce(c.phone, '')) || '","TotalBillAmount":"') || ltrim(rtrim(dbo.tsql_str((s.invtotal)::numeric, 12, 2)))) || '","TotalQuantity":"') || ltrim(rtrim(dbo.tsql_str((coalesce((SELECT sum((d.looseqty + d.bonusqty)) FROM dbo.saledetail AS d WHERE (d.saleinvcode = v_saleinvcode)), 0))::numeric)))) || '","TotalSaleValue":"') || ltrim(rtrim(dbo.tsql_str(((coalesce(s.invtotal, 0) - coalesce(dbo.fn_gettaxonsaleinv((s.saleinvcode)::integer), 0)))::numeric, 12, 2)))) || '","TotalTaxCharged":"') || ltrim(rtrim(dbo.tsql_str((dbo.fn_gettaxonsaleinv((s.saleinvcode)::integer))::numeric, 12, 2)))) || '","Discount":"') || ltrim(rtrim(dbo.tsql_str((coalesce((SELECT sum(round(((((d.looseqty * d.itemflatdisc)) + (((d.looseqty * ((d.saleprice - d.itemflatdisc))) * ((d.discperc * 0.01))))))::numeric, 2)) FROM dbo.saledetail AS d WHERE (d.saleinvcode = v_saleinvcode)), 0))::numeric, 12, 2)))) || '","FurtherTax":"0.0","PaymentMode":"1","RefUSIN":"null","InvoiceType":"1","Items":[') AS a FROM dbo.saleledger AS s, dbo.customer AS c, dbo.accounts AS a WHERE (((s.saleinvcode = v_saleinvcode) AND (s.custcode = c.custcode)) AND (s.custcode = a.acccode)) UNION ALL SELECT (((((((((((((((((('{"ItemCode":"' || i.customicode) || '","ItemName":"') || i.name) || '","Quantity":"') || ltrim(rtrim(dbo.tsql_str(((d.looseqty + d.bonusqty))::numeric, 10, 4)))) || '","PCTCode":"') || p.description) || '","TaxRate":"') || ltrim(rtrim(dbo.tsql_str((sts.taxperc)::numeric, 6, 2)))) || '","SaleValue":"') || ltrim(rtrim(dbo.tsql_str(((d.looseqty * d.saleprice))::numeric, 12, 2)))) || '","TotalAmount":"') || ltrim(rtrim(dbo.tsql_str(((d.looseqty * d.saleprice))::numeric, 12, 2)))) || '","TaxCharged":"') || ltrim(rtrim(dbo.tsql_str(((((d.looseqty + d.bonusqty)) * d.unitsalestax))::numeric, 12, 2)))) || '","Discount":"') || ltrim(rtrim(dbo.tsql_str((round(((((d.looseqty * d.itemflatdisc)) + (((d.looseqty * ((d.saleprice - d.itemflatdisc))) * ((d.discperc * 0.01))))))::numeric, 2))::numeric, 12, 2)))) || '","FurtherTax":"0.0","InvoiceType":"1","RefUSIN":"null"},') AS a FROM dbo.saledetail AS d, dbo.item AS i, dbo.pct AS p, dbo.salestaxschedule AS sts WHERE ((((d.saleinvcode = v_saleinvcode) AND (d.icode = i.icode)) AND (i.pctcode = p.pctcode)) AND (i.salestaxschedulecode = sts.salestaxschedulecode))) AS t;
  FETCH NEXT FROM cur_c1 INTO v_q;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    v_qry := (v_qry || v_q);
    FETCH NEXT FROM cur_c1 INTO v_q;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  v_json := '';
  IF ((right(v_qry, 1))::citext = ',') THEN
    v_qry := left(v_qry, (length(rtrim(v_qry)) - 1));
  END IF;
  v_json := (v_qry || ']}');
  RAISE NOTICE '%', v_json;
  CLOSE cur_c1;
  -- DEALLOCATE C1
  return_value := 0;
  "json" := v_json;
  RETURN;
  return_value := 0;
  "json" := v_json;
  RETURN;
END
$body$;

-- ==== proc sp_GetSatisfiedQty_For_Prescription ====
CREATE OR REPLACE FUNCTION dbo.sp_getsatisfiedqty_for_prescription(prescode integer, icode integer, INOUT satisfiedqty numeric, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_prescode integer;
  v_icode integer;
  v_satisfiedqty numeric(15,4);
BEGIN
  v_prescode := prescode;
  v_icode := icode;
  v_satisfiedqty := satisfiedqty;
  v_satisfiedqty := 0;
  v_satisfiedqty := (SELECT coalesce(sum(looseqty), 0) FROM dbo.saleledger AS sl JOIN dbo.saledetail AS sd ON (((sl.saleinvcode = sd.saleinvcode) AND (sl.prescode = v_prescode)) AND (sd.icode = v_icode)));
  IF ((v_satisfiedqty IS NULL)) THEN
    v_satisfiedqty := 0;
  END IF;
  return_value := 0;
  satisfiedqty := v_satisfiedqty;
  RETURN;
END
$body$;

-- ==== proc SP_GetService_AliasName ====
CREATE OR REPLACE FUNCTION dbo.sp_getservice_aliasname(usercode integer, aliasname citext, INOUT servicecode integer, INOUT servicename citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_usercode integer;
  v_aliasname citext;
  v_servicecode integer;
  v_servicename citext;
  v_groupcode integer;
  v_tempcode integer;
  v_retcode integer;
  v_err integer;
  v_rowcount integer;
  _r1 record;
  _r2 record;
  _rc integer;
BEGIN
  v_usercode := usercode;
  v_aliasname := aliasname;
  v_servicecode := servicecode;
  v_servicename := servicename;
  v_retcode := 0;
  _rc := 1;
  v_groupcode := (SELECT min(groupcode) FROM dbo.usergroups WHERE (usercode = v_usercode));
  _rc := 1;
  v_err := 0;
  v_rowcount := _rc;
  _rc := 1;
  IF ((v_err = 0) AND (v_rowcount = 1)) THEN
    IF ((dbo.fn_getpreference('EnableServiceCatRights'))::citext = 'Y') THEN
      _rc := 0;
      FOR _r1 IN SELECT service.servicecode AS c1, service.name AS c2 FROM dbo.service WHERE (((service.active = 'Y') AND (service.aliasname = v_aliasname)) AND (service.servicecatcode IN (SELECT servicecatcode FROM dbo.groupallowedservicecategory WHERE (groupcode = v_groupcode)))) LOOP
        _rc := _rc + 1;
        v_servicecode := _r1.c1;
        v_servicename := _r1.c2;
      END LOOP;
      v_err := 0;
      v_rowcount := _rc;
      _rc := 1;
      IF (v_err <> 0) THEN
        RAISE EXCEPTION 'Unable to fetch Service Alias Name = %', v_aliasname;
        v_retcode := -1;
        _rc := 1;
        return_value := v_retcode;
        servicecode := v_servicecode;
        servicename := v_servicename;
        RETURN;
      END IF;
    ELSE
      _rc := 0;
      FOR _r2 IN SELECT service.servicecode AS c1, service.name AS c2 FROM dbo.service WHERE ((service.active = 'Y') AND (service.aliasname = v_aliasname)) LOOP
        _rc := _rc + 1;
        v_servicecode := _r2.c1;
        v_servicename := _r2.c2;
      END LOOP;
      v_err := 0;
      v_rowcount := _rc;
      _rc := 1;
      IF (v_err <> 0) THEN
        RAISE EXCEPTION 'Unable to fetch Service Alias Name = %', v_aliasname;
        v_retcode := -1;
        _rc := 1;
        return_value := v_retcode;
        servicecode := v_servicecode;
        servicename := v_servicename;
        RETURN;
      END IF;
    END IF;
  ELSE
    RAISE EXCEPTION 'Unable to fetch group code for user code = %', v_usercode;
    return_value := -1;
    servicecode := v_servicecode;
    servicename := v_servicename;
    RETURN;
  END IF;
  IF (v_servicecode IS NULL) THEN
    RAISE EXCEPTION 'Unable to fetch Service Alias Name = %', v_aliasname;
    v_retcode := -1;
    _rc := 1;
    return_value := v_retcode;
    servicecode := v_servicecode;
    servicename := v_servicename;
    RETURN;
  END IF;
  return_value := v_retcode;
  servicecode := v_servicecode;
  servicename := v_servicename;
  RETURN;
  return_value := 0;
  servicecode := v_servicecode;
  servicename := v_servicename;
  RETURN;
END
$body$;

-- ==== proc SP_GetServiceInfo ====
CREATE OR REPLACE FUNCTION dbo.sp_getserviceinfo(serviceinvcode integer, INOUT servicedate timestamp, INOUT patientcode integer, INOUT regno citext, INOUT patientname citext, INOUT fname citext, INOUT dob timestamp, INOUT gender citext, INOUT custcode integer, INOUT address1 citext, INOUT address2 citext, INOUT phone citext, INOUT ageyears integer, INOUT agemonths integer, INOUT agedays integer, INOUT admissioncode integer, INOUT patientlocation integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_serviceinvcode integer;
  v_servicedate timestamp(3);
  v_patientcode integer;
  v_regno citext;
  v_patientname citext;
  v_fname citext;
  v_dob timestamp(3);
  v_gender citext;
  v_custcode integer;
  v_address1 citext;
  v_address2 citext;
  v_phone citext;
  v_ageyears integer;
  v_agemonths integer;
  v_agedays integer;
  v_admissioncode integer;
  v_patientlocation integer;
  _r1 record;
  _r2 record;
BEGIN
  v_serviceinvcode := serviceinvcode;
  v_servicedate := servicedate;
  v_patientcode := patientcode;
  v_regno := regno;
  v_patientname := patientname;
  v_fname := fname;
  v_dob := dob;
  v_gender := gender;
  v_custcode := custcode;
  v_address1 := address1;
  v_address2 := address2;
  v_phone := phone;
  v_ageyears := ageyears;
  v_agemonths := agemonths;
  v_agedays := agedays;
  v_admissioncode := admissioncode;
  v_patientlocation := patientlocation;
  -- SET NOCOUNT ON
  FOR _r1 IN SELECT sh.date AS c1, (SELECT p.patientcode FROM dbo.patient AS p WHERE (p.patientcode IN (SELECT sh.patientcode AS patientcode UNION ALL SELECT pa.patientcode FROM dbo.patientadmission AS pa WHERE (pa.admissioncode = sh.admissioncode)))) AS c2, sh.admissioncode AS c3 FROM dbo.serviceheader AS sh WHERE (sh.serviceinvcode = v_serviceinvcode) LOOP
    v_servicedate := _r1.c1;
    v_patientcode := _r1.c2;
    v_admissioncode := _r1.c3;
  END LOOP;
  IF (v_serviceinvcode > 0) THEN
    IF (v_patientcode > 0) THEN
      SELECT r.regno, r.patientname, r.fname, r.dob, r.gender, r.custcode, r.address1, r.address2, r.phone, r.ageyears, r.agemonths, r.agedays INTO v_regno, v_patientname, v_fname, v_dob, v_gender, v_custcode, v_address1, v_address2, v_phone, v_ageyears, v_agemonths, v_agedays FROM dbo.sp_getpatientinfo(patientcode => v_patientcode, regno => v_regno, patientname => v_patientname, fname => v_fname, dob => v_dob, gender => v_gender, custcode => v_custcode, address1 => v_address1, address2 => v_address2, phone => v_phone, ageyears => v_ageyears, agemonths => v_agemonths, agedays => v_agedays) AS r;
    END IF;
    IF (v_admissioncode > 0) THEN
      FOR _r2 IN SELECT pa.locationcode AS c1 FROM dbo.patientadmission AS pa WHERE (pa.admissioncode = v_admissioncode) LOOP
        v_patientlocation := _r2.c1;
      END LOOP;
    END IF;
  END IF;
  return_value := 0;
  servicedate := v_servicedate;
  patientcode := v_patientcode;
  regno := v_regno;
  patientname := v_patientname;
  fname := v_fname;
  dob := v_dob;
  gender := v_gender;
  custcode := v_custcode;
  address1 := v_address1;
  address2 := v_address2;
  phone := v_phone;
  ageyears := v_ageyears;
  agemonths := v_agemonths;
  agedays := v_agedays;
  admissioncode := v_admissioncode;
  patientlocation := v_patientlocation;
  RETURN;
  return_value := 0;
  servicedate := v_servicedate;
  patientcode := v_patientcode;
  regno := v_regno;
  patientname := v_patientname;
  fname := v_fname;
  dob := v_dob;
  gender := v_gender;
  custcode := v_custcode;
  address1 := v_address1;
  address2 := v_address2;
  phone := v_phone;
  ageyears := v_ageyears;
  agemonths := v_agemonths;
  agedays := v_agedays;
  admissioncode := v_admissioncode;
  patientlocation := v_patientlocation;
  RETURN;
END
$body$;

