-- ==== proc SP_GetServiceRowInfo ====
CREATE OR REPLACE FUNCTION dbo.sp_getservicerowinfo(servicerowid integer, INOUT serviceinvcode integer, INOUT servicedate timestamp, INOUT patientcode integer, INOUT regno citext, INOUT patientname citext, INOUT fname citext, INOUT dob timestamp, INOUT gender citext, INOUT custcode integer, INOUT address1 citext, INOUT address2 citext, INOUT phone citext, INOUT ageyears integer, INOUT agemonths integer, INOUT agedays integer, INOUT admissioncode integer, INOUT patientlocation integer, INOUT servicecode integer, INOUT deliverydate timestamp, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_servicerowid integer;
  v_serviceinvcode integer;
  v_servicedate timestamp(3);
  v_patientcode integer;
  v_regno citext;
  v_patientname citext;
  v_fname citext;
  v_dob timestamp(3);
  v_gender citext;
  v_custcode integer;
  v_address1 citext;
  v_address2 citext;
  v_phone citext;
  v_ageyears integer;
  v_agemonths integer;
  v_agedays integer;
  v_admissioncode integer;
  v_patientlocation integer;
  v_servicecode integer;
  v_deliverydate timestamp(3);
  _r1 record;
  _r2 record;
BEGIN
  v_servicerowid := servicerowid;
  v_serviceinvcode := serviceinvcode;
  v_servicedate := servicedate;
  v_patientcode := patientcode;
  v_regno := regno;
  v_patientname := patientname;
  v_fname := fname;
  v_dob := dob;
  v_gender := gender;
  v_custcode := custcode;
  v_address1 := address1;
  v_address2 := address2;
  v_phone := phone;
  v_ageyears := ageyears;
  v_agemonths := agemonths;
  v_agedays := agedays;
  v_admissioncode := admissioncode;
  v_patientlocation := patientlocation;
  v_servicecode := servicecode;
  v_deliverydate := deliverydate;
  -- SET NOCOUNT ON
  FOR _r1 IN SELECT sd.serviceinvcode AS c1, sh.date AS c2, (SELECT p.patientcode FROM dbo.patient AS p WHERE (p.patientcode IN (SELECT sh.patientcode AS patientcode UNION ALL SELECT pa.patientcode FROM dbo.patientadmission AS pa WHERE (pa.admissioncode = sh.admissioncode)))) AS c3, sh.admissioncode AS c4, sd.servicecode AS c5, sd.deliverydate AS c6 FROM dbo.servicedetail AS sd, dbo.serviceheader AS sh WHERE ((sd.srvrowid = v_servicerowid) AND (sd.serviceinvcode = sh.serviceinvcode)) LOOP
    v_serviceinvcode := _r1.c1;
    v_servicedate := _r1.c2;
    v_patientcode := _r1.c3;
    v_admissioncode := _r1.c4;
    v_servicecode := _r1.c5;
    v_deliverydate := _r1.c6;
  END LOOP;
  IF ((v_serviceinvcode > 0) AND (v_servicecode > 0)) THEN
    IF (v_patientcode > 0) THEN
      SELECT r.regno, r.patientname, r.fname, r.dob, r.gender, r.custcode, r.address1, r.address2, r.phone, r.ageyears, r.agemonths, r.agedays INTO v_regno, v_patientname, v_fname, v_dob, v_gender, v_custcode, v_address1, v_address2, v_phone, v_ageyears, v_agemonths, v_agedays FROM dbo.sp_getpatientinfo(patientcode => v_patientcode, regno => v_regno, patientname => v_patientname, fname => v_fname, dob => v_dob, gender => v_gender, custcode => v_custcode, address1 => v_address1, address2 => v_address2, phone => v_phone, ageyears => v_ageyears, agemonths => v_agemonths, agedays => v_agedays) AS r;
    END IF;
    IF (v_admissioncode > 0) THEN
      FOR _r2 IN SELECT pa.locationcode AS c1 FROM dbo.patientadmission AS pa WHERE (pa.admissioncode = v_admissioncode) LOOP
        v_patientlocation := _r2.c1;
      END LOOP;
    END IF;
  END IF;
  return_value := 0;
  serviceinvcode := v_serviceinvcode;
  servicedate := v_servicedate;
  patientcode := v_patientcode;
  regno := v_regno;
  patientname := v_patientname;
  fname := v_fname;
  dob := v_dob;
  gender := v_gender;
  custcode := v_custcode;
  address1 := v_address1;
  address2 := v_address2;
  phone := v_phone;
  ageyears := v_ageyears;
  agemonths := v_agemonths;
  agedays := v_agedays;
  admissioncode := v_admissioncode;
  patientlocation := v_patientlocation;
  servicecode := v_servicecode;
  deliverydate := v_deliverydate;
  RETURN;
  return_value := 0;
  serviceinvcode := v_serviceinvcode;
  servicedate := v_servicedate;
  patientcode := v_patientcode;
  regno := v_regno;
  patientname := v_patientname;
  fname := v_fname;
  dob := v_dob;
  gender := v_gender;
  custcode := v_custcode;
  address1 := v_address1;
  address2 := v_address2;
  phone := v_phone;
  ageyears := v_ageyears;
  agemonths := v_agemonths;
  agedays := v_agedays;
  admissioncode := v_admissioncode;
  patientlocation := v_patientlocation;
  servicecode := v_servicecode;
  deliverydate := v_deliverydate;
  RETURN;
END
$body$;

