-- ==== proc SP_GetSRInvoice_JSON ====
CREATE OR REPLACE FUNCTION dbo.sp_getsrinvoice_json(srinvcode integer, INOUT "json" citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srinvcode integer;
  v_json citext;
  v_qry citext;
  v_q citext;
  v_posid citext;
  cur_c1 refcursor;
  _fs integer := -1;
BEGIN
  v_srinvcode := srinvcode;
  v_json := "json";
  -- SET NOCOUNT ON
  v_posid := coalesce(dbo.fn_getpreference('FBRPOSID'), '');
  v_qry := '';
  OPEN cur_c1 FOR SELECT a FROM (SELECT (((((((((((((((((('{"InvoiceNumber":"","POSID":"' || v_posid) || '","USIN":"') || ltrim(rtrim(dbo.tsql_str((srinvcode)::numeric)))) || '","DateTime":"') || left(to_char(date, 'YYYY-MM-DD HH24:MI:SS.MS'), 100)) || '","BuyerNTN":"","BuyerCNIC":"","BuyerName":"","BuyerPhoneNumber":"","TotalBillAmount":"') || ltrim(rtrim(dbo.tsql_str((invtotal)::numeric, 12, 2)))) || '","TotalQuantity":"') || ltrim(rtrim(dbo.tsql_str((coalesce((SELECT sum((d.looseqty + d.bonusqty)) FROM dbo.srdetail AS d WHERE (d.srinvcode = v_srinvcode)), 0))::numeric)))) || '","TotalSaleValue":"') || ltrim(rtrim(dbo.tsql_str(((coalesce(invtotal, 0) - coalesce(dbo.fn_gettaxonsrinv((srinvcode)::integer), 0)))::numeric, 12, 2)))) || '","TotalTaxCharged":"') || ltrim(rtrim(dbo.tsql_str((dbo.fn_gettaxonsrinv((srinvcode)::integer))::numeric, 12, 2)))) || '","Discount":"') || ltrim(rtrim(dbo.tsql_str((coalesce((SELECT sum(round(((((d.looseqty * d.srprice) * ((d.discperc * 0.01)))))::numeric, 2)) FROM dbo.srdetail AS d WHERE (d.srinvcode = v_srinvcode)), 0))::numeric, 12, 2)))) || '","FurtherTax":"0.0","PaymentMode":"1","RefUSIN":"') || ltrim(rtrim(coalesce(dbo.tsql_str((saleinvcode)::numeric), 'null')))) || '","InvoiceType":"3","Items":[') AS a FROM dbo.srledger WHERE (srinvcode = v_srinvcode) UNION ALL SELECT (((((((((((((((((((('{"ItemCode":"' || i.customicode) || '","ItemName":"') || i.name) || '","Quantity":"') || ltrim(rtrim(dbo.tsql_str(((d.looseqty + d.bonusqty))::numeric, 10, 4)))) || '","PCTCode":"') || p.description) || '","TaxRate":"') || ltrim(rtrim(dbo.tsql_str((sts.taxperc)::numeric, 6, 2)))) || '","SaleValue":"') || ltrim(rtrim(dbo.tsql_str(((d.looseqty * d.srprice))::numeric, 12, 2)))) || '","TotalAmount":"') || ltrim(rtrim(dbo.tsql_str(((d.looseqty * d.srprice))::numeric, 12, 2)))) || '","TaxCharged":"') || ltrim(rtrim(dbo.tsql_str(((((d.looseqty + d.bonusqty)) * d.unitsalestax))::numeric, 12, 2)))) || '","Discount":"') || ltrim(rtrim(dbo.tsql_str((round(((((d.looseqty * d.srprice) * ((d.discperc * 0.01)))))::numeric, 2))::numeric, 12, 2)))) || '","FurtherTax":"0.0","InvoiceType":"3","RefUSIN":"') || ltrim(rtrim(coalesce(dbo.tsql_str((s.saleinvcode)::numeric), 'null')))) || '"},') AS a FROM dbo.srledger AS s, dbo.srdetail AS d, dbo.item AS i, dbo.pct AS p, dbo.salestaxschedule AS sts WHERE ((((((s.srinvcode = v_srinvcode) AND (d.srinvcode = v_srinvcode)) AND (s.srinvcode = d.srinvcode)) AND (d.icode = i.icode)) AND (i.pctcode = p.pctcode)) AND (i.salestaxschedulecode = sts.salestaxschedulecode))) AS t;
  FETCH NEXT FROM cur_c1 INTO v_q;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    v_qry := (v_qry || v_q);
    FETCH NEXT FROM cur_c1 INTO v_q;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  v_json := '';
  IF ((right(v_qry, 1))::citext = ',') THEN
    v_qry := left(v_qry, (length(rtrim(v_qry)) - 1));
  END IF;
  v_json := (v_qry || ']}');
  RAISE NOTICE '%', v_json;
  CLOSE cur_c1;
  -- DEALLOCATE C1
  return_value := 0;
  "json" := v_json;
  RETURN;
  return_value := 0;
  "json" := v_json;
  RETURN;
END
$body$;

-- ==== proc sp_GetTabMaxKey ====
CREATE OR REPLACE FUNCTION dbo.sp_gettabmaxkey(tabname citext, INOUT key integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_tabname citext;
  v_key integer;
  v_err integer;
  v_rowcount integer;
  _r1 record;
  _rc integer;
BEGIN
  v_tabname := tabname;
  v_key := key;
  -- SET NOCOUNT On
  _rc := 0;
  FOR _r1 IN SELECT tabmaxkey AS c1 FROM dbo._tabmaxkey WHERE (_tabmaxkey.tabname = v_tabname) FOR UPDATE OF _tabmaxkey LOOP
    _rc := _rc + 1;
    v_key := _r1.c1;
  END LOOP;
  v_err := 0;
  v_rowcount := _rc;
  _rc := 1;
  IF ((v_err = 0) AND (v_rowcount > 0)) THEN
    v_key := (v_key + 1);
    _rc := 1;
    UPDATE dbo._tabmaxkey SET tabmaxkey = v_key WHERE (_tabmaxkey.tabname = v_tabname);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_err := 0;
    v_rowcount := _rc;
    _rc := 1;
    IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
      -- SET NOCOUNT OFF
      RAISE EXCEPTION 'Exception occured in updating key for table %', v_tabname;
      return_value := -1;
      key := v_key;
      RETURN;
    END IF;
  ELSE
    -- SET NOCOUNT OFF
    RAISE EXCEPTION 'Exception occured in fetching key for table %', v_tabname;
    return_value := -1;
    key := v_key;
    RETURN;
  END IF;
  -- SET NOCOUNT OFF
  return_value := 0;
  key := v_key;
  RETURN;
  return_value := 0;
  key := v_key;
  RETURN;
END
$body$;

-- ==== proc SP_GetTransactionAmount ====
CREATE OR REPLACE FUNCTION dbo.sp_gettransactionamount(documentcode integer, INOUT amount numeric, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_documentcode integer;
  v_amount numeric(15,2);
BEGIN
  v_documentcode := documentcode;
  v_amount := amount;
  v_amount := coalesce((SELECT sum(x.amt) AS amt FROM (SELECT coalesce(t.cashcharged, 0) AS amt FROM dbo.transactionheader AS t WHERE (t.documentcode = v_documentcode) UNION ALL SELECT coalesce(sum(t.amount), 0) AS amt FROM dbo.transactiondetail AS t WHERE (t.documentcode = v_documentcode)) AS x), 0);
  return_value := 0;
  amount := v_amount;
  RETURN;
END
$body$;

