-- ==== proc SP_GetVersionInfo ====
CREATE OR REPLACE FUNCTION dbo.sp_getversioninfo(srv citext, db citext, owner citext, INOUT sequenceid integer, INOUT appversion integer, INOUT dbstatus integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_sequenceid integer;
  v_appversion integer;
  v_dbstatus integer;
  v_qry citext;
  _dq1 text;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  v_sequenceid := sequenceid;
  v_appversion := appversion;
  v_dbstatus := dbstatus;
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  DELETE FROM dbo.reportdata;
  v_qry := (((((('INSERT INTO REPORTDATA (code1, code2, code3) SELECT * FROM ' || v_srv) || '.') || v_db) || '.') || v_owner) || '.Sequence');
  _dq1 := v_qry;
  IF _dq1 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq1);
  END IF;
  v_sequenceid := trunc((SELECT code1 FROM dbo.reportdata))::integer;
  v_appversion := trunc((SELECT code2 FROM dbo.reportdata))::integer;
  v_dbstatus := trunc((SELECT code3 FROM dbo.reportdata))::integer;
  return_value := 0;
  sequenceid := v_sequenceid;
  appversion := v_appversion;
  dbstatus := v_dbstatus;
  RETURN;
END
$body$;

-- ==== proc SP_GetVoucherCode ====
CREATE OR REPLACE FUNCTION dbo.sp_getvouchercode(ai_vochcatcode integer, INOUT ai_vouchercode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_vochcatcode integer;
  v_ai_vouchercode integer;
  v_err integer;
  v_rowcount integer;
  v_catname citext;
  _r1 record;
  _rc integer;
BEGIN
  v_ai_vochcatcode := ai_vochcatcode;
  v_ai_vouchercode := ai_vouchercode;
  v_catname := (SELECT name FROM dbo.vochercategory WHERE (vochcatcode = v_ai_vochcatcode));
  _rc := 1;
  IF (v_catname IS NULL) THEN
    -- SET NOCOUNT OFF
    RAISE EXCEPTION 'Voucher category does not exists, wrong voucher category code passed';
    return_value := -1;
    ai_vouchercode := v_ai_vouchercode;
    RETURN;
  END IF;
  -- SET NOCOUNT On
  _rc := 0;
  FOR _r1 IN SELECT counter AS c1 FROM dbo.vochercategory WHERE (vochcatcode = v_ai_vochcatcode) FOR UPDATE OF vochercategory LOOP
    _rc := _rc + 1;
    v_ai_vouchercode := _r1.c1;
  END LOOP;
  v_err := 0;
  v_rowcount := _rc;
  _rc := 1;
  IF ((v_err = 0) AND (v_rowcount > 0)) THEN
    v_ai_vouchercode := (v_ai_vouchercode + 1);
    _rc := 1;
    UPDATE dbo.vochercategory SET counter = v_ai_vouchercode WHERE (vochercategory.vochcatcode = v_ai_vochcatcode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_err := 0;
    v_rowcount := _rc;
    _rc := 1;
    IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
      -- SET NOCOUNT OFF
      RAISE EXCEPTION 'Exception occured in updating counter for voucher category %', v_catname;
      return_value := -1;
      ai_vouchercode := v_ai_vouchercode;
      RETURN;
    END IF;
  ELSE
    -- SET NOCOUNT OFF
    RAISE EXCEPTION 'Exception occured in fetching voucher code for voucher category %', v_catname;
    return_value := -1;
    ai_vouchercode := v_ai_vouchercode;
    RETURN;
  END IF;
  -- SET NOCOUNT OFF
  return_value := 0;
  ai_vouchercode := v_ai_vouchercode;
  RETURN;
  return_value := 0;
  ai_vouchercode := v_ai_vouchercode;
  RETURN;
END
$body$;

-- ==== proc sp_GLOpeningBalance ====
CREATE OR REPLACE FUNCTION dbo.sp_glopeningbalance(l_date timestamp, l_acccode numeric, INOUT lf_balance double precision, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_l_date timestamp(3);
  v_l_acccode numeric(5,0);
  v_lf_balance double precision;
  v_l_balance numeric(11,2);
BEGIN
  v_l_date := l_date;
  v_l_acccode := l_acccode;
  v_lf_balance := lf_balance;
  DROP TABLE IF EXISTS tmp_tmpjv;
  CREATE TEMP TABLE tmp_tmpjv ON COMMIT DROP AS SELECT sum(gldetail.debit) AS debit, sum(gldetail.credit) AS credit FROM dbo.glheader, dbo.gldetail WHERE (((glheader.glvochcode = gldetail.glvochcode) AND (glheader.date <= v_l_date)) AND (gldetail.acccode = v_l_acccode));
  SELECT (CASE sum(debit) WHEN NULL THEN 0.0 ELSE sum(debit) END - CASE sum(credit) WHEN NULL THEN 0.0 ELSE sum(credit) END) INTO v_l_balance FROM tmp_tmpjv AS tmpjv;
  v_lf_balance := (v_l_balance)::double precision;
  DROP TABLE IF EXISTS tmp_tmpjv;
  return_value := 0;
  lf_balance := v_lf_balance;
  RETURN;
END
$body$;

-- ==== proc SP_GodownDetail_RepairForZeroDecimal ====
CREATE OR REPLACE FUNCTION dbo.sp_godowndetail_repairforzerodecimal(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_colprec integer;
  v_gd_err_rows integer;
BEGIN
  v_colprec := coalesce((SELECT colprecision FROM dbo.columnpreferences WHERE ((columnname = 'Qty') AND (colprecision = 0))), 0);
  IF (v_colprec = 0) THEN
    v_gd_err_rows := (SELECT count(icode) FROM dbo.godowndetail WHERE (currqty <> trunc(currqty)::integer));
    IF (v_gd_err_rows > 0) THEN
      UPDATE dbo.godowndetail SET currqty = round((currqty)::numeric, 0) WHERE (currqty <> trunc(currqty)::integer);
      DELETE FROM dbo.godowndetail WHERE (currqty = 0);
      UPDATE dbo.saledetail SET looseqty = round((looseqty)::numeric, 0) WHERE (looseqty <> trunc(looseqty)::integer);
      UPDATE dbo.saledetail SET bonusqty = round((bonusqty)::numeric, 0) WHERE (bonusqty <> trunc(bonusqty)::integer);
      UPDATE dbo.srdetail SET looseqty = round((looseqty)::numeric, 0) WHERE (looseqty <> trunc(looseqty)::integer);
      UPDATE dbo.srdetail SET bonusqty = round((bonusqty)::numeric, 0) WHERE (bonusqty <> trunc(bonusqty)::integer);
      UPDATE dbo.adjdetail SET looseqty = round((looseqty)::numeric, 0) WHERE (looseqty <> trunc(looseqty)::integer);
      UPDATE dbo.tdetail SET qty = round((qty)::numeric, 0) WHERE (qty <> trunc(qty)::integer);
      UPDATE dbo.duesatisfydetail SET duesatisfyqty = round((duesatisfyqty)::numeric, 0) WHERE (duesatisfyqty <> trunc(duesatisfyqty)::integer);
      UPDATE dbo.purdetail SET looseqty = round((looseqty)::numeric, 0) WHERE (looseqty <> trunc(looseqty)::integer);
      UPDATE dbo.purdetail SET packqty = round((packqty)::numeric, 0) WHERE (packqty <> trunc(packqty)::integer);
      UPDATE dbo.purdetail SET bonusqty = round((bonusqty)::numeric, 0) WHERE (bonusqty <> trunc(bonusqty)::integer);
    END IF;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_GodownItemOpeningStock ====
CREATE OR REPLACE FUNCTION dbo.sp_godownitemopeningstock(l_date timestamp, l_gcode integer, l_icode integer, INOUT l_godownqty numeric, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_l_date timestamp(3);
  v_l_gcode integer;
  v_l_icode integer;
  v_l_godownqty numeric(15,4);
  v_l_purqty numeric(15,4);
  v_l_purretqty numeric(15,4);
  v_l_saleqty numeric(15,4);
  v_l_saleretqty numeric(15,4);
  v_l_satisfyqty numeric(15,4);
  v_l_transferqty_increase numeric(15,4);
  v_l_transferqty_decrease numeric(15,4);
  v_l_issueqty numeric(15,4);
  v_l_receiptqty numeric(15,4);
  v_l_adjqty numeric(15,4);
BEGIN
  v_l_date := l_date;
  v_l_gcode := l_gcode;
  v_l_icode := l_icode;
  v_l_godownqty := l_godownqty;
  v_l_purqty := (SELECT coalesce(sum(CASE WHEN (purledger.purcatcode IN (3, 7, 8)) THEN ((purdetail.looseqty + ((purdetail.packqty * purdetail.packunits))) + purdetail.bonusqty) ELSE ((purdetail.looseqty + ((purdetail.packqty * purdetail.packunits))) + ((purdetail.bonusqty * purdetail.packunits))) END), 0) FROM dbo.purledger, dbo.purdetail WHERE (((((purledger.purinvcode = purdetail.purinvcode) AND (purdetail.gcode = v_l_gcode)) AND (purdetail.icode = v_l_icode)) AND (purledger.posted = 'Y')) AND (purledger.postdate < v_l_date)));
  v_l_purretqty := (SELECT coalesce(sum(((prdetail.looseqty + (prdetail.packqty * prdetail.packunits)) + prdetail.bonusqty)), 0) FROM dbo.prledger, dbo.prdetail WHERE (((((prledger.prinvcode = prdetail.prinvcode) AND (prdetail.gcode = v_l_gcode)) AND (prdetail.icode = v_l_icode)) AND (prledger.posted = 'Y')) AND (prledger.postdate < v_l_date)));
  v_l_saleqty := (SELECT coalesce(sum(((saledetail.looseqty + saledetail.bonusqty) + (saledetail.packqty * saledetail.packunits))), 0) FROM dbo.saleledger, dbo.saledetail WHERE (((((saleledger.saleinvcode = saledetail.saleinvcode) AND (saledetail.gcode = v_l_gcode)) AND (saledetail.icode = v_l_icode)) AND (saledetail.due IS NULL)) AND (saleledger.date < v_l_date)));
  v_l_saleretqty := (SELECT coalesce(sum(((srdetail.looseqty + srdetail.bonusqty) + (srdetail.packqty * srdetail.packunits))), 0) FROM dbo.srledger, dbo.srdetail WHERE (((((srledger.srinvcode = srdetail.srinvcode) AND (srdetail.gcode = v_l_gcode)) AND (srdetail.icode = v_l_icode)) AND (srledger.posted = 'Y')) AND (srledger.postdate < v_l_date)));
  v_l_satisfyqty := (SELECT coalesce(sum(duesatisfydetail.duesatisfyqty), 0) FROM dbo.duesatisfyheader, dbo.duesatisfydetail WHERE ((((duesatisfyheader.duesatisfycode = duesatisfydetail.duesatisfycode) AND (duesatisfydetail.gcode = v_l_gcode)) AND (duesatisfydetail.icode = v_l_icode)) AND (duesatisfyheader.duesatisfydate < v_l_date)));
  v_l_transferqty_increase := (SELECT coalesce(sum(tdetail.qty), 0) FROM dbo.theader, dbo.tdetail WHERE (((((theader.transcode = tdetail.transcode) AND (theader.dgcode = v_l_gcode)) AND (tdetail.icode = v_l_icode)) AND (theader.date < v_l_date)) AND (theader.posted = 'Y')));
  v_l_transferqty_decrease := (SELECT coalesce(sum(tdetail.qty), 0) FROM dbo.theader, dbo.tdetail WHERE (((((theader.transcode = tdetail.transcode) AND (theader.sgcode = v_l_gcode)) AND (tdetail.icode = v_l_icode)) AND (theader.date < v_l_date)) AND (theader.posted = 'Y')));
  v_l_issueqty := (SELECT coalesce(sum(issuedetail.qty), 0) FROM dbo.issueheader, dbo.issuedetail WHERE ((((issueheader.date < v_l_date) AND (issueheader.issueinvcode = issuedetail.issueinvcode)) AND (issuedetail.gcode = v_l_gcode)) AND (issuedetail.icode = v_l_icode)));
  v_l_receiptqty := (SELECT coalesce(sum(receiptdetail.qty), 0) FROM dbo.receiptheader, dbo.receiptdetail WHERE (((((receiptheader.date < v_l_date) AND (receiptheader.receiptinvcode = receiptdetail.receiptinvcode)) AND (receiptdetail.gcode = v_l_gcode)) AND (receiptdetail.icode = v_l_icode)) AND (receiptheader.posted = 'Y')));
  v_l_adjqty := (SELECT coalesce(sum(CASE adjcatcode WHEN 1 THEN adjdetail.looseqty ELSE (-adjdetail.looseqty) END), 0) FROM dbo.adjheader, dbo.adjdetail WHERE (((((adjheader.date < v_l_date) AND (adjheader.adjcode = adjdetail.adjcode)) AND (adjdetail.gcode = v_l_gcode)) AND (adjdetail.icode = v_l_icode)) AND (adjheader.posted = 'Y')));
  v_l_godownqty := (((((((((v_l_purqty + v_l_saleretqty) - v_l_issueqty) - v_l_purretqty) - v_l_saleqty) - v_l_satisfyqty) + v_l_receiptqty) + v_l_adjqty) + v_l_transferqty_increase) - v_l_transferqty_decrease);
  return_value := 0;
  l_godownqty := v_l_godownqty;
  RETURN;
END
$body$;

-- ==== proc SP_GodownWiseStockInHand ====
CREATE OR REPLACE FUNCTION dbo.sp_godownwisestockinhand(reportgrouping citext, grouplist citext, zerorows smallint, pricetype smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_reportgrouping citext;
  v_grouplist citext;
  v_zerorows smallint;
  v_pricetype smallint;
BEGIN
  v_reportgrouping := reportgrouping;
  v_grouplist := grouplist;
  v_zerorows := zerorows;
  v_pricetype := pricetype;
  DELETE FROM dbo.reportdata;
  DROP TABLE IF EXISTS tv_sp_godownwisestockinhand_tab_grouplist;
  CREATE TEMP TABLE tv_sp_godownwisestockinhand_tab_grouplist (
    code integer NOT NULL
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tv_sp_godownwisestockinhand_tab_itemlist;
  CREATE TEMP TABLE tv_sp_godownwisestockinhand_tab_itemlist (
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tv_sp_godownwisestockinhand_tab_grouplist SELECT code FROM dbo.udf_stringtotabl(v_grouplist, ',') AS udf_stringtotabl;
  INSERT INTO tv_sp_godownwisestockinhand_tab_itemlist SELECT code FROM dbo.udf_selectitems(v_reportgrouping, v_grouplist) AS udf_selectitems;
  INSERT INTO dbo.reportdata (code1, name1, code2, name2, code3, name3, name4, name5, value1, value2, value3, value4, value5, name6, name7, name8) SELECT g.gcode AS code1, g.name AS name1, CASE v_reportgrouping WHEN 'M' THEN i.manfcode WHEN 'C' THEN i.icatcode WHEN 'L' THEN i.iccode ELSE i.packcode END AS code2, CASE v_reportgrouping WHEN 'M' THEN (SELECT m.name FROM dbo.manufacturer AS m WHERE (m.manfcode = i.manfcode)) WHEN 'C' THEN (SELECT c.name FROM dbo.itemcategory AS c WHERE (c.icatcode = i.icatcode)) WHEN 'L' THEN (SELECT c.name FROM dbo.itemclass AS c WHERE (c.iccode = i.iccode)) ELSE (SELECT p.name FROM dbo.itempacking AS p WHERE (p.packcode = i.packcode)) END AS name2, i.icode AS code3, i.name AS name3, i.customicode AS name4, i.packingdesc AS name5, CASE v_pricetype WHEN 1 THEN round(((i.saleprice / i.packunits))::numeric, 2) WHEN 2 THEN round(((i.purprice / i.packunits))::numeric, 2) WHEN 3 THEN round((i.avgprice)::numeric, 2) END AS value1, i.packunits AS value2, coalesce(sum(gd.currqty), 0) AS value3, coalesce(round((((sum(gd.currqty))::double precision / (i.packunits)::double precision))::numeric, 2), 0) AS value4, (coalesce(sum(gd.currqty), 0) * CASE v_pricetype WHEN 1 THEN round(((i.saleprice / i.packunits))::numeric, 2) WHEN 2 THEN round(((i.purprice / i.packunits))::numeric, 2) WHEN 3 THEN round((i.avgprice)::numeric, 2) END) AS value5, CASE WHEN (v_reportgrouping = 'M') THEN (SELECT c.name FROM dbo.itemcategory AS c WHERE (c.icatcode = i.icatcode)) ELSE (SELECT m.name FROM dbo.manufacturer AS m WHERE (m.manfcode = i.manfcode)) END AS name6, CASE WHEN (v_reportgrouping IN ('C', 'M')) THEN (SELECT c.name FROM dbo.itemclass AS c WHERE (c.iccode = i.iccode)) ELSE (SELECT c.name FROM dbo.itemcategory AS c WHERE (c.icatcode = i.icatcode)) END AS name7, CASE WHEN (v_reportgrouping IN ('C', 'M', 'L')) THEN (SELECT p.name FROM dbo.itempacking AS p WHERE (p.packcode = i.packcode)) ELSE (SELECT c.name FROM dbo.itemclass AS c WHERE (c.iccode = i.iccode)) END AS name8 FROM (SELECT gcode, icode, currqty AS currqty FROM dbo.godowndetail WHERE (icode IN (SELECT code FROM tv_sp_godownwisestockinhand_tab_itemlist AS tab_itemlist)) UNION ALL SELECT g.gcode, (SELECT min(code) AS code FROM tv_sp_godownwisestockinhand_tab_itemlist AS tab_itemlist) AS icode, 0 AS currqty FROM dbo.godown AS g WHERE (g.gcode NOT IN (SELECT DISTINCT gcode FROM dbo.godowndetail)) UNION ALL SELECT (SELECT min(gcode) AS gcode FROM dbo.godown) AS gcode, icode, 0 AS currqty FROM (SELECT code AS icode FROM tv_sp_godownwisestockinhand_tab_itemlist AS tab_itemlist WHERE (code NOT IN (SELECT DISTINCT icode FROM dbo.godowndetail))) AS i WHERE (1 = v_zerorows)) AS gd, dbo.godown AS g, dbo.item AS i WHERE (((i.icode = gd.icode) AND (gd.gcode = g.gcode)) AND (i.active = 1)) GROUP BY g.gcode, g.name, i.icode, i.name, i.customicode, i.icatcode, i.manfcode, i.iccode, i.packcode, i.purprice, i.saleprice, i.avgprice, i.packunits, i.packingdesc;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_GraduateClass ====
CREATE OR REPLACE FUNCTION dbo.sp_graduateclass(graduationcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_graduationcode integer;
  v_graduatedstudents integer;
  v_err integer;
  v_thisid integer;
  v_studentcode integer;
  v_classcode integer;
  v_rollno citext;
  v_rowid integer;
  v_usercode smallint;
  v_reason citext;
BEGIN
  v_graduationcode := graduationcode;
  v_graduatedstudents := coalesce((SELECT count(*) FROM dbo.classgraduationdetail WHERE ((graduationcode = v_graduationcode) AND (graduate = 'Y'))), 0);
  IF (v_graduatedstudents <= 0) THEN
    return_value := 0;
    RETURN;
  END IF;
  DROP TABLE IF EXISTS tv_sp_graduateclass_studentlist;
  CREATE TEMP TABLE tv_sp_graduateclass_studentlist (
    classcode integer,
    studentcode integer,
    rollno citext,
    rowid integer,
    thisid integer GENERATED BY DEFAULT AS IDENTITY
) ON COMMIT DROP;
  INSERT INTO tv_sp_graduateclass_studentlist (classcode, studentcode, rollno, rowid) SELECT c.classcode, d.studentcode, d.rollno, d.rowid FROM dbo.classgraduation AS c, dbo.classgraduationdetail AS d WHERE (((c.graduationcode = v_graduationcode) AND (c.graduationcode = d.graduationcode)) AND (graduate = 'Y')) ORDER BY d.rowid;
  v_graduatedstudents := coalesce((SELECT count(*) FROM tv_sp_graduateclass_studentlist AS studentlist), 0);
  IF (v_graduatedstudents <= 0) THEN
    return_value := 0;
    RETURN;
  END IF;
  v_reason := coalesce((SELECT remarks FROM dbo.classgraduation WHERE (graduationcode = v_graduationcode)), 'School Leaving By Graduation');
  v_usercode := coalesce((SELECT usercode FROM dbo.classgraduation WHERE (graduationcode = v_graduationcode)), 1);
  v_thisid := 1;
  WHILE (v_thisid <= v_graduatedstudents) LOOP
    v_classcode := (SELECT classcode FROM tv_sp_graduateclass_studentlist AS studentlist WHERE (thisid = v_thisid));
    v_studentcode := (SELECT studentcode FROM tv_sp_graduateclass_studentlist AS studentlist WHERE (thisid = v_thisid));
    v_rollno := (SELECT rollno FROM tv_sp_graduateclass_studentlist AS studentlist WHERE (thisid = v_thisid));
    v_rowid := (SELECT rowid FROM tv_sp_graduateclass_studentlist AS studentlist WHERE (thisid = v_thisid));
    INSERT INTO dbo.schoolleaving (date, studentcode, classcode, rollno, admissiondate, lastserviceinvcode, lastserviceinvdate, reason, usercode, graduationrowid) SELECT localtimestamp(3) AS date, studentcode, classcode, rollno, admissiondate, serviceinvcode, lastserviceinvdate, v_reason, v_usercode, v_rowid FROM dbo.studentclass WHERE ((classcode = v_classcode) AND (studentcode = v_studentcode));
    IF ((v_err <> 0) OR (0 <> 0)) THEN
      RAISE EXCEPTION 'Can Not Insert Student Record in School Leaving for the specified class';
      return_value := -1;
      RETURN;
    END IF;
    UPDATE dbo.studentclass SET graduationrowid = v_rowid WHERE ((classcode = v_classcode) AND (studentcode = v_studentcode));
    IF ((v_err <> 0) OR (0 <> 0)) THEN
      RAISE EXCEPTION 'Can Not Update Student Entrollment in the specified class';
      return_value := -1;
      RETURN;
    END IF;
    UPDATE dbo.student SET status = 'L' WHERE (studentcode = v_studentcode);
    v_thisid := (v_thisid + 1);
  END LOOP;
  UPDATE dbo.class SET promoted = 'Y', graduated = 'Y' WHERE (classcode = v_classcode);
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_GroupWise_RePrioritizeStockBatches ====
CREATE OR REPLACE FUNCTION dbo.sp_groupwise_reprioritizestockbatches(method integer, "grouping" citext, grouplist citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_method integer;
  v_grouping citext;
  v_grouplist citext;
  v_batch citext;
  v_itemname citext;
  v_icode integer;
  v_oldicode integer;
  v_errcode integer;
  v_priority integer;
  v_expiry timestamp(3);
  v_indate timestamp(3);
  cur_cursor1 refcursor;
  cur_cursor2 refcursor;
  _fs integer := -1;
BEGIN
  v_method := method;
  v_grouping := "grouping";
  v_grouplist := grouplist;
  DROP TABLE IF EXISTS tv_sp_groupwise_reprioritizestockbatches_tab_grouplist;
  CREATE TEMP TABLE tv_sp_groupwise_reprioritizestockbatches_tab_grouplist (
    code integer NOT NULL
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tv_sp_groupwise_reprioritizestockbatches_tab_itemlist;
  CREATE TEMP TABLE tv_sp_groupwise_reprioritizestockbatches_tab_itemlist (
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tv_sp_groupwise_reprioritizestockbatches_tab_grouplist SELECT code FROM dbo.udf_stringtotabl(v_grouplist, ',') AS udf_stringtotabl;
  INSERT INTO tv_sp_groupwise_reprioritizestockbatches_tab_itemlist SELECT code FROM dbo.udf_selectitems(v_grouping, v_grouplist) AS udf_selectitems;
  IF (v_method = 1) THEN
    UPDATE dbo.godowndetail SET priority = 10 WHERE (godowndetail.icode IN (SELECT code FROM tv_sp_groupwise_reprioritizestockbatches_tab_itemlist AS tab_itemlist));
  END IF;
  IF (v_method = 2) THEN
    UPDATE dbo.godowndetail SET priority = 9 WHERE (godowndetail.icode IN (SELECT code FROM tv_sp_groupwise_reprioritizestockbatches_tab_itemlist AS tab_itemlist));
    v_oldicode := NULL;
    v_priority := 0;
    OPEN cur_cursor1 FOR SELECT t.icode, t.batch, t.expiry, min(t.indate) AS indate FROM (SELECT gd.icode, gd.batch, gd.expiry, min(h.postdate) AS indate FROM dbo.purdetail AS d, dbo.purledger AS h, dbo.godowndetail AS gd WHERE ((((((h.posted = 'Y') AND (h.purinvcode = d.purinvcode)) AND (d.icode = gd.icode)) AND (d.batch = gd.batch)) AND (d.expiry = gd.expiry)) AND (gd.icode IN (SELECT code FROM tv_sp_groupwise_reprioritizestockbatches_tab_itemlist AS tab_itemlist))) GROUP BY gd.icode, gd.batch, gd.expiry UNION ALL SELECT gd.icode, gd.batch, gd.expiry, min(h.postdate) AS indate FROM dbo.srdetail AS d, dbo.srledger AS h, dbo.godowndetail AS gd WHERE ((((((h.posted = 'Y') AND (h.srinvcode = d.srinvcode)) AND (d.icode = gd.icode)) AND (d.batch = gd.batch)) AND (d.expiry = gd.expiry)) AND (gd.icode IN (SELECT code FROM tv_sp_groupwise_reprioritizestockbatches_tab_itemlist AS tab_itemlist))) GROUP BY gd.icode, gd.batch, gd.expiry UNION ALL SELECT gd.icode, gd.batch, gd.expiry, min(h.postdate) AS indate FROM dbo.receiptdetail AS d, dbo.receiptheader AS h, dbo.godowndetail AS gd WHERE ((((((h.posted = 'Y') AND (h.receiptinvcode = d.receiptinvcode)) AND (d.icode = gd.icode)) AND (d.batch = gd.batch)) AND (d.expiry = gd.expiry)) AND (gd.icode IN (SELECT code FROM tv_sp_groupwise_reprioritizestockbatches_tab_itemlist AS tab_itemlist))) GROUP BY gd.icode, gd.batch, gd.expiry UNION ALL SELECT gd.icode, gd.batch, gd.expiry, min(h.date) AS indate FROM dbo.adjdetail AS d, dbo.adjheader AS h, dbo.godowndetail AS gd WHERE (((((((h.posted = 'Y') AND (adjcatcode = 1)) AND (h.adjcode = d.adjcode)) AND (d.icode = gd.icode)) AND (d.batch = gd.batch)) AND (d.expiry = gd.expiry)) AND (gd.icode IN (SELECT code FROM tv_sp_groupwise_reprioritizestockbatches_tab_itemlist AS tab_itemlist))) GROUP BY gd.icode, gd.batch, gd.expiry) AS t GROUP BY t.icode, t.batch, t.expiry ORDER BY icode, indate, expiry, batch;
    FETCH NEXT FROM cur_cursor1 INTO v_icode, v_batch, v_expiry, v_indate;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    WHILE (_fs = 0) LOOP
      IF (v_icode = v_oldicode) THEN
        v_priority := (v_priority + 1);
      ELSE
        v_priority := 1;
      END IF;
      IF (v_priority > 8) THEN
        v_priority := 8;
      END IF;
      UPDATE dbo.godowndetail SET priority = v_priority WHERE (((icode = v_icode) AND (batch = v_batch)) AND (expiry = v_expiry));
      v_oldicode := v_icode;
      FETCH NEXT FROM cur_cursor1 INTO v_icode, v_batch, v_expiry, v_indate;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    END LOOP;
    CLOSE cur_cursor1;
    -- DEALLOCATE cursor1
  END IF;
  IF (v_method = 3) THEN
    UPDATE dbo.godowndetail SET priority = 30 WHERE (godowndetail.icode IN (SELECT code FROM tv_sp_groupwise_reprioritizestockbatches_tab_itemlist AS tab_itemlist));
    v_oldicode := NULL;
    v_priority := 10;
    OPEN cur_cursor2 FOR SELECT t.icode, t.batch, t.expiry, max(t.indate) AS indate FROM (SELECT gd.icode, gd.batch, gd.expiry, max(h.postdate) AS indate FROM dbo.purdetail AS d, dbo.purledger AS h, dbo.godowndetail AS gd WHERE ((((((h.posted = 'Y') AND (h.purinvcode = d.purinvcode)) AND (d.icode = gd.icode)) AND (d.batch = gd.batch)) AND (d.expiry = gd.expiry)) AND (gd.icode IN (SELECT code FROM tv_sp_groupwise_reprioritizestockbatches_tab_itemlist AS tab_itemlist))) GROUP BY gd.icode, gd.batch, gd.expiry UNION ALL SELECT gd.icode, gd.batch, gd.expiry, max(h.postdate) AS indate FROM dbo.srdetail AS d, dbo.srledger AS h, dbo.godowndetail AS gd WHERE ((((((h.posted = 'Y') AND (h.srinvcode = d.srinvcode)) AND (d.icode = gd.icode)) AND (d.batch = gd.batch)) AND (d.expiry = gd.expiry)) AND (gd.icode IN (SELECT code FROM tv_sp_groupwise_reprioritizestockbatches_tab_itemlist AS tab_itemlist))) GROUP BY gd.icode, gd.batch, gd.expiry UNION ALL SELECT gd.icode, gd.batch, gd.expiry, max(h.postdate) AS indate FROM dbo.receiptdetail AS d, dbo.receiptheader AS h, dbo.godowndetail AS gd WHERE ((((((h.posted = 'Y') AND (h.receiptinvcode = d.receiptinvcode)) AND (d.icode = gd.icode)) AND (d.batch = gd.batch)) AND (d.expiry = gd.expiry)) AND (gd.icode IN (SELECT code FROM tv_sp_groupwise_reprioritizestockbatches_tab_itemlist AS tab_itemlist))) GROUP BY gd.icode, gd.batch, gd.expiry UNION ALL SELECT gd.icode, gd.batch, gd.expiry, max(h.date) AS indate FROM dbo.adjdetail AS d, dbo.adjheader AS h, dbo.godowndetail AS gd WHERE (((((((h.posted = 'Y') AND (adjcatcode = 1)) AND (h.adjcode = d.adjcode)) AND (d.icode = gd.icode)) AND (d.batch = gd.batch)) AND (d.expiry = gd.expiry)) AND (gd.icode IN (SELECT code FROM tv_sp_groupwise_reprioritizestockbatches_tab_itemlist AS tab_itemlist))) GROUP BY gd.icode, gd.batch, gd.expiry) AS t GROUP BY t.icode, t.batch, t.expiry ORDER BY icode, indate DESC, expiry, batch;
    FETCH NEXT FROM cur_cursor2 INTO v_icode, v_batch, v_expiry, v_indate;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    WHILE (_fs = 0) LOOP
      IF (v_icode = v_oldicode) THEN
        v_priority := (v_priority + 1);
      ELSE
        v_priority := 11;
      END IF;
      IF (v_priority > 29) THEN
        v_priority := 29;
      END IF;
      UPDATE dbo.godowndetail SET priority = v_priority WHERE (((icode = v_icode) AND (batch = v_batch)) AND (expiry = v_expiry));
      v_oldicode := v_icode;
      FETCH NEXT FROM cur_cursor2 INTO v_icode, v_batch, v_expiry, v_indate;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    END LOOP;
    CLOSE cur_cursor2;
    -- DEALLOCATE cursor2
  END IF;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_GuestCheckInBalance ====
CREATE OR REPLACE FUNCTION dbo.sp_guestcheckinbalance(guestcheckincode integer, INOUT balance numeric, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_guestcheckincode integer;
  v_balance numeric(15,2);
BEGIN
  v_guestcheckincode := guestcheckincode;
  v_balance := balance;
  PERFORM dbo.sp_virtualgl(ac_type => 'A');
  v_balance := coalesce((SELECT sum((v.debit - v.credit)) AS balance FROM dbo.virtualgl AS v, dbo.accounts AS a WHERE (((v.guestcode IN (SELECT p.guestcode FROM dbo.guestcheckin AS p WHERE (p.guestcheckincode = v_guestcheckincode))) AND (v.acccode = a.acccode)) AND (v.acccode IN (SELECT acccode FROM dbo.accounts WHERE (subcode = 3))))), 0);
  return_value := 0;
  balance := v_balance;
  RETURN;
END
$body$;

-- ==== proc sp_GuestOpeningBalance ====
CREATE OR REPLACE FUNCTION dbo.sp_guestopeningbalance(al_guestcode integer, ad_edate timestamp, INOUT af_openbalance numeric, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_al_guestcode integer;
  v_ad_edate timestamp(3);
  v_af_openbalance numeric(15,5);
BEGIN
  v_al_guestcode := al_guestcode;
  v_ad_edate := ad_edate;
  v_af_openbalance := af_openbalance;
  v_af_openbalance := coalesce((SELECT (sum(v.debit) - sum(v.credit)) FROM dbo.virtualgl AS v WHERE (((v.guestcode = v_al_guestcode) AND (v.acccode IN (SELECT custcode FROM dbo.guest WHERE (guestcode = v_al_guestcode)))) AND (v.date < v_ad_edate))), 0);
  return_value := 0;
  af_openbalance := v_af_openbalance;
  RETURN;
END
$body$;

-- ==== proc sp_HoldOn ====
CREATE OR REPLACE FUNCTION dbo.sp_holdon(value smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_value smallint;
  v_m smallint;
  v_s smallint;
  v_result smallint;
  v_time citext;
BEGIN
  v_value := value;
  v_m := 0;
  v_s := 0;
  v_value := trunc((SELECT fcatlength FROM dbo.syscatelog WHERE (fcatid = 7)))::smallint;
  IF (v_value >= 60) THEN
    v_result := ((v_value % 60));
    IF (v_result = 0) THEN
      v_m := (v_value / 60);
    ELSE
      v_m := (v_value / 60);
      v_s := v_result;
    END IF;
  ELSE
    v_s := v_value;
  END IF;
  v_time := ((('00:' || (v_m)::text) || ':') || (v_s)::text);
  -- WaitFor Delay @time
  RAISE EXCEPTION 'untranslated T-SQL (WAITFOR)' USING ERRCODE = '0A000';
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_Import_Purchases_From_DataCarryDB ====
CREATE OR REPLACE FUNCTION dbo.sp_import_purchases_from_datacarrydb(srv citext, db citext, owner citext, sinvcode integer, linvcode integer, suppcode smallint, usercode smallint, OUT return_value integer, OUT rs1 refcursor, OUT rs2 refcursor, OUT rs3 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_sinvcode integer;
  v_linvcode integer;
  v_suppcode smallint;
  v_usercode smallint;
  v_query citext;
  v_temp citext;
  v_errcode integer;
  v_purinvcode integer;
  v_end_invcode integer;
  v_rowcount integer;
  _dq1 text;
  _dq2 text;
  _dq3 text;
  _rc integer;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  v_sinvcode := sinvcode;
  v_linvcode := linvcode;
  v_suppcode := suppcode;
  v_usercode := usercode;
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  DROP TABLE IF EXISTS tmp_header;
  CREATE TEMP TABLE tmp_header ON COMMIT DROP AS SELECT purinvcode AS oldinvcode, -1 AS purinvcode, purcatcode, suppcode, suppinvcode, salesmancode, date, pocode, discperc, flatdisc, misccharges, salestax, posted, postdate, remarks, originaldate, modifiedby, postedby, suppinvdate, grn, porb, invgstperc1, purtypecode, headerno, headerinvno, invtotal, accountfor, paymentmode, paymentacccode, amt, amtby, amtdate, amtreference, outstandingamt, marked, transferable, transfered, transferedon, transferedby, imported, importedby, printbalance, purinvpagesize, currencycode, conversionfactor, printcounter, associatedsaleordercode, associatedsaleinvcode, gccode, vehicle, shipto, newpurchaseorderno, lcno, updateavgpricewithnetrate, impactinventory, imppurinvcode, creditdays, suppinvamount, crs_transfered, crs_transferedon, icatcode, monthlycounter, dailycounter, custcode, qe1_acccode, qe2_acccode, qe3_acccode, qe4_acccode, qe5_acccode, we1_acccode, we2_acccode, we3_acccode, we4_acccode, we5_acccode FROM dbo.purledger WHERE (purinvcode < 0);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  DROP TABLE IF EXISTS tmp_detail;
  CREATE TEMP TABLE tmp_detail ON COMMIT DROP AS SELECT purinvcode AS oldinvcode, -1 AS purinvcode, icode, gcode, batch, expiry, packqty, looseqty, packunits, purprice, discperc, avgprice, bonusqty, purrowid, newavgprice, currstock, gstperc, unitsalestax, purutn, saleprice, itemdescription, rate, salepriceforitem, foreignprice, purpriceinadvpur, netrate, recentpurprice, totalpieces, piecesinhand, receiptrowid, manfcodeforitem, discountedsaleprice, flatdiscforitem, retailprice, alternatecustomicode, manfdate, unitweight, qe1, qe2, qe3, qe4, qe5, we1, we2, we3, we4, we5, batchsaleprice FROM dbo.purdetail WHERE (purinvcode < 0);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_query := 'ALTER TABLE tmp_header ADD COLUMN RowID integer NOT NULL GENERATED BY DEFAULT AS IDENTITY';
  _rc := 1;
  _dq1 := v_query;
  IF _dq1 IS NOT NULL THEN
    IF _dq1 ~* '^[[:space:]]*select' THEN OPEN rs1 FOR EXECUTE dbo.tsql_dyn(_dq1); ELSE EXECUTE dbo.tsql_dyn(_dq1); END IF;
  END IF;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF (0 <> 0) THEN
    RAISE EXCEPTION 'Problem in adding identity column in temporary table';
    return_value := -1;
    RETURN;
  END IF;
  v_query := 'Insert Into tmp_header (OldInvCode,PurInvCode,PurCatCode,SuppCode,SuppInvCode,SalesmanCode,Date,POCode,DiscPerc,FlatDisc,MiscCharges,SalesTax,Posted,postdate,Remarks,OriginalDate,ModifiedBy,PostedBy,SuppInvDate,GRN,PORB,InvGSTPerc1,purtypecode,HeaderNo,HeaderInvNo,InvTotal,AccountFor,PaymentMode,PaymentAccCode,Amt,AmtBY,AmtDate,AmtReference,OutstandingAmt,Marked,Transferable,Transfered,TransferedOn,TransferedBy,Imported,ImportedBy,PrintBalance,PurInvPageSize,CurrencyCode,ConversionFactor,PrintCounter,AssociatedSaleOrderCode,AssociatedSaleInvCode,GCCode,Vehicle,ShipTo,NewPurchaseOrderNo,LCNO,UpdateAvgPriceWithNetRate,ImpactInventory,ImpPurInvCode,CreditDays,SuppInvAmount,CRS_Transfered,CRS_TransferedOn,ICatCode,MonthlyCounter,DailyCounter,CustCode,QE1_AccCode,QE2_AccCode,QE3_AccCode,QE4_AccCode,QE5_AccCode,WE1_AccCode,WE2_AccCode,WE3_AccCode,WE4_AccCode,WE5_AccCode) ';
  _rc := 1;
  v_query := (v_query || ' Select OldInvCode=PurInvCode,PurInvCode=-1,PurCatCode,SuppCode,SuppInvCode,SalesmanCode,Date,POCode,DiscPerc,FlatDisc,MiscCharges,SalesTax,Posted,postdate,Remarks,OriginalDate,ModifiedBy,PostedBy,SuppInvDate,GRN,PORB,InvGSTPerc1,purtypecode,HeaderNo,HeaderInvNo,InvTotal,AccountFor,PaymentMode,PaymentAccCode,Amt,AmtBY,AmtDate,AmtReference,OutstandingAmt,Marked,Transferable,Transfered,TransferedOn,TransferedBy,Imported,ImportedBy,PrintBalance,PurInvPageSize,CurrencyCode,ConversionFactor,PrintCounter,AssociatedSaleOrderCode,AssociatedSaleInvCode,GCCode,Vehicle,ShipTo,NewPurchaseOrderNo,LCNO,UpdateAvgPriceWithNetRate,ImpactInventory,ImpPurInvCode,CreditDays,SuppInvAmount,CRS_Transfered,CRS_TransferedOn,ICatCode,MonthlyCounter,DailyCounter,CustCode,QE1_AccCode,QE2_AccCode,QE3_AccCode,QE4_AccCode,QE5_AccCode,WE1_AccCode,WE2_AccCode,WE3_AccCode,WE4_AccCode,WE5_AccCode ');
  _rc := 1;
  v_query := ((((((((v_query || ' From ') || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.') || 'PurLedger ');
  _rc := 1;
  v_query := ((((v_query || ' Where PurInvCode Between ') || (v_sinvcode)::text) || ' And ') || (v_linvcode)::text);
  _rc := 1;
  IF (v_suppcode > 0) THEN
    v_query := ((v_query || ' AND SuppCode = ') || (v_suppcode)::text);
    _rc := 1;
  END IF;
  v_query := (v_query || ' ORDER BY OldInvCode ');
  _rc := 1;
  _dq2 := v_query;
  IF _dq2 IS NOT NULL THEN
    IF _dq2 ~* '^[[:space:]]*select' THEN OPEN rs2 FOR EXECUTE dbo.tsql_dyn(_dq2); ELSE EXECUTE dbo.tsql_dyn(_dq2); END IF;
  END IF;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((0 = 0) AND (_rc > 0)) THEN
    v_query := 'Insert Into tmp_detail (OldInvCode,PurInvCode,ICode,Gcode,Batch,Expiry,PackQty,LooseQty,PackUnits,PurPrice,DiscPerc,AvgPrice,BonusQty,NewAvgPrice,CurrStock,GSTPerc,UnitSalesTax,PurUtn,SalePrice,itemdescription,rate,SalePriceForItem,ForeignPrice,PurPriceInAdvPur,NetRate,RecentPurPrice,TotalPieces,PiecesInHand,ReceiptRowID,ManfCodeForItem,DiscountedSalePrice,FlatDiscForItem,RetailPrice,AlternateCustomICode,ManfDate,UnitWeight,QE1,QE2,QE3,QE4,QE5,WE1,WE2,WE3,WE4,WE5,BatchSalePrice) ';
    _rc := 1;
    v_query := (v_query || 'Select OldInvCode=PurInvCode,PurInvCode=-1,ICode,Gcode,Batch,Expiry,PackQty,LooseQty,PackUnits,PurPrice,DiscPerc,AvgPrice,BonusQty,NewAvgPrice,CurrStock,GSTPerc,UnitSalesTax,PurUtn,SalePrice,itemdescription,rate,SalePriceForItem,ForeignPrice,PurPriceInAdvPur,NetRate,RecentPurPrice,TotalPieces,PiecesInHand,ReceiptRowID,ManfCodeForItem,DiscountedSalePrice,FlatDiscForItem,RetailPrice,AlternateCustomICode,ManfDate,UnitWeight,QE1,QE2,QE3,QE4,QE5,WE1,WE2,WE3,WE4,WE5,BatchSalePrice ');
    _rc := 1;
    v_query := ((((((((v_query || 'From ') || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.') || 'PurDetail ');
    _rc := 1;
    v_query := ((((v_query || 'Where PurInvCode Between ') || (v_sinvcode)::text) || ' And ') || (v_linvcode)::text);
    _rc := 1;
    IF (v_suppcode > 0) THEN
      v_query := (((v_query || ' AND PurInvCode IN (SELECT PurInvCode FROM PurLedger WHERE SuppCode = ') || (v_suppcode)::text) || ') ');
      _rc := 1;
    END IF;
    v_query := (v_query || ' ORDER BY OldInvCode, PurRowId ');
    _rc := 1;
    _dq3 := v_query;
    IF _dq3 IS NOT NULL THEN
      IF _dq3 ~* '^[[:space:]]*select' THEN OPEN rs3 FOR EXECUTE dbo.tsql_dyn(_dq3); ELSE EXECUTE dbo.tsql_dyn(_dq3); END IF;
    END IF;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem in inserting detail records From Remote DataBase';
      return_value := -1;
      RETURN;
    END IF;
  ELSE
    IF ((_rc = 0) AND (0 = 0)) THEN
      return_value := 1;
      RETURN;
    ELSE
      RAISE EXCEPTION 'Problem in inserting header records From Remote DataBase';
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  v_rowcount := (SELECT count(*) FROM tmp_header AS header);
  _rc := 1;
  IF ((v_linvcode >= v_sinvcode) AND (v_rowcount > 0)) THEN
    v_errcode := 0;
    _rc := 1;
    SELECT r.return_value, r.key INTO v_errcode, v_purinvcode FROM dbo.sp_locktabmaxkey(tabname => 'PurLedger', key => v_purinvcode) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Problem while Fetching PurLedger Key Value';
      return_value := -1;
      RETURN;
    END IF;
    UPDATE tmp_header AS header SET purinvcode = (v_purinvcode + rowid);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    UPDATE tmp_detail AS d SET purinvcode = h.purinvcode FROM tmp_header AS h WHERE (h.oldinvcode = d.oldinvcode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    INSERT INTO dbo.purledger (purinvcode, purcatcode, suppcode, suppinvcode, salesmancode, date, pocode, discperc, flatdisc, misccharges, salestax, posted, postdate, remarks, originaldate, modifiedby, postedby, suppinvdate, grn, porb, invgstperc1, purtypecode, headerno, headerinvno, invtotal, accountfor, paymentmode, paymentacccode, amt, amtby, amtdate, amtreference, outstandingamt, marked, transferable, transfered, transferedon, transferedby, imported, importedby, printbalance, purinvpagesize, currencycode, conversionfactor, printcounter, associatedsaleordercode, associatedsaleinvcode, gccode, vehicle, shipto, newpurchaseorderno, lcno, updateavgpricewithnetrate, impactinventory, imppurinvcode, creditdays, suppinvamount, crs_transfered, crs_transferedon, icatcode, monthlycounter, dailycounter, custcode, qe1_acccode, qe2_acccode, qe3_acccode, qe4_acccode, qe5_acccode, we1_acccode, we2_acccode, we3_acccode, we4_acccode, we5_acccode) SELECT purinvcode, purcatcode, suppcode, suppinvcode, salesmancode, date, pocode, discperc, flatdisc, misccharges, salestax, 'N' AS posted, postdate, remarks, originaldate, NULL::smallint AS modifiedby, NULL::smallint AS postedby, suppinvdate, grn, porb, invgstperc1, purtypecode, headerno, headerinvno, invtotal, accountfor, paymentmode, paymentacccode, amt, amtby, amtdate, amtreference, outstandingamt, marked, transferable, transfered, transferedon, transferedby, imported, importedby, printbalance, purinvpagesize, currencycode, conversionfactor, printcounter, associatedsaleordercode, associatedsaleinvcode, gccode, vehicle, shipto, newpurchaseorderno, lcno, updateavgpricewithnetrate, impactinventory, imppurinvcode, creditdays, suppinvamount, crs_transfered, crs_transferedon, icatcode, monthlycounter, dailycounter, custcode, qe1_acccode, qe2_acccode, qe3_acccode, qe4_acccode, qe5_acccode, we1_acccode, we2_acccode, we3_acccode, we4_acccode, we5_acccode FROM tmp_header AS header ORDER BY oldinvcode;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem while Inserting Record in PurLedger';
      RAISE EXCEPTION 'T-SQL ROLLBACK in sp_Import_Purchases_From_DataCarryDB' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
    INSERT INTO dbo.purdetail (purinvcode, icode, gcode, batch, expiry, packqty, looseqty, packunits, purprice, discperc, avgprice, bonusqty, newavgprice, currstock, gstperc, unitsalestax, purutn, saleprice, itemdescription, rate, salepriceforitem, foreignprice, purpriceinadvpur, netrate, recentpurprice, totalpieces, piecesinhand, receiptrowid, manfcodeforitem, discountedsaleprice, flatdiscforitem, retailprice, alternatecustomicode, manfdate, unitweight, qe1, qe2, qe3, qe4, qe5, we1, we2, we3, we4, we5, batchsaleprice) SELECT purinvcode, icode, gcode, batch, expiry, packqty, looseqty, packunits, purprice, discperc, avgprice, bonusqty, newavgprice, currstock, gstperc, unitsalestax, purutn, saleprice, itemdescription, rate, salepriceforitem, foreignprice, purpriceinadvpur, netrate, recentpurprice, totalpieces, piecesinhand, receiptrowid, manfcodeforitem, discountedsaleprice, flatdiscforitem, retailprice, alternatecustomicode, manfdate, unitweight, qe1, qe2, qe3, qe4, qe5, we1, we2, we3, we4, we5, batchsaleprice FROM tmp_detail AS detail;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem while Inserting Record in Purchase Detail';
      RAISE EXCEPTION 'T-SQL ROLLBACK in sp_Import_Purchases_From_DataCarryDB' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
    v_end_invcode := coalesce((SELECT max(purinvcode) FROM tmp_header AS header), 1);
    _rc := 1;
    v_errcode := 0;
    _rc := 1;
    SELECT r.return_value INTO v_errcode FROM dbo.sp_updatetabmaxkey(tabname => 'PurLedger', key => v_end_invcode) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Problem while Updating PurLedger Key Value';
      RAISE EXCEPTION 'T-SQL ROLLBACK in sp_Import_Purchases_From_DataCarryDB' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
    UPDATE dbo.purledger SET invtotal = coalesce(dbo.fn_getpurinvtotal((purinvcode)::integer), 0) WHERE (purinvcode IN (SELECT purinvcode FROM tmp_header AS header));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    UPDATE dbo.purledger SET outstandingamt = invtotal WHERE (purinvcode IN (SELECT purinvcode FROM tmp_header AS header));
    GET DIAGNOSTICS _rc = ROW_COUNT;
  END IF;
  IF (0 = 0) THEN
    return_value := 0;
    RETURN;
  ELSE
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_Import_Quot_SO_PO_FromParentServer ====
CREATE OR REPLACE FUNCTION dbo.sp_import_quot_so_po_fromparentserver(srv citext, db citext, owner citext, quot citext, so citext, po citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_quot citext;
  v_so citext;
  v_po citext;
  v_sql citext;
  v_query citext;
  v_from citext;
  v_err integer;
  v_rt_code integer;
  _dq1 text;
  _dq2 text;
  _dq3 text;
  _dq4 text;
  _dq5 text;
  _dq6 text;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  v_quot := quot;
  v_so := so;
  v_po := po;
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  v_from := ((((((' FROM ' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.');
  IF (v_quot = 'Y') THEN
    v_sql := (('SELECT * ' || v_from) || 'QuotationHeader Q WHERE Q.QuotationCode NOT IN (SELECT QuotationCode FROM QuotationHeader)');
    v_query := ('INSERT INTO DBO.QuotationHeader ' || v_sql);
    _dq1 := v_query;
    IF _dq1 IS NOT NULL THEN
      EXECUTE dbo.tsql_dyn(_dq1);
    END IF;
    v_err := 0;
    IF ((0 <> 0) OR (v_err <> 0)) THEN
      RAISE EXCEPTION 'Quotation Header Import Problem: Error Importing Quotations Header From Parent Server.';
      return_value := -1;
      RETURN;
    END IF;
    v_sql := (('SELECT D.QuotationCode, D.ICode, D.Qty, D.PackUnits, D.SalePrice, D.DiscPerc, D.SalesTax, D.ItemFlatDisc, D.BonusQty, D.GSTPerc, D.UnitSalesTax, D.ItemDescription, D.GCode, D.RemoteNetSaleQty, D.RemoteStock, D.PORate, D.SpecialRate, D.RefNo ' || v_from) || 'QuotationDetail D, QuotationHeader Q WHERE Q.QuotationCode = D.QuotationCode AND Q.QuotationCode NOT IN (SELECT DISTINCT QD.QuotationCode FROM QuotationDetail QD) ORDER BY D.QuotationCode, D.ROWID');
    v_query := ('INSERT INTO DBO.QuotationDetail (QuotationCode, ICode, Qty, PackUnits, SalePrice, DiscPerc, SalesTax, ItemFlatDisc, BonusQty, GSTPerc, UnitSalesTax, ItemDescription, GCode, RemoteNetSaleQty, RemoteStock, PORate, SpecialRate, RefNo)' || v_sql);
    _dq2 := v_query;
    IF _dq2 IS NOT NULL THEN
      EXECUTE dbo.tsql_dyn(_dq2);
    END IF;
    v_err := 0;
    IF ((0 <> 0) OR (v_err <> 0)) THEN
      RAISE EXCEPTION 'Quotation Detail Import Problem: Error Importing Quotations Detail From Parent Server.';
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  IF (v_so = 'Y') THEN
    v_sql := (('SELECT * ' || v_from) || 'SaleOrderHeader H WHERE H.SaleOrderCode NOT IN (SELECT SaleOrderCode FROM SaleOrderHeader) ');
    v_query := ('INSERT INTO DBO.SaleOrderHeader ' || v_sql);
    _dq3 := v_query;
    IF _dq3 IS NOT NULL THEN
      EXECUTE dbo.tsql_dyn(_dq3);
    END IF;
    v_err := 0;
    IF ((0 <> 0) OR (v_err <> 0)) THEN
      RAISE EXCEPTION 'Sale Order Header Import Problem: Error Importing Sale Order Header From Parent Server.';
      return_value := -1;
      RETURN;
    END IF;
    v_sql := (('SELECT D.SaleOrderCode, D.ICode, D.GCode, D.LooseQty, D.PackUnits, D.SalePrice, D.AvgPrice, D.Rate, D.DiscPerc, D.ItemFlatDisc, D.SaleItemDescription, D.PackPrice, D.UnitSalesTax, D.GSTPerc, D.BonusQty, D.RowGroup, D.PackQtyForSale, D.BonusPackQtyForSale, D.Remarks, D.SaleOrderItemStatusCode, D.QuotationRowID, D.PrescriptionRowID, D.Batch, D.Expiry ' || v_from) || 'SaleOrderDetail D, SaleOrderHeader H WHERE H.SaleOrderCode = D.SaleOrderCode AND H.SaleOrderCode NOT IN (SELECT DISTINCT DD.SaleOrderCode FROM SaleOrderDetail DD) ORDER BY D.SaleOrderCode, D.ROWID');
    v_query := ('INSERT INTO DBO.SaleOrderDetail (SaleOrderCode, ICode, GCode, LooseQty, PackUnits, SalePrice, AvgPrice, Rate, DiscPerc, ItemFlatDisc, SaleItemDescription, PackPrice, UnitSalesTax, GSTPerc, BonusQty, RowGroup, PackQtyForSale, BonusPackQtyForSale, Remarks, SaleOrderItemStatusCode, QuotationRowID, PrescriptionRowID, Batch, Expiry)' || v_sql);
    _dq4 := v_query;
    IF _dq4 IS NOT NULL THEN
      EXECUTE dbo.tsql_dyn(_dq4);
    END IF;
    v_err := 0;
    IF ((0 <> 0) OR (v_err <> 0)) THEN
      RAISE EXCEPTION 'Sale Order Detail Import Problem: Error Importing Sale Order Detail From Parent Server.';
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  IF (v_po = 'Y') THEN
    v_sql := (('SELECT * ' || v_from) || 'PurOrderHeader H WHERE H.POCode NOT IN (SELECT POCode FROM PurOrderHeader)');
    v_query := ('INSERT INTO DBO.PurOrderHeader ' || v_sql);
    _dq5 := v_query;
    IF _dq5 IS NOT NULL THEN
      EXECUTE dbo.tsql_dyn(_dq5);
    END IF;
    v_err := 0;
    IF ((0 <> 0) OR (v_err <> 0)) THEN
      RAISE EXCEPTION 'Purchase Order Header Import Problem: Error Importing Purchase Order Header From Parent Server.';
      return_value := -1;
      RETURN;
    END IF;
    v_sql := (('SELECT D.POCode, D.ICode, D.Batch, D.Expiry, D.Qty, D.Rate, D.DiscPerc, D.BonusQty, D.Stock, D.ReorderQty, D.OptimumQty, D.MinQty, D.PackUnits, D.SoldQty, D.ReturnQty, D.QtySatisfied, D.BonusQtySatisfied, D.SaleOrderRequest, D.TransitStock, D.Remarks, D.ItemFlatDisc, D.PackSalesTax, D.GSTPerc, D.PurPrice, D.SalePrice, D.RPP, D.PackAvgPrice, D.ForeignPrice, D.LastPurInvCode, D.LastPurDate ' || v_from) || 'PurOrderDetail D, PurOrderHeader H WHERE H.POCode = D.POCode AND H.POCode NOT IN (SELECT DISTINCT DD.POCode FROM PurOrderDetail DD) ORDER BY D.POCode, D.PORowID');
    v_query := ('INSERT INTO DBO.PurOrderDetail (POCode, ICode, Batch, Expiry, Qty, Rate, DiscPerc, BonusQty, Stock, ReorderQty, OptimumQty, MinQty, PackUnits, SoldQty, ReturnQty, QtySatisfied, BonusQtySatisfied, SaleOrderRequest, TransitStock, Remarks, ItemFlatDisc, PackSalesTax, GSTPerc, PurPrice, SalePrice, RPP, PackAvgPrice, ForeignPrice, LastPurInvCode, LastPurDate)' || v_sql);
    _dq6 := v_query;
    IF _dq6 IS NOT NULL THEN
      EXECUTE dbo.tsql_dyn(_dq6);
    END IF;
    v_err := 0;
    IF ((0 <> 0) OR (v_err <> 0)) THEN
      RAISE EXCEPTION 'Purchase Order Detail Import Problem: Error Importing Purchase Order Detail From Parent Server.';
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_Import_Quotation_From_DataCarryDB ====
CREATE OR REPLACE FUNCTION dbo.sp_import_quotation_from_datacarrydb(srv citext, db citext, owner citext, sinvcode integer, linvcode integer, custcode smallint, usercode smallint, OUT return_value integer, OUT rs1 refcursor, OUT rs2 refcursor, OUT rs3 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_sinvcode integer;
  v_linvcode integer;
  v_custcode smallint;
  v_usercode smallint;
  v_query citext;
  v_temp citext;
  v_errcode integer;
  v_quotationcode integer;
  v_end_invcode integer;
  v_rowcount integer;
  _dq1 text;
  _dq2 text;
  _dq3 text;
  _rc integer;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  v_sinvcode := sinvcode;
  v_linvcode := linvcode;
  v_custcode := custcode;
  v_usercode := usercode;
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  DROP TABLE IF EXISTS tmp_header;
  CREATE TEMP TABLE tmp_header ON COMMIT DROP AS SELECT quotationcode AS oldinvcode, -1 AS quotationcode, custcode, salesmancode, date, discperc, flatdisc, misccharges, salestax, sprice, validateupto, postdate, remarks, custrefno, headerno, originaldate, modifiedby, postedby, posted, invgstperc1, remarks2, remarks3, remarks4, remarks5, remarks6, remarks7, remarks8, remarks9, pagesize, messagecode, smancode, loosepack, consolidatedsaleorder FROM dbo.quotationheader WHERE (quotationcode < 0);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  DROP TABLE IF EXISTS tmp_detail;
  CREATE TEMP TABLE tmp_detail ON COMMIT DROP AS SELECT quotationcode AS oldinvcode, -1 AS quotationcode, icode, qty, packunits, saleprice, discperc, salestax, itemflatdisc, bonusqty, gstperc, unitsalestax, itemdescription, gcode, remotenetsaleqty, remotestock, porate, podiscperc, specialrate, refno FROM dbo.quotationdetail WHERE (quotationcode < 0);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_query := 'ALTER TABLE tmp_header ADD COLUMN RowID integer NOT NULL GENERATED BY DEFAULT AS IDENTITY';
  _rc := 1;
  _dq1 := v_query;
  IF _dq1 IS NOT NULL THEN
    IF _dq1 ~* '^[[:space:]]*select' THEN OPEN rs1 FOR EXECUTE dbo.tsql_dyn(_dq1); ELSE EXECUTE dbo.tsql_dyn(_dq1); END IF;
  END IF;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF (0 <> 0) THEN
    RAISE EXCEPTION 'Problem in adding identity column in temporary table';
    return_value := -1;
    RETURN;
  END IF;
  v_query := 'Insert Into tmp_header (OldInvCode,QuotationCode,CustCode,SalesmanCode,date,DiscPerc,FlatDisc,MiscCharges,SalesTax,SPrice,ValidateUpTo,PostDate,Remarks,CustRefNo,headerno,OriginalDate,ModifiedBy,PostedBy,Posted,InvGSTPerc1,Remarks2,Remarks3,Remarks4,Remarks5,Remarks6,Remarks7,Remarks8,Remarks9,Pagesize,MessageCode,SManCode,LoosePack,ConsolidatedSaleOrder) ';
  _rc := 1;
  v_query := (v_query || ' Select OldInvCode=QuotationCode,QuotationCode=-1,CustCode,SalesmanCode,date,DiscPerc,FlatDisc,MiscCharges,SalesTax,SPrice,ValidateUpTo,PostDate,Remarks,CustRefNo,headerno,OriginalDate,ModifiedBy,PostedBy,Posted,InvGSTPerc1,Remarks2,Remarks3,Remarks4,Remarks5,Remarks6,Remarks7,Remarks8,Remarks9,Pagesize,MessageCode,SManCode,LoosePack,ConsolidatedSaleOrder ');
  _rc := 1;
  v_query := ((((((((v_query || ' From ') || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.') || 'QuotationHeader ');
  _rc := 1;
  v_query := ((((v_query || ' Where QuotationCode Between ') || (v_sinvcode)::text) || ' And ') || (v_linvcode)::text);
  _rc := 1;
  IF (v_custcode > 0) THEN
    v_query := ((v_query || ' AND CustCode = ') || (v_custcode)::text);
    _rc := 1;
  END IF;
  v_query := (v_query || ' ORDER BY OldInvCode ');
  _rc := 1;
  _dq2 := v_query;
  IF _dq2 IS NOT NULL THEN
    IF _dq2 ~* '^[[:space:]]*select' THEN OPEN rs2 FOR EXECUTE dbo.tsql_dyn(_dq2); ELSE EXECUTE dbo.tsql_dyn(_dq2); END IF;
  END IF;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((0 = 0) AND (_rc > 0)) THEN
    v_query := 'Insert Into tmp_detail (OldInvCode,QuotationCode,ICode,Qty,PackUnits,SalePrice,DiscPerc,SalesTax,itemflatdisc,BonusQty,GSTPerc,UnitSalesTax,ItemDescription,gcode,RemoteNetSaleQty,RemoteStock,PORate,PODiscPerc,SpecialRate,RefNo) ';
    _rc := 1;
    v_query := (v_query || 'Select OldInvCode=QuotationCode,QuotationCode=-1,ICode,Qty,PackUnits,SalePrice,DiscPerc,SalesTax,itemflatdisc,BonusQty,GSTPerc,UnitSalesTax,ItemDescription,gcode,RemoteNetSaleQty,RemoteStock,PORate,PODiscPerc,SpecialRate,RefNo ');
    _rc := 1;
    v_query := ((((((((v_query || 'From ') || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.') || 'QuotationDetail ');
    _rc := 1;
    v_query := ((((v_query || 'Where QuotationCode Between ') || (v_sinvcode)::text) || ' And ') || (v_linvcode)::text);
    _rc := 1;
    IF (v_custcode > 0) THEN
      v_query := (((v_query || ' AND QuotationCode IN (SELECT QuotationCode FROM QuotationHeader WHERE CustCode = ') || (v_custcode)::text) || ') ');
      _rc := 1;
    END IF;
    v_query := (v_query || ' ORDER BY OldInvCode, RowID ');
    _rc := 1;
    _dq3 := v_query;
    IF _dq3 IS NOT NULL THEN
      IF _dq3 ~* '^[[:space:]]*select' THEN OPEN rs3 FOR EXECUTE dbo.tsql_dyn(_dq3); ELSE EXECUTE dbo.tsql_dyn(_dq3); END IF;
    END IF;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem in inserting detail records From Remote DataBase';
      return_value := -1;
      RETURN;
    END IF;
  ELSE
    IF ((_rc = 0) AND (0 = 0)) THEN
      return_value := 1;
      RETURN;
    ELSE
      RAISE EXCEPTION 'Problem in inserting header records From Remote DataBase';
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  v_rowcount := (SELECT count(*) FROM tmp_header AS header);
  _rc := 1;
  IF ((v_linvcode >= v_sinvcode) AND (v_rowcount > 0)) THEN
    v_errcode := 0;
    _rc := 1;
    SELECT r.return_value, r.key INTO v_errcode, v_quotationcode FROM dbo.sp_locktabmaxkey(tabname => 'Quotation', key => v_quotationcode) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Problem while Fetching QuotationHeader Key Value';
      return_value := -1;
      RETURN;
    END IF;
    UPDATE tmp_header AS header SET quotationcode = (v_quotationcode + rowid);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    UPDATE tmp_detail AS d SET quotationcode = h.quotationcode FROM tmp_header AS h WHERE (h.oldinvcode = d.oldinvcode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    INSERT INTO dbo.quotationheader (quotationcode, custcode, salesmancode, date, discperc, flatdisc, misccharges, salestax, sprice, validateupto, postdate, remarks, custrefno, headerno, originaldate, modifiedby, postedby, posted, invgstperc1, remarks2, remarks3, remarks4, remarks5, remarks6, remarks7, remarks8, remarks9, pagesize, messagecode, smancode, loosepack, consolidatedsaleorder) SELECT quotationcode, custcode, salesmancode, date, discperc, flatdisc, misccharges, salestax, sprice, validateupto, postdate, remarks, custrefno, headerno, originaldate, NULL::smallint AS modifiedby, NULL::smallint AS postedby, 'N' AS posted, invgstperc1, remarks2, remarks3, remarks4, remarks5, remarks6, remarks7, remarks8, remarks9, pagesize, messagecode, smancode, loosepack, consolidatedsaleorder FROM tmp_header AS header ORDER BY oldinvcode;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem while Inserting Record in QuotationHeader';
      RAISE EXCEPTION 'T-SQL ROLLBACK in sp_Import_Quotation_From_DataCarryDB' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
    INSERT INTO dbo.quotationdetail (quotationcode, icode, qty, packunits, saleprice, discperc, salestax, itemflatdisc, bonusqty, gstperc, unitsalestax, itemdescription, gcode, remotenetsaleqty, remotestock, porate, podiscperc, specialrate, refno) SELECT quotationcode, icode, qty, packunits, saleprice, discperc, salestax, itemflatdisc, bonusqty, gstperc, unitsalestax, itemdescription, gcode, remotenetsaleqty, remotestock, porate, podiscperc, specialrate, refno FROM tmp_detail AS detail;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem while Inserting Record in Quotation Detail';
      RAISE EXCEPTION 'T-SQL ROLLBACK in sp_Import_Quotation_From_DataCarryDB' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
    v_end_invcode := coalesce((SELECT max(quotationcode) FROM tmp_header AS header), 1);
    _rc := 1;
    v_errcode := 0;
    _rc := 1;
    SELECT r.return_value INTO v_errcode FROM dbo.sp_updatetabmaxkey(tabname => 'Quotation', key => v_end_invcode) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Problem while Updating QuotationHeader Key Value';
      RAISE EXCEPTION 'T-SQL ROLLBACK in sp_Import_Quotation_From_DataCarryDB' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  IF (0 = 0) THEN
    return_value := 0;
    RETURN;
  ELSE
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_Import_ServiceSales_From_DataCarryDB ====
CREATE OR REPLACE FUNCTION dbo.sp_import_servicesales_from_datacarrydb(srv citext, db citext, owner citext, sinvcode integer, linvcode integer, custcode smallint, usercode smallint, OUT return_value integer, OUT rs1 refcursor, OUT rs2 refcursor, OUT rs3 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_sinvcode integer;
  v_linvcode integer;
  v_custcode smallint;
  v_usercode smallint;
  v_query citext;
  v_temp citext;
  v_errcode integer;
  v_serviceinvcode integer;
  v_end_invcode integer;
  v_rowcount integer;
  _dq1 text;
  _dq2 text;
  _dq3 text;
  _rc integer;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  v_sinvcode := sinvcode;
  v_linvcode := linvcode;
  v_custcode := custcode;
  v_usercode := usercode;
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  DROP TABLE IF EXISTS tmp_sheader;
  CREATE TEMP TABLE tmp_sheader ON COMMIT DROP AS SELECT serviceinvcode AS oldinvcode, -1 AS serviceinvcode, custcode, salesmancode, servicecatcode, remarks, originaldate, modifiedby, date, postedby, postdate, headerno, discperc, flatdisc, misccharges, saleinvcode, posted, doctcode, reprintingcounter, serviceocode, cashreceived, patientcode, admissioncode, duedate, fullpatientname, patientage, patientsex, patientrefby, ref1, ref2, cashacccode, cashtendered, cashcharged, cashback, invtotal, outstandingamt, tokenno, guestcode, guestcheckincode, studentcode, marked, serviceinvtypecode, messagecode, serviceinvgstperc FROM dbo.serviceheader WHERE (serviceinvcode < 0);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  DROP TABLE IF EXISTS tmp_sdetail;
  CREATE TEMP TABLE tmp_sdetail ON COMMIT DROP AS SELECT serviceinvcode AS oldinvcode, -1 AS serviceinvcode, servicecode, price, discperc, smancode, qty, commission, deliverydate, sampletaken, reportmade, costprice, remarks, serviceflatdisc, servicegstperc, serviceflattax, transportroutecode, vehiclecode FROM dbo.servicedetail WHERE (serviceinvcode < 0);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_query := 'ALTER TABLE tmp_sheader ADD COLUMN RowID integer NOT NULL GENERATED BY DEFAULT AS IDENTITY';
  _rc := 1;
  _dq1 := v_query;
  IF _dq1 IS NOT NULL THEN
    IF _dq1 ~* '^[[:space:]]*select' THEN OPEN rs1 FOR EXECUTE dbo.tsql_dyn(_dq1); ELSE EXECUTE dbo.tsql_dyn(_dq1); END IF;
  END IF;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF (0 <> 0) THEN
    RAISE EXCEPTION 'Problem in adding identity column in temporary table';
    return_value := -1;
    RETURN;
  END IF;
  v_query := 'Insert Into tmp_sheader (OldInvCode,ServiceInvCode,CustCode,SalesmanCode,ServiceCatCode,Remarks,OriginalDate,ModifiedBy,Date,PostedBy,PostDate,HeaderNo,DiscPerc,FlatDisc,MiscCharges,SaleInvCode,Posted,DoctCode,RePrintingCounter,ServiceOCode,CashReceived,PatientCode,AdmissionCode,DueDate,FullPatientName,PatientAge,PatientSex,PatientRefBy,Ref1,Ref2,CashAccCode,CashTendered,CashCharged,CashBack,InvTotal,OutStandingAmt,TokenNo,GuestCode,GuestCheckInCode,StudentCode,Marked,ServiceInvTypeCode,MessageCode,ServiceInvGSTPerc ) ';
  _rc := 1;
  v_query := (v_query || ' Select OldInvCode=ServiceInvCode,ServiceInvCode=-1,CustCode,SalesmanCode,ServiceCatCode,Remarks,OriginalDate,ModifiedBy,Date,PostedBy,PostDate,HeaderNo,DiscPerc,FlatDisc,MiscCharges,SaleInvCode,Posted,DoctCode,RePrintingCounter,ServiceOCode,CashReceived,PatientCode,AdmissionCode,DueDate,FullPatientName,PatientAge,PatientSex,PatientRefBy,Ref1,Ref2,CashAccCode,CashTendered,CashCharged,CashBack,InvTotal,OutStandingAmt,TokenNo,GuestCode,GuestCheckInCode,StudentCode,Marked,ServiceInvTypeCode,MessageCode,ServiceInvGSTPerc ');
  _rc := 1;
  v_query := ((((((((v_query || ' From ') || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.') || 'ServiceHeader ');
  _rc := 1;
  v_query := (((((v_query || ' Where ServiceInvCode Between ') || (v_sinvcode)::text) || ' And ') || (v_linvcode)::text) || ' AND LTRIM(RTRIM(CAST(ServiceInvCode AS VARCHAR(10)))) NOT IN (SELECT LTRIM(RTRIM(Ref2)) FROM ServiceHeader WHERE Ref2 IS NOT NULL) ');
  _rc := 1;
  IF (v_custcode > 0) THEN
    v_query := ((v_query || ' AND CustCode = ') || (v_custcode)::text);
    _rc := 1;
  END IF;
  v_query := (v_query || ' ORDER BY OldInvCode ');
  _rc := 1;
  _dq2 := v_query;
  IF _dq2 IS NOT NULL THEN
    IF _dq2 ~* '^[[:space:]]*select' THEN OPEN rs2 FOR EXECUTE dbo.tsql_dyn(_dq2); ELSE EXECUTE dbo.tsql_dyn(_dq2); END IF;
  END IF;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((0 = 0) AND (_rc > 0)) THEN
    v_query := 'Insert Into tmp_sdetail (OldInvCode,ServiceInvCode,ServiceCode,Price,DiscPerc,SmanCode,Qty,Commission,DeliveryDate,SampleTaken,ReportMade,CostPrice,Remarks,ServiceFlatDisc,ServiceGSTPerc,ServiceFlatTax,TransportRouteCode,VehicleCode) ';
    _rc := 1;
    v_query := (v_query || 'Select OldInvCode=ServiceInvCode,ServiceInvCode=-1,ServiceCode,Price,DiscPerc,SmanCode,Qty,Commission,DeliveryDate,SampleTaken,ReportMade,CostPrice,Remarks,ServiceFlatDisc,ServiceGSTPerc,ServiceFlatTax,TransportRouteCode,VehicleCode ');
    _rc := 1;
    v_query := ((((((((v_query || 'From ') || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.') || 'ServiceDetail ');
    _rc := 1;
    v_query := (((((v_query || 'Where ServiceInvCode Between ') || (v_sinvcode)::text) || ' And ') || (v_linvcode)::text) || ' AND LTRIM(RTRIM(CAST(ServiceInvCode AS VARCHAR(10)))) NOT IN (SELECT LTRIM(RTRIM(Ref2)) FROM ServiceHeader WHERE Ref2 IS NOT NULL) ');
    _rc := 1;
    IF (v_custcode > 0) THEN
      v_query := (((v_query || ' AND ServiceInvCode IN (SELECT ServiceInvCode FROM ServiceHeader WHERE CustCode = ') || (v_custcode)::text) || ') ');
      _rc := 1;
    END IF;
    v_query := (v_query || ' ORDER BY OldInvCode, SrvRowId ');
    _rc := 1;
    _dq3 := v_query;
    IF _dq3 IS NOT NULL THEN
      IF _dq3 ~* '^[[:space:]]*select' THEN OPEN rs3 FOR EXECUTE dbo.tsql_dyn(_dq3); ELSE EXECUTE dbo.tsql_dyn(_dq3); END IF;
    END IF;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem in inserting detail records From Remote DataBase';
      return_value := -1;
      RETURN;
    END IF;
  ELSE
    IF ((_rc = 0) AND (0 = 0)) THEN
      return_value := 1;
      RETURN;
    ELSE
      RAISE EXCEPTION 'Problem in inserting header records From Remote DataBase';
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  v_rowcount := (SELECT count(*) FROM tmp_sheader AS sheader);
  _rc := 1;
  IF ((v_linvcode >= v_sinvcode) AND (v_rowcount > 0)) THEN
    v_errcode := 0;
    _rc := 1;
    SELECT r.return_value, r.key INTO v_errcode, v_serviceinvcode FROM dbo.sp_locktabmaxkey(tabname => 'ServiceHeader', key => v_serviceinvcode) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Problem while Fetching ServiceHeader Key Value';
      return_value := -1;
      RETURN;
    END IF;
    UPDATE tmp_sheader AS sheader SET serviceinvcode = (v_serviceinvcode + rowid);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    UPDATE tmp_sdetail AS d SET serviceinvcode = h.serviceinvcode FROM tmp_sheader AS h WHERE (h.oldinvcode = d.oldinvcode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    INSERT INTO dbo.serviceheader (serviceinvcode, custcode, salesmancode, servicecatcode, remarks, originaldate, modifiedby, date, postedby, postdate, headerno, discperc, flatdisc, misccharges, saleinvcode, posted, doctcode, reprintingcounter, serviceocode, cashreceived, patientcode, admissioncode, duedate, fullpatientname, patientage, patientsex, patientrefby, ref1, ref2, cashacccode, cashtendered, cashcharged, cashback, invtotal, outstandingamt, tokenno, guestcode, guestcheckincode, studentcode, marked, serviceinvtypecode, messagecode, serviceinvgstperc) SELECT serviceinvcode, custcode, salesmancode, servicecatcode, remarks, originaldate, modifiedby, date, postedby, postdate, headerno, discperc, flatdisc, misccharges, NULL::integer AS saleinvcode, posted, doctcode, reprintingcounter, NULL::integer AS serviceocode, cashreceived, patientcode, NULL::integer AS admissioncode, duedate, fullpatientname, patientage, patientsex, patientrefby, ref1, oldinvcode AS ref2, cashacccode, cashtendered, cashcharged, cashback, invtotal, outstandingamt, tokenno, guestcode, guestcheckincode, studentcode, marked, serviceinvtypecode, messagecode, serviceinvgstperc FROM tmp_sheader AS sheader ORDER BY oldinvcode;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem while Inserting Record in ServiceHeader';
      RAISE EXCEPTION 'T-SQL ROLLBACK in sp_Import_ServiceSales_From_DataCarryDB' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
    INSERT INTO dbo.servicedetail (serviceinvcode, servicecode, price, discperc, smancode, qty, commission, deliverydate, sampletaken, reportmade, costprice, remarks, serviceflatdisc, servicegstperc, serviceflattax, transportroutecode, vehiclecode) SELECT serviceinvcode, servicecode, price, discperc, smancode, qty, commission, deliverydate, sampletaken, reportmade, costprice, remarks, serviceflatdisc, servicegstperc, serviceflattax, transportroutecode, vehiclecode FROM tmp_sdetail AS sdetail;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Problem while Inserting Record in ServiceDetail';
      RAISE EXCEPTION 'T-SQL ROLLBACK in sp_Import_ServiceSales_From_DataCarryDB' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
    v_end_invcode := coalesce((SELECT max(serviceinvcode) FROM tmp_sheader AS sheader), 1);
    _rc := 1;
    v_errcode := 0;
    _rc := 1;
    SELECT r.return_value INTO v_errcode FROM dbo.sp_updatetabmaxkey(tabname => 'ServiceHeader', key => v_end_invcode) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Problem while Updating ServiceHeader Key Value';
      RAISE EXCEPTION 'T-SQL ROLLBACK in sp_Import_ServiceSales_From_DataCarryDB' USING ERRCODE = 'TS001';
      return_value := -1;
      RETURN;
    END IF;
    UPDATE dbo.serviceheader SET invtotal = coalesce(dbo.fn_getserviceinvtotal((serviceinvcode)::integer), 0) WHERE (serviceinvcode IN (SELECT serviceinvcode FROM tmp_sheader AS sheader));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    UPDATE dbo.serviceheader SET outstandingamt = CASE WHEN (cashcharged > invtotal) THEN 0 ELSE (invtotal - cashcharged) END WHERE ((servicecatcode <> 10) AND (serviceinvcode IN (SELECT serviceinvcode FROM tmp_sheader AS sheader)));
    GET DIAGNOSTICS _rc = ROW_COUNT;
  END IF;
  IF (0 = 0) THEN
    return_value := 0;
    RETURN;
  ELSE
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_ImportData ====
CREATE OR REPLACE FUNCTION dbo.sp_importdata(srv citext, db citext, owner citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_tablename citext;
  v_imp_tablename citext;
  v_full_table_name citext;
  v_sql citext;
  v_query citext;
  v_from citext;
  v_lastdate timestamp(3);
  v_table_id integer;
  v_err integer;
  v_rt_code integer;
  v_dt timestamp(3);
  cur_tmpcrs1 refcursor;
  _dq1 text;
  _dq2 text;
  _fs integer := -1;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  v_sql := 'SELECT * INTO ';
  v_from := ((((((' FROM ' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.');
  OPEN cur_tmpcrs1 FOR SELECT ltrim(rtrim(tablename)) AS tablename, ('DBO.Import_' || ltrim(rtrim(tablename))) AS imp_tablename FROM dbo.transferabledata WHERE ((enable = 'Y') AND (((((autoinsert = 'Y') OR (autoupdate = 'Y')) OR (autodelete = 'Y')) OR (updatetabmaxkey = 'Y')))) ORDER BY priority;
  FETCH NEXT FROM cur_tmpcrs1 INTO v_tablename, v_imp_tablename;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    v_full_table_name := ((ltrim(rtrim(v_owner)) || '.') || v_tablename);
    -- SET @table_id = OBJECT_ID(@full_table_name)
    RAISE EXCEPTION 'untranslated T-SQL (OBJECT_ID of non-literal)' USING ERRCODE = '0A000';
    v_err := 0;
    IF (((0 <> 0) OR (v_err <> 0)) OR (v_table_id IS NULL)) THEN
      RAISE EXCEPTION 'Import Basic Data Problem: Invalid Object Refered: Name = %', v_full_table_name;
      CLOSE cur_tmpcrs1;
      -- DEALLOCATE TmpCrs1
      return_value := -1;
      RETURN;
    END IF;
    IF ((lower(v_tablename))::citext = 'item') THEN
      v_lastdate := coalesce((SELECT max(lastupdate) FROM dbo.item), '01-01-1900 00:00:00');
      v_query := (((((v_sql || v_imp_tablename) || ' ') || v_from) || v_tablename) || ' AS T WHERE T.LastUpdate NOT IN (SELECT DISTINCT I.LASTUPDATE FROM Item I)');
    ELSE
      v_query := ((((v_sql || v_imp_tablename) || ' ') || v_from) || v_tablename);
    END IF;
    _dq1 := v_query;
    IF _dq1 IS NOT NULL THEN
      EXECUTE dbo.tsql_dyn(_dq1);
    END IF;
    v_err := 0;
    IF ((0 <> 0) OR (v_err <> 0)) THEN
      RAISE EXCEPTION 'Import Basic Data Problem: Error Transfering Data From % into % ', v_tablename, v_imp_tablename;
      CLOSE cur_tmpcrs1;
      -- DEALLOCATE TmpCrs1
      return_value := -1;
      RETURN;
    END IF;
    FETCH NEXT FROM cur_tmpcrs1 INTO v_tablename, v_imp_tablename;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_tmpcrs1;
  -- DEALLOCATE TmpCrs1
  v_full_table_name := (ltrim(rtrim(v_owner)) || '.GodownDetail');
  -- SET @table_id = OBJECT_ID(@full_table_name)
  RAISE EXCEPTION 'untranslated T-SQL (OBJECT_ID of non-literal)' USING ERRCODE = '0A000';
  v_err := 0;
  IF (((0 <> 0) OR (v_err <> 0)) OR (v_table_id IS NULL)) THEN
    RAISE EXCEPTION 'Import Stock Data Problem: Invalid Object Refered: Name = %', v_full_table_name;
    return_value := -1;
    RETURN;
  END IF;
  v_imp_tablename := (ltrim(rtrim(v_owner)) || '.Import_GodownDetail');
  v_query := ((((v_sql || v_imp_tablename) || ' ') || v_from) || 'GodownDetail');
  _dq2 := v_query;
  IF _dq2 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq2);
  END IF;
  v_err := 0;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Import Stock Data Problem: Error Transfering Data From % into % ', v_tablename, v_imp_tablename;
    return_value := -1;
    RETURN;
  END IF;
  v_dt := localtimestamp(3);
  SELECT r.return_value INTO v_rt_code FROM dbo.sp_set_datetime_preference(prefname => 'LastDataImport', prefvalue => v_dt) AS r;
  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
    RAISE EXCEPTION 'Unable to Record Last Sale Import Information in Software Preferences';
    return_value := -1;
    RETURN;
  END IF;
  INSERT INTO dbo.dataimportlog (logdate, importedby, importtype, remarks) VALUES (localtimestamp(3), 1, 'Complete Data Import', 'Complete Data Import');
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_ImportData_From_ParentServer ====
CREATE OR REPLACE FUNCTION dbo.sp_importdata_from_parentserver(srv citext, db citext, owner citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_rt_code integer;
  v_err integer;
  v_continue integer;
  v_rc integer;
  v_sequenceid integer;
  v_myseq integer;
  v_appversion integer;
  v_myver integer;
  v_dbstatus integer;
  v_dbstat integer;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  -- BEGIN TRANSACTION (the caller owns the transaction)
  v_myseq := trunc(coalesce((SELECT sequenceid FROM dbo.sequence), 0))::integer;
  v_myver := trunc(coalesce((SELECT appversion FROM dbo.sequence), 0))::integer;
  v_dbstat := coalesce((SELECT dbstatus FROM dbo.sequence), 0);
  SELECT r.return_value, r.sequenceid, r.appversion, r.dbstatus INTO v_rc, v_sequenceid, v_appversion, v_dbstatus FROM dbo.sp_getversioninfo(srv => v_srv, db => v_db, owner => v_owner, sequenceid => v_sequenceid, appversion => v_appversion, dbstatus => v_dbstatus) AS r;
  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
    RAISE EXCEPTION 'T-SQL ROLLBACK in sp_ImportData_From_ParentServer' USING ERRCODE = 'TS001';
  ELSE
    IF (((v_sequenceid <> v_myseq) OR (v_appversion <> v_myver)) OR (v_dbstatus <> v_dbstat)) THEN
      RAISE EXCEPTION 'T-SQL ROLLBACK in sp_ImportData_From_ParentServer' USING ERRCODE = 'TS001';
    ELSE
      SELECT r.return_value INTO v_rt_code FROM dbo.sp_dropimporttables() AS r;
      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
        RAISE EXCEPTION 'T-SQL ROLLBACK in sp_ImportData_From_ParentServer' USING ERRCODE = 'TS001';
      ELSE
        -- COMMIT (the caller owns the transaction)
        -- BEGIN TRANSACTION (the caller owns the transaction)
        SELECT r.return_value INTO v_rt_code FROM dbo.sp_importdata(srv => v_srv, db => v_db, owner => v_owner) AS r;
        IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
          RAISE EXCEPTION 'T-SQL ROLLBACK in sp_ImportData_From_ParentServer' USING ERRCODE = 'TS001';
        ELSE
          -- COMMIT (the caller owns the transaction)
        END IF;
      END IF;
    END IF;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_ImportSales ====
CREATE OR REPLACE FUNCTION dbo.sp_importsales(srv citext, db citext, owner citext, startdate timestamp, enddate timestamp, INOUT templatecode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_startdate timestamp(3);
  v_enddate timestamp(3);
  v_templatecode integer;
  v_tablequalifier citext;
  v_sqldetail citext;
  v_headercode integer;
  v_errcode integer;
  _dq1 text;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  v_startdate := startdate;
  v_enddate := enddate;
  v_templatecode := templatecode;
  -- SET NOCOUNT ON
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  -- SET XACT_ABORT ON
  v_tablequalifier := ((((ltrim(rtrim(v_srv)) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner)));
  SELECT r.return_value, r.key INTO v_errcode, v_templatecode FROM dbo.sp_gettabmaxkey(tabname => 'SaleTemplateHeader', key => v_templatecode) AS r;
  v_errcode := 0;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem in generating sale template';
    return_value := -1;
    templatecode := v_templatecode;
    RETURN;
  END IF;
  INSERT INTO dbo.saletemplateheader (saletemplatecode, date, modified, name, headerno) SELECT v_templatecode, localtimestamp(3) AS date, localtimestamp(3) AS modified, (((((('FROM ' || ltrim(rtrim(left(to_char(v_startdate, 'Mon DD YYYY HH12:MIAM'), 100)))) || ' TO ') || ltrim(rtrim(left(to_char(v_enddate, 'Mon DD YYYY HH12:MIAM'), 100)))) || ' (') || ltrim(rtrim(dbo.tsql_str((v_templatecode)::numeric)))) || ')') AS name, 1 AS headerno;
  IF (0 <> 0) THEN
    RAISE EXCEPTION 'Problem in generating sale template header';
    return_value := -1;
    templatecode := v_templatecode;
    RETURN;
  END IF;
  v_errcode := 0;
  v_sqldetail := (((((((((((('INSERT INTO DBO.SaleTemplateDetail (SaleTemplateCode, Icode, LooseQty, PackQty, SalePrice, DiscPerc, ItemFlatDisc, UnitSalesTax, GSTPerc, PackUnits, Remarks, BonusQty, SaleInvCode, SaleDate, CustCode, SaleCatCode, Marked) SELECT Template=' || ltrim(rtrim(dbo.tsql_str((v_templatecode)::numeric)))) || ' , D.ICode, LooseQty=SUM(D.LooseQty), PackQty=0, D.SalePrice, D.DiscPerc, D.ItemFlatDisc, D.UnitSalesTax, D.GstPerc, D.PackUnits, Remarks=S.Remarks, BonusQty = SUM(D.BonusQty), SaleInvCode=S.SaleInvCode, SaleDate=S.Date, CustCode=S.CustCode, S.SaleCatCode, Marked=''Y'' FROM ') || v_tablequalifier) || '.SaleLedger S, ') || v_tablequalifier) || '.SaleDetail D, ') || v_tablequalifier) || '.Item I WHERE S.SaleInvCode = D.SaleInvCode AND S.Date BETWEEN ''') || ltrim(rtrim(left(to_char(v_startdate, 'Mon DD YYYY HH12:MIAM'), 100)))) || ''' AND ''') || ltrim(rtrim(left(to_char(v_enddate, 'Mon DD YYYY HH12:MIAM'), 100)))) || ''' AND D.ICode = I.ICode GROUP BY I.Name, S.SaleInvCode, S.Date, S.CustCode, S.SaleCatCode, S.Remarks, D.ICode, D.SalePrice, D.DiscPerc, D.ItemFlatDisc, D.UnitSalesTax, D.GstPerc, D.PackUnits ORDER BY S.SaleInvCode, D.ICode');
  _dq1 := v_sqldetail;
  IF _dq1 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq1);
  END IF;
  IF ((0 = 0) AND (v_errcode = 0)) THEN
    return_value := 0;
    templatecode := v_templatecode;
    RETURN;
  ELSE
    RAISE EXCEPTION 'Unable To successfully generate sale template detail';
  END IF;
  return_value := -1;
  templatecode := v_templatecode;
  RETURN;
  return_value := 0;
  templatecode := v_templatecode;
  RETURN;
END
$body$;

-- ==== proc sp_ImportStock_From_ParentServer ====
CREATE OR REPLACE FUNCTION dbo.sp_importstock_from_parentserver(srv citext, db citext, owner citext, usercode smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_usercode smallint;
  v_query citext;
  v_from citext;
  v_rt_code integer;
  v_err integer;
  v_continue integer;
  v_rc integer;
  v_sequenceid integer;
  v_myseq integer;
  v_appversion integer;
  v_myver integer;
  v_dbstatus integer;
  v_dbstat integer;
  _dq1 text;
  _dq2 text;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  v_usercode := usercode;
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  v_myseq := trunc(coalesce((SELECT sequenceid FROM dbo.sequence), 0))::integer;
  v_myver := trunc(coalesce((SELECT appversion FROM dbo.sequence), 0))::integer;
  v_dbstat := coalesce((SELECT dbstatus FROM dbo.sequence), 0);
  -- BEGIN TRANSACTION (the caller owns the transaction)
  SELECT r.return_value, r.sequenceid, r.appversion, r.dbstatus INTO v_rc, v_sequenceid, v_appversion, v_dbstatus FROM dbo.sp_getversioninfo(srv => v_srv, db => v_db, owner => v_owner, sequenceid => v_sequenceid, appversion => v_appversion, dbstatus => v_dbstatus) AS r;
  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
    RAISE EXCEPTION 'T-SQL ROLLBACK in sp_ImportStock_From_ParentServer' USING ERRCODE = 'TS001';
    RAISE EXCEPTION 'Import Stock Problem: Failure in Version Fetching';
    return_value := -1;
    RETURN;
  ELSE
    IF (((v_sequenceid <> v_myseq) OR (v_appversion <> v_myver)) OR (v_dbstatus <> v_dbstat)) THEN
      RAISE EXCEPTION 'T-SQL ROLLBACK in sp_ImportStock_From_ParentServer' USING ERRCODE = 'TS001';
      RAISE EXCEPTION 'Import Stock Problem: Version Conflict Exist between the two databases';
      return_value := -1;
      RETURN;
    ELSE
      v_query := 'TRUNCATE TABLE GodownDetail';
      _dq1 := v_query;
      IF _dq1 IS NOT NULL THEN
        EXECUTE dbo.tsql_dyn(_dq1);
      END IF;
      IF (0 <> 0) THEN
        RAISE EXCEPTION 'T-SQL ROLLBACK in sp_ImportStock_From_ParentServer' USING ERRCODE = 'TS001';
        RAISE EXCEPTION 'Stock Truncation Problem';
        return_value := -1;
        RETURN;
      END IF;
      v_query := (((((('INSERT INTO GodownDetail SELECT T.* FROM ' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.GodownDetail T WHERE T.ICode IN (SELECT ICode FROM Item)');
      _dq2 := v_query;
      IF _dq2 IS NOT NULL THEN
        EXECUTE dbo.tsql_dyn(_dq2);
      END IF;
      IF (0 <> 0) THEN
        RAISE EXCEPTION 'T-SQL ROLLBACK in sp_ImportStock_From_ParentServer' USING ERRCODE = 'TS001';
        RAISE EXCEPTION 'Stock Import Error';
        return_value := -1;
        RETURN;
      ELSE
        INSERT INTO dbo.dataimportlog (logdate, importedby, importtype, remarks) VALUES (localtimestamp(3), v_usercode, 'Stock Position Only', 'Stock Position Updated via Job');
      END IF;
    END IF;
  END IF;
  -- COMMIT (the caller owns the transaction)
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_IncomeStatement ====
