  INSERT INTO dbo.reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5) SELECT -1 AS code1, 1 AS code2, 0 AS code3, (SELECT name FROM dbo.categoryaccounts WHERE (catacccode = v_ln_revenuefromsalescat)) AS name1, '' AS name2, coalesce(sum((coalesce(v.debit, 0) - coalesce(v.credit, 0))), 0) AS value1, 0 AS value2, 0 AS value3, 0 AS value4, v_ad_sdate AS date1, v_ad_edate AS date2, (v_ac_level)::numeric(15,2) AS value5 FROM dbo.virtualgl AS v WHERE (((v.acccode IN (SELECT acccode FROM dbo.accounts WHERE (subcode IN (SELECT subacccode FROM dbo.subaccounts WHERE (catacccode = v_ln_revenuefromsalescat))))) AND (v.date >= v_ad_sdate)) AND (v.date <= v_ad_edate));
