  END IF;
  IF (v_ln_temp <> 0) THEN
    INSERT INTO dbo.reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5) SELECT -1 AS code1, 11 AS code2, 0 AS code3, 'NET INCOME/LOSS FOR THE PERIOD' AS name1, '' AS name2, (SELECT coalesce(sum(coalesce(value1, 0)), 0) FROM dbo.reportdata WHERE (code2 IN ((SELECT max(code2) FROM dbo.reportdata WHERE (code2 IN (3, 5, 7, 9))), 10))) AS value1, 0 AS value2, 0 AS value3, 0 AS value4, v_ad_sdate AS date1, v_ad_edate AS date2, (v_ac_level)::numeric(15,2) AS value5;
    GET DIAGNOSTICS _rc = ROW_COUNT;
  END IF;
  IF (_rc <> 0) THEN
    v_ln_temp := (SELECT coalesce(sum(coalesce(value1, 0)), 0) FROM dbo.reportdata WHERE (code2 = 11));
    _rc := 1;
  END IF;
  UPDATE dbo.reportdata SET value1 = 0 WHERE (value1 IS NULL);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF (v_ac_level <> '0') THEN
    v_ln_temp := (SELECT coalesce(code2, 0) FROM dbo.reportdata WHERE (code2 = 1));
    _rc := 1;
    IF (v_ln_temp <> 0) THEN
      INSERT INTO dbo.reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5) SELECT 1 AS code1, (SELECT (max(code2) + 1) FROM dbo.reportdata) AS code2, ac.acccode AS code3, ac.name AS name1, (SELECT DISTINCT name1 FROM dbo.reportdata WHERE (code2 = 1)) AS name2, a.balance AS value1, 0 AS value2, 0 AS value3, 1 AS value4, v_ad_sdate AS date1, v_ad_edate AS date2, (v_ac_level)::numeric(15,2) AS value5 FROM (SELECT acccode, coalesce(sum((debit - credit)), 0) AS balance FROM dbo.virtualgl WHERE (((acccode IN (SELECT acccode FROM dbo.accounts WHERE (subcode IN (SELECT subacccode FROM dbo.subaccounts WHERE (catacccode = v_ln_revenuefromsalescat))))) AND (date >= v_ad_sdate)) AND (date <= v_ad_edate)) GROUP BY acccode) AS a, dbo.accounts AS ac WHERE (a.acccode = ac.acccode);
      GET DIAGNOSTICS _rc = ROW_COUNT;
    END IF;
    v_ln_temp := (SELECT coalesce(code2, 0) FROM dbo.reportdata WHERE (code2 = 2));
    _rc := 1;
    IF (v_ln_temp <> 0) THEN
      IF (v_invsys = 'P') THEN
        INSERT INTO dbo.reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5) SELECT 2 AS code1, (SELECT (max(code2) + 1) FROM dbo.reportdata) AS code2, -2 AS code3, 'OPENING STOCK/INVENTORY ' AS name1, (SELECT DISTINCT name1 FROM dbo.reportdata WHERE (code2 = 2)) AS name2, (SELECT round((coalesce(sum(coalesce((newavgprice * newstock), 0)), 0))::numeric, 0) FROM dbo.stockledger WHERE ((date < v_ad_sdate) AND (((((icode)::text || ' ') || (utn)::text))::citext IN (SELECT (((icode)::text || ' ') || (max(utn))::text) FROM dbo.stockledger WHERE (date < v_ad_sdate) GROUP BY icode)))) AS value1, 0 AS value2, 0 AS value3, 1 AS value4, v_ad_sdate AS date1, v_ad_edate AS date2, (v_ac_level)::numeric(15,2) AS value5;
        GET DIAGNOSTICS _rc = ROW_COUNT;
      END IF;
      INSERT INTO dbo.reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5) SELECT 2 AS code1, (SELECT (max(code2) + 1) FROM dbo.reportdata) AS code2, ac.acccode AS code3, ac.name AS name1, (SELECT DISTINCT name1 FROM dbo.reportdata WHERE (code2 = 2)) AS name2, coalesce(a.balance, 0) AS value1, 0 AS value2, 0 AS value3, 1 AS value4, v_ad_sdate AS date1, v_ad_edate AS date2, (v_ac_level)::numeric(15,2) AS value5 FROM (SELECT acccode, sum((coalesce(debit, 0) - coalesce(credit, 0))) AS balance FROM dbo.virtualgl WHERE (((acccode IN (SELECT acccode FROM dbo.accounts WHERE (subcode IN (SELECT subacccode FROM dbo.subaccounts WHERE (catacccode = v_ln_directexpensescat))))) AND (date >= v_ad_sdate)) AND (date <= v_ad_edate)) GROUP BY acccode) AS a, dbo.accounts AS ac WHERE (a.acccode = ac.acccode);
      GET DIAGNOSTICS _rc = ROW_COUNT;
      IF (v_invsys = 'P') THEN
        INSERT INTO dbo.reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5) SELECT 2 AS code1, (SELECT (max(code2) + 1) FROM dbo.reportdata) AS code2, -1 AS code3, 'CLOSING STOCK/INVENTORY ' AS name1, (SELECT DISTINCT name1 FROM dbo.reportdata WHERE (code2 = 2)) AS name2, (SELECT round((coalesce(sum((-coalesce((newavgprice * newstock), 0))), 0))::numeric, 0) FROM dbo.stockledger WHERE ((date <= v_ad_edate) AND (((((icode)::text || ' ') || (utn)::text))::citext IN (SELECT (((icode)::text || ' ') || (max(utn))::text) FROM dbo.stockledger WHERE (date <= v_ad_edate) GROUP BY icode)))) AS value1, 0 AS value2, 0 AS value3, 1 AS value4, v_ad_sdate AS date1, v_ad_edate AS date2, (v_ac_level)::numeric(15,2) AS value5;
        GET DIAGNOSTICS _rc = ROW_COUNT;
      END IF;
    END IF;
    v_ln_temp := (SELECT coalesce(code2, 0) FROM dbo.reportdata WHERE (code2 = 4));
    _rc := 1;
    IF (v_ln_temp <> 0) THEN
      INSERT INTO dbo.reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5) SELECT 4 AS code1, (SELECT (max(code2) + 1) FROM dbo.reportdata) AS code2, acccode AS code3, name AS name1, (SELECT DISTINCT name1 FROM dbo.reportdata WHERE (code2 = 4)) AS name2, coalesce(balance, 0) AS value1, 0 AS value2, 0 AS value3, 1 AS value4, v_ad_sdate AS date1, v_ad_edate AS date2, (v_ac_level)::numeric(15,2) AS value5 FROM (SELECT a.acccode, a.name, sum((coalesce(v.debit, 0) - coalesce(v.credit, 0))) AS balance FROM dbo.virtualgl AS v, dbo.accounts AS a WHERE ((((v.acccode IN (SELECT acccode FROM dbo.accounts WHERE (subcode IN (SELECT subacccode FROM dbo.subaccounts WHERE (catacccode IN (SELECT catacccode FROM dbo.categoryaccounts WHERE (catacccode = v_ln_operatingexpensescat))))))) AND (v.acccode = a.acccode)) AND (v.date >= v_ad_sdate)) AND (v.date <= v_ad_edate)) GROUP BY a.acccode, a.name) AS a;
      GET DIAGNOSTICS _rc = ROW_COUNT;
    END IF;
    v_ln_temp := (SELECT coalesce(code2, 0) FROM dbo.reportdata WHERE (code2 = 6));
    _rc := 1;
    IF (v_ln_temp <> 0) THEN
      INSERT INTO dbo.reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5) SELECT 6 AS code1, (SELECT (max(code2) + 1) FROM dbo.reportdata) AS code2, acccode AS code3, name AS name1, (SELECT DISTINCT name1 FROM dbo.reportdata WHERE (code2 = 6)) AS name2, coalesce(balance, 0) AS value1, 0 AS value2, 0 AS value3, 1 AS value4, v_ad_sdate AS date1, v_ad_edate AS date2, (v_ac_level)::numeric(15,2) AS value5 FROM (SELECT a.acccode, a.name, sum((coalesce(v.debit, 0) - coalesce(v.credit, 0))) AS balance FROM dbo.virtualgl AS v, dbo.accounts AS a WHERE ((((v.acccode IN (SELECT acccode FROM dbo.accounts WHERE (subcode IN (SELECT subacccode FROM dbo.subaccounts WHERE (catacccode IN (SELECT catacccode FROM dbo.categoryaccounts WHERE (catacccode = v_ln_otherexpensescat))))))) AND (v.acccode = a.acccode)) AND (v.date >= v_ad_sdate)) AND (v.date <= v_ad_edate)) GROUP BY a.acccode, a.name) AS a;
      GET DIAGNOSTICS _rc = ROW_COUNT;
    END IF;
    v_ln_temp := (SELECT coalesce(code2, 0) FROM dbo.reportdata WHERE (code2 = 8));
    _rc := 1;
    IF (v_ln_temp <> 0) THEN
      INSERT INTO dbo.reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5) SELECT 8 AS code1, (SELECT (max(code2) + 1) FROM dbo.reportdata) AS code2, acccode AS code3, name AS name1, (SELECT DISTINCT name1 FROM dbo.reportdata WHERE (code2 = 8)) AS name2, coalesce(balance, 0) AS value1, 0 AS value2, 0 AS value3, 1 AS value4, v_ad_sdate AS date1, v_ad_edate AS date2, (v_ac_level)::numeric(15,2) AS value5 FROM (SELECT a.acccode, a.name, sum((coalesce(v.debit, 0) - coalesce(v.credit, 0))) AS balance FROM dbo.virtualgl AS v, dbo.accounts AS a WHERE ((((v.acccode IN (SELECT acccode FROM dbo.accounts WHERE (subcode IN (SELECT subacccode FROM dbo.subaccounts WHERE (catacccode IN (SELECT catacccode FROM dbo.categoryaccounts WHERE (catacccode = v_ln_otherrevenuescat))))))) AND (v.acccode = a.acccode)) AND (v.date >= v_ad_sdate)) AND (v.date <= v_ad_edate)) GROUP BY a.acccode, a.name) AS a;
      GET DIAGNOSTICS _rc = ROW_COUNT;
    END IF;
    INSERT INTO dbo.reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5) SELECT (10 + catacccode) AS code1, catacccode AS code2, acccode AS code3, name AS name1, catname AS name2, coalesce(balance, 0) AS value1, 0 AS value2, 0 AS value3, 1 AS value4, v_ad_sdate AS date1, v_ad_edate AS date2, (v_ac_level)::numeric(15,2) AS value5 FROM (SELECT a.acccode, a.name, c.catacccode, c.name AS catname, sum((coalesce(v.debit, 0) - coalesce(v.credit, 0))) AS balance FROM dbo.virtualgl AS v, dbo.accounts AS a, dbo.subaccounts AS s, dbo.categoryaccounts AS c WHERE ((((((v.acccode IN (SELECT acccode FROM dbo.accounts WHERE (subcode IN (SELECT subacccode FROM dbo.subaccounts WHERE (catacccode IN (SELECT catacccode FROM dbo.categoryaccounts WHERE ((mainacccode IN (4, 5)) AND (catacccode NOT IN (v_ln_revenuefromsalescat, v_ln_directexpensescat, v_ln_operatingexpensescat, v_ln_otherexpensescat, v_ln_otherrevenuescat))))))))) AND (v.acccode = a.acccode)) AND (v.date >= v_ad_sdate)) AND (v.date <= v_ad_edate)) AND (a.subcode = s.subacccode)) AND (s.catacccode = c.catacccode)) GROUP BY a.acccode, a.name, c.name, c.catacccode) AS a;
    GET DIAGNOSTICS _rc = ROW_COUNT;
  END IF;
  UPDATE dbo.reportdata SET value1 = 0 WHERE (value1 IS NULL);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((v_ac_level = '2') OR (v_ac_level = '3')) THEN
    INSERT INTO dbo.reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5) SELECT (SELECT (max(code1) + 1) FROM dbo.reportdata) AS code1, catcode AS code2, acccode AS code3, (SELECT name FROM dbo.salecategory WHERE (salecatcode = s.catcode)) AS name1, (SELECT DISTINCT name1 FROM dbo.reportdata WHERE (code3 = v_ln_salesacc)) AS name2, coalesce(balance, 0) AS value1, 0 AS value2, 0 AS value3, 2 AS value4, v_ad_sdate AS date1, v_ad_edate AS date2, (v_ac_level)::numeric(15,2) AS value5 FROM (SELECT acccode, catcode, sum((debit - credit)) AS balance FROM dbo.virtualgl AS v WHERE (((acccode IN (v_ln_salesacc)) AND (date >= v_ad_sdate)) AND (date <= v_ad_edate)) GROUP BY v.acccode, v.catcode) AS s;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    INSERT INTO dbo.reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5) SELECT (SELECT (max(code1) + 1) FROM dbo.reportdata) AS code1, catcode AS code2, acccode AS code3, (SELECT name FROM dbo.salecategory WHERE (salecatcode = sr.catcode)) AS name1, (SELECT DISTINCT name1 FROM dbo.reportdata WHERE (code3 = v_ln_salesretacc)) AS name2, coalesce(balance, 0) AS value1, 0 AS value2, 0 AS value3, 2 AS value4, v_ad_sdate AS date1, v_ad_edate AS date2, (v_ac_level)::numeric(15,2) AS value5 FROM (SELECT acccode, catcode, sum((debit - credit)) AS balance FROM dbo.virtualgl AS v WHERE (((acccode IN (v_ln_salesretacc)) AND (date >= v_ad_sdate)) AND (date <= v_ad_edate)) GROUP BY v.acccode, v.catcode) AS sr;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    INSERT INTO dbo.reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5) SELECT (SELECT (max(code1) + 1) FROM dbo.reportdata) AS code1, catcode AS code2, acccode AS code3, (SELECT name FROM dbo.purcategory WHERE (purcatcode = p.catcode)) AS name1, (SELECT DISTINCT name1 FROM dbo.reportdata WHERE (code3 = v_ln_purchaseacc)) AS name2, coalesce(balance, 0) AS value1, 0 AS value2, 0 AS value3, 2 AS value4, v_ad_sdate AS date1, v_ad_edate AS date2, (v_ac_level)::numeric(15,2) AS value5 FROM (SELECT acccode, catcode, sum((debit - credit)) AS balance FROM dbo.virtualgl AS v WHERE (((acccode IN (v_ln_purchaseacc)) AND (date >= v_ad_sdate)) AND (date <= v_ad_edate)) GROUP BY v.acccode, v.catcode) AS p;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    INSERT INTO dbo.reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5) SELECT (SELECT (max(code1) + 1) FROM dbo.reportdata) AS code1, catcode AS code2, acccode AS code3, (SELECT name FROM dbo.purcategory WHERE (purcatcode = p.catcode)) AS name1, (SELECT DISTINCT name1 FROM dbo.reportdata WHERE (code3 = v_ln_purchaseretacc)) AS name2, coalesce(balance, 0) AS value1, 0 AS value2, 0 AS value3, 2 AS value4, v_ad_sdate AS date1, v_ad_edate AS date2, (v_ac_level)::numeric(15,2) AS value5 FROM (SELECT acccode, catcode, sum((debit - credit)) AS balance FROM dbo.virtualgl AS v WHERE (((acccode IN (v_ln_purchaseretacc)) AND (date >= v_ad_sdate)) AND (date <= v_ad_edate)) GROUP BY v.acccode, v.catcode) AS p;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    INSERT INTO dbo.reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5) SELECT (SELECT (max(code1) + 1) FROM dbo.reportdata) AS code1, catcode AS code2, a.acccode AS code3, (SELECT name FROM dbo.salecategory WHERE (salecatcode = s.catcode)) AS name1, (SELECT DISTINCT name1 FROM dbo.reportdata WHERE (code3 = v_ln_revfromservice)) AS name2, coalesce(balance, 0) AS value1, 0 AS value2, 0 AS value3, 2 AS value4, v_ad_sdate AS date1, v_ad_edate AS date2, (v_ac_level)::numeric(15,2) AS value5 FROM (SELECT acccode, catcode, sum((debit - credit)) AS balance FROM dbo.virtualgl AS v WHERE (((acccode IN (v_ln_revfromservice)) AND (date >= v_ad_sdate)) AND (date <= v_ad_edate)) GROUP BY v.acccode, v.catcode) AS s, dbo.accounts AS a WHERE (s.acccode = a.acccode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
  END IF;
  IF (v_ac_level = '3') THEN
    v_ln_temp := (SELECT coalesce(code2, 0) FROM dbo.reportdata WHERE (code3 = -2));
    _rc := 1;
    IF ((v_ln_temp <> 0) AND (v_invsys = 'P')) THEN
      INSERT INTO dbo.reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5) SELECT (SELECT (max(code1) + 1) FROM dbo.reportdata) AS code1, 0 AS code2, item.icode AS code3, item.name AS name1, (SELECT DISTINCT name1 FROM dbo.reportdata WHERE (code3 = -2)) AS name2, stockval AS value1, newstock AS value2, newavgprice AS value3, 3 AS value4, v_ad_sdate AS date1, v_ad_edate AS date2, (v_ac_level)::numeric(15,2) AS value5 FROM (SELECT icode, newstock, newavgprice, (-coalesce((newavgprice * newstock), 0)) AS stockval FROM dbo.stockledger WHERE (((date < v_ad_sdate) AND (((((icode)::text || ' ') || (utn)::text))::citext IN (SELECT (((icode)::text || ' ') || (max(utn))::text) FROM dbo.stockledger WHERE (date < v_ad_sdate) GROUP BY icode))) AND (newstock > 0))) AS os, dbo.item WHERE (os.icode = item.icode) ORDER BY item.name;
      GET DIAGNOSTICS _rc = ROW_COUNT;
    END IF;
    v_ln_temp := (SELECT coalesce(code2, 0) FROM dbo.reportdata WHERE (code3 = -1));
    _rc := 1;
    IF ((v_ln_temp <> 0) AND (v_invsys = 'P')) THEN
      INSERT INTO dbo.reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5) SELECT (SELECT (max(code1) + 1) FROM dbo.reportdata) AS code1, 0 AS code2, item.icode AS code3, item.name AS name1, (SELECT DISTINCT name1 FROM dbo.reportdata WHERE (code3 = -1)) AS name2, stockval AS value1, newstock AS value2, newavgprice AS value3, 3 AS value4, v_ad_sdate AS date1, v_ad_edate AS date2, (v_ac_level)::numeric(15,2) AS value5 FROM (SELECT icode, newstock, newavgprice, (-coalesce((newavgprice * newstock), 0)) AS stockval FROM dbo.stockledger WHERE (((date <= v_ad_edate) AND (((((icode)::text || ' ') || (utn)::text))::citext IN (SELECT (((icode)::text || ' ') || (max(utn))::text) FROM dbo.stockledger WHERE (date <= v_ad_edate) GROUP BY icode))) AND (newstock > 0))) AS cs, dbo.item WHERE (cs.icode = item.icode) ORDER BY item.name;
      GET DIAGNOSTICS _rc = ROW_COUNT;
    END IF;
  END IF;
  UPDATE dbo.reportdata SET value1 = 0 WHERE (value1 IS NULL);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  UPDATE dbo.reportdata SET value2 = 0 WHERE (value2 IS NULL);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  -- COMMIT (the caller owns the transaction)
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_IncomeStatment ====
CREATE OR REPLACE FUNCTION dbo.sp_incomestatment(ad_sdate timestamp, ad_edate timestamp, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ad_sdate timestamp(3);
  v_ad_edate timestamp(3);
  v_ln_cashacc numeric(5,0);
  v_ln_equityacc numeric(5,0);
  v_ln_freightacc numeric(5,0);
  v_ln_octroiacc numeric(5,0);
  v_ln_salestaxacc numeric(5,0);
  v_ln_inventoryacc numeric(5,0);
  v_ln_favourableacc numeric(5,0);
  v_ln_unfavourableacc numeric(5,0);
  v_ln_avgpurcostacc numeric(5,0);
  v_ln_salesacc numeric(5,0);
  v_ln_salesfixdiscacc numeric(5,0);
  v_ln_miscchargesacc numeric(5,0);
  v_ln_salesretacc numeric(5,0);
  v_ln_purchaseacc numeric(5,0);
  v_ln_revfromservices numeric(5,0);
  v_ln_netsal numeric(25,5);
  v_ln_gp numeric(25,5);
  v_ln_other_income_exp numeric(25,5);
BEGIN
  v_ad_sdate := ad_sdate;
  v_ad_edate := ad_edate;
  v_ln_cashacc := (SELECT code FROM dbo.global WHERE (name = 'GT_CashACC'));
  v_ln_equityacc := (SELECT code FROM dbo.global WHERE (name = 'GT_EquityACC'));
  v_ln_freightacc := (SELECT code FROM dbo.global WHERE (name = 'GT_FreightACC'));
  v_ln_octroiacc := (SELECT code FROM dbo.global WHERE (name = 'GT_OctroiACC'));
  v_ln_salestaxacc := (SELECT code FROM dbo.global WHERE (name = 'GT_AdvanceSalesTaxACC'));
  v_ln_inventoryacc := (SELECT code FROM dbo.global WHERE (name = 'GT_InventoryACC'));
  v_ln_favourableacc := (SELECT code FROM dbo.global WHERE (name = 'GT_FavourableACC'));
  v_ln_unfavourableacc := (SELECT code FROM dbo.global WHERE (name = 'GT_UnFavourableACC'));
  v_ln_salesacc := (SELECT code FROM dbo.global WHERE (name = 'GT_SalesACC'));
  v_ln_salesfixdiscacc := (SELECT code FROM dbo.global WHERE (name = 'GT_SalesFixDiscountACC'));
  v_ln_miscchargesacc := (SELECT code FROM dbo.global WHERE (name = 'GT_MiscChargesACC'));
  v_ln_salesretacc := (SELECT code FROM dbo.global WHERE (name = 'GT_SalesReturnACC'));
  v_ln_purchaseacc := (SELECT code FROM dbo.global WHERE (name = 'GT_PurchaseACC'));
  v_ln_revfromservices := (SELECT code FROM dbo.global WHERE (name = 'GT_RevenueFromServices'));
  DROP TABLE IF EXISTS tmp_lt_accounts;
  CREATE TEMP TABLE tmp_lt_accounts (
    acccode numeric(5,0) NOT NULL,
    type numeric(2,0) NOT NULL,
    currbalance numeric(25,5) NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_accounts SELECT a.acccode, 0, 0 FROM dbo.accounts AS a WHERE (acccode NOT IN (v_ln_revfromservices, v_ln_salesretacc, v_ln_salesacc));
  DROP TABLE IF EXISTS tmp_lt_purchasesummary;
  CREATE TEMP TABLE tmp_lt_purchasesummary (
    acccode numeric(5,0) NOT NULL,
    netamt numeric(25,2) NOT NULL,
    flatdisc numeric(11,2) NOT NULL,
    misccharges numeric(11,2) NOT NULL,
    salestax numeric(11,2) NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_purchasesummary SELECT CASE purledger.purcatcode WHEN 1 THEN v_ln_cashacc WHEN 3 THEN v_ln_equityacc WHEN 7 THEN v_ln_cashacc ELSE purledger.suppcode END, coalesce(round((((((sum((((((purdetail.looseqty + (purdetail.packqty * purdetail.packunits))) * purdetail.purprice)) * ((1 - ((.01 * purdetail.discperc)))))) * ((1 - ((.01 * purledger.discperc))))) + purledger.misccharges) + purledger.salestax) - purledger.flatdisc))::numeric, 0), 0), purledger.flatdisc, purledger.misccharges, purledger.salestax FROM dbo.purledger, dbo.purdetail WHERE ((((purledger.date >= v_ad_sdate) AND (purledger.date <= v_ad_edate)) AND (purledger.posted = 'Y')) AND (purledger.purinvcode = purdetail.purinvcode)) GROUP BY purledger.purinvcode, purledger.purcatcode, purledger.date, purledger.discperc, purledger.misccharges, purledger.salestax, purledger.flatdisc, purledger.suppcode;
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance - (SELECT coalesce(sum(flatdisc), 0) FROM tmp_lt_purchasesummary AS lt_purchasesummary)) WHERE (lt_accounts.acccode = v_ln_freightacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(misccharges), 0) FROM tmp_lt_purchasesummary AS lt_purchasesummary)) WHERE (lt_accounts.acccode = v_ln_octroiacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(salestax), 0) FROM tmp_lt_purchasesummary AS lt_purchasesummary)) WHERE (lt_accounts.acccode = v_ln_salestaxacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance - (SELECT coalesce(sum(lt_purchasesummary.netamt), 0) FROM tmp_lt_purchasesummary AS lt_purchasesummary WHERE (lt_purchasesummary.acccode = lt_accounts.acccode))) FROM tmp_lt_purchasesummary AS lt_purchasesummary WHERE (lt_accounts.acccode = lt_purchasesummary.acccode);
  DROP TABLE IF EXISTS tmp_lt_purchasesummary;
  DROP TABLE IF EXISTS tmp_lt_purretsummary;
  CREATE TEMP TABLE tmp_lt_purretsummary (
    acccode numeric(5,0) NOT NULL,
    netamt numeric(15,2) NOT NULL,
    flatdisc numeric(11,2) NOT NULL,
    misccharges numeric(11,2) NOT NULL,
    salestax numeric(11,2) NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_purretsummary SELECT CASE prledger.prcatcode WHEN 4 THEN v_ln_cashacc WHEN 6 THEN v_ln_equityacc ELSE prledger.suppcode END, coalesce(round((((((sum((((((prdetail.looseqty + (prdetail.packqty * prdetail.packunits))) * prdetail.prprice)) * ((1 - ((.01 * prdetail.discperc)))))) * ((1 - ((.01 * prledger.discperc))))) + prledger.misccharges) + prledger.salestax) - prledger.flatdisc))::numeric, 0), 0), prledger.flatdisc, prledger.misccharges, prledger.salestax FROM dbo.prledger, dbo.prdetail WHERE ((((prledger.date >= v_ad_sdate) AND (prledger.date <= v_ad_edate)) AND (prledger.posted = 'Y')) AND (prledger.prinvcode = prdetail.prinvcode)) GROUP BY prledger.prinvcode, prledger.suppcode, prledger.prcatcode, prledger.date, prledger.discperc, prledger.misccharges, prledger.salestax, prledger.flatdisc;
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(flatdisc), 0) FROM tmp_lt_purretsummary AS lt_purretsummary)) WHERE (lt_accounts.acccode = v_ln_freightacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance - (SELECT coalesce(sum(misccharges), 0) FROM tmp_lt_purretsummary AS lt_purretsummary)) WHERE (lt_accounts.acccode = v_ln_octroiacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance - (SELECT coalesce(sum(salestax), 0) FROM tmp_lt_purretsummary AS lt_purretsummary)) WHERE (lt_accounts.acccode = v_ln_salestaxacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(lt_purretsummary.netamt), 0) FROM tmp_lt_purretsummary AS lt_purretsummary WHERE (lt_purretsummary.acccode = lt_accounts.acccode))) FROM tmp_lt_purretsummary AS lt_purretsummary WHERE (lt_accounts.acccode = lt_purretsummary.acccode);
  DROP TABLE IF EXISTS tmp_lt_purretsummary;
  DROP TABLE IF EXISTS tmp_lt_salesummary;
  CREATE TEMP TABLE tmp_lt_salesummary (
    acccode numeric(5,0) NOT NULL,
    inventoryamt numeric(15,5) NOT NULL,
    netamt numeric(15,5) NOT NULL,
    salecatcode numeric(1,0) NOT NULL,
    flatdisc numeric(11,2) NOT NULL,
    misccharges numeric(11,2) NOT NULL,
    salestax numeric(11,2) NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_salesummary SELECT CASE saleledger.salecatcode WHEN 1 THEN v_ln_cashacc WHEN 3 THEN v_ln_cashacc ELSE saleledger.custcode END, coalesce(sum((((saledetail.looseqty + (saledetail.packqty * saledetail.packunits))) * saledetail.avgprice)), 0), coalesce(round((((((sum((((((saledetail.looseqty + (saledetail.packqty * saledetail.packunits))) * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc)))))) * ((1 - ((.01 * saleledger.discperc))))) + saleledger.misccharges) + saleledger.salestax) - saleledger.flatdisc))::numeric, 0), 0), saleledger.salecatcode, saleledger.flatdisc, saleledger.misccharges, saleledger.salestax FROM dbo.saleledger, dbo.saledetail WHERE ((((saleledger.date >= v_ad_sdate) AND (saleledger.date <= v_ad_edate)) AND (saleledger.posted = 'Y')) AND (saleledger.saleinvcode = saledetail.saleinvcode)) GROUP BY saleledger.saleinvcode, saleledger.custcode, saleledger.salecatcode, saleledger.date, saleledger.discperc, saleledger.misccharges, saleledger.salestax, saleledger.flatdisc;
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(inventoryamt), 0) FROM tmp_lt_salesummary AS lt_salesummary)) WHERE (lt_accounts.acccode = v_ln_purchaseacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(flatdisc), 0) FROM tmp_lt_salesummary AS lt_salesummary)) WHERE (lt_accounts.acccode = v_ln_salesfixdiscacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance - (SELECT coalesce(sum(misccharges), 0) FROM tmp_lt_salesummary AS lt_salesummary)) WHERE (lt_accounts.acccode = v_ln_miscchargesacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance - (SELECT coalesce(sum(salestax), 0) FROM tmp_lt_salesummary AS lt_salesummary)) WHERE (lt_accounts.acccode = v_ln_salestaxacc);
  INSERT INTO tmp_lt_accounts SELECT DISTINCT v_ln_salesacc, salecatcode, 0 FROM tmp_lt_salesummary AS lt_salesummary;
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance - (SELECT coalesce(sum(netamt), 0) FROM tmp_lt_salesummary AS lt_salesummary WHERE (lt_salesummary.salecatcode = lt_accounts.type))) WHERE (lt_accounts.acccode = v_ln_salesacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(lt_salesummary.netamt), 0) FROM tmp_lt_salesummary AS lt_salesummary WHERE (lt_salesummary.acccode = lt_accounts.acccode))) FROM tmp_lt_salesummary AS lt_salesummary WHERE (lt_accounts.acccode = lt_salesummary.acccode);
  DROP TABLE IF EXISTS tmp_lt_salesummary;
  DROP TABLE IF EXISTS tmp_lt_saleretsummary;
  CREATE TEMP TABLE tmp_lt_saleretsummary (
    acccode numeric(5,0) NOT NULL,
    inventoryamt numeric(15,5) NOT NULL,
    netamt numeric(15,5) NOT NULL,
    srcatcode numeric(1,0) NOT NULL,
    flatdisc numeric(11,2) NOT NULL,
    misccharges numeric(11,2) NOT NULL,
    salestax numeric(11,2) NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_saleretsummary SELECT CASE srledger.srcatcode WHEN 6 THEN v_ln_cashacc WHEN 8 THEN v_ln_cashacc ELSE srledger.custcode END, coalesce((sum((((((srdetail.looseqty + (srdetail.packqty * srdetail.packunits))) * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc)))))) * ((1 - ((.01 * srledger.discperc))))), 0), coalesce(round((((((sum((((((srdetail.looseqty + (srdetail.packqty * srdetail.packunits))) * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc)))))) * ((1 - ((.01 * srledger.discperc))))) + srledger.misccharges) + srledger.salestax) - srledger.flatdisc))::numeric, 0), 0), srledger.srcatcode, srledger.flatdisc, srledger.misccharges, srledger.salestax FROM dbo.srledger, dbo.srdetail WHERE ((((srledger.date >= v_ad_sdate) AND (srledger.date <= v_ad_edate)) AND (srledger.posted = 'Y')) AND (srledger.srinvcode = srdetail.srinvcode)) GROUP BY srledger.srinvcode, srledger.custcode, srledger.srcatcode, srledger.date, srledger.discperc, srledger.misccharges, srledger.salestax, srledger.flatdisc;
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance - (SELECT coalesce(sum(inventoryamt), 0) FROM tmp_lt_saleretsummary AS lt_saleretsummary)) WHERE (lt_accounts.acccode = v_ln_purchaseacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance - (SELECT coalesce(sum(flatdisc), 0) FROM tmp_lt_saleretsummary AS lt_saleretsummary)) WHERE (lt_accounts.acccode = v_ln_salesfixdiscacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(misccharges), 0) FROM tmp_lt_saleretsummary AS lt_saleretsummary)) WHERE (lt_accounts.acccode = v_ln_miscchargesacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(salestax), 0) FROM tmp_lt_saleretsummary AS lt_saleretsummary)) WHERE (lt_accounts.acccode = v_ln_salestaxacc);
  INSERT INTO tmp_lt_accounts SELECT DISTINCT v_ln_salesretacc, srcatcode, 0 FROM tmp_lt_saleretsummary AS lt_saleretsummary;
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(netamt), 0) FROM tmp_lt_saleretsummary AS lt_saleretsummary WHERE (lt_saleretsummary.srcatcode = lt_accounts.type))) WHERE (lt_accounts.acccode = v_ln_salesretacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance - (SELECT coalesce(sum(netamt), 0) FROM tmp_lt_saleretsummary AS lt_saleretsummary WHERE (lt_saleretsummary.acccode = lt_accounts.acccode))) FROM tmp_lt_saleretsummary AS lt_saleretsummary WHERE (lt_accounts.acccode = lt_saleretsummary.acccode);
  DROP TABLE IF EXISTS tmp_lt_saleretsummary;
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum((gldetail.debit - gldetail.credit)), 0) FROM dbo.glheader, dbo.gldetail WHERE (((((glheader.date >= v_ad_sdate) AND (glheader.date <= v_ad_edate)) AND (glheader.posted = 'Y')) AND (glheader.glvochcode = gldetail.glvochcode)) AND (gldetail.acccode = lt_accounts.acccode)))) WHERE (lt_accounts.acccode IN (SELECT DISTINCT acccode FROM dbo.gldetail));
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(CASE notecatcode WHEN 1 THEN (amount * -1) ELSE notes.amount END), 0) FROM dbo.notes WHERE ((((notes.postdate >= v_ad_sdate) AND (notes.postdate <= v_ad_edate)) AND (notes.posted = 'Y')) AND (notes.acccode = lt_accounts.acccode)))) WHERE (lt_accounts.acccode IN (SELECT DISTINCT acccode FROM dbo.notes));
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(CASE notecatcode WHEN 1 THEN amount ELSE (notes.amount * -1) END), 0) FROM dbo.notes WHERE ((((notes.postdate >= v_ad_sdate) AND (notes.postdate <= v_ad_edate)) AND (notes.posted = 'Y')) AND (notes.bankacccode = lt_accounts.acccode)))) WHERE (lt_accounts.acccode IN (SELECT DISTINCT bankacccode FROM dbo.notes));
  DROP TABLE IF EXISTS tmp_lt_stockadj;
  CREATE TEMP TABLE tmp_lt_stockadj (
    acccode numeric(5,0) NOT NULL,
    netamt numeric(15,5) NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_stockadj SELECT h.acccode, round((sum((((d.looseqty + d.bonusqty)) * d.price)))::numeric, 0) AS netamt FROM dbo.adjheader AS h, dbo.adjdetail AS d WHERE (((((h.date >= v_ad_sdate) AND (h.date <= v_ad_edate)) AND (h.posted = 'Y')) AND (h.adjcatcode = 2)) AND (h.adjcode = d.adjcode)) GROUP BY h.adjcode, h.acccode;
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(netamt), 0) FROM tmp_lt_stockadj AS lt_stockadj)) FROM tmp_lt_stockadj AS lt_stockadj WHERE (lt_accounts.acccode = lt_stockadj.acccode);
  DROP TABLE IF EXISTS tmp_lt_stockadj;
  DROP TABLE IF EXISTS tmp_lt_stockadj2;
  CREATE TEMP TABLE tmp_lt_stockadj2 (
    acccode numeric(5,0) NOT NULL,
    netamt numeric(15,5) NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_stockadj2 SELECT h.acccode, round((sum((((d.looseqty + d.bonusqty)) * d.price)))::numeric, 0) AS netamt FROM dbo.adjheader AS h, dbo.adjdetail AS d WHERE (((((h.posteddate >= v_ad_sdate) AND (h.posteddate <= v_ad_edate)) AND (h.posted = 'Y')) AND (h.adjcatcode = 1)) AND (h.adjcode = d.adjcode)) GROUP BY h.adjcode, h.acccode;
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance - (SELECT coalesce(sum(netamt), 0) FROM tmp_lt_stockadj2 AS lt_stockadj2)) FROM tmp_lt_stockadj2 AS lt_stockadj2 WHERE (lt_accounts.acccode = lt_stockadj2.acccode);
  DROP TABLE IF EXISTS tmp_lt_stockadj2;
  DROP TABLE IF EXISTS tmp_lt_services;
  CREATE TEMP TABLE tmp_lt_services (
    acccode numeric(5,0) NOT NULL,
    netamt numeric(15,5) NOT NULL,
    servicecatcode numeric(2,0) NOT NULL,
    flatdisc numeric(11,2) NOT NULL,
    misccharges numeric(11,2) NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_services SELECT CASE h.servicecatcode WHEN 10 THEN v_ln_cashacc WHEN 12 THEN v_ln_cashacc ELSE h.custcode END, coalesce(round((sum((((((coalesce(d.price, 0) * ((1 - ((.01 * coalesce(d.discperc, 0))))))) * ((1 - ((.01 * h.discperc))))) + coalesce(h.misccharges, 0)) - coalesce(h.flatdisc, 0))))::numeric, 0), 0), h.servicecatcode, coalesce(h.flatdisc, 0) AS flatdisc, coalesce(h.misccharges, 0) AS misccharges FROM dbo.serviceheader AS h, dbo.servicedetail AS d WHERE ((((h.date >= v_ad_sdate) AND (h.date <= v_ad_edate)) AND (h.posted = 'Y')) AND (h.serviceinvcode = d.serviceinvcode)) GROUP BY h.serviceinvcode, h.custcode, h.servicecatcode, h.date, h.discperc, h.misccharges, h.flatdisc;
  INSERT INTO tmp_lt_accounts SELECT DISTINCT v_ln_revfromservices, servicecatcode, 0 FROM tmp_lt_services AS lt_services;
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance - (SELECT coalesce(sum(netamt), 0) FROM tmp_lt_services AS lt_services WHERE (lt_services.servicecatcode = lt_accounts.type))) WHERE (lt_accounts.acccode = v_ln_revfromservices);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(lt_services.netamt), 0) FROM tmp_lt_services AS lt_services WHERE (lt_services.acccode = lt_accounts.acccode))) FROM tmp_lt_services AS lt_services WHERE (lt_accounts.acccode = lt_services.acccode);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(flatdisc), 0) FROM tmp_lt_services AS lt_services)) WHERE (lt_accounts.acccode = v_ln_salesfixdiscacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance - (SELECT coalesce(sum(misccharges), 0) FROM tmp_lt_services AS lt_services)) WHERE (lt_accounts.acccode = v_ln_miscchargesacc);
  DROP TABLE IF EXISTS tmp_lt_services;
  DROP TABLE IF EXISTS tmp_lt_servicesret;
  CREATE TEMP TABLE tmp_lt_servicesret (
    acccode numeric(5,0) NOT NULL,
    netamt numeric(15,5) NOT NULL,
    servicecatcode numeric(2,0) NOT NULL,
    flatdisc numeric(11,2) NOT NULL,
    misccharges numeric(11,2) NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_servicesret SELECT CASE h.servicercatcode WHEN 13 THEN v_ln_cashacc WHEN 15 THEN v_ln_cashacc ELSE h.custcode END, coalesce(round((sum((((((coalesce(d.serviceprice, 0) * ((1 - ((.01 * coalesce(d.discperc, 0))))))) * ((1 - ((.01 * h.discperc))))) + coalesce(h.misccharges, 0)) - coalesce(h.flatdisc, 0))))::numeric, 0), 0), h.servicercatcode, coalesce(h.flatdisc, 0) AS flatdisc, coalesce(h.misccharges, 0) AS misccharges FROM dbo.servicerheader AS h, dbo.servicerdetail AS d WHERE ((((h.date >= v_ad_sdate) AND (h.date <= v_ad_edate)) AND (h.posted = 'Y')) AND (h.servicerinvcode = d.servicerinvcode)) GROUP BY h.servicerinvcode, h.custcode, h.servicercatcode, h.date, h.discperc, h.misccharges, h.flatdisc;
  INSERT INTO tmp_lt_accounts SELECT DISTINCT v_ln_revfromservices, servicecatcode, 0 FROM tmp_lt_servicesret AS lt_servicesret;
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(netamt), 0) FROM tmp_lt_servicesret AS lt_servicesret WHERE (lt_servicesret.servicecatcode = lt_accounts.type))) WHERE (lt_accounts.acccode = v_ln_revfromservices);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance - (SELECT coalesce(sum(lt_servicesret.netamt), 0) FROM tmp_lt_servicesret AS lt_servicesret WHERE (lt_servicesret.acccode = lt_accounts.acccode))) FROM tmp_lt_servicesret AS lt_servicesret WHERE (lt_accounts.acccode = lt_servicesret.acccode);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance - (SELECT coalesce(sum(flatdisc), 0) FROM tmp_lt_servicesret AS lt_servicesret)) WHERE (lt_accounts.acccode = v_ln_salesfixdiscacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(misccharges), 0) FROM tmp_lt_servicesret AS lt_servicesret)) WHERE (lt_accounts.acccode = v_ln_miscchargesacc);
  DROP TABLE IF EXISTS tmp_lt_servicesret;
  DROP TABLE IF EXISTS tmp_lt_amt;
  CREATE TEMP TABLE tmp_lt_amt (
    acccode integer NOT NULL,
    subacccode smallint NOT NULL,
    catacccode smallint NOT NULL,
    mainacccode smallint NOT NULL,
    acname citext NOT NULL,
    subacname citext NOT NULL,
    catacname citext NOT NULL,
    mainacname citext NOT NULL,
    value1 numeric(25,5) NULL,
    type numeric(2,0) NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_amt (acccode, subacccode, catacccode, mainacccode, acname, subacname, catacname, mainacname, value1, type) SELECT a.acccode, s.subacccode, c.catacccode, m.mainacccode, a.name, s.name, c.name, m.name, lt_accounts.currbalance, lt_accounts.type FROM tmp_lt_accounts AS lt_accounts, dbo.accounts AS a, dbo.subaccounts AS s, dbo.categoryaccounts AS c, dbo.mainaccounts AS m WHERE ((((((lt_accounts.acccode = a.acccode) AND (a.subcode = s.subacccode)) AND (s.catacccode = c.catacccode)) AND (c.mainacccode = m.mainacccode)) AND (m.mainacccode IN (4, 5))) AND (lt_accounts.currbalance <> 0));
  UPDATE tmp_lt_amt AS lt_amt SET acname = salecategory.name FROM dbo.salecategory WHERE ((lt_amt.acccode IN (v_ln_revfromservices, v_ln_salesretacc, v_ln_salesacc)) AND (lt_amt.type = salecategory.salecatcode));
  DELETE FROM dbo.reportdata;
  INSERT INTO dbo.reportdata (code1, code2, name1, name2, name3, value1, value2, date1, date2) SELECT acccode AS code1, subacccode AS code2, acname, subacname, mainacname, value1, 0, v_ad_sdate AS date1, v_ad_edate AS date2 FROM tmp_lt_amt AS lt_amt WHERE (acccode = v_ln_salesacc);
  INSERT INTO dbo.reportdata (code1, code2, name1, name2, name3, value1, value2, date1, date2) SELECT acccode AS code1, subacccode AS code2, 'TOTAL SALES FOR THE PERIOD' AS acname, subacname, mainacname, 0 AS value1, sum(value1) AS value2, v_ad_sdate AS date1, v_ad_edate AS date2 FROM tmp_lt_amt AS lt_amt WHERE (acccode = v_ln_salesacc) GROUP BY acccode, catacccode, subacccode, mainacccode, subacname, catacname, mainacname;
  INSERT INTO dbo.reportdata (code1, code2, name1, name2, name3, value1, value2, date1, date2) SELECT acccode AS code1, subacccode AS code2, acname, subacname, mainacname, value1, 0, v_ad_sdate AS date1, v_ad_edate AS date2 FROM tmp_lt_amt AS lt_amt WHERE (acccode = v_ln_salesretacc);
  INSERT INTO dbo.reportdata (code1, code2, name1, name2, name3, value1, value2, date1, date2) SELECT acccode AS code1, subacccode AS code2, 'TOTAL RETURNS FOR THE PERIOD' AS acname, subacname, mainacname, 0 AS value1, sum(value1) AS value2, v_ad_sdate AS date1, v_ad_edate AS date2 FROM tmp_lt_amt AS lt_amt WHERE (acccode = v_ln_salesretacc) GROUP BY acccode, catacccode, subacccode, mainacccode, subacname, catacname, mainacname;
  SELECT sum(value2) INTO v_ln_netsal FROM dbo.reportdata;
  INSERT INTO dbo.reportdata (code1, code2, name1, name2, name3, value1, value2, date1, date2) SELECT DISTINCT acccode AS code1, subacccode AS code2, 'NET SALES FOR THE PERIOD' AS acname, subacname, mainacname, 0 AS value1, (SELECT sum(i.value1) FROM dbo.reportdata AS i) AS value2, v_ad_sdate AS date1, v_ad_edate AS date2 FROM tmp_lt_amt AS lt_amt WHERE (acccode = v_ln_salesretacc);
  INSERT INTO dbo.reportdata (code1, code2, name1, name2, name3, value1, value2, date1, date2) SELECT acccode AS code1, subacccode AS code2, 'COST OF SALES' AS acname, subacname, mainacname, 0 AS value1, value1 AS value2, v_ad_sdate AS date1, v_ad_edate AS date2 FROM tmp_lt_amt AS lt_amt WHERE (acccode = v_ln_purchaseacc);
  SELECT (v_ln_netsal + sum(i.value2)) INTO v_ln_gp FROM dbo.reportdata AS i WHERE (i.code1 = v_ln_purchaseacc);
  INSERT INTO dbo.reportdata (code1, code2, name1, name2, name3, value1, value2, date1, date2) SELECT acccode AS code1, subacccode AS code2, 'GROSS PROFIT/(LOSS)' AS acname, subacname, mainacname, 0 AS value1, v_ln_gp AS value2, v_ad_sdate AS date1, v_ad_edate AS date2 FROM tmp_lt_amt AS lt_amt WHERE (acccode = v_ln_purchaseacc);
  SELECT sum(value1) INTO v_ln_other_income_exp FROM tmp_lt_amt AS lt_amt WHERE (acccode NOT IN (SELECT i.code1 FROM dbo.reportdata AS i));
  INSERT INTO dbo.reportdata (code1, code2, name1, name2, name3, value1, value2, date1, date2) SELECT acccode AS code1, subacccode AS code2, acname, 'Misc. Sales Income' AS subacname, mainacname, 0 AS value1, value1 AS value2, v_ad_sdate AS date1, v_ad_edate AS date2 FROM tmp_lt_amt AS lt_amt WHERE (acccode = v_ln_miscchargesacc);
  INSERT INTO dbo.reportdata (code1, code2, name1, name2, name3, value1, value2, date1, date2) SELECT acccode AS code1, subacccode AS code2, acname, subacname, mainacname, 0 AS value1, value1 AS vlaue2, v_ad_sdate AS date1, v_ad_edate AS date2 FROM tmp_lt_amt AS lt_amt WHERE (acccode = v_ln_revfromservices);
  INSERT INTO dbo.reportdata (code1, code2, name1, name2, name3, value1, value2, date1, date2) SELECT subacccode, subacccode, acname, subacname, mainacname, 0 AS value1, sum(value2) AS value2, date1 AS date1, date2 AS date2 FROM (SELECT acccode, subacccode, subacname AS acname, subacname, mainacname, 0 AS value1, sum(value1) AS value2, v_ad_sdate AS date1, v_ad_edate AS date2 FROM tmp_lt_amt AS lt_amt WHERE (acccode NOT IN (SELECT i.code1 FROM dbo.reportdata AS i)) GROUP BY mainacccode, catacccode, subacccode, acccode, subacname, mainacname, acname) AS abc GROUP BY subacccode, subacname, mainacname, acname, date1, date2 ORDER BY 1;
  INSERT INTO dbo.reportdata (code1, code2, name1, name2, name3, value1, value2, date1, date2) SELECT NULL::numeric(15,4) AS code1, NULL::numeric(15,4) AS code2, 'NET PROFIT/(LOSS)' AS acname, NULL::citext, NULL::citext, 0 AS value1, (v_ln_other_income_exp + v_ln_gp) AS value2, v_ad_sdate AS date1, v_ad_edate AS date2;
  DROP TABLE IF EXISTS tmp_lt_accounts;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_InheritQuotation ====
CREATE OR REPLACE FUNCTION dbo.sp_inheritquotation(ai_quotationcode integer, ai_acccode integer, as_remarks citext, ai_usercode smallint, INOUT ai_newquotationcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_quotationcode integer;
  v_ai_acccode integer;
  v_as_remarks citext;
  v_ai_usercode smallint;
  v_ai_newquotationcode integer;
  v_err integer;
  v_rowcount integer;
  v_tabmaxkey integer;
  v_ai_newcode integer;
BEGIN
  v_ai_quotationcode := ai_quotationcode;
  v_ai_acccode := ai_acccode;
  v_as_remarks := as_remarks;
  v_ai_usercode := ai_usercode;
  v_ai_newquotationcode := ai_newquotationcode;
  SELECT r.return_value, r.key INTO v_err, v_tabmaxkey FROM dbo.sp_gettabmaxkey(tabname => 'Quotation', key => v_tabmaxkey) AS r;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'New Quotation Code generation problem';
    return_value := -1;
    ai_newquotationcode := v_ai_newquotationcode;
    RETURN;
  END IF;
  INSERT INTO dbo.quotationheader (quotationcode, custcode, salesmancode, date, discperc, flatdisc, misccharges, salestax, sprice, validateupto, postdate, remarks, custrefno, headerno, originaldate, modifiedby, postedby, posted, invgstperc1, remarks2, remarks3, remarks4, remarks5, remarks6, remarks7, remarks8, remarks9, pagesize, messagecode, smancode, loosepack, consolidatedsaleorder, active, locked, autoinsertnewitems) SELECT v_tabmaxkey AS quotationcode, v_ai_acccode AS custcode, v_ai_usercode AS salesmancode, localtimestamp(3) AS date, discperc, flatdisc, misccharges, salestax, sprice, validateupto, localtimestamp(3) AS postdate, v_as_remarks AS remarks, custrefno, headerno, localtimestamp(3) AS originaldate, modifiedby, postedby, 'N' AS posted, invgstperc1, remarks2, remarks3, remarks4, remarks5, remarks6, remarks7, remarks8, remarks9, pagesize, messagecode, smancode, loosepack, consolidatedsaleorder, active, locked, autoinsertnewitems FROM dbo.quotationheader WHERE (quotationcode = v_ai_quotationcode);
  v_err := 0;
  IF (v_err <> 0) THEN
    RAISE EXCEPTION 'Quotation Header Problem';
    return_value := -1;
    ai_newquotationcode := v_ai_newquotationcode;
    RETURN;
  END IF;
  INSERT INTO dbo.quotationdetail (quotationcode, icode, qty, packunits, saleprice, discperc, salestax, itemflatdisc, bonusqty, gstperc, unitsalestax, itemdescription, gcode, remotenetsaleqty, remotestock, porate, podiscperc, specialrate, refno) SELECT v_tabmaxkey AS quotationcode, icode, qty, packunits, saleprice, discperc, salestax, itemflatdisc, bonusqty, gstperc, unitsalestax, itemdescription, gcode, remotenetsaleqty, remotestock, porate, podiscperc, specialrate, refno FROM dbo.quotationdetail WHERE (quotationcode = v_ai_quotationcode);
  v_err := 0;
  IF (v_err <> 0) THEN
    RAISE EXCEPTION 'Quotation Header Problem';
    return_value := -1;
    ai_newquotationcode := v_ai_newquotationcode;
    RETURN;
  END IF;
  v_ai_newquotationcode := v_tabmaxkey;
  return_value := 0;
  ai_newquotationcode := v_ai_newquotationcode;
  RETURN;
  return_value := 0;
  ai_newquotationcode := v_ai_newquotationcode;
  RETURN;
END
$body$;

-- ==== proc sp_init_after_opening_voch ====
CREATE OR REPLACE FUNCTION dbo.sp_init_after_opening_voch(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
BEGIN
  UPDATE dbo.gldetail SET glutn = ((SELECT utn FROM dbo._utn) + glrowid);
  UPDATE dbo._utn SET utn = (SELECT (max(glutn) + 1) FROM dbo.gldetail);
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_init_customers_balances ====
CREATE OR REPLACE FUNCTION dbo.sp_init_customers_balances(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
BEGIN
  INSERT INTO dbo.glheader (glvochcode, vouchercode, vochcatcode, acccode, date, salesmancode, posted, postdate, remarks, originaldate, modifiedby, postedby) SELECT (SELECT (coalesce(max(glvochcode), 0) + 1) FROM dbo.glheader), (SELECT (coalesce(max(vouchercode), 0) + 1) FROM dbo.glheader WHERE (glheader.vochcatcode = 5)), 5, trunc((SELECT code FROM dbo.global WHERE ((tablename = 'Accounts') AND (name = 'GT_EquityACC'))))::smallint, localtimestamp(3), 1, 'Y', localtimestamp(3), ('CUSTOMER OPENING BALANCE TRANSAFERRED TO CAPITAL ON ' || left(to_char(localtimestamp(3), 'YY/MM/DD'), 30)), localtimestamp(3), NULL::smallint, 1;
  INSERT INTO dbo.gldetail (glvochcode, acccode, patientcode, guestcode, studentcode, debit, credit, chkno, remarks, balance, outstandingamt) SELECT (SELECT max(glvochcode) FROM dbo.glheader), acccode, patientcode, guestcode, studentcode, CASE WHEN (balance > 0) THEN abs(balance) ELSE 0 END AS debit, CASE WHEN (balance < 0) THEN abs(balance) ELSE 0 END AS credit, '', ('CUSTOMER OPENING BALANCE ON ' || left(to_char(localtimestamp(3), 'YY/MM/DD'), 30)), 0, 0 FROM (SELECT acccode, patientcode, guestcode, studentcode, sum((debit - credit)) AS balance FROM dbo.virtualgl WHERE (acccode IN (SELECT custcode FROM dbo.customer)) GROUP BY acccode, patientcode, guestcode, studentcode HAVING (sum((debit - credit)) <> 0)) AS b;
  INSERT INTO dbo.gldetail (glvochcode, acccode, patientcode, guestcode, studentcode, debit, credit, chkno, remarks, balance, outstandingamt) SELECT (SELECT max(glvochcode) FROM dbo.glheader) AS glvochcode, trunc((SELECT code FROM dbo.global WHERE ((tablename = 'Accounts') AND (name = 'GT_EquityACC'))))::smallint AS acccode, NULL::integer AS patientcode, NULL::integer AS guestcode, NULL::integer AS studentcode, CASE WHEN (balance > 0) THEN 0 ELSE abs(balance) END AS debit, CASE WHEN (balance < 0) THEN 0 ELSE abs(balance) END AS credit, '', ('CUSTOMER OPENING BALANCE TRANSAFERRED TO CAPITAL ON ' || left(to_char(localtimestamp(3), 'YY/MM/DD'), 30)), 0, 0 FROM (SELECT sum((debit - credit)) AS balance FROM dbo.gldetail WHERE (glvochcode = (SELECT max(glvochcode) FROM dbo.glheader)) HAVING (sum((debit - credit)) <> 0)) AS b;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

