-- ==== proc SP_init_Fetch_LastPurchaseHistory ====
CREATE OR REPLACE FUNCTION dbo.sp_init_fetch_lastpurchasehistory(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
BEGIN
  TRUNCATE TABLE dbo.lastpurchasehistory;
  INSERT INTO dbo.lastpurchasehistory (purinvcode, supplier, date, purcatcode, icode, packunits, qty, bonusqty, purprice, saleprice, discperc, itemflatdisc, unitsalestax, gstperc, netrate, avgprice, newavgprice, invdiscperc, currstock, alternatecustomicode, itemadvancetaxperc, salestaxschedulecode, pctcode) SELECT pl.purinvcode AS purinvcode, (SELECT a.name FROM dbo.accounts AS a WHERE (a.acccode = pl.suppcode)) AS supplier, pl.date AS date, pl.purcatcode AS purcatcode, pd.icode AS icode, pd.packunits AS packunits, (pd.packqty + pd.looseqty) AS qty, pd.bonusqty AS bonusqty, pd.purprice AS purprice, pd.saleprice AS saleprice, pd.discperc AS discperc, pd.itemflatdisc AS itemflatdisc, pd.unitsalestax AS unitsalestax, pd.gstperc AS gstperc, pd.netrate AS netrate, pd.avgprice AS avgprice, pd.newavgprice AS newavgprice, pl.discperc AS invdiscperc, pd.currstock, pd.alternatecustomicode, pd.itemadvancetaxperc, pd.salestaxschedulecode, pd.pctcode FROM dbo.purledger AS pl, dbo.purdetail AS pd, (SELECT dd.icode, max(dd.purinvcode) AS purinvcode FROM dbo.purdetail AS dd GROUP BY dd.icode) AS d WHERE ((((pl.purinvcode = pd.purinvcode) AND (pl.purinvcode = d.purinvcode)) AND (pd.purinvcode = d.purinvcode)) AND (pd.icode = d.icode));
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_init_loyaltypoints ====
CREATE OR REPLACE FUNCTION dbo.sp_init_loyaltypoints(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_err integer;
  v_rowcount integer;
BEGIN
  -- SET NOCOUNT ON
  DROP TABLE IF EXISTS tmp_op_points;
  CREATE TEMP TABLE tmp_op_points ON COMMIT DROP AS SELECT loyaltycardcode, 0 AS pointsbalance, sum((pointsdebit - pointscredit)) AS adjustedpoints, sum((debit - credit)) AS adjustmentvalue FROM dbo.loyaltycardledger GROUP BY loyaltycardcode;
  IF (0 <> 0) THEN
    RAISE EXCEPTION '1-Error Processing Opening Loyalty Points';
    return_value := -1;
    RETURN;
  END IF;
  DELETE FROM tmp_op_points AS op_points WHERE ((adjustedpoints = 0) AND (adjustmentvalue = 0));
  IF (0 <> 0) THEN
    RAISE EXCEPTION '1-Error Processing Opening Loyalty Points';
    return_value := -1;
    RETURN;
  END IF;
  v_rowcount := coalesce((SELECT count(*) FROM tmp_op_points AS op_points), 0);
  IF (v_rowcount = 0) THEN
    return_value := 0;
    RETURN;
  END IF;
  DROP TABLE IF EXISTS tmp_tempadj;
  CREATE TEMP TABLE tmp_tempadj (
    adjustmentcode integer,
    adjustmenttypecode smallint,
    date timestamp(3),
    usercode smallint,
    loyaltycardcode integer,
    pointsbalance integer,
    adjustedpoints integer,
    adjustmentvalue integer,
    remarks citext,
    rowid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_tempadj (adjustmentcode, adjustmenttypecode, date, usercode, loyaltycardcode, pointsbalance, adjustedpoints, adjustmentvalue, remarks) SELECT 0 AS adjustmentcode, CASE WHEN (adjustedpoints > 0) THEN 1 ELSE 2 END AS adjustmenttypecode, localtimestamp(3) AS date, 1 AS usercode, loyaltycardcode, pointsbalance, abs(adjustedpoints) AS adjustedpoints, trunc(abs(adjustmentvalue))::integer AS adjustmentvalue, 'Opening Points B/F:' AS remarks FROM tmp_op_points AS op_points ORDER BY loyaltycardcode;
  v_err := 0;
  IF (v_err <> 0) THEN
    RAISE EXCEPTION '4-Error Processing Opening Loyalty Points';
    return_value := -1;
    RETURN;
  END IF;
  UPDATE tmp_tempadj AS tempadj SET adjustmentcode = rowid;
  v_err := 0;
  IF (v_err <> 0) THEN
    RAISE EXCEPTION '5-Error Processing Opening Loyalty Points';
    return_value := -1;
    RETURN;
  END IF;
  INSERT INTO dbo.loyaltypointadjustment (adjustmentcode, adjustmenttypecode, date, usercode, loyaltycardcode, pointsbalance, adjustedpoints, adjustmentvalue, remarks) SELECT adjustmentcode, adjustmenttypecode, date, usercode, loyaltycardcode, pointsbalance, adjustedpoints, adjustmentvalue, remarks FROM tmp_tempadj AS tempadj;
  v_err := 0;
  IF (v_err <> 0) THEN
    RAISE EXCEPTION '6-Error Processing Opening Loyalty Points';
    return_value := -1;
    RETURN;
  END IF;
  TRUNCATE TABLE dbo.loyaltycardledger;
  INSERT INTO dbo.loyaltycardledger SELECT lp.loyaltycardcode, a.acccode, lp.date, lp.usercode, CASE WHEN (lp.adjustmenttypecode = 1) THEN lp.adjustedpoints ELSE 0 END AS pointsdebit, CASE WHEN (lp.adjustmenttypecode = 1) THEN 0 ELSE lp.adjustedpoints END AS pointscredit, CASE WHEN (lp.adjustmenttypecode = 1) THEN lp.adjustmentvalue ELSE 0 END AS debit, CASE WHEN (lp.adjustmenttypecode = 1) THEN 0 ELSE lp.adjustmentvalue END AS credit, lp.remarks AS remarks, 'AD' AS invoicetype, adjustmentcode AS invoicecode FROM dbo.loyaltypointadjustment AS lp, dbo.loyaltycard AS c, dbo.accounts AS a WHERE ((lp.loyaltycardcode = c.loyaltycardcode) AND (c.acccode = a.acccode));
  v_err := 0;
  IF (v_err <> 0) THEN
    RAISE EXCEPTION '7-Error Processing Opening Loyalty Points';
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_init_opening_pur ====
CREATE OR REPLACE FUNCTION dbo.sp_init_opening_pur(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
BEGIN
  IF ((SELECT count(*) FROM dbo.godowndetail) > 0) THEN
    INSERT INTO dbo.purledger (purinvcode, purcatcode, suppcode, salesmancode, date, discperc, flatdisc, misccharges, salestax, posted, postdate, remarks) VALUES (1, 3, 18, 1, localtimestamp(3), 0, 0, 0, 0, 'Y', localtimestamp(3), 'Opening Purchase ');
    INSERT INTO dbo.purdetail (purinvcode, icode, gcode, batch, expiry, packqty, looseqty, bonusqty, packunits, purprice, discperc, avgprice, newavgprice, saleprice, recentpurprice, netrate) SELECT 1, item.icode, godowndetail.gcode, godowndetail.batch, godowndetail.expiry, 0, godowndetail.currqty, 0, item.packunits, item.avgprice, 0, item.avgprice, item.avgprice, item.saleprice, item.recentpurprice, item.avgprice FROM dbo.item, dbo.godowndetail WHERE (item.icode = godowndetail.icode);
    UPDATE dbo.purdetail SET purutn = purrowid;
    UPDATE dbo._utn SET utn = (SELECT (coalesce(max(purrowid), 0) + 3) FROM dbo.purdetail);
    UPDATE dbo.purledger SET invtotal = p.net FROM (SELECT purledger.purinvcode AS purinvcode, (round((((sum(((((purdetail.looseqty + purdetail.packqty) + purdetail.bonusqty)) * purdetail.unitsalestax)) + sum(round((((((((purdetail.looseqty + purdetail.packqty)) * purdetail.purprice) * ((1 - ((.01 * purdetail.discperc))))) * purdetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((((purdetail.looseqty + purdetail.packqty)) * purdetail.purprice)) * ((1 - ((.01 * purdetail.discperc)))))) * ((1 - ((.01 * purledger.discperc))))) - purledger.flatdisc)) * ((purledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) + round((((((sum(((((purdetail.looseqty + purdetail.packqty)) * purdetail.purprice) * ((1 - ((.01 * purdetail.discperc)))))) * ((1 - ((.01 * purledger.discperc))))) + purledger.misccharges) + purledger.salestax) - purledger.flatdisc))::numeric, 0)) AS net FROM dbo.purledger, dbo.purdetail WHERE (purledger.purinvcode = purdetail.purinvcode) GROUP BY purledger.purinvcode, purledger.suppcode, purledger.purcatcode, purledger.postdate, purledger.discperc, purledger.misccharges, purledger.salestax, purledger.flatdisc, purledger.invgstperc1) AS p WHERE (purledger.purinvcode = p.purinvcode);
  END IF;
  UPDATE dbo._utn SET utn = (SELECT (coalesce(max(purrowid), 0) + 3) FROM dbo.purdetail);
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_init_others_balances ====
CREATE OR REPLACE FUNCTION dbo.sp_init_others_balances(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
BEGIN
  INSERT INTO dbo.glheader (glvochcode, vouchercode, vochcatcode, acccode, date, salesmancode, posted, postdate, remarks, originaldate, modifiedby, postedby) SELECT (SELECT (coalesce(max(glvochcode), 0) + 1) FROM dbo.glheader), (SELECT (coalesce(max(vouchercode), 0) + 1) FROM dbo.glheader WHERE (glheader.vochcatcode = 5)), 5, trunc((SELECT code FROM dbo.global WHERE ((tablename = 'Accounts') AND (name = 'GT_EquityACC'))))::smallint, localtimestamp(3), 1, 'Y', localtimestamp(3), ('OPENING BALANCE TRANSFERRED TO CAPITAL ON ' || left(to_char(localtimestamp(3), 'YY/MM/DD'), 30)), localtimestamp(3), NULL::smallint, 1;
  INSERT INTO dbo.gldetail (glvochcode, acccode, debit, credit, chkno, remarks, balance, outstandingamt) SELECT (SELECT max(glvochcode) FROM dbo.glheader), acccode, CASE WHEN (balance > 0) THEN abs(balance) ELSE 0 END AS debit, CASE WHEN (balance < 0) THEN abs(balance) ELSE 0 END AS credit, '', ('OPENING BALANCE ON ' || left(to_char(localtimestamp(3), 'YY/MM/DD'), 30)), 0, 0 FROM (SELECT acccode, sum((debit - credit)) AS balance FROM dbo.virtualgl WHERE (acccode IN (SELECT acccode FROM dbo.accounts AS a, dbo.subaccounts AS s, dbo.categoryaccounts AS c, dbo.mainaccounts AS m WHERE (((((a.subcode NOT IN (3, 7)) AND (m.mainacccode IN (1, 2, 3))) AND (m.mainacccode = c.mainacccode)) AND (c.catacccode = s.catacccode)) AND (s.subacccode = a.subcode)))) GROUP BY acccode HAVING (sum((debit - credit)) <> 0)) AS b;
  INSERT INTO dbo.gldetail (glvochcode, acccode, debit, credit, chkno, remarks, balance, outstandingamt) SELECT (SELECT max(glvochcode) FROM dbo.glheader) AS glvochcode, trunc((SELECT code FROM dbo.global WHERE ((tablename = 'Accounts') AND (name = 'GT_EquityACC'))))::smallint AS acccode, CASE WHEN (balance > 0) THEN 0 ELSE abs(balance) END AS debit, CASE WHEN (balance < 0) THEN 0 ELSE abs(balance) END AS credit, '', ('OPENING BALANCE TRANSFERRED TO CAPITAL ON ' || left(to_char(localtimestamp(3), 'YY/MM/DD'), 30)), 0, 0 FROM (SELECT sum((debit - credit)) AS balance FROM dbo.gldetail WHERE (glvochcode = (SELECT max(glvochcode) FROM dbo.glheader)) HAVING (sum((debit - credit)) <> 0)) AS b;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

