  INSERT INTO dbo.gldetail (glvochcode, acccode, debit, credit, chkno, remarks, balance, outstandingamt) SELECT (SELECT max(glvochcode) FROM dbo.glheader), acccode, CASE WHEN (balance > 0) THEN abs(balance) ELSE 0 END AS debit, CASE WHEN (balance < 0) THEN abs(balance) ELSE 0 END AS credit, '', ('SUPPLIER OPENING BALANCE ON ' || left(to_char(localtimestamp(3), 'YY/MM/DD'), 30)), 0, 0 FROM (SELECT acccode, sum((debit - credit)) AS balance FROM dbo.virtualgl WHERE (acccode IN (SELECT suppcode FROM dbo.supplier)) GROUP BY acccode HAVING (sum((debit - credit)) <> 0)) AS b;
  INSERT INTO dbo.gldetail (glvochcode, acccode, debit, credit, chkno, remarks, balance, outstandingamt) SELECT (SELECT max(glvochcode) FROM dbo.glheader) AS glvochcode, trunc((SELECT code FROM dbo.global WHERE ((tablename = 'Accounts') AND (name = 'GT_EquityACC'))))::smallint AS acccode, CASE WHEN (balance > 0) THEN 0 ELSE abs(balance) END AS debit, CASE WHEN (balance < 0) THEN 0 ELSE abs(balance) END AS credit, '', ('SUPPLIER OPENING BALANCE TRANSFERRED TO CAPITAL ON ' || left(to_char(localtimestamp(3), 'YY/MM/DD'), 30)), 0, 0 FROM (SELECT sum((debit - credit)) AS balance FROM dbo.gldetail WHERE (glvochcode = (SELECT max(glvochcode) FROM dbo.glheader)) HAVING (sum((debit - credit)) <> 0)) AS b;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_init_update_headertabmaxkey ====
CREATE OR REPLACE FUNCTION dbo.sp_init_update_headertabmaxkey(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
BEGIN
  DELETE FROM dbo._headertabmaxkey;
  INSERT INTO dbo._headertabmaxkey (headercode, module, tabmaxkey) SELECT (trunc((tabname)::numeric))::smallint AS headercode, 1 AS module, trunc(tabmaxkey)::integer FROM dbo._tabmaxkey WHERE ((tabid = 12) AND (tabname <> 'SaleLedger'));
  INSERT INTO dbo._headertabmaxkey (headercode, module, tabmaxkey) SELECT (trunc((tabname)::numeric))::smallint AS headercode, 2 AS module, 0 FROM dbo._tabmaxkey WHERE ((tabid = 12) AND (tabname <> 'SaleLedger'));
  INSERT INTO dbo._headertabmaxkey (headercode, module, tabmaxkey) SELECT (trunc((tabname)::numeric))::smallint AS headercode, 3 AS module, 0 FROM dbo._tabmaxkey WHERE ((tabid = 12) AND (tabname <> 'SaleLedger'));
  INSERT INTO dbo._headertabmaxkey (headercode, module, tabmaxkey) SELECT (trunc((tabname)::numeric))::smallint AS headercode, 4 AS module, 0 FROM dbo._tabmaxkey WHERE ((tabid = 12) AND (tabname <> 'SaleLedger'));
  INSERT INTO dbo._headertabmaxkey (headercode, module, tabmaxkey) SELECT (trunc((tabname)::numeric))::smallint AS headercode, 5 AS module, 0 FROM dbo._tabmaxkey WHERE ((tabid = 12) AND (tabname <> 'SaleLedger'));
  INSERT INTO dbo._headertabmaxkey (headercode, module, tabmaxkey) SELECT (trunc((tabname)::numeric))::smallint AS headercode, 6 AS module, 0 FROM dbo._tabmaxkey WHERE ((tabid = 12) AND (tabname <> 'SaleLedger'));
  INSERT INTO dbo._headertabmaxkey (headercode, module, tabmaxkey) SELECT (trunc((tabname)::numeric))::smallint AS headercode, 7 AS module, 0 FROM dbo._tabmaxkey WHERE ((tabid = 12) AND (tabname <> 'SaleLedger'));
  INSERT INTO dbo._headertabmaxkey (headercode, module, tabmaxkey) SELECT (trunc((tabname)::numeric))::smallint AS headercode, 8 AS module, 0 FROM dbo._tabmaxkey WHERE ((tabid = 12) AND (tabname <> 'SaleLedger'));
  INSERT INTO dbo._headertabmaxkey (headercode, module, tabmaxkey) SELECT (trunc((tabname)::numeric))::smallint AS headercode, 12 AS module, 0 FROM dbo._tabmaxkey WHERE ((tabid = 12) AND (tabname <> 'SaleLedger'));
  INSERT INTO dbo._headertabmaxkey (headercode, module, tabmaxkey) SELECT (trunc((tabname)::numeric))::smallint AS headercode, 15 AS module, 0 FROM dbo._tabmaxkey WHERE ((tabid = 12) AND (tabname <> 'SaleLedger'));
  INSERT INTO dbo._headertabmaxkey (headercode, module, tabmaxkey) SELECT (trunc((tabname)::numeric))::smallint AS headercode, 21 AS module, 0 FROM dbo._tabmaxkey WHERE ((tabid = 12) AND (tabname <> 'SaleLedger'));
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_init_update_tabmaxkey ====
CREATE OR REPLACE FUNCTION dbo.sp_init_update_tabmaxkey(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_err integer;
BEGIN
  SELECT r.return_value INTO v_err FROM dbo.sp_initialize_tabmaxkey() AS r;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Problem in TabMaxKey Initialization';
    return_value := -1;
    RETURN;
  END IF;
  TRUNCATE TABLE dbo.virtualgl;
  TRUNCATE TABLE dbo.stockledger;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_Initialize_TabMaxKey ====
CREATE OR REPLACE FUNCTION dbo.sp_initialize_tabmaxkey(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_qry citext;
  v_colname citext;
  v_tbl citext;
  v_pk citext;
  v_fulltbl citext;
  v_keyseq smallint;
  v_table_id integer;
  v_err integer;
  cur_upd1 refcursor;
  cur_upd2 refcursor;
  _dq1 text;
  _fs integer := -1;
BEGIN
  -- SET NOCOUNT ON
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  OPEN cur_upd1 FOR SELECT ltrim(rtrim(tabname)) AS tablename FROM dbo._tabmaxkey WHERE ((tabid <> 12) AND (tabname NOT IN ('Quotation', 'SaleLedgerCashDummy', 'SaleLedgerCreditDummy', 'DataTransferLog', 'PrescriptionHeaderLog', 'SRLedger'))) UNION ALL SELECT 'SaleLedger' AS tablename ORDER BY 1;
  FETCH NEXT FROM cur_upd1 INTO v_tbl;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    v_pk := '';
    v_fulltbl := ('DBO.' || v_tbl);
    -- SET @table_id = OBJECT_ID(@FullTBL)
    RAISE EXCEPTION 'untranslated T-SQL (OBJECT_ID of non-literal)' USING ERRCODE = '0A000';
    v_err := 0;
    IF (((0 <> 0) OR (v_err <> 0)) OR (v_table_id IS NULL)) THEN
      RAISE EXCEPTION 'TabMaxKey Initialization: Invalid Object Refered: Name = %', v_fulltbl;
      CLOSE cur_upd1;
      -- DEALLOCATE Upd1
      return_value := -1;
      RETURN;
    END IF;
    -- OPEN Upd2
    RAISE EXCEPTION 'untranslated T-SQL (system table sysindexes)' USING ERRCODE = '0A000';
    FETCH NEXT FROM cur_upd2 INTO v_colname, v_keyseq;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    WHILE (_fs = 0) LOOP
      IF (v_keyseq <> 1) THEN
        v_pk := (v_pk || ' AND ');
      END IF;
      v_pk := ((v_pk || ' ') || ltrim(rtrim(v_colname)));
      FETCH NEXT FROM cur_upd2 INTO v_colname, v_keyseq;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    END LOOP;
    CLOSE cur_upd2;
    -- DEALLOCATE Upd2
    v_qry := (((((('UPDATE _TabMaxKey SET Tabmaxkey = COALESCE((SELECT MAX(' || v_pk) || ') FROM ') || v_tbl) || '), 0) WHERE Tabname = ''') || v_tbl) || '''');
    _dq1 := v_qry;
    IF _dq1 IS NOT NULL THEN
      EXECUTE dbo.tsql_dyn(_dq1);
    END IF;
    v_err := 0;
    IF ((0 <> 0) OR (v_err <> 0)) THEN
      RAISE EXCEPTION 'TabMaxKey Initialization: Problem In Updation of % Table', v_fulltbl;
      CLOSE cur_upd1;
      -- DEALLOCATE Upd1
      return_value := -1;
      RETURN;
    END IF;
    FETCH NEXT FROM cur_upd1 INTO v_tbl;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_upd1;
  -- DEALLOCATE Upd1
  UPDATE dbo._tabmaxkey SET tabmaxkey = coalesce((SELECT max(transferlogid) FROM dbo.datatransferlog), 0) WHERE (tabname = 'DataTransferLog');
  UPDATE dbo._tabmaxkey SET tabmaxkey = coalesce((SELECT max(logid) FROM dbo.prescriptionheaderlog), 0) WHERE (tabname = 'PrescriptionHeaderLog');
  UPDATE dbo._tabmaxkey SET tabmaxkey = coalesce((SELECT max(a) FROM (SELECT coalesce(max(srinvcode), 0) AS a FROM dbo.srledger UNION SELECT coalesce(max(srbufferinvcode), 0) AS a FROM dbo.srbufferledger) AS t), 0) WHERE (tabname = 'SRLedger');
  UPDATE dbo._tabmaxkey SET tabmaxkey = coalesce((SELECT max(quotationcode) FROM dbo.quotationheader), 0) WHERE (tabname = 'Quotation');
  UPDATE dbo._tabmaxkey SET tabmaxkey = 0 WHERE (tabname IN ('SaleLedgerCashDummy', 'SaleLedgerCreditDummy'));
  UPDATE dbo._tabmaxkey SET tabmaxkey = 0 WHERE ((tabid = 12) AND (tabname <> 'SaleLedger'));
  UPDATE dbo.vochercategory SET counter = coalesce((SELECT max(glheader.vouchercode) FROM dbo.glheader WHERE (glheader.vochcatcode = vochercategory.vochcatcode)), 0);
  UPDATE dbo.notescategory SET counter = coalesce((SELECT max(notes.vouchercode) FROM dbo.notes WHERE (notes.notecatcode = notescategory.notecatcode)), 0);
  UPDATE dbo.saletype SET counter = coalesce((SELECT max(coalesce(saleledger.saletypeinvno, 0)) FROM dbo.saleledger WHERE (saleledger.saletypecode = saletype.saletypecode)), 0);
  UPDATE dbo.saleordercategory SET counter = coalesce((SELECT max(coalesce(saleorderheader.saleordercode, 0)) FROM dbo.saleorderheader WHERE (saleorderheader.socatcode = saleordercategory.socatcode)), 0);
  UPDATE dbo.receiptcategory SET counter = coalesce((SELECT max(coalesce(receiptheader.receiptcode, 0)) FROM dbo.receiptheader WHERE (receiptheader.receiptcategorycode = receiptcategory.receiptcategorycode)), 0);
  UPDATE dbo.issuecategory SET counter = coalesce((SELECT max(coalesce(issueheader.issuecode, 0)) FROM dbo.issueheader WHERE (issueheader.issuecategorycode = issuecategory.issuecategorycode)), 0);
  UPDATE dbo._tabmaxkey SET tabmaxkey = 100 WHERE ((tabname = 'Accounts') AND (coalesce((SELECT max(coalesce(acccode, 0)) FROM dbo.accounts), 0) < 100));
  UPDATE dbo._tabmaxkey SET tabmaxkey = 100 WHERE ((tabname = 'SubAccounts') AND (coalesce((SELECT max(coalesce(subacccode, 0)) FROM dbo.subaccounts), 0) < 100));
  UPDATE dbo._tabmaxkey SET tabmaxkey = 100 WHERE ((tabname = 'CategoryAccounts') AND (coalesce((SELECT max(coalesce(catacccode, 0)) FROM dbo.categoryaccounts), 0) < 100));
  UPDATE dbo._tabmaxkey SET tabmaxkey = 100 WHERE ((tabname = 'VocherCategory') AND (coalesce((SELECT max(coalesce(vochcatcode, 0)) FROM dbo.vochercategory), 0) < 100));
  UPDATE dbo._headertabmaxkey SET tabmaxkey = coalesce((SELECT max(coalesce(s.headerinvno, 0)) FROM dbo.saleledger AS s WHERE (s.headerno = _headertabmaxkey.headercode)), 0) WHERE (module = 1);
  UPDATE dbo._headertabmaxkey SET tabmaxkey = coalesce((SELECT max(coalesce(s.headerinvno, 0)) FROM dbo.srledger AS s WHERE (s.headerno = _headertabmaxkey.headercode)), 0) WHERE (module = 2);
  UPDATE dbo._headertabmaxkey SET tabmaxkey = coalesce((SELECT max(coalesce(s.headerinvno, 0)) FROM dbo.purledger AS s WHERE (s.headerno = _headertabmaxkey.headercode)), 0) WHERE (module = 3);
  UPDATE dbo._headertabmaxkey SET tabmaxkey = coalesce((SELECT max(coalesce(s.headerinvno, 0)) FROM dbo.prledger AS s WHERE (s.headerno = _headertabmaxkey.headercode)), 0) WHERE (module = 4);
  UPDATE dbo._headertabmaxkey SET tabmaxkey = coalesce((SELECT max(coalesce(s.headerinvno, 0)) FROM dbo.issueheader AS s WHERE (s.headerno = _headertabmaxkey.headercode)), 0) WHERE (module = 5);
  UPDATE dbo._headertabmaxkey SET tabmaxkey = coalesce((SELECT max(coalesce(s.headerinvno, 0)) FROM dbo.receiptheader AS s WHERE (s.headerno = _headertabmaxkey.headercode)), 0) WHERE (module = 6);
  UPDATE dbo._headertabmaxkey SET tabmaxkey = coalesce((SELECT max(coalesce(s.headerinvno, 0)) FROM dbo.adjheader AS s WHERE (s.headerno = _headertabmaxkey.headercode)), 0) WHERE (module = 7);
  UPDATE dbo._headertabmaxkey SET tabmaxkey = coalesce((SELECT max(coalesce(s.headerinvno, 0)) FROM dbo.theader AS s WHERE (s.headerno = _headertabmaxkey.headercode)), 0) WHERE (module = 8);
  UPDATE dbo._headertabmaxkey SET tabmaxkey = coalesce((SELECT max(coalesce(s.headerinvno, 0)) FROM dbo.saleorderheader AS s WHERE (s.headerno = _headertabmaxkey.headercode)), 0) WHERE (module = 12);
  UPDATE dbo._headertabmaxkey SET tabmaxkey = 0 WHERE (module = 15);
  UPDATE dbo._headertabmaxkey SET tabmaxkey = coalesce((SELECT max(coalesce(s.headerinvno, 0)) FROM dbo.advsaleledger AS s WHERE (s.headerno = _headertabmaxkey.headercode)), 0) WHERE (module = 21);
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_InitializeServiceTicketing ====
CREATE OR REPLACE FUNCTION dbo.sp_initializeserviceticketing(serviceticketcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_serviceticketcode integer;
  v_totrows integer;
  v_errcode integer;
  v_errortext citext;
BEGIN
  v_serviceticketcode := serviceticketcode;
  -- SET NOCOUNT ON
  IF ((v_serviceticketcode IS NULL) OR (v_serviceticketcode < 0)) THEN
    v_serviceticketcode := 0;
  END IF;
  DELETE FROM dbo.serviceticket;
  IF (0 <> 0) THEN
    v_errortext := 'Problem while Deleting Service Ticketing Information....';
    RAISE EXCEPTION '%', v_errortext;
    return_value := -1;
    RETURN;
  END IF;
  UPDATE dbo._tabmaxkey SET tabmaxkey = coalesce(v_serviceticketcode, 0) WHERE (tabname = 'ServiceTicket');
  IF (0 <> 0) THEN
    v_errortext := ('Problem while updating Starting Service Ticket No. ' || ltrim(rtrim(dbo.tsql_str((v_serviceticketcode)::numeric, 10))));
    RAISE EXCEPTION '%', v_errortext;
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_InPatientBalance ====
CREATE OR REPLACE FUNCTION dbo.sp_inpatientbalance(admissioncode integer, INOUT balance numeric, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_admissioncode integer;
  v_balance numeric(15,2);
BEGIN
  v_admissioncode := admissioncode;
  v_balance := balance;
  PERFORM dbo.sp_virtualgl(ac_type => 'A');
  v_balance := coalesce((SELECT sum((v.debit - v.credit)) AS balance FROM dbo.virtualgl AS v, dbo.accounts AS a WHERE (((v.patientcode IN (SELECT p.patientcode FROM dbo.patientadmission AS p WHERE (p.admissioncode = v_admissioncode))) AND (v.acccode = a.acccode)) AND (v.acccode IN (SELECT acccode FROM dbo.accounts WHERE (subcode = 3))))), 0);
  return_value := 0;
  balance := v_balance;
  RETURN;
END
$body$;

-- ==== proc SP_Insert_CashierActivity ====
CREATE OR REPLACE FUNCTION dbo.sp_insert_cashieractivity(moduleid smallint, doccode integer, catcode smallint, category citext, acccode smallint, usercode smallint, machinename citext, headerno smallint, headerinvno integer, amount numeric, cashacccode smallint, cashtendered numeric, cashcharged numeric, cashback numeric, remarks citext, cashierjobcode integer, printed citext, supervised citext, INOUT rowid integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_moduleid smallint;
  v_doccode integer;
  v_catcode smallint;
  v_category citext;
  v_acccode smallint;
  v_usercode smallint;
  v_machinename citext;
  v_headerno smallint;
  v_headerinvno integer;
  v_amount numeric(15,2);
  v_cashacccode smallint;
  v_cashtendered numeric(15,2);
  v_cashcharged numeric(15,2);
  v_cashback numeric(15,2);
  v_remarks citext;
  v_cashierjobcode integer;
  v_printed citext;
  v_supervised citext;
  v_rowid integer;
  v_rowsaffected integer;
  v_err integer;
  v_retcode integer;
  v_errcode integer;
  v_ai_dr_acccode integer;
  v_ai_cr_acccode integer;
  v_glvochcode integer;
  v_vochcode integer;
  v_newdoccode integer;
  v_ai_vochcatcode smallint;
  v_ai_salesmancode smallint;
  v_ad_date timestamp(3);
  v_ai_posted citext;
  v_as_chkno citext;
  _rc integer;
BEGIN
  v_moduleid := moduleid;
  v_doccode := doccode;
  v_catcode := catcode;
  v_category := category;
  v_acccode := acccode;
  v_usercode := usercode;
  v_machinename := machinename;
  v_headerno := headerno;
  v_headerinvno := headerinvno;
  v_amount := amount;
  v_cashacccode := cashacccode;
  v_cashtendered := cashtendered;
  v_cashcharged := cashcharged;
  v_cashback := cashback;
  v_remarks := remarks;
  v_cashierjobcode := cashierjobcode;
  v_printed := printed;
  v_supervised := supervised;
  v_rowid := rowid;
  v_ai_salesmancode := (SELECT jobowner FROM dbo.cashierjob WHERE (cashierjobcode = v_cashierjobcode));
  _rc := 1;
  v_retcode := -1;
  _rc := 1;
  v_newdoccode := v_doccode;
  _rc := 1;
  IF (v_newdoccode = 0) THEN
    v_newdoccode := NULL;
    _rc := 1;
  END IF;
  IF (v_moduleid > 100) THEN
    INSERT INTO dbo.cashieractivity (date, moduleid, doccode, catcode, category, acccode, usercode, machinename, headerno, headerinvno, amount, cashacccode, cashtendered, cashcharged, cashback, remarks, cashierjobcode, printed, supervised, supervisedon, glvochcode) SELECT localtimestamp(3) AS date, v_moduleid, v_doccode, v_catcode, v_category, v_acccode, v_usercode, v_machinename, v_headerno, v_headerinvno, v_amount, v_cashacccode, v_cashtendered, v_cashcharged, v_cashback, v_remarks, v_cashierjobcode, v_printed, v_supervised, localtimestamp(3), NULL::integer AS glvochcode;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_rowsaffected := _rc;
    v_err := 0;
    _rc := 1;
    IF ((v_rowsaffected = 0) AND (v_err <> 0)) THEN
      RAISE EXCEPTION 'Unable to Insert Cashier Activity Row Doc. Code: %', v_doccode;
      return_value := -1;
      rowid := v_rowid;
      RETURN;
    END IF;
    v_rowid := (SELECT max(rowid) FROM dbo.cashieractivity WHERE ((moduleid = v_moduleid) AND (doccode = v_doccode)));
    _rc := 1;
    IF (v_rowid > 0) THEN
      v_ai_vochcatcode := CASE v_moduleid WHEN 101 THEN 2 WHEN 102 THEN 12 WHEN 103 THEN 1 ELSE 15 END;
      _rc := 1;
      v_ad_date := localtimestamp(3);
      _rc := 1;
      v_as_chkno := (SELECT (v_doccode)::text);
      _rc := 1;
      v_ai_dr_acccode := CASE v_moduleid WHEN 101 THEN v_cashacccode WHEN 102 THEN v_cashacccode WHEN 103 THEN v_acccode ELSE v_acccode END;
      _rc := 1;
      v_ai_cr_acccode := CASE v_moduleid WHEN 101 THEN v_acccode WHEN 102 THEN v_acccode WHEN 103 THEN v_cashacccode ELSE v_cashacccode END;
      _rc := 1;
      SELECT r.return_value, r.glvochcode, r.vochcode INTO v_err, v_glvochcode, v_vochcode FROM dbo.sp_createvoucher(ai_vochcatcode => (v_ai_vochcatcode)::integer, ai_acccode => (v_cashacccode)::integer, ad_date => v_ad_date, ai_salesmancode => (v_ai_salesmancode)::integer, as_posted => 'Y', ad_postdate => v_ad_date, as_remarks => v_remarks, ad_originaldate => v_ad_date, ai_modifiedby => (v_ai_salesmancode)::integer, ai_postedby => (v_ai_salesmancode)::integer, as_chkno => v_as_chkno, ai_dr_acccode => v_ai_dr_acccode, ai_cr_acccode => v_ai_cr_acccode, an_amount => v_cashcharged, as_chkno_detail => '', as_remarks_detail => v_remarks, ai_patientcode => NULL, ai_guestcode => NULL, ai_studentcode => NULL, ai_invoicecode => v_doccode, an_outstandingamt => (0)::numeric, an_balance => (0)::numeric, glvochcode => v_glvochcode, vochcode => v_vochcode) AS r;
      IF ((0 <> 0) OR (v_err <> 0)) THEN
        RAISE EXCEPTION 'Problem Creating Voucher Against Document Code = %', v_doccode;
        return_value := -1;
        rowid := v_rowid;
        RETURN;
      END IF;
      UPDATE dbo.cashieractivity SET glvochcode = v_glvochcode WHERE (rowid = v_rowid);
      GET DIAGNOSTICS _rc = ROW_COUNT;
      v_retcode := 0;
      _rc := 1;
    END IF;
  END IF;
  return_value := v_retcode;
  rowid := v_rowid;
  RETURN;
  return_value := 0;
  rowid := v_rowid;
  RETURN;
END
$body$;

-- ==== proc SP_Insert_EventLog ====
CREATE OR REPLACE FUNCTION dbo.sp_insert_eventlog(eventtype citext, module citext, detail citext, usercode smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_eventtype citext;
  v_module citext;
  v_detail citext;
  v_usercode smallint;
  _rc integer;
BEGIN
  v_eventtype := eventtype;
  v_module := module;
  v_detail := detail;
  v_usercode := usercode;
  INSERT INTO dbo.eventlog (date, eventtype, module, detail, usercode) SELECT localtimestamp(3) AS date, v_eventtype AS eventtype, v_module AS module, v_detail AS detail, v_usercode AS usercode;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((_rc = 0) AND (0 <> 0)) THEN
    RAISE EXCEPTION 'Unable to Insert EventLog.';
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_Insert_PostedInvoiceEditingLog ====
CREATE OR REPLACE FUNCTION dbo.sp_insert_postedinvoiceeditinglog(doctype citext, documentcode integer, machine citext, usercode smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
