    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_InsertBasicData ====
CREATE OR REPLACE FUNCTION dbo.sp_insertbasicdata(srv citext, db citext, owner citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_ins citext;
  v_sql citext;
  v_qry citext;
  v_tablename citext;
  v_list citext;
  v_from citext;
  v_endd citext;
  v_con citext;
  v_notin citext;
  v_pkcond citext;
  v_whrtbm citext;
  v_full_table_name citext;
  v_colname citext;
  v_maxcol citext;
  v_tabmaxsql citext;
  v_priority smallint;
  v_keyseq smallint;
  v_table_id integer;
  v_err integer;
  v_updmaxkey citext;
  cur_ins1 refcursor;
  cur_ins2 refcursor;
  _dq1 text;
  _dq2 text;
  _fs integer := -1;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  -- SET NOCOUNT ON
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  v_ins := 'INSERT INTO ';
  v_sql := 'SELECT ';
  v_from := ((((((' FROM ' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.');
  v_endd := ' AS T WHERE ';
  v_con := 'CONVERT(VarChar(10),';
  v_notin := ' NOT IN (SELECT ';
  OPEN cur_ins1 FOR SELECT ltrim(rtrim(tablename)) AS tablename, priority, updatetabmaxkey FROM dbo.transferabledata WHERE ((enable = 'Y') AND (autoinsert = 'Y')) ORDER BY priority;
  FETCH NEXT FROM cur_ins1 INTO v_tablename, v_priority, v_updmaxkey;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    v_pkcond := '';
    v_maxcol := '';
    v_full_table_name := ((ltrim(rtrim(v_owner)) || '.') || v_tablename);
    -- SET @table_id = OBJECT_ID(@full_table_name)
    RAISE EXCEPTION 'untranslated T-SQL (OBJECT_ID of non-literal)' USING ERRCODE = '0A000';
    v_err := 0;
    IF ((v_err <> 0) OR (v_table_id IS NULL)) THEN
      RAISE EXCEPTION 'Data Insertion: Invalid Object Refered: Name = %', v_full_table_name;
      CLOSE cur_ins1;
      -- DEALLOCATE Ins1
      return_value := -1;
      RETURN;
    END IF;
    -- OPEN Ins2
    RAISE EXCEPTION 'untranslated T-SQL (system table sysindexes)' USING ERRCODE = '0A000';
    FETCH NEXT FROM cur_ins2 INTO v_colname, v_keyseq;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    WHILE (_fs = 0) LOOP
      IF (v_pkcond <> '') THEN
        v_pkcond := (v_pkcond || ' + ');
      END IF;
      v_pkcond := ((((v_pkcond || ' ') || v_con) || ltrim(rtrim(v_colname))) || ')');
      v_maxcol := (('MAX(' || rtrim(ltrim(v_colname))) || ')');
      FETCH NEXT FROM cur_ins2 INTO v_colname, v_keyseq;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    END LOOP;
    CLOSE cur_ins2;
    -- DEALLOCATE Ins2
    v_sql := ' SELECT ';
    v_list := '';
    SELECT r.return_value, r.list INTO v_err, v_list FROM dbo.sp_columnlist(owner => v_owner, "table" => v_tablename, list => v_list) AS r;
    v_err := 0;
    IF ((0 <> 0) OR (v_err <> 0)) THEN
      CLOSE cur_ins1;
      -- DEALLOCATE Ins1
      return_value := -1;
      RETURN;
    END IF;
    IF (v_tablename = 'GroupRights') THEN
      v_qry := (((((((((((((((v_ins || v_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_list) || v_from) || v_tablename) || v_endd) || v_pkcond) || v_notin) || v_pkcond) || ' FROM ') || v_tablename) || ') AND T.RightCode IN (SELECT DISTINCT R.RightCode FROM Rights R)');
    ELSE
      IF (v_tablename = 'Item') THEN
        v_list := replace((v_list)::citext, ('UserCode,')::citext, ('')::citext);
        v_qry := (((((((((((((((v_ins || v_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_list) || v_from) || v_tablename) || v_endd) || v_pkcond) || v_notin) || v_pkcond) || ' FROM ') || v_tablename) || ')');
      ELSE
        v_qry := (((((((((((((((v_ins || v_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_list) || v_from) || v_tablename) || v_endd) || v_pkcond) || v_notin) || v_pkcond) || ' FROM ') || v_tablename) || ')');
      END IF;
    END IF;
    _dq1 := v_qry;
    IF _dq1 IS NOT NULL THEN
      EXECUTE dbo.tsql_dyn(_dq1);
    END IF;
    v_err := 0;
    IF ((0 <> 0) OR (v_err <> 0)) THEN
      RAISE EXCEPTION 'Data Insertion: Error Transfering % Data', v_full_table_name;
      CLOSE cur_ins1;
      -- DEALLOCATE Ins1
      return_value := -1;
      RETURN;
    END IF;
    IF (v_updmaxkey = 'Y') THEN
      v_tabmaxsql := '';
      v_tabmaxsql := (((((((('UPDATE _tabmaxkey SET TABMAXKEY = ' || ' COALESCE((SELECT ') || v_maxcol) || ' FROM  ') || rtrim(ltrim(v_tablename))) || '), 0) ') || 'WHERE TABNAME = ''') || rtrim(ltrim(v_tablename))) || '''');
      _dq2 := v_tabmaxsql;
      IF _dq2 IS NOT NULL THEN
        EXECUTE dbo.tsql_dyn(_dq2);
      END IF;
      v_err := 0;
      IF ((0 <> 0) OR (v_err <> 0)) THEN
        RAISE EXCEPTION 'Data Insertion: Error While Updating the TABMAXKEY of % ', v_full_table_name;
        CLOSE cur_ins1;
        -- DEALLOCATE Ins1
        return_value := -1;
        RETURN;
      END IF;
    END IF;
    FETCH NEXT FROM cur_ins1 INTO v_tablename, v_priority, v_updmaxkey;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_ins1;
  -- DEALLOCATE Ins1
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

