-- ==== proc SP_InsertBasicData_To_DataCarryDB ====
CREATE OR REPLACE FUNCTION dbo.sp_insertbasicdata_to_datacarrydb(srv citext, db citext, owner citext, custcode smallint, exportitemchangessince timestamp, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
