BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  v_custcode := custcode;
  v_exportitemchangessince := exportitemchangessince;
  -- SET NOCOUNT ON
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  v_itemtimestamp := coalesce((SELECT left(to_char(v_exportitemchangessince, 'YYYY-MM-DD HH24:MI:SS.MS'), 100)), '1990-01-01 00:00:00');
  v_ins := (((((('INSERT INTO ' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.');
  v_sql := 'SELECT ';
  v_from := ' FROM ';
  v_endd := ' AS T ';
  v_con := 'CONVERT(VarChar(10),';
  v_notin := ' NOT IN (SELECT ';
  OPEN cur_ins1 FOR SELECT ltrim(rtrim(tablename)) AS tablename, priority, updatetabmaxkey FROM dbo.transferabledata WHERE ((enable = 'Y') AND (autoinsert = 'Y')) ORDER BY priority;
