  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    v_pkcond := '';
    v_maxcol := '';
    v_full_table_name := v_tablename;
    -- SET @table_id = OBJECT_ID(@full_table_name)
    RAISE EXCEPTION 'untranslated T-SQL (OBJECT_ID of non-literal)' USING ERRCODE = '0A000';
    v_err := 0;
    IF ((v_err <> 0) OR (v_table_id IS NULL)) THEN
      RAISE EXCEPTION 'Data Insertion: Invalid Object Refered: Name = %', v_full_table_name;
      CLOSE cur_ins1;
      -- DEALLOCATE Ins1
      return_value := -1;
      RETURN;
    END IF;
    -- OPEN Ins2
    RAISE EXCEPTION 'untranslated T-SQL (system table sysindexes)' USING ERRCODE = '0A000';
    FETCH NEXT FROM cur_ins2 INTO v_colname, v_keyseq;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    WHILE (_fs = 0) LOOP
      IF (v_pkcond <> '') THEN
        v_pkcond := (v_pkcond || ' + ');
      END IF;
      v_pkcond := ((((v_pkcond || ' ') || v_con) || ltrim(rtrim(v_colname))) || ')');
      v_maxcol := (('MAX(' || rtrim(ltrim(v_colname))) || ')');
      FETCH NEXT FROM cur_ins2 INTO v_colname, v_keyseq;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    END LOOP;
    CLOSE cur_ins2;
    -- DEALLOCATE Ins2
    v_sql := ' SELECT ';
    v_list := '';
    SELECT r.return_value, r.list INTO v_err, v_list FROM dbo.sp_columnlist(owner => 'dbo', "table" => v_tablename, list => v_list) AS r;
    v_err := 0;
    IF ((0 <> 0) OR (v_err <> 0)) THEN
      CLOSE cur_ins1;
      -- DEALLOCATE Ins1
      return_value := -1;
      RETURN;
    END IF;
    v_sourcelist := v_list;
    IF ((lower(v_tablename))::citext = 'service') THEN
      v_sourcelist := replace((v_sourcelist)::citext, ('Description,')::citext, ((v_colname || 'Description=LEFT(Description,255),'))::citext);
    END IF;
    IF ((lower(v_tablename))::citext = 'servicecomponent') THEN
      v_sourcelist := replace((v_sourcelist)::citext, ('RefDescription,')::citext, ((v_colname || 'RefDescription=LEFT(RefDescription,255),'))::citext);
    END IF;
    IF ((lower(v_tablename))::citext = 'customer') THEN
      v_sourcelist := replace((v_sourcelist)::citext, ('SpecialInstructions,')::citext, ((v_colname || 'SpecialInstructions=LEFT(SpecialInstructions,255),'))::citext);
    END IF;
    IF ((lower(v_tablename))::citext = 'supplier') THEN
      v_sourcelist := replace((v_sourcelist)::citext, ('SpecialInstructions,')::citext, ((v_colname || 'SpecialInstructions=LEFT(SpecialInstructions,255),'))::citext);
    END IF;
    -- OPEN Ins3
    RAISE EXCEPTION 'untranslated T-SQL (system table sysobjects)' USING ERRCODE = '0A000';
    FETCH NEXT FROM cur_ins3 INTO v_colname, v_position;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    WHILE (_fs = 0) LOOP
      -- IF ColumnProperty (@table_id, @ColName, 'IsIdentity') <> 1
      -- 		BEGIN
      -- 			IF @ColName = (SELECT columnname FROM TransferableData_ExportRestrictedColumns WHERE columnname = @ColName and tablename = @TableName)
      -- 			BEGIN
      -- 				SET @SOURCELIST = REPLACE(@SOURCELIST,@ColName+',',@ColName+'=0,')
      -- 			END
      -- 		END
      RAISE EXCEPTION 'untranslated T-SQL (function ColumnProperty)' USING ERRCODE = '0A000';
      FETCH NEXT FROM cur_ins3 INTO v_colname, v_position;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    END LOOP;
    CLOSE cur_ins3;
    -- DEALLOCATE Ins3
    IF ((right(v_sourcelist, 1))::citext = ',') THEN
      v_sourcelist := left(v_sourcelist, (length(rtrim(v_sourcelist)) - 1));
    END IF;
    IF ((lower(v_tablename))::citext = 'item') THEN
      v_qry := ((((((((((((v_ins || v_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_sourcelist) || v_from) || v_tablename) || v_endd) || ' WHERE T.LASTUPDATE >= ''') || v_itemtimestamp) || '''');
    ELSE
      v_qry := (((((((((v_ins || v_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_sourcelist) || v_from) || v_tablename) || v_endd);
    END IF;
    IF (((lower(v_tablename))::citext = 'item') AND (v_custcode > 0)) THEN
      v_qry := (((v_qry || ' AND T.ICatCode IN (SELECT DISTINCT CI.ICatCode FROM DBO.CustWiseItemCategory CI WHERE CI.CustCode = ') || ltrim(rtrim(dbo.tsql_str((v_custcode)::numeric, 7)))) || ') ');
    END IF;
    IF (((lower(v_tablename))::citext = 'itemsuppliers') AND (v_custcode > 0)) THEN
      v_qry := (((v_qry || ' WHERE T.ICode IN (SELECT DISTINCT I.ICode FROM DBO.CustWiseItemCategory CI, Item I WHERE CI.CustCode = ') || ltrim(rtrim(dbo.tsql_str((v_custcode)::numeric, 7)))) || ' AND CI.ICatCode = I.ICatCode) ');
    END IF;
    IF (((lower(v_tablename))::citext = 'item') OR ((lower(v_tablename))::citext = 'itemsuppliers')) THEN
      v_srow := 0;
      v_lrow := 50000;
      WHILE (v_srow <= 2000000) LOOP
        IF (v_custcode > 0) THEN
          v_icodestr := (((' AND T.ICode BETWEEN ' || ltrim(rtrim(dbo.tsql_str((v_srow)::numeric)))) || ' AND ') || ltrim(rtrim(dbo.tsql_str((v_lrow)::numeric))));
        ELSE
          IF ((lower(v_tablename))::citext = 'itemsuppliers') THEN
            v_icodestr := (((' WHERE T.ICode BETWEEN ' || ltrim(rtrim(dbo.tsql_str((v_srow)::numeric)))) || ' AND ') || ltrim(rtrim(dbo.tsql_str((v_lrow)::numeric))));
          ELSE
            v_icodestr := (((' AND T.ICode BETWEEN ' || ltrim(rtrim(dbo.tsql_str((v_srow)::numeric)))) || ' AND ') || ltrim(rtrim(dbo.tsql_str((v_lrow)::numeric))));
          END IF;
        END IF;
        v_iqry := (v_qry || v_icodestr);
        _dq1 := v_iqry;
        IF _dq1 IS NOT NULL THEN
          EXECUTE dbo.tsql_dyn(_dq1);
        END IF;
        v_err := 0;
        IF ((0 <> 0) OR (v_err <> 0)) THEN
          RAISE EXCEPTION 'Data Insertion: Error Transfering % Data', v_full_table_name;
          CLOSE cur_ins1;
          -- DEALLOCATE Ins1
          return_value := -1;
          RETURN;
        END IF;
        IF ((lower(v_tablename))::citext = 'item') THEN
          v_iqry := (((((((((('Update ' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.') || 'Item Set UserCode=1 , ISizeCode=1, IStyleCode=1, IColourCode=1, ISleeveCode=1, IYarnCode=1, IFabricCode=1, IBrandCode=1, IPartCode=1 WHERE ICode BETWEEN ') || ltrim(rtrim(dbo.tsql_str((v_srow)::numeric)))) || ' AND ') || ltrim(rtrim(dbo.tsql_str((v_lrow)::numeric))));
          _dq2 := v_iqry;
          IF _dq2 IS NOT NULL THEN
            EXECUTE dbo.tsql_dyn(_dq2);
          END IF;
          IF (0 <> 0) THEN
            RAISE EXCEPTION 'Updation Problem of Default Values In DataCarryDB';
            return_value := -1;
            RETURN;
          END IF;
        END IF;
        v_srow := (v_lrow + 1);
        v_lrow := (v_lrow + 50000);
      END LOOP;
    ELSE
      _dq3 := v_qry;
      IF _dq3 IS NOT NULL THEN
        EXECUTE dbo.tsql_dyn(_dq3);
      END IF;
      v_err := 0;
      IF ((0 <> 0) OR (v_err <> 0)) THEN
        RAISE EXCEPTION 'Data Insertion: Error Transfering % Data', v_full_table_name;
        CLOSE cur_ins1;
        -- DEALLOCATE Ins1
        return_value := -1;
        RETURN;
      END IF;
    END IF;
    FETCH NEXT FROM cur_ins1 INTO v_tablename, v_priority, v_updmaxkey;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_ins1;
  -- DEALLOCATE Ins1
  v_qry := ((((((('Delete From ' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.') || 'DataImportlog ');
  _dq4 := v_qry;
  IF _dq4 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq4);
  END IF;
  IF (0 <> 0) THEN
    RAISE EXCEPTION 'Problem Initializing Data Import Log in DataCarryDB';
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

