    v_query := (v_query || ' From 	ExpiryIntimationDetail ');
    v_query := (((((((((((v_query || ' Where   IntimationCode Between ') || (v_scode)::text) || ' And ') || (v_lcode)::text) || ' AND IntimationCode IN (SELECT IntimationCode FROM ExpiryIntimation WHERE IntimationTypeCode = ') || (v_type)::text) || ' AND IntimationCode Between ') || (v_scode)::text) || ' And ') || (v_lcode)::text) || ') ');
    v_query := (v_query || ' ORDER BY RowID ');
    _dq2 := v_query;
    IF _dq2 IS NOT NULL THEN
      IF _dq2 ~* '^[[:space:]]*select' THEN OPEN rs2 FOR EXECUTE dbo.tsql_dyn(_dq2); ELSE EXECUTE dbo.tsql_dyn(_dq2); END IF;
    END IF;
    IF (0 <> 0) THEN
      RAISE EXCEPTION 'Problem in inserting detail records of Expiry Intimation to Remote DataBase';
      return_value := -1;
      RETURN;
    END IF;
  ELSE
    RAISE EXCEPTION 'Problem in inserting header records of Expiry Intimation to Remote DataBase';
    return_value := -1;
    RETURN;
  END IF;
  return_value := 1;
  RETURN;
  return_value := 0;
  RETURN;
