CREATE OR REPLACE FUNCTION dbo.sp_insertpr_to_datacarrydb(srv citext, db citext, owner citext, sprcode integer, lprcode integer, OUT return_value integer, OUT rs1 refcursor, OUT rs2 refcursor)
