    v_query := (v_query || 'Select 	SaleOrdercode, ICode, GCode, LooseQty, PackUnits, SalePrice, AvgPrice, Rate, DiscPerc, RowID, itemflatdisc, SaleItemDescription, PackPrice, UnitSalesTax, GSTPerc, bonusqty, RowGroup ');
    _rc := 1;
    v_query := (v_query || 'From  	SaleOrderDetail ');
    _rc := 1;
    v_query := ((((v_query || 'Where   Saleordercode Between ') || (v_ssocode)::text) || ' And ') || (v_lsocode)::text);
    _rc := 1;
    IF (v_custcode > 0) THEN
      v_query := (((v_query || ' AND Saleordercode IN (SELECT Saleordercode FROM SaleOrderHeader WHERE CustCode = ') || (v_custcode)::text) || ') ');
      _rc := 1;
    END IF;
    _dq2 := v_query;
    IF _dq2 IS NOT NULL THEN
      IF _dq2 ~* '^[[:space:]]*select' THEN OPEN rs2 FOR EXECUTE dbo.tsql_dyn(_dq2); ELSE EXECUTE dbo.tsql_dyn(_dq2); END IF;
    END IF;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF (0 <> 0) THEN
      RAISE EXCEPTION 'Problem in inserting detail records to Remote DataBase';
      return_value := -1;
      RETURN;
    END IF;
  ELSE
    IF ((_rc = 0) AND (0 = 0)) THEN
      return_value := 1;
      RETURN;
    ELSE
      RAISE EXCEPTION 'Problem in inserting header records to Remote DataBase';
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  return_value := 1;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_IsActiveItem ====
CREATE OR REPLACE FUNCTION dbo.sp_isactiveitem(icode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_icode integer;
  v_active smallint;
BEGIN
  v_icode := icode;
  IF (v_icode IS NULL) THEN
    RAISE EXCEPTION 'Unable to fetch Item Active Y/N Status, Not a valid item ';
    return_value := -1;
    RETURN;
  END IF;
  v_active := (SELECT active FROM dbo.item WHERE (icode = v_icode));
  IF (v_active IS NULL) THEN
    RAISE EXCEPTION 'Unable to fetch Item Status for Active Y/N Item Code = %', v_icode;
    return_value := -1;
    RETURN;
  END IF;
  return_value := v_active;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_IsAllowedCustomerGroupCategory ====
CREATE OR REPLACE FUNCTION dbo.sp_isallowedcustomergroupcategory(groupcode integer, custcode integer, INOUT allowed integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_groupcode integer;
  v_custcode integer;
  v_allowed integer;
BEGIN
  v_groupcode := groupcode;
  v_custcode := custcode;
  v_allowed := allowed;
  SELECT count(*) INTO v_allowed FROM dbo.customer WHERE ((custcatcode IN (SELECT customercategorycode FROM dbo.customergroupcategory WHERE (groupcode = v_groupcode))) AND (custcode = v_custcode));
  return_value := 0;
  allowed := v_allowed;
  RETURN;
END
$body$;

-- ==== proc sp_IssueInvList_From_DropBox ====
CREATE OR REPLACE FUNCTION dbo.sp_issueinvlist_from_dropbox(srv citext, db citext, owner citext, sitecode integer, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_sitecode integer;
  v_query citext;
  v_prefix citext;
  _dq1 text;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  v_sitecode := sitecode;
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  v_prefix := '';
  IF (((length(rtrim(ltrim(rtrim(v_srv)))) = 0) OR (v_srv IS NULL))) THEN
    v_prefix := '';
  ELSE
    v_prefix := (v_srv || '.');
  END IF;
  IF (((length(rtrim(ltrim(rtrim(v_db)))) = 0) OR (v_db IS NULL))) THEN
    v_prefix := v_prefix;
  ELSE
    v_prefix := ((v_prefix || v_db) || '.');
  END IF;
  IF (((length(rtrim(ltrim(rtrim(v_owner)))) = 0) OR (v_owner IS NULL))) THEN
    v_prefix := ((v_prefix || 'DBO') || '.');
  ELSE
    v_prefix := ((v_prefix || v_owner) || '.');
  END IF;
  v_query := (((('Select SiteCode, Site=(SELECT Site.Name + SPACE(1) + CHAR(45) + SPACE(1) + InstanceID FROM Site WHERE Site.Sitecode = T.SiteCode), T.IssueInvCode, T.Date, T.Remarks From ' || v_prefix) || 'DB_IssueHeader AS T WHERE T.TargetSiteCode = ') || ltrim(rtrim(dbo.tsql_str((v_sitecode)::numeric)))) || ' AND T.Pulled = ''N''');
  _dq1 := v_query;
  IF _dq1 IS NOT NULL THEN
    IF _dq1 ~* '^[[:space:]]*select' THEN OPEN rs1 FOR EXECUTE dbo.tsql_dyn(_dq1); ELSE EXECUTE dbo.tsql_dyn(_dq1); END IF;
  END IF;
  return_value := 1;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_itemactivity ====
CREATE OR REPLACE FUNCTION dbo.sp_itemactivity(s_date timestamp, l_date timestamp, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_s_date timestamp(3);
  v_l_date timestamp(3);
BEGIN
  v_s_date := s_date;
  v_l_date := l_date;
  DELETE FROM dbo.reportdata;
  INSERT INTO dbo.reportdata (code10, code11, name1, name2, code1, value1, code2, value2, code3, value3, code4, value4, code5, value5, code6, value6, code7, value7, code8, value8, code9, value9) SELECT a.icode, a.icatcode AS icatcode, a.name AS itemname, a.customicode AS aliasname, coalesce((SELECT sum((saledetail.looseqty + saledetail.bonusqty)) FROM dbo.saledetail, dbo.saleledger WHERE ((((saleledger.date BETWEEN v_s_date AND v_l_date) AND (saleledger.saleinvcode = saledetail.saleinvcode)) AND (saledetail.due IS NULL)) AND (saledetail.icode = a.icode))), 0) AS saleqty, coalesce((SELECT sum((((saledetail.looseqty + saledetail.bonusqty)) * rate)) FROM dbo.saledetail, dbo.saleledger WHERE ((((saleledger.date BETWEEN v_s_date AND v_l_date) AND (saleledger.saleinvcode = saledetail.saleinvcode)) AND (saledetail.due IS NULL)) AND (saledetail.icode = a.icode))), 0) AS salevalues, coalesce((SELECT sum(duesatisfydetail.duesatisfyqty) FROM dbo.duesatisfydetail, dbo.duesatisfyheader WHERE (((duesatisfyheader.duesatisfydate BETWEEN v_s_date AND v_l_date) AND (duesatisfyheader.duesatisfycode = duesatisfydetail.duesatisfycode)) AND (duesatisfydetail.icode = a.icode))), 0) AS satisfyqty, coalesce((SELECT sum((duesatisfydetail.duesatisfyqty * ((packsaleprice / packunits)))) FROM dbo.duesatisfydetail, dbo.duesatisfyheader WHERE (((duesatisfyheader.duesatisfydate BETWEEN v_s_date AND v_l_date) AND (duesatisfyheader.duesatisfycode = duesatisfydetail.duesatisfycode)) AND (duesatisfydetail.icode = a.icode))), 0) AS satisfyvalue, coalesce((SELECT sum((srdetail.looseqty + srdetail.bonusqty)) FROM dbo.srdetail, dbo.srledger WHERE (((srledger.date BETWEEN v_s_date AND v_l_date) AND (srledger.srinvcode = srdetail.srinvcode)) AND (srdetail.icode = a.icode))), 0) AS saleretqty, coalesce((SELECT sum((((srdetail.looseqty + srdetail.bonusqty)) * saleprice)) FROM dbo.srdetail, dbo.srledger WHERE (((srledger.date BETWEEN v_s_date AND v_l_date) AND (srledger.srinvcode = srdetail.srinvcode)) AND (srdetail.icode = a.icode))), 0) AS saleretvalue, coalesce((SELECT sum(CASE WHEN (purledger.purcatcode IN (3, 7, 8)) THEN (purdetail.looseqty + purdetail.bonusqty) ELSE (((purdetail.packqty + purdetail.bonusqty)) * purdetail.packunits) END) FROM dbo.purdetail, dbo.purledger WHERE ((((purledger.postdate BETWEEN v_s_date AND v_l_date) AND (purledger.posted = 'Y')) AND (purledger.purinvcode = purdetail.purinvcode)) AND (purdetail.icode = a.icode))), 0) AS purqty, coalesce((SELECT sum(CASE WHEN (purledger.purcatcode IN (3, 7, 8)) THEN (((purdetail.looseqty + purdetail.bonusqty)) * ((purdetail.saleprice / purdetail.packunits))) ELSE ((((purdetail.packqty + purdetail.bonusqty)) * ((purdetail.saleprice / purdetail.packunits)))) END) FROM dbo.purdetail, dbo.purledger WHERE ((((purledger.postdate BETWEEN v_s_date AND v_l_date) AND (purledger.posted = 'Y')) AND (purledger.purinvcode = purdetail.purinvcode)) AND (purdetail.icode = a.icode))), 0) AS purvalues, coalesce((SELECT sum((prdetail.looseqty + prdetail.bonusqty)) FROM dbo.prdetail, dbo.prledger WHERE (((prledger.date BETWEEN v_s_date AND v_l_date) AND (prledger.prinvcode = prdetail.prinvcode)) AND (prdetail.icode = a.icode))), 0) AS prqty, coalesce((SELECT sum((((prdetail.looseqty + prdetail.bonusqty)) * ((prdetail.packsaleprice / prdetail.packunits)))) FROM dbo.prdetail, dbo.prledger WHERE (((prledger.date BETWEEN v_s_date AND v_l_date) AND (prledger.prinvcode = prdetail.prinvcode)) AND (prdetail.icode = a.icode))), 0) AS prvalue, coalesce((SELECT sum(adjdetail.looseqty) FROM dbo.adjdetail, dbo.adjheader WHERE ((((adjheader.date BETWEEN v_s_date AND v_l_date) AND (adjcatcode = 1)) AND (adjheader.adjcode = adjdetail.adjcode)) AND (adjdetail.icode = a.icode))), 0) AS adjincqty, coalesce((SELECT sum((adjdetail.looseqty * ((adjdetail.saleprice / adjdetail.packunits)))) FROM dbo.adjdetail, dbo.adjheader WHERE ((((adjheader.date BETWEEN v_s_date AND v_l_date) AND (adjcatcode = 1)) AND (adjheader.adjcode = adjdetail.adjcode)) AND (adjdetail.icode = a.icode))), 0) AS adjincval, coalesce((SELECT sum(adjdetail.looseqty) FROM dbo.adjdetail, dbo.adjheader WHERE ((((adjheader.date BETWEEN v_s_date AND v_l_date) AND (adjcatcode <> 1)) AND (adjheader.adjcode = adjdetail.adjcode)) AND (adjdetail.icode = a.icode))), 0) AS adjdecrqty, coalesce((SELECT sum((adjdetail.looseqty * ((adjdetail.saleprice / adjdetail.packunits)))) FROM dbo.adjdetail, dbo.adjheader WHERE ((((adjheader.date BETWEEN v_s_date AND v_l_date) AND (adjcatcode <> 1)) AND (adjheader.adjcode = adjdetail.adjcode)) AND (adjdetail.icode = a.icode))), 0) AS adjdecrval, coalesce((SELECT sum(issuedetail.qty) FROM dbo.issuedetail, dbo.issueheader WHERE (((issueheader.date BETWEEN v_s_date AND v_l_date) AND (issueheader.issueinvcode = issuedetail.issueinvcode)) AND (issuedetail.icode = a.icode))), 0) AS issueqty, coalesce((SELECT sum((issuedetail.qty * saleprice)) FROM dbo.issuedetail, dbo.issueheader WHERE (((issueheader.date BETWEEN v_s_date AND v_l_date) AND (issueheader.issueinvcode = issuedetail.issueinvcode)) AND (issuedetail.icode = a.icode))), 0) AS issueval, coalesce((SELECT sum(receiptdetail.qty) FROM dbo.receiptdetail, dbo.receiptheader WHERE ((((receiptheader.date BETWEEN v_s_date AND v_l_date) AND (receiptheader.posted = 'Y')) AND (receiptheader.receiptinvcode = receiptdetail.receiptinvcode)) AND (receiptdetail.icode = a.icode))), 0) AS receiptqty, coalesce((SELECT sum((receiptdetail.qty * saleprice)) FROM dbo.receiptdetail, dbo.receiptheader WHERE ((((receiptheader.date BETWEEN v_s_date AND v_l_date) AND (receiptheader.posted = 'Y')) AND (receiptheader.receiptinvcode = receiptdetail.receiptinvcode)) AND (receiptdetail.icode = a.icode))), 0) AS receiptvalue FROM dbo.item AS a WHERE (a.active = 1);
  return_value := 0;
  RETURN;
END
$body$;

