-- ==== proc sp_itemingodowns ====
CREATE OR REPLACE FUNCTION dbo.sp_itemingodowns(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
BEGIN
  DELETE FROM dbo.stockinallgodown;
  INSERT INTO dbo.stockinallgodown SELECT item.customicode, item.name, item.saleprice, item.purprice, item.avgprice, item.packunits, item.iccode, item.icatcode, item.packcode, item.manfcode, (SELECT name FROM dbo.godown WHERE (godown.gcode = i.gcode)) AS godown, coalesce((SELECT sum(currqty) AS currqty FROM dbo.godowndetail WHERE ((godowndetail.icode = i.icode) AND (godowndetail.gcode = i.gcode)) GROUP BY godowndetail.icode, godowndetail.gcode), 0) AS currqty FROM (SELECT i.icode, g.gcode FROM dbo.item AS i, dbo.godown AS g) AS i, dbo.item WHERE (i.icode = item.icode) ORDER BY i.icode, i.gcode;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_ITEMNETSALE_SMANWISE_BREAKUP ====
CREATE OR REPLACE FUNCTION dbo.sp_itemnetsale_smanwise_breakup(ar_startdate timestamp, ar_enddate timestamp, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ar_startdate timestamp(3);
  v_ar_enddate timestamp(3);
BEGIN
  v_ar_startdate := ar_startdate;
  v_ar_enddate := ar_enddate;
  DELETE FROM dbo.reportdata;
  INSERT INTO dbo.reportdata (name1, name2, code1, name3, name4, value1, code2) SELECT sm.name, m.name AS name, i.manfcode AS code, i.customicode AS aliasname, i.name AS itemname, sum(value) AS value, sum(qty) AS qty FROM (SELECT sd.icode, ((ltrim(rtrim((extract(month from date)::integer)::text)) || '-01-') || rtrim(ltrim(to_char(date, 'YYYY')))) AS date, sum(((sd.looseqty + sd.bonusqty) + (sd.packqty * sd.packunits))) AS qty, sum((((((sd.looseqty + (sd.packqty * sd.packunits))) * sd.saleprice) * ((1 - (sd.discperc * 0.01)))) * ((1 - (sl.discperc * 0.01))))) AS value, sl.smancode FROM dbo.saleledger AS sl, dbo.saledetail AS sd WHERE ((((sl.posted = 'Y') AND (sl.saleinvcode = sd.saleinvcode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) GROUP BY sl.smancode, sd.icode, sl.date UNION ALL SELECT sd.icode, ((ltrim(rtrim((extract(month from date)::integer)::text)) || '-01-') || rtrim(ltrim(to_char(date, 'YYYY')))) AS date, (-sum(((sd.looseqty + sd.bonusqty) + (sd.packqty * sd.packunits)))) AS qty, (-sum((((((sd.looseqty + (sd.packqty * sd.packunits))) * sd.srprice) * ((1 - (sd.discperc * 0.01)))) * ((1 - (sl.discperc * 0.01)))))) AS value, sl.smancode FROM dbo.srledger AS sl, dbo.srdetail AS sd WHERE ((((sl.posted = 'Y') AND (sl.srinvcode = sd.srinvcode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) GROUP BY sl.smancode, sd.icode, sl.date) AS st, dbo.item AS i, dbo.manufacturer AS m, dbo.salesman AS sm WHERE (((st.icode = i.icode) AND (i.manfcode = m.manfcode)) AND (sm.salesmancode = st.smancode)) GROUP BY sm.name, st.smancode, m.name, i.manfcode, i.customicode, i.name ORDER BY sm.name, st.smancode, m.name, i.manfcode, i.name, i.customicode;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_ItemOpeningStock ====
CREATE OR REPLACE FUNCTION dbo.sp_itemopeningstock(l_date timestamp, l_gcode integer, l_icode integer, INOUT l_godownqty numeric, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_l_date timestamp(3);
  v_l_gcode integer;
  v_l_icode integer;
  v_l_godownqty numeric(15,4);
  v_l_purqty numeric(15,4);
  v_l_purretqty numeric(15,4);
  v_l_saleqty numeric(15,4);
  v_l_saleretqty numeric(15,4);
  v_l_satisfyqty numeric(15,4);
  v_l_transferqty_increase numeric(15,4);
  v_l_transferqty_decrease numeric(15,4);
  v_l_issueqty numeric(15,4);
  v_l_receiptqty numeric(15,4);
  v_l_adjqty numeric(15,4);
BEGIN
  v_l_date := l_date;
  v_l_gcode := l_gcode;
  v_l_icode := l_icode;
  v_l_godownqty := l_godownqty;
  v_l_purqty := (SELECT coalesce(sum(CASE WHEN (purledger.purcatcode IN (3, 7, 8)) THEN ((purdetail.looseqty + ((purdetail.packqty * purdetail.packunits))) + purdetail.bonusqty) ELSE ((purdetail.looseqty + ((purdetail.packqty * purdetail.packunits))) + ((purdetail.bonusqty * purdetail.packunits))) END), 0) FROM dbo.purledger, dbo.purdetail WHERE ((((purledger.purinvcode = purdetail.purinvcode) AND (purdetail.icode = v_l_icode)) AND (purledger.posted = 'Y')) AND (purledger.postdate < v_l_date)));
  v_l_purretqty := (SELECT coalesce(sum(((prdetail.looseqty + (prdetail.packqty * prdetail.packunits)) + prdetail.bonusqty)), 0) FROM dbo.prledger, dbo.prdetail WHERE (((prledger.prinvcode = prdetail.prinvcode) AND (prdetail.icode = v_l_icode)) AND (prledger.date < v_l_date)));
  v_l_saleqty := (SELECT coalesce(sum(((saledetail.looseqty + saledetail.bonusqty) + (saledetail.packqty * saledetail.packunits))), 0) FROM dbo.saleledger, dbo.saledetail WHERE ((((saleledger.saleinvcode = saledetail.saleinvcode) AND (saledetail.icode = v_l_icode)) AND (saledetail.due IS NULL)) AND (saleledger.date < v_l_date)));
  v_l_saleretqty := (SELECT coalesce(sum(((srdetail.looseqty + srdetail.bonusqty) + (srdetail.packqty * srdetail.packunits))), 0) FROM dbo.srledger, dbo.srdetail WHERE ((((srledger.srinvcode = srdetail.srinvcode) AND (srdetail.icode = v_l_icode)) AND (srledger.posted = 'Y')) AND (srledger.postdate < v_l_date)));
  v_l_satisfyqty := (SELECT coalesce(sum(duesatisfydetail.duesatisfyqty), 0) FROM dbo.duesatisfyheader, dbo.duesatisfydetail WHERE (((duesatisfyheader.duesatisfycode = duesatisfydetail.duesatisfycode) AND (duesatisfydetail.icode = v_l_icode)) AND (duesatisfyheader.duesatisfydate < v_l_date)));
  v_l_transferqty_increase := (SELECT coalesce(sum(tdetail.qty), 0) FROM dbo.theader, dbo.tdetail WHERE ((((theader.transcode = tdetail.transcode) AND (theader.dgcode = v_l_gcode)) AND (tdetail.icode = v_l_icode)) AND (theader.date < v_l_date)));
  v_l_transferqty_decrease := (SELECT coalesce(sum(tdetail.qty), 0) FROM dbo.theader, dbo.tdetail WHERE ((((theader.transcode = tdetail.transcode) AND (theader.sgcode = v_l_gcode)) AND (tdetail.icode = v_l_icode)) AND (theader.date < v_l_date)));
  v_l_issueqty := (SELECT coalesce(sum(issuedetail.qty), 0) FROM dbo.issueheader, dbo.issuedetail WHERE (((issueheader.date < v_l_date) AND (issueheader.issueinvcode = issuedetail.issueinvcode)) AND (issuedetail.icode = v_l_icode)));
  v_l_receiptqty := (SELECT coalesce(sum(receiptdetail.qty), 0) FROM dbo.receiptheader, dbo.receiptdetail WHERE ((((receiptheader.date < v_l_date) AND (receiptheader.receiptinvcode = receiptdetail.receiptinvcode)) AND (receiptdetail.icode = v_l_icode)) AND (receiptheader.posted = 'Y')));
  v_l_adjqty := (SELECT coalesce(sum(CASE adjcatcode WHEN 1 THEN adjdetail.looseqty ELSE (-adjdetail.looseqty) END), 0) FROM dbo.adjheader, dbo.adjdetail WHERE ((((adjheader.date < v_l_date) AND (adjheader.adjcode = adjdetail.adjcode)) AND (adjdetail.icode = v_l_icode)) AND (adjheader.posted = 'Y')));
  v_l_godownqty := (((((((v_l_purqty + v_l_saleretqty) - v_l_issueqty) - v_l_purretqty) - v_l_saleqty) - v_l_satisfyqty) + v_l_receiptqty) + v_l_adjqty);
  OPEN rs1 FOR SELECT v_l_godownqty AS balance, v_l_purqty AS purchase, v_l_saleretqty AS salereturn, v_l_purretqty AS purchasereturn, v_l_saleqty AS sale, v_l_satisfyqty AS satisfy;
  return_value := 0;
  l_godownqty := v_l_godownqty;
  RETURN;
END
$body$;

