-- ==== proc SP_ItemStockMovementAtAvgPrice ====
CREATE OR REPLACE FUNCTION dbo.sp_itemstockmovementatavgprice(ar_startdate timestamp, ar_enddate timestamp, reportgrouping citext, grouplist citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ar_startdate timestamp(3);
  v_ar_enddate timestamp(3);
  v_reportgrouping citext;
  v_grouplist citext;
BEGIN
  v_ar_startdate := ar_startdate;
  v_ar_enddate := ar_enddate;
  v_reportgrouping := reportgrouping;
  v_grouplist := grouplist;
  TRUNCATE TABLE dbo.reportdata;
  DROP TABLE IF EXISTS tv_sp_itemstockmovementatavgprice_tab_itemlist;
  CREATE TEMP TABLE tv_sp_itemstockmovementatavgprice_tab_itemlist (
    code integer NOT NULL
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tv_sp_itemstockmovementatavgprice_tab_avg;
  CREATE TEMP TABLE tv_sp_itemstockmovementatavgprice_tab_avg (
    date timestamp(3),
    icode integer NOT NULL,
    avgprice numeric(15,5)
) ON COMMIT DROP;
  INSERT INTO tv_sp_itemstockmovementatavgprice_tab_itemlist SELECT code FROM dbo.udf_selectitems(v_reportgrouping, v_grouplist) AS udf_selectitems;
