  INSERT INTO dbo.reportdata (code1, name1, name2, code2, name3, name4, code3, code4, code5, value1, value2, value3, value4, value5, value6, value7, value8, value9, value10, value11, value12, value13, value14, value15, value16, value17, value18) SELECT a.icode AS icode, i.customicode AS aliasname, i.name AS item, CASE v_reportgrouping WHEN 'M' THEN i.manfcode WHEN 'C' THEN i.icatcode WHEN 'L' THEN i.iccode ELSE i.packcode END AS code, max(i.packingdesc) AS packingdesc, CASE v_reportgrouping WHEN 'M' THEN m.name WHEN 'C' THEN c.name WHEN 'L' THEN l.name ELSE p.name END AS name, coalesce((SELECT t.avgprice FROM tv_sp_itemstockmovementatavgprice_tab_avg AS t WHERE ((t.icode = a.icode) AND (t.date <= v_ar_startdate)) ORDER BY t.date DESC LIMIT 1), 0) AS oprate, coalesce((SELECT t.avgprice FROM tv_sp_itemstockmovementatavgprice_tab_avg AS t WHERE ((t.icode = a.icode) AND (t.date <= v_ar_enddate)) ORDER BY t.date DESC LIMIT 1), 0) AS clrate, sum(a.openqty) AS openqty, sum(a.purqty) AS purqty, sum(a.purvalue) AS purvalue, sum(a.pretqty) AS pretqty, sum(a.pretvalue) AS pretvalue, sum(a.saleqty) AS saleqty, sum(a.salevalue) AS salevalue, sum(a.sretqty) AS sretqty, sum(a.sretvalue) AS sretvalue, sum(a.issueqty) AS issueqty, sum(a.issuevalue) AS issuevalue, sum(a.duesatisfyqty) AS duesatisfyqty, sum(a.duesatisfyvalue) AS duesatisfyvalue, sum(a.receiptqty) AS receiptqty, sum(a.receiptvalue) AS receiptvalue, sum(a.adjincqty) AS adjincqty, sum(a.adjincvalue) AS adjincvalue, sum(a.adjdecqty) AS adjdecqty, sum(a.adjdecvalue) AS adjdecvalue FROM dbo.item AS i, dbo.manufacturer AS m, dbo.itemcategory AS c, dbo.itemclass AS l, dbo.itempacking AS p, (SELECT icode, sum(CASE WHEN (type = 'OP') THEN qty ELSE 0 END) AS openqty, sum(CASE WHEN (type = 'PV') THEN qty ELSE 0 END) AS purqty, sum(CASE WHEN (type = 'PV') THEN value ELSE 0 END) AS purvalue, sum(CASE WHEN (type = 'PR') THEN qty ELSE 0 END) AS pretqty, sum(CASE WHEN (type = 'PR') THEN value ELSE 0 END) AS pretvalue, sum(CASE WHEN (type = 'SV') THEN qty ELSE 0 END) AS saleqty, sum(CASE WHEN (type = 'SV') THEN value ELSE 0 END) AS salevalue, sum(CASE WHEN (type = 'SR') THEN qty ELSE 0 END) AS sretqty, sum(CASE WHEN (type = 'SR') THEN value ELSE 0 END) AS sretvalue, sum(CASE WHEN (type = 'IV') THEN qty ELSE 0 END) AS issueqty, sum(CASE WHEN (type = 'IV') THEN value ELSE 0 END) AS issuevalue, sum(CASE WHEN (type = 'DS') THEN qty ELSE 0 END) AS duesatisfyqty, sum(CASE WHEN (type = 'DS') THEN value ELSE 0 END) AS duesatisfyvalue, sum(CASE WHEN (type = 'RV') THEN qty ELSE 0 END) AS receiptqty, sum(CASE WHEN (type = 'RV') THEN value ELSE 0 END) AS receiptvalue, sum(CASE WHEN (type = 'AI') THEN qty ELSE 0 END) AS adjincqty, sum(CASE WHEN (type = 'AI') THEN value ELSE 0 END) AS adjincvalue, sum(CASE WHEN (type = 'AD') THEN qty ELSE 0 END) AS adjdecqty, sum(CASE WHEN (type = 'AD') THEN value ELSE 0 END) AS adjdecvalue FROM (SELECT 'OP' AS type, pd.icode, sum(coalesce(CASE pl.purcatcode WHEN 1 THEN (((pd.packqty + pd.bonusqty)) * pd.packunits) WHEN 2 THEN (((pd.packqty + pd.bonusqty)) * pd.packunits) ELSE (pd.looseqty + pd.bonusqty) END, 0)) AS qty, 0 AS value FROM dbo.purledger AS pl, dbo.purdetail AS pd WHERE ((((pl.posted = 'Y') AND (pl.purinvcode = pd.purinvcode)) AND (pl.postdate < v_ar_startdate)) AND (pd.icode IN (SELECT code FROM tv_sp_itemstockmovementatavgprice_tab_itemlist AS tab_itemlist))) GROUP BY pd.icode UNION ALL SELECT 'OP' AS type, pd.icode, (-sum(((pd.looseqty + pd.bonusqty) + (pd.packqty * pd.packunits)))) AS qty, 0 AS value FROM dbo.prledger AS pl, dbo.prdetail AS pd WHERE ((((pl.posted = 'Y') AND (pl.prinvcode = pd.prinvcode)) AND (pl.date < v_ar_startdate)) AND (pd.icode IN (SELECT code FROM tv_sp_itemstockmovementatavgprice_tab_itemlist AS tab_itemlist))) GROUP BY pd.icode UNION ALL SELECT 'OP' AS type, sd.icode, (-sum((sd.looseqty + sd.bonusqty))) AS qty, 0 AS value FROM dbo.saleledger AS sl, dbo.saledetail AS sd WHERE (((((sl.posted = 'Y') AND (sl.saleinvcode = sd.saleinvcode)) AND (sl.date < v_ar_startdate)) AND (sd.due IS NULL)) AND (sd.icode IN (SELECT code FROM tv_sp_itemstockmovementatavgprice_tab_itemlist AS tab_itemlist))) GROUP BY sd.icode UNION ALL SELECT 'OP' AS type, sd.icode, sum((sd.looseqty + sd.bonusqty)) AS qty, 0 AS value FROM dbo.srledger AS sl, dbo.srdetail AS sd WHERE ((((sl.posted = 'Y') AND (sl.srinvcode = sd.srinvcode)) AND (sl.postdate < v_ar_startdate)) AND (sd.icode IN (SELECT code FROM tv_sp_itemstockmovementatavgprice_tab_itemlist AS tab_itemlist))) GROUP BY sd.icode UNION ALL SELECT 'OP' AS type, sd.icode, (-sum(sd.qty)) AS qty, 0 AS value FROM dbo.issueheader AS sl, dbo.issuedetail AS sd WHERE ((((sl.posted = 'Y') AND (sl.issueinvcode = sd.issueinvcode)) AND (sl.date < v_ar_startdate)) AND (sd.icode IN (SELECT code FROM tv_sp_itemstockmovementatavgprice_tab_itemlist AS tab_itemlist))) GROUP BY sd.icode UNION ALL SELECT 'OP' AS type, sd.icode, sum(sd.qty) AS qty, 0 AS value FROM dbo.receiptheader AS sl, dbo.receiptdetail AS sd WHERE ((((sl.posted = 'Y') AND (sl.receiptinvcode = sd.receiptinvcode)) AND (sl.postdate < v_ar_startdate)) AND (sd.icode IN (SELECT code FROM tv_sp_itemstockmovementatavgprice_tab_itemlist AS tab_itemlist))) GROUP BY sd.icode UNION ALL SELECT 'OP' AS type, sd.icode, sum(sd.looseqty) AS qty, 0 AS value FROM dbo.adjheader AS sl, dbo.adjdetail AS sd WHERE (((((sl.posted = 'Y') AND (sl.adjcode = sd.adjcode)) AND (sl.adjcatcode = 1)) AND (sl.posteddate < v_ar_startdate)) AND (sd.icode IN (SELECT code FROM tv_sp_itemstockmovementatavgprice_tab_itemlist AS tab_itemlist))) GROUP BY sd.icode UNION ALL SELECT 'OP' AS type, sd.icode, (-sum(sd.looseqty)) AS qty, 0 AS value FROM dbo.adjheader AS sl, dbo.adjdetail AS sd WHERE (((((sl.posted = 'Y') AND (sl.adjcode = sd.adjcode)) AND (sl.adjcatcode = 2)) AND (sl.posteddate < v_ar_startdate)) AND (sd.icode IN (SELECT code FROM tv_sp_itemstockmovementatavgprice_tab_itemlist AS tab_itemlist))) GROUP BY sd.icode UNION ALL SELECT 'OP' AS type, d.icode, (-sum(d.duesatisfyqty)) AS qty, 0 AS value FROM dbo.duesatisfyheader AS h, dbo.duesatisfydetail AS d WHERE (((h.duesatisfycode = d.duesatisfycode) AND (h.duesatisfydate < v_ar_startdate)) AND (d.icode IN (SELECT code FROM tv_sp_itemstockmovementatavgprice_tab_itemlist AS tab_itemlist))) GROUP BY d.icode UNION ALL SELECT 'PV' AS type, pd.icode, sum(coalesce(CASE pl.purcatcode WHEN 1 THEN (((pd.packqty + pd.bonusqty)) * pd.packunits) WHEN 2 THEN (((pd.packqty + pd.bonusqty)) * pd.packunits) ELSE (pd.looseqty + pd.bonusqty) END, 0)) AS qty, sum(coalesce(((((pd.packqty + pd.looseqty) + pd.bonusqty)) * pd.netrate), 0)) AS value FROM dbo.purledger AS pl, dbo.purdetail AS pd WHERE ((((pl.posted = 'Y') AND (pl.postdate BETWEEN v_ar_startdate AND v_ar_enddate)) AND (pl.purinvcode = pd.purinvcode)) AND (pd.icode IN (SELECT code FROM tv_sp_itemstockmovementatavgprice_tab_itemlist AS tab_itemlist))) GROUP BY pd.icode UNION ALL SELECT 'PR' AS type, pd.icode, sum((pd.looseqty + pd.bonusqty)) AS qty, sum((((pd.looseqty + pd.bonusqty)) * pd.avgprice)) AS value FROM dbo.prledger AS pl, dbo.prdetail AS pd WHERE ((((pl.posted = 'Y') AND (pl.date BETWEEN v_ar_startdate AND v_ar_enddate)) AND (pl.prinvcode = pd.prinvcode)) AND (pd.icode IN (SELECT code FROM tv_sp_itemstockmovementatavgprice_tab_itemlist AS tab_itemlist))) GROUP BY pd.icode UNION ALL SELECT 'SV' AS type, sd.icode, sum((sd.looseqty + sd.bonusqty)) AS qty, sum((((sd.looseqty + sd.bonusqty)) * sd.avgprice)) AS value FROM dbo.saleledger AS sl, dbo.saledetail AS sd WHERE (((((sl.posted = 'Y') AND (sl.date BETWEEN v_ar_startdate AND v_ar_enddate)) AND (sl.saleinvcode = sd.saleinvcode)) AND (sd.due IS NULL)) AND (sd.icode IN (SELECT code FROM tv_sp_itemstockmovementatavgprice_tab_itemlist AS tab_itemlist))) GROUP BY sd.icode UNION ALL SELECT 'SR' AS type, sd.icode, sum((sd.looseqty + sd.bonusqty)) AS qty, sum((((sd.looseqty + sd.bonusqty)) * CASE WHEN (sl.saleinvcode > 0) THEN sd.avgprice ELSE ((sd.srprice * ((1 - (sd.discperc * 0.01)))) * ((1 - (sl.discperc * 0.01)))) END)) AS value FROM dbo.srledger AS sl, dbo.srdetail AS sd WHERE ((((sl.posted = 'Y') AND (sl.postdate BETWEEN v_ar_startdate AND v_ar_enddate)) AND (sl.srinvcode = sd.srinvcode)) AND (sd.icode IN (SELECT code FROM tv_sp_itemstockmovementatavgprice_tab_itemlist AS tab_itemlist))) GROUP BY sd.icode UNION ALL SELECT 'IV' AS type, sd.icode, sum(sd.qty) AS qty, sum((sd.qty * sd.avgprice)) AS value FROM dbo.issueheader AS sl, dbo.issuedetail AS sd WHERE ((((sl.posted = 'Y') AND (sl.date BETWEEN v_ar_startdate AND v_ar_enddate)) AND (sl.issueinvcode = sd.issueinvcode)) AND (sd.icode IN (SELECT code FROM tv_sp_itemstockmovementatavgprice_tab_itemlist AS tab_itemlist))) GROUP BY sd.icode UNION ALL SELECT 'DS' AS type, d.icode, sum(d.duesatisfyqty) AS qty, sum(((d.duesatisfyqty) * d.avgprice)) AS value FROM dbo.duesatisfyheader AS h, dbo.duesatisfydetail AS d WHERE (((h.duesatisfydate BETWEEN v_ar_startdate AND v_ar_enddate) AND (h.duesatisfycode = d.duesatisfycode)) AND (d.icode IN (SELECT code FROM tv_sp_itemstockmovementatavgprice_tab_itemlist AS tab_itemlist))) GROUP BY d.icode UNION ALL SELECT 'RV' AS type, sd.icode, sum(sd.qty) AS qty, sum(((sd.qty) * sd.avgprice)) AS value FROM dbo.receiptheader AS sl, dbo.receiptdetail AS sd WHERE ((((sl.posted = 'Y') AND (sl.postdate BETWEEN v_ar_startdate AND v_ar_enddate)) AND (sl.receiptinvcode = sd.receiptinvcode)) AND (sd.icode IN (SELECT code FROM tv_sp_itemstockmovementatavgprice_tab_itemlist AS tab_itemlist))) GROUP BY sd.icode UNION ALL SELECT 'AI' AS type, sd.icode, sum(sd.looseqty) AS qty, sum((sd.looseqty * sd.avgprice)) AS value FROM dbo.adjheader AS sl, dbo.adjdetail AS sd WHERE (((((sl.adjcatcode = 1) AND (sl.posted = 'Y')) AND (sl.posteddate BETWEEN v_ar_startdate AND v_ar_enddate)) AND (sl.adjcode = sd.adjcode)) AND (sd.icode IN (SELECT code FROM tv_sp_itemstockmovementatavgprice_tab_itemlist AS tab_itemlist))) GROUP BY sd.icode UNION ALL SELECT 'AD' AS type, sd.icode, sum(sd.looseqty) AS qty, sum((sd.looseqty * sd.avgprice)) AS value FROM dbo.adjheader AS sl, dbo.adjdetail AS sd WHERE (((((sl.adjcatcode = 2) AND (sl.posted = 'Y')) AND (sl.posteddate BETWEEN v_ar_startdate AND v_ar_enddate)) AND (sl.adjcode = sd.adjcode)) AND (sd.icode IN (SELECT code FROM tv_sp_itemstockmovementatavgprice_tab_itemlist AS tab_itemlist))) GROUP BY sd.icode UNION ALL SELECT 'OP' AS type, icode, 0 AS qty, 0 AS value FROM dbo.item WHERE (icode IN (SELECT code FROM tv_sp_itemstockmovementatavgprice_tab_itemlist AS tab_itemlist))) AS k GROUP BY icode) AS a WHERE (((((i.icode = a.icode) AND (i.manfcode = m.manfcode)) AND (i.icatcode = c.icatcode)) AND (i.iccode = l.iccode)) AND (i.packcode = p.packcode)) GROUP BY a.icode, i.customicode, i.name, i.icatcode, i.iccode, i.manfcode, i.packcode, i.packingdesc, m.name, c.name, l.name, p.name;
