-- ==== proc SP_LockBatch ====
CREATE OR REPLACE FUNCTION dbo.sp_lockbatch(gcode integer, icode integer, batch citext, expiry timestamp, qty numeric, lockbatch citext, lockreasoncode smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_gcode integer;
  v_icode integer;
  v_batch citext;
  v_expiry timestamp(3);
  v_qty numeric(15,4);
  v_lockbatch citext;
  v_lockreasoncode smallint;
  v_itemname citext;
  v_string_expiry citext;
  v_rowsaffected integer;
  v_err integer;
  _rc integer;
BEGIN
  v_gcode := gcode;
  v_icode := icode;
  v_batch := batch;
  v_expiry := expiry;
  v_qty := qty;
  v_lockbatch := lockbatch;
  v_lockreasoncode := lockreasoncode;
  UPDATE dbo.godowndetail SET locked = v_lockbatch, lockreasoncode = v_lockreasoncode WHERE (((((godowndetail.gcode = v_gcode) AND (godowndetail.icode = v_icode)) AND (godowndetail.batch = v_batch)) AND (godowndetail.expiry = v_expiry)) AND (godowndetail.currqty = v_qty));
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_rowsaffected := _rc;
  v_err := 0;
  _rc := 1;
  IF ((v_rowsaffected = 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Unable to lock batch for an item';
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

