DECLARE
  v_tabname citext;
  v_key integer;
BEGIN
  v_tabname := tabname;
  v_key := key;
  v_key := trunc((SELECT tabmaxkey FROM dbo._tabmaxkey WHERE (_tabmaxkey.tabname = v_tabname) FOR UPDATE OF _tabmaxkey))::integer;
  IF ((v_key IS NULL) OR (0 <> 0)) THEN
    RAISE EXCEPTION 'Exception occured while Fetching key value for table %', v_tabname;
    return_value := -1;
    key := v_key;
    RETURN;
  END IF;
  return_value := 0;
  key := v_key;
  RETURN;
  return_value := 0;
  key := v_key;
  RETURN;
END
$body$;

-- ==== proc SP_LockVisit ====
CREATE OR REPLACE FUNCTION dbo.sp_lockvisit(ai_visitcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
