$body$;

-- ==== proc SP_MachineWiseSaleAndReturn_CrossTab ====
CREATE OR REPLACE FUNCTION dbo.sp_machinewisesaleandreturn_crosstab(startdate timestamp, enddate timestamp, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_startdate timestamp(3);
  v_enddate timestamp(3);
BEGIN
  v_startdate := startdate;
  v_enddate := enddate;
  DELETE FROM dbo.reportdata;
  INSERT INTO dbo.reportdata (code1, name1, name2, value1, value2, date1, date2) SELECT s.maingroup, s.categoryname, s.machinename, sum(s.sale) AS sale, sum(s.salereturn) AS salereturn, v_startdate, v_enddate FROM (SELECT t.maingroup, CASE WHEN ((subgroup = 2) OR (subgroup = 9)) THEN '*** Discount ***' WHEN ((subgroup = 3) OR (subgroup = 10)) THEN '*** Misc. Charges ***' WHEN ((subgroup = 4) OR (subgroup = 11)) THEN '*** Sales Tax ***' WHEN ((subgroup = 5) OR (subgroup = 12)) THEN '*** Rounding Difference ***' WHEN ((subgroup = 6) OR (subgroup = 13)) THEN '*** Credit ***' WHEN (subgroup = 7) THEN '*** Returns ***' ELSE ic.name END AS categoryname, t.machinename, sum(CASE t.subgroup WHEN 8 THEN 0 ELSE t.value END) AS sale, sum(CASE WHEN (t.subgroup >= 8) THEN t.value ELSE 0 END) AS salereturn FROM (SELECT 1 AS maingroup, 1 AS subgroup, (SELECT min(machinename) FROM dbo.saleledger) AS machinename, icatcode, 0 AS value FROM dbo.itemcategory UNION ALL SELECT 1 AS maingroup, 1 AS subgroup, sl.machinename, i.icatcode, coalesce(sum(round(((((((sd.looseqty + (sd.packqty * sd.packunits))) * ((sd.saleprice - sd.itemflatdisc)))) * ((1 - ((.01 * sd.discperc))))))::numeric, 2)), 0) AS value FROM dbo.saledetail AS sd, dbo.saleledger AS sl, dbo.item AS i WHERE (((sl.date BETWEEN v_startdate AND v_enddate) AND (sl.saleinvcode = sd.saleinvcode)) AND (sd.icode = i.icode)) GROUP BY sl.machinename, i.icatcode UNION ALL SELECT 2 AS maingroup, 2 AS subgroup, sl.machinename, 9999999 AS icatcode, (-((sl.flatdisc + coalesce(((sum(round(((((((sd.looseqty + (sd.packqty * sd.packunits))) * ((sd.saleprice - sd.itemflatdisc)))) * ((1 - ((.01 * sd.discperc))))))::numeric, 2)) * 0.01) * sl.discperc), 0)))) AS value FROM dbo.saledetail AS sd, dbo.saleledger AS sl WHERE (((sl.date BETWEEN v_startdate AND v_enddate) AND (((sl.flatdisc <> 0) OR (sl.discperc <> 0)))) AND (sl.saleinvcode = sd.saleinvcode)) GROUP BY sl.machinename, sl.saleinvcode, sl.flatdisc, sl.discperc UNION ALL SELECT 2 AS maingroup, 3 AS subgroup, sl.machinename, 9999999 AS icatcode, sum(sl.misccharges) AS value FROM dbo.saledetail AS sd, dbo.saleledger AS sl WHERE (((sl.date BETWEEN v_startdate AND v_enddate) AND (sl.misccharges <> 0)) AND (sl.saleinvcode = sd.saleinvcode)) GROUP BY sl.machinename UNION ALL SELECT 2 AS maingroup, 4 AS subgroup, t.machinename, 9999999 AS icatcode, coalesce(sum(round(((t.itemsalestax + t.invtax))::numeric, 0)), 0) AS value FROM (SELECT sl.machinename, sum(round((((sd.looseqty * sd.unitsalestax) + round((((round((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc))) * ((1 - (sd.discperc * 0.01)))))::numeric, 2) * sd.gstperc) * 0.01))::numeric, 2)))::numeric, 2)) AS itemsalestax, round((((((((sum((sd.looseqty * sd.saleprice)) - round((sum(round((((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc))) * ((sd.discperc * .01)))) + ((sd.looseqty * sd.itemflatdisc))))::numeric, 2)))::numeric, 2)) - (sum(round((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc))) * ((1 - ((sd.discperc * .01))))))::numeric, 2)) * ((sl.discperc * 0.01)))) - sl.flatdisc)) * sl.invgstperc1) * 0.01))::numeric, 2) AS invtax FROM dbo.saleledger AS sl, dbo.saledetail AS sd WHERE ((((((sl.invgstperc1 <> 0) OR (sd.unitsalestax <> 0)) OR (sd.gstperc <> 0))) AND (sl.date BETWEEN v_startdate AND v_enddate)) AND (sl.saleinvcode = sd.saleinvcode)) GROUP BY sl.misccharges, sl.flatdisc, sl.date, sl.saleinvcode, sl.machinename, sl.discperc, sl.salestax, sl.invgstperc1) AS t GROUP BY t.machinename UNION ALL SELECT 2 AS maingroup, 5 AS subgroup, sl.machinename, 9999999 AS icatcode, (round((((((sum((sd.looseqty * sd.saleprice)) - round((sum(round((((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc))) * ((sd.discperc * .01)))) + ((sd.looseqty * sd.itemflatdisc))))::numeric, 2)))::numeric, 2)) - (sum(round((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc))) * ((1 - ((sd.discperc * .01))))))::numeric, 2)) * ((sl.discperc * 0.01)))) + sl.misccharges) - sl.flatdisc))::numeric, 0) - (((((sum((sd.looseqty * sd.saleprice)) - round((sum(round((((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc))) * ((sd.discperc * .01)))) + ((sd.looseqty * sd.itemflatdisc))))::numeric, 2)))::numeric, 2)) - (sum(round((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc))) * ((1 - ((sd.discperc * .01))))))::numeric, 2)) * ((sl.discperc * 0.01)))) + sl.misccharges) - sl.flatdisc))) AS value FROM dbo.saleledger AS sl, dbo.saledetail AS sd WHERE (((sl.salecatcode NOT IN (2)) AND (sl.date BETWEEN v_startdate AND v_enddate)) AND (sl.saleinvcode = sd.saleinvcode)) GROUP BY sl.saleinvcode, sl.machinename, sl.discperc, sl.misccharges, sl.flatdisc UNION ALL SELECT 2 AS maingroup, 6 AS subgroup, sl.machinename, 9999999 AS icatcode, (-dbo.fn_getsaleinvtotal((sl.saleinvcode)::integer)) AS value FROM dbo.saleledger AS sl WHERE ((sl.salecatcode IN (2)) AND (sl.date BETWEEN v_startdate AND v_enddate)) GROUP BY sl.saleinvcode, sl.machinename UNION ALL SELECT 2 AS maingroup, 7 AS subgroup, sl.machinename, 9999999 AS icatcode, (-dbo.fn_getsrinvtotal((sl.srinvcode)::integer)) AS value FROM dbo.srledger AS sl WHERE (sl.date BETWEEN v_startdate AND v_enddate) GROUP BY sl.srinvcode, sl.machinename UNION ALL SELECT 1 AS maingroup, 8 AS subgroup, sl.machinename, i.icatcode, (-coalesce(sum(round(((((((sd.looseqty + (sd.packqty * sd.packunits))) * sd.srprice)) * ((1 - ((.01 * sd.discperc))))))::numeric, 2)), 0)) AS value FROM dbo.srdetail AS sd, dbo.srledger AS sl, dbo.item AS i WHERE (((sl.date BETWEEN v_startdate AND v_enddate) AND (sl.srinvcode = sd.srinvcode)) AND (sd.icode = i.icode)) GROUP BY sl.machinename, i.icatcode UNION ALL SELECT 2 AS maingroup, 9 AS subgroup, sl.machinename, 9999999 AS icatcode, ((sl.flatdisc + coalesce(((sum(round(((((((sd.looseqty + (sd.packqty * sd.packunits))) * (sd.srprice))) * ((1 - ((.01 * sd.discperc))))))::numeric, 2)) * 0.01) * sl.discperc), 0))) AS value FROM dbo.srdetail AS sd, dbo.srledger AS sl WHERE (((sl.date BETWEEN v_startdate AND v_enddate) AND (((sl.flatdisc <> 0) OR (sl.discperc <> 0)))) AND (sl.srinvcode = sd.srinvcode)) GROUP BY sl.machinename, sl.srinvcode, sl.flatdisc, sl.discperc UNION ALL SELECT 2 AS maingroup, 10 AS subgroup, sl.machinename, 9999999 AS icatcode, (-sum(sl.misccharges)) AS value FROM dbo.srdetail AS sd, dbo.srledger AS sl WHERE (((sl.date BETWEEN v_startdate AND v_enddate) AND (sl.misccharges <> 0)) AND (sl.srinvcode = sd.srinvcode)) GROUP BY sl.machinename UNION ALL SELECT 2 AS maingroup, 11 AS subgroup, t.machinename, 9999999 AS icatcode, (-coalesce(sum(round(((t.itemsalestax + t.invtax))::numeric, 0)), 0)) AS value FROM (SELECT sl.machinename, sum(round((((sd.looseqty * sd.unitsalestax) + round((((round((((sd.looseqty * (sd.srprice)) * ((1 - (sd.discperc * 0.01)))))::numeric, 2) * sd.gstperc) * 0.01))::numeric, 2)))::numeric, 2)) AS itemsalestax, round((((((((sum((sd.looseqty * sd.srprice)) - round((sum(round(((((sd.looseqty * sd.srprice) * ((sd.discperc * .01)))))::numeric, 2)))::numeric, 2)) - (sum(round((((sd.looseqty * sd.srprice) * ((1 - ((sd.discperc * .01))))))::numeric, 2)) * ((sl.discperc * 0.01)))) - sl.flatdisc)) * sl.invgstperc1) * 0.01))::numeric, 2) AS invtax FROM dbo.srledger AS sl, dbo.srdetail AS sd WHERE ((((((sl.invgstperc1 <> 0) OR (sd.unitsalestax <> 0)) OR (sd.gstperc <> 0))) AND (sl.date BETWEEN v_startdate AND v_enddate)) AND (sl.srinvcode = sd.srinvcode)) GROUP BY sl.misccharges, sl.flatdisc, sl.date, sl.srinvcode, sl.machinename, sl.discperc, sl.salestax, sl.invgstperc1) AS t GROUP BY t.machinename UNION ALL SELECT 2 AS maingroup, 12 AS subgroup, sl.machinename, 9999999 AS icatcode, (-((round((((((sum((sd.looseqty * sd.srprice)) - round((sum(round(((((sd.looseqty * sd.srprice) * ((sd.discperc * .01)))))::numeric, 2)))::numeric, 2)) - (sum(round((((sd.looseqty * sd.srprice) * ((1 - ((sd.discperc * .01))))))::numeric, 2)) * ((sl.discperc * 0.01)))) + sl.misccharges) - sl.flatdisc))::numeric, 0) - (((((sum((sd.looseqty * sd.srprice)) - round((sum(round(((((sd.looseqty * sd.srprice) * ((sd.discperc * .01)))))::numeric, 2)))::numeric, 2)) - (sum(round((((sd.looseqty * sd.srprice) * ((1 - ((sd.discperc * .01))))))::numeric, 2)) * ((sl.discperc * 0.01)))) + sl.misccharges) - sl.flatdisc))))) AS value FROM dbo.srledger AS sl, dbo.srdetail AS sd WHERE (((sl.srcatcode NOT IN (2)) AND (sl.date BETWEEN v_startdate AND v_enddate)) AND (sl.srinvcode = sd.srinvcode)) GROUP BY sl.srinvcode, sl.machinename, sl.discperc, sl.misccharges, sl.flatdisc UNION ALL SELECT 2 AS maingroup, 13 AS subgroup, sl.machinename, 9999999 AS icatcode, dbo.fn_getsrinvtotal((sl.srinvcode)::integer) AS value FROM dbo.srledger AS sl WHERE ((sl.srcatcode NOT IN (8)) AND (sl.date BETWEEN v_startdate AND v_enddate)) GROUP BY sl.srinvcode, sl.machinename) AS t LEFT JOIN dbo.itemcategory AS ic ON ((t.icatcode = ic.icatcode)) GROUP BY t.maingroup, t.subgroup, t.machinename, ic.name) AS s GROUP BY s.maingroup, s.machinename, s.categoryname ORDER BY s.maingroup, s.machinename, s.categoryname;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_MakeAccountAliasUnique ====
CREATE OR REPLACE FUNCTION dbo.sp_makeaccountaliasunique(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_acccode integer;
  v_aliasname citext;
  v_oldaliasname citext;
  v_counter integer;
  v_conflictrows integer;
  cur_c1 refcursor;
  _fs integer := -1;
BEGIN
  -- SET NOCOUNT ON
  UPDATE dbo.accounts SET aliasname = (rtrim(ltrim((acccode)::text)) || 'R1') WHERE (aliasname IS NULL);
  SELECT count(*) INTO v_conflictrows FROM dbo.accounts WHERE (aliasname IN (SELECT aliasname FROM dbo.accounts GROUP BY aliasname HAVING (count(aliasname) > 1)));
  WHILE (v_conflictrows > 0) LOOP
    OPEN cur_c1 FOR SELECT acccode, aliasname FROM dbo.accounts WHERE (aliasname IN (SELECT aliasname FROM dbo.accounts GROUP BY aliasname HAVING (count(aliasname) > 1))) ORDER BY aliasname, acccode;
    v_oldaliasname := NULL;
    v_counter := 0;
    FETCH NEXT FROM cur_c1 INTO v_acccode, v_aliasname;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    WHILE (_fs = 0) LOOP
      IF (v_oldaliasname IS NULL) THEN
        v_oldaliasname := v_aliasname;
        v_counter := 0;
      END IF;
      IF (v_oldaliasname <> v_aliasname) THEN
        v_oldaliasname := v_aliasname;
        v_counter := 0;
      ELSE
        v_counter := (v_counter + 1);
        UPDATE dbo.accounts SET aliasname = ((rtrim(ltrim(aliasname)) || 'V') || rtrim(ltrim((v_counter)::text))) WHERE ((aliasname = v_aliasname) AND (acccode = v_acccode));
      END IF;
      FETCH NEXT FROM cur_c1 INTO v_acccode, v_aliasname;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    END LOOP;
    CLOSE cur_c1;
    -- DEALLOCATE C1
    SELECT count(*) INTO v_conflictrows FROM dbo.accounts WHERE (aliasname IN (SELECT aliasname FROM dbo.accounts GROUP BY aliasname HAVING (count(aliasname) > 1)));
  END LOOP;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_MakePriceChanges ====
CREATE OR REPLACE FUNCTION dbo.sp_makepricechanges(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_constcount integer;
  v_rowid integer;
  v_rowcount integer;
  v_loopcount integer;
  v_priority numeric(6,2);
  v_table citext;
  v_col citext;
  v_const citext;
  v_stmt citext;
  v_oldtable citext;
  v_newdatatype citext;
  cur_c1 refcursor;
  _dq1 text;
  cur_c2 refcursor;
  _dq2 text;
  _dq3 text;
  _dq4 text;
  _fs integer := -1;
BEGIN
  -- OPEN C1
  RAISE EXCEPTION 'untranslated T-SQL (system table sysobjects)' USING ERRCODE = '0A000';
  FETCH NEXT FROM cur_c1 INTO v_table, v_col, v_priority, v_const, v_newdatatype;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    v_stmt := ((('ALTER TABLE DBO.' || ltrim(rtrim(v_table))) || ' DROP CONSTRAINT ') || ltrim(rtrim(v_const)));
    _dq1 := v_stmt;
    IF _dq1 IS NOT NULL THEN
      EXECUTE dbo.tsql_dyn(_dq1);
    END IF;
    FETCH NEXT FROM cur_c1 INTO v_table, v_col, v_priority, v_const, v_newdatatype;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_c1;
  -- DEALLOCATE C1
  OPEN cur_c2 FOR SELECT dd.tablename, dd.columnname, dd.priority, dd.newdatatype FROM dbo.pricechanges AS dd ORDER BY dd.priority;
  FETCH NEXT FROM cur_c2 INTO v_table, v_col, v_priority, v_newdatatype;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    v_stmt := (((((('UPDATE DBO.' || ltrim(rtrim(v_table))) || ' SET ') || v_col) || ' = 0.00 WHERE ') || v_col) || ' IS NULL');
    _dq2 := v_stmt;
    IF _dq2 IS NOT NULL THEN
      EXECUTE dbo.tsql_dyn(_dq2);
    END IF;
    v_stmt := ((((('ALTER TABLE DBO.' || ltrim(rtrim(v_table))) || ' ALTER COLUMN ') || v_col) || ' ') || v_newdatatype);
    _dq3 := v_stmt;
    IF _dq3 IS NOT NULL THEN
      EXECUTE dbo.tsql_dyn(_dq3);
    END IF;
    v_stmt := ((((((('ALTER TABLE DBO.' || ltrim(rtrim(v_table))) || ' ADD CONSTRAINT DF_') || ltrim(rtrim(v_table))) || '_') || ltrim(rtrim(v_col))) || ' DEFAULT (0) FOR ') || ltrim(rtrim(v_col)));
    _dq4 := v_stmt;
    IF _dq4 IS NOT NULL THEN
      EXECUTE dbo.tsql_dyn(_dq4);
    END IF;
    FETCH NEXT FROM cur_c2 INTO v_table, v_col, v_priority, v_newdatatype;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_c2;
  -- DEALLOCATE C2
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_ManageLoyaltyPoints ====
CREATE OR REPLACE FUNCTION dbo.sp_manageloyaltypoints(invtype citext, invoicecode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_invtype citext;
  v_invoicecode integer;
  v_netamt numeric(12,2);
  v_loyaltyamt numeric(12,2);
  v_loyaltycardcode integer;
  v_loyaltypoints integer;
  v_pointsvalue numeric(12,2);
  v_loyaltypolicycode integer;
  _r1 record;
  _r2 record;
BEGIN
  v_invtype := invtype;
  v_invoicecode := invoicecode;
  -- SET NOCOUNT ON
  IF ((v_invoicecode IS NULL) OR (v_invoicecode < 0)) THEN
    v_loyaltypoints := 0;
    RAISE EXCEPTION 'Problem occured while fetching Invoice/Document Information';
    return_value := -1;
    RETURN;
  END IF;
  DELETE FROM dbo.loyaltycardledger WHERE ((invoicetype = v_invtype) AND (invoicecode = v_invoicecode));
  IF (v_invtype = 'SV') THEN
    v_netamt := coalesce((SELECT dbo.fn_getsaleinvloyaltytotal(v_invoicecode) AS amt), 0);
    v_loyaltycardcode := (SELECT min(loyaltycardcode) FROM dbo.loyaltycard WHERE ((expirydate >= (date_trunc('day', localtimestamp(3)))::timestamp(3)) AND (acccode IN (SELECT custcode FROM dbo.saleledger WHERE (saleinvcode = v_invoicecode)))));
    v_loyaltypolicycode := (SELECT loyaltypolicycode FROM dbo.loyaltycard WHERE (loyaltycardcode = v_loyaltycardcode));
    v_loyaltyamt := v_netamt;
    v_loyaltypoints := 0;
    IF ((v_loyaltypolicycode > 0) AND (v_loyaltycardcode > 0)) THEN
      FOR _r1 IN SELECT a.loyaltypoints AS c1, a.redemptionvalue AS c2 FROM (SELECT d.loyaltypoints, d.redemptionvalue FROM dbo.loyaltypolicydetail AS d, (SELECT min(salelimit) AS salelimit FROM dbo.loyaltypolicydetail WHERE ((loyaltypolicycode = v_loyaltypolicycode) AND (salelimit >= v_loyaltyamt)) UNION SELECT max(salelimit) AS salelimit FROM dbo.loyaltypolicydetail WHERE ((loyaltypolicycode = v_loyaltypolicycode) AND (salelimit <= v_loyaltyamt))) AS t WHERE (((d.loyaltypolicycode = v_loyaltypolicycode) AND (d.salelimit = t.salelimit)) AND (t.salelimit <= v_loyaltyamt))) AS a LOOP
        v_loyaltypoints := _r1.c1;
        v_pointsvalue := _r1.c2;
      END LOOP;
      IF ((v_loyaltypoints > 0) OR (v_pointsvalue > 0)) THEN
        INSERT INTO dbo.loyaltycardledger (loyaltycardcode, acccode, date, usercode, pointsdebit, pointscredit, debit, credit, remarks, invoicetype, invoicecode) SELECT l.loyaltycardcode, l.acccode, s.date AS date, s.salesmancode, v_loyaltypoints, 0, v_pointsvalue AS debit, 0.00 AS credit, 'Loyalty Points Earned', v_invtype, v_invoicecode FROM dbo.saleledger AS s, dbo.loyaltycard AS l WHERE ((((s.saleinvcode = v_invoicecode) AND (l.loyaltycardcode = v_loyaltycardcode)) AND (s.custcode = l.acccode)) AND (s.saleinvcode NOT IN (SELECT DISTINCT invoicecode FROM dbo.loyaltycardledger WHERE (invoicetype = 'SV'))));
      END IF;
    ELSE
      v_loyaltypoints := 0;
      return_value := 0;
      RETURN;
    END IF;
  END IF;
  IF (v_invtype = 'SR') THEN
    v_netamt := coalesce((SELECT dbo.fn_getsrinvloyaltytotal(v_invoicecode) AS amt), 0);
    v_loyaltycardcode := (SELECT min(loyaltycardcode) FROM dbo.loyaltycard WHERE ((expirydate >= (date_trunc('day', localtimestamp(3)))::timestamp(3)) AND (acccode IN (SELECT custcode FROM dbo.srledger WHERE (srinvcode = v_invoicecode)))));
    v_loyaltypolicycode := (SELECT loyaltypolicycode FROM dbo.loyaltycard WHERE (loyaltycardcode = v_loyaltycardcode));
    v_loyaltyamt := v_netamt;
    v_loyaltypoints := 0;
    IF ((v_loyaltypolicycode > 0) AND (v_loyaltycardcode > 0)) THEN
      FOR _r2 IN SELECT a.loyaltypoints AS c1, a.redemptionvalue AS c2 FROM (SELECT d.loyaltypoints, d.redemptionvalue FROM dbo.loyaltypolicydetail AS d, (SELECT min(salelimit) AS salelimit FROM dbo.loyaltypolicydetail WHERE ((loyaltypolicycode = v_loyaltypolicycode) AND (salelimit >= v_loyaltyamt)) UNION SELECT max(salelimit) AS salelimit FROM dbo.loyaltypolicydetail WHERE ((loyaltypolicycode = v_loyaltypolicycode) AND (salelimit <= v_loyaltyamt))) AS t WHERE (((d.loyaltypolicycode = v_loyaltypolicycode) AND (d.salelimit = t.salelimit)) AND (t.salelimit <= v_loyaltyamt))) AS a LOOP
        v_loyaltypoints := _r2.c1;
        v_pointsvalue := _r2.c2;
      END LOOP;
      IF ((v_loyaltypoints > 0) OR (v_pointsvalue > 0)) THEN
        INSERT INTO dbo.loyaltycardledger (loyaltycardcode, acccode, date, usercode, pointsdebit, pointscredit, debit, credit, remarks, invoicetype, invoicecode) SELECT l.loyaltycardcode, l.acccode, s.date AS date, s.salesmancode, 0, v_loyaltypoints, 0.00 AS debit, v_pointsvalue AS credit, 'Loyalty Points Reversed', v_invtype, v_invoicecode FROM dbo.srledger AS s, dbo.loyaltycard AS l WHERE ((((s.srinvcode = v_invoicecode) AND (l.loyaltycardcode = v_loyaltycardcode)) AND (s.custcode = l.acccode)) AND (s.srinvcode NOT IN (SELECT DISTINCT invoicecode FROM dbo.loyaltycardledger WHERE (invoicetype = 'SR'))));
      END IF;
    ELSE
      v_loyaltypoints := 0;
      return_value := 0;
      RETURN;
    END IF;
  END IF;
  IF (v_invtype = 'RD') THEN
    INSERT INTO dbo.loyaltycardledger (loyaltycardcode, acccode, date, usercode, pointsdebit, pointscredit, debit, credit, remarks, invoicetype, invoicecode) SELECT l.loyaltycardcode, l.acccode, lr.date AS date, lr.usercode, 0 AS pointsdebit, lr.pointsredeemed AS pointscredit, 0 AS debit, lr.pointsvalue AS credit, 'Loyalty Points Redeemed', v_invtype, v_invoicecode FROM dbo.loyaltyredemption AS lr, dbo.loyaltycard AS l WHERE (((lr.loyaltyredemptioncode = v_invoicecode) AND (lr.loyaltycardcode = l.loyaltycardcode)) AND (lr.loyaltyredemptioncode NOT IN (SELECT DISTINCT invoicecode FROM dbo.loyaltycardledger WHERE (invoicetype = 'RD'))));
  END IF;
  IF (v_invtype = 'AD') THEN
    INSERT INTO dbo.loyaltycardledger (loyaltycardcode, acccode, date, usercode, pointsdebit, pointscredit, debit, credit, remarks, invoicetype, invoicecode) SELECT l.loyaltycardcode, l.acccode, la.date AS date, la.usercode, CASE WHEN (la.adjustmenttypecode = 1) THEN la.adjustedpoints ELSE 0 END AS pointsdebit, CASE WHEN (la.adjustmenttypecode = 1) THEN 0 ELSE la.adjustedpoints END AS pointscredit, CASE WHEN (la.adjustmenttypecode = 1) THEN la.adjustmentvalue ELSE 0 END AS debit, CASE WHEN (la.adjustmenttypecode = 1) THEN 0 ELSE la.adjustmentvalue END AS credit, ('Loyalty Points ' || CASE WHEN (la.adjustmenttypecode = 1) THEN 'Added ' ELSE 'Deducted' END), v_invtype, v_invoicecode FROM dbo.loyaltypointadjustment AS la, dbo.loyaltycard AS l WHERE (((la.adjustmentcode = v_invoicecode) AND (la.loyaltycardcode = l.loyaltycardcode)) AND (la.adjustmentcode NOT IN (SELECT DISTINCT invoicecode FROM dbo.loyaltycardledger WHERE (invoicetype = 'AD'))));
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

