-- ==== proc SP_Mark_UserAttendance ====
CREATE OR REPLACE FUNCTION dbo.sp_mark_userattendance(usercode smallint, rowid integer, mode integer, date_in_out timestamp, INOUT msg citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_usercode smallint;
  v_rowid integer;
  v_mode integer;
  v_date_in_out timestamp(3);
  v_msg citext;
  v_uc smallint;
  v_rid integer;
  v_username citext;
  v_dt timestamp(3);
  v_dt2 timestamp(3);
  _rc integer;
BEGIN
  v_usercode := usercode;
  v_rowid := rowid;
  v_mode := mode;
  v_date_in_out := date_in_out;
  v_msg := msg;
  v_username := coalesce((SELECT username FROM dbo.users WHERE (usercode = v_usercode)), '');
  _rc := 1;
  v_uc := (SELECT usercode FROM dbo.users WHERE (usercode = v_usercode) FOR UPDATE OF users);
  _rc := 1;
  SELECT r.rowid INTO v_rid FROM dbo.sp_check_userattendance(usercode => v_usercode, rowid => v_rid) AS r;
  IF (0 <> 0) THEN
    RAISE EXCEPTION 'Unable to fetch user attendance status user = %, RowId = % ', v_username, v_rid;
    return_value := -1;
    msg := v_msg;
    RETURN;
  END IF;
  IF (v_rid = v_rowid) THEN
    v_dt := v_date_in_out;
    _rc := 1;
    IF (v_mode = 1) THEN
      INSERT INTO dbo.userattendance (usercode, timein, timeout, remarks) SELECT v_usercode, v_dt, NULL::timestamp(3), '';
      GET DIAGNOSTICS _rc = ROW_COUNT;
      IF (0 <> 0) THEN
        RAISE EXCEPTION 'Unable to Insert user attendance record user = % ', v_username;
        return_value := -1;
        msg := v_msg;
        RETURN;
      ELSE
        v_msg := ('Time-in On = ' || ltrim(rtrim(left(to_char(v_dt, 'Mon DD YYYY HH12:MIAM'), 100))));
        _rc := 1;
      END IF;
    ELSE
      v_dt2 := (SELECT timein FROM dbo.userattendance WHERE ((usercode = v_usercode) AND (rowid = v_rowid)));
      _rc := 1;
      IF (v_dt2 > v_date_in_out) THEN
        RAISE EXCEPTION 'User Time-in date is greater than current system date~r~nUnable to update user attendance record user = %, RowId = % ', v_username, v_rid;
        return_value := -1;
        msg := v_msg;
        RETURN;
      ELSE
        UPDATE dbo.userattendance SET timeout = v_dt WHERE ((usercode = v_usercode) AND (rowid = v_rowid));
        GET DIAGNOSTICS _rc = ROW_COUNT;
        IF ((0 <> 0) OR (_rc <= 0)) THEN
          RAISE EXCEPTION 'Unable to update user attendance record user = %, RowId = % ', v_username, v_rid;
          return_value := -1;
          msg := v_msg;
          RETURN;
        ELSE
          v_msg := ((('Time-in On = ' || ltrim(rtrim(left(to_char(v_dt2, 'Mon DD YYYY HH12:MIAM'), 100)))) || ', Time-out On = ') || ltrim(rtrim(left(to_char(v_dt, 'Mon DD YYYY HH12:MIAM'), 100))));
          _rc := 1;
        END IF;
      END IF;
    END IF;
  ELSE
    RAISE EXCEPTION 'Unable to mark User Attendance for user = %, RowId = %, Possible Reasons are Time in/out status changed, Try again ', v_username, v_rid;
    return_value := -1;
    msg := v_msg;
    RETURN;
  END IF;
  return_value := 0;
  msg := v_msg;
  RETURN;
  return_value := 0;
  msg := v_msg;
  RETURN;
END
$body$;

-- ==== proc SP_MarkAttendance ====
CREATE OR REPLACE FUNCTION dbo.sp_markattendance(empcode integer, fingercode smallint, INOUT attendancecode bigint, attendancedatetime timestamp, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_empcode integer;
  v_fingercode smallint;
  v_attendancecode bigint;
  v_attendancedatetime timestamp(3);
  v_applydepttimeslabs citext;
  v_deptcode integer;
  v_weekday integer;
  v_margin integer;
  v_timeslabtype smallint;
  v_attendancestatuscode smallint;
  v_datetimenow timestamp(3);
  v_starttime timestamp(3);
  v_endtime timestamp(3);
  _r1 record;
  _r2 record;
  _r3 record;
BEGIN
  v_empcode := empcode;
  v_fingercode := fingercode;
  v_attendancecode := attendancecode;
  v_attendancedatetime := attendancedatetime;
  -- SET NOCOUNT ON
  v_applydepttimeslabs := dbo.fn_getpreference('ApplyDeptTimeSlabsInOnlineAtten');
  IF (v_applydepttimeslabs IS NULL) THEN
    v_applydepttimeslabs := 'N';
  END IF;
  IF (v_attendancedatetime IS NULL) THEN
    v_datetimenow := localtimestamp(3);
  ELSE
    v_datetimenow := v_attendancedatetime;
  END IF;
  v_deptcode := (SELECT deptcode FROM dbo.emp_employee WHERE (empcode = v_empcode));
  v_weekday := (extract(dow from localtimestamp(3))::integer + 1);
  IF (v_applydepttimeslabs = 'Y') THEN
    FOR _r1 IN SELECT timeslabtype AS c1, starttime AS c2, endtime AS c3 FROM (SELECT 1 AS timeslabtype, left(to_char(fhtimein, 'HH24:MI:SS:MS'), 10) AS starttime, left(to_char(fhtimeout, 'HH24:MI:SS:MS'), 10) AS endtime FROM dbo.emp_departmenttiming WHERE (((deptcode = v_deptcode) AND (weekdaycode = v_weekday)) AND ((left(to_char(localtimestamp(3), 'HH24:MI:SS:MS'), 10))::citext BETWEEN (left(to_char(fhtimein, 'HH24:MI:SS:MS'), 10))::citext AND (left(to_char(fhtimeout, 'HH24:MI:SS:MS'), 10))::citext)) UNION SELECT 2 AS timeslabtype, left(to_char(shtimein, 'HH24:MI:SS:MS'), 10) AS starttime, left(to_char(shtimeout, 'HH24:MI:SS:MS'), 10) AS endtime FROM dbo.emp_departmenttiming WHERE (((deptcode = v_deptcode) AND (weekdaycode = v_weekday)) AND ((left(to_char(localtimestamp(3), 'HH24:MI:SS:MS'), 10))::citext BETWEEN (left(to_char(shtimein, 'HH24:MI:SS:MS'), 10))::citext AND (left(to_char(shtimeout, 'HH24:MI:SS:MS'), 10))::citext))) AS timeslabs LIMIT 1 LOOP
      v_timeslabtype := _r1.c1;
      v_starttime := _r1.c2;
      v_endtime := _r1.c3;
    END LOOP;
    IF ((v_timeslabtype <= 0) OR (v_timeslabtype IS NULL)) THEN
      RAISE EXCEPTION 'No Allowed Time Slot Exists for this employee, Please consult administrator to check allowed time slot for concerned department';
    END IF;
    v_starttime := (((left(to_char(localtimestamp(3), 'MM/DD/YYYY'), 100) || ' ') || left(to_char(v_starttime, 'HH24:MI:SS:MS'), 100)))::timestamp(3);
    v_endtime := (((left(to_char(localtimestamp(3), 'MM/DD/YYYY'), 100) || ' ') || left(to_char(v_endtime, 'HH24:MI:SS:MS'), 100)))::timestamp(3);
  ELSE
    v_attendancecode := (SELECT min(attendancecode) FROM dbo.emp_attendance WHERE (((empcode = v_empcode) AND (payed = 'N')) AND (timeout IS NULL)));
    IF (v_attendancecode IS NULL) THEN
      v_starttime := ((left(to_char(localtimestamp(3), 'MM/DD/YYYY'), 100) || ' 00:00:00'))::timestamp(3);
      v_endtime := ((left(to_char((localtimestamp(3) + (1) * interval '1 day'), 'MM/DD/YYYY'), 100) || ' 23:59:59'))::timestamp(3);
      v_timeslabtype := 0;
    ELSE
      v_starttime := (SELECT timein FROM dbo.emp_attendance WHERE ((((empcode = v_empcode) AND (payed = 'N')) AND (timeout IS NULL)) AND (attendancecode = v_attendancecode)));
      v_endtime := (SELECT timein FROM dbo.emp_attendance WHERE ((((empcode = v_empcode) AND (payed = 'N')) AND (timeout IS NULL)) AND (attendancecode = v_attendancecode)));
      v_timeslabtype := 0;
    END IF;
  END IF;
  IF ((v_attendancecode IS NULL) OR (v_attendancecode <= 0)) THEN
    v_attendancecode := (SELECT min(attendancecode) FROM dbo.emp_attendance WHERE ((((empcode = v_empcode) AND (payed = 'N')) AND (timein BETWEEN v_starttime AND v_endtime)) AND (timeout IS NULL)));
  END IF;
  IF (v_attendancecode > 0) THEN
    FOR _r2 IN SELECT attendancestatuscode AS c1, margin AS c2 FROM dbo.emp_attendancestatus WHERE ((timetype = 2) AND (half = v_timeslabtype)) LIMIT 1 LOOP
      v_attendancestatuscode := _r2.c1;
      v_margin := _r2.c2;
    END LOOP;
    UPDATE dbo.emp_attendance SET timeout = v_datetimenow, fingercodeout = v_fingercode, attendancestatuscode = CASE WHEN (dbo.tsql_datediff('minute', v_datetimenow, v_endtime) > v_margin) THEN v_attendancestatuscode ELSE attendancestatuscode END WHERE (attendancecode = v_attendancecode);
    return_value := 0;
    attendancecode := v_attendancecode;
    RETURN;
  END IF;
  FOR _r3 IN SELECT attendancestatuscode AS c1, margin AS c2 FROM dbo.emp_attendancestatus WHERE ((((autoset = 'Y') AND (timetype = 1)) AND (half = v_timeslabtype)) AND (attendancestatuscode = CASE WHEN (dbo.tsql_datediff('minute', v_endtime, v_datetimenow) <= margin) THEN attendancestatuscode ELSE v_attendancestatuscode END)) LIMIT 1 LOOP
    v_attendancestatuscode := _r3.c1;
    v_margin := _r3.c2;
  END LOOP;
  IF (coalesce(v_attendancestatuscode, 0) <= 0) THEN
    v_attendancestatuscode := 1;
  END IF;
  INSERT INTO dbo.emp_attendance (empcode, fingercode, timein, timeout, attendancestatuscode, payed, comments, fingercodeout) VALUES (v_empcode, v_fingercode, v_datetimenow, NULL::timestamp(3), v_attendancestatuscode, 'N', NULL::citext, NULL::smallint);
  v_attendancecode := (SELECT max(attendancecode) FROM dbo.emp_attendance WHERE ((((empcode = v_empcode) AND (payed = 'N')) AND (timein BETWEEN v_starttime AND v_endtime)) AND (timeout IS NULL)));
  return_value := 0;
  attendancecode := v_attendancecode;
  RETURN;
  return_value := 0;
  attendancecode := v_attendancecode;
  RETURN;
END
$body$;

-- ==== proc sp_MarkSamplesAsProcessed ====
CREATE OR REPLACE FUNCTION dbo.sp_marksamplesasprocessed(ai_sinvcode integer, ai_linvcode integer, ai_usercode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_sinvcode integer;
  v_ai_linvcode integer;
  v_ai_usercode integer;
BEGIN
  v_ai_sinvcode := ai_sinvcode;
  v_ai_linvcode := ai_linvcode;
  v_ai_usercode := ai_usercode;
  UPDATE dbo.samples SET processed = 'Y', processeddate = localtimestamp(3), processedby = v_ai_usercode WHERE (((samplecode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (posted = 'Y')) AND (processed = 'N'));
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_maxutn ====
CREATE OR REPLACE FUNCTION dbo.sp_maxutn(lbi_rows bigint, INOUT lbi_maxutn bigint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_lbi_rows bigint;
  v_lbi_maxutn bigint;
  v_err integer;
  v_rowcount integer;
  _rc integer;
BEGIN
  v_lbi_rows := lbi_rows;
  v_lbi_maxutn := lbi_maxutn;
  v_lbi_maxutn := (SELECT utn FROM dbo._utn FOR UPDATE OF _utn);
  _rc := 1;
  v_err := 0;
  v_rowcount := _rc;
  _rc := 1;
  IF ((v_err = 0) AND (v_rowcount > 0)) THEN
    UPDATE dbo._utn SET utn = (utn + v_lbi_rows);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_err := 0;
    v_rowcount := _rc;
    _rc := 1;
    IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
      RAISE EXCEPTION 'Unable to Update transaction UTN';
      return_value := -1;
      lbi_maxutn := v_lbi_maxutn;
      RETURN;
    END IF;
  ELSE
    RAISE EXCEPTION 'Unable to fetch transaction UTN';
    return_value := -1;
    lbi_maxutn := v_lbi_maxutn;
    RETURN;
  END IF;
  return_value := 0;
  lbi_maxutn := v_lbi_maxutn;
  RETURN;
  return_value := 0;
  lbi_maxutn := v_lbi_maxutn;
  RETURN;
END
$body$;

-- ==== proc SP_MonthlyNetSaleSummary ====
CREATE OR REPLACE FUNCTION dbo.sp_monthlynetsalesummary(type citext, startdate timestamp, enddate timestamp, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_type citext;
  v_startdate timestamp(3);
  v_enddate timestamp(3);
BEGIN
  v_type := type;
  v_startdate := startdate;
  v_enddate := enddate;
  DELETE FROM dbo.reportdata;
  INSERT INTO dbo.reportdata (name1, code1, name2, date1, value1) SELECT v_type, t.code, 'OVERALL NET SALES' AS name, (t.date)::timestamp(3), sum(t.amt) AS amt FROM (SELECT 1 AS code, ((ltrim(rtrim(dbo.tsql_str((extract(month from s.date)::integer)::numeric))) || '-01-') || ltrim(rtrim(dbo.tsql_str((extract(year from s.date)::integer)::numeric)))) AS date, sum(s.invtotal) AS amt FROM dbo.saleledger AS s WHERE (s.date BETWEEN v_startdate AND v_enddate) GROUP BY s.headerno, ((ltrim(rtrim(dbo.tsql_str((extract(month from s.date)::integer)::numeric))) || '-01-') || ltrim(rtrim(dbo.tsql_str((extract(year from s.date)::integer)::numeric)))) UNION ALL SELECT 1 AS code, ((ltrim(rtrim(dbo.tsql_str((extract(month from s.date)::integer)::numeric))) || '-01-') || ltrim(rtrim(dbo.tsql_str((extract(year from s.date)::integer)::numeric)))) AS date, (-sum(s.invtotal)) AS amt FROM dbo.srledger AS s WHERE (s.date BETWEEN v_startdate AND v_enddate) GROUP BY s.headerno, ((ltrim(rtrim(dbo.tsql_str((extract(month from s.date)::integer)::numeric))) || '-01-') || ltrim(rtrim(dbo.tsql_str((extract(year from s.date)::integer)::numeric))))) AS t WHERE ((upper(v_type))::citext = 'OVERALL NET SALES') GROUP BY t.code, t.date UNION ALL SELECT v_type, t.code, ('Header No.:' || dbo.tsql_str((t.code)::numeric)) AS name, (t.date)::timestamp(3), sum(t.amt) AS amt FROM (SELECT s.headerno AS code, ((ltrim(rtrim(dbo.tsql_str((extract(month from s.date)::integer)::numeric))) || '-01-') || ltrim(rtrim(dbo.tsql_str((extract(year from s.date)::integer)::numeric)))) AS date, sum(s.invtotal) AS amt FROM dbo.saleledger AS s WHERE (s.date BETWEEN v_startdate AND v_enddate) GROUP BY s.headerno, ((ltrim(rtrim(dbo.tsql_str((extract(month from s.date)::integer)::numeric))) || '-01-') || ltrim(rtrim(dbo.tsql_str((extract(year from s.date)::integer)::numeric)))) UNION ALL SELECT s.headerno AS code, ((ltrim(rtrim(dbo.tsql_str((extract(month from s.date)::integer)::numeric))) || '-01-') || ltrim(rtrim(dbo.tsql_str((extract(year from s.date)::integer)::numeric)))) AS date, (-sum(s.invtotal)) AS amt FROM dbo.srledger AS s WHERE (s.date BETWEEN v_startdate AND v_enddate) GROUP BY s.headerno, ((ltrim(rtrim(dbo.tsql_str((extract(month from s.date)::integer)::numeric))) || '-01-') || ltrim(rtrim(dbo.tsql_str((extract(year from s.date)::integer)::numeric))))) AS t WHERE ((upper(v_type))::citext = 'HEADER') GROUP BY t.code, t.date UNION ALL SELECT v_type, t.code, (SELECT k.name FROM dbo.salesman AS k WHERE (k.salesmancode = t.code)) AS name, (t.date)::timestamp(3), sum(t.amt) AS amt FROM (SELECT s.smancode AS code, ((ltrim(rtrim(dbo.tsql_str((extract(month from s.date)::integer)::numeric))) || '-01-') || ltrim(rtrim(dbo.tsql_str((extract(year from s.date)::integer)::numeric)))) AS date, sum(s.invtotal) AS amt FROM dbo.saleledger AS s WHERE (s.date BETWEEN v_startdate AND v_enddate) GROUP BY s.smancode, ((ltrim(rtrim(dbo.tsql_str((extract(month from s.date)::integer)::numeric))) || '-01-') || ltrim(rtrim(dbo.tsql_str((extract(year from s.date)::integer)::numeric)))) UNION ALL SELECT s.smancode AS code, ((ltrim(rtrim(dbo.tsql_str((extract(month from s.date)::integer)::numeric))) || '-01-') || ltrim(rtrim(dbo.tsql_str((extract(year from s.date)::integer)::numeric)))) AS date, (-sum(s.invtotal)) AS amt FROM dbo.srledger AS s WHERE (s.date BETWEEN v_startdate AND v_enddate) GROUP BY s.smancode, ((ltrim(rtrim(dbo.tsql_str((extract(month from s.date)::integer)::numeric))) || '-01-') || ltrim(rtrim(dbo.tsql_str((extract(year from s.date)::integer)::numeric))))) AS t WHERE ((upper(v_type))::citext = 'SALE PERSON') GROUP BY t.code, t.date UNION ALL SELECT v_type, t.code, (SELECT k.name FROM dbo.accounts AS k WHERE (k.acccode = t.code)) AS name, (t.date)::timestamp(3), sum(t.amt) AS amt FROM (SELECT s.custcode AS code, ((ltrim(rtrim(dbo.tsql_str((extract(month from s.date)::integer)::numeric))) || '-01-') || ltrim(rtrim(dbo.tsql_str((extract(year from s.date)::integer)::numeric)))) AS date, sum(s.invtotal) AS amt FROM dbo.saleledger AS s WHERE (s.date BETWEEN v_startdate AND v_enddate) GROUP BY s.custcode, ((ltrim(rtrim(dbo.tsql_str((extract(month from s.date)::integer)::numeric))) || '-01-') || ltrim(rtrim(dbo.tsql_str((extract(year from s.date)::integer)::numeric)))) UNION ALL SELECT s.custcode AS code, ((ltrim(rtrim(dbo.tsql_str((extract(month from s.date)::integer)::numeric))) || '-01-') || ltrim(rtrim(dbo.tsql_str((extract(year from s.date)::integer)::numeric)))) AS date, (-sum(s.invtotal)) AS amt FROM dbo.srledger AS s WHERE (s.date BETWEEN v_startdate AND v_enddate) GROUP BY s.custcode, ((ltrim(rtrim(dbo.tsql_str((extract(month from s.date)::integer)::numeric))) || '-01-') || ltrim(rtrim(dbo.tsql_str((extract(year from s.date)::integer)::numeric))))) AS t WHERE ((upper(v_type))::citext = 'CUSTOMER') GROUP BY t.code, t.date UNION ALL SELECT v_type, t.code, (SELECT k.name FROM dbo.area AS k WHERE (k.areacode = t.code)) AS name, (t.date)::timestamp(3), sum(t.amt) AS amt FROM (SELECT c.areacode AS code, ((ltrim(rtrim(dbo.tsql_str((extract(month from s.date)::integer)::numeric))) || '-01-') || ltrim(rtrim(dbo.tsql_str((extract(year from s.date)::integer)::numeric)))) AS date, sum(s.invtotal) AS amt FROM dbo.saleledger AS s, dbo.customer AS c WHERE ((s.date BETWEEN v_startdate AND v_enddate) AND (s.custcode = c.custcode)) GROUP BY c.areacode, ((ltrim(rtrim(dbo.tsql_str((extract(month from s.date)::integer)::numeric))) || '-01-') || ltrim(rtrim(dbo.tsql_str((extract(year from s.date)::integer)::numeric)))) UNION ALL SELECT c.areacode AS code, ((ltrim(rtrim(dbo.tsql_str((extract(month from s.date)::integer)::numeric))) || '-01-') || ltrim(rtrim(dbo.tsql_str((extract(year from s.date)::integer)::numeric)))) AS date, (-sum(s.invtotal)) AS amt FROM dbo.srledger AS s, dbo.customer AS c WHERE ((s.date BETWEEN v_startdate AND v_enddate) AND (s.custcode = c.custcode)) GROUP BY c.areacode, ((ltrim(rtrim(dbo.tsql_str((extract(month from s.date)::integer)::numeric))) || '-01-') || ltrim(rtrim(dbo.tsql_str((extract(year from s.date)::integer)::numeric))))) AS t WHERE ((upper(v_type))::citext = 'AREA') GROUP BY t.code, t.date UNION ALL SELECT v_type, t.code, (SELECT k.name FROM dbo.subarea AS k WHERE (k.subareacode = t.code)) AS name, (t.date)::timestamp(3), sum(t.amt) AS amt FROM (SELECT c.subareacode AS code, ((ltrim(rtrim(dbo.tsql_str((extract(month from s.date)::integer)::numeric))) || '-01-') || ltrim(rtrim(dbo.tsql_str((extract(year from s.date)::integer)::numeric)))) AS date, sum(s.invtotal) AS amt FROM dbo.saleledger AS s, dbo.customer AS c WHERE ((s.date BETWEEN v_startdate AND v_enddate) AND (s.custcode = c.custcode)) GROUP BY c.subareacode, ((ltrim(rtrim(dbo.tsql_str((extract(month from s.date)::integer)::numeric))) || '-01-') || ltrim(rtrim(dbo.tsql_str((extract(year from s.date)::integer)::numeric)))) UNION ALL SELECT c.subareacode AS code, ((ltrim(rtrim(dbo.tsql_str((extract(month from s.date)::integer)::numeric))) || '-01-') || ltrim(rtrim(dbo.tsql_str((extract(year from s.date)::integer)::numeric)))) AS date, (-sum(s.invtotal)) AS amt FROM dbo.srledger AS s, dbo.customer AS c WHERE ((s.date BETWEEN v_startdate AND v_enddate) AND (s.custcode = c.custcode)) GROUP BY c.subareacode, ((ltrim(rtrim(dbo.tsql_str((extract(month from s.date)::integer)::numeric))) || '-01-') || ltrim(rtrim(dbo.tsql_str((extract(year from s.date)::integer)::numeric))))) AS t WHERE ((upper(v_type))::citext = 'SUBAREA') GROUP BY t.code, t.date UNION ALL SELECT v_type, t.code, (SELECT k.name FROM dbo.customercategory AS k WHERE (k.custcatcode = t.code)) AS name, (t.date)::timestamp(3), sum(t.amt) AS amt FROM (SELECT c.custcatcode AS code, ((ltrim(rtrim(dbo.tsql_str((extract(month from s.date)::integer)::numeric))) || '-01-') || ltrim(rtrim(dbo.tsql_str((extract(year from s.date)::integer)::numeric)))) AS date, sum(s.invtotal) AS amt FROM dbo.saleledger AS s, dbo.customer AS c WHERE ((s.date BETWEEN v_startdate AND v_enddate) AND (s.custcode = c.custcode)) GROUP BY c.custcatcode, ((ltrim(rtrim(dbo.tsql_str((extract(month from s.date)::integer)::numeric))) || '-01-') || ltrim(rtrim(dbo.tsql_str((extract(year from s.date)::integer)::numeric)))) UNION ALL SELECT c.custcatcode AS code, ((ltrim(rtrim(dbo.tsql_str((extract(month from s.date)::integer)::numeric))) || '-01-') || ltrim(rtrim(dbo.tsql_str((extract(year from s.date)::integer)::numeric)))) AS date, (-sum(s.invtotal)) AS amt FROM dbo.srledger AS s, dbo.customer AS c WHERE ((s.date BETWEEN v_startdate AND v_enddate) AND (s.custcode = c.custcode)) GROUP BY c.custcatcode, ((ltrim(rtrim(dbo.tsql_str((extract(month from s.date)::integer)::numeric))) || '-01-') || ltrim(rtrim(dbo.tsql_str((extract(year from s.date)::integer)::numeric))))) AS t WHERE ((upper(v_type))::citext = 'CUSTOMER CATEGORY') GROUP BY t.code, t.date UNION ALL SELECT v_type, t.code, (SELECT k.username FROM dbo.users AS k WHERE (k.usercode = t.code)) AS name, (t.date)::timestamp(3), sum(t.amt) AS amt FROM (SELECT s.salesmancode AS code, ((ltrim(rtrim(dbo.tsql_str((extract(month from s.date)::integer)::numeric))) || '-01-') || ltrim(rtrim(dbo.tsql_str((extract(year from s.date)::integer)::numeric)))) AS date, sum(s.invtotal) AS amt FROM dbo.saleledger AS s WHERE (s.date BETWEEN v_startdate AND v_enddate) GROUP BY s.salesmancode, ((ltrim(rtrim(dbo.tsql_str((extract(month from s.date)::integer)::numeric))) || '-01-') || ltrim(rtrim(dbo.tsql_str((extract(year from s.date)::integer)::numeric)))) UNION ALL SELECT s.salesmancode AS code, ((ltrim(rtrim(dbo.tsql_str((extract(month from s.date)::integer)::numeric))) || '-01-') || ltrim(rtrim(dbo.tsql_str((extract(year from s.date)::integer)::numeric)))) AS date, (-sum(s.invtotal)) AS amt FROM dbo.srledger AS s WHERE (s.date BETWEEN v_startdate AND v_enddate) GROUP BY s.salesmancode, ((ltrim(rtrim(dbo.tsql_str((extract(month from s.date)::integer)::numeric))) || '-01-') || ltrim(rtrim(dbo.tsql_str((extract(year from s.date)::integer)::numeric))))) AS t WHERE ((upper(v_type))::citext = 'USER') GROUP BY t.code, t.date;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_MONTHLYSALES ====
CREATE OR REPLACE FUNCTION dbo.sp_monthlysales(ar_startdate timestamp, ar_enddate timestamp, ai_pricetype integer, ai_returns integer, ai_bonus integer, ai_allcust integer, ai_custcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ar_startdate timestamp(3);
  v_ar_enddate timestamp(3);
  v_ai_pricetype integer;
  v_ai_returns integer;
  v_ai_bonus integer;
  v_ai_allcust integer;
  v_ai_custcode integer;
BEGIN
  v_ar_startdate := ar_startdate;
  v_ar_enddate := ar_enddate;
  v_ai_pricetype := ai_pricetype;
  v_ai_returns := ai_returns;
  v_ai_bonus := ai_bonus;
  v_ai_allcust := ai_allcust;
  v_ai_custcode := ai_custcode;
  DELETE FROM dbo.reportdata;
  INSERT INTO dbo.reportdata (date1, name1, code1, name2, name3, name4, code2, value1, value2, value3, name5, name6) SELECT (st.date)::timestamp(3), ic.name AS name, i.icatcode AS code, i.name AS item, i.customicode AS aliasname, i.packingdesc AS packingdesc, st.icode, round(((i.saleprice / CASE WHEN (i.packunits > 0) THEN i.packunits ELSE 1 END))::numeric, 2) AS rate, sum(qty) AS saleqty, sum(CASE v_ai_pricetype WHEN 1 THEN value ELSE (round(((i.saleprice / CASE WHEN (i.packunits > 0) THEN i.packunits ELSE 1 END))::numeric, 2) * qty) END) AS salevalue, (SELECT m.name FROM dbo.manufacturer AS m WHERE (m.manfcode = i.manfcode)) AS manfname, CASE WHEN (v_ai_allcust = 0) THEN (SELECT a.name FROM dbo.accounts AS a WHERE (a.acccode = v_ai_custcode)) ELSE 'ALL CUSTOMERS' END AS customer FROM (SELECT sd.icode, ((ltrim(rtrim((extract(month from date)::integer)::text)) || '-01-') || rtrim(ltrim(to_char(date, 'YYYY')))) AS date, sum(((sd.looseqty + CASE v_ai_bonus WHEN 0 THEN 0 ELSE sd.bonusqty END) + (sd.packqty * sd.packunits))) AS qty, sum((((((sd.looseqty + (sd.packqty * sd.packunits))) * ((sd.saleprice - sd.itemflatdisc))) * ((1 - (sd.discperc * 0.01)))) * ((1 - (sl.discperc * 0.01))))) AS value FROM dbo.saleledger AS sl, dbo.saledetail AS sd, (SELECT c.custcode FROM dbo.customer AS c WHERE ((v_ai_allcust = 0) AND (c.custcode = v_ai_custcode)) UNION SELECT c.custcode FROM dbo.customer AS c WHERE (v_ai_allcust = 1)) AS cs WHERE (((((sl.posted = 'Y') AND (sl.saleinvcode = sd.saleinvcode)) AND (sl.custcode = cs.custcode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) GROUP BY sd.icode, sl.date UNION ALL SELECT sd.icode, ((ltrim(rtrim((extract(month from date)::integer)::text)) || '-01-') || rtrim(ltrim(to_char(date, 'YYYY')))) AS date, sum((sd.looseqty + CASE v_ai_bonus WHEN 0 THEN 0 ELSE sd.bonusqty END)) AS qty, sum(((((sd.looseqty) * ((sd.saleprice - sd.itemflatdisc))) * ((1 - (sd.discperc * 0.01)))) * ((1 - (sl.discperc * 0.01))))) AS value FROM dbo.saleledger AS sl, dbo.saleinvdetail AS sd, (SELECT c.custcode FROM dbo.customer AS c WHERE ((v_ai_allcust = 0) AND (c.custcode = v_ai_custcode)) UNION SELECT c.custcode FROM dbo.customer AS c WHERE (v_ai_allcust = 1)) AS cs WHERE ((((((sl.impactinventory = 'N') AND (sl.posted = 'Y')) AND (sl.saleinvcode = sd.saleinvcode)) AND (sl.custcode = cs.custcode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) GROUP BY sd.icode, sl.date UNION ALL SELECT sd.icode, ((ltrim(rtrim((extract(month from date)::integer)::text)) || '-01-') || rtrim(ltrim(to_char(date, 'YYYY')))) AS date, (-sum(((sd.looseqty + CASE v_ai_bonus WHEN 0 THEN 0 ELSE sd.bonusqty END) + (sd.packqty * sd.packunits)))) AS qty, (-sum((((((sd.looseqty + (sd.packqty * sd.packunits))) * sd.srprice) * ((1 - (sd.discperc * 0.01)))) * ((1 - (sl.discperc * 0.01)))))) AS value FROM dbo.srledger AS sl, dbo.srdetail AS sd, (SELECT c.custcode FROM dbo.customer AS c WHERE ((v_ai_allcust = 0) AND (c.custcode = v_ai_custcode)) UNION SELECT c.custcode FROM dbo.customer AS c WHERE (v_ai_allcust = 1)) AS cs WHERE ((((((sl.posted = 'Y') AND (sl.srinvcode = sd.srinvcode)) AND (sl.custcode = cs.custcode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) AND (v_ai_returns = 1)) GROUP BY sd.icode, sl.date) AS st, dbo.item AS i, dbo.itemcategory AS ic WHERE ((st.icode = i.icode) AND (i.icatcode = ic.icatcode)) GROUP BY st.icode, i.name, i.customicode, st.date, i.icatcode, ic.name, i.manfcode, i.saleprice, i.packunits, i.packingdesc ORDER BY st.date, ic.name, i.icatcode, i.name, i.customicode, st.icode;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_MONTHLYSALES_MANFWISE ====
CREATE OR REPLACE FUNCTION dbo.sp_monthlysales_manfwise(ar_startdate timestamp, ar_enddate timestamp, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ar_startdate timestamp(3);
  v_ar_enddate timestamp(3);
BEGIN
  v_ar_startdate := ar_startdate;
  v_ar_enddate := ar_enddate;
  DELETE FROM dbo.reportdata;
  INSERT INTO dbo.reportdata (date1, name1, code1, name2, name3, code2, value1, value2, value3, name4) SELECT (st.date)::timestamp(3), m.name AS name, i.manfcode AS code, i.name AS item, i.customicode AS aliasname, st.icode, round(((i.saleprice / CASE WHEN (i.packunits > 0) THEN i.packunits ELSE 1 END))::numeric, 2) AS rate, sum(qty) AS saleqty, sum(value) AS salevalue, i.packingdesc FROM (SELECT sd.icode, ((ltrim(rtrim((extract(month from date)::integer)::text)) || '-01-') || rtrim(ltrim(to_char(date, 'YYYY')))) AS date, sum(((sd.looseqty + sd.bonusqty) + (sd.packqty * sd.packunits))) AS qty, sum((((((sd.looseqty + (sd.packqty * sd.packunits))) * ((sd.saleprice - sd.itemflatdisc))) * ((1 - (sd.discperc * 0.01)))) * ((1 - (sl.discperc * 0.01))))) AS value FROM dbo.saleledger AS sl, dbo.saledetail AS sd WHERE ((((sl.posted = 'Y') AND (sl.saleinvcode = sd.saleinvcode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) GROUP BY sd.icode, sl.date UNION ALL SELECT sd.icode, ((ltrim(rtrim((extract(month from date)::integer)::text)) || '-01-') || rtrim(ltrim(to_char(date, 'YYYY')))) AS date, sum((sd.looseqty + sd.bonusqty)) AS qty, sum(((((sd.looseqty) * ((sd.saleprice - sd.itemflatdisc))) * ((1 - (sd.discperc * 0.01)))) * ((1 - (sl.discperc * 0.01))))) AS value FROM dbo.saleledger AS sl, dbo.saleinvdetail AS sd WHERE (((((sl.impactinventory = 'N') AND (sl.posted = 'Y')) AND (sl.saleinvcode = sd.saleinvcode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) GROUP BY sd.icode, sl.date UNION ALL SELECT sd.icode, ((ltrim(rtrim((extract(month from date)::integer)::text)) || '-01-') || rtrim(ltrim(to_char(date, 'YYYY')))) AS date, (-sum(((sd.looseqty + sd.bonusqty) + (sd.packqty * sd.packunits)))) AS qty, (-sum((((((sd.looseqty + (sd.packqty * sd.packunits))) * sd.srprice) * ((1 - (sd.discperc * 0.01)))) * ((1 - (sl.discperc * 0.01)))))) AS value FROM dbo.srledger AS sl, dbo.srdetail AS sd WHERE ((((sl.posted = 'Y') AND (sl.srinvcode = sd.srinvcode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) GROUP BY sd.icode, sl.date) AS st, dbo.item AS i, dbo.manufacturer AS m WHERE ((st.icode = i.icode) AND (i.manfcode = m.manfcode)) GROUP BY st.icode, i.name, i.customicode, st.date, i.manfcode, m.name, i.saleprice, i.packunits, i.packingdesc ORDER BY st.date, m.name, i.manfcode, i.name, i.customicode, st.icode;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_MONTHLYSALES_SMANWISE ====
CREATE OR REPLACE FUNCTION dbo.sp_monthlysales_smanwise(ar_startdate timestamp, ar_enddate timestamp, ar_smancode smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ar_startdate timestamp(3);
  v_ar_enddate timestamp(3);
  v_ar_smancode smallint;
BEGIN
  v_ar_startdate := ar_startdate;
  v_ar_enddate := ar_enddate;
  v_ar_smancode := ar_smancode;
  DELETE FROM dbo.reportdata;
  INSERT INTO dbo.reportdata (date1, name1, code1, value1) SELECT (st.date)::timestamp(3), m.name AS name, i.manfcode AS code, sum(value) AS salevalue FROM (SELECT sd.icode, ((ltrim(rtrim((extract(month from date)::integer)::text)) || '-01-') || rtrim(ltrim(to_char(date, 'YYYY')))) AS date, sum(((sd.looseqty + sd.bonusqty) + (sd.packqty * sd.packunits))) AS qty, sum((((((sd.looseqty + (sd.packqty * sd.packunits))) * ((sd.saleprice - sd.itemflatdisc))) * ((1 - (sd.discperc * 0.01)))) * ((1 - (sl.discperc * 0.01))))) AS value FROM dbo.saleledger AS sl, dbo.saledetail AS sd WHERE (((((sl.posted = 'Y') AND (sl.saleinvcode = sd.saleinvcode)) AND (sl.smancode = v_ar_smancode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) GROUP BY sd.icode, sl.date UNION ALL SELECT sd.icode, ((ltrim(rtrim((extract(month from date)::integer)::text)) || '-01-') || rtrim(ltrim(to_char(date, 'YYYY')))) AS date, sum((sd.looseqty + sd.bonusqty)) AS qty, sum(((((sd.looseqty) * ((sd.saleprice - sd.itemflatdisc))) * ((1 - (sd.discperc * 0.01)))) * ((1 - (sl.discperc * 0.01))))) AS value FROM dbo.saleledger AS sl, dbo.saledetail AS sd WHERE ((((((sl.impactinventory = 'N') AND (sl.posted = 'Y')) AND (sl.saleinvcode = sd.saleinvcode)) AND (sl.smancode = v_ar_smancode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) GROUP BY sd.icode, sl.date UNION ALL SELECT sd.icode, ((ltrim(rtrim((extract(month from date)::integer)::text)) || '-01-') || rtrim(ltrim(to_char(date, 'YYYY')))) AS date, (-sum(((sd.looseqty + sd.bonusqty) + (sd.packqty * sd.packunits)))) AS qty, (-sum((((((sd.looseqty + (sd.packqty * sd.packunits))) * sd.srprice) * ((1 - (sd.discperc * 0.01)))) * ((1 - (sl.discperc * 0.01)))))) AS value FROM dbo.srledger AS sl, dbo.srdetail AS sd WHERE (((((sl.posted = 'Y') AND (sl.srinvcode = sd.srinvcode)) AND (sl.smancode = v_ar_smancode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) GROUP BY sd.icode, sl.date) AS st, dbo.item AS i, dbo.manufacturer AS m WHERE ((st.icode = i.icode) AND (i.manfcode = m.manfcode)) GROUP BY st.date, m.name, i.manfcode ORDER BY st.date, m.name, i.manfcode;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_MONTHLYSALESANDSTOCK_ITEMWISE ====
CREATE OR REPLACE FUNCTION dbo.sp_monthlysalesandstock_itemwise(ar_startdate timestamp, ar_enddate timestamp, ar_icode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ar_startdate timestamp(3);
  v_ar_enddate timestamp(3);
  v_ar_icode integer;
  v_date1 timestamp(3);
  v_date2 timestamp(3);
BEGIN
  v_ar_startdate := ar_startdate;
  v_ar_enddate := ar_enddate;
  v_ar_icode := ar_icode;
  DELETE FROM dbo.reportdata;
  v_date1 := v_ar_startdate;
  v_date2 := v_ar_enddate;
  WHILE (v_date1 <= v_date2) LOOP
    INSERT INTO dbo.reportdata (date1, date2, code1, name1, name2, value1, value2, code2) SELECT (((ltrim(rtrim((extract(month from v_date1)::integer)::text)) || '-01-') || ltrim(rtrim((extract(year from v_date1)::integer)::text))))::timestamp(3) AS date1, (((ltrim(rtrim((CASE WHEN ((extract(month from v_date1)::integer + 1) = 13) THEN 1 ELSE (extract(month from v_date1)::integer + 1) END)::text)) || '-01-') || rtrim(ltrim((CASE WHEN ((extract(month from v_date1)::integer + 1) = 13) THEN (extract(year from v_date1)::integer + 1) ELSE extract(year from v_date1)::integer END)::text))))::timestamp(3) AS date2, v_ar_icode, customicode, name, 0, 0, 0 FROM dbo.item WHERE (icode = v_ar_icode);
    INSERT INTO dbo.reportdata (date1, date2, code1, name1, name2, value1, value2, code2) SELECT (((ltrim(rtrim((extract(month from v_date1)::integer)::text)) || '-01-') || ltrim(rtrim((extract(year from v_date1)::integer)::text))))::timestamp(3) AS date1, (((ltrim(rtrim((CASE WHEN ((extract(month from v_date1)::integer + 1) = 13) THEN 1 ELSE (extract(month from v_date1)::integer + 1) END)::text)) || '-01-') || rtrim(ltrim((CASE WHEN ((extract(month from v_date1)::integer + 1) = 13) THEN (extract(year from v_date1)::integer + 1) ELSE extract(year from v_date1)::integer END)::text))))::timestamp(3) AS date2, v_ar_icode, customicode, name, 0, 0, 1 FROM dbo.item WHERE (icode = v_ar_icode);
    v_date1 := (((ltrim(rtrim((CASE WHEN ((extract(month from v_date1)::integer + 1) = 13) THEN 1 ELSE (extract(month from v_date1)::integer + 1) END)::text)) || '-01-') || rtrim(ltrim((CASE WHEN ((extract(month from v_date1)::integer + 1) = 13) THEN (extract(year from v_date1)::integer + 1) ELSE extract(year from v_date1)::integer END)::text))))::timestamp(3);
  END LOOP;
  UPDATE dbo.reportdata AS reportdata SET value1 = coalesce((SELECT sum(netqty) FROM (SELECT ((((packqty + bonusqty)) * packunits)) AS netqty FROM dbo.purdetail, dbo.purledger WHERE (((((purledger.purcatcode IN (1, 2)) AND (purledger.purinvcode = purdetail.purinvcode)) AND (posted = 'Y')) AND (purdetail.icode = v_ar_icode)) AND (purledger.date < reportdata.date2)) UNION ALL SELECT ((looseqty + bonusqty)) AS netqty FROM dbo.purdetail, dbo.purledger WHERE (((((purledger.purcatcode IN (3, 7, 8)) AND (purledger.purinvcode = purdetail.purinvcode)) AND (posted = 'Y')) AND (purdetail.icode = v_ar_icode)) AND (purledger.date < reportdata.date2)) UNION ALL SELECT (-((looseqty + bonusqty))) AS netqty FROM dbo.prdetail, dbo.prledger WHERE (((prledger.prinvcode = prdetail.prinvcode) AND (prdetail.icode = v_ar_icode)) AND (prledger.date < reportdata.date2)) UNION ALL SELECT (-((looseqty + bonusqty))) AS netqty FROM dbo.saledetail, dbo.saleledger WHERE ((((saleledger.saleinvcode = saledetail.saleinvcode) AND (due IS NULL)) AND (saledetail.icode = v_ar_icode)) AND (saleledger.date < reportdata.date2)) UNION ALL SELECT ((looseqty + bonusqty)) AS netqty FROM dbo.srdetail, dbo.srledger WHERE (((srledger.srinvcode = srdetail.srinvcode) AND (srdetail.icode = v_ar_icode)) AND (srledger.date < reportdata.date2)) UNION ALL SELECT (-(duesatisfyqty)) AS netqty FROM dbo.duesatisfydetail, dbo.duesatisfyheader WHERE (((duesatisfyheader.duesatisfycode = duesatisfydetail.duesatisfycode) AND (duesatisfydetail.icode = v_ar_icode)) AND (duesatisfyheader.duesatisfydate < reportdata.date2)) UNION ALL SELECT (-(qty)) AS netqty FROM dbo.issuedetail, dbo.issueheader WHERE (((issueheader.issueinvcode = issuedetail.issueinvcode) AND (issuedetail.icode = v_ar_icode)) AND (issueheader.date < reportdata.date2)) UNION ALL SELECT qty AS netqty FROM dbo.receiptdetail, dbo.receiptheader WHERE ((((receiptheader.receiptinvcode = receiptdetail.receiptinvcode) AND (posted = 'Y')) AND (receiptdetail.icode = v_ar_icode)) AND (receiptheader.date < reportdata.date2)) UNION ALL SELECT CASE adjcatcode WHEN 1 THEN looseqty WHEN 2 THEN (-looseqty) END AS netqty FROM dbo.adjdetail, dbo.adjheader WHERE (((adjheader.adjcode = adjdetail.adjcode) AND (adjdetail.icode = v_ar_icode)) AND (adjheader.date < reportdata.date2))) AS net), 0), name3 = 'Closing Stock' WHERE (code2 = 0);
  UPDATE dbo.reportdata AS reportdata SET value1 = coalesce((SELECT sum(qty) FROM (SELECT sum(((sd.looseqty + sd.bonusqty) + (sd.packqty * sd.packunits))) AS qty FROM dbo.saleledger AS sl, dbo.saledetail AS sd WHERE (((((sl.posted = 'Y') AND (sl.saleinvcode = sd.saleinvcode)) AND (sd.icode = v_ar_icode)) AND (sl.date >= reportdata.date1)) AND (sl.date < reportdata.date2)) UNION ALL SELECT sum((sd.looseqty + sd.bonusqty)) AS qty FROM dbo.saleledger AS sl, dbo.saleinvdetail AS sd WHERE ((((((sl.impactinventory = 'N') AND (sl.posted = 'Y')) AND (sl.saleinvcode = sd.saleinvcode)) AND (sd.icode = v_ar_icode)) AND (sl.date >= reportdata.date1)) AND (sl.date < reportdata.date2)) UNION ALL SELECT (-sum(((sd.looseqty + sd.bonusqty) + (sd.packqty * sd.packunits)))) AS qty FROM dbo.srledger AS sl, dbo.srdetail AS sd WHERE (((((sl.posted = 'Y') AND (sl.srinvcode = sd.srinvcode)) AND (sd.icode = v_ar_icode)) AND (sl.date >= reportdata.date1)) AND (sl.date < reportdata.date2))) AS s), 0), name3 = 'Net Sale' WHERE (code2 = 1);
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_MONTHLYSALESCLASSWISE ====
CREATE OR REPLACE FUNCTION dbo.sp_monthlysalesclasswise(ar_startdate timestamp, ar_enddate timestamp, as_isactualprice citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ar_startdate timestamp(3);
  v_ar_enddate timestamp(3);
  v_as_isactualprice citext;
BEGIN
  v_ar_startdate := ar_startdate;
  v_ar_enddate := ar_enddate;
  v_as_isactualprice := as_isactualprice;
  DELETE FROM dbo.reportdata;
  INSERT INTO dbo.reportdata (date1, name1, code1, name2, name3, code2, value1, value2, value3, name4) SELECT (st.date)::timestamp(3), ic.name AS name, i.iccode AS code, i.name AS item, i.customicode AS aliasname, st.icode, round(((i.saleprice / CASE WHEN (i.packunits > 0) THEN i.packunits ELSE 1 END))::numeric, 2) AS rate, sum(qty) AS saleqty, (CASE WHEN (v_as_isactualprice = 'Y') THEN sum(value) ELSE (sum(qty) * round(((i.saleprice / CASE WHEN (i.packunits > 0) THEN i.packunits ELSE 1 END))::numeric, 2)) END) AS salevalue, i.packingdesc FROM dbo.item AS i LEFT JOIN (SELECT sd.icode, ((ltrim(rtrim((extract(month from date)::integer)::text)) || '-01-') || rtrim(ltrim(to_char(date, 'YYYY')))) AS date, sum(((sd.looseqty + sd.bonusqty) + (sd.packqty * sd.packunits))) AS qty, sum((((((sd.looseqty + (sd.packqty * sd.packunits))) * sd.saleprice) * ((1 - (sd.discperc * 0.01)))) * ((1 - (sl.discperc * 0.01))))) AS value FROM dbo.saleledger AS sl, dbo.saledetail AS sd WHERE ((((sl.posted = 'Y') AND (sl.saleinvcode = sd.saleinvcode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) GROUP BY sd.icode, sl.date UNION ALL SELECT sd.icode, ((ltrim(rtrim((extract(month from date)::integer)::text)) || '-01-') || rtrim(ltrim(to_char(date, 'YYYY')))) AS date, sum((sd.looseqty + sd.bonusqty)) AS qty, sum(((((sd.looseqty) * sd.saleprice) * ((1 - (sd.discperc * 0.01)))) * ((1 - (sl.discperc * 0.01))))) AS value FROM dbo.saleledger AS sl, dbo.saleinvdetail AS sd WHERE (((((sl.impactinventory = 'N') AND (sl.posted = 'Y')) AND (sl.saleinvcode = sd.saleinvcode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) GROUP BY sd.icode, sl.date UNION ALL SELECT sd.icode, ((ltrim(rtrim((extract(month from date)::integer)::text)) || '-01-') || rtrim(ltrim(to_char(date, 'YYYY')))) AS date, (-sum(((sd.looseqty + sd.bonusqty) + (sd.packqty * sd.packunits)))) AS qty, (-sum((((((sd.looseqty + (sd.packqty * sd.packunits))) * sd.srprice) * ((1 - (sd.discperc * 0.01)))) * ((1 - (sl.discperc * 0.01)))))) AS value FROM dbo.srledger AS sl, dbo.srdetail AS sd WHERE ((((sl.posted = 'Y') AND (sl.srinvcode = sd.srinvcode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) GROUP BY sd.icode, sl.date) AS st ON ((i.icode = st.icode)), dbo.itemclass AS ic WHERE (i.iccode = ic.iccode) GROUP BY st.icode, i.name, i.customicode, st.date, i.iccode, ic.name, i.saleprice, i.packunits, i.packingdesc ORDER BY st.date, ic.name, i.iccode, i.name, i.customicode, st.icode;
  UPDATE dbo.reportdata SET date1 = (SELECT max(date1) FROM dbo.reportdata) WHERE (date1 IS NULL);
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_MONTHLYSALESSUMMARY ====
CREATE OR REPLACE FUNCTION dbo.sp_monthlysalessummary(ar_startdate timestamp, ar_enddate timestamp, reportgrouping citext, grouplist citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ar_startdate timestamp(3);
  v_ar_enddate timestamp(3);
  v_reportgrouping citext;
  v_grouplist citext;
BEGIN
  v_ar_startdate := ar_startdate;
  v_ar_enddate := ar_enddate;
  v_reportgrouping := reportgrouping;
  v_grouplist := grouplist;
  DELETE FROM dbo.reportdata;
  DROP TABLE IF EXISTS tv_sp_monthlysalessummary_tab_grouplist;
  CREATE TEMP TABLE tv_sp_monthlysalessummary_tab_grouplist (
    code integer NOT NULL
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tv_sp_monthlysalessummary_tab_itemlist;
  CREATE TEMP TABLE tv_sp_monthlysalessummary_tab_itemlist (
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tv_sp_monthlysalessummary_tab_grouplist SELECT code FROM dbo.udf_stringtotabl(v_grouplist, ',') AS udf_stringtotabl;
  INSERT INTO tv_sp_monthlysalessummary_tab_itemlist SELECT code FROM dbo.udf_selectitems(v_reportgrouping, v_grouplist) AS udf_selectitems;
  INSERT INTO dbo.reportdata (name1, name2, code1, name3, value1) SELECT t.month AS name1, t.groupname AS name2, t.groupcode AS code1, t.saletype AS name3, sum(t.value) AS value1 FROM (SELECT s.month AS month, CASE v_reportgrouping WHEN 'M' THEN i.manfcode WHEN 'C' THEN i.icatcode WHEN 'L' THEN i.iccode ELSE i.packcode END AS groupcode, CASE v_reportgrouping WHEN 'M' THEN (SELECT m.name FROM dbo.manufacturer AS m WHERE (m.manfcode = i.manfcode)) WHEN 'C' THEN (SELECT c.name FROM dbo.itemcategory AS c WHERE (c.icatcode = i.icatcode)) WHEN 'L' THEN (SELECT c.name FROM dbo.itemclass AS c WHERE (c.iccode = i.iccode)) ELSE (SELECT p.name FROM dbo.itempacking AS p WHERE (p.packcode = i.packcode)) END AS groupname, s.icode AS icode, (SELECT st.name FROM dbo.saletype AS st WHERE (st.saletypecode = s.saletypecode)) AS saletype, sum(value) AS value FROM (SELECT sd.icode, sl.saletypecode, ((trim(to_char(date, 'Month')) || ' ') || to_char(date, 'YYYY')) AS month, sum((((((sd.looseqty + (sd.packqty * sd.packunits))) * sd.saleprice) * ((1 - (sd.discperc * 0.01)))) * ((1 - (sl.discperc * 0.01))))) AS value FROM dbo.saleledger AS sl, dbo.saledetail AS sd, tv_sp_monthlysalessummary_tab_itemlist AS i WHERE (((((sl.posted = 'Y') AND (sl.saleinvcode = sd.saleinvcode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) AND (sd.icode = i.code)) GROUP BY sd.icode, sl.saletypecode, ((trim(to_char(date, 'Month')) || ' ') || to_char(date, 'YYYY')) UNION ALL SELECT sd.icode, sl.saletypecode, ((trim(to_char(date, 'Month')) || ' ') || to_char(date, 'YYYY')) AS month, sum(((((sd.looseqty) * sd.saleprice) * ((1 - (sd.discperc * 0.01)))) * ((1 - (sl.discperc * 0.01))))) AS value FROM dbo.saleledger AS sl, dbo.saleinvdetail AS sd, tv_sp_monthlysalessummary_tab_itemlist AS i WHERE ((((((sl.impactinventory = 'N') AND (sl.posted = 'Y')) AND (sl.saleinvcode = sd.saleinvcode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) AND (sd.icode = i.code)) GROUP BY sd.icode, sl.saletypecode, ((trim(to_char(date, 'Month')) || ' ') || to_char(date, 'YYYY')) UNION ALL SELECT sd.icode, (SELECT s.saletypecode FROM dbo.saleledger AS s WHERE (s.saleinvcode = sl.saleinvcode)) AS saletypecode, ((trim(to_char(date, 'Month')) || ' ') || to_char(date, 'YYYY')) AS month, (-sum((((((sd.looseqty + (sd.packqty * sd.packunits))) * sd.srprice) * ((1 - (sd.discperc * 0.01)))) * ((1 - (sl.discperc * 0.01)))))) AS value FROM dbo.srledger AS sl, dbo.srdetail AS sd, tv_sp_monthlysalessummary_tab_itemlist AS i WHERE (((((sl.posted = 'Y') AND (sl.srinvcode = sd.srinvcode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) AND (sd.icode = i.code)) GROUP BY sd.icode, sl.saleinvcode, ((trim(to_char(date, 'Month')) || ' ') || to_char(date, 'YYYY'))) AS s, (SELECT * FROM dbo.item WHERE (icode IN (SELECT code FROM tv_sp_monthlysalessummary_tab_itemlist AS tab_itemlist))) AS i WHERE (i.icode = s.icode) GROUP BY s.month, s.icode, s.saletypecode, i.icatcode, i.iccode, i.manfcode, i.packcode UNION ALL SELECT ((trim(to_char(v_ar_startdate, 'Month')) || ' ') || to_char(v_ar_startdate, 'YYYY')) AS month, k.code AS groupcode, CASE v_reportgrouping WHEN 'M' THEN (SELECT m.name FROM dbo.manufacturer AS m WHERE (m.manfcode = k.code)) WHEN 'C' THEN (SELECT c.name FROM dbo.itemcategory AS c WHERE (c.icatcode = k.code)) WHEN 'L' THEN (SELECT c.name FROM dbo.itemclass AS c WHERE (c.iccode = k.code)) ELSE (SELECT p.name FROM dbo.itempacking AS p WHERE (p.packcode = k.code)) END AS groupname, 0 AS icode, NULL AS saletype, 0 AS value FROM (SELECT code FROM tv_sp_monthlysalessummary_tab_grouplist AS tab_grouplist) AS k) AS t GROUP BY t.month, t.groupname, t.groupcode, t.saletype;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_MyExecuteLocal ====
CREATE OR REPLACE FUNCTION dbo.sp_myexecutelocal(qry citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_qry citext;
  _dq1 text;
BEGIN
  v_qry := qry;
  _dq1 := v_qry;
  IF _dq1 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq1);
  END IF;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_newtableid ====
CREATE OR REPLACE FUNCTION dbo.sp_newtableid(as_tablename citext, INOUT ai_newid integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_as_tablename citext;
  v_ai_newid integer;
BEGIN
  v_as_tablename := as_tablename;
  v_ai_newid := ai_newid;
  v_ai_newid := trunc((SELECT tabmaxkey FROM dbo._tabmaxkey WHERE (_tabmaxkey.tabname = v_as_tablename) FOR UPDATE OF _tabmaxkey))::integer;
  v_ai_newid := (SELECT (v_ai_newid + 1));
  UPDATE dbo._tabmaxkey SET tabmaxkey = v_ai_newid WHERE (_tabmaxkey.tabname = v_as_tablename);
  return_value := 0;
  ai_newid := v_ai_newid;
  RETURN;
END
$body$;

-- ==== proc SP_OpeningBalance ====
CREATE OR REPLACE FUNCTION dbo.sp_openingbalance(acccode integer, datetime timestamp, INOUT bal numeric, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_acccode integer;
  v_datetime timestamp(3);
  v_bal numeric(15,5);
BEGIN
  v_acccode := acccode;
  v_datetime := datetime;
  v_bal := bal;
  PERFORM dbo.sp_virtualgl(ac_type => 'A');
  v_bal := 0;
  v_bal := coalesce((SELECT coalesce(sum((debit - credit)), 0) FROM dbo.virtualgl WHERE ((acccode IN (SELECT acccode FROM dbo.udf_getsummaryaccountlist(v_acccode) AS udf_getsummaryaccountlist)) AND (date <= v_datetime))), 0);
  return_value := 0;
  bal := v_bal;
  RETURN;
END
$body$;

-- ==== proc SP_OpeningCashInHand ====
CREATE OR REPLACE FUNCTION dbo.sp_openingcashinhand(ad_date timestamp, INOUT af_openbalance double precision, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ad_date timestamp(3);
  v_af_openbalance double precision;
  v_ln_openbalance numeric(12,2);
BEGIN
  v_ad_date := ad_date;
  v_af_openbalance := af_openbalance;
  DROP TABLE IF EXISTS tmp_lt_cashamts;
  CREATE TEMP TABLE tmp_lt_cashamts (
    received numeric(11,2) NOT NULL,
    payed numeric(11,2) NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_cashamts SELECT coalesce((round((((sum((saledetail.looseqty * saledetail.unitsalestax)) + sum(round(((((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc))))) * saledetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc)))))) * ((1 - ((.01 * saleledger.discperc))))) - saleledger.flatdisc)) * ((saleledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) + round((((((sum((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc)))))) * ((1 - ((.01 * saleledger.discperc))))) + saleledger.misccharges) + saleledger.salestax) - saleledger.flatdisc))::numeric, 0)), 0) AS received, 0.0 AS payed FROM dbo.saleledger, dbo.saledetail WHERE ((((saleledger.saleinvcode = saledetail.saleinvcode) AND ((((saleledger.salecatcode = 1) OR (saleledger.salecatcode = 3)) OR (saleledger.salecatcode = 5)))) AND (saleledger.posted = 'Y')) AND (saleledger.date < v_ad_date)) GROUP BY saleledger.saleinvcode, saleledger.salecatcode, saleledger.date, saleledger.discperc, saleledger.misccharges, saleledger.salestax, saleledger.invgstperc1, saleledger.flatdisc;
  INSERT INTO tmp_lt_cashamts SELECT 0 AS received, coalesce((round((((sum((srdetail.looseqty * srdetail.unitsalestax)) + sum(round(((((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc))))) * srdetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc)))))) * ((1 - ((.01 * srledger.discperc))))) - srledger.flatdisc)) * ((srledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) + round((((((sum((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc)))))) * ((1 - ((.01 * srledger.discperc))))) + srledger.misccharges) + srledger.salestax) - srledger.flatdisc))::numeric, 0)), 0) AS payed FROM dbo.srledger, dbo.srdetail WHERE ((((srledger.srinvcode = srdetail.srinvcode) AND (((srledger.srcatcode = 6) OR (srledger.srcatcode = 8)))) AND (srledger.posted = 'Y')) AND (srledger.date < v_ad_date)) GROUP BY srledger.srinvcode, srledger.srcatcode, srledger.date, srledger.discperc, srledger.misccharges, srledger.salestax, srledger.invgstperc1, srledger.flatdisc;
  INSERT INTO tmp_lt_cashamts SELECT CASE WHEN (round(((((sum(((servicedetail.price) * ((1 - ((.01 * servicedetail.discperc)))))) * ((1 - ((.01 * serviceheader.discperc))))) + serviceheader.misccharges) - serviceheader.flatdisc))::numeric, 0) IS NULL) THEN 0.0 ELSE round(((((sum(((servicedetail.price) * ((1 - ((.01 * servicedetail.discperc)))))) * ((1 - ((.01 * serviceheader.discperc))))) + serviceheader.misccharges) - serviceheader.flatdisc))::numeric, 0) END AS received, 0 AS payed FROM dbo.serviceheader LEFT JOIN dbo.servicedetail ON ((serviceheader.serviceinvcode = servicedetail.serviceinvcode)) WHERE (((serviceheader.servicecatcode IN (10, 12)) AND (serviceheader.posted = 'Y')) AND (serviceheader.date < v_ad_date)) GROUP BY serviceheader.serviceinvcode, serviceheader.servicecatcode, serviceheader.date, serviceheader.discperc, serviceheader.misccharges, serviceheader.flatdisc;
  INSERT INTO tmp_lt_cashamts SELECT 0 AS received, CASE WHEN (round(((((sum(((servicerdetail.serviceprice) * ((1 - ((.01 * servicerdetail.discperc)))))) * ((1 - ((.01 * servicerheader.discperc))))) + servicerheader.misccharges) - servicerheader.flatdisc))::numeric, 0) IS NULL) THEN 0.0 ELSE round(((((sum(((servicerdetail.serviceprice) * ((1 - ((.01 * servicerdetail.discperc)))))) * ((1 - ((.01 * servicerheader.discperc))))) + servicerheader.misccharges) - servicerheader.flatdisc))::numeric, 0) END AS payed FROM dbo.servicerheader LEFT JOIN dbo.servicerdetail ON ((servicerheader.servicerinvcode = servicerdetail.servicerinvcode)) WHERE (((servicerheader.servicercatcode IN (13, 15)) AND (servicerheader.posted = 'Y')) AND (servicerheader.date < v_ad_date)) GROUP BY servicerheader.servicerinvcode, servicerheader.servicercatcode, servicerheader.date, servicerheader.discperc, servicerheader.misccharges, servicerheader.flatdisc;
  INSERT INTO tmp_lt_cashamts SELECT 0 AS received, coalesce((round((((sum(((((purdetail.looseqty + purdetail.packqty) + purdetail.bonusqty)) * purdetail.unitsalestax)) + sum(round((((((((purdetail.looseqty + purdetail.packqty)) * purdetail.purprice) * ((1 - ((.01 * purdetail.discperc))))) * purdetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((((purdetail.looseqty + purdetail.packqty)) * purdetail.purprice)) * ((1 - ((.01 * purdetail.discperc)))))) * ((1 - ((.01 * purledger.discperc))))) - purledger.flatdisc)) * ((purledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) + round((((((sum(((((purdetail.looseqty + purdetail.packqty)) * purdetail.purprice) * ((1 - ((.01 * purdetail.discperc)))))) * ((1 - ((.01 * purledger.discperc))))) + purledger.misccharges) + purledger.salestax) - purledger.flatdisc))::numeric, 0)), 0) AS payed FROM dbo.purledger, dbo.purdetail WHERE ((((purledger.purinvcode = purdetail.purinvcode) AND (purledger.purcatcode = 1)) AND (purledger.posted = 'Y')) AND (purledger.date < v_ad_date)) GROUP BY purledger.purinvcode, purledger.purcatcode, purledger.date, purledger.discperc, purledger.misccharges, purledger.salestax, purledger.invgstperc1, purledger.flatdisc;
  INSERT INTO tmp_lt_cashamts SELECT 0 AS received, coalesce((round((((sum(((((purdetail.looseqty + purdetail.packqty) + purdetail.bonusqty)) * purdetail.unitsalestax)) + sum(round((((((((purdetail.looseqty + purdetail.packqty)) * purdetail.purprice) * ((1 - ((.01 * purdetail.discperc))))) * purdetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((((purdetail.looseqty + purdetail.packqty)) * purdetail.purprice)) * ((1 - ((.01 * purdetail.discperc)))))) * ((1 - ((.01 * purledger.discperc))))) - purledger.flatdisc)) * ((purledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) + round((((((sum(((((purdetail.looseqty + purdetail.packqty)) * purdetail.purprice) * ((1 - ((.01 * purdetail.discperc)))))) * ((1 - ((.01 * purledger.discperc))))) + purledger.misccharges) + purledger.salestax) - purledger.flatdisc))::numeric, 0)), 0) AS payed FROM dbo.purledger, dbo.purdetail WHERE ((((purledger.purinvcode = purdetail.purinvcode) AND (purledger.purcatcode = 7)) AND (purledger.posted = 'Y')) AND (purledger.date < v_ad_date)) GROUP BY purledger.purinvcode, purledger.purcatcode, purledger.date, purledger.discperc, purledger.misccharges, purledger.salestax, purledger.invgstperc1, purledger.flatdisc;
  INSERT INTO tmp_lt_cashamts SELECT coalesce((round((((sum((((prdetail.looseqty + prdetail.bonusqty)) * prdetail.unitsalestax)) + sum(round((((((prdetail.looseqty * prdetail.prprice) * ((1 - ((.01 * prdetail.discperc))))) * prdetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((prdetail.looseqty * prdetail.prprice)) * ((1 - ((.01 * prdetail.discperc)))))) * ((1 - ((.01 * prledger.discperc))))) - prledger.flatdisc)) * ((prledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) + round((((((sum((((prdetail.looseqty * prdetail.prprice)) * ((1 - ((.01 * prdetail.discperc)))))) * ((1 - ((.01 * prledger.discperc))))) + prledger.misccharges) + prledger.salestax) - prledger.flatdisc))::numeric, 0)), 0) AS received, 0 AS payed FROM dbo.prledger, dbo.prdetail WHERE ((((prledger.prinvcode = prdetail.prinvcode) AND (prledger.prcatcode = 4)) AND (prledger.posted = 'Y')) AND (prledger.date < v_ad_date)) GROUP BY prledger.prinvcode, prledger.prcatcode, prledger.date, prledger.discperc, prledger.misccharges, prledger.salestax, prledger.invgstperc1, prledger.flatdisc;
  INSERT INTO tmp_lt_cashamts SELECT CASE WHEN (sum(gldetail.debit) IS NULL) THEN 0 ELSE sum(gldetail.debit) END AS received, CASE WHEN (sum(gldetail.credit) IS NULL) THEN 0 ELSE sum(gldetail.credit) END AS payed FROM dbo.glheader, dbo.gldetail WHERE ((((glheader.glvochcode = gldetail.glvochcode) AND (glheader.posted = 'Y')) AND (glheader.date < v_ad_date)) AND (gldetail.acccode IN (SELECT accounts.acccode FROM dbo.accounts WHERE (accounts.subcode = (SELECT code FROM dbo.global WHERE ((lower(name))::citext = (lower('GT_CashSub'))::citext))))));
  v_ln_openbalance := (SELECT CASE WHEN ((sum(received) - sum(payed)) IS NULL) THEN 0.0 ELSE (sum(received) - sum(payed)) END FROM tmp_lt_cashamts AS lt_cashamts);
  v_af_openbalance := (SELECT (v_ln_openbalance)::double precision);
  return_value := 0;
  af_openbalance := v_af_openbalance;
  RETURN;
END
$body$;

-- ==== proc sp_OtherAccTransactionStatus ====
CREATE OR REPLACE FUNCTION dbo.sp_otheracctransactionstatus(ad_date timestamp, ad_ldate timestamp, ai_subacccode smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ad_date timestamp(3);
  v_ad_ldate timestamp(3);
  v_ai_subacccode smallint;
BEGIN
  v_ad_date := ad_date;
  v_ad_ldate := ad_ldate;
  v_ai_subacccode := ai_subacccode;
  DROP TABLE IF EXISTS tmp_lt_pvamts;
  CREATE TEMP TABLE tmp_lt_pvamts (
    debit numeric(15,2) NOT NULL,
    credit numeric(15,2) NOT NULL,
    code numeric(5,0) NOT NULL,
    name citext NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_pvamts SELECT coalesce(sum(gldetail.debit), 0), coalesce(sum(gldetail.credit), 0), gldetail.acccode AS custcode, (SELECT accounts.name FROM dbo.accounts WHERE (accounts.acccode = gldetail.acccode)) AS name FROM dbo.glheader, dbo.gldetail, dbo.accounts WHERE (((((((glheader.glvochcode = gldetail.glvochcode) AND (glheader.date < v_ad_date)) AND (glheader.posted = 'Y')) AND (gldetail.acccode NOT IN (SELECT custcode FROM dbo.customer))) AND (gldetail.acccode NOT IN (SELECT suppcode FROM dbo.supplier))) AND (gldetail.acccode = accounts.acccode)) AND (accounts.subcode = v_ai_subacccode)) GROUP BY gldetail.acccode;
  INSERT INTO tmp_lt_pvamts SELECT 0, coalesce(sum(notes.amount), 0), notes.acccode AS custcode, (SELECT accounts.name FROM dbo.accounts WHERE (accounts.acccode = notes.acccode)) AS name FROM dbo.notes, dbo.accounts WHERE (((((((notes.notecatcode = 1) AND (notes.posted = 'Y')) AND (notes.postdate < v_ad_date)) AND (notes.acccode NOT IN (SELECT custcode FROM dbo.customer))) AND (notes.acccode NOT IN (SELECT suppcode FROM dbo.supplier))) AND (notes.acccode = accounts.acccode)) AND (accounts.subcode = v_ai_subacccode)) GROUP BY notes.acccode;
  DELETE FROM dbo.reportdata;
  INSERT INTO dbo.reportdata (code1, name1, value1, value2, value3) SELECT code, name, coalesce((sum(debit) - sum(credit)), 0), 0, 0 FROM tmp_lt_pvamts AS lt_pvamts GROUP BY name, code;
  UPDATE dbo.reportdata AS reportdata SET name1 = accounts.name FROM dbo.accounts WHERE ((reportdata.name1 IS NULL) AND (reportdata.code1 = accounts.acccode));
  DELETE FROM tmp_lt_pvamts AS lt_pvamts;
  INSERT INTO tmp_lt_pvamts SELECT coalesce(sum(gldetail.debit), 0), coalesce(sum(gldetail.credit), 0), gldetail.acccode AS custcode, (SELECT accounts.name FROM dbo.accounts WHERE (accounts.acccode = gldetail.acccode)) AS name FROM dbo.glheader, dbo.gldetail, dbo.accounts WHERE ((((((((glheader.glvochcode = gldetail.glvochcode) AND (glheader.date >= v_ad_date)) AND (glheader.date <= v_ad_ldate)) AND (glheader.posted = 'Y')) AND (gldetail.acccode NOT IN (SELECT custcode FROM dbo.customer))) AND (gldetail.acccode NOT IN (SELECT suppcode FROM dbo.supplier))) AND (gldetail.acccode = accounts.acccode)) AND (accounts.subcode = v_ai_subacccode)) GROUP BY gldetail.acccode;
  INSERT INTO tmp_lt_pvamts SELECT 0, coalesce(sum(notes.amount), 0), notes.acccode AS custcode, (SELECT accounts.name FROM dbo.accounts WHERE (accounts.acccode = notes.acccode)) AS name FROM dbo.notes, dbo.accounts WHERE ((((((((notes.notecatcode = 1) AND (notes.posted = 'Y')) AND (notes.postdate >= v_ad_date)) AND (notes.postdate <= v_ad_ldate)) AND (notes.acccode NOT IN (SELECT custcode FROM dbo.customer))) AND (notes.acccode NOT IN (SELECT suppcode FROM dbo.supplier))) AND (notes.acccode = accounts.acccode)) AND (accounts.subcode = v_ai_subacccode)) GROUP BY notes.acccode;
  UPDATE dbo.reportdata SET value2 = a.ddebit, value3 = a.dcredit FROM (SELECT code, name, coalesce(sum(debit), 0) AS ddebit, coalesce(sum(credit), 0) AS dcredit FROM tmp_lt_pvamts AS lt_pvamts GROUP BY name, code) AS a WHERE (reportdata.code1 = a.code);
  DROP TABLE IF EXISTS tmp_lt_pvamts;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_PatientOpeningBalance ====
CREATE OR REPLACE FUNCTION dbo.sp_patientopeningbalance(al_patientcode integer, ad_edate timestamp, INOUT af_openbalance numeric, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_al_patientcode integer;
  v_ad_edate timestamp(3);
  v_af_openbalance numeric(15,5);
BEGIN
  v_al_patientcode := al_patientcode;
  v_ad_edate := ad_edate;
  v_af_openbalance := af_openbalance;
  v_af_openbalance := coalesce((SELECT (sum(v.debit) - sum(v.credit)) FROM dbo.virtualgl AS v WHERE (((v.patientcode = v_al_patientcode) AND (v.acccode IN (SELECT p.custcode FROM dbo.patient AS p WHERE (p.patientcode = v_al_patientcode)))) AND (v.date < v_ad_edate))), 0);
  return_value := 0;
  af_openbalance := v_af_openbalance;
  RETURN;
END
$body$;

-- ==== proc SP_PerformSchoolLeaving ====
CREATE OR REPLACE FUNCTION dbo.sp_performschoolleaving(studentcode integer, classcode integer, usercode smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_studentcode integer;
  v_classcode integer;
  v_usercode smallint;
  v_errcode integer;
  v_invcount integer;
  v_servicerinvcode integer;
  v_serviceinvcode integer;
  v_unpostedtrans integer;
  v_srallocationcode integer;
  v_tot_services integer;
  v_resultcode integer;
  v_servicecode integer;
  v_start_no integer;
  v_end_no integer;
  v_rowid integer;
  v_in_rowid integer;
  v_in_qty integer;
  v_tmpcode integer;
  v_msg citext;
  v_date timestamp(3);
  v_sr_balance numeric(15,2);
  v_svc_balance numeric(15,2);
  v_amt numeric(15,2);
  v_new_service_balance numeric(15,2);
  v_new_sr_balance numeric(15,2);
  _rc integer;
BEGIN
  v_studentcode := studentcode;
  v_classcode := classcode;
  v_usercode := usercode;
  -- SET NOCOUNT ON
  DROP TABLE IF EXISTS tv_sp_performschoolleaving_svc;
  CREATE TEMP TABLE tv_sp_performschoolleaving_svc (
    serviceinvcode integer,
    rowid integer GENERATED BY DEFAULT AS IDENTITY
) ON COMMIT DROP;
  IF (v_usercode IS NULL) THEN
    v_usercode := 1;
    _rc := 1;
  END IF;
  v_invcount := coalesce((SELECT count(serviceinvcode) FROM dbo.serviceheader WHERE ((studentcode = v_studentcode) AND (outstandingamt > 0))), 0);
  _rc := 1;
  INSERT INTO tv_sp_performschoolleaving_svc (serviceinvcode) SELECT DISTINCT serviceinvcode FROM dbo.serviceheader WHERE ((studentcode = v_studentcode) AND (outstandingamt > 0));
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_invcount := _rc;
  _rc := 1;
  IF (v_invcount > 0) THEN
    v_errcode := 0;
    _rc := 1;
    SELECT r.return_value, r.key INTO v_errcode, v_start_no FROM dbo.sp_locktabmaxkey(tabname => 'ServiceRHeader', key => v_start_no) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Problem while Fetching Service Return Header Value';
      return_value := -1;
      RETURN;
    END IF;
    v_rowid := 1;
    _rc := 1;
    WHILE (v_rowid <= v_invcount) LOOP
      v_date := localtimestamp(3);
      _rc := 1;
      v_servicerinvcode := (v_start_no + v_rowid);
      _rc := 1;
      v_end_no := v_servicerinvcode;
      _rc := 1;
      v_serviceinvcode := (SELECT serviceinvcode FROM tv_sp_performschoolleaving_svc AS svc WHERE (rowid = v_rowid));
      _rc := 1;
      INSERT INTO dbo.servicerheader (servicerinvcode, serviceinvcode, custcode, salesmancode, servicercatcode, remarks, originaldate, modifiedby, date, postedby, postdate, headerno, discperc, flatdisc, misccharges, saleinvcode, posted, doctcode, patientcode, admissioncode, cashacccode, cashtendered, cashcharged, cashback, invtotal, guestcode, guestcheckincode, studentcode, outstandingamt, marked) SELECT v_servicerinvcode, serviceinvcode, custcode, salesmancode, CASE WHEN (servicecatcode = 10) THEN 13 ELSE 14 END AS servicercatcode, (('Return Against Service Inv. ' || ltrim(rtrim((serviceinvcode)::text))) || ' On School Leaving') AS remarks, v_date AS originaldate, NULL::smallint AS modifiedby, v_date AS date, v_usercode AS postedby, v_date AS postdate, headerno, discperc, flatdisc, misccharges, saleinvcode, 'Y' AS posted, doctcode, patientcode, admissioncode, cashacccode, 0 AS cashtendered, 0 AS cashcharged, 0 AS cashback, invtotal, guestcode, guestcheckincode, studentcode, outstandingamt, 'N' AS marked FROM dbo.serviceheader WHERE (serviceinvcode IN (SELECT serviceinvcode FROM tv_sp_performschoolleaving_svc AS svc WHERE (rowid = v_rowid)));
      GET DIAGNOSTICS _rc = ROW_COUNT;
      IF ((0 <> 0) OR (_rc <= 0)) THEN
        RAISE EXCEPTION 'Problem while Inserting Service Purchase Invoice Header Value';
        return_value := -1;
        RETURN;
      END IF;
      INSERT INTO dbo.servicerdetail (servicerinvcode, servicecode, serviceprice, discperc, smancode, qty, srvrowid, commission, costprice, serviceflatdisc) SELECT v_servicerinvcode, servicecode, price AS serviceprice, discperc, smancode, qty, srvrowid, commission, costprice, serviceflatdisc FROM dbo.servicedetail WHERE (serviceinvcode IN (SELECT serviceinvcode FROM tv_sp_performschoolleaving_svc AS svc WHERE (rowid = v_rowid))) ORDER BY srvrowid;
      GET DIAGNOSTICS _rc = ROW_COUNT;
      IF ((0 <> 0) OR (_rc <= 0)) THEN
        RAISE EXCEPTION 'Problem while Inserting Service Return Detail Rows';
        return_value := -1;
        RETURN;
      END IF;
      UPDATE dbo.servicerheader SET invtotal = dbo.fn_getservicereturninvtotal((servicerinvcode)::integer) WHERE (servicerinvcode = v_servicerinvcode);
      GET DIAGNOSTICS _rc = ROW_COUNT;
      UPDATE dbo.servicerheader SET outstandingamt = invtotal WHERE (servicerinvcode = v_servicerinvcode);
      GET DIAGNOSTICS _rc = ROW_COUNT;
      SELECT r.return_value INTO v_errcode FROM dbo.sp_lockservicesrinvoice(ai_servicerinvcode => v_servicerinvcode) AS r;
      IF ((0 <> 0) OR (v_errcode <> 0)) THEN
        RAISE EXCEPTION 'Problem while Locking Service Return Invoice : %', v_servicerinvcode;
        return_value := -1;
        RETURN;
      END IF;
      SELECT r.return_value INTO v_errcode FROM dbo.sp_lockserviceinvoice(ai_serviceinvcode => v_serviceinvcode) AS r;
      IF ((0 <> 0) OR (v_errcode <> 0)) THEN
        RAISE EXCEPTION 'Problem while Locking Service Invoice : %', v_serviceinvcode;
        return_value := -1;
        RETURN;
      END IF;
      SELECT r.return_value, r.rowscount, r.msg INTO v_errcode, v_unpostedtrans, v_msg FROM dbo.sp_checkunpostedserviceinvintransactions(invcode => v_serviceinvcode, code => NULL, callermodule => 'SR', rowscount => v_unpostedtrans, msg => v_msg) AS r;
      IF ((0 <> 0) OR (v_errcode <> 0)) THEN
        RAISE EXCEPTION 'Unposted Transactions exists for Service Invoice : %', v_serviceinvcode;
        return_value := -1;
        RETURN;
      END IF;
      IF (v_unpostedtrans = 0) THEN
        SELECT r.return_value, r.an_balance INTO v_errcode, v_sr_balance FROM dbo.sp_getservicesrinvbalance(ai_srinvcode => v_servicerinvcode, an_balance => v_sr_balance) AS r;
        IF ((0 <> 0) OR (v_errcode <> 0)) THEN
          RAISE EXCEPTION 'Problem while Fetching Service Return Invoice Balance : %', v_servicerinvcode;
          return_value := -1;
          RETURN;
        END IF;
        IF (v_sr_balance > 0) THEN
          SELECT r.return_value, r.an_balance INTO v_errcode, v_svc_balance FROM dbo.sp_getserviceinvbalance(ai_invcode => v_serviceinvcode, an_balance => v_svc_balance) AS r;
          IF ((0 <> 0) OR (v_errcode <> 0)) THEN
            RAISE EXCEPTION 'Problem while Fetching Service Invoice Balance : %', v_serviceinvcode;
            return_value := -1;
            RETURN;
          END IF;
          IF (v_svc_balance > 0) THEN
            IF (v_svc_balance <= v_sr_balance) THEN
              v_amt := v_svc_balance;
              _rc := 1;
            ELSE
              v_amt := v_sr_balance;
              _rc := 1;
            END IF;
            v_new_service_balance := (v_svc_balance - v_amt);
            _rc := 1;
            v_new_sr_balance := (v_sr_balance - v_amt);
            _rc := 1;
            SELECT r.return_value INTO v_errcode FROM dbo.sp_updateservicesrinvbalance(ai_invcode => v_servicerinvcode, an_amt => v_new_sr_balance) AS r;
            IF ((0 <> 0) OR (v_errcode <> 0)) THEN
              RAISE EXCEPTION 'Problem while Updating Service Return Invoice Balance For Ret #: %', v_servicerinvcode;
              return_value := -1;
              RETURN;
            END IF;
            SELECT r.return_value INTO v_errcode FROM dbo.sp_updateserviceinvbalance(ai_invcode => v_serviceinvcode, an_amt => v_new_service_balance) AS r;
            IF ((0 <> 0) OR (v_errcode <> 0)) THEN
              RAISE EXCEPTION 'Problem while Updating Service Invoice Balance for Inv : %', v_serviceinvcode;
              return_value := -1;
              RETURN;
            END IF;
            SELECT r.return_value, r.ai_srallocationcode INTO v_errcode, v_srallocationcode FROM dbo.sp_createservicesrallocation(ai_servicerinvcode => v_servicerinvcode, ai_serviceinvcode => v_serviceinvcode, ad_date => v_date, ai_usercode => (v_usercode)::integer, ac_posted => 'Y', ad_postdate => v_date, an_outstandingamt => v_svc_balance, an_amt => v_amt, ai_srallocationcode => v_srallocationcode) AS r;
            IF ((0 <> 0) OR (v_errcode <> 0)) THEN
              RAISE EXCEPTION 'Problem while Updating Service Invoice Balance for Inv : %', v_serviceinvcode;
              return_value := -1;
              RETURN;
            END IF;
          END IF;
        END IF;
      END IF;
      v_rowid := (v_rowid + 1);
      _rc := 1;
    END LOOP;
    SELECT r.return_value INTO v_errcode FROM dbo.sp_updatetabmaxkey(tabname => 'ServiceRHeader', key => v_end_no) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Problem while Updating Service Return Key Value';
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  DELETE FROM dbo.studentclass WHERE ((studentcode = v_studentcode) AND (classcode = v_classcode));
  GET DIAGNOSTICS _rc = ROW_COUNT;
  UPDATE dbo.student SET status = 'L' WHERE (studentcode = v_studentcode);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  PERFORM dbo.sp_virtualgl(ac_type => 'A');
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_POList_From_DataCarryDB ====
CREATE OR REPLACE FUNCTION dbo.sp_polist_from_datacarrydb(srv citext, db citext, owner citext, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_query citext;
  _dq1 text;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  v_query := ((((((('Select POCode, Date, Remarks, PurOrderCatCode From  ' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.') || 'PurOrderHeader');
  _dq1 := v_query;
  IF _dq1 IS NOT NULL THEN
    IF _dq1 ~* '^[[:space:]]*select' THEN OPEN rs1 FOR EXECUTE dbo.tsql_dyn(_dq1); ELSE EXECUTE dbo.tsql_dyn(_dq1); END IF;
  END IF;
  return_value := 1;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_POList_From_DropBox ====
CREATE OR REPLACE FUNCTION dbo.sp_polist_from_dropbox(srv citext, db citext, owner citext, sitecode integer, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_sitecode integer;
  v_query citext;
  v_prefix citext;
  _dq1 text;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  v_sitecode := sitecode;
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  v_prefix := '';
  IF (((length(rtrim(ltrim(rtrim(v_srv)))) = 0) OR (v_srv IS NULL))) THEN
    v_prefix := '';
  ELSE
    v_prefix := (v_srv || '.');
  END IF;
  IF (((length(rtrim(ltrim(rtrim(v_db)))) = 0) OR (v_db IS NULL))) THEN
    v_prefix := v_prefix;
  ELSE
    v_prefix := ((v_prefix || v_db) || '.');
  END IF;
  IF (((length(rtrim(ltrim(rtrim(v_owner)))) = 0) OR (v_owner IS NULL))) THEN
    v_prefix := ((v_prefix || 'DBO') || '.');
  ELSE
    v_prefix := ((v_prefix || v_owner) || '.');
  END IF;
  v_query := (((('Select SiteCode, Site=(SELECT Site.Name + SPACE(1) + CHAR(45) + SPACE(1) + InstanceID FROM Site WHERE Site.Sitecode = T.SiteCode), T.POCode, T.Date, T.Remarks, T.PurOrderCatCode, T.CustCode From  ' || v_prefix) || 'DB_PurOrderHeader AS T WHERE T.TargetSiteCode = ') || ltrim(rtrim(dbo.tsql_str((v_sitecode)::numeric)))) || ' AND T.Pulled = ''N''');
  _dq1 := v_query;
  IF _dq1 IS NOT NULL THEN
    IF _dq1 ~* '^[[:space:]]*select' THEN OPEN rs1 FOR EXECUTE dbo.tsql_dyn(_dq1); ELSE EXECUTE dbo.tsql_dyn(_dq1); END IF;
  END IF;
  return_value := 1;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_Post_SaleReturn_BillSummary ====
CREATE OR REPLACE FUNCTION dbo.sp_post_salereturn_billsummary(srbufferinvcode integer, usercode integer, billsumm citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srbufferinvcode integer;
  v_usercode integer;
  v_billsumm citext;
  v_saleinvcode integer;
  v_utn integer;
  v_rowid integer;
  v_priority smallint;
  v_icode integer;
  v_gcode integer;
  v_packunits integer;
  v_totalpieces integer;
  v_piecesinhand integer;
  v_looseqty numeric(15,4);
  v_bonusqty numeric(15,4);
  v_totalqty numeric(15,4);
  v_currqty numeric(15,4);
  v_batchqty numeric(15,4);
  v_reqqty numeric(15,4);
  v_newqty numeric(15,4);
  v_total_availablestock numeric(15,4);
  v_price numeric(12,2);
  v_purprice numeric(12,2);
  v_saleprice numeric(12,2);
  v_recentpurprice numeric(12,2);
  v_newavgprice numeric(15,5);
  v_discperc numeric(5,2);
  v_batch citext;
  v_itemname citext;
  v_avgprice numeric(15,5);
  v_items_rows integer;
  v_counter integer;
  v_rowcount integer;
  v_totalrows integer;
  v_continue integer;
  v_err integer;
  v_rt_code integer;
  v_expiry timestamp(3);
  v_updactmon citext;
  cur_cursor_items refcursor;
  _rc integer;
  _fs integer := -1;
BEGIN
  v_srbufferinvcode := srbufferinvcode;
  v_usercode := usercode;
  v_billsumm := billsumm;
  v_continue := 0;
  _rc := 1;
  v_priority := 10;
  _rc := 1;
  OPEN cur_cursor_items FOR SELECT rd.icode, rd.gcode, rd.batch, rd.expiry, rd.looseqty, rd.bonusqty, rd.packunits, rd.srprice, rd.discperc, rd.totalpieces, rd.piecesinhand, rd.rowid, i.name FROM dbo.srbufferledger AS r, dbo.srbufferdetail AS rd, dbo.item AS i WHERE ((((r.srbufferinvcode = v_srbufferinvcode) AND (r.retviabillsummary = v_billsumm)) AND (r.srbufferinvcode = rd.srbufferinvcode)) AND (rd.icode = i.icode)) ORDER BY r.srbufferinvcode, rd.rowid;
  v_items_rows := (-1);
  _rc := 1;
  IF (v_items_rows <= 0) THEN
    RAISE EXCEPTION 'Unable to fetch sale return invoice : %', v_srbufferinvcode;
    CLOSE cur_cursor_items;
    -- DEALLOCATE Cursor_Items
    return_value := -1;
    RETURN;
  END IF;
  FETCH NEXT FROM cur_cursor_items INTO v_icode, v_gcode, v_batch, v_expiry, v_looseqty, v_bonusqty, v_packunits, v_price, v_discperc, v_totalpieces, v_piecesinhand, v_rowid, v_itemname;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    SELECT r.return_value, r.lbi_maxutn INTO v_rt_code, v_utn FROM dbo.sp_maxutn(lbi_rows => (1)::bigint, lbi_maxutn => (v_utn)::bigint) AS r;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      RAISE EXCEPTION 'Error occured in fetching utn ';
      CLOSE cur_cursor_items;
      -- DEALLOCATE Cursor_Items
      return_value := -1;
      RETURN;
    END IF;
    SELECT r.return_value, r.avgprice INTO v_rt_code, v_avgprice FROM dbo.sp_getitemavgprice(icode => v_icode, avgprice => v_avgprice) AS r;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      RAISE EXCEPTION 'Error occured in Fetching Avg Price for Item : %', v_itemname;
      CLOSE cur_cursor_items;
      -- DEALLOCATE Cursor_Items
      return_value := -1;
      RETURN;
    END IF;
    IF (v_batch <> 'due') THEN
      SELECT r.return_value INTO v_rt_code FROM dbo.sp_isactiveitem(icode => v_icode) AS r;
      IF ((0 <> 0) OR (v_rt_code < 0)) THEN
        RAISE EXCEPTION 'Error occured in fetching item status for active Y/N, Item Name : %', v_itemname;
        CLOSE cur_cursor_items;
        -- DEALLOCATE Cursor_Items
        return_value := -1;
        RETURN;
      END IF;
      IF (v_rt_code = 0) THEN
        SELECT r.return_value INTO v_rt_code FROM dbo.sp_setitemactivestatus(icode => v_icode, active => (1)::smallint) AS r;
        IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
          RAISE EXCEPTION 'Error occured in marking item status as active, Item Name : %', v_itemname;
          CLOSE cur_cursor_items;
          -- DEALLOCATE Cursor_Items
          return_value := -1;
          RETURN;
        END IF;
      END IF;
      v_packunits := CASE WHEN (v_packunits IS NULL) THEN 1 WHEN (v_packunits = 0) THEN 1 ELSE v_packunits END;
      _rc := 1;
      SELECT r.return_value, r.qty INTO v_rt_code, v_total_availablestock FROM dbo.sp_getitemstockall(icode => v_icode, qty => v_total_availablestock) AS r;
      SELECT r.return_value, r.qty INTO v_rt_code, v_currqty FROM dbo.sp_getitemstockbatch(gcode => v_gcode, icode => v_icode, batch => v_batch, expiry => v_expiry, qty => v_currqty) AS r;
      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
        RAISE EXCEPTION 'Error occured in fetching batch wise item stock details for Item Name : %', v_itemname;
        CLOSE cur_cursor_items;
        -- DEALLOCATE Cursor_Items
        return_value := -1;
        RETURN;
      END IF;
      v_newqty := ((v_currqty + v_looseqty) + v_bonusqty);
      _rc := 1;
      SELECT r.return_value INTO v_rt_code FROM dbo.sp_updateitemstockbatch(gcode => v_gcode, icode => v_icode, batch => v_batch, expiry => v_expiry, newqty => v_newqty) AS r;
      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
        RAISE EXCEPTION 'Error occured in Updating batch wise item stock details for Item Name : %', v_itemname;
        CLOSE cur_cursor_items;
        -- DEALLOCATE Cursor_Items
        return_value := -1;
        RETURN;
      END IF;
    END IF;
    SELECT r.return_value INTO v_rt_code FROM dbo.sp_getitemtotalpiecesinhand(icode => v_icode, qty => v_piecesinhand) AS r;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      RAISE EXCEPTION 'Error occured in Fetching item wise pieces in hand details for Item Name : %', v_itemname;
      CLOSE cur_cursor_items;
      -- DEALLOCATE Cursor_Items
      return_value := -1;
      RETURN;
    END IF;
    SELECT r.return_value INTO v_rt_code FROM dbo.sp_updateitemtotalpiecesinhand(icode => v_icode, incdec => 1, totalpieces => v_totalpieces) AS r;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      RAISE EXCEPTION 'Error occured in updating item wise pieces in hand details for Item Name : %', v_itemname;
      CLOSE cur_cursor_items;
      -- DEALLOCATE Cursor_Items
      return_value := -1;
      RETURN;
    END IF;
    UPDATE dbo.srbufferdetail SET currstock = v_total_availablestock, avgprice = v_avgprice, srutn = v_utn, piecesinhand = v_piecesinhand WHERE ((srbufferinvcode = v_srbufferinvcode) AND (rowid = v_rowid));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_err := 0;
    v_rowcount := _rc;
    _rc := 1;
    IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
      RAISE EXCEPTION 'Error occured in updating Sale Return Detail of S/R Code : %', v_srbufferinvcode;
      CLOSE cur_cursor_items;
      -- DEALLOCATE Cursor_Items
      return_value := -1;
      RETURN;
    END IF;
    FETCH NEXT FROM cur_cursor_items INTO v_icode, v_gcode, v_batch, v_expiry, v_looseqty, v_bonusqty, v_packunits, v_price, v_discperc, v_totalpieces, v_piecesinhand, v_rowid, v_itemname;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_cursor_items;
  -- DEALLOCATE Cursor_Items
  UPDATE dbo.srbufferledger SET posted = 'Y', postdate = localtimestamp(3), postedby = v_usercode WHERE (((srbufferinvcode = v_srbufferinvcode) AND (posted = 'N')) AND (retviabillsummary = v_billsumm));
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_err := 0;
  v_rowcount := _rc;
  _rc := 1;
  IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
    RAISE EXCEPTION 'Error occured in updation of Sale Return Posting Status, S/R Code : %', v_srbufferinvcode;
    return_value := -1;
    RETURN;
  END IF;
  INSERT INTO dbo.srledger (srinvcode, saleinvcode, date, srcatcode, custcode, salesmancode, discperc, flatdisc, misccharges, posted, postdate, remarks, salestax, originaldate, modifiedby, postedby, headerno, invgstperc1, smancode, custrefno, custrefno2, custrefno3, custrefno4, patientcode, machinename, headerinvno, admissioncode, invtotal, accountfor, paymentmode, paymentacccode, amt, amtby, amtdate, amtreference, outstandingamt, marked, pagesize, reprintingcounter, doctcode, considerinpo, cashacccode, cashtendered, cashcharged, cashback, retviabillsummary) SELECT srbufferinvcode, saleinvcode, date, srcatcode, custcode, salesmancode, discperc, flatdisc, misccharges, posted, postdate, remarks, salestax, originaldate, modifiedby, postedby, headerno, invgstperc1, smancode, custrefno, custrefno2, custrefno3, custrefno4, patientcode, machinename, headerinvno, admissioncode, invtotal, accountfor, paymentmode, paymentacccode, amt, amtby, amtdate, amtreference, outstandingamt, marked, pagesize, 0 AS reprintingcounter, NULL::smallint AS doctcode, 'Y' AS considerinpo, cashacccode, cashtendered, cashcharged, cashback, retviabillsummary FROM dbo.srbufferledger WHERE ((srbufferinvcode = v_srbufferinvcode) AND (retviabillsummary = v_billsumm));
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_err := 0;
  v_rowcount := _rc;
  _rc := 1;
  IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
    RAISE EXCEPTION 'Error occured in Inserting Sale Return Buffer Record into Sales Return Ledger For S/R Code : %', v_srbufferinvcode;
    return_value := -1;
    RETURN;
  END IF;
  INSERT INTO dbo.srdetail (srinvcode, icode, gcode, batch, expiry, packqty, looseqty, packunits, srprice, discperc, salestax, avgprice, unitsalestax, gstperc, srutn, bonusqty, salerowid, returnitemdescription, totalpieces, piecesinhand, currstock) SELECT srbufferinvcode, icode, gcode, batch, expiry, trunc(packqty)::integer, looseqty, packunits, srprice, discperc, salestax, avgprice, unitsalestax, gstperc, srutn, bonusqty, salerowid, returnitemdescription, totalpieces, piecesinhand, currstock FROM dbo.srbufferdetail WHERE (srbufferinvcode = v_srbufferinvcode);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_err := 0;
  v_rowcount := _rc;
  _rc := 1;
  IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
    RAISE EXCEPTION 'Error occured in Inserting Sale Return Buffer Detail Record into Sales Return Detail Ledger For S/R Code : %', v_srbufferinvcode;
    return_value := -1;
    RETURN;
  END IF;
  v_saleinvcode := (SELECT saleinvcode FROM dbo.srbufferledger WHERE ((retviabillsummary = v_billsumm) AND (srbufferinvcode = v_srbufferinvcode)));
  _rc := 1;
  IF (v_saleinvcode > 0) THEN
    UPDATE dbo.saleledger SET returncounter = (returncounter + 1) WHERE (saleinvcode = v_saleinvcode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_err := 0;
    v_rowcount := _rc;
    _rc := 1;
    IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
      RAISE EXCEPTION 'Error occured in updating Sale Invoice For Return Counter, Sale Inv. Code : %', v_saleinvcode;
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  v_updactmon := (SELECT dbo.fn_getpreference('IncSRInActMonitor') AS a);
  _rc := 1;
  IF ((upper(v_updactmon))::citext = 'Y') THEN
    SELECT r.return_value INTO v_rt_code FROM dbo.sp_updateactivitymonitor(documenttype => 'SR', documentcode => v_srbufferinvcode) AS r;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      RAISE EXCEPTION 'Error occured in updating Activity Monitor For Sale Return Code : %', v_srbufferinvcode;
      CLOSE cur_cursor_items;
      -- DEALLOCATE Cursor_Items
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_PostAdjLedger ====
CREATE OR REPLACE FUNCTION dbo.sp_postadjledger(ai_sinvcode integer, ai_linvcode integer, ai_prcatcode1 integer, ai_salesmancode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_sinvcode integer;
  v_ai_linvcode integer;
  v_ai_prcatcode1 integer;
  v_ai_salesmancode integer;
BEGIN
  v_ai_sinvcode := ai_sinvcode;
  v_ai_linvcode := ai_linvcode;
  v_ai_prcatcode1 := ai_prcatcode1;
  v_ai_salesmancode := ai_salesmancode;
  UPDATE dbo.adjheader SET posted = 'Y', posteddate = localtimestamp(3), postedby = v_ai_salesmancode WHERE (((adjheader.adjcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (adjheader.adjcatcode = v_ai_prcatcode1)) AND (adjheader.posted = 'N'));
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_PostAdvSaleLedger ====
CREATE OR REPLACE FUNCTION dbo.sp_postadvsaleledger(ai_sinvcode integer, ai_linvcode integer, ai_salesmancode integer, ai_custcode integer, ai_oneorall integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_sinvcode integer;
  v_ai_linvcode integer;
  v_ai_salesmancode integer;
  v_ai_custcode integer;
  v_ai_oneorall integer;
  v_advsaleinvcode integer;
BEGIN
  v_ai_sinvcode := ai_sinvcode;
  v_ai_linvcode := ai_linvcode;
  v_ai_salesmancode := ai_salesmancode;
  v_ai_custcode := ai_custcode;
  v_ai_oneorall := ai_oneorall;
  v_advsaleinvcode := v_ai_sinvcode;
  IF (v_ai_oneorall = 0) THEN
    UPDATE dbo.advsaleledger SET posted = 'Y', postdate = localtimestamp(3), postedby = v_ai_salesmancode WHERE ((((advsaleledger.advsaleinvcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (advsaleledger.custcode = v_ai_custcode)) AND (advsaleledger.posted = 'N')) AND (advsaleledger.deleted = 'N'));
  ELSE
    UPDATE dbo.advsaleledger SET posted = 'Y', postdate = localtimestamp(3), postedby = v_ai_salesmancode WHERE (((advsaleledger.advsaleinvcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (advsaleledger.posted = 'N')) AND (advsaleledger.deleted = 'N'));
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_PostBillSummary ====
CREATE OR REPLACE FUNCTION dbo.sp_postbillsummary(billsummcode1 integer, billsummcode2 integer, usercode integer, billsumm citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_billsummcode1 integer;
  v_billsummcode2 integer;
  v_usercode integer;
  v_billsumm citext;
  v_billsummtopost integer;
  v_totrows integer;
  v_billsummarycode integer;
  v_srbufferinvcode integer;
  v_srinvcode integer;
  v_srallocationcode integer;
  v_err integer;
  v_rt_code integer;
  v_saleinvcode integer;
  v_returnsaleinvoice integer;
  v_rowid integer;
  v_cashamt numeric(15,2);
  v_chequeamt numeric(15,2);
  v_debitnoteamt numeric(15,2);
  v_creditnoteamt numeric(15,2);
  v_saleinvbalance numeric(15,2);
  v_returnamt numeric(15,2);
  v_newbalance numeric(15,2);
  cur_c_bsr refcursor;
  _rc integer;
  _fs integer := -1;
BEGIN
  v_billsummcode1 := billsummcode1;
  v_billsummcode2 := billsummcode2;
  v_usercode := usercode;
  v_billsumm := billsumm;
  DROP TABLE IF EXISTS tmp_returnlist;
  CREATE TEMP TABLE tmp_returnlist (
    billsummarycode integer,
    saleinvcode integer,
    srinvcode integer,
    rowid integer GENERATED BY DEFAULT AS IDENTITY
) ON COMMIT DROP;
  v_billsummtopost := coalesce((SELECT count(b.billsummarycode) FROM dbo.billsummary AS b WHERE (((b.billsummarycode BETWEEN v_billsummcode1 AND v_billsummcode2) AND (b.posted = 'N')) AND (b.finalized = 'Y'))), 0);
  _rc := 1;
  IF (v_billsummtopost > 0) THEN
    SELECT r.return_value INTO v_rt_code FROM dbo.sp_generate_billsummary_vouchers(billsummcode1 => v_billsummcode1, billsummcode2 => v_billsummcode2, usercode => v_usercode) AS r;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      DROP TABLE IF EXISTS tmp_returnlist;
      return_value := -1;
      RETURN;
    END IF;
    OPEN cur_c_bsr FOR SELECT DISTINCT b.billsummarycode, d.saleinvcode, d.srbufferinvcode FROM dbo.billsummary AS b, dbo.billsummarydetail AS d, dbo.srbufferledger AS sr WHERE ((((((((b.billsummarycode BETWEEN v_billsummcode1 AND v_billsummcode2) AND (b.posted = 'N')) AND (b.finalized = 'Y')) AND (b.billsummarycode = d.billsummarycode)) AND (d.srbufferinvcode IS NOT NULL)) AND (sr.posted = 'N')) AND (sr.srbufferinvcode = d.srbufferinvcode)) AND (sr.retviabillsummary = v_billsumm)) ORDER BY b.billsummarycode, d.srbufferinvcode;
    v_totrows := (-1);
    _rc := 1;
    IF (v_totrows <= 0) THEN
      CLOSE cur_c_bsr;
      -- DEALLOCATE C_BSR
    ELSE
      FETCH NEXT FROM cur_c_bsr INTO v_billsummarycode, v_saleinvcode, v_srbufferinvcode;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
      WHILE (_fs = 0) LOOP
        SELECT r.return_value INTO v_rt_code FROM dbo.sp_post_salereturn_billsummary(srbufferinvcode => v_srbufferinvcode, usercode => v_usercode, billsumm => v_billsumm) AS r;
        IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
          RAISE EXCEPTION 'Error occured in Posting sales return code : %, Bill Summary Code: %', v_srbufferinvcode, v_billsummarycode;
          CLOSE cur_c_bsr;
          -- DEALLOCATE C_BSR
          DROP TABLE IF EXISTS tmp_returnlist;
          return_value := -1;
          RETURN;
        END IF;
        INSERT INTO tmp_returnlist (billsummarycode, saleinvcode, srinvcode) VALUES (v_billsummarycode, v_saleinvcode, v_srbufferinvcode);
        GET DIAGNOSTICS _rc = ROW_COUNT;
        FETCH NEXT FROM cur_c_bsr INTO v_billsummarycode, v_saleinvcode, v_srbufferinvcode;
        IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
      END LOOP;
      CLOSE cur_c_bsr;
      -- DEALLOCATE C_BSR
    END IF;
    UPDATE dbo.billsummary SET posted = 'Y', postedby = v_usercode, postdate = localtimestamp(3) WHERE (((billsummarycode BETWEEN v_billsummcode1 AND v_billsummcode2) AND (posted = 'N')) AND (finalized = 'Y'));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((0 <> 0) OR (_rc = 0)) THEN
      RAISE EXCEPTION 'Error occured in Posting of Bill Summary Range: [% TO %]', v_billsummcode1, v_billsummcode2;
      DROP TABLE IF EXISTS tmp_returnlist;
      return_value := -1;
      RETURN;
    END IF;
    v_rowid := 1;
    _rc := 1;
    v_totrows := (SELECT count(*) FROM tmp_returnlist AS returnlist);
    _rc := 1;
    IF (v_totrows > 0) THEN
      WHILE (v_rowid <= v_totrows) LOOP
        v_billsummarycode := (SELECT billsummarycode FROM tmp_returnlist AS returnlist WHERE (rowid = v_rowid));
        _rc := 1;
        v_saleinvcode := (SELECT saleinvcode FROM tmp_returnlist AS returnlist WHERE (rowid = v_rowid));
        _rc := 1;
        v_srinvcode := (SELECT srinvcode FROM tmp_returnlist AS returnlist WHERE (rowid = v_rowid));
        _rc := 1;
        v_returnsaleinvoice := (SELECT saleinvcode FROM dbo.srledger WHERE (srinvcode = v_srinvcode));
        _rc := 1;
        IF ((((v_billsummarycode > 0) AND (v_srinvcode > 0)) AND (v_saleinvcode > 0)) AND (v_saleinvcode = v_returnsaleinvoice)) THEN
          SELECT r.return_value, r.srallocationcode INTO v_rt_code, v_srallocationcode FROM dbo.sp_allocatesalereturn(srinvcode => v_srinvcode, saleinvcode => v_saleinvcode, usercode => (v_usercode)::smallint, srallocationcode => v_srallocationcode) AS r;
          IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
            RAISE EXCEPTION 'Error occured while allocating Sale Return Invoice: %, against Sales Invoice: % on Posting of Bill Summary: %', v_srinvcode, v_saleinvcode, v_billsummarycode;
            DROP TABLE IF EXISTS tmp_returnlist;
            return_value := -1;
            RETURN;
          END IF;
        END IF;
        v_rowid := (v_rowid + 1);
        _rc := 1;
      END LOOP;
    END IF;
  END IF;
  DROP TABLE IF EXISTS tmp_returnlist;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_PostedPurAndReturnCategoryWise ====
CREATE OR REPLACE FUNCTION dbo.sp_postedpurandreturncategorywise(ad_date timestamp, ad_ldate timestamp, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ad_date timestamp(3);
  v_ad_ldate timestamp(3);
BEGIN
  v_ad_date := ad_date;
  v_ad_ldate := ad_ldate;
  DELETE FROM dbo.reportdata;
  INSERT INTO dbo.reportdata (code1, name1, value1, value2, value4, value5) SELECT a.icatcode, (SELECT name FROM dbo.itemcategory WHERE (icatcode = a.icatcode)) AS catname, (SELECT coalesce(sum(round(((((((pd.looseqty + pd.packqty)) * pd.purprice)) * ((1 - ((.01 * pd.discperc))))))::numeric, 2)), 0) FROM dbo.purdetail AS pd, dbo.purledger AS pl, dbo.item AS i WHERE (((((pl.date BETWEEN v_ad_date AND v_ad_ldate) AND (pl.posted = 'Y')) AND (pl.purinvcode = pd.purinvcode)) AND (pd.icode = i.icode)) AND (i.icatcode = a.icatcode))) AS purvalue, (SELECT coalesce(sum(round(((((((prd.looseqty + prd.packqty)) * prd.prprice)) * ((1 - ((.01 * prd.discperc))))))::numeric, 2)), 0) FROM dbo.prdetail AS prd, dbo.prledger AS prl, dbo.item AS i WHERE (((((prl.date BETWEEN v_ad_date AND v_ad_ldate) AND (prl.posted = 'Y')) AND (prl.prinvcode = prd.prinvcode)) AND (prd.icode = i.icode)) AND (i.icatcode = a.icatcode))) AS prvalue, (SELECT coalesce(sum(round((((((pd.looseqty + ((pd.packqty * pd.packunits)))) * ((pd.saleprice / CASE pd.packunits WHEN 0 THEN 1 ELSE pd.packunits END)))))::numeric, 2)), 0) FROM dbo.purdetail AS pd, dbo.purledger AS pl, dbo.item AS i WHERE (((((pl.date BETWEEN v_ad_date AND v_ad_ldate) AND (pl.posted = 'Y')) AND (pl.purinvcode = pd.purinvcode)) AND (pd.icode = i.icode)) AND (i.icatcode = a.icatcode))) AS pursalevalue, (SELECT coalesce(sum(round((((((prd.looseqty + prd.packqty)) * ((prd.packsaleprice / CASE prd.packunits WHEN 0 THEN 1 ELSE prd.packunits END)))))::numeric, 2)), 0) FROM dbo.prdetail AS prd, dbo.prledger AS prl, dbo.item AS i WHERE (((((prl.date BETWEEN v_ad_date AND v_ad_ldate) AND (prl.posted = 'Y')) AND (prl.prinvcode = prd.prinvcode)) AND (prd.icode = i.icode)) AND (i.icatcode = a.icatcode))) AS prsalevalue FROM (SELECT DISTINCT (item.icatcode) AS icatcode FROM dbo.purdetail, dbo.purledger, dbo.item WHERE (((purledger.date BETWEEN v_ad_date AND v_ad_ldate) AND (purledger.purinvcode = purdetail.purinvcode)) AND (purdetail.icode = item.icode)) UNION SELECT DISTINCT (item.icatcode) AS icatcode FROM dbo.prdetail, dbo.prledger, dbo.item WHERE (((prledger.date BETWEEN v_ad_date AND v_ad_ldate) AND (prledger.prinvcode = prdetail.prinvcode)) AND (prdetail.icode = item.icode))) AS a;
  UPDATE dbo.reportdata SET value3 = (value1 - value2);
  -- COMMIT (the caller owns the transaction)
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_PostEmployeeAdvance ====
CREATE OR REPLACE FUNCTION dbo.sp_postemployeeadvance(ai_startcode integer, ai_endcode integer, ai_usercode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_startcode integer;
  v_ai_endcode integer;
  v_ai_usercode integer;
  v_rc integer;
  v_rowid integer;
  v_totrows integer;
  v_advancecode integer;
  v_ai_vochcatcode integer;
  v_ai_acccode integer;
  v_ad_date timestamp(3);
  v_ai_salesmancode integer;
  v_as_posted citext;
  v_ad_postdate timestamp(3);
  v_as_remarks citext;
  v_ad_originaldate timestamp(3);
  v_ai_modifiedby integer;
  v_ai_postedby integer;
  v_as_chkno citext;
  v_ai_dr_acccode integer;
  v_ai_cr_acccode integer;
  v_an_amount numeric(15,2);
  v_as_chkno_detail citext;
  v_as_remarks_detail citext;
  v_ai_patientcode integer;
  v_ai_guestcode integer;
  v_ai_studentcode integer;
  v_ai_invoicecode integer;
  v_an_outstandingamt numeric(15,2);
  v_an_balance numeric(15,2);
  v_glvochcode integer;
  v_vochcode integer;
  v_smancode smallint;
  _r1 record;
BEGIN
  v_ai_startcode := ai_startcode;
  v_ai_endcode := ai_endcode;
  v_ai_usercode := ai_usercode;
  -- SET NOCOUNT ON
  DROP TABLE IF EXISTS tmp_lt_list;
  CREATE TEMP TABLE tmp_lt_list (
    code integer NOT NULL,
    rowid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_list (code) SELECT advancecode FROM dbo.emp_advance WHERE ((posted = 'N') AND (advancecode BETWEEN v_ai_startcode AND v_ai_endcode));
  v_rowid := 1;
  v_totrows := coalesce((SELECT count(*) FROM tmp_lt_list AS lt_list), 0);
  WHILE (v_rowid <= v_totrows) LOOP
    v_advancecode := (SELECT code FROM tmp_lt_list AS lt_list WHERE (rowid = v_rowid));
    FOR _r1 IN SELECT 'Y' AS c1, 5 AS c2, 2 AS c3, 5 AS c4, 2 AS c5, date AS c6, date AS c7, remarks AS c8, date AS c9, NULL AS c10, NULL AS c11, refno AS c12, empadvacccode AS c13, acccode AS c14, amount AS c15, refno AS c16, remarks AS c17, NULL AS c18, NULL AS c19, NULL AS c20, NULL AS c21, 0.00 AS c22, 0.00 AS c23, NULL AS c24, v_ai_usercode AS c25, NULL AS c26, NULL AS c27 FROM dbo.emp_advance WHERE ((advancecode = v_advancecode) AND (posted = 'N')) LOOP
      v_as_posted := _r1.c1;
      v_ai_vochcatcode := _r1.c2;
      v_ai_acccode := _r1.c3;
      v_ai_vochcatcode := _r1.c4;
      v_ai_acccode := _r1.c5;
      v_ad_date := _r1.c6;
      v_ad_postdate := _r1.c7;
      v_as_remarks := _r1.c8;
      v_ad_originaldate := _r1.c9;
      v_ai_modifiedby := _r1.c10;
      v_ai_postedby := _r1.c11;
      v_as_chkno := _r1.c12;
      v_ai_dr_acccode := _r1.c13;
      v_ai_cr_acccode := _r1.c14;
      v_an_amount := _r1.c15;
      v_as_chkno_detail := _r1.c16;
      v_as_remarks_detail := _r1.c17;
      v_ai_patientcode := _r1.c18;
      v_ai_guestcode := _r1.c19;
      v_ai_studentcode := _r1.c20;
      v_ai_invoicecode := _r1.c21;
      v_an_outstandingamt := _r1.c22;
      v_an_balance := _r1.c23;
      v_smancode := _r1.c24;
      v_ai_salesmancode := _r1.c25;
      v_glvochcode := _r1.c26;
      v_vochcode := _r1.c27;
    END LOOP;
    SELECT r.return_value, r.glvochcode, r.vochcode INTO v_rc, v_glvochcode, v_vochcode FROM dbo.sp_createvoucher(ai_vochcatcode => v_ai_vochcatcode, ai_acccode => v_ai_acccode, ad_date => v_ad_date, ai_salesmancode => v_ai_salesmancode, as_posted => v_as_posted, ad_postdate => v_ad_postdate, as_remarks => v_as_remarks, ad_originaldate => v_ad_originaldate, ai_modifiedby => v_ai_modifiedby, ai_postedby => v_ai_postedby, as_chkno => v_as_chkno, ai_dr_acccode => v_ai_dr_acccode, ai_cr_acccode => v_ai_cr_acccode, an_amount => v_an_amount, as_chkno_detail => v_as_chkno_detail, as_remarks_detail => v_as_remarks_detail, ai_patientcode => v_ai_patientcode, ai_guestcode => v_ai_guestcode, ai_studentcode => v_ai_studentcode, ai_invoicecode => v_ai_invoicecode, an_outstandingamt => v_an_outstandingamt, an_balance => v_an_balance, glvochcode => v_glvochcode, vochcode => v_vochcode, smancode => v_smancode) AS r;
    IF ((0 <> 0) OR (v_rc <> 0)) THEN
      RAISE EXCEPTION 'Unable to Add Loyalty Points for Customer on Sale Posting';
      return_value := -1;
      RETURN;
    END IF;
    UPDATE dbo.emp_advance SET glvochcode = v_glvochcode, posted = 'Y', postedon = localtimestamp(3), postedby = v_ai_usercode WHERE ((posted = 'N') AND (advancecode = v_advancecode));
    v_rowid := (v_rowid + 1);
  END LOOP;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_PostGeneralLedger ====
CREATE OR REPLACE FUNCTION dbo.sp_postgeneralledger(ai_sinvcode integer, ai_linvcode integer, ai_vouchertype integer, ai_salesmancode integer, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_sinvcode integer;
  v_ai_linvcode integer;
  v_ai_vouchertype integer;
  v_ai_salesmancode integer;
  v_rowid integer;
  v_totrows integer;
  v_rt_code integer;
  v_glvochcode integer;
  v_ai_list citext;
BEGIN
  v_ai_sinvcode := ai_sinvcode;
  v_ai_linvcode := ai_linvcode;
  v_ai_vouchertype := ai_vouchertype;
  v_ai_salesmancode := ai_salesmancode;
  DROP TABLE IF EXISTS tmp_lt_list;
  CREATE TEMP TABLE tmp_lt_list (
    code integer NOT NULL,
    rowid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_list (code) SELECT glvochcode FROM dbo.glheader WHERE (((glheader.glvochcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (glheader.vochcatcode = v_ai_vouchertype)) AND (glheader.posted = 'N'));
  UPDATE dbo.glheader SET posted = 'Y', postdate = localtimestamp(3), postedby = v_ai_salesmancode WHERE (((glheader.glvochcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (glheader.vochcatcode = v_ai_vouchertype)) AND (glheader.posted = 'N'));
  v_rowid := 1;
  v_totrows := coalesce((SELECT count(*) FROM tmp_lt_list AS lt_list), 0);
  v_ai_list := '';
  WHILE (v_rowid <= v_totrows) LOOP
    v_glvochcode := (SELECT code FROM tmp_lt_list AS lt_list WHERE (rowid = v_rowid));
    v_ai_list := ((coalesce(v_ai_list, '') || ltrim(rtrim(dbo.tsql_str((v_glvochcode)::numeric, 10)))) || ',');
    v_rowid := (v_rowid + 1);
  END LOOP;
  IF ((right(v_ai_list, 1))::citext = ',') THEN
    v_ai_list := left(v_ai_list, (length(rtrim(v_ai_list)) - 1));
  END IF;
  IF (length(rtrim(v_ai_list)) > 0) THEN
    SELECT r.return_value, r.rs1 INTO v_rt_code, rs1 FROM dbo.sp_createautotriggersms(ai_list => v_ai_list, ai_moduleid => (45)::smallint, ai_event => 'Posting') AS r;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      RAISE EXCEPTION 'Unable to Create Auto Trigger SMS on Voucher Posting';
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_PostInstallment ====
CREATE OR REPLACE FUNCTION dbo.sp_postinstallment(installmentcode integer, usercode smallint, INOUT saleinvcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_installmentcode integer;
  v_usercode smallint;
  v_saleinvcode integer;
  v_custcode smallint;
  v_gcode smallint;
  v_icode integer;
  v_packunits integer;
  v_headerno smallint;
  v_rowgroup integer;
  v_innercounter integer;
  v_saleprice numeric(12,2);
  v_rate numeric(12,2);
  v_discperc numeric(5,2);
  v_itemflatdisc numeric(12,2);
  v_salecatcode smallint;
  v_saletypecode smallint;
  v_unitsalestax numeric(12,2);
  v_gstperc1 numeric(6,2);
  v_gstperc2 numeric(6,2);
  v_hold_avgprice numeric(15,5);
  v_satisfiableqty numeric(15,4);
  v_satisfiedqty numeric(15,4);
  v_markupamt numeric(10,2);
  v_processingfee numeric(10,2);
  v_downpayment numeric(10,2);
  v_module integer;
  v_headerinvno integer;
  v_continue integer;
  v_rt_code integer;
  v_err integer;
  v_totalrows integer;
  v_rowcount integer;
  v_counter integer;
  v_totalqty numeric(15,4);
  v_givenqty numeric(15,4);
  v_reqqty numeric(15,4);
  v_batchqty numeric(15,4);
  v_delqty numeric(15,4);
  v_currqty numeric(15,4);
  v_newqty numeric(15,4);
  v_total_availablestock numeric(15,4);
  v_netamount numeric(12,2);
  v_batch citext;
  v_itemname citext;
  v_expiry timestamp(3);
  v_serverdate timestamp(3);
  v_machinename citext;
  v_saleutn bigint;
  v_smancode smallint;
  v_inquirypersoncode smallint;
  _r1 record;
  _r2 record;
  cur_itembatch_cursor refcursor;
  _rc integer;
  _fs integer := -1;
BEGIN
  v_installmentcode := installmentcode;
  v_usercode := usercode;
  v_saleinvcode := saleinvcode;
  v_module := (SELECT module FROM dbo.module WHERE (name = 'Sales'));
  _rc := 1;
  v_headerno := 1;
  _rc := 1;
  v_machinename := current_setting('cluster_name', true);
  _rc := 1;
  v_salecatcode := 2;
  _rc := 1;
  v_saletypecode := (SELECT min(saletypecode) FROM dbo.saletype);
  _rc := 1;
  v_serverdate := localtimestamp(3);
  _rc := 1;
  _rc := 0;
  FOR _r1 IN SELECT custcode AS c1, gcode AS c2, icode AS c3, packunits AS c4, qty AS c5, saleprice AS c6, itemflatdisc AS c7, discperc AS c8, markupamt AS c9, processingfee AS c10, downpayment AS c11, round((((round(((((qty * ((saleprice - itemflatdisc))) * ((1 - (discperc * 0.01))))))::numeric, 2) + markupamt) + processingfee))::numeric, 0) AS c12, smancode AS c13, inquirypersoncode AS c14 FROM dbo.installmentheader WHERE (((installmentcode = v_installmentcode) AND (posted = 'N')) AND (approved = 'Y')) LOOP
    _rc := _rc + 1;
    v_custcode := _r1.c1;
    v_gcode := _r1.c2;
    v_icode := _r1.c3;
    v_packunits := _r1.c4;
    v_satisfiableqty := _r1.c5;
    v_satisfiedqty := 0;
    v_saleprice := _r1.c6;
    v_itemflatdisc := _r1.c7;
    v_discperc := _r1.c8;
    v_unitsalestax := 0;
    v_gstperc1 := 0;
    v_markupamt := _r1.c9;
    v_processingfee := _r1.c10;
    v_downpayment := _r1.c11;
    v_itemname := (SELECT i.name FROM dbo.item AS i WHERE (i.icode = v_icode));
    v_netamount := _r1.c12;
    v_smancode := _r1.c13;
    v_inquirypersoncode := _r1.c14;
  END LOOP;
  v_totalrows := _rc;
  _rc := 1;
  IF (v_totalrows = 0) THEN
    RAISE EXCEPTION 'Installment code : % is not available for posting', v_installmentcode;
    return_value := -1;
    saleinvcode := v_saleinvcode;
    RETURN;
  END IF;
  IF (v_satisfiableqty = 0) THEN
    v_satisfiableqty := 1;
    _rc := 1;
  END IF;
  v_saleprice := round(((v_netamount / v_satisfiableqty))::numeric, 2);
  _rc := 1;
  v_continue := 0;
  _rc := 1;
  v_rowgroup := 0;
  _rc := 1;
  v_totalqty := (SELECT coalesce(sum(currqty), 0) FROM dbo.godowndetail WHERE ((godowndetail.gcode = v_gcode) AND (godowndetail.icode = v_icode)));
  _rc := 1;
  IF (v_totalqty < v_satisfiableqty) THEN
    RAISE EXCEPTION 'Not Enough Stock exists for this item : % to sale against Installment code : %', v_itemname, v_installmentcode;
    return_value := -1;
    saleinvcode := v_saleinvcode;
    RETURN;
  END IF;
  SELECT r.return_value, r.key INTO v_rt_code, v_saleinvcode FROM dbo.sp_gettabmaxkey(tabname => 'Saleledger', key => v_saleinvcode) AS r;
  v_rowgroup := 0;
  _rc := 1;
  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
    RAISE EXCEPTION 'Error in Generating Sale Invoice No. against Installment code : %', v_installmentcode;
    return_value := -1;
    saleinvcode := v_saleinvcode;
    RETURN;
  END IF;
  SELECT r.return_value, r.key INTO v_rt_code, v_headerinvno FROM dbo.sp_getheadertabmaxkey(headercode => v_headerno, modulecode => (v_module)::smallint, key => v_headerinvno) AS r;
  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
    RAISE EXCEPTION 'Error in Generating Header Sale Invoice No. against Installment code : %', v_installmentcode;
    return_value := -1;
    saleinvcode := v_saleinvcode;
    RETURN;
  END IF;
  v_err := 0;
  _rc := 1;
  v_rowcount := 1;
  _rc := 1;
  INSERT INTO dbo.saleledger (saleinvcode, salecatcode, custcode, sprice, salesmancode, date, discperc, flatdisc, misccharges, salestax, posted, postdate, headerno, headerinvno, originaldate, invtotal, machinename, modifycounter, billingdate, saletypecode, cashacccode, cashtendered, cashcharged, cashback, outstandingamt, smancode, deliveredby) VALUES (v_saleinvcode, v_salecatcode, v_custcode, 1, v_usercode, v_serverdate, 0, 0, 0, 0, 'Y', v_serverdate, v_headerno, v_headerinvno, v_serverdate, v_netamount, v_machinename, 0, v_serverdate, v_saletypecode, 2, v_downpayment, v_downpayment, 0, (v_netamount - v_downpayment), v_smancode, v_inquirypersoncode);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_err := 0;
  v_rowcount := _rc;
  _rc := 1;
  IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
    RAISE EXCEPTION 'Error occured in inserting record into Sale Ledger : %', v_saleinvcode;
    return_value := -1;
    saleinvcode := v_saleinvcode;
    RETURN;
  END IF;
  IF (v_satisfiedqty > v_satisfiableqty) THEN
    RAISE EXCEPTION 'Qty Satisfied Exceeded Required Qty for item : %', v_itemname;
    return_value := -1;
    saleinvcode := v_saleinvcode;
    RETURN;
  END IF;
  SELECT r.return_value, r.avgprice INTO v_rt_code, v_hold_avgprice FROM dbo.sp_getitemavgprice(icode => v_icode, avgprice => v_hold_avgprice) AS r;
  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
    RAISE EXCEPTION 'Error in Fetching Avg. Price for item : %', v_itemname;
    return_value := -1;
    saleinvcode := v_saleinvcode;
    RETURN;
  END IF;
  SELECT r.return_value, r.qty INTO v_rt_code, v_total_availablestock FROM dbo.sp_getitemstockall(icode => v_icode, qty => v_total_availablestock) AS r;
  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
    return_value := -1;
    saleinvcode := v_saleinvcode;
    RETURN;
  END IF;
  v_givenqty := v_satisfiableqty;
  _rc := 1;
  v_totalqty := (SELECT coalesce(sum(currqty), 0) FROM dbo.godowndetail WHERE ((godowndetail.gcode = v_gcode) AND (godowndetail.icode = v_icode)));
  _rc := 1;
  IF (v_totalqty >= v_givenqty) THEN
    v_rowgroup := (v_rowgroup + 1);
    _rc := 1;
    _rc := 0;
    FOR _r2 IN SELECT saleprice AS c1, packunits AS c2 FROM dbo.item WHERE (icode = v_icode) LOOP
      _rc := _rc + 1;
      v_rate := _r2.c1;
      v_packunits := _r2.c2;
    END LOOP;
    IF ((v_packunits = 0) OR (v_packunits IS NULL)) THEN
      v_packunits := 1;
      _rc := 1;
    END IF;
    v_reqqty := v_givenqty;
    _rc := 1;
    OPEN cur_itembatch_cursor FOR SELECT batch, expiry, currqty FROM dbo.godowndetail WHERE ((godowndetail.gcode = v_gcode) AND (godowndetail.icode = v_icode)) ORDER BY priority, expiry, currqty;
    v_totalrows := (-1);
    _rc := 1;
    FETCH NEXT FROM cur_itembatch_cursor INTO v_batch, v_expiry, v_currqty;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    v_counter := 1;
    _rc := 1;
    WHILE ((((_fs = 0) AND (v_counter <= v_totalrows)) AND (v_reqqty > 0)) AND (v_continue <> -1)) LOOP
      v_batchqty := v_currqty;
      _rc := 1;
      IF (v_batchqty >= v_reqqty) THEN
        v_delqty := v_reqqty;
        _rc := 1;
      ELSE
        v_delqty := v_batchqty;
        _rc := 1;
      END IF;
      v_reqqty := (v_reqqty - v_delqty);
      _rc := 1;
      SELECT r.return_value, r.lbi_maxutn INTO v_rt_code, v_saleutn FROM dbo.sp_maxutn(lbi_rows => (1)::bigint, lbi_maxutn => v_saleutn) AS r;
      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
        v_continue := -1;
        _rc := 1;
      END IF;
      v_total_availablestock := (v_total_availablestock - v_delqty);
      _rc := 1;
      INSERT INTO dbo.saledetail (saleinvcode, icode, gcode, batch, expiry, packqty, looseqty, packunits, saleprice, avgprice, rate, discperc, salestax, itemflatdisc, packprice, unitsalestax, gstperc, saleutn, balancestock, rowgroup) VALUES (v_saleinvcode, v_icode, v_gcode, v_batch, v_expiry, 0, v_delqty, v_packunits, v_saleprice, v_hold_avgprice, (v_rate / v_packunits), 0, 0, 0, v_rate, v_unitsalestax, v_gstperc1, v_saleutn, v_total_availablestock, v_rowgroup);
      GET DIAGNOSTICS _rc = ROW_COUNT;
      v_err := 0;
      v_rowcount := _rc;
      _rc := 1;
      IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
        RAISE EXCEPTION 'Error occured in inserting record into Sale Detail for Sale Inv. No. : %', v_saleinvcode;
        v_continue := -1;
        _rc := 1;
      ELSE
        v_newqty := (v_currqty - v_delqty);
        _rc := 1;
        IF (v_newqty > 0) THEN
          SELECT r.return_value INTO v_rt_code FROM dbo.sp_saleupdateitemstockbatch(gcode => (v_gcode)::integer, icode => v_icode, batch => v_batch, expiry => v_expiry, newqty => v_newqty, oldqty => v_currqty) AS r;
        ELSE
          SELECT r.return_value INTO v_rt_code FROM dbo.sp_deleteitemstockbatch(gcode => (v_gcode)::integer, icode => v_icode, batch => v_batch, expiry => v_expiry, oldqty => v_delqty) AS r;
        END IF;
        IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
          v_continue := -1;
          _rc := 1;
        END IF;
      END IF;
      v_counter := (v_counter + 1);
      _rc := 1;
      FETCH NEXT FROM cur_itembatch_cursor INTO v_batch, v_expiry, v_currqty;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    END LOOP;
    CLOSE cur_itembatch_cursor;
    -- DEALLOCATE ItemBatch_Cursor
  ELSE
    RAISE EXCEPTION 'Not enough stock for item (%) to decrease for Sale Inv. No : %', v_itemname, v_saleinvcode;
    v_continue := -1;
    _rc := 1;
  END IF;
  IF ((v_continue >= 0)) THEN
    UPDATE dbo.installmentheader SET posted = 'Y', postedby = v_usercode, postdate = localtimestamp(3), saleinvcode = v_saleinvcode WHERE (installmentcode = v_installmentcode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_err := 0;
    v_rowcount := _rc;
    _rc := 1;
    IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
      RAISE EXCEPTION 'Unable to update Installment staus from Not Posted To Posted For Installment Code : %', v_installmentcode;
      v_continue := -1;
      _rc := 1;
    END IF;
  END IF;
  return_value := v_continue;
  saleinvcode := v_saleinvcode;
  RETURN;
  return_value := 0;
  saleinvcode := v_saleinvcode;
  RETURN;
END
$body$;

-- ==== proc sp_PostIssue_From_Production ====
CREATE OR REPLACE FUNCTION dbo.sp_postissue_from_production(prodcode integer, usercode smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_prodcode integer;
  v_usercode smallint;
  v_issueinvcode integer;
BEGIN
  v_prodcode := prodcode;
  v_usercode := usercode;
  v_issueinvcode := (SELECT issueinvcode FROM dbo.prodheader WHERE ((prodcode = v_prodcode) AND (issueinvcode IN (SELECT issueinvcode FROM dbo.issueheader WHERE (posted = 'N')))));
  IF ((v_prodcode > 0) AND (v_issueinvcode > 0)) THEN
    UPDATE dbo.issueheader SET posted = 'Y', postdate = localtimestamp(3), postedby = v_usercode WHERE ((issueheader.issueinvcode = v_issueinvcode) AND (issueheader.posted = 'N'));
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_PostIssueLedger ====
CREATE OR REPLACE FUNCTION dbo.sp_postissueledger(ai_sinvcode integer, ai_linvcode integer, ai_salesmancode integer, issuecategorycode smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_sinvcode integer;
  v_ai_linvcode integer;
  v_ai_salesmancode integer;
  v_issuecategorycode smallint;
BEGIN
  v_ai_sinvcode := ai_sinvcode;
  v_ai_linvcode := ai_linvcode;
  v_ai_salesmancode := ai_salesmancode;
  v_issuecategorycode := issuecategorycode;
  UPDATE dbo.issueheader SET posted = 'Y', postdate = localtimestamp(3), postedby = v_ai_salesmancode WHERE ((((issueheader.issueinvcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (issueheader.issuecategorycode = v_issuecategorycode)) AND (issueheader.posted = 'N')) AND (issueheader.issueinvcode NOT IN (SELECT prodheader.issueinvcode FROM dbo.prodheader WHERE (prodheader.issueinvcode IS NOT NULL))));
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_PostIssueReq ====
CREATE OR REPLACE FUNCTION dbo.sp_postissuereq(ai_sinvcode integer, ai_linvcode integer, ai_salesmancode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_sinvcode integer;
  v_ai_linvcode integer;
  v_ai_salesmancode integer;
BEGIN
  v_ai_sinvcode := ai_sinvcode;
  v_ai_linvcode := ai_linvcode;
  v_ai_salesmancode := ai_salesmancode;
  UPDATE dbo.issuereqheader SET posted = 'Y', postdate = localtimestamp(3), postedby = v_ai_salesmancode WHERE ((issuereqheader.issuereqinvcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (issuereqheader.posted = 'N'));
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_PostItemConversion ====
CREATE OR REPLACE FUNCTION dbo.sp_postitemconversion(code integer, usercode smallint, headerno smallint, serverdate timestamp, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_code integer;
  v_usercode smallint;
  v_headerno smallint;
  v_serverdate timestamp(3);
  v_adjinccode integer;
  v_adjdeccode integer;
  v_headerinvno integer;
  v_adjutn bigint;
  v_effect integer;
  v_icode integer;
  v_gcode smallint;
  v_batch citext;
  v_expiry timestamp(3);
  v_defaultbatch citext;
  v_defaultexpiry timestamp(3);
  v_reqqty numeric(15,4);
  v_givenqty numeric(15,4);
  v_totalqty numeric(15,4);
  v_currqty numeric(15,4);
  v_delqty numeric(15,4);
  v_batchqty numeric(15,4);
  v_newqty numeric(15,4);
  v_totstock numeric(15,4);
  v_hold_avgprice numeric(15,5);
  v_packunits smallint;
  v_price numeric(12,2);
  v_purprice numeric(12,2);
  v_saleprice numeric(12,2);
  v_recentpurprice numeric(12,2);
  v_newavgprice numeric(15,5);
  v_adjinc_items_rows integer;
  v_adjdec_items_rows integer;
  v_totalrows integer;
  v_counter integer;
  v_module smallint;
  v_continue integer;
  v_err integer;
  v_rowcount integer;
  v_rt_code integer;
  v_err_string citext;
  v_itemname citext;
  v_updateavgprice citext;
  v_remarks citext;
  cur_cursor_adjinc_items refcursor;
  cur_cursor_adjdec_items refcursor;
  cur_itembatch_cursor refcursor;
  _rc integer;
  _fs integer := -1;
BEGIN
  v_code := code;
  v_usercode := usercode;
  v_headerno := headerno;
  v_serverdate := serverdate;
  v_effect := (SELECT itemconversioneffectcode FROM dbo.itemconversionheader WHERE (itemconversioncode = v_code));
  _rc := 1;
  v_remarks := (SELECT coalesce(remarks, '') FROM dbo.itemconversionheader WHERE (itemconversioncode = v_code));
  _rc := 1;
  v_remarks := (((v_code)::text || ' , ') || v_remarks);
  _rc := 1;
  v_rt_code := (SELECT count(*) FROM dbo.itemconversionheader WHERE ((itemconversioncode = v_code) AND (posted = 'Y')));
  _rc := 1;
  IF (v_rt_code > 0) THEN
    return_value := 0;
    RETURN;
  END IF;
  v_continue := 0;
  _rc := 1;
  v_module := (SELECT module FROM dbo.module WHERE (name = 'Adjustment'));
  _rc := 1;
  v_defaultbatch := dbo.fn_getpreference('defaultbatch');
  _rc := 1;
  v_defaultexpiry := dbo.fn_get_datetime_preference('defaultexpiry');
  _rc := 1;
  v_updateavgprice := dbo.fn_getpreference('UpdAvgPriceInAdjInc');
  _rc := 1;
  IF (v_effect = 1) THEN
  ELSE
  END IF;
  OPEN cur_cursor_adjinc_items FOR SELECT itemconversiondetail.gcode, itemconversiondetail.icode, itemconversiondetail.qty AS givenqty, item.packunits, item.purprice, item.saleprice, item.recentpurprice FROM dbo.itemconversiondetail JOIN dbo.item ON (itemconversiondetail.icode = item.icode) WHERE ((itemconversioncode = v_code) AND (qty > 0)) ORDER BY rowid;
  v_adjinc_items_rows := (-1);
  _rc := 1;
  IF (v_adjinc_items_rows > 0) THEN
    SELECT r.return_value, r.key INTO v_rt_code, v_adjinccode FROM dbo.sp_gettabmaxkey(tabname => 'AdjHeader', key => v_adjinccode) AS r;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      v_continue := -1;
      _rc := 1;
    ELSE
      SELECT r.return_value, r.key INTO v_rt_code, v_headerinvno FROM dbo.sp_getheadertabmaxkey(headercode => v_headerno, modulecode => v_module, key => v_headerinvno) AS r;
      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
        v_continue := -1;
        _rc := 1;
      ELSE
        INSERT INTO dbo.adjheader (adjcode, adjcatcode, usercode, remarks, date, modifieddate, modifiedby, posted, posteddate, postedby, headerno, headerinvno) VALUES (v_adjinccode, 1, v_usercode, v_remarks, v_serverdate, v_serverdate, NULL::integer, 'Y', v_serverdate, v_usercode, v_headerno, v_headerinvno);
        GET DIAGNOSTICS _rc = ROW_COUNT;
        v_err := 0;
        v_rowcount := _rc;
        _rc := 1;
        IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
          RAISE EXCEPTION 'Error occured in inserting record into Adjustment Increase Header for Item Conversion Code : %', v_code;
          v_continue := -1;
          _rc := 1;
        ELSE
          FETCH NEXT FROM cur_cursor_adjinc_items INTO v_gcode, v_icode, v_givenqty, v_packunits, v_purprice, v_saleprice, v_recentpurprice;
          IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
          WHILE ((_fs = 0) AND (v_continue >= 0)) LOOP
            SELECT r.return_value, r.avgprice INTO v_rt_code, v_hold_avgprice FROM dbo.sp_getitemavgprice(icode => v_icode, avgprice => v_hold_avgprice) AS r;
            IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
              v_continue := -1;
              _rc := 1;
            ELSE
              SELECT r.return_value, r.lbi_maxutn INTO v_rt_code, v_adjutn FROM dbo.sp_maxutn(lbi_rows => (1)::bigint, lbi_maxutn => v_adjutn) AS r;
              IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                v_continue := -1;
                _rc := 1;
              END IF;
              v_packunits := CASE WHEN (v_packunits IS NULL) THEN 1 WHEN (v_packunits = 0) THEN 1 ELSE v_packunits END;
              _rc := 1;
              IF ((v_hold_avgprice IS NULL) OR (v_hold_avgprice = 0)) THEN
                v_price := (v_purprice / v_packunits);
                _rc := 1;
              ELSE
                v_price := (v_hold_avgprice)::numeric(8,2);
                _rc := 1;
              END IF;
              SELECT r.return_value, r.qty INTO v_rt_code, v_totstock FROM dbo.sp_getitemstockall(icode => v_icode, qty => v_totstock) AS r;
              IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                v_continue := -1;
                _rc := 1;
              END IF;
              IF (v_updateavgprice = 'Y') THEN
                v_newavgprice := coalesce((SELECT round(((((((v_totstock * v_hold_avgprice)) + ((v_givenqty * v_price)))) / ((v_givenqty + v_totstock))))::numeric, 5)), 0);
                _rc := 1;
                SELECT r.return_value INTO v_rt_code FROM dbo.sp_updateitemavgprice(icode => v_icode, avgprice => v_newavgprice) AS r;
                IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                  v_continue := -1;
                  _rc := 1;
                END IF;
              ELSE
                v_newavgprice := v_hold_avgprice;
                _rc := 1;
              END IF;
              IF (v_continue <> -1) THEN
                INSERT INTO dbo.adjdetail (adjcode, gcode, icode, batch, expiry, looseqty, priority, price, avgprice, packunits, saleprice, purprice, recentpurprice, adjutn, updateavgprice, newavgprice, currstock) VALUES (v_adjinccode, v_gcode, v_icode, v_defaultbatch, v_defaultexpiry, v_givenqty, 0, v_price, v_hold_avgprice, v_packunits, v_saleprice, v_purprice, v_recentpurprice, v_adjutn, v_updateavgprice, v_newavgprice, v_totstock);
                GET DIAGNOSTICS _rc = ROW_COUNT;
                v_err := 0;
                v_rowcount := _rc;
                _rc := 1;
                IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
                  RAISE EXCEPTION 'Error occured in inserting record into Adjustment Increase Detail for Item Conversion Code : %', v_code;
                  v_continue := -1;
                  _rc := 1;
                ELSE
                  SELECT r.return_value, r.qty INTO v_rt_code, v_currqty FROM dbo.sp_getitemstockbatch(gcode => (v_gcode)::integer, icode => v_icode, batch => v_defaultbatch, expiry => v_defaultexpiry, qty => v_currqty) AS r;
                  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                    v_continue := -1;
                    _rc := 1;
                  ELSE
                    v_newqty := (v_currqty + v_givenqty);
                    _rc := 1;
                    SELECT r.return_value INTO v_rt_code FROM dbo.sp_updateitemstockbatch(gcode => (v_gcode)::integer, icode => v_icode, batch => v_defaultbatch, expiry => v_defaultexpiry, newqty => v_newqty) AS r;
                    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                      v_continue := -1;
                      _rc := 1;
                    END IF;
                  END IF;
                END IF;
              END IF;
            END IF;
            FETCH NEXT FROM cur_cursor_adjinc_items INTO v_gcode, v_icode, v_givenqty, v_packunits, v_purprice, v_saleprice, v_recentpurprice;
            IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
          END LOOP;
        END IF;
      END IF;
    END IF;
  END IF;
  CLOSE cur_cursor_adjinc_items;
  -- DEALLOCATE Cursor_AdjInc_Items
  IF (v_continue <> 0) THEN
    return_value := -1;
    RETURN;
  ELSE
    v_continue := 0;
    _rc := 1;
    IF (v_effect = 1) THEN
    ELSE
    END IF;
    OPEN cur_cursor_adjdec_items FOR SELECT itemconversionheader.gcode, itemconversionheader.icode, itemconversionheader.qty AS givenqty, item.packunits, item.purprice, item.saleprice, item.recentpurprice FROM dbo.itemconversionheader JOIN dbo.item ON (itemconversionheader.icode = item.icode) WHERE ((itemconversioncode = v_code) AND (qty > 0));
    v_adjdec_items_rows := (-1);
    _rc := 1;
    IF (v_adjdec_items_rows > 0) THEN
      SELECT r.return_value, r.key INTO v_rt_code, v_adjdeccode FROM dbo.sp_gettabmaxkey(tabname => 'AdjHeader', key => v_adjdeccode) AS r;
      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
        v_continue := -1;
        _rc := 1;
      ELSE
        SELECT r.return_value, r.key INTO v_rt_code, v_headerinvno FROM dbo.sp_getheadertabmaxkey(headercode => v_headerno, modulecode => v_module, key => v_headerinvno) AS r;
        IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
          v_continue := -1;
          _rc := 1;
        ELSE
          INSERT INTO dbo.adjheader (adjcode, adjcatcode, usercode, remarks, date, modifieddate, modifiedby, posted, posteddate, postedby, headerno, headerinvno) VALUES (v_adjdeccode, 2, v_usercode, v_remarks, v_serverdate, v_serverdate, NULL::integer, 'Y', v_serverdate, v_usercode, v_headerno, v_headerinvno);
          GET DIAGNOSTICS _rc = ROW_COUNT;
          v_err := 0;
          v_rowcount := _rc;
          _rc := 1;
          IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
            RAISE EXCEPTION 'Error occured in inserting record into Adjustment Decrease for Item Conversion Code : %', v_code;
            v_continue := -1;
            _rc := 1;
          ELSE
            FETCH NEXT FROM cur_cursor_adjdec_items INTO v_gcode, v_icode, v_givenqty, v_packunits, v_purprice, v_saleprice, v_recentpurprice;
            IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
            WHILE ((_fs = 0) AND (v_continue >= 0)) LOOP
              SELECT r.return_value, r.avgprice INTO v_rt_code, v_hold_avgprice FROM dbo.sp_getitemavgprice(icode => v_icode, avgprice => v_hold_avgprice) AS r;
              IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                v_continue := -1;
                _rc := 1;
              ELSE
                v_packunits := CASE WHEN (v_packunits IS NULL) THEN 1 WHEN (v_packunits = 0) THEN 1 ELSE v_packunits END;
                _rc := 1;
                v_totalqty := (SELECT coalesce(sum(currqty), 0) FROM dbo.godowndetail WHERE ((godowndetail.gcode = v_gcode) AND (godowndetail.icode = v_icode)));
                _rc := 1;
                IF (v_totalqty >= v_givenqty) THEN
                  v_reqqty := v_givenqty;
                  _rc := 1;
                  OPEN cur_itembatch_cursor FOR SELECT batch, expiry, currqty FROM dbo.godowndetail WHERE ((godowndetail.gcode = v_gcode) AND (godowndetail.icode = v_icode)) ORDER BY priority, expiry, currqty;
                  v_totalrows := (-1);
                  _rc := 1;
                  FETCH NEXT FROM cur_itembatch_cursor INTO v_batch, v_expiry, v_currqty;
                  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
                  v_counter := 1;
                  _rc := 1;
                  WHILE (((_fs = 0) AND (v_counter <= v_totalrows)) AND (v_reqqty > 0)) LOOP
                    v_batchqty := v_currqty;
                    _rc := 1;
                    IF (v_batchqty >= v_reqqty) THEN
                      v_delqty := v_reqqty;
                      _rc := 1;
                    ELSE
                      v_delqty := v_batchqty;
                      _rc := 1;
                    END IF;
                    v_reqqty := (v_reqqty - v_delqty);
                    _rc := 1;
                    SELECT r.return_value, r.lbi_maxutn INTO v_rt_code, v_adjutn FROM dbo.sp_maxutn(lbi_rows => (1)::bigint, lbi_maxutn => v_adjutn) AS r;
                    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                      v_continue := -1;
                      _rc := 1;
                    END IF;
                    SELECT r.return_value, r.qty INTO v_rt_code, v_totstock FROM dbo.sp_getitemstockall(icode => v_icode, qty => v_totstock) AS r;
                    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                      v_continue := -1;
                      _rc := 1;
                    END IF;
                    v_newavgprice := v_hold_avgprice;
                    _rc := 1;
                    INSERT INTO dbo.adjdetail (adjcode, gcode, icode, batch, expiry, looseqty, priority, price, avgprice, packunits, saleprice, purprice, recentpurprice, adjutn, updateavgprice, newavgprice, currstock) VALUES (v_adjdeccode, v_gcode, v_icode, v_batch, v_expiry, v_delqty, 0, v_hold_avgprice, v_hold_avgprice, v_packunits, v_saleprice, v_purprice, v_recentpurprice, v_adjutn, v_updateavgprice, v_newavgprice, v_totstock);
                    GET DIAGNOSTICS _rc = ROW_COUNT;
                    v_err := 0;
                    v_rowcount := _rc;
                    _rc := 1;
                    IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
                      RAISE EXCEPTION 'Error occured in inserting record into Adjustment Decrease Detail for Item Conversion Code : %', v_code;
                      v_continue := -1;
                      _rc := 1;
                    ELSE
                      v_newqty := (v_currqty - v_delqty);
                      _rc := 1;
                      IF (v_newqty > 0) THEN
                        SELECT r.return_value INTO v_rt_code FROM dbo.sp_saleupdateitemstockbatch(gcode => (v_gcode)::integer, icode => v_icode, batch => v_batch, expiry => v_expiry, newqty => v_newqty, oldqty => v_currqty) AS r;
                      ELSE
                        SELECT r.return_value INTO v_rt_code FROM dbo.sp_deleteitemstockbatch(gcode => (v_gcode)::integer, icode => v_icode, batch => v_batch, expiry => v_expiry, oldqty => v_delqty) AS r;
                      END IF;
                      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                        v_continue := -1;
                        _rc := 1;
                      END IF;
                    END IF;
                    v_counter := (v_counter + 1);
                    _rc := 1;
                    FETCH NEXT FROM cur_itembatch_cursor INTO v_batch, v_expiry, v_currqty;
                    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
                  END LOOP;
                  CLOSE cur_itembatch_cursor;
                  -- DEALLOCATE ItemBatch_Cursor
                ELSE
                  v_itemname := (SELECT name FROM dbo.item WHERE (icode = v_icode));
                  _rc := 1;
                  RAISE EXCEPTION 'Not enough stock for item (%) to decrease for Item Conversion Code : %', v_itemname, v_code;
                  v_continue := -1;
                  _rc := 1;
                END IF;
              END IF;
              FETCH NEXT FROM cur_cursor_adjdec_items INTO v_gcode, v_icode, v_givenqty, v_packunits, v_purprice, v_saleprice, v_recentpurprice;
              IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
            END LOOP;
          END IF;
        END IF;
      END IF;
    END IF;
    CLOSE cur_cursor_adjdec_items;
    -- DEALLOCATE Cursor_AdjDec_Items
    IF (v_continue <> 0) THEN
      return_value := -1;
      RETURN;
    ELSE
      UPDATE dbo.itemconversionheader SET posted = 'Y', postedby = v_usercode, postdate = localtimestamp(3), adjincreasecode = CASE WHEN (v_adjinc_items_rows > 0) THEN v_adjinccode ELSE NULL END, adjdecreasecode = CASE WHEN (v_adjdec_items_rows > 0) THEN v_adjdeccode ELSE NULL END WHERE (itemconversioncode = v_code);
      GET DIAGNOSTICS _rc = ROW_COUNT;
      IF ((0 <> 0) OR (_rc = 0)) THEN
        RAISE EXCEPTION 'Posting fail for Item Conversion Code (%) due to updation problem.', v_code;
        return_value := -1;
        RETURN;
      END IF;
      IF (v_adjinccode > 0) THEN
        IF ((SELECT dbo.fn_getpreference('IncAdjInActMonitor') AS a) = 'Y') THEN
          SELECT r.return_value INTO v_rt_code FROM dbo.sp_updateactivitymonitor(documenttype => 'AI', documentcode => v_adjinccode) AS r;
          IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
            RAISE EXCEPTION 'Posting fail for Item Conversion Code (%) due to activity monitor updation problem.', v_code;
            return_value := -1;
            RETURN;
          END IF;
        END IF;
      END IF;
      IF (v_adjdeccode > 0) THEN
        IF ((SELECT dbo.fn_getpreference('IncAdjInActMonitor') AS a) = 'Y') THEN
          SELECT r.return_value INTO v_rt_code FROM dbo.sp_updateactivitymonitor(documenttype => 'AD', documentcode => v_adjdeccode) AS r;
          IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
            RAISE EXCEPTION 'Posting fail for Item Conversion Code (%) due to activity monitor updation problem.', v_code;
            return_value := -1;
            RETURN;
          END IF;
        END IF;
      END IF;
      return_value := 0;
      RETURN;
    END IF;
  END IF;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_PostNote ====
CREATE OR REPLACE FUNCTION dbo.sp_postnote(ai_code integer, ai_usercode integer, ai_notetype integer, ad_postdate timestamp, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_code integer;
  v_ai_usercode integer;
  v_ai_notetype integer;
  v_ad_postdate timestamp(3);
BEGIN
  v_ai_code := ai_code;
  v_ai_usercode := ai_usercode;
  v_ai_notetype := ai_notetype;
  v_ad_postdate := ad_postdate;
  UPDATE dbo.notes AS notes SET posted = 'Y', postdate = v_ad_postdate, postedby = v_ai_usercode WHERE (((((notes.notecode = v_ai_code) AND (notes.notecatcode = v_ai_notetype)) AND (notes.posted = 'N')) AND (notes.finalized = 'Y')) AND (notes.bankacccode IS NOT NULL));
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_PostNotes ====
CREATE OR REPLACE FUNCTION dbo.sp_postnotes(ai_sinvcode integer, ai_linvcode integer, ai_usercode integer, ai_acccode integer, ai_notetype integer, ai_oneorall integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_sinvcode integer;
  v_ai_linvcode integer;
  v_ai_usercode integer;
  v_ai_acccode integer;
  v_ai_notetype integer;
  v_ai_oneorall integer;
BEGIN
  v_ai_sinvcode := ai_sinvcode;
  v_ai_linvcode := ai_linvcode;
  v_ai_usercode := ai_usercode;
  v_ai_acccode := ai_acccode;
  v_ai_notetype := ai_notetype;
  v_ai_oneorall := ai_oneorall;
  IF (v_ai_oneorall = 0) THEN
    UPDATE dbo.notes AS notes SET posted = 'Y', postdate = localtimestamp(3), postedby = v_ai_usercode WHERE ((((((notes.notecode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (notes.notecatcode = v_ai_notetype)) AND (notes.acccode = v_ai_acccode)) AND (notes.posted = 'N')) AND (notes.finalized = 'Y')) AND (notes.bankacccode IS NOT NULL));
  ELSE
    UPDATE dbo.notes SET posted = 'Y', postdate = localtimestamp(3), postedby = v_ai_usercode WHERE (((((notes.notecode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (notes.notecatcode = v_ai_notetype)) AND (notes.posted = 'N')) AND (notes.finalized = 'Y')) AND (notes.bankacccode IS NOT NULL));
  END IF;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_PostPayroll ====
CREATE OR REPLACE FUNCTION dbo.sp_postpayroll(ai_scode integer, ai_ecode integer, ai_usercode smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_scode integer;
  v_ai_ecode integer;
  v_ai_usercode smallint;
  v_innercounter integer;
  v_innercounter2 integer;
  v_continue integer;
  v_rt_code integer;
  v_err integer;
  v_totalrows integer;
  v_totalrows2 integer;
  v_totalrows3 integer;
  v_rowcount integer;
  v_counter integer;
  v_serverdate timestamp(3);
  v_payrollcode integer;
  v_advance numeric(15,2);
  v_empcode integer;
  v_acccode smallint;
  v_advacccode smallint;
  v_advancecode integer;
  v_amount numeric(15,2);
  v_returnedamt numeric(15,2);
  v_balance numeric(15,2);
  v_installment numeric(15,2);
  cur_c1 refcursor;
  cur_c2 refcursor;
  cur_c3 refcursor;
  _fs integer := -1;
BEGIN
  v_ai_scode := ai_scode;
  v_ai_ecode := ai_ecode;
  v_ai_usercode := ai_usercode;
  v_serverdate := localtimestamp(3);
  OPEN cur_c1 FOR SELECT ep.payrollcode AS payrollcode, ep.advance AS advance, ep.empcode AS empcode, e.acccode AS acccode, e.advacccode AS advacccode, coalesce((SELECT sum((ea.amount - ea.returnedamt)) FROM dbo.emp_advance AS ea WHERE (ea.empadvacccode = e.advacccode)), 0) AS balance FROM dbo.emp_payroll AS ep, dbo.emp_employee AS e WHERE (((ep.posted = 'N') AND (ep.empcode = e.empcode)) AND (ep.payrollcode BETWEEN v_ai_scode AND v_ai_ecode)) ORDER BY payrollcode;
  v_totalrows := (-1);
  IF (v_totalrows = 0) THEN
    RAISE EXCEPTION 'Payroll Posting : No rows available for posting';
    CLOSE cur_c1;
    -- DEALLOCATE C1
    return_value := -1;
    RETURN;
  END IF;
  v_continue := 0;
  v_err := 0;
  v_rowcount := 1;
  v_counter := 1;
  FETCH NEXT FROM cur_c1 INTO v_payrollcode, v_advance, v_empcode, v_acccode, v_advacccode, v_balance;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE ((_fs = 0) AND (v_counter <= v_totalrows)) LOOP
    IF (v_advance > v_balance) THEN
      RAISE EXCEPTION 'Payroll Posting : Advance installment is more than advance taken. Payroll Code: % ', v_payrollcode;
      CLOSE cur_c1;
      -- DEALLOCATE C1
      return_value := -1;
      RETURN;
    END IF;
    OPEN cur_c2 FOR SELECT advancecode, amount, returnedamt, installment FROM dbo.emp_advance WHERE ((((empadvacccode = v_advacccode) AND (((amount - returnedamt)) > 0)) AND (v_advance > 0)) AND (installment > 0)) ORDER BY advancecode;
    v_totalrows2 := (-1);
    IF (v_totalrows2 > 0) THEN
      FETCH NEXT FROM cur_c2 INTO v_advancecode, v_amount, v_returnedamt, v_installment;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
      v_innercounter := 1;
      WHILE (((_fs = 0) AND (v_innercounter <= v_totalrows2)) AND (v_advance > 0)) LOOP
        IF (v_advance >= v_installment) THEN
          UPDATE dbo.emp_advance SET returnedamt = (returnedamt + v_installment) WHERE (advancecode = v_advancecode);
          v_advance := (v_advance - v_installment);
        ELSE
          UPDATE dbo.emp_advance SET returnedamt = (returnedamt + v_advance) WHERE (advancecode = v_advancecode);
          v_advance := 0;
        END IF;
        v_innercounter := (v_innercounter + 1);
        FETCH NEXT FROM cur_c2 INTO v_advancecode, v_amount, v_returnedamt, v_installment;
        IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
      END LOOP;
      IF (v_advance > 0) THEN
        OPEN cur_c3 FOR SELECT advancecode, amount, returnedamt FROM dbo.emp_advance WHERE (((empadvacccode = v_advacccode) AND (((amount - returnedamt)) > 0)) AND (v_advance > 0)) ORDER BY advancecode;
        v_totalrows3 := (-1);
        IF (v_totalrows3 > 0) THEN
          FETCH NEXT FROM cur_c3 INTO v_advancecode, v_amount, v_returnedamt;
          IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
          v_innercounter2 := 1;
          WHILE (((_fs = 0) AND (v_innercounter2 <= v_totalrows3)) AND (v_advance > 0)) LOOP
            IF (v_advance >= ((v_amount - v_returnedamt))) THEN
              UPDATE dbo.emp_advance SET returnedamt = amount WHERE (advancecode = v_advancecode);
              v_advance := (v_advance - ((v_amount - v_returnedamt)));
            ELSE
              UPDATE dbo.emp_advance SET returnedamt = (returnedamt + v_advance) WHERE (advancecode = v_advancecode);
              v_advance := 0;
            END IF;
            v_innercounter2 := (v_innercounter2 + 1);
            FETCH NEXT FROM cur_c3 INTO v_advancecode, v_amount, v_returnedamt;
            IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
          END LOOP;
          CLOSE cur_c3;
          -- DEALLOCATE C3
        END IF;
      END IF;
    END IF;
    CLOSE cur_c2;
    -- DEALLOCATE C2
    UPDATE dbo.emp_payroll SET posted = 'Y', postdate = localtimestamp(3), postedby = v_ai_usercode WHERE ((payrollcode = v_payrollcode) AND (posted = 'N'));
    v_counter := (v_counter + 1);
    FETCH NEXT FROM cur_c1 INTO v_payrollcode, v_advance, v_empcode, v_acccode, v_advacccode, v_balance;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_c1;
  -- DEALLOCATE c1
  return_value := v_continue;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_PostPointOfSaleLedger ====
CREATE OR REPLACE FUNCTION dbo.sp_postpointofsaleledger(ai_sinvcode integer, ai_linvcode integer, ai_salesmancode integer, ai_custcode integer, ai_oneorall integer, ac_impactinventory citext, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_sinvcode integer;
  v_ai_linvcode integer;
  v_ai_salesmancode integer;
  v_ai_custcode integer;
  v_ai_oneorall integer;
  v_ac_impactinventory citext;
  v_saleinvcode integer;
  v_ai_list citext;
  v_loyalty citext;
  v_rowid integer;
  v_totrows integer;
  v_rt_code integer;
BEGIN
  v_ai_sinvcode := ai_sinvcode;
  v_ai_linvcode := ai_linvcode;
  v_ai_salesmancode := ai_salesmancode;
  v_ai_custcode := ai_custcode;
  v_ai_oneorall := ai_oneorall;
  v_ac_impactinventory := ac_impactinventory;
  DROP TABLE IF EXISTS tmp_lt_invoicelist;
  CREATE TEMP TABLE tmp_lt_invoicelist (
    code integer NOT NULL,
    rowid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL
) ON COMMIT DROP;
  v_saleinvcode := v_ai_sinvcode;
  v_loyalty := dbo.fn_getpreference('ApplyLoyaltypolicyonsaleposting');
  IF (v_ai_oneorall = 0) THEN
    INSERT INTO tmp_lt_invoicelist (code) SELECT saleinvcode FROM dbo.saleledger WHERE (((((saleledger.saleinvcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (saleledger.salecatcode IN (1, 2, 3))) AND (saleledger.custcode = v_ai_custcode)) AND (saleledger.posted = 'N')) AND (saleledger.impactinventory = v_ac_impactinventory));
    UPDATE dbo.saleledger SET posted = 'Y', postdate = localtimestamp(3), postedby = v_ai_salesmancode WHERE (((((saleledger.saleinvcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (saleledger.salecatcode IN (1, 2, 3))) AND (saleledger.custcode = v_ai_custcode)) AND (saleledger.posted = 'N')) AND (saleledger.impactinventory = v_ac_impactinventory));
  ELSE
    INSERT INTO tmp_lt_invoicelist (code) SELECT saleinvcode FROM dbo.saleledger WHERE ((((saleledger.saleinvcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (saleledger.salecatcode IN (1, 2, 3))) AND (saleledger.posted = 'N')) AND (saleledger.impactinventory = v_ac_impactinventory));
    UPDATE dbo.saleledger SET posted = 'Y', postdate = localtimestamp(3), postedby = v_ai_salesmancode WHERE ((((saleledger.saleinvcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (saleledger.salecatcode IN (1, 2, 3))) AND (saleledger.posted = 'N')) AND (saleledger.impactinventory = v_ac_impactinventory));
  END IF;
  v_rowid := 1;
  v_totrows := coalesce((SELECT count(*) FROM tmp_lt_invoicelist AS lt_invoicelist), 0);
  WHILE (v_rowid <= v_totrows) LOOP
    v_saleinvcode := (SELECT code FROM tmp_lt_invoicelist AS lt_invoicelist WHERE (rowid = v_rowid));
    IF (v_loyalty = 'Y') THEN
      SELECT r.return_value INTO v_rt_code FROM dbo.sp_manageloyaltypoints(invtype => 'SV', invoicecode => v_saleinvcode) AS r;
      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
        RAISE EXCEPTION 'Unable to Add Loyalty Points for Customer on Sale Posting';
        return_value := -1;
        RETURN;
      END IF;
    END IF;
    v_ai_list := ((v_ai_list || ltrim(rtrim(dbo.tsql_str((v_saleinvcode)::numeric, 10)))) || ',');
    v_rowid := (v_rowid + 1);
  END LOOP;
  IF ((right(v_ai_list, 1))::citext = ',') THEN
    v_ai_list := left(v_ai_list, (length(rtrim(v_ai_list)) - 1));
  END IF;
  SELECT r.return_value, r.rs1 INTO v_rt_code, rs1 FROM dbo.sp_createautotriggersms(ai_list => v_ai_list, ai_moduleid => (1)::smallint, ai_event => 'Posting') AS r;
  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
    RAISE EXCEPTION 'Unable to Create Auto Trigger SMS on Sale Posting';
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

