-- ==== proc sp_PostProduction ====
CREATE OR REPLACE FUNCTION dbo.sp_postproduction(prodcode integer, usercode integer, headerno integer, serverdate timestamp, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_prodcode integer;
  v_usercode integer;
  v_headerno integer;
  v_serverdate timestamp(3);
  v_err integer;
  v_rows integer;
  v_rt_code integer;
  v_issueinvcode integer;
  v_receiptinvcode integer;
  _rc integer;
BEGIN
  v_prodcode := prodcode;
  v_usercode := usercode;
  v_headerno := headerno;
  v_serverdate := serverdate;
  UPDATE dbo.prodheader SET posted = 'Y', postedby = v_usercode, postdate = localtimestamp(3) WHERE (((prodcode = v_prodcode) AND (posted = 'N')) AND (finalized = 'Y'));
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_err := 0;
  v_rows := _rc;
  _rc := 1;
  IF (((v_err = 0) AND (v_rows > 0))) THEN
    SELECT r.return_value, r.issueinvcode INTO v_rt_code, v_issueinvcode FROM dbo.sp_generateissue(prodcode => v_prodcode, usercode => v_usercode, headerno => v_headerno, serverdate => v_serverdate, issueinvcode => v_issueinvcode) AS r;
    IF (((0 = 0) AND (v_rt_code = 0))) THEN
      SELECT r.return_value, r.receiptinvcode INTO v_rt_code, v_receiptinvcode FROM dbo.sp_generatereceipt(prodcode => v_prodcode, usercode => v_usercode, headerno => v_headerno, serverdate => v_serverdate, issueinvcode => v_issueinvcode, receiptinvcode => v_receiptinvcode) AS r;
      IF (((0 = 0) OR (v_rt_code = 0))) THEN
        UPDATE dbo.prodheader SET issueinvcode = v_issueinvcode, receiptinvcode = v_receiptinvcode WHERE (prodcode = v_prodcode);
        GET DIAGNOSTICS _rc = ROW_COUNT;
        v_err := 0;
        v_rows := _rc;
        _rc := 1;
        IF (((v_err <> 0) OR (v_rows = 0))) THEN
          RAISE EXCEPTION 'Error occured in Posting Production (ProdCode= % ), Error in Updation of Issue / Receipt Document Contents', v_prodcode;
          return_value := -4;
          RETURN;
        END IF;
      ELSE
        RAISE EXCEPTION 'Error occured in Posting Production (ProdCode= % ), Error in Generation of Production Receipt Document', v_prodcode;
        return_value := -3;
        RETURN;
      END IF;
    ELSE
      RAISE EXCEPTION 'Error occured in Posting Production (ProdCode= % ), Error in Generation of Production Issue Document', v_prodcode;
      return_value := -2;
      RETURN;
    END IF;
  ELSE
    IF ((v_err <> 0)) THEN
      RAISE EXCEPTION 'Error occured in Posting Production (ProdCode= % )', v_prodcode;
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

