-- ==== proc sp_PostPurOrder ====
CREATE OR REPLACE FUNCTION dbo.sp_postpurorder(sinvcode integer, linvcode integer, usercode smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_sinvcode integer;
  v_linvcode integer;
  v_usercode smallint;
  v_icode integer;
  v_qty numeric(15,4);
  v_itemname citext;
  v_rt_code integer;
  v_continue integer;
  v_avgprice numeric(15,5);
  cur_item_cursor refcursor;
  _fs integer := -1;
BEGIN
  v_sinvcode := sinvcode;
  v_linvcode := linvcode;
  v_usercode := usercode;
  v_continue := 0;
  OPEN cur_item_cursor FOR SELECT pd.icode, ((((pd.qty + pd.bonusqty)) * pd.packunits)) AS qty FROM dbo.purorderheader AS ph JOIN dbo.purorderdetail AS pd ON (ph.pocode = pd.pocode) JOIN dbo.item AS i ON (pd.icode = i.icode) WHERE ((ph.pocode BETWEEN v_sinvcode AND v_linvcode) AND (ph.posted = 'N')) ORDER BY pd.pocode, pd.porowid;
  FETCH NEXT FROM cur_item_cursor INTO v_icode, v_qty;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    SELECT r.return_value INTO v_rt_code FROM dbo.sp_getitemavgprice(icode => v_icode, avgprice => v_avgprice) AS r;
    IF ((0 = 0) AND (v_rt_code = 0)) THEN
      SELECT r.return_value INTO v_rt_code FROM dbo.sp_updatetransitstock(mode => (0)::smallint, icode => v_icode, qty => v_qty) AS r;
      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
        v_itemname := (SELECT name FROM dbo.item WHERE (icode = v_icode));
        RAISE EXCEPTION 'Unable to Update Transit Stock for Item: %', v_itemname;
        v_continue := -1;
      END IF;
    ELSE
      v_itemname := (SELECT name FROM dbo.item WHERE (icode = v_icode));
      RAISE EXCEPTION 'Unable to Lock Item: % for Transit Stock Updation.', v_itemname;
      v_continue := -1;
    END IF;
    FETCH NEXT FROM cur_item_cursor INTO v_icode, v_qty;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_item_cursor;
  -- DEALLOCATE Item_Cursor
  IF (v_continue = 0) THEN
    UPDATE dbo.purorderheader SET posted = 'Y', postdate = localtimestamp(3), postedby = v_usercode WHERE ((pocode BETWEEN v_sinvcode AND v_linvcode) AND (posted = 'N'));
  END IF;
  return_value := v_continue;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_PostReceipt_From_Production ====
CREATE OR REPLACE FUNCTION dbo.sp_postreceipt_from_production(prodcode integer, usercode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_prodcode integer;
  v_usercode integer;
  v_receiptinvcode integer;
  v_issueinvcode integer;
  v_utn integer;
  v_pricetype smallint;
  v_priority smallint;
  v_groupcode integer;
  v_icode integer;
  v_gcode integer;
  v_packunits integer;
  v_givenqty numeric(15,4);
  v_totalqty numeric(15,4);
  v_currqty numeric(15,4);
  v_delqty numeric(15,4);
  v_batchqty numeric(15,4);
  v_reqqty numeric(15,4);
  v_newqty numeric(15,4);
  v_totstock numeric(15,4);
  v_price numeric(12,2);
  v_purprice numeric(12,2);
  v_saleprice numeric(12,2);
  v_hold_avgprice numeric(15,5);
  v_recentpurprice numeric(12,2);
  v_newavgprice numeric(15,5);
  v_batch citext;
  v_itemname citext;
  v_updateavgprice citext;
  v_items_rows integer;
  v_counter integer;
  v_rowcount integer;
  v_totalrows integer;
  v_continue integer;
  v_err integer;
  v_rt_code integer;
  v_expiry timestamp(3);
  v_recomputecost citext;
  cur_cursor_items refcursor;
  _fs integer := -1;
BEGIN
  v_prodcode := prodcode;
  v_usercode := usercode;
  v_receiptinvcode := (SELECT receiptinvcode FROM dbo.prodheader WHERE ((prodcode = v_prodcode) AND (receiptinvcode IN (SELECT receiptinvcode FROM dbo.receiptheader WHERE (posted = 'N')))));
  v_issueinvcode := (SELECT issueinvcode FROM dbo.prodheader WHERE ((prodcode = v_prodcode) AND (issueinvcode IN (SELECT issueinvcode FROM dbo.issueheader WHERE (posted = 'Y')))));
  IF (((v_prodcode > 0) AND (v_receiptinvcode > 0)) AND (v_issueinvcode > 0)) THEN
    v_continue := 0;
    v_updateavgprice := dbo.fn_getpreference('UpdAvgPriceInReceipt');
    v_priority := 10;
    v_recomputecost := dbo.fn_getpreference('ReComputeCostInProduction');
    UPDATE dbo.receiptdetail AS rd SET currstock = coalesce((SELECT sum(gd.currqty) FROM dbo.godowndetail AS gd WHERE (gd.icode = rd.icode)), 0), price = coalesce(CASE WHEN (v_issueinvcode > 0) THEN CASE v_recomputecost WHEN 'Y' THEN (SELECT (sum((isd.qty * isd.price)) / CASE WHEN (rd.qty = 0) THEN 1 ELSE rd.qty END) FROM dbo.prodheader AS h, dbo.prodbuffer AS b, dbo.proddetail AS d, dbo.issuedetail AS isd WHERE (((((((h.prodcode = v_prodcode) AND (h.prodcode = d.prodcode)) AND (d.icode = rd.icode)) AND (d.prodcode = b.prodcode)) AND (b.prodrowid = d.rowid)) AND (h.issueinvcode = isd.issueinvcode)) AND (isd.icode = b.icode))) ELSE CASE v_pricetype WHEN 1 THEN round(((i.saleprice / i.packunits))::numeric, 2) WHEN 2 THEN round(((i.saleprice2 / i.packunits))::numeric, 2) WHEN 3 THEN round(((i.saleprice3 / i.packunits))::numeric, 2) WHEN 4 THEN round(((i.purprice / i.packunits))::numeric, 2) WHEN 5 THEN round(((i.recentpurprice / i.packunits))::numeric, 2) WHEN 6 THEN round((i.avgprice)::numeric, 2) WHEN 7 THEN round(((i.saleprice4 / i.packunits))::numeric, 2) WHEN 8 THEN round(((i.saleprice5 / i.packunits))::numeric, 2) END END ELSE CASE v_pricetype WHEN 1 THEN round(((i.saleprice / i.packunits))::numeric, 2) WHEN 2 THEN round(((i.saleprice2 / i.packunits))::numeric, 2) WHEN 3 THEN round(((i.saleprice3 / i.packunits))::numeric, 2) WHEN 4 THEN round(((i.purprice / i.packunits))::numeric, 2) WHEN 5 THEN round(((i.recentpurprice / i.packunits))::numeric, 2) WHEN 6 THEN round((i.avgprice)::numeric, 2) WHEN 7 THEN round(((i.saleprice4 / i.packunits))::numeric, 2) WHEN 8 THEN round(((i.saleprice5 / i.packunits))::numeric, 2) END END, 0) FROM dbo.item AS i WHERE ((rd.receiptinvcode = v_receiptinvcode) AND (rd.icode = i.icode));
    OPEN cur_cursor_items FOR SELECT rd.gcode, rd.icode, rd.batch, rd.expiry, sum(rd.qty) AS qty, max(rd.packunits) AS packunits, max(rd.purchaseprice) AS purprice, max(rd.saleprice) AS saleprice, max(rd.mrpp) AS recentpurprice, CASE WHEN (v_issueinvcode > 0) THEN CASE v_recomputecost WHEN 'Y' THEN (SELECT (sum((isd.qty * isd.price)) / CASE WHEN (sum(rd.qty) = 0) THEN 1 ELSE sum(rd.qty) END) FROM dbo.prodheader AS h, dbo.prodbuffer AS b, dbo.proddetail AS d, dbo.issuedetail AS isd WHERE (((((((h.prodcode = v_prodcode) AND (h.prodcode = d.prodcode)) AND (d.icode = rd.icode)) AND (d.prodcode = b.prodcode)) AND (b.prodrowid = d.rowid)) AND (h.issueinvcode = isd.issueinvcode)) AND (isd.icode = b.icode))) ELSE CASE v_pricetype WHEN 1 THEN round(((max(i.saleprice) / max(i.packunits)))::numeric, 2) WHEN 2 THEN round(((max(i.saleprice2) / max(i.packunits)))::numeric, 2) WHEN 3 THEN round(((max(i.saleprice3) / max(i.packunits)))::numeric, 2) WHEN 4 THEN round(((max(i.purprice) / max(i.packunits)))::numeric, 2) WHEN 5 THEN round(((max(i.recentpurprice) / max(i.packunits)))::numeric, 2) WHEN 6 THEN round((max(i.avgprice))::numeric, 2) WHEN 7 THEN round(((max(i.saleprice4) / max(i.packunits)))::numeric, 2) WHEN 8 THEN round(((max(i.saleprice5) / max(i.packunits)))::numeric, 2) END END ELSE CASE v_pricetype WHEN 1 THEN round(((max(i.saleprice) / max(i.packunits)))::numeric, 2) WHEN 2 THEN round(((max(i.saleprice2) / max(i.packunits)))::numeric, 2) WHEN 3 THEN round(((max(i.saleprice3) / max(i.packunits)))::numeric, 2) WHEN 4 THEN round(((max(i.purprice) / max(i.packunits)))::numeric, 2) WHEN 5 THEN round(((max(i.recentpurprice) / max(i.packunits)))::numeric, 2) WHEN 6 THEN round((max(i.avgprice))::numeric, 2) WHEN 7 THEN round(((max(i.saleprice4) / max(i.packunits)))::numeric, 2) WHEN 8 THEN round(((max(i.saleprice5) / max(i.packunits)))::numeric, 2) END END AS price FROM dbo.receiptdetail AS rd, dbo.item AS i WHERE ((rd.receiptinvcode = v_receiptinvcode) AND (rd.icode = i.icode)) GROUP BY rd.gcode, rd.icode, rd.batch, rd.expiry;
    v_items_rows := (-1);
    IF (v_items_rows > 0) THEN
      FETCH NEXT FROM cur_cursor_items INTO v_gcode, v_icode, v_batch, v_expiry, v_givenqty, v_packunits, v_purprice, v_saleprice, v_recentpurprice, v_price;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
      WHILE ((_fs = 0) AND (v_continue >= 0)) LOOP
        SELECT r.return_value, r.avgprice INTO v_rt_code, v_hold_avgprice FROM dbo.sp_getitemavgprice(icode => v_icode, avgprice => v_hold_avgprice) AS r;
        IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
          v_continue := -1;
        ELSE
          SELECT r.return_value, r.lbi_maxutn INTO v_rt_code, v_utn FROM dbo.sp_maxutn(lbi_rows => (1)::bigint, lbi_maxutn => (v_utn)::bigint) AS r;
          IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
            v_continue := -1;
          END IF;
          v_packunits := CASE WHEN (v_packunits IS NULL) THEN 1 WHEN (v_packunits = 0) THEN 1 ELSE v_packunits END;
          SELECT r.return_value, r.qty INTO v_rt_code, v_totstock FROM dbo.sp_getitemstockall(icode => v_icode, qty => v_totstock) AS r;
          IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
            v_continue := -1;
          END IF;
          IF (v_updateavgprice = 'Y') THEN
            v_newavgprice := coalesce((SELECT round(((((((v_totstock * v_hold_avgprice)) + ((v_givenqty * v_price)))) / ((v_givenqty + v_totstock))))::numeric, 5)), 0);
            SELECT r.return_value INTO v_rt_code FROM dbo.sp_updateitemavgprice(icode => v_icode, avgprice => v_newavgprice) AS r;
            IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
              v_continue := -1;
            END IF;
          ELSE
            v_newavgprice := v_hold_avgprice;
          END IF;
          IF (v_continue <> -1) THEN
            SELECT r.return_value, r.qty INTO v_rt_code, v_currqty FROM dbo.sp_getitemstockbatch(gcode => v_gcode, icode => v_icode, batch => v_batch, expiry => v_expiry, qty => v_currqty) AS r;
            IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
              v_continue := -1;
            ELSE
              v_newqty := (v_currqty + v_givenqty);
              SELECT r.return_value INTO v_rt_code FROM dbo.sp_updateitemstockbatch(gcode => v_gcode, icode => v_icode, batch => v_batch, expiry => v_expiry, newqty => v_newqty) AS r;
              IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                v_continue := -1;
              END IF;
            END IF;
          END IF;
        END IF;
        FETCH NEXT FROM cur_cursor_items INTO v_gcode, v_icode, v_batch, v_expiry, v_givenqty, v_packunits, v_purprice, v_saleprice, v_recentpurprice, v_price;
        IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
      END LOOP;
    END IF;
    CLOSE cur_cursor_items;
    -- DEALLOCATE Cursor_Items
    IF (v_continue = 0) THEN
      UPDATE dbo.receiptheader SET posted = 'Y', postedby = v_usercode, postdate = localtimestamp(3) WHERE (receiptinvcode = v_receiptinvcode);
    END IF;
  END IF;
  IF (v_continue <> 0) THEN
    return_value := -1;
    RETURN;
  ELSE
    return_value := 0;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_PostSaleLedger ====
CREATE OR REPLACE FUNCTION dbo.sp_postsaleledger(ai_sinvcode integer, ai_linvcode integer, ai_salcatcode integer, ai_salesmancode integer, ai_custcode integer, ai_oneorall integer, ac_impactinventory citext, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_sinvcode integer;
  v_ai_linvcode integer;
  v_ai_salcatcode integer;
  v_ai_salesmancode integer;
  v_ai_custcode integer;
  v_ai_oneorall integer;
  v_ac_impactinventory citext;
  v_custcode integer;
  v_saleinvcode integer;
  v_rowid integer;
  v_totrows integer;
  v_rt_code integer;
  v_balance numeric(15,5);
  v_dt timestamp(3);
  v_savebal citext;
  v_ai_list citext;
  v_loyalty citext;
  v_autofiscalize citext;
BEGIN
  v_ai_sinvcode := ai_sinvcode;
  v_ai_linvcode := ai_linvcode;
  v_ai_salcatcode := ai_salcatcode;
  v_ai_salesmancode := ai_salesmancode;
  v_ai_custcode := ai_custcode;
  v_ai_oneorall := ai_oneorall;
  v_ac_impactinventory := ac_impactinventory;
  DROP TABLE IF EXISTS tmp_lt_invoicelist;
  CREATE TEMP TABLE tmp_lt_invoicelist (
    code integer NOT NULL,
    rowid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL
) ON COMMIT DROP;
  v_ai_list := '';
  v_savebal := dbo.fn_getpreference('SaveBalanceOnSalePosting');
  v_saleinvcode := v_ai_sinvcode;
  v_loyalty := dbo.fn_getpreference('ApplyLoyaltypolicyonsaleposting');
  v_autofiscalize := coalesce(dbo.fn_getpreference('AutoFiscalizeOnPosting'), 'N');
  IF (v_ai_oneorall = 0) THEN
    IF (v_savebal = 'Y') THEN
      IF (v_ai_salcatcode = 3) THEN
        INSERT INTO tmp_lt_invoicelist (code) SELECT saleinvcode FROM dbo.saleledger WHERE (((((((saleledger.saleinvcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (saleledger.salecatcode = 3)) AND (saleledger.custcode = v_ai_custcode)) AND (saleledger.posted = 'N')) AND (saleledger.deleted = 'N')) AND (saleledger.impactinventory = v_ac_impactinventory)) AND (saleledger.admissioncode IS NULL));
        UPDATE dbo.saleledger SET posted = 'Y', postdate = localtimestamp(3), postedby = v_ai_salesmancode, unreceivedbalance = saleledger.invtotal, balance = 0 WHERE (((((((saleledger.saleinvcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (saleledger.salecatcode = 3)) AND (saleledger.custcode = v_ai_custcode)) AND (saleledger.posted = 'N')) AND (saleledger.deleted = 'N')) AND (saleledger.impactinventory = v_ac_impactinventory)) AND (saleledger.admissioncode IS NULL));
      ELSE
        WHILE (v_saleinvcode <= v_ai_linvcode) LOOP
          v_custcode := 0;
          v_balance := 0;
          v_custcode := (SELECT custcode FROM dbo.saleledger WHERE (((((((saleinvcode = v_saleinvcode) AND (saleledger.salecatcode IN (1, 2))) AND (saleledger.custcode = v_ai_custcode)) AND (saleledger.posted = 'N')) AND (saleledger.deleted = 'N')) AND (saleledger.impactinventory = v_ac_impactinventory)) AND (saleledger.admissioncode IS NULL)));
          v_dt := localtimestamp(3);
          IF (v_custcode IS NOT NULL) THEN
            SELECT r.bal INTO v_balance FROM dbo.sp_openingbalance(acccode => v_custcode, datetime => v_dt, bal => v_balance) AS r;
            INSERT INTO tmp_lt_invoicelist (code) SELECT saleinvcode FROM dbo.saleledger WHERE (((((((saleledger.saleinvcode = v_saleinvcode) AND (saleledger.salecatcode IN (1, 2))) AND (saleledger.custcode = v_ai_custcode)) AND (saleledger.posted = 'N')) AND (saleledger.deleted = 'N')) AND (saleledger.impactinventory = v_ac_impactinventory)) AND (saleledger.admissioncode IS NULL));
            UPDATE dbo.saleledger SET posted = 'Y', postdate = localtimestamp(3), postedby = v_ai_salesmancode, unreceivedbalance = saleledger.invtotal, balance = v_balance WHERE (((((((saleledger.saleinvcode = v_saleinvcode) AND (saleledger.salecatcode IN (1, 2))) AND (saleledger.custcode = v_ai_custcode)) AND (saleledger.posted = 'N')) AND (saleledger.deleted = 'N')) AND (saleledger.impactinventory = v_ac_impactinventory)) AND (saleledger.admissioncode IS NULL));
          END IF;
          v_saleinvcode := (v_saleinvcode + 1);
        END LOOP;
      END IF;
    ELSE
      IF (v_ai_salcatcode = 3) THEN
        INSERT INTO tmp_lt_invoicelist (code) SELECT saleinvcode FROM dbo.saleledger WHERE (((((((saleledger.saleinvcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (saleledger.salecatcode = 3)) AND (saleledger.custcode = v_ai_custcode)) AND (saleledger.posted = 'N')) AND (saleledger.deleted = 'N')) AND (saleledger.impactinventory = v_ac_impactinventory)) AND (saleledger.admissioncode IS NULL));
        UPDATE dbo.saleledger SET posted = 'Y', postdate = localtimestamp(3), postedby = v_ai_salesmancode, unreceivedbalance = saleledger.invtotal, balance = 0 WHERE (((((((saleledger.saleinvcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (saleledger.salecatcode = 3)) AND (saleledger.custcode = v_ai_custcode)) AND (saleledger.posted = 'N')) AND (saleledger.deleted = 'N')) AND (saleledger.impactinventory = v_ac_impactinventory)) AND (saleledger.admissioncode IS NULL));
      ELSE
        INSERT INTO tmp_lt_invoicelist (code) SELECT saleinvcode FROM dbo.saleledger WHERE (((((((saleledger.saleinvcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (saleledger.salecatcode IN (1, 2))) AND (saleledger.custcode = v_ai_custcode)) AND (saleledger.posted = 'N')) AND (saleledger.deleted = 'N')) AND (saleledger.impactinventory = v_ac_impactinventory)) AND (saleledger.admissioncode IS NULL));
        UPDATE dbo.saleledger SET posted = 'Y', postdate = localtimestamp(3), postedby = v_ai_salesmancode, unreceivedbalance = saleledger.invtotal, balance = 0 WHERE (((((((saleledger.saleinvcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (saleledger.salecatcode IN (1, 2))) AND (saleledger.custcode = v_ai_custcode)) AND (saleledger.posted = 'N')) AND (saleledger.deleted = 'N')) AND (saleledger.impactinventory = v_ac_impactinventory)) AND (saleledger.admissioncode IS NULL));
      END IF;
    END IF;
  ELSE
    IF (v_savebal = 'Y') THEN
      IF (v_ai_salcatcode = 3) THEN
        INSERT INTO tmp_lt_invoicelist (code) SELECT saleinvcode FROM dbo.saleledger WHERE ((((((saleledger.saleinvcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (saleledger.salecatcode = 3)) AND (saleledger.posted = 'N')) AND (saleledger.deleted = 'N')) AND (saleledger.impactinventory = v_ac_impactinventory)) AND (saleledger.admissioncode IS NULL));
        UPDATE dbo.saleledger SET posted = 'Y', postdate = localtimestamp(3), postedby = v_ai_salesmancode, unreceivedbalance = saleledger.invtotal, balance = 0 WHERE ((((((saleledger.saleinvcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (saleledger.salecatcode = 3)) AND (saleledger.posted = 'N')) AND (saleledger.deleted = 'N')) AND (saleledger.impactinventory = v_ac_impactinventory)) AND (saleledger.admissioncode IS NULL));
      ELSE
        WHILE (v_saleinvcode <= v_ai_linvcode) LOOP
          v_custcode := 0;
          v_balance := 0;
          v_custcode := (SELECT custcode FROM dbo.saleledger WHERE ((((((saleinvcode = v_saleinvcode) AND (saleledger.salecatcode IN (1, 2))) AND (saleledger.posted = 'N')) AND (saleledger.deleted = 'N')) AND (saleledger.impactinventory = v_ac_impactinventory)) AND (saleledger.admissioncode IS NULL)));
          v_dt := localtimestamp(3);
          IF (v_custcode IS NOT NULL) THEN
            SELECT r.bal INTO v_balance FROM dbo.sp_openingbalance(acccode => v_custcode, datetime => v_dt, bal => v_balance) AS r;
            INSERT INTO tmp_lt_invoicelist (code) SELECT saleinvcode FROM dbo.saleledger WHERE ((((((saleledger.saleinvcode = v_saleinvcode) AND (saleledger.salecatcode IN (1, 2))) AND (saleledger.posted = 'N')) AND (saleledger.deleted = 'N')) AND (saleledger.impactinventory = v_ac_impactinventory)) AND (saleledger.admissioncode IS NULL));
            UPDATE dbo.saleledger SET posted = 'Y', postdate = localtimestamp(3), postedby = v_ai_salesmancode, unreceivedbalance = saleledger.invtotal, balance = v_balance WHERE ((((((saleledger.saleinvcode = v_saleinvcode) AND (saleledger.salecatcode IN (1, 2))) AND (saleledger.posted = 'N')) AND (saleledger.deleted = 'N')) AND (saleledger.impactinventory = v_ac_impactinventory)) AND (saleledger.admissioncode IS NULL));
          END IF;
          v_saleinvcode := (v_saleinvcode + 1);
        END LOOP;
      END IF;
    ELSE
      IF (v_ai_salcatcode = 3) THEN
        INSERT INTO tmp_lt_invoicelist (code) SELECT saleinvcode FROM dbo.saleledger WHERE ((((((saleledger.saleinvcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (saleledger.salecatcode = 3)) AND (saleledger.posted = 'N')) AND (saleledger.deleted = 'N')) AND (saleledger.impactinventory = v_ac_impactinventory)) AND (saleledger.admissioncode IS NULL));
        UPDATE dbo.saleledger SET posted = 'Y', postdate = localtimestamp(3), postedby = v_ai_salesmancode, unreceivedbalance = saleledger.invtotal, balance = 0 WHERE ((((((saleledger.saleinvcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (saleledger.salecatcode = 3)) AND (saleledger.posted = 'N')) AND (saleledger.deleted = 'N')) AND (saleledger.impactinventory = v_ac_impactinventory)) AND (saleledger.admissioncode IS NULL));
      ELSE
        INSERT INTO tmp_lt_invoicelist (code) SELECT saleinvcode FROM dbo.saleledger WHERE ((((((saleledger.saleinvcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (saleledger.salecatcode IN (1, 2))) AND (saleledger.posted = 'N')) AND (saleledger.deleted = 'N')) AND (saleledger.impactinventory = v_ac_impactinventory)) AND (saleledger.admissioncode IS NULL));
        UPDATE dbo.saleledger SET posted = 'Y', postdate = localtimestamp(3), postedby = v_ai_salesmancode, unreceivedbalance = saleledger.invtotal, balance = 0 WHERE ((((((saleledger.saleinvcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (saleledger.salecatcode IN (1, 2))) AND (saleledger.posted = 'N')) AND (saleledger.deleted = 'N')) AND (saleledger.impactinventory = v_ac_impactinventory)) AND (saleledger.admissioncode IS NULL));
      END IF;
    END IF;
  END IF;
  v_rowid := 1;
  v_totrows := coalesce((SELECT count(*) FROM tmp_lt_invoicelist AS lt_invoicelist), 0);
  WHILE (v_rowid <= v_totrows) LOOP
    v_saleinvcode := (SELECT code FROM tmp_lt_invoicelist AS lt_invoicelist WHERE (rowid = v_rowid));
    IF (v_loyalty = 'Y') THEN
      SELECT r.return_value INTO v_rt_code FROM dbo.sp_manageloyaltypoints(invtype => 'SV', invoicecode => v_saleinvcode) AS r;
      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
        RAISE EXCEPTION 'Unable to Add Loyalty Points for Customer on Sale Posting';
        return_value := -1;
        RETURN;
      END IF;
    END IF;
    v_ai_list := ((v_ai_list || ltrim(rtrim(dbo.tsql_str((v_saleinvcode)::numeric, 10)))) || ',');
    v_rowid := (v_rowid + 1);
  END LOOP;
  IF ((right(v_ai_list, 1))::citext = ',') THEN
    v_ai_list := left(v_ai_list, (length(rtrim(v_ai_list)) - 1));
  END IF;
  SELECT r.return_value, r.rs1 INTO v_rt_code, rs1 FROM dbo.sp_createautotriggersms(ai_list => v_ai_list, ai_moduleid => (1)::smallint, ai_event => 'Posting') AS r;
  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
    RAISE EXCEPTION 'Unable to Create Auto Trigger SMS on Sale Posting';
    return_value := -1;
    RETURN;
  END IF;
  SELECT r.return_value INTO v_rt_code FROM dbo.sp_updateitemmeter(list => v_ai_list) AS r;
  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
    RAISE EXCEPTION 'Unable to Update Item Meter on Sale Posting';
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_PostSaleLedger_wrt_Patient ====
CREATE OR REPLACE FUNCTION dbo.sp_postsaleledger_wrt_patient(ai_sinvcode integer, ai_linvcode integer, ai_salcatcode integer, ai_salesmancode integer, ai_patientcode integer, ac_impactinventory citext, OUT return_value integer, OUT rs1 refcursor)
