  v_totrows integer;
  v_rt_code integer;
  v_balance numeric(15,5);
  v_dt timestamp(3);
  v_savebal citext;
  v_ai_list citext;
BEGIN
  v_ai_sinvcode := ai_sinvcode;
  v_ai_linvcode := ai_linvcode;
  v_ai_salcatcode := ai_salcatcode;
  v_ai_salesmancode := ai_salesmancode;
  v_ai_patientcode := ai_patientcode;
  v_ac_impactinventory := ac_impactinventory;
  DROP TABLE IF EXISTS tmp_lt_invoicelist;
  CREATE TEMP TABLE tmp_lt_invoicelist (
    code integer NOT NULL,
    rowid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL
) ON COMMIT DROP;
  v_savebal := dbo.fn_getpreference('SaveBalanceOnSalePosting');
  v_saleinvcode := v_ai_sinvcode;
  IF (v_ai_salcatcode = 3) THEN
    INSERT INTO tmp_lt_invoicelist (code) SELECT saleinvcode FROM dbo.saleledger WHERE (((((((saleledger.saleinvcode = v_saleinvcode) AND (saleledger.salecatcode IN (3))) AND (saleledger.patientcode = v_ai_patientcode)) AND (saleledger.posted = 'N')) AND (saleledger.deleted = 'N')) AND (saleledger.impactinventory = v_ac_impactinventory)) AND (saleledger.admissioncode IS NULL));
    UPDATE dbo.saleledger SET posted = 'Y', postdate = localtimestamp(3), postedby = v_ai_salesmancode, unreceivedbalance = saleledger.invtotal, balance = 0 WHERE (((((((saleledger.saleinvcode = v_saleinvcode) AND (saleledger.salecatcode IN (3))) AND (saleledger.patientcode = v_ai_patientcode)) AND (saleledger.posted = 'N')) AND (saleledger.deleted = 'N')) AND (saleledger.impactinventory = v_ac_impactinventory)) AND (saleledger.admissioncode IS NULL));
  ELSE
    IF (v_savebal = 'Y') THEN
      WHILE (v_saleinvcode <= v_ai_linvcode) LOOP
        v_custcode := 0;
        v_balance := 0;
        v_custcode := (SELECT custcode FROM dbo.saleledger WHERE (((((((saleinvcode = v_saleinvcode) AND (saleledger.salecatcode IN (1, 2))) AND (saleledger.patientcode = v_ai_patientcode)) AND (saleledger.posted = 'N')) AND (saleledger.deleted = 'N')) AND (saleledger.impactinventory = v_ac_impactinventory)) AND (saleledger.admissioncode IS NULL)));
        v_dt := localtimestamp(3);
        IF (v_custcode IS NOT NULL) THEN
          SELECT r.bal INTO v_balance FROM dbo.sp_openingbalance(acccode => v_custcode, datetime => v_dt, bal => v_balance) AS r;
          INSERT INTO tmp_lt_invoicelist (code) SELECT saleinvcode FROM dbo.saleledger WHERE (((((((saleledger.saleinvcode = v_saleinvcode) AND (saleledger.salecatcode IN (1, 2))) AND (saleledger.patientcode = v_ai_patientcode)) AND (saleledger.posted = 'N')) AND (saleledger.deleted = 'N')) AND (saleledger.impactinventory = v_ac_impactinventory)) AND (saleledger.admissioncode IS NULL));
          UPDATE dbo.saleledger SET posted = 'Y', postdate = localtimestamp(3), postedby = v_ai_salesmancode, unreceivedbalance = saleledger.invtotal, balance = v_balance WHERE (((((((saleledger.saleinvcode = v_saleinvcode) AND (saleledger.salecatcode IN (1, 2))) AND (saleledger.patientcode = v_ai_patientcode)) AND (saleledger.posted = 'N')) AND (saleledger.deleted = 'N')) AND (saleledger.impactinventory = v_ac_impactinventory)) AND (saleledger.admissioncode IS NULL));
        END IF;
        v_saleinvcode := (v_saleinvcode + 1);
