  CREATE TEMP TABLE tmp_lt_invoicelist (
    code integer NOT NULL,
    rowid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL
) ON COMMIT DROP;
  v_savebal := dbo.fn_getpreference('SaveBalanceOnSalePosting');
  v_saleinvcode := v_ai_sinvcode;
  IF (v_ai_salcatcode = 3) THEN
    INSERT INTO tmp_lt_invoicelist (code) SELECT saleinvcode FROM dbo.saleledger WHERE ((((((((saleledger.saleinvcode >= (CASE v_ac_isall WHEN 'Y' THEN saleinvcode ELSE v_ai_sinvcode END)) AND (saleledger.saleinvcode <= (CASE v_ac_isall WHEN 'Y' THEN saleinvcode ELSE v_ai_linvcode END))) AND (saleledger.salecatcode = 3)) AND (saleledger.custcode IN (SELECT custcode FROM dbo.customer WHERE (areacode = v_ai_areacode)))) AND (saleledger.posted = 'N')) AND (saleledger.deleted = 'N')) AND (saleledger.impactinventory = v_ac_impactinventory)) AND (saleledger.admissioncode IS NULL));
