-- ==== proc sp_PostSaleOrder_wrt_Patient ====
CREATE OR REPLACE FUNCTION dbo.sp_postsaleorder_wrt_patient(ai_socatcode integer, ai_sinvcode integer, ai_linvcode integer, ai_usercode integer, ai_patientcode integer, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_socatcode integer;
  v_ai_sinvcode integer;
  v_ai_linvcode integer;
  v_ai_usercode integer;
  v_ai_patientcode integer;
  v_ordercode integer;
  v_rowid integer;
  v_totrows integer;
  v_rt_code integer;
  v_ai_list citext;
BEGIN
  v_ai_socatcode := ai_socatcode;
  v_ai_sinvcode := ai_sinvcode;
  v_ai_linvcode := ai_linvcode;
  v_ai_usercode := ai_usercode;
  v_ai_patientcode := ai_patientcode;
  DROP TABLE IF EXISTS tmp_lt_invoicelist;
  CREATE TEMP TABLE tmp_lt_invoicelist (
    code integer NOT NULL,
    rowid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_invoicelist (code) SELECT saleordercode FROM dbo.saleorderheader WHERE ((((((saleorderheader.socatcode = v_ai_socatcode) AND (saleorderheader.saleordercode BETWEEN v_ai_sinvcode AND v_ai_linvcode)) AND (saleorderheader.patientcode = v_ai_patientcode)) AND (saleorderheader.posted = 'N')) AND (saleorderheader.finalized = 'Y')) AND (saleorderheader.deleted = 'N'));
  UPDATE dbo.saleorderheader SET posted = 'Y', postdate = localtimestamp(3), postedby = v_ai_usercode WHERE ((((((saleorderheader.socatcode = v_ai_socatcode) AND (saleorderheader.saleordercode BETWEEN v_ai_sinvcode AND v_ai_linvcode)) AND (saleorderheader.patientcode = v_ai_patientcode)) AND (saleorderheader.posted = 'N')) AND (saleorderheader.finalized = 'Y')) AND (saleorderheader.deleted = 'N'));
  v_rowid := 1;
  v_totrows := coalesce((SELECT count(*) FROM tmp_lt_invoicelist AS lt_invoicelist), 0);
  WHILE (v_rowid <= v_totrows) LOOP
    v_ordercode := (SELECT code FROM tmp_lt_invoicelist AS lt_invoicelist WHERE (rowid = v_rowid));
    v_ai_list := ((v_ai_list || ltrim(rtrim(dbo.tsql_str((v_ordercode)::numeric, 10)))) || ',');
    v_rowid := (v_rowid + 1);
  END LOOP;
  IF ((right(v_ai_list, 1))::citext = ',') THEN
    v_ai_list := left(v_ai_list, (length(rtrim(v_ai_list)) - 1));
  END IF;
  SELECT r.return_value, r.rs1 INTO v_rt_code, rs1 FROM dbo.sp_createautotriggersms(ai_list => v_ai_list, ai_moduleid => (12)::smallint, ai_event => 'Posting') AS r;
  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
    RAISE EXCEPTION 'Unable to Create Auto Trigger SMS on Sale Order Posting';
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

