-- ==== proc SP_PostService_CustWise ====
CREATE OR REPLACE FUNCTION dbo.sp_postservice_custwise(ai_sinvcode integer, ai_linvcode integer, ai_servicecatcode integer, ai_salesmancode integer, ai_custcode integer, ai_oneorall integer, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_sinvcode integer;
  v_ai_linvcode integer;
  v_ai_servicecatcode integer;
  v_ai_salesmancode integer;
  v_ai_custcode integer;
  v_ai_oneorall integer;
  v_rowid integer;
  v_totrows integer;
  v_rt_code integer;
  v_serviceinvcode integer;
  v_serviceresultcode integer;
  v_ai_list citext;
  v_patientmodule integer;
BEGIN
  v_ai_sinvcode := ai_sinvcode;
  v_ai_linvcode := ai_linvcode;
  v_ai_servicecatcode := ai_servicecatcode;
  v_ai_salesmancode := ai_salesmancode;
  v_ai_custcode := ai_custcode;
  v_ai_oneorall := ai_oneorall;
  DROP TABLE IF EXISTS tmp_lt_invoicelist;
  CREATE TEMP TABLE tmp_lt_invoicelist (
    code integer NOT NULL,
    rowid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL
) ON COMMIT DROP;
  v_ai_list := '';
  IF (v_ai_oneorall = 0) THEN
    IF (v_ai_servicecatcode = 10) THEN
      INSERT INTO tmp_lt_invoicelist (code) SELECT serviceinvcode FROM dbo.serviceheader WHERE (((((serviceheader.serviceinvcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (serviceheader.servicecatcode = 10)) AND (serviceheader.custcode = v_ai_custcode)) AND (serviceheader.posted = 'N')) AND (serviceheader.admissioncode IS NULL));
      UPDATE dbo.serviceheader SET posted = 'Y', postdate = localtimestamp(3), postedby = v_ai_salesmancode WHERE (((((serviceheader.serviceinvcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (serviceheader.servicecatcode = 10)) AND (serviceheader.custcode = v_ai_custcode)) AND (serviceheader.posted = 'N')) AND (serviceheader.admissioncode IS NULL));
    ELSE
      INSERT INTO tmp_lt_invoicelist (code) SELECT serviceinvcode FROM dbo.serviceheader WHERE (((((serviceheader.serviceinvcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (serviceheader.servicecatcode NOT IN (10))) AND (serviceheader.custcode = v_ai_custcode)) AND (serviceheader.posted = 'N')) AND (serviceheader.admissioncode IS NULL));
      UPDATE dbo.serviceheader SET posted = 'Y', postdate = localtimestamp(3), postedby = v_ai_salesmancode WHERE (((((serviceheader.serviceinvcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (serviceheader.servicecatcode NOT IN (10))) AND (serviceheader.custcode = v_ai_custcode)) AND (serviceheader.posted = 'N')) AND (serviceheader.admissioncode IS NULL));
    END IF;
  ELSE
    IF (v_ai_servicecatcode = 10) THEN
      INSERT INTO tmp_lt_invoicelist (code) SELECT serviceinvcode FROM dbo.serviceheader WHERE ((((serviceheader.serviceinvcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (serviceheader.servicecatcode = 10)) AND (serviceheader.posted = 'N')) AND (serviceheader.admissioncode IS NULL));
      UPDATE dbo.serviceheader SET posted = 'Y', postdate = localtimestamp(3), postedby = v_ai_salesmancode WHERE ((((serviceheader.serviceinvcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (serviceheader.servicecatcode = 10)) AND (serviceheader.posted = 'N')) AND (serviceheader.admissioncode IS NULL));
    ELSE
      INSERT INTO tmp_lt_invoicelist (code) SELECT serviceinvcode FROM dbo.serviceheader WHERE ((((serviceheader.serviceinvcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (serviceheader.servicecatcode NOT IN (10))) AND (serviceheader.posted = 'N')) AND (serviceheader.admissioncode IS NULL));
      UPDATE dbo.serviceheader SET posted = 'Y', postdate = localtimestamp(3), postedby = v_ai_salesmancode WHERE ((((serviceheader.serviceinvcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (serviceheader.servicecatcode NOT IN (10))) AND (serviceheader.posted = 'N')) AND (serviceheader.admissioncode IS NULL));
    END IF;
  END IF;
  v_patientmodule := CASE WHEN (v_ai_servicecatcode = 10) THEN 22 ELSE 23 END;
  v_rowid := 1;
  v_totrows := coalesce((SELECT count(*) FROM tmp_lt_invoicelist AS lt_invoicelist), 0);
  WHILE (v_rowid <= v_totrows) LOOP
    v_serviceinvcode := (SELECT code FROM tmp_lt_invoicelist AS lt_invoicelist WHERE (rowid = v_rowid));
    SELECT r.return_value, r.serviceresultcode INTO v_rt_code, v_serviceresultcode FROM dbo.sp_autogenerateserviceresult(serviceinvcode => v_serviceinvcode, usercode => (v_ai_salesmancode)::smallint, serviceresultcode => v_serviceresultcode) AS r;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      RAISE EXCEPTION 'Unable to Generate Service Result for Service Invoice Code = %', v_serviceinvcode;
      return_value := -1;
      RETURN;
    END IF;
    SELECT r.return_value INTO v_rt_code FROM dbo.sp_autogeneratepurchaseofservice_doctorsharebased(serviceinvcode => v_serviceinvcode, usercode => (v_ai_salesmancode)::smallint) AS r;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      RAISE EXCEPTION 'Unable to Generate Doctor share based Purchase of Service for Service Invoice Code = %', v_serviceinvcode;
      return_value := -1;
      RETURN;
    END IF;
    SELECT r.return_value INTO v_rt_code FROM dbo.sp_autogenerateserviceinvpurtemplate(serviceinvcode => v_serviceinvcode, usercode => (v_ai_salesmancode)::smallint) AS r;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      RAISE EXCEPTION 'Unable to Generate Service Purchase Template for Service Invoice Code = %', v_serviceinvcode;
      return_value := -1;
      RETURN;
    END IF;
    v_ai_list := ((v_ai_list || ltrim(rtrim(dbo.tsql_str((v_serviceinvcode)::numeric, 10)))) || ',');
    v_rowid := (v_rowid + 1);
  END LOOP;
  IF ((right(v_ai_list, 1))::citext = ',') THEN
    v_ai_list := left(v_ai_list, (length(rtrim(v_ai_list)) - 1));
  END IF;
  SELECT r.return_value, r.rs1 INTO v_rt_code, rs1 FROM dbo.sp_createautotriggersms(ai_list => v_ai_list, ai_moduleid => (v_patientmodule)::smallint, ai_event => 'Posting') AS r;
  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
    RAISE EXCEPTION 'Unable to Create Auto Trigger SMS on Service Posting';
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

