CREATE OR REPLACE FUNCTION dbo.sp_postserviceheader_wrt_patientadmission(ai_sinvcode integer, ai_linvcode integer, ai_servicecatcode integer, ai_salesmancode integer, ai_admissioncode integer, ai_oneorall integer, OUT return_value integer)
