  IF (v_ai_oneorall = 0) THEN
    INSERT INTO tmp_lt_invoicelist (code) SELECT serviceinvcode FROM dbo.serviceheader WHERE (((((serviceheader.admissioncode = v_ai_admissioncode) AND (serviceheader.posted = 'N')) AND (serviceheader.admissioncode IS NOT NULL)) AND (serviceheader.serviceinvcode BETWEEN v_ai_sinvcode AND v_ai_linvcode)) AND (serviceheader.servicecatcode IN (v_ai_servicecatcode)));
    UPDATE dbo.serviceheader SET posted = 'Y', postdate = localtimestamp(3), postedby = v_ai_salesmancode WHERE (((((serviceheader.admissioncode = v_ai_admissioncode) AND (serviceheader.posted = 'N')) AND (serviceheader.admissioncode IS NOT NULL)) AND (serviceheader.serviceinvcode BETWEEN v_ai_sinvcode AND v_ai_linvcode)) AND (serviceheader.servicecatcode IN (v_ai_servicecatcode)));
  ELSE
    INSERT INTO tmp_lt_invoicelist (code) SELECT serviceinvcode FROM dbo.serviceheader WHERE ((((serviceheader.admissioncode IS NOT NULL) AND (serviceheader.posted = 'N')) AND (serviceheader.serviceinvcode BETWEEN v_ai_sinvcode AND v_ai_linvcode)) AND (serviceheader.servicecatcode IN (v_ai_servicecatcode)));
    UPDATE dbo.serviceheader SET posted = 'Y', postdate = localtimestamp(3), postedby = v_ai_salesmancode WHERE ((((serviceheader.admissioncode IS NOT NULL) AND (serviceheader.posted = 'N')) AND (serviceheader.serviceinvcode BETWEEN v_ai_sinvcode AND v_ai_linvcode)) AND (serviceheader.servicecatcode IN (v_ai_servicecatcode)));
  END IF;
  v_rowid := 1;
  v_totrows := coalesce((SELECT count(*) FROM tmp_lt_invoicelist AS lt_invoicelist), 0);
  WHILE (v_rowid <= v_totrows) LOOP
    v_serviceinvcode := (SELECT code FROM tmp_lt_invoicelist AS lt_invoicelist WHERE (rowid = v_rowid));
    SELECT r.return_value, r.serviceresultcode INTO v_rt_code, v_serviceresultcode FROM dbo.sp_autogenerateserviceresult(serviceinvcode => v_serviceinvcode, usercode => (v_ai_salesmancode)::smallint, serviceresultcode => v_serviceresultcode) AS r;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      RAISE EXCEPTION 'Unable to Generate Service Result for Service Invoice Code = %', v_serviceinvcode;
      return_value := -1;
      RETURN;
    END IF;
    SELECT r.return_value INTO v_rt_code FROM dbo.sp_autogenerateserviceinvpurtemplate(serviceinvcode => v_serviceinvcode, usercode => (v_ai_salesmancode)::smallint) AS r;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      RAISE EXCEPTION 'Unable to Generate Service Purchase Template for Service Invoice Code = %', v_serviceinvcode;
      return_value := -1;
      RETURN;
    END IF;
    v_rowid := (v_rowid + 1);
  END LOOP;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_PostServiceIssueRequest ====
CREATE OR REPLACE FUNCTION dbo.sp_postserviceissuerequest(ai_sinvcode integer, ai_linvcode integer, usercode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_sinvcode integer;
  v_ai_linvcode integer;
  v_usercode integer;
  v_rowid integer;
  v_totrows integer;
  v_rt_code integer;
  v_issueinvcode integer;
  v_errcode integer;
  v_code integer;
BEGIN
  v_ai_sinvcode := ai_sinvcode;
  v_ai_linvcode := ai_linvcode;
  v_usercode := usercode;
  DROP TABLE IF EXISTS tmp_lt_invoicelist;
  CREATE TEMP TABLE tmp_lt_invoicelist (
    code integer NOT NULL,
    rowid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_invoicelist (code) SELECT serviceissuerequestcode FROM dbo.serviceissuerequest WHERE ((serviceissuerequestcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (posted = 'N'));
  UPDATE dbo.serviceissuerequest SET posted = 'Y', postdate = localtimestamp(3), postedby = v_usercode WHERE ((serviceissuerequestcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (posted = 'N'));
  v_rowid := 1;
  v_totrows := coalesce((SELECT count(*) FROM tmp_lt_invoicelist AS lt_invoicelist), 0);
  WHILE (v_rowid <= v_totrows) LOOP
    v_code := (SELECT code FROM tmp_lt_invoicelist AS lt_invoicelist WHERE (rowid = v_rowid));
    SELECT r.return_value, r.issueinvcode INTO v_errcode, v_issueinvcode FROM dbo.sp_autoissueconsumableitem(serviceissuerequestcode => v_code, usercode => v_usercode, issueinvcode => v_issueinvcode) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Problem while Generation of Issue against Service Consumable Items.';
      return_value := -1;
      RETURN;
    END IF;
    v_rowid := (v_rowid + 1);
  END LOOP;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

