-- ==== proc sp_PostStockAdjustment ====
CREATE OR REPLACE FUNCTION dbo.sp_poststockadjustment(adjbuffercode integer, usercode smallint, headerno smallint, serverdate timestamp, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_adjbuffercode integer;
  v_usercode smallint;
  v_headerno smallint;
  v_serverdate timestamp(3);
  v_adjinccode integer;
  v_adjdeccode integer;
  v_headerinvno integer;
  v_adjutn bigint;
  v_icode integer;
  v_gcode smallint;
  v_batch citext;
  v_expiry timestamp(3);
  v_defaultbatch citext;
  v_defaultexpiry timestamp(3);
  v_reqqty numeric(15,4);
  v_givenqty numeric(15,4);
  v_totalqty numeric(15,4);
  v_currqty numeric(15,4);
  v_delqty numeric(15,4);
  v_batchqty numeric(15,4);
  v_newqty numeric(15,4);
  v_totstock numeric(15,4);
  v_hold_avgprice numeric(15,5);
  v_packunits smallint;
  v_price numeric(12,2);
  v_purprice numeric(12,2);
  v_saleprice numeric(12,2);
  v_recentpurprice numeric(12,2);
  v_newavgprice numeric(15,5);
  v_adjinc_items_rows integer;
  v_adjdec_items_rows integer;
  v_totalrows integer;
  v_counter integer;
  v_module smallint;
  v_continue integer;
  v_err integer;
  v_rowcount integer;
  v_rt_code integer;
  v_err_string citext;
  v_itemname citext;
  v_updateavgprice citext;
  v_remarks citext;
  v_alternatecustomicode citext;
  cur_cursor_adjinc_items refcursor;
  cur_cursor_adjdec_items refcursor;
  cur_itembatch_cursor refcursor;
  _rc integer;
  _fs integer := -1;
BEGIN
  v_adjbuffercode := adjbuffercode;
  v_usercode := usercode;
  v_headerno := headerno;
  v_serverdate := serverdate;
  v_remarks := (SELECT coalesce(remarks, '') FROM dbo.adjbufferheader WHERE (adjbuffercode = v_adjbuffercode));
  _rc := 1;
  v_remarks := (((v_adjbuffercode)::text || ' , ') || v_remarks);
  _rc := 1;
  v_rt_code := (SELECT count(*) FROM dbo.adjbufferheader WHERE ((adjbuffercode = v_adjbuffercode) AND (posted = 'Y')));
  _rc := 1;
  IF (v_rt_code > 0) THEN
    return_value := 0;
    RETURN;
  END IF;
  v_continue := 0;
  _rc := 1;
  v_gcode := (SELECT gcode FROM dbo.adjbufferheader WHERE (adjbuffercode = v_adjbuffercode));
  _rc := 1;
  v_module := (SELECT module FROM dbo.module WHERE (name = 'Adjustment'));
  _rc := 1;
  v_defaultbatch := dbo.fn_getpreference('defaultbatch');
  _rc := 1;
  v_defaultexpiry := dbo.fn_get_datetime_preference('defaultexpiry');
  _rc := 1;
  v_updateavgprice := dbo.fn_getpreference('UpdAvgPriceInAdjInc');
  _rc := 1;
  OPEN cur_cursor_adjinc_items FOR SELECT adjbufferdetail.icode, ((stockonshelf - stockinhand)) AS givenqty, packunits, purprice, saleprice, recentpurprice, alternatecustomicode FROM dbo.adjbufferdetail JOIN dbo.item ON (adjbufferdetail.icode = item.icode) WHERE ((adjbuffercode = v_adjbuffercode) AND (((stockonshelf - stockinhand)) > 0)) ORDER BY rowid;
  v_adjinc_items_rows := (-1);
  _rc := 1;
  IF (v_adjinc_items_rows > 0) THEN
    SELECT r.return_value, r.key INTO v_rt_code, v_adjinccode FROM dbo.sp_gettabmaxkey(tabname => 'AdjHeader', key => v_adjinccode) AS r;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      v_continue := -1;
      _rc := 1;
    ELSE
      SELECT r.return_value, r.key INTO v_rt_code, v_headerinvno FROM dbo.sp_getheadertabmaxkey(headercode => v_headerno, modulecode => v_module, key => v_headerinvno) AS r;
      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
        v_continue := -1;
        _rc := 1;
      ELSE
        INSERT INTO dbo.adjheader (adjcode, adjcatcode, usercode, remarks, date, modifieddate, modifiedby, posted, posteddate, postedby, headerno, headerinvno) VALUES (v_adjinccode, 1, v_usercode, v_remarks, v_serverdate, v_serverdate, NULL::integer, 'Y', v_serverdate, v_usercode, v_headerno, v_headerinvno);
        GET DIAGNOSTICS _rc = ROW_COUNT;
        v_err := 0;
        v_rowcount := _rc;
        _rc := 1;
        IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
          RAISE EXCEPTION 'Error occured in inserting record into Adjustment Increase Header for Stock Adjustment : %', v_adjbuffercode;
          v_continue := -1;
          _rc := 1;
        ELSE
          FETCH NEXT FROM cur_cursor_adjinc_items INTO v_icode, v_givenqty, v_packunits, v_purprice, v_saleprice, v_recentpurprice, v_alternatecustomicode;
          IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
          WHILE ((_fs = 0) AND (v_continue >= 0)) LOOP
            SELECT r.return_value, r.avgprice INTO v_rt_code, v_hold_avgprice FROM dbo.sp_getitemavgprice(icode => v_icode, avgprice => v_hold_avgprice) AS r;
            IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
              v_continue := -1;
              _rc := 1;
            ELSE
              SELECT r.return_value, r.lbi_maxutn INTO v_rt_code, v_adjutn FROM dbo.sp_maxutn(lbi_rows => (1)::bigint, lbi_maxutn => v_adjutn) AS r;
              IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                v_continue := -1;
                _rc := 1;
              END IF;
              v_packunits := CASE WHEN (v_packunits IS NULL) THEN 1 WHEN (v_packunits = 0) THEN 1 ELSE v_packunits END;
              _rc := 1;
              IF ((v_hold_avgprice IS NULL) OR (v_hold_avgprice = 0)) THEN
                v_price := (v_purprice / v_packunits);
                _rc := 1;
              ELSE
                v_price := (v_hold_avgprice)::numeric(8,2);
                _rc := 1;
              END IF;
              SELECT r.return_value, r.qty INTO v_rt_code, v_totstock FROM dbo.sp_getitemstockall(icode => v_icode, qty => v_totstock) AS r;
              IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                v_continue := -1;
                _rc := 1;
              END IF;
              IF (v_updateavgprice = 'Y') THEN
                v_newavgprice := coalesce((SELECT round(((((((v_totstock * v_hold_avgprice)) + ((v_givenqty * v_price)))) / ((v_givenqty + v_totstock))))::numeric, 5)), 0);
                _rc := 1;
                SELECT r.return_value INTO v_rt_code FROM dbo.sp_updateitemavgprice(icode => v_icode, avgprice => v_newavgprice) AS r;
                IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                  v_continue := -1;
                  _rc := 1;
                END IF;
              ELSE
                v_newavgprice := v_hold_avgprice;
                _rc := 1;
              END IF;
              IF (v_continue <> -1) THEN
                INSERT INTO dbo.adjdetail (adjcode, gcode, icode, batch, expiry, looseqty, priority, price, avgprice, packunits, saleprice, purprice, recentpurprice, adjutn, updateavgprice, newavgprice, currstock, alternatecustomicode) VALUES (v_adjinccode, v_gcode, v_icode, v_defaultbatch, v_defaultexpiry, v_givenqty, 0, v_price, v_hold_avgprice, v_packunits, v_saleprice, v_purprice, v_recentpurprice, v_adjutn, v_updateavgprice, v_newavgprice, v_totstock, v_alternatecustomicode);
                GET DIAGNOSTICS _rc = ROW_COUNT;
                v_err := 0;
                v_rowcount := _rc;
                _rc := 1;
                IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
                  RAISE EXCEPTION 'Error occured in inserting record into Adjustment Increase Detail for Stock Adjustment : %', v_adjbuffercode;
                  v_continue := -1;
                  _rc := 1;
                ELSE
                  SELECT r.return_value, r.qty INTO v_rt_code, v_currqty FROM dbo.sp_getitemstockbatch(gcode => (v_gcode)::integer, icode => v_icode, batch => v_defaultbatch, expiry => v_defaultexpiry, qty => v_currqty) AS r;
                  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                    v_continue := -1;
                    _rc := 1;
                  ELSE
                    v_newqty := (v_currqty + v_givenqty);
                    _rc := 1;
                    SELECT r.return_value INTO v_rt_code FROM dbo.sp_updateitemstockbatch(gcode => (v_gcode)::integer, icode => v_icode, batch => v_defaultbatch, expiry => v_defaultexpiry, newqty => v_newqty) AS r;
                    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                      v_continue := -1;
                      _rc := 1;
                    END IF;
                  END IF;
                END IF;
              END IF;
            END IF;
            FETCH NEXT FROM cur_cursor_adjinc_items INTO v_icode, v_givenqty, v_packunits, v_purprice, v_saleprice, v_recentpurprice, v_alternatecustomicode;
            IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
          END LOOP;
        END IF;
      END IF;
    END IF;
  END IF;
  CLOSE cur_cursor_adjinc_items;
  -- DEALLOCATE Cursor_AdjInc_Items
  IF (v_continue <> 0) THEN
    return_value := -1;
    RETURN;
  ELSE
    v_continue := 0;
    _rc := 1;
    OPEN cur_cursor_adjdec_items FOR SELECT adjbufferdetail.icode, abs((stockonshelf - stockinhand)) AS givenqty, packunits, purprice, saleprice, recentpurprice, alternatecustomicode FROM dbo.adjbufferdetail JOIN dbo.item ON (adjbufferdetail.icode = item.icode) WHERE (((adjbuffercode = v_adjbuffercode) AND (stockonshelf <> stockinhand)) AND (((stockonshelf - stockinhand)) <= 0)) ORDER BY rowid;
    v_adjdec_items_rows := (-1);
    _rc := 1;
    IF (v_adjdec_items_rows > 0) THEN
      SELECT r.return_value, r.key INTO v_rt_code, v_adjdeccode FROM dbo.sp_gettabmaxkey(tabname => 'AdjHeader', key => v_adjdeccode) AS r;
      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
        v_continue := -1;
        _rc := 1;
      ELSE
        SELECT r.return_value, r.key INTO v_rt_code, v_headerinvno FROM dbo.sp_getheadertabmaxkey(headercode => v_headerno, modulecode => v_module, key => v_headerinvno) AS r;
        IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
          v_continue := -1;
          _rc := 1;
        ELSE
          INSERT INTO dbo.adjheader (adjcode, adjcatcode, usercode, remarks, date, modifieddate, modifiedby, posted, posteddate, postedby, headerno, headerinvno) VALUES (v_adjdeccode, 2, v_usercode, v_remarks, v_serverdate, v_serverdate, NULL::integer, 'Y', v_serverdate, v_usercode, v_headerno, v_headerinvno);
          GET DIAGNOSTICS _rc = ROW_COUNT;
          v_err := 0;
          v_rowcount := _rc;
          _rc := 1;
          IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
            RAISE EXCEPTION 'Error occured in inserting record into Adjustment Decrease for Stock Adjustment : %', v_adjbuffercode;
            v_continue := -1;
            _rc := 1;
          ELSE
            FETCH NEXT FROM cur_cursor_adjdec_items INTO v_icode, v_givenqty, v_packunits, v_purprice, v_saleprice, v_recentpurprice, v_alternatecustomicode;
            IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
            WHILE ((_fs = 0) AND (v_continue >= 0)) LOOP
              SELECT r.return_value, r.avgprice INTO v_rt_code, v_hold_avgprice FROM dbo.sp_getitemavgprice(icode => v_icode, avgprice => v_hold_avgprice) AS r;
              IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                v_continue := -1;
                _rc := 1;
              ELSE
                v_packunits := CASE WHEN (v_packunits IS NULL) THEN 1 WHEN (v_packunits = 0) THEN 1 ELSE v_packunits END;
                _rc := 1;
                v_totalqty := (SELECT coalesce(sum(currqty), 0) FROM dbo.godowndetail WHERE ((godowndetail.gcode = v_gcode) AND (godowndetail.icode = v_icode)));
                _rc := 1;
                IF (v_totalqty >= v_givenqty) THEN
                  v_reqqty := v_givenqty;
                  _rc := 1;
                  OPEN cur_itembatch_cursor FOR SELECT batch, expiry, currqty FROM dbo.godowndetail WHERE ((godowndetail.gcode = v_gcode) AND (godowndetail.icode = v_icode)) ORDER BY priority, expiry, currqty;
                  v_totalrows := (-1);
                  _rc := 1;
                  FETCH NEXT FROM cur_itembatch_cursor INTO v_batch, v_expiry, v_currqty;
                  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
                  v_counter := 1;
                  _rc := 1;
                  WHILE (((_fs = 0) AND (v_counter <= v_totalrows)) AND (v_reqqty > 0)) LOOP
                    v_batchqty := v_currqty;
                    _rc := 1;
                    IF (v_batchqty >= v_reqqty) THEN
                      v_delqty := v_reqqty;
                      _rc := 1;
                    ELSE
                      v_delqty := v_batchqty;
                      _rc := 1;
                    END IF;
                    v_reqqty := (v_reqqty - v_delqty);
                    _rc := 1;
                    SELECT r.return_value, r.lbi_maxutn INTO v_rt_code, v_adjutn FROM dbo.sp_maxutn(lbi_rows => (1)::bigint, lbi_maxutn => v_adjutn) AS r;
                    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                      v_continue := -1;
                      _rc := 1;
                    END IF;
                    SELECT r.return_value, r.qty INTO v_rt_code, v_totstock FROM dbo.sp_getitemstockall(icode => v_icode, qty => v_totstock) AS r;
                    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                      v_continue := -1;
                      _rc := 1;
                    END IF;
                    v_newavgprice := v_hold_avgprice;
                    _rc := 1;
                    INSERT INTO dbo.adjdetail (adjcode, gcode, icode, batch, expiry, looseqty, priority, price, avgprice, packunits, saleprice, purprice, recentpurprice, adjutn, updateavgprice, newavgprice, currstock, alternatecustomicode) VALUES (v_adjdeccode, v_gcode, v_icode, v_batch, v_expiry, v_delqty, 0, v_hold_avgprice, v_hold_avgprice, v_packunits, v_saleprice, v_purprice, v_recentpurprice, v_adjutn, v_updateavgprice, v_newavgprice, v_totstock, v_alternatecustomicode);
                    GET DIAGNOSTICS _rc = ROW_COUNT;
                    v_err := 0;
                    v_rowcount := _rc;
                    _rc := 1;
                    IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
                      RAISE EXCEPTION 'Error occured in inserting record into Adjustment Decrease Detail for Stock Adjustment : %', v_adjbuffercode;
                      v_continue := -1;
                      _rc := 1;
                    ELSE
                      v_newqty := (v_currqty - v_delqty);
                      _rc := 1;
                      IF (v_newqty > 0) THEN
                        SELECT r.return_value INTO v_rt_code FROM dbo.sp_saleupdateitemstockbatch(gcode => (v_gcode)::integer, icode => v_icode, batch => v_batch, expiry => v_expiry, newqty => v_newqty, oldqty => v_currqty) AS r;
                      ELSE
                        SELECT r.return_value INTO v_rt_code FROM dbo.sp_deleteitemstockbatch(gcode => (v_gcode)::integer, icode => v_icode, batch => v_batch, expiry => v_expiry, oldqty => v_delqty) AS r;
                      END IF;
                      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                        v_continue := -1;
                        _rc := 1;
                      END IF;
                    END IF;
                    v_counter := (v_counter + 1);
                    _rc := 1;
                    FETCH NEXT FROM cur_itembatch_cursor INTO v_batch, v_expiry, v_currqty;
                    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
                  END LOOP;
                  CLOSE cur_itembatch_cursor;
                  -- DEALLOCATE ItemBatch_Cursor
                ELSE
                  v_itemname := (SELECT name FROM dbo.item WHERE (icode = v_icode));
                  _rc := 1;
                  RAISE EXCEPTION 'Not enough stock for item (%) to decrease for Stock Adjusment : %', v_itemname, v_adjbuffercode;
                  v_continue := -1;
                  _rc := 1;
                END IF;
              END IF;
              FETCH NEXT FROM cur_cursor_adjdec_items INTO v_icode, v_givenqty, v_packunits, v_purprice, v_saleprice, v_recentpurprice, v_alternatecustomicode;
              IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
            END LOOP;
          END IF;
        END IF;
      END IF;
    END IF;
    CLOSE cur_cursor_adjdec_items;
    -- DEALLOCATE Cursor_AdjDec_Items
    IF (v_continue <> 0) THEN
      return_value := -1;
      RETURN;
    ELSE
      UPDATE dbo.adjbufferheader SET posted = 'Y', postedby = v_usercode, posteddate = localtimestamp(3), adjinccode = CASE WHEN (v_adjinc_items_rows > 0) THEN v_adjinccode ELSE NULL END, adjdeccode = CASE WHEN (v_adjdec_items_rows > 0) THEN v_adjdeccode ELSE NULL END WHERE (adjbuffercode = v_adjbuffercode);
      GET DIAGNOSTICS _rc = ROW_COUNT;
      IF ((0 <> 0) OR (_rc = 0)) THEN
        RAISE EXCEPTION 'Posting fail for Stock Adjustment (%) due to updation problem.', v_adjbuffercode;
        return_value := -1;
        RETURN;
      END IF;
      IF (v_adjinccode > 0) THEN
        IF ((SELECT dbo.fn_getpreference('IncAdjInActMonitor') AS a) = 'Y') THEN
          SELECT r.return_value INTO v_rt_code FROM dbo.sp_updateactivitymonitor(documenttype => 'AI', documentcode => v_adjinccode) AS r;
          IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
            RAISE EXCEPTION 'Posting fail for Stock Adjustment (%) due to activity monitor updation problem.', v_adjbuffercode;
            return_value := -1;
            RETURN;
          END IF;
        END IF;
      END IF;
      IF (v_adjdeccode > 0) THEN
        IF ((SELECT dbo.fn_getpreference('IncAdjInActMonitor') AS a) = 'Y') THEN
          SELECT r.return_value INTO v_rt_code FROM dbo.sp_updateactivitymonitor(documenttype => 'AD', documentcode => v_adjdeccode) AS r;
          IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
            RAISE EXCEPTION 'Posting fail for Stock Adjustment (%) due to activity monitor updation problem.', v_adjbuffercode;
            return_value := -1;
            RETURN;
          END IF;
        END IF;
      END IF;
      return_value := 0;
      RETURN;
    END IF;
  END IF;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_PostStudentFeeSheet ====
CREATE OR REPLACE FUNCTION dbo.sp_poststudentfeesheet(ai_code integer, ai_usercode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_code integer;
  v_ai_usercode integer;
  v_rowid integer;
  v_totrows integer;
  v_rt_code integer;
  v_serviceinvcode integer;
  v_classcode integer;
  v_studentcode integer;
  v_rollno citext;
  v_servicecode integer;
  v_remarks citext;
  v_fee numeric(15,2);
  v_flatdisc numeric(15,2);
  v_discperc numeric(5,2);
  v_usercode smallint;
  v_servicetemplate integer;
  v_servicetemplatecode integer;
  v_errcode integer;
  v_end_invcode integer;
  v_feeday integer;
  v_today integer;
  v_duedate timestamp(3);
  v_newduedate timestamp(3);
  v_netamount numeric(15,2);
  cur_c1 refcursor;
  cur_c2 refcursor;
  _rc integer;
  _fs integer := -1;
BEGIN
  v_ai_code := ai_code;
  v_ai_usercode := ai_usercode;
  v_usercode := v_ai_usercode;
  _rc := 1;
  OPEN cur_c1 FOR SELECT d.studentcode, d.classcode, d.rollno, sum(((((d.fee - d.flatdisc)) * ((1 - (d.discperc * 0.01)))))) AS netamount, s.remarks, d.servicetemplatecode, d.duedate FROM dbo.studentfeesheetdetail AS d, dbo.studentfeesheet AS s, dbo.class AS c, dbo.student AS st WHERE (((((s.studentfeesheetcode = v_ai_code) AND (s.studentfeesheetcode = d.studentfeesheetcode)) AND (d.classcode = c.classcode)) AND (d.studentcode = st.studentcode)) AND (((((d.fee - d.flatdisc)) * ((1 - (d.discperc * 0.01))))) > 0)) GROUP BY d.classcode, c.name, d.rollno, d.studentcode, st.name, s.remarks, d.servicetemplatecode, d.duedate ORDER BY c.name, d.rollno, st.name;
  v_totrows := (-1);
  _rc := 1;
  IF (v_totrows > 0) THEN
    FETCH NEXT FROM cur_c1 INTO v_studentcode, v_classcode, v_rollno, v_netamount, v_remarks, v_servicetemplatecode, v_duedate;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    WHILE (_fs = 0) LOOP
      v_newduedate := v_duedate;
      _rc := 1;
      IF (v_newduedate IS NULL) THEN
        v_feeday := coalesce((SELECT class.feedueon FROM dbo.class WHERE (class.classcode = v_classcode)), 1);
        _rc := 1;
        v_today := (SELECT extract(day from localtimestamp(3))::integer);
        _rc := 1;
        IF (v_today >= v_feeday) THEN
          IF (extract(month from localtimestamp(3))::integer < 12) THEN
            v_duedate := (((((ltrim(rtrim(dbo.tsql_str((extract(year from localtimestamp(3))::integer)::numeric, 7))) || '-') || ltrim(rtrim(dbo.tsql_str(((extract(month from localtimestamp(3))::integer + 1))::numeric, 7)))) || '-') || ltrim(rtrim(dbo.tsql_str((v_feeday)::numeric, 7)))))::timestamp(3);
            _rc := 1;
          ELSE
            v_duedate := (((((ltrim(rtrim(dbo.tsql_str(((extract(year from localtimestamp(3))::integer + 1))::numeric, 7))) || '-') || '01') || '-') || ltrim(rtrim(dbo.tsql_str((v_feeday)::numeric, 7)))))::timestamp(3);
            _rc := 1;
          END IF;
        ELSE
          v_duedate := (((((ltrim(rtrim(dbo.tsql_str((extract(year from localtimestamp(3))::integer)::numeric, 7))) || '-') || ltrim(rtrim(dbo.tsql_str((extract(month from localtimestamp(3))::integer)::numeric, 7)))) || '-') || ltrim(rtrim(dbo.tsql_str((v_feeday)::numeric, 7)))))::timestamp(3);
          _rc := 1;
        END IF;
      ELSE
        v_duedate := v_newduedate;
        _rc := 1;
      END IF;
      v_duedate := coalesce(v_duedate, localtimestamp(3));
      _rc := 1;
      v_errcode := 0;
      _rc := 1;
      SELECT r.return_value, r.key INTO v_errcode, v_serviceinvcode FROM dbo.sp_locktabmaxkey(tabname => 'ServiceHeader', key => v_serviceinvcode) AS r;
      IF ((0 <> 0) OR (v_errcode <> 0)) THEN
        RAISE EXCEPTION 'Problem while Fetching ServiceHeader Key Value';
        return_value := -1;
        RETURN;
      END IF;
      v_serviceinvcode := (v_serviceinvcode + 1);
      _rc := 1;
      INSERT INTO dbo.serviceheader (serviceinvcode, custcode, salesmancode, servicecatcode, remarks, originaldate, modifiedby, date, postedby, postdate, headerno, discperc, flatdisc, misccharges, saleinvcode, posted, reprintingcounter, serviceocode, cashreceived, cashtendered, cashcharged, cashback, studentcode, duedate) SELECT v_serviceinvcode, s.custcode AS custcode, v_usercode AS salesmancode, 11 AS serivcecatcode, v_remarks AS remarks, localtimestamp(3) AS originaldate, NULL::smallint AS modifiedby, localtimestamp(3) AS date, v_usercode AS postedby, localtimestamp(3) AS postdate, 1 AS headerno, 0 AS discperc, 0 AS flatdisc, 0 AS misccharges, NULL::integer AS saleinvcode, 'Y' AS posted, 0 AS reprintingcounter, NULL::integer AS serviceocode, 0 AS cashreceived, 0 AS cashtendered, 0 AS cashcharged, 0 AS cashback, s.studentcode AS studentcode, v_duedate AS duedate FROM dbo.student AS s WHERE (s.studentcode = v_studentcode);
      GET DIAGNOSTICS _rc = ROW_COUNT;
      IF ((0 <> 0) OR (_rc = 0)) THEN
        RAISE EXCEPTION 'Problem while Inserting Record in ServiceHeader';
        return_value := -1;
        RETURN;
      END IF;
      OPEN cur_c2 FOR SELECT d.servicecode, d.fee, d.flatdisc, d.discperc, d.rowid FROM dbo.studentfeesheetdetail AS d, dbo.studentfeesheet AS s, dbo.class AS c, dbo.student AS st WHERE ((((((((s.studentfeesheetcode = v_ai_code) AND (s.studentfeesheetcode = d.studentfeesheetcode)) AND (d.studentcode = v_studentcode)) AND (d.classcode = v_classcode)) AND (d.rollno = v_rollno)) AND (d.classcode = c.classcode)) AND (d.studentcode = st.studentcode)) AND (((((d.fee - d.flatdisc)) * ((1 - (d.discperc * 0.01))))) > 0)) ORDER BY d.rowid, st.name;
      FETCH NEXT FROM cur_c2 INTO v_servicecode, v_fee, v_flatdisc, v_discperc, v_rowid;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
      WHILE (_fs = 0) LOOP
        INSERT INTO dbo.servicedetail (serviceinvcode, servicecode, smancode, qty, price, serviceflatdisc, discperc, remarks) SELECT v_serviceinvcode, v_servicecode, 1 AS smancode, 1 AS qty, v_fee AS saleprice, CASE WHEN (round(((((v_fee - v_flatdisc)) * ((1 - (v_discperc * 0.01)))))::numeric, 2) > 0) THEN v_flatdisc ELSE v_fee END AS serviceflatdisc, v_discperc AS discperc, v_remarks;
        GET DIAGNOSTICS _rc = ROW_COUNT;
        IF ((0 <> 0) OR (_rc = 0)) THEN
          RAISE EXCEPTION 'Problem while Inserting Record in ServiceDetail';
          return_value := -1;
          RETURN;
        END IF;
        UPDATE dbo.studentclass AS studentclass SET lastserviceinvdate = localtimestamp(3), serviceinvcode = v_serviceinvcode WHERE ((classcode = v_classcode) AND (studentcode = v_studentcode));
        GET DIAGNOSTICS _rc = ROW_COUNT;
        IF ((0 <> 0) OR (_rc = 0)) THEN
          RAISE EXCEPTION 'Problem in Updating Student Fee Record';
          return_value := -1;
          RETURN;
        END IF;
        FETCH NEXT FROM cur_c2 INTO v_servicecode, v_fee, v_flatdisc, v_discperc, v_rowid;
        IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
      END LOOP;
      CLOSE cur_c2;
      -- DEALLOCATE C2
      v_errcode := 0;
      _rc := 1;
      SELECT r.return_value INTO v_errcode FROM dbo.sp_updatetabmaxkey(tabname => 'ServiceHeader', key => v_serviceinvcode) AS r;
      IF ((0 <> 0) OR (v_errcode <> 0)) THEN
        RAISE EXCEPTION 'Problem while Updating ServiceHeader Key Value';
        return_value := -1;
        RETURN;
      END IF;
      UPDATE dbo.serviceheader SET invtotal = coalesce(dbo.fn_getserviceinvtotal((serviceinvcode)::integer), 0) WHERE (serviceinvcode = v_serviceinvcode);
      GET DIAGNOSTICS _rc = ROW_COUNT;
      UPDATE dbo.serviceheader SET outstandingamt = coalesce(dbo.fn_getserviceinvtotal((serviceinvcode)::integer), 0) WHERE (serviceinvcode = v_serviceinvcode);
      GET DIAGNOSTICS _rc = ROW_COUNT;
      UPDATE dbo.studentfeesheetdetail SET serviceinvcode = v_serviceinvcode WHERE ((((studentfeesheetcode = v_ai_code) AND (studentcode = v_studentcode)) AND (classcode = v_classcode)) AND (rollno = v_rollno));
      GET DIAGNOSTICS _rc = ROW_COUNT;
      FETCH NEXT FROM cur_c1 INTO v_studentcode, v_classcode, v_rollno, v_netamount, v_remarks, v_servicetemplatecode, v_duedate;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    END LOOP;
    UPDATE dbo.studentfeesheet SET posted = 'Y', postedby = v_ai_usercode, postedon = localtimestamp(3) WHERE (studentfeesheetcode = v_ai_code);
    GET DIAGNOSTICS _rc = ROW_COUNT;
  END IF;
  CLOSE cur_c1;
  -- DEALLOCATE C1
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_PostTransactionsBeforeAutoMigration ====
CREATE OR REPLACE FUNCTION dbo.sp_posttransactionsbeforeautomigration(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_errorno integer;
  v_rowsaffected integer;
  _rc integer;
BEGIN
  UPDATE dbo.saleledger SET posted = 'Y', postdate = localtimestamp(3), postedby = 1 WHERE (posted = 'N');
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_errorno := 0;
  v_rowsaffected := _rc;
  _rc := 1;
  IF (v_errorno <> 0) THEN
    RAISE EXCEPTION 'Error Posting Some Sale Invoices.';
    return_value := v_errorno;
    RETURN;
  END IF;
  UPDATE dbo.srledger SET posted = 'Y', postdate = localtimestamp(3), postedby = 1 WHERE (posted = 'N');
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_errorno := 0;
  v_rowsaffected := _rc;
  _rc := 1;
  IF (v_errorno <> 0) THEN
    RAISE EXCEPTION 'Error Posting Some Sale Return Invoices.';
    return_value := v_errorno;
    RETURN;
  END IF;
  UPDATE dbo.srbufferledger SET posted = 'Y', postdate = localtimestamp(3), postedby = 1 WHERE (posted = 'N');
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_errorno := 0;
  v_rowsaffected := _rc;
  _rc := 1;
  IF (v_errorno <> 0) THEN
    RAISE EXCEPTION 'Error Posting Some Sale Return Buffer Invoices.';
    return_value := v_errorno;
    RETURN;
  END IF;
  UPDATE dbo.advsaleledger SET posted = 'Y', postdate = localtimestamp(3), postedby = 1 WHERE (posted = 'N');
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_errorno := 0;
  v_rowsaffected := _rc;
  _rc := 1;
  IF (v_errorno <> 0) THEN
    RAISE EXCEPTION 'Error Posting Some Advanced Sale Invoices.';
    return_value := v_errorno;
    RETURN;
  END IF;
  UPDATE dbo.advpurheader SET posted = 'Y', postdate = localtimestamp(3), postedby = 1 WHERE (posted = 'N');
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_errorno := 0;
  v_rowsaffected := _rc;
  _rc := 1;
  IF (v_errorno <> 0) THEN
    RAISE EXCEPTION 'Error Posting Some Advanced Purchase Invoices.';
    return_value := v_errorno;
    RETURN;
  END IF;
  UPDATE dbo.imppurheader SET posted = 'Y', posteddate = localtimestamp(3), postedby = 1 WHERE (posted = 'N');
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_errorno := 0;
  v_rowsaffected := _rc;
  _rc := 1;
  IF (v_errorno <> 0) THEN
    RAISE EXCEPTION 'Error Posting Some Imported Purchase Invoices.';
    return_value := v_errorno;
    RETURN;
  END IF;
  UPDATE dbo.purregister SET posted = 'Y', postdate = localtimestamp(3), postedby = 1 WHERE (posted = 'N');
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_errorno := 0;
  v_rowsaffected := _rc;
  _rc := 1;
  IF (v_errorno <> 0) THEN
    RAISE EXCEPTION 'Error Posting Some Purchase Register Invoices.';
    return_value := v_errorno;
    RETURN;
  END IF;
  UPDATE dbo.prledger SET posted = 'Y', postdate = localtimestamp(3), postedby = 1 WHERE (posted = 'N');
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_errorno := 0;
  v_rowsaffected := _rc;
  _rc := 1;
  IF (v_errorno <> 0) THEN
    RAISE EXCEPTION 'Error Posting Some Purchase Return Invoices.';
    return_value := v_errorno;
    RETURN;
  END IF;
  UPDATE dbo.issueheader SET posted = 'Y', postdate = localtimestamp(3), postedby = 1 WHERE (posted = 'N');
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_errorno := 0;
  v_rowsaffected := _rc;
  _rc := 1;
  IF (v_errorno <> 0) THEN
    RAISE EXCEPTION 'Error Posting Some Issue Invoices.';
    return_value := v_errorno;
    RETURN;
  END IF;
  UPDATE dbo.receiptheader SET posted = 'Y', postdate = localtimestamp(3), postedby = 1 WHERE (posted = 'N');
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_errorno := 0;
  v_rowsaffected := _rc;
  _rc := 1;
  IF (v_errorno <> 0) THEN
    RAISE EXCEPTION 'Error Posting Some Receipt Invoices.';
    return_value := v_errorno;
    RETURN;
  END IF;
  UPDATE dbo.theader SET posted = 'Y', postdate = localtimestamp(3), postedby = 1 WHERE (posted = 'N');
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_errorno := 0;
  v_rowsaffected := _rc;
  _rc := 1;
  IF (v_errorno <> 0) THEN
    RAISE EXCEPTION 'Error Posting Some Transfer Invoices.';
    return_value := v_errorno;
    RETURN;
  END IF;
  UPDATE dbo.adjheader SET posted = 'Y', posteddate = localtimestamp(3), postedby = 1 WHERE (posted = 'N');
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_errorno := 0;
  v_rowsaffected := _rc;
  _rc := 1;
  IF (v_errorno <> 0) THEN
    RAISE EXCEPTION 'Error Posting Some Adjustments.';
    return_value := v_errorno;
    RETURN;
  END IF;
  UPDATE dbo.adjbufferheader SET posted = 'Y', posteddate = localtimestamp(3), postedby = 1 WHERE (posted = 'N');
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_errorno := 0;
  v_rowsaffected := _rc;
  _rc := 1;
  IF (v_errorno <> 0) THEN
    RAISE EXCEPTION 'Error Posting Some Adjustment buffer documents.';
    return_value := v_errorno;
    RETURN;
  END IF;
  UPDATE dbo.serviceheader SET posted = 'Y', postdate = localtimestamp(3), postedby = 1 WHERE (posted = 'N');
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_errorno := 0;
  v_rowsaffected := _rc;
  _rc := 1;
  IF (v_errorno <> 0) THEN
    RAISE EXCEPTION 'Error Posting Some service Invoices.';
    return_value := v_errorno;
    RETURN;
  END IF;
  UPDATE dbo.servicerheader SET posted = 'Y', postdate = localtimestamp(3), postedby = 1 WHERE (posted = 'N');
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_errorno := 0;
  v_rowsaffected := _rc;
  _rc := 1;
  IF (v_errorno <> 0) THEN
    RAISE EXCEPTION 'Error Posting Some service return Invoices.';
    return_value := v_errorno;
    RETURN;
  END IF;
  UPDATE dbo.servicepurheader SET posted = 'Y', postdate = localtimestamp(3), postedby = 1 WHERE (posted = 'N');
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_errorno := 0;
  v_rowsaffected := _rc;
  _rc := 1;
  IF (v_errorno <> 0) THEN
    RAISE EXCEPTION 'Error Posting Some service purchase Invoices.';
    return_value := v_errorno;
    RETURN;
  END IF;
  UPDATE dbo.serviceprheader SET posted = 'Y', postdate = localtimestamp(3), postedby = 1 WHERE (posted = 'N');
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_errorno := 0;
  v_rowsaffected := _rc;
  _rc := 1;
  IF (v_errorno <> 0) THEN
    RAISE EXCEPTION 'Error Posting Some service purchase return Invoices.';
    return_value := v_errorno;
    RETURN;
  END IF;
  UPDATE dbo.glheader SET posted = 'Y', postdate = localtimestamp(3), postedby = 1 WHERE (posted = 'N');
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_errorno := 0;
  v_rowsaffected := _rc;
  _rc := 1;
  IF (v_errorno <> 0) THEN
    RAISE EXCEPTION 'Error Posting Some a/c vouchers.';
    return_value := v_errorno;
    RETURN;
  END IF;
  UPDATE dbo.notes SET posted = 'Y', postdate = localtimestamp(3), postedby = 1 WHERE (posted = 'N');
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_errorno := 0;
  v_rowsaffected := _rc;
  _rc := 1;
  IF (v_errorno <> 0) THEN
    RAISE EXCEPTION 'Error Posting Some notes receivables/payables.';
    return_value := v_errorno;
    RETURN;
  END IF;
  UPDATE dbo.transactionheader SET posted = 'Y', postdate = localtimestamp(3), postedby = 1 WHERE (posted = 'N');
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_errorno := 0;
  v_rowsaffected := _rc;
  _rc := 1;
  IF (v_errorno <> 0) THEN
    RAISE EXCEPTION 'Error Posting Some Transaction window entries.';
    return_value := v_errorno;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_PostTransferHeader ====
CREATE OR REPLACE FUNCTION dbo.sp_posttransferheader(ai_sinvcode integer, ai_linvcode integer, ai_strategy integer, ai_groupcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_sinvcode integer;
  v_ai_linvcode integer;
  v_ai_strategy integer;
  v_ai_groupcode integer;
BEGIN
  v_ai_sinvcode := ai_sinvcode;
  v_ai_linvcode := ai_linvcode;
  v_ai_strategy := ai_strategy;
  v_ai_groupcode := ai_groupcode;
  UPDATE dbo.theader SET posted = 'Y', postdate = localtimestamp(3) WHERE (((theader.transcode BETWEEN v_ai_sinvcode AND v_ai_linvcode) AND (theader.posted = 'N')) AND (sgcode IN (SELECT godown.gcode FROM dbo.godown WHERE (gcode IN (CASE v_ai_strategy WHEN 2 THEN (SELECT g.gcode FROM dbo.godown AS g WHERE (g.gcode = godown.gcode)) ELSE (SELECT g.gcode FROM dbo.groupallowedgodown AS g WHERE (((g.groupcode = v_ai_groupcode) AND (g.module = 8)) AND (godown.gcode = g.gcode))) END)))));
  return_value := 0;
  RETURN;
END
