-- ==== proc SP_PostVisit ====
CREATE OR REPLACE FUNCTION dbo.sp_postvisit(ai_svisitcode integer, ai_lvisitcode integer, ai_usercode integer, ai_doctcode smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_svisitcode integer;
  v_ai_lvisitcode integer;
  v_ai_usercode integer;
  v_ai_doctcode smallint;
BEGIN
  v_ai_svisitcode := ai_svisitcode;
  v_ai_lvisitcode := ai_lvisitcode;
  v_ai_usercode := ai_usercode;
  v_ai_doctcode := ai_doctcode;
  IF ((v_ai_doctcode = 0) OR (v_ai_doctcode IS NULL)) THEN
    UPDATE dbo.visitappointment SET appointmentstatuscode = 5, posted = 'Y' WHERE (appointmentcode IN (SELECT DISTINCT appointmentcode FROM dbo.visit WHERE (((visitcode BETWEEN v_ai_svisitcode AND v_ai_lvisitcode) AND (posted = 'N')) AND (doctcode IN (SELECT uad.doctcode FROM dbo.useralloweddoctor AS uad WHERE (uad.usercode = v_ai_usercode))))));
    UPDATE dbo.visit SET posted = 'Y' WHERE (((visitcode BETWEEN v_ai_svisitcode AND v_ai_lvisitcode) AND (posted = 'N')) AND (doctcode IN (SELECT uad.doctcode FROM dbo.useralloweddoctor AS uad WHERE (uad.usercode = v_ai_usercode))));
  ELSE
    UPDATE dbo.visitappointment SET appointmentstatuscode = 5, posted = 'Y' WHERE (appointmentcode IN (SELECT DISTINCT appointmentcode FROM dbo.visit WHERE ((((visitcode BETWEEN v_ai_svisitcode AND v_ai_lvisitcode) AND (doctcode = v_ai_doctcode)) AND (posted = 'N')) AND (doctcode IN (SELECT uad.doctcode FROM dbo.useralloweddoctor AS uad WHERE (uad.usercode = v_ai_usercode))))));
    UPDATE dbo.visit SET posted = 'Y' WHERE ((((visitcode BETWEEN v_ai_svisitcode AND v_ai_lvisitcode) AND (doctcode = v_ai_doctcode)) AND (posted = 'N')) AND (doctcode IN (SELECT uad.doctcode FROM dbo.useralloweddoctor AS uad WHERE (uad.usercode = v_ai_usercode))));
  END IF;
  return_value := 0;
  RETURN;
END
$body$;

