CREATE OR REPLACE FUNCTION dbo.sp_preserve_deletedsaleitemslog(icode integer, gcode smallint, packunits smallint, qty numeric, bonusqty numeric, saleprice numeric, discperc numeric, itemflatdisc numeric, unitsalestax numeric, gstperc numeric, date timestamp, machinename citext, usercode smallint, saleinvcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
