-- ==== proc sp_PRList_From_DropBox ====
CREATE OR REPLACE FUNCTION dbo.sp_prlist_from_dropbox(srv citext, db citext, owner citext, sitecode integer, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_sitecode integer;
  v_query citext;
  v_prefix citext;
  _dq1 text;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  v_sitecode := sitecode;
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  v_prefix := '';
  IF (((length(rtrim(ltrim(rtrim(v_srv)))) = 0) OR (v_srv IS NULL))) THEN
    v_prefix := '';
  ELSE
    v_prefix := (v_srv || '.');
  END IF;
  IF (((length(rtrim(ltrim(rtrim(v_db)))) = 0) OR (v_db IS NULL))) THEN
    v_prefix := v_prefix;
  ELSE
    v_prefix := ((v_prefix || v_db) || '.');
  END IF;
  IF (((length(rtrim(ltrim(rtrim(v_owner)))) = 0) OR (v_owner IS NULL))) THEN
    v_prefix := ((v_prefix || 'DBO') || '.');
  ELSE
    v_prefix := ((v_prefix || v_owner) || '.');
  END IF;
  v_query := (((('Select T.SiteCode, Site=(SELECT Site.Name + SPACE(1) + CHAR(45) + SPACE(1) + InstanceID FROM Site WHERE Site.Sitecode = T.SiteCode), T.PRInvCode, T.Date, T.InvTotal, T.Remarks, T.CustCode, T.DataCarryCustCode From  ' || v_prefix) || 'DB_PrLedger AS T  WHERE T.TargetSiteCode = ') || ltrim(rtrim(dbo.tsql_str((v_sitecode)::numeric)))) || ' AND T.Pulled = ''N''');
  _dq1 := v_query;
  IF _dq1 IS NOT NULL THEN
    IF _dq1 ~* '^[[:space:]]*select' THEN OPEN rs1 FOR EXECUTE dbo.tsql_dyn(_dq1); ELSE EXECUTE dbo.tsql_dyn(_dq1); END IF;
  END IF;
  return_value := 1;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_PromoteClass ====
CREATE OR REPLACE FUNCTION dbo.sp_promoteclass(promotioncode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_promotioncode integer;
  v_promotedstudents integer;
  v_err integer;
  v_thisid integer;
  v_studentcode integer;
  v_classcode integer;
  v_rollno citext;
  v_rowid integer;
  v_classfrom integer;
  _rc integer;
BEGIN
  v_promotioncode := promotioncode;
  v_promotedstudents := coalesce((SELECT count(*) FROM dbo.classpromotiondetail WHERE ((promotioncode = v_promotioncode) AND (promote = 'Y'))), 0);
  _rc := 1;
  IF (v_promotedstudents <= 0) THEN
    return_value := 0;
    RETURN;
  END IF;
  DROP TABLE IF EXISTS tv_sp_promoteclass_studentlist;
  CREATE TEMP TABLE tv_sp_promoteclass_studentlist (
    promoteclassfrom integer,
    promoteclassto integer,
    studentcode integer,
    rollno citext,
    rowid integer,
    thisid integer GENERATED BY DEFAULT AS IDENTITY
) ON COMMIT DROP;
  INSERT INTO tv_sp_promoteclass_studentlist (promoteclassfrom, promoteclassto, studentcode, rollno, rowid) SELECT c.promoteclassfrom, promoteclassto, d.studentcode, d.rollno, d.rowid FROM dbo.classpromotion AS c, dbo.classpromotiondetail AS d WHERE (((c.promotioncode = v_promotioncode) AND (c.promotioncode = d.promotioncode)) AND (promote = 'Y')) ORDER BY d.rowid;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_promotedstudents := coalesce((SELECT count(*) FROM tv_sp_promoteclass_studentlist AS studentlist), 0);
  _rc := 1;
  IF (v_promotedstudents <= 0) THEN
    return_value := 0;
    RETURN;
  END IF;
  v_thisid := 1;
  _rc := 1;
  WHILE (v_thisid <= v_promotedstudents) LOOP
    v_classfrom := (SELECT promoteclassfrom FROM tv_sp_promoteclass_studentlist AS studentlist WHERE (thisid = v_thisid));
    _rc := 1;
    v_classcode := (SELECT promoteclassto FROM tv_sp_promoteclass_studentlist AS studentlist WHERE (thisid = v_thisid));
    _rc := 1;
    v_studentcode := (SELECT studentcode FROM tv_sp_promoteclass_studentlist AS studentlist WHERE (thisid = v_thisid));
    _rc := 1;
    v_rollno := (SELECT rollno FROM tv_sp_promoteclass_studentlist AS studentlist WHERE (thisid = v_thisid));
    _rc := 1;
    v_rowid := (SELECT rowid FROM tv_sp_promoteclass_studentlist AS studentlist WHERE (thisid = v_thisid));
    _rc := 1;
    SELECT r.return_value, r.rollno INTO v_err, v_rollno FROM dbo.sp_admit_student(classcode => v_classcode, studentcode => v_studentcode, rollno => v_rollno) AS r;
    IF ((v_err <> 0) OR (0 <> 0)) THEN
      RAISE EXCEPTION 'Can Not Admit student in the specified class';
      return_value := -1;
      RETURN;
    END IF;
    UPDATE dbo.studentclass SET promotionrowid = v_rowid WHERE ((classcode = v_classfrom) AND (studentcode = v_studentcode));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((_rc = 0) AND (0 <> 0)) THEN
      RAISE EXCEPTION 'Can Not Update Record for Admitted student in the specified class';
      return_value := -1;
      RETURN;
    END IF;
    v_thisid := (v_thisid + 1);
    _rc := 1;
  END LOOP;
  UPDATE dbo.class SET promoted = 'Y' WHERE (classcode = v_classfrom);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_PurAndReturnCategoryWise ====
CREATE OR REPLACE FUNCTION dbo.sp_purandreturncategorywise(ad_date timestamp, ad_ldate timestamp, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ad_date timestamp(3);
  v_ad_ldate timestamp(3);
BEGIN
  v_ad_date := ad_date;
  v_ad_ldate := ad_ldate;
  DELETE FROM dbo.reportdata;
  INSERT INTO dbo.reportdata (code1, name1, value1, value2) SELECT a.icatcode, (SELECT name FROM dbo.itemcategory WHERE (icatcode = a.icatcode)) AS catname, (SELECT coalesce(sum(round(((((((pd.looseqty + pd.packqty)) * pd.purprice)) * ((1 - ((.01 * pd.discperc))))))::numeric, 2)), 0) FROM dbo.purdetail AS pd, dbo.purledger AS pl, dbo.item AS i WHERE ((((pl.date BETWEEN v_ad_date AND v_ad_ldate) AND (pl.purinvcode = pd.purinvcode)) AND (pd.icode = i.icode)) AND (i.icatcode = a.icatcode))) AS purvalue, (SELECT coalesce(sum(round(((((((prd.looseqty + prd.packqty)) * prd.prprice)) * ((1 - ((.01 * prd.discperc))))))::numeric, 2)), 0) FROM dbo.prdetail AS prd, dbo.prledger AS prl, dbo.item AS i WHERE ((((prl.date BETWEEN v_ad_date AND v_ad_ldate) AND (prl.prinvcode = prd.prinvcode)) AND (prd.icode = i.icode)) AND (i.icatcode = a.icatcode))) AS prvalue FROM (SELECT DISTINCT (item.icatcode) AS icatcode FROM dbo.purdetail, dbo.purledger, dbo.item WHERE (((purledger.date BETWEEN v_ad_date AND v_ad_ldate) AND (purledger.purinvcode = purdetail.purinvcode)) AND (purdetail.icode = item.icode)) UNION SELECT DISTINCT (item.icatcode) AS icatcode FROM dbo.prdetail, dbo.prledger, dbo.item WHERE (((prledger.date BETWEEN v_ad_date AND v_ad_ldate) AND (prledger.prinvcode = prdetail.prinvcode)) AND (prdetail.icode = item.icode))) AS a;
  UPDATE dbo.reportdata SET value3 = (value1 - value2);
  -- COMMIT (the caller owns the transaction)
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_purchase_rate_comparison ====
CREATE OR REPLACE FUNCTION dbo.sp_purchase_rate_comparison(start_date timestamp, end_date timestamp, purchase_category citext, reportgrouping citext, grouplist citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_start_date timestamp(3);
  v_end_date timestamp(3);
  v_purchase_category citext;
  v_reportgrouping citext;
  v_grouplist citext;
  v_date timestamp(3);
  v_purcatcode integer;
  v_icode integer;
  v_purinvcode integer;
  v_qty integer;
  v_packunits integer;
  v_flag integer;
  v_inner_counter integer;
  v_icode2 integer;
  v_purinvcode2 integer;
  v_customicode citext;
  v_item citext;
  v_supplier citext;
  v_groupname citext;
  v_utn bigint;
  v_utn2 bigint;
  v_purprice numeric(15,2);
  v_purprice2 numeric(15,2);
  v_saleprice numeric(15,2);
  v_saleprice2 numeric(15,2);
  v_inv1 integer;
  v_price1 numeric(15,2);
  v_inv2 integer;
  v_price2 numeric(15,2);
  v_inv3 integer;
  v_price3 numeric(15,2);
  v_inv4 integer;
  v_price4 numeric(15,2);
  v_sprice1 numeric(15,2);
  v_sprice2 numeric(15,2);
  v_sprice3 numeric(15,2);
  v_sprice4 numeric(15,2);
  cur_abc refcursor;
  cur_xyz refcursor;
  _fs integer := -1;
BEGIN
  v_start_date := start_date;
  v_end_date := end_date;
  v_purchase_category := purchase_category;
  v_reportgrouping := reportgrouping;
  v_grouplist := grouplist;
  DELETE FROM dbo.reportdata;
  DROP TABLE IF EXISTS tv_sp_purchase_rate_comparison_tab_grouplist;
  CREATE TEMP TABLE tv_sp_purchase_rate_comparison_tab_grouplist (
    code integer NOT NULL
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tv_sp_purchase_rate_comparison_tab_itemlist;
  CREATE TEMP TABLE tv_sp_purchase_rate_comparison_tab_itemlist (
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tv_sp_purchase_rate_comparison_tab_grouplist SELECT code FROM dbo.udf_stringtotabl(v_grouplist, ',') AS udf_stringtotabl;
  INSERT INTO tv_sp_purchase_rate_comparison_tab_itemlist SELECT code FROM dbo.udf_selectitems(v_reportgrouping, v_grouplist) AS udf_selectitems;
  OPEN cur_abc FOR SELECT CASE v_reportgrouping WHEN 'M' THEN (SELECT m.name FROM dbo.manufacturer AS m WHERE (m.manfcode = i.manfcode)) WHEN 'C' THEN (SELECT c.name FROM dbo.itemcategory AS c WHERE (c.icatcode = i.icatcode)) WHEN 'L' THEN (SELECT c.name FROM dbo.itemclass AS c WHERE (c.iccode = i.iccode)) ELSE (SELECT p.name FROM dbo.itempacking AS p WHERE (p.packcode = i.packcode)) END AS groupname, p.date, p.purcatcode, p.icode, i.customicode, i.name AS item, a.name AS supplier, p.purinvcode, p.netrate, (p.qty + p.bonus) AS qty, p.packunits, 0, p.purutn AS utn, p.saleprice FROM (SELECT pl.date, pl.purcatcode, pd.icode, pl.purinvcode, max(((((((((pd.purprice * ((pd.looseqty + pd.packqty))) * ((1 - (pd.discperc * .01)))) * ((1 - (pl.discperc * .01)))) + ((pd.unitsalestax * (((pd.looseqty + pd.packqty) + pd.bonusqty))))) + round((((((pd.purprice * ((pd.looseqty + pd.packqty))) * ((1 - (pd.discperc * .01)))) * 0.01) * pd.gstperc))::numeric, 2)) + (round((((((round(((round((((pd.purprice * ((pd.looseqty + pd.packqty))) * ((1 - (pd.discperc * .01)))))::numeric, 2) * ((1 - (pl.discperc * 0.01)))))::numeric, 2) - pl.flatdisc)) * 0.01) * pl.invgstperc1))::numeric, 2)))) / (((pd.looseqty + pd.packqty) + pd.bonusqty)))) AS netrate, sum((pd.looseqty + pd.packqty)) AS qty, sum(pd.bonusqty) AS bonus, pl.suppcode, pd.packunits, max(pd.purutn) AS purutn, pd.salepriceforitem AS saleprice FROM dbo.purledger AS pl, dbo.purdetail AS pd, (SELECT code AS icode FROM tv_sp_purchase_rate_comparison_tab_itemlist AS tab_itemlist) AS tl WHERE ((((((pl.posted = 'Y') AND (pl.purcatcode >= CASE v_purchase_category WHEN 'P' THEN 1 WHEN 'L' THEN 3 END)) AND (pl.purcatcode <= CASE v_purchase_category WHEN 'P' THEN 2 WHEN 'L' THEN 8 END)) AND (pl.date BETWEEN v_start_date AND v_end_date)) AND (pl.purinvcode = pd.purinvcode)) AND (pd.icode = tl.icode)) GROUP BY pl.purinvcode, pd.icode, pl.date, pl.purcatcode, pl.suppcode, pd.purprice, pd.packunits, pd.salepriceforitem) AS p, dbo.item AS i, dbo.accounts AS a WHERE ((p.suppcode = a.acccode) AND (p.icode = i.icode)) ORDER BY p.date, p.purcatcode, p.purinvcode, i.name, utn;
  FETCH NEXT FROM cur_abc INTO v_groupname, v_date, v_purcatcode, v_icode, v_customicode, v_item, v_supplier, v_purinvcode, v_purprice, v_qty, v_packunits, v_flag, v_utn, v_saleprice;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    INSERT INTO dbo.reportdata (name5, name4, date1, code1, code2, name1, name2, name3, code3, value1, value2, value3, code4, value4, value9) VALUES (v_reportgrouping, v_groupname, v_date, v_purcatcode, v_icode, v_customicode, v_item, v_supplier, v_purinvcode, v_purprice, v_qty, v_packunits, v_flag, v_utn, v_saleprice);
    v_inv1 := NULL;
    v_price1 := NULL;
    v_inv2 := NULL;
    v_price2 := NULL;
    v_inv3 := NULL;
    v_price3 := NULL;
    v_inv4 := NULL;
    v_price4 := NULL;
    v_sprice1 := NULL;
    v_sprice2 := NULL;
    v_sprice3 := NULL;
    v_sprice4 := NULL;
    -- SET ROWCOUNT 4
    RAISE EXCEPTION 'untranslated T-SQL (SET ROWCOUNT n)' USING ERRCODE = '0A000';
    v_inner_counter := 0;
    OPEN cur_xyz FOR SELECT pd.icode, pl.purinvcode, max(((((((((pd.purprice * ((pd.looseqty + pd.packqty))) * ((1 - (pd.discperc * .01)))) * ((1 - (pl.discperc * .01)))) + ((pd.unitsalestax * (((pd.looseqty + pd.packqty) + pd.bonusqty))))) + round((((((pd.purprice * ((pd.looseqty + pd.packqty))) * ((1 - (pd.discperc * .01)))) * 0.01) * pd.gstperc))::numeric, 2)) + (round((((((round(((round((((pd.purprice * ((pd.looseqty + pd.packqty))) * ((1 - (pd.discperc * .01)))))::numeric, 2) * ((1 - (pl.discperc * 0.01)))))::numeric, 2) - pl.flatdisc)) * 0.01) * pl.invgstperc1))::numeric, 2)))) / (((pd.looseqty + pd.packqty) + pd.bonusqty)))) AS netrate, pd.salepriceforitem, max(pd.purutn) AS utn FROM dbo.purledger AS pl, dbo.purdetail AS pd WHERE (((((((pl.purinvcode <> v_purinvcode) AND (pl.posted = 'Y')) AND (pl.purcatcode >= CASE v_purchase_category WHEN 'P' THEN 1 WHEN 'L' THEN 3 END)) AND (pl.purcatcode <= CASE v_purchase_category WHEN 'P' THEN 2 WHEN 'L' THEN 8 END)) AND (pd.icode = v_icode)) AND (pd.purutn < v_utn)) AND (pl.purinvcode = pd.purinvcode)) GROUP BY pl.purinvcode, pd.icode, pd.purprice, pl.purcatcode, pd.salepriceforitem ORDER BY utn DESC;
    FETCH NEXT FROM cur_xyz INTO v_icode2, v_purinvcode2, v_purprice2, v_saleprice2, v_utn2;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    WHILE (_fs = 0) LOOP
      v_inner_counter := (v_inner_counter + 1);
      IF (v_inner_counter = 1) THEN
        v_inv1 := NULL;
        v_price1 := NULL;
        v_inv2 := NULL;
        v_price2 := NULL;
        v_inv3 := NULL;
        v_price3 := NULL;
        v_inv4 := NULL;
        v_price4 := NULL;
        v_sprice1 := NULL;
        v_sprice2 := NULL;
        v_sprice3 := NULL;
        v_sprice4 := NULL;
        v_inv1 := v_purinvcode2;
        v_price1 := v_purprice2;
        v_sprice1 := v_saleprice2;
      END IF;
      IF (v_inner_counter = 2) THEN
        v_inv2 := v_purinvcode2;
        v_price2 := v_purprice2;
        v_sprice2 := v_saleprice2;
      END IF;
      IF (v_inner_counter = 3) THEN
        v_inv3 := v_purinvcode2;
        v_price3 := v_purprice2;
        v_sprice3 := v_saleprice2;
      END IF;
      IF (v_inner_counter = 4) THEN
        v_inv4 := v_purinvcode2;
        v_price4 := v_purprice2;
        v_sprice4 := v_saleprice2;
      END IF;
      v_icode2 := NULL;
      v_purinvcode2 := NULL;
      v_purprice2 := NULL;
      v_utn2 := NULL;
      v_saleprice2 := NULL;
      FETCH NEXT FROM cur_xyz INTO v_icode2, v_purinvcode2, v_purprice2, v_saleprice2, v_utn2;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    END LOOP;
    UPDATE dbo.reportdata SET code5 = v_inv1, value5 = v_price1, code6 = v_inv2, value6 = v_price2, code7 = v_inv3, value7 = v_price3, code8 = v_inv4, value8 = v_price4, value11 = v_sprice1, value12 = v_sprice2, value13 = v_sprice3, value14 = v_sprice4 WHERE (value4 = v_utn);
    CLOSE cur_xyz;
    -- DEALLOCATE xyz
    FETCH NEXT FROM cur_abc INTO v_groupname, v_date, v_purcatcode, v_icode, v_customicode, v_item, v_supplier, v_purinvcode, v_purprice, v_qty, v_packunits, v_flag, v_utn, v_saleprice;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_abc;
  -- DEALLOCATE abc
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_PurchaseBased_SatisfyDue ====
CREATE OR REPLACE FUNCTION dbo.sp_purchasebased_satisfydue(purinvcode integer, usercode integer, serverdate timestamp, INOUT duecode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_purinvcode integer;
  v_usercode integer;
  v_serverdate timestamp(3);
  v_duecode integer;
  v_dueadjcode integer;
  v_totalrows integer;
  v_continue integer;
  v_counter integer;
  v_icode integer;
  v_oldicode integer;
  v_gcode smallint;
  v_totstock numeric(15,4);
  v_satisfiableqty numeric(15,4);
  v_rt_code integer;
  v_err_string citext;
  v_itemname citext;
  v_err integer;
  v_rowcount integer;
  _rc integer;
BEGIN
  v_purinvcode := purinvcode;
  v_usercode := usercode;
  v_serverdate := serverdate;
  v_duecode := duecode;
  v_continue := 0;
  _rc := 1;
  DROP TABLE IF EXISTS tv_sp_purchasebased_satisfydue_temp_table;
  CREATE TEMP TABLE tv_sp_purchasebased_satisfydue_temp_table (
    saleinvcode integer,
    itemname citext,
    icode integer,
    gcode smallint,
    salerowid integer,
    dueqty numeric(15,4),
    satisfiedqty numeric(15,4),
    stock numeric(15,4),
    satisfiableqty numeric(15,4),
    selected citext,
    rowid integer GENERATED BY DEFAULT AS IDENTITY
) ON COMMIT DROP;
  INSERT INTO tv_sp_purchasebased_satisfydue_temp_table (saleinvcode, itemname, icode, gcode, salerowid, dueqty, satisfiedqty, stock, satisfiableqty, selected) SELECT saleinvcode, itemname, icode, gcode, salerowid, dueqty, satisfiedqty, stock, coalesce((dueqty - satisfiedqty), 0) AS satisfiableqty, 'N' AS selected FROM (SELECT sl.saleinvcode AS saleinvcode, i.name AS itemname, sd.icode AS icode, sd.gcode AS gcode, sd.rowid AS salerowid, sd.looseqty AS dueqty, coalesce((SELECT sum(dsd.duesatisfyqty) FROM dbo.duesatisfyheader AS dsh, dbo.duesatisfydetail AS dsd WHERE ((((dsh.saleinvcode = sl.saleinvcode) AND (dsh.duesatisfycode = dsd.duesatisfycode)) AND (dsd.icode = sd.icode)) AND (dsd.salerowid = sd.rowid))), 0) AS satisfiedqty, coalesce((SELECT sum(gd.currqty) FROM dbo.godowndetail AS gd WHERE ((gd.icode = sd.icode) AND (sd.gcode = gd.gcode))), 0) AS stock FROM dbo.saleledger AS sl, dbo.saledetail AS sd, dbo.item AS i, (SELECT DISTINCT icode, gcode FROM dbo.purdetail WHERE (purinvcode = v_purinvcode)) AS p WHERE ((((((sl.saleinvcode = sd.saleinvcode) AND (sl.posted = 'Y')) AND (sd.icode = i.icode)) AND (sd.due = 'D')) AND (sd.icode = p.icode)) AND (sd.gcode = p.gcode))) AS t WHERE ((((t.dueqty - t.satisfiedqty)) > 0) AND (t.stock > 0)) ORDER BY t.itemname, t.saleinvcode;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_totalrows := coalesce((SELECT count(*) FROM tv_sp_purchasebased_satisfydue_temp_table AS temp_table), 0);
  _rc := 1;
  v_counter := 1;
  _rc := 1;
  v_oldicode := -1;
  _rc := 1;
  WHILE ((v_totalrows > 0) AND (v_counter <= v_totalrows)) LOOP
    v_icode := (SELECT icode FROM tv_sp_purchasebased_satisfydue_temp_table AS temp_table WHERE (rowid = v_counter));
    _rc := 1;
    IF (v_icode <> v_oldicode) THEN
      v_oldicode := v_icode;
      _rc := 1;
      v_totstock := coalesce((SELECT stock FROM tv_sp_purchasebased_satisfydue_temp_table AS temp_table WHERE (rowid = v_counter)), 0);
      _rc := 1;
    END IF;
    IF (v_totstock > 0) THEN
      v_satisfiableqty := (SELECT satisfiableqty FROM tv_sp_purchasebased_satisfydue_temp_table AS temp_table WHERE (rowid = v_counter));
      _rc := 1;
      UPDATE tv_sp_purchasebased_satisfydue_temp_table AS temp_table SET stock = v_totstock WHERE (rowid = v_counter);
      GET DIAGNOSTICS _rc = ROW_COUNT;
      IF (v_satisfiableqty <= v_totstock) THEN
        v_totstock := (v_totstock - v_satisfiableqty);
        _rc := 1;
      ELSE
        UPDATE tv_sp_purchasebased_satisfydue_temp_table AS temp_table SET satisfiableqty = v_totstock WHERE (rowid = v_counter);
        GET DIAGNOSTICS _rc = ROW_COUNT;
        v_totstock := 0;
        _rc := 1;
      END IF;
      UPDATE tv_sp_purchasebased_satisfydue_temp_table AS temp_table SET selected = 'Y' WHERE (rowid = v_counter);
      GET DIAGNOSTICS _rc = ROW_COUNT;
    END IF;
    v_counter := (v_counter + 1);
    _rc := 1;
  END LOOP;
  DELETE FROM tv_sp_purchasebased_satisfydue_temp_table AS temp_table WHERE (selected = 'N');
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_totalrows := coalesce((SELECT count(*) FROM tv_sp_purchasebased_satisfydue_temp_table AS temp_table), 0);
  _rc := 1;
  IF (v_totalrows > 0) THEN
    SELECT r.return_value, r.key INTO v_rt_code, v_dueadjcode FROM dbo.sp_gettabmaxkey(tabname => 'DueAdjHeader', key => v_dueadjcode) AS r;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      v_continue := -1;
      _rc := 1;
      RAISE EXCEPTION 'Unable to Generate New Due Adjustment code';
    ELSE
      INSERT INTO dbo.dueadjheader (dueadjcode, date, startdate, enddate, remarks, usercode) VALUES (v_dueadjcode, v_serverdate, ('01-01-1990 00:00:00')::timestamp(3), localtimestamp(3), ('Auto Due Satisfied on Purchase Inv. # ' || rtrim(ltrim(dbo.tsql_str((v_purinvcode)::numeric, 10)))), v_usercode);
      GET DIAGNOSTICS _rc = ROW_COUNT;
      INSERT INTO dbo.dueadjdetail (dueadjcode, saleinvcode, icode, gcode, salerowid, dueqty, satisfiedqty, satisfiableqty, duedelete) SELECT v_dueadjcode, saleinvcode, icode, gcode, salerowid, dueqty, satisfiedqty, satisfiableqty, 'N' AS duedelete FROM tv_sp_purchasebased_satisfydue_temp_table AS temp_table;
      GET DIAGNOSTICS _rc = ROW_COUNT;
      v_err := 0;
      v_rowcount := _rc;
      _rc := 1;
      IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
        RAISE EXCEPTION 'Error occured in inserting record into Due Adjustment Detail';
        v_continue := -1;
        _rc := 1;
      END IF;
      IF (v_continue >= 0) THEN
        SELECT r.return_value INTO v_rt_code FROM dbo.sp_satisfydueinbulk(dueadjcode => v_dueadjcode, usercode => v_usercode, serverdate => v_serverdate) AS r;
        IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
          v_continue := -1;
          _rc := 1;
          RAISE EXCEPTION 'Unable to Generate New Due Adjustment code';
        END IF;
      END IF;
    END IF;
  END IF;
  v_duecode := v_dueadjcode;
  _rc := 1;
  return_value := v_continue;
  duecode := v_duecode;
  RETURN;
  return_value := 0;
  duecode := v_duecode;
  RETURN;
END
$body$;

-- ==== proc sp_PurInvList_From_DataCarryDB ====
CREATE OR REPLACE FUNCTION dbo.sp_purinvlist_from_datacarrydb(srv citext, db citext, owner citext, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_query citext;
  _dq1 text;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  v_query := ((((((('Select Purinvcode, Date, InvTotal, Remarks From 	' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.') || 'PurLedger');
  _dq1 := v_query;
  IF _dq1 IS NOT NULL THEN
    IF _dq1 ~* '^[[:space:]]*select' THEN OPEN rs1 FOR EXECUTE dbo.tsql_dyn(_dq1); ELSE EXECUTE dbo.tsql_dyn(_dq1); END IF;
  END IF;
  return_value := 1;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

