-- ==== proc SP_ReGenerateServiceResult ====
CREATE OR REPLACE FUNCTION dbo.sp_regenerateserviceresult(serviceinvcode integer, usercode smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_serviceinvcode integer;
  v_usercode smallint;
  v_tot_services integer;
  v_serviceresultcode integer;
  v_servicecode integer;
  v_patientcode integer;
  v_gestationcode smallint;
  v_posted citext;
  v_expiry timestamp(3);
  v_price numeric(12,2);
  v_start_ticket integer;
  v_end_ticket integer;
  v_errcode integer;
  v_rowid integer;
  v_in_rowid integer;
  v_in_qty integer;
  v_ticketcode integer;
  _r1 record;
  _rc integer;
BEGIN
  v_serviceinvcode := serviceinvcode;
  v_usercode := usercode;
  -- SET NOCOUNT ON
  v_serviceresultcode := (SELECT max(serviceresultcode) FROM dbo.serviceresultheader WHERE (serviceinvcode = v_serviceinvcode));
  _rc := 1;
  DROP TABLE IF EXISTS tv_sp_regenerateserviceresult_service_table;
  CREATE TEMP TABLE tv_sp_regenerateserviceresult_service_table (
    servicecode integer,
    qty integer,
    expiry timestamp(3),
    price numeric(12,2),
    rowid integer GENERATED BY DEFAULT AS IDENTITY
) ON COMMIT DROP;
  IF (v_serviceinvcode IS NULL) THEN
    return_value := 0;
    RETURN;
  END IF;
  IF (v_usercode IS NULL) THEN
    v_usercode := 1;
    _rc := 1;
  END IF;
  v_posted := coalesce((SELECT posted FROM dbo.serviceheader WHERE (serviceinvcode = v_serviceinvcode)), 'N');
  _rc := 1;
  IF ((v_posted = 'N') OR (v_posted IS NULL)) THEN
    return_value := 0;
    RETURN;
  END IF;
  v_tot_services := (SELECT (SELECT count(sd.servicecode) FROM dbo.servicedetail AS sd, dbo.service AS sv WHERE (((sd.serviceinvcode = v_serviceinvcode) AND (sd.servicecode = sv.servicecode)) AND (sv.resultrequired = 'Y'))) AS servicecount FROM dbo.serviceheader WHERE ((serviceinvcode = v_serviceinvcode) AND (posted = 'Y')));
  _rc := 1;
  IF ((v_tot_services <= 0) OR (v_tot_services IS NULL)) THEN
    return_value := 0;
    RETURN;
  END IF;
  _rc := 0;
  FOR _r1 IN SELECT p.patientcode AS c1, p.gestationcode AS c2 FROM dbo.patient AS p WHERE (p.patientcode IN (SELECT sh.patientcode AS patientcode FROM dbo.serviceheader AS sh WHERE (sh.serviceinvcode = v_serviceinvcode) UNION ALL SELECT pa.patientcode FROM dbo.patientadmission AS pa, dbo.serviceheader AS sh WHERE ((sh.serviceinvcode = v_serviceinvcode) AND (sh.admissioncode = pa.admissioncode)))) LOOP
    _rc := _rc + 1;
    v_patientcode := _r1.c1;
    v_gestationcode := _r1.c2;
  END LOOP;
  DELETE FROM dbo.serviceresultdetail WHERE (serviceresultcode = v_serviceresultcode);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  INSERT INTO dbo.serviceresultdetail (serviceresultcode, servicerowid, rowid, servicehead, servicecomponentcode, servicecomponentunitcode, testmachinecode, costprice, saleprice, componentvalue, lowerreferencevalue, upperreferencevalue, comments, remarks, componentvalue2, deliverydate, printonreport) SELECT v_serviceresultcode AS serviceresultcode, d.srvrowid AS srvrowid, sb.rowid AS rowid, sb.servicehead AS servicehead, sb.servicecomponentcode AS servicecomponentcode, (SELECT s.servicecomponentunitcode FROM dbo.servicecomponent AS s WHERE (s.servicecomponentcode = sb.servicecomponentcode)) AS servicecomponentunitcode, 1 AS testmachinecode, sb.costprice AS costprice, sb.saleprice AS saleprice, CASE WHEN (s.serviceresulttemplate IS NULL) THEN NULL ELSE (SELECT max(srd.componentvalue) FROM dbo.serviceresultdetail AS srd WHERE ((srd.serviceresultcode = s.serviceresulttemplate) AND (srd.servicecomponentcode = sb.servicecomponentcode))) END AS componentvalue, CASE WHEN (s.serviceresulttemplate IS NULL) THEN NULL ELSE (SELECT max(srd.lowerreferencevalue) FROM dbo.serviceresultdetail AS srd WHERE ((srd.serviceresultcode = s.serviceresulttemplate) AND (srd.servicecomponentcode = sb.servicecomponentcode))) END AS lowerreferencevalue, CASE WHEN (s.serviceresulttemplate IS NULL) THEN NULL ELSE (SELECT max(srd.upperreferencevalue) FROM dbo.serviceresultdetail AS srd WHERE ((srd.serviceresultcode = s.serviceresulttemplate) AND (srd.servicecomponentcode = sb.servicecomponentcode))) END AS upperreferencevalue, CASE WHEN (s.serviceresulttemplate IS NULL) THEN NULL ELSE (SELECT max(srd.comments) FROM dbo.serviceresultdetail AS srd WHERE ((srd.serviceresultcode = s.serviceresulttemplate) AND (srd.servicecomponentcode = sb.servicecomponentcode))) END AS comments, CASE WHEN (s.serviceresulttemplate IS NULL) THEN NULL ELSE (SELECT max(srd.remarks) FROM dbo.serviceresultdetail AS srd WHERE ((srd.serviceresultcode = s.serviceresulttemplate) AND (srd.servicecomponentcode = sb.servicecomponentcode))) END AS remarks, CASE WHEN (s.serviceresulttemplate IS NULL) THEN NULL ELSE (SELECT max(srd.componentvalue2) FROM dbo.serviceresultdetail AS srd WHERE ((srd.serviceresultcode = s.serviceresulttemplate) AND (srd.servicecomponentcode = sb.servicecomponentcode))) END AS componentvalue2, d.deliverydate AS deliverydate, sb.printonreport AS printonreport FROM dbo.serviceheader AS h, dbo.servicedetail AS d, dbo.service AS s, dbo.servicebreakup AS sb WHERE (((((h.serviceinvcode = v_serviceinvcode) AND (h.serviceinvcode = d.serviceinvcode)) AND (d.servicecode = s.servicecode)) AND (s.resultrequired = 'Y')) AND (s.servicecode = sb.servicecode)) ORDER BY d.srvrowid, sb.servicehead, rowid;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((0 <> 0) OR (_rc <= 0)) THEN
    RAISE EXCEPTION 'Problem while Inserting Service Result Detail Rows';
    return_value := -1;
    RETURN;
  END IF;
  UPDATE dbo.serviceresultheader SET posted = 'N' WHERE (serviceresultcode = v_serviceresultcode);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_REGIONAREASALES ====
CREATE OR REPLACE FUNCTION dbo.sp_regionareasales(ar_regcode integer, ar_startdate timestamp, ar_enddate timestamp, reportgrouping citext, grouplist citext, pricetype integer, includebonus integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ar_regcode integer;
  v_ar_startdate timestamp(3);
  v_ar_enddate timestamp(3);
  v_reportgrouping citext;
  v_grouplist citext;
  v_pricetype integer;
  v_includebonus integer;
BEGIN
  v_ar_regcode := ar_regcode;
  v_ar_startdate := ar_startdate;
  v_ar_enddate := ar_enddate;
  v_reportgrouping := reportgrouping;
  v_grouplist := grouplist;
  v_pricetype := pricetype;
  v_includebonus := includebonus;
  DELETE FROM dbo.reportdata;
  DROP TABLE IF EXISTS tv_sp_regionareasales_tab_grouplist;
  CREATE TEMP TABLE tv_sp_regionareasales_tab_grouplist (
    code integer NOT NULL
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tv_sp_regionareasales_tab_itemlist;
  CREATE TEMP TABLE tv_sp_regionareasales_tab_itemlist (
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tv_sp_regionareasales_tab_grouplist SELECT code FROM dbo.udf_stringtotabl(v_grouplist, ',') AS udf_stringtotabl;
  INSERT INTO tv_sp_regionareasales_tab_itemlist SELECT code FROM dbo.udf_selectitems(v_reportgrouping, v_grouplist) AS udf_selectitems;
  DELETE FROM dbo.reportdata;
  INSERT INTO dbo.reportdata (code1, code2, code3, code4, name1, name2, name3, name4, name5, name6, name7, name8, value1, value2) SELECT s.icode AS code1, s.areacode AS code2, s.regioncode AS code3, CASE v_reportgrouping WHEN 'M' THEN i.manfcode WHEN 'C' THEN i.icatcode WHEN 'L' THEN i.iccode ELSE i.packcode END AS code4, i.name AS name1, (SELECT area.shortname FROM dbo.area WHERE (areacode = s.areacode)) AS name2, (SELECT name FROM dbo.region WHERE (regioncode = s.regioncode)) AS name3, CASE v_reportgrouping WHEN 'M' THEN (SELECT m.name FROM dbo.manufacturer AS m WHERE (m.manfcode = i.manfcode)) WHEN 'C' THEN (SELECT c.name FROM dbo.itemcategory AS c WHERE (c.icatcode = i.icatcode)) WHEN 'L' THEN (SELECT c.name FROM dbo.itemclass AS c WHERE (c.iccode = i.iccode)) ELSE (SELECT p.name FROM dbo.itempacking AS p WHERE (p.packcode = i.packcode)) END AS name4, i.customicode AS name5, i.packingdesc AS name6, (SELECT area.shortname FROM dbo.area WHERE (areacode = s.areacode)) AS name7, rtrim(ltrim(dbo.tsql_str((s.icode)::numeric))) AS name8, sum(qty) AS value1, round((sum(CASE v_pricetype WHEN 1 THEN netamt WHEN 2 THEN (qty * round(((i.saleprice / CASE i.packunits WHEN 0 THEN 1 ELSE i.packunits END))::numeric, 2)) WHEN 3 THEN (qty * round(((i.purprice / CASE i.packunits WHEN 0 THEN 1 ELSE i.packunits END))::numeric, 2)) WHEN 4 THEN (qty * i.avgprice) END))::numeric, 0) AS value2 FROM (SELECT -1 AS invno, i.icode AS icode, -1 AS custcode, 0 AS qty, 0 AS netamt, a.areacode, r.regioncode FROM dbo.area AS a, dbo.region AS r, (SELECT min(code) AS icode FROM tv_sp_regionareasales_tab_itemlist AS tab_itemlist) AS i WHERE ((r.regioncode = v_ar_regcode) AND (r.regioncode = a.regioncode)) UNION ALL SELECT -1 AS invno, i.icode AS icode, -1 AS custcode, 0 AS qty, 0 AS netamt, a.areacode, a.regioncode FROM (SELECT min(areacode) AS areacode, regioncode FROM dbo.area WHERE (regioncode = v_ar_regcode) GROUP BY regioncode) AS a, (SELECT code AS icode FROM tv_sp_regionareasales_tab_itemlist AS tab_itemlist) AS i UNION ALL SELECT sl.saleinvcode AS invno, sd.icode, sl.custcode AS custcode, coalesce(sum((sd.looseqty + CASE WHEN (v_includebonus = 1) THEN sd.bonusqty ELSE 0 END)), 0) AS qty, round((coalesce((sum((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc)))) * ((1 - ((.01 * sd.discperc)))))) * ((1 - ((.01 * sl.discperc))))), 0))::numeric, 2) AS netamt, c.areacode, r.regioncode FROM dbo.saleledger AS sl, dbo.saledetail AS sd, dbo.customer AS c, dbo.area AS a, dbo.region AS r, tv_sp_regionareasales_tab_itemlist AS i WHERE (((((((((r.regioncode = v_ar_regcode) AND (r.regioncode = a.regioncode)) AND (a.areacode = c.areacode)) AND (c.custcode = sl.custcode)) AND (sl.posted = 'Y')) AND (sl.saleinvcode = sd.saleinvcode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) AND (sd.icode = i.code)) GROUP BY sl.saleinvcode, sd.icode, sl.custcode, r.regioncode, c.areacode, sl.discperc UNION ALL SELECT sl.srinvcode AS invno, sd.icode, sl.custcode AS custcode, (-coalesce(sum((sd.looseqty + CASE WHEN (v_includebonus = 1) THEN sd.bonusqty ELSE 0 END)), 0)) AS qty, (-round((coalesce((sum((((sd.looseqty * sd.srprice)) * ((1 - ((.01 * sd.discperc)))))) * ((1 - ((.01 * sl.discperc))))), 0))::numeric, 2)) AS netamt, c.areacode, r.regioncode FROM dbo.srledger AS sl, dbo.srdetail AS sd, dbo.customer AS c, dbo.area AS a, dbo.region AS r, tv_sp_regionareasales_tab_itemlist AS i WHERE (((((((((r.regioncode = v_ar_regcode) AND (r.regioncode = a.regioncode)) AND (a.areacode = c.areacode)) AND (c.custcode = sl.custcode)) AND (sl.posted = 'Y')) AND (sl.srinvcode = sd.srinvcode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) AND (sd.icode = i.code)) GROUP BY sl.srinvcode, sd.icode, sl.custcode, r.regioncode, c.areacode, sl.discperc) AS s, dbo.item AS i, dbo.itemcategory AS ic WHERE (((s.icode = i.icode) AND (i.icatcode = ic.icatcode)) AND (i.icode IN (SELECT code FROM tv_sp_regionareasales_tab_itemlist AS tab_itemlist))) GROUP BY s.icode, s.regioncode, s.areacode, i.name, i.customicode, i.packingdesc, i.icatcode, i.iccode, i.manfcode, i.packcode;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_REGIONWISESALES ====
CREATE OR REPLACE FUNCTION dbo.sp_regionwisesales(ar_startdate timestamp, ar_enddate timestamp, reportgrouping citext, grouplist citext, regionlist citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ar_startdate timestamp(3);
  v_ar_enddate timestamp(3);
  v_reportgrouping citext;
  v_grouplist citext;
  v_regionlist citext;
BEGIN
  v_ar_startdate := ar_startdate;
  v_ar_enddate := ar_enddate;
  v_reportgrouping := reportgrouping;
  v_grouplist := grouplist;
  v_regionlist := regionlist;
  DELETE FROM dbo.reportdata;
  DROP TABLE IF EXISTS tv_sp_regionwisesales_tab_grouplist;
  CREATE TEMP TABLE tv_sp_regionwisesales_tab_grouplist (
    code integer NOT NULL
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tv_sp_regionwisesales_tab_itemlist;
  CREATE TEMP TABLE tv_sp_regionwisesales_tab_itemlist (
    code integer NOT NULL
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tv_sp_regionwisesales_tab_regionlist;
  CREATE TEMP TABLE tv_sp_regionwisesales_tab_regionlist (
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tv_sp_regionwisesales_tab_grouplist SELECT code FROM dbo.udf_stringtotabl(v_grouplist, ',') AS udf_stringtotabl;
  INSERT INTO tv_sp_regionwisesales_tab_regionlist SELECT code FROM dbo.udf_stringtotabl(v_regionlist, ',') AS udf_stringtotabl;
  INSERT INTO tv_sp_regionwisesales_tab_itemlist SELECT code FROM dbo.udf_selectitems(v_reportgrouping, v_grouplist) AS udf_selectitems;
  INSERT INTO dbo.reportdata (code1, code2, code3, name1, name2, name3, name4, name5, name6, value1, value2) SELECT s.icode AS code1, s.regioncode AS code2, CASE v_reportgrouping WHEN 'M' THEN i.manfcode WHEN 'C' THEN i.icatcode WHEN 'L' THEN i.iccode ELSE i.packcode END AS code3, i.name AS name1, (SELECT name FROM dbo.region WHERE (regioncode = s.regioncode)) AS name2, CASE v_reportgrouping WHEN 'M' THEN (SELECT m.name FROM dbo.manufacturer AS m WHERE (m.manfcode = i.manfcode)) WHEN 'C' THEN (SELECT c.name FROM dbo.itemcategory AS c WHERE (c.icatcode = i.icatcode)) WHEN 'L' THEN (SELECT c.name FROM dbo.itemclass AS c WHERE (c.iccode = i.iccode)) ELSE (SELECT p.name FROM dbo.itempacking AS p WHERE (p.packcode = i.packcode)) END AS name3, i.customicode AS name4, i.packingdesc AS name5, rtrim(ltrim(dbo.tsql_str((s.icode)::numeric))) AS name6, sum(qty) AS value1, round((sum(netamt))::numeric, 0) AS value2 FROM (SELECT -1 AS invno, i.icode AS icode, -1 AS custcode, 0 AS qty, 0 AS netamt, r.regioncode FROM (SELECT code AS regioncode FROM tv_sp_regionwisesales_tab_regionlist AS tab_regionlist) AS r, (SELECT min(code) AS icode FROM tv_sp_regionwisesales_tab_itemlist AS tab_itemlist) AS i UNION ALL SELECT -1 AS invno, i.icode AS icode, -1 AS custcode, 0 AS qty, 0 AS netamt, r.regioncode FROM (SELECT min(code) AS regioncode FROM tv_sp_regionwisesales_tab_regionlist AS tab_regionlist) AS r, (SELECT code AS icode FROM tv_sp_regionwisesales_tab_itemlist AS tab_itemlist) AS i UNION ALL SELECT sl.saleinvcode AS invno, sd.icode, sl.custcode AS custcode, coalesce(sum((sd.looseqty + sd.bonusqty)), 0) AS qty, round((coalesce((sum((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc)))) * ((1 - ((.01 * sd.discperc)))))) * ((1 - ((.01 * sl.discperc))))), 0))::numeric, 2) AS netamt, r.regioncode FROM dbo.saleledger AS sl, dbo.saledetail AS sd, dbo.customer AS c, dbo.area AS a, (SELECT code AS regioncode FROM tv_sp_regionwisesales_tab_regionlist AS tab_regionlist) AS r, tv_sp_regionwisesales_tab_itemlist AS i WHERE ((((((((r.regioncode = a.regioncode) AND (a.areacode = c.areacode)) AND (c.custcode = sl.custcode)) AND (sl.posted = 'Y')) AND (sl.saleinvcode = sd.saleinvcode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) AND (sd.icode = i.code)) GROUP BY sl.saleinvcode, sd.icode, sl.custcode, r.regioncode, sl.discperc UNION ALL SELECT sl.srinvcode AS invno, sd.icode, sl.custcode AS custcode, (-coalesce(sum((sd.looseqty + sd.bonusqty)), 0)) AS qty, (-round((coalesce((sum((((sd.looseqty * sd.srprice)) * ((1 - ((.01 * sd.discperc)))))) * ((1 - ((.01 * sl.discperc))))), 0))::numeric, 2)) AS netamt, r.regioncode FROM dbo.srledger AS sl, dbo.srdetail AS sd, dbo.customer AS c, dbo.area AS a, (SELECT code AS regioncode FROM tv_sp_regionwisesales_tab_regionlist AS tab_regionlist) AS r, tv_sp_regionwisesales_tab_itemlist AS i WHERE ((((((((r.regioncode = a.regioncode) AND (a.areacode = c.areacode)) AND (c.custcode = sl.custcode)) AND (sl.posted = 'Y')) AND (sl.srinvcode = sd.srinvcode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) AND (sd.icode = i.code)) GROUP BY sl.srinvcode, sd.icode, sl.custcode, r.regioncode, sl.discperc) AS s, dbo.item AS i, dbo.itemcategory AS ic WHERE (((s.icode = i.icode) AND (i.icatcode = ic.icatcode)) AND (i.icode IN (SELECT code FROM tv_sp_regionwisesales_tab_itemlist AS tab_itemlist))) GROUP BY s.icode, s.regioncode, i.name, i.customicode, i.packingdesc, i.icatcode, i.iccode, i.manfcode, i.packcode;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_RejectInstallment ====
CREATE OR REPLACE FUNCTION dbo.sp_rejectinstallment(startcode integer, endcode integer, usercode smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_startcode integer;
  v_endcode integer;
  v_usercode smallint;
  v_totalrows integer;
  _rc integer;
BEGIN
  v_startcode := startcode;
  v_endcode := endcode;
  v_usercode := usercode;
  UPDATE dbo.installmentheader SET rejected = 'Y', rejectedby = v_usercode, rejectedon = localtimestamp(3) WHERE (((installmentcode BETWEEN v_startcode AND v_endcode) AND (posted = 'N')) AND (approved = 'N'));
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_totalrows := _rc;
  _rc := 1;
  IF (v_totalrows = 0) THEN
    RAISE EXCEPTION 'No Installment Estimate available for Rejection';
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_Repair_NetRate_RPP ====
CREATE OR REPLACE FUNCTION dbo.sp_repair_netrate_rpp(upd_netrate_in_pur smallint, upd_rpp_in_pur smallint, upd_rpp_in_item smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_upd_netrate_in_pur smallint;
  v_upd_rpp_in_pur smallint;
  v_upd_rpp_in_item smallint;
BEGIN
  v_upd_netrate_in_pur := upd_netrate_in_pur;
  v_upd_rpp_in_pur := upd_rpp_in_pur;
  v_upd_rpp_in_item := upd_rpp_in_item;
  IF (v_upd_netrate_in_pur = 1) THEN
    UPDATE dbo.purdetail AS purdetail SET netrate = t.netrate FROM (SELECT pd.purinvcode, pd.icode, pd.purrowid, round((((((pd.itemvalue + ((((pd.itemvalue / pur.grossvalue)) * pur.invlevelcharges)))) / pd.totqty)))::numeric, 5) AS netrate FROM (SELECT p.purinvcode, d.icode, d.purrowid, (((d.packqty + d.looseqty) + d.bonusqty)) AS totqty, round(((((((((d.looseqty + d.packqty)) * d.purprice) * ((1 - (d.discperc * .01))))) + round(((d.unitsalestax * (((d.packqty + d.looseqty) + d.bonusqty))))::numeric, 2)) + round((((((((d.looseqty + d.packqty)) * d.purprice) * ((1 - (d.discperc * .01)))) * d.gstperc) * 0.01))::numeric, 2)))::numeric, 2) AS itemvalue FROM dbo.purledger AS p, dbo.purdetail AS d WHERE (p.purinvcode = d.purinvcode)) AS pd, (SELECT pu.purinvcode, (((pu.misccharges + pu.invgstvalue) - pu.flatdisc) - pu.discpercvalue) AS invlevelcharges, pu.grossvalue FROM (SELECT p.purinvcode, sum(round(((((((((d.looseqty + d.packqty)) * d.purprice) * ((1 - (d.discperc * .01))))) + round(((d.unitsalestax * (((d.packqty + d.looseqty) + d.bonusqty))))::numeric, 2)) + round((((((((d.looseqty + d.packqty)) * d.purprice) * ((1 - (d.discperc * .01)))) * d.gstperc) * 0.01))::numeric, 2)))::numeric, 2)) AS grossvalue, sum((((((((d.looseqty + d.packqty)) * d.purprice) * ((1 - (d.discperc * .01))))) * p.discperc) * .01)) AS discpercvalue, round(((((((round(((sum(((((d.looseqty + d.packqty)) * d.purprice) * ((1 - (d.discperc * .01))))) * ((1 - (p.discperc * 0.01)))))::numeric, 2)) - p.flatdisc)) * p.invgstperc1) * 0.01))::numeric, 2) AS invgstvalue, p.misccharges, p.flatdisc FROM dbo.purledger AS p, dbo.purdetail AS d WHERE (p.purinvcode = d.purinvcode) GROUP BY p.purinvcode, p.discperc, p.flatdisc, p.misccharges, p.flatdisc, p.invgstperc1) AS pu) AS pur WHERE (pd.purinvcode = pur.purinvcode)) AS t WHERE ((t.purinvcode = purdetail.purinvcode) AND (purdetail.purrowid = t.purrowid));
  END IF;
  IF (v_upd_rpp_in_pur = 1) THEN
    UPDATE dbo.purdetail SET recentpurprice = coalesce(CASE WHEN (prev.previd IS NULL) THEN 0 ELSE (SELECT round((pd.netrate)::numeric, 2) FROM dbo.purdetail AS pd WHERE (pd.purrowid = prev.previd)) END, 0) FROM dbo.purdetail AS pdd LEFT JOIN (SELECT d.icode, d.purrowid, (SELECT max(dd.purrowid) AS pid FROM dbo.purledger AS p, dbo.purdetail AS dd WHERE ((((dd.icode = d.icode) AND (dd.purrowid < d.purrowid)) AND (p.purinvcode = dd.purinvcode)) AND (p.purcatcode IN (1, 2))) GROUP BY dd.icode) AS previd FROM dbo.purdetail AS d) AS prev ON ((pdd.purrowid = prev.purrowid));
  END IF;
  IF (v_upd_rpp_in_item = 1) THEN
    UPDATE dbo.item AS i SET recentpurprice = coalesce(round((rpp.netrate)::numeric, 2), recentpurprice) FROM (SELECT dd.icode, dd.netrate FROM dbo.purdetail AS dd, (SELECT d.icode, max(d.purrowid) AS pid FROM dbo.purledger AS p, dbo.purdetail AS d WHERE ((p.purinvcode = d.purinvcode) AND (p.purcatcode IN (1, 2))) GROUP BY d.icode) AS p WHERE (dd.purrowid = p.pid)) AS rpp WHERE (i.icode = rpp.icode);
  END IF;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_RepairBatchWiseCorruptedStock ====
CREATE OR REPLACE FUNCTION dbo.sp_repairbatchwisecorruptedstock(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_gcode integer;
  v_rowid integer;
  v_totrows integer;
BEGIN
  DROP TABLE IF EXISTS tv_sp_repairbatchwisecorruptedstock_godown;
  CREATE TEMP TABLE tv_sp_repairbatchwisecorruptedstock_godown (
    code integer,
    id integer GENERATED BY DEFAULT AS IDENTITY
) ON COMMIT DROP;
  INSERT INTO tv_sp_repairbatchwisecorruptedstock_godown (code) SELECT gcode FROM dbo.godown;
  DELETE FROM dbo.reportdata;
  v_totrows := coalesce((SELECT count(gcode) FROM dbo.godown), 0);
  v_rowid := 1;
  WHILE (v_rowid <= v_totrows) LOOP
    v_gcode := (SELECT code FROM tv_sp_repairbatchwisecorruptedstock_godown AS godown WHERE (id = v_rowid));
    DELETE FROM dbo.reportdata;
    INSERT INTO dbo.reportdata (code1, value1) SELECT t.icode, sum(CASE WHEN (t.type <> 'ST') THEN t.net ELSE 0 END) AS net FROM (SELECT icode, sum(((packqty * packunits) + (bonusqty * packunits))) AS net, 'PU' AS type FROM dbo.purdetail, dbo.purledger WHERE ((((purledger.purcatcode IN (1, 2)) AND (purledger.purinvcode = purdetail.purinvcode)) AND (posted = (upper('Y'))::citext)) AND (gcode = v_gcode)) GROUP BY icode UNION ALL SELECT icode, sum((looseqty + bonusqty)) AS net, 'PU' AS type FROM dbo.purdetail, dbo.purledger WHERE ((((purledger.purcatcode IN (3, 7, 8)) AND (purledger.purinvcode = purdetail.purinvcode)) AND (posted = (upper('Y'))::citext)) AND (gcode = v_gcode)) GROUP BY icode UNION ALL SELECT icode, (-sum((looseqty + bonusqty))) AS net, 'PR' AS type FROM dbo.prdetail WHERE (gcode = v_gcode) GROUP BY icode UNION ALL SELECT icode, (-sum((looseqty + bonusqty))) AS net, 'SL' AS type FROM dbo.saledetail WHERE ((due IS NULL) AND (gcode = v_gcode)) GROUP BY icode UNION ALL SELECT icode, sum((looseqty + bonusqty)) AS net, 'SR' AS type FROM dbo.srdetail WHERE (gcode = v_gcode) GROUP BY icode UNION ALL SELECT icode, (-sum(qty)) AS net, 'IS' AS type FROM dbo.issuedetail, dbo.issueheader WHERE ((issueheader.issueinvcode = issuedetail.issueinvcode) AND (gcode = v_gcode)) GROUP BY icode UNION ALL SELECT icode, (-sum(duesatisfyqty)) AS net, 'DS' AS type FROM dbo.duesatisfydetail WHERE (gcode = v_gcode) GROUP BY icode UNION ALL SELECT icode, sum(qty) AS net, 'DS' AS type FROM dbo.receiptheader, dbo.receiptdetail WHERE (((receiptheader.posted = 'Y') AND (receiptheader.receiptinvcode = receiptdetail.receiptinvcode)) AND (gcode = v_gcode)) GROUP BY icode UNION ALL SELECT icode, sum(looseqty) AS net, 'AI' AS type FROM dbo.adjheader, dbo.adjdetail WHERE ((((adjheader.posted = 'Y') AND (adjheader.adjcatcode = 1)) AND (adjheader.adjcode = adjdetail.adjcode)) AND (adjdetail.gcode = v_gcode)) GROUP BY icode UNION ALL SELECT icode, (-sum(looseqty)) AS net, 'AD' AS type FROM dbo.adjheader, dbo.adjdetail WHERE ((((adjheader.posted = 'Y') AND (adjheader.adjcatcode = 2)) AND (adjheader.adjcode = adjdetail.adjcode)) AND (adjdetail.gcode = v_gcode)) GROUP BY icode UNION ALL SELECT icode, (-sum(qty)) AS net, 'TM' AS type FROM dbo.theader, dbo.tdetail WHERE (((theader.posted = 'Y') AND (theader.sgcode = v_gcode)) AND (theader.transcode = tdetail.transcode)) GROUP BY icode UNION ALL SELECT icode, sum(qty) AS net, 'TN' AS type FROM dbo.theader, dbo.tdetail WHERE (((theader.posted = 'Y') AND (theader.dgcode = v_gcode)) AND (theader.transcode = tdetail.transcode)) GROUP BY icode UNION ALL SELECT icode, sum(currqty) AS net, 'ST' AS type FROM dbo.godowndetail WHERE (gcode = v_gcode) GROUP BY icode) AS t, dbo.item WHERE (t.icode = item.icode) GROUP BY t.icode, item.name HAVING (sum(CASE WHEN (t.type = 'ST') THEN t.net ELSE 0 END) <> sum(CASE WHEN (t.type <> 'ST') THEN t.net ELSE 0 END)) ORDER BY t.icode;
    UPDATE dbo.reportdata SET date1 = coalesce((SELECT min(d.expiry) FROM dbo.godowndetail AS d WHERE ((reportdata.code1 = d.icode) AND (d.gcode = v_gcode))), coalesce((SELECT min(expiry) FROM dbo.purdetail WHERE (purutn IN (SELECT max(purutn) FROM dbo.purdetail AS p WHERE (p.icode = reportdata.code1)))), '12/12/2010 00:00:00'));
    DELETE FROM dbo.godowndetail WHERE ((icode IN (SELECT code1 FROM dbo.reportdata)) AND (gcode = v_gcode));
    UPDATE dbo.reportdata SET code2 = v_gcode;
    INSERT INTO dbo.godowndetail (gcode, icode, currqty, batch, expiry, priority, manfdate) SELECT trunc(code2)::smallint, trunc(code1)::integer, value1, coalesce((SELECT batch FROM dbo.purdetail WHERE (purutn IN (SELECT max(purutn) FROM dbo.purdetail AS p WHERE (p.icode = reportdata.code1)))), '.'), date1, 10, NULL::timestamp(3) FROM dbo.reportdata WHERE (value1 > 0);
    v_rowid := (v_rowid + 1);
  END LOOP;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_RepairDB ====
CREATE OR REPLACE FUNCTION dbo.sp_repairdb(db citext, option integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_db citext;
  v_option integer;
  v_qry citext;
BEGIN
  v_db := db;
  v_option := option;
  -- SET NOCOUNT ON
  IF (v_db IS NULL) THEN
    return_value := 0;
    RETURN;
  END IF;
  IF (v_option IS NULL) THEN
    return_value := 0;
    RETURN;
  END IF;
  v_qry := (('dbcc CheckDB(''' || v_db) || '''');
  IF (v_option = 0) THEN
    v_qry := (v_qry || '');
  END IF;
  IF (v_option = 1) THEN
    v_qry := (v_qry || ', REPAIR_FAST');
  END IF;
  IF (v_option = 2) THEN
    v_qry := (v_qry || ', REPAIR_REBUILD');
  END IF;
  IF (v_option = 3) THEN
    v_qry := (v_qry || ', REPAIR_ALLOW_DATA_LOSS');
  END IF;
  v_qry := (v_qry || ') with tableresults, ALL_ERRORMSGS');
  TRUNCATE TABLE dbo.dbcc_history RESTART IDENTITY;
  EXECUTE coalesce('INSERT INTO dbo.dbcc_history (errorid, levelid, stateid, messagetext, repairlevel, statusid, dbid, objectid, indid, fileid, pageid, slotid, reffileid, refpageid, refslotid, allocationid) ' || v_qry, 'SELECT 1');
  IF (0 <> 0) THEN
    return_value := 0;
    RETURN;
  END IF;
  INSERT INTO dbo.dbrepairlog (date, repairlevel, objectname) SELECT localtimestamp(3) AS date, CASE v_option WHEN 1 THEN 'REPAIR_FAST' WHEN 2 THEN 'REPAIR_REBUILD' WHEN 3 THEN 'REPAIR_ALLOW_DATA_LOSS' ELSE '' END AS repairlevel, v_db AS objectname;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_RePrioritizeStockBatches ====
CREATE OR REPLACE FUNCTION dbo.sp_reprioritizestockbatches(method integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_method integer;
  v_batch citext;
  v_itemname citext;
  v_icode integer;
  v_oldicode integer;
  v_errcode integer;
  v_priority integer;
  v_expiry timestamp(3);
  v_indate timestamp(3);
  cur_cursor1 refcursor;
  cur_cursor2 refcursor;
  _fs integer := -1;
BEGIN
  v_method := method;
  IF (v_method = 1) THEN
    UPDATE dbo.godowndetail SET priority = 10;
  END IF;
  IF (v_method = 2) THEN
    UPDATE dbo.godowndetail SET priority = 9;
    v_oldicode := NULL;
    v_priority := 0;
    OPEN cur_cursor1 FOR SELECT t.icode, t.batch, t.expiry, min(t.indate) AS indate FROM (SELECT gd.icode, gd.batch, gd.expiry, min(h.postdate) AS indate FROM dbo.purdetail AS d, dbo.purledger AS h, dbo.godowndetail AS gd WHERE (((((h.posted = 'Y') AND (h.purinvcode = d.purinvcode)) AND (d.icode = gd.icode)) AND (d.batch = gd.batch)) AND (d.expiry = gd.expiry)) GROUP BY gd.icode, gd.batch, gd.expiry UNION ALL SELECT gd.icode, gd.batch, gd.expiry, min(h.postdate) AS indate FROM dbo.srdetail AS d, dbo.srledger AS h, dbo.godowndetail AS gd WHERE (((((h.posted = 'Y') AND (h.srinvcode = d.srinvcode)) AND (d.icode = gd.icode)) AND (d.batch = gd.batch)) AND (d.expiry = gd.expiry)) GROUP BY gd.icode, gd.batch, gd.expiry UNION ALL SELECT gd.icode, gd.batch, gd.expiry, min(h.postdate) AS indate FROM dbo.receiptdetail AS d, dbo.receiptheader AS h, dbo.godowndetail AS gd WHERE (((((h.posted = 'Y') AND (h.receiptinvcode = d.receiptinvcode)) AND (d.icode = gd.icode)) AND (d.batch = gd.batch)) AND (d.expiry = gd.expiry)) GROUP BY gd.icode, gd.batch, gd.expiry UNION ALL SELECT gd.icode, gd.batch, gd.expiry, min(h.date) AS indate FROM dbo.adjdetail AS d, dbo.adjheader AS h, dbo.godowndetail AS gd WHERE ((((((h.posted = 'Y') AND (adjcatcode = 1)) AND (h.adjcode = d.adjcode)) AND (d.icode = gd.icode)) AND (d.batch = gd.batch)) AND (d.expiry = gd.expiry)) GROUP BY gd.icode, gd.batch, gd.expiry) AS t GROUP BY t.icode, t.batch, t.expiry ORDER BY icode, indate, expiry, batch;
    FETCH NEXT FROM cur_cursor1 INTO v_icode, v_batch, v_expiry, v_indate;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    WHILE (_fs = 0) LOOP
      IF (v_icode = v_oldicode) THEN
        v_priority := (v_priority + 1);
      ELSE
        v_priority := 1;
      END IF;
      IF (v_priority > 8) THEN
        v_priority := 8;
      END IF;
      UPDATE dbo.godowndetail SET priority = v_priority WHERE (((icode = v_icode) AND (batch = v_batch)) AND (expiry = v_expiry));
      v_oldicode := v_icode;
      FETCH NEXT FROM cur_cursor1 INTO v_icode, v_batch, v_expiry, v_indate;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    END LOOP;
    CLOSE cur_cursor1;
    -- DEALLOCATE cursor1
  END IF;
  IF (v_method = 3) THEN
    UPDATE dbo.godowndetail SET priority = 30;
    v_oldicode := NULL;
    v_priority := 10;
    OPEN cur_cursor2 FOR SELECT t.icode, t.batch, t.expiry, max(t.indate) AS indate FROM (SELECT gd.icode, gd.batch, gd.expiry, max(h.postdate) AS indate FROM dbo.purdetail AS d, dbo.purledger AS h, dbo.godowndetail AS gd WHERE (((((h.posted = 'Y') AND (h.purinvcode = d.purinvcode)) AND (d.icode = gd.icode)) AND (d.batch = gd.batch)) AND (d.expiry = gd.expiry)) GROUP BY gd.icode, gd.batch, gd.expiry UNION ALL SELECT gd.icode, gd.batch, gd.expiry, max(h.postdate) AS indate FROM dbo.srdetail AS d, dbo.srledger AS h, dbo.godowndetail AS gd WHERE (((((h.posted = 'Y') AND (h.srinvcode = d.srinvcode)) AND (d.icode = gd.icode)) AND (d.batch = gd.batch)) AND (d.expiry = gd.expiry)) GROUP BY gd.icode, gd.batch, gd.expiry UNION ALL SELECT gd.icode, gd.batch, gd.expiry, max(h.postdate) AS indate FROM dbo.receiptdetail AS d, dbo.receiptheader AS h, dbo.godowndetail AS gd WHERE (((((h.posted = 'Y') AND (h.receiptinvcode = d.receiptinvcode)) AND (d.icode = gd.icode)) AND (d.batch = gd.batch)) AND (d.expiry = gd.expiry)) GROUP BY gd.icode, gd.batch, gd.expiry UNION ALL SELECT gd.icode, gd.batch, gd.expiry, max(h.date) AS indate FROM dbo.adjdetail AS d, dbo.adjheader AS h, dbo.godowndetail AS gd WHERE ((((((h.posted = 'Y') AND (adjcatcode = 1)) AND (h.adjcode = d.adjcode)) AND (d.icode = gd.icode)) AND (d.batch = gd.batch)) AND (d.expiry = gd.expiry)) GROUP BY gd.icode, gd.batch, gd.expiry) AS t GROUP BY t.icode, t.batch, t.expiry ORDER BY icode, indate DESC, expiry, batch;
    FETCH NEXT FROM cur_cursor2 INTO v_icode, v_batch, v_expiry, v_indate;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    WHILE (_fs = 0) LOOP
      IF (v_icode = v_oldicode) THEN
        v_priority := (v_priority + 1);
      ELSE
        v_priority := 11;
      END IF;
      IF (v_priority > 29) THEN
        v_priority := 29;
      END IF;
      UPDATE dbo.godowndetail SET priority = v_priority WHERE (((icode = v_icode) AND (batch = v_batch)) AND (expiry = v_expiry));
      v_oldicode := v_icode;
      FETCH NEXT FROM cur_cursor2 INTO v_icode, v_batch, v_expiry, v_indate;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    END LOOP;
    CLOSE cur_cursor2;
    -- DEALLOCATE cursor2
  END IF;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_RequestHttpWebService ====
CREATE OR REPLACE FUNCTION dbo.sp_requesthttpwebservice(url citext, httpmethod citext, paramsvalues citext, soapaction citext DEFAULT NULL, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_url citext;
  v_httpmethod citext;
  v_paramsvalues citext;
  v_soapaction citext;
  v_obj integer;
  v_response citext;
  v_status citext;
  v_statustext citext;
  v_method citext;
  v_host citext;
  v_envelope citext;
  v_params citext;
  v_param citext;
  v_value citext;
BEGIN
  v_url := url;
  v_httpmethod := httpmethod;
  v_paramsvalues := paramsvalues;
  v_soapaction := soapaction;
  -- SET NOCOUNT ON
  IF ((v_httpmethod IN ('get', 'GET')) AND (length(rtrim(v_paramsvalues)) > 0)) THEN
    v_url := ((v_url || '?') || v_paramsvalues);
  END IF;
  v_method := (CASE WHEN (v_httpmethod IN ('soap', 'SOAP')) THEN 'POST' ELSE v_httpmethod END);
  -- exec sp_OACreate 'MSXML2.ServerXMLHttp', @obj out
  RAISE EXCEPTION 'untranslated T-SQL (unknown procedure sp_OACreate)' USING ERRCODE = '0A000';
  -- exec sp_OAMethod @obj, 'Open', null, @method, @Url, false
  RAISE EXCEPTION 'untranslated T-SQL (unknown procedure sp_OAMethod)' USING ERRCODE = '0A000';
  IF (v_httpmethod IN ('get', 'GET')) THEN
    -- exec sp_OAMethod @obj, 'send'
    RAISE EXCEPTION 'untranslated T-SQL (unknown procedure sp_OAMethod)' USING ERRCODE = '0A000';
  ELSE
    IF (v_httpmethod IN ('post', 'POST')) THEN
      -- exec sp_OAMethod @obj, 'setRequestHeader', null, 'Content-Type', 'application/json' --'application/x-www-form-urlencoded'
      RAISE EXCEPTION 'untranslated T-SQL (unknown procedure sp_OAMethod)' USING ERRCODE = '0A000';
      -- exec sp_OAMethod @obj, 'send', null, @ParamsValues
      RAISE EXCEPTION 'untranslated T-SQL (unknown procedure sp_OAMethod)' USING ERRCODE = '0A000';
    ELSE
      IF (v_httpmethod IN ('soap', 'SOAP')) THEN
        IF (v_soapaction IS NULL) THEN
          RAISE NOTICE '@SoapAction is null';
        END IF;
        v_host := v_url;
        IF (v_host LIKE 'http://%') THEN
          v_host := right(v_host, (length(rtrim(v_host)) - 7));
        ELSE
          IF (v_host LIKE 'https://%') THEN
            v_host := right(v_host, (length(rtrim(v_host)) - 8));
          END IF;
        END IF;
        IF ((strpos((v_host)::citext, (':')::citext) > 0) AND (strpos((v_host)::citext, (':')::citext) < strpos((v_host)::citext, ('/')::citext))) THEN
          v_host := left(v_host, (strpos((v_host)::citext, (':')::citext) - 1));
        ELSE
          v_host := left(v_host, (strpos((v_host)::citext, ('/')::citext) - 1));
        END IF;
        v_envelope := '<?xml version="1.0" encoding="utf-8"?><soap:Envelope xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:xsd="http://www.w3.org/2001/XMLSchema" xmlns:soap="http://schemas.xmlsoap.org/soap/envelope/"><soap:Body><{action} xmlns="http://tempuri.org/">{params}</{action}></soap:Body></soap:Envelope>';
        v_params := '';
        WHILE (length(rtrim(v_paramsvalues)) > 0) LOOP
          v_param := NULL;
          v_value := NULL;
          IF (strpos((v_paramsvalues)::citext, ('&')::citext) > 0) THEN
            v_param := left(v_paramsvalues, (strpos((v_paramsvalues)::citext, ('&')::citext) - 1));
            v_value := right(v_param, (length(rtrim(v_param)) - strpos((v_param)::citext, ('=')::citext)));
            v_param := left(v_param, (strpos((v_param)::citext, ('=')::citext) - 1));
            v_params := (((((((v_params || '<') || v_param) || '>') || v_value) || '</') || v_param) || '>');
            v_paramsvalues := right(v_paramsvalues, (length(rtrim(v_paramsvalues)) - length(rtrim((((v_param || '=') || v_value) || '&')))));
          ELSE
            v_value := right(v_paramsvalues, (length(rtrim(v_paramsvalues)) - strpos((v_paramsvalues)::citext, ('=')::citext)));
            v_param := left(v_paramsvalues, (strpos((v_paramsvalues)::citext, ('=')::citext) - 1));
            v_params := (((((((v_params || '<') || v_param) || '>') || v_value) || '</') || v_param) || '>');
            v_paramsvalues := NULL;
          END IF;
        END LOOP;
        v_envelope := replace((v_envelope)::citext, ('{action}')::citext, (v_soapaction)::citext);
        v_envelope := replace((v_envelope)::citext, ('{params}')::citext, (v_params)::citext);
        v_soapaction := ('http://tempuri.org/' || v_soapaction);
        RAISE NOTICE '%', v_host;
        RAISE NOTICE '%', v_soapaction;
        RAISE NOTICE '%', v_envelope;
        -- exec sp_OAMethod @obj, 'setRequestHeader', null, 'Content-Type', 'text/xml; charset=utf-8'
        RAISE EXCEPTION 'untranslated T-SQL (unknown procedure sp_OAMethod)' USING ERRCODE = '0A000';
        -- exec sp_OAMethod @obj, 'setRequestHeader', null, 'Host', @host
        RAISE EXCEPTION 'untranslated T-SQL (unknown procedure sp_OAMethod)' USING ERRCODE = '0A000';
        -- exec sp_OAMethod @obj, 'setRequestHeader', null, 'SOAPAction', @SoapAction
        RAISE EXCEPTION 'untranslated T-SQL (unknown procedure sp_OAMethod)' USING ERRCODE = '0A000';
        -- exec sp_OAMethod @obj, 'send', null, @envelope
        RAISE EXCEPTION 'untranslated T-SQL (unknown procedure sp_OAMethod)' USING ERRCODE = '0A000';
      END IF;
    END IF;
  END IF;
  -- exec sp_OAGetProperty @obj, 'responseText', @response out
  RAISE EXCEPTION 'untranslated T-SQL (unknown procedure sp_OAGetProperty)' USING ERRCODE = '0A000';
  -- exec sp_OADestroy @obj
  RAISE EXCEPTION 'untranslated T-SQL (unknown procedure sp_OADestroy)' USING ERRCODE = '0A000';
  OPEN rs1 FOR SELECT v_status AS status, v_statustext AS statustext, v_response AS response;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_RestrictSelectedClassItems ====
CREATE OR REPLACE FUNCTION dbo.sp_restrictselectedclassitems(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
BEGIN
  UPDATE dbo.item SET restricted = 'Y' WHERE ((iccode = 2) AND (((extract(hour from localtimestamp(3))::integer > 7) AND (extract(hour from localtimestamp(3))::integer < 23))));
  UPDATE dbo.item SET restricted = 'N' WHERE ((iccode = 2) AND (NOT (((extract(hour from localtimestamp(3))::integer > 7) AND (extract(hour from localtimestamp(3))::integer < 23)))));
  UPDATE dbo.item SET restricted = 'N' WHERE ((iccode = 3) AND (((extract(hour from localtimestamp(3))::integer > 7) AND (extract(hour from localtimestamp(3))::integer < 23))));
  UPDATE dbo.item SET restricted = 'Y' WHERE ((iccode = 3) AND (NOT (((extract(hour from localtimestamp(3))::integer > 7) AND (extract(hour from localtimestamp(3))::integer < 23)))));
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_Returndatetime ====
CREATE OR REPLACE FUNCTION dbo.sp_returndatetime(INOUT ad_date timestamp, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ad_date timestamp(3);
BEGIN
  v_ad_date := ad_date;
  v_ad_date := (SELECT localtimestamp(3));
  return_value := 0;
  ad_date := v_ad_date;
  RETURN;
END
$body$;

-- ==== proc sp_SaleAndReturnCatClassWise ====
CREATE OR REPLACE FUNCTION dbo.sp_saleandreturncatclasswise(ad_date timestamp, ad_ldate timestamp, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ad_date timestamp(3);
  v_ad_ldate timestamp(3);
BEGIN
  v_ad_date := ad_date;
  v_ad_ldate := ad_ldate;
  DELETE FROM dbo.reportdata;
  INSERT INTO dbo.reportdata (name1, code1, name2, value1, value2, value4, value5) SELECT (SELECT itemcategory.name FROM dbo.itemcategory WHERE (itemcategory.icatcode = a.icatcode)) AS categoryname, a.iccode, (SELECT name FROM dbo.itemclass WHERE (iccode = a.iccode)) AS classname, (SELECT coalesce(sum(round(((((((sd.looseqty + (sd.packqty * sd.packunits))) * ((sd.saleprice - sd.itemflatdisc)))) * ((1 - ((.01 * sd.discperc))))))::numeric, 2)), 0) FROM dbo.saledetail AS sd, dbo.saleledger AS sl, dbo.item AS i WHERE (((((sl.date BETWEEN v_ad_date AND v_ad_ldate) AND (sl.saleinvcode = sd.saleinvcode)) AND (sd.icode = i.icode)) AND (i.iccode = a.iccode)) AND (i.icatcode = a.icatcode))) AS salevalue, (SELECT coalesce(sum(round(((((((srd.looseqty + (srd.packqty * srd.packunits))) * srd.srprice)) * ((1 - ((.01 * srd.discperc))))))::numeric, 2)), 0) FROM dbo.srdetail AS srd, dbo.srledger AS srl, dbo.item AS i WHERE (((((srl.date BETWEEN v_ad_date AND v_ad_ldate) AND (srl.srinvcode = srd.srinvcode)) AND (srd.icode = i.icode)) AND (i.iccode = a.iccode)) AND (i.icatcode = a.icatcode))) AS srvalue, (SELECT coalesce(sum((sd.looseqty + (sd.packqty * sd.packunits))), 0) FROM dbo.saledetail AS sd, dbo.saleledger AS sl, dbo.item AS i WHERE (((((sl.date BETWEEN v_ad_date AND v_ad_ldate) AND (sl.saleinvcode = sd.saleinvcode)) AND (sd.icode = i.icode)) AND (i.iccode = a.iccode)) AND (i.icatcode = a.icatcode))) AS saleqty, (SELECT coalesce(sum((srd.looseqty + (srd.packqty * srd.packunits))), 0) FROM dbo.srdetail AS srd, dbo.srledger AS srl, dbo.item AS i WHERE (((((srl.date BETWEEN v_ad_date AND v_ad_ldate) AND (srl.srinvcode = srd.srinvcode)) AND (srd.icode = i.icode)) AND (i.iccode = a.iccode)) AND (i.icatcode = a.icatcode))) AS srqty FROM (SELECT DISTINCT item.iccode AS iccode, item.icatcode AS icatcode FROM dbo.saledetail, dbo.saleledger, dbo.item WHERE (((saleledger.date BETWEEN v_ad_date AND v_ad_ldate) AND (saleledger.saleinvcode = saledetail.saleinvcode)) AND (saledetail.icode = item.icode)) UNION SELECT DISTINCT item.iccode AS iccode, item.icatcode AS icatcode FROM dbo.srdetail, dbo.srledger, dbo.item WHERE (((srledger.date BETWEEN v_ad_date AND v_ad_ldate) AND (srledger.srinvcode = srdetail.srinvcode)) AND (srdetail.icode = item.icode))) AS a;
  UPDATE dbo.reportdata SET value3 = (value1 - value2);
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_SaleAndReturnCategoryWise ====
CREATE OR REPLACE FUNCTION dbo.sp_saleandreturncategorywise(ad_date timestamp, ad_ldate timestamp, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ad_date timestamp(3);
  v_ad_ldate timestamp(3);
BEGIN
  v_ad_date := ad_date;
  v_ad_ldate := ad_ldate;
  DELETE FROM dbo.reportdata;
  INSERT INTO dbo.reportdata (code1, name1, value1, value2, value4, value5) SELECT a.icatcode, (SELECT name FROM dbo.itemcategory WHERE (icatcode = a.icatcode)) AS catname, (SELECT coalesce(sum(((sd.looseqty * ((sd.saleprice - sd.itemflatdisc))) * ((1 - ((.01 * sd.discperc)))))), 0) FROM dbo.saledetail AS sd, dbo.saleledger AS sl, dbo.item AS i WHERE ((((sl.date BETWEEN v_ad_date AND v_ad_ldate) AND (sl.saleinvcode = sd.saleinvcode)) AND (sd.icode = i.icode)) AND (i.icatcode = a.icatcode))) AS salevalue, (SELECT coalesce(sum(((srd.looseqty * srd.srprice) * ((1 - ((.01 * srd.discperc)))))), 0) FROM dbo.srdetail AS srd, dbo.srledger AS srl, dbo.item AS i WHERE ((((srl.date BETWEEN v_ad_date AND v_ad_ldate) AND (srl.srinvcode = srd.srinvcode)) AND (srd.icode = i.icode)) AND (i.icatcode = a.icatcode))) AS srvalue, (SELECT coalesce((sum((sd.looseqty * sd.unitsalestax)) + sum(round((((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc))) * ((1 - ((.01 * sd.discperc))))) * sd.gstperc) * 0.01))::numeric, 2))), 0) FROM dbo.saledetail AS sd, dbo.saleledger AS sl, dbo.item AS i WHERE ((((sl.date BETWEEN v_ad_date AND v_ad_ldate) AND (sl.saleinvcode = sd.saleinvcode)) AND (sd.icode = i.icode)) AND (i.icatcode = a.icatcode))) AS saletax, (SELECT coalesce((sum((sd.looseqty * sd.unitsalestax)) + sum(round((((((sd.looseqty * sd.srprice) * ((1 - ((.01 * sd.discperc))))) * sd.gstperc) * 0.01))::numeric, 2))), 0) FROM dbo.srdetail AS sd, dbo.srledger AS sl, dbo.item AS i WHERE ((((sl.date BETWEEN v_ad_date AND v_ad_ldate) AND (sl.srinvcode = sd.srinvcode)) AND (sd.icode = i.icode)) AND (i.icatcode = a.icatcode))) AS returntax FROM (SELECT DISTINCT (item.icatcode) AS icatcode FROM dbo.saledetail, dbo.saleledger, dbo.item WHERE (((saleledger.date BETWEEN v_ad_date AND v_ad_ldate) AND (saleledger.saleinvcode = saledetail.saleinvcode)) AND (saledetail.icode = item.icode)) UNION SELECT DISTINCT (item.icatcode) AS icatcode FROM dbo.srdetail, dbo.srledger, dbo.item WHERE (((srledger.date BETWEEN v_ad_date AND v_ad_ldate) AND (srledger.srinvcode = srdetail.srinvcode)) AND (srdetail.icode = item.icode))) AS a;
  UPDATE dbo.reportdata SET value3 = (value1 - value2);
  -- COMMIT (the caller owns the transaction)
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_SaleAndReturnCategoryWise_wrt_SaleCat ====
CREATE OR REPLACE FUNCTION dbo.sp_saleandreturncategorywise_wrt_salecat(ad_date timestamp, ad_ldate timestamp, salecategory citext DEFAULT 'R', OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ad_date timestamp(3);
  v_ad_ldate timestamp(3);
  v_salecategory citext;
  v_salecatcode smallint;
  v_srcatcode smallint;
BEGIN
  v_ad_date := ad_date;
  v_ad_ldate := ad_ldate;
  v_salecategory := salecategory;
  IF ((upper(v_salecategory))::citext = 'W') THEN
    v_salecatcode := 2;
    v_srcatcode := 7;
  ELSE
    v_salecatcode := 3;
    v_srcatcode := 8;
  END IF;
  TRUNCATE TABLE dbo.reportdata;
  INSERT INTO dbo.reportdata (code1, name1, value1, value2) SELECT a.icatcode, (SELECT name FROM dbo.itemcategory WHERE (icatcode = a.icatcode)) AS catname, (SELECT coalesce(sum(round(((((((sd.looseqty + (sd.packqty * sd.packunits))) * ((sd.saleprice - sd.itemflatdisc)))) * ((1 - ((.01 * sd.discperc))))))::numeric, 2)), 0) FROM dbo.saledetail AS sd, dbo.saleledger AS sl, dbo.item AS i WHERE (((((sl.date BETWEEN v_ad_date AND v_ad_ldate) AND (sl.saleinvcode = sd.saleinvcode)) AND (sl.salecatcode = v_salecatcode)) AND (sd.icode = i.icode)) AND (i.icatcode = a.icatcode))) AS salevalue, (SELECT coalesce(sum(round(((((((srd.looseqty + (srd.packqty * srd.packunits))) * srd.srprice)) * ((1 - ((.01 * srd.discperc))))))::numeric, 2)), 0) FROM dbo.srdetail AS srd, dbo.srledger AS srl, dbo.item AS i WHERE (((((srl.date BETWEEN v_ad_date AND v_ad_ldate) AND (srl.srinvcode = srd.srinvcode)) AND (srl.srcatcode = v_srcatcode)) AND (srd.icode = i.icode)) AND (i.icatcode = a.icatcode))) AS srvalue FROM (SELECT DISTINCT (item.icatcode) AS icatcode FROM dbo.saledetail, dbo.saleledger, dbo.item WHERE ((((saleledger.date BETWEEN v_ad_date AND v_ad_ldate) AND (saleledger.saleinvcode = saledetail.saleinvcode)) AND (saleledger.salecatcode = v_salecatcode)) AND (saledetail.icode = item.icode)) UNION SELECT DISTINCT (item.icatcode) AS icatcode FROM dbo.srdetail, dbo.srledger, dbo.item WHERE ((((srledger.date BETWEEN v_ad_date AND v_ad_ldate) AND (srledger.srinvcode = srdetail.srinvcode)) AND (srledger.srinvcode = v_srcatcode)) AND (srdetail.icode = item.icode))) AS a;
  UPDATE dbo.reportdata SET value3 = (value1 - value2);
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_SaleAndReturnClassWise ====
CREATE OR REPLACE FUNCTION dbo.sp_saleandreturnclasswise(ad_date timestamp, ad_ldate timestamp, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ad_date timestamp(3);
  v_ad_ldate timestamp(3);
BEGIN
  v_ad_date := ad_date;
  v_ad_ldate := ad_ldate;
  DELETE FROM dbo.reportdata;
  INSERT INTO dbo.reportdata (code1, name1, value1, value2, value4, value5) SELECT a.iccode, (SELECT name FROM dbo.itemclass WHERE (iccode = a.iccode)) AS classname, (SELECT coalesce(sum(round(((((((sd.looseqty + (sd.packqty * sd.packunits))) * ((sd.saleprice - sd.itemflatdisc)))) * ((1 - ((.01 * sd.discperc))))))::numeric, 2)), 0) FROM dbo.saledetail AS sd, dbo.saleledger AS sl, dbo.item AS i WHERE ((((sl.date BETWEEN v_ad_date AND v_ad_ldate) AND (sl.saleinvcode = sd.saleinvcode)) AND (sd.icode = i.icode)) AND (i.iccode = a.iccode))) AS salevalue, (SELECT coalesce(sum(round(((((((srd.looseqty + (srd.packqty * srd.packunits))) * srd.srprice)) * ((1 - ((.01 * srd.discperc))))))::numeric, 2)), 0) FROM dbo.srdetail AS srd, dbo.srledger AS srl, dbo.item AS i WHERE ((((srl.date BETWEEN v_ad_date AND v_ad_ldate) AND (srl.srinvcode = srd.srinvcode)) AND (srd.icode = i.icode)) AND (i.iccode = a.iccode))) AS srvalue, (SELECT coalesce(sum((sd.looseqty + (sd.packqty * sd.packunits))), 0) FROM dbo.saledetail AS sd, dbo.saleledger AS sl, dbo.item AS i WHERE ((((sl.date BETWEEN v_ad_date AND v_ad_ldate) AND (sl.saleinvcode = sd.saleinvcode)) AND (sd.icode = i.icode)) AND (i.iccode = a.iccode))) AS saleqty, (SELECT coalesce(sum((srd.looseqty + (srd.packqty * srd.packunits))), 0) FROM dbo.srdetail AS srd, dbo.srledger AS srl, dbo.item AS i WHERE ((((srl.date BETWEEN v_ad_date AND v_ad_ldate) AND (srl.srinvcode = srd.srinvcode)) AND (srd.icode = i.icode)) AND (i.iccode = a.iccode))) AS srqty FROM (SELECT DISTINCT (item.iccode) AS iccode FROM dbo.saledetail, dbo.saleledger, dbo.item WHERE (((saleledger.date BETWEEN v_ad_date AND v_ad_ldate) AND (saleledger.saleinvcode = saledetail.saleinvcode)) AND (saledetail.icode = item.icode)) UNION SELECT DISTINCT (item.iccode) AS iccode FROM dbo.srdetail, dbo.srledger, dbo.item WHERE (((srledger.date BETWEEN v_ad_date AND v_ad_ldate) AND (srledger.srinvcode = srdetail.srinvcode)) AND (srdetail.icode = item.icode))) AS a;
  UPDATE dbo.reportdata SET value3 = (value1 - value2);
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_SaleAndReturnClassWise_invrange ====
