-- ==== proc sp_SaleInvList_From_DataCarryDB ====
CREATE OR REPLACE FUNCTION dbo.sp_saleinvlist_from_datacarrydb(srv citext, db citext, owner citext, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_query citext;
  _dq1 text;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  v_query := ((((((('Select SaleInvCode, Date, InvTotal, Remarks From 	' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.') || 'SaleLedger');
  _dq1 := v_query;
  IF _dq1 IS NOT NULL THEN
    IF _dq1 ~* '^[[:space:]]*select' THEN OPEN rs1 FOR EXECUTE dbo.tsql_dyn(_dq1); ELSE EXECUTE dbo.tsql_dyn(_dq1); END IF;
  END IF;
  return_value := 1;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_SaleInvList_From_DropBox ====
CREATE OR REPLACE FUNCTION dbo.sp_saleinvlist_from_dropbox(srv citext, db citext, owner citext, sitecode integer, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_sitecode integer;
  v_query citext;
  v_prefix citext;
  _dq1 text;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  v_sitecode := sitecode;
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  v_prefix := '';
  IF (((length(rtrim(ltrim(rtrim(v_srv)))) = 0) OR (v_srv IS NULL))) THEN
    v_prefix := '';
  ELSE
    v_prefix := (v_srv || '.');
  END IF;
  IF (((length(rtrim(ltrim(rtrim(v_db)))) = 0) OR (v_db IS NULL))) THEN
    v_prefix := v_prefix;
  ELSE
    v_prefix := ((v_prefix || v_db) || '.');
  END IF;
  IF (((length(rtrim(ltrim(rtrim(v_owner)))) = 0) OR (v_owner IS NULL))) THEN
    v_prefix := ((v_prefix || 'DBO') || '.');
  ELSE
    v_prefix := ((v_prefix || v_owner) || '.');
  END IF;
  v_query := (((('Select SiteCode, Site=(SELECT Site.Name + SPACE(1) + CHAR(45) + SPACE(1) + InstanceID FROM Site WHERE Site.Sitecode = T.SiteCode), T.SaleInvCode, T.Date, T.InvTotal, T.Remarks From 	' || v_prefix) || 'DB_SaleLedger AS T WHERE T.TargetSiteCode = ') || ltrim(rtrim(dbo.tsql_str((v_sitecode)::numeric)))) || ' AND T.Pulled = ''N''');
  _dq1 := v_query;
  IF _dq1 IS NOT NULL THEN
    IF _dq1 ~* '^[[:space:]]*select' THEN OPEN rs1 FOR EXECUTE dbo.tsql_dyn(_dq1); ELSE EXECUTE dbo.tsql_dyn(_dq1); END IF;
  END IF;
  return_value := 1;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_Salereturninfo ====
CREATE OR REPLACE FUNCTION dbo.sp_salereturninfo(al_code integer, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_al_code integer;
BEGIN
  v_al_code := al_code;
  DROP TABLE IF EXISTS tmp_lt_pvamts;
  CREATE TEMP TABLE tmp_lt_pvamts (
    name citext NOT NULL,
    name1 citext NOT NULL,
    icode integer,
    customicoe citext,
    gcode smallint,
    batch citext,
    expiry timestamp(3),
    saleprice numeric(12,2),
    discperc numeric(5,2),
    looseqty numeric(15,4),
    packunits smallint,
    returnqty numeric(15,4)
) ON COMMIT DROP;
  INSERT INTO tmp_lt_pvamts SELECT item.name, ((item.name || repeat(' ', 70)) || dbo.tsql_str((item.icode)::numeric)) AS name1, item.icode, item.customicode, saledetail.gcode, saledetail.batch, saledetail.expiry, saledetail.saleprice, saledetail.discperc, saledetail.looseqty, saledetail.packunits, (SELECT coalesce(sum(srdetail.looseqty), 0) FROM dbo.srledger, dbo.srdetail WHERE (((((((srledger.saleinvcode = saledetail.saleinvcode) AND (srledger.posted = 'Y')) AND (srledger.srinvcode = srdetail.srinvcode)) AND (srdetail.gcode = saledetail.gcode)) AND (srdetail.icode = item.icode)) AND (srdetail.batch = saledetail.batch)) AND (srdetail.expiry = saledetail.expiry))) AS returnqty FROM dbo.item, dbo.saledetail WHERE ((((saledetail.saleinvcode = v_al_code)) AND ((item.icode = saledetail.icode))) AND ((saledetail.due IS NULL)));
  INSERT INTO tmp_lt_pvamts SELECT item.name, ((item.name || repeat(' ', 70)) || dbo.tsql_str((item.icode)::numeric)), item.icode, max(item.customicode), duesatisfydetail.gcode, duesatisfydetail.batch, duesatisfydetail.expiry, saledetail.saleprice, saledetail.discperc, sum(duesatisfydetail.duesatisfyqty) AS looseqty, saledetail.packunits, (SELECT coalesce(sum(srdetail.looseqty), 0) FROM dbo.srledger, dbo.srdetail WHERE (((((((srledger.saleinvcode = duesatisfyheader.saleinvcode) AND (srledger.posted = 'Y')) AND (srledger.srinvcode = srdetail.srinvcode)) AND (srdetail.gcode = duesatisfydetail.gcode)) AND (srdetail.icode = duesatisfydetail.icode)) AND (srdetail.batch = duesatisfydetail.batch)) AND (srdetail.expiry = duesatisfydetail.expiry))) AS returnqty FROM dbo.item, dbo.saledetail, dbo.duesatisfydetail, dbo.duesatisfyheader WHERE ((((((((saledetail.saleinvcode = v_al_code)) AND ((duesatisfyheader.saleinvcode = v_al_code))) AND ((duesatisfyheader.duesatisfycode = duesatisfydetail.duesatisfycode))) AND ((item.icode = duesatisfydetail.icode))) AND ((saledetail.gcode = duesatisfydetail.gcode))) AND ((saledetail.icode = duesatisfydetail.icode))) AND ((saledetail.due IN ('S', 'D', 'X')))) GROUP BY item.icode, item.name, duesatisfydetail.icode, duesatisfydetail.gcode, duesatisfydetail.batch, duesatisfydetail.expiry, duesatisfyheader.saleinvcode, saledetail.saleprice, saledetail.discperc, saledetail.packunits;
  OPEN rs1 FOR SELECT * FROM tmp_lt_pvamts AS lt_pvamts;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_SaleReturnPur ====
CREATE OR REPLACE FUNCTION dbo.sp_salereturnpur(s_date timestamp, l_date timestamp, l_manfcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_s_date timestamp(3);
  v_l_date timestamp(3);
  v_l_manfcode integer;
BEGIN
  v_s_date := s_date;
  v_l_date := l_date;
  v_l_manfcode := l_manfcode;
  DROP TABLE IF EXISTS tmp_lt_test;
  CREATE TEMP TABLE tmp_lt_test (
    test numeric(5,0) NOT NULL
) ON COMMIT DROP;
  DELETE FROM dbo.reportdata;
  INSERT INTO dbo.reportdata (code1, value1, value2, value3, value4, value5, value6, value7, value8) SELECT a.icode, round(((a.saleprice / a.packunits))::numeric, 2) AS saleprice, round(((a.purprice / a.packunits))::numeric, 2) AS purprice, coalesce((coalesce((SELECT sum(saledetail.looseqty) FROM dbo.saledetail, dbo.saleledger WHERE ((((saleledger.date BETWEEN v_s_date AND v_l_date) AND (saleledger.saleinvcode = saledetail.saleinvcode)) AND (saledetail.due IS NULL)) AND (saledetail.icode = a.icode))), 0) + coalesce((SELECT sum(duesatisfydetail.duesatisfyqty) FROM dbo.duesatisfydetail, dbo.duesatisfyheader WHERE (((duesatisfyheader.duesatisfydate BETWEEN v_s_date AND v_l_date) AND (duesatisfyheader.duesatisfycode = duesatisfydetail.duesatisfycode)) AND (duesatisfydetail.icode = a.icode))), 0)), 0) AS saleqty, coalesce((SELECT sum(srdetail.looseqty) FROM dbo.srdetail, dbo.srledger WHERE (((srledger.date BETWEEN v_s_date AND v_l_date) AND (srledger.srinvcode = srdetail.srinvcode)) AND (srdetail.icode = a.icode))), 0) AS saleretqty, coalesce((SELECT sum(CASE WHEN (purledger.purcatcode IN (3, 7, 8)) THEN (purdetail.looseqty + purdetail.bonusqty) ELSE (((purdetail.packqty + purdetail.bonusqty)) * purdetail.packunits) END) FROM dbo.purdetail, dbo.purledger WHERE ((((purledger.postdate BETWEEN v_s_date AND v_l_date) AND (purledger.posted = 'Y')) AND (purledger.purinvcode = purdetail.purinvcode)) AND (purdetail.icode = a.icode))), 0) AS purqty, coalesce((SELECT sum((prdetail.looseqty + prdetail.bonusqty)) FROM dbo.prdetail, dbo.prledger WHERE (((prledger.date BETWEEN v_s_date AND v_l_date) AND (prledger.prinvcode = prdetail.prinvcode)) AND (prdetail.icode = a.icode))), 0) AS prqtu, coalesce((SELECT sum(CASE WHEN (adjheader.adjcatcode = 1) THEN adjdetail.looseqty ELSE ((-1) * adjdetail.looseqty) END) FROM dbo.adjdetail, dbo.adjheader WHERE (((adjheader.date BETWEEN v_s_date AND v_l_date) AND (adjheader.adjcode = adjdetail.adjcode)) AND (adjdetail.icode = a.icode))), 0) AS adj, (coalesce((SELECT sum(issuedetail.qty) FROM dbo.issuedetail, dbo.issueheader WHERE (((issueheader.date BETWEEN v_s_date AND v_l_date) AND (issueheader.issueinvcode = issuedetail.issueinvcode)) AND (issuedetail.icode = a.icode))), 0) - coalesce((SELECT sum(receiptdetail.qty) FROM dbo.receiptdetail, dbo.receiptheader WHERE ((((receiptheader.date BETWEEN v_s_date AND v_l_date) AND (receiptheader.posted = 'Y')) AND (receiptheader.receiptinvcode = receiptdetail.receiptinvcode)) AND (receiptdetail.icode = a.icode))), 0)) AS issue FROM dbo.item AS a WHERE ((a.manfcode = v_l_manfcode) AND (a.active = 1));
  DROP TABLE IF EXISTS tmp_lt_test;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_SaleReturnPurWithDue ====
CREATE OR REPLACE FUNCTION dbo.sp_salereturnpurwithdue(s_date timestamp, l_date timestamp, l_manfcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_s_date timestamp(3);
  v_l_date timestamp(3);
  v_l_manfcode integer;
BEGIN
  v_s_date := s_date;
  v_l_date := l_date;
  v_l_manfcode := l_manfcode;
  DROP TABLE IF EXISTS tmp_lt_test;
  CREATE TEMP TABLE tmp_lt_test (
    test numeric(5,0) NOT NULL
) ON COMMIT DROP;
  DELETE FROM dbo.reportdata;
  INSERT INTO dbo.reportdata (code1, value1, value2, value3, value4, value5, value6, value7, value8) SELECT a.icode, round(((a.saleprice / a.packunits))::numeric, 2) AS saleprice, round(((a.purprice / a.packunits))::numeric, 2) AS purprice, coalesce((coalesce((SELECT sum(saledetail.looseqty) FROM dbo.saledetail, dbo.saleledger WHERE (((saleledger.date BETWEEN v_s_date AND v_l_date) AND (saleledger.saleinvcode = saledetail.saleinvcode)) AND (saledetail.icode = a.icode))), 0) + coalesce((SELECT sum(duesatisfydetail.duesatisfyqty) FROM dbo.duesatisfydetail, dbo.duesatisfyheader, dbo.saleledger WHERE (((((saleledger.date < v_s_date) AND (saleledger.saleinvcode = duesatisfyheader.saleinvcode)) AND (duesatisfyheader.duesatisfydate BETWEEN v_s_date AND v_l_date)) AND (duesatisfyheader.duesatisfycode = duesatisfydetail.duesatisfycode)) AND (duesatisfydetail.icode = a.icode))), 0)), 0) AS saleqty, coalesce((SELECT sum(srdetail.looseqty) FROM dbo.srdetail, dbo.srledger WHERE (((srledger.date BETWEEN v_s_date AND v_l_date) AND (srledger.srinvcode = srdetail.srinvcode)) AND (srdetail.icode = a.icode))), 0) AS saleretqty, coalesce((SELECT sum(CASE WHEN (purledger.purcatcode IN (3, 7, 8)) THEN (purdetail.looseqty + purdetail.bonusqty) ELSE (((purdetail.packqty + purdetail.bonusqty)) * purdetail.packunits) END) FROM dbo.purdetail, dbo.purledger WHERE ((((purledger.postdate BETWEEN v_s_date AND v_l_date) AND (purledger.posted = 'Y')) AND (purledger.purinvcode = purdetail.purinvcode)) AND (purdetail.icode = a.icode))), 0) AS purqty, coalesce((SELECT sum((prdetail.looseqty + prdetail.bonusqty)) FROM dbo.prdetail, dbo.prledger WHERE (((prledger.date BETWEEN v_s_date AND v_l_date) AND (prledger.prinvcode = prdetail.prinvcode)) AND (prdetail.icode = a.icode))), 0) AS prqtu, coalesce((SELECT sum(CASE WHEN (adjheader.adjcatcode = 1) THEN adjdetail.looseqty ELSE ((-1) * adjdetail.looseqty) END) FROM dbo.adjdetail, dbo.adjheader WHERE (((adjheader.date BETWEEN v_s_date AND v_l_date) AND (adjheader.adjcode = adjdetail.adjcode)) AND (adjdetail.icode = a.icode))), 0) AS adj, (coalesce((SELECT sum(issuedetail.qty) FROM dbo.issuedetail, dbo.issueheader WHERE (((issueheader.date BETWEEN v_s_date AND v_l_date) AND (issueheader.issueinvcode = issuedetail.issueinvcode)) AND (issuedetail.icode = a.icode))), 0) - coalesce((SELECT sum(receiptdetail.qty) FROM dbo.receiptdetail, dbo.receiptheader WHERE ((((receiptheader.date BETWEEN v_s_date AND v_l_date) AND (receiptheader.posted = 'Y')) AND (receiptheader.receiptinvcode = receiptdetail.receiptinvcode)) AND (receiptdetail.icode = a.icode))), 0)) AS issue FROM dbo.item AS a WHERE ((a.manfcode = v_l_manfcode) AND (a.active = 1));
  DROP TABLE IF EXISTS tmp_lt_test;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_SALESMAN_AREASALES_CROSSTAB ====
CREATE OR REPLACE FUNCTION dbo.sp_salesman_areasales_crosstab(salesmancode integer, startdate timestamp, enddate timestamp, reportgrouping citext, grouplist citext, pricetype smallint, totcol double precision, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_salesmancode integer;
  v_startdate timestamp(3);
  v_enddate timestamp(3);
  v_reportgrouping citext;
  v_grouplist citext;
  v_pricetype smallint;
  v_totcol double precision;
  v_upd citext;
  v_col citext;
  v_rowid integer;
  v_colname citext;
  v_colcode citext;
  v_str_col citext;
  v_totareas double precision;
  v_curriter integer;
  v_iterations integer;
  v_i integer;
  v_tot integer;
  v_icode integer;
  v_areacode integer;
  v_qty integer;
  v_val numeric(15,5);
  v_err integer;
  _dq1 text;
  cur_c1 refcursor;
  _dq2 text;
  _fs integer := -1;
BEGIN
  v_salesmancode := salesmancode;
  v_startdate := startdate;
  v_enddate := enddate;
  v_reportgrouping := reportgrouping;
  v_grouplist := grouplist;
  v_pricetype := pricetype;
  v_totcol := totcol;
  DELETE FROM dbo.crosstab_reportdata;
  -- SET NOCOUNT ON
  DROP TABLE IF EXISTS tv_sp_salesman_areasales_crosstab_coltable;
  CREATE TEMP TABLE tv_sp_salesman_areasales_crosstab_coltable (
    code integer,
    shortname citext,
    rowid integer GENERATED BY DEFAULT AS IDENTITY
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tv_sp_salesman_areasales_crosstab_saleareastable;
  CREATE TEMP TABLE tv_sp_salesman_areasales_crosstab_saleareastable (
    code integer
) ON COMMIT DROP;
  INSERT INTO tv_sp_salesman_areasales_crosstab_saleareastable SELECT DISTINCT c.areacode FROM dbo.saleledger AS s, dbo.saledetail AS d, dbo.customer AS c WHERE ((((((s.smancode = v_salesmancode) AND (s.saleinvcode = d.saleinvcode)) AND (s.date >= v_startdate)) AND (s.date <= v_enddate)) AND (s.posted = 'Y')) AND (s.custcode = c.custcode));
  v_totareas := coalesce((SELECT count(code) FROM tv_sp_salesman_areasales_crosstab_saleareastable AS saleareastable), 0);
  DROP TABLE IF EXISTS tv_sp_salesman_areasales_crosstab_tab_grouplist;
  CREATE TEMP TABLE tv_sp_salesman_areasales_crosstab_tab_grouplist (
    code integer NOT NULL
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tv_sp_salesman_areasales_crosstab_tab_itemlist;
  CREATE TEMP TABLE tv_sp_salesman_areasales_crosstab_tab_itemlist (
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tv_sp_salesman_areasales_crosstab_tab_grouplist SELECT code FROM dbo.udf_stringtotabl(v_grouplist, ',') AS udf_stringtotabl;
  INSERT INTO tv_sp_salesman_areasales_crosstab_tab_itemlist SELECT code FROM dbo.udf_selectitems(v_reportgrouping, v_grouplist) AS udf_selectitems;
  IF ((v_totareas > 0) AND (v_totcol > 0)) THEN
    v_tot := trunc((SELECT min(a) FROM (SELECT v_totcol AS a UNION SELECT v_totareas AS a) AS t))::integer;
    INSERT INTO tv_sp_salesman_areasales_crosstab_coltable (code, shortname) SELECT area.areacode, area.shortname FROM tv_sp_salesman_areasales_crosstab_saleareastable AS a, dbo.area WHERE (a.code = area.areacode) ORDER BY area.shortname;
    v_iterations := trunc(ceiling((v_totareas / v_totcol)))::integer;
    v_curriter := 1;
    v_rowid := 0;
    WHILE (v_curriter <= v_iterations) LOOP
      INSERT INTO dbo.crosstab_reportdata (code1, code2, code3) SELECT code, v_curriter, v_salesmancode FROM tv_sp_salesman_areasales_crosstab_tab_itemlist AS tab_itemlist;
      v_i := 1;
      WHILE (v_i <= v_tot) LOOP
        v_rowid := (v_rowid + 1);
        v_colname := rtrim(ltrim(coalesce((SELECT shortname FROM tv_sp_salesman_areasales_crosstab_coltable AS coltable WHERE (rowid = v_rowid)), '')));
        v_colcode := rtrim(ltrim(dbo.tsql_str(((SELECT code FROM tv_sp_salesman_areasales_crosstab_coltable AS coltable WHERE (rowid = v_rowid)))::numeric, 7)));
        IF (v_colcode IS NULL) THEN
          EXIT;
        ELSE
          v_str_col := ltrim(rtrim(dbo.tsql_str((v_i)::numeric, 7)));
          v_upd := ((((((((('UPDATE CrossTab_ReportData SET C_Name' || v_str_col) || ' = ''') || v_colname) || ''', C_Code') || v_str_col) || ' = ') || v_colcode) || ' WHERE CODE2 = ') || ltrim(rtrim(dbo.tsql_str((v_curriter)::numeric, 7))));
          _dq1 := v_upd;
          IF _dq1 IS NOT NULL THEN
            EXECUTE dbo.tsql_dyn(_dq1);
          END IF;
          v_err := 0;
          IF (v_err <> 0) THEN
            v_upd := ('UPDATION ERROR, DETAILS: ' || v_upd);
            RAISE EXCEPTION '%', v_upd;
            return_value := -1;
            RETURN;
          END IF;
          v_i := (v_i + 1);
        END IF;
      END LOOP;
      v_curriter := (v_curriter + 1);
    END LOOP;
    OPEN cur_c1 FOR SELECT s.icode, coalesce(sum(s.qty), 0) AS qty, round((sum(CASE v_pricetype WHEN 1 THEN s.netamt WHEN 2 THEN (s.qty * round(((i.saleprice / CASE i.packunits WHEN 0 THEN 1 ELSE i.packunits END))::numeric, 2)) WHEN 3 THEN (s.qty * round(((i.purprice / CASE i.packunits WHEN 0 THEN 1 ELSE i.packunits END))::numeric, 2)) ELSE (s.qty * round((i.avgprice)::numeric, 2)) END))::numeric, 0) AS val, s.areacode FROM (SELECT sl.saleinvcode AS invno, sd.icode, sl.custcode AS custcode, coalesce(sum((sd.looseqty + sd.bonusqty)), 0) AS qty, round((coalesce((sum((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc)))) * ((1 - ((.01 * sd.discperc)))))) * ((1 - ((.01 * sl.discperc))))), 0))::numeric, 2) AS netamt, c.areacode, sl.smancode FROM dbo.saleledger AS sl, dbo.saledetail AS sd, dbo.customer AS c, dbo.area AS a WHERE (((((((sl.smancode = v_salesmancode) AND (a.areacode = c.areacode)) AND (c.custcode = sl.custcode)) AND (sl.posted = 'Y')) AND (sl.saleinvcode = sd.saleinvcode)) AND (sl.date >= v_startdate)) AND (sl.date <= v_enddate)) GROUP BY sl.smancode, sl.saleinvcode, sd.icode, sl.custcode, c.areacode, sl.discperc UNION ALL SELECT sl.srinvcode AS invno, sd.icode, sl.custcode AS custcode, (-coalesce(sum((sd.looseqty + sd.bonusqty)), 0)) AS qty, (-round((coalesce((sum((((sd.looseqty * sd.srprice)) * ((1 - ((.01 * sd.discperc)))))) * ((1 - ((.01 * sl.discperc))))), 0))::numeric, 2)) AS netamt, c.areacode, sl.smancode FROM dbo.srledger AS sl, dbo.srdetail AS sd, dbo.customer AS c, dbo.area AS a WHERE (((((((sl.smancode = v_salesmancode) AND (a.areacode = c.areacode)) AND (c.custcode = sl.custcode)) AND (sl.posted = 'Y')) AND (sl.srinvcode = sd.srinvcode)) AND (sl.date >= v_startdate)) AND (sl.date <= v_enddate)) GROUP BY sl.smancode, sl.srinvcode, sd.icode, sl.custcode, c.areacode, sl.discperc) AS s, dbo.item AS i WHERE ((i.icode = s.icode) AND (i.icode IN (SELECT code FROM tv_sp_salesman_areasales_crosstab_tab_itemlist AS tab_itemlist))) GROUP BY s.areacode, s.icode ORDER BY s.areacode, s.icode;
    FETCH NEXT FROM cur_c1 INTO v_icode, v_qty, v_val, v_areacode;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    WHILE (_fs = 0) LOOP
      v_i := 1;
      WHILE (v_i <= v_tot) LOOP
        v_colcode := ltrim(rtrim(dbo.tsql_str((v_icode)::numeric, 7)));
        v_colname := ltrim(rtrim(dbo.tsql_str((v_areacode)::numeric, 7)));
        v_str_col := ltrim(rtrim(dbo.tsql_str((v_i)::numeric, 7)));
        v_upd := ((((((((((((((((((('UPDATE CrossTab_ReportData SET ' || 'QTY') || v_str_col) || ' = ') || ltrim(rtrim(dbo.tsql_str((v_qty)::numeric, 7)))) || ', VAL') || v_str_col) || ' = ') || ltrim(rtrim(dbo.tsql_str((v_val)::numeric, 15, 5)))) || ', C_Code') || v_str_col) || ' = ') || v_colname) || ' WHERE CODE1 = ') || v_colcode) || ' AND ') || ' C_Code') || v_str_col) || ' = ') || v_colname);
        _dq2 := v_upd;
        IF _dq2 IS NOT NULL THEN
          EXECUTE dbo.tsql_dyn(_dq2);
        END IF;
        v_err := 0;
        IF (v_err <> 0) THEN
          v_upd := ('CROSSTAB PLOTING ERROR, DETAILS: ' || v_upd);
          RAISE EXCEPTION '%', v_upd;
          CLOSE cur_c1;
          -- DEALLOCATE C1
          return_value := -1;
          RETURN;
        END IF;
        v_i := (v_i + 1);
      END LOOP;
      FETCH NEXT FROM cur_c1 INTO v_icode, v_qty, v_val, v_areacode;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    END LOOP;
    CLOSE cur_c1;
    -- DEALLOCATE C1
    UPDATE dbo.crosstab_reportdata AS c SET name1 = i.name, name2 = i.customicode, name3 = i.packingdesc, name4 = (SELECT name FROM dbo.salesman WHERE (salesmancode = v_salesmancode)), code5 = CASE v_reportgrouping WHEN 'M' THEN i.manfcode WHEN 'C' THEN i.icatcode WHEN 'L' THEN i.iccode ELSE i.packcode END, name5 = CASE v_reportgrouping WHEN 'M' THEN (SELECT m.name FROM dbo.manufacturer AS m WHERE (m.manfcode = i.manfcode)) WHEN 'C' THEN (SELECT c.name FROM dbo.itemcategory AS c WHERE (c.icatcode = i.icatcode)) WHEN 'L' THEN (SELECT c.name FROM dbo.itemclass AS c WHERE (c.iccode = i.iccode)) ELSE (SELECT p.name FROM dbo.itempacking AS p WHERE (p.packcode = i.packcode)) END, value1 = CASE v_pricetype WHEN 1 THEN round(((i.saleprice / CASE i.packunits WHEN 0 THEN 1 ELSE i.packunits END))::numeric, 2) WHEN 2 THEN round(((i.saleprice / CASE i.packunits WHEN 0 THEN 1 ELSE i.packunits END))::numeric, 2) WHEN 3 THEN round(((i.purprice / CASE i.packunits WHEN 0 THEN 1 ELSE i.packunits END))::numeric, 2) ELSE round((i.avgprice)::numeric, 2) END FROM dbo.item AS i WHERE (i.icode = c.code1);
    PERFORM dbo.sp_update_total_crosstab_reportdata();
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_SalesMan_CollectionPlan ====
CREATE OR REPLACE FUNCTION dbo.sp_salesman_collectionplan(date timestamp, salesmancode smallint, overduedays integer, OUT return_value integer, OUT rs1 refcursor, OUT rs2 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_date timestamp(3);
  v_salesmancode smallint;
  v_overduedays integer;
  v_oldacccode integer;
  v_acccode integer;
  v_rowid integer;
  v_daysold integer;
  v_startlimit integer;
  v_endlimit integer;
  v_weekofmonth integer;
  v_weekday integer;
  v_tdate timestamp(3);
  v_amt numeric(15,5);
  v_paid numeric(15,5);
  v_pmt numeric(15,5);
  cur_c1 refcursor;
  _fs integer := -1;
BEGIN
  v_date := date;
  v_salesmancode := salesmancode;
  v_overduedays := overduedays;
  PERFORM dbo.sp_virtualgl(ac_type => 'A');
  v_weekofmonth := (SELECT dbo.fn_weekdaycountinmonth(v_date));
  v_weekday := (extract(dow from v_date)::integer + 1);
  OPEN rs1 FOR SELECT v_weekofmonth, v_weekday;
  IF ((((v_weekofmonth IS NULL) OR (v_weekofmonth = 0)) OR (v_weekday IS NULL)) OR (v_weekday = 0)) THEN
    RAISE EXCEPTION 'Not A valid Date Selected, Please Select a valid date';
    return_value := -1;
    RETURN;
  END IF;
  DELETE FROM dbo.reportdata;
  DROP TABLE IF EXISTS tmp_lt_amt;
  CREATE TEMP TABLE tmp_lt_amt (
    acccode integer NOT NULL,
    date timestamp(3) NOT NULL,
    amount numeric(15,5) NOT NULL DEFAULT 0,
    paid numeric(15,5) NOT NULL DEFAULT 0,
    rowid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    daysold integer NOT NULL DEFAULT 0
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_lt_cust;
  CREATE TEMP TABLE tmp_lt_cust (
    acccode integer NOT NULL
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_lt_pmt;
  CREATE TEMP TABLE tmp_lt_pmt (
    acccode integer NOT NULL,
    amount numeric(15,5) NOT NULL DEFAULT 0
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_lt_interval;
  CREATE TEMP TABLE tmp_lt_interval (
    intervalid integer GENERATED BY DEFAULT AS IDENTITY (START WITH 0 INCREMENT BY 1 MINVALUE 0) NOT NULL,
    lowerlimit integer NOT NULL DEFAULT 0,
    upperlimit integer NOT NULL DEFAULT 0
) ON COMMIT DROP;
  v_startlimit := 0;
  WHILE (v_startlimit <= v_overduedays) LOOP
    v_endlimit := (v_startlimit + CASE v_startlimit WHEN 0 THEN 0 ELSE (v_overduedays - 1) END);
    v_endlimit := CASE WHEN (v_endlimit > v_overduedays) THEN v_overduedays ELSE v_endlimit END;
    INSERT INTO tmp_lt_interval (lowerlimit, upperlimit) VALUES (v_startlimit, v_endlimit);
    v_startlimit := (v_endlimit + 1);
  END LOOP;
  INSERT INTO tmp_lt_interval (lowerlimit, upperlimit) VALUES (v_startlimit, 99999999);
  INSERT INTO tmp_lt_cust SELECT c.custcode FROM dbo.customer AS c WHERE ((c.salesmancode = v_salesmancode) AND (c.collectionpolicycode IN (SELECT DISTINCT cp.contactpolicycode FROM dbo.contactpolicy AS cp, dbo.contactpolicydetail AS cpd WHERE (((cp.contactpolicycode = cpd.contactpolicycode) AND (cpd.weekdaycode = v_weekday)) AND (cpd.weekofmonth = v_weekofmonth)))));
  OPEN rs2 FOR SELECT * FROM tmp_lt_cust AS lt_cust;
  INSERT INTO tmp_lt_amt (acccode, date, amount, paid, daysold) SELECT acccode, date, debit AS amount, 0 AS paid, ((v_date)::date - (date)::date) AS daysold FROM dbo.virtualgl WHERE (((date <= v_date) AND (debit > 0)) AND (acccode IN (SELECT acccode FROM tmp_lt_cust AS lt_cust))) ORDER BY acccode, date, debit;
  INSERT INTO tmp_lt_pmt SELECT acccode, sum(credit) AS amount FROM dbo.virtualgl WHERE (((date <= v_date) AND (credit > 0)) AND (acccode IN (SELECT acccode FROM tmp_lt_cust AS lt_cust))) GROUP BY acccode ORDER BY acccode;
  OPEN cur_c1 FOR SELECT * FROM tmp_lt_amt AS lt_amt;
  FETCH NEXT FROM cur_c1 INTO v_acccode, v_tdate, v_amt, v_paid, v_rowid, v_daysold;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    v_pmt := coalesce((SELECT coalesce(amount, 0) FROM tmp_lt_pmt AS lt_pmt WHERE (acccode = v_acccode)), 0);
    IF (v_pmt <> 0) THEN
      UPDATE tmp_lt_amt AS lt_amt SET paid = (paid + CASE WHEN (v_amt >= v_pmt) THEN v_pmt ELSE v_amt END) WHERE (rowid = v_rowid);
      v_pmt := (v_pmt - (SELECT CASE WHEN (v_amt >= v_pmt) THEN v_pmt ELSE v_amt END));
      UPDATE tmp_lt_pmt AS lt_pmt SET amount = v_pmt WHERE (acccode = v_acccode);
    END IF;
    FETCH NEXT FROM cur_c1 INTO v_acccode, v_tdate, v_amt, v_paid, v_rowid, v_daysold;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_c1;
  -- DEALLOCATE C1
  DELETE FROM tmp_lt_amt AS lt_amt WHERE ((amount - paid) = 0);
  INSERT INTO dbo.reportdata (code1, code2, name1, name2, name3, name4, name5, value1, value2, value3) SELECT ar.areacode AS code1, ac.acccode AS code2, ar.name AS name1, ac.aliasname AS name2, ac.name AS name3, ltrim(rtrim(c.address1)) AS name4, (SELECT s.name FROM dbo.salesman AS s WHERE (s.salesmancode = v_salesmancode)) AS name5, sum(CASE WHEN (l.daysold > v_overduedays) THEN 0 ELSE (amount - paid) END) AS value1, sum(CASE WHEN (l.daysold > v_overduedays) THEN (amount - paid) ELSE 0 END) AS value2, coalesce((SELECT sum((v.debit - v.credit)) FROM dbo.virtualgl AS v WHERE ((v.acccode = ac.acccode) AND (v.date <= v_date))), 0) AS value3 FROM tmp_lt_amt AS l, dbo.accounts AS ac, dbo.area AS ar, dbo.customer AS c WHERE (((l.acccode = ac.acccode) AND (ac.acccode = c.custcode)) AND (c.areacode = ar.areacode)) GROUP BY ar.areacode, ar.name, ac.acccode, ac.name, ac.aliasname, c.address1, c.address2, c.phone UNION ALL SELECT ar.areacode AS code1, ac.acccode AS code2, ar.name AS name1, ac.aliasname AS name2, ac.name AS name3, ltrim(rtrim(c.address1)) AS name4, (SELECT s.name FROM dbo.salesman AS s WHERE (s.salesmancode = v_salesmancode)) AS name5, 0 AS value1, 0 AS value2, coalesce((SELECT sum((v.debit - v.credit)) FROM dbo.virtualgl AS v WHERE ((v.acccode = ac.acccode) AND (v.date <= v_date))), 0) AS value3 FROM tmp_lt_cust AS l, dbo.accounts AS ac, dbo.area AS ar, dbo.customer AS c WHERE ((((l.acccode NOT IN (SELECT DISTINCT acccode FROM tmp_lt_amt AS lt_amt)) AND (l.acccode = ac.acccode)) AND (ac.acccode = c.custcode)) AND (c.areacode = ar.areacode));
  DROP TABLE IF EXISTS tmp_lt_amt;
  DROP TABLE IF EXISTS tmp_lt_pmt;
  -- DROP TABLE #lt_cust skipped: an open result set reads it (ON COMMIT DROP removes it)
  DROP TABLE IF EXISTS tmp_lt_interval;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_SALESMANWISE_RECEIPTS ====
CREATE OR REPLACE FUNCTION dbo.sp_salesmanwise_receipts(month integer, year integer, smanlist citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_month integer;
  v_year integer;
  v_smanlist citext;
BEGIN
  v_month := month;
  v_year := year;
  v_smanlist := smanlist;
  DELETE FROM dbo.reportdata;
  DROP TABLE IF EXISTS tv_sp_salesmanwise_receipts_tab_smanlist;
  CREATE TEMP TABLE tv_sp_salesmanwise_receipts_tab_smanlist (
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tv_sp_salesmanwise_receipts_tab_smanlist SELECT code FROM dbo.udf_stringtotabl(v_smanlist, ',') AS udf_stringtotabl;
  INSERT INTO dbo.reportdata (name1, name2, value1, code1, code2) SELECT sm.name AS salesman, coalesce(r.date, left(to_char((SELECT min(date) FROM dbo.udf_daysofmonthlist((v_month)::smallint, v_year) AS udf_daysofmonthlist), 'DD/MM/YYYY'), 12)) AS date, sum(coalesce(r.amt, 0)) AS amt, v_month AS code1, v_year AS code2 FROM (SELECT * FROM dbo.salesman WHERE (salesmancode IN (SELECT code FROM tv_sp_salesmanwise_receipts_tab_smanlist AS tab_smanlist))) AS sm LEFT JOIN (SELECT c.salesmancode, left(to_char(h.date, 'DD/MM/YYYY'), 12) AS date, sum(d.credit) AS amt FROM dbo.customer AS c, dbo.gldetail AS d, dbo.glheader AS h WHERE ((((((h.vochcatcode IN (2, 4)) AND (h.glvochcode = d.glvochcode)) AND (d.acccode = c.custcode)) AND (extract(month from h.date)::integer = v_month)) AND (extract(year from h.date)::integer = v_year)) AND (c.salesmancode IN (SELECT code FROM tv_sp_salesmanwise_receipts_tab_smanlist AS tab_smanlist))) GROUP BY c.salesmancode, h.date UNION ALL SELECT sm.salesmancode, left(to_char(h.date, 'DD/MM/YYYY'), 12) AS date, 0 AS amt FROM dbo.udf_daysofmonthlist((v_month)::smallint, v_year) AS h, (SELECT min(salesmancode) AS salesmancode FROM dbo.salesman WHERE (salesmancode IN (SELECT code FROM tv_sp_salesmanwise_receipts_tab_smanlist AS tab_smanlist))) AS sm) AS r ON ((sm.salesmancode = r.salesmancode)) GROUP BY sm.name, r.date;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_SaleUpdateItemStockBatch ====
CREATE OR REPLACE FUNCTION dbo.sp_saleupdateitemstockbatch(gcode integer, icode integer, batch citext, expiry timestamp, newqty numeric, oldqty numeric, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_gcode integer;
  v_icode integer;
  v_batch citext;
  v_expiry timestamp(3);
  v_newqty numeric(15,4);
  v_oldqty numeric(15,4);
  v_itemname citext;
  v_string_expiry citext;
  _r1 record;
  _rc integer;
BEGIN
  v_gcode := gcode;
  v_icode := icode;
  v_batch := batch;
  v_expiry := expiry;
  v_newqty := newqty;
  v_oldqty := oldqty;
  UPDATE dbo.godowndetail SET currqty = v_newqty WHERE (((((godowndetail.gcode = v_gcode) AND (godowndetail.icode = v_icode)) AND (godowndetail.batch = v_batch)) AND (godowndetail.expiry = v_expiry)) AND (godowndetail.currqty = v_oldqty));
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((_rc = 0) OR (0 <> 0)) THEN
    _rc := 0;
    FOR _r1 IN SELECT name AS c1 FROM dbo.item WHERE (icode = v_icode) LOOP
      _rc := _rc + 1;
      v_itemname := _r1.c1;
    END LOOP;
    v_string_expiry := left(to_char(v_expiry, 'DD/MM/YYYY'), 25);
    _rc := 1;
    RAISE EXCEPTION 'Not enough stock available for the item (%) in batch no. (%) with expiry (%)', v_itemname, v_batch, v_string_expiry;
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_SatisfyDueInBulk ====
CREATE OR REPLACE FUNCTION dbo.sp_satisfydueinbulk(dueadjcode integer, usercode integer, serverdate timestamp, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_dueadjcode integer;
  v_usercode integer;
  v_serverdate timestamp(3);
  v_saleinvcode integer;
  v_duesatisfycode integer;
  v_dueutn bigint;
  v_icode integer;
  v_gcode smallint;
  v_salerowid integer;
  v_batch citext;
  v_expiry timestamp(3);
  v_reqqty numeric(15,4);
  v_givenqty numeric(15,4);
  v_totalqty numeric(15,4);
  v_currqty numeric(15,4);
  v_delqty numeric(15,4);
  v_batchqty numeric(15,4);
  v_newqty numeric(15,4);
  v_satisfiableqty numeric(15,4);
  v_satisfiedqty numeric(15,4);
  v_dueqty numeric(15,4);
  v_total_availablestock numeric(15,4);
  v_hold_avgprice numeric(15,5);
  v_packunits smallint;
  v_price numeric(12,2);
  v_saleprice numeric(12,2);
  v_continue integer;
  v_counter integer;
  v_totalrows integer;
  v_err integer;
  v_rowcount integer;
  v_rt_code integer;
  v_err_string citext;
  v_itemname citext;
  cur_cursor_duesatisfyinvoices refcursor;
  cur_cursor_duesatisfyinvoice_items refcursor;
  _r1 record;
  cur_itembatch_cursor refcursor;
  cur_cursor_duedeleteinvoices refcursor;
  cur_cursor_duedeleteinvoice_items refcursor;
  _rc integer;
  _fs integer := -1;
BEGIN
  v_dueadjcode := dueadjcode;
  v_usercode := usercode;
  v_serverdate := serverdate;
  OPEN cur_cursor_duesatisfyinvoices FOR SELECT saleinvcode FROM dbo.dueadjdetail WHERE (((dueadjcode = v_dueadjcode) AND (duedelete = 'N')) AND (satisfiableqty > 0)) GROUP BY saleinvcode ORDER BY saleinvcode;
  FETCH NEXT FROM cur_cursor_duesatisfyinvoices INTO v_saleinvcode;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  v_continue := 0;
  _rc := 1;
  WHILE ((_fs = 0) AND (v_continue >= 0)) LOOP
    SELECT r.return_value, r.key INTO v_rt_code, v_duesatisfycode FROM dbo.sp_gettabmaxkey(tabname => 'DueSatisfyHeader', key => v_duesatisfycode) AS r;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      v_continue := -1;
      _rc := 1;
    ELSE
      INSERT INTO dbo.duesatisfyheader (duesatisfycode, saleinvcode, duesatisfydate, usercode, dueadjcode) VALUES (v_duesatisfycode, v_saleinvcode, v_serverdate, v_usercode, v_dueadjcode);
      GET DIAGNOSTICS _rc = ROW_COUNT;
      OPEN cur_cursor_duesatisfyinvoice_items FOR SELECT icode, gcode, salerowid, satisfiableqty FROM dbo.dueadjdetail WHERE ((((dueadjcode = v_dueadjcode) AND (saleinvcode = v_saleinvcode)) AND (duedelete = 'N')) AND (satisfiableqty > 0));
      FETCH NEXT FROM cur_cursor_duesatisfyinvoice_items INTO v_icode, v_gcode, v_salerowid, v_satisfiableqty;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
      WHILE ((_fs = 0) AND (v_continue >= 0)) LOOP
        IF (dbo.fn_locksaledetailrow(v_saleinvcode, v_icode, v_salerowid) > 0) THEN
          v_satisfiedqty := dbo.fn_getitemduesatisfiedqty(v_saleinvcode, v_icode, v_salerowid);
          _rc := 1;
          v_dueqty := dbo.fn_getitemdueqty(v_saleinvcode, v_icode, v_salerowid);
          _rc := 1;
          IF (v_dueqty = ((v_satisfiedqty + v_satisfiableqty))) THEN
            PERFORM dbo.sp_updatesaledetail(saleinvcode => v_saleinvcode, gcode => (v_gcode)::integer, icode => v_icode, due => 'S', salerowid => v_salerowid);
            IF (0 <> 0) THEN
              v_continue := -1;
              _rc := 1;
              RAISE EXCEPTION 'Unable to update Due satisfy status in sale detail for SaleInv: %', v_saleinvcode;
            END IF;
          ELSE
            IF (v_dueqty < ((v_satisfiedqty + v_satisfiableqty))) THEN
              v_continue := -1;
              _rc := 1;
              RAISE EXCEPTION 'Unable to update Due satisfy status in sale detail for SaleInv: %. Reason satisfiable qty exceeds from satisfied qty for Itemcode: %', v_saleinvcode, v_icode;
            END IF;
          END IF;
          IF (v_continue >= 0) THEN
            SELECT r.return_value, r.avgprice INTO v_rt_code, v_hold_avgprice FROM dbo.sp_getitemavgprice(icode => v_icode, avgprice => v_hold_avgprice) AS r;
            IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
              v_continue := -1;
              _rc := 1;
            ELSE
              v_total_availablestock := (SELECT coalesce(sum(currqty), 0) FROM dbo.godowndetail WHERE (godowndetail.icode = v_icode));
              _rc := 1;
              IF ((v_total_availablestock < 0) OR (v_total_availablestock IS NULL)) THEN
                v_total_availablestock := 0;
                _rc := 1;
              END IF;
              v_givenqty := v_satisfiableqty;
              _rc := 1;
              v_totalqty := (SELECT coalesce(sum(currqty), 0) FROM dbo.godowndetail WHERE ((godowndetail.gcode = v_gcode) AND (godowndetail.icode = v_icode)));
              _rc := 1;
              IF (v_totalqty >= v_givenqty) THEN
                _rc := 0;
                FOR _r1 IN SELECT saleprice AS c1, packunits AS c2 FROM dbo.item WHERE (icode = v_icode) LOOP
                  _rc := _rc + 1;
                  v_saleprice := _r1.c1;
                  v_packunits := _r1.c2;
                END LOOP;
                IF ((v_packunits = 0) OR (v_packunits IS NULL)) THEN
                  v_packunits := 1;
                  _rc := 1;
                END IF;
                v_reqqty := v_givenqty;
                _rc := 1;
                OPEN cur_itembatch_cursor FOR SELECT batch, expiry, currqty FROM dbo.godowndetail WHERE ((godowndetail.gcode = v_gcode) AND (godowndetail.icode = v_icode)) ORDER BY priority, expiry, currqty;
                v_totalrows := (-1);
                _rc := 1;
                FETCH NEXT FROM cur_itembatch_cursor INTO v_batch, v_expiry, v_currqty;
                IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
                v_counter := 1;
                _rc := 1;
                WHILE (((_fs = 0) AND (v_counter <= v_totalrows)) AND (v_reqqty > 0)) LOOP
                  v_batchqty := v_currqty;
                  _rc := 1;
                  IF (v_batchqty >= v_reqqty) THEN
                    v_delqty := v_reqqty;
                    _rc := 1;
                  ELSE
                    v_delqty := v_batchqty;
                    _rc := 1;
                  END IF;
                  v_reqqty := (v_reqqty - v_delqty);
                  _rc := 1;
                  SELECT r.return_value, r.lbi_maxutn INTO v_rt_code, v_dueutn FROM dbo.sp_maxutn(lbi_rows => (1)::bigint, lbi_maxutn => v_dueutn) AS r;
                  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                    v_continue := -1;
                    _rc := 1;
                  END IF;
                  v_total_availablestock := (v_total_availablestock - v_delqty);
                  _rc := 1;
                  INSERT INTO dbo.duesatisfydetail (duesatisfycode, icode, gcode, batch, expiry, duesatisfyqty, avgprice, duesatisfyutn, packsaleprice, packunits, salerowid, balancestock) VALUES (v_duesatisfycode, v_icode, v_gcode, v_batch, v_expiry, v_delqty, v_hold_avgprice, v_dueutn, v_saleprice, v_packunits, v_salerowid, v_total_availablestock);
                  GET DIAGNOSTICS _rc = ROW_COUNT;
                  v_err := 0;
                  v_rowcount := _rc;
                  _rc := 1;
                  IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
                    RAISE EXCEPTION 'Error occured in inserting record into Due Sastisfy Detail for Due Satisfy Code : %', v_duesatisfycode;
                    v_continue := -1;
                    _rc := 1;
                  ELSE
                    v_newqty := (v_currqty - v_delqty);
                    _rc := 1;
                    IF (v_newqty > 0) THEN
                      SELECT r.return_value INTO v_rt_code FROM dbo.sp_saleupdateitemstockbatch(gcode => (v_gcode)::integer, icode => v_icode, batch => v_batch, expiry => v_expiry, newqty => v_newqty, oldqty => v_currqty) AS r;
                    ELSE
                      SELECT r.return_value INTO v_rt_code FROM dbo.sp_deleteitemstockbatch(gcode => (v_gcode)::integer, icode => v_icode, batch => v_batch, expiry => v_expiry, oldqty => v_delqty) AS r;
                    END IF;
                    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                      v_continue := -1;
                      _rc := 1;
                    END IF;
                  END IF;
                  v_counter := (v_counter + 1);
                  _rc := 1;
                  FETCH NEXT FROM cur_itembatch_cursor INTO v_batch, v_expiry, v_currqty;
                  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
                END LOOP;
                CLOSE cur_itembatch_cursor;
                -- DEALLOCATE ItemBatch_Cursor
              ELSE
                v_itemname := (SELECT name FROM dbo.item WHERE (icode = v_icode));
                _rc := 1;
                RAISE EXCEPTION 'Not enough stock for item (%) to decrease for Due Satisfy Code : %', v_itemname, v_duesatisfycode;
                v_continue := -1;
                _rc := 1;
              END IF;
            END IF;
          END IF;
        END IF;
        FETCH NEXT FROM cur_cursor_duesatisfyinvoice_items INTO v_icode, v_gcode, v_salerowid, v_satisfiableqty;
        IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
      END LOOP;
      CLOSE cur_cursor_duesatisfyinvoice_items;
      -- DEALLOCATE Cursor_DueSatisfyInvoice_Items
    END IF;
    FETCH NEXT FROM cur_cursor_duesatisfyinvoices INTO v_saleinvcode;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_cursor_duesatisfyinvoices;
  -- DEALLOCATE Cursor_DueSatisfyInvoices
  IF (v_continue >= 0) THEN
    OPEN cur_cursor_duedeleteinvoices FOR SELECT saleinvcode FROM dbo.dueadjdetail WHERE ((dueadjcode = v_dueadjcode) AND (duedelete = 'Y')) GROUP BY saleinvcode ORDER BY saleinvcode;
    FETCH NEXT FROM cur_cursor_duedeleteinvoices INTO v_saleinvcode;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    v_continue := 0;
    _rc := 1;
    WHILE ((_fs = 0) AND (v_continue >= 0)) LOOP
      SELECT r.return_value, r.key INTO v_rt_code, v_duesatisfycode FROM dbo.sp_gettabmaxkey(tabname => 'DueSatisfyHeader', key => v_duesatisfycode) AS r;
      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
        v_continue := -1;
        _rc := 1;
      ELSE
        INSERT INTO dbo.duesatisfyheader (duesatisfycode, saleinvcode, duesatisfydate, usercode, dueadjcode) VALUES (v_duesatisfycode, v_saleinvcode, v_serverdate, v_usercode, v_dueadjcode);
        GET DIAGNOSTICS _rc = ROW_COUNT;
        OPEN cur_cursor_duedeleteinvoice_items FOR SELECT icode, gcode, salerowid FROM dbo.dueadjdetail WHERE (((dueadjcode = v_dueadjcode) AND (saleinvcode = v_saleinvcode)) AND (duedelete = 'Y'));
        FETCH NEXT FROM cur_cursor_duedeleteinvoice_items INTO v_icode, v_gcode, v_salerowid;
        IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
        WHILE ((_fs = 0) AND (v_continue >= 0)) LOOP
          IF (dbo.fn_locksaledetailrow(v_saleinvcode, v_icode, v_salerowid) > 0) THEN
            v_satisfiedqty := dbo.fn_getitemduesatisfiedqty(v_saleinvcode, v_icode, v_salerowid);
            _rc := 1;
            v_dueqty := dbo.fn_getitemdueqty(v_saleinvcode, v_icode, v_salerowid);
            _rc := 1;
            IF (v_dueqty > v_satisfiedqty) THEN
              PERFORM dbo.sp_updatesaledetail(saleinvcode => v_saleinvcode, gcode => (v_gcode)::integer, icode => v_icode, due => 'X', salerowid => v_salerowid);
              IF (0 <> 0) THEN
                v_continue := -1;
                _rc := 1;
                RAISE EXCEPTION 'Unable to update Due delete status in sale detail for SaleInv: %', v_saleinvcode;
              END IF;
            ELSE
              v_continue := -1;
              _rc := 1;
              RAISE EXCEPTION 'Unable to update Due delete status in sale detail for SaleInv: % and Item code : %. Reason Due qty is already satisfied', v_saleinvcode, v_icode;
            END IF;
            IF (v_continue >= 0) THEN
              INSERT INTO dbo.duedeletedetail (duesatisfycode, icode, deletedqty, salerowid) VALUES (v_duesatisfycode, v_icode, ((v_dueqty - v_satisfiedqty)), v_salerowid);
              GET DIAGNOSTICS _rc = ROW_COUNT;
              v_err := 0;
              v_rowcount := _rc;
              _rc := 1;
              IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
                RAISE EXCEPTION 'Error occured in inserting record into Due Detail Detail for Due Delete Code : %', v_duesatisfycode;
                v_continue := -1;
                _rc := 1;
              END IF;
            END IF;
          END IF;
          FETCH NEXT FROM cur_cursor_duedeleteinvoice_items INTO v_icode, v_gcode, v_salerowid;
          IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
        END LOOP;
        CLOSE cur_cursor_duedeleteinvoice_items;
        -- DEALLOCATE Cursor_DueDeleteInvoice_Items
      END IF;
      FETCH NEXT FROM cur_cursor_duedeleteinvoices INTO v_saleinvcode;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    END LOOP;
    CLOSE cur_cursor_duedeleteinvoices;
    -- DEALLOCATE Cursor_DueDeleteInvoices
  END IF;
  return_value := v_continue;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_Select_Service ====
CREATE OR REPLACE FUNCTION dbo.sp_select_service(col citext, tablename citext, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_col citext;
  v_tablename citext;
  v_qry citext;
  v_columnname citext;
  _dq1 text;
BEGIN
  v_col := col;
  v_tablename := tablename;
  -- SET @columnname = (SELECT MAX(Name) FROM SysColumns WHERE ID IN (SELECT ID FROM SysObjects WHERE name=@tablename) AND Name = @col)
  RAISE EXCEPTION 'untranslated T-SQL (system table SysColumns)' USING ERRCODE = '0A000';
  IF (v_columnname IS NULL) THEN
    v_qry := 'SELECT '''' AS Mycolumn WHERE 1=2';
  ELSE
    v_qry := ((('SELECT DISTINCT mycolumn=' || v_col) || ' FROM ') || v_tablename);
  END IF;
  _dq1 := v_qry;
  IF _dq1 IS NOT NULL THEN
    IF _dq1 ~* '^[[:space:]]*select' THEN OPEN rs1 FOR EXECUTE dbo.tsql_dyn(_dq1); ELSE EXECUTE dbo.tsql_dyn(_dq1); END IF;
  END IF;
  return_value := 0;
  RETURN;
END
$body$;

