-- ==== proc SP_Set_DateTime_Preference ====
CREATE OR REPLACE FUNCTION dbo.sp_set_datetime_preference(prefname citext, prefvalue timestamp, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_prefname citext;
  v_prefvalue timestamp(3);
  v_retvalue integer;
  _rc integer;
BEGIN
  v_prefname := prefname;
  v_prefvalue := prefvalue;
  UPDATE dbo.softwarepreferences SET prefvalue = ltrim(rtrim(left(to_char(v_prefvalue, 'YYYY-MM-DD HH24:MI:SS'), 200))), prefvalue2 = ltrim(rtrim(left(to_char(v_prefvalue, 'YYYY-MM-DD HH24:MI:SS'), 200))) WHERE ((lower(name))::citext = (lower(v_prefname))::citext);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((_rc <> 0) AND (0 = 0)) THEN
    v_retvalue := 0;
    _rc := 1;
  ELSE
    v_retvalue := 1;
    _rc := 1;
  END IF;
  return_value := v_retvalue;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

