-- ==== proc sp_setDateForAutoSaleGen ====
CREATE OR REPLACE FUNCTION dbo.sp_setdateforautosalegen(startdate timestamp, enddate timestamp, sinvno integer, einvno integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_startdate timestamp(3);
  v_enddate timestamp(3);
  v_sinvno integer;
  v_einvno integer;
  v_noofdaysforsale integer;
  v_startday integer;
  v_selectedday integer;
  v_startrange integer;
  v_endrange integer;
  v_perdayinv integer;
BEGIN
  v_startdate := startdate;
  v_enddate := enddate;
  v_sinvno := sinvno;
  v_einvno := einvno;
  v_noofdaysforsale := (((v_enddate)::date - (v_startdate)::date) + 1);
  v_startday := 1;
  v_startrange := v_sinvno;
  v_perdayinv := (((v_einvno - v_sinvno)) / v_noofdaysforsale);
  WHILE ((v_startday <= v_noofdaysforsale)) LOOP
    v_endrange := (v_startrange + v_perdayinv);
    UPDATE dbo.saleledger SET originaldate = v_startdate, date = v_startdate, postdate = v_startdate, billingdate = v_startdate WHERE (saleinvcode BETWEEN v_startrange AND v_endrange);
    v_startrange := (v_endrange + 1);
    v_startday := (v_startday + 1);
    v_startdate := (v_startdate + (1) * interval '1 day');
  END LOOP;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_SetGLDetail ====
CREATE OR REPLACE FUNCTION dbo.sp_setgldetail(ai_glvochcode integer, ai_dr_acccode integer, ai_cr_acccode integer, an_amount numeric, as_chkno citext, as_remarks citext, ai_patientcode integer, ai_guestcode integer, ai_studentcode integer, ai_invoicecode integer, an_outstandingamt numeric, an_balance numeric, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_glvochcode integer;
  v_ai_dr_acccode integer;
  v_ai_cr_acccode integer;
  v_an_amount numeric(15,2);
  v_as_chkno citext;
  v_as_remarks citext;
  v_ai_patientcode integer;
  v_ai_guestcode integer;
  v_ai_studentcode integer;
  v_ai_invoicecode integer;
  v_an_outstandingamt numeric(15,2);
  v_an_balance numeric(15,2);
  v_err integer;
  v_rowcount integer;
  v_bal numeric(15,5);
  v_maxutn bigint;
  _rc integer;
BEGIN
  v_ai_glvochcode := ai_glvochcode;
  v_ai_dr_acccode := ai_dr_acccode;
  v_ai_cr_acccode := ai_cr_acccode;
  v_an_amount := an_amount;
  v_as_chkno := as_chkno;
  v_as_remarks := as_remarks;
  v_ai_patientcode := ai_patientcode;
  v_ai_guestcode := ai_guestcode;
  v_ai_studentcode := ai_studentcode;
  v_ai_invoicecode := ai_invoicecode;
  v_an_outstandingamt := an_outstandingamt;
  v_an_balance := an_balance;
  SELECT r.return_value, r.lbi_maxutn INTO v_err, v_maxutn FROM dbo.sp_maxutn(lbi_rows => (2)::bigint, lbi_maxutn => v_maxutn) AS r;
  IF ((v_err <> 0) AND (0 <> 0)) THEN
    return_value := -1;
    RETURN;
  END IF;
  v_bal := CASE WHEN (v_an_balance <> 0) THEN v_an_balance ELSE coalesce((SELECT sum((debit - credit)) FROM dbo.virtualgl WHERE (acccode = v_ai_dr_acccode)), 0) END;
  _rc := 1;
  INSERT INTO dbo.gldetail (glvochcode, acccode, debit, credit, chkno, remarks, glutn, patientcode, guestcode, studentcode, invoicecode, outstandingamt, balance) VALUES (v_ai_glvochcode, v_ai_dr_acccode, abs(v_an_amount), 0, v_as_chkno, v_as_remarks, v_maxutn, v_ai_patientcode, v_ai_guestcode, v_ai_studentcode, v_ai_invoicecode, v_an_outstandingamt, v_bal);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_err := 0;
  v_rowcount := _rc;
  _rc := 1;
  IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
    RAISE EXCEPTION 'Debit part of Voucher Insertion Failed in GLDetail';
    return_value := -1;
    RETURN;
  ELSE
    v_bal := CASE WHEN (v_an_balance <> 0) THEN v_an_balance ELSE coalesce((SELECT sum((debit - credit)) FROM dbo.virtualgl WHERE (acccode = v_ai_cr_acccode)), 0) END;
    _rc := 1;
    INSERT INTO dbo.gldetail (glvochcode, acccode, debit, credit, chkno, remarks, glutn, patientcode, guestcode, studentcode, invoicecode, outstandingamt, balance) VALUES (v_ai_glvochcode, v_ai_cr_acccode, 0, abs(v_an_amount), v_as_chkno, v_as_remarks, (v_maxutn + 1), v_ai_patientcode, v_ai_guestcode, v_ai_studentcode, v_ai_invoicecode, v_an_outstandingamt, v_bal);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_err := 0;
    v_rowcount := _rc;
    _rc := 1;
    IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
      RAISE EXCEPTION 'Credit part of Voucher Insertion Failed in GLDetail';
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_SetGLHeader ====
CREATE OR REPLACE FUNCTION dbo.sp_setglheader(ai_glvochcode integer, ai_vochcatcode integer, ai_acccode integer, ad_date timestamp, ai_salesmancode integer, as_posted citext, ad_postdate timestamp, as_remarks citext, ad_originaldate timestamp, ai_modifiedby integer, ai_postedby integer, as_chkno citext, ai_vouchercode integer, smancode smallint DEFAULT NULL, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_glvochcode integer;
  v_ai_vochcatcode integer;
  v_ai_acccode integer;
  v_ad_date timestamp(3);
  v_ai_salesmancode integer;
  v_as_posted citext;
  v_ad_postdate timestamp(3);
  v_as_remarks citext;
  v_ad_originaldate timestamp(3);
  v_ai_modifiedby integer;
  v_ai_postedby integer;
  v_as_chkno citext;
  v_ai_vouchercode integer;
  v_smancode smallint;
  v_err integer;
  v_rowcount integer;
  _rc integer;
BEGIN
  v_ai_glvochcode := ai_glvochcode;
  v_ai_vochcatcode := ai_vochcatcode;
  v_ai_acccode := ai_acccode;
  v_ad_date := ad_date;
  v_ai_salesmancode := ai_salesmancode;
  v_as_posted := as_posted;
  v_ad_postdate := ad_postdate;
  v_as_remarks := as_remarks;
  v_ad_originaldate := ad_originaldate;
  v_ai_modifiedby := ai_modifiedby;
  v_ai_postedby := ai_postedby;
  v_as_chkno := as_chkno;
  v_ai_vouchercode := ai_vouchercode;
  v_smancode := smancode;
  INSERT INTO dbo.glheader (glvochcode, vochcatcode, acccode, date, salesmancode, posted, postdate, remarks, originaldate, modifiedby, postedby, chkno, vouchercode, smancode) VALUES (v_ai_glvochcode, v_ai_vochcatcode, v_ai_acccode, v_ad_date, v_ai_salesmancode, v_as_posted, v_ad_postdate, v_as_remarks, v_ad_originaldate, v_ai_modifiedby, v_ai_postedby, v_as_chkno, v_ai_vouchercode, v_smancode);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_err := 0;
  v_rowcount := _rc;
  _rc := 1;
  IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
    RAISE EXCEPTION 'Exception occured in Creating Voucher in GLHeader';
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_SetItemActiveStatus ====
CREATE OR REPLACE FUNCTION dbo.sp_setitemactivestatus(icode integer, active smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_icode integer;
  v_active smallint;
  v_err integer;
  v_rowcount integer;
  _rc integer;
BEGIN
  v_icode := icode;
  v_active := active;
  IF (v_icode IS NULL) THEN
    RAISE EXCEPTION 'Unable to fetch Item Status, Not a Valid Item';
    return_value := -1;
    RETURN;
  END IF;
  IF (v_active IS NULL) THEN
    RAISE EXCEPTION 'Unable to Update Item Active Status Y/N for Item Code = %, Active status Can not be NULL', v_icode;
    return_value := -1;
    RETURN;
  ELSE
    UPDATE dbo.item SET active = v_active WHERE (icode = v_icode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_err := 0;
    v_rowcount := _rc;
    _rc := 1;
    IF ((v_err = 0) AND (v_rowcount = 1)) THEN
      return_value := 0;
      RETURN;
    ELSE
      RAISE EXCEPTION 'Unable to Update Item Active Status Y/N for Item Code = %', v_icode;
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_SetPreference ====
CREATE OR REPLACE FUNCTION dbo.sp_setpreference(prefname citext, prefvalue citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_prefname citext;
  v_prefvalue citext;
  v_retval integer;
  _rc integer;
BEGIN
  v_prefname := prefname;
  v_prefvalue := prefvalue;
  UPDATE dbo.softwarepreferences SET prefvalue = v_prefvalue, prefvalue2 = v_prefvalue WHERE ((lower(name))::citext = (lower(v_prefname))::citext);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((_rc <> 0) AND (0 = 0)) THEN
    v_retval := 0;
    _rc := 1;
  ELSE
    v_retval := 1;
    _rc := 1;
  END IF;
  return_value := v_retval;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_SetUserResponsibility_For_DataCarry ====
CREATE OR REPLACE FUNCTION dbo.sp_setuserresponsibility_for_datacarry(srv citext, db citext, owner citext, type citext, usercode smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_type citext;
  v_usercode smallint;
  v_ins citext;
  v_sql citext;
  v_qry citext;
  v_tablename citext;
  v_list citext;
  v_from citext;
  v_endd citext;
  v_con citext;
  v_notin citext;
  v_pkcond citext;
  v_whrtbm citext;
  v_full_table_name citext;
  v_colname citext;
  v_maxcol citext;
  v_tabmaxsql citext;
  v_priority smallint;
  v_keyseq smallint;
  v_table_id integer;
  v_err integer;
  v_updmaxkey citext;
  _dq1 text;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  v_type := type;
  v_usercode := usercode;
  -- SET NOCOUNT ON
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  v_full_table_name := 'DBO.Item';
  v_tablename := 'Item';
  v_from := ((((((' FROM ' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.');
  v_qry := (((((((('UPDATE ' || v_full_table_name) || ' SET UserCode = ') || ltrim(rtrim(dbo.tsql_str((v_usercode)::numeric, 10)))) || v_from) || v_tablename) || ' AS T, ') || v_full_table_name) || ' AS I WHERE T.ICode = I.ICode ');
  _dq1 := v_qry;
  IF _dq1 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq1);
  END IF;
  v_err := 0;
  IF (v_err <> 0) THEN
    RAISE EXCEPTION 'Data Updation: Problem Occurred While Assigning User Responsibility For Data Carry DB';
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_SetVoucherCategoryCounters ====
CREATE OR REPLACE FUNCTION dbo.sp_setvouchercategorycounters(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_catcount integer;
  v_counter integer;
BEGIN
  -- BEGIN TRANSACTION (the caller owns the transaction)
  v_catcount := (SELECT count(*) FROM dbo.vochercategory);
  v_counter := 1;
  WHILE (v_counter <= v_catcount) LOOP
    DROP TABLE IF EXISTS tmp_lt_table;
    CREATE TEMP TABLE tmp_lt_table (
    glvochcode integer NOT NULL,
    vouchercode integer GENERATED BY DEFAULT AS IDENTITY NOT NULL
) ON COMMIT DROP;
    INSERT INTO tmp_lt_table (glvochcode) SELECT glvochcode FROM dbo.glheader WHERE (vochcatcode = v_counter) ORDER BY glvochcode;
    UPDATE dbo.glheader AS glheader SET vouchercode = lt_table.vouchercode FROM tmp_lt_table AS lt_table WHERE (glheader.glvochcode = lt_table.glvochcode);
    DROP TABLE IF EXISTS tmp_lt_table;
    v_counter := (v_counter + 1);
  END LOOP;
  UPDATE dbo.vochercategory SET counter = coalesce((SELECT coalesce(max(vouchercode), 0) FROM dbo.glheader WHERE (glheader.vochcatcode = vochercategory.vochcatcode)), 0);
  -- COMMIT (the caller owns the transaction)
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_SetVoucherCode_Notes ====
CREATE OR REPLACE FUNCTION dbo.sp_setvouchercode_notes(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_catcount integer;
  v_counter integer;
BEGIN
  -- BEGIN TRANSACTION (the caller owns the transaction)
  v_catcount := (SELECT count(*) FROM dbo.notescategory);
  v_counter := 1;
  WHILE (v_counter <= v_catcount) LOOP
    DROP TABLE IF EXISTS tmp_lt_table;
    CREATE TEMP TABLE tmp_lt_table (
    notecode integer NOT NULL,
    vouchercode integer GENERATED BY DEFAULT AS IDENTITY NOT NULL
) ON COMMIT DROP;
    INSERT INTO tmp_lt_table (notecode) SELECT notecode FROM dbo.notes WHERE (notecatcode = v_counter) ORDER BY notecode;
    UPDATE dbo.notes AS notes SET vouchercode = lt_table.vouchercode FROM tmp_lt_table AS lt_table WHERE (notes.notecode = lt_table.notecode);
    DROP TABLE IF EXISTS tmp_lt_table;
    v_counter := (v_counter + 1);
  END LOOP;
  UPDATE dbo.notescategory SET counter = coalesce((SELECT coalesce(max(vouchercode), 0) FROM dbo.notes WHERE (notes.notecatcode = notescategory.notecatcode)), 0);
  -- COMMIT (the caller owns the transaction)
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_SingleCustomerBalance ====
CREATE OR REPLACE FUNCTION dbo.sp_singlecustomerbalance(ai_custcode smallint, INOUT af_balance double precision, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_custcode smallint;
  v_af_balance double precision;
BEGIN
  v_ai_custcode := ai_custcode;
  v_af_balance := af_balance;
  DROP TABLE IF EXISTS tmp_lt_pvamts;
  CREATE TEMP TABLE tmp_lt_pvamts (
    custcode numeric(5,0) NOT NULL,
    debit numeric(15,2) NOT NULL,
    credit numeric(15,2) NOT NULL
) ON COMMIT DROP;
  DELETE FROM dbo.reportdata;
  INSERT INTO tmp_lt_pvamts SELECT saleledger.custcode, coalesce((round((((sum((((saledetail.looseqty + saledetail.bonusqty)) * saledetail.unitsalestax)) + sum(round(((((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc))))) * saledetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc)))))) * ((1 - ((.01 * saleledger.discperc))))) - saleledger.flatdisc)) * ((saleledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) + round((((((sum((((saledetail.looseqty * ((saledetail.saleprice - saledetail.itemflatdisc)))) * ((1 - ((.01 * saledetail.discperc)))))) * ((1 - ((.01 * saleledger.discperc))))) + saleledger.misccharges) + saleledger.salestax) - saleledger.flatdisc))::numeric, 0)), 0) AS debit, 0.0 AS credit FROM dbo.saleledger, dbo.saledetail WHERE ((((saleledger.saleinvcode = saledetail.saleinvcode) AND (saleledger.salecatcode = 2)) AND (saleledger.posted = 'Y')) AND (saleledger.custcode = v_ai_custcode)) GROUP BY saleledger.saleinvcode, salecatcode, saleledger.date, saleledger.discperc, saleledger.misccharges, saleledger.salestax, saleledger.flatdisc, saleledger.invgstperc1, saleledger.custcode;
  INSERT INTO tmp_lt_pvamts SELECT srledger.custcode, 0 AS debit, coalesce((round((((sum((((srdetail.looseqty + srdetail.bonusqty)) * srdetail.unitsalestax)) + sum(round(((((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc))))) * srdetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc)))))) * ((1 - ((.01 * srledger.discperc))))) - srledger.flatdisc)) * ((srledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) + round((((((sum((((srdetail.looseqty * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc)))))) * ((1 - ((.01 * srledger.discperc))))) + srledger.misccharges) + srledger.salestax) - srledger.flatdisc))::numeric, 0)), 0) AS credit FROM dbo.srledger, dbo.srdetail WHERE ((((srledger.srinvcode = srdetail.srinvcode) AND (srledger.srcatcode = 7)) AND (srledger.posted = 'Y')) AND (srledger.custcode = v_ai_custcode)) GROUP BY srledger.srinvcode, srcatcode, srledger.date, srledger.discperc, srledger.misccharges, srledger.salestax, srledger.flatdisc, srledger.invgstperc1, srledger.custcode;
  INSERT INTO tmp_lt_pvamts SELECT serviceheader.custcode, coalesce((((sum((coalesce(servicedetail.price, 0) * ((1 - ((.01 * servicedetail.discperc)))))) * ((1 - ((.01 * serviceheader.discperc))))) + serviceheader.misccharges) - serviceheader.flatdisc), 0) AS debit, 0.0 AS credit FROM dbo.serviceheader, dbo.servicedetail WHERE ((((serviceheader.serviceinvcode = servicedetail.serviceinvcode) AND (serviceheader.servicecatcode = 11)) AND (serviceheader.posted = 'Y')) AND (serviceheader.custcode = v_ai_custcode)) GROUP BY serviceheader.serviceinvcode, serviceheader.servicecatcode, serviceheader.date, serviceheader.discperc, serviceheader.misccharges, serviceheader.flatdisc, serviceheader.custcode;
  INSERT INTO tmp_lt_pvamts SELECT servicerheader.custcode, 0.0 AS debit, coalesce((((sum((coalesce(servicerdetail.serviceprice, 0) * ((1 - ((.01 * servicerdetail.discperc)))))) * ((1 - ((.01 * servicerheader.discperc))))) + servicerheader.misccharges) - servicerheader.flatdisc), 0) AS credit FROM dbo.servicerheader, dbo.servicerdetail WHERE ((((servicerheader.servicerinvcode = servicerdetail.servicerinvcode) AND (servicerheader.servicercatcode = 14)) AND (servicerheader.posted = 'Y')) AND (servicerheader.custcode = v_ai_custcode)) GROUP BY servicerheader.servicerinvcode, servicerheader.servicercatcode, servicerheader.date, servicerheader.discperc, servicerheader.misccharges, servicerheader.flatdisc, servicerheader.custcode;
  INSERT INTO tmp_lt_pvamts SELECT gldetail.acccode, CASE sum(round((gldetail.debit)::numeric, 0)) WHEN NULL THEN 0.0 ELSE sum(round((gldetail.debit)::numeric, 0)) END, CASE sum(round((gldetail.credit)::numeric, 0)) WHEN NULL THEN 0.0 ELSE sum(round((gldetail.credit)::numeric, 0)) END FROM dbo.glheader, dbo.gldetail WHERE (((glheader.posted = 'Y') AND (gldetail.acccode = v_ai_custcode)) AND (glheader.glvochcode = gldetail.glvochcode)) GROUP BY gldetail.acccode;
  INSERT INTO tmp_lt_pvamts SELECT notes.acccode, 0, coalesce(sum(notes.amount), 0) FROM dbo.notes WHERE (((notes.posted = 'Y') AND (notes.notecatcode = 1)) AND (notes.acccode = v_ai_custcode)) GROUP BY notes.acccode;
  v_af_balance := (SELECT (sum(lt_pvamts.debit) - sum(lt_pvamts.credit)) FROM tmp_lt_pvamts AS lt_pvamts);
  DROP TABLE IF EXISTS tmp_lt_pvamts;
  return_value := 0;
  af_balance := v_af_balance;
  RETURN;
END
$body$;

-- ==== proc sp_SLOpeningBalance ====
CREATE OR REPLACE FUNCTION dbo.sp_slopeningbalance(al_suppcode numeric, ad_edate timestamp, INOUT af_openbalance double precision, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_al_suppcode numeric(5,0);
  v_ad_edate timestamp(3);
  v_af_openbalance double precision;
  v_ln_openbalance numeric(12,2);
BEGIN
  v_al_suppcode := al_suppcode;
  v_ad_edate := ad_edate;
  v_af_openbalance := af_openbalance;
  DROP TABLE IF EXISTS tmp_lt_pvamts;
  CREATE TEMP TABLE tmp_lt_pvamts (
    debit numeric(15,2) NOT NULL,
    credit numeric(15,2) NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_pvamts SELECT 0.0 AS debit, coalesce((round((((((sum(((purdetail.packqty * purdetail.purprice) * ((1 - ((.01 * purdetail.discperc)))))) * ((1 - ((.01 * purledger.discperc))))) + purledger.misccharges) + purledger.salestax) - purledger.flatdisc))::numeric, 0) + round((((sum((((purdetail.packqty + purdetail.bonusqty)) * purdetail.unitsalestax)) + sum(round((((((purdetail.packqty * purdetail.purprice) * ((1 - ((.01 * purdetail.discperc))))) * purdetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((purdetail.packqty * purdetail.purprice)) * ((1 - ((.01 * purdetail.discperc)))))) * ((1 - ((.01 * purledger.discperc))))) - purledger.flatdisc)) * ((purledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0)), 0) AS credit FROM dbo.purledger, dbo.purdetail WHERE (((((purledger.purcatcode IN (2, 1)) AND (purledger.date <= v_ad_edate)) AND (purledger.posted = 'Y')) AND (purledger.suppcode = v_al_suppcode)) AND (purledger.purinvcode = purdetail.purinvcode)) GROUP BY purledger.purinvcode, purledger.purcatcode, purledger.date, purledger.discperc, purledger.misccharges, purledger.salestax, purledger.invgstperc1, purledger.flatdisc;
  INSERT INTO tmp_lt_pvamts SELECT 0.0 AS debit, coalesce((round((((((sum((((purdetail.looseqty * purdetail.purprice)) * ((1 - ((.01 * purdetail.discperc)))))) * ((1 - ((.01 * purledger.discperc))))) + purledger.misccharges) + purledger.salestax) - purledger.flatdisc))::numeric, 0) + round((((sum((((purdetail.looseqty + purdetail.bonusqty)) * purdetail.unitsalestax)) + sum(round((((((purdetail.looseqty * purdetail.purprice) * ((1 - ((.01 * purdetail.discperc))))) * purdetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((purdetail.looseqty * purdetail.purprice)) * ((1 - ((.01 * purdetail.discperc)))))) * ((1 - ((.01 * purledger.discperc))))) - purledger.flatdisc)) * ((purledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0)), 0) AS credit FROM dbo.purledger, dbo.purdetail WHERE (((((purledger.purcatcode IN (8, 7)) AND (purledger.date <= v_ad_edate)) AND (purledger.posted = 'Y')) AND (purledger.suppcode = v_al_suppcode)) AND (purledger.purinvcode = purdetail.purinvcode)) GROUP BY purledger.purinvcode, purledger.purcatcode, purledger.date, purledger.discperc, purledger.misccharges, purledger.salestax, purledger.invgstperc1, purledger.flatdisc;
  INSERT INTO tmp_lt_pvamts SELECT coalesce((round((((((sum((((prdetail.looseqty * prdetail.prprice)) * ((1 - ((.01 * prdetail.discperc)))))) * ((1 - ((.01 * prledger.discperc))))) + prledger.misccharges) + prledger.salestax) - prledger.flatdisc))::numeric, 0) + round((((sum((((prdetail.looseqty + prdetail.bonusqty)) * prdetail.unitsalestax)) + sum(round((((((prdetail.looseqty * prdetail.prprice) * ((1 - ((.01 * prdetail.discperc))))) * prdetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((prdetail.looseqty * prdetail.prprice)) * ((1 - ((.01 * prdetail.discperc)))))) * ((1 - ((.01 * prledger.discperc))))) - prledger.flatdisc)) * ((prledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0)), 0) AS debit, 0.0 AS credit FROM dbo.prledger, dbo.prdetail WHERE (((((prledger.prcatcode IN (5, 4)) AND (prledger.date <= v_ad_edate)) AND (prledger.posted = 'Y')) AND (prledger.suppcode = v_al_suppcode)) AND (prledger.prinvcode = prdetail.prinvcode)) GROUP BY prledger.prinvcode, prledger.prcatcode, prledger.date, prledger.discperc, prledger.misccharges, prledger.salestax, prledger.invgstperc1, prledger.flatdisc;
  INSERT INTO tmp_lt_pvamts SELECT CASE sum(gldetail.debit) WHEN NULL THEN 0.0 ELSE sum(gldetail.debit) END, CASE sum(gldetail.credit) WHEN NULL THEN 0.0 ELSE sum(gldetail.credit) END FROM dbo.glheader, dbo.gldetail WHERE ((((glheader.glvochcode = gldetail.glvochcode) AND (glheader.date <= v_ad_edate)) AND (glheader.posted = 'Y')) AND (gldetail.acccode = v_al_suppcode));
  INSERT INTO tmp_lt_pvamts SELECT coalesce(sum(notes.amount), 0), 0 FROM dbo.notes WHERE ((((notes.notecatcode = 2) AND (notes.posted = 'Y')) AND (notes.postdate <= v_ad_edate)) AND (notes.acccode = v_al_suppcode));
  v_ln_openbalance := (SELECT (sum(debit) - sum(credit)) FROM tmp_lt_pvamts AS lt_pvamts);
  v_af_openbalance := (SELECT (v_ln_openbalance)::double precision);
  DROP TABLE IF EXISTS tmp_lt_pvamts;
  return_value := 0;
  af_openbalance := v_af_openbalance;
  RETURN;
END
$body$;

