-- ==== proc sp_stock_inout ====
CREATE OR REPLACE FUNCTION dbo.sp_stock_inout(s_date timestamp, l_date timestamp, l_code integer, ls_grouping citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_s_date timestamp(3);
  v_l_date timestamp(3);
  v_l_code integer;
  v_ls_grouping citext;
BEGIN
  v_s_date := s_date;
  v_l_date := l_date;
  v_l_code := l_code;
  v_ls_grouping := ls_grouping;
  DROP TABLE IF EXISTS tmp_lt_test;
  CREATE TEMP TABLE tmp_lt_test (
    test numeric(5,0) NOT NULL
) ON COMMIT DROP;
  DELETE FROM dbo.reportdata;
  INSERT INTO dbo.reportdata (code1, value1, value2, value3, value4, value5, value6, value7, value8, value9, value10, value11) SELECT a.icode, round(((a.saleprice / a.packunits))::numeric, 2) AS saleprice, round(((a.purprice / a.packunits))::numeric, 2) AS purprice, coalesce((SELECT sum(saledetail.looseqty) FROM dbo.saledetail, dbo.saleledger WHERE ((((saleledger.date BETWEEN v_s_date AND v_l_date) AND (saleledger.saleinvcode = saledetail.saleinvcode)) AND (saledetail.due IS NULL)) AND (saledetail.icode = a.icode))), 0) AS saleqty, coalesce((SELECT sum(srdetail.looseqty) FROM dbo.srdetail, dbo.srledger WHERE (((srledger.date BETWEEN v_s_date AND v_l_date) AND (srledger.srinvcode = srdetail.srinvcode)) AND (srdetail.icode = a.icode))), 0) AS saleretqty, coalesce((SELECT sum(CASE WHEN (purledger.purcatcode IN (3, 7, 8)) THEN (purdetail.looseqty + purdetail.bonusqty) ELSE (((purdetail.packqty + purdetail.bonusqty)) * purdetail.packunits) END) FROM dbo.purdetail, dbo.purledger WHERE ((((purledger.postdate BETWEEN v_s_date AND v_l_date) AND (purledger.posted = 'Y')) AND (purledger.purinvcode = purdetail.purinvcode)) AND (purdetail.icode = a.icode))), 0) AS purqty, coalesce((SELECT sum((prdetail.looseqty + prdetail.bonusqty)) FROM dbo.prdetail, dbo.prledger WHERE (((prledger.date BETWEEN v_s_date AND v_l_date) AND (prledger.prinvcode = prdetail.prinvcode)) AND (prdetail.icode = a.icode))), 0) AS prqtu, coalesce((SELECT sum(adjdetail.looseqty) FROM dbo.adjdetail, dbo.adjheader WHERE ((((adjheader.adjcatcode = 1) AND (adjheader.date BETWEEN v_s_date AND v_l_date)) AND (adjheader.adjcode = adjdetail.adjcode)) AND (adjdetail.icode = a.icode))), 0) AS adj, coalesce((SELECT sum(adjdetail.looseqty) FROM dbo.adjdetail, dbo.adjheader WHERE ((((adjheader.adjcatcode = 2) AND (adjheader.date BETWEEN v_s_date AND v_l_date)) AND (adjheader.adjcode = adjdetail.adjcode)) AND (adjdetail.icode = a.icode))), 0) AS adjdec, coalesce((SELECT sum(issuedetail.qty) FROM dbo.issuedetail, dbo.issueheader WHERE (((issueheader.date BETWEEN v_s_date AND v_l_date) AND (issueheader.issueinvcode = issuedetail.issueinvcode)) AND (issuedetail.icode = a.icode))), 0) AS issue, coalesce((SELECT sum(receiptdetail.qty) FROM dbo.receiptdetail, dbo.receiptheader WHERE ((((receiptheader.date BETWEEN v_s_date AND v_l_date) AND (receiptheader.posted = 'Y')) AND (receiptheader.receiptinvcode = receiptdetail.receiptinvcode)) AND (receiptdetail.icode = a.icode))), 0) AS receipt, coalesce((SELECT sum(duesatisfydetail.duesatisfyqty) FROM dbo.duesatisfydetail, dbo.duesatisfyheader WHERE (((duesatisfyheader.duesatisfydate BETWEEN v_s_date AND v_l_date) AND (duesatisfyheader.duesatisfycode = duesatisfydetail.duesatisfycode)) AND (duesatisfydetail.icode = a.icode))), 0) AS duesatisfy FROM dbo.item AS a WHERE ((a.active = 1) AND ((CASE v_ls_grouping WHEN 'M' THEN a.manfcode WHEN 'C' THEN a.icatcode WHEN 'L' THEN a.iccode WHEN 'P' THEN a.packcode END) = v_l_code));
  DROP TABLE IF EXISTS tmp_lt_test;
  return_value := 0;
  RETURN;
END
$body$;

