-- ==== proc SP_STOCKLEDGER ====
CREATE OR REPLACE FUNCTION dbo.sp_stockledger(OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
BEGIN
  OPEN rs1 FOR SELECT count(*) FROM dbo.stockledger;
  INSERT INTO dbo.stockledger (documentcode, date, documenttype, icode, gcode, batch, expiry, qty, bonus, packunits, rate, discperc, invdiscperc, stock, avgprice, newstock, newavgprice, utn, due) SELECT pl.purinvcode AS documentcode, pl.postdate AS date, 'PV' AS documenttype, pd.icode, pd.gcode, pd.batch, pd.expiry, coalesce(CASE pl.purcatcode WHEN 1 THEN (packqty * packunits) WHEN 2 THEN (packqty * packunits) ELSE looseqty END, 0) AS qty, coalesce(CASE pl.purcatcode WHEN 1 THEN (bonusqty * packunits) WHEN 2 THEN (bonusqty * packunits) ELSE bonusqty END, 0) AS bonus, pd.packunits, pd.purprice AS rate, pd.discperc, pl.discperc AS invdiscperc, coalesce(pd.currstock, 0) AS stock, coalesce(pd.avgprice, 0) AS avgprice, ((coalesce(pd.currstock, 0) + coalesce(CASE pl.purcatcode WHEN 1 THEN (packqty * packunits) WHEN 2 THEN (packqty * packunits) ELSE looseqty END, 0)) + coalesce(CASE pl.purcatcode WHEN 1 THEN (bonusqty * packunits) WHEN 2 THEN (bonusqty * packunits) ELSE bonusqty END, 0)) AS newstock, coalesce(pd.newavgprice, 0) AS newavgprice, pd.purutn AS utn, NULL::citext AS due FROM dbo.purledger AS pl, dbo.purdetail AS pd WHERE (((pl.posted = 'Y') AND (pl.purinvcode = pd.purinvcode)) AND (NOT EXISTS (SELECT st.utn AS purutn FROM dbo.stockledger AS st WHERE ((st.documenttype = 'PV') AND (pd.purutn = st.utn)))));
  INSERT INTO dbo.stockledger (documentcode, date, documenttype, icode, gcode, batch, expiry, qty, bonus, packunits, rate, discperc, invdiscperc, stock, avgprice, newstock, newavgprice, utn, due) SELECT pl.prinvcode AS documentcode, pl.date AS date, 'PR' AS documenttype, pd.icode, pd.gcode, pd.batch, pd.expiry, (pd.looseqty + (pd.packqty * pd.packunits)) AS qty, pd.bonusqty AS bonus, pd.packunits, pd.prprice AS rate, pd.discperc, pl.discperc AS invdiscperc, coalesce(((pd.balancestock + ((pd.looseqty + bonusqty))) + ((pd.packqty * pd.packunits))), 0) AS stock, coalesce(pd.avgprice, 0) AS avgprice, coalesce(pd.balancestock, 0) AS newstock, coalesce(pd.avgprice, 0) AS newavgprice, pd.prutn AS utn, NULL::citext AS due FROM dbo.prledger AS pl, dbo.prdetail AS pd WHERE (((pl.posted = 'Y') AND (pl.prinvcode = pd.prinvcode)) AND (NOT EXISTS (SELECT st.utn AS prutn FROM dbo.stockledger AS st WHERE ((st.documenttype = 'PR') AND (pd.prutn = st.utn)))));
  INSERT INTO dbo.stockledger (documentcode, date, documenttype, icode, gcode, batch, expiry, qty, bonus, packunits, rate, discperc, invdiscperc, stock, avgprice, newstock, newavgprice, utn, due) SELECT sl.saleinvcode AS documentcode, sl.date AS date, 'SV' AS documenttype, sd.icode, sd.gcode, sd.batch, sd.expiry, (sd.looseqty + ((sd.packqty * sd.packunits))) AS qty, sd.bonusqty AS bonus, sd.packunits, sd.saleprice AS rate, sd.discperc AS discperc, sl.discperc AS invdiscperc, coalesce(CASE WHEN (sd.due IS NULL) THEN ((sd.balancestock + sd.looseqty) + sd.bonusqty) ELSE sd.balancestock END, 0) AS stock, sd.avgprice, coalesce(sd.balancestock, 0) AS newstock, sd.avgprice AS newavgprice, sd.saleutn AS utn, sd.due AS due FROM dbo.saleledger AS sl, dbo.saledetail AS sd WHERE (((sl.posted = 'Y') AND (sl.saleinvcode = sd.saleinvcode)) AND (NOT EXISTS (SELECT st.utn AS saleutn FROM dbo.stockledger AS st WHERE ((st.documenttype = 'SV') AND (sd.saleutn = st.utn)))));
  INSERT INTO dbo.stockledger (documentcode, date, documenttype, icode, gcode, batch, expiry, qty, bonus, packunits, rate, discperc, invdiscperc, stock, avgprice, newstock, newavgprice, utn, due) SELECT sl.srinvcode AS documentcode, sl.postdate AS date, 'SR' AS documenttype, sd.icode, sd.gcode, sd.batch, sd.expiry, (sd.looseqty + (sd.packqty * sd.packunits)) AS qty, sd.bonusqty AS bonus, sd.packunits, sd.srprice AS rate, sd.discperc AS discperc, sl.discperc AS invdiscperc, coalesce(sd.currstock, 0) AS stock, sd.avgprice, coalesce((((sd.currstock + sd.looseqty) + sd.bonusqty) + ((sd.packqty * sd.packunits))), 0) AS newstock, sd.newavgprice AS newavgprice, sd.srutn AS utn, NULL::citext AS due FROM dbo.srledger AS sl, dbo.srdetail AS sd WHERE (((sl.posted = 'Y') AND (sl.srinvcode = sd.srinvcode)) AND (NOT EXISTS (SELECT st.utn AS srutn FROM dbo.stockledger AS st WHERE ((st.documenttype = 'SR') AND (sd.srutn = st.utn)))));
  INSERT INTO dbo.stockledger (documentcode, date, documenttype, icode, gcode, batch, expiry, qty, bonus, packunits, rate, discperc, invdiscperc, stock, avgprice, newstock, newavgprice, utn, due) SELECT rh.receiptinvcode AS documentcode, rh.postdate AS date, 'RV' AS documenttype, rd.icode, rd.gcode, rd.batch, rd.expiry, rd.qty AS qty, 0 AS bonus, rd.packunits, rd.price AS rate, 0 AS discperc, 0 AS invdiscperc, coalesce(rd.currstock, 0) AS stock, rd.avgprice AS avgprice, coalesce((rd.currstock + rd.qty), 0) AS newstock, rd.newavgprice AS newavgprice, rd.receiptutn AS utn, NULL::citext AS due FROM dbo.receiptheader AS rh, dbo.receiptdetail AS rd WHERE (((rh.posted = 'Y') AND (rh.receiptinvcode = rd.receiptinvcode)) AND (NOT EXISTS (SELECT st.utn AS receiptutn FROM dbo.stockledger AS st WHERE ((st.documenttype = 'RV') AND (rd.receiptutn = st.utn)))));
  INSERT INTO dbo.stockledger (documentcode, date, documenttype, icode, gcode, batch, expiry, qty, bonus, packunits, rate, discperc, invdiscperc, stock, avgprice, newstock, newavgprice, utn, due) SELECT ih.issueinvcode AS documentcode, ih.date AS date, 'IV' AS documenttype, isd.icode, isd.gcode, isd.batch, isd.expiry, isd.qty AS qty, 0 AS bonus, isd.packunits, isd.saleprice AS rate, 0 AS discperc, 0 AS invdiscperc, coalesce((isd.balancestock + isd.qty), 0) AS stock, isd.avgprice AS avgprice, coalesce(isd.balancestock, 0) AS newstock, isd.avgprice AS newavgprice, isd.issueutn AS utn, NULL::citext AS due FROM dbo.issueheader AS ih, dbo.issuedetail AS isd WHERE (((ih.posted = 'Y') AND (ih.issueinvcode = isd.issueinvcode)) AND (NOT EXISTS (SELECT st.utn AS issueutn FROM dbo.stockledger AS st WHERE ((st.documenttype = 'IV') AND (isd.issueutn = st.utn)))));
  INSERT INTO dbo.stockledger (documentcode, date, documenttype, icode, gcode, batch, expiry, qty, bonus, packunits, rate, discperc, invdiscperc, stock, avgprice, newstock, newavgprice, utn, due) SELECT ah.adjcode AS documentcode, ah.posteddate AS date, 'AI' AS documenttype, ad.icode, ad.gcode, ad.batch, ad.expiry, ad.looseqty AS qty, 0 AS bonus, ad.packunits, ad.price AS rate, 0 AS discperc, 0 AS invdiscperc, coalesce(ad.currstock, 0) AS stock, ad.avgprice AS avgprice, coalesce((ad.currstock + ad.looseqty), 0) AS newstock, ad.newavgprice AS newavgprice, ad.adjutn AS utn, NULL::citext AS due FROM dbo.adjheader AS ah, dbo.adjdetail AS ad WHERE ((((ah.adjcatcode = 1) AND (ah.posted = 'Y')) AND (ah.adjcode = ad.adjcode)) AND (NOT EXISTS (SELECT st.utn AS adjutn FROM dbo.stockledger AS st WHERE ((st.documenttype = 'AI') AND (ad.adjutn = st.utn)))));
  INSERT INTO dbo.stockledger (documentcode, date, documenttype, icode, gcode, batch, expiry, qty, bonus, packunits, rate, discperc, invdiscperc, stock, avgprice, newstock, newavgprice, utn, due) SELECT ah.adjcode AS documentcode, ah.posteddate AS date, 'AD' AS documenttype, ad.icode, ad.gcode, ad.batch, ad.expiry, ad.looseqty AS qty, 0 AS bonus, ad.packunits, ad.price AS rate, 0 AS discperc, 0 AS invdiscperc, coalesce(ad.currstock, 0) AS stock, ad.avgprice AS avgprice, coalesce((ad.currstock - ad.looseqty), 0) AS newstock, ad.avgprice AS newavgprice, ad.adjutn AS utn, NULL::citext AS due FROM dbo.adjheader AS ah, dbo.adjdetail AS ad WHERE ((((ah.adjcatcode = 2) AND (ah.posted = 'Y')) AND (ah.adjcode = ad.adjcode)) AND (NOT EXISTS (SELECT st.utn AS adjutn FROM dbo.stockledger AS st WHERE ((st.documenttype = 'AD') AND (ad.adjutn = st.utn)))));
  INSERT INTO dbo.stockledger (documentcode, date, documenttype, icode, gcode, batch, expiry, qty, bonus, packunits, rate, discperc, invdiscperc, stock, avgprice, newstock, newavgprice, utn, due) SELECT dh.duesatisfycode AS documentcode, dh.duesatisfydate AS date, 'DS' AS documenttype, dsd.icode, dsd.gcode, dsd.batch, dsd.expiry, dsd.duesatisfyqty AS qty, 0 AS bonus, 1 AS packunits, 0 AS rate, 0 AS discperc, 0 AS invdiscperc, coalesce((dsd.balancestock + dsd.duesatisfyqty), 0) AS stock, dsd.avgprice AS avgprice, coalesce(dsd.balancestock, 0) AS newstock, dsd.avgprice AS newavgprice, dsd.duesatisfyutn AS utn, NULL::citext AS due FROM dbo.duesatisfyheader AS dh, dbo.duesatisfydetail AS dsd WHERE ((dh.duesatisfycode = dsd.duesatisfycode) AND (NOT EXISTS (SELECT st.utn AS duesatisfyutn FROM dbo.stockledger AS st WHERE ((st.documenttype = 'DS') AND (dsd.duesatisfyutn = st.utn)))));
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_stockmovementcatwise ====
CREATE OR REPLACE FUNCTION dbo.sp_stockmovementcatwise(s_date timestamp, l_date timestamp, l_catcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_s_date timestamp(3);
  v_l_date timestamp(3);
  v_l_catcode integer;
BEGIN
  v_s_date := s_date;
  v_l_date := l_date;
  v_l_catcode := l_catcode;
  DROP TABLE IF EXISTS tmp_lt_test;
  CREATE TEMP TABLE tmp_lt_test (
    test numeric(5,0) NOT NULL
) ON COMMIT DROP;
  DELETE FROM dbo.reportdata;
  INSERT INTO dbo.reportdata (code1, value1, value2, value3, value4, value5, value6, value7, value8) SELECT a.icode, round(((a.saleprice / a.packunits))::numeric, 2) AS saleprice, round(((a.purprice / a.packunits))::numeric, 2) AS purprice, coalesce((coalesce((SELECT sum(saledetail.looseqty) FROM dbo.saledetail, dbo.saleledger WHERE ((((saleledger.date BETWEEN v_s_date AND v_l_date) AND (saleledger.saleinvcode = saledetail.saleinvcode)) AND (saledetail.due IS NULL)) AND (saledetail.icode = a.icode))), 0) + coalesce((SELECT sum(duesatisfydetail.duesatisfyqty) FROM dbo.duesatisfydetail, dbo.duesatisfyheader WHERE (((duesatisfyheader.duesatisfydate BETWEEN v_s_date AND v_l_date) AND (duesatisfyheader.duesatisfycode = duesatisfydetail.duesatisfycode)) AND (duesatisfydetail.icode = a.icode))), 0)), 0) AS saleqty, coalesce((SELECT sum(srdetail.looseqty) FROM dbo.srdetail, dbo.srledger WHERE (((srledger.date BETWEEN v_s_date AND v_l_date) AND (srledger.srinvcode = srdetail.srinvcode)) AND (srdetail.icode = a.icode))), 0) AS saleretqty, coalesce((SELECT sum(CASE WHEN (purledger.purcatcode IN (3, 7, 8)) THEN (purdetail.looseqty + purdetail.bonusqty) ELSE (((purdetail.packqty + purdetail.bonusqty)) * purdetail.packunits) END) FROM dbo.purdetail, dbo.purledger WHERE ((((purledger.postdate BETWEEN v_s_date AND v_l_date) AND (purledger.posted = 'Y')) AND (purledger.purinvcode = purdetail.purinvcode)) AND (purdetail.icode = a.icode))), 0) AS purqty, coalesce((SELECT sum((prdetail.looseqty + prdetail.bonusqty)) FROM dbo.prdetail, dbo.prledger WHERE (((prledger.date BETWEEN v_s_date AND v_l_date) AND (prledger.prinvcode = prdetail.prinvcode)) AND (prdetail.icode = a.icode))), 0) AS prqtu, coalesce((SELECT sum(CASE WHEN (adjheader.adjcatcode = 1) THEN adjdetail.looseqty ELSE ((-1) * adjdetail.looseqty) END) FROM dbo.adjdetail, dbo.adjheader WHERE (((adjheader.date BETWEEN v_s_date AND v_l_date) AND (adjheader.adjcode = adjdetail.adjcode)) AND (adjdetail.icode = a.icode))), 0) AS adj, (coalesce((SELECT sum(issuedetail.qty) FROM dbo.issuedetail, dbo.issueheader WHERE (((issueheader.date BETWEEN v_s_date AND v_l_date) AND (issueheader.issueinvcode = issuedetail.issueinvcode)) AND (issuedetail.icode = a.icode))), 0) - coalesce((SELECT sum(receiptdetail.qty) FROM dbo.receiptdetail, dbo.receiptheader WHERE ((((receiptheader.date BETWEEN v_s_date AND v_l_date) AND (receiptheader.posted = 'Y')) AND (receiptheader.receiptinvcode = receiptdetail.receiptinvcode)) AND (receiptdetail.icode = a.icode))), 0)) AS issue FROM dbo.item AS a WHERE ((a.icatcode = v_l_catcode) AND (a.active = 1));
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_stockmovementclasswise ====
CREATE OR REPLACE FUNCTION dbo.sp_stockmovementclasswise(s_date timestamp, l_date timestamp, l_iccode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_s_date timestamp(3);
  v_l_date timestamp(3);
  v_l_iccode integer;
BEGIN
  v_s_date := s_date;
  v_l_date := l_date;
  v_l_iccode := l_iccode;
  DELETE FROM dbo.reportdata;
  INSERT INTO dbo.reportdata (code1, value1, value2, value3, value4, value5, value6, value7, value8) SELECT a.icode, round(((a.saleprice / a.packunits))::numeric, 2) AS saleprice, round(((a.purprice / a.packunits))::numeric, 2) AS purprice, coalesce((coalesce((SELECT sum(saledetail.looseqty) FROM dbo.saledetail, dbo.saleledger WHERE ((((saleledger.date BETWEEN v_s_date AND v_l_date) AND (saleledger.saleinvcode = saledetail.saleinvcode)) AND (saledetail.due IS NULL)) AND (saledetail.icode = a.icode))), 0) + coalesce((SELECT sum(duesatisfydetail.duesatisfyqty) FROM dbo.duesatisfydetail, dbo.duesatisfyheader WHERE (((duesatisfyheader.duesatisfydate BETWEEN v_s_date AND v_l_date) AND (duesatisfyheader.duesatisfycode = duesatisfydetail.duesatisfycode)) AND (duesatisfydetail.icode = a.icode))), 0)), 0) AS saleqty, coalesce((SELECT sum(srdetail.looseqty) FROM dbo.srdetail, dbo.srledger WHERE (((srledger.date BETWEEN v_s_date AND v_l_date) AND (srledger.srinvcode = srdetail.srinvcode)) AND (srdetail.icode = a.icode))), 0) AS saleretqty, coalesce((SELECT sum(CASE WHEN (purledger.purcatcode IN (3, 7, 8)) THEN (purdetail.looseqty + purdetail.bonusqty) ELSE (((purdetail.packqty + purdetail.bonusqty)) * purdetail.packunits) END) FROM dbo.purdetail, dbo.purledger WHERE ((((purledger.postdate BETWEEN v_s_date AND v_l_date) AND (purledger.posted = 'Y')) AND (purledger.purinvcode = purdetail.purinvcode)) AND (purdetail.icode = a.icode))), 0) AS purqty, coalesce((SELECT sum((prdetail.looseqty + prdetail.bonusqty)) FROM dbo.prdetail, dbo.prledger WHERE (((prledger.date BETWEEN v_s_date AND v_l_date) AND (prledger.prinvcode = prdetail.prinvcode)) AND (prdetail.icode = a.icode))), 0) AS prqtu, coalesce((SELECT sum(CASE WHEN (adjheader.adjcatcode = 1) THEN adjdetail.looseqty ELSE ((-1) * adjdetail.looseqty) END) FROM dbo.adjdetail, dbo.adjheader WHERE (((adjheader.date BETWEEN v_s_date AND v_l_date) AND (adjheader.adjcode = adjdetail.adjcode)) AND (adjdetail.icode = a.icode))), 0) AS adj, (coalesce((SELECT sum(issuedetail.qty) FROM dbo.issuedetail, dbo.issueheader WHERE (((issueheader.date BETWEEN v_s_date AND v_l_date) AND (issueheader.issueinvcode = issuedetail.issueinvcode)) AND (issuedetail.icode = a.icode))), 0) - coalesce((SELECT sum(receiptdetail.qty) FROM dbo.receiptdetail, dbo.receiptheader WHERE ((((receiptheader.date BETWEEN v_s_date AND v_l_date) AND (receiptheader.posted = 'Y')) AND (receiptheader.receiptinvcode = receiptdetail.receiptinvcode)) AND (receiptdetail.icode = a.icode))), 0)) AS issue FROM dbo.item AS a WHERE ((a.iccode = v_l_iccode) AND (a.active = 1));
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_StockRegister ====
CREATE OR REPLACE FUNCTION dbo.sp_stockregister(OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
BEGIN
  OPEN rs1 FOR SELECT ('PV-' || rtrim(ltrim((pl.purinvcode)::text))) AS type, pl.postdate AS postdate, NULL AS due, pl.postdate AS date, u.username AS salesman, CASE WHEN ((((purcatcode = 1) OR (purcatcode = 2)) OR (purcatcode = 7)) OR (purcatcode = 8)) THEN (SELECT accounts.name FROM dbo.accounts WHERE (accounts.acccode = pl.suppcode)) ELSE 'Opening Purchase' END AS title, CASE WHEN (pl.purcatcode IN (3, 7, 8)) THEN ((pd.looseqty + ((pd.packqty * pd.packunits))) + pd.bonusqty) ELSE ((pd.looseqty + ((pd.packqty * pd.packunits))) + ((pd.bonusqty * pd.packunits))) END AS qtyin, 0 AS qtyout, pd.batch AS batch, pd.avgprice AS avgprice, 0 AS balqty, 0.00 AS rate, (SELECT item.name FROM dbo.item WHERE (icode = 5412)) AS itemname, 0 AS toutqty, pd.expiry AS expiry, '         ' AS reference, CASE WHEN (((purcatcode = 3) OR (purcatcode = 7)) OR (purcatcode = 8)) THEN pd.purprice ELSE (pd.purprice / pd.packunits) END AS price, pd.discperc AS discount FROM dbo.purledger AS pl, dbo.purdetail AS pd, dbo.users AS u WHERE ((((((pl.purinvcode = pd.purinvcode) AND (pd.icode = 5412)) AND (pd.gcode = 1)) AND (pl.postdate BETWEEN '1/1/2000' AND '10/10/2000')) AND (pl.posted = 'Y')) AND (pl.salesmancode = u.usercode)) UNION SELECT ('PR-' || rtrim(ltrim((pl.prinvcode)::text))) AS type, pl.date AS postdate, NULL AS due, pl.postdate AS date, u.username AS salesman, CASE WHEN ((prcatcode = 4) OR (prcatcode = 5)) THEN (SELECT accounts.name FROM dbo.accounts WHERE (accounts.acccode = pl.suppcode)) ELSE 'Opening Purchase Return' END AS title, 0 AS qtyin, ((pd.looseqty + ((pd.packqty * pd.packunits))) + pd.bonusqty) AS qtyout, pd.batch AS batch, pd.avgprice AS avgprice, 0 AS balqty, 0.00 AS rate, '                                        ' AS itemname, 0 AS toutqty, pd.expiry AS expiry, '          ' AS reference, pd.prprice AS price, pd.discperc AS discount FROM dbo.prledger AS pl, dbo.prdetail AS pd, dbo.users AS u WHERE ((((((pl.prinvcode = pd.prinvcode) AND (pd.icode = 5412)) AND (pd.gcode = 1)) AND (pl.postdate BETWEEN '1/1/2000' AND '10/10/2000')) AND (pl.posted = 'Y')) AND (pl.salesmancode = u.usercode)) UNION SELECT (CASE sl.srcatcode WHEN 8 THEN 'RR-' ELSE 'WR-' END || rtrim(ltrim((sl.srinvcode)::text))) AS type, sl.postdate AS postdate, NULL AS due, sl.postdate AS date, u.username AS salesman, CASE WHEN ((srcatcode = 6) OR (srcatcode = 7)) THEN (SELECT accounts.name FROM dbo.accounts WHERE (accounts.acccode = sl.custcode)) ELSE 'Retail Sale Return Cash' END AS title, sd.looseqty AS qtyin, 0 AS qtyout, sd.batch AS batch, sd.avgprice AS avgprice, 0 AS balqty, 0.00 AS rate, '                                        ' AS itemname, 0 AS toutqty, sd.expiry AS expiry, '                ' AS reference, sd.srprice AS price, sd.discperc AS discount FROM dbo.srledger AS sl, dbo.srdetail AS sd, dbo.users AS u WHERE ((((((sl.srinvcode = sd.srinvcode) AND (sd.icode = 5412)) AND (sd.gcode = 1)) AND (sl.postdate BETWEEN '1/1/2000' AND '10/10/2000')) AND (sl.posted = 'Y')) AND (sl.salesmancode = u.usercode)) UNION SELECT ('SN-' || rtrim(ltrim((duesatisfyheader.saleinvcode)::text))) AS type, duesatisfyheader.duesatisfydate AS postdate, 'A' AS due, duesatisfyheader.duesatisfydate AS date, u.username AS salesman, CASE WHEN (((SELECT sl.salecatcode FROM dbo.saleledger AS sl WHERE (sl.saleinvcode = duesatisfyheader.saleinvcode)) = 1) OR ((SELECT sl.salecatcode FROM dbo.saleledger AS sl WHERE (sl.saleinvcode = duesatisfyheader.saleinvcode)) = 2)) THEN (SELECT accounts.name FROM dbo.accounts, dbo.saleledger AS sl WHERE ((sl.saleinvcode = duesatisfyheader.saleinvcode) AND (accounts.acccode = sl.custcode))) ELSE 'Retail Sale Cash' END AS title, 0 AS qtyin, duesatisfydetail.duesatisfyqty AS qtyout, duesatisfydetail.batch AS batch, 0 AS avgprice, 0 AS balqty, 0.00 AS rate, '                                        ' AS itemname, 0 AS toutqty, duesatisfydetail.expiry AS expiry, '         ' AS reference, (SELECT saleprice FROM dbo.saledetail AS sd WHERE ((sd.saleinvcode = duesatisfyheader.saleinvcode) AND (sd.icode = 5412)) GROUP BY icode, saleprice) AS price, (SELECT discperc FROM dbo.saledetail AS sd WHERE ((sd.saleinvcode = duesatisfyheader.saleinvcode) AND (sd.icode = 5412)) GROUP BY icode, discperc) AS discount FROM dbo.duesatisfyheader, dbo.duesatisfydetail, dbo.users AS u WHERE (((((duesatisfyheader.duesatisfycode = duesatisfydetail.duesatisfycode) AND (duesatisfydetail.icode = 5412)) AND (duesatisfyheader.duesatisfydate BETWEEN '1/1/2000' AND '10/10/2000')) AND (duesatisfyheader.usercode = u.usercode)) AND (duesatisfydetail.gcode = 1)) UNION SELECT ('DN-' || rtrim(ltrim((duesatisfyheader.saleinvcode)::text))) AS type, duesatisfyheader.duesatisfydate AS postdate, 'B' AS due, duesatisfyheader.duesatisfydate AS date, u.username AS salesman, CASE WHEN (((SELECT sl.salecatcode FROM dbo.saleledger AS sl WHERE (sl.saleinvcode = duesatisfyheader.saleinvcode)) = 1) OR ((SELECT sl.salecatcode FROM dbo.saleledger AS sl WHERE (sl.saleinvcode = duesatisfyheader.saleinvcode)) = 2)) THEN (SELECT accounts.name FROM dbo.accounts, dbo.saleledger AS sl WHERE ((sl.saleinvcode = duesatisfyheader.saleinvcode) AND (accounts.acccode = sl.custcode))) ELSE 'Retail Sale Cash' END AS title, 0 AS qtyin, duedeletedetail.deletedqty AS qtyout, '' AS batch, 0 AS avgprice, 0 AS balqty, 0.00 AS rate, '                                        ' AS itemname, 0 AS toutqty, NULL AS expiry, '         ' AS reference, (SELECT saleprice FROM dbo.saledetail AS sd WHERE ((sd.saleinvcode = duesatisfyheader.saleinvcode) AND (sd.icode = 5412)) GROUP BY icode, saleprice) AS price, (SELECT discperc FROM dbo.saledetail AS sd WHERE ((sd.saleinvcode = duesatisfyheader.saleinvcode) AND (sd.icode = 5412)) GROUP BY icode, discperc) AS discount FROM dbo.duesatisfyheader, dbo.duedeletedetail, dbo.users AS u WHERE ((((duesatisfyheader.duesatisfycode = duedeletedetail.duesatisfycode) AND (duedeletedetail.icode = 5412)) AND (duesatisfyheader.duesatisfydate BETWEEN '1/1/2000' AND '10/10/2000')) AND (duesatisfyheader.usercode = u.usercode)) UNION SELECT ('AI-' || rtrim(ltrim((adjheader.adjcode)::text))) AS type, adjheader.posteddate AS postdate, 'z' AS due, adjheader.date AS date, u.username AS salesman, ('Stock Adjustment-' || CASE WHEN ((adjheader.adjcatcode = 1)) THEN 'Increase' ELSE 'Decrease' END) AS title, CASE WHEN ((adjheader.adjcatcode = 1)) THEN adjdetail.looseqty ELSE 0 END AS qtyin, CASE WHEN ((adjheader.adjcatcode = 1)) THEN 0 ELSE adjdetail.looseqty END AS qtyout, adjdetail.batch AS batch, 0 AS avprice, 0 AS balqty, 0.00 AS rate, '                                        ' AS itemname, 0 AS toutqty, adjdetail.expiry AS expiry, '         ' AS reference, 0 AS price, 0 AS discount FROM dbo.adjheader, dbo.adjdetail, dbo.users AS u WHERE ((((((adjheader.adjcode = adjdetail.adjcode) AND (adjdetail.gcode = 1)) AND (adjdetail.icode = 5412)) AND (adjheader.adjcatcode = 1)) AND (adjheader.posteddate BETWEEN '1/1/2000' AND '10/10/2000')) AND (adjheader.usercode = u.usercode)) UNION SELECT ('TO-' || rtrim(ltrim((theader.transcode)::text))) AS type, theader.postdate AS postdate, 'z' AS due, theader.date AS date, u.username AS salesman, CASE WHEN ((theader.sgcode = 1)) THEN 'Transfer Out' ELSE 'Transfer In' END AS title, CASE WHEN ((theader.sgcode = 1)) THEN 0 ELSE tdetail.qty END AS qtyin, CASE WHEN ((theader.dgcode = 1)) THEN tdetail.qty ELSE 0 END AS qtyout, tdetail.batch AS batch, 0 AS avgprice, 0 AS balqty, 0.00 AS rate, '                                        ' AS itemname, 0 AS toutqty, tdetail.expiry AS expiry, '         ' AS reference, 0 AS price, 0 AS discount FROM dbo.theader, dbo.tdetail, dbo.users AS u WHERE (((((theader.transcode = tdetail.transcode) AND (((theader.sgcode = 1) OR (theader.dgcode = 1)))) AND (tdetail.icode = 5412)) AND (theader.date BETWEEN '1/1/2000' AND '10/10/2000')) AND (theader.salesmancode = u.usercode)) UNION SELECT ('II-' || rtrim(ltrim((issueheader.issueinvcode)::text))) AS type, issueheader.postdate AS postdate, 'z' AS due, issueheader.date AS date, u.username AS salesman, 'Receipt' AS title, 0 AS qtyin, issuedetail.qty AS qtyout, issuedetail.batch AS batch, 0 AS avgprice, 0 AS balqty, 0.00 AS rate, '                                        ' AS itemname, 0 AS toutqty, issuedetail.expiry AS expiry, '         ' AS reference, issuedetail.saleprice AS price, 0 AS discount FROM dbo.issueheader, dbo.issuedetail, dbo.users AS u WHERE (((((issueheader.issueinvcode = issuedetail.issueinvcode) AND (issuedetail.icode = 5412)) AND (issuedetail.gcode = 1)) AND (issueheader.date BETWEEN '1/1/2000' AND '10/10/2000')) AND (issueheader.salesmancode = u.usercode)) UNION SELECT ('II-' || rtrim(ltrim((receiptheader.receiptinvcode)::text))) AS type, receiptheader.postdate AS postdate, 'z' AS due, receiptheader.date AS date, u.username AS salesman, 'Receipt' AS title, receiptdetail.qty AS qtyin, 0 AS qtyout, receiptdetail.batch AS batch, 0 AS avgprice, 0 AS balqty, 0.00 AS rate, '                                        ' AS itemname, 0 AS toutqty, receiptdetail.expiry AS expiry, '         ' AS reference, receiptdetail.saleprice AS price, 0 AS discount FROM dbo.receiptheader, dbo.receiptdetail, dbo.users AS u WHERE (((((receiptheader.receiptinvcode = receiptdetail.receiptinvcode) AND (receiptdetail.icode = 5412)) AND (receiptdetail.gcode = 1)) AND (receiptheader.postdate BETWEEN '1/1/2000' AND '10/10/2000')) AND (receiptheader.salesmancode = u.usercode)) UNION SELECT (CASE sl.salecatcode WHEN 1 THEN 'WS-' WHEN 2 THEN 'WS-' WHEN 3 THEN 'RS-' WHEN 4 THEN 'CS-' ELSE 'UK-' END || rtrim(ltrim((sl.saleinvcode)::text))) AS type, sl.postdate AS postdate, sd.due AS due, sl.date AS date, u.username AS salesman, CASE WHEN ((salecatcode = 1) OR (salecatcode = 2)) THEN (SELECT accounts.name FROM dbo.accounts WHERE (accounts.acccode = sl.custcode)) ELSE 'Retail Sale Cash' END AS title, 0 AS qtyin, sd.looseqty AS qtyout, sd.batch AS batch, sd.avgprice AS avgprice, 0 AS balqty, 0.00 AS rate, '                                        ' AS itemname, 0 AS toutqty, sd.expiry AS expiry, sl.custrefno AS reference, sd.saleprice AS price, sd.discperc AS discount FROM dbo.saleledger AS sl, dbo.saledetail AS sd, dbo.users AS u WHERE (((((sl.saleinvcode = sd.saleinvcode) AND (sd.icode = 5412)) AND (sd.gcode = 1)) AND (sl.date BETWEEN '1/1/2000' AND '10/10/2000')) AND (sl.salesmancode = u.usercode)) ORDER BY 4, 9, 15;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_StockReport ====
CREATE OR REPLACE FUNCTION dbo.sp_stockreport(dailyreportdays integer, archivereportdays integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_dailyreportdays integer;
  v_archivereportdays integer;
BEGIN
  v_dailyreportdays := dailyreportdays;
  v_archivereportdays := archivereportdays;
  INSERT INTO dbo.stockreport (date, gcode, icode, stock, purchaseprice, saleprice, avgprice, recentpurchaseprice, packunits) SELECT localtimestamp(3) AS date, gd.gcode AS gcode, gd.icode AS icode, sum(gd.currqty) AS stock, i.purprice AS purchaseprice, i.saleprice AS saleprice, i.avgprice AS avprice, i.recentpurprice AS recentpurchaseprice, i.packunits AS packunits FROM dbo.godowndetail AS gd, dbo.item AS i WHERE ((gd.icode = i.icode) AND ((left(to_char(localtimestamp(3), 'MM/DD/YYYY'), 100))::citext NOT IN (SELECT DISTINCT left(to_char(date, 'MM/DD/YYYY'), 100) FROM dbo.stockreport))) GROUP BY gd.gcode, gd.icode, i.purprice, i.saleprice, i.avgprice, i.recentpurprice, i.packunits;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_StudentOpeningBalance ====
CREATE OR REPLACE FUNCTION dbo.sp_studentopeningbalance(al_studentcode integer, ad_edate timestamp, INOUT af_openbalance numeric, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_al_studentcode integer;
  v_ad_edate timestamp(3);
  v_af_openbalance numeric(15,5);
BEGIN
  v_al_studentcode := al_studentcode;
  v_ad_edate := ad_edate;
  v_af_openbalance := af_openbalance;
  v_af_openbalance := coalesce((SELECT (sum(v.debit) - sum(v.credit)) FROM dbo.virtualgl AS v WHERE (((v.studentcode = v_al_studentcode) AND (v.acccode IN (SELECT custcode FROM dbo.student WHERE (studentcode = v_al_studentcode)))) AND (v.date < v_ad_edate))), 0);
  return_value := 0;
  af_openbalance := v_af_openbalance;
  RETURN;
END
$body$;

-- ==== proc SP_SUBAREASALES ====
CREATE OR REPLACE FUNCTION dbo.sp_subareasales(ar_startdate timestamp, ar_enddate timestamp, reportgrouping citext, grouplist citext, subarealist citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ar_startdate timestamp(3);
  v_ar_enddate timestamp(3);
  v_reportgrouping citext;
  v_grouplist citext;
  v_subarealist citext;
BEGIN
  v_ar_startdate := ar_startdate;
  v_ar_enddate := ar_enddate;
  v_reportgrouping := reportgrouping;
  v_grouplist := grouplist;
  v_subarealist := subarealist;
  DELETE FROM dbo.reportdata;
  DROP TABLE IF EXISTS tv_sp_subareasales_tab_grouplist;
  CREATE TEMP TABLE tv_sp_subareasales_tab_grouplist (
    code integer NOT NULL
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tv_sp_subareasales_tab_itemlist;
  CREATE TEMP TABLE tv_sp_subareasales_tab_itemlist (
    code integer NOT NULL
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tv_sp_subareasales_tab_subarealist;
  CREATE TEMP TABLE tv_sp_subareasales_tab_subarealist (
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tv_sp_subareasales_tab_grouplist SELECT code FROM dbo.udf_stringtotabl(v_grouplist, ',') AS udf_stringtotabl;
  INSERT INTO tv_sp_subareasales_tab_subarealist SELECT code FROM dbo.udf_stringtotabl(v_subarealist, ',') AS udf_stringtotabl;
  INSERT INTO tv_sp_subareasales_tab_itemlist SELECT code FROM dbo.udf_selectitems(v_reportgrouping, v_grouplist) AS udf_selectitems;
  INSERT INTO dbo.reportdata (code1, code2, code3, code4, name1, name2, name3, name4, name5, name6, name7, value1, value2) SELECT s.icode AS code1, s.subareacode AS code2, CASE v_reportgrouping WHEN 'M' THEN i.manfcode WHEN 'C' THEN i.icatcode WHEN 'L' THEN i.iccode ELSE i.packcode END AS code3, 0 AS code4, i.name AS name1, (SELECT subarea.name FROM dbo.subarea WHERE (subarea.subareacode = s.subareacode)) AS name2, CASE v_reportgrouping WHEN 'M' THEN (SELECT m.name FROM dbo.manufacturer AS m WHERE (m.manfcode = i.manfcode)) WHEN 'C' THEN (SELECT c.name FROM dbo.itemcategory AS c WHERE (c.icatcode = i.icatcode)) WHEN 'L' THEN (SELECT c.name FROM dbo.itemclass AS c WHERE (c.iccode = i.iccode)) ELSE (SELECT p.name FROM dbo.itempacking AS p WHERE (p.packcode = i.packcode)) END AS name3, i.customicode AS name4, i.packingdesc AS name5, rtrim(ltrim(dbo.tsql_str((s.icode)::numeric))) AS name6, '' AS name7, sum(qty) AS value1, round((sum(netamt))::numeric, 0) AS value2 FROM (SELECT -1 AS invno, i.icode AS icode, -1 AS custcode, 0 AS qty, 0 AS netamt, a.subareacode FROM (SELECT code AS subareacode FROM tv_sp_subareasales_tab_subarealist AS tab_subarealist) AS a, (SELECT min(code) AS icode FROM tv_sp_subareasales_tab_itemlist AS tab_itemlist) AS i UNION ALL SELECT -1 AS invno, i.icode AS icode, -1 AS custcode, 0 AS qty, 0 AS netamt, a.subareacode FROM (SELECT min(code) AS subareacode FROM tv_sp_subareasales_tab_subarealist AS tab_subarealist) AS a, (SELECT code AS icode FROM tv_sp_subareasales_tab_itemlist AS tab_itemlist) AS i UNION ALL SELECT sl.saleinvcode AS invno, sd.icode, sl.custcode AS custcode, coalesce(sum((sd.looseqty + sd.bonusqty)), 0) AS qty, round((coalesce((sum((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc)))) * ((1 - ((.01 * sd.discperc)))))) * ((1 - ((.01 * sl.discperc))))), 0))::numeric, 2) AS netamt, sa.subareacode FROM dbo.saleledger AS sl, dbo.saledetail AS sd, dbo.customer AS c, (SELECT code AS subareacode FROM tv_sp_subareasales_tab_subarealist AS tab_subarealist) AS sa WHERE ((((((c.subareacode = sa.subareacode) AND (c.custcode = sl.custcode)) AND (sl.posted = 'Y')) AND (sl.saleinvcode = sd.saleinvcode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) GROUP BY sl.saleinvcode, sd.icode, sl.custcode, sa.subareacode, sl.discperc UNION ALL SELECT sl.srinvcode AS invno, sd.icode, sl.custcode AS custcode, (-coalesce(sum((sd.looseqty + sd.bonusqty)), 0)) AS qty, (-round((coalesce((sum((((sd.looseqty * sd.srprice)) * ((1 - ((.01 * sd.discperc)))))) * ((1 - ((.01 * sl.discperc))))), 0))::numeric, 2)) AS netamt, sa.subareacode FROM dbo.srledger AS sl, dbo.srdetail AS sd, dbo.customer AS c, (SELECT code AS subareacode FROM tv_sp_subareasales_tab_subarealist AS tab_subarealist) AS sa WHERE ((((((sa.subareacode = c.subareacode) AND (c.custcode = sl.custcode)) AND (sl.posted = 'Y')) AND (sl.srinvcode = sd.srinvcode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) GROUP BY sl.srinvcode, sd.icode, sl.custcode, sa.subareacode, sl.discperc) AS s, dbo.item AS i WHERE ((s.icode = i.icode) AND (i.icode IN (SELECT code FROM tv_sp_subareasales_tab_itemlist AS tab_itemlist))) GROUP BY s.subareacode, s.icode, i.name, i.customicode, i.packingdesc, i.icatcode, i.iccode, i.manfcode, i.packcode;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_SUBAREASALES_CROSSTAB ====
CREATE OR REPLACE FUNCTION dbo.sp_subareasales_crosstab(startdate timestamp, enddate timestamp, reportgrouping citext, grouplist citext, pricetype smallint, totcol double precision, subarealist citext, onlysalearea citext, mergebonus smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_startdate timestamp(3);
  v_enddate timestamp(3);
  v_reportgrouping citext;
  v_grouplist citext;
  v_pricetype smallint;
  v_totcol double precision;
  v_subarealist citext;
  v_onlysalearea citext;
  v_mergebonus smallint;
  v_upd citext;
  v_col citext;
  v_rowid integer;
  v_colname citext;
  v_colcode citext;
  v_str_col citext;
  v_totareas double precision;
  v_curriter integer;
  v_iterations integer;
  v_i integer;
  v_tot integer;
  v_icode integer;
  v_subareacode integer;
  v_qty numeric(15,4);
  v_bonus numeric(15,4);
  v_val numeric(15,5);
  v_err integer;
  _dq1 text;
  cur_c1 refcursor;
  _dq2 text;
  _fs integer := -1;
BEGIN
  v_startdate := startdate;
  v_enddate := enddate;
  v_reportgrouping := reportgrouping;
  v_grouplist := grouplist;
  v_pricetype := pricetype;
  v_totcol := totcol;
  v_subarealist := subarealist;
  v_onlysalearea := onlysalearea;
  v_mergebonus := mergebonus;
  DELETE FROM dbo.crosstab_reportdata;
  -- SET NOCOUNT ON
  DROP TABLE IF EXISTS tv_sp_subareasales_crosstab_coltable;
  CREATE TEMP TABLE tv_sp_subareasales_crosstab_coltable (
    code integer,
    shortname citext,
    rowid integer GENERATED BY DEFAULT AS IDENTITY
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tv_sp_subareasales_crosstab_saleareastable;
  CREATE TEMP TABLE tv_sp_subareasales_crosstab_saleareastable (
    code integer
) ON COMMIT DROP;
  INSERT INTO tv_sp_subareasales_crosstab_saleareastable SELECT code FROM dbo.udf_stringtotabl(v_subarealist, ',') AS udf_stringtotabl;
  DROP TABLE IF EXISTS tv_sp_subareasales_crosstab_tab_grouplist;
  CREATE TEMP TABLE tv_sp_subareasales_crosstab_tab_grouplist (
    code integer NOT NULL
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tv_sp_subareasales_crosstab_tab_itemlist;
  CREATE TEMP TABLE tv_sp_subareasales_crosstab_tab_itemlist (
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tv_sp_subareasales_crosstab_tab_grouplist SELECT code FROM dbo.udf_stringtotabl(v_grouplist, ',') AS udf_stringtotabl;
  INSERT INTO tv_sp_subareasales_crosstab_tab_itemlist SELECT code FROM dbo.udf_selectitems(v_reportgrouping, v_grouplist) AS udf_selectitems;
  IF (v_onlysalearea = 'Y') THEN
    DELETE FROM tv_sp_subareasales_crosstab_saleareastable AS saleareastable WHERE (code NOT IN (SELECT DISTINCT (customer.subareacode) FROM dbo.saleledger, dbo.customer, dbo.item, dbo.saledetail WHERE (((((((posted = 'Y') AND (saleledger.date >= v_startdate)) AND (saleledger.date <= v_enddate)) AND (saleledger.custcode = customer.custcode)) AND (saleledger.saleinvcode = saledetail.saleinvcode)) AND (saledetail.icode = item.icode)) AND (CASE v_reportgrouping WHEN 'M' THEN item.manfcode WHEN 'C' THEN item.icatcode WHEN 'L' THEN item.iccode ELSE item.packcode END IN (SELECT code FROM tv_sp_subareasales_crosstab_tab_grouplist AS tab_grouplist))) UNION SELECT DISTINCT (customer.subareacode) FROM dbo.srledger, dbo.customer, dbo.srdetail, dbo.item WHERE (((((((posted = 'Y') AND (srledger.date >= v_startdate)) AND (srledger.date <= v_enddate)) AND (srledger.custcode = customer.custcode)) AND (srledger.srinvcode = srdetail.srinvcode)) AND (srdetail.icode = item.icode)) AND (CASE v_reportgrouping WHEN 'M' THEN item.manfcode WHEN 'C' THEN item.icatcode WHEN 'L' THEN item.iccode ELSE item.packcode END IN (SELECT code FROM tv_sp_subareasales_crosstab_tab_grouplist AS tab_grouplist)))));
  END IF;
  v_totareas := coalesce((SELECT count(code) FROM tv_sp_subareasales_crosstab_saleareastable AS saleareastable), 0);
  IF ((v_totareas > 0) AND (v_totcol > 0)) THEN
    v_tot := trunc((SELECT min(a) FROM (SELECT v_totcol AS a UNION SELECT v_totareas AS a) AS t))::integer;
    INSERT INTO tv_sp_subareasales_crosstab_coltable (code, shortname) SELECT s.subareacode, s.name FROM tv_sp_subareasales_crosstab_saleareastable AS a, dbo.subarea AS s WHERE (a.code = s.subareacode) ORDER BY s.name;
    v_iterations := trunc(ceiling((v_totareas / v_totcol)))::integer;
    v_curriter := 1;
    v_rowid := 0;
    WHILE (v_curriter <= v_iterations) LOOP
      INSERT INTO dbo.crosstab_reportdata (code1, code2, code3) SELECT code, v_curriter, NULL::integer FROM tv_sp_subareasales_crosstab_tab_itemlist AS tab_itemlist;
      v_i := 1;
      WHILE (v_i <= v_tot) LOOP
        v_rowid := (v_rowid + 1);
        v_colname := rtrim(ltrim(coalesce((SELECT shortname FROM tv_sp_subareasales_crosstab_coltable AS coltable WHERE (rowid = v_rowid)), '')));
        v_colcode := rtrim(ltrim(dbo.tsql_str(((SELECT code FROM tv_sp_subareasales_crosstab_coltable AS coltable WHERE (rowid = v_rowid)))::numeric, 7)));
        IF (v_colcode IS NULL) THEN
          EXIT;
        ELSE
          v_str_col := ltrim(rtrim(dbo.tsql_str((v_i)::numeric, 7)));
          v_upd := ((((((((('UPDATE CrossTab_ReportData SET C_Name' || v_str_col) || ' = ''') || v_colname) || ''', C_Code') || v_str_col) || ' = ') || v_colcode) || ' WHERE CODE2 = ') || ltrim(rtrim(dbo.tsql_str((v_curriter)::numeric, 7))));
          _dq1 := v_upd;
          IF _dq1 IS NOT NULL THEN
            EXECUTE dbo.tsql_dyn(_dq1);
          END IF;
          v_err := 0;
          IF (v_err <> 0) THEN
            v_upd := ('UPDATION ERROR, DETAILS: ' || v_upd);
            RAISE EXCEPTION '%', v_upd;
            return_value := -1;
            RETURN;
          END IF;
          v_i := (v_i + 1);
        END IF;
      END LOOP;
      v_curriter := (v_curriter + 1);
    END LOOP;
    OPEN cur_c1 FOR SELECT s.icode, coalesce(sum(s.qty), 0) AS qty, coalesce(sum(s.bonus), 0) AS bonus, round((sum(CASE v_pricetype WHEN 1 THEN s.netamt WHEN 2 THEN (s.qty * round(((i.saleprice / CASE i.packunits WHEN 0 THEN 1 ELSE i.packunits END))::numeric, 2)) WHEN 3 THEN (s.qty * round(((i.purprice / CASE i.packunits WHEN 0 THEN 1 ELSE i.packunits END))::numeric, 2)) ELSE (s.qty * round((i.avgprice)::numeric, 2)) END))::numeric, 0) AS val, s.subareacode FROM (SELECT sl.saleinvcode AS invno, sd.icode, sl.custcode AS custcode, coalesce(sum((sd.looseqty + CASE WHEN (v_mergebonus = 1) THEN sd.bonusqty ELSE 0 END)), 0) AS qty, coalesce(sum(CASE WHEN (v_mergebonus = 1) THEN 0 ELSE sd.bonusqty END), 0) AS bonus, round((coalesce((sum((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc)))) * ((1 - ((.01 * sd.discperc)))))) * ((1 - ((.01 * sl.discperc))))), 0))::numeric, 2) AS netamt, c.subareacode FROM dbo.saleledger AS sl, dbo.saledetail AS sd, dbo.customer AS c WHERE ((((((c.subareacode IN (SELECT code FROM tv_sp_subareasales_crosstab_saleareastable AS saleareastable)) AND (c.custcode = sl.custcode)) AND (sl.posted = 'Y')) AND (sl.saleinvcode = sd.saleinvcode)) AND (sl.date >= v_startdate)) AND (sl.date <= v_enddate)) GROUP BY sl.saleinvcode, sd.icode, sl.custcode, c.subareacode, sl.discperc UNION ALL SELECT sl.srinvcode AS invno, sd.icode, sl.custcode AS custcode, (-coalesce(sum((sd.looseqty + CASE WHEN (v_mergebonus = 1) THEN sd.bonusqty ELSE 0 END)), 0)) AS qty, (-coalesce(sum(CASE WHEN (v_mergebonus = 0) THEN sd.bonusqty ELSE 0 END), 0)) AS bonus, (-round((coalesce((sum((((sd.looseqty * sd.srprice)) * ((1 - ((.01 * sd.discperc)))))) * ((1 - ((.01 * sl.discperc))))), 0))::numeric, 2)) AS netamt, c.subareacode FROM dbo.srledger AS sl, dbo.srdetail AS sd, dbo.customer AS c WHERE ((((((c.subareacode IN (SELECT code FROM tv_sp_subareasales_crosstab_saleareastable AS saleareastable)) AND (c.custcode = sl.custcode)) AND (sl.posted = 'Y')) AND (sl.srinvcode = sd.srinvcode)) AND (sl.date >= v_startdate)) AND (sl.date <= v_enddate)) GROUP BY sl.srinvcode, sd.icode, sl.custcode, c.subareacode, sl.discperc) AS s, dbo.item AS i WHERE ((i.icode = s.icode) AND (i.icode IN (SELECT code FROM tv_sp_subareasales_crosstab_tab_itemlist AS tab_itemlist))) GROUP BY s.subareacode, s.icode ORDER BY s.subareacode, s.icode;
    FETCH NEXT FROM cur_c1 INTO v_icode, v_qty, v_bonus, v_val, v_subareacode;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    WHILE (_fs = 0) LOOP
      v_i := 1;
      WHILE (v_i <= v_tot) LOOP
        v_colcode := ltrim(rtrim(dbo.tsql_str((v_icode)::numeric, 7)));
        v_colname := ltrim(rtrim(dbo.tsql_str((v_subareacode)::numeric, 7)));
        v_str_col := ltrim(rtrim(dbo.tsql_str((v_i)::numeric, 7)));
        v_upd := ((((((((((((((((((((((('UPDATE CrossTab_ReportData SET ' || 'QTY') || v_str_col) || ' = ') || ltrim(rtrim(dbo.tsql_str((v_qty)::numeric, 15, 4)))) || ', Value') || v_str_col) || ' = ') || ltrim(rtrim(dbo.tsql_str((v_bonus)::numeric, 15, 4)))) || ', VAL') || v_str_col) || ' = ') || ltrim(rtrim(dbo.tsql_str((v_val)::numeric, 15, 5)))) || ', C_Code') || v_str_col) || ' = ') || v_colname) || ' WHERE CODE1 = ') || v_colcode) || ' AND ') || ' C_Code') || v_str_col) || ' = ') || v_colname);
        _dq2 := v_upd;
        IF _dq2 IS NOT NULL THEN
          EXECUTE dbo.tsql_dyn(_dq2);
        END IF;
        v_err := 0;
        IF (v_err <> 0) THEN
          v_upd := ('CROSSTAB PLOTING ERROR, DETAILS: ' || v_upd);
          RAISE EXCEPTION '%', v_upd;
          CLOSE cur_c1;
          -- DEALLOCATE C1
          return_value := -1;
          RETURN;
        END IF;
        v_i := (v_i + 1);
      END LOOP;
      FETCH NEXT FROM cur_c1 INTO v_icode, v_qty, v_bonus, v_val, v_subareacode;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    END LOOP;
    CLOSE cur_c1;
    -- DEALLOCATE C1
    UPDATE dbo.crosstab_reportdata AS c SET name1 = i.name, name2 = i.customicode, name3 = i.packingdesc, name4 = NULL::citext, code5 = CASE v_reportgrouping WHEN 'M' THEN i.manfcode WHEN 'C' THEN i.icatcode WHEN 'L' THEN i.iccode ELSE i.packcode END, name5 = CASE v_reportgrouping WHEN 'M' THEN (SELECT m.name FROM dbo.manufacturer AS m WHERE (m.manfcode = i.manfcode)) WHEN 'C' THEN (SELECT c.name FROM dbo.itemcategory AS c WHERE (c.icatcode = i.icatcode)) WHEN 'L' THEN (SELECT c.name FROM dbo.itemclass AS c WHERE (c.iccode = i.iccode)) ELSE (SELECT p.name FROM dbo.itempacking AS p WHERE (p.packcode = i.packcode)) END, value14 = CASE v_pricetype WHEN 1 THEN round(((i.saleprice / CASE i.packunits WHEN 0 THEN 1 ELSE i.packunits END))::numeric, 2) WHEN 2 THEN round(((i.saleprice / CASE i.packunits WHEN 0 THEN 1 ELSE i.packunits END))::numeric, 2) WHEN 3 THEN round(((i.purprice / CASE i.packunits WHEN 0 THEN 1 ELSE i.packunits END))::numeric, 2) ELSE round((i.avgprice)::numeric, 2) END FROM dbo.item AS i WHERE (i.icode = c.code1);
    IF (v_mergebonus = 0) THEN
      UPDATE dbo.crosstab_reportdata SET totqty = t.totqty, value15 = t.totbonus, totval = t.totval FROM dbo.crosstab_reportdata AS c, (SELECT code1, sum(((((((((((((coalesce(qty1, 0) + coalesce(qty2, 0)) + coalesce(qty3, 0)) + coalesce(qty4, 0)) + coalesce(qty5, 0)) + coalesce(qty6, 0)) + coalesce(qty7, 0)) + coalesce(qty8, 0)) + coalesce(qty9, 0)) + coalesce(qty10, 0)) + coalesce(qty11, 0)) + coalesce(qty12, 0)) + coalesce(qty13, 0))) AS totqty, sum(((((((((((((coalesce(value1, 0) + coalesce(value2, 0)) + coalesce(value3, 0)) + coalesce(value4, 0)) + coalesce(value5, 0)) + coalesce(value6, 0)) + coalesce(value7, 0)) + coalesce(value8, 0)) + coalesce(value9, 0)) + coalesce(value10, 0)) + coalesce(value11, 0)) + coalesce(value12, 0)) + coalesce(value13, 0))) AS totbonus, sum(((((((((((((coalesce(val1, 0) + coalesce(val2, 0)) + coalesce(val3, 0)) + coalesce(val4, 0)) + coalesce(val5, 0)) + coalesce(val6, 0)) + coalesce(val7, 0)) + coalesce(val8, 0)) + coalesce(val9, 0)) + coalesce(val10, 0)) + coalesce(val11, 0)) + coalesce(val12, 0)) + coalesce(val13, 0))) AS totval FROM dbo.crosstab_reportdata GROUP BY code1) AS t WHERE (c.code1 = t.code1);
    ELSE
      UPDATE dbo.crosstab_reportdata SET totqty = t.totqty, totval = t.totval FROM dbo.crosstab_reportdata AS c, (SELECT code1, sum((((((((((((((((((((((((((coalesce(qty1, 0) + coalesce(qty2, 0)) + coalesce(qty3, 0)) + coalesce(qty4, 0)) + coalesce(qty5, 0)) + coalesce(qty6, 0)) + coalesce(qty7, 0)) + coalesce(qty8, 0)) + coalesce(qty9, 0)) + coalesce(qty10, 0)) + coalesce(qty11, 0)) + coalesce(qty12, 0)) + coalesce(qty13, 0)) + coalesce(value1, 0)) + coalesce(value2, 0)) + coalesce(value3, 0)) + coalesce(value4, 0)) + coalesce(value5, 0)) + coalesce(value6, 0)) + coalesce(value7, 0)) + coalesce(value8, 0)) + coalesce(value9, 0)) + coalesce(value10, 0)) + coalesce(value11, 0)) + coalesce(value12, 0)) + coalesce(value13, 0))) AS totqty, sum(((((((((((((coalesce(val1, 0) + coalesce(val2, 0)) + coalesce(val3, 0)) + coalesce(val4, 0)) + coalesce(val5, 0)) + coalesce(val6, 0)) + coalesce(val7, 0)) + coalesce(val8, 0)) + coalesce(val9, 0)) + coalesce(val10, 0)) + coalesce(val11, 0)) + coalesce(val12, 0)) + coalesce(val13, 0))) AS totval FROM dbo.crosstab_reportdata GROUP BY code1) AS t WHERE (c.code1 = t.code1);
    END IF;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_Supervise_CashierActivity ====
CREATE OR REPLACE FUNCTION dbo.sp_supervise_cashieractivity(rowid integer, moduleid smallint, doccode integer, catcode smallint, acccode smallint, cashacccode smallint, cashtendered numeric, cashcharged numeric, cashback numeric, remarks citext, cashierjobcode integer, printed citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_rowid integer;
  v_moduleid smallint;
  v_doccode integer;
  v_catcode smallint;
  v_acccode smallint;
  v_cashacccode smallint;
  v_cashtendered numeric(15,2);
  v_cashcharged numeric(15,2);
  v_cashback numeric(15,2);
  v_remarks citext;
  v_cashierjobcode integer;
  v_printed citext;
  v_rowsaffected integer;
  v_count integer;
  v_err integer;
  v_posted citext;
  _rc integer;
BEGIN
  v_rowid := rowid;
  v_moduleid := moduleid;
  v_doccode := doccode;
  v_catcode := catcode;
  v_acccode := acccode;
  v_cashacccode := cashacccode;
  v_cashtendered := cashtendered;
  v_cashcharged := cashcharged;
  v_cashback := cashback;
  v_remarks := remarks;
  v_cashierjobcode := cashierjobcode;
  v_printed := printed;
  v_count := coalesce((SELECT count(*) FROM dbo.cashieractivity WHERE ((rowid = v_rowid) AND (supervised = 'N'))), 0);
  _rc := 1;
  IF ((v_count <= 0) OR (v_count IS NULL)) THEN
    RAISE EXCEPTION 'Unable to Supervise because the document is already supervised, Document #: %', v_doccode;
    return_value := -1;
    RETURN;
  END IF;
  IF ((v_moduleid = 10) OR (v_moduleid = 11)) THEN
    UPDATE dbo.saleledger SET salecatcode = CASE v_catcode WHEN 1 THEN 3 ELSE 2 END, custcode = v_acccode, cashacccode = v_cashacccode, cashtendered = v_cashtendered, cashcharged = v_cashcharged, cashback = v_cashback, posted = 'Y', postdate = localtimestamp(3), postedby = (SELECT jobowner FROM dbo.cashierjob WHERE (cashierjobcode = v_cashierjobcode)), outstandingamt = CASE WHEN ((outstandingamt - v_cashcharged) >= 0) THEN (outstandingamt - v_cashcharged) ELSE 0.00 END WHERE (saleinvcode = v_doccode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_rowsaffected := _rc;
    v_err := 0;
    _rc := 1;
    IF ((v_rowsaffected = 0) AND (v_err = 0)) THEN
      RAISE EXCEPTION 'Unable to Update Changes Made to Sale Inv #: %', v_doccode;
      return_value := -1;
      RETURN;
    END IF;
    v_posted := (SELECT posted FROM dbo.saleledger WHERE (saleinvcode = v_doccode));
    _rc := 1;
    IF (v_posted = 'Y') THEN
      DELETE FROM dbo.virtualgl WHERE ((documenttype = 'SV') AND (documentcode = v_doccode));
      GET DIAGNOSTICS _rc = ROW_COUNT;
    END IF;
  END IF;
  IF ((v_moduleid = 22) OR (v_moduleid = 23)) THEN
    UPDATE dbo.serviceheader SET servicecatcode = CASE v_catcode WHEN 1 THEN 10 ELSE 11 END, custcode = v_acccode, cashacccode = v_cashacccode, cashtendered = v_cashtendered, cashcharged = v_cashcharged, cashback = v_cashback, posted = 'Y', postdate = localtimestamp(3), postedby = (SELECT jobowner FROM dbo.cashierjob WHERE (cashierjobcode = v_cashierjobcode)), outstandingamt = CASE WHEN ((outstandingamt - v_cashcharged) >= 0) THEN (outstandingamt - v_cashcharged) ELSE 0.00 END WHERE (serviceinvcode = v_doccode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_rowsaffected := _rc;
    v_err := 0;
    _rc := 1;
    IF ((v_rowsaffected = 0) AND (v_err = 0)) THEN
      RAISE EXCEPTION 'Unable to Update Changes Made to Service Inv #: %', v_doccode;
      return_value := -1;
      RETURN;
    END IF;
    v_posted := (SELECT posted FROM dbo.serviceheader WHERE (serviceinvcode = v_doccode));
    _rc := 1;
    IF (v_posted = 'Y') THEN
      DELETE FROM dbo.virtualgl WHERE ((documenttype = 'RS') AND (documentcode = v_doccode));
      GET DIAGNOSTICS _rc = ROW_COUNT;
    END IF;
  END IF;
  IF ((v_moduleid = 31) OR (v_moduleid = 32)) THEN
    UPDATE dbo.srledger SET srcatcode = CASE v_catcode WHEN 1 THEN 8 ELSE 7 END, custcode = v_acccode, cashacccode = v_cashacccode, cashtendered = v_cashtendered, cashcharged = v_cashcharged, cashback = v_cashback, posted = 'Y', postdate = localtimestamp(3), postedby = (SELECT jobowner FROM dbo.cashierjob WHERE (cashierjobcode = v_cashierjobcode)), outstandingamt = CASE WHEN ((outstandingamt - v_cashcharged) >= 0) THEN (outstandingamt - v_cashcharged) ELSE 0.00 END WHERE (srinvcode = v_doccode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_rowsaffected := _rc;
    v_err := 0;
    _rc := 1;
    IF ((v_rowsaffected = 0) AND (v_err = 0)) THEN
      RAISE EXCEPTION 'Unable to Update Changes Made to S/R Inv #: %', v_doccode;
      return_value := -1;
      RETURN;
    END IF;
    v_posted := (SELECT posted FROM dbo.srledger WHERE (srinvcode = v_doccode));
    _rc := 1;
    IF (v_posted = 'Y') THEN
      DELETE FROM dbo.virtualgl WHERE ((documenttype = 'SR') AND (documentcode = v_doccode));
      GET DIAGNOSTICS _rc = ROW_COUNT;
    END IF;
  END IF;
  IF (v_moduleid = 102) THEN
    UPDATE dbo.saleledger SET outstandingamt = CASE WHEN ((outstandingamt - v_cashcharged) >= 0) THEN (outstandingamt - v_cashcharged) ELSE 0.00 END WHERE (saleinvcode = v_doccode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
  END IF;
  IF (v_moduleid = 104) THEN
    UPDATE dbo.purledger SET outstandingamt = CASE WHEN ((outstandingamt - v_cashcharged) >= 0) THEN (outstandingamt - v_cashcharged) ELSE 0.00 END WHERE (purinvcode = v_doccode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
  END IF;
  IF (v_moduleid IN (10, 11, 22, 23, 31, 32)) THEN
    UPDATE dbo.cashieractivity SET catcode = v_catcode, acccode = v_acccode, cashacccode = v_cashacccode, remarks = v_remarks, cashtendered = v_cashtendered, cashcharged = v_cashcharged, cashback = v_cashback, cashierjobcode = v_cashierjobcode, printed = v_printed, supervised = 'Y', supervisedon = localtimestamp(3), category = ((CASE v_catcode WHEN 1 THEN 'Cash' ELSE 'Credit' END || ' ') || CASE WHEN (v_moduleid IN (10, 11)) THEN 'Sale' WHEN (v_moduleid IN (22, 23)) THEN 'Service' ELSE 'S/Return' END) WHERE (rowid = v_rowid);
    GET DIAGNOSTICS _rc = ROW_COUNT;
  ELSE
    UPDATE dbo.cashieractivity SET supervised = 'Y', supervisedon = localtimestamp(3) WHERE (rowid = v_rowid);
    GET DIAGNOSTICS _rc = ROW_COUNT;
  END IF;
  v_rowsaffected := _rc;
  v_err := 0;
  _rc := 1;
  IF ((v_rowsaffected = 0) AND (v_err = 0)) THEN
    RAISE EXCEPTION 'Unable to Update Cashier Activity';
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_SuppliersBalance ====
CREATE OR REPLACE FUNCTION dbo.sp_suppliersbalance(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
BEGIN
  DROP TABLE IF EXISTS tmp_lt_pvamts;
  CREATE TEMP TABLE tmp_lt_pvamts (
    suppcode numeric(5,0) NOT NULL,
    debit numeric(15,2) NOT NULL,
    credit numeric(15,2) NOT NULL
) ON COMMIT DROP;
  DELETE FROM dbo.reportdata;
  INSERT INTO tmp_lt_pvamts SELECT supplier.suppcode, 0.0 AS debit, coalesce((round((((((sum(((purdetail.packqty * purdetail.purprice) * ((1 - ((.01 * purdetail.discperc)))))) * ((1 - ((.01 * purledger.discperc))))) + purledger.misccharges) + purledger.salestax) - purledger.flatdisc))::numeric, 0) + round((((sum((((purdetail.packqty + purdetail.bonusqty)) * purdetail.unitsalestax)) + sum(round((((((purdetail.packqty * purdetail.purprice) * ((1 - ((.01 * purdetail.discperc))))) * purdetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((purdetail.packqty * purdetail.purprice)) * ((1 - ((.01 * purdetail.discperc)))))) * ((1 - ((.01 * purledger.discperc))))) - purledger.flatdisc)) * ((purledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0)), 0) AS credit FROM dbo.purledger, dbo.purdetail, dbo.supplier WHERE ((((purledger.purinvcode = purdetail.purinvcode) AND (purledger.purcatcode IN (1, 2))) AND (purledger.posted = 'Y')) AND (purledger.suppcode = supplier.suppcode)) GROUP BY purledger.purinvcode, purledger.purcatcode, purledger.date, purledger.discperc, purledger.misccharges, purledger.salestax, purledger.flatdisc, purledger.invgstperc1, supplier.suppcode;
  INSERT INTO tmp_lt_pvamts SELECT supplier.suppcode, 0.0 AS debit, coalesce((round((((((sum((((purdetail.looseqty * purdetail.purprice)) * ((1 - ((.01 * purdetail.discperc)))))) * ((1 - ((.01 * purledger.discperc))))) + purledger.misccharges) + purledger.salestax) - purledger.flatdisc))::numeric, 0) + round((((sum((((purdetail.looseqty + purdetail.bonusqty)) * purdetail.unitsalestax)) + sum(round((((((purdetail.looseqty * purdetail.purprice) * ((1 - ((.01 * purdetail.discperc))))) * purdetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((purdetail.looseqty * purdetail.purprice)) * ((1 - ((.01 * purdetail.discperc)))))) * ((1 - ((.01 * purledger.discperc))))) - purledger.flatdisc)) * ((purledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0)), 0) AS credit FROM dbo.purledger, dbo.purdetail, dbo.supplier WHERE ((((purledger.purinvcode = purdetail.purinvcode) AND (purledger.purcatcode IN (7, 8))) AND (purledger.posted = 'Y')) AND (purledger.suppcode = supplier.suppcode)) GROUP BY purledger.purinvcode, purledger.purcatcode, purledger.date, purledger.discperc, purledger.misccharges, purledger.salestax, purledger.flatdisc, purledger.invgstperc1, supplier.suppcode;
  INSERT INTO tmp_lt_pvamts SELECT supplier.suppcode, coalesce((round((((((sum((((prdetail.looseqty * prdetail.prprice)) * ((1 - ((.01 * prdetail.discperc)))))) * ((1 - ((.01 * prledger.discperc))))) + prledger.misccharges) + prledger.salestax) - prledger.flatdisc))::numeric, 0) + round((((sum((((prdetail.looseqty + prdetail.bonusqty)) * prdetail.unitsalestax)) + sum(round((((((prdetail.looseqty * prdetail.prprice) * ((1 - ((.01 * prdetail.discperc))))) * prdetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((prdetail.looseqty * prdetail.prprice)) * ((1 - ((.01 * prdetail.discperc)))))) * ((1 - ((.01 * prledger.discperc))))) - prledger.flatdisc)) * ((prledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0)), 0) AS debit, 0.0 AS credit FROM dbo.prledger, dbo.prdetail, dbo.supplier WHERE ((((prledger.prinvcode = prdetail.prinvcode) AND (prledger.prcatcode IN (4, 5))) AND (prledger.posted = 'Y')) AND (prledger.suppcode = supplier.suppcode)) GROUP BY prledger.prinvcode, prledger.prcatcode, prledger.date, prledger.discperc, prledger.misccharges, prledger.salestax, prledger.flatdisc, prledger.invgstperc1, supplier.suppcode;
  INSERT INTO tmp_lt_pvamts SELECT supplier.suppcode, CASE sum(round((gldetail.debit)::numeric, 0)) WHEN NULL THEN 0.0 ELSE sum(round((gldetail.debit)::numeric, 0)) END, CASE sum(round((gldetail.credit)::numeric, 0)) WHEN NULL THEN 0.0 ELSE sum(round((gldetail.credit)::numeric, 0)) END FROM dbo.glheader, dbo.gldetail, dbo.supplier WHERE (((glheader.posted = 'Y') AND (gldetail.acccode = supplier.suppcode)) AND (glheader.glvochcode = gldetail.glvochcode)) GROUP BY supplier.suppcode;
  INSERT INTO tmp_lt_pvamts SELECT supplier.suppcode, coalesce(sum(notes.amount), 0), 0 FROM dbo.notes, dbo.supplier WHERE (((notes.posted = 'Y') AND (notes.notecatcode = 2)) AND (notes.acccode = supplier.suppcode)) GROUP BY supplier.suppcode;
  INSERT INTO dbo.reportdata (code1, name1, value1) SELECT accounts.acccode, accounts.name, (sum(lt_pvamts.debit) - sum(lt_pvamts.credit)) FROM tmp_lt_pvamts AS lt_pvamts, dbo.accounts WHERE (lt_pvamts.suppcode = accounts.acccode) GROUP BY accounts.acccode, accounts.name ORDER BY accounts.name;
  DROP TABLE IF EXISTS tmp_lt_pvamts;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_SupplierTransactionStatus ====
CREATE OR REPLACE FUNCTION dbo.sp_suppliertransactionstatus(ad_sdate timestamp, ad_edate timestamp, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ad_sdate timestamp(3);
  v_ad_edate timestamp(3);
  v_ln_openbalance numeric(12,2);
BEGIN
  v_ad_sdate := ad_sdate;
  v_ad_edate := ad_edate;
  DROP TABLE IF EXISTS tmp_lt_pvamts;
  CREATE TEMP TABLE tmp_lt_pvamts (
    debit numeric(15,2) NOT NULL,
    credit numeric(15,2) NOT NULL,
    code numeric(5,0) NOT NULL,
    name citext NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_pvamts SELECT 0.0 AS debit, coalesce((round((((((sum(((purdetail.packqty * purdetail.purprice) * ((1 - ((.01 * purdetail.discperc)))))) * ((1 - ((.01 * purledger.discperc))))) + purledger.misccharges) + purledger.salestax) - purledger.flatdisc))::numeric, 0) + round((((sum((((purdetail.packqty + purdetail.bonusqty)) * purdetail.unitsalestax)) + sum(round((((((purdetail.packqty * purdetail.purprice) * ((1 - ((.01 * purdetail.discperc))))) * purdetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((purdetail.packqty * purdetail.purprice)) * ((1 - ((.01 * purdetail.discperc)))))) * ((1 - ((.01 * purledger.discperc))))) - purledger.flatdisc)) * ((purledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0)), 0) AS credit, purledger.suppcode AS suppcode, (SELECT name FROM dbo.accounts WHERE (accounts.acccode = purledger.suppcode)) AS name FROM dbo.purledger, dbo.purdetail, dbo.supplier WHERE (((((purledger.purcatcode IN (2, 1)) AND (purledger.date < v_ad_sdate)) AND (purledger.posted = 'Y')) AND (purledger.suppcode = supplier.suppcode)) AND (purledger.purinvcode = purdetail.purinvcode)) GROUP BY purledger.purinvcode, purledger.purcatcode, purledger.suppcode, purledger.date, purledger.discperc, purledger.misccharges, purledger.salestax, purledger.invgstperc1, purledger.flatdisc;
