  INSERT INTO tmp_lt_pvamts SELECT coalesce((round((((((sum((((prdetail.looseqty * prdetail.prprice)) * ((1 - ((.01 * prdetail.discperc)))))) * ((1 - ((.01 * prledger.discperc))))) + prledger.misccharges) + prledger.salestax) - prledger.flatdisc))::numeric, 0) + round((((sum((((prdetail.looseqty + prdetail.bonusqty)) * prdetail.unitsalestax)) + sum(round((((((prdetail.looseqty * prdetail.prprice) * ((1 - ((.01 * prdetail.discperc))))) * prdetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((prdetail.looseqty * prdetail.prprice)) * ((1 - ((.01 * prdetail.discperc)))))) * ((1 - ((.01 * prledger.discperc))))) - prledger.flatdisc)) * ((prledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0)), 0) AS debit, 0.0 AS credit, prledger.suppcode AS code, (SELECT name FROM dbo.accounts WHERE (accounts.acccode = prledger.suppcode)) AS name FROM dbo.prledger, dbo.prdetail, dbo.supplier WHERE (((((prledger.prcatcode IN (5, 4)) AND (prledger.date < v_ad_sdate)) AND (prledger.posted = 'Y')) AND (prledger.suppcode = supplier.suppcode)) AND (prledger.prinvcode = prdetail.prinvcode)) GROUP BY prledger.prinvcode, prledger.prcatcode, prledger.suppcode, prledger.date, prledger.discperc, prledger.misccharges, prledger.salestax, prledger.invgstperc1, prledger.flatdisc;
