  INSERT INTO tmp_lt_pvamts SELECT coalesce(sum(notes.amount), 0), 0, notes.acccode AS code, (SELECT name FROM dbo.accounts WHERE (accounts.acccode = notes.acccode)) AS name FROM dbo.notes, dbo.supplier WHERE ((((notes.notecatcode = 2) AND (notes.posted = 'Y')) AND (notes.postdate < v_ad_sdate)) AND (notes.acccode = supplier.suppcode)) GROUP BY notes.acccode;
  DELETE FROM dbo.reportdata;
  INSERT INTO dbo.reportdata (code1, name1, value1, value2, value3) SELECT code, name, (sum(debit) - sum(credit)), 0, 0 FROM tmp_lt_pvamts AS lt_pvamts GROUP BY code, name;
  INSERT INTO dbo.reportdata (code1, value1, value2, value3) SELECT supplier.suppcode, 0, 0, 0 FROM dbo.supplier WHERE (supplier.suppcode NOT IN (SELECT code1 FROM dbo.reportdata));
  UPDATE dbo.reportdata AS reportdata SET name1 = accounts.name FROM dbo.accounts WHERE ((reportdata.name1 = NULL) AND (reportdata.code1 = accounts.acccode));
  DELETE FROM tmp_lt_pvamts AS lt_pvamts;
  INSERT INTO tmp_lt_pvamts SELECT 0.0 AS debit, coalesce((round((((((sum(((purdetail.packqty * purdetail.purprice) * ((1 - ((.01 * purdetail.discperc)))))) * ((1 - ((.01 * purledger.discperc))))) + purledger.misccharges) + purledger.salestax) - purledger.flatdisc))::numeric, 0) + round((((sum((((purdetail.packqty + purdetail.bonusqty)) * purdetail.unitsalestax)) + sum(round((((((purdetail.packqty * purdetail.purprice) * ((1 - ((.01 * purdetail.discperc))))) * purdetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((purdetail.packqty * purdetail.purprice)) * ((1 - ((.01 * purdetail.discperc)))))) * ((1 - ((.01 * purledger.discperc))))) - purledger.flatdisc)) * ((purledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0)), 0) AS credit, purledger.suppcode AS suppcode, (SELECT name FROM dbo.accounts WHERE (acccode = purledger.suppcode)) AS name FROM dbo.purledger, dbo.purdetail, dbo.supplier WHERE ((((((purledger.purcatcode IN (2, 1)) AND (purledger.date >= v_ad_sdate)) AND (purledger.date <= v_ad_edate)) AND (purledger.posted = 'Y')) AND (purledger.suppcode = supplier.suppcode)) AND (purledger.purinvcode = purdetail.purinvcode)) GROUP BY purledger.purinvcode, purledger.purcatcode, purledger.suppcode, purledger.date, purledger.discperc, purledger.misccharges, purledger.salestax, purledger.invgstperc1, purledger.flatdisc;
  INSERT INTO tmp_lt_pvamts SELECT 0.0 AS debit, coalesce((round((((((sum((((purdetail.looseqty * purdetail.purprice)) * ((1 - ((.01 * purdetail.discperc)))))) * ((1 - ((.01 * purledger.discperc))))) + purledger.misccharges) + purledger.salestax) - purledger.flatdisc))::numeric, 0) + round((((sum((((purdetail.looseqty + purdetail.bonusqty)) * purdetail.unitsalestax)) + sum(round((((((purdetail.looseqty * purdetail.purprice) * ((1 - ((.01 * purdetail.discperc))))) * purdetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((purdetail.looseqty * purdetail.purprice)) * ((1 - ((.01 * purdetail.discperc)))))) * ((1 - ((.01 * purledger.discperc))))) - purledger.flatdisc)) * ((purledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0)), 0) AS credit, purledger.suppcode AS code, (SELECT name FROM dbo.accounts WHERE (acccode = purledger.suppcode)) AS name FROM dbo.purledger, dbo.purdetail, dbo.supplier WHERE ((((((purledger.purcatcode IN (8, 7)) AND (purledger.date >= v_ad_sdate)) AND (purledger.date <= v_ad_edate)) AND (purledger.posted = 'Y')) AND (purledger.suppcode = supplier.suppcode)) AND (purledger.purinvcode = purdetail.purinvcode)) GROUP BY purledger.purinvcode, purledger.purcatcode, purledger.suppcode, purledger.date, purledger.discperc, purledger.misccharges, purledger.salestax, purledger.invgstperc1, purledger.flatdisc;
  INSERT INTO tmp_lt_pvamts SELECT coalesce((round((((((sum((((prdetail.looseqty * prdetail.prprice)) * ((1 - ((.01 * prdetail.discperc)))))) * ((1 - ((.01 * prledger.discperc))))) + prledger.misccharges) + prledger.salestax) - prledger.flatdisc))::numeric, 0) + round((((sum((((prdetail.looseqty + prdetail.bonusqty)) * prdetail.unitsalestax)) + sum(round((((((prdetail.looseqty * prdetail.prprice) * ((1 - ((.01 * prdetail.discperc))))) * prdetail.gstperc) * .01))::numeric, 2))) + round((((((sum((((prdetail.looseqty * prdetail.prprice)) * ((1 - ((.01 * prdetail.discperc)))))) * ((1 - ((.01 * prledger.discperc))))) - prledger.flatdisc)) * ((prledger.invgstperc1 * .01))))::numeric, 2)))::numeric, 0)), 0) AS debit, 0.0 AS credit, prledger.suppcode AS code, (SELECT name FROM dbo.accounts WHERE (acccode = prledger.suppcode)) AS name FROM dbo.prledger, dbo.prdetail, dbo.supplier WHERE ((((((prledger.prcatcode IN (5, 4)) AND (prledger.date >= v_ad_sdate)) AND (prledger.date <= v_ad_edate)) AND (prledger.posted = 'Y')) AND (prledger.suppcode = supplier.suppcode)) AND (prledger.prinvcode = prdetail.prinvcode)) GROUP BY prledger.prinvcode, prledger.prcatcode, prledger.suppcode, prledger.date, prledger.discperc, prledger.misccharges, prledger.salestax, prledger.invgstperc1, prledger.flatdisc;
  INSERT INTO tmp_lt_pvamts SELECT CASE sum(gldetail.debit) WHEN NULL THEN 0.0 ELSE sum(gldetail.debit) END, CASE sum(gldetail.credit) WHEN NULL THEN 0.0 ELSE sum(gldetail.credit) END, gldetail.acccode AS code, (SELECT name FROM dbo.accounts WHERE (accounts.acccode = gldetail.acccode)) AS name FROM dbo.glheader, dbo.gldetail, dbo.supplier WHERE (((((glheader.glvochcode = gldetail.glvochcode) AND (glheader.date >= v_ad_sdate)) AND (glheader.date <= v_ad_edate)) AND (glheader.posted = 'Y')) AND (gldetail.acccode = supplier.suppcode)) GROUP BY gldetail.acccode;
  INSERT INTO tmp_lt_pvamts SELECT coalesce(sum(notes.amount), 0), 0, notes.acccode AS code, (SELECT name FROM dbo.accounts WHERE (accounts.acccode = notes.acccode)) AS name FROM dbo.notes, dbo.supplier WHERE (((((notes.notecatcode = 2) AND (notes.posted = 'Y')) AND (notes.postdate >= v_ad_sdate)) AND (notes.postdate <= v_ad_edate)) AND (notes.acccode = supplier.suppcode)) GROUP BY notes.acccode;
  UPDATE dbo.reportdata SET value2 = a.ddebit, value3 = a.dcredit FROM (SELECT code, name, coalesce(sum(debit), 0) AS ddebit, coalesce(sum(credit), 0) AS dcredit FROM tmp_lt_pvamts AS lt_pvamts GROUP BY code, name) AS a WHERE (reportdata.code1 = a.code);
  DROP TABLE IF EXISTS tmp_lt_pvamts;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_SyncBasicData_On_Remote ====
CREATE OR REPLACE FUNCTION dbo.sp_syncbasicdata_on_remote(srv citext, db citext, owner citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_lastdatetime timestamp(3);
  v_lastsynced timestamp(3);
  v_tablename citext;
  v_full_table_name citext;
  v_con citext;
  v_remoteref citext;
  v_colname citext;
  v_whr citext;
  v_from citext;
  v_pkcond citext;
  v_notin citext;
  v_in citext;
  v_endd citext;
  v_maxcol citext;
  v_tabmaxsql citext;
  v_sql citext;
  v_list citext;
  v_autoinsert citext;
  v_autoupdate citext;
  v_autodelete citext;
  v_updmaxkey citext;
  v_table_id integer;
  v_err integer;
  v_sourcecount integer;
  v_targetcount integer;
  v_priority smallint;
  v_keyseq smallint;
  v_position smallint;
  v_del citext;
  v_del_qry citext;
  v_ins citext;
  v_ins_qry citext;
  v_upd citext;
  v_setpart citext;
  v_upd_pkcond citext;
  v_upd_qry citext;
  v_qry citext;
  cur_tmpcrs1 refcursor;
  _dq1 text;
  _dq2 text;
  cur_tmpcrs2 refcursor;
  _dq3 text;
  cur_tmpcrs3 refcursor;
  _dq4 text;
  _dq5 text;
  _dq6 text;
  _fs integer := -1;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  -- SET XACT_ABORT ON
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  IF ((ltrim(rtrim(v_srv)))::citext = '') THEN
    v_from := ((((' FROM ' || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.');
  ELSE
    v_from := ((((((' FROM ' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.');
  END IF;
  IF ((ltrim(rtrim(v_srv)))::citext = '') THEN
    v_remoteref := (((('' || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.');
  ELSE
    v_remoteref := (((((('' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.');
  END IF;
  v_notin := ' NOT IN (SELECT ';
  v_con := 'CONVERT(VarChar(10),';
  v_sql := 'SELECT ';
  v_in := ' IN (SELECT ';
  v_whr := 'WHERE ';
  v_endd := ' AS T WHERE ';
  v_lastdatetime := coalesce((SELECT serverdatatime FROM dbo.datatransferdate), '1900-01-01 00:00:00');
  v_lastsynced := coalesce((SELECT (max(logdate) - (1) * interval '1 day') FROM dbo.dataimportlog WHERE (importtype = 'Data Sync.')), '1900-01-01 00:00:00');
  v_del := 'DELETE ';
  v_upd := 'UPDATE ';
  v_setpart := 'SET ';
  v_ins := 'INSERT INTO ';
  OPEN cur_tmpcrs1 FOR SELECT ltrim(rtrim(tablename)) AS tablename, priority, autoinsert, autoupdate, autodelete, updatetabmaxkey FROM dbo.transferabledata WHERE (enable = 'Y') ORDER BY priority;
  FETCH NEXT FROM cur_tmpcrs1 INTO v_tablename, v_priority, v_autoinsert, v_autoupdate, v_autodelete, v_updmaxkey;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    v_full_table_name := ((ltrim(rtrim(v_owner)) || '.') || v_tablename);
    -- SET @table_id = OBJECT_ID(@full_table_name)
    RAISE EXCEPTION 'untranslated T-SQL (OBJECT_ID of non-literal)' USING ERRCODE = '0A000';
    v_err := 0;
    IF (((0 <> 0) OR (v_err <> 0)) OR (v_table_id IS NULL)) THEN
      RAISE EXCEPTION 'Data Updation: Invalid Object Refered: Name = %', v_full_table_name;
      CLOSE cur_tmpcrs1;
      -- DEALLOCATE TmpCrs1
      return_value := -1;
      RETURN;
    END IF;
    DELETE FROM dbo.reportdata;
    v_qry := ('INSERT INTO REPORTDATA (Code1) SELECT Count(*) FROM ' || v_tablename);
    _dq1 := v_qry;
    IF _dq1 IS NOT NULL THEN
      EXECUTE dbo.tsql_dyn(_dq1);
    END IF;
    v_err := 0;
    IF (v_err <> 0) THEN
      RAISE EXCEPTION 'Error Fetching Source Count for % Data', v_full_table_name;
      CLOSE cur_tmpcrs1;
      -- DEALLOCATE TmpCrs1
      return_value := -1;
      RETURN;
    END IF;
    v_sourcecount := trunc(coalesce((SELECT sum(code1) FROM dbo.reportdata), 0))::integer;
    DELETE FROM dbo.reportdata;
    v_qry := (('INSERT INTO REPORTDATA (Code1) SELECT Count(*) FROM ' || v_remoteref) || v_tablename);
    _dq2 := v_qry;
    IF _dq2 IS NOT NULL THEN
      EXECUTE dbo.tsql_dyn(_dq2);
    END IF;
    v_err := 0;
    IF (v_err <> 0) THEN
      RAISE EXCEPTION 'Error Fetching Target Count for % Data', v_full_table_name;
      CLOSE cur_tmpcrs1;
      -- DEALLOCATE TmpCrs1
      return_value := -1;
      RETURN;
    END IF;
    v_targetcount := trunc(coalesce((SELECT sum(code1) FROM dbo.reportdata), 0))::integer;
    IF ((v_sourcecount <> v_targetcount) OR (v_tablename = 'Item')) THEN
      v_pkcond := '';
      v_maxcol := '';
      v_upd_pkcond := '';
      -- OPEN TmpCrs2
      RAISE EXCEPTION 'untranslated T-SQL (system table sysindexes)' USING ERRCODE = '0A000';
      FETCH NEXT FROM cur_tmpcrs2 INTO v_colname, v_keyseq;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
      WHILE (_fs = 0) LOOP
        IF (v_keyseq <> 1) THEN
          v_pkcond := (v_pkcond || ' + ');
          v_upd_pkcond := (v_upd_pkcond || ' AND ');
        END IF;
        v_pkcond := ((((v_pkcond || ' ') || v_con) || ltrim(rtrim(v_colname))) || ')');
        v_upd_pkcond := ((((((v_upd_pkcond || ' T.') || ltrim(rtrim(v_colname))) || '=') || v_tablename) || '.') || ltrim(rtrim(v_colname)));
        v_maxcol := (('MAX(' || rtrim(ltrim(v_colname))) || ')');
        FETCH NEXT FROM cur_tmpcrs2 INTO v_colname, v_keyseq;
        IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
      END LOOP;
      CLOSE cur_tmpcrs2;
      -- DEALLOCATE TmpCrs2
      IF (v_autodelete = 'Y') THEN
        v_del_qry := (((((((v_del || 'FROM OPENQUERY(') || v_srv) || ',''SELECT ') || v_pkcond) || ' FROM ') || v_tablename) || ''')');
        _dq3 := v_del_qry;
        IF _dq3 IS NOT NULL THEN
          EXECUTE dbo.tsql_dyn(_dq3);
        END IF;
        v_err := 0;
        IF (v_err <> 0) THEN
          RAISE EXCEPTION 'Data Deletion: Error Transfering % Data', v_full_table_name;
          CLOSE cur_tmpcrs1;
          -- DEALLOCATE TmpCrs1
          return_value := -1;
          RETURN;
        END IF;
      END IF;
      IF (v_autoupdate = 'Y') THEN
        v_setpart := 'SET ';
        -- OPEN TmpCrs3
        RAISE EXCEPTION 'untranslated T-SQL (system table sysobjects)' USING ERRCODE = '0A000';
        FETCH NEXT FROM cur_tmpcrs3 INTO v_colname, v_position;
        IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
        WHILE (_fs = 0) LOOP
          -- IF ColumnProperty (@table_id, @ColName, 'IsIdentity') <> 1
          -- 				BEGIN
          -- 					IF @ColName = (SELECT columnname FROM TransferableData_RestrictedColumns WHERE columnname = @ColName and tablename = @TableName)
          -- 					BEGIN
          -- 						SET @ColName = @ColName
          -- 					END
          -- 					ELSE
          -- 					BEGIN
          -- 						IF @SETPART <> 'SET '
          -- 						BEGIN
          -- 							SET @SETPART = @SETPART + ','
          -- 						END
          -- 
          -- 						SET @SETPART = @SETPART + LTRIM(RTRIM(@ColName)) + '=' + 'T.' +  LTRIM(RTRIM(@ColName))
          -- 					END
          -- 				END
          RAISE EXCEPTION 'untranslated T-SQL (function ColumnProperty)' USING ERRCODE = '0A000';
          FETCH NEXT FROM cur_tmpcrs3 INTO v_colname, v_position;
          IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
        END LOOP;
        CLOSE cur_tmpcrs3;
        -- DEALLOCATE TmpCrs3
        IF (v_setpart <> 'SET ') THEN
          IF (v_tablename = 'Item') THEN
            v_upd_qry := (((((((((((((((((v_upd || v_remoteref) || v_tablename) || ' ') || v_setpart) || ' FROM ') || v_tablename) || ' AS T, ') || v_remoteref) || v_tablename) || ' AS ') || v_tablename) || ' WHERE ') || v_upd_pkcond) || ' AND T.LastUpdate >= ') || '''') || left(to_char(v_lastsynced, 'YYYY-MM-DD HH24:MI:SS.MS'), 100)) || '''');
          ELSE
            v_upd_qry := (((((((((((((v_upd || v_remoteref) || v_tablename) || ' ') || v_setpart) || ' FROM ') || v_tablename) || ' AS T, ') || v_remoteref) || v_tablename) || ' AS ') || v_tablename) || ' WHERE ') || v_upd_pkcond);
          END IF;
          _dq4 := v_upd_qry;
          IF _dq4 IS NOT NULL THEN
            EXECUTE dbo.tsql_dyn(_dq4);
          END IF;
          v_err := 0;
          IF ((0 <> 0) OR (v_err <> 0)) THEN
            RAISE EXCEPTION 'Data Updation: Error Transfering % Data', v_full_table_name;
            CLOSE cur_tmpcrs1;
            -- DEALLOCATE TmpCrs1
            return_value := -1;
            RETURN;
          END IF;
        END IF;
      END IF;
      IF ((v_autoinsert = 'Y') AND (v_tablename <> 'Rights')) THEN
        v_sql := ' SELECT ';
        v_list := '';
        SELECT r.return_value, r.list INTO v_err, v_list FROM dbo.sp_columnlist(owner => v_owner, "table" => v_tablename, list => v_list) AS r;
        v_err := 0;
        IF ((0 <> 0) OR (v_err <> 0)) THEN
          CLOSE cur_tmpcrs1;
          -- DEALLOCATE TmpCrs1
          return_value := -1;
          RETURN;
        END IF;
        IF (v_tablename = 'GroupRights') THEN
          v_ins_qry := (((((((((((((((((((v_ins || v_remoteref) || v_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_list) || ' FROM ') || v_tablename) || v_endd) || v_pkcond) || v_notin) || v_pkcond) || ' FROM ') || v_remoteref) || v_tablename) || ')  AND RightCode IN (SELECT RightCode FROM ') || v_remoteref) || ' Rights)');
        ELSE
          v_ins_qry := (((((((((((((((((v_ins || v_remoteref) || v_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_list) || ' FROM ') || v_tablename) || v_endd) || v_pkcond) || v_notin) || v_pkcond) || ' FROM ') || v_remoteref) || v_tablename) || ')');
        END IF;
        _dq5 := v_ins_qry;
        IF _dq5 IS NOT NULL THEN
          EXECUTE dbo.tsql_dyn(_dq5);
        END IF;
        v_err := 0;
        IF ((0 <> 0) OR (v_err <> 0)) THEN
          RAISE EXCEPTION 'Data Insertion: Error Transfering % Data', v_full_table_name;
          CLOSE cur_tmpcrs1;
          -- DEALLOCATE TmpCrs1
          return_value := -1;
          RETURN;
        END IF;
      END IF;
    END IF;
    FETCH NEXT FROM cur_tmpcrs1 INTO v_tablename, v_priority, v_autoinsert, v_autoupdate, v_autodelete, v_updmaxkey;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_tmpcrs1;
  -- DEALLOCATE TmpCrs1
  DELETE FROM dbo.datatransferdate;
  IF ((ltrim(rtrim(v_srv)))::citext = '') THEN
    v_ins_qry := ((((('INSERT INTO DataTransferDate (ServerDataTime) SELECT ServerDataTime = COALESCE((SELECT localtimestamp(3) - 0.042 FROM ' || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '._UTN)') || ', localtimestamp(3))');
  ELSE
    v_ins_qry := ((((((('INSERT INTO DataTransferDate (ServerDataTime) SELECT ServerDataTime = COALESCE((SELECT localtimestamp(3) - 0.042 FROM ' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '._UTN)') || ', localtimestamp(3))');
  END IF;
  _dq6 := v_ins_qry;
  IF _dq6 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq6);
  END IF;
  v_err := 0;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Data Transfer: Error While recoridng data transfer date';
    return_value := -1;
    RETURN;
  END IF;
  INSERT INTO dbo.dataimportlog (logdate, importedby, importtype, remarks) VALUES (localtimestamp(3), 1, 'Data Sync.', ((v_srv || ' DB:') || v_db));
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_SyncImportedData ====
CREATE OR REPLACE FUNCTION dbo.sp_syncimporteddata(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_tablename citext;
  v_full_table_name citext;
  v_con citext;
  v_imp_tablename citext;
  v_colname citext;
  v_whr citext;
  v_from citext;
  v_pkcond citext;
  v_notin citext;
  v_endd citext;
  v_maxcol citext;
  v_tabmaxsql citext;
  v_sql citext;
  v_list citext;
  v_autoinsert citext;
  v_autoupdate citext;
  v_autodelete citext;
  v_updmaxkey citext;
  v_table_id integer;
  v_err integer;
  v_rt_code integer;
  v_priority smallint;
  v_keyseq smallint;
  v_position smallint;
  v_syncstock citext;
  v_del citext;
  v_del_qry citext;
  v_ins citext;
  v_ins_qry citext;
  v_upd citext;
  v_setpart citext;
  v_upd_pkcond citext;
  v_upd_qry citext;
  v_dt timestamp(3);
  cur_tmpcrs1 refcursor;
  cur_tmpcrs2 refcursor;
  _dq1 text;
  cur_tmpcrs3 refcursor;
  _dq2 text;
  _dq3 text;
  _dq4 text;
  _dq5 text;
  _fs integer := -1;
BEGIN
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  v_syncstock := coalesce((SELECT dbo.fn_getpreference('syncstockfromparentserver')), 'N');
  IF (((ltrim(rtrim(v_syncstock)))::citext = '') OR (v_syncstock IS NULL)) THEN
    v_syncstock := 'N';
  END IF;
  v_from := ' FROM ';
  v_notin := ' NOT IN (SELECT ';
  v_con := 'CONVERT(VarChar(100),';
  v_sql := 'SELECT ';
  v_whr := 'WHERE ';
  v_endd := ' AS T WHERE ';
  v_del := 'DELETE ';
  v_upd := 'UPDATE ';
  v_setpart := 'SET ';
  v_ins := 'INSERT INTO ';
  OPEN cur_tmpcrs1 FOR SELECT ltrim(rtrim(tablename)) AS tablename, priority, autoinsert, autoupdate, autodelete, updatetabmaxkey FROM dbo.transferabledata WHERE (enable = 'Y') ORDER BY priority;
  FETCH NEXT FROM cur_tmpcrs1 INTO v_tablename, v_priority, v_autoinsert, v_autoupdate, v_autodelete, v_updmaxkey;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    v_imp_tablename := ('DBO.Import_' || v_tablename);
    v_full_table_name := ('DBO.' || v_tablename);
    -- SET @table_id = OBJECT_ID(@full_table_name)
    RAISE EXCEPTION 'untranslated T-SQL (OBJECT_ID of non-literal)' USING ERRCODE = '0A000';
    v_err := 0;
    IF (((0 <> 0) OR (v_err <> 0)) OR (v_table_id IS NULL)) THEN
      RAISE EXCEPTION 'Data Updation: Invalid Object Refered: Name = %', v_full_table_name;
      CLOSE cur_tmpcrs1;
      -- DEALLOCATE TmpCrs1
      return_value := -1;
      RETURN;
    END IF;
    v_pkcond := '';
    v_maxcol := '';
    v_upd_pkcond := '';
    -- OPEN TmpCrs2
    RAISE EXCEPTION 'untranslated T-SQL (system table sysindexes)' USING ERRCODE = '0A000';
    FETCH NEXT FROM cur_tmpcrs2 INTO v_colname, v_keyseq;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    WHILE (_fs = 0) LOOP
      IF (v_keyseq <> 1) THEN
        v_pkcond := (v_pkcond || ' + ');
        v_upd_pkcond := (v_upd_pkcond || ' AND ');
      END IF;
      v_pkcond := ((((v_pkcond || ' ') || v_con) || ltrim(rtrim(v_colname))) || ')');
      v_upd_pkcond := ((((((v_upd_pkcond || ' T.') || ltrim(rtrim(v_colname))) || ' = ') || v_tablename) || '.') || ltrim(rtrim(v_colname)));
      v_maxcol := (('MAX(' || rtrim(ltrim(v_colname))) || ')');
      FETCH NEXT FROM cur_tmpcrs2 INTO v_colname, v_keyseq;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    END LOOP;
    CLOSE cur_tmpcrs2;
    -- DEALLOCATE TmpCrs2
    IF ((v_autodelete = 'Y') AND (v_tablename <> 'Rights')) THEN
      v_del_qry := (((((((((v_del || v_tablename) || ' ') || v_whr) || v_pkcond) || v_notin) || v_pkcond) || v_from) || v_imp_tablename) || ')');
      _dq1 := v_del_qry;
      IF _dq1 IS NOT NULL THEN
        EXECUTE dbo.tsql_dyn(_dq1);
      END IF;
      v_err := 0;
      IF (v_err <> 0) THEN
        RAISE EXCEPTION 'Data Deletion: Error Transfering % Data', v_full_table_name;
        CLOSE cur_tmpcrs1;
        -- DEALLOCATE TmpCrs1
        return_value := -1;
        RETURN;
      END IF;
    END IF;
    IF (v_autoupdate = 'Y') THEN
      v_setpart := 'SET ';
      -- OPEN TmpCrs3
      RAISE EXCEPTION 'untranslated T-SQL (system table sysobjects)' USING ERRCODE = '0A000';
      FETCH NEXT FROM cur_tmpcrs3 INTO v_colname, v_position;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
      WHILE (_fs = 0) LOOP
        -- IF ColumnProperty (@table_id, @ColName, 'IsIdentity') <> 1
        -- 			BEGIN
        -- 				IF @ColName = (SELECT columnname FROM TransferableData_RestrictedColumns WHERE columnname = @ColName and tablename = @TableName)
        -- 				BEGIN
        -- 					SET @ColName = @ColName
        -- 				END
        -- 				ELSE
        -- 				BEGIN
        -- 					IF @SETPART <> 'SET '
        -- 					BEGIN
        -- 						SET @SETPART = @SETPART + ','
        -- 					END
        -- 
        -- 					SET @SETPART = @SETPART + LTRIM(RTRIM(@ColName)) + '=' + 'T.' +  LTRIM(RTRIM(@ColName))
        -- 				END
        -- 			END
        RAISE EXCEPTION 'untranslated T-SQL (function ColumnProperty)' USING ERRCODE = '0A000';
        FETCH NEXT FROM cur_tmpcrs3 INTO v_colname, v_position;
        IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
      END LOOP;
      CLOSE cur_tmpcrs3;
      -- DEALLOCATE TmpCrs3
      IF (v_setpart <> 'SET ') THEN
        v_upd_qry := (((((((((v_upd || v_tablename) || ' ') || v_setpart) || ' ') || v_from) || v_imp_tablename) || v_endd) || ' ') || v_upd_pkcond);
        _dq2 := v_upd_qry;
        IF _dq2 IS NOT NULL THEN
          EXECUTE dbo.tsql_dyn(_dq2);
        END IF;
        v_err := 0;
        IF ((0 <> 0) OR (v_err <> 0)) THEN
          RAISE EXCEPTION 'Data Updation: Error Transfering % Data', v_full_table_name;
          CLOSE cur_tmpcrs1;
          -- DEALLOCATE TmpCrs1
          return_value := -1;
          RETURN;
        END IF;
      END IF;
    END IF;
    IF ((v_autoinsert = 'Y') AND (v_tablename <> 'Rights')) THEN
      v_sql := ' SELECT ';
      v_list := '';
      SELECT r.return_value, r.list INTO v_err, v_list FROM dbo.sp_columnlist(owner => 'DBO', "table" => v_tablename, list => v_list) AS r;
      v_err := 0;
      IF ((0 <> 0) OR (v_err <> 0)) THEN
        CLOSE cur_tmpcrs1;
        -- DEALLOCATE TmpCrs1
        return_value := -1;
        RETURN;
      END IF;
      IF (v_tablename = 'GroupRights') THEN
        v_ins_qry := (((((((((((((((v_ins || v_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_list) || v_from) || v_imp_tablename) || v_endd) || v_pkcond) || v_notin) || v_pkcond) || ' FROM ') || v_tablename) || ')  AND RightCode IN (SELECT RightCode FROM Rights)');
      ELSE
        IF (v_tablename = 'Item') THEN
          v_list := replace((v_list)::citext, ('UserCode,')::citext, ('')::citext);
          v_ins_qry := (((((((((((((((v_ins || v_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_list) || v_from) || v_imp_tablename) || v_endd) || v_pkcond) || v_notin) || v_pkcond) || ' FROM ') || v_tablename) || ')');
        ELSE
          v_ins_qry := (((((((((((((((v_ins || v_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_list) || v_from) || v_imp_tablename) || v_endd) || v_pkcond) || v_notin) || v_pkcond) || ' FROM ') || v_tablename) || ')');
        END IF;
      END IF;
      _dq3 := v_ins_qry;
      IF _dq3 IS NOT NULL THEN
        EXECUTE dbo.tsql_dyn(_dq3);
      END IF;
      v_err := 0;
      IF ((0 <> 0) OR (v_err <> 0)) THEN
        RAISE EXCEPTION 'Data Insertion: Error Transfering % Data', v_full_table_name;
        CLOSE cur_tmpcrs1;
        -- DEALLOCATE TmpCrs1
        return_value := -1;
        RETURN;
      END IF;
    END IF;
    IF (v_updmaxkey = 'Y') THEN
      v_tabmaxsql := '';
      v_tabmaxsql := (((((((('UPDATE _tabmaxkey SET TABMAXKEY = ' || ' COALESCE((SELECT ') || v_maxcol) || ' FROM  ') || rtrim(ltrim(v_tablename))) || '), 0) ') || 'WHERE TABNAME = ''') || rtrim(ltrim(v_tablename))) || '''');
      _dq4 := v_tabmaxsql;
      IF _dq4 IS NOT NULL THEN
        EXECUTE dbo.tsql_dyn(_dq4);
      END IF;
      v_err := 0;
      IF ((0 <> 0) OR (v_err <> 0)) THEN
        RAISE EXCEPTION 'Data Insertion: Error While Updating the TABMAXKEY of % ', v_full_table_name;
        CLOSE cur_tmpcrs1;
        -- DEALLOCATE TmpCrs1
        return_value := -1;
        RETURN;
      END IF;
    END IF;
    FETCH NEXT FROM cur_tmpcrs1 INTO v_tablename, v_priority, v_autoinsert, v_autoupdate, v_autodelete, v_updmaxkey;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_tmpcrs1;
  -- DEALLOCATE TmpCrs1
  IF (v_syncstock = 'Y') THEN
    TRUNCATE TABLE dbo.godowndetail;
    v_ins_qry := 'INSERT INTO DBO.GodownDetail SELECT * FROM DBO.Import_GodownDetail';
    _dq5 := v_ins_qry;
    IF _dq5 IS NOT NULL THEN
      EXECUTE dbo.tsql_dyn(_dq5);
    END IF;
    v_err := 0;
    IF ((0 <> 0) OR (v_err <> 0)) THEN
      RAISE EXCEPTION 'Data Insertion: Synchronization of Godown Detail Failed';
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  v_dt := localtimestamp(3);
  SELECT r.return_value INTO v_rt_code FROM dbo.sp_set_datetime_preference(prefname => 'LastDataSynchronization', prefvalue => v_dt) AS r;
  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
    RAISE EXCEPTION 'Unable to Record Last Data Synchronization Information in Software Preferences';
    return_value := -1;
    RETURN;
  END IF;
  INSERT INTO dbo.dataimportlog (logdate, importedby, importtype, remarks) VALUES (localtimestamp(3), 1, 'Data Synchronization', 'Data Synchronization');
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_SyncTransactionData_OnRemote ====
CREATE OR REPLACE FUNCTION dbo.sp_synctransactiondata_onremote(srv citext, db citext, owner citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_err integer;
  v_syncablerows integer;
  v_rowid integer;
  v_tablename citext;
  v_archaccdata citext;
  v_synchronize citext;
  v_del_qry citext;
  v_remoteref citext;
  v_frm citext;
  v_parenttable citext;
  v_parentpk citext;
  v_updateparent citext;
  v_posted citext;
  v_qry citext;
  v_sql citext;
  v_list citext;
  v_from citext;
  v_list2 citext;
  cur_c1 refcursor;
  _dq1 text;
  _dq2 text;
  _dq3 text;
  _dq4 text;
  _dq5 text;
  _fs integer := -1;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  -- SET XACT_ABORT ON
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  v_frm := ' FROM DBO.';
  v_archaccdata := dbo.fn_getpreference('archiveaccountingdata');
  v_archaccdata := coalesce(v_archaccdata, 'N');
  IF ((ltrim(rtrim(v_srv)))::citext = '') THEN
    v_from := ((((' FROM ' || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.');
  ELSE
    v_from := ((((((' FROM ' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.');
  END IF;
  IF ((ltrim(rtrim(v_srv)))::citext = '') THEN
    v_remoteref := (((('' || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.');
  ELSE
    v_remoteref := (((((('' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.');
  END IF;
  DROP TABLE IF EXISTS tmp_ins_temp;
  CREATE TEMP TABLE tmp_ins_temp (
    rowid integer,
    tablename citext,
    synchronize citext,
    parenttable citext,
    parentpk citext,
    updateparent citext,
    posted citext
) ON COMMIT DROP;
  INSERT INTO tmp_ins_temp SELECT 41, 'PurQuotationHeader', 'Y', NULL::citext, 'PurQuotationCode', 'N', 'Y' UNION ALL SELECT 42, 'PurQuotationDetail', 'Y', 'PurQuotationHeader', 'PurQuotationCode', 'Y', 'Y' UNION ALL SELECT 43, 'SaleOrderHeader', 'Y', NULL::citext, 'SaleOrderCode', 'N', 'Y' UNION ALL SELECT 44, 'SaleOrderDetail', 'Y', 'SaleOrderHeader', 'SaleOrderCode', 'Y', 'Y' UNION ALL SELECT 45, 'QuotationHeader', 'Y', NULL::citext, 'QuotationCode', 'N', 'Y' UNION ALL SELECT 46, 'QuotationDetail', 'Y', 'QuotationHeader', 'QuotationCode', 'Y', 'Y' UNION ALL SELECT 47, 'PurOrderHeader', 'Y', NULL::citext, 'POCode', 'N', 'Y' UNION ALL SELECT 48, 'PurOrderDetail', 'Y', 'PurOrderHeader', 'POCode', 'Y', 'Y' UNION ALL SELECT 50, 'PurRegister', 'Y', NULL::citext, 'PurRegisterCode', 'N', 'Y' UNION ALL SELECT 60, 'ImpPurHeader', 'Y', NULL::citext, 'ImpPurInvCode', 'N', 'Y' UNION ALL SELECT 70, 'PurLedger', 'Y', NULL::citext, 'PurInvCode', 'N', 'Y' UNION ALL SELECT 80, 'AdvPurHeader', 'Y', NULL::citext, 'AdvPurInvCode', 'N', 'Y' UNION ALL SELECT 90, 'PurExp', 'Y', 'PurLedger', 'PurInvCode', 'N', 'Y' UNION ALL SELECT 100, 'ProformaPurDetail', 'Y', 'PurLedger', 'PurInvCode', 'N', 'Y' UNION ALL SELECT 110, 'PurDetail', 'Y', 'PurLedger', 'PurInvCode', 'Y', 'Y' UNION ALL SELECT 120, 'AdvPurDetail', 'Y', 'AdvPurHeader', 'AdvPurInvCode', 'Y', 'Y' UNION ALL SELECT 130, 'ImpPurDetail', 'Y', 'ImpPurHeader', 'ImpPurInvCode', 'Y', 'Y' UNION ALL SELECT 140, 'PurRegisterDetail', 'Y', 'PurRegister', 'PurRegisterCode', 'Y', 'Y' UNION ALL SELECT 150, 'PRLedger', 'Y', NULL::citext, 'PRInvCode', 'N', 'Y' UNION ALL SELECT 160, 'PRAllocationHeader', 'Y', NULL::citext, 'PRAllocationCode', 'N', 'Y' UNION ALL SELECT 170, 'PRDetail', 'Y', 'PRLedger', 'PRInvCode', 'Y', 'Y' UNION ALL SELECT 180, 'PRAllocationDetail', 'Y', 'PRAllocationHeader', 'PRAllocationCode', 'Y', 'Y' UNION ALL SELECT 190, 'DueAdjHeader', 'Y', NULL::citext, 'DueAdjCode', 'N', 'N' UNION ALL SELECT 200, 'SaleLedger', 'Y', NULL::citext, 'SaleInvCode', 'N', 'Y' UNION ALL SELECT 201, 'SaleInvGroup', 'Y', NULL::citext, 'SaleInvGroupCode', 'N', 'N' UNION ALL SELECT 202, 'SaleInvGroupDetail', 'Y', 'SaleInvGroup', 'SaleInvGroupCode', 'Y', 'N' UNION ALL SELECT 203, 'DispatchHeader', 'Y', NULL::citext, 'DispCode', 'N', 'Y' UNION ALL SELECT 204, 'DispatchDetail', 'Y', 'DispatchHeader', 'DispCode', 'Y', 'Y' UNION ALL SELECT 205, 'SaleSetsHeader', 'Y', 'SaleSetsHeader', 'SetCode', 'N', 'N' UNION ALL SELECT 206, 'SaleSetsDetail', 'Y', 'SaleSetsHeader', 'SetCode', 'N', 'N' UNION ALL SELECT 207, 'SaleSetsOrigDetail', 'Y', 'SaleSetsHeader', 'SetCode', 'Y', 'N' UNION ALL SELECT 210, 'DueSatisfyHeader', 'Y', NULL::citext, 'DueSatisfyCode', 'N', 'N' UNION ALL SELECT 220, 'SaleLedgerLog', 'Y', 'SaleLedger', 'SaleInvCode', 'N', 'Y' UNION ALL SELECT 230, 'SRBufferLedger', 'Y', NULL::citext, 'SRBufferInvCode', 'N', 'Y' UNION ALL SELECT 240, 'SRLedger', 'Y', NULL::citext, 'SRInvCode', 'N', 'Y' UNION ALL SELECT 245, 'CashierWindow', 'Y', 'SaleLedger', 'SaleInvCode', 'Y', 'Y' UNION ALL SELECT 250, 'SaleInvDetail', 'Y', 'SaleLedger', 'SaleInvCode', 'N', 'Y' UNION ALL SELECT 260, 'SaleDetailLog', 'Y', 'SaleLedger', 'SaleInvCode', 'N', 'Y' UNION ALL SELECT 270, 'SaleDetail', 'Y', 'SaleLedger', 'SaleInvCode', 'Y', 'Y' UNION ALL SELECT 280, 'SRDetail', 'Y', 'SRLedger', 'SRInvCode', 'Y', 'Y' UNION ALL SELECT 290, 'SRBufferDetail', 'Y', 'SRBufferLedger', 'SRBufferInvCode', 'Y', 'Y' UNION ALL SELECT 300, 'SRAllocationHeader', 'Y', NULL::citext, 'SRAllocationCode', 'N', 'Y' UNION ALL SELECT 310, 'SRAllocationDetail', 'Y', 'SRAllocationHeader', 'SRAllocationCode', 'Y', 'Y' UNION ALL SELECT 320, 'RefusedSaleHeader', 'Y', NULL::citext, 'RefusedSaleInvCode', 'N', 'N' UNION ALL SELECT 330, 'RefusedSaleDetail', 'Y', 'RefusedSaleHeader', 'RefusedSaleInvCode', 'Y', 'N' UNION ALL SELECT 350, 'DueDeleteDetail', 'Y', 'DueSatisfyHeader', 'DueSatisfyCode', 'N', 'N' UNION ALL SELECT 360, 'DueSatisfyDetail', 'Y', 'DueSatisfyHeader', 'DueSatisfyCode', 'Y', 'N' UNION ALL SELECT 370, 'DueAdjDetail', 'Y', 'DueAdjHeader', 'DueAdjCode', 'Y', 'N' UNION ALL SELECT 380, 'AdjHeader', 'Y', NULL::citext, 'AdjCode', 'N', 'Y' UNION ALL SELECT 390, 'AdjBufferHeader', 'Y', NULL::citext, 'AdjBufferCode', 'N', 'Y' UNION ALL SELECT 400, 'AdjDetail', 'Y', 'AdjHeader', 'AdjCode', 'Y', 'Y' UNION ALL SELECT 410, 'ItemConversionHeader', 'Y', NULL::citext, 'ItemConversionCode', 'N', 'Y' UNION ALL SELECT 420, 'ItemConversionDetail', 'Y', 'ItemConversionHeader', 'ItemConversionCode', 'Y', 'Y' UNION ALL SELECT 430, 'AdjBufferDetail', 'Y', 'AdjBufferHeader', 'AdjBufferCode', 'Y', 'Y' UNION ALL SELECT 440, 'TransferRequisitionHeader', 'Y', NULL::citext, 'TransReqCode', 'N', 'N' UNION ALL SELECT 450, 'TransferRequisitionDetail', 'Y', 'TransferRequisitionHeader', 'TransReqCode', 'Y', 'N' UNION ALL SELECT 460, 'Theader', 'Y', NULL::citext, 'TransCode', 'N', 'Y' UNION ALL SELECT 470, 'TDetail', 'Y', 'Theader', 'TransCode', 'Y', 'Y' UNION ALL SELECT 480, 'IssueReqHeader', 'Y', NULL::citext, 'IssueReqInvCode', 'N', 'Y' UNION ALL SELECT 490, 'IssueReqDetail', 'Y', 'IssueReqHeader', 'IssueReqInvCode', 'Y', 'Y' UNION ALL SELECT 500, 'IssueHeader', 'Y', NULL::citext, 'IssueInvCode', 'N', 'Y' UNION ALL SELECT 510, 'ReceiptHeader', 'Y', NULL::citext, 'ReceiptInvCode', 'N', 'Y' UNION ALL SELECT 520, 'IssueDetail', 'Y', 'IssueHeader', 'IssueInvCode', 'Y', 'Y' UNION ALL SELECT 530, 'ReceiptDetail', 'Y', 'ReceiptHeader', 'ReceiptInvCode', 'Y', 'Y' UNION ALL SELECT 540, 'ProdHeader', 'Y', NULL::citext, 'ProdCode', 'N', 'Y' UNION ALL SELECT 550, 'ProdBuffer', 'Y', 'ProdHeader', 'ProdCode', 'N', 'Y' UNION ALL SELECT 560, 'ProdDetail', 'Y', 'ProdHeader', 'ProdCode', 'Y', 'Y' UNION ALL SELECT 700, 'ServiceHeader', 'Y', NULL::citext, 'ServiceInvCode', 'N', 'Y' UNION ALL SELECT 710, 'ServiceDetail', 'Y', 'ServiceHeader', 'ServiceInvCode', 'Y', 'Y' UNION ALL SELECT 720, 'ServiceRHeader', 'Y', NULL::citext, 'ServiceRInvCode', 'N', 'Y' UNION ALL SELECT 730, 'ServiceRDetail', 'Y', 'ServiceRHeader', 'ServiceRInvCode', 'Y', 'Y' UNION ALL SELECT 740, 'ServiceSrAllocationHeader', 'Y', NULL::citext, 'ServiceSrAllocationCode', 'N', 'Y' UNION ALL SELECT 750, 'ServiceSrAllocationDetail', 'Y', 'ServiceSrAllocationHeader', 'ServiceSrAllocationCode', 'Y', 'Y' UNION ALL SELECT 760, 'ServicePurHeader', 'Y', NULL::citext, 'ServicePurInvCode', 'N', 'Y' UNION ALL SELECT 770, 'ServicePurDetail', 'Y', 'ServicePurHeader', 'ServicePurInvCode', 'Y', 'Y' UNION ALL SELECT 780, 'ServicePrHeader', 'Y', NULL::citext, 'ServicePrInvCode', 'N', 'Y' UNION ALL SELECT 790, 'ServicePrDetail', 'Y', 'ServicePrHeader', 'ServicePrInvCode', 'Y', 'Y' UNION ALL SELECT 800, 'ServicePrAllocationHeader', 'Y', NULL::citext, 'ServicePrAllocationCode', 'N', 'Y' UNION ALL SELECT 810, 'ServicePrAllocationDetail', 'Y', 'ServicePrAllocationHeader', 'ServicePrAllocationCode', 'Y', 'Y' UNION ALL SELECT 1010, 'GLHeader', v_archaccdata, NULL::citext, 'GLVochCode', 'N', 'Y' UNION ALL SELECT 1020, 'GLDetail', v_archaccdata, 'GLHeader', 'GLVochCode', 'Y', 'Y' UNION ALL SELECT 1030, 'Notes', v_archaccdata, NULL::citext, 'NoteCode', 'Y', 'Y' UNION ALL SELECT 1040, 'NotesDetail', v_archaccdata, 'Notes', 'NoteCode', 'Y', 'Y' UNION ALL SELECT 1050, 'TransactionHeader', v_archaccdata, NULL::citext, 'DocumentCode', 'N', 'Y' UNION ALL SELECT 1060, 'TransactionDetail', v_archaccdata, 'TransactionHeader', 'DocumentCode', 'Y', 'Y' UNION ALL SELECT 1065, 'AvgPriceAdjHeader', v_archaccdata, NULL::citext, 'DocumentCode', 'N', 'Y' UNION ALL SELECT 1070, 'AvgPriceAdjDetail', v_archaccdata, 'AvgPriceAdjHeader', 'DocumentCode', 'Y', 'Y';
  OPEN cur_c1 FOR SELECT rowid, tablename, synchronize, parenttable, parentpk, updateparent, posted FROM tmp_ins_temp AS ins_temp ORDER BY rowid;
  FETCH NEXT FROM cur_c1 INTO v_rowid, v_tablename, v_synchronize, v_parenttable, v_parentpk, v_updateparent, v_posted;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    v_qry := '';
    DELETE FROM dbo.reportdata;
    IF (v_parenttable IS NULL) THEN
      IF (v_posted = 'Y') THEN
        v_qry := (('INSERT INTO REPORTDATA (Code1) SELECT COALESCE(COUNT(*), 0) FROM ' || v_tablename) || ' WHERE Posted = ''Y'' AND Synced = ''N''');
      ELSE
        v_qry := (('INSERT INTO REPORTDATA (Code1) SELECT COALESCE(COUNT(*), 0) FROM ' || v_tablename) || ' WHERE Synced = ''N''');
      END IF;
    ELSE
      IF (v_posted = 'Y') THEN
        v_qry := (((((((('INSERT INTO REPORTDATA (Code1) SELECT COALESCE(COUNT(*), 0) FROM ' || v_tablename) || ' WHERE ') || v_parentpk) || ' IN (SELECT ') || v_parentpk) || ' FROM ') || v_parenttable) || ' WHERE Posted = ''Y'' AND Synced = ''N'')');
      ELSE
        v_qry := (((((((('INSERT INTO REPORTDATA (Code1) SELECT COALESCE(COUNT(*), 0) FROM ' || v_tablename) || ' WHERE ') || v_parentpk) || ' IN (SELECT ') || v_parentpk) || ' FROM ') || v_parenttable) || ' WHERE Synced = ''N'')');
      END IF;
    END IF;
    _dq1 := v_qry;
    IF _dq1 IS NOT NULL THEN
      EXECUTE dbo.tsql_dyn(_dq1);
    END IF;
    v_syncablerows := trunc(coalesce((SELECT sum(code1) FROM dbo.reportdata), 0))::integer;
    IF ((v_synchronize = 'Y') AND (v_syncablerows > 0)) THEN
      v_qry := '';
      v_sql := ' SELECT ';
      v_list := '';
      SELECT r.return_value, r.list INTO v_err, v_list FROM dbo.sp_columnlist(owner => v_owner, "table" => v_tablename, list => v_list) AS r;
      v_err := 0;
      IF ((0 <> 0) OR (v_err <> 0)) THEN
        CLOSE cur_c1;
        -- DEALLOCATE C1
        return_value := -1;
        RETURN;
      END IF;
      IF (v_parenttable IS NULL) THEN
        IF (v_posted = 'Y') THEN
          IF ((left(v_tablename, 10))::citext = 'SaleLedger') THEN
            v_list2 := v_list;
            v_list2 := replace((v_list2)::citext, ('SRBufferInvCode')::citext, ('NULL')::citext);
            v_list2 := replace((v_list2)::citext, ('SaleOrderCode')::citext, ('NULL')::citext);
            v_qry := (((((((((('INSERT INTO ' || v_remoteref) || v_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_list2) || v_frm) || v_tablename) || ' WHERE Posted = ''Y'' AND Synced = ''N''');
          ELSE
            v_qry := (((((((((('INSERT INTO ' || v_remoteref) || v_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_list) || v_frm) || v_tablename) || ' WHERE Posted = ''Y'' AND Synced = ''N''');
          END IF;
        ELSE
          v_qry := (((((((((('INSERT INTO ' || v_remoteref) || v_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_list) || v_frm) || v_tablename) || ' WHERE Synced = ''N''');
        END IF;
      ELSE
        IF (v_posted = 'Y') THEN
          v_qry := (((((((((((((((('INSERT INTO ' || v_remoteref) || v_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_list) || v_frm) || v_tablename) || ' WHERE ') || v_parentpk) || ' IN (SELECT ') || v_parentpk) || ' FROM ') || v_parenttable) || ' WHERE Posted = ''Y'' AND Synced = ''N'')');
        ELSE
          v_qry := (((((((((((((((('INSERT INTO ' || v_remoteref) || v_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_list) || v_frm) || v_tablename) || ' WHERE ') || v_parentpk) || ' IN (SELECT ') || v_parentpk) || ' FROM ') || v_parenttable) || ' WHERE Synced = ''N'')');
        END IF;
      END IF;
      IF (length(rtrim(ltrim(rtrim(v_qry)))) > 0) THEN
        RAISE NOTICE '%', v_qry;
        _dq2 := v_qry;
        IF _dq2 IS NOT NULL THEN
          EXECUTE dbo.tsql_dyn(_dq2);
        END IF;
        v_err := 0;
        IF ((0 <> 0) OR (v_err <> 0)) THEN
          RAISE EXCEPTION 'Data Insertion: Error Transfering % Data', v_tablename;
          CLOSE cur_c1;
          -- DEALLOCATE C1
          return_value := -1;
          RETURN;
        END IF;
        IF (v_updateparent = 'Y') THEN
          IF (v_posted = 'Y') THEN
            v_qry := (('UPDATE ' || v_parenttable) || ' SET Synced = ''Y'', SyncedOn=localtimestamp(3), SyncedBy=1 WHERE Posted = ''Y'' AND Synced = ''N''');
          ELSE
            v_qry := (('UPDATE ' || v_parenttable) || ' SET Synced = ''Y'', SyncedOn=localtimestamp(3), SyncedBy=1 WHERE Synced = ''N''');
          END IF;
          RAISE NOTICE '%', v_qry;
          _dq3 := v_qry;
          IF _dq3 IS NOT NULL THEN
            EXECUTE dbo.tsql_dyn(_dq3);
          END IF;
          v_err := 0;
          IF ((0 <> 0) OR (v_err <> 0)) THEN
            RAISE EXCEPTION 'Data Updation: Error Updating Sync. Status for % Data', v_parenttable;
            CLOSE cur_c1;
            -- DEALLOCATE C1
            return_value := -1;
            RETURN;
          END IF;
        END IF;
      END IF;
    END IF;
    FETCH NEXT FROM cur_c1 INTO v_rowid, v_tablename, v_synchronize, v_parenttable, v_parentpk, v_updateparent, v_posted;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_c1;
  -- DEALLOCATE C1
  v_qry := (('DELETE ' || v_remoteref) || 'GodownDetail');
  _dq4 := v_qry;
  IF _dq4 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq4);
  END IF;
  v_err := 0;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Data Truncation Error: Error Transfering % Data', 'GodownDetail';
    return_value := -1;
    RETURN;
  END IF;
  v_qry := (('INSERT INTO ' || v_remoteref) || 'GodownDetail SELECT * FROM GodownDetail');
  _dq5 := v_qry;
  IF _dq5 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq5);
  END IF;
  v_err := 0;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Data Insertion: Error Transfering % Data', 'GodownDetail';
    return_value := -1;
    RETURN;
  END IF;
  INSERT INTO dbo.dataimportlog (logdate, importedby, importtype, remarks) VALUES (localtimestamp(3), 1, 'Trans. Synced', 'Data Synced');
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_TemplateMarking ====
CREATE OR REPLACE FUNCTION dbo.sp_templatemarking(template integer, "group" citext, grouplist citext, marked citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_template integer;
  v_group citext;
  v_grouplist citext;
  v_marked citext;
BEGIN
  v_template := template;
  v_group := "group";
  v_grouplist := grouplist;
  v_marked := marked;
  -- SET NOCOUNT ON
  UPDATE dbo.saletemplatedetail AS saletemplatedetail SET marked = v_marked FROM (SELECT code AS icode FROM dbo.udf_selectitems(v_group, v_grouplist) AS udf_selectitems) AS t WHERE ((saletemplatedetail.saletemplatecode = v_template) AND (saletemplatedetail.icode = t.icode));
  IF (0 <> 0) THEN
    RAISE EXCEPTION 'Problem in marking sale template rows';
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_test1 ====
CREATE OR REPLACE FUNCTION dbo.sp_test1(ad_startdate timestamp, ad_enddate timestamp, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ad_startdate timestamp(3);
  v_ad_enddate timestamp(3);
  v_ln_cashacc numeric(5,0);
  v_ln_equityacc numeric(5,0);
  v_ln_freightacc numeric(5,0);
  v_ln_octroiacc numeric(5,0);
  v_ln_salestaxacc numeric(5,0);
  v_ln_inventoryacc numeric(5,0);
  v_ln_favourableacc numeric(5,0);
  v_ln_unfavourableacc numeric(5,0);
  v_ln_avgpurcostacc numeric(5,0);
  v_ln_salesacc numeric(5,0);
  v_ln_salesfixdiscacc numeric(5,0);
  v_ln_miscchargesacc numeric(5,0);
  v_ln_salesretacc numeric(5,0);
  v_ln_purchaseacc numeric(5,0);
BEGIN
  v_ad_startdate := ad_startdate;
  v_ad_enddate := ad_enddate;
  v_ln_cashacc := (SELECT code FROM dbo.global WHERE (name = 'GT_CashACC'));
  v_ln_equityacc := (SELECT code FROM dbo.global WHERE (name = 'GT_EquityACC'));
  v_ln_freightacc := (SELECT code FROM dbo.global WHERE (name = 'GT_FreightACC'));
  v_ln_octroiacc := (SELECT code FROM dbo.global WHERE (name = 'GT_OctroiACC'));
  v_ln_salestaxacc := (SELECT code FROM dbo.global WHERE (name = 'GT_AdvanceSalesTaxACC'));
  v_ln_inventoryacc := (SELECT code FROM dbo.global WHERE (name = 'GT_InventoryACC'));
  v_ln_favourableacc := (SELECT code FROM dbo.global WHERE (name = 'GT_FavourableACC'));
  v_ln_unfavourableacc := (SELECT code FROM dbo.global WHERE (name = 'GT_UnFavourableACC'));
  v_ln_salesacc := (SELECT code FROM dbo.global WHERE (name = 'GT_SalesACC'));
  v_ln_salesfixdiscacc := (SELECT code FROM dbo.global WHERE (name = 'GT_SalesFixDiscountACC'));
  v_ln_miscchargesacc := (SELECT code FROM dbo.global WHERE (name = 'GT_MiscChargesACC'));
  v_ln_salesretacc := (SELECT code FROM dbo.global WHERE (name = 'GT_SalesReturnACC'));
  v_ln_purchaseacc := (SELECT code FROM dbo.global WHERE (name = 'GT_PurchaseACC'));
  DROP TABLE IF EXISTS tmp_lt_accounts;
  CREATE TEMP TABLE tmp_lt_accounts (
    acccode numeric(5,0) NOT NULL,
    accname citext NULL,
    subaccname citext NULL,
    openbalance numeric(12,2) NOT NULL
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_lt_accountsledger;
  CREATE TEMP TABLE tmp_lt_accountsledger (
    acccode numeric(5,0) NOT NULL,
    type citext NOT NULL,
    date timestamp(3) NOT NULL,
    debit numeric(12,2) NOT NULL,
    credit numeric(12,2) NOT NULL,
    remarks citext NULL
) ON COMMIT DROP;
  PERFORM dbo.sp_accountsbalance(ad_date => v_ad_startdate);
  INSERT INTO tmp_lt_accounts SELECT code1, name1, name2, value1 FROM dbo.reportdata;
  OPEN rs1 FOR SELECT code1, name1, name2, value1 FROM dbo.reportdata;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_Test2 ====
CREATE OR REPLACE FUNCTION dbo.sp_test2(ad_date timestamp, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ad_date timestamp(3);
  v_ln_cashacc numeric(5,0);
  v_ln_equityacc numeric(5,0);
  v_ln_freightacc numeric(5,0);
  v_ln_octroiacc numeric(5,0);
  v_ln_salestaxacc numeric(5,0);
  v_ln_inventoryacc numeric(5,0);
  v_ln_favourableacc numeric(5,0);
  v_ln_unfavourableacc numeric(5,0);
  v_ln_avgpurcostacc numeric(5,0);
  v_ln_salesacc numeric(5,0);
  v_ln_salesfixdiscacc numeric(5,0);
  v_ln_miscchargesacc numeric(5,0);
  v_ln_salesretacc numeric(5,0);
  v_ln_purchaseacc numeric(5,0);
BEGIN
  v_ad_date := ad_date;
  v_ln_cashacc := (SELECT code FROM dbo.global WHERE (name = 'GT_CashACC'));
  v_ln_equityacc := (SELECT code FROM dbo.global WHERE (name = 'GT_EquityACC'));
  v_ln_freightacc := (SELECT code FROM dbo.global WHERE (name = 'GT_FreightACC'));
  v_ln_octroiacc := (SELECT code FROM dbo.global WHERE (name = 'GT_OctroiACC'));
  v_ln_salestaxacc := (SELECT code FROM dbo.global WHERE (name = 'GT_AdvanceSalesTaxACC'));
  v_ln_inventoryacc := (SELECT code FROM dbo.global WHERE (name = 'GT_InventoryACC'));
  v_ln_favourableacc := (SELECT code FROM dbo.global WHERE (name = 'GT_FavourableACC'));
  v_ln_unfavourableacc := (SELECT code FROM dbo.global WHERE (name = 'GT_UnFavourableACC'));
  v_ln_salesacc := (SELECT code FROM dbo.global WHERE (name = 'GT_SalesACC'));
  v_ln_salesfixdiscacc := (SELECT code FROM dbo.global WHERE (name = 'GT_SalesFixDiscountACC'));
  v_ln_miscchargesacc := (SELECT code FROM dbo.global WHERE (name = 'GT_MiscChargesACC'));
  v_ln_salesretacc := (SELECT code FROM dbo.global WHERE (name = 'GT_SalesReturnACC'));
  v_ln_purchaseacc := (SELECT code FROM dbo.global WHERE (name = 'GT_PurchaseACC'));
  DROP TABLE IF EXISTS tmp_lt_accounts;
  CREATE TEMP TABLE tmp_lt_accounts (
    acccode numeric(5,0) NOT NULL,
    currbalance numeric(11,2) NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_accounts SELECT acccode, 0 FROM dbo.accounts;
  DROP TABLE IF EXISTS tmp_lt_purchasesummary;
  CREATE TEMP TABLE tmp_lt_purchasesummary (
    acccode numeric(5,0) NOT NULL,
    inventoryamt numeric(11,2) NOT NULL,
    netamt numeric(11,2) NOT NULL,
    flatdisc numeric(11,2) NOT NULL,
    misccharges numeric(11,2) NOT NULL,
    salestax numeric(11,2) NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_purchasesummary SELECT CASE purledger.purcatcode WHEN 1 THEN v_ln_cashacc WHEN 3 THEN v_ln_equityacc ELSE purledger.suppcode END, coalesce((sum((((((purdetail.looseqty + (purdetail.packqty * purdetail.packunits))) * purdetail.purprice)) * ((1 - ((.01 * purdetail.discperc)))))) * ((1 - ((.01 * purledger.discperc))))), 0), coalesce(round((((((sum((((((purdetail.looseqty + (purdetail.packqty * purdetail.packunits))) * purdetail.purprice)) * ((1 - ((.01 * purdetail.discperc)))))) * ((1 - ((.01 * purledger.discperc))))) + purledger.misccharges) + purledger.salestax) - purledger.flatdisc))::numeric, 0), 0), purledger.flatdisc, purledger.misccharges, purledger.salestax FROM dbo.purledger, dbo.purdetail WHERE ((purledger.date <= v_ad_date) AND (purledger.purinvcode = purdetail.purinvcode)) GROUP BY purledger.purinvcode, purledger.suppcode, purledger.purcatcode, purledger.date, purledger.discperc, purledger.misccharges, purledger.salestax, purledger.flatdisc;
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(inventoryamt), 0) FROM tmp_lt_purchasesummary AS lt_purchasesummary)) WHERE (lt_accounts.acccode = v_ln_inventoryacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance - (SELECT coalesce(sum(flatdisc), 0) FROM tmp_lt_purchasesummary AS lt_purchasesummary)) WHERE (lt_accounts.acccode = v_ln_freightacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(misccharges), 0) FROM tmp_lt_purchasesummary AS lt_purchasesummary)) WHERE (lt_accounts.acccode = v_ln_octroiacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(salestax), 0) FROM tmp_lt_purchasesummary AS lt_purchasesummary)) WHERE (lt_accounts.acccode = v_ln_salestaxacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance - (SELECT coalesce(sum(lt_purchasesummary.netamt), 0) FROM tmp_lt_purchasesummary AS lt_purchasesummary WHERE (lt_purchasesummary.acccode = lt_accounts.acccode))) FROM tmp_lt_purchasesummary AS lt_purchasesummary WHERE (lt_accounts.acccode = lt_purchasesummary.acccode);
  DROP TABLE IF EXISTS tmp_lt_purchasesummary;
  DROP TABLE IF EXISTS tmp_lt_purretsummary;
  CREATE TEMP TABLE tmp_lt_purretsummary (
    acccode numeric(5,0) NOT NULL,
    inventoryamt numeric(11,2) NOT NULL,
    netamt numeric(11,2) NOT NULL,
    flatdisc numeric(11,2) NOT NULL,
    misccharges numeric(11,2) NOT NULL,
    salestax numeric(11,2) NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_purretsummary SELECT CASE prledger.prcatcode WHEN 4 THEN v_ln_cashacc WHEN 6 THEN v_ln_equityacc ELSE prledger.suppcode END, coalesce((sum((((((prdetail.looseqty + (prdetail.packqty * prdetail.packunits))) * prdetail.prprice)) * ((1 - ((.01 * prdetail.discperc)))))) * ((1 - ((.01 * prledger.discperc))))), 0), coalesce(round((((((sum((((((prdetail.looseqty + (prdetail.packqty * prdetail.packunits))) * prdetail.prprice)) * ((1 - ((.01 * prdetail.discperc)))))) * ((1 - ((.01 * prledger.discperc))))) + prledger.misccharges) + prledger.salestax) - prledger.flatdisc))::numeric, 0), 0), prledger.flatdisc, prledger.misccharges, prledger.salestax FROM dbo.prledger, dbo.prdetail WHERE ((prledger.date <= v_ad_date) AND (prledger.prinvcode = prdetail.prinvcode)) GROUP BY prledger.prinvcode, prledger.suppcode, prledger.prcatcode, prledger.date, prledger.discperc, prledger.misccharges, prledger.salestax, prledger.flatdisc;
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance - (SELECT coalesce(sum(inventoryamt), 0) FROM tmp_lt_purretsummary AS lt_purretsummary)) WHERE (lt_accounts.acccode = v_ln_inventoryacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(flatdisc), 0) FROM tmp_lt_purretsummary AS lt_purretsummary)) WHERE (lt_accounts.acccode = v_ln_freightacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance - (SELECT coalesce(sum(misccharges), 0) FROM tmp_lt_purretsummary AS lt_purretsummary)) WHERE (lt_accounts.acccode = v_ln_octroiacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance - (SELECT coalesce(sum(salestax), 0) FROM tmp_lt_purretsummary AS lt_purretsummary)) WHERE (lt_accounts.acccode = v_ln_salestaxacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(lt_purretsummary.netamt), 0) FROM tmp_lt_purretsummary AS lt_purretsummary WHERE (lt_purretsummary.acccode = lt_accounts.acccode))) FROM tmp_lt_purretsummary AS lt_purretsummary WHERE (lt_accounts.acccode = lt_purretsummary.acccode);
  DROP TABLE IF EXISTS tmp_lt_purretsummary;
  DROP TABLE IF EXISTS tmp_lt_salesummary;
  CREATE TEMP TABLE tmp_lt_salesummary (
    acccode numeric(5,0) NOT NULL,
    inventoryamt numeric(11,2) NOT NULL,
    netamt numeric(11,2) NOT NULL,
    flatdisc numeric(11,2) NOT NULL,
    misccharges numeric(11,2) NOT NULL,
    salestax numeric(11,2) NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_salesummary SELECT CASE saleledger.salecatcode WHEN 1 THEN v_ln_cashacc WHEN 3 THEN v_ln_cashacc ELSE saleledger.custcode END, coalesce(sum((((saledetail.looseqty + (saledetail.packqty * saledetail.packunits))) * saledetail.avgprice)), 0), coalesce(round((((((sum((((((saledetail.looseqty + (saledetail.packqty * saledetail.packunits))) * saledetail.saleprice)) * ((1 - ((.01 * saledetail.discperc)))))) * ((1 - ((.01 * saleledger.discperc))))) + saleledger.misccharges) + saleledger.salestax) - saleledger.flatdisc))::numeric, 0), 0), saleledger.flatdisc, saleledger.misccharges, saleledger.salestax FROM dbo.saleledger, dbo.saledetail WHERE ((saleledger.date <= v_ad_date) AND (saleledger.saleinvcode = saledetail.saleinvcode)) GROUP BY saleledger.saleinvcode, saleledger.custcode, saleledger.salecatcode, saleledger.date, saleledger.discperc, saleledger.misccharges, saleledger.salestax, saleledger.flatdisc;
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance - (SELECT coalesce(sum(inventoryamt), 0) FROM tmp_lt_salesummary AS lt_salesummary)) WHERE (lt_accounts.acccode = v_ln_inventoryacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(inventoryamt), 0) FROM tmp_lt_salesummary AS lt_salesummary)) WHERE (lt_accounts.acccode = v_ln_purchaseacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(flatdisc), 0) FROM tmp_lt_salesummary AS lt_salesummary)) WHERE (lt_accounts.acccode = v_ln_salesfixdiscacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance - (SELECT coalesce(sum(misccharges), 0) FROM tmp_lt_salesummary AS lt_salesummary)) WHERE (lt_accounts.acccode = v_ln_miscchargesacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance - (SELECT coalesce(sum(salestax), 0) FROM tmp_lt_salesummary AS lt_salesummary)) WHERE (lt_accounts.acccode = v_ln_salestaxacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance - (SELECT coalesce(sum((((netamt - salestax) + flatdisc) - misccharges)), 0) FROM tmp_lt_salesummary AS lt_salesummary)) WHERE (lt_accounts.acccode = v_ln_salesacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(lt_salesummary.netamt), 0) FROM tmp_lt_salesummary AS lt_salesummary WHERE (lt_salesummary.acccode = lt_accounts.acccode))) FROM tmp_lt_salesummary AS lt_salesummary WHERE (lt_accounts.acccode = lt_salesummary.acccode);
  DROP TABLE IF EXISTS tmp_lt_salesummary;
  DROP TABLE IF EXISTS tmp_lt_saleretsummary;
  CREATE TEMP TABLE tmp_lt_saleretsummary (
    acccode numeric(5,0) NOT NULL,
    inventoryamt numeric(11,2) NOT NULL,
    netamt numeric(11,2) NOT NULL,
    flatdisc numeric(11,2) NOT NULL,
    misccharges numeric(11,2) NOT NULL,
    salestax numeric(11,2) NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_saleretsummary SELECT CASE srledger.srcatcode WHEN 6 THEN v_ln_cashacc WHEN 8 THEN v_ln_cashacc ELSE srledger.custcode END, coalesce((sum((((((srdetail.looseqty + (srdetail.packqty * srdetail.packunits))) * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc)))))) * ((1 - ((.01 * srledger.discperc))))), 0), coalesce(round((((((sum((((((srdetail.looseqty + (srdetail.packqty * srdetail.packunits))) * srdetail.srprice)) * ((1 - ((.01 * srdetail.discperc)))))) * ((1 - ((.01 * srledger.discperc))))) + srledger.misccharges) + srledger.salestax) - srledger.flatdisc))::numeric, 0), 0), srledger.flatdisc, srledger.misccharges, srledger.salestax FROM dbo.srledger, dbo.srdetail WHERE ((srledger.date <= v_ad_date) AND (srledger.srinvcode = srdetail.srinvcode)) GROUP BY srledger.srinvcode, srledger.custcode, srledger.srcatcode, srledger.date, srledger.discperc, srledger.misccharges, srledger.salestax, srledger.flatdisc;
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(inventoryamt), 0) FROM tmp_lt_saleretsummary AS lt_saleretsummary)) WHERE (lt_accounts.acccode = v_ln_inventoryacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance - (SELECT coalesce(sum(inventoryamt), 0) FROM tmp_lt_saleretsummary AS lt_saleretsummary)) WHERE (lt_accounts.acccode = v_ln_purchaseacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance - (SELECT coalesce(sum(flatdisc), 0) FROM tmp_lt_saleretsummary AS lt_saleretsummary)) WHERE (lt_accounts.acccode = v_ln_salesfixdiscacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(misccharges), 0) FROM tmp_lt_saleretsummary AS lt_saleretsummary)) WHERE (lt_accounts.acccode = v_ln_miscchargesacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(salestax), 0) FROM tmp_lt_saleretsummary AS lt_saleretsummary)) WHERE (lt_accounts.acccode = v_ln_salestaxacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(inventoryamt), 0) FROM tmp_lt_saleretsummary AS lt_saleretsummary)) WHERE (lt_accounts.acccode = v_ln_salesretacc);
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance - (SELECT coalesce(sum(netamt), 0) FROM tmp_lt_saleretsummary AS lt_saleretsummary)) FROM tmp_lt_saleretsummary AS lt_saleretsummary WHERE (lt_accounts.acccode = lt_saleretsummary.acccode);
  DROP TABLE IF EXISTS tmp_lt_saleretsummary;
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum((gldetail.debit - gldetail.credit)), 0) FROM dbo.glheader, dbo.gldetail WHERE (((glheader.date <= v_ad_date) AND (glheader.glvochcode = gldetail.glvochcode)) AND (gldetail.acccode = lt_accounts.acccode)))) WHERE (lt_accounts.acccode IN (SELECT DISTINCT acccode FROM dbo.gldetail));
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(CASE notecatcode WHEN 1 THEN (amount * -1) ELSE notes.amount END), 0) FROM dbo.notes WHERE ((notes.issuedate <= v_ad_date) AND (notes.acccode = lt_accounts.acccode)))) WHERE (lt_accounts.acccode IN (SELECT DISTINCT acccode FROM dbo.notes));
  UPDATE tmp_lt_accounts AS lt_accounts SET currbalance = (lt_accounts.currbalance + (SELECT coalesce(sum(CASE notecatcode WHEN 1 THEN amount ELSE (notes.amount * -1) END), 0) FROM dbo.notes WHERE ((notes.issuedate <= v_ad_date) AND (notes.bankacccode = lt_accounts.acccode)))) WHERE (lt_accounts.acccode IN (SELECT DISTINCT bankacccode FROM dbo.notes));
  OPEN rs1 FOR SELECT accounts.name, subaccounts.name, lt_accounts.currbalance, accounts.acccode FROM dbo.accounts, tmp_lt_accounts AS lt_accounts, dbo.subaccounts WHERE ((accounts.acccode = lt_accounts.acccode) AND (accounts.subcode = subaccounts.subacccode));
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_TransferAccountingVoucher ====
CREATE OR REPLACE FUNCTION dbo.sp_transferaccountingvoucher(srv citext, db citext, owner citext, usercode smallint, INOUT logid integer, OUT return_value integer, OUT rs1 refcursor, OUT rs2 refcursor, OUT rs3 refcursor, OUT rs4 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_usercode smallint;
  v_logid integer;
  v_srcupd citext;
  v_full_table_name citext;
  v_accountname citext;
  v_sqlheader citext;
  v_sqldetail citext;
  v_sql citext;
  v_list citext;
  v_table_id integer;
  v_headercount integer;
  v_tabmaxkey integer;
  v_vouchercode integer;
  v_oldglvochcode integer;
  v_vochcatcode integer;
  v_acccode integer;
  v_thiscount integer;
  v_retcode integer;
  v_importcount integer;
  v_glrowid integer;
  v_errcode integer;
  v_detailcount bigint;
  v_maxutn bigint;
  v_lastutn bigint;
  v_expiry timestamp(3);
  v_changevochtype citext;
  _dq1 text;
  _dq2 text;
  _dq3 text;
  _dq4 text;
  cur_gl1 refcursor;
  _dq5 text;
  _dq6 text;
  _dq7 text;
  _fs integer := -1;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  v_usercode := usercode;
  v_logid := logid;
  -- SET NOCOUNT ON
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  v_sqlheader := (((((('SELECT T.*, OLDGLVochCode=T.GLVochCode INTO GLHTEMP FROM ' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.GLHeader AS T WHERE T.Transferable = ''Y'' and T.Transfered = ''N'' ');
  v_sqldetail := (((((('SELECT T.*, OLDGLVochCode=T.GLVochCode INTO GLDTEMP FROM ' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.GLDetail AS T WHERE T.GLVochCode IN (SELECT GLVochCode FROM GLHTEMP)');
  v_srcupd := (((((((('UPDATE ' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.GLHeader SET TRANSFERED=''Y'', TRANSFEREDON = localtimestamp(3), TRANSFEREDBY = ') || ltrim(rtrim(dbo.tsql_str((v_usercode)::numeric)))) || ' WHERE GLVochCode IN (SELECT GLVochCode=OLDGLVochCode FROM GLHTEMP WHERE GLVochCode >= 0)');
  _dq1 := v_sqlheader;
  IF _dq1 IS NOT NULL THEN
    IF _dq1 ~* '^[[:space:]]*select' THEN OPEN rs1 FOR EXECUTE dbo.tsql_dyn(_dq1); ELSE EXECUTE dbo.tsql_dyn(_dq1); END IF;
  END IF;
  v_errcode := 0;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Error Fetching The Required Accounting Vouchers From Source/Parent Database';
    return_value := -1;
    logid := v_logid;
    RETURN;
  END IF;
  v_headercount := coalesce((SELECT coalesce(count(*), 0) FROM dbo.glhtemp), 0);
  v_errcode := 0;
  IF (((0 <> 0) OR (v_errcode <> 0)) OR (v_headercount <= 0)) THEN
    return_value := 0;
    logid := v_logid;
    RETURN;
  END IF;
  _dq2 := v_sqldetail;
  IF _dq2 IS NOT NULL THEN
    IF _dq2 ~* '^[[:space:]]*select' THEN OPEN rs2 FOR EXECUTE dbo.tsql_dyn(_dq2); ELSE EXECUTE dbo.tsql_dyn(_dq2); END IF;
  END IF;
  v_errcode := 0;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem in fetching Accounting Vouchers Detail';
    return_value := -1;
    logid := v_logid;
    RETURN;
  END IF;
  v_detailcount := coalesce((SELECT coalesce(count(*), 0) FROM dbo.gldtemp), 0);
  v_errcode := 0;
  IF (((0 <> 0) OR (v_errcode <> 0)) OR (v_detailcount <= 0)) THEN
    RAISE EXCEPTION 'Problem in fetching Accounting Vouchers Detail';
    return_value := -1;
    logid := v_logid;
    RETURN;
  END IF;
  v_changevochtype := ' UPDATE GLHTEMP SET VochCatCode = CASE WHEN VochCatCode <= 5 THEN VochCatCode WHEN VochCatCode = 12 THEN 2 WHEN VochCatCode = 13 THEN 4 WHEN VochCatCode = 15 THEN 1 WHEN VochCatCode = 16 THEN 3 ELSE 5 END  ';
  _dq3 := v_changevochtype;
  IF _dq3 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq3);
  END IF;
  v_errcode := 0;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem in transformation of a/c vouchers from invoice based to a/c based';
    return_value := -1;
    logid := v_logid;
    RETURN;
  END IF;
  v_changevochtype := ' UPDATE GLDTEMP SET InvoiceCode=NULL, OutStandingAmt=0, Balance=0  ';
  _dq4 := v_changevochtype;
  IF _dq4 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq4);
  END IF;
  v_errcode := 0;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem in transformation of a/c vouchers from invoice based to a/c based';
    return_value := -1;
    logid := v_logid;
    RETURN;
  END IF;
  SELECT r.return_value, r.key INTO v_errcode, v_logid FROM dbo.sp_gettabmaxkey(tabname => 'datatransferlog', key => v_logid) AS r;
  v_errcode := 0;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem in generating data transfer log';
    return_value := -1;
    logid := v_logid;
    RETURN;
  END IF;
  SELECT r.return_value, r.lbi_maxutn INTO v_errcode, v_maxutn FROM dbo.sp_maxutn(lbi_rows => v_detailcount, lbi_maxutn => v_maxutn) AS r;
  IF ((v_errcode <> 0) AND (0 <> 0)) THEN
    RAISE EXCEPTION 'Problem in generating GL UTN';
    return_value := -1;
    logid := v_logid;
    RETURN;
  END IF;
  v_errcode := 0;
  v_lastutn := (v_maxutn - v_detailcount);
  OPEN cur_gl1 FOR SELECT glvochcode, vochcatcode FROM dbo.glhtemp ORDER BY glvochcode;
  FETCH NEXT FROM cur_gl1 INTO v_oldglvochcode, v_vochcatcode;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    v_thiscount := 0;
    UPDATE dbo.gldtemp SET glvochcode = -1000 WHERE (oldglvochcode = v_oldglvochcode);
    v_thiscount := coalesce((SELECT count(oldglvochcode) FROM dbo.gldtemp WHERE (oldglvochcode = v_oldglvochcode)), 0);
    IF (v_thiscount = 0) THEN
      UPDATE dbo.glhtemp SET glvochcode = -1000 WHERE (oldglvochcode = v_oldglvochcode);
    ELSE
      SELECT r.return_value, r.key INTO v_errcode, v_tabmaxkey FROM dbo.sp_gettabmaxkey(tabname => 'glheader', key => v_tabmaxkey) AS r;
      IF ((0 <> 0) OR (v_errcode <> 0)) THEN
        CLOSE cur_gl1;
        -- DEALLOCATE GL1
        return_value := -1;
        logid := v_logid;
        RETURN;
      END IF;
      SELECT r.return_value, r.ai_vouchercode INTO v_errcode, v_vouchercode FROM dbo.sp_getvouchercode(ai_vochcatcode => v_vochcatcode, ai_vouchercode => v_vouchercode) AS r;
      IF ((0 <> 0) OR (v_errcode <> 0)) THEN
        RAISE EXCEPTION 'Voucher Code Generation Problem';
        CLOSE cur_gl1;
        -- DEALLOCATE GL1
        return_value := -1;
        logid := v_logid;
        RETURN;
      END IF;
      UPDATE dbo.glhtemp SET glvochcode = v_tabmaxkey, vouchercode = v_vouchercode, salesmancode = v_usercode, modifiedby = NULL, posted = 'N', postedby = NULL, transferable = 'N', transfered = 'N', transferedby = NULL, transferedon = NULL, imported = 'Y', importedby = v_usercode WHERE (oldglvochcode = v_oldglvochcode);
      UPDATE dbo.gldtemp SET glvochcode = v_tabmaxkey WHERE (oldglvochcode = v_oldglvochcode);
    END IF;
    FETCH NEXT FROM cur_gl1 INTO v_oldglvochcode, v_vochcatcode;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_gl1;
  -- DEALLOCATE GL1
  v_importcount := coalesce((SELECT count(*) FROM dbo.glhtemp WHERE (glhtemp.glvochcode >= 0)), 0);
  IF (v_importcount > 0) THEN
    -- SET XACT_ABORT ON
    _dq5 := v_srcupd;
    IF _dq5 IS NOT NULL THEN
      EXECUTE dbo.tsql_dyn(_dq5);
    END IF;
    v_errcode := 0;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Unable To update the transfer status at source/parent database';
      return_value := -1;
      logid := v_logid;
      RETURN;
    END IF;
    -- SET XACT_ABORT OFF
    v_list := '';
    SELECT r.return_value, r.list INTO v_errcode, v_list FROM dbo.sp_columnlist(owner => v_owner, "table" => 'GLHeader', list => v_list) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Unable To update accounting voucher header';
      return_value := -1;
      logid := v_logid;
      RETURN;
    END IF;
    v_sql := ((((('INSERT INTO DBO.GLHeader ( ' || v_list) || ' ) ') || 'SELECT ') || v_list) || ' FROM GLHTEMP WHERE GLHTEMP.GLVochCode >= 0');
    _dq6 := v_sql;
    IF _dq6 IS NOT NULL THEN
      IF _dq6 ~* '^[[:space:]]*select' THEN OPEN rs3 FOR EXECUTE dbo.tsql_dyn(_dq6); ELSE EXECUTE dbo.tsql_dyn(_dq6); END IF;
    END IF;
    v_errcode := 0;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Unable To update accounting voucher header';
      return_value := -1;
      logid := v_logid;
      RETURN;
    END IF;
    v_list := '';
    SELECT r.return_value, r.list INTO v_errcode, v_list FROM dbo.sp_columnlist(owner => v_owner, "table" => 'GLDetail', list => v_list) AS r;
    v_errcode := 0;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Unable To update accounting voucher detail';
      return_value := -1;
      logid := v_logid;
      RETURN;
    END IF;
    v_sql := ((((('INSERT INTO DBO.GLDETAIL ( ' || v_list) || ' ) ') || 'SELECT ') || v_list) || ' FROM GLDTEMP WHERE GLDTEMP.GLVochCode >= 0');
    _dq7 := v_sql;
    IF _dq7 IS NOT NULL THEN
      IF _dq7 ~* '^[[:space:]]*select' THEN OPEN rs4 FOR EXECUTE dbo.tsql_dyn(_dq7); ELSE EXECUTE dbo.tsql_dyn(_dq7); END IF;
    END IF;
    v_errcode := 0;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Unable To update accounting voucher detail';
      return_value := -1;
      logid := v_logid;
      RETURN;
    END IF;
  END IF;
  IF ((0 = 0) AND (v_errcode = 0)) THEN
    INSERT INTO dbo.datatransferlog (transferlogid, logdate, transferedby, invoicecode, invoicetype, date, acccode, sgcode, dgcode, status) SELECT v_logid, localtimestamp(3) AS logdate, v_usercode AS transferedby, oldglvochcode AS invoicecode, 0 AS invoicetype, localtimestamp(3) AS date, acccode AS acccode, NULL::smallint, NULL::smallint, CASE glvochcode WHEN -1000 THEN 0 ELSE 1 END AS status FROM dbo.glhtemp;
    INSERT INTO dbo.datatransferlogdetail (transferlogid, invoicecode, invoicetype, icode, gcode, batch, expiry, qty, bonusqty, price, status) SELECT v_logid, oldglvochcode AS invoicecode, 0 AS invoicetype, acccode AS icode, NULL::smallint AS gcode, NULL::citext AS batch, NULL::timestamp(3) AS expiry, (debit - credit) AS qty, 0 AS bonusqty, 1 AS purprice, CASE glvochcode WHEN -1000 THEN 0 ELSE 1 END AS status FROM dbo.gldtemp;
  END IF;
  DROP TABLE IF EXISTS dbo.glhtemp;
  DROP TABLE IF EXISTS dbo.gldtemp;
  IF ((0 = 0) AND (v_errcode = 0)) THEN
    return_value := 0;
    logid := v_logid;
    RETURN;
  ELSE
    RAISE EXCEPTION 'Unable To successfully transfer accounting voucher';
  END IF;
  return_value := -1;
  logid := v_logid;
  RETURN;
  return_value := 0;
  logid := v_logid;
  RETURN;
END
$body$;

-- ==== proc SP_TransferBasicData ====
CREATE OR REPLACE FUNCTION dbo.sp_transferbasicdata(srv citext, db citext, owner citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_lastdatetime timestamp(3);
  v_tablename citext;
  v_full_table_name citext;
  v_con citext;
  v_colname citext;
  v_whr citext;
  v_from citext;
  v_pkcond citext;
  v_notin citext;
  v_in citext;
  v_endd citext;
  v_maxcol citext;
  v_tabmaxsql citext;
  v_sql citext;
  v_list citext;
  v_autoinsert citext;
  v_autoupdate citext;
  v_autodelete citext;
  v_updmaxkey citext;
  v_table_id integer;
  v_err integer;
  v_priority smallint;
  v_keyseq smallint;
  v_position smallint;
  v_del citext;
  v_del_qry citext;
  v_ins citext;
  v_ins_qry citext;
  v_upd citext;
  v_setpart citext;
  v_upd_pkcond citext;
  v_upd_qry citext;
  cur_tmpcrs1 refcursor;
  cur_tmpcrs2 refcursor;
  _dq1 text;
  cur_tmpcrs3 refcursor;
  _dq2 text;
  _dq3 text;
  _dq4 text;
  _dq5 text;
  _fs integer := -1;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  IF ((ltrim(rtrim(v_srv)))::citext = '') THEN
    v_from := ((((' FROM ' || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.');
  ELSE
    v_from := ((((((' FROM ' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.');
  END IF;
  v_notin := ' NOT IN (SELECT ';
  v_con := 'CONVERT(VarChar(10),';
  v_sql := 'SELECT ';
  v_in := ' IN (SELECT ';
  v_whr := 'WHERE ';
  v_endd := ' AS T WHERE ';
  v_lastdatetime := coalesce((SELECT serverdatatime FROM dbo.datatransferdate), '1900-01-01 00:00:00');
  v_del := 'DELETE ';
  v_upd := 'UPDATE ';
  v_setpart := 'SET ';
  v_ins := 'INSERT INTO ';
  OPEN cur_tmpcrs1 FOR SELECT ltrim(rtrim(tablename)) AS tablename, priority, autoinsert, autoupdate, autodelete, updatetabmaxkey FROM dbo.transferabledata WHERE (enable = 'Y') ORDER BY priority;
  FETCH NEXT FROM cur_tmpcrs1 INTO v_tablename, v_priority, v_autoinsert, v_autoupdate, v_autodelete, v_updmaxkey;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    v_full_table_name := ((ltrim(rtrim(v_owner)) || '.') || v_tablename);
    -- SET @table_id = OBJECT_ID(@full_table_name)
    RAISE EXCEPTION 'untranslated T-SQL (OBJECT_ID of non-literal)' USING ERRCODE = '0A000';
    v_err := 0;
    IF (((0 <> 0) OR (v_err <> 0)) OR (v_table_id IS NULL)) THEN
      RAISE EXCEPTION 'Data Updation: Invalid Object Refered: Name = %', v_full_table_name;
      CLOSE cur_tmpcrs1;
      -- DEALLOCATE TmpCrs1
      return_value := -1;
      RETURN;
    END IF;
    v_pkcond := '';
    v_maxcol := '';
    v_upd_pkcond := '';
    -- OPEN TmpCrs2
    RAISE EXCEPTION 'untranslated T-SQL (system table sysindexes)' USING ERRCODE = '0A000';
    FETCH NEXT FROM cur_tmpcrs2 INTO v_colname, v_keyseq;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    WHILE (_fs = 0) LOOP
      IF (v_keyseq <> 1) THEN
        v_pkcond := (v_pkcond || ' + ');
        v_upd_pkcond := (v_upd_pkcond || ' AND ');
      END IF;
      v_pkcond := ((((v_pkcond || ' ') || v_con) || ltrim(rtrim(v_colname))) || ')');
      v_upd_pkcond := ((((((v_upd_pkcond || ' T.') || ltrim(rtrim(v_colname))) || ' = ') || v_tablename) || '.') || ltrim(rtrim(v_colname)));
      v_maxcol := (('MAX(' || rtrim(ltrim(v_colname))) || ')');
      FETCH NEXT FROM cur_tmpcrs2 INTO v_colname, v_keyseq;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    END LOOP;
    CLOSE cur_tmpcrs2;
    -- DEALLOCATE TmpCrs2
    IF (v_autodelete = 'Y') THEN
      v_del_qry := (((((((((v_del || v_tablename) || ' ') || v_whr) || v_pkcond) || v_notin) || v_pkcond) || v_from) || v_tablename) || ')');
      _dq1 := v_del_qry;
      IF _dq1 IS NOT NULL THEN
        EXECUTE dbo.tsql_dyn(_dq1);
      END IF;
      v_err := 0;
      IF (v_err <> 0) THEN
        RAISE EXCEPTION 'Data Deletion: Error Transfering % Data', v_full_table_name;
        CLOSE cur_tmpcrs1;
        -- DEALLOCATE TmpCrs1
        return_value := -1;
        RETURN;
      END IF;
    END IF;
    IF (v_autoupdate = 'Y') THEN
      v_setpart := 'SET ';
      -- OPEN TmpCrs3
      RAISE EXCEPTION 'untranslated T-SQL (system table sysobjects)' USING ERRCODE = '0A000';
      FETCH NEXT FROM cur_tmpcrs3 INTO v_colname, v_position;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
      WHILE (_fs = 0) LOOP
        -- IF ColumnProperty (@table_id, @ColName, 'IsIdentity') <> 1
        -- 			BEGIN
        -- 				IF @ColName = (SELECT columnname FROM TransferableData_RestrictedColumns WHERE columnname = @ColName and tablename = @TableName)
        -- 				BEGIN
        -- 					SET @ColName = @ColName
        -- 				END
        -- 				ELSE
        -- 				BEGIN
        -- 					IF @SETPART <> 'SET '
        -- 					BEGIN
        -- 						SET @SETPART = @SETPART + ','
        -- 					END
        -- 
        -- 					SET @SETPART = @SETPART + LTRIM(RTRIM(@ColName)) + '=' + 'T.' +  LTRIM(RTRIM(@ColName))
        -- 				END
        -- 			END
        RAISE EXCEPTION 'untranslated T-SQL (function ColumnProperty)' USING ERRCODE = '0A000';
        FETCH NEXT FROM cur_tmpcrs3 INTO v_colname, v_position;
        IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
      END LOOP;
      CLOSE cur_tmpcrs3;
      -- DEALLOCATE TmpCrs3
      IF (v_setpart <> 'SET ') THEN
        v_upd_qry := (((((((((v_upd || v_tablename) || ' ') || v_setpart) || ' ') || v_from) || v_tablename) || v_endd) || ' ') || v_upd_pkcond);
        _dq2 := v_upd_qry;
        IF _dq2 IS NOT NULL THEN
          EXECUTE dbo.tsql_dyn(_dq2);
        END IF;
        v_err := 0;
        IF ((0 <> 0) OR (v_err <> 0)) THEN
          RAISE EXCEPTION 'Data Updation: Error Transfering % Data', v_full_table_name;
          CLOSE cur_tmpcrs1;
          -- DEALLOCATE TmpCrs1
          return_value := -1;
          RETURN;
        END IF;
      END IF;
    END IF;
    IF ((v_autoinsert = 'Y') AND (v_tablename <> 'Rights')) THEN
      v_sql := ' SELECT ';
      v_list := '';
      SELECT r.return_value, r.list INTO v_err, v_list FROM dbo.sp_columnlist(owner => v_owner, "table" => v_tablename, list => v_list) AS r;
      v_err := 0;
      IF ((0 <> 0) OR (v_err <> 0)) THEN
        CLOSE cur_tmpcrs1;
        -- DEALLOCATE TmpCrs1
        return_value := -1;
        RETURN;
      END IF;
      IF (v_tablename = 'GroupRights') THEN
        v_ins_qry := (((((((((((((((v_ins || v_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_list) || v_from) || v_tablename) || v_endd) || v_pkcond) || v_notin) || v_pkcond) || ' FROM ') || v_tablename) || ')  AND RightCode IN (SELECT RightCode FROM Rights)');
      ELSE
        v_ins_qry := (((((((((((((((v_ins || v_tablename) || ' (') || v_list) || ' )  ') || v_sql) || v_list) || v_from) || v_tablename) || v_endd) || v_pkcond) || v_notin) || v_pkcond) || ' FROM ') || v_tablename) || ')');
      END IF;
      _dq3 := v_ins_qry;
      IF _dq3 IS NOT NULL THEN
        EXECUTE dbo.tsql_dyn(_dq3);
      END IF;
      v_err := 0;
      IF ((0 <> 0) OR (v_err <> 0)) THEN
        RAISE EXCEPTION 'Data Insertion: Error Transfering % Data', v_full_table_name;
        CLOSE cur_tmpcrs1;
        -- DEALLOCATE TmpCrs1
        return_value := -1;
        RETURN;
      END IF;
    END IF;
    IF (v_updmaxkey = 'Y') THEN
      v_tabmaxsql := '';
      v_tabmaxsql := (((((((('UPDATE _tabmaxkey SET TABMAXKEY = ' || ' COALESCE((SELECT ') || v_maxcol) || ' FROM  ') || rtrim(ltrim(v_tablename))) || '), 0) ') || 'WHERE TABNAME = ''') || rtrim(ltrim(v_tablename))) || '''');
      _dq4 := v_tabmaxsql;
      IF _dq4 IS NOT NULL THEN
        EXECUTE dbo.tsql_dyn(_dq4);
      END IF;
      v_err := 0;
      IF ((0 <> 0) OR (v_err <> 0)) THEN
        RAISE EXCEPTION 'Data Insertion: Error While Updating the TABMAXKEY of % ', v_full_table_name;
        CLOSE cur_tmpcrs1;
        -- DEALLOCATE TmpCrs1
        return_value := -1;
        RETURN;
      END IF;
    END IF;
    FETCH NEXT FROM cur_tmpcrs1 INTO v_tablename, v_priority, v_autoinsert, v_autoupdate, v_autodelete, v_updmaxkey;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_tmpcrs1;
  -- DEALLOCATE TmpCrs1
  DELETE FROM dbo.datatransferdate;
  IF ((ltrim(rtrim(v_srv)))::citext = '') THEN
    v_ins_qry := ((((('INSERT INTO DataTransferDate (ServerDataTime) SELECT ServerDataTime = COALESCE((SELECT localtimestamp(3) - 0.042 FROM ' || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '._UTN)') || ', localtimestamp(3))');
  ELSE
    v_ins_qry := ((((((('INSERT INTO DataTransferDate (ServerDataTime) SELECT ServerDataTime = COALESCE((SELECT localtimestamp(3) - 0.042 FROM ' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '._UTN)') || ', localtimestamp(3))');
  END IF;
  _dq5 := v_ins_qry;
  IF _dq5 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq5);
  END IF;
  v_err := 0;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Data Transfer: Error While recoridng data transfer date';
    return_value := -1;
    RETURN;
  END IF;
  INSERT INTO dbo.dataimportlog (logdate, importedby, importtype, remarks) VALUES (localtimestamp(3), 1, 'Data Synchronization', ((v_srv || ' DB:') || v_db));
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_TransferInterGodownTransfers ====
CREATE OR REPLACE FUNCTION dbo.sp_transferintergodowntransfers(srv citext, db citext, owner citext, usercode smallint, INOUT logid integer, OUT return_value integer, OUT rs1 refcursor, OUT rs2 refcursor, OUT rs3 refcursor, OUT rs4 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_usercode smallint;
  v_logid integer;
  v_srcupd citext;
  v_batch citext;
  v_errortext citext;
  v_itemname citext;
  v_sqlheader citext;
  v_sqldetail citext;
  v_sql citext;
  v_list citext;
  v_headercount integer;
  v_tabmaxkey integer;
  v_headertabmaxkey integer;
  v_headercode integer;
  v_errcode integer;
  v_oldinvcode integer;
  v_ttcode integer;
  v_icode integer;
  v_gcode integer;
  v_thiscount integer;
  v_retcode integer;
  v_importcount integer;
  v_sgcode integer;
  v_dgcode integer;
  v_id integer;
  v_packunits integer;
  v_insercount integer;
  v_qty numeric(15,4);
  v_reqqty numeric(15,4);
  v_tqty numeric(15,4);
  v_sourcestock numeric(15,4);
  v_targetstock numeric(15,4);
  v_newstock numeric(15,4);
  v_batchstock numeric(15,4);
  v_reorderqty integer;
  v_optimumqty integer;
  v_detailcount bigint;
  v_maxutn bigint;
  v_expiry timestamp(3);
  v_purprice numeric(15,5);
  v_saleprice numeric(15,5);
  v_discperc double precision;
  v_rpp numeric(15,5);
  v_avgprice numeric(15,5);
  _dq1 text;
  _dq2 text;
  cur_tran1 refcursor;
  cur_tran2 refcursor;
  _r3 record;
  cur_tran3 refcursor;
  _dq4 text;
  _dq5 text;
  _dq6 text;
  _rc integer;
  _fs integer := -1;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  v_usercode := usercode;
  v_logid := logid;
  -- SET NOCOUNT ON
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  v_sqlheader := (((((('SELECT T.*, OLDINVCODE=T.TRANSCODE INTO THTEMP FROM ' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.THeader AS T WHERE T.Transferable = ''Y'' and T.Transfered = ''N'' ');
  _rc := 1;
  v_sqldetail := (((((('SELECT T.*, OLDINVCODE=T.TRANSCODE, ID2=0 INTO TDTEMP FROM ' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.TDetail AS T WHERE T.TRANSCODE IN (SELECT TRANSCODE FROM THTEMP) ORDER BY T.ID');
  _rc := 1;
  v_srcupd := (((((((('UPDATE ' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.THeader SET TRANSFERED=''Y'', TRANSFEREDON = localtimestamp(3), TRANSFEREDBY = ') || ltrim(rtrim(dbo.tsql_str((v_usercode)::numeric)))) || ' WHERE TRANSCODE IN (SELECT OLDINVCODE FROM THTEMP WHERE TRANSCODE >= 0)');
  _rc := 1;
  _dq1 := v_sqlheader;
  IF _dq1 IS NOT NULL THEN
    IF _dq1 ~* '^[[:space:]]*select' THEN OPEN rs1 FOR EXECUTE dbo.tsql_dyn(_dq1); ELSE EXECUTE dbo.tsql_dyn(_dq1); END IF;
  END IF;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_errcode := 0;
  _rc := 1;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Error Fetching The Required Inter Godown Transfers From Source Database';
    return_value := -1;
    logid := v_logid;
    RETURN;
  END IF;
  v_headercount := (SELECT coalesce(count(*), 0) FROM dbo.thtemp);
  _rc := 1;
  v_errcode := 0;
  _rc := 1;
  IF (((0 <> 0) OR (v_errcode <> 0)) OR (v_headercount <= 0)) THEN
    return_value := 0;
    logid := v_logid;
    RETURN;
  END IF;
  _dq2 := v_sqldetail;
  IF _dq2 IS NOT NULL THEN
    IF _dq2 ~* '^[[:space:]]*select' THEN OPEN rs2 FOR EXECUTE dbo.tsql_dyn(_dq2); ELSE EXECUTE dbo.tsql_dyn(_dq2); END IF;
  END IF;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_errcode := 0;
  _rc := 1;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem in fetching Inter Godown Transfers Detail';
    return_value := -1;
    logid := v_logid;
    RETURN;
  END IF;
  v_detailcount := (SELECT coalesce(count(*), 0) FROM dbo.tdtemp);
  _rc := 1;
  v_errcode := 0;
  _rc := 1;
  IF (((0 <> 0) OR (v_errcode <> 0)) OR (v_detailcount <= 0)) THEN
    RAISE EXCEPTION 'Problem in fetching Transfer Invoices Detail';
    return_value := -1;
    logid := v_logid;
    RETURN;
  END IF;
  SELECT r.return_value, r.key INTO v_errcode, v_logid FROM dbo.sp_gettabmaxkey(tabname => 'datatransferlog', key => v_logid) AS r;
  v_errcode := 0;
  _rc := 1;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem in generating data transfer log';
    return_value := -1;
    logid := v_logid;
    RETURN;
  END IF;
  DROP TABLE IF EXISTS dbo.tdtemp2;
  CREATE TABLE dbo.tdtemp2 AS SELECT * FROM (SELECT * FROM dbo.tdtemp WHERE (transcode < 0) UNION SELECT * FROM dbo.tdtemp WHERE (transcode < 0)) AS a;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((0 <> 0) OR (_rc > 0)) THEN
    RAISE EXCEPTION 'Problem in generating transfer invoice(s) number';
    return_value := -1;
    logid := v_logid;
    RETURN;
  END IF;
  v_errcode := 0;
  _rc := 1;
  OPEN cur_tran1 FOR SELECT oldinvcode, ttcode, sgcode, dgcode, coalesce(headerno, 1) AS headerno FROM dbo.thtemp ORDER BY oldinvcode;
  FETCH NEXT FROM cur_tran1 INTO v_oldinvcode, v_ttcode, v_sgcode, v_dgcode, v_headercode;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    v_thiscount := 0;
    _rc := 1;
    OPEN cur_tran2 FOR SELECT icode, max(id) AS id, sum(qty), max(coalesce(reorderqty, 0)) AS reorderqty, max(coalesce(optimumqty, 0)) AS optimumqty FROM dbo.tdtemp WHERE (oldinvcode = v_oldinvcode) GROUP BY icode ORDER BY id, icode;
    FETCH NEXT FROM cur_tran2 INTO v_icode, v_id, v_qty, v_reorderqty, v_optimumqty;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    WHILE (_fs = 0) LOOP
      IF (v_qty > 0) THEN
        v_itemname := coalesce((SELECT name FROM dbo.item WHERE (icode = v_icode)), '');
        _rc := 1;
        v_avgprice := 0;
        _rc := 1;
        v_sourcestock := 0;
        _rc := 1;
        v_targetstock := 0;
        _rc := 1;
        SELECT r.return_value, r.avgprice INTO v_errcode, v_avgprice FROM dbo.sp_getitemavgprice(icode => v_icode, avgprice => v_avgprice) AS r;
        IF ((0 <> 0) OR (v_errcode <> 0)) THEN
          RAISE EXCEPTION 'Unable to fetch item average price, transfer # = %, item = (%)', v_oldinvcode, v_itemname;
          CLOSE cur_tran2;
          -- DEALLOCATE tran2
          CLOSE cur_tran1;
          -- DEALLOCATE tran1
          return_value := -1;
          logid := v_logid;
          RETURN;
        END IF;
        SELECT r.qty INTO v_targetstock FROM dbo.sp_getitemstocktotal(gcode => v_dgcode, icode => v_icode, qty => v_targetstock) AS r;
        IF (0 <> 0) THEN
          RAISE EXCEPTION 'Unable to fetch stock for target/destination godown, transfer # = %, Item = (%)', v_oldinvcode, v_itemname;
          CLOSE cur_tran2;
          -- DEALLOCATE tran2
          CLOSE cur_tran1;
          -- DEALLOCATE tran1
          return_value := -1;
          logid := v_logid;
          RETURN;
        END IF;
        SELECT r.qty INTO v_sourcestock FROM dbo.sp_getitemstocktotal(gcode => v_sgcode, icode => v_icode, qty => v_sourcestock) AS r;
        IF (0 <> 0) THEN
          RAISE EXCEPTION 'Unable to fetch stock for source godown, transfer # = %, Item = (%)', v_oldinvcode, v_itemname;
          CLOSE cur_tran2;
          -- DEALLOCATE tran2
          CLOSE cur_tran1;
          -- DEALLOCATE tran1
          return_value := -1;
          logid := v_logid;
          RETURN;
        END IF;
        _rc := 0;
        FOR _r3 IN SELECT coalesce(purprice, 0) AS c1, coalesce(saleprice, 0) AS c2, coalesce(packunits, 0) AS c3 FROM dbo.item WHERE (icode = v_icode) LOOP
          _rc := _rc + 1;
          v_purprice := _r3.c1;
          v_saleprice := _r3.c2;
          v_packunits := _r3.c3;
        END LOOP;
        IF (_rc = 0) THEN
          RAISE EXCEPTION 'Unable to fetch item packunits, purchase and sale prices. Transfer # = %, Item = (%)', v_oldinvcode, v_itemname;
          CLOSE cur_tran2;
          -- DEALLOCATE tran2
          CLOSE cur_tran1;
          -- DEALLOCATE tran1
          return_value := -1;
          logid := v_logid;
          RETURN;
        END IF;
        IF (v_qty <= v_sourcestock) THEN
          v_reqqty := v_qty;
          _rc := 1;
          v_insercount := 0;
          _rc := 1;
          v_retcode := 0;
          _rc := 1;
          OPEN cur_tran3 FOR SELECT batch, expiry, currqty FROM dbo.godowndetail WHERE ((godowndetail.gcode = v_sgcode) AND (godowndetail.icode = v_icode)) ORDER BY priority, expiry, currqty;
          FETCH NEXT FROM cur_tran3 INTO v_batch, v_expiry, v_batchstock;
          IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
          WHILE (_fs = 0) LOOP
            IF (v_batchstock >= v_reqqty) THEN
              v_tqty := v_reqqty;
              _rc := 1;
            ELSE
              v_tqty := v_batchstock;
              _rc := 1;
            END IF;
            v_reqqty := (v_reqqty - v_tqty);
            _rc := 1;
            v_newstock := (v_batchstock - v_tqty);
            _rc := 1;
            IF (v_newstock > 0) THEN
              UPDATE dbo.godowndetail SET currqty = v_newstock WHERE CURRENT OF cur_tran3;
              GET DIAGNOSTICS _rc = ROW_COUNT;
              IF (_rc = 0) THEN
                v_retcode := 1;
                _rc := 1;
              END IF;
            ELSE
              IF (v_newstock = 0) THEN
                DELETE FROM dbo.godowndetail WHERE CURRENT OF cur_tran3;
                GET DIAGNOSTICS _rc = ROW_COUNT;
                IF (_rc = 0) THEN
                  v_retcode := 1;
                  _rc := 1;
                END IF;
              ELSE
                v_retcode := 1;
                _rc := 1;
              END IF;
            END IF;
            IF (v_retcode = 0) THEN
              SELECT r.return_value INTO v_retcode FROM dbo.sp_updategodowndetail(gcode => v_dgcode, icode => v_icode, batch => v_batch, expiry => v_expiry, qty => v_tqty) AS r;
              IF ((0 <> 0) OR (v_retcode <> 0)) THEN
                CLOSE cur_tran3;
                -- DEALLOCATE tran3
                CLOSE cur_tran2;
                -- DEALLOCATE tran2
                CLOSE cur_tran1;
                -- DEALLOCATE tran1
                return_value := -1;
                logid := v_logid;
                RETURN;
              END IF;
              SELECT r.return_value, r.lbi_maxutn INTO v_errcode, v_maxutn FROM dbo.sp_maxutn(lbi_rows => (1)::bigint, lbi_maxutn => v_maxutn) AS r;
              IF ((v_errcode <> 0) AND (0 <> 0)) THEN
                CLOSE cur_tran3;
                -- DEALLOCATE tran3
                CLOSE cur_tran2;
                -- DEALLOCATE tran2
                CLOSE cur_tran1;
                -- DEALLOCATE tran1
                return_value := -1;
                logid := v_logid;
                RETURN;
              END IF;
              v_insercount := (v_insercount + 1);
              _rc := 1;
              INSERT INTO dbo.tdtemp2 SELECT * FROM dbo.tdtemp WHERE (id = v_id);
              GET DIAGNOSTICS _rc = ROW_COUNT;
              IF ((0 <> 0) OR (_rc = 0)) THEN
                RAISE EXCEPTION 'Unable to Insert Row for Transfer # = %, Item = (%)', v_oldinvcode, v_itemname;
                CLOSE cur_tran3;
                -- DEALLOCATE tran3
                CLOSE cur_tran2;
                -- DEALLOCATE tran2
                CLOSE cur_tran1;
                -- DEALLOCATE tran1
                return_value := -1;
                logid := v_logid;
                RETURN;
              END IF;
              UPDATE dbo.tdtemp2 SET id2 = v_insercount, batch = v_batch, expiry = v_expiry, qty = v_tqty, avgprice = v_avgprice, purprice = v_purprice, saleprice = v_saleprice, packunits = v_packunits, sourcestock = v_sourcestock, targetstock = v_targetstock, requiredqty = v_qty, transferutn = v_maxutn WHERE ((id = v_id) AND (id2 = 0));
              GET DIAGNOSTICS _rc = ROW_COUNT;
              IF ((0 <> 0) OR (_rc = 0)) THEN
                RAISE EXCEPTION 'Unable to Update Row for Transfer # = %, Item = (%)', v_oldinvcode, v_itemname;
                CLOSE cur_tran3;
                -- DEALLOCATE tran3
                CLOSE cur_tran2;
                -- DEALLOCATE tran2
                CLOSE cur_tran1;
                -- DEALLOCATE tran1
                return_value := -1;
                logid := v_logid;
                RETURN;
              END IF;
            ELSE
              RAISE EXCEPTION 'Unable to Update stock for Transfer # = %, Item = (%)', v_oldinvcode, v_itemname;
              CLOSE cur_tran3;
              -- DEALLOCATE tran3
              CLOSE cur_tran2;
              -- DEALLOCATE tran2
              CLOSE cur_tran1;
              -- DEALLOCATE tran1
              return_value := -1;
              logid := v_logid;
              RETURN;
            END IF;
            IF (v_retcode <> 0) THEN
              EXIT;
            END IF;
            IF (v_reqqty = 0) THEN
              EXIT;
            END IF;
            FETCH NEXT FROM cur_tran3 INTO v_batch, v_expiry, v_batchstock;
            IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
          END LOOP;
          CLOSE cur_tran3;
          -- DEALLOCATE tran3
        ELSE
          v_retcode := 1;
          _rc := 1;
        END IF;
        IF (v_retcode <> 0) THEN
          UPDATE dbo.tdtemp SET transcode = -1000 WHERE ((oldinvcode = v_oldinvcode) AND (icode = v_icode));
          GET DIAGNOSTICS _rc = ROW_COUNT;
        ELSE
          v_thiscount := (v_thiscount + 1);
          _rc := 1;
        END IF;
      ELSE
        UPDATE dbo.tdtemp SET transcode = -1000 WHERE ((oldinvcode = v_oldinvcode) AND (icode = v_icode));
        GET DIAGNOSTICS _rc = ROW_COUNT;
      END IF;
      FETCH NEXT FROM cur_tran2 INTO v_icode, v_id, v_qty, v_reorderqty, v_optimumqty;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    END LOOP;
    CLOSE cur_tran2;
    -- DEALLOCATE tran2
    IF (v_thiscount = 0) THEN
      UPDATE dbo.thtemp SET transcode = -1000 WHERE (oldinvcode = v_oldinvcode);
      GET DIAGNOSTICS _rc = ROW_COUNT;
    ELSE
      SELECT r.return_value, r.key INTO v_errcode, v_tabmaxkey FROM dbo.sp_gettabmaxkey(tabname => 'theader', key => v_tabmaxkey) AS r;
      IF ((0 <> 0) OR (v_errcode <> 0)) THEN
        CLOSE cur_tran1;
        -- DEALLOCATE tran1
        return_value := -1;
        logid := v_logid;
        RETURN;
      END IF;
      SELECT r.return_value, r.key INTO v_errcode, v_headertabmaxkey FROM dbo.sp_getheadertabmaxkey(headercode => (v_headercode)::smallint, modulecode => (8)::smallint, key => v_headertabmaxkey) AS r;
      IF ((0 <> 0) OR (v_errcode <> 0)) THEN
        CLOSE cur_tran1;
        -- DEALLOCATE tran1
        return_value := -1;
        logid := v_logid;
        RETURN;
      END IF;
      UPDATE dbo.thtemp SET transcode = v_tabmaxkey, headerno = coalesce(v_headercode, 1), headerinvno = v_headertabmaxkey, salesmancode = v_usercode, posted = 'Y', transferable = 'N', transfered = 'N', transferedby = NULL, transferedon = NULL, imported = 'Y', importedby = v_usercode WHERE (oldinvcode = v_oldinvcode);
      GET DIAGNOSTICS _rc = ROW_COUNT;
      UPDATE dbo.tdtemp2 SET transcode = v_tabmaxkey WHERE (oldinvcode = v_oldinvcode);
      GET DIAGNOSTICS _rc = ROW_COUNT;
    END IF;
    FETCH NEXT FROM cur_tran1 INTO v_oldinvcode, v_ttcode, v_sgcode, v_dgcode, v_headercode;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_tran1;
  -- DEALLOCATE tran1
  v_importcount := coalesce((SELECT count(*) FROM dbo.thtemp WHERE (thtemp.transcode >= 0)), 0);
  _rc := 1;
  IF (v_importcount > 0) THEN
    -- SET XACT_ABORT ON
    _dq4 := v_srcupd;
    IF _dq4 IS NOT NULL THEN
      EXECUTE dbo.tsql_dyn(_dq4);
    END IF;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_errcode := 0;
    _rc := 1;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Unable To update the transfer status at source database';
      return_value := -1;
      logid := v_logid;
      RETURN;
    END IF;
    -- SET XACT_ABORT OFF
    v_list := '';
    _rc := 1;
    SELECT r.return_value, r.list INTO v_errcode, v_list FROM dbo.sp_columnlist(owner => v_owner, "table" => 'Theader', list => v_list) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Unable To update the transfer header';
      return_value := -1;
      logid := v_logid;
      RETURN;
    END IF;
    v_sql := ((((('INSERT INTO THEADER ( ' || v_list) || ' ) ') || 'SELECT ') || v_list) || ' FROM THTEMP WHERE THTEMP.TRANSCODE >=0');
    _rc := 1;
    _dq5 := v_sql;
    IF _dq5 IS NOT NULL THEN
      IF _dq5 ~* '^[[:space:]]*select' THEN OPEN rs3 FOR EXECUTE dbo.tsql_dyn(_dq5); ELSE EXECUTE dbo.tsql_dyn(_dq5); END IF;
    END IF;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_errcode := 0;
    _rc := 1;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Unable To update the transfer header';
      return_value := -1;
      logid := v_logid;
      RETURN;
    END IF;
    v_list := '';
    _rc := 1;
    SELECT r.return_value, r.list INTO v_errcode, v_list FROM dbo.sp_columnlist(owner => v_owner, "table" => 'TDetail', list => v_list) AS r;
    v_errcode := 0;
    _rc := 1;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Unable To update the transfer detail';
      return_value := -1;
      logid := v_logid;
      RETURN;
    END IF;
    v_sql := ((((('INSERT INTO TDETAIL ( ' || v_list) || ' ) ') || 'SELECT ') || v_list) || ' FROM TDTEMP2 WHERE TDTEMP2.TRANSCODE >=0 ORDER BY TDTEMP2.ID');
    _rc := 1;
    _dq6 := v_sql;
    IF _dq6 IS NOT NULL THEN
      IF _dq6 ~* '^[[:space:]]*select' THEN OPEN rs4 FOR EXECUTE dbo.tsql_dyn(_dq6); ELSE EXECUTE dbo.tsql_dyn(_dq6); END IF;
    END IF;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_errcode := 0;
    _rc := 1;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Unable To update the transfer detail';
      return_value := -1;
      logid := v_logid;
      RETURN;
    END IF;
  END IF;
  IF ((0 = 0) AND (v_errcode = 0)) THEN
    INSERT INTO dbo.datatransferlog (transferlogid, logdate, transferedby, invoicecode, invoicetype, date, acccode, sgcode, dgcode, status) SELECT v_logid, localtimestamp(3) AS logdate, v_usercode AS transferedby, oldinvcode AS invoicecode, 8 AS invoicetype, localtimestamp(3) AS date, NULL::integer AS acccode, thtemp.sgcode, thtemp.dgcode, CASE transcode WHEN -1000 THEN 0 ELSE 1 END AS status FROM dbo.thtemp;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    INSERT INTO dbo.datatransferlogdetail (transferlogid, invoicecode, invoicetype, icode, gcode, batch, expiry, qty, price, status) SELECT v_logid, oldinvcode AS invoicecode, 8 AS invoicetype, icode, NULL::smallint, batch, expiry, qty, (purprice / CASE packunits WHEN 0 THEN 1 ELSE packunits END) AS price, CASE transcode WHEN -1000 THEN 0 ELSE 1 END AS status FROM dbo.tdtemp;
    GET DIAGNOSTICS _rc = ROW_COUNT;
  END IF;
  DROP TABLE IF EXISTS dbo.thtemp;
  DROP TABLE IF EXISTS dbo.tdtemp;
  DROP TABLE IF EXISTS dbo.tdtemp2;
  IF ((0 = 0) AND (v_errcode = 0)) THEN
    return_value := 0;
    logid := v_logid;
    RETURN;
  ELSE
    RAISE EXCEPTION 'Unable To successfully transfer inter godown transfers';
  END IF;
  return_value := -1;
  logid := v_logid;
  RETURN;
  return_value := 0;
  logid := v_logid;
  RETURN;
END
$body$;

-- ==== proc SP_TransferPurchaseInvoices ====
CREATE OR REPLACE FUNCTION dbo.sp_transferpurchaseinvoices(srv citext, db citext, owner citext, usercode smallint, INOUT logid integer, OUT return_value integer, OUT rs1 refcursor, OUT rs2 refcursor, OUT rs3 refcursor, OUT rs4 refcursor)
  LANGUAGE plpgsql AS $body$
