    logid := v_logid;
    RETURN;
  END IF;
  _dq2 := v_sqldetail;
  IF _dq2 IS NOT NULL THEN
    IF _dq2 ~* '^[[:space:]]*select' THEN OPEN rs2 FOR EXECUTE dbo.tsql_dyn(_dq2); ELSE EXECUTE dbo.tsql_dyn(_dq2); END IF;
  END IF;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_errcode := 0;
  _rc := 1;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem in fetching Purchase Invoices Detail';
    return_value := -1;
    logid := v_logid;
    RETURN;
  END IF;
  v_detailcount := coalesce((SELECT coalesce(count(*), 0) FROM dbo.pdtemp), 0);
  _rc := 1;
  v_errcode := 0;
  _rc := 1;
  IF (((0 <> 0) OR (v_errcode <> 0)) OR (v_detailcount <= 0)) THEN
    RAISE EXCEPTION 'Problem in fetching Purchase Invoices Detail';
    return_value := -1;
    logid := v_logid;
    RETURN;
  END IF;
  SELECT r.return_value, r.key INTO v_errcode, v_logid FROM dbo.sp_gettabmaxkey(tabname => 'datatransferlog', key => v_logid) AS r;
  v_errcode := 0;
  _rc := 1;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem in generating data transfer log';
    return_value := -1;
    logid := v_logid;
    RETURN;
  END IF;
  SELECT r.return_value, r.lbi_maxutn INTO v_errcode, v_maxutn FROM dbo.sp_maxutn(lbi_rows => v_detailcount, lbi_maxutn => v_maxutn) AS r;
  v_errcode := 0;
  _rc := 1;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem in generating purchase invoice(s) number';
    return_value := -1;
    logid := v_logid;
    RETURN;
  END IF;
  v_errcode := 0;
  _rc := 1;
  OPEN cur_pur1 FOR SELECT oldinvcode, purcatcode, discperc, invgstperc1, coalesce(headerno, 1) AS headerno FROM dbo.pltemp ORDER BY oldinvcode;
  FETCH NEXT FROM cur_pur1 INTO v_oldinvcode, v_purcatcode, v_invdiscperc, v_invgstperc1, v_headercode;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    v_thiscount := 0;
    _rc := 1;
    OPEN cur_pur2 FOR SELECT icode, gcode, batch, expiry, purrowid, packqty, looseqty, bonusqty, packunits, purprice, discperc, unitsalestax, gstperc FROM dbo.pdtemp WHERE (oldinvcode = v_oldinvcode) ORDER BY purrowid;
    FETCH NEXT FROM cur_pur2 INTO v_icode, v_gcode, v_batch, v_expiry, v_purrowid, v_packqty, v_looseqty, v_bonusqty, v_packunits, v_purprice, v_discperc, v_unitsaletax, v_gstperc;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    WHILE (_fs = 0) LOOP
      v_itemname := coalesce((SELECT name FROM dbo.item WHERE (icode = v_icode)), '');
      _rc := 1;
      IF ((v_purcatcode = 1) OR (v_purcatcode = 2)) THEN
        v_qty := (((v_packqty + v_bonusqty)) * v_packunits);
        _rc := 1;
        v_itemcost := coalesce((SELECT (((v_packqty * v_purprice) * ((1 - (v_discperc * 0.01)))) * ((1 - (v_invdiscperc * 0.01))))), 0);
        _rc := 1;
        v_rpp := (((round(((((((v_purprice * ((1 - (v_discperc * .01)))) * ((1 - (v_invdiscperc * .01)))) * v_packqty)) / ((v_packqty + v_bonusqty))))::numeric, 2) + v_unitsaletax) + round((((round(((v_purprice * ((1 - (v_discperc * .01)))))::numeric, 2) * v_gstperc) * 0.01))::numeric, 2)) + round((((((round(((v_purprice * ((1 - (v_discperc * .01)))))::numeric, 2) * ((1 - (v_invdiscperc * .01))))) * v_invgstperc1) * 0.01))::numeric, 2));
        _rc := 1;
        v_avgprice := 0;
        _rc := 1;
        v_newavgprice := 0;
        _rc := 1;
        UPDATE dbo.item SET purprice = CASE (SELECT dbo.fn_getpreference('UpdatePurPrice') AS a) WHEN 'Y' THEN coalesce(v_purprice, 0) ELSE coalesce(item.purprice, 0) END, purdiscperc = CASE (SELECT dbo.fn_getpreference('UpdatePurDisc') AS a) WHEN 'Y' THEN coalesce(v_discperc, 0) ELSE coalesce(item.purdiscperc, 0) END, salediscperc = CASE (SELECT dbo.fn_getpreference('PurReplaceItemSaledisc') AS a) WHEN 'Y' THEN CASE (SELECT dbo.fn_get_int_preference('PurReplaceItemSalediscNo') AS a) WHEN 1 THEN coalesce(v_discperc, 0) ELSE coalesce(item.salediscperc, 0) END ELSE coalesce(item.salediscperc, 0) END, salediscperc2 = CASE (SELECT dbo.fn_getpreference('PurReplaceItemSaledisc') AS a) WHEN 'Y' THEN CASE (SELECT dbo.fn_get_int_preference('PurReplaceItemSalediscNo') AS a) WHEN 2 THEN coalesce(v_discperc, 0) ELSE coalesce(item.salediscperc2, 0) END ELSE coalesce(item.salediscperc2, 0) END, salediscperc3 = CASE (SELECT dbo.fn_getpreference('PurReplaceItemSaledisc') AS a) WHEN 'Y' THEN CASE (SELECT dbo.fn_get_int_preference('PurReplaceItemSalediscNo') AS a) WHEN 3 THEN coalesce(v_discperc, 0) ELSE coalesce(item.salediscperc3, 0) END ELSE coalesce(item.salediscperc3, 0) END, salediscperc4 = CASE (SELECT dbo.fn_getpreference('PurReplaceItemSaledisc') AS a) WHEN 'Y' THEN CASE (SELECT dbo.fn_get_int_preference('PurReplaceItemSalediscNo') AS a) WHEN 4 THEN coalesce(v_discperc, 0) ELSE coalesce(item.salediscperc4, 0) END ELSE coalesce(item.salediscperc4, 0) END, salediscperc5 = CASE (SELECT dbo.fn_getpreference('PurReplaceItemSaledisc') AS a) WHEN 'Y' THEN CASE (SELECT dbo.fn_get_int_preference('PurReplaceItemSalediscNo') AS a) WHEN 5 THEN coalesce(v_discperc, 0) ELSE coalesce(item.salediscperc5, 0) END ELSE coalesce(item.salediscperc5, 0) END, recentpurprice5 = coalesce(recentpurprice4, 0), recentpurprice4 = coalesce(recentpurprice3, 0), recentpurprice3 = coalesce(recentpurprice2, 0), recentpurprice2 = coalesce(recentpurprice, 0), recentpurprice = coalesce(v_rpp, 0) WHERE (icode = v_icode);
        GET DIAGNOSTICS _rc = ROW_COUNT;
      ELSE
        v_qty := (v_looseqty + v_bonusqty);
        _rc := 1;
        v_itemcost := coalesce((SELECT (((v_looseqty * v_purprice) * ((1 - (v_discperc * 0.01)))) * ((1 - (v_invdiscperc * 0.01))))), 0);
        _rc := 1;
      END IF;
      SELECT r.return_value, r.avgprice INTO v_errcode, v_avgprice FROM dbo.sp_getitemavgprice(icode => v_icode, avgprice => (v_avgprice)::numeric) AS r;
      IF ((0 <> 0) OR (v_errcode <> 0)) THEN
        CLOSE cur_pur2;
        -- DEALLOCATE pur2
        CLOSE cur_pur1;
        -- DEALLOCATE pur1
        return_value := -1;
        logid := v_logid;
        RETURN;
      END IF;
      SELECT r.qty INTO v_stock FROM dbo.sp_getitemstockall(icode => v_icode, qty => (v_stock)::numeric) AS r;
      IF (0 <> 0) THEN
        v_stock := 0;
        _rc := 1;
      END IF;
      UPDATE dbo.pdtemp SET avgprice = v_avgprice, purutn = v_maxutn, currstock = v_stock, newavgprice = (((((v_avgprice * v_stock)) + (v_itemcost))) / CASE (v_qty + v_stock) WHEN 0 THEN 1 ELSE ((v_qty + v_stock)) END) WHERE (purrowid = v_purrowid);
      GET DIAGNOSTICS _rc = ROW_COUNT;
      IF (_rc = 0) THEN
        RAISE EXCEPTION 'Problem processing purchase invoice # %, item = (%)', v_oldinvcode, v_itemname;
        CLOSE cur_pur2;
        -- DEALLOCATE pur2
        CLOSE cur_pur1;
        -- DEALLOCATE pur1
        return_value := -1;
        logid := v_logid;
        RETURN;
      END IF;
      v_newavgprice := coalesce((SELECT newavgprice FROM dbo.pdtemp WHERE (purrowid = v_purrowid)), 0);
      _rc := 1;
      v_stock := 0;
      _rc := 1;
      PERFORM dbo.sp_updateitemavgprice(icode => v_icode, avgprice => (v_newavgprice)::numeric);
      IF (0 <> 0) THEN
        RAISE EXCEPTION 'Problem in updating item average price on purchase invoice # %, item = (%)', v_oldinvcode, v_itemname;
        CLOSE cur_pur2;
        -- DEALLOCATE pur2
        CLOSE cur_pur1;
        -- DEALLOCATE pur1
        return_value := -1;
        logid := v_logid;
        RETURN;
      END IF;
      SELECT r.return_value, r.qty INTO v_errcode, v_stock FROM dbo.sp_getitemstockbatch(gcode => v_gcode, icode => v_icode, batch => v_batch, expiry => v_expiry, qty => (v_stock)::numeric) AS r;
      IF ((0 <> 0) OR (v_errcode <> 0)) THEN
        CLOSE cur_pur2;
        -- DEALLOCATE pur2
        CLOSE cur_pur1;
        -- DEALLOCATE pur1
        return_value := -1;
        logid := v_logid;
        RETURN;
      END IF;
      v_stock := (v_stock + v_qty);
      _rc := 1;
      SELECT r.return_value INTO v_errcode FROM dbo.sp_updateitemstockbatch(gcode => v_gcode, icode => v_icode, batch => v_batch, expiry => v_expiry, newqty => (v_stock)::numeric) AS r;
      IF ((0 <> 0) OR (v_errcode <> 0)) THEN
        CLOSE cur_pur2;
        -- DEALLOCATE pur2
        CLOSE cur_pur1;
        -- DEALLOCATE pur1
        return_value := -1;
        logid := v_logid;
        RETURN;
      END IF;
      v_maxutn := (v_maxutn + 1);
      _rc := 1;
      UPDATE dbo.pdtemp SET purinvcode = -1000 WHERE (purrowid = v_purrowid);
      GET DIAGNOSTICS _rc = ROW_COUNT;
      v_thiscount := (v_thiscount + 1);
      _rc := 1;
      FETCH NEXT FROM cur_pur2 INTO v_icode, v_gcode, v_batch, v_expiry, v_purrowid, v_packqty, v_looseqty, v_bonusqty, v_packunits, v_purprice, v_discperc, v_unitsaletax, v_gstperc;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    END LOOP;
    CLOSE cur_pur2;
    -- DEALLOCATE pur2
    IF (v_thiscount = 0) THEN
      UPDATE dbo.pltemp SET purinvcode = -1000 WHERE (oldinvcode = v_oldinvcode);
      GET DIAGNOSTICS _rc = ROW_COUNT;
    ELSE
      SELECT r.return_value, r.key INTO v_errcode, v_tabmaxkey FROM dbo.sp_gettabmaxkey(tabname => 'purledger', key => v_tabmaxkey) AS r;
      IF ((0 <> 0) OR (v_errcode <> 0)) THEN
        CLOSE cur_pur1;
        -- DEALLOCATE pur1
        return_value := -1;
        logid := v_logid;
        RETURN;
      END IF;
      SELECT r.return_value, r.key INTO v_errcode, v_headertabmaxkey FROM dbo.sp_getheadertabmaxkey(headercode => (v_headercode)::smallint, modulecode => (3)::smallint, key => v_headertabmaxkey) AS r;
      IF ((0 <> 0) OR (v_errcode <> 0)) THEN
        CLOSE cur_pur1;
        -- DEALLOCATE pur1
        return_value := -1;
        logid := v_logid;
        RETURN;
      END IF;
      UPDATE dbo.pltemp SET purinvcode = v_tabmaxkey, headerno = coalesce(v_headercode, 1), headerinvno = v_headertabmaxkey, pocode = NULL, paymentmode = NULL, paymentacccode = NULL, amt = 0, amtdate = NULL, amtby = NULL, amtreference = NULL, outstandingamt = 0, marked = 'N', salesmancode = v_usercode, modifiedby = NULL, posted = 'Y', postedby = v_usercode, transferable = 'N', transfered = 'N', transferedby = NULL, transferedon = NULL, imported = 'Y', importedby = v_usercode WHERE (oldinvcode = v_oldinvcode);
      GET DIAGNOSTICS _rc = ROW_COUNT;
      UPDATE dbo.pdtemp SET purinvcode = v_tabmaxkey WHERE (oldinvcode = v_oldinvcode);
      GET DIAGNOSTICS _rc = ROW_COUNT;
    END IF;
    FETCH NEXT FROM cur_pur1 INTO v_oldinvcode, v_purcatcode, v_invdiscperc, v_invgstperc1, v_headercode;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_pur1;
  -- DEALLOCATE pur1
  v_importcount := coalesce((SELECT count(*) FROM dbo.pltemp WHERE (pltemp.purinvcode >= 0)), 0);
  _rc := 1;
  IF (v_importcount > 0) THEN
    UPDATE dbo.pltemp AS pltemp SET invtotal = p.net FROM (SELECT pl.purinvcode AS purinvcode, (round((((sum(((((pd.looseqty + pd.packqty) + pd.bonusqty)) * pd.unitsalestax)) + sum(round((((((((pd.looseqty + pd.packqty)) * pd.purprice) * ((1 - ((.01 * pd.discperc))))) * pd.gstperc) * .01))::numeric, 2))) + round((((((sum((((((pd.looseqty + pd.packqty)) * pd.purprice)) * ((1 - ((.01 * pd.discperc)))))) * ((1 - ((.01 * pl.discperc))))) - pl.flatdisc)) * ((pl.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) + round((((((sum(((((pd.looseqty + pd.packqty)) * pd.purprice) * ((1 - ((.01 * pd.discperc)))))) * ((1 - ((.01 * pl.discperc))))) + pl.misccharges) + pl.salestax) - pl.flatdisc))::numeric, 0)) AS net FROM dbo.pltemp AS pl, dbo.pdtemp AS pd WHERE (pl.purinvcode = pd.purinvcode) GROUP BY pl.purinvcode, pl.suppcode, pl.purcatcode, pl.postdate, pl.discperc, pl.misccharges, pl.salestax, pl.flatdisc, pl.invgstperc1) AS p WHERE ((pltemp.purinvcode >= 0) AND (pltemp.purinvcode = p.purinvcode));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    UPDATE dbo.pltemp SET outstandingamt = invtotal WHERE (pltemp.purinvcode >= 0);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    -- SET XACT_ABORT ON
    _dq3 := v_srcupd;
    IF _dq3 IS NOT NULL THEN
      EXECUTE dbo.tsql_dyn(_dq3);
    END IF;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_errcode := 0;
    _rc := 1;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Unable To update the transfer status at source database';
      return_value := -1;
      logid := v_logid;
      RETURN;
    END IF;
    -- SET XACT_ABORT OFF
    v_list := '';
    _rc := 1;
    SELECT r.return_value, r.list INTO v_errcode, v_list FROM dbo.sp_columnlist(owner => v_owner, "table" => 'PurLedger', list => v_list) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Unable To update purchase header';
      return_value := -1;
      logid := v_logid;
      RETURN;
    END IF;
    v_sql := ((((('INSERT INTO PURLEDGER ( ' || v_list) || ' ) ') || 'SELECT ') || v_list) || ' FROM PLTEMP WHERE PLTEMP.PURINVCODE >= 0');
    _rc := 1;
    _dq4 := v_sql;
    IF _dq4 IS NOT NULL THEN
      IF _dq4 ~* '^[[:space:]]*select' THEN OPEN rs3 FOR EXECUTE dbo.tsql_dyn(_dq4); ELSE EXECUTE dbo.tsql_dyn(_dq4); END IF;
    END IF;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_errcode := 0;
    _rc := 1;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Unable To update purchase header';
      return_value := -1;
      logid := v_logid;
      RETURN;
    END IF;
    v_list := '';
    _rc := 1;
    SELECT r.return_value, r.list INTO v_errcode, v_list FROM dbo.sp_columnlist(owner => v_owner, "table" => 'PurDetail', list => v_list) AS r;
    v_errcode := 0;
    _rc := 1;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Unable To update purchase detail';
      return_value := -1;
      logid := v_logid;
      RETURN;
    END IF;
    v_sql := ((((('INSERT INTO PURDETAIL ( ' || v_list) || ' ) ') || 'SELECT ') || v_list) || ' FROM PDTEMP WHERE PDTEMP.PURINVCODE >= 0');
    _rc := 1;
    _dq5 := v_sql;
    IF _dq5 IS NOT NULL THEN
      IF _dq5 ~* '^[[:space:]]*select' THEN OPEN rs4 FOR EXECUTE dbo.tsql_dyn(_dq5); ELSE EXECUTE dbo.tsql_dyn(_dq5); END IF;
    END IF;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_errcode := 0;
    _rc := 1;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Unable To update purchase detail';
      return_value := -1;
      logid := v_logid;
      RETURN;
    END IF;
  END IF;
  IF ((0 = 0) AND (v_errcode = 0)) THEN
    INSERT INTO dbo.datatransferlog (transferlogid, logdate, transferedby, invoicecode, invoicetype, date, acccode, sgcode, dgcode, status) SELECT v_logid, localtimestamp(3) AS logdate, v_usercode AS transferedby, oldinvcode AS invoicecode, 3 AS invoicetype, localtimestamp(3) AS date, suppcode AS acccode, NULL::smallint, NULL::smallint, CASE purinvcode WHEN -1000 THEN 0 ELSE 1 END AS status FROM dbo.pltemp;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    INSERT INTO dbo.datatransferlogdetail (transferlogid, invoicecode, invoicetype, icode, gcode, batch, expiry, qty, bonusqty, price, status) SELECT v_logid, oldinvcode AS invoicecode, 3 AS invoicetype, icode, gcode, batch, expiry, (looseqty + packqty) AS qty, bonusqty, purprice, CASE purinvcode WHEN -1000 THEN 0 ELSE 1 END AS status FROM dbo.pdtemp;
    GET DIAGNOSTICS _rc = ROW_COUNT;
  END IF;
  DROP TABLE IF EXISTS dbo.pltemp;
  DROP TABLE IF EXISTS dbo.pdtemp;
  IF ((0 = 0) AND (v_errcode = 0)) THEN
    return_value := 0;
    logid := v_logid;
    RETURN;
  ELSE
    RAISE EXCEPTION 'Unable To successfully transfer purchase invoices';
  END IF;
  return_value := -1;
  logid := v_logid;
  RETURN;
  return_value := 0;
  logid := v_logid;
  RETURN;
END
$body$;

-- ==== proc SP_TransferPurchaseInvoices2 ====
CREATE OR REPLACE FUNCTION dbo.sp_transferpurchaseinvoices2(srv citext, db citext, owner citext, usercode smallint, INOUT logid integer, OUT return_value integer, OUT rs1 refcursor, OUT rs2 refcursor, OUT rs3 refcursor, OUT rs4 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_usercode smallint;
  v_logid integer;
  v_srcupd citext;
  v_batch citext;
  v_full_table_name citext;
  v_itemname citext;
  v_sqlheader citext;
  v_sqldetail citext;
  v_sql citext;
  v_list citext;
  v_table_id integer;
  v_headercount integer;
  v_tabmaxkey integer;
  v_headertabmaxkey integer;
  v_headercode integer;
  v_oldinvcode integer;
  v_purcatcode integer;
  v_icode integer;
  v_gcode integer;
  v_thiscount integer;
  v_retcode integer;
  v_importcount integer;
  v_purrowid integer;
  v_packunits integer;
  v_errcode integer;
  v_packqty numeric(15,4);
  v_looseqty numeric(15,4);
  v_bonusqty numeric(15,4);
  v_qty numeric(15,4);
  v_detailcount bigint;
  v_maxutn bigint;
  v_expiry timestamp(3);
  v_itemcost double precision;
  v_stock numeric(15,4);
  v_newavgprice numeric(15,5);
  v_invdiscperc double precision;
  v_purprice numeric(15,5);
  v_discperc double precision;
  v_rpp numeric(15,5);
  v_unitsaletax double precision;
  v_gstperc double precision;
  v_invgstperc1 double precision;
  v_avgprice numeric(15,5);
  _dq1 text;
  _dq2 text;
  cur_pur1 refcursor;
  cur_pur2 refcursor;
  _dq3 text;
  _dq4 text;
  _dq5 text;
  _fs integer := -1;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  v_usercode := usercode;
  v_logid := logid;
  -- SET NOCOUNT ON
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  v_sqlheader := (((((('SELECT T.*, OLDINVCODE=T.PURINVCODE INTO PLTEMP FROM ' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.PurLedger AS T WHERE T.Transferable = ''Y'' and T.Transfered = ''N'' ');
  v_sqldetail := (((((('SELECT T.*, OLDINVCODE=T.PURINVCODE INTO PDTEMP FROM ' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.PurDetail AS T WHERE T.PurInvCode IN (SELECT PurinvCode FROM PLTEMP) ORDER BY T.PurRowID');
  v_srcupd := (((((((('UPDATE ' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.PurLedger SET TRANSFERED=''Y'', TRANSFEREDON = localtimestamp(3), TRANSFEREDBY = ') || ltrim(rtrim(dbo.tsql_str((v_usercode)::numeric)))) || ' WHERE PURINVCODE IN (SELECT OLDINVCODE FROM PLTEMP WHERE PURINVCODE >= 0)');
  _dq1 := v_sqlheader;
  IF _dq1 IS NOT NULL THEN
    IF _dq1 ~* '^[[:space:]]*select' THEN OPEN rs1 FOR EXECUTE dbo.tsql_dyn(_dq1); ELSE EXECUTE dbo.tsql_dyn(_dq1); END IF;
  END IF;
  v_errcode := 0;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Error Fetching The Required Purchase Invoices From Source Database';
    return_value := -1;
    logid := v_logid;
    RETURN;
  END IF;
  v_headercount := coalesce((SELECT coalesce(count(*), 0) FROM dbo.pltemp), 0);
  v_errcode := 0;
  IF (((0 <> 0) OR (v_errcode <> 0)) OR (v_headercount <= 0)) THEN
    return_value := 0;
    logid := v_logid;
    RETURN;
  END IF;
  _dq2 := v_sqldetail;
  IF _dq2 IS NOT NULL THEN
    IF _dq2 ~* '^[[:space:]]*select' THEN OPEN rs2 FOR EXECUTE dbo.tsql_dyn(_dq2); ELSE EXECUTE dbo.tsql_dyn(_dq2); END IF;
  END IF;
  v_errcode := 0;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem in fetching Purchase Invoices Detail';
    return_value := -1;
    logid := v_logid;
    RETURN;
  END IF;
  v_detailcount := coalesce((SELECT coalesce(count(*), 0) FROM dbo.pdtemp), 0);
  v_errcode := 0;
  IF (((0 <> 0) OR (v_errcode <> 0)) OR (v_detailcount <= 0)) THEN
    RAISE EXCEPTION 'Problem in fetching Purchase Invoices Detail';
    return_value := -1;
    logid := v_logid;
    RETURN;
  END IF;
  SELECT r.return_value, r.key INTO v_errcode, v_logid FROM dbo.sp_gettabmaxkey(tabname => 'datatransferlog', key => v_logid) AS r;
  v_errcode := 0;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem in generating data transfer log';
    return_value := -1;
    logid := v_logid;
    RETURN;
  END IF;
  v_errcode := 0;
  OPEN cur_pur1 FOR SELECT oldinvcode, purcatcode, discperc, invgstperc1, coalesce(headerno, 1) AS headerno FROM dbo.pltemp ORDER BY oldinvcode;
  FETCH NEXT FROM cur_pur1 INTO v_oldinvcode, v_purcatcode, v_invdiscperc, v_invgstperc1, v_headercode;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    v_thiscount := 0;
    OPEN cur_pur2 FOR SELECT icode, gcode, batch, expiry, purrowid, packqty, looseqty, bonusqty, packunits, purprice, discperc, unitsalestax, gstperc FROM dbo.pdtemp WHERE (oldinvcode = v_oldinvcode) ORDER BY purrowid;
    FETCH NEXT FROM cur_pur2 INTO v_icode, v_gcode, v_batch, v_expiry, v_purrowid, v_packqty, v_looseqty, v_bonusqty, v_packunits, v_purprice, v_discperc, v_unitsaletax, v_gstperc;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    WHILE (_fs = 0) LOOP
      UPDATE dbo.pdtemp SET purinvcode = -1000 WHERE (purrowid = v_purrowid);
      v_thiscount := (v_thiscount + 1);
      FETCH NEXT FROM cur_pur2 INTO v_icode, v_gcode, v_batch, v_expiry, v_purrowid, v_packqty, v_looseqty, v_bonusqty, v_packunits, v_purprice, v_discperc, v_unitsaletax, v_gstperc;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    END LOOP;
    CLOSE cur_pur2;
    -- DEALLOCATE pur2
    IF (v_thiscount = 0) THEN
      UPDATE dbo.pltemp SET purinvcode = -1000 WHERE (oldinvcode = v_oldinvcode);
    ELSE
      SELECT r.return_value, r.key INTO v_errcode, v_tabmaxkey FROM dbo.sp_gettabmaxkey(tabname => 'purledger', key => v_tabmaxkey) AS r;
      IF ((0 <> 0) OR (v_errcode <> 0)) THEN
        CLOSE cur_pur1;
        -- DEALLOCATE pur1
        return_value := -1;
        logid := v_logid;
        RETURN;
      END IF;
      SELECT r.return_value, r.key INTO v_errcode, v_headertabmaxkey FROM dbo.sp_getheadertabmaxkey(headercode => (v_headercode)::smallint, modulecode => (3)::smallint, key => v_headertabmaxkey) AS r;
      IF ((0 <> 0) OR (v_errcode <> 0)) THEN
        CLOSE cur_pur1;
        -- DEALLOCATE pur1
        return_value := -1;
        logid := v_logid;
        RETURN;
      END IF;
      UPDATE dbo.pltemp SET purinvcode = v_tabmaxkey, headerno = coalesce(v_headercode, 1), headerinvno = v_headertabmaxkey, pocode = NULL, paymentmode = NULL, paymentacccode = NULL, amt = 0, amtdate = NULL, amtby = NULL, amtreference = NULL, outstandingamt = 0, marked = 'N', salesmancode = v_usercode, modifiedby = NULL, posted = 'N', postedby = NULL, transferable = 'N', transfered = 'N', transferedby = NULL, transferedon = NULL, imported = 'Y', importedby = v_usercode WHERE (oldinvcode = v_oldinvcode);
      UPDATE dbo.pdtemp SET purinvcode = v_tabmaxkey WHERE (oldinvcode = v_oldinvcode);
    END IF;
    FETCH NEXT FROM cur_pur1 INTO v_oldinvcode, v_purcatcode, v_invdiscperc, v_invgstperc1, v_headercode;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_pur1;
  -- DEALLOCATE pur1
  v_importcount := coalesce((SELECT count(*) FROM dbo.pltemp WHERE (pltemp.purinvcode >= 0)), 0);
  IF (v_importcount > 0) THEN
    UPDATE dbo.pltemp AS pltemp SET invtotal = p.net FROM (SELECT pl.purinvcode AS purinvcode, (round((((sum(((((pd.looseqty + pd.packqty) + pd.bonusqty)) * pd.unitsalestax)) + sum(round((((((((pd.looseqty + pd.packqty)) * pd.purprice) * ((1 - ((.01 * pd.discperc))))) * pd.gstperc) * .01))::numeric, 2))) + round((((((sum((((((pd.looseqty + pd.packqty)) * pd.purprice)) * ((1 - ((.01 * pd.discperc)))))) * ((1 - ((.01 * pl.discperc))))) - pl.flatdisc)) * ((pl.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) + round((((((sum(((((pd.looseqty + pd.packqty)) * pd.purprice) * ((1 - ((.01 * pd.discperc)))))) * ((1 - ((.01 * pl.discperc))))) + pl.misccharges) + pl.salestax) - pl.flatdisc))::numeric, 0)) AS net FROM dbo.pltemp AS pl, dbo.pdtemp AS pd WHERE (pl.purinvcode = pd.purinvcode) GROUP BY pl.purinvcode, pl.suppcode, pl.purcatcode, pl.postdate, pl.discperc, pl.misccharges, pl.salestax, pl.flatdisc, pl.invgstperc1) AS p WHERE ((pltemp.purinvcode >= 0) AND (pltemp.purinvcode = p.purinvcode));
    UPDATE dbo.pltemp SET outstandingamt = invtotal WHERE (pltemp.purinvcode >= 0);
    -- SET XACT_ABORT ON
    _dq3 := v_srcupd;
    IF _dq3 IS NOT NULL THEN
      EXECUTE dbo.tsql_dyn(_dq3);
    END IF;
    v_errcode := 0;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Unable To update the transfer status at source database';
      return_value := -1;
      logid := v_logid;
      RETURN;
    END IF;
    -- SET XACT_ABORT OFF
    v_list := '';
    SELECT r.return_value, r.list INTO v_errcode, v_list FROM dbo.sp_columnlist(owner => v_owner, "table" => 'PurLedger', list => v_list) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Unable To update purchase header';
      return_value := -1;
      logid := v_logid;
      RETURN;
    END IF;
    v_sql := ((((('INSERT INTO PURLEDGER ( ' || v_list) || ' ) ') || 'SELECT ') || v_list) || ' FROM PLTEMP WHERE PLTEMP.PURINVCODE >= 0');
    _dq4 := v_sql;
    IF _dq4 IS NOT NULL THEN
      IF _dq4 ~* '^[[:space:]]*select' THEN OPEN rs3 FOR EXECUTE dbo.tsql_dyn(_dq4); ELSE EXECUTE dbo.tsql_dyn(_dq4); END IF;
    END IF;
    v_errcode := 0;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Unable To update purchase header';
      return_value := -1;
      logid := v_logid;
      RETURN;
    END IF;
    v_list := '';
    SELECT r.return_value, r.list INTO v_errcode, v_list FROM dbo.sp_columnlist(owner => v_owner, "table" => 'PurDetail', list => v_list) AS r;
    v_errcode := 0;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Unable To update purchase detail';
      return_value := -1;
      logid := v_logid;
      RETURN;
    END IF;
    v_sql := ((((('INSERT INTO PURDETAIL ( ' || v_list) || ' ) ') || 'SELECT ') || v_list) || ' FROM PDTEMP WHERE PDTEMP.PURINVCODE >= 0 ORDER BY PDTEMP.PurRowID');
    _dq5 := v_sql;
    IF _dq5 IS NOT NULL THEN
      IF _dq5 ~* '^[[:space:]]*select' THEN OPEN rs4 FOR EXECUTE dbo.tsql_dyn(_dq5); ELSE EXECUTE dbo.tsql_dyn(_dq5); END IF;
    END IF;
    v_errcode := 0;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Unable To update purchase detail';
      return_value := -1;
      logid := v_logid;
      RETURN;
    END IF;
  END IF;
  IF ((0 = 0) AND (v_errcode = 0)) THEN
    INSERT INTO dbo.datatransferlog (transferlogid, logdate, transferedby, invoicecode, invoicetype, date, acccode, sgcode, dgcode, status) SELECT v_logid, localtimestamp(3) AS logdate, v_usercode AS transferedby, oldinvcode AS invoicecode, 3 AS invoicetype, localtimestamp(3) AS date, suppcode AS acccode, NULL::smallint, NULL::smallint, CASE purinvcode WHEN -1000 THEN 0 ELSE 1 END AS status FROM dbo.pltemp;
    INSERT INTO dbo.datatransferlogdetail (transferlogid, invoicecode, invoicetype, icode, gcode, batch, expiry, qty, bonusqty, price, status) SELECT v_logid, oldinvcode AS invoicecode, 3 AS invoicetype, icode, gcode, batch, expiry, (looseqty + packqty) AS qty, bonusqty, purprice, CASE purinvcode WHEN -1000 THEN 0 ELSE 1 END AS status FROM dbo.pdtemp ORDER BY purrowid;
  END IF;
  DROP TABLE IF EXISTS dbo.pltemp;
  DROP TABLE IF EXISTS dbo.pdtemp;
  IF ((0 = 0) AND (v_errcode = 0)) THEN
    return_value := 0;
    logid := v_logid;
    RETURN;
  ELSE
    RAISE EXCEPTION 'Unable To successfully transfer purchase invoices';
  END IF;
  return_value := -1;
  logid := v_logid;
  RETURN;
  return_value := 0;
  logid := v_logid;
  RETURN;
END
$body$;

-- ==== proc SP_TransferSaleIntoSaleOrders ====
CREATE OR REPLACE FUNCTION dbo.sp_transfersaleintosaleorders(srv citext, db citext, owner citext, usercode smallint, INOUT startsaleordercode integer, INOUT endsaleordercode integer, OUT return_value integer, OUT rs1 refcursor, OUT rs2 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_usercode smallint;
  v_startsaleordercode integer;
  v_endsaleordercode integer;
  v_tablequalifier citext;
  v_srcupd citext;
  v_batch citext;
  v_itemname citext;
  v_sqlheader citext;
  v_sqldetail citext;
  v_sql citext;
  v_list citext;
  v_headercount integer;
  v_tabmaxkey integer;
  v_headertabmaxkey integer;
  v_headercode integer;
  v_errcode integer;
  v_oldinvcode integer;
  v_salecatcode integer;
  v_retcode integer;
  v_rowid integer;
  v_invcount integer;
  v_detailcount bigint;
  _dq1 text;
  _dq2 text;
  _dq3 text;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  v_usercode := usercode;
  v_startsaleordercode := startsaleordercode;
  v_endsaleordercode := endsaleordercode;
  -- SET NOCOUNT ON
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  DROP TABLE IF EXISTS tv_sp_transfersaleintosaleorders_tab_so;
  CREATE TEMP TABLE tv_sp_transfersaleintosaleorders_tab_so (
    saleinvcode integer NOT NULL,
    newsaleordercode integer NOT NULL,
    rowid integer GENERATED BY DEFAULT AS IDENTITY (START WITH 0 INCREMENT BY 1 MINVALUE 0)
) ON COMMIT DROP;
  v_tablequalifier := ((((ltrim(rtrim(v_srv)) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner)));
  v_sqlheader := (('SELECT T.*, OLDINVCODE=T.SaleInvCode, NewSaleOrderCode=-1 INTO SOHTEMP FROM ' || v_tablequalifier) || '.SaleLedger AS T WHERE T.Transferable = ''Y'' and T.Transfered = ''N'' ');
  v_sqldetail := (('SELECT T.*, OLDINVCODE=T.SaleInvCode, NewSaleOrderCode=-1 INTO SODTEMP FROM ' || v_tablequalifier) || '.SaleDetail AS T WHERE T.SaleInvCode IN (SELECT SaleInvCode FROM SOHTEMP) ORDER BY T.RowID');
  v_srcupd := (((('UPDATE ' || v_tablequalifier) || '.SaleLedger SET TRANSFERED=''Y'', TRANSFEREDON = localtimestamp(3), TRANSFEREDBY = ') || ltrim(rtrim(dbo.tsql_str((v_usercode)::numeric)))) || ' WHERE SaleInvCode IN (SELECT OLDINVCODE FROM SOHTEMP WHERE SaleInvCode >= 0)');
  _dq1 := v_sqlheader;
  IF _dq1 IS NOT NULL THEN
    IF _dq1 ~* '^[[:space:]]*select' THEN OPEN rs1 FOR EXECUTE dbo.tsql_dyn(_dq1); ELSE EXECUTE dbo.tsql_dyn(_dq1); END IF;
  END IF;
  v_errcode := 0;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Error Fetching The Required Sales Invoices From Source Database';
    return_value := -1;
    startsaleordercode := v_startsaleordercode;
    endsaleordercode := v_endsaleordercode;
    RETURN;
  END IF;
  v_headercount := (SELECT coalesce(count(*), 0) FROM dbo.sohtemp);
  v_errcode := 0;
  IF (((0 <> 0) OR (v_errcode <> 0)) OR (v_headercount <= 0)) THEN
    return_value := 0;
    startsaleordercode := v_startsaleordercode;
    endsaleordercode := v_endsaleordercode;
    RETURN;
  END IF;
  _dq2 := v_sqldetail;
  IF _dq2 IS NOT NULL THEN
    IF _dq2 ~* '^[[:space:]]*select' THEN OPEN rs2 FOR EXECUTE dbo.tsql_dyn(_dq2); ELSE EXECUTE dbo.tsql_dyn(_dq2); END IF;
  END IF;
  v_errcode := 0;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem in fetching Sales Invoices Detail';
    return_value := -1;
    startsaleordercode := v_startsaleordercode;
    endsaleordercode := v_endsaleordercode;
    RETURN;
  END IF;
  v_invcount := coalesce((SELECT count(saleinvcode) FROM dbo.sohtemp), 0);
  SELECT r.return_value, r.key INTO v_errcode, v_startsaleordercode FROM dbo.sp_gettabmaxkey(tabname => 'SaleOrderHeader', key => v_startsaleordercode) AS r;
  v_errcode := 0;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem in generating sale order header';
    return_value := -1;
    startsaleordercode := v_startsaleordercode;
    endsaleordercode := v_endsaleordercode;
    RETURN;
  END IF;
  INSERT INTO tv_sp_transfersaleintosaleorders_tab_so (saleinvcode, newsaleordercode) SELECT saleinvcode, 0 AS newsaleordercode FROM dbo.sohtemp WHERE (saleinvcode > 0);
  IF (0 <> 0) THEN
    RAISE EXCEPTION 'Problem in inserting row in temporary table, Error Code = % ', 0;
    return_value := -1;
    startsaleordercode := v_startsaleordercode;
    endsaleordercode := v_endsaleordercode;
    RETURN;
  END IF;
  UPDATE tv_sp_transfersaleintosaleorders_tab_so AS tab_so SET newsaleordercode = (v_startsaleordercode + rowid);
  IF (0 <> 0) THEN
    RAISE EXCEPTION 'Problem in generating new sale order code in temporary table ';
    return_value := -1;
    startsaleordercode := v_startsaleordercode;
    endsaleordercode := v_endsaleordercode;
    RETURN;
  END IF;
  UPDATE dbo.sohtemp SET newsaleordercode = (SELECT newsaleordercode FROM tv_sp_transfersaleintosaleorders_tab_so AS t WHERE (t.saleinvcode = sohtemp.saleinvcode));
  IF (0 <> 0) THEN
    RAISE EXCEPTION 'Problem in updating new sale order code in SOHTEMP table ';
    return_value := -1;
    startsaleordercode := v_startsaleordercode;
    endsaleordercode := v_endsaleordercode;
    RETURN;
  END IF;
  UPDATE dbo.sodtemp SET newsaleordercode = (SELECT sohtemp.newsaleordercode FROM dbo.sohtemp WHERE (sohtemp.saleinvcode = sodtemp.saleinvcode));
  IF (0 <> 0) THEN
    RAISE EXCEPTION 'Problem in updating new sale order code in SODTEMP table ';
    return_value := -1;
    startsaleordercode := v_startsaleordercode;
    endsaleordercode := v_endsaleordercode;
    RETURN;
  END IF;
  INSERT INTO dbo.saleorderheader (saleordercode, custcode, usercode, date, originaldate, billingdate, discperc, flatdisc, misccharges, invgstperc1, posted, postdate, headerno, headerinvno, modifiedby, postedby, doctcode, patientcode, messagecode, smancode, relationcode, diseasecode, wardcode, invoicesize, gstno, invtotal, sprice, remarks, custrefno, custrefno2, custrefno3, custrefno4, deleted, finalized, grn, suppinvcode, oldsaleinvcode) SELECT newsaleordercode, custcode, salesmancode, date, originaldate, billingdate, discperc, flatdisc, misccharges, invgstperc1, 'N' AS posted, postdate, headerno, headerinvno, modifiedby, postedby, doctcode, patientcode, messagecode, smancode, relationcode, diseasecode, wardcode, invoicesize, gstno, invtotal, sprice, remarks, custrefno, custrefno2, custrefno3, custrefno4, deleted, 'N' AS finalized, grn, suppinvcode, oldinvcode AS oldsaleinvcode FROM dbo.sohtemp;
  IF (0 <> 0) THEN
    RAISE EXCEPTION 'Problem in inserting sale order header';
    return_value := -1;
    startsaleordercode := v_startsaleordercode;
    endsaleordercode := v_endsaleordercode;
    RETURN;
  END IF;
  INSERT INTO dbo.saleorderdetail (saleordercode, icode, gcode, looseqty, packunits, saleprice, avgprice, rate, discperc, itemflatdisc, saleitemdescription, packprice, unitsalestax, gstperc, bonusqty, rowgroup, packqtyforsale, bonuspackqtyforsale, remarks, saleorderitemstatuscode, quotationrowid, prescriptionrowid, batch, expiry) SELECT newsaleordercode, icode, gcode, sum(looseqty) AS looseqty, packunits, max(saleprice) AS saleprice, max(avgprice) AS avgprice, max(rate) AS rate, max(discperc) AS discperc, max(itemflatdisc) AS itemflatdisc, saleitemdescription, max(packprice) AS packprice, max(unitsalestax) AS unitsalestax, max(gstperc) AS gstperc, max(bonusqty) AS bonusqty, 1 AS rowgroup, 0 AS packqtyforsale, 0 AS bonuspackqtyforsale, saleitemdescription AS remarks, NULL::smallint AS saleorderitemstatuscode, NULL::integer AS quotationrowid, NULL::integer AS prescriptionrowid, '.' AS batch, ('12-12-2222')::timestamp(3) AS expiry FROM dbo.sodtemp GROUP BY newsaleordercode, icode, gcode, packunits, saleitemdescription, saleitemdescription ORDER BY rowid;
  IF (0 <> 0) THEN
    RAISE EXCEPTION 'Problem in inserting sale order detail';
    return_value := -1;
    startsaleordercode := v_startsaleordercode;
    endsaleordercode := v_endsaleordercode;
    RETURN;
  END IF;
  v_endsaleordercode := (SELECT max(newsaleordercode) FROM dbo.sohtemp);
  SELECT r.return_value INTO v_errcode FROM dbo.sp_updatetabmaxkey(tabname => 'SaleOrderHeader', key => v_endsaleordercode) AS r;
  v_errcode := 0;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem in updating max sale order code';
    return_value := -1;
    startsaleordercode := v_startsaleordercode;
    endsaleordercode := v_endsaleordercode;
    RETURN;
  END IF;
  -- SET XACT_ABORT ON
  _dq3 := v_srcupd;
  IF _dq3 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq3);
  END IF;
  v_errcode := 0;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Unable To update the transfer status at source database';
    return_value := -1;
    startsaleordercode := v_startsaleordercode;
    endsaleordercode := v_endsaleordercode;
    RETURN;
  END IF;
  -- SET XACT_ABORT OFF
  DROP TABLE IF EXISTS dbo.sohtemp;
  DROP TABLE IF EXISTS dbo.sodtemp;
  IF ((0 = 0) AND (v_errcode = 0)) THEN
    return_value := 0;
    startsaleordercode := v_startsaleordercode;
    endsaleordercode := v_endsaleordercode;
    RETURN;
  ELSE
    RAISE EXCEPTION 'Unable To successfully transfer sale orders';
  END IF;
  return_value := -1;
  startsaleordercode := v_startsaleordercode;
  endsaleordercode := v_endsaleordercode;
  RETURN;
  return_value := 0;
  startsaleordercode := v_startsaleordercode;
  endsaleordercode := v_endsaleordercode;
  RETURN;
END
$body$;

-- ==== proc SP_TransferSaleInvoices ====
CREATE OR REPLACE FUNCTION dbo.sp_transfersaleinvoices(srv citext, db citext, owner citext, usercode smallint, INOUT logid integer, OUT return_value integer, OUT rs1 refcursor, OUT rs2 refcursor, OUT rs3 refcursor, OUT rs4 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_usercode smallint;
  v_logid integer;
  v_tablequalifier citext;
  v_srcupd citext;
  v_batch citext;
  v_itemname citext;
  v_sqlheader citext;
  v_sqldetail citext;
  v_sql citext;
  v_list citext;
  v_headercount integer;
  v_tabmaxkey integer;
  v_headertabmaxkey integer;
  v_headercode integer;
  v_errcode integer;
  v_oldinvcode integer;
  v_salecatcode integer;
  v_icode integer;
  v_gcode integer;
  v_thiscount integer;
  v_retcode integer;
  v_importcount integer;
  v_id integer;
  v_packunits integer;
  v_insercount integer;
  v_rowgroup integer;
  v_defaultgst integer;
  v_tqty numeric(15,4);
  v_tbqty numeric(15,4);
  v_qty numeric(15,4);
  v_reqqty numeric(15,4);
  v_stock numeric(15,4);
  v_newstock numeric(15,4);
  v_totalstock numeric(15,4);
  v_batchstock numeric(15,4);
  v_bonusqty numeric(15,4);
  v_dueqty numeric(15,4);
  v_packqty numeric(15,4);
  v_looseqty numeric(15,4);
  v_detailcount bigint;
  v_maxutn bigint;
  v_expiry timestamp(3);
  v_purprice numeric(15,5);
  v_saleprice numeric(15,5);
  v_discperc double precision;
  v_rpp numeric(15,5);
  v_avgprice numeric(15,5);
  v_unitsalestax double precision;
  v_gstperc double precision;
  _dq1 text;
  _dq2 text;
  cur_sal1 refcursor;
  cur_sal2 refcursor;
  cur_sal3 refcursor;
  _dq3 text;
  _dq4 text;
  _dq5 text;
  _rc integer;
  _fs integer := -1;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  v_usercode := usercode;
  v_logid := logid;
  -- SET NOCOUNT ON
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  v_tablequalifier := ((((ltrim(rtrim(v_srv)) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner)));
  _rc := 1;
  v_sqlheader := (('SELECT T.*, OLDINVCODE=T.SaleInvCode INTO SHTEMP FROM ' || v_tablequalifier) || '.SaleLedger AS T WHERE T.Transferable = ''Y'' and T.Transfered = ''N'' ');
  _rc := 1;
  v_sqldetail := (('SELECT T.*, OLDINVCODE=T.SaleInvCode, ID2=0 INTO SDTEMP FROM ' || v_tablequalifier) || '.SaleDetail AS T WHERE T.SaleInvCode IN (SELECT SaleInvCode FROM SHTEMP) ORDER BY T.ROWID');
  _rc := 1;
  v_srcupd := (((('UPDATE ' || v_tablequalifier) || '.SaleLedger SET TRANSFERED=''Y'', TRANSFEREDON = localtimestamp(3), TRANSFEREDBY = ') || ltrim(rtrim(dbo.tsql_str((v_usercode)::numeric)))) || ' WHERE SaleInvCode IN (SELECT OLDINVCODE FROM SHTEMP WHERE SaleInvCode >= 0)');
  _rc := 1;
  _dq1 := v_sqlheader;
  IF _dq1 IS NOT NULL THEN
    IF _dq1 ~* '^[[:space:]]*select' THEN OPEN rs1 FOR EXECUTE dbo.tsql_dyn(_dq1); ELSE EXECUTE dbo.tsql_dyn(_dq1); END IF;
  END IF;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_errcode := 0;
  _rc := 1;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Error Fetching The Required Sales Invoices From Source Database';
    return_value := -1;
    logid := v_logid;
    RETURN;
  END IF;
  v_headercount := (SELECT coalesce(count(*), 0) FROM dbo.shtemp);
  _rc := 1;
  v_errcode := 0;
  _rc := 1;
  IF (((0 <> 0) OR (v_errcode <> 0)) OR (v_headercount <= 0)) THEN
    return_value := 0;
    logid := v_logid;
    RETURN;
  END IF;
  _dq2 := v_sqldetail;
  IF _dq2 IS NOT NULL THEN
    IF _dq2 ~* '^[[:space:]]*select' THEN OPEN rs2 FOR EXECUTE dbo.tsql_dyn(_dq2); ELSE EXECUTE dbo.tsql_dyn(_dq2); END IF;
  END IF;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_errcode := 0;
  _rc := 1;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem in fetching Sales Invoices Detail';
    return_value := -1;
    logid := v_logid;
    RETURN;
  END IF;
  v_detailcount := (SELECT coalesce(count(*), 0) FROM dbo.sdtemp);
  _rc := 1;
  v_errcode := 0;
  _rc := 1;
  IF (((0 <> 0) OR (v_errcode <> 0)) OR (v_detailcount <= 0)) THEN
    RAISE EXCEPTION 'Problem in fetching Sales Invoices Detail';
    return_value := -1;
    logid := v_logid;
    RETURN;
  END IF;
  SELECT r.return_value, r.key INTO v_errcode, v_logid FROM dbo.sp_gettabmaxkey(tabname => 'datatransferlog', key => v_logid) AS r;
  v_errcode := 0;
  _rc := 1;
  IF ((0 <> 0) OR (v_errcode <> 0)) THEN
    RAISE EXCEPTION 'Problem in generating data transfer log';
    return_value := -1;
    logid := v_logid;
    RETURN;
  END IF;
  DROP TABLE IF EXISTS dbo.sdtemp2;
  CREATE TABLE dbo.sdtemp2 AS SELECT * FROM (SELECT * FROM dbo.sdtemp WHERE (saleinvcode < 0) UNION SELECT * FROM dbo.sdtemp WHERE (saleinvcode < 0)) AS a;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((0 <> 0) OR (_rc > 0)) THEN
    RAISE EXCEPTION 'Problem in generating sales invoice(s) number';
    return_value := -1;
    logid := v_logid;
    RETURN;
  END IF;
  -- ALTER TABLE SDTEMP2 ALTER COLUMN RowID BIGINT
  RAISE EXCEPTION 'untranslated T-SQL (ALTER TABLE of a permanent table)' USING ERRCODE = '0A000';
  v_errcode := 0;
  _rc := 1;
  OPEN cur_sal1 FOR SELECT s.oldinvcode, s.salecatcode, coalesce(s.headerno, 1) AS headerno, c.defaultgst FROM dbo.shtemp AS s, dbo.customer AS c WHERE (s.custcode = c.custcode) ORDER BY oldinvcode;
  FETCH NEXT FROM cur_sal1 INTO v_oldinvcode, v_salecatcode, v_headercode, v_defaultgst;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    v_thiscount := 0;
    _rc := 1;
    v_retcode := 0;
    _rc := 1;
    OPEN cur_sal2 FOR SELECT s.icode, s.gcode, max(s.rowid) AS id, sum(s.packqty) AS packqty, sum(s.bonusqty) AS bonusqty, sum(s.looseqty) AS looseqty, s.rowgroup, sum(CASE WHEN (s.due IS NULL) THEN 0 ELSE s.looseqty END) AS dueqty, CASE v_defaultgst WHEN 2 THEN i.gstperc2 ELSE i.gstperc1 END AS itemgstperc, round(((i.packsalestax / CASE i.packunits WHEN 0 THEN 1 ELSE i.packunits END))::numeric, 2) AS unitsalestax, i.packunits, round(((i.saleprice / CASE i.packunits WHEN 0 THEN 1 ELSE i.packunits END))::numeric, 2) AS saleprice FROM dbo.sdtemp AS s, dbo.item AS i WHERE ((oldinvcode = v_oldinvcode) AND (s.icode = i.icode)) GROUP BY s.oldinvcode, s.icode, s.rowgroup, s.gcode, i.gstperc1, i.gstperc2, i.packunits, i.saleprice, i.packsalestax ORDER BY id;
    FETCH NEXT FROM cur_sal2 INTO v_icode, v_gcode, v_id, v_packqty, v_bonusqty, v_looseqty, v_rowgroup, v_dueqty, v_gstperc, v_unitsalestax, v_packunits, v_saleprice;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    WHILE (_fs = 0) LOOP
      v_itemname := coalesce((SELECT name FROM dbo.item WHERE (icode = v_icode)), '');
      _rc := 1;
      v_qty := ((v_looseqty - v_dueqty) + v_bonusqty);
      _rc := 1;
      v_looseqty := (v_looseqty - v_dueqty);
      _rc := 1;
      IF (v_qty >= 0) THEN
        IF (v_qty > 0) THEN
          v_avgprice := 0;
          _rc := 1;
          v_stock := 0;
          _rc := 1;
          v_totalstock := 0;
          _rc := 1;
          v_retcode := 0;
          _rc := 1;
          SELECT r.return_value, r.avgprice INTO v_errcode, v_avgprice FROM dbo.sp_getitemavgprice(icode => v_icode, avgprice => v_avgprice) AS r;
          IF ((0 <> 0) OR (v_errcode <> 0)) THEN
            CLOSE cur_sal2;
            -- DEALLOCATE sal2
            CLOSE cur_sal1;
            -- DEALLOCATE sal1
            return_value := -1;
            logid := v_logid;
            RETURN;
          END IF;
          SELECT r.qty INTO v_stock FROM dbo.sp_getitemstocktotal(gcode => v_gcode, icode => v_icode, qty => v_stock) AS r;
          IF (0 <> 0) THEN
            RAISE EXCEPTION 'Unable to fetch godown stock for sale # = %, godown code = %, item = (%)', v_oldinvcode, v_gcode, v_itemname;
            CLOSE cur_sal2;
            -- DEALLOCATE sal2
            CLOSE cur_sal1;
            -- DEALLOCATE sal1
            return_value := -1;
            logid := v_logid;
            RETURN;
          END IF;
          SELECT r.qty INTO v_totalstock FROM dbo.sp_getitemstockall(icode => v_icode, qty => v_totalstock) AS r;
          IF (0 <> 0) THEN
            RAISE EXCEPTION 'Unable to fetch total stock for sale # = %, item = (%)', v_oldinvcode, v_itemname;
            CLOSE cur_sal2;
            -- DEALLOCATE sal2
            CLOSE cur_sal1;
            -- DEALLOCATE sal1
            return_value := -1;
            logid := v_logid;
            RETURN;
          END IF;
          IF (v_qty <= v_stock) THEN
            v_reqqty := v_qty;
            _rc := 1;
            v_insercount := 0;
            _rc := 1;
            OPEN cur_sal3 FOR SELECT batch, expiry, currqty FROM dbo.godowndetail WHERE ((godowndetail.gcode = v_gcode) AND (godowndetail.icode = v_icode)) ORDER BY priority, expiry, currqty;
            FETCH NEXT FROM cur_sal3 INTO v_batch, v_expiry, v_batchstock;
            IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
            WHILE (_fs = 0) LOOP
              v_tqty := 0;
              _rc := 1;
              v_tbqty := 0;
              _rc := 1;
              v_retcode := 0;
              _rc := 1;
              IF (v_batchstock >= v_reqqty) THEN
                v_tqty := v_looseqty;
                _rc := 1;
                v_tbqty := v_bonusqty;
                _rc := 1;
              ELSE
                IF (v_batchstock <= v_looseqty) THEN
                  v_tqty := v_batchstock;
                  _rc := 1;
                  v_tbqty := 0;
                  _rc := 1;
                ELSE
                  v_tqty := v_looseqty;
                  _rc := 1;
                  v_tbqty := (v_batchstock - v_looseqty);
                  _rc := 1;
                END IF;
              END IF;
              v_looseqty := (v_looseqty - v_tqty);
              _rc := 1;
              v_bonusqty := (v_bonusqty - v_tbqty);
              _rc := 1;
              v_reqqty := (v_looseqty + v_bonusqty);
              _rc := 1;
              v_newstock := (v_batchstock - ((v_tqty + v_tbqty)));
              _rc := 1;
              v_totalstock := (v_totalstock - ((v_tqty + v_tbqty)));
              _rc := 1;
              IF (v_newstock > 0) THEN
                UPDATE dbo.godowndetail SET currqty = v_newstock WHERE CURRENT OF cur_sal3;
                GET DIAGNOSTICS _rc = ROW_COUNT;
                IF (_rc = 0) THEN
                  v_retcode := 1;
                  _rc := 1;
                END IF;
              ELSE
                IF (v_newstock = 0) THEN
                  DELETE FROM dbo.godowndetail WHERE CURRENT OF cur_sal3;
                  GET DIAGNOSTICS _rc = ROW_COUNT;
                  IF (_rc = 0) THEN
                    v_retcode := 1;
                    _rc := 1;
                  END IF;
                ELSE
                  v_retcode := 1;
                  _rc := 1;
                END IF;
              END IF;
              IF (v_retcode = 0) THEN
                SELECT r.return_value, r.lbi_maxutn INTO v_errcode, v_maxutn FROM dbo.sp_maxutn(lbi_rows => (1)::bigint, lbi_maxutn => v_maxutn) AS r;
                IF ((v_errcode <> 0) AND (0 <> 0)) THEN
                  CLOSE cur_sal3;
                  -- DEALLOCATE sal3
                  CLOSE cur_sal2;
                  -- DEALLOCATE sal2
                  CLOSE cur_sal1;
                  -- DEALLOCATE sal1
                  return_value := -1;
                  logid := v_logid;
                  RETURN;
                END IF;
                v_insercount := (v_insercount + 1);
                _rc := 1;
                INSERT INTO dbo.sdtemp2 SELECT * FROM dbo.sdtemp WHERE (rowid = v_id);
                GET DIAGNOSTICS _rc = ROW_COUNT;
                IF ((0 <> 0) OR (_rc = 0)) THEN
                  RAISE EXCEPTION 'Unable to Insert Row for sale # = %, item = (%)', v_oldinvcode, v_itemname;
                  CLOSE cur_sal3;
                  -- DEALLOCATE sal3
                  CLOSE cur_sal2;
                  -- DEALLOCATE sal2
                  CLOSE cur_sal1;
                  -- DEALLOCATE sal1
                  return_value := -1;
                  logid := v_logid;
                  RETURN;
                END IF;
                UPDATE dbo.sdtemp2 SET id2 = v_insercount, batch = v_batch, expiry = v_expiry, looseqty = v_tqty, bonusqty = v_tbqty, due = NULL, satisfieddate = NULL, saleutn = v_maxutn, balancestock = coalesce(v_totalstock, 0), gstperc = v_gstperc, unitsalestax = v_unitsalestax, packunits = v_packunits, saleprice = v_saleprice WHERE ((rowid = v_id) AND (id2 = 0));
                GET DIAGNOSTICS _rc = ROW_COUNT;
                IF ((0 <> 0) OR (_rc = 0)) THEN
                  RAISE EXCEPTION 'Unable to Update Row for sale # = %, item = (%)', v_oldinvcode, v_itemname;
                  CLOSE cur_sal3;
                  -- DEALLOCATE sal3
                  CLOSE cur_sal2;
                  -- DEALLOCATE sal2
                  CLOSE cur_sal1;
                  -- DEALLOCATE sal1
                  return_value := -1;
                  logid := v_logid;
                  RETURN;
                END IF;
              ELSE
                RAISE EXCEPTION 'Unable to Update stock for Sale # = %, Item = (%)', v_oldinvcode, v_itemname;
                CLOSE cur_sal3;
                -- DEALLOCATE sal3
                CLOSE cur_sal2;
                -- DEALLOCATE sal2
                CLOSE cur_sal1;
                -- DEALLOCATE sal1
                return_value := -1;
                logid := v_logid;
                RETURN;
              END IF;
              IF (v_retcode <> 0) THEN
                EXIT;
              END IF;
              IF (v_reqqty = 0) THEN
                EXIT;
              END IF;
              FETCH NEXT FROM cur_sal3 INTO v_batch, v_expiry, v_batchstock;
              IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
            END LOOP;
            CLOSE cur_sal3;
            -- DEALLOCATE sal3
          ELSE
            v_retcode := 1;
            _rc := 1;
          END IF;
        END IF;
        IF (v_dueqty > 0) THEN
          v_insercount := 1;
          _rc := 1;
          v_retcode := 0;
          _rc := 1;
          INSERT INTO dbo.sdtemp2 SELECT * FROM dbo.sdtemp WHERE (rowid = v_id);
          GET DIAGNOSTICS _rc = ROW_COUNT;
          SELECT r.return_value, r.lbi_maxutn INTO v_errcode, v_maxutn FROM dbo.sp_maxutn(lbi_rows => (1)::bigint, lbi_maxutn => v_maxutn) AS r;
          IF ((v_errcode <> 0) AND (0 <> 0)) THEN
            CLOSE cur_sal2;
            -- DEALLOCATE sal2
            CLOSE cur_sal1;
            -- DEALLOCATE sal1
            return_value := -1;
            logid := v_logid;
            RETURN;
          END IF;
          UPDATE dbo.sdtemp2 SET id2 = v_insercount, batch = 'Due', expiry = left(to_char((localtimestamp(3) + (1) * interval '1 year'), 'Mon DD YYYY HH12:MIAM'), 12), looseqty = v_dueqty, bonusqty = 0, due = 'D', satisfieddate = NULL, saleutn = v_maxutn, balancestock = coalesce(v_totalstock, 0), gstperc = v_gstperc, unitsalestax = v_unitsalestax, packunits = v_packunits, saleprice = v_saleprice WHERE ((rowid = v_id) AND (id2 = 0));
          GET DIAGNOSTICS _rc = ROW_COUNT;
        END IF;
        IF (v_retcode <> 0) THEN
          UPDATE dbo.sdtemp SET saleinvcode = -1000 WHERE ((rowid = v_id) AND (rowgroup = v_rowgroup));
          GET DIAGNOSTICS _rc = ROW_COUNT;
        ELSE
          v_thiscount := (v_thiscount + 1);
          _rc := 1;
        END IF;
      ELSE
        UPDATE dbo.sdtemp SET saleinvcode = -1000 WHERE ((rowid = v_id) AND (rowgroup = v_rowgroup));
        GET DIAGNOSTICS _rc = ROW_COUNT;
      END IF;
      FETCH NEXT FROM cur_sal2 INTO v_icode, v_gcode, v_id, v_packqty, v_bonusqty, v_looseqty, v_rowgroup, v_dueqty, v_gstperc, v_unitsalestax, v_packunits, v_saleprice;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    END LOOP;
    CLOSE cur_sal2;
    -- DEALLOCATE sal2
    IF (v_thiscount = 0) THEN
      UPDATE dbo.shtemp SET saleinvcode = -1000 WHERE (oldinvcode = v_oldinvcode);
      GET DIAGNOSTICS _rc = ROW_COUNT;
    ELSE
      SELECT r.return_value, r.key INTO v_errcode, v_tabmaxkey FROM dbo.sp_gettabmaxkey(tabname => 'saleledger', key => v_tabmaxkey) AS r;
      IF ((0 <> 0) OR (v_errcode <> 0)) THEN
        CLOSE cur_sal1;
        -- DEALLOCATE sal1
        return_value := -1;
        logid := v_logid;
        RETURN;
      END IF;
      SELECT r.return_value, r.key INTO v_errcode, v_headertabmaxkey FROM dbo.sp_getheadertabmaxkey(headercode => (v_headercode)::smallint, modulecode => (1)::smallint, key => v_headertabmaxkey) AS r;
      IF ((0 <> 0) OR (v_errcode <> 0)) THEN
        CLOSE cur_sal1;
        -- DEALLOCATE sal1
        return_value := -1;
        logid := v_logid;
        RETURN;
      END IF;
      UPDATE dbo.shtemp SET saleinvcode = v_tabmaxkey, headerno = coalesce(v_headercode, 1), headerinvno = v_headertabmaxkey, salesmancode = v_usercode, posted = 'N', modifiedby = NULL, postedby = NULL, quotationno = NULL, reprintingcounter = 0, modifycounter = 0, returncounter = 0, paymentmode = NULL, paymentacccode = NULL, amt = 0, amtby = NULL, amtreference = NULL, outstandingamt = 0, marked = 'N', transferable = 'N', transfered = 'N', transferedby = NULL, transferedon = NULL, imported = 'Y', importedby = v_usercode, gstno = v_defaultgst WHERE (oldinvcode = v_oldinvcode);
      GET DIAGNOSTICS _rc = ROW_COUNT;
      UPDATE dbo.sdtemp2 SET saleinvcode = v_tabmaxkey WHERE (oldinvcode = v_oldinvcode);
      GET DIAGNOSTICS _rc = ROW_COUNT;
    END IF;
    FETCH NEXT FROM cur_sal1 INTO v_oldinvcode, v_salecatcode, v_headercode, v_defaultgst;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_sal1;
  -- DEALLOCATE sal1
  v_importcount := coalesce((SELECT count(*) FROM dbo.shtemp WHERE (shtemp.saleinvcode >= 0)), 0);
  _rc := 1;
  IF (v_importcount > 0) THEN
    UPDATE dbo.shtemp AS shtemp SET invtotal = s.net FROM (SELECT h.saleinvcode, (round((((sum((((d.looseqty + d.bonusqty)) * d.unitsalestax)) + sum(round(((((((d.looseqty * ((d.saleprice - d.itemflatdisc)))) * ((1 - ((.01 * d.discperc))))) * d.gstperc) * .01))::numeric, 2))) + round((((((sum((((d.looseqty * ((d.saleprice - d.itemflatdisc)))) * ((1 - ((.01 * d.discperc)))))) * ((1 - ((.01 * h.discperc))))) - h.flatdisc)) * ((h.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) + round((((((sum((((d.looseqty * ((d.saleprice - d.itemflatdisc)))) * ((1 - ((.01 * d.discperc)))))) * ((1 - ((.01 * h.discperc))))) + h.misccharges) + h.salestax) - h.flatdisc))::numeric, 0)) AS net FROM dbo.shtemp AS h, dbo.sdtemp2 AS d WHERE (h.saleinvcode = d.saleinvcode) GROUP BY h.saleinvcode, h.discperc, h.misccharges, h.salestax, h.flatdisc, h.invgstperc1) AS s WHERE ((shtemp.saleinvcode >= 0) AND (shtemp.saleinvcode = s.saleinvcode));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    UPDATE dbo.shtemp SET flatdisc = 0 WHERE ((saleinvcode >= 0) AND (invtotal < 0));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    UPDATE dbo.sdtemp2 SET itemflatdisc = 0 WHERE (saleinvcode IN (SELECT saleinvcode FROM dbo.shtemp WHERE ((saleinvcode >= 0) AND (invtotal < 0))));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    UPDATE dbo.shtemp AS shtemp SET invtotal = s.net FROM (SELECT h.saleinvcode, (round((((sum((((d.looseqty + d.bonusqty)) * d.unitsalestax)) + sum(round(((((((d.looseqty * ((d.saleprice - d.itemflatdisc)))) * ((1 - ((.01 * d.discperc))))) * d.gstperc) * .01))::numeric, 2))) + round((((((sum((((d.looseqty * ((d.saleprice - d.itemflatdisc)))) * ((1 - ((.01 * d.discperc)))))) * ((1 - ((.01 * h.discperc))))) - h.flatdisc)) * ((h.invgstperc1 * .01))))::numeric, 2)))::numeric, 0) + round((((((sum((((d.looseqty * ((d.saleprice - d.itemflatdisc)))) * ((1 - ((.01 * d.discperc)))))) * ((1 - ((.01 * h.discperc))))) + h.misccharges) + h.salestax) - h.flatdisc))::numeric, 0)) AS net FROM dbo.shtemp AS h, dbo.sdtemp2 AS d WHERE (h.saleinvcode = d.saleinvcode) GROUP BY h.saleinvcode, h.discperc, h.misccharges, h.salestax, h.flatdisc, h.invgstperc1) AS s WHERE ((shtemp.saleinvcode >= 0) AND (shtemp.saleinvcode = s.saleinvcode));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    UPDATE dbo.shtemp SET outstandingamt = invtotal WHERE (shtemp.saleinvcode >= 0);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    -- SET XACT_ABORT ON
    _dq3 := v_srcupd;
    IF _dq3 IS NOT NULL THEN
      EXECUTE dbo.tsql_dyn(_dq3);
    END IF;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_errcode := 0;
    _rc := 1;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Unable To update the transfer status at source database';
      return_value := -1;
      logid := v_logid;
      RETURN;
    END IF;
    -- SET XACT_ABORT OFF
    v_list := '';
    _rc := 1;
    SELECT r.return_value, r.list INTO v_errcode, v_list FROM dbo.sp_columnlist(owner => v_owner, "table" => 'SaleLedger', list => v_list) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Unable To update sale invoice header';
      return_value := -1;
      logid := v_logid;
      RETURN;
    END IF;
    v_sql := ((((('INSERT INTO SaleLedger ( ' || v_list) || ' ) ') || 'SELECT ') || v_list) || ' FROM SHTEMP WHERE SHTEMP.SALEINVCODE >=0');
    _rc := 1;
    _dq4 := v_sql;
    IF _dq4 IS NOT NULL THEN
      IF _dq4 ~* '^[[:space:]]*select' THEN OPEN rs3 FOR EXECUTE dbo.tsql_dyn(_dq4); ELSE EXECUTE dbo.tsql_dyn(_dq4); END IF;
    END IF;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_errcode := 0;
    _rc := 1;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Unable To update sale invoice header';
      return_value := -1;
      logid := v_logid;
      RETURN;
    END IF;
    v_list := '';
    _rc := 1;
    SELECT r.return_value, r.list INTO v_errcode, v_list FROM dbo.sp_columnlist(owner => v_owner, "table" => 'SaleDetail', list => v_list) AS r;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Unable To update sale invoice detail';
      return_value := -1;
      logid := v_logid;
      RETURN;
    END IF;
    v_sql := ((((('INSERT INTO SALEDETAIL ( ' || v_list) || ' ) ') || 'SELECT ') || v_list) || ' FROM SDTEMP2 WHERE SALEINVCODE >= 0 ORDER BY ROWID');
    _rc := 1;
    _dq5 := v_sql;
    IF _dq5 IS NOT NULL THEN
      IF _dq5 ~* '^[[:space:]]*select' THEN OPEN rs4 FOR EXECUTE dbo.tsql_dyn(_dq5); ELSE EXECUTE dbo.tsql_dyn(_dq5); END IF;
    END IF;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_errcode := 0;
    _rc := 1;
    IF ((0 <> 0) OR (v_errcode <> 0)) THEN
      RAISE EXCEPTION 'Unable To update sale invoice detail';
      return_value := -1;
      logid := v_logid;
      RETURN;
    END IF;
  END IF;
  IF ((0 = 0) AND (v_errcode = 0)) THEN
    INSERT INTO dbo.datatransferlog (transferlogid, logdate, transferedby, invoicecode, invoicetype, date, acccode, sgcode, dgcode, status) SELECT v_logid, localtimestamp(3) AS logdate, v_usercode AS transferedby, oldinvcode AS invoicecode, 1 AS invoicetype, localtimestamp(3) AS date, shtemp.custcode AS acccode, NULL::smallint, NULL::smallint, CASE saleinvcode WHEN -1000 THEN 0 ELSE 1 END AS status FROM dbo.shtemp;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    INSERT INTO dbo.datatransferlogdetail (transferlogid, invoicecode, invoicetype, icode, gcode, batch, expiry, qty, bonusqty, price, status) SELECT v_logid, oldinvcode AS invoicecode, 1 AS invoicetype, icode, gcode, batch, expiry, looseqty, bonusqty, saleprice, CASE saleinvcode WHEN -1000 THEN 0 ELSE 1 END AS status FROM dbo.sdtemp;
    GET DIAGNOSTICS _rc = ROW_COUNT;
  END IF;
  DROP TABLE IF EXISTS dbo.shtemp;
  DROP TABLE IF EXISTS dbo.sdtemp;
  DROP TABLE IF EXISTS dbo.sdtemp2;
  IF ((0 = 0) AND (v_errcode = 0)) THEN
    return_value := 0;
    logid := v_logid;
    RETURN;
  ELSE
    RAISE EXCEPTION 'Unable To successfully transfer sale invoices';
  END IF;
  return_value := -1;
  logid := v_logid;
  RETURN;
  return_value := 0;
  logid := v_logid;
  RETURN;
END
$body$;

-- ==== proc sp_Translate_ChildeServer_Sale ====
CREATE OR REPLACE FUNCTION dbo.sp_translate_childeserver_sale(childserver citext, invtype integer, invcode integer, usercode integer, refund numeric, INOUT saleinvcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_childserver citext;
  v_invtype integer;
  v_invcode integer;
  v_usercode integer;
  v_refund numeric(10,2);
  v_saleinvcode integer;
  v_headerno integer;
  v_gcode integer;
  v_curr_rowid integer;
  v_module integer;
  v_custcode integer;
  v_saletypecode smallint;
  v_salecatcode integer;
  v_headerinvno integer;
  v_continue integer;
  v_rt_code integer;
  v_err integer;
  v_totalrows integer;
  v_rowcount integer;
  v_invcounter integer;
  v_counter integer;
  v_satisfiableqty numeric(15,4);
  v_satisfiedqty numeric(15,4);
  v_item_in_inv_exist integer;
  v_saleprice numeric(12,2);
  v_rate numeric(12,2);
  v_discperc numeric(5,2);
  v_itemflatdisc numeric(15,2);
  v_unitsalestax numeric(12,2);
  v_gstperc1 numeric(6,2);
  v_gstperc2 numeric(6,2);
  v_hold_avgprice numeric(15,5);
  v_icode integer;
  v_anyitem_exist numeric(15,4);
  v_packunits integer;
  v_totalqty numeric(15,4);
  v_givenqty numeric(15,4);
  v_reqqty numeric(15,4);
  v_batchqty numeric(15,4);
  v_delqty numeric(15,4);
  v_currqty numeric(15,4);
  v_newqty numeric(15,4);
  v_total_availablestock numeric(15,4);
  v_itemadvancetaxperc numeric(5,2);
  v_batch citext;
  v_itemname citext;
  v_expiry timestamp(3);
  v_serverdate timestamp(3);
  v_saleutn bigint;
  v_salerowcount integer;
  v_rowgroup integer;
  v_lineitems_rowcount integer;
  v_innercounter integer;
  v_saledesc citext;
  v_updateloyaltypoints citext;
  v_keepinvno citext;
  v_updaterefno1 citext;
  _r1 record;
  cur_itembatch_cursor refcursor;
  _rc integer;
  _fs integer := -1;
BEGIN
  v_childserver := childserver;
  v_invtype := invtype;
  v_invcode := invcode;
  v_usercode := usercode;
  v_refund := refund;
  v_saleinvcode := saleinvcode;
  -- SET NOCOUNT ON
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  v_custcode := 19;
  _rc := 1;
  v_salecatcode := 3;
  _rc := 1;
  v_saletypecode := 2;
  _rc := 1;
  v_module := (SELECT module FROM dbo.module WHERE (name = 'Sales'));
  _rc := 1;
  v_serverdate := localtimestamp(3);
  _rc := 1;
  v_updateloyaltypoints := coalesce((SELECT dbo.fn_getpreference('ApplyLoyaltypolicyonsaleposting')), 'N');
  _rc := 1;
  v_keepinvno := coalesce((SELECT dbo.fn_getpreference('KeepChildServerInvoiceNoIntact')), 'N');
  _rc := 1;
  v_updaterefno1 := coalesce((SELECT dbo.fn_getpreference('CopyChildServerInvoiceNoInRef1')), 'N');
  _rc := 1;
  DROP TABLE IF EXISTS tmp_sale;
  CREATE TEMP TABLE tmp_sale (
    id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    icode integer,
    gcode integer,
    satisfiableqty numeric(15,4),
    satisfiedqty numeric(15,4),
    saleprice numeric(12,2),
    rate numeric(12,2),
    packunits smallint NOT NULL,
    discperc numeric(8,2),
    itemflatdisc numeric(12,2),
    unitsalestax numeric(12,2),
    gstperc numeric(6,2),
    saledesc citext,
    itemadvancetaxperc numeric(5,2)
) ON COMMIT DROP;
  INSERT INTO tmp_sale (icode, gcode, satisfiableqty, satisfiedqty, saleprice, rate, packunits, discperc, itemflatdisc, unitsalestax, gstperc, saledesc, itemadvancetaxperc) SELECT icode, gcode, coalesce(sum(looseqty), 0) AS looseqty, 0, saleprice, rate, packunits, discperc, itemflatdisc, unitsalestax, gstperc, ltrim(rtrim(dbo.tsql_str((max(saleutn))::numeric))) AS saledesc, 0 AS itemadvancetaxperc FROM dbo.imp_advsaledetail WHERE ((((v_invtype = 2) AND (childserver = v_childserver)) AND (advsaleinvcode = v_invcode)) AND (looseqty > 0)) GROUP BY icode, gcode, saleprice, rate, packunits, discperc, itemflatdisc, unitsalestax, gstperc UNION ALL SELECT icode, gcode, coalesce(sum(looseqty), 0) AS looseqty, 0, saleprice, rate, packunits, discperc, itemflatdisc, unitsalestax, gstperc, ltrim(rtrim(dbo.tsql_str((max(saleutn))::numeric))) AS saledesc, itemadvancetaxperc AS itemadvancetaxperc FROM dbo.imp_saledetail WHERE ((((v_invtype = 1) AND (childserver = v_childserver)) AND (saleinvcode = v_invcode)) AND (looseqty > 0)) GROUP BY icode, gcode, saleprice, rate, packunits, discperc, itemflatdisc, unitsalestax, gstperc, itemadvancetaxperc ORDER BY 1;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF (v_invtype = 1) THEN
    v_salerowcount := coalesce((SELECT count(*) FROM dbo.imp_saledetail WHERE ((saleinvcode = v_invcode) AND (childserver = v_childserver))), 0);
    _rc := 1;
  ELSE
    v_salerowcount := coalesce((SELECT count(*) FROM dbo.imp_advsaledetail WHERE ((advsaleinvcode = v_invcode) AND (childserver = v_childserver))), 0);
    _rc := 1;
  END IF;
  v_anyitem_exist := (SELECT sum((satisfiableqty - satisfiedqty)) FROM tmp_sale AS sale);
  _rc := 1;
  IF (v_invtype = 1) THEN
    v_headerno := (SELECT headerno FROM dbo.imp_saleledger WHERE ((saleinvcode = v_invcode) AND (childserver = v_childserver)));
    _rc := 1;
    v_headerinvno := (SELECT headerinvno FROM dbo.imp_saleledger WHERE ((saleinvcode = v_invcode) AND (childserver = v_childserver)));
    _rc := 1;
  ELSE
    v_headerno := (SELECT headerno FROM dbo.imp_advsaleledger WHERE ((advsaleinvcode = v_invcode) AND (childserver = v_childserver)));
    _rc := 1;
    v_headerinvno := (SELECT headerinvno FROM dbo.imp_advsaleledger WHERE ((advsaleinvcode = v_invcode) AND (childserver = v_childserver)));
    _rc := 1;
  END IF;
  v_continue := 0;
  _rc := 1;
  v_invcounter := 1;
  _rc := 1;
  v_rowgroup := 0;
  _rc := 1;
  WHILE ((v_anyitem_exist > 0) AND (v_continue >= 0)) LOOP
    IF (v_keepinvno = 'N') THEN
      SELECT r.return_value, r.key INTO v_rt_code, v_saleinvcode FROM dbo.sp_gettabmaxkey(tabname => 'Saleledger', key => v_saleinvcode) AS r;
    ELSE
      v_saleinvcode := v_invcode;
      _rc := 1;
    END IF;
    v_rowgroup := 0;
    _rc := 1;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      v_continue := -1;
      _rc := 1;
    ELSE
      IF (v_keepinvno = 'N') THEN
        SELECT r.return_value, r.key INTO v_rt_code, v_headerinvno FROM dbo.sp_getheadertabmaxkey(headercode => (v_headerno)::smallint, modulecode => (v_module)::smallint, key => v_headerinvno) AS r;
      ELSE
        v_headerinvno := v_headerinvno;
        _rc := 1;
      END IF;
      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
        v_continue := -1;
        _rc := 1;
      ELSE
        v_err := 0;
        _rc := 1;
        v_rowcount := 1;
        _rc := 1;
        INSERT INTO dbo.saleledger (saleinvcode, salecatcode, custcode, salesmancode, date, discperc, flatdisc, misccharges, salestax, posted, postdate, remarks, custrefno, headerno, headerinvno, originaldate, modifiedby, postedby, sprice, quotationno, doctcode, patientcode, reprintingcounter, cashreceived, invgstperc1, printwaranty, printbatch, messagecode, smancode, invoicesize, custrefno2, custrefno3, custrefno4, gstno, invtotal, machinename, modifycounter, itemdiscpercno, relationcode, diseasecode, wardcode, admissioncode, returncounter, paid, billingdate, unreceivedbalance, totalofsalereturns, listofsrinvoices, printbalance, accountfor, paymentmode, paymentacccode, amt, amtby, amtdate, amtreference, outstandingamt, marked, transferable, transfered, transferedon, transferedby, imported, importedby, deliveredby, saletypecode, balance, pptcustcode, deleted, prescode, impactinventory, saleordercode, salecomments1, salecomments2, altersaleinvcode, recurringinvoice, recurringperiod, lastrecurringinvcode, recurringagainst, considerinpo, visitcode, duedate, srbufferinvcode, custrefno5, gccode, grn, suppinvcode, vehicle, shipto, guaranteepersoncode, cashtendered, cashcharged, cashback, cashacccode, custlicno, custlicexpiry, moduleid, doccode, saletypeinvno, crs_transfered, crs_transferedon, guestcode, guestcheckincode, studentcode, custsitecode, transmit, transmited, fiscalized, fiscalizedon, fiscalinvoiceno, advancetax, advancetaxamt, fbrposfee) SELECT v_saleinvcode, salecatcode, custcode, salesmancode, date, discperc, (flatdisc + coalesce(v_refund, 0)) AS flatdisc, misccharges, 0 AS salestax, 'Y' AS posted, postdate, remarks, CASE WHEN (v_updaterefno1 = 'Y') THEN ltrim(rtrim(dbo.tsql_str((v_saleinvcode)::numeric))) ELSE custrefno END AS custrefno, v_headerno, v_headerinvno, originaldate, modifiedby, postedby, sprice, quotationno, doctcode, patientcode, reprintingcounter, cashreceived, invgstperc1, printwaranty, printbatch, messagecode, smancode, invoicesize, custrefno2, custrefno3, custrefno4, gstno, invtotal AS invtotal, machinename, modifycounter, itemdiscpercno, relationcode, diseasecode, wardcode, admissioncode AS admissioncode, returncounter, paid, billingdate, unreceivedbalance AS unreceivedbalance, totalofsalereturns AS totalofsalereturns, listofsrinvoices, printbalance, accountfor, paymentmode, paymentacccode, amt, amtby, amtdate, amtreference, outstandingamt, marked, transferable, transfered, transferedon AS transferedon, transferedby AS transferedby, imported, importedby AS importedby, deliveredby AS deliveredby, saletypecode, balance, pptcustcode AS pptcustcode, deleted, prescode AS prescode, impactinventory, saleordercode AS saleordercode, salecomments1, salecomments2, altersaleinvcode, recurringinvoice, recurringperiod, lastrecurringinvcode AS lastrecurringinvcode, recurringagainst AS recurringagainst, considerinpo, visitcode AS visitcode, duedate, srbufferinvcode AS srbufferinvcode, custrefno5 AS custrefno5, gccode AS gccode, grn AS grn, suppinvcode AS suppinvcode, vehicle AS vehicle, shipto AS shipto, guaranteepersoncode AS guaranteepersoncode, cashtendered, cashcharged, cashback AS cashback, cashacccode, custlicno AS custlicno, custlicexpiry AS custlicexpiry, -1 AS moduleid, saleinvcode AS doccode, saletypeinvno, crs_transfered, crs_transferedon AS crs_transferedon, guestcode AS guestcode, guestcheckincode AS guestcheckincode, studentcode AS studentcode, custsitecode AS custsitecode, transmit, transmited, fiscalized, fiscalizedon AS fiscalizedon, fiscalinvoiceno AS fiscalinvoiceno, advancetax, coalesce(advancetaxamt, 0), fbrposfee AS fbrposfee FROM dbo.imp_saleledger WHERE (((v_invtype = 1) AND (saleinvcode = v_invcode)) AND (childserver = v_childserver)) UNION ALL SELECT v_saleinvcode, CASE invtype WHEN 1 THEN v_salecatcode ELSE 2 END AS salecatcode, custcode, salesmancode, date, discperc, (flatdisc + coalesce(v_refund, 0)) AS flatdisc, misccharges, 0 AS salestax, 'Y' AS posted, postdate, remarks, CASE WHEN (v_updaterefno1 = 'Y') THEN ltrim(rtrim(dbo.tsql_str((v_saleinvcode)::numeric))) ELSE custrefno END, v_headerno, v_headerinvno, originaldate, modifiedby, postedby, sprice, quotationno, doctcode, patientcode, reprintingcounter, cashamt AS cashreceived, invgstperc1, printwaranty, printbatch, messagecode, smancode, invoicesize, custrefno2, custrefno3, custrefno4, gstno, 0 AS invtotal, machinename, modifycounter, itemdiscpercno, relationcode, diseasecode, wardcode, NULL::integer AS admissioncode, 0 AS returncounter, 'N' AS paid, billingdate, 0 AS unreceivedbalance, 0 AS totalofsalereturns, '' AS listofsrinvoices, printbalance, 'Y' AS accountfor, paymentmode, paymentacccode, amt, amtby, amtdate, amtreference, outstandingamt, 'N' AS marked, 'Y' AS transferable, 'N' AS transfered, NULL::timestamp AS transferedon, NULL::integer AS transferedby, 'N' AS imported, NULL::integer AS importedby, NULL::integer AS deliveredby, saletypecode, balance, NULL::integer AS pptcustcode, deleted, NULL::integer AS prescode, 'Y' AS impactinventory, NULL::integer AS saleordercode, salecomments1, salecomments2, 0 AS altersaleinvcode, 'N' AS recurringinvoice, 0 AS recurringperiod, NULL::integer AS lastrecurringinvcode, NULL::integer AS recurringagainst, 'Y' AS considerinpo, NULL::integer AS visitcode, date AS duedate, NULL::integer AS srbufferinvcode, NULL::citext AS custrefno5, NULL::integer AS gccode, NULL::citext AS grn, NULL::citext AS suppinvcode, NULL::citext AS vehicle, NULL::citext AS shipto, NULL::integer AS guaranteepersoncode, cashtendered, cashamt AS cashcharged, 0 AS cashback, 2 AS cashacccode, NULL::citext AS custlicno, NULL::timestamp AS custlicexpiry, -1 AS moduleid, advsaleinvcode AS doccode, 0 AS saletypeinvno, 'N' AS crs_transfered, NULL::timestamp AS crs_transferedon, NULL::integer AS guestcode, NULL::integer AS guestcheckincode, NULL::integer AS studentcode, NULL::integer AS custsitecode, transmit, transmited, 'N' AS fiscalized, NULL::timestamp AS fiscalizedon, NULL::citext AS fiscalinvoiceno, 'N' AS advancetax, 0 AS advancetaxamt, 0 AS fbrposfee FROM dbo.imp_advsaleledger WHERE (((v_invtype = 2) AND (advsaleinvcode = v_invcode)) AND (childserver = v_childserver));
        GET DIAGNOSTICS _rc = ROW_COUNT;
        v_err := 0;
        v_rowcount := _rc;
        _rc := 1;
        IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
          RAISE EXCEPTION 'Error occured in inserting record into Sale Ledger : %', v_saleinvcode;
          v_continue := -1;
          _rc := 1;
        ELSE
          v_curr_rowid := 1;
          _rc := 1;
          v_anyitem_exist := (SELECT sum((satisfiableqty - satisfiedqty)) FROM tmp_sale AS sale);
          _rc := 1;
          v_lineitems_rowcount := v_salerowcount;
          _rc := 1;
          v_innercounter := 1;
          _rc := 1;
          WHILE (((((v_salerowcount > 0)) AND ((v_anyitem_exist > 0))) AND ((v_innercounter <= v_lineitems_rowcount))) AND ((v_continue >= 0))) LOOP
            _rc := 0;
            FOR _r1 IN SELECT icode AS c1, gcode AS c2, satisfiableqty AS c3, satisfiedqty AS c4, saleprice AS c5, rate AS c6, packunits AS c7, discperc AS c8, itemflatdisc AS c9, unitsalestax AS c10, gstperc AS c11, saledesc AS c12, itemadvancetaxperc AS c13 FROM tmp_sale AS sale WHERE (id = v_curr_rowid) LOOP
              _rc := _rc + 1;
              v_icode := _r1.c1;
              v_gcode := _r1.c2;
              v_satisfiableqty := _r1.c3;
              v_satisfiedqty := _r1.c4;
              v_saleprice := _r1.c5;
              v_rate := _r1.c6;
              v_packunits := _r1.c7;
              v_discperc := _r1.c8;
              v_itemflatdisc := _r1.c9;
              v_unitsalestax := _r1.c10;
              v_gstperc1 := _r1.c11;
              v_saledesc := _r1.c12;
              v_itemadvancetaxperc := _r1.c13;
            END LOOP;
            v_rowcount := _rc;
            _rc := 1;
            IF (((v_rowcount = 1)) AND ((((v_satisfiableqty - v_satisfiedqty)) > 0))) THEN
              v_givenqty := (v_satisfiableqty - v_satisfiedqty);
              _rc := 1;
              SELECT r.return_value, r.avgprice INTO v_rt_code, v_hold_avgprice FROM dbo.sp_getitemavgprice(icode => v_icode, avgprice => v_hold_avgprice) AS r;
              IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                v_continue := -1;
                _rc := 1;
              ELSE
                SELECT r.return_value, r.qty INTO v_rt_code, v_total_availablestock FROM dbo.sp_getitemstockall(icode => v_icode, qty => v_total_availablestock) AS r;
                IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                  v_continue := -1;
                  _rc := 1;
                END IF;
                v_totalqty := (SELECT coalesce(sum(currqty), 0) FROM dbo.godowndetail WHERE ((godowndetail.gcode = v_gcode) AND (godowndetail.icode = v_icode)));
                _rc := 1;
                v_rowgroup := (v_rowgroup + 1);
                _rc := 1;
                IF ((v_packunits = 0) OR (v_packunits IS NULL)) THEN
                  v_packunits := 1;
                  _rc := 1;
                END IF;
                IF (v_givenqty > 0) THEN
                  IF (v_totalqty >= v_givenqty) THEN
                    v_reqqty := v_givenqty;
                    _rc := 1;
                  ELSE
                    v_reqqty := v_totalqty;
                    _rc := 1;
                  END IF;
                  OPEN cur_itembatch_cursor FOR SELECT batch, expiry, currqty FROM dbo.godowndetail WHERE ((godowndetail.gcode = v_gcode) AND (godowndetail.icode = v_icode)) ORDER BY priority, expiry, currqty;
                  v_totalrows := (-1);
                  _rc := 1;
                  FETCH NEXT FROM cur_itembatch_cursor INTO v_batch, v_expiry, v_currqty;
                  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
                  v_counter := 1;
                  _rc := 1;
                  WHILE (((_fs = 0) AND (v_counter <= v_totalrows)) AND (v_reqqty > 0)) LOOP
                    v_batchqty := v_currqty;
                    _rc := 1;
                    IF (v_batchqty >= v_reqqty) THEN
                      v_delqty := v_reqqty;
                      _rc := 1;
                    ELSE
                      v_delqty := v_batchqty;
                      _rc := 1;
                    END IF;
                    v_reqqty := (v_reqqty - v_delqty);
                    _rc := 1;
                    SELECT r.return_value, r.lbi_maxutn INTO v_rt_code, v_saleutn FROM dbo.sp_maxutn(lbi_rows => (1)::bigint, lbi_maxutn => v_saleutn) AS r;
                    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                      v_continue := -1;
                      _rc := 1;
                    END IF;
                    v_total_availablestock := (v_total_availablestock - v_delqty);
                    _rc := 1;
                    INSERT INTO dbo.saledetail (saleinvcode, icode, gcode, batch, expiry, packqty, looseqty, packunits, saleprice, avgprice, rate, discperc, salestax, itemflatdisc, packprice, unitsalestax, gstperc, saleutn, balancestock, rowgroup, saleitemdescription, itemadvancetaxperc) VALUES (v_saleinvcode, v_icode, v_gcode, v_batch, v_expiry, 0, v_delqty, v_packunits, v_saleprice, v_hold_avgprice, v_rate, v_discperc, 0, v_itemflatdisc, (v_rate * v_packunits), v_unitsalestax, v_gstperc1, v_saleutn, v_total_availablestock, v_rowgroup, v_saledesc, v_itemadvancetaxperc);
                    GET DIAGNOSTICS _rc = ROW_COUNT;
                    v_err := 0;
                    v_rowcount := _rc;
                    _rc := 1;
                    IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
                      RAISE EXCEPTION 'Error occured in inserting record into Sale Detail for Sale Inv. No. : %', v_saleinvcode;
                      v_continue := -1;
                      _rc := 1;
                    ELSE
                      v_newqty := (v_currqty - v_delqty);
                      _rc := 1;
                      IF (v_newqty > 0) THEN
                        SELECT r.return_value INTO v_rt_code FROM dbo.sp_saleupdateitemstockbatch(gcode => v_gcode, icode => v_icode, batch => v_batch, expiry => v_expiry, newqty => v_newqty, oldqty => v_currqty) AS r;
                      ELSE
                        SELECT r.return_value INTO v_rt_code FROM dbo.sp_deleteitemstockbatch(gcode => v_gcode, icode => v_icode, batch => v_batch, expiry => v_expiry, oldqty => v_delqty) AS r;
                      END IF;
                      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                        v_continue := -1;
                        _rc := 1;
                      END IF;
                    END IF;
                    v_counter := (v_counter + 1);
                    _rc := 1;
                    FETCH NEXT FROM cur_itembatch_cursor INTO v_batch, v_expiry, v_currqty;
                    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
                  END LOOP;
                  CLOSE cur_itembatch_cursor;
                  -- DEALLOCATE ItemBatch_Cursor
                  IF (v_totalqty < v_givenqty) THEN
                    v_givenqty := (v_givenqty - v_totalqty);
                    _rc := 1;
                    IF (v_givenqty > 0) THEN
                      SELECT r.return_value, r.lbi_maxutn INTO v_rt_code, v_saleutn FROM dbo.sp_maxutn(lbi_rows => (1)::bigint, lbi_maxutn => v_saleutn) AS r;
                      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                        v_continue := -1;
                        _rc := 1;
                      ELSE
                        INSERT INTO dbo.saledetail (saleinvcode, icode, gcode, due, batch, expiry, packqty, looseqty, packunits, saleprice, avgprice, rate, discperc, salestax, itemflatdisc, packprice, unitsalestax, gstperc, saleutn, balancestock, rowgroup, saleitemdescription) VALUES (v_saleinvcode, v_icode, v_gcode, 'D', 'due', (left(to_char((localtimestamp(3) + (365) * interval '1 day'), 'MM/DD/YYYY'), 100))::timestamp(3), 0, v_givenqty, v_packunits, v_saleprice, v_hold_avgprice, v_rate, v_discperc, 0, v_itemflatdisc, (v_rate * v_packunits), v_unitsalestax, v_gstperc1, v_saleutn, v_total_availablestock, v_rowgroup, v_saledesc);
                        GET DIAGNOSTICS _rc = ROW_COUNT;
                        v_err := 0;
                        v_rowcount := _rc;
                        _rc := 1;
                        IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
                          RAISE EXCEPTION 'Error occured in inserting due record into Sale Detail for Sale Inv. No. : %', v_saleinvcode;
                          v_continue := -1;
                          _rc := 1;
                        END IF;
                      END IF;
                    END IF;
                  END IF;
                END IF;
              END IF;
            END IF;
            UPDATE tmp_sale AS sale SET satisfiedqty = satisfiableqty WHERE (id = v_curr_rowid);
            GET DIAGNOSTICS _rc = ROW_COUNT;
            v_curr_rowid := (v_curr_rowid + 1);
            _rc := 1;
            v_innercounter := (v_innercounter + 1);
            _rc := 1;
            v_anyitem_exist := (SELECT sum((satisfiableqty - satisfiedqty)) FROM tmp_sale AS sale);
            _rc := 1;
          END LOOP;
        END IF;
      END IF;
    END IF;
    v_anyitem_exist := (SELECT sum((satisfiableqty - satisfiedqty)) FROM tmp_sale AS sale);
    _rc := 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_sale;
  IF ((v_continue >= 0)) THEN
    IF (v_saleinvcode > 0) THEN
      INSERT INTO dbo.cashierwindow (saleinvcode, acccode, remarks, amount, rowid) SELECT v_saleinvcode, acccode, remarks, amount, rowid FROM dbo.imp_cashierwindow WHERE (((childserver = v_childserver) AND (saleinvcode = v_invcode)) AND (saleinvcode IN (SELECT saleinvcode FROM dbo.imp_saleledger WHERE (((v_invtype = 1) AND (saleinvcode = v_invcode)) AND (childserver = v_childserver)))));
      GET DIAGNOSTICS _rc = ROW_COUNT;
      UPDATE dbo.saleledger SET invtotal = dbo.fn_getsaleinvtotal((saleledger.saleinvcode)::integer) WHERE (saleinvcode = v_saleinvcode);
      GET DIAGNOSTICS _rc = ROW_COUNT;
      v_err := 0;
      v_rowcount := _rc;
      _rc := 1;
      IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
        RAISE EXCEPTION 'Unable to update Sale Invoice for Sale Inv. total';
        v_continue := -1;
        _rc := 1;
      END IF;
      IF (v_updateloyaltypoints = 'Y') THEN
        SELECT r.return_value INTO v_rt_code FROM dbo.sp_manageloyaltypoints(invtype => 'SV', invoicecode => v_saleinvcode) AS r;
        IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
          RAISE EXCEPTION 'Unable to update loyalty points On Sale Invoice : %', v_saleinvcode;
          v_continue := -1;
          _rc := 1;
        END IF;
      END IF;
    END IF;
  END IF;
  return_value := v_continue;
  saleinvcode := v_saleinvcode;
  RETURN;
  return_value := 0;
  saleinvcode := v_saleinvcode;
  RETURN;
END
$body$;

-- ==== proc sp_Translate_ChildeServer_SaleReturn ====
CREATE OR REPLACE FUNCTION dbo.sp_translate_childeserver_salereturn(childserver citext, advsaleinvcode integer, usercode integer, refund numeric, INOUT srinvcode integer, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_childserver citext;
  v_advsaleinvcode integer;
  v_usercode integer;
  v_refund numeric(10,2);
  v_srinvcode integer;
  v_sale numeric(15,4);
  v_headerno integer;
  v_gcode integer;
  v_curr_rowid integer;
  v_module integer;
  v_custcode integer;
  v_saletypecode smallint;
  v_srcatcode integer;
  v_headerinvno integer;
  v_continue integer;
  v_rt_code integer;
  v_err integer;
  v_totalrows integer;
  v_rowcount integer;
  v_invcounter integer;
  v_counter integer;
  v_satisfiableqty numeric(15,4);
  v_item_in_inv_exist integer;
  v_srprice numeric(12,2);
  v_rate numeric(12,2);
  v_discperc numeric(5,2);
  v_itemflatdisc numeric(15,2);
  v_unitsalestax numeric(12,2);
  v_gstperc1 numeric(6,2);
  v_gstperc2 numeric(6,2);
  v_hold_avgprice numeric(15,5);
  v_icode integer;
  v_anyitem_exist integer;
  v_packunits integer;
  v_totalqty numeric(15,4);
  v_givenqty numeric(15,4);
  v_reqqty numeric(15,4);
  v_batchqty numeric(15,4);
  v_delqty numeric(15,4);
  v_currqty numeric(15,4);
  v_newqty numeric(15,4);
  v_totalstock numeric(15,4);
  v_batch citext;
  v_itemname citext;
  v_expiry timestamp(3);
  v_serverdate timestamp(3);
  v_saleutn bigint;
  v_firsttime smallint;
  v_advsale_rowcount integer;
  v_rowgroup integer;
  v_lineitems_rowcount integer;
  v_innercounter integer;
  _r1 record;
  _rc integer;
BEGIN
  v_childserver := childserver;
  v_advsaleinvcode := advsaleinvcode;
  v_usercode := usercode;
  v_refund := refund;
  v_srinvcode := srinvcode;
  -- SET NOCOUNT ON
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  v_firsttime := 0;
  _rc := 1;
  v_custcode := 19;
  _rc := 1;
  v_srcatcode := 8;
  _rc := 1;
  v_saletypecode := 2;
  _rc := 1;
  v_module := (SELECT module FROM dbo.module WHERE (name = 'SALES RETURN'));
  _rc := 1;
  v_serverdate := localtimestamp(3);
  _rc := 1;
  DROP TABLE IF EXISTS tmp_salereturn;
  CREATE TEMP TABLE tmp_salereturn (
    id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    icode integer,
    gcode integer,
    batch citext,
    satisfiableqty numeric(15,4),
    saleprice numeric(12,2),
    rate numeric(12,2),
    packunits smallint NOT NULL,
    discperc numeric(8,2),
    itemflatdisc numeric(12,2),
    unitsalestax numeric(12,2),
    gstperc numeric(6,2)
) ON COMMIT DROP;
  INSERT INTO tmp_salereturn (icode, gcode, batch, satisfiableqty, saleprice, rate, packunits, discperc, itemflatdisc, unitsalestax, gstperc) SELECT icode, gcode, batch, sum(abs(looseqty)), saleprice, rate, packunits, discperc, itemflatdisc, unitsalestax, gstperc FROM dbo.imp_advsaledetail WHERE (((childserver = v_childserver) AND (advsaleinvcode = v_advsaleinvcode)) AND (looseqty < 0)) GROUP BY icode, gcode, batch, saleprice, rate, packunits, discperc, itemflatdisc, unitsalestax, gstperc ORDER BY icode;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_sale := coalesce((SELECT sum(looseqty) FROM dbo.imp_advsaledetail WHERE (((childserver = v_childserver) AND (advsaleinvcode = v_advsaleinvcode)) AND (looseqty > 0))), 0);
  _rc := 1;
  v_advsale_rowcount := coalesce((SELECT count(*) FROM dbo.imp_advsaledetail WHERE ((childserver = v_childserver) AND (advsaleinvcode = v_advsaleinvcode))), 0);
  _rc := 1;
  v_anyitem_exist := trunc((SELECT sum(abs(satisfiableqty)) FROM tmp_salereturn AS salereturn))::integer;
  _rc := 1;
  v_headerno := (SELECT headerno FROM dbo.imp_advsaleledger WHERE ((childserver = v_childserver) AND (advsaleinvcode = v_advsaleinvcode)));
  _rc := 1;
  v_continue := 0;
  _rc := 1;
  v_invcounter := 1;
  _rc := 1;
  v_rowgroup := 0;
  _rc := 1;
  WHILE ((v_anyitem_exist > 0) AND (v_continue >= 0)) LOOP
    SELECT r.return_value, r.key INTO v_rt_code, v_srinvcode FROM dbo.sp_gettabmaxkey(tabname => 'SRledger', key => v_srinvcode) AS r;
    v_rowgroup := 0;
    _rc := 1;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      v_continue := -1;
      _rc := 1;
    ELSE
      SELECT r.return_value, r.key INTO v_rt_code, v_headerinvno FROM dbo.sp_getheadertabmaxkey(headercode => (v_headerno)::smallint, modulecode => (v_module)::smallint, key => v_headerinvno) AS r;
      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
        v_continue := -1;
        _rc := 1;
      ELSE
        v_err := 0;
        _rc := 1;
        v_rowcount := 1;
        _rc := 1;
        INSERT INTO dbo.srledger (srinvcode, saleinvcode, date, srcatcode, custcode, salesmancode, discperc, flatdisc, misccharges, posted, postdate, remarks, salestax, originaldate, modifiedby, postedby, headerno, invgstperc1, smancode, custrefno, custrefno2, custrefno3, custrefno4, patientcode, machinename, headerinvno, admissioncode, invtotal, accountfor, paymentmode, paymentacccode, amt, amtby, amtdate, amtreference, outstandingamt, marked, pagesize, reprintingcounter, doctcode, considerinpo) SELECT v_srinvcode, NULL::integer AS saleinvcode, date, CASE invtype WHEN 1 THEN v_srcatcode ELSE 7 END AS srcatcode, custcode, salesmancode, discperc, CASE WHEN (v_sale = 0) THEN flatdisc ELSE 0 END AS flatdisc, (CASE WHEN (v_sale = 0) THEN misccharges ELSE 0 END + coalesce(v_refund, 0)) AS misccharges, 'Y' AS posted, localtimestamp(3) AS postdate, remarks, 0 AS salestax, originaldate, modifiedby, v_usercode AS postedby, v_headerno, invgstperc1, smancode, custrefno, custrefno2, custrefno3, custrefno4, patientcode, machinename, v_headerinvno, NULL::integer AS admissioncode, 0 AS invtotal, 'Y' AS accountfor, paymentmode, paymentacccode, amt, amtby, amtdate, amtreference, outstandingamt, 'N' AS marked, invoicesize, 0 AS reprintingcounter, doctcode, 'Y' AS considerinpo FROM dbo.imp_advsaleledger WHERE ((childserver = v_childserver) AND (advsaleinvcode = v_advsaleinvcode));
        GET DIAGNOSTICS _rc = ROW_COUNT;
        v_err := 0;
        v_rowcount := _rc;
        _rc := 1;
        IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
          RAISE EXCEPTION 'Error occured in inserting record into Sale Return Ledger : %', v_srinvcode;
          v_continue := -1;
          _rc := 1;
        ELSE
          v_curr_rowid := 1;
          _rc := 1;
          v_anyitem_exist := trunc((SELECT sum(satisfiableqty) FROM tmp_salereturn AS salereturn))::integer;
          _rc := 1;
          v_lineitems_rowcount := v_advsale_rowcount;
          _rc := 1;
          v_innercounter := 1;
          _rc := 1;
          WHILE (((((v_advsale_rowcount > 0)) AND ((v_anyitem_exist > 0))) AND ((v_innercounter <= v_lineitems_rowcount))) AND ((v_continue >= 0))) LOOP
            _rc := 0;
            FOR _r1 IN SELECT icode AS c1, gcode AS c2, coalesce((SELECT dbo.fn_getpreference('defaultbatch')), '.') AS c3, (date_trunc('day', (SELECT (localtimestamp(3) + ((SELECT dbo.fn_get_int_preference('expiry'))) * interval '1 day'))))::timestamp(3) AS c4, satisfiableqty AS c5, saleprice AS c6, rate AS c7, packunits AS c8, discperc AS c9, itemflatdisc AS c10, unitsalestax AS c11, gstperc AS c12 FROM tmp_salereturn AS salereturn WHERE (id = v_curr_rowid) LOOP
              _rc := _rc + 1;
              v_icode := _r1.c1;
              v_gcode := _r1.c2;
              v_batch := _r1.c3;
              v_expiry := _r1.c4;
              v_satisfiableqty := _r1.c5;
              v_srprice := _r1.c6;
              v_rate := _r1.c7;
              v_packunits := _r1.c8;
              v_discperc := _r1.c9;
              v_itemflatdisc := _r1.c10;
              v_unitsalestax := _r1.c11;
              v_gstperc1 := _r1.c12;
            END LOOP;
            v_rowcount := _rc;
            _rc := 1;
            IF (((v_rowcount = 1)) AND ((v_satisfiableqty > 0))) THEN
              v_givenqty := v_satisfiableqty;
              _rc := 1;
              SELECT r.return_value, r.avgprice INTO v_rt_code, v_hold_avgprice FROM dbo.sp_getitemavgprice(icode => v_icode, avgprice => v_hold_avgprice) AS r;
              IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                v_continue := -1;
                _rc := 1;
              ELSE
                v_totalstock := (SELECT coalesce(sum(currqty), 0) FROM dbo.godowndetail WHERE (godowndetail.icode = v_icode));
                _rc := 1;
                v_totalqty := (SELECT coalesce(sum(currqty), 0) FROM dbo.godowndetail WHERE ((godowndetail.gcode = v_gcode) AND (godowndetail.icode = v_icode)));
                _rc := 1;
                v_rowgroup := (v_rowgroup + 1);
                _rc := 1;
                IF ((v_packunits = 0) OR (v_packunits IS NULL)) THEN
                  v_packunits := 1;
                  _rc := 1;
                END IF;
                IF (v_givenqty > 0) THEN
                  SELECT r.return_value, r.lbi_maxutn INTO v_rt_code, v_saleutn FROM dbo.sp_maxutn(lbi_rows => (1)::bigint, lbi_maxutn => v_saleutn) AS r;
                  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                    v_continue := -1;
                    _rc := 1;
                  END IF;
                  INSERT INTO dbo.srdetail (srinvcode, icode, gcode, batch, expiry, packqty, looseqty, packunits, srprice, discperc, salestax, avgprice, unitsalestax, gstperc, srutn, bonusqty, saleprice, salerowid, currstock) SELECT v_srinvcode, v_icode, v_gcode, v_batch, v_expiry, 0, v_givenqty, v_packunits, ((v_srprice - v_itemflatdisc)), v_discperc, 0, v_hold_avgprice, v_unitsalestax, v_gstperc1, v_saleutn, 0, ((v_srprice - v_itemflatdisc)), NULL::integer, v_totalstock;
                  GET DIAGNOSTICS _rc = ROW_COUNT;
                  v_err := 0;
                  v_rowcount := _rc;
                  _rc := 1;
                  IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
                    RAISE EXCEPTION 'Error occured in inserting record into Sale Return Detail for Sale Return No. : %', v_srinvcode;
                    v_continue := -1;
                    _rc := 1;
                  ELSE
                    v_currqty := 0;
                    _rc := 1;
                    SELECT r.return_value, r.qty INTO v_rt_code, v_currqty FROM dbo.sp_getitemstockbatch(gcode => v_gcode, icode => v_icode, batch => v_batch, expiry => v_expiry, qty => v_currqty) AS r;
                    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                      RAISE EXCEPTION 'Error occured in checking Batch details of some items during processing of Sale Return No. : %', v_srinvcode;
                      v_continue := -1;
                      _rc := 1;
                    END IF;
                    v_newqty := (coalesce(v_currqty, 0) + coalesce(v_givenqty, 0));
                    _rc := 1;
                    rs1 := NULL;
                    OPEN rs1 FOR SELECT v_curr_rowid AS row, v_gcode AS gcode, v_icode AS icode, v_batch AS batch, v_expiry AS expiry, v_currqty AS qty, v_givenqty AS thisqty, v_newqty AS newqty;
                    IF (v_newqty > 0) THEN
                      SELECT r.return_value INTO v_rt_code FROM dbo.sp_updateitemstockbatch(gcode => v_gcode, icode => v_icode, batch => v_batch, expiry => v_expiry, newqty => v_newqty, manfdate => NULL) AS r;
                      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                        RAISE EXCEPTION 'Error occured in updation of Batch details of some items during processing of Sale Return No. : %', v_srinvcode;
                        v_continue := -1;
                        _rc := 1;
                      END IF;
                    END IF;
                  END IF;
                  v_counter := (v_counter + 1);
                  _rc := 1;
                END IF;
              END IF;
            END IF;
            UPDATE tmp_salereturn AS salereturn SET satisfiableqty = 0 WHERE (id = v_curr_rowid);
            GET DIAGNOSTICS _rc = ROW_COUNT;
            v_curr_rowid := (v_curr_rowid + 1);
            _rc := 1;
            v_innercounter := (v_innercounter + 1);
            _rc := 1;
            v_anyitem_exist := trunc((SELECT sum(satisfiableqty) FROM tmp_salereturn AS salereturn))::integer;
            _rc := 1;
          END LOOP;
        END IF;
      END IF;
    END IF;
    v_anyitem_exist := trunc((SELECT sum(satisfiableqty) FROM tmp_salereturn AS salereturn))::integer;
    _rc := 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_salereturn;
  IF ((v_continue >= 0)) THEN
    IF (v_srinvcode > 0) THEN
      UPDATE dbo.srledger SET invtotal = coalesce(dbo.fn_getsrinvtotal((srledger.srinvcode)::integer), 0) WHERE (srinvcode = v_srinvcode);
      GET DIAGNOSTICS _rc = ROW_COUNT;
      v_err := 0;
      v_rowcount := _rc;
      _rc := 1;
      IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
        RAISE EXCEPTION 'Unable to update Sale Return Invoices for Inv. total';
        v_continue := -1;
        _rc := 1;
      END IF;
    END IF;
  END IF;
  return_value := v_continue;
  srinvcode := v_srinvcode;
  RETURN;
  return_value := 0;
  srinvcode := v_srinvcode;
  RETURN;
END
$body$;

-- ==== proc sp_Translate_ChildeServer_SReturn ====
CREATE OR REPLACE FUNCTION dbo.sp_translate_childeserver_sreturn(childserver citext, oldsrinvcode integer, usercode integer, INOUT srinvcode integer, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_childserver citext;
  v_oldsrinvcode integer;
  v_usercode integer;
  v_srinvcode integer;
  v_sale numeric(15,4);
  v_headerno integer;
  v_gcode integer;
  v_curr_rowid integer;
  v_module integer;
  v_custcode integer;
  v_saletypecode smallint;
  v_srcatcode integer;
  v_headerinvno integer;
  v_continue integer;
  v_rt_code integer;
  v_err integer;
  v_totalrows integer;
  v_rowcount integer;
  v_invcounter integer;
  v_counter integer;
  v_looseqty numeric(15,4);
  v_bonusqty numeric(15,4);
  v_item_in_inv_exist integer;
  v_srprice numeric(12,2);
  v_rate numeric(12,2);
  v_discperc numeric(5,2);
  v_itemflatdisc numeric(15,2);
  v_unitsalestax numeric(12,2);
  v_gstperc1 numeric(6,2);
  v_gstperc2 numeric(6,2);
  v_hold_avgprice numeric(15,5);
  v_icode integer;
  v_anyitem_exist integer;
  v_packunits integer;
  v_totalqty numeric(15,4);
  v_givenqty numeric(15,4);
  v_reqqty numeric(15,4);
  v_batchqty numeric(15,4);
  v_delqty numeric(15,4);
  v_currqty numeric(15,4);
  v_newqty numeric(15,4);
  v_totalstock numeric(15,4);
  v_itemadvancetaxperc numeric(5,2);
  v_batch citext;
  v_returndesc citext;
  v_itemname citext;
  v_expiry timestamp(3);
  v_serverdate timestamp(3);
  v_saleutn bigint;
  v_firsttime smallint;
  v_keepinvno citext;
  v_updaterefno1 citext;
  v_advsale_rowcount integer;
  v_rowgroup integer;
  v_lineitems_rowcount integer;
  v_innercounter integer;
  v_updateloyaltypoints citext;
  _r1 record;
  _rc integer;
BEGIN
  v_childserver := childserver;
  v_oldsrinvcode := oldsrinvcode;
  v_usercode := usercode;
  v_srinvcode := srinvcode;
  -- SET NOCOUNT ON
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  v_keepinvno := coalesce((SELECT dbo.fn_getpreference('KeepChildServerInvoiceNoIntact')), 'N');
  _rc := 1;
  v_updaterefno1 := coalesce((SELECT dbo.fn_getpreference('CopyChildServerInvoiceNoInRef1')), 'N');
  _rc := 1;
  v_firsttime := 0;
  _rc := 1;
  v_custcode := 19;
  _rc := 1;
  v_srcatcode := 8;
  _rc := 1;
  v_saletypecode := 2;
  _rc := 1;
  v_module := (SELECT module FROM dbo.module WHERE (name = 'SALES RETURN'));
  _rc := 1;
  v_serverdate := localtimestamp(3);
  _rc := 1;
  v_updateloyaltypoints := coalesce((SELECT dbo.fn_getpreference('ApplyLoyaltypolicyonsaleposting')), 'N');
  _rc := 1;
  DROP TABLE IF EXISTS tmp_salereturn;
  CREATE TEMP TABLE tmp_salereturn (
    id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    icode integer,
    gcode integer,
    batch citext,
    expiry timestamp(3),
    looseqty numeric(15,4),
    bonusqty numeric(15,4),
    srprice numeric(12,2),
    packunits smallint NOT NULL,
    discperc numeric(8,2),
    unitsalestax numeric(12,2),
    gstperc numeric(6,2),
    returndesc citext,
    itemadvancetaxperc numeric(5,2)
) ON COMMIT DROP;
  INSERT INTO tmp_salereturn (icode, gcode, batch, expiry, looseqty, bonusqty, srprice, packunits, discperc, unitsalestax, gstperc, returndesc, itemadvancetaxperc) SELECT icode, gcode, batch, expiry, sum(abs(looseqty)), sum(abs(bonusqty)) AS bonusqty, srprice, packunits, discperc, unitsalestax, gstperc, returnitemdescription, itemadvancetaxperc FROM dbo.imp_srdetail WHERE ((childserver = v_childserver) AND (srinvcode = v_oldsrinvcode)) GROUP BY icode, gcode, batch, expiry, srprice, packunits, discperc, unitsalestax, gstperc, returnitemdescription, itemadvancetaxperc ORDER BY icode;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_sale := coalesce((SELECT sum(looseqty) FROM dbo.imp_srdetail WHERE (((childserver = v_childserver) AND (srinvcode = v_oldsrinvcode)) AND (looseqty > 0))), 0);
  _rc := 1;
  v_advsale_rowcount := coalesce((SELECT count(*) FROM dbo.imp_srdetail WHERE ((childserver = v_childserver) AND (srinvcode = v_oldsrinvcode))), 0);
  _rc := 1;
  v_anyitem_exist := trunc((SELECT sum(abs(looseqty)) FROM tmp_salereturn AS salereturn))::integer;
  _rc := 1;
  v_headerno := (SELECT headerno FROM dbo.imp_srledger WHERE ((childserver = v_childserver) AND (srinvcode = v_oldsrinvcode)));
  _rc := 1;
  v_headerinvno := (SELECT headerinvno FROM dbo.imp_srledger WHERE ((childserver = v_childserver) AND (srinvcode = v_oldsrinvcode)));
  _rc := 1;
  v_continue := 0;
  _rc := 1;
  v_invcounter := 1;
  _rc := 1;
  v_rowgroup := 0;
  _rc := 1;
  WHILE ((v_anyitem_exist > 0) AND (v_continue >= 0)) LOOP
    IF (v_keepinvno = 'N') THEN
      SELECT r.return_value, r.key INTO v_rt_code, v_srinvcode FROM dbo.sp_gettabmaxkey(tabname => 'SRledger', key => v_srinvcode) AS r;
    ELSE
      v_srinvcode := v_oldsrinvcode;
      _rc := 1;
    END IF;
    v_rowgroup := 0;
    _rc := 1;
    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
      v_continue := -1;
      _rc := 1;
    ELSE
      IF (v_keepinvno = 'N') THEN
        SELECT r.return_value, r.key INTO v_rt_code, v_headerinvno FROM dbo.sp_getheadertabmaxkey(headercode => (v_headerno)::smallint, modulecode => (v_module)::smallint, key => v_headerinvno) AS r;
      ELSE
        v_headerinvno := v_headerinvno;
        _rc := 1;
      END IF;
      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
        v_continue := -1;
        _rc := 1;
      ELSE
        v_err := 0;
        _rc := 1;
        v_rowcount := 1;
        _rc := 1;
        INSERT INTO dbo.srledger (srinvcode, saleinvcode, date, srcatcode, custcode, salesmancode, discperc, flatdisc, misccharges, posted, postdate, remarks, salestax, originaldate, modifiedby, postedby, headerno, invgstperc1, smancode, custrefno, custrefno2, custrefno3, custrefno4, patientcode, machinename, headerinvno, admissioncode, invtotal, accountfor, paymentmode, paymentacccode, amt, amtby, amtdate, amtreference, outstandingamt, marked, pagesize, reprintingcounter, doctcode, considerinpo, cashacccode, cashtendered, cashcharged, cashback, retviabillsummary, crs_transfered, crs_transferedon, guestcode, guestcheckincode, studentcode, synced, syncedon, syncedby, currencycode, conversionrate, fiscalized, fiscalizedon, fiscalinvoiceno, transmit, transmited, advancetax, advancetaxamt, fbrposfee) SELECT v_srinvcode, NULL::integer AS saleinvcode, date, srcatcode, custcode, salesmancode, discperc, flatdisc, misccharges, 'Y' AS posted, localtimestamp(3) AS postdate, remarks, 0 AS salestax, originaldate, modifiedby, v_usercode AS postedby, v_headerno, invgstperc1, smancode, CASE WHEN (v_updaterefno1 = 'Y') THEN ltrim(rtrim(dbo.tsql_str((v_srinvcode)::numeric))) ELSE custrefno END AS custrefno, custrefno2, custrefno3, custrefno AS custrefno4, patientcode, machinename, v_headerinvno, NULL::integer AS admissioncode, invtotal, accountfor, paymentmode, paymentacccode, amt, amtby, amtdate, amtreference, outstandingamt, 'N' AS marked, pagesize, reprintingcounter, doctcode, considerinpo, cashacccode, cashtendered, cashcharged, cashback, retviabillsummary, crs_transfered, crs_transferedon, guestcode, guestcheckincode, studentcode, synced, syncedon, syncedby, currencycode, conversionrate, fiscalized, fiscalizedon, fiscalinvoiceno, 'N' AS transmit, 'N' AS transmited, advancetax, advancetaxamt, fbrposfee FROM dbo.imp_srledger WHERE ((childserver = v_childserver) AND (srinvcode = v_oldsrinvcode));
        GET DIAGNOSTICS _rc = ROW_COUNT;
        v_err := 0;
        v_rowcount := _rc;
        _rc := 1;
        IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
          RAISE EXCEPTION 'Error occured in inserting record into Sale Return Ledger : %', v_srinvcode;
          v_continue := -1;
          _rc := 1;
        ELSE
          v_curr_rowid := 1;
          _rc := 1;
          v_anyitem_exist := trunc((SELECT sum((looseqty + bonusqty)) FROM tmp_salereturn AS salereturn))::integer;
          _rc := 1;
          v_lineitems_rowcount := v_advsale_rowcount;
          _rc := 1;
          v_innercounter := 1;
          _rc := 1;
          WHILE (((((v_advsale_rowcount > 0)) AND ((v_anyitem_exist > 0))) AND ((v_innercounter <= v_lineitems_rowcount))) AND ((v_continue >= 0))) LOOP
            _rc := 0;
            FOR _r1 IN SELECT icode AS c1, gcode AS c2, batch AS c3, expiry AS c4, looseqty AS c5, bonusqty AS c6, srprice AS c7, packunits AS c8, discperc AS c9, unitsalestax AS c10, gstperc AS c11, returndesc AS c12, itemadvancetaxperc AS c13 FROM tmp_salereturn AS salereturn WHERE (id = v_curr_rowid) LOOP
              _rc := _rc + 1;
              v_icode := _r1.c1;
              v_gcode := _r1.c2;
              v_batch := _r1.c3;
              v_expiry := _r1.c4;
              v_looseqty := _r1.c5;
              v_bonusqty := _r1.c6;
              v_srprice := _r1.c7;
              v_packunits := _r1.c8;
              v_discperc := _r1.c9;
              v_unitsalestax := _r1.c10;
              v_gstperc1 := _r1.c11;
              v_returndesc := _r1.c12;
              v_itemadvancetaxperc := _r1.c13;
            END LOOP;
            v_rowcount := _rc;
            _rc := 1;
            IF (((v_rowcount = 1)) AND ((v_looseqty > 0))) THEN
              v_givenqty := (v_looseqty + v_bonusqty);
              _rc := 1;
              SELECT r.return_value, r.avgprice INTO v_rt_code, v_hold_avgprice FROM dbo.sp_getitemavgprice(icode => v_icode, avgprice => v_hold_avgprice) AS r;
              IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                v_continue := -1;
                _rc := 1;
              ELSE
                v_totalstock := (SELECT coalesce(sum(currqty), 0) FROM dbo.godowndetail WHERE (godowndetail.icode = v_icode));
                _rc := 1;
                v_totalqty := (SELECT coalesce(sum(currqty), 0) FROM dbo.godowndetail WHERE ((godowndetail.gcode = v_gcode) AND (godowndetail.icode = v_icode)));
                _rc := 1;
                v_rowgroup := (v_rowgroup + 1);
                _rc := 1;
                IF ((v_packunits = 0) OR (v_packunits IS NULL)) THEN
                  v_packunits := 1;
                  _rc := 1;
                END IF;
                IF (v_givenqty > 0) THEN
                  SELECT r.return_value, r.lbi_maxutn INTO v_rt_code, v_saleutn FROM dbo.sp_maxutn(lbi_rows => (1)::bigint, lbi_maxutn => v_saleutn) AS r;
                  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                    v_continue := -1;
                    _rc := 1;
                  END IF;
                  INSERT INTO dbo.srdetail (srinvcode, icode, gcode, batch, expiry, packqty, looseqty, packunits, srprice, discperc, salestax, avgprice, unitsalestax, gstperc, srutn, bonusqty, saleprice, salerowid, returnitemdescription, itemadvancetaxperc, currstock) SELECT v_srinvcode, v_icode, v_gcode, v_batch, v_expiry, 0, v_looseqty, v_packunits, v_srprice, v_discperc, 0, v_hold_avgprice, v_unitsalestax, v_gstperc1, v_saleutn, v_bonusqty, v_srprice, NULL::integer, v_returndesc, v_itemadvancetaxperc, v_totalstock;
                  GET DIAGNOSTICS _rc = ROW_COUNT;
                  v_err := 0;
                  v_rowcount := _rc;
                  _rc := 1;
                  IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
                    RAISE EXCEPTION 'Error occured in inserting record into Sale Return Detail for Sale Return No. : %', v_srinvcode;
                    v_continue := -1;
                    _rc := 1;
                  ELSE
                    v_currqty := 0;
                    _rc := 1;
                    SELECT r.return_value, r.qty INTO v_rt_code, v_currqty FROM dbo.sp_getitemstockbatch(gcode => v_gcode, icode => v_icode, batch => v_batch, expiry => v_expiry, qty => v_currqty) AS r;
                    IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                      RAISE EXCEPTION 'Error occured in checking Batch details of some items during processing of Sale Return No. : %', v_srinvcode;
                      v_continue := -1;
                      _rc := 1;
                    END IF;
                    v_newqty := (coalesce(v_currqty, 0) + coalesce(v_givenqty, 0));
                    _rc := 1;
                    rs1 := NULL;
                    OPEN rs1 FOR SELECT v_curr_rowid AS row, v_gcode AS gcode, v_icode AS icode, v_batch AS batch, v_expiry AS expiry, v_currqty AS qty, v_givenqty AS thisqty, v_newqty AS newqty;
                    IF (v_newqty > 0) THEN
                      SELECT r.return_value INTO v_rt_code FROM dbo.sp_updateitemstockbatch(gcode => v_gcode, icode => v_icode, batch => v_batch, expiry => v_expiry, newqty => v_newqty, manfdate => NULL) AS r;
                      IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
                        RAISE EXCEPTION 'Error occured in updation of Batch details of some items during processing of Sale Return No. : %', v_srinvcode;
                        v_continue := -1;
                        _rc := 1;
                      END IF;
                    END IF;
                  END IF;
                  v_counter := (v_counter + 1);
                  _rc := 1;
                END IF;
              END IF;
            END IF;
            UPDATE tmp_salereturn AS salereturn SET looseqty = 0, bonusqty = 0 WHERE (id = v_curr_rowid);
            GET DIAGNOSTICS _rc = ROW_COUNT;
            v_curr_rowid := (v_curr_rowid + 1);
            _rc := 1;
            v_innercounter := (v_innercounter + 1);
            _rc := 1;
            v_anyitem_exist := trunc((SELECT sum((looseqty + bonusqty)) FROM tmp_salereturn AS salereturn))::integer;
            _rc := 1;
          END LOOP;
        END IF;
      END IF;
    END IF;
    v_anyitem_exist := trunc((SELECT sum((looseqty + bonusqty)) FROM tmp_salereturn AS salereturn))::integer;
    _rc := 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_salereturn;
  IF ((v_continue >= 0)) THEN
    IF (v_srinvcode > 0) THEN
      UPDATE dbo.srledger SET invtotal = coalesce(dbo.fn_getsrinvtotal((srledger.srinvcode)::integer), 0) WHERE (srinvcode = v_srinvcode);
      GET DIAGNOSTICS _rc = ROW_COUNT;
      v_err := 0;
      v_rowcount := _rc;
      _rc := 1;
      IF ((v_err <> 0) OR (v_rowcount = 0)) THEN
        RAISE EXCEPTION 'Unable to update Sale Return Invoices for Inv. total';
        v_continue := -1;
        _rc := 1;
      END IF;
      IF (v_updateloyaltypoints = 'Y') THEN
        SELECT r.return_value INTO v_rt_code FROM dbo.sp_manageloyaltypoints(invtype => 'SR', invoicecode => v_srinvcode) AS r;
        IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
          RAISE EXCEPTION 'Unable to update loyalty points On S/R Invoice : %', v_srinvcode;
          v_continue := -1;
          _rc := 1;
        END IF;
      END IF;
    END IF;
  END IF;
  return_value := v_continue;
  srinvcode := v_srinvcode;
  RETURN;
  return_value := 0;
  srinvcode := v_srinvcode;
  RETURN;
END
$body$;

-- ==== proc SP_Transmit_ChildServerSales ====
CREATE OR REPLACE FUNCTION dbo.sp_transmit_childserversales(custcode integer, startdate timestamp, enddate timestamp, srv citext, parentsrv citext, db citext, owner citext, saletype integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_custcode integer;
  v_startdate timestamp(3);
  v_enddate timestamp(3);
  v_srv citext;
  v_parentsrv citext;
  v_db citext;
  v_owner citext;
  v_saletype integer;
  v_ins citext;
  v_sql citext;
  v_whr citext;
  v_whr_cln citext;
  v_query citext;
  v_stdate citext;
  v_edate citext;
  v_err integer;
  v_rt_code integer;
  v_dt timestamp(3);
  _dq1 text;
  _dq2 text;
  _dq3 text;
  _dq4 text;
BEGIN
  v_custcode := custcode;
  v_startdate := startdate;
  v_enddate := enddate;
  v_srv := srv;
  v_parentsrv := parentsrv;
  v_db := db;
  v_owner := owner;
  v_saletype := saletype;
  -- SET XACT_ABORT ON
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  v_stdate := (SELECT ((left(to_char(v_startdate, 'MM-DD-YYYY'), 100) || ' ') || left(to_char(v_startdate, 'HH24:MI:SS:MS'), 100)));
  v_edate := (SELECT ((left(to_char(v_enddate, 'MM-DD-YYYY'), 100) || ' ') || left(to_char(v_enddate, 'HH24:MI:SS:MS'), 100)));
  IF (v_saletype = 1) THEN
    v_ins := (((((('INSERT INTO ' || ltrim(rtrim(v_parentsrv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.IMP_SaleLedger ');
    v_sql := (((' SELECT ServerName=' || '''') || v_srv) || ''', TransDate=GETDATE(), InvType = 1, SaleInvCode, SaleCatCode , CustCode , SalesmanCode, date, DiscPerc, FlatDisc, MiscCharges, SalesTax, Posted, PostDate, Remarks, CustRefNo, headerno, headerinvno, OriginalDate, ModifiedBy, PostedBy, SPrice, QuotationNo, DoctCode, PatientCode, RePrintingCounter, CashReceived, InvGSTPerc1, PrintWaranty, PrintBatch, MessageCode, SManCode, InvoiceSize, CustRefno2, CustRefno3, CustRefno4, GSTNO, InvTotal, MachineName, ModifyCounter, itemdiscpercno, RelationCode, DiseaseCode, WardCode, AdmissionCode, ReturnCounter, Paid, BillingDate, UnReceivedBalance, TotalOfSaleReturns, ListOfSrInvoices, printbalance, AccountFor, PaymentMode, PaymentAccCode, Amt, AmtBY, AmtDate, AmtReference, OutstandingAmt, Marked, Transferable, Transfered, TransferedOn, TransferedBy, Imported, ImportedBy, deliveredby, SaleTypeCode, Balance, PptCustCode, DELETED, PresCode, ImpactInventory, SaleOrderCode, SaleComments1, SaleComments2, AlterSaleInvCode, RecurringInvoice, RecurringPeriod, LastRecurringInvCode, RecurringAgainst, ConsiderInPO, VisitCode, DueDate, SRBufferInvCode, CustRefNo5, GCCode, GRN, SuppInvCode,  Vehicle, ShipTo, GuaranteePersonCode, CashTendered, CashCharged, CashBack, CashAccCode, CustLicNo, CustLicExpiry, ModuleId, DocCode=SaleInvCode, SaleTypeInvNo, CRS_Transfered, CRS_TransferedOn, GuestCode, GuestCheckInCode, StudentCode, CustSiteCode, Transmit, Transmited, Fiscalized, FiscalizedOn, FiscalInvoiceNo, AdvanceTax, ISNULL(AdvanceTaxAmt, 0), FBRPOSFee FROM SaleLedger ');
  END IF;
  IF (v_saletype = 2) THEN
    v_ins := (((((('INSERT INTO ' || ltrim(rtrim(v_parentsrv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.IMP_AdvSaleLedger ');
    v_sql := (((' SELECT ServerName=' || '''') || v_srv) || ''', TransDate=GETDATE(), InvType = 2, * FROM AdvSaleLedger ');
  END IF;
  IF (v_saletype = 3) THEN
    v_ins := (((((('INSERT INTO ' || ltrim(rtrim(v_parentsrv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.IMP_SRLedger ');
    v_sql := (((' SELECT ServerName=' || '''') || v_srv) || ''', TransDate=GETDATE(), InvType = 3, SRInvCode,SaleInvCode,Date,SRCatCode,CustCode,SalesmanCode,DiscPerc,FlatDisc,MiscCharges,Posted,PostDate,Remarks,SalesTax,OriginalDate,ModifiedBy,PostedBy,HeaderNo,InvGSTPerc1,Smancode,CustRefno,CustRefno2,CustRefno3,CustRefno4,PatientCode,MachineName,HeaderInvNo,AdmissionCode,invtotal,AccountFor,PaymentMode,PaymentAccCode,Amt,AmtBY,AmtDate,AmtReference,OutstandingAmt,Marked,PageSize,ReprintingCounter,DoctCode,ConsiderInPO,CashAccCode,CashTendered,CashCharged,CashBack,RetViaBillSummary,CRS_Transfered,CRS_TransferedOn,GuestCode,GuestCheckInCode,StudentCode,Synced,SyncedOn,SyncedBy,CurrencyCode,ConversionRate,Fiscalized,FiscalizedOn,FiscalInvoiceNo,Transmit,Transmited,AdvanceTax,AdvanceTaxAmt,FBRPOSFee FROM SRLedger ');
  END IF;
  IF (v_custcode IS NULL) THEN
    v_whr := (((((((((((((((' WHERE Transmit = ' || chr(39)) || 'Y') || chr(39)) || ' AND Transmited = ') || chr(39)) || 'N') || chr(39)) || ' AND DATE BETWEEN ') || chr(39)) || v_stdate) || chr(39)) || ' AND ') || chr(39)) || v_edate) || chr(39));
  ELSE
    v_whr := (((((((((((((((((' WHERE CustCode = ' || (SELECT ltrim(rtrim(dbo.tsql_str((v_custcode)::numeric, 8))))) || ' AND Transmit = ') || chr(39)) || 'Y') || chr(39)) || ' AND Transmited = ') || chr(39)) || 'N') || chr(39)) || ' AND DATE BETWEEN ') || chr(39)) || v_stdate) || chr(39)) || ' AND ') || chr(39)) || v_edate) || chr(39));
  END IF;
  v_whr_cln := v_whr;
  v_query := ((v_ins || v_sql) || v_whr);
  _dq1 := v_query;
  IF _dq1 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq1);
  END IF;
  v_err := 0;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Transmit Sales Data Problem: Error Transfering Sales Data From Server (%) TO Server (%) ', v_srv, v_parentsrv;
    return_value := -1;
    RETURN;
  ELSE
    IF (v_saletype = 1) THEN
      v_ins := (((((('INSERT INTO ' || ltrim(rtrim(v_parentsrv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.IMP_SaleDetail ');
      v_sql := ((('SELECT ServerName=' || '''') || v_srv) || ''', SaleInvcode, ICode, GCode, Batch, Expiry, PackQty, LooseQty, PackUnits, SalePrice, AvgPrice, Rate, DiscPerc, SalesTax, RowID, Due, SatisfiedDate, itemflatdisc, SaleItemDescription, PackPrice, UnitSalesTax, GSTPerc, SaleUtn, bonusqty, claimable, balancestock, RowGroup, ClaimableDiscPerc, ManfDate, PackQtyForSale, BonusPackQtyForSale, SaleOrderRowID, DescICode, SourceSaleInvCode=SaleInvCode, SaleRowID=NULL, IssueRowID=NULL, PurUnitRate, RPPUnitRate, TotalPieces, PiecesInHand, PackSalePrice, RefusalSaleRowID=NULL, AlternatePurPrice, CommissionPerUnit, CommissionPerc, AlternateCustomICode, BatchCost, ISNULL(ItemAdvanceTaxPerc,0) FROM SaleDetail WHERE SaleInvCode IN (SELECT SaleInvCode FROM SaleLedger ');
    END IF;
    IF (v_saletype = 2) THEN
      v_ins := (((((('INSERT INTO ' || ltrim(rtrim(v_parentsrv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.IMP_AdvSaleDetail ');
      v_sql := ((('SELECT ServerName=' || '''') || v_srv) || ''', * FROM AdvSaleDetail WHERE AdvSaleInvCode IN (SELECT AdvSaleInvCode FROM AdvSaleLedger ');
    END IF;
    IF (v_saletype = 3) THEN
      v_ins := (((((('INSERT INTO ' || ltrim(rtrim(v_parentsrv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.IMP_SRDetail (ChildServer,SRInvcode,Icode,Gcode,Batch,Expiry,PackQty,LooseQty,PackUnits,SRPrice,DiscPerc,SalesTax,AvgPrice,UnitSalesTax,GSTPerc,SRUtn,BonusQty,SalePrice,SaleRowId,ReturnItemDescription,TotalPieces,PiecesInHand,AlternatePurPrice,CommissionPerUnit,CommissionPerc,AlternateCustomICode,NewAvgPrice,Claimable,ClaimableDiscPerc,ItemAdvanceTaxPerc) ');
      v_sql := ((('SELECT ServerName=' || '''') || v_srv) || ''',SRInvcode,Icode,Gcode,Batch,Expiry,PackQty,LooseQty,PackUnits,SRPrice,DiscPerc,SalesTax,AvgPrice,UnitSalesTax,GSTPerc,SRUtn,BonusQty,SalePrice,SaleRowId,ReturnItemDescription=LTRIM(RTRIM(STR(SRUTN))),TotalPieces,PiecesInHand,AlternatePurPrice,CommissionPerUnit,CommissionPerc,AlternateCustomICode,NewAvgPrice,Claimable,ClaimableDiscPerc,ISNULL(ItemAdvanceTaxPerc,0) FROM SRDetail WHERE SRInvCode IN (SELECT SRInvCode FROM SRLedger ');
    END IF;
    IF (v_custcode IS NULL) THEN
      v_whr := ((((((((((((((((' WHERE Transmit = ' || chr(39)) || 'Y') || chr(39)) || ' AND Transmited = ') || chr(39)) || 'N') || chr(39)) || ' AND DATE BETWEEN ') || chr(39)) || v_stdate) || chr(39)) || ' AND ') || chr(39)) || v_edate) || chr(39)) || ')');
    ELSE
      v_whr := ((((((((((((((((((' WHERE CustCode = ' || (SELECT ltrim(rtrim(dbo.tsql_str((v_custcode)::numeric, 8))))) || ' AND Transmit = ') || chr(39)) || 'Y') || chr(39)) || ' AND Transmited = ') || chr(39)) || 'N') || chr(39)) || ' AND DATE BETWEEN ') || chr(39)) || v_stdate) || chr(39)) || ' AND ') || chr(39)) || v_edate) || chr(39)) || ')');
    END IF;
    v_query := ((v_ins || v_sql) || v_whr);
    _dq2 := v_query;
    IF _dq2 IS NOT NULL THEN
      EXECUTE dbo.tsql_dyn(_dq2);
    END IF;
    v_err := 0;
    IF ((0 <> 0) OR (v_err <> 0)) THEN
      RAISE EXCEPTION 'Transmit Sales Data Detail Problem: Error Transfering Sales Data Detail From Server (%) TO Server (%) ', v_srv, v_parentsrv;
      return_value := -1;
      RETURN;
    ELSE
      IF (v_saletype = 1) THEN
        v_ins := (((((((((('INSERT INTO ' || ltrim(rtrim(v_parentsrv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.IMP_CashierWindow SELECT ChildServer=') || chr(39)) || v_srv) || chr(39)) || ', CW.* FROM CashierWindow CW WHERE CW.SaleInvCode IN (SELECT SaleInvCode FROM SaleLedger ');
      END IF;
      IF (v_saletype = 3) THEN
        v_ins := (((((((((((((('INSERT INTO ' || ltrim(rtrim(v_parentsrv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.IMP_MasterCashWin SELECT ChildServer=') || chr(39)) || v_srv) || chr(39)) || ', CW.* FROM MasterCashWin CW WHERE CW.DocumentType = ') || chr(39)) || 'SR') || chr(39)) || ' AND DocumentCode IN (SELECT SRInvCode FROM SRLedger ');
      END IF;
      v_query := (v_ins || v_whr);
      _dq3 := v_query;
      IF _dq3 IS NOT NULL THEN
        EXECUTE dbo.tsql_dyn(_dq3);
      END IF;
      v_err := 0;
      IF ((0 <> 0) OR (v_err <> 0)) THEN
        RAISE EXCEPTION 'Transmit Sales Data Problem: Error Updating Master Cashier Window Related Data (%)', v_saletype;
        return_value := -1;
        RETURN;
      END IF;
      IF (v_saletype = 1) THEN
        v_query := (((('UPDATE SaleLedger SET Transmited = ' || chr(39)) || 'Y') || chr(39)) || v_whr_cln);
      END IF;
      IF (v_saletype = 2) THEN
        v_query := (((('UPDATE AdvSaleLedger SET Transmited = ' || chr(39)) || 'Y') || chr(39)) || v_whr_cln);
      END IF;
      IF (v_saletype = 3) THEN
        v_query := (((('UPDATE SRLedger SET Transmited = ' || chr(39)) || 'Y') || chr(39)) || v_whr_cln);
      END IF;
      _dq4 := v_query;
      IF _dq4 IS NOT NULL THEN
        EXECUTE dbo.tsql_dyn(_dq4);
      END IF;
      v_err := 0;
      IF ((0 <> 0) OR (v_err <> 0)) THEN
        RAISE EXCEPTION 'Transmit Sales Data Problem: Error Updating Sales Regarding Transmit Status';
        return_value := -1;
        RETURN;
      END IF;
    END IF;
  END IF;
  v_dt := localtimestamp(3);
  SELECT r.return_value INTO v_rt_code FROM dbo.sp_set_datetime_preference(prefname => 'LastSaleTransmited', prefvalue => v_dt) AS r;
  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
    RAISE EXCEPTION 'Unable to Record Last Sale Transmit Information in Software Preferences';
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_Update_Customer_Info ====
CREATE OR REPLACE FUNCTION dbo.sp_update_customer_info(ai_custcode smallint, ai_areacode smallint, ai_subareacode smallint, ai_countycode smallint, as_address1 citext, as_address2 citext, as_block citext, ad_charges numeric, adt_openingdate timestamp, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_custcode smallint;
  v_ai_areacode smallint;
  v_ai_subareacode smallint;
  v_ai_countycode smallint;
  v_as_address1 citext;
  v_as_address2 citext;
  v_as_block citext;
  v_ad_charges numeric(12,2);
  v_adt_openingdate timestamp(3);
BEGIN
  v_ai_custcode := ai_custcode;
  v_ai_areacode := ai_areacode;
  v_ai_subareacode := ai_subareacode;
  v_ai_countycode := ai_countycode;
  v_as_address1 := as_address1;
  v_as_address2 := as_address2;
  v_as_block := as_block;
  v_ad_charges := ad_charges;
  v_adt_openingdate := adt_openingdate;
  UPDATE dbo.accounts SET openingdate = v_adt_openingdate WHERE (acccode = v_ai_custcode);
  UPDATE dbo.customer SET address1 = v_as_address1, address2 = v_as_address2, areacode = v_ai_areacode, subareacode = v_ai_subareacode, countycode = v_ai_countycode, block = v_as_block, charges = v_ad_charges WHERE (custcode = v_ai_custcode);
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_Update_Item_MinQty ====
CREATE OR REPLACE FUNCTION dbo.sp_update_item_minqty(icode integer, qty integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_icode integer;
  v_qty integer;
  v_err integer;
  v_rowcount integer;
  v_itemname citext;
  _rc integer;
BEGIN
  v_icode := icode;
  v_qty := qty;
  v_itemname := coalesce((SELECT name FROM dbo.item WHERE (icode = v_icode)), '');
  _rc := 1;
  UPDATE dbo.item SET minqty = coalesce(v_qty, 0) WHERE (item.icode = v_icode);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_rowcount := _rc;
  v_err := 0;
  _rc := 1;
  IF ((v_rowcount <> 1) AND (v_err <> 0)) THEN
    RAISE EXCEPTION 'Unable to update minimum qty. for item = % ', v_itemname;
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

