-- ==== proc SP_Update_ItemBatchSalePrice ====
CREATE OR REPLACE FUNCTION dbo.sp_update_itembatchsaleprice(icode integer, batch citext, expiry timestamp, saleprice numeric, usercode smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_icode integer;
  v_batch citext;
  v_expiry timestamp(3);
  v_saleprice numeric(15,2);
  v_usercode smallint;
  v_rowsaffected integer;
  v_err integer;
  _rc integer;
BEGIN
  v_icode := icode;
  v_batch := batch;
  v_expiry := expiry;
  v_saleprice := saleprice;
  v_usercode := usercode;
  UPDATE dbo.itembatchpricing SET saleprice = v_saleprice, usercode = v_usercode, lastmodified = localtimestamp(3), lastmodifiedby = v_usercode WHERE (((icode = v_icode) AND (batch = v_batch)) AND (expiry = v_expiry));
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_rowsaffected := _rc;
  v_err := 0;
  _rc := 1;
  IF ((v_rowsaffected = 0) AND (v_err = 0)) THEN
    INSERT INTO dbo.itembatchpricing (icode, batch, expiry, saleprice, arrivedon, usercode, lastmodified, lastmodifiedby) SELECT v_icode AS icode, v_batch AS batch, v_expiry AS expiry, v_saleprice AS saleprice, localtimestamp(3) AS arrivedon, v_usercode AS usercode, NULL::timestamp(3) AS lastmodified, NULL::smallint AS lastmodifiedby;
    GET DIAGNOSTICS _rc = ROW_COUNT;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_Update_ItemHistoricalCost_In_Sale_And_Return ====
CREATE OR REPLACE FUNCTION dbo.sp_update_itemhistoricalcost_in_sale_and_return(dbname citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_dbname citext;
  v_qry citext;
  v_err integer;
  v_rt_code integer;
  _dq1 text;
  _dq2 text;
BEGIN
  v_dbname := dbname;
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  v_qry := (((((('UPDATE ' || v_dbname) || '.DBO.SaleDetail SET AvgPrice = COALESCE((SELECT DBO.Fn_GetItemCostHistory(D.ICode, S.Date)), AvgPrice) FROM ') || v_dbname) || '.DBO.SaleLedger S, ') || v_dbname) || '.DBO.SaleDetail D WHERE S.SaleInvCode = D.SaleInvCode ');
  _dq1 := v_qry;
  IF _dq1 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq1);
  END IF;
  v_err := 0;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Updation of Historical Cost in Sales Data Failed.';
    return_value := -1;
    RETURN;
  END IF;
  v_qry := (((((('UPDATE ' || v_dbname) || '.DBO.SRDetail SET AvgPrice = COALESCE((SELECT DBO.Fn_GetItemCostHistory(D.ICode, S.Date)), AvgPrice) FROM ') || v_dbname) || '.DBO.SRLedger S, ') || v_dbname) || '.DBO.SRDetail D WHERE S.SRInvCode = D.SRInvCode ');
  _dq2 := v_qry;
  IF _dq2 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq2);
  END IF;
  v_err := 0;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Updation of Historical Cost in Sales Return Data Failed.';
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_Update_Supplier_Item_Info ====
CREATE OR REPLACE FUNCTION dbo.sp_update_supplier_item_info(suppcode smallint, icode integer, rate numeric, discperc numeric, saleqty integer, bonusqty integer, days integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_suppcode smallint;
  v_icode integer;
  v_rate numeric(15,2);
  v_discperc numeric(6,2);
  v_saleqty integer;
  v_bonusqty integer;
  v_days integer;
  v_rowcount integer;
  v_err integer;
BEGIN
  v_suppcode := suppcode;
  v_icode := icode;
  v_rate := rate;
  v_discperc := discperc;
  v_saleqty := saleqty;
  v_bonusqty := bonusqty;
  v_days := days;
  v_rowcount := coalesce((SELECT count(*) AS c FROM dbo.itemsuppliers WHERE ((suppcode = v_suppcode) AND (icode = v_icode))), 0);
  IF (v_rowcount = 0) THEN
    INSERT INTO dbo.itemsuppliers (icode, suppcode, priority, rate, discperc, saleqty, bonusqty, days) SELECT v_icode, v_suppcode, (coalesce((SELECT max(priority) FROM dbo.itemsuppliers WHERE (icode = v_icode)), 0) + 1) AS priority, v_rate, v_discperc, v_saleqty, v_bonusqty, v_days;
  ELSE
    UPDATE dbo.itemsuppliers SET icode = v_icode, suppcode = v_suppcode, rate = v_rate, discperc = v_discperc, saleqty = v_saleqty, bonusqty = v_bonusqty, days = v_days WHERE ((suppcode = v_suppcode) AND (icode = v_icode));
  END IF;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (
    suppcode smallint,
    icode integer,
    rate numeric(15,2),
    rowid integer GENERATED BY DEFAULT AS IDENTITY
) ON COMMIT DROP;
  INSERT INTO tmp_temp (suppcode, icode) SELECT suppcode, icode FROM dbo.itemsuppliers WHERE (icode = v_icode) ORDER BY rate;
  UPDATE dbo.itemsuppliers SET priority = (SELECT t.rowid FROM tmp_temp AS t WHERE ((t.icode = itemsuppliers.icode) AND (t.suppcode = itemsuppliers.suppcode))) WHERE (icode = v_icode);
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_UPDATE_TOTAL_CrossTab_ReportData ====
CREATE OR REPLACE FUNCTION dbo.sp_update_total_crosstab_reportdata(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
BEGIN
  UPDATE dbo.crosstab_reportdata SET totqty = t.totqty, totval = t.totval FROM dbo.crosstab_reportdata AS c, (SELECT code1, sum(((((((((((((coalesce(qty1, 0) + coalesce(qty2, 0)) + coalesce(qty3, 0)) + coalesce(qty4, 0)) + coalesce(qty5, 0)) + coalesce(qty6, 0)) + coalesce(qty7, 0)) + coalesce(qty8, 0)) + coalesce(qty9, 0)) + coalesce(qty10, 0)) + coalesce(qty11, 0)) + coalesce(qty12, 0)) + coalesce(qty13, 0))) AS totqty, sum(((((((((((((coalesce(val1, 0) + coalesce(val2, 0)) + coalesce(val3, 0)) + coalesce(val4, 0)) + coalesce(val5, 0)) + coalesce(val6, 0)) + coalesce(val7, 0)) + coalesce(val8, 0)) + coalesce(val9, 0)) + coalesce(val10, 0)) + coalesce(val11, 0)) + coalesce(val12, 0)) + coalesce(val13, 0))) AS totval FROM dbo.crosstab_reportdata GROUP BY code1) AS t WHERE (c.code1 = t.code1);
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_UPDATE_TOTAL_CrossTab_ReportData2 ====
CREATE OR REPLACE FUNCTION dbo.sp_update_total_crosstab_reportdata2(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
BEGIN
  UPDATE dbo.crosstab_reportdata SET totqty = t.totqty, totval = t.totval FROM dbo.crosstab_reportdata AS c, (SELECT code1, sum((((((((((((((((((((((((((coalesce(qty1, 0) + coalesce(qty2, 0)) + coalesce(qty3, 0)) + coalesce(qty4, 0)) + coalesce(qty5, 0)) + coalesce(qty6, 0)) + coalesce(qty7, 0)) + coalesce(qty8, 0)) + coalesce(qty9, 0)) + coalesce(qty10, 0)) + coalesce(qty11, 0)) + coalesce(qty12, 0)) + coalesce(qty13, 0)) + coalesce(value1, 0)) + coalesce(value2, 0)) + coalesce(value3, 0)) + coalesce(value4, 0)) + coalesce(value5, 0)) + coalesce(value6, 0)) + coalesce(value7, 0)) + coalesce(value8, 0)) + coalesce(value9, 0)) + coalesce(value10, 0)) + coalesce(value11, 0)) + coalesce(value12, 0)) + coalesce(value13, 0))) AS totqty, sum(((((((((((((coalesce(val1, 0) + coalesce(val2, 0)) + coalesce(val3, 0)) + coalesce(val4, 0)) + coalesce(val5, 0)) + coalesce(val6, 0)) + coalesce(val7, 0)) + coalesce(val8, 0)) + coalesce(val9, 0)) + coalesce(val10, 0)) + coalesce(val11, 0)) + coalesce(val12, 0)) + coalesce(val13, 0))) AS totval FROM dbo.crosstab_reportdata GROUP BY code1) AS t WHERE (c.code1 = t.code1);
  return_value := 0;
