-- ==== proc SP_UpdateActivityMonitor ====
CREATE OR REPLACE FUNCTION dbo.sp_updateactivitymonitor(documenttype citext, documentcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_documenttype citext;
  v_documentcode integer;
  v_rowsaffected integer;
  v_err integer;
  _rc integer;
BEGIN
  v_documenttype := documenttype;
  v_documentcode := documentcode;
  IF ((v_documenttype IS NULL) OR (v_documentcode IS NULL)) THEN
    RAISE EXCEPTION 'Error Calling Activity Monitor';
    return_value := -1;
    RETURN;
  END IF;
  IF (v_documenttype <> 'SV') THEN
    DELETE FROM dbo.activitymonitor WHERE ((documenttype = v_documenttype) AND (documentcode = v_documentcode));
    GET DIAGNOSTICS _rc = ROW_COUNT;
  END IF;
  IF (v_documenttype = 'SV') THEN
    DELETE FROM dbo.activitymonitor WHERE ((documentcode = v_documentcode) AND (documenttype IN ('ST', 'SC')));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    INSERT INTO dbo.activitymonitor (documentcode, documenttype, doccatcode, category, date, partytype, partycode, usercode, amount, remarks, printed, machinename, headerno, headerinvno) SELECT v_documentcode AS documentcode, CASE WHEN (salecatcode <= 2) THEN 'ST' ELSE 'SC' END AS documenttype, salecatcode AS doccatcode, CASE WHEN (salecatcode <= 2) THEN 'Credit Sale' ELSE 'Cash Sale' END AS category, date AS date, 'C' AS partytype, custcode AS partycode, salesmancode AS usercode, coalesce(invtotal, 0) AS amount, remarks AS remarks, 'N' AS printed, machinename, headerno, coalesce(headerinvno, v_documentcode) FROM dbo.saleledger WHERE ((saleinvcode = v_documentcode) AND (saleinvcode NOT IN (SELECT DISTINCT documentcode FROM dbo.activitymonitor WHERE ((documenttype = (CASE WHEN (salecatcode <= 2) THEN 'ST' ELSE 'SC' END)::citext) AND (documentcode = v_documentcode)))));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_rowsaffected := _rc;
    v_err := 0;
    _rc := 1;
    IF ((v_rowsaffected = 0) AND (v_err = 0)) THEN
      RAISE EXCEPTION 'Unable to Update Activity Monitor for Sale Invoice No. = (%)', v_documentcode;
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  IF (v_documenttype = 'SR') THEN
    INSERT INTO dbo.activitymonitor (documentcode, documenttype, doccatcode, category, date, partytype, partycode, usercode, amount, remarks, printed, machinename, headerno, headerinvno) SELECT v_documentcode AS documentcode, v_documenttype AS documenttype, srcatcode AS doccatcode, CASE WHEN (srcatcode <= 7) THEN 'Credit S/Return' ELSE 'Cash S/Return' END AS category, date AS date, 'C' AS partytype, custcode AS partycode, salesmancode AS usercode, invtotal AS amount, remarks AS remarks, 'N' AS printed, machinename, headerno, coalesce(headerinvno, v_documentcode) FROM dbo.srledger WHERE ((srinvcode = v_documentcode) AND (srinvcode NOT IN (SELECT DISTINCT documentcode FROM dbo.activitymonitor WHERE ((documenttype = v_documenttype) AND (documentcode = v_documentcode)))));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_rowsaffected := _rc;
    v_err := 0;
    _rc := 1;
    IF ((v_rowsaffected = 0) AND (v_err = 0)) THEN
      RAISE EXCEPTION 'Unable to Update Activity Monitor for Sale Return No. = (%)', v_documentcode;
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  IF (v_documenttype = 'PV') THEN
    INSERT INTO dbo.activitymonitor (documentcode, documenttype, doccatcode, category, date, partytype, partycode, usercode, amount, remarks, printed, machinename, headerno, headerinvno) SELECT v_documentcode AS documentcode, v_documenttype AS documenttype, purcatcode AS doccatcode, CASE WHEN (purcatcode <= 2) THEN 'Pack Purchase' WHEN (purcatcode = 3) THEN 'Open Purchase' ELSE 'Loose Purchase' END AS category, date AS date, 'S' AS partytype, suppcode AS partycode, salesmancode AS usercode, invtotal AS amount, remarks AS remarks, 'N' AS printed, NULL::citext AS machinename, headerno, coalesce(headerinvno, v_documentcode) FROM dbo.purledger WHERE ((purinvcode = v_documentcode) AND (purinvcode NOT IN (SELECT DISTINCT documentcode FROM dbo.activitymonitor WHERE ((documenttype = v_documenttype) AND (documentcode = v_documentcode)))));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_rowsaffected := _rc;
    v_err := 0;
    _rc := 1;
    IF ((v_rowsaffected = 0) AND (v_err = 0)) THEN
      RAISE EXCEPTION 'Unable to Update Activity Monitor for Purchase Invoice No. = (%)', v_documentcode;
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  IF (v_documenttype = 'PR') THEN
    INSERT INTO dbo.activitymonitor (documentcode, documenttype, doccatcode, category, date, partytype, partycode, usercode, amount, remarks, printed, machinename, headerno, headerinvno) SELECT v_documentcode AS documentcode, v_documenttype AS documenttype, prcatcode AS doccatcode, 'Purchase Return' AS category, date AS date, 'S' AS partytype, suppcode AS partycode, salesmancode AS usercode, invtotal AS amount, remarks AS remarks, 'N' AS printed, NULL::citext AS machinename, headerno, coalesce(headerinvno, v_documentcode) FROM dbo.prledger WHERE ((prinvcode = v_documentcode) AND (prinvcode NOT IN (SELECT DISTINCT documentcode FROM dbo.activitymonitor WHERE ((documenttype = v_documenttype) AND (documentcode = v_documentcode)))));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_rowsaffected := _rc;
    v_err := 0;
    _rc := 1;
    IF ((v_rowsaffected = 0) AND (v_err = 0)) THEN
      RAISE EXCEPTION 'Unable to Update Activity Monitor for Purchase Return Invoice No. = (%)', v_documentcode;
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  IF (v_documenttype = 'SO') THEN
    INSERT INTO dbo.activitymonitor (documentcode, documenttype, doccatcode, category, date, partytype, partycode, usercode, amount, remarks, printed, machinename, headerno, headerinvno) SELECT v_documentcode AS documentcode, v_documenttype AS documenttype, 1 AS doccatcode, 'Sale Order' AS category, date AS date, 'C' AS partytype, custcode AS partycode, usercode AS usercode, invtotal AS amount, remarks AS remarks, 'N' AS printed, machinename, headerno, coalesce(headerinvno, v_documentcode) FROM dbo.saleorderheader WHERE ((saleordercode = v_documentcode) AND (saleordercode NOT IN (SELECT DISTINCT documentcode FROM dbo.activitymonitor WHERE ((documenttype = v_documenttype) AND (documentcode = v_documentcode)))));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_rowsaffected := _rc;
    v_err := 0;
    _rc := 1;
    IF ((v_rowsaffected = 0) AND (v_err = 0)) THEN
      RAISE EXCEPTION 'Unable to Update Activity Monitor for Sale Order No. = (%)', v_documentcode;
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  IF (v_documenttype = 'IV') THEN
    INSERT INTO dbo.activitymonitor (documentcode, documenttype, doccatcode, category, date, partytype, partycode, usercode, amount, remarks, printed, machinename, headerno, headerinvno) SELECT v_documentcode AS documentcode, v_documenttype AS documenttype, coalesce(issuetypecode, 1) AS doccatcode, coalesce((SELECT issuetype.name FROM dbo.issuetype WHERE (issuetype.issuetypecode = issueheader.issuetypecode)), 'Issue') AS category, date AS date, CASE recipientcode WHEN 1 THEN 'D' WHEN 2 THEN 'C' WHEN 3 THEN 'S' WHEN 4 THEN 'P' ELSE 'A' END AS partytype, CASE recipientcode WHEN 1 THEN deptcode WHEN 2 THEN acccode WHEN 3 THEN acccode WHEN 4 THEN recipientsalesman ELSE acccode END AS partycode, salesmancode AS usercode, round(((SELECT sum((d.qty * d.price)) FROM dbo.issuedetail AS d WHERE (d.issueinvcode = issueheader.issueinvcode)))::numeric, 0) AS amount, remarks AS remarks, 'N' AS printed, NULL::citext AS machinename, headerno, coalesce(headerinvno, v_documentcode) FROM dbo.issueheader WHERE ((issueinvcode = v_documentcode) AND (issueinvcode NOT IN (SELECT DISTINCT documentcode FROM dbo.activitymonitor WHERE ((documenttype = v_documenttype) AND (documentcode = v_documentcode)))));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_rowsaffected := _rc;
    v_err := 0;
    _rc := 1;
    IF ((v_rowsaffected = 0) AND (v_err = 0)) THEN
      RAISE EXCEPTION 'Unable to Update Activity Monitor for Issue Invoice No. = (%)', v_documentcode;
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  IF (v_documenttype = 'RC') THEN
    INSERT INTO dbo.activitymonitor (documentcode, documenttype, doccatcode, category, date, partytype, partycode, usercode, amount, remarks, printed, machinename, headerno, headerinvno) SELECT v_documentcode AS documentcode, v_documenttype AS documenttype, 1 AS doccatcode, 'Receipt' AS category, date AS date, CASE recipientcode WHEN 1 THEN 'D' WHEN 2 THEN 'C' WHEN 3 THEN 'S' WHEN 4 THEN 'P' ELSE 'A' END AS partytype, CASE recipientcode WHEN 1 THEN deptcode WHEN 2 THEN acccode WHEN 3 THEN acccode WHEN 4 THEN recipientsalesman ELSE acccode END AS partycode, salesmancode AS usercode, round(((SELECT sum((d.qty * d.price)) FROM dbo.receiptdetail AS d WHERE (d.receiptinvcode = receiptheader.receiptinvcode)))::numeric, 0) AS amount, remarks AS remarks, 'N' AS printed, NULL::citext AS machinename, headerno, coalesce(headerinvno, v_documentcode) FROM dbo.receiptheader WHERE ((receiptinvcode = v_documentcode) AND (receiptinvcode NOT IN (SELECT DISTINCT documentcode FROM dbo.activitymonitor WHERE ((documenttype = v_documenttype) AND (documentcode = v_documentcode)))));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_rowsaffected := _rc;
    v_err := 0;
    _rc := 1;
    IF ((v_rowsaffected = 0) AND (v_err = 0)) THEN
      RAISE EXCEPTION 'Unable to Update Activity Monitor for Receipt Invoice No. = (%)', v_documentcode;
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  IF (v_documenttype = 'AI') THEN
    INSERT INTO dbo.activitymonitor (documentcode, documenttype, doccatcode, category, date, partytype, partycode, usercode, amount, remarks, printed, machinename, headerno, headerinvno) SELECT v_documentcode AS documentcode, v_documenttype AS documenttype, adjcatcode AS doccatcode, 'Adj. Increase' AS category, date AS date, 'O' AS partytype, adjcatcode AS partycode, usercode AS usercode, round(((SELECT sum((d.looseqty * d.price)) FROM dbo.adjdetail AS d WHERE (d.adjcode = adjheader.adjcode)))::numeric, 0) AS amount, remarks AS remarks, 'N' AS printed, NULL::citext AS machinename, headerno, coalesce(headerinvno, v_documentcode) FROM dbo.adjheader WHERE (((adjcode = v_documentcode) AND (adjcatcode = 1)) AND (adjcode NOT IN (SELECT DISTINCT documentcode FROM dbo.activitymonitor WHERE ((documenttype = v_documenttype) AND (documentcode = v_documentcode)))));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_rowsaffected := _rc;
    v_err := 0;
    _rc := 1;
    IF ((v_rowsaffected = 0) AND (v_err = 0)) THEN
      RAISE EXCEPTION 'Unable to Update Activity Monitor for Stock Adjustment Increase No. = (%)', v_documentcode;
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  IF (v_documenttype = 'AD') THEN
    INSERT INTO dbo.activitymonitor (documentcode, documenttype, doccatcode, category, date, partytype, partycode, usercode, amount, remarks, printed, machinename, headerno, headerinvno) SELECT v_documentcode AS documentcode, v_documenttype AS documenttype, adjcatcode AS doccatcode, 'Adj. Decrease' AS category, date AS date, 'O' AS partytype, adjcatcode AS partycode, usercode AS usercode, round(((SELECT sum((d.looseqty * d.price)) FROM dbo.adjdetail AS d WHERE (d.adjcode = adjheader.adjcode)))::numeric, 0) AS amount, remarks AS remarks, 'N' AS printed, NULL::citext AS machinename, headerno, coalesce(headerinvno, v_documentcode) FROM dbo.adjheader WHERE (((adjcode = v_documentcode) AND (adjcatcode = 2)) AND (adjcode NOT IN (SELECT DISTINCT documentcode FROM dbo.activitymonitor WHERE ((documenttype = v_documenttype) AND (documentcode = v_documentcode)))));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_rowsaffected := _rc;
    v_err := 0;
    _rc := 1;
    IF ((v_rowsaffected = 0) AND (v_err = 0)) THEN
      RAISE EXCEPTION 'Unable to Update Activity Monitor for Stock Adjustment Decrease No. = (%)', v_documentcode;
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  IF (v_documenttype = 'QU') THEN
    INSERT INTO dbo.activitymonitor (documentcode, documenttype, doccatcode, category, date, partytype, partycode, usercode, amount, remarks, printed, machinename, headerno, headerinvno) SELECT v_documentcode AS documentcode, v_documenttype AS documenttype, 1 AS doccatcode, 'Quotation' AS category, date AS date, 'C' AS partytype, custcode AS partycode, salesmancode AS usercode, round(((SELECT sum((d.qty * d.saleprice)) FROM dbo.quotationdetail AS d WHERE (d.quotationcode = quotationheader.quotationcode)))::numeric, 0) AS amount, remarks AS remarks, 'N' AS printed, NULL::citext AS machinename, headerno, v_documentcode AS headerinvno FROM dbo.quotationheader WHERE ((quotationcode = v_documentcode) AND (quotationcode NOT IN (SELECT DISTINCT documentcode FROM dbo.activitymonitor WHERE ((documenttype = v_documenttype) AND (documentcode = v_documentcode)))));
