  IF (v_documenttype = 'VO') THEN
    INSERT INTO dbo.activitymonitor (documentcode, documenttype, doccatcode, category, date, partytype, partycode, usercode, amount, remarks, printed, machinename, headerno, headerinvno) SELECT v_documentcode AS documentcode, v_documenttype AS documenttype, 1 AS doccatcode, CASE WHEN (admissioncode IS NULL) THEN 'Service Order' ELSE 'In-Patient Service Order' END AS category, date AS date, 'C' AS partytype, custcode AS partycode, salesmancode AS usercode, coalesce((SELECT (((sum(((d.qty * (coalesce((d.price - d.serviceflatdisc), 0))) * ((1 - ((0.01 * coalesce(d.discperc, 0))))))) * ((1 - ((0.01 * coalesce(serviceoheader.discperc, 0)))))) + coalesce(serviceoheader.misccharges, 0)) - coalesce(serviceoheader.flatdisc, 0)) FROM dbo.serviceodetail AS d WHERE (d.serviceocode = v_documentcode)), 0) AS amount, remarks AS remarks, 'N' AS printed, NULL::citext AS machinename, headerno, v_documentcode FROM dbo.serviceoheader WHERE ((serviceocode = v_documentcode) AND (serviceocode NOT IN (SELECT DISTINCT documentcode FROM dbo.activitymonitor WHERE ((documenttype = v_documenttype) AND (documentcode = v_documentcode)))));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_rowsaffected := _rc;
