    END IF;
  END IF;
  IF (v_documenttype = 'SP') THEN
    INSERT INTO dbo.activitymonitor (documentcode, documenttype, doccatcode, category, date, partytype, partycode, usercode, amount, remarks, printed, machinename, headerno, headerinvno) SELECT v_documentcode AS documentcode, v_documenttype AS documenttype, 1 AS doccatcode, 'Purchase Of Service' AS category, date AS date, 'S' AS partytype, suppcode AS partycode, usercode AS usercode, round((coalesce((SELECT (((sum(((d.qty * (coalesce((d.price - d.serviceflatdisc), 0))) * ((1 - ((0.01 * coalesce(d.discperc, 0))))))) * ((1 - ((0.01 * coalesce(servicepurheader.discperc, 0)))))) + coalesce(servicepurheader.misccharges, 0)) - coalesce(servicepurheader.flatdisc, 0)) FROM dbo.servicepurdetail AS d WHERE (d.servicepurinvcode = v_documentcode)), 0))::numeric, 0) AS amount, remarks AS remarks, 'N' AS printed, NULL::citext AS machinename, headerno, v_documentcode FROM dbo.servicepurheader WHERE ((servicepurinvcode = v_documentcode) AND (servicepurinvcode NOT IN (SELECT DISTINCT documentcode FROM dbo.activitymonitor WHERE ((documenttype = v_documenttype) AND (documentcode = v_documentcode)))));
    GET DIAGNOSTICS _rc = ROW_COUNT;
