    IF ((v_rowsaffected = 0) AND (v_err = 0)) THEN
      RAISE EXCEPTION 'Unable to Update Activity Monitor for Purchase Of Service No. = (%)', v_documentcode;
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  IF (v_documenttype = 'RP') THEN
    INSERT INTO dbo.activitymonitor (documentcode, documenttype, doccatcode, category, date, partytype, partycode, usercode, amount, remarks, printed, machinename, headerno, headerinvno) SELECT v_documentcode AS documentcode, v_documenttype AS documenttype, 1 AS doccatcode, 'P/R Of Service' AS category, date AS date, 'S' AS partytype, suppcode AS partycode, usercode AS usercode, round((coalesce((SELECT (((sum(((d.qty * (coalesce((d.price - d.serviceflatdisc), 0))) * ((1 - ((0.01 * coalesce(d.discperc, 0))))))) * ((1 - ((0.01 * coalesce(serviceprheader.discperc, 0)))))) + coalesce(serviceprheader.misccharges, 0)) - coalesce(serviceprheader.flatdisc, 0)) FROM dbo.serviceprdetail AS d WHERE (d.serviceprinvcode = v_documentcode)), 0))::numeric, 0) AS amount, remarks AS remarks, 'N' AS printed, NULL::citext AS machinename, headerno, v_documentcode FROM dbo.serviceprheader WHERE ((serviceprinvcode = v_documentcode) AND (serviceprinvcode NOT IN (SELECT DISTINCT documentcode FROM dbo.activitymonitor WHERE ((documenttype = v_documenttype) AND (documentcode = v_documentcode)))));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_rowsaffected := _rc;
    v_err := 0;
    _rc := 1;
    IF ((v_rowsaffected = 0) AND (v_err = 0)) THEN
      RAISE EXCEPTION 'Unable to Update Activity Monitor for P/R Of Service No. = (%)', v_documentcode;
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  IF (v_documenttype = 'PD') THEN
    INSERT INTO dbo.activitymonitor (documentcode, documenttype, doccatcode, category, date, partytype, partycode, usercode, amount, remarks, printed, machinename, headerno, headerinvno) SELECT v_documentcode AS documentcode, v_documenttype AS documenttype, 1 AS doccatcode, 'Production' AS category, date AS date, 'G' AS partytype, receiptgcode AS partycode, CASE WHEN (modifiedby IS NULL) THEN createdby ELSE modifiedby END AS usercode, round((coalesce((SELECT coalesce(sum((d.qty * i.saleprice)), 0) FROM dbo.proddetail AS d, dbo.item AS i WHERE ((d.prodcode = v_documentcode) AND (d.icode = i.icode))), 0))::numeric, 0) AS amount, remarks AS remarks, 'N' AS printed, NULL::citext AS machinename, 1 AS headerno, v_documentcode FROM dbo.prodheader WHERE ((prodcode = v_documentcode) AND (prodcode NOT IN (SELECT DISTINCT documentcode FROM dbo.activitymonitor WHERE ((documenttype = v_documenttype) AND (documentcode = v_documentcode)))));
