      return_value := -1;
      RETURN;
    END IF;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_UpdateBasicData ====
CREATE OR REPLACE FUNCTION dbo.sp_updatebasicdata(srv citext, db citext, owner citext, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_upd citext;
  v_sql citext;
  v_qry citext;
  v_setpart citext;
  v_colname citext;
  v_endd citext;
  v_tablename citext;
  v_pkcond citext;
  v_full_table_name citext;
  v_priority smallint;
  v_keyseq smallint;
  v_position smallint;
  v_table_id integer;
  v_err integer;
  v_rt_code integer;
  cur_upd1 refcursor;
  cur_upd2 refcursor;
  cur_upd3 refcursor;
  _dq1 text;
  _fs integer := -1;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  v_upd := 'UPDATE ';
  v_setpart := 'SET ';
  v_sql := ((((((' FROM ' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.');
  v_endd := ' AS T WHERE ';
  OPEN cur_upd1 FOR SELECT ltrim(rtrim(tablename)) AS tablename, priority FROM dbo.transferabledata WHERE ((enable = 'Y') AND (autoupdate = 'Y')) ORDER BY priority;
  FETCH NEXT FROM cur_upd1 INTO v_tablename, v_priority;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    v_pkcond := '';
    v_setpart := 'SET ';
    v_full_table_name := ((ltrim(rtrim(v_owner)) || '.') || v_tablename);
    -- SET @table_id = OBJECT_ID(@full_table_name)
    RAISE EXCEPTION 'untranslated T-SQL (OBJECT_ID of non-literal)' USING ERRCODE = '0A000';
    v_err := 0;
    IF (((0 <> 0) OR (v_err <> 0)) OR (v_table_id IS NULL)) THEN
      RAISE EXCEPTION 'Data Updation: Invalid Object Refered: Name = %', v_full_table_name;
      CLOSE cur_upd1;
      -- DEALLOCATE Upd1
      return_value := -1;
      RETURN;
    END IF;
    -- OPEN Upd2
    RAISE EXCEPTION 'untranslated T-SQL (system table sysindexes)' USING ERRCODE = '0A000';
    FETCH NEXT FROM cur_upd2 INTO v_colname, v_keyseq;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    WHILE (_fs = 0) LOOP
      IF (v_keyseq <> 1) THEN
        v_pkcond := (v_pkcond || ' AND ');
      END IF;
      v_pkcond := ((((((v_pkcond || ' T.') || ltrim(rtrim(v_colname))) || ' = ') || v_tablename) || '.') || ltrim(rtrim(v_colname)));
      FETCH NEXT FROM cur_upd2 INTO v_colname, v_keyseq;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    END LOOP;
    CLOSE cur_upd2;
    -- DEALLOCATE Upd2
    -- OPEN Upd3
    RAISE EXCEPTION 'untranslated T-SQL (system table sysobjects)' USING ERRCODE = '0A000';
    FETCH NEXT FROM cur_upd3 INTO v_colname, v_position;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    WHILE (_fs = 0) LOOP
      -- IF ColumnProperty (@table_id, @ColName, 'IsIdentity') <> 1
      -- 		BEGIN
      -- 			IF @ColName = (SELECT columnname FROM TransferableData_RestrictedColumns WHERE columnname = @ColName and tablename = @TableName)
      -- 			BEGIN
      -- 				SET @ColName = @ColName
      -- 			END
      -- 			ELSE
      -- 			BEGIN
      -- 				IF @SETPART <> 'SET '
      -- 				BEGIN
      -- 					SET @SETPART = @SETPART + ','
      -- 				END
      -- --				SET @SETPART = @SETPART + @TableName + '.' + LTRIM(RTRIM(@ColName)) + '=' + 'T.' +  LTRIM(RTRIM(@ColName))
      -- 				IF LOWER(@TableName) = 'item'
      -- 				BEGIN
      -- 					IF lower(@ColName) = 'changereason' OR lower(@ColName) = 'module'
      -- 						SET @SETPART = @SETPART + LTRIM(RTRIM(@ColName)) + '=' + '''Data Transfer'''
      -- 					ELSE
      -- 						SET @SETPART = @SETPART + LTRIM(RTRIM(@ColName)) + '=' + 'T.' +  LTRIM(RTRIM(@ColName))
      -- 				END
      -- 				ELSE
      -- 					SET @SETPART = @SETPART + LTRIM(RTRIM(@ColName)) + '=' + 'T.' +  LTRIM(RTRIM(@ColName))
      -- 			END
      -- 		END
      RAISE EXCEPTION 'untranslated T-SQL (function ColumnProperty)' USING ERRCODE = '0A000';
      FETCH NEXT FROM cur_upd3 INTO v_colname, v_position;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    END LOOP;
    CLOSE cur_upd3;
    -- DEALLOCATE Upd3
    IF (v_setpart <> 'SET ') THEN
      IF ((lower(v_tablename))::citext = 'item') THEN
        v_qry := ((('SELECT * INTO tmp_tempitem ' || v_sql) || lower(v_tablename)) || '         ');
        v_qry := ((((((((v_qry || v_upd) || v_tablename) || ' ') || v_setpart) || ' FROM tmp_tempitem ') || v_endd) || ' ') || v_pkcond);
      ELSE
        v_qry := (((((((((v_upd || v_tablename) || ' ') || v_setpart) || ' ') || v_sql) || v_tablename) || v_endd) || ' ') || v_pkcond);
      END IF;
      _dq1 := v_qry;
      IF _dq1 IS NOT NULL THEN
        rs1 := NULL;
        IF _dq1 ~* '^[[:space:]]*select' THEN OPEN rs1 FOR EXECUTE dbo.tsql_dyn(_dq1); ELSE EXECUTE dbo.tsql_dyn(_dq1); END IF;
      END IF;
      v_err := 0;
      IF ((0 <> 0) OR (v_err <> 0)) THEN
        RAISE EXCEPTION 'Data Updation: Error Transfering % Data', v_full_table_name;
        CLOSE cur_upd1;
        -- DEALLOCATE Upd1
        return_value := -1;
        RETURN;
      END IF;
    END IF;
    IF ((lower(v_tablename))::citext = 'item') THEN
      SELECT r.return_value INTO v_err FROM dbo.sp_updateitems_categorywise(srv => v_srv, db => v_db, owner => v_owner) AS r;
      IF ((0 <> 0) OR (v_err <> 0)) THEN
        RAISE EXCEPTION 'Data Updation: Item Category Wise Updation Error';
        CLOSE cur_upd1;
        -- DEALLOCATE Upd1
        return_value := -1;
        RETURN;
      END IF;
    END IF;
    FETCH NEXT FROM cur_upd1 INTO v_tablename, v_priority;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_upd1;
  -- DEALLOCATE Upd1
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_UpdateCashierActivity ====
CREATE OR REPLACE FUNCTION dbo.sp_updatecashieractivity(moduleid smallint, doccode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_moduleid smallint;
  v_doccode integer;
  v_rowsaffected integer;
  v_err integer;
  v_autofillcashcharged citext;
  _rc integer;
BEGIN
  v_moduleid := moduleid;
  v_doccode := doccode;
  v_autofillcashcharged := dbo.fn_getpreference('AutoFillCashCharged');
  _rc := 1;
  IF ((v_moduleid IS NULL) OR (v_doccode IS NULL)) THEN
    RAISE EXCEPTION 'Error Calling Cashier Activity Monitor';
    return_value := -1;
    RETURN;
  END IF;
  IF (v_moduleid = 1) THEN
    DELETE FROM dbo.cashieractivity WHERE ((moduleid IN (10, 11)) AND (doccode = v_doccode));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    INSERT INTO dbo.cashieractivity (date, moduleid, doccode, catcode, category, acccode, usercode, machinename, headerno, headerinvno, amount, cashacccode, cashtendered, cashcharged, cashback, remarks, cashierjobcode, printed, supervised, supervisedon, glvochcode) SELECT date AS date, CASE WHEN (salecatcode <= 2) THEN 11 ELSE 10 END AS moduleid, v_doccode AS doccode, CASE WHEN (salecatcode <= 2) THEN 2 ELSE 1 END AS catcode, CASE WHEN (salecatcode <= 2) THEN 'Credit Sale' ELSE 'Cash Sale' END AS category, custcode AS acccode, salesmancode AS usercode, machinename, headerno, coalesce(headerinvno, v_doccode), coalesce(invtotal, 0) AS amount, cashacccode AS cashacccode, cashtendered AS cashtendered, CASE WHEN (salecatcode <= 2) THEN cashcharged ELSE CASE WHEN (cashcharged > 0) THEN cashcharged ELSE CASE WHEN (v_autofillcashcharged = 'N') THEN cashcharged ELSE coalesce(invtotal, 0) END END END AS cashcharged, CASE WHEN (salecatcode <= 2) THEN cashback ELSE CASE WHEN (cashcharged > 0) THEN cashback ELSE CASE WHEN (v_autofillcashcharged = 'N') THEN cashback ELSE 0.00 END END END AS cashback, remarks AS remarks, NULL::integer AS cashierjobcode, 'N' AS printed, 'N' AS supervised, NULL::timestamp(3) AS supervisedon, NULL::integer AS glvochcode FROM dbo.saleledger WHERE ((saleinvcode = v_doccode) AND (saleinvcode NOT IN (SELECT DISTINCT doccode FROM dbo.cashieractivity WHERE ((moduleid IN (10, 11)) AND (doccode = v_doccode)))));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_rowsaffected := _rc;
    v_err := 0;
    _rc := 1;
    IF ((v_rowsaffected = 0) AND (v_err = 0)) THEN
      RAISE EXCEPTION 'Unable to Update Cashier Activity for Sale Invoice No. = (%)', v_doccode;
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  IF (v_moduleid = 2) THEN
    DELETE FROM dbo.cashieractivity WHERE ((moduleid IN (31, 32)) AND (doccode = v_doccode));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    INSERT INTO dbo.cashieractivity (date, moduleid, doccode, catcode, category, acccode, usercode, machinename, headerno, headerinvno, amount, cashacccode, cashtendered, cashcharged, cashback, remarks, cashierjobcode, printed, supervised, supervisedon, glvochcode) SELECT date AS date, CASE WHEN (srcatcode <= 7) THEN 32 ELSE 31 END AS moduleid, v_doccode AS doccode, CASE WHEN (srcatcode <= 7) THEN 2 ELSE 1 END AS catcode, CASE WHEN (srcatcode <= 7) THEN 'Credit S/Return' ELSE 'Cash S/Return' END AS category, custcode AS acccode, salesmancode AS usercode, machinename, headerno, coalesce(headerinvno, v_doccode), coalesce(invtotal, 0) AS amount, cashacccode AS cashacccode, cashtendered AS cashtendered, cashcharged AS cashcharged, cashback AS cashback, remarks AS remarks, NULL::integer AS cashierjobcode, 'N' AS printed, 'N' AS supervised, NULL::timestamp(3) AS supervisedon, NULL::integer AS glvochcode FROM dbo.srledger WHERE ((srinvcode = v_doccode) AND (srinvcode NOT IN (SELECT DISTINCT doccode FROM dbo.cashieractivity WHERE ((moduleid IN (31, 32)) AND (doccode = v_doccode)))));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_rowsaffected := _rc;
    v_err := 0;
    _rc := 1;
    IF ((v_rowsaffected = 0) AND (v_err = 0)) THEN
      RAISE EXCEPTION 'Unable to Update Cashier Activity for Sale Return No. = (%)', v_doccode;
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  IF ((v_moduleid = 22) OR (v_moduleid = 23)) THEN
    DELETE FROM dbo.cashieractivity WHERE ((moduleid IN (22, 23)) AND (doccode = v_doccode));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    INSERT INTO dbo.cashieractivity (date, moduleid, doccode, catcode, category, acccode, usercode, machinename, headerno, headerinvno, amount, cashacccode, cashtendered, cashcharged, cashback, remarks, cashierjobcode, printed, supervised, supervisedon, glvochcode) SELECT date AS date, CASE WHEN (servicecatcode = 15) THEN 23 ELSE 22 END AS moduleid, v_doccode AS doccode, CASE WHEN (servicecatcode = 15) THEN 2 ELSE 1 END AS catcode, CASE WHEN (servicecatcode = 15) THEN 'Credit Service' ELSE 'Cash Service' END AS category, custcode AS acccode, salesmancode AS usercode, NULL::citext AS machinename, headerno, serviceinvcode AS headerinvno, coalesce(invtotal, 0) AS amount, cashacccode AS cashacccode, cashtendered AS cashtendered, CASE WHEN (servicecatcode = 15) THEN cashcharged ELSE CASE WHEN (cashcharged > 0) THEN cashcharged ELSE CASE WHEN (v_autofillcashcharged = 'N') THEN cashcharged ELSE coalesce(invtotal, 0) END END END AS cashcharged, CASE WHEN (servicecatcode = 15) THEN cashback ELSE CASE WHEN (cashcharged > 0) THEN cashback ELSE CASE WHEN (v_autofillcashcharged = 'N') THEN cashback ELSE 0.00 END END END AS cashback, remarks AS remarks, NULL::integer AS cashierjobcode, 'N' AS printed, 'N' AS supervised, NULL::timestamp(3) AS supervisedon, NULL::integer AS glvochcode FROM dbo.serviceheader WHERE ((serviceinvcode = v_doccode) AND (serviceinvcode NOT IN (SELECT DISTINCT doccode FROM dbo.cashieractivity WHERE ((moduleid IN (22, 23)) AND (doccode = v_doccode)))));
    GET DIAGNOSTICS _rc = ROW_COUNT;
    v_rowsaffected := _rc;
    v_err := 0;
    _rc := 1;
    IF ((v_rowsaffected = 0) AND (v_err = 0)) THEN
      RAISE EXCEPTION 'Unable to Update Cashier Activity for Service Invoice No. = (%)', v_doccode;
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_UpdateGodownDetail ====
CREATE OR REPLACE FUNCTION dbo.sp_updategodowndetail(gcode integer, icode integer, batch citext, expiry timestamp, qty numeric, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_gcode integer;
  v_icode integer;
  v_batch citext;
  v_expiry timestamp(3);
  v_qty numeric(15,4);
  v_itemname citext;
  v_string_expiry citext;
  v_rowsaffected integer;
  v_err integer;
  v_priority smallint;
  v_method smallint;
  _r1 record;
  _r2 record;
  _rc integer;
BEGIN
  v_gcode := gcode;
  v_icode := icode;
  v_batch := batch;
  v_expiry := expiry;
  v_qty := qty;
  UPDATE dbo.godowndetail SET currqty = (currqty + v_qty) WHERE ((((godowndetail.gcode = v_gcode) AND (godowndetail.icode = v_icode)) AND (godowndetail.batch = v_batch)) AND (godowndetail.expiry = v_expiry));
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_rowsaffected := _rc;
  v_err := 0;
  _rc := 1;
  IF ((v_rowsaffected = 0) AND (v_err = 0)) THEN
    v_method := (SELECT dbo.fn_get_int_preference('InventoryMovementMethod'));
    _rc := 1;
    IF (v_method = 1) THEN
      v_priority := 10;
      _rc := 1;
    ELSE
      IF (v_method = 3) THEN
        v_priority := coalesce((SELECT min(priority) FROM dbo.godowndetail WHERE (icode = v_icode)), 10);
        _rc := 1;
        IF (((v_priority - 1)) <= 0) THEN
          UPDATE dbo.godowndetail SET priority = CASE WHEN (priority >= 255) THEN 255 ELSE (priority + 1) END WHERE (icode = v_icode);
          GET DIAGNOSTICS _rc = ROW_COUNT;
          v_priority := coalesce((SELECT min(priority) FROM dbo.godowndetail WHERE (icode = v_icode)), 10);
          _rc := 1;
          IF (((v_priority - 1)) <= 0) THEN
            v_priority := 0;
            _rc := 1;
          ELSE
            v_priority := (v_priority - 1);
            _rc := 1;
          END IF;
        ELSE
          v_priority := (v_priority - 1);
          _rc := 1;
        END IF;
      ELSE
        IF (v_method = 2) THEN
          v_priority := coalesce((SELECT max(priority) FROM dbo.godowndetail WHERE (icode = v_icode)), 10);
          _rc := 1;
          IF (((v_priority + 1)) >= 255) THEN
            UPDATE dbo.godowndetail SET priority = CASE WHEN (priority >= 255) THEN 255 WHEN (priority <= 0) THEN 0 ELSE (priority - 1) END WHERE (icode = v_icode);
            GET DIAGNOSTICS _rc = ROW_COUNT;
            v_priority := coalesce((SELECT max(priority) FROM dbo.godowndetail WHERE (icode = v_icode)), 10);
            _rc := 1;
            IF (((v_priority + 1)) >= 255) THEN
              v_priority := 255;
              _rc := 1;
            ELSE
              v_priority := (v_priority + 1);
              _rc := 1;
            END IF;
          ELSE
            v_priority := (v_priority + 1);
            _rc := 1;
          END IF;
        END IF;
      END IF;
    END IF;
    INSERT INTO dbo.godowndetail (gcode, icode, batch, expiry, currqty, priority) VALUES (v_gcode, v_icode, v_batch, v_expiry, v_qty, v_priority);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((_rc = 0) OR (0 <> 0)) THEN
      _rc := 0;
      FOR _r1 IN SELECT name AS c1 FROM dbo.item WHERE (icode = v_icode) LOOP
        _rc := _rc + 1;
        v_itemname := _r1.c1;
      END LOOP;
      v_string_expiry := left(to_char(v_expiry, 'DD/MM/YYYY'), 25);
      _rc := 1;
      RAISE EXCEPTION 'Unable to insert stock for the item (%) in batch no. (%) with expiry (%)', v_itemname, v_batch, v_string_expiry;
      return_value := -1;
      RETURN;
    END IF;
  ELSE
    IF ((v_rowsaffected <> 1) OR (v_err <> 0)) THEN
      _rc := 0;
      FOR _r2 IN SELECT name AS c1 FROM dbo.item WHERE (icode = v_icode) LOOP
        _rc := _rc + 1;
        v_itemname := _r2.c1;
      END LOOP;
      v_string_expiry := left(to_char(v_expiry, 'DD/MM/YYYY'), 25);
      _rc := 1;
      RAISE EXCEPTION 'Not enough stock available for the item (%) in batch no. (%) with expiry (%)', v_itemname, v_batch, v_string_expiry;
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

