-- ==== proc SP_UpdateItemMeter ====
CREATE OR REPLACE FUNCTION dbo.sp_updateitemmeter(list citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_list citext;
  v_rows integer;
  v_rowid integer;
  v_saleinvcode integer;
  v_showitemmeter citext;
BEGIN
  v_list := list;
  -- SET NOCOUNT On
  DROP TABLE IF EXISTS tv_sp_updateitemmeter_sale;
  CREATE TEMP TABLE tv_sp_updateitemmeter_sale (
    code integer,
    rowid integer GENERATED BY DEFAULT AS IDENTITY
) ON COMMIT DROP;
  v_showitemmeter := (SELECT dbo.fn_getpreference('ShowItemMeterInSale') AS a);
  IF (v_showitemmeter = 'N') THEN
    return_value := 0;
    RETURN;
  END IF;
  INSERT INTO tv_sp_updateitemmeter_sale (code) SELECT code FROM dbo.udf_stringtotabl(v_list, ',') AS udf_stringtotabl ORDER BY code;
  v_rows := coalesce((SELECT count(*) FROM tv_sp_updateitemmeter_sale AS sale), 0);
  IF (v_rows > 0) THEN
    v_rowid := 1;
    WHILE (v_rowid <= v_rows) LOOP
      v_saleinvcode := (SELECT code FROM tv_sp_updateitemmeter_sale AS sale WHERE (rowid = v_rowid));
      UPDATE dbo.saledetail AS sd SET meterreading = coalesce(im.currentreading, 0) FROM dbo.itemmeter AS im WHERE ((sd.saleinvcode = v_saleinvcode) AND (sd.itemmetercode = im.itemmetercode));
      UPDATE dbo.itemmeter AS im SET currentreading = (coalesce(currentreading, 0) + sd.looseqty) FROM dbo.saledetail AS sd WHERE (((sd.saleinvcode = v_saleinvcode) AND (sd.itemmetercode = im.itemmetercode)) AND (sd.meterreading = im.currentreading));
      v_rowid := (v_rowid + 1);
    END LOOP;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

