-- ==== proc SP_UpdateItems_CategoryWise ====
CREATE OR REPLACE FUNCTION dbo.sp_updateitems_categorywise(srv citext, db citext, owner citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_upd citext;
  v_sql citext;
  v_qry citext;
  v_setpart citext;
  v_colname citext;
  v_qry_itemcat citext;
  v_endd citext;
  v_tablename citext;
  v_pkcond citext;
  v_full_table_name citext;
  v_priority smallint;
  v_keyseq smallint;
  v_position smallint;
  v_table_id integer;
  v_err integer;
  v_icatcode smallint;
  v_updatepurprice citext;
  v_updatesaleprice citext;
  v_updatesaleprice2 citext;
  v_updatesaleprice3 citext;
  v_updatesaleprice4 citext;
  v_updatesaleprice5 citext;
  v_updatesalediscperc citext;
  v_updatesalediscperc2 citext;
  v_updatesalediscperc3 citext;
  v_updatesalediscperc4 citext;
  v_updatesalediscperc5 citext;
  cur_ic1 refcursor;
  _dq1 text;
  _fs integer := -1;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  v_upd := 'UPDATE ';
  v_setpart := 'SET ';
  v_sql := ((((((' FROM ' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.');
  v_endd := ' AS T WHERE ';
  v_tablename := 'Item';
  v_pkcond := ' T.ICode = Item.ICode AND Item.ICatCode = ';
  OPEN cur_ic1 FOR SELECT icatcode, updatepurprice, updatesaleprice, updatesaleprice2, updatesaleprice3, updatesaleprice4, updatesaleprice5, updatesalediscperc, updatesalediscperc2, updatesalediscperc3, updatesalediscperc4, updatesalediscperc5 FROM dbo.itemcategorywiseupdation WHERE (((((((((((updatepurprice = 'Y') OR (updatesaleprice = 'Y')) OR (updatesaleprice2 = 'Y')) OR (updatesaleprice3 = 'Y')) OR (updatesaleprice4 = 'Y')) OR (updatesaleprice5 = 'Y')) OR (updatesalediscperc = 'Y')) OR (updatesalediscperc2 = 'Y')) OR (updatesalediscperc3 = 'Y')) OR (updatesalediscperc4 = 'Y')) OR (updatesalediscperc5 = 'Y'));
  FETCH NEXT FROM cur_ic1 INTO v_icatcode, v_updatepurprice, v_updatesaleprice, v_updatesaleprice2, v_updatesaleprice3, v_updatesaleprice4, v_updatesaleprice5, v_updatesalediscperc, v_updatesalediscperc2, v_updatesalediscperc3, v_updatesalediscperc4, v_updatesalediscperc5;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  WHILE (_fs = 0) LOOP
    v_setpart := 'SET ';
    IF (v_updatepurprice = 'Y') THEN
      v_setpart := (v_setpart || 'PurPrice=T.PurPrice,');
    END IF;
    IF (v_updatesaleprice = 'Y') THEN
      v_setpart := (v_setpart || 'SalePrice=T.SalePrice,');
    END IF;
    IF (v_updatesaleprice2 = 'Y') THEN
      v_setpart := (v_setpart || 'SalePrice2=T.SalePrice2,');
    END IF;
    IF (v_updatesaleprice3 = 'Y') THEN
      v_setpart := (v_setpart || 'SalePrice3=T.SalePrice3,');
    END IF;
    IF (v_updatesaleprice4 = 'Y') THEN
      v_setpart := (v_setpart || 'SalePrice4=T.SalePrice4,');
    END IF;
    IF (v_updatesaleprice5 = 'Y') THEN
      v_setpart := (v_setpart || 'SalePrice5=T.SalePrice5,');
    END IF;
    IF (v_updatesalediscperc = 'Y') THEN
      v_setpart := (v_setpart || 'SaleDiscPerc=T.SaleDiscPerc,');
    END IF;
    IF (v_updatesalediscperc2 = 'Y') THEN
      v_setpart := (v_setpart || 'SaleDiscPerc2=T.SaleDiscPerc2,');
    END IF;
    IF (v_updatesalediscperc3 = 'Y') THEN
      v_setpart := (v_setpart || 'SaleDiscPerc3=T.SaleDiscPerc3,');
    END IF;
    IF (v_updatesalediscperc4 = 'Y') THEN
      v_setpart := (v_setpart || 'SaleDiscPerc4=T.SaleDiscPerc4,');
    END IF;
    IF (v_updatesalediscperc5 = 'Y') THEN
      v_setpart := (v_setpart || 'SaleDiscPerc5=T.SaleDiscPerc5');
    END IF;
    IF ((right(v_setpart, 1))::citext = ',') THEN
      v_setpart := left(v_setpart, (length(rtrim(v_setpart)) - 1));
    END IF;
    v_qry := ((((((((((v_upd || v_tablename) || ' ') || v_setpart) || ' ') || v_sql) || v_tablename) || v_endd) || ' ') || v_pkcond) || ltrim(rtrim(dbo.tsql_str((v_icatcode)::numeric))));
    _dq1 := v_qry;
    IF _dq1 IS NOT NULL THEN
      EXECUTE dbo.tsql_dyn(_dq1);
    END IF;
    v_err := 0;
    IF ((0 <> 0) OR (v_err <> 0)) THEN
      RAISE EXCEPTION 'Data Updation: Error Transfering % Data', v_full_table_name;
      CLOSE cur_ic1;
      -- DEALLOCATE IC1
      return_value := -1;
      RETURN;
    END IF;
    FETCH NEXT FROM cur_ic1 INTO v_icatcode, v_updatepurprice, v_updatesaleprice, v_updatesaleprice2, v_updatesaleprice3, v_updatesaleprice4, v_updatesaleprice5, v_updatesalediscperc, v_updatesalediscperc2, v_updatesalediscperc3, v_updatesalediscperc4, v_updatesalediscperc5;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_ic1;
  -- DEALLOCATE IC1
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

