    INSERT INTO dbo.godowndetail (gcode, icode, batch, expiry, currqty, manfdate, priority) VALUES (v_gcode, v_icode, v_batch, v_expiry, v_newqty, v_manfdate, v_priority);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((_rc = 0) OR (0 <> 0)) THEN
