-- ==== proc SP_UpdateItemStockLedger ====
CREATE OR REPLACE FUNCTION dbo.sp_updateitemstockledger(icode integer, updatebasetable citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_icode integer;
  v_updatebasetable citext;
  v_rowid integer;
  v_items_rows integer;
  v_counter integer;
  v_totalrows integer;
  v_continue integer;
  v_err integer;
  v_rt_code integer;
  v_documentcode integer;
  v_documenttype citext;
  v_qty numeric(15,4);
  v_bonus numeric(15,4);
  v_stock numeric(15,4);
  v_newstock numeric(15,4);
  v_utn bigint;
  v_due citext;
  v_prevstock numeric(15,4);
  cur_cstock refcursor;
  _fs integer := -1;
BEGIN
  v_icode := icode;
  v_updatebasetable := updatebasetable;
  -- SET NOCOUNT ON
  v_continue := 0;
  IF ((v_updatebasetable IS NULL) OR (v_updatebasetable = '')) THEN
    v_updatebasetable := 'N';
  END IF;
  OPEN cur_cstock FOR SELECT documentcode, documenttype, qty, bonus, stock, newstock, utn, due FROM dbo.stockledger WHERE (icode = v_icode) ORDER BY utn;
  v_totalrows := (-1);
  FETCH NEXT FROM cur_cstock INTO v_documentcode, v_documenttype, v_qty, v_bonus, v_stock, v_newstock, v_utn, v_due;
  IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  v_counter := 1;
  WHILE ((_fs = 0) AND (v_counter <= v_totalrows)) LOOP
    IF ((v_counter = 1) AND (((((v_documenttype = 'PV') OR (v_documenttype = 'RV')) OR (v_documenttype = 'SR')) OR (v_documenttype = 'AI')))) THEN
      v_prevstock := v_newstock;
    END IF;
    v_prevstock := coalesce(v_prevstock, 0);
    IF (((((v_documenttype = 'PR') OR (v_documenttype = 'SV')) OR (v_documenttype = 'IV')) OR (v_documenttype = 'DS')) OR (v_documenttype = 'AD')) THEN
      IF (v_documenttype = 'SV') THEN
        UPDATE dbo.stockledger SET stock = v_prevstock, newstock = CASE WHEN (due IS NULL) THEN ((v_prevstock - v_qty) - v_bonus) ELSE v_prevstock END WHERE ((icode = v_icode) AND (utn = v_utn));
        IF (v_updatebasetable = 'Y') THEN
          UPDATE dbo.saledetail SET balancestock = CASE WHEN (due IS NULL) THEN ((v_prevstock - v_qty) - v_bonus) ELSE v_prevstock END WHERE ((saleinvcode = v_documentcode) AND (saleutn = v_utn));
        END IF;
        v_prevstock := coalesce((SELECT max(newstock) FROM dbo.stockledger WHERE ((icode = v_icode) AND (utn = v_utn))), 0);
      ELSE
        IF ((v_documenttype = 'PR') AND (v_updatebasetable = 'Y')) THEN
          UPDATE dbo.prdetail SET balancestock = ((v_prevstock - v_qty) - v_bonus) WHERE ((prinvcode = v_documentcode) AND (prutn = v_utn));
        END IF;
        IF ((v_documenttype = 'IV') AND (v_updatebasetable = 'Y')) THEN
          UPDATE dbo.issuedetail SET balancestock = ((v_prevstock - v_qty) - v_bonus) WHERE ((issueinvcode = v_documentcode) AND (issueutn = v_utn));
        END IF;
        IF ((v_documenttype = 'DS') AND (v_updatebasetable = 'Y')) THEN
          UPDATE dbo.duesatisfydetail SET balancestock = ((v_prevstock - v_qty) - v_bonus) WHERE ((duesatisfycode = v_documentcode) AND (duesatisfyutn = v_utn));
        END IF;
        IF ((v_documenttype = 'AD') AND (v_updatebasetable = 'Y')) THEN
          UPDATE dbo.adjdetail SET currstock = ((v_prevstock - v_qty) - v_bonus) WHERE ((adjcode = v_documentcode) AND (adjutn = v_utn));
        END IF;
        v_prevstock := ((v_prevstock - v_qty) - v_bonus);
      END IF;
    END IF;
    IF ((v_counter <> 1) AND (((((v_documenttype = 'PV') OR (v_documenttype = 'RV')) OR (v_documenttype = 'SR')) OR (v_documenttype = 'AI')))) THEN
      UPDATE dbo.stockledger SET stock = v_prevstock, newstock = ((v_prevstock + v_qty) + v_bonus) WHERE ((icode = v_icode) AND (utn = v_utn));
      IF ((v_documenttype = 'PV') AND (v_updatebasetable = 'Y')) THEN
        UPDATE dbo.purdetail SET currstock = v_prevstock WHERE ((purinvcode = v_documentcode) AND (purutn = v_utn));
      END IF;
      IF ((v_documenttype = 'RV') AND (v_updatebasetable = 'Y')) THEN
        UPDATE dbo.receiptdetail SET currstock = v_prevstock WHERE ((receiptinvcode = v_documentcode) AND (receiptutn = v_utn));
      END IF;
      IF ((v_documenttype = 'SR') AND (v_updatebasetable = 'Y')) THEN
        UPDATE dbo.srdetail SET currstock = v_prevstock WHERE ((srinvcode = v_documentcode) AND (srutn = v_utn));
      END IF;
      IF ((v_documenttype = 'AI') AND (v_updatebasetable = 'Y')) THEN
        UPDATE dbo.adjdetail SET currstock = v_prevstock WHERE ((adjcode = v_documentcode) AND (adjutn = v_utn));
      END IF;
      v_prevstock := ((v_prevstock + v_qty) + v_bonus);
    END IF;
    v_counter := (v_counter + 1);
    FETCH NEXT FROM cur_cstock INTO v_documentcode, v_documenttype, v_qty, v_bonus, v_stock, v_newstock, v_utn, v_due;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
  END LOOP;
  CLOSE cur_cstock;
  -- DEALLOCATE CStock
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_UpdateItemTotalPiecesInHand ====
CREATE OR REPLACE FUNCTION dbo.sp_updateitemtotalpiecesinhand(icode integer, incdec integer, totalpieces integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_icode integer;
  v_incdec integer;
  v_totalpieces integer;
  v_totalpieces_to_update integer;
  v_currenttotalpieces integer;
  v_itemname citext;
BEGIN
  v_icode := icode;
  v_incdec := incdec;
  v_totalpieces := totalpieces;
  v_itemname := (SELECT name FROM dbo.item WHERE (icode = v_icode));
  v_currenttotalpieces := coalesce((SELECT totalpieces FROM dbo.item WHERE (icode = v_icode)), 0);
  v_totalpieces_to_update := (v_totalpieces * v_incdec);
  IF ((v_incdec < 0) AND (v_currenttotalpieces < v_totalpieces)) THEN
    RAISE EXCEPTION 'Not Enough pieces available to issue/decrease for the item %', v_itemname;
    return_value := -1;
    RETURN;
  END IF;
  UPDATE dbo.item SET totalpieces = (totalpieces + v_totalpieces_to_update) WHERE (icode = v_icode);
  IF (0 <> 0) THEN
    RAISE EXCEPTION 'Unable to update total pieces for the item %', v_itemname;
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

