-- ==== proc sp_UpdatePurLedgerDailyICatCounter ====
CREATE OR REPLACE FUNCTION dbo.sp_updatepurledgerdailyicatcounter(ai_icatcode integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ai_icatcode integer;
  v_currentdate timestamp(3);
  v_lastdate timestamp(3);
  v_currentday integer;
  v_lastday integer;
  _rc integer;
BEGIN
  v_ai_icatcode := ai_icatcode;
  v_currentdate := localtimestamp(3);
  _rc := 1;
  v_lastdate := (SELECT lastmonthdate FROM dbo.serverdatemonthpur);
  _rc := 1;
  v_currentday := extract(doy from v_currentdate)::integer;
  _rc := 1;
  v_lastday := extract(doy from v_lastdate)::integer;
  _rc := 1;
  IF (((v_currentday > v_lastday)) OR (((v_currentday = 1) AND (v_lastday > 364)))) THEN
    UPDATE dbo.itemcategory SET purdailycounter = 0;
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((_rc > 0) AND (0 = 0)) THEN
      UPDATE dbo.serverdatemonthpur SET lastmonthdate = localtimestamp(3);
      GET DIAGNOSTICS _rc = ROW_COUNT;
      IF ((_rc = 0) OR (0 <> 0)) THEN
        RAISE EXCEPTION 'Unable to update ServerDateMonth.';
        return_value := -1;
        RETURN;
      END IF;
    ELSE
      RAISE EXCEPTION 'Unable to update ItemCategory  Counter.';
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  return_value := 0;
  RETURN;
END
$body$;

