-- ==== proc SP_UpdateStockLedger ====
CREATE OR REPLACE FUNCTION dbo.sp_updatestockledger(purgestockledger citext, updatebasetable citext, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_purgestockledger citext;
  v_updatebasetable citext;
  v_icode integer;
  v_rowid integer;
  v_items_rows integer;
  v_counter integer;
  _rc integer;
BEGIN
  v_purgestockledger := purgestockledger;
  v_updatebasetable := updatebasetable;
  -- SET NOCOUNT ON
  IF ((v_purgestockledger IS NULL) OR (v_purgestockledger = '')) THEN
    v_purgestockledger := 'N';
    _rc := 1;
  END IF;
  IF ((v_updatebasetable IS NULL) OR (v_updatebasetable = '')) THEN
    v_updatebasetable := 'N';
    _rc := 1;
  END IF;
  IF (v_purgestockledger = 'Y') THEN
    TRUNCATE TABLE dbo.stockledger;
  END IF;
  SELECT r.rs1 INTO rs1 FROM dbo.sp_stockledger() AS r;
  DROP TABLE IF EXISTS tv_sp_updatestockledger_citems;
  CREATE TEMP TABLE tv_sp_updatestockledger_citems (
    icode integer,
    rowid integer GENERATED BY DEFAULT AS IDENTITY
) ON COMMIT DROP;
  INSERT INTO tv_sp_updatestockledger_citems (icode) SELECT icode FROM dbo.item WHERE (icode IN (SELECT DISTINCT icode FROM dbo.stockledger)) ORDER BY icode;
  GET DIAGNOSTICS _rc = ROW_COUNT;
  v_items_rows := _rc;
  _rc := 1;
  v_rowid := 1;
  _rc := 1;
  RAISE NOTICE '%', ('Total Rows = ' || dbo.tsql_str((v_items_rows)::numeric));
  WHILE (v_rowid <= v_items_rows) LOOP
    RAISE NOTICE '%', ('Row ID = ' || dbo.tsql_str((v_rowid)::numeric));
    v_icode := (SELECT icode FROM tv_sp_updatestockledger_citems AS citems WHERE (rowid = v_rowid));
    _rc := 1;
    -- EXECUTE DBO.UpdateItemStockLedger @ICode, @UpdateBaseTable
    RAISE EXCEPTION 'untranslated T-SQL (unknown procedure UpdateItemStockLedger)' USING ERRCODE = '0A000';
    v_rowid := (v_rowid + 1);
    _rc := 1;
  END LOOP;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_UpdateTabMaxKey ====
CREATE OR REPLACE FUNCTION dbo.sp_updatetabmaxkey(tabname citext, key integer, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_tabname citext;
  v_key integer;
  _rc integer;
BEGIN
  v_tabname := tabname;
  v_key := key;
  UPDATE dbo._tabmaxkey SET tabmaxkey = coalesce(v_key, 0) WHERE (_tabmaxkey.tabname = v_tabname);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((0 <> 0) OR (_rc = 0)) THEN
    RAISE EXCEPTION 'Exception occured while Updating key value for table %', v_tabname;
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_UpdateTransitStock ====
CREATE OR REPLACE FUNCTION dbo.sp_updatetransitstock(mode smallint, icode integer, qty numeric, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_mode smallint;
  v_icode integer;
  v_qty numeric(15,4);
  v_itemname citext;
  v_autoupdate citext;
  _rc integer;
BEGIN
  v_mode := mode;
  v_icode := icode;
  v_qty := qty;
  v_autoupdate := (SELECT dbo.fn_getpreference('AutoUpdateTransitStock') AS a);
  _rc := 1;
  IF ((upper(v_autoupdate))::citext = 'Y') THEN
    IF ((v_mode < 0) OR (v_mode > 1)) THEN
      RAISE EXCEPTION 'UnRecognized Mode argument passed to StoredProcedure (sp_UpdateTransitStock) ';
      return_value := -1;
      RETURN;
    END IF;
    UPDATE dbo.item SET transitstock = CASE v_mode WHEN 0 THEN ((transitstock + v_qty)) WHEN 1 THEN CASE WHEN (((transitstock - v_qty)) < 0) THEN 0 ELSE ((transitstock - v_qty)) END END WHERE (icode = v_icode);
    GET DIAGNOSTICS _rc = ROW_COUNT;
    IF ((_rc = 0) OR (0 <> 0)) THEN
      v_itemname := (SELECT name FROM dbo.item WHERE (icode = v_icode));
      _rc := 1;
      RAISE EXCEPTION 'Unable to update TransitStock for Item: ';
      return_value := -1;
      RETURN;
    END IF;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

