CREATE OR REPLACE FUNCTION dbo.sp_validateserviceticket(serviceticketcode integer, INOUT date timestamp, INOUT serviceinvcode integer, INOUT servicecode integer, INOUT servicecatcode smallint, INOUT ticketused citext, INOUT ticketusedon timestamp, INOUT usercode smallint, INOUT expireson timestamp, INOUT price numeric, INOUT errortext citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_serviceticketcode integer;
  v_date timestamp(3);
  v_serviceinvcode integer;
  v_servicecode integer;
  v_servicecatcode smallint;
  v_ticketused citext;
  v_ticketusedon timestamp(3);
  v_usercode smallint;
  v_expireson timestamp(3);
  v_price numeric(12,2);
  v_errortext citext;
  v_totrows integer;
  v_errcode integer;
  _rc integer;
BEGIN
  v_serviceticketcode := serviceticketcode;
  v_date := date;
  v_serviceinvcode := serviceinvcode;
  v_servicecode := servicecode;
  v_servicecatcode := servicecatcode;
  v_ticketused := ticketused;
  v_ticketusedon := ticketusedon;
  v_usercode := usercode;
  v_expireson := expireson;
  v_price := price;
  v_errortext := errortext;
  -- SET NOCOUNT ON
  DROP TABLE IF EXISTS tv_sp_validateserviceticket_ticket_table;
  CREATE TEMP TABLE tv_sp_validateserviceticket_ticket_table (
    date timestamp(3),
    serviceinvcode integer,
    servicecode integer,
    servicecatcode smallint,
    ticketused citext,
    ticketusedon timestamp(3),
    usercode smallint,
    expireson timestamp(3),
    price numeric(12,2)
) ON COMMIT DROP;
  IF ((v_serviceticketcode IS NULL) OR (v_serviceticketcode <= 0)) THEN
    return_value := 0;
    date := v_date;
    serviceinvcode := v_serviceinvcode;
    servicecode := v_servicecode;
    servicecatcode := v_servicecatcode;
    ticketused := v_ticketused;
    ticketusedon := v_ticketusedon;
    usercode := v_usercode;
    expireson := v_expireson;
    price := v_price;
    errortext := v_errortext;
    RETURN;
  END IF;
  INSERT INTO tv_sp_validateserviceticket_ticket_table SELECT date, serviceinvcode, servicecode, (SELECT s.servicecatcode FROM dbo.service AS s WHERE (s.servicecode = serviceticket.servicecode)) AS servicecatcode, ticketused, ticketusedon, usercode, expireson, price FROM dbo.serviceticket WHERE (serviceticketcode = v_serviceticketcode);
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((0 <> 0) OR (_rc = 0)) THEN
    v_errortext := 'Problem while Fetching Service Ticket Information....';
    _rc := 1;
    RAISE EXCEPTION '%', v_errortext;
    return_value := -1;
    date := v_date;
    serviceinvcode := v_serviceinvcode;
    servicecode := v_servicecode;
    servicecatcode := v_servicecatcode;
    ticketused := v_ticketused;
    ticketusedon := v_ticketusedon;
    usercode := v_usercode;
    expireson := v_expireson;
    price := v_price;
    errortext := v_errortext;
    RETURN;
  END IF;
  v_totrows := coalesce((SELECT count(*) FROM tv_sp_validateserviceticket_ticket_table AS ticket_table), 0);
  _rc := 1;
  IF ((0 <> 0) OR (v_totrows = 0)) THEN
    v_errortext := (('Service Ticket No. ' || ltrim(rtrim(dbo.tsql_str((v_serviceticketcode)::numeric, 10)))) || ' doese not exists, Please enter some other ticket no.');
    _rc := 1;
    RAISE EXCEPTION '%', v_errortext;
    return_value := -1;
    date := v_date;
    serviceinvcode := v_serviceinvcode;
    servicecode := v_servicecode;
    servicecatcode := v_servicecatcode;
    ticketused := v_ticketused;
    ticketusedon := v_ticketusedon;
    usercode := v_usercode;
    expireson := v_expireson;
    price := v_price;
    errortext := v_errortext;
    RETURN;
  END IF;
  v_date := (SELECT date FROM tv_sp_validateserviceticket_ticket_table AS ticket_table);
  _rc := 1;
  v_serviceinvcode := (SELECT serviceinvcode FROM tv_sp_validateserviceticket_ticket_table AS ticket_table);
  _rc := 1;
  v_servicecode := (SELECT servicecode FROM tv_sp_validateserviceticket_ticket_table AS ticket_table);
  _rc := 1;
  v_servicecatcode := (SELECT servicecatcode FROM tv_sp_validateserviceticket_ticket_table AS ticket_table);
  _rc := 1;
  v_ticketused := coalesce((SELECT ticketused FROM tv_sp_validateserviceticket_ticket_table AS ticket_table), 'N');
  _rc := 1;
  v_ticketusedon := (SELECT ticketusedon FROM tv_sp_validateserviceticket_ticket_table AS ticket_table);
  _rc := 1;
  v_usercode := (SELECT usercode FROM tv_sp_validateserviceticket_ticket_table AS ticket_table);
  _rc := 1;
  v_expireson := (SELECT expireson FROM tv_sp_validateserviceticket_ticket_table AS ticket_table);
  _rc := 1;
  v_price := coalesce((SELECT price FROM tv_sp_validateserviceticket_ticket_table AS ticket_table), 0);
  _rc := 1;
  IF (v_ticketused = 'Y') THEN
    v_errortext := (('Service Ticket No. ' || ltrim(rtrim(dbo.tsql_str((v_serviceticketcode)::numeric, 10)))) || ' is Already Used, Please enter some other ticket no.');
    _rc := 1;
    return_value := 1;
    date := v_date;
    serviceinvcode := v_serviceinvcode;
    servicecode := v_servicecode;
    servicecatcode := v_servicecatcode;
    ticketused := v_ticketused;
    ticketusedon := v_ticketusedon;
    usercode := v_usercode;
    expireson := v_expireson;
    price := v_price;
    errortext := v_errortext;
    RETURN;
  END IF;
  IF (v_expireson < localtimestamp(3)) THEN
    v_errortext := (('Service Ticket No. ' || ltrim(rtrim(dbo.tsql_str((v_serviceticketcode)::numeric, 10)))) || ' is Already Expired, Please enter some other ticket no.');
    _rc := 1;
    return_value := 2;
    date := v_date;
    serviceinvcode := v_serviceinvcode;
    servicecode := v_servicecode;
    servicecatcode := v_servicecatcode;
    ticketused := v_ticketused;
    ticketusedon := v_ticketusedon;
    usercode := v_usercode;
    expireson := v_expireson;
    price := v_price;
    errortext := v_errortext;
    RETURN;
  END IF;
  UPDATE dbo.serviceticket SET ticketused = 'Y', ticketusedon = localtimestamp(3) WHERE (((serviceticketcode = v_serviceticketcode) AND (ticketused = 'N')) AND (expireson >= localtimestamp(3)));
  GET DIAGNOSTICS _rc = ROW_COUNT;
  IF ((0 <> 0) OR (_rc = 0)) THEN
    v_errortext := (('Problem while updating Record for Service Ticket No. ' || ltrim(rtrim(dbo.tsql_str((v_serviceticketcode)::numeric, 10)))) || ', Please enter some other ticket no.');
    _rc := 1;
    RAISE EXCEPTION '%', v_errortext;
    return_value := -1;
    date := v_date;
    serviceinvcode := v_serviceinvcode;
    servicecode := v_servicecode;
    servicecatcode := v_servicecatcode;
    ticketused := v_ticketused;
    ticketusedon := v_ticketusedon;
    usercode := v_usercode;
    expireson := v_expireson;
    price := v_price;
    errortext := v_errortext;
    RETURN;
  END IF;
  return_value := 0;
  date := v_date;
  serviceinvcode := v_serviceinvcode;
  servicecode := v_servicecode;
  servicecatcode := v_servicecatcode;
  ticketused := v_ticketused;
  ticketusedon := v_ticketusedon;
  usercode := v_usercode;
  expireson := v_expireson;
  price := v_price;
  errortext := v_errortext;
  RETURN;
  return_value := 0;
  date := v_date;
  serviceinvcode := v_serviceinvcode;
  servicecode := v_servicecode;
  servicecatcode := v_servicecatcode;
  ticketused := v_ticketused;
  ticketusedon := v_ticketusedon;
  usercode := v_usercode;
  expireson := v_expireson;
  price := v_price;
  errortext := v_errortext;
  RETURN;
END
$body$;

