-- ==== proc sp_VirtualGL ====
CREATE OR REPLACE FUNCTION dbo.sp_virtualgl(ac_type citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ac_type citext;
  v_rc integer;
  v_goodsacc smallint;
  v_goodsissueacc smallint;
  v_ln_purchaseacc numeric(5,0);
  v_ln_cashacc numeric(5,0);
  v_ln_equityacc numeric(5,0);
  v_ln_invacc numeric(5,0);
  v_ln_cgs numeric(5,0);
  v_ln_salesacc numeric(5,0);
  v_ln_salesretacc numeric(5,0);
  v_ln_purchaseretacc numeric(5,0);
  v_ln_revfromservice numeric(5,0);
  v_ln_salestaxacc numeric(5,0);
  v_ln_salestaxonsvc numeric(5,0);
  v_ln_advincometaxpur numeric(5,0);
  v_ln_advincometaxsale numeric(5,0);
  v_ln_fbrposfeeacc numeric(5,0);
  v_invsys citext;
  v_autopurgevirtualgl citext;
BEGIN
  v_ac_type := ac_type;
  -- SET NOCOUNT ON
  TRUNCATE TABLE dbo.virtualgltemp;
  v_rc := (SELECT count(*) FROM dbo.virtualgl);
  IF (upper(v_ac_type) IS NULL) THEN
    v_ac_type := 'A';
  END IF;
  IF (((upper(v_ac_type))::citext <> 'S') AND ((upper(v_ac_type))::citext <> 'A')) THEN
    v_ac_type := 'A';
  END IF;
  v_goodsacc := trunc(coalesce((SELECT code FROM dbo.global WHERE (name = 'GT_GoodsReceiptAcc')), 31))::smallint;
  v_goodsissueacc := trunc(coalesce((SELECT code FROM dbo.global WHERE (name = 'GT_GoodsIssuedAcc')), 31))::smallint;
  v_invsys := coalesce((SELECT dbo.fn_getpreference('InventorySystemUsed') AS a), 'P');
  v_ln_invacc := (SELECT code FROM dbo.global WHERE (name = 'GT_InventoryAcc'));
  v_ln_cgs := (SELECT code FROM dbo.global WHERE (name = 'GT_CostOfGoodsSoldAcc'));
  v_ln_purchaseacc := (SELECT code FROM dbo.global WHERE (name = 'GT_PurchaseAccount'));
  v_ln_cashacc := (SELECT code FROM dbo.global WHERE (name = 'GT_CashACC'));
  v_ln_equityacc := (SELECT code FROM dbo.global WHERE (name = 'GT_EquityACC'));
  v_ln_salesacc := (SELECT code FROM dbo.global WHERE (name = 'GT_SalesACC'));
  v_ln_salesretacc := (SELECT code FROM dbo.global WHERE (name = 'GT_SalesReturnACC'));
  v_ln_purchaseretacc := (SELECT code FROM dbo.global WHERE (name = 'GT_PurchaseReturnsAccount'));
  v_ln_revfromservice := (SELECT code FROM dbo.global WHERE (name = 'GT_RevenueFromServices'));
  v_ln_salestaxacc := (SELECT code FROM dbo.global WHERE (name = 'GT_AdvanceSalesTaxACC'));
  v_ln_salestaxonsvc := (SELECT code FROM dbo.global WHERE (name = 'GT_SalesTaxPayableOnServices'));
  v_ln_advincometaxpur := (SELECT code FROM dbo.global WHERE (name = 'GT_AdvIncomeTaxPur'));
  v_ln_advincometaxsale := (SELECT code FROM dbo.global WHERE (name = 'GT_AdvIncomeTaxSale'));
  v_ln_fbrposfeeacc := (SELECT code FROM dbo.global WHERE (name = 'GT_FBRPOSFeeAcc'));
  v_autopurgevirtualgl := coalesce((SELECT dbo.fn_getpreference('AutoPurgeVirtualGL') AS a), 'N');
  -- BEGIN TRANSACTION (the caller owns the transaction)
  IF (v_autopurgevirtualgl = 'Y') THEN
    TRUNCATE TABLE dbo.virtualgl;
    -- COMMIT (the caller owns the transaction)
    return_value := 0;
    RETURN;
  END IF;
  IF (v_ac_type <> 'C') THEN
    PERFORM dbo.sp_virtualgl_purchase();
    PERFORM dbo.sp_virtualgl_purchasereturn();
    PERFORM dbo.sp_virtualgl_purchaseservices();
  END IF;
  IF (v_ac_type <> 'S') THEN
    PERFORM dbo.sp_virtualgl_sales();
    PERFORM dbo.sp_virtualgl_salesreturn();
    PERFORM dbo.sp_virtualgl_services();
    PERFORM dbo.sp_virtualgl_saleorder();
  END IF;
  PERFORM dbo.sp_virtualgl_receipt();
  PERFORM dbo.sp_virtualgl_issue();
  PERFORM dbo.sp_virtualgl_adjustment();
  PERFORM dbo.sp_virtualgl_guest();
  PERFORM dbo.sp_virtualgl_patient();
  PERFORM dbo.sp_virtualgl_vouchers();
  PERFORM dbo.sp_virtualgl_notes();
  PERFORM dbo.sp_virtualgl_transactionwindow();
  PERFORM dbo.sp_virtualgl_payroll();
  PERFORM dbo.sp_virtualgl_products();
  PERFORM dbo.sp_virtualgl_cashiershift();
  INSERT INTO dbo.virtualgl (documentcode, documenttype, catcode, acccode, alternateacccode, date, debit, credit, remarks, checkno, usercode, vouchercode, invoicecode, invoicetype, outstandingamt, balance, vrow, patientcode, grn, gccode, vehicle, shipto, guestcode, studentcode, currencycode, conversionrate) SELECT documentcode, documenttype, catcode, dr_acccode AS dr_acccode, CASE WHEN (dr_acccode IN (SELECT acccode FROM dbo.accounts WHERE (subcode IN (SELECT code FROM dbo.global WHERE (name = 'GT_CashSub'))))) THEN alternateacccode ELSE NULL END AS alternateacccode, date, CASE WHEN (dr_acccode IN (SELECT acccode FROM dbo.accounts WHERE (acccode IN (v_ln_invacc, v_goodsacc, v_goodsissueacc, v_ln_purchaseacc, v_ln_salesacc, v_ln_salesretacc, v_ln_purchaseretacc, v_ln_revfromservice)))) THEN ((gross - coalesce(advincometax, 0)) - coalesce(fbrposfee, 0)) ELSE (coalesce(gross, 0) + coalesce(saletax, 0)) END AS debit, 0 AS credit, dr_remarks, checkno, usercode, vouchercode, invoicecode, invoicetype, outstandingamt, balance, 0 AS vrow, patientcode, grn, gccode, vehicle, shipto, guestcode, studentcode, currencycode, conversionrate FROM dbo.virtualgltemp UNION ALL SELECT documentcode, documenttype, catcode, cr_acccode AS cr_acccode, CASE WHEN (cr_acccode IN (SELECT acccode FROM dbo.accounts WHERE (subcode IN (SELECT code FROM dbo.global WHERE (name = 'GT_CashSub'))))) THEN alternateacccode ELSE NULL END AS alternateacccode, date, 0 AS debit, CASE WHEN (cr_acccode IN (SELECT acccode FROM dbo.accounts WHERE (acccode IN (v_ln_invacc, v_goodsacc, v_goodsissueacc, v_ln_purchaseacc, v_ln_salesacc, v_ln_salesretacc, v_ln_purchaseretacc, v_ln_revfromservice)))) THEN ((gross - coalesce(advincometax, 0)) - coalesce(fbrposfee, 0)) ELSE (coalesce(gross, 0) + coalesce(saletax, 0)) END AS credit, cr_remarks, checkno, usercode, vouchercode, invoicecode, invoicetype, outstandingamt, balance, 1 AS vrow, patientcode, grn, gccode, vehicle, shipto, guestcode, studentcode, currencycode, conversionrate FROM dbo.virtualgltemp UNION ALL SELECT documentcode, documenttype, catcode, CASE WHEN ((documenttype = 'RS') OR (documenttype = 'RR')) THEN v_ln_salestaxonsvc ELSE v_ln_salestaxacc END AS acccode, NULL::integer AS alternateacccode, date, CASE documenttype WHEN 'PV' THEN saletax WHEN 'SR' THEN saletax WHEN 'RR' THEN saletax ELSE 0 END AS debit, CASE documenttype WHEN 'SV' THEN saletax WHEN 'PR' THEN saletax WHEN 'RS' THEN saletax ELSE 0 END AS credit, saletax_remarks, checkno, usercode, vouchercode, invoicecode, invoicetype, outstandingamt, balance, 2 AS vrow, patientcode, grn, gccode, vehicle, shipto, guestcode, studentcode, currencycode, conversionrate FROM dbo.virtualgltemp WHERE (saletax <> 0) UNION ALL SELECT documentcode, documenttype, catcode, CASE WHEN ((documenttype = 'SV') OR (documenttype = 'SR')) THEN v_ln_advincometaxsale ELSE v_ln_advincometaxpur END AS acccode, NULL::integer AS alternateacccode, date, CASE documenttype WHEN 'PV' THEN advincometax WHEN 'SR' THEN advincometax ELSE 0 END AS debit, CASE documenttype WHEN 'SV' THEN advincometax WHEN 'PR' THEN advincometax ELSE 0 END AS credit, ('Adv. Income Tax ' || CASE WHEN ((documenttype = 'SR') OR (documenttype = 'PR')) THEN 'Reversed' ELSE 'Accounted For' END) AS saletax_remarks, checkno, usercode, vouchercode, invoicecode, invoicetype, outstandingamt, balance, 2 AS vrow, patientcode, grn, gccode, vehicle, shipto, guestcode, studentcode, currencycode, conversionrate FROM dbo.virtualgltemp WHERE ((((((documenttype = 'SV') OR (documenttype = 'SR')) OR (documenttype = 'PV')) OR (documenttype = 'PR'))) AND (advincometax <> 0)) UNION ALL SELECT documentcode, documenttype, catcode, CASE WHEN ((documenttype = 'SV') OR (documenttype = 'SR')) THEN v_ln_fbrposfeeacc ELSE v_ln_fbrposfeeacc END AS acccode, NULL::integer AS alternateacccode, date, CASE documenttype WHEN 'SR' THEN coalesce(fbrposfee, 0) ELSE 0 END AS debit, CASE documenttype WHEN 'SV' THEN coalesce(fbrposfee, 0) ELSE 0 END AS credit, ('FBR POS Service Fee ' || CASE documenttype WHEN 'SR' THEN 'Reversed' ELSE 'Accounted For' END) AS saletax_remarks, checkno, usercode, vouchercode, invoicecode, invoicetype, outstandingamt, balance, 2 AS vrow, patientcode, grn, gccode, vehicle, shipto, guestcode, studentcode, currencycode, conversionrate FROM dbo.virtualgltemp WHERE ((((documenttype = 'SV') OR (documenttype = 'SR'))) AND (coalesce(fbrposfee, 0) <> 0)) UNION ALL SELECT documentcode, documenttype, catcode, dramtacccode AS dramtacccode, NULL::integer AS alternateacccode, amtdate, amt AS debit, 0 AS credit, (((((CASE documenttype WHEN 'PV' THEN 'Paid during pur. inv. no.' WHEN 'PR' THEN 'Received during p/return no.' WHEN 'SV' THEN 'Received during sale inv. no.' WHEN 'SR' THEN 'Paid during s/return no.' ELSE dr_remarks END || ':') || ltrim(rtrim(dbo.tsql_str((invoicecode)::numeric)))) || ' (') || coalesce((SELECT ltrim(rtrim(a.name)) FROM dbo.accounts AS a WHERE (a.acccode = virtualgltemp.dr_acccode)), '')) || ')') AS remarks, amtref AS checkno, amtby, vouchercode, invoicecode, invoicetype, outstandingamt, balance, 3 AS vrow, patientcode, grn, gccode, vehicle, shipto, guestcode, studentcode, currencycode, conversionrate FROM dbo.virtualgltemp WHERE (amt > 0) UNION ALL SELECT documentcode, documenttype, catcode, cramtacccode AS cramtacccode, NULL::integer AS alternateacccode, amtdate, 0 AS debit, amt AS credit, (((((CASE documenttype WHEN 'PV' THEN 'Paid during pur. inv. no.' WHEN 'PR' THEN 'Received during p/return no.' WHEN 'SV' THEN 'Received during sale inv. no.' WHEN 'SR' THEN 'Paid during s/return no.' ELSE cr_remarks END || ':') || ltrim(rtrim(dbo.tsql_str((invoicecode)::numeric)))) || ' (') || coalesce((SELECT ltrim(rtrim(a.name)) FROM dbo.accounts AS a WHERE (a.acccode = virtualgltemp.dr_acccode)), '')) || ')') AS remarks, amtref AS checkno, amtby, vouchercode, invoicecode, invoicetype, outstandingamt, balance, 4 AS vrow, patientcode, grn, gccode, vehicle, shipto, guestcode, studentcode, currencycode, conversionrate FROM dbo.virtualgltemp WHERE (amt > 0) UNION ALL SELECT documentcode, documenttype, catcode, CASE WHEN (documenttype = 'SV') THEN v_ln_cgs ELSE v_ln_invacc END AS dr_acccode, NULL::integer AS alternateacccode, date, cgs AS debit, 0 AS credit, (CASE WHEN (documenttype = 'SV') THEN 'Cost of Sale charged for Sale Inv. #' ELSE 'Inventory Accounted for S/R  Inv. #' END || ltrim(rtrim(dbo.tsql_str((documentcode)::numeric)))) AS remarks, checkno, usercode, vouchercode, invoicecode, invoicetype, outstandingamt, balance, 0 AS vrow, patientcode, grn, gccode, vehicle, shipto, guestcode, studentcode, currencycode, conversionrate FROM dbo.virtualgltemp WHERE (((v_invsys <> 'P') AND (documenttype IN ('SV', 'SR'))) AND (cgs <> 0)) UNION ALL SELECT documentcode, documenttype, catcode, CASE WHEN (documenttype = 'SV') THEN v_ln_invacc ELSE v_ln_cgs END AS dr_acccode, NULL::integer AS alternateacccode, date, 0 AS debit, cgs AS credit, (CASE WHEN (documenttype = 'SV') THEN 'Inventory Accounted for Sale Inv. #' ELSE 'Cost of Sale Reversed for S/R Inv. #' END || ltrim(rtrim(dbo.tsql_str((documentcode)::numeric)))) AS remarks, checkno, usercode, vouchercode, invoicecode, invoicetype, outstandingamt, balance, 0 AS vrow, patientcode, grn, gccode, vehicle, shipto, guestcode, studentcode, currencycode, conversionrate FROM dbo.virtualgltemp WHERE (((v_invsys <> 'P') AND (documenttype IN ('SV', 'SR'))) AND (cgs <> 0));
  -- COMMIT (the caller owns the transaction)
  TRUNCATE TABLE dbo.virtualgltemp;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_VirtualGL_Adjustment ====
CREATE OR REPLACE FUNCTION dbo.sp_virtualgl_adjustment(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ln_purchaseacc numeric(5,0);
  v_ln_cashacc numeric(5,0);
  v_ln_equityacc numeric(5,0);
  v_ln_invacc numeric(5,0);
  v_ln_cgs numeric(5,0);
  v_ln_salesacc numeric(5,0);
  v_ln_salesretacc numeric(5,0);
  v_ln_purchaseretacc numeric(5,0);
  v_ln_revfromservice numeric(5,0);
  v_ln_salestaxacc numeric(5,0);
  v_sremks citext;
  v_invsys citext;
BEGIN
  -- SET NOCOUNT ON
  v_invsys := coalesce((SELECT dbo.fn_getpreference('InventorySystemUsed') AS a), 'P');
  v_ln_invacc := (SELECT code FROM dbo.global WHERE (name = 'GT_InventoryAcc'));
  v_ln_cgs := (SELECT code FROM dbo.global WHERE (name = 'GT_CostOfGoodsSoldAcc'));
  v_ln_cashacc := (SELECT code FROM dbo.global WHERE (name = 'GT_CashACC'));
  v_ln_salesacc := (SELECT code FROM dbo.global WHERE (name = 'GT_SalesACC'));
  v_ln_salesretacc := (SELECT code FROM dbo.global WHERE (name = 'GT_SalesReturnACC'));
  v_ln_salestaxacc := (SELECT code FROM dbo.global WHERE (name = 'GT_AdvanceSalesTaxACC'));
  DROP TABLE IF EXISTS tmp_lsl;
  CREATE TEMP TABLE tmp_lsl (
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lsl SELECT adjcode FROM dbo.adjheader WHERE ((posted = 'Y') AND (NOT EXISTS (SELECT DISTINCT documentcode FROM dbo.virtualgl AS v WHERE ((v.documenttype IN ('AI', 'AD')) AND (v.documentcode = adjheader.adjcode)))));
  INSERT INTO dbo.virtualgltemp SELECT a.adjcode AS documentcode, CASE a.adjcatcode WHEN 1 THEN 'AI' ELSE 'AD' END AS documenttype, a.adjcatcode AS catcode, trunc(CASE a.adjcatcode WHEN 1 THEN v_ln_invacc ELSE a.acccode END)::smallint AS dr_acccode, trunc(CASE a.adjcatcode WHEN 1 THEN a.acccode ELSE v_ln_invacc END)::smallint AS cr_acccode, NULL::smallint AS alternateacccode, a.date AS date, 0 AS saletax, round((sum((d.looseqty * d.price)))::numeric, 0) AS gross, (CASE a.adjcatcode WHEN 1 THEN 'Stock Adjustment Increase # ' ELSE 'Stock Adjustment Decrease # ' END || ltrim(rtrim(dbo.tsql_str((a.adjcode)::numeric)))) AS dr_remarks, (CASE a.adjcatcode WHEN 1 THEN 'Stock Adjustment Increase # ' ELSE 'Stock Adjustment Decrease # ' END || ltrim(rtrim(dbo.tsql_str((a.adjcode)::numeric)))) AS cr_remarks, '' AS saletax_remarks, NULL::citext AS checkno, a.usercode AS usercode, a.adjcode AS vouchercode, a.adjcode AS invoicecode, NULL::smallint AS invoicetype, 0 AS amt, NULL::integer AS dramtacccode, NULL::integer AS cramtacccode, NULL::smallint AS amtby, NULL::timestamp(3) AS amtdate, NULL::citext AS amtref, 0 AS outstandingamt, 0 AS balance, NULL::integer AS patientcode, NULL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto, NULL::integer AS guestcode, NULL::integer AS studentcode, 0 AS cgs, NULL::smallint AS currencycode, NULL::numeric(11,5) AS conversionrate, 0.00 AS advincometax, 0.00 AS fbrposfee FROM dbo.adjheader AS a, dbo.adjdetail AS d WHERE (((a.adjcode IN (SELECT code FROM tmp_lsl AS lsl)) AND (a.adjcode = d.adjcode)) AND (a.acccode IS NOT NULL)) GROUP BY a.adjcode, a.acccode, a.adjcatcode, a.date, a.usercode, a.remarks;
  TRUNCATE TABLE tmp_lsl RESTART IDENTITY;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_VirtualGL_CashierShift ====
CREATE OR REPLACE FUNCTION dbo.sp_virtualgl_cashiershift(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
BEGIN
  -- SET NOCOUNT ON
  DROP TABLE IF EXISTS tmp_lsl;
  CREATE TEMP TABLE tmp_lsl (
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lsl SELECT cashiershiftcode FROM dbo.cashiershift WHERE ((shiftstatus = 'C') AND (NOT EXISTS (SELECT DISTINCT documentcode FROM dbo.virtualgl AS v WHERE ((v.documenttype IN ('CSHIFT')) AND (v.documentcode = cashiershift.cashiershiftcode)))));
