, NULL::integer AS invoicecode, NULL::smallint AS invoicetype, 0 AS outstandingamt, 0 AS balance, 0 AS vrow, NULL::integer AS patientcode, NULL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto, NULL::integer AS guestcode, NULL::integer AS studentcode, NULL::smallint AS currencycode, NULL::numeric(11,5) AS conversionrate FROM dbo.cashiershift WHERE ((((shiftstatus = 'C') AND (cashiershiftcode IN (SELECT code FROM tmp_lsl AS lsl))) AND (diffamt > 0)) AND (difftransferedto IS NOT NULL)) UNION ALL SELECT cashiershiftcode AS documentcode, 'CSHIFT' AS documenttype, 1 AS catcode, difftransferedto AS acccode, NULL::smallint AS alternateacccode, closedon AS date, abs(diffamt) AS debit, 0.00 AS credit, (((('Short Cash From Cashier Shift # ' || ltrim(rtrim(dbo.tsql_str((cashiershiftcode)::numeric)))) || '(') || coalesce((SELECT u.username FROM dbo.users AS u WHERE (u.usercode = shiftowner)), '')) || ')') AS remarks, NULL::citext AS checkno, shiftowner, cashiershiftcode AS vouchercode, NULL::integer AS invoicecode, NULL::smallint AS invoicetype, 0 AS outstandingamt, 0 AS balance, 0 AS vrow, NULL::integer AS patientcode, NULL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto, NULL::integer AS guestcode, NULL::integer AS studentcode, NULL::smallint AS currencycode, NULL::numeric(11,5) AS conversionrate FROM dbo.cashiershift WHERE ((((shiftstatus = 'C') AND (cashiershiftcode IN (SELECT code FROM tmp_lsl AS lsl))) AND (diffamt < 0)) AND (difftransferedto IS NOT NULL)) UNION ALL SELECT cashiershiftcode AS documentcode, 'CSHIFT' AS documenttype, 1 AS catcode, cashacccode AS acccode, NULL::smallint AS alternateacccode, closedon AS date, 0.00 AS debit, abs(diffamt) AS credit, (((('Short Cash From Cashier Shift # ' || ltrim(rtrim(dbo.tsql_str((cashiershiftcode)::numeric)))) || '(') || coalesce((SELECT u.username FROM dbo.users AS u WHERE (u.usercode = shiftowner)), '')) || ')') AS remarks, NULL::citext AS checkno, shiftowner, cashiershiftcode AS vouchercode, NULL::integer AS invoicecode, NULL::smallint AS invoicetype, 0 AS outstandingamt, 0 AS balance, 0 AS vrow, NULL::integer AS patientcode, NULL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto, NULL::integer AS guestcode, NULL::integer AS studentcode, NULL::smallint AS currencycode, NULL::numeric(11,5) AS conversionrate FROM dbo.cashiershift WHERE ((((shiftstatus = 'C') AND (cashiershiftcode IN (SELECT code FROM tmp_lsl AS lsl))) AND (diffamt < 0)) AND (difftransferedto IS NOT NULL));
