 patientcode, NULL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto, s.guestcode AS guestcode, NULL::integer AS studentcode, 0 AS cgs, NULL::smallint AS currencycode, NULL::numeric(11,5) AS conversionrate, 0.00 AS advincometax, 0.00 AS fbrposfee FROM dbo.guestcheckin AS s, dbo.mastercashwin AS d, dbo.guest AS g WHERE ((((d.documenttype = 'GC') AND (s.guestcheckincode = d.documentcode)) AND (s.guestcode = g.guestcode)) AND (s.guestcheckincode IN (SELECT code FROM tmp_lt_guestcheckin AS lt_guestcheckin)));
