-- ==== proc SP_VirtualGL_Issue ====
CREATE OR REPLACE FUNCTION dbo.sp_virtualgl_issue(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_invacc smallint;
  v_goodsacc smallint;
  v_invsys citext;
  v_sremks citext;
BEGIN
  -- SET NOCOUNT ON
  v_invsys := coalesce((SELECT dbo.fn_getpreference('InventorySystemUsed') AS a), 'P');
  v_invacc := trunc(coalesce((SELECT code FROM dbo.global WHERE (name = 'GT_InventoryAcc')), 7))::smallint;
  v_goodsacc := trunc(coalesce((SELECT code FROM dbo.global WHERE (name = 'GT_GoodsIssuedAcc')), 30))::smallint;
  v_sremks := (SELECT dbo.fn_getpreference('ShowIssueRemarksinledger') AS a);
  DROP TABLE IF EXISTS tmp_lsl;
  CREATE TEMP TABLE tmp_lsl (
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lsl SELECT issueinvcode FROM dbo.issueheader WHERE ((posted = 'Y') AND (NOT EXISTS (SELECT DISTINCT documentcode FROM dbo.virtualgl AS v WHERE ((v.documenttype IN ('ISU')) AND (v.documentcode = issueheader.issueinvcode)))));
  INSERT INTO dbo.virtualgltemp SELECT a.issueinvcode AS documentcode, 'ISU' AS documenttype, a.issuecategorycode AS catcode, a.dracccode AS dr_acccode, CASE WHEN (v_invsys <> 'P') THEN v_invacc ELSE v_goodsacc END AS cr_acccode, NULL::smallint AS alternateacccode, a.date AS date, 0 AS saletax, round((sum((d.qty * d.price)))::numeric, 0) AS gross, CASE v_sremks WHEN 'Y' THEN a.remarks ELSE CASE WHEN (a.remarks IS NULL) THEN ('Goods Issue against Issue Inv #' || ltrim(rtrim(dbo.tsql_str((a.issueinvcode)::numeric)))) ELSE a.remarks END END AS dr_remarks, CASE v_sremks WHEN 'Y' THEN a.remarks ELSE CASE WHEN (a.remarks IS NULL) THEN ('Goods Issue against Issue Inv #' || ltrim(rtrim(dbo.tsql_str((a.issueinvcode)::numeric)))) ELSE a.remarks END END AS cr_remarks, '' AS saletax_remarks, CASE v_sremks WHEN 'Y' THEN left(ltrim(rtrim(a.referenceno)), 20) ELSE NULL END AS checkno, a.salesmancode AS usercode, a.issuecode AS vouchercode, a.issueinvcode AS invoicecode, NULL::smallint AS invoicetype, 0 AS amt, NULL::integer AS dramtacccode, NULL::integer AS cramtacccode, NULL::smallint AS amtby, NULL::timestamp(3) AS amtdate, NULL::citext AS amtref, 0 AS outstandingamt, 0 AS balance, NULL::integer AS patientcode, NULL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto, NULL::integer AS guestcode, NULL::integer AS studentcode, 0 AS cgs, NULL::smallint AS currencycode, NULL::numeric(11,5) AS conversionrate, 0.00 AS advincometax, 0.00 AS fbrposfee FROM dbo.issueheader AS a, dbo.issuedetail AS d WHERE ((((a.accountfor = 'Y') AND (a.dracccode IS NOT NULL)) AND (a.issueinvcode IN (SELECT code FROM tmp_lsl AS lsl))) AND (a.issueinvcode = d.issueinvcode)) GROUP BY a.issueinvcode, a.issuecode, a.dracccode, a.issuecategorycode, a.date, a.salesmancode, a.remarks, a.referenceno;
  TRUNCATE TABLE tmp_lsl RESTART IDENTITY;
  return_value := 0;
  RETURN;
END
$body$;

