LL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto, NULL::integer AS guestcode, NULL::integer AS studentcode, NULL::smallint AS currencycode, NULL::numeric(11,5) AS conversionrate FROM dbo.notes WHERE (notes.notecode IN (SELECT code FROM tmp_lt_notes AS lt_notes));
  TRUNCATE TABLE tmp_lt_notes RESTART IDENTITY;
  return_value := 0;
  RETURN;
