-- ==== proc SP_VirtualGL_Payroll ====
CREATE OR REPLACE FUNCTION dbo.sp_virtualgl_payroll(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ln_cashacc numeric(5,0);
  v_ln_payrollpayable numeric(5,0);
  v_sremks citext;
  v_payrollbookon citext;
BEGIN
  -- SET NOCOUNT ON
  v_ln_cashacc := (SELECT code FROM dbo.global WHERE (name = 'GT_CashACC'));
  v_ln_payrollpayable := (SELECT code FROM dbo.global WHERE (name = 'GT_PayrollPayableAcc'));
  v_payrollbookon := (SELECT dbo.fn_getpreference('bookingdateinpayroll') AS a);
  DROP TABLE IF EXISTS tmp_lsl;
  CREATE TEMP TABLE tmp_lsl (
    code integer NOT NULL
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_lsl2;
  CREATE TEMP TABLE tmp_lsl2 (
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lsl SELECT payrollcode FROM dbo.emp_payroll WHERE ((posted = 'Y') AND (NOT EXISTS (SELECT DISTINCT documentcode FROM dbo.virtualgl AS v WHERE ((v.documenttype IN ('PAY')) AND (v.documentcode = emp_payroll.payrollcode)))));
