 AS vouchercode, NULL::integer AS invoicecode, NULL::smallint AS invoicetype, 0 AS outstandingamt, 0 AS balance, 1 AS vrow, NULL::integer AS patientcode, NULL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto, NULL::integer AS guestcode, NULL::integer AS studentcode, NULL::smallint AS currencycode, NULL::numeric(11,5) AS conversionrate FROM dbo.emp_payroll AS ep, dbo.emp_employee AS e WHERE ((((ep.posted = 'Y') AND (ep.payrollcode IN (SELECT code FROM tmp_lsl AS lsl))) AND (ep.empcode = e.empcode)) AND (ep.advance > 0)) UNION ALL SELECT ep.payrollcode AS documentcode, 'PAY' AS documenttype, 1 AS catcode, a.acccode AS acccode, NULL::smallint AS alternateacccode, CASE v_payrollbookon WHEN 'P' THEN ep.postdate ELSE ep.date END AS date, 0 AS debit, round((((((ep.basicpay * epd.percentage) * 0.01)) + epd.flatamount))::numeric, 2) AS credit, ep.remarks, NULL::citext AS checkno, ep.postedby, ep.payrollcode AS vouchercode, NULL::integer AS invoicecode, NULL::smallint AS invoicetype, 0 AS outstandingamt, 0 AS balance, 2 AS vrow, NULL::integer AS patientcode, NULL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto, NULL::integer AS guestcode, NULL::integer AS studentcode, NULL::smallint AS currencycode, NULL::numeric(11,5) AS conversionrate FROM dbo.emp_payroll AS ep, dbo.emp_employee AS e, dbo.emp_payrolldeductions AS epd, dbo.accounts AS a WHERE (((((ep.posted = 'Y') AND (ep.payrollcode IN (SELECT code FROM tmp_lsl AS lsl))) AND (ep.empcode = e.empcode)) AND (ep.payrollcode = epd.payrollcode)) AND (epd.deductioncode = a.acccode)) UNION ALL SELECT ep.payrollcode AS documentcode, 'PAY' AS documenttype, 1 AS catcode, v_ln_payrollpayable AS acccode, NULL::smallint AS alternateacccode, CASE v_payrollbookon WHEN 'P' THEN ep.postdate ELSE ep.date END AS date, 0 AS debit, ep.netpayable AS credit, ep.remarks, NULL::citext AS checkno, ep.postedby, ep.payrollcode AS vouchercode, NULL::integer AS invoicecode, NULL::smallint AS invoicetype, 0 AS outstandingamt, 0 AS balance, 3 AS vrow, NULL::integer AS patientcode, NULL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto, NULL::integer AS guestcode, NULL::integer AS studentcode, NULL::smallint AS currencycode, NULL::numeric(11,5) AS conversionrate FROM dbo.emp_payroll AS ep WHERE ((ep.posted = 'Y') AND (ep.payrollcode IN (SELECT code FROM tmp_lsl AS lsl))) UNION ALL SELECT ep.payrollcode AS documentcode, 'PAYD' AS documenttype, 1 AS catcode, v_ln_payrollpayable AS acccode, NULL::smallint AS alternateacccode, ep.paymentdate, ep.netpayable AS debit, 0.00 AS credit, ep.paymentremarks, paymentrefno AS checkno, coalesce(ep.paidby, 1), ep.payrollcode AS vouchercode, NULL::integer AS invoicecode, NULL::smallint AS invoicetype, 0 AS outstandingamt, 0 AS balance, 0 AS vrow, NULL::integer AS patientcode, NULL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto, NULL::integer AS guestcode, NULL::integer AS studentcode, NULL::smallint AS currencycode, NULL::numeric(11,5) AS conversionrate FROM dbo.emp_payroll AS ep WHERE (((ep.posted = 'Y') AND (ep.paid = 'Y')) AND (ep.payrollcode IN (SELECT code FROM tmp_lsl2 AS lsl2))) UNION ALL SELECT ep.payrollcode AS documentcode, 'PAYD' AS documenttype, 1 AS catcode, ep.paidvia AS acccode, NULL::smallint AS alternateacccode, ep.paymentdate, 0.00 AS debit, ep.netpayable AS credit, ep.paymentremarks, paymentrefno AS checkno, coalesce(ep.paidby, 1), ep.payrollcode AS vouchercode, NULL::integer AS invoicecode, NULL::smallint AS invoicetype, 0 AS outstandingamt, 0 AS balance, 1 AS vrow, NULL::integer AS patientcode, NULL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto, NULL::integer AS guestcode, NULL::integer AS studentcode, NULL::smallint AS currencycode, NULL::numeric(11,5) AS conversionrate FROM dbo.emp_payroll AS ep WHERE (((ep.posted = 'Y') AND (ep.paid = 'Y')) AND (ep.payrol