-- ==== proc SP_VirtualGL_Products ====
CREATE OR REPLACE FUNCTION dbo.sp_virtualgl_products(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ln_purchaseacc numeric(5,0);
  v_ln_cashacc numeric(5,0);
  v_ln_equityacc numeric(5,0);
  v_ln_invacc numeric(5,0);
  v_ln_cgs numeric(5,0);
  v_ln_salesacc numeric(5,0);
  v_ln_salesretacc numeric(5,0);
  v_ln_purchaseretacc numeric(5,0);
  v_ln_revfromservice numeric(5,0);
  v_ln_salestaxacc numeric(5,0);
  v_ln_advincometaxsale numeric(5,0);
  v_ln_fbrposfeeacc numeric(5,0);
  v_sremks citext;
  v_invsys citext;
  v_roundupyo smallint;
  v_advincometax citext;
BEGIN
  -- SET NOCOUNT ON
  v_advincometax := coalesce((SELECT dbo.fn_getpreference('ApplyAdvanceIncomeTaxInSale') AS a), 'N');
  v_roundupyo := (SELECT dbo.fn_get_int_preference('roundsaleinvon') AS a);
  v_invsys := coalesce((SELECT dbo.fn_getpreference('InventorySystemUsed') AS a), 'P');
  v_ln_invacc := (SELECT code FROM dbo.global WHERE (name = 'GT_ProductInvAcc'));
  v_ln_cgs := (SELECT code FROM dbo.global WHERE (name = 'GT_CostOfProductsSaleAcc'));
  v_ln_cashacc := (SELECT code FROM dbo.global WHERE (name = 'GT_CashACC'));
  v_ln_salesacc := (SELECT code FROM dbo.global WHERE (name = 'GT_ProductSalesAcc'));
  v_ln_salesretacc := (SELECT code FROM dbo.global WHERE (name = 'GT_SalesReturnACC'));
  v_ln_salestaxacc := (SELECT code FROM dbo.global WHERE (name = 'GT_AdvanceSalesTaxACC'));
  v_ln_advincometaxsale := (SELECT code FROM dbo.global WHERE (name = 'GT_AdvIncomeTaxSale'));
  v_ln_fbrposfeeacc := (SELECT code FROM dbo.global WHERE (name = 'GT_FBRPOSFeeAcc'));
  v_ln_revfromservice := (SELECT code FROM dbo.global WHERE (name = 'GT_OtheRevFrmProductsAcc'));
  DROP TABLE IF EXISTS tmp_lsl;
  CREATE TEMP TABLE tmp_lsl (
    code integer NOT NULL
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_lsl2;
  CREATE TEMP TABLE tmp_lsl2 (
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lsl SELECT productcode FROM dbo.product WHERE ((aquired = 'Y') AND (NOT EXISTS (SELECT DISTINCT documentcode FROM dbo.virtualgl AS v WHERE ((v.documenttype = 'PDA') AND (v.documentcode = product.productcode)))));
  INSERT INTO tmp_lsl2 SELECT productcode FROM dbo.product WHERE ((sold = 'Y') AND (NOT EXISTS (SELECT DISTINCT documentcode FROM dbo.virtualgl AS v WHERE ((v.documenttype = 'PDS') AND (v.documentcode = product.productcode)))));
  INSERT INTO dbo.virtualgltemp SELECT productcode AS documentcode, 'PDA' AS documenttype, 1 AS catcode, trunc(v_ln_invacc)::smallint AS dr_acccode, suppcode AS cr_acccode, NULL::smallint AS alternateacccode, aquiredon AS date, 0.00 AS saletax, (purchaseprice + transportation) AS gross, ('Product Acquired On Code ' || rtrim(ltrim((productcode)::text))) AS dr_remarks, ('Product Acquired On Code ' || rtrim(ltrim((productcode)::text))) AS cr_remarks, '' AS saletax_remarks, NULL::citext AS checkno, coalesce(aquiredby, 1) AS usercode, productcode AS vouchercode, productcode AS invoicecode, 2 AS invoicetype, 0.00 AS amt, NULL::integer AS dramtacccode, NULL::integer AS cramtacccode, NULL::smallint AS amtby, NULL::timestamp(3) AS amtdate, NULL::citext AS amtref, (purchaseprice + transportation) AS outstandingamt, (purchaseprice + transportation) AS balance, NULL::integer AS patientcode, NULL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto, NULL::integer, NULL::integer, 0.00 AS cgs, NULL::smallint AS currencycode, NULL::numeric(11,5) AS conversionrate, 0 AS advincometax, 0 AS fbrposfee FROM dbo.product WHERE (productcode IN (SELECT code FROM tmp_lsl AS lsl));
  INSERT INTO dbo.virtualgltemp SELECT productcode AS documentcode, 'PDA' AS documenttype, 1 AS catcode, suppcode AS dr_acccode, trunc(v_ln_revfromservice)::smallint AS cr_acccode, NULL::smallint AS alternateacccode, aquiredon AS date, 0.00 AS saletax, firmcommissionreceived AS gross, ('Commission Relaized On Product Code ' || rtrim(ltrim((productcode)::text))) AS dr_remarks, ('Commission Relaized On Product Code ' || rtrim(ltrim((productcode)::text))) AS cr_remarks, '' AS saletax_remarks, NULL::citext AS checkno, coalesce(aquiredby, 1) AS usercode, productcode AS vouchercode, productcode AS invoicecode, 2 AS invoicetype, 0.00 AS amt, NULL::integer AS dramtacccode, NULL::integer AS cramtacccode, NULL::smallint AS amtby, NULL::timestamp(3) AS amtdate, NULL::citext AS amtref, (purchaseprice + transportation) AS outstandingamt, (purchaseprice + transportation) AS balance, NULL::integer AS patientcode, NULL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto, NULL::integer, NULL::integer, 0.00 AS cgs, NULL::smallint AS currencycode, NULL::numeric(11,5) AS conversionrate, 0 AS advincometax, 0 AS fbrposfee FROM dbo.product WHERE ((firmcommissionreceived > 0) AND (productcode IN (SELECT code FROM tmp_lsl AS lsl)));
  INSERT INTO dbo.virtualgltemp SELECT productcode AS documentcode, 'PDS' AS documenttype, 1 AS catcode, custcode AS dr_acccode, trunc(v_ln_salesacc)::smallint AS cr_acccode, NULL::smallint AS alternateacccode, soldon AS date, 0.00 AS saletax, (saleprice - discount) AS gross, ('Product Sale Against Code ' || rtrim(ltrim((productcode)::text))) AS dr_remarks, ('Product Sale Against Code ' || rtrim(ltrim((productcode)::text))) AS cr_remarks, '' AS saletax_remarks, NULL::citext AS checkno, coalesce(soldby, 1) AS usercode, productcode AS vouchercode, productcode AS invoicecode, 1 AS invoicetype, 0.00 AS amt, NULL::integer AS dramtacccode, NULL::integer AS cramtacccode, NULL::smallint AS amtby, NULL::timestamp(3) AS amtdate, NULL::citext AS amtref, (saleprice - discount) AS outstandingamt, (saleprice - discount) AS balance, NULL::integer AS patientcode, NULL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto, NULL::integer, NULL::integer, 0.00 AS cgs, NULL::smallint AS currencycode, NULL::numeric(11,5) AS conversionrate, 0 AS advincometax, 0 AS fbrposfee FROM dbo.product WHERE (productcode IN (SELECT code FROM tmp_lsl2 AS lsl2));
  INSERT INTO dbo.virtualgltemp SELECT productcode AS documentcode, 'PDS' AS documenttype, 1 AS catcode, trunc(v_ln_cgs)::smallint AS dr_acccode, trunc(v_ln_invacc)::smallint AS cr_acccode, NULL::smallint AS alternateacccode, soldon AS date, 0.00 AS saletax, (purchaseprice + transportation) AS gross, ('Product Cost Of Sales Realized On Code ' || rtrim(ltrim((productcode)::text))) AS dr_remarks, ('Product Cost Of Sales Realized On Code ' || rtrim(ltrim((productcode)::text))) AS cr_remarks, '' AS saletax_remarks, NULL::citext AS checkno, coalesce(soldby, 1) AS usercode, productcode AS vouchercode, productcode AS invoicecode, 1 AS invoicetype, 0.00 AS amt, NULL::integer AS dramtacccode, NULL::integer AS cramtacccode, NULL::smallint AS amtby, NULL::timestamp(3) AS amtdate, NULL::citext AS amtref, (purchaseprice + transportation) AS outstandingamt, (purchaseprice + transportation) AS balance, NULL::integer AS patientcode, NULL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto, NULL::integer, NULL::integer, 0.00 AS cgs, NULL::smallint AS currencycode, NULL::numeric(11,5) AS conversionrate, 0 AS advincometax, 0 AS fbrposfee FROM dbo.product WHERE (productcode IN (SELECT code FROM tmp_lsl2 AS lsl2));
  TRUNCATE TABLE tmp_lsl RESTART IDENTITY;
  TRUNCATE TABLE tmp_lsl2 RESTART IDENTITY;
  return_value := 0;
  RETURN;
END
$body$;

