-- ==== proc SP_VirtualGL_SaleOrder ====
CREATE OR REPLACE FUNCTION dbo.sp_virtualgl_saleorder(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ln_purchaseacc numeric(5,0);
  v_ln_cashacc numeric(5,0);
  v_ln_equityacc numeric(5,0);
  v_ln_salesacc numeric(5,0);
  v_ln_salesretacc numeric(5,0);
  v_ln_purchaseretacc numeric(5,0);
  v_ln_revfromservice numeric(5,0);
  v_ln_salestaxacc numeric(5,0);
BEGIN
  -- SET NOCOUNT ON
  v_ln_cashacc := (SELECT code FROM dbo.global WHERE (name = 'GT_CashACC'));
  v_ln_salesacc := (SELECT code FROM dbo.global WHERE (name = 'GT_SalesACC'));
  v_ln_salesretacc := (SELECT code FROM dbo.global WHERE (name = 'GT_SalesReturnACC'));
  v_ln_revfromservice := (SELECT code FROM dbo.global WHERE (name = 'GT_RevenueFromServices'));
  v_ln_salestaxacc := (SELECT code FROM dbo.global WHERE (name = 'GT_AdvanceSalesTaxACC'));
  DROP TABLE IF EXISTS tmp_lt_saleorder;
  CREATE TEMP TABLE tmp_lt_saleorder (
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_saleorder SELECT saleordercode FROM dbo.saleorderheader WHERE ((posted = 'Y') AND (NOT EXISTS (SELECT DISTINCT v.documentcode FROM dbo.virtualgl AS v WHERE ((v.documenttype IN ('SO')) AND (v.documentcode = saleorderheader.saleordercode)))));
  INSERT INTO dbo.virtualgltemp SELECT s.saleordercode AS documentcode, 'SO' AS documenttype, 1 AS catcode, s.paymentacccode AS dr_acccode, s.custcode AS cr_acccode, NULL::smallint AS alternateacccode, s.amtdate AS date, 0 AS saletax, s.amt AS gross, ('Advance received on sale order #: ' || rtrim(ltrim((s.saleordercode)::text))) AS dr_remarks, ('Advance received on sale order #: ' || rtrim(ltrim((s.saleordercode)::text))) AS cr_remarks, NULL::citext AS saletax_remarks, s.amtreference AS checkno, s.amtby AS usercode, s.saleordercode AS vouchercode, s.saleordercode AS invoicecode, NULL::smallint AS invoicetype, 0 AS amt, NULL::integer AS dramtacccode, NULL::integer AS cramtacccode, NULL::smallint AS amtby, NULL::timestamp(3) AS amtdate, NULL::citext AS amtref, 0 AS outstandingamt, 0 AS balance, s.patientcode AS patientcode, NULL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto, NULL::integer AS guestcode, NULL::integer AS studentcode, 0 AS cgs, NULL::smallint AS currencycode, NULL::numeric(11,5) AS conversionrate, 0.00 AS advincometax, 0.00 AS fbrposfee FROM dbo.saleorderheader AS s WHERE (((s.saleordercode IN (SELECT code FROM tmp_lt_saleorder AS lt_saleorder)) AND (s.amt > 0)) AND (s.amtdate IS NOT NULL));
  TRUNCATE TABLE tmp_lt_saleorder RESTART IDENTITY;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_VirtualGL_Sales ====
CREATE OR REPLACE FUNCTION dbo.sp_virtualgl_sales(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
