  INSERT INTO dbo.virtualgltemp SELECT s.saleinvcode AS documentcode, 'SV' AS documenttype, s.salecatcode AS catcode, CASE s.salecatcode WHEN 1 THEN s.cashacccode WHEN 3 THEN s.cashacccode ELSE s.custcode END AS dr_acccode, trunc(v_ln_salesacc)::smallint AS cr_acccode, CASE s.salecatcode WHEN 1 THEN s.custcode WHEN 3 THEN s.custcode ELSE NULL END AS alternateacccode, s.date AS date, CASE s.updateavgpricewithnetrate WHEN 'N' THEN round((((sum((((d.looseqty + d.bonusqty)) * d.unitsalestax)) + sum(round(((((((d.looseqty * ((d.saleprice - d.itemflatdisc)))) * ((1 - ((.01 * d.discperc))))) * d.gstperc) * .01))::numeric, 2))) + round((((((sum((((d.looseqty * ((d.saleprice - d.itemflatdisc)))) * ((1 - ((.01 * d.discperc)))))) * ((1 - ((.01 * s.discperc))))) - s.flatdisc)) * ((s.invgstperc1 * .01))))::numeric, 2)))::numeric, v_roundupyo) ELSE 0.00 END AS saletax, CASE s.updateavgpricewithnetrate WHEN 'N' THEN round((((((sum((((d.looseqty * ((d.saleprice - d.itemflatdisc)))) * ((1 - ((.01 * d.discperc)))))) * ((1 - ((.01 * s.discperc))))) + s.misccharges) + s.salestax) - s.flatdisc))::numeric, v_roundupyo) ELSE (round((((((sum((((d.looseqty * ((d.saleprice - d.itemflatdisc)))) * ((1 - ((.01 * d.discperc)))))) * ((1 - ((.01 * s.discperc))))) + s.misccharges) + s.salestax) - s.flatdisc))::numeric, v_roundupyo) + round((((sum((((d.looseqty + d.bonusqty)) * d.unitsalestax)) + sum(round(((((((d.looseqty * ((d.saleprice - d.itemflatdisc)))) * ((1 - ((.01 * d.discperc))))) * d.gstperc) * .01))::numeric, 2))) + round((((((sum((((d.looseqty * ((d.saleprice - d.itemflatdisc)))) * ((1 - ((.01 * d.discperc)))))) * ((1 - ((.01 * s.discperc))))) - s.flatdisc)) * ((s.invgstperc1 * .01))))::numeric, 2)))::numeric, v_roundupyo)) END AS gross, CASE v_sremks WHEN 'Y' THEN s.remarks ELSE (CASE s.salecatcode WHEN 3 THEN 'Cash receipt on sale #: ' WHEN 1 THEN 'Cash receipt on sale #: ' ELSE 'Receivable on cr. sale #: ' END || rtrim(ltrim((s.saleinvcode)::text))) END AS dr_remarks, ((('Revenue from ' || CASE s.salecatcode WHEN 3 THEN 'cash' WHEN 1 THEN 'cash' ELSE 'cr.' END) || ' sale #: ') || rtrim(ltrim((s.saleinvcode)::text))) AS cr_remarks, ((((('S.Tax ' || CASE s.salecatcode WHEN 3 THEN 'received' WHEN 1 THEN 'received' ELSE 'receivable' END) || ' on ') || CASE s.salecatcode WHEN 3 THEN 'cash' WHEN 1 THEN 'cash' ELSE 'cr.' END) || ' sale #: ') || rtrim(ltrim((s.saleinvcode)::text))) AS saletax_remarks, NULL::citext AS checkno, s.salesmancode AS usercode, s.saleinvcode AS vouchercode, s.saleinvcode AS invoicecode, 1 AS invoicetype, CASE s.salecatcode WHEN 2 THEN s.amt ELSE 0 END AS amt, s.paymentacccode AS dramtacccode, s.custcode AS cramtacccode, s.amtby AS amtby, s.amtdate AS amtdate, s.amtreference AS amtref, s.outstandingamt AS outstandingamt, 0 AS balance, CASE WHEN (s.patientcode IS NULL) THEN CASE WHEN (s.admissioncode IS NULL) THEN NULL ELSE (SELECT a.patientcode FROM dbo.patientadmission AS a WHERE (s.admissioncode = a.admissioncode)) END ELSE s.patientcode END AS patientcode, s.grn AS grn, s.gccode AS gccode, s.vehicle AS vehicle, s.shipto AS shipto, s.guestcode, s.studentcode, coalesce(sum((((d.looseqty + d.bonusqty)) * d.avgprice)), 0) AS cgs, s.currencycode, s.conversionrate, CASE WHEN (v_advincometax = 'Y') THEN coalesce(s.advancetaxamt, 0) ELSE 0 END AS advincometax, s.fbrposfee FROM dbo.saleledger AS s, dbo.saledetail AS d WHERE ((s.saleinvcode IN (SELECT code FROM tmp_lsl AS lsl)) AND (s.saleinvcode = d.saleinvcode)) GROUP BY s.saleinvcode, s.custcode, s.salecatcode, s.date, s.discperc, s.misccharges, s.salestax, s.flatdisc, s.invgstperc1, s.salesmancode, s.amt, s.paymentacccode, s.amtby, s.amtdate, s.amtreference, s.outstandingamt, s.patientcode, s.admissioncode, s.remarks, s.grn, s.gccode, s.vehicle, s.shipto, s.cashacccode, s.guestcode, s.studentcode, s.updateavgpricewithnetrate, s.currencycode, s.conversionrate, s.advancetaxamt, s.fbrposfee;
  INSERT INTO dbo.virtualgltemp SELECT s.saleinvcode AS documentcode, 'SV' AS documenttype, s.salecatcode AS catcode, CASE s.salecatcode WHEN 1 THEN s.cashacccode WHEN 3 THEN s.cashacccode ELSE s.custcode END AS dr_acccode, trunc(v_ln_salesacc)::smallint AS cr_acccode, CASE s.salecatcode WHEN 1 THEN s.custcode WHEN 3 THEN s.custcode ELSE NULL END AS alternateacccode, s.date AS date, CASE s.updateavgpricewithnetrate WHEN 'N' THEN round((((sum((((d.looseqty + d.bonusqty)) * d.unitsalestax)) + sum(round(((((((d.looseqty * ((d.saleprice - d.itemflatdisc)))) * ((1 - ((.01 * d.discperc))))) * d.gstperc) * .01))::numeric, 2))) + round((((((sum((((d.looseqty * ((d.saleprice - d.itemflatdisc)))) * ((1 - ((.01 * d.discperc)))))) * ((1 - ((.01 * s.discperc))))) - s.flatdisc)) * ((s.invgstperc1 * .01))))::numeric, 2)))::numeric, v_roundupyo) ELSE 0.00 END AS saletax, CASE s.updateavgpricewithnetrate WHEN 'N' THEN round((((((sum((((d.looseqty * ((d.saleprice - d.itemflatdisc)))) * ((1 - ((.01 * d.discperc)))))) * ((1 - ((.01 * s.discperc))))) + s.misccharges) + s.salestax) - s.flatdisc))::numeric, v_roundupyo) ELSE (round((((((sum((((d.looseqty * ((d.saleprice - d.itemflatdisc)))) * ((1 - ((.01 * d.discperc)))))) * ((1 - ((.01 * s.discperc))))) + s.misccharges) + s.salestax) - s.flatdisc))::numeric, v_roundupyo) + round((((sum((((d.looseqty + d.bonusqty)) * d.unitsalestax)) + sum(round(((((((d.looseqty * ((d.saleprice - d.itemflatdisc)))) * ((1 - ((.01 * d.discperc))))) * d.gstperc) * .01))::numeric, 2))) + round((((((sum((((d.looseqty * ((d.saleprice - d.itemflatdisc)))) * ((1 - ((.01 * d.discperc)))))) * ((1 - ((.01 * s.discperc))))) - s.flatdisc)) * ((s.invgstperc1 * .01))))::numeric, 2)))::numeric, v_roundupyo)) END AS gross, CASE v_sremks WHEN 'Y' THEN s.remarks ELSE (CASE s.salecatcode WHEN 3 THEN 'Cash receipt on sale #: ' WHEN 1 THEN 'Cash receipt on sale #: ' ELSE 'Receivable on cr. sale #: ' END || rtrim(ltrim((s.saleinvcode)::text))) END AS dr_remarks, ((('Revenue from ' || CASE s.salecatcode WHEN 3 THEN 'cash' WHEN 1 THEN 'cash' ELSE 'cr.' END) || ' sale #: ') || rtrim(ltrim((s.saleinvcode)::text))) AS cr_remarks, ((((('S.Tax ' || CASE s.salecatcode WHEN 3 THEN 'received' WHEN 1 THEN 'received' ELSE 'receivable' END) || ' on ') || CASE s.salecatcode WHEN 3 THEN 'cash' WHEN 1 THEN 'cash' ELSE 'cr.' END) || ' sale #: ') || rtrim(ltrim((s.saleinvcode)::text))) AS saletax_remarks, NULL::citext AS checkno, s.salesmancode AS usercode, s.saleinvcode AS vouchercode, s.saleinvcode AS invoicecode, 1 AS invoicetype, CASE s.salecatcode WHEN 2 THEN s.amt ELSE 0 END AS amt, s.paymentacccode AS dramtacccode, s.custcode AS cramtacccode, s.amtby AS amtby, s.amtdate AS amtdate, s.amtreference AS amtref, s.outstandingamt AS outstandingamt, 0 AS balance, CASE WHEN (s.patientcode IS NULL) THEN CASE WHEN (s.admissioncode IS NULL) THEN NULL ELSE (SELECT a.patientcode FROM dbo.patientadmission AS a WHERE (s.admissioncode = a.admissioncode)) END ELSE s.patientcode END AS patientcode, s.grn AS grn, s.gccode AS gccode, s.vehicle AS vehicle, s.shipto AS shipto, s.guestcode, s.studentcode, 0 AS cgs, s.currencycode, s.conversionrate, CASE WHEN (v_advincometax = 'Y') THEN coalesce(s.advancetaxamt, 0) ELSE 0 END AS advincometax, s.fbrposfee FROM dbo.saleledger AS s, dbo.saleinvdetail AS d WHERE ((s.saleinvcode IN (SELECT code FROM tmp_lsl AS lsl)) AND (s.saleinvcode = d.saleinvcode)) GROUP BY s.saleinvcode, s.custcode, s.salecatcode, s.date, s.discperc, s.misccharges, s.salestax, s.flatdisc, s.invgstperc1, s.salesmancode, s.amt, s.paymentacccode, s.amtby, s.amtdate, s.amtreference, s.outstandingamt, s.patientcode, s.admissioncode, s.remarks, s.grn, s.gccode, s.vehicle, s.shipto, s.cashacccode, s.guestcode, s.studentcode, s.updateavgpricewithnetrate, s.currencycode, s.conversionrate, s.advancetaxamt, s.fbrposfee;
  INSERT INTO dbo.virtualgltemp SELECT s.saleinvcode AS documentcode, 'SV' AS documenttype, s.salecatcode AS catcode, CASE WHEN (d.debit > 0) THEN acccode ELSE s.custcode END AS dr_acccode, CASE WHEN (d.debit > 0) THEN s.custcode ELSE acccode END AS cr_acccode, NULL::smallint AS alternateacccode, s.date AS date, 0 AS saletax, CASE WHEN (d.debit > 0) THEN d.debit ELSE d.credit END AS gross, d.remarks AS dr_remarks, d.remarks AS cr_remarks, '' AS saletax_remarks, d.checkno AS checkno, s.salesmancode AS usercode, s.saleinvcode AS vouchercode, s.saleinvcode AS invoicecode, 1 AS invoicetype, 0 AS amt, NULL::integer AS dramtacccode, NULL::integer AS cramtacccode, NULL::smallint AS amtby, NULL::timestamp(3) AS amtdate, NULL::citext AS amtref, s.outstandingamt AS outstandingamt, 0 AS balance, CASE WHEN (s.patientcode IS NULL) THEN CASE WHEN (s.admissioncode IS NULL) THEN NULL ELSE (SELECT a.patientcode FROM dbo.patientadmission AS a WHERE (s.admissioncode = a.admissioncode)) END ELSE s.patientcode END AS patientcode, s.grn AS grn, s.gccode AS gccode, s.vehicle AS vehicle, s.shipto AS shipto, s.guestcode, s.studentcode, 0 AS cgs, s.currencycode, s.conversionrate, 0.00 AS advincometax, 0.00 AS fbrposfee FROM dbo.saleledger AS s, dbo.salereceivableadj AS d WHERE ((s.saleinvcode IN (SELECT code FROM tmp_lsl AS lsl)) AND (s.saleinvcode = d.saleinvcode));
  INSERT INTO dbo.virtualgltemp SELECT s.saleinvcode AS documentcode, 'SV' AS documenttype, s.salecatcode AS catcode, s.cashacccode AS dr_acccode, s.custcode AS cr_acccode, NULL::smallint AS alternateacccode, s.date AS date, 0 AS saletax, s.cashcharged AS gross, ('Cash Received on Sale Inv. No.' || ltrim(rtrim(dbo.tsql_str((s.saleinvcode)::numeric, 10)))) AS dr_remarks, ('Cash Received on Sale Inv. No.' || ltrim(rtrim(dbo.tsql_str((s.saleinvcode)::numeric, 10)))) AS cr_remarks, '' AS saletax_remarks, NULL::citext AS checkno, s.salesmancode AS usercode, s.saleinvcode AS vouchercode, s.saleinvcode AS invoicecode, 1 AS invoicetype, 0 AS amt, NULL::integer AS dramtacccode, NULL::integer AS cramtacccode, NULL::smallint AS amtby, NULL::timestamp(3) AS amtdate, NULL::citext AS amtref, s.outstandingamt AS outstandingamt, 0 AS balance, CASE WHEN (s.patientcode IS NULL) THEN CASE WHEN (s.admissioncode IS NULL) THEN NULL ELSE (SELECT a.patientcode FROM dbo.patientadmission AS a WHERE (s.admissioncode = a.admissioncode)) END ELSE s.patientcode END AS patientcode, s.grn AS grn, s.gccode AS gccode, s.vehicle AS vehicle, s.shipto AS shipto, s.guestcode, s.studentcode, 0 AS cgs, s.currencycode, s.conversionrate, 0.00 AS advincometax, 0.00 AS fbrposfee FROM dbo.saleledger AS s WHERE (((s.salecatcode NOT IN (1, 3)) AND (s.cashcharged > 0)) AND (s.saleinvcode IN (SELECT code FROM tmp_lsl AS lsl))) UNION ALL SELECT s.saleinvcode AS documentcode, 'SV' AS documenttype, s.salecatcode AS catcode, d.acccode AS dr_acccode, s.custcode AS cr_acccode, NULL::smallint AS alternateacccode, s.date AS date, 0 AS saletax, amount AS gross, d.remarks AS dr_remarks, d.remarks AS cr_remarks, '' AS saletax_remarks, NULL::citext AS checkno, s.salesmancode AS usercode, s.saleinvcode AS vouchercode, s.saleinvcode AS invoicecode, 1 AS invoicetype, 0 AS amt, NULL::integer AS dramtacccode, NULL::integer AS cramtacccode, NULL::smallint AS amtby, NULL::timestamp(3) AS amtdate, NULL::citext AS amtref, s.outstandingamt AS outstandingamt, 0 AS balance, CASE WHEN (s.patientcode IS NULL) THEN CASE WHEN (s.admissioncode IS NULL) THEN NULL ELSE (SELECT a.patientcode FROM dbo.patientadmission AS a WHERE (s.admissioncode = a.admissioncode)) END ELSE s.patientcode END AS patientcode, s.grn AS grn, s.gccode AS gccode, s.vehicle AS vehicle, s.shipto AS shipto, s.guestcode, s.studentcode, 0 AS cgs, s.currencycode, s.conversionrate, 0.00 AS advincometax, 0.00 AS fbrposfee FROM dbo.saleledger AS s, dbo.cashierwindow AS d WHERE ((s.saleinvcode IN (SELECT code FROM tmp_lsl AS lsl)) AND (s.saleinvcode = d.saleinvcode));
  TRUNCATE TABLE tmp_lsl RESTART IDENTITY;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_VirtualGL_SalesReturn ====
CREATE OR REPLACE FUNCTION dbo.sp_virtualgl_salesreturn(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ln_purchaseacc numeric(5,0);
  v_ln_cashacc numeric(5,0);
  v_ln_equityacc numeric(5,0);
  v_ln_invacc numeric(5,0);
  v_ln_cgs numeric(5,0);
  v_ln_salesacc numeric(5,0);
  v_ln_salesretacc numeric(5,0);
  v_ln_purchaseretacc numeric(5,0);
  v_ln_revfromservice numeric(5,0);
  v_ln_salestaxacc numeric(5,0);
  v_srremks citext;
  v_invsys citext;
  v_roundupyo smallint;
BEGIN
  -- SET NOCOUNT ON
  v_roundupyo := (SELECT dbo.fn_get_int_preference('roundsalereturninvon') AS a);
  v_invsys := coalesce((SELECT dbo.fn_getpreference('InventorySystemUsed') AS a), 'P');
  v_ln_invacc := (SELECT code FROM dbo.global WHERE (name = 'GT_InventoryAcc'));
  v_ln_cgs := (SELECT code FROM dbo.global WHERE (name = 'GT_CostOfGoodsSoldAcc'));
  v_ln_cashacc := (SELECT code FROM dbo.global WHERE (name = 'GT_CashACC'));
  v_ln_salesacc := (SELECT code FROM dbo.global WHERE (name = 'GT_SalesACC'));
  v_ln_salesretacc := (SELECT code FROM dbo.global WHERE (name = 'GT_SalesReturnACC'));
  v_ln_salestaxacc := (SELECT code FROM dbo.global WHERE (name = 'GT_AdvanceSalesTaxACC'));
  v_srremks := (SELECT dbo.fn_getpreference('ShowSRetRemarksInLedger') AS a);
  DROP TABLE IF EXISTS tmp_lt_sret;
  CREATE TEMP TABLE tmp_lt_sret (
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_sret SELECT srinvcode FROM dbo.srledger AS s WHERE (((s.posted = 'Y') AND (s.accountfor = 'Y')) AND (NOT EXISTS (SELECT DISTINCT v.documentcode FROM dbo.virtualgl AS v WHERE ((v.documenttype = 'SR') AND (v.documentcode = s.srinvcode)))));
  INSERT INTO dbo.virtualgltemp SELECT s.srinvcode AS documentcode, 'SR' AS documenttype, s.srcatcode AS catcode, trunc(v_ln_salesretacc)::smallint AS dr_acccode, CASE s.srcatcode WHEN 6 THEN s.cashacccode WHEN 8 THEN s.cashacccode ELSE s.custcode END AS cr_acccode, CASE s.srcatcode WHEN 6 THEN s.custcode WHEN 8 THEN s.custcode ELSE NULL END AS alternateacccode, s.date AS date, CASE s.updateavgpricewithnetrate WHEN 'N' THEN round((((sum((((d.looseqty + d.bonusqty)) * d.unitsalestax)) + sum(round(((((((d.looseqty * d.srprice)) * ((1 - ((.01 * d.discperc))))) * d.gstperc) * .01))::numeric, 2))) + round((((((sum((((d.looseqty * d.srprice)) * ((1 - ((.01 * d.discperc)))))) * ((1 - ((.01 * s.discperc))))) - s.flatdisc)) * ((s.invgstperc1 * .01))))::numeric, 2)))::numeric, v_roundupyo) ELSE 0.00 END AS saletax, CASE s.updateavgpricewithnetrate WHEN 'N' THEN round((((((sum((((d.looseqty * d.srprice)) * ((1 - ((.01 * d.discperc)))))) * ((1 - ((.01 * s.discperc))))) + s.misccharges) + s.salestax) - s.flatdisc))::numeric, v_roundupyo) ELSE (round((((((sum((((d.looseqty * d.srprice)) * ((1 - ((.01 * d.discperc)))))) * ((1 - ((.01 * s.discperc))))) + s.misccharges) + s.salestax) - s.flatdisc))::numeric, v_roundupyo) + round((((sum((((d.looseqty + d.bonusqty)) * d.unitsalestax)) + sum(round(((((((d.looseqty * d.srprice)) * ((1 - ((.01 * d.discperc))))) * d.gstperc) * .01))::numeric, 2))) + round((((((sum((((d.looseqty * d.srprice)) * ((1 - ((.01 * d.discperc)))))) * ((1 - ((.01 * s.discperc))))) - s.flatdisc)) * ((s.invgstperc1 * .01))))::numeric, 2)))::numeric, v_roundupyo)) END AS gross, (((('Revenue (reversal) on ' || CASE s.srcatcode WHEN 6 THEN 'cash' WHEN 8 THEN 'cash' ELSE 'cr.' END) || ' sale ret. #: ') || rtrim(ltrim((s.srinvcode)::text))) || CASE WHEN (s.saleinvcode IS NULL) THEN '' ELSE (', Sale #:' || rtrim(ltrim((s.saleinvcode)::text))) END) AS dr_remarks, CASE v_srremks WHEN 'Y' THEN s.remarks ELSE ((CASE s.srcatcode WHEN 6 THEN 'Cash paid on sale ret.#: ' WHEN 8 THEN 'Cash paid on sale ret.#: ' ELSE 'Payable on cr. sale ret.#: ' END || rtrim(ltrim((s.srinvcode)::text))) || CASE WHEN (s.saleinvcode IS NULL) THEN '' ELSE (', Sale #:' || rtrim(ltrim((s.saleinvcode)::text))) END) END AS cr_remarks, (((('S.Tax ' || CASE s.srcatcode WHEN 6 THEN 'Paid' WHEN 8 THEN 'Paid' ELSE 'Payable' END) || ' on sale ret. #: ') || rtrim(ltrim((s.srinvcode)::text))) || CASE WHEN (s.saleinvcode IS NULL) THEN '' ELSE (', sale #:' || rtrim(ltrim((s.saleinvcode)::text))) END) AS saletax_remarks, NULL::citext AS checkno, coalesce(s.salesmancode, 0) AS usercode, s.srinvcode AS vouchercode, s.srinvcode AS invoicecode, 3 AS invoicetype, CASE s.srcatcode WHEN 8 THEN 0 ELSE s.amt END AS amt, s.custcode AS dramtacccode, s.paymentacccode AS cramtacccode, s.amtby AS amtby, s.amtdate AS amtdate, s.amtreference AS amtref, s.outstandingamt AS outstandingamt, 0 AS balance, CASE WHEN (s.patientcode IS NULL) THEN CASE WHEN (s.admissioncode IS NULL) THEN NULL ELSE (SELECT a.patientcode FROM dbo.patientadmission AS a WHERE (s.admissioncode = a.admissioncode)) END ELSE s.patientcode END AS patientcode, NULL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto, s.guestcode, s.studentcode, coalesce(sum((((d.looseqty + d.bonusqty)) * CASE WHEN (s.saleinvcode > 0) THEN d.avgprice ELSE (((d.srprice * ((1 - (d.discperc * 0.01)))) * ((1 - (s.discperc * 0.01))))) END)), 0) AS cgs, s.currencycode, s.conversionrate, coalesce(s.advancetaxamt, 0) AS advincometax, coalesce(s.fbrposfee, 0) AS fbrposfee FROM dbo.srledger AS s, dbo.srdetail AS d WHERE ((s.srinvcode IN (SELECT code FROM tmp_lt_sret AS lt_sret)) AND (s.srinvcode = d.srinvcode)) GROUP BY s.srinvcode, s.custcode, s.srcatcode, s.cashacccode, s.date, s.discperc, s.misccharges, s.salestax, s.flatdisc, s.invgstperc1, s.salesmancode, s.saleinvcode, s.amt, s.paymentacccode, s.amtby, s.amtdate, s.amtreference, s.outstandingamt, s.patientcode, s.admissioncode, s.cashacccode, s.remarks, s.guestcode, s.studentcode, s.updateavgpricewithnetrate, s.currencycode, s.conversionrate, s.advancetaxamt, s.fbrposfee;
  INSERT INTO dbo.virtualgltemp SELECT s.srinvcode AS documentcode, 'SR' AS documenttype, s.srcatcode AS catcode, s.custcode AS dr_acccode, s.cashacccode AS cr_acccode, NULL::smallint AS alternateacccode, s.date AS date, 0 AS saletax, s.cashcharged AS gross, ('Cash Paid on S/R No.' || ltrim(rtrim(dbo.tsql_str((s.srinvcode)::numeric, 10)))) AS dr_remarks, ('Cash Paid on S/R No.' || ltrim(rtrim(dbo.tsql_str((s.srinvcode)::numeric, 10)))) AS cr_remarks, '' AS saletax_remarks, NULL::citext AS checkno, s.salesmancode AS usercode, s.srinvcode AS vouchercode, s.srinvcode AS invoicecode, 3 AS invoicetype, 0 AS amt, NULL::integer AS dramtacccode, NULL::integer AS cramtacccode, NULL::smallint AS amtby, NULL::timestamp(3) AS amtdate, NULL::citext AS amtref, s.outstandingamt AS outstandingamt, 0 AS balance, CASE WHEN (s.patientcode IS NULL) THEN CASE WHEN (s.admissioncode IS NULL) THEN NULL ELSE (SELECT a.patientcode FROM dbo.patientadmission AS a WHERE (s.admissioncode = a.admissioncode)) END ELSE s.patientcode END AS patientcode, NULL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto, s.guestcode, s.studentcode, 0 AS cgs, s.currencycode, s.conversionrate, 0.00 AS advincometax, 0.00 AS fbrposfee FROM dbo.srledger AS s WHERE (((s.srcatcode NOT IN (6, 8)) AND (s.cashcharged > 0)) AND (s.srinvcode IN (SELECT code FROM tmp_lt_sret AS lt_sret))) UNION ALL SELECT s.srinvcode AS documentcode, 'SR' AS documenttype, s.srcatcode AS catcode, s.custcode AS dr_acccode, d.acccode AS cr_acccode, NULL::smallint AS alternateacccode, s.date AS date, 0 AS saletax, amount AS gross, d.remarks AS dr_remarks, d.remarks AS cr_remarks, '' AS saletax_remarks, NULL::citext AS checkno, s.salesmancode AS usercode, s.srinvcode AS vouchercode, s.srinvcode AS invoicecode, 3 AS invoicetype, 0 AS amt, NULL::integer AS dramtacccode, NULL::integer AS cramtacccode, NULL::smallint AS amtby, NULL::timestamp(3) AS amtdate, NULL::citext AS amtref, s.outstandingamt AS outstandingamt, 0 AS balance, CASE WHEN (s.patientcode IS NULL) THEN CASE WHEN (s.admissioncode IS NULL) THEN NULL ELSE (SELECT a.patientcode FROM dbo.patientadmission AS a WHERE (s.admissioncode = a.admissioncode)) END ELSE s.patientcode END AS patientcode, NULL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto, s.guestcode, s.studentcode, 0 AS cgs, s.currencycode, s.conversionrate, 0.00 AS advincometax, 0.00 AS fbrposfee FROM dbo.srledger AS s, dbo.mastercashwin AS d WHERE (((s.srinvcode IN (SELECT code FROM tmp_lt_sret AS lt_sret)) AND (s.srinvcode = d.documentcode)) AND (d.documenttype = 'SR'));
  TRUNCATE TABLE tmp_lt_sret RESTART IDENTITY;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_VirtualGL_Services ====
CREATE OR REPLACE FUNCTION dbo.sp_virtualgl_services(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_revfromservice integer;
  v_svcremks citext;
  v_svcrremks citext;
BEGIN
  -- SET NOCOUNT ON
  v_revfromservice := trunc((SELECT code FROM dbo.global WHERE (name = 'GT_RevenueFromServices')))::integer;
  v_svcremks := (SELECT dbo.fn_getpreference('ShowSvcRemarksInLedger') AS a);
  v_svcrremks := (SELECT dbo.fn_getpreference('ShowSvcRetRemarksInLedger') AS a);
  DROP TABLE IF EXISTS tmp_lt_service;
  CREATE TEMP TABLE tmp_lt_service (
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_service SELECT serviceinvcode FROM dbo.serviceheader AS s WHERE ((NOT EXISTS (SELECT DISTINCT v.documentcode FROM dbo.virtualgl AS v WHERE ((v.documenttype = 'RS') AND (v.documentcode = s.serviceinvcode)))) AND (s.posted = 'Y'));
  DROP TABLE IF EXISTS tmp_lt_serviceret;
  CREATE TEMP TABLE tmp_lt_serviceret (
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_serviceret SELECT servicerinvcode FROM dbo.servicerheader AS s WHERE ((NOT EXISTS (SELECT DISTINCT v.documentcode FROM dbo.virtualgl AS v WHERE ((v.documenttype = 'RR') AND (v.documentcode = s.servicerinvcode)))) AND (s.posted = 'Y'));
  INSERT INTO dbo.virtualgltemp SELECT h.serviceinvcode AS documentcode, 'RS' AS documenttype, h.servicecatcode AS catcode, h.custcode AS dr_acccode, v_revfromservice AS cr_acccode, CASE WHEN (h.servicecatcode = 10) THEN h.custcode WHEN (h.servicecatcode = 12) THEN h.custcode ELSE NULL END AS alternateacccode, h.date AS date, round((((coalesce(sum((((((d.qty * ((d.price - d.serviceflatdisc))) * ((1 - (d.discperc * 0.01))))) * 0.01) * d.servicegstperc)), 0) + coalesce(sum((d.qty * d.serviceflattax)), 0)) + coalesce(round((((((sum((((d.qty * ((d.price - d.serviceflatdisc))) * ((1 - (d.discperc * 0.01)))) * ((1 - (h.discperc * 0.01))))) - h.flatdisc)) * 0.01) * h.serviceinvgstperc))::numeric, 2), 0)))::numeric, 0) AS saletax, coalesce(round(((((sum((((d.qty * coalesce((d.price - d.serviceflatdisc), 0))) * ((1 - ((.01 * coalesce(d.discperc, 0))))))) * ((1 - ((.01 * coalesce(h.discperc, 0)))))) + coalesce(h.misccharges, 0)) - coalesce(h.flatdisc, 0)))::numeric, 0), 0) AS gross, CASE v_svcremks WHEN 'Y' THEN h.remarks ELSE ((CASE h.servicecatcode WHEN 10 THEN 'Sale of Service on Inv. #: ' WHEN 12 THEN 'Sale of Service on Inv. #: ' ELSE 'Receivable on cr. service #: ' END || rtrim(ltrim((h.serviceinvcode)::text))) || CASE WHEN (h.saleinvcode IS NULL) THEN '' ELSE (', sale #:' || rtrim(ltrim((h.saleinvcode)::text))) END) END AS dr_remarks, (CASE h.servicecatcode WHEN 10 THEN 'Revenue from cash service #: ' ELSE 'Revenue from credit service #: ' END || rtrim(ltrim((h.serviceinvcode)::text))) AS cr_remarks, ('Sales Tax Payable on Service Inv. #: ' || rtrim(ltrim((h.serviceinvcode)::text))) AS saletax_remarks, NULL::citext AS checkno, coalesce(h.salesmancode, 0) AS usercode, h.serviceinvcode AS vouchercode, h.serviceinvcode AS invoicecode, 5 AS invoicetype, 0 AS amt, NULL::integer AS dramtacccode, NULL::integer AS cramtacccode, NULL::smallint AS amtby, NULL::timestamp(3) AS amtdate, NULL::citext AS amtref, 0 AS outstandingamt, 0 AS balance, CASE WHEN (h.patientcode IS NULL) THEN CASE WHEN (h.admissioncode IS NULL) THEN NULL ELSE (SELECT a.patientcode FROM dbo.patientadmission AS a WHERE (h.admissioncode = a.admissioncode)) END ELSE h.patientcode END AS patientcode, NULL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto, h.guestcode AS guestcode, h.studentcode AS studentcode, 0 AS cgs, NULL::smallint AS currencycode, NULL::numeric(11,5) AS conversionrate, 0.00 AS advincometax, 0.00 AS fbrposfee FROM dbo.serviceheader AS h, dbo.servicedetail AS d WHERE ((h.serviceinvcode IN (SELECT code FROM tmp_lt_service AS lt_service)) AND (h.serviceinvcode = d.serviceinvcode)) GROUP BY h.serviceinvcode, h.custcode, h.servicecatcode, h.cashacccode, h.date, h.discperc, h.misccharges, h.flatdisc, h.serviceinvgstperc, h.salesmancode, h.saleinvcode, h.patientcode, h.admissioncode, h.remarks, h.guestcode, h.studentcode;
