saletax_remarks, NULL::citext AS checkno, th.usercode AS usercode, th.transactioncode AS vouchercode, th.transactioncode AS invoicecode, NULL::smallint AS invoicetype, 0 AS amt, NULL::integer AS dramtacccode, NULL::integer AS cramtacccode, NULL::smallint AS amtby, NULL::timestamp(3) AS amtdate, NULL::citext AS amtref, 0 AS outstandingamt, 0 AS balance, th.patientcode AS patientcode, NULL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto, NULL::integer AS guestcode, NULL::integer AS studentcode, 0 AS cgs, NULL::smallint AS currencycode, NULL::numeric(11,5) AS conversionrate, 0.00 AS advincometax, 0.00 AS fbrposfee FROM dbo.transactionheader AS th, dbo.transactiondetail AS td, dbo.transactiontype AS tt WHERE ((((((th.posted = 'Y') AND (th.documentcode IN (SELECT code FROM tmp_lt_transaction AS lt_transaction))) AND (th.transactiontypecode = tt.transactiontypecode)) AND (tt.transactioncatcode = 1)) AND (th.documentcode = td.documentcode)) AND (td.amount > 0)) UNION ALL SELECT th.documentcode AS documentcode, tt.shortname AS documenttype, th.transactiontypecode AS catcode, th.acccode AS dr_acccode, th.cashacccode AS cr_acccode, NULL::smallint AS alternateacccode, th.date AS date, 0 AS saletax, th.cashcharged AS gross, ('Cash Paid Against Transaction Doc. Code: ' || ltrim(rtrim(dbo.tsql_str((th.documentcode)::numeric, 10)))) AS dr_remarks, ('Cash Paid Against Transaction Doc. Code: ' || ltrim(rtrim(dbo.tsql_str((th.documentcode)::numeric, 10)))) AS cr_remarks, '' AS saletax_remarks, NULL::citext AS checkno, th.usercode AS usercode, th.transactioncode AS vouchercode, th.transactioncode AS invoicecode, NULL::smallint AS invoicetype, 0 AS amt, NULL::integer AS dramtacccode, NULL::integer AS cramtacccode, NULL::smallint AS amtby, NULL::timestamp(3) AS amtdate, NULL::citext AS amtref, 0 AS outstandingamt, 0 AS balance, th.patientcode AS patientcode, NULL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto, NULL::integer AS guestcode, NULL::integer AS studentcode, 0 AS cgs, NULL::smallint AS currencycode, NULL::numeric(11,5) AS conversionrate, 0.00 AS advincometax, 0.00 AS fbrposfee FROM dbo.transactionheader AS th, dbo.transactiontype AS tt WHERE (((((th.cashcharged > 0) AND (th.posted = 'Y')) AND (th.documentcode IN (SELECT code FROM tmp_lt_transaction AS lt_transaction))) AND (th.transactiontypecode = tt.transactiontypecode)) AND (tt.transactioncatcode = 2)) UNION ALL SELECT th.documentcode AS documentcode, tt.shortname AS documenttype, th.transactiontypecode AS catcode, th.acccode AS dr_acccode, td.acccode AS cr_acccode, NULL::smallint AS alternateacccode, th.date AS date, 0 AS saletax, td.amount AS gross, ('Amount Paid Against Transaction Doc. Code: ' || ltrim(rtrim(dbo.tsql_str((th.documentcode)::numeric, 10)))) AS dr_remarks, ('Amount Paid Against Transaction Doc. Code: ' || ltrim(rtrim(dbo.tsql_str((th.documentcode)::numeric, 10)))) AS cr_remarks, '' AS saletax_remarks, NULL::citext AS checkno, th.usercode AS usercode, th.transactioncode AS vouchercode, th.transactioncode AS invoicecode, NULL::smallint AS invoicetype, 0 AS amt, NULL::integer AS dramtacccode, NULL::integer AS cramtacccode, NULL::smallint AS amtby, NULL::timestamp(3) AS amtdate, NULL::citext AS amtref, 0 AS outstandingamt, 0 AS balance, th.patientcode AS patientcode, NULL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto, NULL::integer AS guestcode, NULL::integer AS studentcode, 0 AS cgs, NULL::smallint AS currencycode, NULL::numeric(11,5) AS conversionrate, 0.00 AS advincometax, 0.00 AS fbrposfee FROM dbo.transactionheader AS th, dbo.transactiondetail AS td, dbo.transactiontype AS tt WHERE ((((((th.posted = 'Y') AND (th.documentcode IN (SELECT code FROM tmp_lt_transaction AS lt_transaction))) AND (th.transactiontypecode = tt.transactiontypecode)) AND (tt.transactioncatcode = 2)) AND (th.documentcode = td.documentcode)) AND (td.amount > 0));
