-- ==== proc SP_VirtualGL_Vouchers ====
CREATE OR REPLACE FUNCTION dbo.sp_virtualgl_vouchers(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ln_purchaseacc numeric(5,0);
  v_ln_cashacc numeric(5,0);
  v_ln_equityacc numeric(5,0);
  v_ln_salesacc numeric(5,0);
  v_ln_salesretacc numeric(5,0);
  v_ln_purchaseretacc numeric(5,0);
  v_ln_revfromservice numeric(5,0);
  v_ln_salestaxacc numeric(5,0);
BEGIN
  -- SET NOCOUNT ON
  v_ln_purchaseacc := (SELECT code FROM dbo.global WHERE (name = 'GT_PurchaseAccount'));
  v_ln_cashacc := (SELECT code FROM dbo.global WHERE (name = 'GT_CashACC'));
  v_ln_equityacc := (SELECT code FROM dbo.global WHERE (name = 'GT_EquityACC'));
  v_ln_purchaseretacc := (SELECT code FROM dbo.global WHERE (name = 'GT_PurchaseReturnsAccount'));
  v_ln_salestaxacc := (SELECT code FROM dbo.global WHERE (name = 'GT_AdvanceSalesTaxACC'));
  DROP TABLE IF EXISTS tmp_lt_voucher;
  CREATE TEMP TABLE tmp_lt_voucher (
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tmp_lt_voucher SELECT glvochcode FROM dbo.glheader AS h WHERE ((NOT EXISTS (SELECT DISTINCT v.documentcode FROM dbo.virtualgl AS v, dbo.vochercategory AS vc WHERE ((v.documenttype = vc.shortname) AND (v.documentcode = h.glvochcode)))) AND (h.posted = 'Y'));
  INSERT INTO dbo.virtualgl (documentcode, documenttype, catcode, acccode, alternateacccode, date, debit, credit, remarks, checkno, usercode, vouchercode, invoicecode, invoicetype, outstandingamt, balance, vrow, patientcode, grn, gccode, vehicle, shipto, guestcode, studentcode, currencycode, conversionrate) SELECT h.glvochcode AS documentcode, vc.shortname AS documenttype, h.vochcatcode AS catcode, d.acccode AS acccode, NULL::smallint AS alternateacccode, h.date AS date, d.debit AS debit, d.credit AS credit, CASE WHEN (h.acccode = d.acccode) THEN h.remarks ELSE d.remarks END AS remarks, CASE WHEN (h.acccode = d.acccode) THEN h.chkno ELSE d.chkno END AS checkno, h.salesmancode AS usercode, h.vouchercode, d.invoicecode, vc.invoicetype, d.outstandingamt AS outstandingamt, d.balance AS balance, CASE d.debit WHEN 0 THEN 1 ELSE 0 END AS vrow, d.patientcode, NULL::citext AS grn, NULL::smallint AS gccode, NULL::citext AS vehicle, NULL::citext AS shipto, d.guestcode AS guestcode, d.studentcode AS studentcode, h.currencycode, h.conversionrate FROM dbo.glheader AS h, dbo.gldetail AS d, dbo.vochercategory AS vc WHERE (((h.glvochcode IN (SELECT code FROM tmp_lt_voucher AS lt_voucher)) AND (h.glvochcode = d.glvochcode)) AND (h.vochcatcode = vc.vochcatcode));
  TRUNCATE TABLE tmp_lt_voucher RESTART IDENTITY;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_WaseelaMini_Droptable ====
CREATE OR REPLACE FUNCTION dbo.sp_waseelamini_droptable("table" citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_table citext;
  v_drop citext;
  v_qry citext;
  v_tablename citext;
  v_err integer;
  _dq1 text;
BEGIN
  v_table := "table";
  -- SET NOCOUNT ON
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  -- SET XACT_ABORT ON
  v_tablename := ('dbo.' || v_table);
  v_drop := ('DROP TABLE ' || v_tablename);
  v_qry := ((('if exists (select * from dbo.sysobjects where id = object_id(N''' || v_tablename) || ''') and OBJECTPROPERTY(id, N''IsUserTable'') = 1) ') || v_drop);
  _dq1 := v_qry;
  IF _dq1 IS NOT NULL THEN
    EXECUTE dbo.tsql_dyn(_dq1);
  END IF;
  v_err := 0;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Problem occurred while execution of drop Tables Procedure, Table Name = %', v_table;
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_WaseelaMini_Export ====
CREATE OR REPLACE FUNCTION dbo.sp_waseelamini_export(srv citext, db citext, owner citext, "table" citext, OUT return_value integer, OUT rs1 refcursor, OUT rs2 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_srv citext;
  v_db citext;
  v_owner citext;
  v_table citext;
  v_rt_code integer;
  v_err integer;
  v_continue integer;
  v_sql citext;
  v_from citext;
  v_qry citext;
  _dq1 text;
  _dq2 text;
BEGIN
  v_srv := srv;
  v_db := db;
  v_owner := owner;
  v_table := "table";
  -- SET ANSI_NULLS ON
  -- SET ANSI_WARNINGS ON
  -- SET XACT_ABORT ON
  v_qry := (((((((('EXECUTE ' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.SP_WaseelaMini_Truncate ''') || v_table) || '''');
  _dq1 := v_qry;
  IF _dq1 IS NOT NULL THEN
    IF _dq1 ~* '^[[:space:]]*select' THEN OPEN rs1 FOR EXECUTE dbo.tsql_dyn(_dq1); ELSE EXECUTE dbo.tsql_dyn(_dq1); END IF;
  END IF;
  IF ((0 <> 0) OR (v_rt_code <> 0)) THEN
    RAISE EXCEPTION 'Export Data Problem: Truncate Table Failed for % ', v_table;
    return_value := -1;
    RETURN;
  END IF;
  v_sql := (((((('INSERT INTO ' || ltrim(rtrim(v_srv))) || '.') || ltrim(rtrim(v_db))) || '.') || ltrim(rtrim(v_owner))) || '.');
  v_qry := (((v_sql || v_table) || ' SELECT * FROM DBO.View_WaseelaMini_') || v_table);
  _dq2 := v_qry;
  IF _dq2 IS NOT NULL THEN
    IF _dq2 ~* '^[[:space:]]*select' THEN OPEN rs2 FOR EXECUTE dbo.tsql_dyn(_dq2); ELSE EXECUTE dbo.tsql_dyn(_dq2); END IF;
  END IF;
  v_err := 0;
  IF ((0 <> 0) OR (v_err <> 0)) THEN
    RAISE EXCEPTION 'Export Data Problem: Error Transfering Data for % ', v_table;
    return_value := -1;
    RETURN;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
