-- ==== proc SP_WayToMoon ====
CREATE OR REPLACE FUNCTION dbo.sp_waytomoon(fl citext, fl2 citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_fl citext;
  v_fl2 citext;
  v_cmdline citext;
  v_rt_code integer;
  v_ver citext;
BEGIN
  v_fl := fl;
  v_fl2 := fl2;
  v_ver := version();
  IF (dbo.tsql_charindex(('X64')::citext, (v_ver)::citext, 1) > 0) THEN
    v_cmdline := ('dir %systemroot%\syswow64\' || ltrim(rtrim(v_fl)));
  ELSE
    v_cmdline := ('dir %systemroot%\system32\' || ltrim(rtrim(v_fl)));
  END IF;
  -- EXEC @rt_code = master..xp_cmdshell @cmdline, NO_OUTPUT
  RAISE EXCEPTION 'untranslated T-SQL (procedure outside the database: master.xp_cmdshell)' USING ERRCODE = '0A000';
  IF (v_rt_code >= 1) THEN
    return_value := 1;
    RETURN;
  ELSE
    IF (dbo.tsql_charindex(('X64')::citext, (v_ver)::citext, 1) > 0) THEN
      v_cmdline := ('dir %systemroot%\syswow64\' || ltrim(rtrim(v_fl2)));
    ELSE
      v_cmdline := ('dir %systemroot%\system32\' || ltrim(rtrim(v_fl2)));
    END IF;
    -- EXEC @rt_code = master..xp_cmdshell @cmdline, NO_OUTPUT
    RAISE EXCEPTION 'untranslated T-SQL (procedure outside the database: master.xp_cmdshell)' USING ERRCODE = '0A000';
    IF (v_rt_code >= 1) THEN
      return_value := 1;
      RETURN;
    END IF;
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc sp_yearly_sale_summary_monthwise_groping ====
CREATE OR REPLACE FUNCTION dbo.sp_yearly_sale_summary_monthwise_groping(dt_year timestamp, OUT return_value integer, OUT rs1 refcursor)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_dt_year timestamp(3);
BEGIN
  v_dt_year := dt_year;
  DROP TABLE IF EXISTS tmp_mytable1;
  CREATE TEMP TABLE tmp_mytable1 ON COMMIT DROP AS SELECT * FROM (SELECT sl.saleinvcode AS code, max(sl.date) AS date, (CASE max(salecatcode) WHEN 3 THEN 'CASH' ELSE 'CREDIT' END) AS transcategory, dbo.fn_getsaleinvtotal((sl.saleinvcode)::integer) AS invtotal, dbo.fn_getsaleinvtotal((sl.saleinvcode)::integer) AS sales, 0.00 AS returns, 'S' AS transtype FROM dbo.saleledger AS sl, dbo.saledetail AS sd WHERE (((sl.saleinvcode = sd.saleinvcode) AND (date >= (('01/01/' || (extract(year from v_dt_year)::integer)::text))::timestamp)) AND (date <= ((('12/31/' || (extract(year from v_dt_year)::integer)::text) || ' 23:59:59'))::timestamp)) GROUP BY sl.saleinvcode UNION ALL SELECT sl.srinvcode AS code, max(sl.date) AS date, (CASE max(srcatcode) WHEN 8 THEN 'CASH' ELSE 'CREDIT' END) AS transcategory, ((-1) * dbo.fn_getsrinvtotal((sl.srinvcode)::integer)) AS invtotal, 0.00 AS sales, dbo.fn_getsrinvtotal((sl.srinvcode)::integer) AS returns, 'SR' AS transtype FROM dbo.srledger AS sl, dbo.srdetail AS sd WHERE (((sl.srinvcode = sd.srinvcode) AND (date >= (('01/01/' || (extract(year from v_dt_year)::integer)::text))::timestamp)) AND (date <= ((('12/31/' || (extract(year from v_dt_year)::integer)::text) || ' 23:59:59'))::timestamp)) GROUP BY sl.srinvcode UNION ALL SELECT pl.purinvcode AS code, max(pl.date) AS date, 'Credit' AS transcategory, dbo.fn_getpurinvtotal((pl.purinvcode)::integer) AS invtotal, 0.00 AS sales, 0.00 AS returns, 'P' AS transtype FROM dbo.purledger AS pl, dbo.purdetail AS pd WHERE (((pl.purinvcode = pd.purinvcode) AND (date >= (('01/01/' || (extract(year from v_dt_year)::integer)::text))::timestamp)) AND (date <= ((('12/31/' || (extract(year from v_dt_year)::integer)::text) || ' 23:59:59'))::timestamp)) GROUP BY pl.purinvcode) AS a;
  OPEN rs1 FOR SELECT left(to_char(((((a.months)::text || '/01/') || (extract(year from v_dt_year)::integer)::text))::timestamp(3), 'Mon DD, YY'), 3) AS monthname, a.months, (SELECT count(DISTINCT (extract(day from date)::integer)) FROM tmp_mytable1 AS mytable1 WHERE ((transtype = 'S') AND (extract(month from date)::integer = a.months))) AS daysofwork, (SELECT count(code) FROM tmp_mytable1 AS mytable1 WHERE (((transtype = 'S') AND (transcategory = 'CASH')) AND (extract(month from date)::integer = a.months))) AS cashinvcount, (SELECT coalesce(sum(invtotal), 0) FROM tmp_mytable1 AS mytable1 WHERE (((transtype IN ('S', 'SR')) AND (transcategory = 'CASH')) AND (extract(month from date)::integer = a.months))) AS cashsaleinvtotal, (SELECT count(code) FROM tmp_mytable1 AS mytable1 WHERE (((transtype = 'S') AND (transcategory = 'CREDIT')) AND (extract(month from date)::integer = a.months))) AS creditinvcount, (SELECT coalesce(sum(invtotal), 0) FROM tmp_mytable1 AS mytable1 WHERE (((transtype IN ('S', 'SR')) AND (transcategory = 'CREDIT')) AND (extract(month from date)::integer = a.months))) AS creditsaleinvtotal, (SELECT count(code) FROM tmp_mytable1 AS mytable1 WHERE ((transtype = 'S') AND (extract(month from date)::integer = a.months))) AS totalsalecount, (SELECT coalesce(sum(invtotal), 0) FROM tmp_mytable1 AS mytable1 WHERE ((transtype IN ('S', 'SR')) AND (extract(month from date)::integer = a.months))) AS totalsaleamount, (SELECT coalesce(sum(invtotal), 0) FROM tmp_mytable1 AS mytable1 WHERE ((transtype IN ('SR')) AND (extract(month from date)::integer = a.months))) AS salereturns, (SELECT coalesce(sum(invtotal), 0) FROM tmp_mytable1 AS mytable1 WHERE ((transtype = 'P') AND (extract(month from date)::integer = a.months))) AS totalpuramount, ((SELECT coalesce(sum(invtotal), 0) FROM tmp_mytable1 AS mytable1 WHERE ((transtype IN ('S', 'SR')) AND (extract(month from date)::integer = a.months))) / (CASE WHEN ((SELECT count(DISTINCT (extract(day from date)::integer)) FROM tmp_mytable1 AS mytable1 WHERE ((transtype = 'S') AND (extract(month from date)::integer = a.months))) = 0) THEN 1 ELSE (SELECT count(DISTINCT (extract(day from date)::integer)) FROM tmp_mytable1 AS mytable1 WHERE ((transtype = 'S') AND (extract(month from date)::integer = a.months))) END)) AS perdayavg, (SELECT coalesce(sum(sales), 0) FROM tmp_mytable1 AS mytable1 WHERE (extract(month from date)::integer = a.months)) AS totalsales FROM (SELECT DISTINCT (extract(month from date)::integer) AS months FROM dbo.saleledger WHERE ((saleledger.date >= (('01/01/' || (extract(year from v_dt_year)::integer)::text))::timestamp) AND (saleledger.date <= ((('12/31/' || (extract(year from v_dt_year)::integer)::text) || ' 23:59:59'))::timestamp))) AS a;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_YEARLYSALESSUMMARY ====
CREATE OR REPLACE FUNCTION dbo.sp_yearlysalessummary(ar_startdate timestamp, ar_enddate timestamp, reportgrouping citext, grouplist citext, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ar_startdate timestamp(3);
  v_ar_enddate timestamp(3);
  v_reportgrouping citext;
  v_grouplist citext;
BEGIN
  v_ar_startdate := ar_startdate;
  v_ar_enddate := ar_enddate;
  v_reportgrouping := reportgrouping;
  v_grouplist := grouplist;
  DELETE FROM dbo.reportdata;
  DROP TABLE IF EXISTS tv_sp_yearlysalessummary_tab_grouplist;
  CREATE TEMP TABLE tv_sp_yearlysalessummary_tab_grouplist (
    code integer NOT NULL
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tv_sp_yearlysalessummary_tab_itemlist;
  CREATE TEMP TABLE tv_sp_yearlysalessummary_tab_itemlist (
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tv_sp_yearlysalessummary_tab_grouplist SELECT code FROM dbo.udf_stringtotabl(v_grouplist, ',') AS udf_stringtotabl;
  INSERT INTO tv_sp_yearlysalessummary_tab_itemlist SELECT code FROM dbo.udf_selectitems(v_reportgrouping, v_grouplist) AS udf_selectitems;
  INSERT INTO dbo.reportdata (code1, name1, code2, value1) SELECT t.year AS code1, t.groupname AS name1, t.groupcode AS code1, sum(t.value) AS value1 FROM (SELECT s.year AS year, CASE v_reportgrouping WHEN 'M' THEN i.manfcode WHEN 'C' THEN i.icatcode WHEN 'L' THEN i.iccode ELSE i.packcode END AS groupcode, CASE v_reportgrouping WHEN 'M' THEN (SELECT m.name FROM dbo.manufacturer AS m WHERE (m.manfcode = i.manfcode)) WHEN 'C' THEN (SELECT c.name FROM dbo.itemcategory AS c WHERE (c.icatcode = i.icatcode)) WHEN 'L' THEN (SELECT c.name FROM dbo.itemclass AS c WHERE (c.iccode = i.iccode)) ELSE (SELECT p.name FROM dbo.itempacking AS p WHERE (p.packcode = i.packcode)) END AS groupname, s.icode AS icode, sum(value) AS value FROM (SELECT sd.icode, extract(year from date)::integer AS year, sum((((((sd.looseqty + (sd.packqty * sd.packunits))) * sd.saleprice) * ((1 - (sd.discperc * 0.01)))) * ((1 - (sl.discperc * 0.01))))) AS value FROM dbo.saleledger AS sl, dbo.saledetail AS sd, tv_sp_yearlysalessummary_tab_itemlist AS i WHERE (((((sl.posted = 'Y') AND (sl.saleinvcode = sd.saleinvcode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) AND (sd.icode = i.code)) GROUP BY sd.icode, extract(year from date)::integer UNION ALL SELECT sd.icode, extract(year from date)::integer AS year, sum(((((sd.looseqty) * sd.saleprice) * ((1 - (sd.discperc * 0.01)))) * ((1 - (sl.discperc * 0.01))))) AS value FROM dbo.saleledger AS sl, dbo.saleinvdetail AS sd, tv_sp_yearlysalessummary_tab_itemlist AS i WHERE ((((((sl.impactinventory = 'N') AND (sl.posted = 'Y')) AND (sl.saleinvcode = sd.saleinvcode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) AND (sd.icode = i.code)) GROUP BY sd.icode, extract(year from date)::integer UNION ALL SELECT sd.icode, extract(year from date)::integer AS year, (-sum((((((sd.looseqty + (sd.packqty * sd.packunits))) * sd.srprice) * ((1 - (sd.discperc * 0.01)))) * ((1 - (sl.discperc * 0.01)))))) AS value FROM dbo.srledger AS sl, dbo.srdetail AS sd, tv_sp_yearlysalessummary_tab_itemlist AS i WHERE (((((sl.posted = 'Y') AND (sl.srinvcode = sd.srinvcode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) AND (sd.icode = i.code)) GROUP BY sd.icode, extract(year from date)::integer) AS s, (SELECT * FROM dbo.item WHERE (icode IN (SELECT code FROM tv_sp_yearlysalessummary_tab_itemlist AS tab_itemlist))) AS i WHERE (i.icode = s.icode) GROUP BY s.year, s.icode, i.icatcode, i.iccode, i.manfcode, i.packcode UNION ALL SELECT extract(year from v_ar_startdate)::integer AS year, k.code AS groupcode, CASE v_reportgrouping WHEN 'M' THEN (SELECT m.name FROM dbo.manufacturer AS m WHERE (m.manfcode = k.code)) WHEN 'C' THEN (SELECT c.name FROM dbo.itemcategory AS c WHERE (c.icatcode = k.code)) WHEN 'L' THEN (SELECT c.name FROM dbo.itemclass AS c WHERE (c.iccode = k.code)) ELSE (SELECT p.name FROM dbo.itempacking AS p WHERE (p.packcode = k.code)) END AS groupname, 0 AS icode, 0 AS value FROM (SELECT code FROM tv_sp_yearlysalessummary_tab_grouplist AS tab_grouplist) AS k) AS t GROUP BY t.year, t.groupname, t.groupcode;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_ZONALAREASALES ====
CREATE OR REPLACE FUNCTION dbo.sp_zonalareasales(ar_zonecode integer, ar_startdate timestamp, ar_enddate timestamp, reportgrouping citext, grouplist citext, pricetype smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_ar_zonecode integer;
  v_ar_startdate timestamp(3);
  v_ar_enddate timestamp(3);
  v_reportgrouping citext;
  v_grouplist citext;
  v_pricetype smallint;
BEGIN
  v_ar_zonecode := ar_zonecode;
  v_ar_startdate := ar_startdate;
  v_ar_enddate := ar_enddate;
  v_reportgrouping := reportgrouping;
  v_grouplist := grouplist;
  v_pricetype := pricetype;
  DELETE FROM dbo.reportdata;
  DROP TABLE IF EXISTS tv_sp_zonalareasales_tab_grouplist;
  CREATE TEMP TABLE tv_sp_zonalareasales_tab_grouplist (
    code integer NOT NULL
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tv_sp_zonalareasales_tab_itemlist;
  CREATE TEMP TABLE tv_sp_zonalareasales_tab_itemlist (
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tv_sp_zonalareasales_tab_grouplist SELECT code FROM dbo.udf_stringtotabl(v_grouplist, ',') AS udf_stringtotabl;
  INSERT INTO tv_sp_zonalareasales_tab_itemlist SELECT code FROM dbo.udf_selectitems(v_reportgrouping, v_grouplist) AS udf_selectitems;
  INSERT INTO dbo.reportdata (code1, code2, code3, code4, name1, name2, name3, name4, name5, name6, name7, name8, value1, value2) SELECT s.icode AS code1, s.areacode AS code2, s.zonecode AS code3, CASE v_reportgrouping WHEN 'M' THEN i.manfcode WHEN 'C' THEN i.icatcode WHEN 'L' THEN i.iccode ELSE i.packcode END AS code4, i.name AS name1, (SELECT area.shortname FROM dbo.area WHERE (areacode = s.areacode)) AS name2, (SELECT name FROM dbo.zone WHERE (zonecode = s.zonecode)) AS name3, CASE v_reportgrouping WHEN 'M' THEN (SELECT m.name FROM dbo.manufacturer AS m WHERE (m.manfcode = i.manfcode)) WHEN 'C' THEN (SELECT c.name FROM dbo.itemcategory AS c WHERE (c.icatcode = i.icatcode)) WHEN 'L' THEN (SELECT c.name FROM dbo.itemclass AS c WHERE (c.iccode = i.iccode)) ELSE (SELECT p.name FROM dbo.itempacking AS p WHERE (p.packcode = i.packcode)) END AS name4, i.customicode AS name5, i.packingdesc AS name6, (SELECT area.shortname FROM dbo.area WHERE (areacode = s.areacode)) AS name7, rtrim(ltrim(dbo.tsql_str((s.icode)::numeric))) AS name8, sum(s.qty) AS value1, round((sum(CASE v_pricetype WHEN 1 THEN s.netamt WHEN 2 THEN (s.qty * round(((i.saleprice / CASE i.packunits WHEN 0 THEN 1 ELSE i.packunits END))::numeric, 2)) WHEN 3 THEN (s.qty * round(((i.purprice / CASE i.packunits WHEN 0 THEN 1 ELSE i.packunits END))::numeric, 2)) ELSE (s.qty * round((i.avgprice)::numeric, 2)) END))::numeric, 0) AS value2 FROM (SELECT -1 AS invno, i.icode AS icode, -1 AS custcode, 0 AS qty, 0 AS netamt, a.areacode, a.zonecode FROM (SELECT areacode, zonecode FROM dbo.zoneareas WHERE (zonecode = v_ar_zonecode)) AS a, (SELECT min(code) AS icode FROM tv_sp_zonalareasales_tab_itemlist AS tab_itemlist) AS i UNION ALL SELECT -1 AS invno, i.icode AS icode, -1 AS custcode, 0 AS qty, 0 AS netamt, a.areacode, a.zonecode FROM (SELECT min(areacode) AS areacode, min(zonecode) AS zonecode FROM dbo.zoneareas WHERE (zonecode = v_ar_zonecode)) AS a, (SELECT code AS icode FROM tv_sp_zonalareasales_tab_itemlist AS tab_itemlist) AS i UNION ALL SELECT sl.saleinvcode AS invno, sd.icode, sl.custcode AS custcode, coalesce(sum((sd.looseqty + sd.bonusqty)), 0) AS qty, round((coalesce((sum((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc)))) * ((1 - ((.01 * sd.discperc)))))) * ((1 - ((.01 * sl.discperc))))), 0))::numeric, 2) AS netamt, c.areacode, a.zonecode FROM dbo.saleledger AS sl, dbo.saledetail AS sd, dbo.customer AS c, (SELECT areacode, zonecode FROM dbo.zoneareas WHERE (zonecode = v_ar_zonecode)) AS a WHERE ((((((a.areacode = c.areacode) AND (c.custcode = sl.custcode)) AND (sl.posted = 'Y')) AND (sl.saleinvcode = sd.saleinvcode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) GROUP BY sl.saleinvcode, sd.icode, sl.custcode, a.zonecode, c.areacode, sl.discperc UNION ALL SELECT sl.srinvcode AS invno, sd.icode, sl.custcode AS custcode, (-coalesce(sum((sd.looseqty + sd.bonusqty)), 0)) AS qty, (-round((coalesce((sum((((sd.looseqty * sd.srprice)) * ((1 - ((.01 * sd.discperc)))))) * ((1 - ((.01 * sl.discperc))))), 0))::numeric, 2)) AS netamt, c.areacode, a.zonecode FROM dbo.srledger AS sl, dbo.srdetail AS sd, dbo.customer AS c, (SELECT areacode, zonecode FROM dbo.zoneareas WHERE (zonecode = v_ar_zonecode)) AS a WHERE ((((((a.areacode = c.areacode) AND (c.custcode = sl.custcode)) AND (sl.posted = 'Y')) AND (sl.srinvcode = sd.srinvcode)) AND (sl.date >= v_ar_startdate)) AND (sl.date <= v_ar_enddate)) GROUP BY sl.srinvcode, sd.icode, sl.custcode, a.zonecode, c.areacode, sl.discperc) AS s, (SELECT * FROM dbo.item WHERE (icode IN (SELECT code FROM tv_sp_zonalareasales_tab_itemlist AS tab_itemlist))) AS i WHERE (i.icode = s.icode) GROUP BY s.icode, s.zonecode, s.areacode, i.name, i.customicode, i.packingdesc, i.icatcode, i.iccode, i.manfcode, i.packcode;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc SP_ZONALAREASALES_CROSSTAB ====
CREATE OR REPLACE FUNCTION dbo.sp_zonalareasales_crosstab(zonecode integer, startdate timestamp, enddate timestamp, reportgrouping citext, grouplist citext, pricetype smallint, totcol double precision, colcaption smallint, mergebonus smallint, OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
DECLARE
  v_zonecode integer;
  v_startdate timestamp(3);
  v_enddate timestamp(3);
  v_reportgrouping citext;
  v_grouplist citext;
  v_pricetype smallint;
  v_totcol double precision;
  v_colcaption smallint;
  v_mergebonus smallint;
  v_upd citext;
  v_col citext;
  v_rowid integer;
  v_colname citext;
  v_colcode citext;
  v_str_col citext;
  v_totareas double precision;
  v_curriter integer;
  v_iterations integer;
  v_i integer;
  v_tot integer;
  v_icode integer;
  v_areacode integer;
  v_qty numeric(15,4);
  v_bonus numeric(15,4);
  v_val numeric(15,5);
  v_err integer;
  _dq1 text;
  cur_c1 refcursor;
  _dq2 text;
  _fs integer := -1;
BEGIN
  v_zonecode := zonecode;
  v_startdate := startdate;
  v_enddate := enddate;
  v_reportgrouping := reportgrouping;
  v_grouplist := grouplist;
  v_pricetype := pricetype;
  v_totcol := totcol;
  v_colcaption := colcaption;
  v_mergebonus := mergebonus;
  DELETE FROM dbo.crosstab_reportdata;
  -- SET NOCOUNT ON
  DROP TABLE IF EXISTS tv_sp_zonalareasales_crosstab_coltable;
  CREATE TEMP TABLE tv_sp_zonalareasales_crosstab_coltable (
    code integer,
    shortname citext,
    rowid integer GENERATED BY DEFAULT AS IDENTITY
) ON COMMIT DROP;
  v_totareas := coalesce((SELECT count(area.areacode) FROM dbo.zoneareas AS z, dbo.area WHERE ((z.zonecode = v_zonecode) AND (z.areacode = area.areacode))), 0);
  DROP TABLE IF EXISTS tv_sp_zonalareasales_crosstab_tab_grouplist;
  CREATE TEMP TABLE tv_sp_zonalareasales_crosstab_tab_grouplist (
    code integer NOT NULL
) ON COMMIT DROP;
  DROP TABLE IF EXISTS tv_sp_zonalareasales_crosstab_tab_itemlist;
  CREATE TEMP TABLE tv_sp_zonalareasales_crosstab_tab_itemlist (
    code integer NOT NULL
) ON COMMIT DROP;
  INSERT INTO tv_sp_zonalareasales_crosstab_tab_grouplist SELECT code FROM dbo.udf_stringtotabl(v_grouplist, ',') AS udf_stringtotabl;
  INSERT INTO tv_sp_zonalareasales_crosstab_tab_itemlist SELECT code FROM dbo.udf_selectitems(v_reportgrouping, v_grouplist) AS udf_selectitems;
  IF ((v_totareas > 0) AND (v_totcol > 0)) THEN
    v_tot := trunc((SELECT min(a) FROM (SELECT v_totcol AS a UNION SELECT v_totareas AS a) AS t))::integer;
    INSERT INTO tv_sp_zonalareasales_crosstab_coltable (code, shortname) SELECT area.areacode, CASE WHEN (v_colcaption = 1) THEN area.shortname ELSE area.name END AS name FROM dbo.zoneareas AS z, dbo.area WHERE ((z.zonecode = v_zonecode) AND (z.areacode = area.areacode)) ORDER BY area.shortname;
    v_iterations := trunc(ceiling((v_totareas / v_totcol)))::integer;
    v_curriter := 1;
    v_rowid := 0;
    WHILE (v_curriter <= v_iterations) LOOP
      INSERT INTO dbo.crosstab_reportdata (code1, code2, code3) SELECT code, v_curriter, v_zonecode FROM tv_sp_zonalareasales_crosstab_tab_itemlist AS tab_itemlist;
      v_i := 1;
      WHILE (v_i <= v_tot) LOOP
        v_rowid := (v_rowid + 1);
        v_colname := rtrim(ltrim(coalesce((SELECT shortname FROM tv_sp_zonalareasales_crosstab_coltable AS coltable WHERE (rowid = v_rowid)), '')));
        v_colcode := rtrim(ltrim(dbo.tsql_str(((SELECT code FROM tv_sp_zonalareasales_crosstab_coltable AS coltable WHERE (rowid = v_rowid)))::numeric, 7)));
        IF (v_colcode IS NULL) THEN
          EXIT;
        ELSE
          v_str_col := ltrim(rtrim(dbo.tsql_str((v_i)::numeric, 7)));
          v_upd := ((((((((('UPDATE CrossTab_ReportData SET C_Name' || v_str_col) || ' = ''') || v_colname) || ''', C_Code') || v_str_col) || ' = ') || v_colcode) || ' WHERE CODE2 = ') || ltrim(rtrim(dbo.tsql_str((v_curriter)::numeric, 7))));
          _dq1 := v_upd;
          IF _dq1 IS NOT NULL THEN
            EXECUTE dbo.tsql_dyn(_dq1);
          END IF;
          v_err := 0;
          IF (v_err <> 0) THEN
            v_upd := ('UPDATION ERROR, DETAILS: ' || v_upd);
            RAISE EXCEPTION '%', v_upd;
            return_value := -1;
            RETURN;
          END IF;
          v_i := (v_i + 1);
        END IF;
      END LOOP;
      v_curriter := (v_curriter + 1);
    END LOOP;
    OPEN cur_c1 FOR SELECT s.icode, coalesce(sum(s.qty), 0) AS qty, coalesce(sum(s.bonus), 0) AS bonus, round((sum(CASE v_pricetype WHEN 1 THEN s.netamt WHEN 2 THEN (s.qty * round(((i.saleprice / CASE i.packunits WHEN 0 THEN 1 ELSE i.packunits END))::numeric, 2)) WHEN 3 THEN (s.qty * round(((i.purprice / CASE i.packunits WHEN 0 THEN 1 ELSE i.packunits END))::numeric, 2)) ELSE (s.qty * round((i.avgprice)::numeric, 2)) END))::numeric, 0) AS val, s.areacode FROM (SELECT sl.saleinvcode AS invno, sd.icode, sl.custcode AS custcode, coalesce(sum((sd.looseqty + CASE WHEN (v_mergebonus = 1) THEN sd.bonusqty ELSE 0 END)), 0) AS qty, coalesce(sum(CASE WHEN (v_mergebonus = 1) THEN 0 ELSE sd.bonusqty END), 0) AS bonus, round((coalesce((sum((((sd.looseqty * ((sd.saleprice - sd.itemflatdisc)))) * ((1 - ((.01 * sd.discperc)))))) * ((1 - ((.01 * sl.discperc))))), 0))::numeric, 2) AS netamt, c.areacode FROM dbo.saleledger AS sl, dbo.saledetail AS sd, dbo.customer AS c, (SELECT areacode, zonecode FROM dbo.zoneareas WHERE (zonecode = v_zonecode)) AS a WHERE ((((((a.areacode = c.areacode) AND (c.custcode = sl.custcode)) AND (sl.posted = 'Y')) AND (sl.saleinvcode = sd.saleinvcode)) AND (sl.date >= v_startdate)) AND (sl.date <= v_enddate)) GROUP BY sl.saleinvcode, sd.icode, sl.custcode, c.areacode, sl.discperc UNION ALL SELECT sl.srinvcode AS invno, sd.icode, sl.custcode AS custcode, (-coalesce(sum((sd.looseqty + CASE WHEN (v_mergebonus = 1) THEN sd.bonusqty ELSE 0 END)), 0)) AS qty, (-coalesce(sum(CASE WHEN (v_mergebonus = 1) THEN 0 ELSE sd.bonusqty END), 0)) AS bonus, (-round((coalesce((sum((((sd.looseqty * sd.srprice)) * ((1 - ((.01 * sd.discperc)))))) * ((1 - ((.01 * sl.discperc))))), 0))::numeric, 2)) AS netamt, c.areacode FROM dbo.srledger AS sl, dbo.srdetail AS sd, dbo.customer AS c, (SELECT areacode, zonecode FROM dbo.zoneareas WHERE (zonecode = v_zonecode)) AS a WHERE ((((((a.areacode = c.areacode) AND (c.custcode = sl.custcode)) AND (sl.posted = 'Y')) AND (sl.srinvcode = sd.srinvcode)) AND (sl.date >= v_startdate)) AND (sl.date <= v_enddate)) GROUP BY sl.srinvcode, sd.icode, sl.custcode, c.areacode, sl.discperc) AS s, dbo.item AS i WHERE ((i.icode = s.icode) AND (i.icode IN (SELECT code FROM tv_sp_zonalareasales_crosstab_tab_itemlist AS tab_itemlist))) GROUP BY s.areacode, s.icode ORDER BY s.areacode, s.icode;
    FETCH NEXT FROM cur_c1 INTO v_icode, v_qty, v_bonus, v_val, v_areacode;
    IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    WHILE (_fs = 0) LOOP
      v_i := 1;
      WHILE (v_i <= v_tot) LOOP
        v_colcode := ltrim(rtrim(dbo.tsql_str((v_icode)::numeric, 7)));
        v_colname := ltrim(rtrim(dbo.tsql_str((v_areacode)::numeric, 7)));
        v_str_col := ltrim(rtrim(dbo.tsql_str((v_i)::numeric, 7)));
        v_upd := ((((((((((((((((((((((('UPDATE CrossTab_ReportData SET ' || 'QTY') || v_str_col) || ' = ') || ltrim(rtrim(dbo.tsql_str((v_qty)::numeric, 7)))) || ', Value') || v_str_col) || ' = ') || ltrim(rtrim(dbo.tsql_str((v_bonus)::numeric, 15, 4)))) || ', VAL') || v_str_col) || ' = ') || ltrim(rtrim(dbo.tsql_str((v_val)::numeric, 15, 5)))) || ', C_Code') || v_str_col) || ' = ') || v_colname) || ' WHERE CODE1 = ') || v_colcode) || ' AND ') || ' C_Code') || v_str_col) || ' = ') || v_colname);
        _dq2 := v_upd;
        IF _dq2 IS NOT NULL THEN
          EXECUTE dbo.tsql_dyn(_dq2);
        END IF;
        v_err := 0;
        IF (v_err <> 0) THEN
          v_upd := ('CROSSTAB PLOTING ERROR, DETAILS: ' || v_upd);
          RAISE EXCEPTION '%', v_upd;
          CLOSE cur_c1;
          -- DEALLOCATE C1
          return_value := -1;
          RETURN;
        END IF;
        v_i := (v_i + 1);
      END LOOP;
      FETCH NEXT FROM cur_c1 INTO v_icode, v_qty, v_bonus, v_val, v_areacode;
      IF FOUND THEN _fs := 0; ELSE _fs := -1; END IF;
    END LOOP;
    CLOSE cur_c1;
    -- DEALLOCATE C1
    UPDATE dbo.crosstab_reportdata AS c SET name1 = i.name, name2 = i.customicode, name3 = i.packingdesc, name4 = (SELECT name FROM dbo.zone WHERE (zonecode = v_zonecode)), code5 = CASE v_reportgrouping WHEN 'M' THEN i.manfcode WHEN 'C' THEN i.icatcode WHEN 'L' THEN i.iccode ELSE i.packcode END, name5 = CASE v_reportgrouping WHEN 'M' THEN (SELECT m.name FROM dbo.manufacturer AS m WHERE (m.manfcode = i.manfcode)) WHEN 'C' THEN (SELECT c.name FROM dbo.itemcategory AS c WHERE (c.icatcode = i.icatcode)) WHEN 'L' THEN (SELECT c.name FROM dbo.itemclass AS c WHERE (c.iccode = i.iccode)) ELSE (SELECT p.name FROM dbo.itempacking AS p WHERE (p.packcode = i.packcode)) END, value14 = CASE v_pricetype WHEN 1 THEN round(((i.saleprice / CASE i.packunits WHEN 0 THEN 1 ELSE i.packunits END))::numeric, 2) WHEN 2 THEN round(((i.saleprice / CASE i.packunits WHEN 0 THEN 1 ELSE i.packunits END))::numeric, 2) WHEN 3 THEN round(((i.purprice / CASE i.packunits WHEN 0 THEN 1 ELSE i.packunits END))::numeric, 2) ELSE round((i.avgprice)::numeric, 2) END FROM dbo.item AS i WHERE (i.icode = c.code1);
    PERFORM dbo.sp_update_total_crosstab_reportdata2();
  END IF;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;

-- ==== proc Update_ItemBatchPrices ====
CREATE OR REPLACE FUNCTION dbo.update_itembatchprices(OUT return_value integer)
  LANGUAGE plpgsql AS $body$
#variable_conflict use_column
BEGIN
  INSERT INTO dbo.itembatchpricing (icode, batch, expiry, saleprice, arrivedon, usercode, lastmodified, lastmodifiedby) SELECT gd.icode AS icode, gd.batch AS batch, gd.expiry AS expiry, CASE WHEN (coalesce((SELECT max(ibp.saleprice) FROM dbo.purdetail AS ibp WHERE (((ibp.icode = gd.icode) AND (ibp.batch = gd.batch)) AND (ibp.expiry = gd.expiry))), 0) = 0) THEN (SELECT i.saleprice FROM dbo.item AS i WHERE (i.icode = gd.icode)) ELSE (SELECT max(ibp.saleprice) FROM dbo.purdetail AS ibp WHERE (((ibp.icode = gd.icode) AND (ibp.batch = gd.batch)) AND (ibp.expiry = gd.expiry))) END AS saleprice, localtimestamp(3) AS arrivedon, 1 AS usercode, NULL::timestamp(3) AS lastmodified, NULL::smallint AS lastmodifiedby FROM dbo.godowndetail AS gd, dbo.item AS i WHERE ((gd.icode = i.icode) AND ((((dbo.tsql_str((gd.icode)::numeric, 10) || gd.batch) || left(to_char(gd.expiry, 'YYYY-MM-DD HH24:MI:SS.MS'), 100)))::citext NOT IN (SELECT DISTINCT ((dbo.tsql_str((ibp.icode)::numeric, 10) || ibp.batch) || left(to_char(ibp.expiry, 'YYYY-MM-DD HH24:MI:SS.MS'), 100)) FROM dbo.itembatchpricing AS ibp))) GROUP BY gd.icode, gd.batch, gd.expiry ORDER BY icode, batch, expiry;
  return_value := 0;
  RETURN;
  return_value := 0;
  RETURN;
END
$body$;
